// Analyse le texte collé, crée mère+prépa, ouvre le diagnostic
async function rdRefsAnalyser(){
  const txt = (document.getElementById('rdr-paste')||{}).value||'';
  const titreInput = (document.getElementById('rdr-titre')||{}).value||'';
  const source = (document.getElementById('rdr-source')||{}).value||'autre';
  const role = (document.getElementById('rdr-role')||{}).value||'garniture';
  const type = (document.getElementById('rdr-type')||{}).value||'';
  const parsed = rdParseTexte(txt);
  const titre = (titreInput || parsed.titre || 'Préparation').trim();

  if(!parsed.ingredients.length){
    alert('Aucun ingrédient détecté. Vérifie le format : une ligne par ingrédient, ex « 200 g crème liquide ».');
    return;
  }
  try{
    // une mère par dépôt pour l'instant (V0) ; le rattachement à une mère existante viendra ensuite
    const refId = await db.rdRefs.add({ titre, source, format:type||'préparation', date:new Date().toISOString(), note:'' });
    const prepId = await db.rdPreps.add({
      refId, nom:titre, role, type,
      ingredients: parsed.ingredients.map(x=>({nom:x.nom, qte:x.qte, unite:x.unite})),
      etapes: parsed.etapes, adn:null, cuisson:'', conservation:'', note:''
    });
    _rdDiagPrep = await db.rdPreps.get(prepId);
    window._rdOpenRef = refId;
    _rdRefTab='diag';
    renderRdRefs();
  }catch(e){ alert('Erreur enregistrement : '+(e&&e.message||e)); }
}


// ---- IMPORT des recettes de l'app vers la bibliothèque (source « moi ») ----
// ===================== R&D : CHARGEUR DE DATA PACKS (chefs) =====================
// Les références chefs (Alice, Bau, …) ne sont plus inlinées dans app.js : elles
// vivent dans des fichiers ./rd_pack_<chef>.json, listés par ./rd_packs.json.
// Précachés par le service worker (offline-first). Chaque pack a la même forme
// que l'ancien RD_SEED_REFS : [ {titre, source, format, preps:[…]}, … ].

// Manifeste : { packs:[...], version:N }. Renvoie {packs:[]} si absent/illisible.
async function rdFetchManifest(){
  try{
    const res = await fetch('./rd_packs.json');
    if(!res.ok) throw new Error('manifeste HTTP '+res.status);
    return await res.json();
  }catch(e){ console.error('rdFetchManifest', e); return {packs:[]}; }
}
// Charge un pack chef. Lève une erreur explicite si introuvable (=> aucune purge).
async function rdFetchPack(chef){
  const res = await fetch('./rd_pack_'+chef+'.json');
  if(!res.ok) throw new Error('pack introuvable: '+chef+' (HTTP '+res.status+')');
  return await res.json();
}
// Insertion d'une ref mère + ses préparations (porteuses de l'ADN).
async function _rdInsertRef(r){
  const refId = await db.rdRefs.add({titre:r.titre, source:r.source, format:r.format, date:new Date().toISOString(), note:''});
  let nPrep = 0;
  for(const p of (r.preps||[])){
    await db.rdPreps.add({refId, nom:p.nom, role:p.role, type:p.type, ingredients:p.ingredients, etapes:p.etapes||[], adn:null, cuisson:'', conservation:'', note:p.note||''});
    nPrep++;
  }
  return {refId, nPrep};
}
// IMPORT idempotent d'un pack : saute toute ref source+titre déjà présente.
async function rdImportPack(chef){
  const refs = await rdFetchPack(chef);
  let nMere=0, nPrep=0, skip=0;
  for(const r of refs){
    const exist = (await db.rdRefs.where('source').equals(r.source).toArray()).find(x=>x.titre===r.titre);
    if(exist){ skip++; continue; }
    const res = await _rdInsertRef(r); nMere++; nPrep += res.nPrep;
  }
  return {nMere, nPrep, skip};
}
// FORCE : charge AVANT de purger (pack absent => rien détruit), puis remplace
// proprement toutes les refs du chef (et leurs preps) sans doublon ni orphelin.
async function rdForcePack(chef){
  const refs = await rdFetchPack(chef);
  const olds = await db.rdRefs.where('source').equals(chef).toArray();
  for(const o of olds){
    const preps = await db.rdPreps.where('refId').equals(o.id).toArray();
    for(const p of preps) await db.rdPreps.delete(p.id);
    await db.rdRefs.delete(o.id);
  }
  let nMere=0, nPrep=0;
  for(const r of refs){ const res = await _rdInsertRef(r); nMere++; nPrep += res.nPrep; }
  return {nMere, nPrep, purged:olds.length};
}
// Seed chefs = import idempotent de TOUS les packs du manifeste.
async function rdSeedRefsChefs(){
  const man = await rdFetchManifest();
  let nMere=0, nPrep=0, skip=0;
  for(const chef of (man.packs||[])){
    try{
      const r = await rdImportPack(chef);
      nMere+=r.nMere; nPrep+=r.nPrep; skip+=r.skip;
    }catch(e){ console.error('rdSeedRefsChefs pack '+chef, e); }
  }
  return {nMere, nPrep, skip};
}

async function rdRefsImportChefs(){
  try{
    const res=await rdSeedRefsChefs();
    window._rdOpenRef=null; renderRdRefs();
    toast(res.nMere+' référence(s) chef ajoutée(s) · '+res.nPrep+' préparation(s)'+(res.skip?(' · '+res.skip+' déjà présente(s)'):''));
  }catch(e){ alert('Erreur import chefs : '+(e&&e.message||e)); }
}
// Force la mise à jour de tous les chefs du manifeste (écrase et resynchronise).
async function rdRefsForceChefs(){
  if(!confirm('Forcer la mise à jour des chefs ? Les références chefs existantes seront remplacées par les versions des packs.')) return;
  try{
    const man = await rdFetchManifest();
    let nMere=0, nPrep=0, purged=0;
    for(const chef of (man.packs||[])){
      try{ const r = await rdForcePack(chef); nMere+=r.nMere; nPrep+=r.nPrep; purged+=r.purged; }
      catch(e){ console.error('rdForcePack '+chef, e); }
    }
    window._rdOpenRef=null; renderRdRefs();
    toast('Chefs resynchronisés : '+nMere+' référence(s) · '+nPrep+' préparation(s)'+(purged?(' · '+purged+' remplacée(s)'):''));
  }catch(e){ alert('Erreur mise à jour chefs : '+(e&&e.message||e)); }
}

function rdSplitItemsByPartie(items){
  const garniture=[], structure=[];
  for(const it of (items||[])){
    const pa=(it.partie||'').toLowerCase();
    if(pa==='ganache'||pa==='cremeux') garniture.push(it); else structure.push(it);
  }
  return {garniture, structure};
}
function rdItemsToIngredients(items, matName){
  return (items||[]).map(it=>({ nom: matName(it.materialId)||('Matière #'+it.materialId),
    qte:(+it.qteParBatch||0)*1000, unite:'g' })).filter(x=>x.qte>0);
}
function rdGuessType(items){
  const ps=new Set((items||[]).map(it=>(it.partie||'').toLowerCase()));
  if(ps.has('cremeux')&&!ps.has('ganache')) return 'crémeux';
  if(ps.has('cremeux')&&ps.has('ganache')) return 'ganache + crémeux';
  return 'ganache';
}
function rdBuildImport(recipe, items, matName){
  const sp=rdSplitItemsByPartie(items); const preps=[];
  if(sp.garniture.length) preps.push({ nom:recipe.produitNom||'Garniture', role:'garniture',
    type:rdGuessType(sp.garniture), ingredients:rdItemsToIngredients(sp.garniture, matName) });
  if(sp.structure.length) preps.push({ nom:'Coque', role:'structure', type:'coque',
    ingredients:rdItemsToIngredients(sp.structure, matName) });
  return { mere:{ titre:recipe.produitNom||'Recette', source:'moi', format:'macaron', srcRecipeId:recipe.id }, preps };
}

// Importe (ou met à jour) toutes les recettes de l'app. Idempotent via srcRecipeId.
async function rdRefsImportMine(){
  try{
    const recipes = await db.recipes.toArray();
    const allItems = await db.recipeItems.toArray();
    const mats = await db.materials.toArray();
    const matName = id => { const m=mats.find(x=>+x.id===+id); return m?m.nom:null; };
    if(!recipes.length){ alert('Aucune recette dans l\'app à importer.'); return; }
    let nMere=0, nPrep=0, maj=0;
    for(const rec of recipes){
      const items = allItems.filter(it=>+it.recipeId===+rec.id);
      const built = rdBuildImport(rec, items, matName);
      if(!built.preps.length) continue;
      // idempotence : on cherche une mère déjà importée pour cette recette source
      let existing = await db.rdRefs.where('source').equals('moi').toArray();
      existing = existing.find(r=>+r.srcRecipeId===+rec.id);
      let refId;
      if(existing){
        refId = existing.id;
        await db.rdRefs.update(refId, { titre:built.mere.titre, format:built.mere.format });
        // on retire les anciennes préparations de cette mère puis on réécrit (mise à jour propre)
        const old = await db.rdPreps.where('refId').equals(refId).toArray();
        for(const o of old) await db.rdPreps.delete(o.id);
        maj++;
      } else {
        refId = await db.rdRefs.add({ ...built.mere, date:new Date().toISOString(), note:'' });
        nMere++;
      }
      for(const pr of built.preps){
        await db.rdPreps.add({ refId, nom:pr.nom, role:pr.role, type:pr.type,
          ingredients:pr.ingredients, etapes:[], adn:null, cuisson:'', conservation:'', note:'' });
        nPrep++;
      }
    }
    window._rdOpenRef=null;
    renderRdRefs();
    toast(`${nMere} recette(s) importée(s)${maj?`, ${maj} mise(s) à jour`:''} · ${nPrep} préparation(s)`);
  }catch(e){ alert('Erreur import : '+(e&&e.message||e)); }
}

