let matSearch='';
let recSearch='';   // texte de recherche recettes (persisté entre re-renders)
let _matCatFilter='all';   // 'all' | 'denree' | 'emballage'
let _matCache=null, _lotCache=null;
async function renderMaterials(){
  // [COCKPIT — étape 3] Focus depuis l'assistant (« stock de chocolat » → 🧂 Stock de Chocolat) :
  // on pré-remplit la recherche pour ouvrir l'écran déjà filtré sur cette matière.
  try{
    const f = window._viewFocus;
    if(f && f.view==='matieres' && f.type==='matiere' && f.val){
      matSearch = String(f.val);
      window._viewFocus = null;
    }
  }catch(e){swallow(e,'renderMaterials')}
  // Tri alphabétique STRICT par nom, insensible à la casse et aux accents,
  // indépendant de l'ordre de saisie (l'index IndexedDB trie mal les accents/majuscules).
  const mats = (await db.materials.toArray())
    .sort((a,b)=> normTxt(a.nom||'').localeCompare(normTxt(b.nom||''), 'fr', {numeric:true}));
  window._allMatsCache = mats;   // cache pour le coût emballage réel (calculs synchrones)
  // précalcul du stock par matière (une seule passe sur les lots)
  const allLots = await db.materialLots.toArray();
  const stockBy={}, dlcBy={}, nbBy={}, sansPrixBy={};
  allLots.forEach(l=>{ const id=l.materialId; if(!(id in stockBy)){stockBy[id]=0;nbBy[id]=0;sansPrixBy[id]=0;}
    const r=+l.qteRestante||0; stockBy[id]+=r;
    if(r>0){ nbBy[id]++; if(l.dlc && (!dlcBy[id]||l.dlc<dlcBy[id])) dlcBy[id]=l.dlc;
      if(!(+l.prix>0)) sansPrixBy[id]++; } });
  _matCache = mats.map(mat=>{
    const total=stockBy[mat.id]||0, dlcMin=dlcBy[mat.id]||null, nbLots=nbBy[mat.id]||0;
    const sansPrix=sansPrixBy[mat.id]||0;
    const low = total<=(+mat.seuil||0);
    const cat = mat.categorie||'denree';
    const prim = normTxt(mat.nom||'');
    const blob = normTxt([mat.nom, mat.marque, mat.unite, mat.ref, cat==='emballage'?'emballage':'denree', low?'à commander':'ok'].filter(Boolean).join(' '));
    return {mat, total, dlcMin, nbLots, sansPrix, low, cat, _prim:prim, _blob:blob, _digits:''};
  });

  const sups = await db.suppliers.toArray();
  const supName = id => (sups.find(s=>s.id===id)||{}).nom||'—';
  const matName = id => (mats.find(s=>s.id===id)||{}).nom||'(supprimée)';
  const matUnit = id => (mats.find(s=>s.id===id)||{}).unite||'';

  // lots récents (cache complet pour recherche, affichage limité par défaut)
  const lots = allLots.slice().sort((a,b)=>(b.dateReception||'').localeCompare(a.dateReception||''));
  _lotCache = lots.map(l=>{
    const prim = normTxt(l.lotFournisseur||'');
    const blob = normTxt([l.lotFournisseur, matName(l.materialId), supName(l.supplierId), fmtDate(l.dateReception), fmtDate(l.dlc)].filter(Boolean).join(' '));
    return {l, matName:matName(l.materialId), supName:supName(l.supplierId), _prim:prim, _blob:blob, _digits:onlyDigits(l.lotFournisseur||'')};
  });

  // Historique consommation : regroupé PAR BATCH (1 recette = 1 titre + ses ingrédients).
  // Les batchs supprimés n'ont plus de prodConsumption (nettoyés à la suppression) ; par
  // sécurité on ignore aussi toute conso dont la production n'existe plus.
  const lotById = id => allLots.find(l=>l.id===id);
  const allProds = await db.productions.toArray();
  const prodById = id => allProds.find(p=>p.id===id);
  const recipes = await db.recipes.toArray();
  const recName = id => (recipes.find(r=>r.id===id)||{}).produitNom||'—';
  const matCatById = id => (mats.find(m=>m.id===id)||{}).categorie||'denree';
  const conso = (await db.prodConsumption.toArray()).filter(c=>!c.annuleeInventaire); // neutralisées exclues (déjà rendues/réaffectées)
  // Historique des emballages prélevés par commande (table v17, peut être absente sur vieux schéma).
  let pkgConso = [];
  try{ pkgConso = await db.packagingConsumption.toArray(); }catch(e){ pkgConso = []; }
  const allOrders = await db.orders.toArray().catch(()=>[]);
  const allClients = await db.clients.toArray().catch(()=>[]);
  const orderById = id => allOrders.find(o=>o.id===id);
  const clientNom = id => (allClients.find(c=>c.id===id)||{}).nom || '';
  // Consommables non rattachés à un batch (papier sulfurisé, film étirable, emballages…)
  const isConsumable = (matId)=>{
    const m = mats.find(x=>x.id===matId);
    if(!m) return false;
    if((m.categorie||'denree')==='emballage') return true;
    return /sulfuris|papier|film|cellophane|étirable|etirable|aluminium|alu\b/i.test(m.nom||'');
  };
  // Regroupe par batch (production existante uniquement)
  const batchMap = new Map();
  const consumablesAgg = new Map(); // matId -> total (hors batch)
  for(const c of conso){
    const lot = lotById(c.materialLotId);
    const matId = lot ? lot.materialId : (c.snapMaterialId||null);
    if(isConsumable(matId)){
      const prev=consumablesAgg.get(matId)||0; consumablesAgg.set(matId, prev+(+c.qteConsommee||0));
      continue;
    }
    const prod = prodById(c.productionId);
    if(!prod) continue; // batch supprimé → on n'affiche pas
    if(!batchMap.has(prod.id)) batchMap.set(prod.id, {prod, items:[]});
    batchMap.get(prod.id).items.push({
      materialId: matId,
      lotFournisseur: lot ? lot.lotFournisseur : (c.snapLotFournisseur||'(lot archivé)'),
      qte: c.qteConsommee
    });
  }
  // Tri des batchs : du plus récent au plus ancien (par heure de fab. ou date)
  const tsOf = p => p.prodTermineTs || p.prodDebutTs || p.prodTimestamp || (p.date?p.date+'T00:00':'');
  const batches = Array.from(batchMap.values())
    .sort((a,b)=> String(tsOf(b.prod)).localeCompare(String(tsOf(a.prod)))).slice(0,30);
  const consumablesList = Array.from(consumablesAgg.entries()).map(([id,total])=>({id,total}))
    .sort((a,b)=> (matName(a.id)||'').localeCompare(matName(b.id)||''));

  // Regroupe l'historique des emballages prélevés PAR COMMANDE (du plus récent au plus ancien).
  const pkgByOrder = new Map();
  pkgConso.forEach(h=>{
    const oid = h.orderId;
    if(!pkgByOrder.has(oid)) pkgByOrder.set(oid, {orderId:oid, date:h.date||'', items:[]});
    const g = pkgByOrder.get(oid);
    g.items.push(h);
    if((h.date||'') > g.date) g.date = h.date||g.date;
  });
  const pkgGroups = Array.from(pkgByOrder.values())
    .sort((a,b)=> String(b.date).localeCompare(String(a.date)))
    .slice(0,40);
  const kindLabel = k => k==='sac' ? '🛍️ sac' : (k==='sac-don' ? '🛍️ sac (don)' : '📦 boîte');

  document.getElementById('main').innerHTML=`
   <div class="topbar"><div><h1>Matières & emballages</h1><p id="matCount">${mats.length} référence(s)</p></div>
     <div class="flex" style="flex-wrap:wrap;gap:8px"><button class="btn gold" onclick="lotForm()">↘ Réception lot</button><button class="btn" onclick="matForm()">+ Référence</button><button class="btn ghost" onclick="genShoppingList()">🛒 Liste de courses</button><button class="btn ghost" onclick="genShoppingListPrev()">🔮 Courses prévisionnelles</button><button class="btn ghost" onclick="inventaireForm()">📋 Inventaire</button></div></div>
   <div class="panel"><h2>Inventaire (stock = somme des lots actifs)</h2>
     <input class="search" id="matSearch" style="width:100%;margin-bottom:12px" placeholder="Nom de référence, unité, état…" value="${esc(matSearch)}" oninput="matFilter(this.value)" autocomplete="off" autocapitalize="off" autocorrect="off">
   ${mats.length?`
     <div class="collapse-sec" style="margin-bottom:10px">
       <button type="button" class="collapse-head" onclick="toggleMatSec('matDenree')">
         <span>🥚 Matières premières <span class="collapse-hint" id="matDenreeCount"></span></span>
         <span class="collapse-arrow" id="matDenreeArrow">▸</span>
       </button>
       <div class="collapse-body" id="matDenreeBody" style="display:none">
         <div id="matBodyDenree" class="mat-cards"></div>
         <div id="matEmptyDenree" class="empty" style="display:none">Aucune matière première.</div>
       </div>
     </div>
     <div class="collapse-sec">
       <button type="button" class="collapse-head" onclick="toggleMatSec('matEmb')">
         <span>📦 Emballages <span class="collapse-hint" id="matEmbCount"></span></span>
         <span class="collapse-arrow" id="matEmbArrow">▸</span>
       </button>
       <div class="collapse-body" id="matEmbBody" style="display:none">
         <div id="matBodyEmb" class="mat-cards"></div>
         <div id="matEmptyEmb" class="empty" style="display:none">Aucun emballage.</div>
       </div>
     </div>`:`<div class="empty">Aucune matière. Crée d'abord tes matières (poudre d'amande, sucre…) et tes emballages, puis réceptionne des lots.</div>`}
   </div>
   <div class="panel"><div class="collapse-sec">
   <button type="button" class="collapse-head" onclick="toggleMatSec('matLots')">
     <span>📥 Lots réceptionnés <span class="collapse-hint">— stock réel par lot (FIFO, DLC)</span></span>
     <span class="collapse-arrow" id="matLotsArrow">▸</span>
   </button>
   <div class="collapse-body" id="matLotsBody" style="display:none">
     <input class="search" id="lotSearch" style="width:100%;margin-bottom:12px" placeholder="N° de lot, matière, fournisseur…" value="${esc(lotSearch)}" oninput="lotFilter(this.value)" autocomplete="off" autocapitalize="off" autocorrect="off">
   ${lots.length?`<div class="table-wrap"><table><thead><tr><th>Réception</th><th>Matière</th><th>N° lot fourn.</th><th>Fournisseur</th><th>Restant / Initial</th><th>DLC</th><th></th></tr></thead>
     <tbody id="lotBody"></tbody></table></div><div id="lotEmpty" class="empty" style="display:none">Aucun lot.</div>`
     :`<div class="empty">Aucun lot réceptionné.</div>`}
   </div></div>
   </div>
   <div class="panel"><div class="collapse-sec">
   <button type="button" class="collapse-head" onclick="toggleMatSec('matBatch')">
     <span>Matières consommées par batch <span class="collapse-hint">— historique par production</span></span>
     <span class="collapse-arrow" id="matBatchArrow">▸</span>
   </button>
   <div class="collapse-body" id="matBatchBody" style="display:none">
   ${batches.length?collapseList(batches.map(b=>{
     const p=b.prod;
     const deb = p.prodDebutTs||p.prodTimestamp||'';
     const fin = p.prodTermineTs||'';
     const dur = (deb&&fin)?ttFormat(new Date(fin)-new Date(deb)):'';
     const compTag = prodComposant(p)!=='complet'?` <span class="tag" style="background:${prodComposant(p)==='assemble'?'#3f7d52':prodComposant(p)==='degustation'?'#caa23b':'#8a6d3b'};color:#fff;font-size:.66rem">${prodComposant(p)==='coques'?'coques':prodComposant(p)==='ganache'?garnLabel(p):prodComposant(p)==='degustation'?'dégustation':'assemblé'}</span>`:'';
     return `<div class="trace-step" style="margin-bottom:12px">
       <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
         <div><b>${esc(recName(p.recipeId))}</b>${compTag}<br>
           <span style="color:#9a8a82;font-size:.78rem">lot ${esc(p.lotProduction||('#'+p.id))}</span></div>
         <button class="btn ghost sm" onclick="closeModal&&closeModal();traceProd(${p.id})" title="Détail du batch">🔎</button>
       </div>
       <div style="font-size:.8rem;color:#6b5a52;margin:4px 0 6px">
         ⏱ ${deb?`Début ${fmtDateTime(deb)}`:'Début —'}${fin?` · Fin ${fmtDateTime(fin)}`:(prodStatut(p)==='demarre'?' · <span class="tag event" style="font-size:.62rem">en cours</span>':'')}${dur?` · durée ${dur}`:''}
         <button class="btn ghost sm" style="margin-left:6px;padding:1px 7px" onclick="prodEditTimes(${p.id})">✎ Heures</button>
       </div>
       ${b.items.map(it=>`<div style="display:flex;justify-content:space-between;font-size:.85rem;padding:2px 0;border-top:1px solid #f0e8da">
         <span>${esc(matName(it.materialId))} <span style="color:#9a8a82">· lot ${esc(it.lotFournisseur||'—')}</span></span>
         <span class="tag out">−${qtyDisp(it.qte, it.materialId)} ${esc(dispUnit(it.materialId).u)}</span></div>`).join('')}
     </div>`;
   }), 1, {moreLabel:n=>`Voir les ${n} batch(s) précédent(s)`, lessLabel:'Réduire'}):`<div class="empty">Aucune consommation rattachée à un batch.</div>`}
   </div></div>
   </div>
   ${consumablesList.length?`<div class="panel"><h2>Consommables <span style="font-weight:400;font-size:.8rem;color:#9a8a82">— non rattachés à un batch (papier, film, emballages…)</span></h2>
     <div class="table-wrap"><table><thead><tr><th>Consommable</th><th>Total consommé</th></tr></thead><tbody>
     ${consumablesList.map(c=>`<tr><td><b>${esc(matName(c.id))}</b></td><td><span class="tag out">−${qtyDisp(c.total, c.id)} ${esc(dispUnit(c.id).u)}</span></td></tr>`).join('')}
     </tbody></table></div></div>`:''}
   <div class="panel"><div class="collapse-sec">
   <button type="button" class="collapse-head" onclick="toggleMatSec('matPkg')">
     <span>📦 Emballages prélevés par commande <span class="collapse-hint">— boîtes & sacs décomptés au picking</span></span>
     <span class="collapse-arrow" id="matPkgArrow">▸</span>
   </button>
   <div class="collapse-body" id="matPkgBody" style="display:none">
   ${pkgGroups.length?collapseList(pkgGroups.map(g=>{
     const o=orderById(g.orderId);
     const cli = o ? (clientNom(o.clientId)||o.histoLabel||'') : '';
     const titre = cli || (o?`Commande #${g.orderId}`:`Commande supprimée #${g.orderId}`);
     const total = g.items.reduce((s,it)=>s+(+it.qte||0),0);
     return `<div class="trace-step" style="margin-bottom:12px">
       <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
         <div><b>${esc(titre)}</b><br>
           <span style="color:#9a8a82;font-size:.78rem">${fmtDate(g.date)}${o?` · ${euro(o.montant)}`:''}</span></div>
         ${o?`<button class="btn ghost sm" onclick="closeModal&&closeModal();cmdView(${g.orderId})" title="Voir la commande">🔎</button>`:''}
       </div>
       ${g.items.map(it=>`<div style="display:flex;justify-content:space-between;font-size:.85rem;padding:2px 0;border-top:1px solid #f0e8da">
         <span>${kindLabel(it.kind)} <b>${esc(it.snapNom||matName(it.materialId))}</b>${it.taille?` <span style="color:#9a8a82">· format ${esc(it.taille)}</span>`:''}</span>
         <span class="tag out">−${qty(it.qte)}</span></div>`).join('')}
       <div style="display:flex;justify-content:flex-end;font-size:.78rem;color:#6b5a52;margin-top:4px">Total : <b style="margin-left:4px">${qty(total)} unité(s)</b></div>
     </div>`;
   }), 1, {moreLabel:n=>`Voir les ${n} commande(s) précédente(s)`, lessLabel:'Réduire'}):`<div class="empty">Aucun emballage prélevé pour l'instant. L'historique se remplit quand tu valides une commande au picking.</div>`}
   </div></div>
   </div>`;
  matFilter(matSearch);
  lotFilter(lotSearch);
}
// Replie/déplie une section d'historique de la vue stock (batch / emballages prélevés).
function toggleMatSec(key){
  const body=document.getElementById(key+'Body'), arrow=document.getElementById(key+'Arrow');
  if(!body) return;
  const open = body.style.display==='none';
  body.style.display = open?'block':'none';
  if(arrow) arrow.textContent = open?'▾':'▸';
}
function _matRow(row){
  const mat=row.mat; const dj=row.dlcMin?daysTo(row.dlcMin):null;
  const emb = row.cat==='emballage';
  const isSac = emb && mat.usage==='sac';
  const sacBadge = isSac ? `<span class="tag" style="background:#caa23b;color:#fff;font-size:.62rem">🛍️ sac</span>` : '';
  const sansPrixBadge = row.sansPrix>0 ? `<span class="tag" style="background:#fbeede;color:#a9772a;font-size:.62rem" title="${row.sansPrix} lot(s) sans prix — coût de revient faussé">⚠ prix manquant (${row.sansPrix})</span>` : '';
  const dlcTxt = emb ? '—' : (row.dlcMin?`${fmtDate(row.dlcMin)} ${dj!==null&&dj<=7?`<span class="tag warn">${dj<=0?'expiré':dj+' j'}</span>`:''}`:'—');
  return `<div class="mat-card">
    <div class="mat-card-top">
      <div class="mat-card-name"><b>${esc(mat.nom)}</b>${sacBadge}${mat.marque?`<span class="mat-marque">🏷️ ${esc(mat.marque)}</span>`:''}${sansPrixBadge}</div>
      <span class="mat-cat-pill" style="background:${isSac?'#caa23b':(emb?'#7a6a9a':'#6aa3a0')}">${isSac?'🛍️':(emb?'📦':'🥚')}</span>
    </div>
    <div class="mat-card-grid">
      <div class="mat-stock">Stock : <b>${qtyDisp(row.total, mat)} ${esc(dispUnit(mat).u)}</b></div>
      <div class="mat-state"><span class="tag ${row.low?'low':'ok'}">${row.low?'À commander':'OK'}</span></div>
      <div class="mat-sub">Seuil : ${qtyDisp(mat.seuil||0, mat)} ${esc(dispUnit(mat).u)}</div>
      <div class="mat-sub mat-lots">Lots : ${row.nbLots}</div>
      <div class="mat-sub mat-dlc">DLC la + proche : ${dlcTxt}</div>
    </div>
    <div class="mat-card-actions">
      <button class="qa pay" onclick="lotForm(0,${mat.id})" title="Ajouter un lot">＋ Lot</button>
      <button class="qa edit" onclick="matForm(${mat.id})" title="Modifier">✎ Modifier</button>
      <button class="qa del" onclick="delMat(${mat.id})" title="Supprimer">🗑</button>
    </div>
  </div>`;
}
function _lotRow(row){
  const l=row.l;
  const sansPrix = !(+l.prix>0);
  const idtxt = l.refProduit ? esc(l.refProduit) : (l.commentaire?`<span style="color:#9a8a82">${esc(l.commentaire)}</span>`:(esc(l.lotFournisseur||'—')));
  const prixBadge = sansPrix ? ` <span class="tag" style="background:#fbeede;color:#a9772a;font-size:.62rem" title="Prix d'achat non renseigné — coût de revient faussé">⚠ prix manquant</span>` : '';
  const prixBtn = sansPrix
    ? `<button class="qa" style="background:#f5c45e;color:#5a3a10" onclick="lotPriceForm(${l.id})" title="Renseigner le prix d'achat">💶 Prix</button>`
    : `<button class="qa edit" onclick="lotPriceForm(${l.id})" title="Modifier le prix">💶</button>`;
  return `<tr>
    <td>${fmtDate(l.dateReception)}</td><td>${esc(row.matName)}${prixBadge}</td>
    <td>${idtxt}</td><td>${esc(row.supName)}</td>
    <td>${qtyDisp(l.qteRestante, l.materialId)} / ${qtyDisp(l.qteInitiale, l.materialId)} ${esc(dispUnit(l.materialId).u)}</td><td>${fmtDate(l.dlc)}</td>
    <td><div class="qa-row">${prixBtn}<button class="qa del" onclick="delLot(${l.id})" title="Supprimer le lot">🗑 Suppr.</button></div></td></tr>`;
}
function matFilter(q){
  matSearch=q||'';
  if(!_matCache) return;
  // Deux sections distinctes : matières premières (denrées) et emballages, peuplées séparément.
  const denrees = _matCache.filter(r=>r.cat!=='emballage');
  const embs    = _matCache.filter(r=>r.cat==='emballage');
  searchRenderBody('matBodyDenree', null, 'matEmptyDenree', denrees, q, _matRow, 8, 'référence(s)');
  searchRenderBody('matBodyEmb',    null, 'matEmptyEmb',    embs,    q, _matRow, 8, 'référence(s)');
  // Nb de résultats par section (après recherche).
  const nbDenree = q ? searchRank(denrees, q).length : denrees.length;
  const nbEmb    = q ? searchRank(embs, q).length    : embs.length;
  // Compteurs dans les en-têtes repliables.
  const dC=document.getElementById('matDenreeCount'); if(dC) dC.textContent = `— ${nbDenree} réf.`;
  const eC=document.getElementById('matEmbCount');    if(eC) eC.textContent = `— ${nbEmb} réf.`;
  const mc=document.getElementById('matCount'); if(mc) mc.textContent = `${_matCache.length} référence(s)`;
  // Ouverture AUTO pendant la recherche : on ouvre les sections qui ont des résultats, on ferme
  // les autres. Quand la recherche est vidée, on referme tout (retour à la vue compacte).
  const searching = !!(q && q.trim());
  _setMatSec('matDenree', searching && nbDenree>0);
  _setMatSec('matEmb',    searching && nbEmb>0);
}
// Force l'état (ouvert/fermé) d'une section repliable de la vue stock.
function _setMatSec(key, open){
  const body=document.getElementById(key+'Body'), arrow=document.getElementById(key+'Arrow');
  if(!body) return;
  body.style.display = open ? 'block' : 'none';
  if(arrow) arrow.textContent = open ? '▾' : '▸';
}
// Génère une liste de courses imprimable à partir des matières ACTUELLEMENT filtrées
// à l'écran (catégorie + recherche, ex. « à commander »). Pour chaque matière, interroge
// l'historique des lots pour proposer le fournisseur au meilleur prix.
// [HELPER COURSES] Meilleur fournisseur pour une matière : pour chaque fournisseur,
// on prend son lot le plus récent, et on retient le prix unitaire le plus bas.
// Extrait de genShoppingList pour être partagé avec la liste prévisionnelle.
// `lots` et `suppliers` sont passés en paramètre (chargés une fois par l'appelant).
function _bestSupplierFor(materialId, lots, suppliers){
  const supName = id => (suppliers.find(s=>s.id===id)||{}).nom || '—';
  const perSup = new Map();
  for(const l of lots){
    if(l.materialId!==materialId || !l.supplierId) continue;
    const cur = perSup.get(l.supplierId);
    const newer = !cur || (l.dateReception||'') > (cur.dateReception||'')
      || ((l.dateReception||'')===(cur.dateReception||'') && (l.id||0)>(cur.id||0));
    if(newer) perSup.set(l.supplierId, l);
  }
  const offres=[];
  for(const [sid,lot] of perSup){ const pu=lotPU(lot); if(pu>0) offres.push({sid,pu,date:lot.dateReception||''}); }
  if(!offres.length) return null;
  offres.sort((a,b)=>a.pu-b.pu);
  return { nom:supName(offres[0].sid), pu:offres[0].pu, date:offres[0].date,
           nbAutres:offres.length-1, ecart: offres.length>1 ? money2(offres[offres.length-1].pu-offres[0].pu) : 0 };
}

async function genShoppingList(){
  if(!_matCache){ toast('Données non chargées'); return; }
  // 1) Reproduire le filtre courant (catégorie + texte de recherche).
  let list = _matCatFilter==='all' ? _matCache : _matCache.filter(r=>r.cat===_matCatFilter);
  list = searchRank(list, matSearch);
  if(!list.length){ toast('Aucune matière dans le filtre actuel'); return; }
  // 2) Charger lots + fournisseurs pour le meilleur prix.
  const [lots, suppliers] = await Promise.all([db.materialLots.toArray(), db.suppliers.toArray()]);
  const bestSupplier = materialId => _bestSupplierFor(materialId, lots, suppliers);
  // 3) Construire les lignes.
  const lignes = list.map(r=>{
    const mat=r.mat;
    const manque = Math.max(0, (+mat.seuil||0) - (r.total||0));
    const best = bestSupplier(mat.id);
    return { nom:mat.nom, unite:mat.unite||'', cat:r.cat, stock:r.total||0, seuil:+mat.seuil||0,
             manque, low:r.low, best };
  });
  // 4) Modale d'aperçu + bouton imprimer.
  const aCommander = lignes.filter(l=>l.low).length;
  openShoppingListModal(lignes, aCommander);
}

// [COURSES PRÉVISIONNELLES] Liste de courses fondée sur les BESOINS RÉELS à venir
// (commandes datées + marchés) et non sur le seuil statique. S'appuie sur le moteur
// besoinMatieresPrevisionnel : pour produire le « net à produire » de chaque parfum sur
// l'horizon, il faut telle quantité de chaque matière → on compare au stock → ce qui manque.
// Réutilise _bestSupplierFor pour le fournisseur au meilleur prix (source de vérité unique).
async function genShoppingListPrev(horizonJours){
  const horizon = horizonJours || 14;
  toast('Calcul des besoins à venir…');
  let res;
  try{
    res = await besoinMatieresPrevisionnel(horizon);
  }catch(e){
    console.error('genShoppingListPrev', e);
    toast('Erreur lors du calcul des besoins'); return;
  }
  if(!res || !res.lignes.length){
    openModal(`<h3>🔮 Courses prévisionnelles</h3>
      <p class="note">Aucune production n'est nécessaire sur les <b>${horizon} prochains jours</b> : ton stock de macarons (et les coques/ganaches mobilisables) couvre déjà les commandes et marchés à venir. Rien à acheter de ce côté.</p>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  // Fournisseur au meilleur prix : on charge lots + fournisseurs une fois.
  const [lots, suppliers] = await Promise.all([db.materialLots.toArray(), db.suppliers.toArray()]);
  // Construire les lignes au format attendu par _shopRow, enrichies du détail parfums.
  const lignes = res.lignes.map(l=>{
    // Agréger le besoin par parfum (un même parfum peut apparaître plusieurs fois si plusieurs items).
    const parParfum = {};
    (l.parfums||[]).forEach(p=>{ parParfum[p.nom] = (parParfum[p.nom]||0) + (p.qte||0); });
    const parfums = Object.keys(parParfum).map(nom=>({nom, qte:parParfum[nom]}))
      .sort((a,b)=>b.qte-a.qte);
    return {
      nom: l.nom, unite: l.unite||'', stock: l.stock, seuil: l.besoin,
      manque: l.manque, low: l.manque>0,
      best: _bestSupplierFor(l.materialId, lots, suppliers),
      _planContext: true,        // bascule le libellé « seuil » → « besoin plan » dans _shopRow
      _parfums: parfums,         // détail des parfums à produire qui mobilisent cette matière
      _pctMarche: (l._pctMarche!=null ? l._pctMarche : 0)   // part marché (badge « prévision marché » si 100%)
    };
  });
  const aCommander = lignes.filter(l=>l.low).length;
  openShoppingListModal(lignes, aCommander, {prev:true, horizon, nbAProduire:res.nbAProduire});
}

/* ============================================================
   INVENTAIRE PHYSIQUE DES MATIÈRES (point H)
   Compter à la main → saisir le réel → l'app corrige l'écart.
   Réutilise le moteur de recherche (searchRank) et la mécanique
   d'ajustement éprouvée : surplus → lot de correction (traçable),
   manque → décrément FIFO. Aucun historique conservé.
   ============================================================ */
let _invCache = null;      // [{mat, total, unite, _prim, _blob, _digits}]
let _invSearch = '';
let _invSaisies = {};      // materialId -> valeur réelle saisie (string) — persistée pendant la session de saisie

// Unité d'affichage : denrées en kg comptées en g (cohérent avec le reste de l'app).
function _invDispOf(mat){
  const u=(mat.unite||'').toLowerCase();
  return (mat.categorie!=='emballage' && u==='kg') ? {u:'g', f:1000} : {u:mat.unite||'', f:1};
}

async function inventaireForm(){
  const [mats, lots] = await Promise.all([db.materials.toArray(), db.materialLots.toArray()]);
  // Stock théorique par matière = somme des qteRestante des lots.
  const stockBy={};
  lots.forEach(l=>{ const id=l.materialId; stockBy[id]=(stockBy[id]||0)+(+l.qteRestante||0); });
  // On inventorie les DENRÉES (matières premières), pas les emballages.
  const denrees = mats.filter(m=>(m.categorie||'denree')!=='emballage');
  _invCache = denrees.map(mat=>{
    const total = stockBy[mat.id]||0;
    const prim = normTxt(mat.nom||'');
    const blob = normTxt([mat.nom, mat.marque, mat.unite, mat.ref].filter(Boolean).join(' '));
    return {mat, total, _prim:prim, _blob:blob, _digits:''};
  });
  _invSearch=''; _invSaisies={};
  openModal(`<h3>📋 Inventaire des matières</h3>
    <p class="note" style="margin-bottom:8px">Compte ton stock réel et saisis-le en face de chaque matière. À l'enregistrement, l'app corrige l'écart : un surplus crée un lot de correction, un manque est retiré au plus proche de la péremption (FIFO). Laisse vide les matières non comptées.</p>
    <input class="search" id="invSearch" style="width:100%;margin-bottom:10px" placeholder="Filtrer : nom, marque, unité…" value="" oninput="inventaireFilter(this.value)" autocomplete="off" autocapitalize="off" autocorrect="off">
    <div class="table-wrap" style="max-height:48vh;overflow:auto"><table><thead><tr><th>Matière</th><th style="text-align:right">Théorique</th><th style="text-align:right">Réel compté</th></tr></thead><tbody id="invBody"></tbody></table></div>
    <div id="invEmpty" class="empty" style="display:none">Aucune matière ne correspond.</div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="inventaireApply()">Enregistrer les corrections</button>
    </div>`);
  inventaireFilter('');
}

// Une ligne de saisie. La valeur saisie est mémorisée dans _invSaisies pour survivre au re-render du filtre.
function _invRow(it){
  const d=_invDispOf(it.mat);
  const theo = round3((+it.total||0)*d.f);
  const saisi = (it.mat.id in _invSaisies) ? _invSaisies[it.mat.id] : '';
  return `<tr>
    <td>${esc(it.mat.nom||'')}</td>
    <td style="text-align:right"><b>${qty(theo)}</b> <span style="color:#9a8a82;font-size:.8rem">${esc(d.u)}</span></td>
    <td style="text-align:right"><input type="number" inputmode="decimal" step="any" min="0" style="width:84px;text-align:right" value="${esc(String(saisi))}" oninput="_invSet(${it.mat.id}, this.value)" placeholder="—"> <span style="color:#9a8a82;font-size:.8rem">${esc(d.u)}</span></td>
  </tr>`;
}

function _invSet(matId, v){ _invSaisies[matId] = v; }

function inventaireFilter(q){
  _invSearch=q||'';
  if(!_invCache) return;
  searchRenderBody('invBody', null, 'invEmpty', _invCache, q, _invRow, 3, 'matière(s)');
}

async function inventaireApply(){
  if(!_invCache){ closeModal(); return; }
  // Construire la liste des corrections : seulement les matières où un réel a été saisi
  // (non vide, numérique) ET différent du théorique. La saisie est en unité d'AFFICHAGE (g
  // pour les kg) → on reconvertit en unité de stockage (kg) avant correction.
  const corrections=[];
  for(const it of _invCache){
    const raw = _invSaisies[it.mat.id];
    if(raw===undefined || String(raw).trim()==='') continue;
    const d=_invDispOf(it.mat);
    const reelAffiche = +String(raw).replace(',','.');
    if(isNaN(reelAffiche) || reelAffiche<0) continue;
    const reelStock = round3(reelAffiche / d.f);       // retour en unité de stockage
    const theoStock = round3(+it.total||0);
    const delta = round3(reelStock - theoStock);
    if(Math.abs(delta) < 1e-6) continue;               // pas d'écart → rien à faire
    corrections.push({mat:it.mat, theoStock, reelStock, delta, dispU:d.u, f:d.f});
  }
  if(!corrections.length){ toast('Aucun écart à corriger'); closeModal(); return; }
  // Récapitulatif AVANT d'écrire (validation explicite).
  const lignes = corrections.map(c=>{
    const sens = c.delta>0 ? '➕' : '➖';
    const theoAff=round3(c.theoStock*c.f), reelAff=round3(c.reelStock*c.f), deltaAff=round3(Math.abs(c.delta)*c.f);
    return `<div class="sum-box" style="font-size:.86rem"><span>${esc(c.mat.nom)} <span style="color:#9a8a82">${qty(theoAff)} → ${qty(reelAff)} ${esc(c.dispU)}</span></span><b style="color:${c.delta>0?'#2e7d32':'#b3261e'}">${sens} ${qty(deltaAff)} ${esc(c.dispU)}</b></div>`;
  }).join('');
  openModal(`<h3>📋 Confirmer l'inventaire</h3>
    <p class="note" style="margin-bottom:8px"><b>${corrections.length} matière(s)</b> avec un écart seront corrigées :</p>
    <div style="max-height:46vh;overflow:auto">${lignes}</div>
    <p class="note" style="margin-top:8px">Les surplus créent un lot de correction (prix 0, traçable) ; les manques sont retirés en FIFO. Cette action modifie ton stock.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick='inventaireConfirm(${JSON.stringify(corrections.map(c=>({id:c.mat.id, nom:c.mat.nom, delta:c.delta})))})'>Confirmer la correction</button>
    </div>`);
}

async function inventaireConfirm(list){
  if(!Array.isArray(list) || !list.length){ closeModal(); return; }
  try{
    await db.transaction('rw', db.materialLots, async()=>{
      for(const c of list){
        const delta = round3(+c.delta||0);
        if(Math.abs(delta) < 1e-6) continue;
        if(delta>0){
          // surplus → lot de correction traçable, NON CHIFFRÉ (marqueur inventaire:true)
          await db.materialLots.add({materialId:c.id, supplierId:0, lotFournisseur:'INV-'+today().replace(/-/g,''),
            qteInitiale:delta, qteRestante:delta, dateReception:today(), dlc:'', prix:0, prixUnitaire:0,
            inventaire:true, note:'Inventaire'});
        } else {
          // manque → décrément FIFO sur les lots actifs (au plus proche de la DLC d'abord)
          let reste = -delta;
          const lots = (await db.materialLots.where('materialId').equals(+c.id).and(l=>+l.qteRestante>0).toArray())
            .sort((a,b)=>(a.dlc||'9999').localeCompare(b.dlc||'9999'));
          for(const l of lots){
            if(reste<=1e-9) break;
            const pris = round3(Math.min(reste, +l.qteRestante));
            if(pris>0){
              // [v1370] On TRACE le retrait d'inventaire sur le lot lui-même (cumul `ajustInventaire`).
              // Sans cette trace, qteRestante baisse sans que rien ne l'explique côté données — et le
              // contrôle S3 (restant = initiale − conso) crie à l'incohérence sur un ajustement LÉGITIME.
              // Un manque d'inventaire n'est ni une consommation ni une perte formelle : c'est un
              // ajustement, et il doit laisser une trace déductible.
              await db.materialLots.update(l.id, {
                qteRestante: subQty(l.qteRestante, pris),
                ajustInventaire: round3((+l.ajustInventaire||0) + pris)
              });
              reste = subQty(reste, pris);
            }
          }
        }
      }
    });
    closeModal();
    toast(`Inventaire enregistré ✓ (${list.length} correction(s))`);
    if(typeof renderMaterials==='function') renderMaterials();
  }catch(e){
    console.error('inventaireConfirm', e);
    toast('Erreur pendant la correction d\'inventaire');
  }
}
function _shopRow(l){
  const manqueTxt = l.manque>0 ? `${qty(l.manque)} ${esc(l.unite)}` : '—';
  const best = l.best
    ? `<b>${esc(l.best.nom)}</b> <span class="ws-time">${euro(l.best.pu)}/${esc(l.unite||'u')}</span>${l.best.nbAutres>0?` <span class="tag ok" style="font-size:.6rem">meilleur prix (−${euro(l.best.ecart)})</span>`:''}`
    : `<span style="color:#c9bcae">aucun historique d'achat</span>`;
  // Mode prévisionnel : détail des parfums à produire qui consomment cette matière.
  const parfumsTxt = (l._parfums && l._parfums.length)
    ? `<div class="shop-sub" style="color:#9a8a82;font-size:.78rem">pour : ${l._parfums.map(p=>`${esc(p.nom)} (${qty(p.qte)})`).join(', ')}</div>`
    : '';
  // [ÉTAPE B] Badge discret UNIQUEMENT pour les matières achetées à 100% pour une PRÉVISION marché
  // (aucune commande ferme ne les réclame). Signale à Benjamin que cet achat repose sur une prévision.
  const previsionTag = (l._pctMarche!=null && l._pctMarche>=100)
    ? ' <span class="tag" style="font-size:.58rem;background:#f3e7c4;color:#8a6d1f;border:1px solid #e3cf93">🔮 prévision marché</span>'
    : '';
  return `<div class="shop-line">
    <div class="shop-chk">☐</div>
    <div class="shop-main">
      <div class="shop-name"><b>${esc(l.nom)}</b> ${l.low?'<span class="tag low" style="font-size:.6rem">à commander</span>':''}${previsionTag}</div>
      <div class="shop-sub">Stock ${qty(l.stock)} / ${l._planContext?'besoin plan':'seuil'} ${qty(l.seuil)} ${esc(l.unite)} · à prévoir : <b>${manqueTxt}</b></div>
      ${parfumsTxt}
      <div class="shop-sup">🏪 ${best}</div>
    </div>
  </div>`;
}
function openShoppingListModal(lignes, aCommander, opts){
  opts = opts || {};
  const dateStr = new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  const titre = opts.prev ? '🔮 Courses prévisionnelles' : '🛒 Liste de courses';
  const note = opts.prev
    ? `Pour honorer tes commandes et marchés des <b>${opts.horizon} prochains jours</b>, tu dois produire <b>${opts.nbAProduire} parfum(s)</b>. Voici les matières nécessaires${aCommander?` · <b>${aCommander} à acheter</b>`:''}. Les quantités tiennent compte de ton stock actuel.`
    : `${lignes.length} référence(s)${aCommander?` · <b>${aCommander} à commander</b>`:''}. Le fournisseur indiqué est celui au <b>meilleur prix</b> d'après ton historique d'achat.`;
  openModal(`<h3>${titre}</h3>
    <p class="note">${note}</p>
    <div class="shop-list" id="shopList">${lignes.map(_shopRow).join('')}</div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Fermer</button>
      <button class="btn" onclick="_printShop()">🖨 Imprimer</button>
    </div>`);
  // stocke les lignes pour l'impression
  window.__shopLignes = lignes; window.__shopDate = dateStr;
}
function _printShop(){
  const lignes = window.__shopLignes||[]; const dateStr=window.__shopDate||'';
  const rows = lignes.map(l=>{
    const manque = l.manque>0 ? `${qty(l.manque)} ${esc(l.unite)}` : '—';
    const best = l.best ? `${esc(l.best.nom)} — ${euro(l.best.pu)}/${esc(l.unite||'u')}` : '—';
    const parfums = (l._parfums && l._parfums.length)
      ? `<div style="color:#777;font-size:10px">pour : ${l._parfums.map(p=>`${esc(p.nom)} (${qty(p.qte)})`).join(', ')}</div>` : '';
    return `<tr>
      <td style="width:22px;text-align:center">☐</td>
      <td><b>${esc(l.nom)}</b>${l.low?' <span style="color:#a9772a;font-size:10px">(à commander)</span>':''}${parfums}</td>
      <td style="text-align:right;white-space:nowrap">${manque}</td>
      <td>${best}</td></tr>`;
  }).join('');
  const win = window.open('', '_blank', 'width=700,height=900');
  if(!win){ toast('Autorise les fenêtres pour imprimer'); return; }
  win.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8">
    <title>Liste de courses</title>
    <style>
@font-face{font-family:'Outfit';font-weight:400;font-display:swap;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'Outfit';font-weight:500;font-display:swap;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'Outfit';font-weight:600;font-display:swap;src:url(data:font/ttf;base64,) format('truetype');}
@font-face{font-family:'Bellota';font-weight:700;font-display:swap;src:url(data:font/ttf;base64,) format('truetype');}
</style>
    <style>
      @page{size:A4;margin:14mm}
      *{margin:0;padding:0;box-sizing:border-box}
      body{font-family:'Outfit',system-ui,sans-serif;color:#3a2a2e;font-size:13px}
      .head{background:#490F25;color:#EBDFCB;padding:10mm 12mm;border-radius:4mm;margin-bottom:8mm;text-align:center}
      .head h1{font-family:'Bellota',cursive;font-weight:700;font-size:22px;color:#fff}
      .head .d{font-size:11px;opacity:.85;margin-top:2mm;text-transform:capitalize}
      table{width:100%;border-collapse:collapse}
      th{background:#E8DDCD;color:#490F25;text-align:left;padding:3mm 3.5mm;font-size:11px;text-transform:uppercase;letter-spacing:.04em}
      th:nth-child(3){text-align:right}
      td{padding:3mm 3.5mm;border-bottom:1px solid #ece3d5;font-size:12.5px;vertical-align:top}
      .foot{margin-top:8mm;font-size:10.5px;color:#8a7a72;text-align:center}
    </style></head><body>
    <div class="head"><h1>🛒 Liste de courses</h1><div class="d">Sensations Macarons · ${dateStr}</div></div>
    <table><thead><tr><th></th><th>Matière première</th><th>À prévoir</th><th>Fournisseur (meilleur prix)</th></tr></thead>
    <tbody>${rows}</tbody></table>
    <div class="foot">Fournisseurs et prix issus de l'historique d'achat · à vérifier au moment de la commande.</div>
    </body></html>`);
  win.document.close();
  setTimeout(()=>{ try{ win.focus(); win.print(); }catch(e){swallow(e,'_printShop')} }, 600);
}
let lotSearch='';
function lotFilter(q){
  lotSearch=q||'';
  if(!_lotCache) return;
  searchRenderBody('lotBody','__noop','lotEmpty', _lotCache, q, _lotRow, 7, 'lot(s)', 5);
}
async function matForm(id){
  const s = id ? await db.materials.get(id) : {unite:'kg', categorie:'denree'};
  const cat = s.categorie || 'denree';
  const isEmb = cat==='emballage';
  // Unité d'une DENRÉE : on force « kg » pour les nouvelles, mais on PRÉSERVE l'unité existante
  // (ex. « g » hérité d'une ancienne version) si la matière est déjà en base, pour ne pas bloquer
  // l'édition du nom/prix ni invalider les lots/recettes déjà saisis dans cette unité.
  const denreeUnite = (id && s.unite) ? s.unite : 'kg';
  const denreeOpts = [...new Set(['kg', denreeUnite])];   // 'kg' + l'unité héritée si différente
  // Denrées alimentaires : tout au KILOGRAMME (prix, stock, recettes) pour une lecture homogène.
  // Emballages : à l'unité.
  openModal(`<h3>${id?'Modifier':'Nouvelle'} ${isEmb?'emballage':'matière'}</h3>
   <div class="field"><label>Catégorie</label>
     <select id="f_cat" onchange="matCatSwitch(this.value)">
       <option value="denree" ${cat==='denree'?'selected':''}>Denrée alimentaire</option>
       <option value="emballage" ${cat==='emballage'?'selected':''}>Emballage</option>
     </select></div>
   <div class="field"><label>Nom</label><input id="f_nom" value="${esc(s.nom)}" placeholder="${isEmb?'ex : Boîte 8 macarons kraft':'ex : Poudre amande'}"></div>
   <div class="field"><label>Marque du produit <span style="color:#9a8a82;font-weight:400">— optionnel (ex : Valrhona)</span></label><input id="f_marque" value="${esc(s.marque||'')}" placeholder="${isEmb?'ex : marque de l’emballage':'ex : Valrhona'}"></div>
   <div class="row2">
     <div class="field" id="f_uniteWrap"><label>Unité</label>
       <select id="f_unite" ${isEmb?'':'disabled'}>${(isEmb?['unité','sachet']:denreeOpts).map(u=>`<option ${ (s.unite===u)||(!isEmb&&!s.unite&&u==='kg')?'selected':''}>${u}</option>`).join('')}</select>
       <p class="note" id="uniteNote" style="margin-top:4px">${isEmb?'Emballages : comptés à l’unité.':(denreeUnite!=='kg'?`Cette denrée est gérée en <b>${esc(denreeUnite)}</b> (unité conservée de sa création ; lots et recettes l’utilisent).`:'Les denrées sont gérées <b>au kilogramme</b> (prix, stock et recettes en kg).')}</p></div>
     <div class="field"><label>Seuil d'alerte ${isEmb?'(unités)':`(${esc(denreeUnite)})`}</label><input type="number" step="0.01" id="f_seuil" value="${s.seuil||0}"></div>
   </div>
   <div class="field"><label>${isEmb?'Prix indicatif / unité (€)':'Prix indicatif au kilo (€/kg)'}</label><input type="number" step="0.01" id="f_prix" value="${s.prixDefaut||0}"></div>
   <div class="field" id="f_embUsageWrap" style="${isEmb?'':'display:none'}"><label>Type d'emballage</label>
     <select id="f_embUsage" onchange="matEmbUsageSwitch(this.value)">
       <option value="coffret" ${s.usage!=='sac'?'selected':''}>📦 Coffret / Boîte (contient des macarons)</option>
       <option value="sac" ${s.usage==='sac'?'selected':''}>🛍️ Sac (ajouté à la commande, sans capacité)</option>
     </select>
     <p class="note" id="embUsageNote" style="margin-top:4px">${s.usage==='sac'?'Un sac n’a pas de capacité en macarons : tu en choisiras le nombre sur chaque commande.':'Un coffret/boîte est relié à un format par sa capacité en macarons.'}</p></div>
   <div class="field" id="f_capWrap" style="${(isEmb && s.usage!=='sac')?'':'display:none'}"><label>Capacité (nb de macarons) <span style="color:#9a8a82;font-weight:400">— relie l'emballage à un format de coffret</span></label>
     <input type="number" min="0" step="1" id="f_cap" value="${s.capacite!=null?esc(s.capacite):''}" placeholder="ex : 8"></div>
   <div id="f_periWrap" style="${isEmb?'display:none':''}">
     <label class="switch-row"><input type="checkbox" id="f_peri" ${s.perissableOuvert?'checked':''} onchange="matPeriSwitch(this.checked)"> Périssable une fois ouvert (crème, lait…)</label>
     <div class="field" id="f_periDaysWrap" style="${s.perissableOuvert?'':'display:none'}"><label>Durée après ouverture (jours) <span style="color:#9a8a82;font-weight:400">— DLC déclenchée dès la 1ʳᵉ utilisation en production</span></label>
       <input type="number" min="1" step="1" id="f_periDays" value="${s.joursApresOuverture!=null?s.joursApresOuverture:7}" placeholder="7"></div>
   </div>
   <p class="note">Le stock réel se gère par <b>lots</b> (bouton « Réception lot »). Ici tu définis seulement ${isEmb?"l'emballage":'la matière'} et son seuil.</p>
   <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button><button class="btn" onclick="saveMat(${id||0})">Enregistrer</button></div>`);
}
// Bascule unité/champs selon la catégorie. Denrée → kg verrouillé ; emballage → unité.
function matCatSwitch(cat){
  const u=document.getElementById('f_unite');
  const note=document.getElementById('uniteNote');
  if(u){
    if(cat==='emballage'){
      u.disabled=false;
      u.innerHTML=['unité','sachet'].map(x=>`<option ${x==='unité'?'selected':''}>${x}</option>`).join('');
      if(note) note.innerHTML='Emballages : comptés à l’unité.';
    } else {
      u.innerHTML='<option selected>kg</option>'; u.value='kg'; u.disabled=true;
      if(note) note.innerHTML='Les denrées sont gérées <b>au kilogramme</b> (prix, stock et recettes en kg).';
    }
  }
  const uw=document.getElementById('f_embUsageWrap'); if(uw) uw.style.display = cat==='emballage' ? 'block' : 'none';
  const cw=document.getElementById('f_capWrap');
  if(cw){
    const usage = document.getElementById('f_embUsage')?.value || 'coffret';
    cw.style.display = (cat==='emballage' && usage!=='sac') ? 'block' : 'none';
  }
  const pw=document.getElementById('f_periWrap'); if(pw) pw.style.display = cat==='emballage' ? 'none' : 'block';
  // met à jour le libellé du prix
  const prixField=document.getElementById('f_prix');
  if(prixField){ const lab=prixField.closest('.field')?.querySelector('label');
    if(lab) lab.textContent = cat==='emballage' ? 'Prix indicatif / unité (€)' : 'Prix indicatif au kilo (€/kg)'; }
  const seuilLab=document.getElementById('f_seuil')?.closest('.field')?.querySelector('label');
  if(seuilLab){
    const uNat = document.getElementById('f_unite')?.value || 'kg';
    seuilLab.textContent = cat==='emballage' ? "Seuil d'alerte (unités)" : `Seuil d'alerte (${uNat})`;
  }
}
// Bascule selon le type d'emballage : un SAC n'a pas de capacité macarons (champ masqué).
function matEmbUsageSwitch(usage){
  const cw=document.getElementById('f_capWrap');
  if(cw) cw.style.display = (usage==='sac') ? 'none' : 'block';
  const note=document.getElementById('embUsageNote');
  if(note) note.innerHTML = (usage==='sac')
    ? 'Un sac n’a pas de capacité en macarons : tu en choisiras le nombre sur chaque commande.'
    : 'Un coffret/boîte est relié à un format par sa capacité en macarons.';
}
function matPeriSwitch(on){ const d=document.getElementById('f_periDaysWrap'); if(d) d.style.display = on?'block':'none'; }
async function saveMat(id){
  const isEmb = val('f_cat')==='emballage';
  const embUsage = isEmb ? (val('f_embUsage')||'coffret') : null;
  const isSac = embUsage==='sac';
  const peri = !isEmb && document.getElementById('f_peri')?.checked;
  // Unité : emballage = valeur choisie ; denrée = « kg » par défaut, MAIS on préserve l'unité
  // existante (ex. « g ») pour une denrée déjà en base, afin de ne pas invalider lots/recettes.
  let unite;
  if(isEmb){ unite = val('f_unite')||'unité'; }
  else if(id){ const _prev = await db.materials.get(id); unite = (_prev && _prev.unite) ? _prev.unite : 'kg'; }
  else { unite = 'kg'; }
  const o={nom:val('f_nom'),marque:(val('f_marque')||'').trim(),unite,seuil:+val('f_seuil')||0,prixDefaut:+val('f_prix')||0,
    categorie: isEmb?'emballage':'denree',
    usage: isEmb ? embUsage : undefined,                       // 'coffret' (défaut) ou 'sac'
    capacite: (isEmb && !isSac) ? (+val('f_cap')||0) : undefined,   // un sac n'a pas de capacité macarons
    perissableOuvert: !!peri, joursApresOuverture: peri ? (Math.max(1,+val('f_periDays')||7)) : undefined};
  if(!o.nom){toast('Nom requis');return;}
  if(id){
    // S3 : interdire le changement d'unité si la matière est déjà utilisée (lots ou recettes)
    const prev = await db.materials.get(id);
    if(prev && prev.unite && prev.unite!==o.unite){
      const nbLots = (await db.materialLots.where('materialId').equals(id).toArray()).length;
      const nbItems = (await db.recipeItems.where('materialId').equals(id).toArray()).length;
      if(nbLots || nbItems){
        toast(`Unité verrouillée : ${nbLots} lot(s) et ${nbItems} recette(s) utilisent « ${prev.unite} »`);
        return;
      }
    }
    await db.materials.update(id,o);
  } else {
    await db.materials.add(o);
  }
  closeModal(); await syncAfterMaterialChange(); renderMaterials(); toast('Matière enregistrée ✓');
}
async function delMat(id){
  const mat = await db.materials.get(id);
  if(!mat){ toast('Matière introuvable'); return; }
  // Garde-fou : une matière utilisée dans une ou plusieurs recettes ne peut pas être supprimée.
  const usedItems = await db.recipeItems.where('materialId').equals(id).toArray().catch(()=>[]);
  if(usedItems.length){
    const recIds = [...new Set(usedItems.map(it=>it.recipeId))];
    const recs = await db.recipes.toArray();
    const recNoms = recIds.map(rid=>{ const r=recs.find(x=>x.id===rid); return r?(r.produitNom||('recette #'+rid)):('recette #'+rid); });
    openModal(`<h3>Suppression impossible</h3>
      <div class="banner" style="background:#f6e3e0;border-color:var(--red,#b3261e);color:#7a2a20">⛔ <div><b>${esc(mat.nom)}</b> est utilisée dans ${recIds.length} recette(s) : <b>${esc([...new Set(recNoms)].join(', '))}</b>.<br>Retirez d'abord cette matière de ces recettes avant de la supprimer.</div></div>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  const nbLots = await db.materialLots.where('materialId').equals(id).count();
  openModal(`<h3>🗑 Supprimer la matière</h3>
    <p style="margin-bottom:10px"><b>${esc(mat.nom)}</b>${nbLots?` — ${nbLots} lot(s) seront aussi supprimés.`:''}</p>
    <p class="note">Cette action est définitive.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn danger" onclick="doDelMat(${id})">🗑 Supprimer</button>
    </div>`);
}
async function doDelMat(id){
  // Re-vérification anti-concurrence : la matière a-t-elle été ajoutée à une recette entre-temps ?
  const stillUsed = await db.recipeItems.where('materialId').equals(id).count().catch(()=>0);
  if(stillUsed){ closeModal(); toast('Matière désormais utilisée dans une recette — suppression annulée'); renderMaterials(); return; }
  await db.transaction('rw',db.materials,db.materialLots,async()=>{
    await db.materialLots.where('materialId').equals(id).delete();
    await db.materials.delete(id);
  });
  closeModal();
  await syncAfterMaterialChange();
  renderMaterials();
  toast('Matière supprimée');
}
async function lotForm(_id, presetMat){
  const mats = await db.materials.toArray();
  const sups = await db.suppliers.toArray();
  if(!mats.length){toast('Crée d\'abord une matière');return;}
  const matOpts = sortByName(mats,'nom').map(m=>`<option value="${m.id}" data-unite="${esc(m.unite)}" data-emb="${m.categorie==='emballage'?1:0}" ${presetMat===m.id?'selected':''}>${esc(m.nom)}${m.marque?' — '+esc(m.marque):''} (${esc(m.unite)})</option>`).join('');
  const supOpts = `<option value="0">— non précisé —</option>`+sortByName(sups,'nom').map(s=>`<option value="${s.id}">${esc(s.nom)}</option>`).join('');
  openModal(`<h3>Réception d'un lot</h3>
   <div class="field"><label>Matière</label><select id="f_mat" onchange="majPrixUnit()">${matOpts}</select></div>
   <div class="row2">
     <div class="field"><label>Fournisseur</label><select id="f_sup">${supOpts}</select></div>
     <div class="field"><label>N° lot fournisseur</label><input id="f_lotf" placeholder="ex: NM-2026-0142"></div>
   </div>
   <div class="row2">
     <div class="field"><label>Quantité reçue <span id="qteUniteHint" style="color:#9a8a82;font-weight:400"></span></label>
       <div style="display:flex;gap:6px;align-items:stretch">
         <input type="number" step="0.001" id="f_qte" value="1" oninput="majPrixUnit()" style="flex:1">
         <select id="f_qteUnite" onchange="majPrixUnit()" style="flex:0 0 auto;width:auto">
           <option value="g">g</option>
           <option value="kg">kg</option>
         </select>
       </div>
     </div>
     <div class="field"><label>Prix total payé (€)</label><input type="number" step="0.01" id="f_prix" value="0" oninput="majPrixUnit()"></div>
   </div>
   <div class="field"><label>Prix unitaire</label><div id="f_pu" style="padding:10px 12px;background:var(--creme-2);border-radius:10px;font-weight:600;color:var(--bordeaux)">—</div></div>
   <div class="row2">
     <div class="field"><label>Date réception</label><input type="date" id="f_date" value="${today()}"></div>
     <div class="field" id="f_dlcWrap"><label>DLC / DDM</label><input type="date" id="f_dlc"></div>
   </div>
   <div class="field"><label>Référence produit <span style="color:#9a8a82;font-weight:400">— EAN / code article (si disponible)</span></label>
     <input id="f_ref" placeholder="ex : 3760123456789 ou ART-BTE08"></div>
   <div class="field"><label>Commentaire d'identification <span style="color:#9a8a82;font-weight:400">— utile si pas de référence</span></label>
     <input id="f_comm" placeholder="ex : Boîte kraft 8 macarons, couvercle transparent"></div>
   <p class="note">Chaque réception crée un lot tracé. Le <b>prix unitaire</b> est calculé automatiquement et alimente le suivi des prix et de la rentabilité. La production puise dans les lots par <b>DLC la plus proche d'abord (FIFO)</b>.</p>
   <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button><button class="btn gold" onclick="saveLot()">Réceptionner</button></div>`);
  majPrixUnit();
}
function majPrixUnit(){
  const q=numVal('f_qte'), p=numVal('f_prix');
  const el=document.getElementById('f_pu'); if(!el)return;
  const sel=document.getElementById('f_mat');
  const opt = sel && sel.options[sel.selectedIndex];
  const unite = opt ? (opt.dataset.unite||'') : '';
  // Emballages (carton, film...) : pas de DLC pertinente -> on masque le champ.
  const isEmb = opt && opt.dataset.emb==='1';
  // Selecteur g/kg : pertinent uniquement pour une denree (un emballage est a l'unite native).
  const uSel=document.getElementById('f_qteUnite');
  if(uSel){ uSel.style.display = isEmb ? 'none' : ''; }
  // Pour une denrée, on présélectionne l'unité NATIVE de la matière dans le curseur de saisie,
  // pour éviter toute confusion (ex. une crème gérée en grammes propose « g » par défaut).
  // On ne force qu'une seule fois par changement de matière (drapeau sur l'élément).
  if(uSel && !isEmb && unite && (uSel.dataset.lastMat !== String(opt?opt.value:''))){
    if(unite==='g' || unite==='kg'){ uSel.value = unite; }
    uSel.dataset.lastMat = String(opt?opt.value:'');
  }
  // Le hint d'unite n'est utile que pour un emballage (le selecteur g/kg le remplace pour une denree).
  const hint=document.getElementById('qteUniteHint');
  if(hint) hint.textContent = (isEmb && unite) ? ('\u2014 en '+unite) : '';
  const dlcWrap=document.getElementById('f_dlcWrap');
  if(dlcWrap){
    dlcWrap.style.display = isEmb ? 'none' : '';
    if(isEmb){ const d=document.getElementById('f_dlc'); if(d) d.value=''; }
  }
  // Prix unitaire indicatif : TOUJOURS affiché au kg pour une denrée (référence constante et comparable),
  // quelle que soit l'unité de saisie. Pour un emballage : prix à l'unité native.
  const uSaisie = isEmb ? unite : (uSel ? uSel.value : 'g');
  if(q>0 && p>0){
    if(isEmb){
      el.textContent = euroPrec(p/q)+' / '+uSaisie;
    } else {
      // Unité native de la matière (kg par défaut, mais peut être g).
      const uNative = unite || 'kg';
      // Quantité ramenée dans l'unité native, en tenant compte de l'unité de saisie.
      let qNative = q;
      if(uSaisie==='g'  && uNative==='kg') qNative = q/1000;
      else if(uSaisie==='kg' && uNative==='g')  qNative = q*1000;
      el.textContent = qNative>0 ? (euroPrec(p/qNative)+' / '+uNative) : '\u2014';
    }
  }
  else { el.textContent='\u2014'; }
}
let _pendingLot = null;   // données du lot en attente de confirmation (prix 0)
async function saveLot(){
  const qteSaisie=round3(numVal('f_qte'));
  if(!qteSaisie||qteSaisie<=0){toast('Quantité invalide');return;}
  const prix=money2(numVal('f_prix'));
  // Conversion d'unité : on stocke TOUJOURS en kg pour les denrées (cohérent avec les recettes).
  // L'unité de SAISIE est désormais choisie par l'utilisateur (sélecteur g/kg) : « g » → ÷1000, « kg » → ×1.
  // Les emballages restent à l'unité native (pas de conversion).
  const _matId=+val('f_mat');
  const _mat=await db.materials.get(_matId).catch(()=>null);
  const _estEmballage = _mat && _mat.categorie==='emballage';
  const _uniteSaisie = val('f_qteUnite') || 'g';
  // Unité NATIVE de stockage de la matière (kg par défaut, mais une denrée peut être gérée en g).
  const _uniteNative = (_mat && _mat.unite) ? _mat.unite : 'kg';
  // Le facteur convertit la quantité saisie vers l'unité native :
  //   saisie 'g' + native 'kg' → ÷1000      saisie 'kg' + native 'g'  → ×1000
  //   saisie == native (g→g ou kg→kg) → ×1   (c'était le bug : on divisait g→g par 1000)
  let _facteur = 1;
  if(!_estEmballage){
    if(_uniteSaisie==='g'  && _uniteNative==='kg') _facteur = 1/1000;   // diviser
    else if(_uniteSaisie==='kg' && _uniteNative==='g')  _facteur = 1000;    // multiplier
    else _facteur = 1;                                                      // même unité : rien
  }
  const qte = round3(qteSaisie*_facteur);
  // On capture TOUTES les valeurs maintenant : ouvrir l'alerte remplace la modale du formulaire.
  const data={
    materialId:_matId, supplierId:+val('f_sup')||0,
    lotFournisseur:val('f_lotf'), qteInitiale:qte, qteRestante:qte,
    prix, prixUnitaire: qte>0 ? (prix/qte) : 0,
    dateReception:val('f_date')||today(), dlc:val('f_dlc')||'',
    refProduit:val('f_ref')||'', commentaire:val('f_comm')||''
  };
  // Garde-fou coût de revient : un lot sans prix d'achat fausse le calcul de marge.
  if(prix<=0){
    _pendingLot = data;
    openModal(`<h3>⚠ Prix d'achat non renseigné</h3>
      <div class="banner" style="background:#fbeede;border-color:#e5c98a"><div>Attention : sans <b>prix d'achat</b>, le <b>coût de revient</b> de tes recettes utilisant cette matière sera <b>faussé</b> (sous-estimé) — marges et rentabilité incluses.</div></div>
      <p class="note">Reviens saisir le prix, ou enregistre quand même si ce lot est réellement gratuit (échantillon, don…).</p>
      <div class="modal-actions">
        <button class="btn ghost" onclick="reopenLotForm()">← Renseigner le prix</button>
        <button class="btn gold" onclick="saveLotConfirm()">Enregistrer sans prix</button>
      </div>`);
    return;
  }
  _pendingLot = data;
  await saveLotConfirm();
}
// Renseigner / corriger le PRIX d'un lot existant. Comme tous les calculs (coût de revient,
// marges, rentabilité) lisent les lots en direct, la correction se répercute instantanément.
async function lotPriceForm(id){
  const l=await db.materialLots.get(id); if(!l){ toast('Lot introuvable'); return; }
  const mat=await db.materials.get(l.materialId);
  const emb = mat && mat.categorie==='emballage';
  // Denrée (kg) : on raisonne en grammes → on affiche la quantité ×1000 avec l'unité « g ».
  const isDenrKg = mat && !emb && (mat.unite||'kg')==='kg';
  const u = emb ? (mat.unite||'unité') : (isDenrKg ? 'g' : (mat&&mat.unite)||'kg');
  const qAff = isDenrKg ? round3((+l.qteInitiale||0)*1000) : (+l.qteInitiale||0);
  openModal(`<h3>💶 Renseigner le prix du lot</h3>
    <p style="margin-bottom:8px"><b>${esc(mat?mat.nom:'?')}</b> · reçu ${fmtDate(l.dateReception)} · ${qty(qAff)} ${esc(u)}</p>
    <div class="field"><label>Prix total payé (€)</label>
      <input type="number" step="0.01" min="0" id="f_lotprix" value="${l.prix>0?l.prix:''}" placeholder="ex : 12.50"></div>
    <p class="note">Le prix unitaire sera recalculé automatiquement, et tous les coûts de revient se mettront à jour.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="lotPriceSave(${id})">Enregistrer le prix</button>
    </div>`);
}
async function lotPriceSave(id){
  const l=await db.materialLots.get(id); if(!l){ toast('Lot introuvable'); return; }
  const prix=money2(+val('f_lotprix')||0);
  const pu = (+l.qteInitiale>0) ? money2(prix/l.qteInitiale) : 0;
  await db.materialLots.update(id, {prix, prixUnitaire:pu});
  closeModal(); renderMaterials();
  toast(prix>0 ? 'Prix enregistré ✓ — coûts mis à jour' : 'Prix remis à 0');
}
// Rouvre le formulaire de réception en conservant la matière déjà choisie.
function reopenLotForm(){
  const matId = _pendingLot ? _pendingLot.materialId : 0;
  _pendingLot = null;
  closeModal();
  lotForm(0, matId);
}
// Enregistrement effectif du lot depuis les données capturées.
async function saveLotConfirm(){
  const o=_pendingLot; _pendingLot=null;
  if(!o || !o.materialId){ toast('Données du lot manquantes'); closeModal(); return; }
  await db.materialLots.add(o);
  closeModal(); renderMaterials();
  toast(o.prix>0 ? 'Lot réceptionné ✓' : 'Lot enregistré (sans prix) ✓');
}
async function delLot(id){
  // S1 : un lot consommé par une production ne peut pas être supprimé (traçabilité HACCP)
  const conso = (await db.prodConsumption.where('materialLotId').equals(id).toArray()).filter(c=>!c.annuleeInventaire); // seules les consos ACTIVES bloquent (une ligne réaffectée ailleurs n'attache plus ce lot)
  if(conso.length){
    const prods = await db.productions.toArray();
    const lots = prods.filter(p=>conso.some(c=>c.productionId===p.id)).map(p=>p.lotProduction||('batch '+p.id));
    openModal(`<h3>Suppression impossible</h3>
      <div class="banner" style="background:#f6e3e0;border-color:var(--red);color:#7a2a20">⛔ <div>Ce lot a été consommé par ${conso.length} production(s) : <b>${esc([...new Set(lots)].join(', '))}</b>.</div></div>
      <p class="note">Pour préserver la traçabilité réglementaire (HACCP), un lot déjà utilisé en production ne peut pas être supprimé. Son historique de consommation doit rester intact.</p>
      <div class="modal-actions"><button class="btn" onclick="closeModal()">Compris</button></div>`);
    return;
  }
  const lot = await db.materialLots.get(id); if(!lot){ toast('Lot introuvable'); return; }
  const dispo = round3(+lot.qteRestante||0);
  if(dispo<=0){
    // Rien à perdre : le lot est déjà vide, sa suppression est un pur ménage.
    if(!confirm('Supprimer ce lot ? (Aucune production ne l\'utilise, stock déjà à 0.)'))return;
    await db.materialLots.delete(id); renderMaterials(); toast('Lot supprimé');
    return;
  }
  // [v1324] Stock restant non nul : on demande la RAISON avant de faire disparaître le lot — sinon
  // sa valeur s'évapore sans laisser de trace (l'angle mort historique du gaspillage matières).
  await declareMaterialLossForm(id, lot, dispo);
}
// [v1324] Demande la raison de la suppression d'un lot encore garni, et affiche par avance le
// montant qui sera enregistré en perte si ce n'est pas une simple erreur de saisie.
async function declareMaterialLossForm(lotId, lot, dispo){
  const mat = await db.materials.get(lot.materialId).catch(()=>null);
  const valeur = materialLossAmount(lot, dispo);
  const uniteLbl = (mat && mat.unite) ? mat.unite : '';
  const motifOpts = MATERIAL_LOSS_REASONS.map(m=>`<option>${esc(m)}</option>`).join('');
  openModal(`<h3>Supprimer ce lot</h3>
    <p style="margin-bottom:8px"><b>${esc(mat?mat.nom:'?')}</b>${lot.lot?` · lot <b>${esc(lot.lot)}</b>`:''}</p>
    <div class="sum-box"><span>Stock restant de ce lot</span><b>${qty(dispo)} ${esc(uniteLbl)} · ${euro(valeur)}</b></div>
    <div class="field"><label>Raison de la suppression</label><select id="f_mlMotif" onchange="_mlHintUpdate(${money2(valeur)})">${motifOpts}</select></div>
    <p class="note" id="f_mlHint">${valeur>0?`Une raison autre que « erreur de saisie » enregistre ${euro(valeur)} en gaspillage matières premières (visible dans 🗑 Gaspillage chiffré).`:'Ce lot n\'a pas de prix connu : aucune perte financière ne sera chiffrée.'}</p>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn danger" onclick="confirmDelLot(${lotId})">Supprimer</button></div>`);
}
// Met à jour le message d'aide de la modale quand Ben change de raison (pas de perte si « erreur de saisie »).
function _mlHintUpdate(valeur){
  const sel = document.getElementById('f_mlMotif'); const hint = document.getElementById('f_mlHint');
  if(!sel || !hint) return;
  const estErreur = sel.value === MATERIAL_LOSS_REASONS[0];
  hint.textContent = estErreur
    ? 'Erreur de saisie : le lot est supprimé sans enregistrer de perte.'
    : (valeur>0 ? `Cette raison enregistre ${euro(valeur)} en gaspillage matières premières (visible dans 🗑 Gaspillage chiffré).` : 'Ce lot n\'a pas de prix connu : aucune perte financière ne sera chiffrée.');
}
// [v1324] Suppression effective, après choix de la raison : enregistre la perte (sauf erreur de
// saisie) puis supprime le lot. Le coût est figé au moment de la suppression (le lot n'existera
// plus ensuite pour le recalculer).
async function confirmDelLot(lotId){
  const lot = await db.materialLots.get(lotId); if(!lot){ closeModal(); toast('Lot introuvable'); return; }
  const motif = (document.getElementById('f_mlMotif')||{}).value || MATERIAL_LOSS_REASONS[0];
  const dispo = round3(+lot.qteRestante||0);
  const estErreurSaisie = motif === MATERIAL_LOSS_REASONS[0];
  if(!estErreurSaisie && dispo>0){
    const coutTotal = materialLossAmount(lot, dispo);
    const mat = await db.materials.get(lot.materialId).catch(()=>null);
    await db.materialLosses.add({
      materialId: lot.materialId, materialNom: mat?mat.nom:'', lotId: lot.id, lotLabel: lot.lot||'',
      date: today(), motif, qte: dispo, coutTotal
    }).catch(e=>console.error('materialLoss', e));
    await db.materialLots.delete(lotId);
    closeModal(); renderMaterials();
    toast(coutTotal>0 ? `Lot supprimé · ${euro(coutTotal)} en perte matière enregistrée` : 'Lot supprimé (sans valeur connue)');
    return;
  }
  await db.materialLots.delete(lotId);
  closeModal(); renderMaterials();
  toast('Lot supprimé');
}

/* ============================================================
   RECETTES (BOM)
   ============================================================ */
// Barre de décomposition du coût de revient d'un macaron (propre à la fiche recette) :
// montre comment matières + consommables + main d'œuvre s'empilent pour former le coût total.
function coutRevientBar(c){
  if(privacyModeEnabled()||!c) return '';
  const mat=c.coutMatUnit||0, conso=c.coutConsoUnit||0, mo=c.coutMODUnit||0;
  const total=mat+conso+mo;
  if(total<=0) return '';
  const segs=[
    {lbl:'Matières', v:mat, col:'#b3261e'},
    {lbl:'Consommables', v:conso, col:'#d98324'},
    {lbl:'Main d\'œuvre', v:mo, col:'#7a4b82'}
  ].filter(s=>s.v>0);
  const pct=v=>Math.round(v/total*100);
  const barre=segs.map(s=>`<div style="width:${Math.max(2,s.v/total*100)}%;background:${s.col}" title="${s.lbl} : ${euro(s.v)}"></div>`).join('');
  const legende=segs.map(s=>`<span style="display:inline-flex;align-items:center;gap:4px;font-size:.72rem;color:#6a5a52">
      <span style="width:10px;height:10px;border-radius:2px;background:${s.col};display:inline-block"></span>${s.lbl} ${euro(s.v)} <span style="color:#9a8a82">(${pct(s.v)}%)</span></span>`).join('');
  return `<div style="background:#fcfaf6;border:1px solid var(--hair);border-radius:11px;padding:10px 12px;margin:0 0 8px">
    <div style="font-size:.74rem;color:#7a6a62;margin-bottom:6px">Comment se construit le coût de <b>${euro(total)}</b> par macaron :</div>
    <div style="display:flex;height:20px;border-radius:6px;overflow:hidden;background:#eee">${barre}</div>
    <div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:8px">${legende}</div>
  </div>`;
}
// [INSTRUCTIONS RECETTE] Volet dépliable (slide vertical) affichant le mode opératoire d'une
// recette. Réutilisé sur la fiche recette ET sur la fiche de production. `instr` = texte brut
// (une étape par ligne). `uid` rend l'identifiant unique si plusieurs volets coexistent.
function instructionsVoletHtml(instr, uid){
  if(!instr || !String(instr).trim()) return '';
  const id = 'instr_'+(uid||Math.random().toString(36).slice(2,7));
  const etapes = String(instr).split('\n').map(s=>s.trim()).filter(Boolean);
  // si les lignes sont déjà numérotées (1. 2. …), on ne renumérote pas ; sinon on numérote.
  const dejaNum = etapes.every(e=>/^\d+[\.\)]/.test(e));
  const liste = etapes.map((e,i)=>`<div style="display:flex;gap:8px;padding:5px 0;border-top:1px solid #f0e9e2">
      <span style="flex:none;font-weight:700;color:var(--caramel,#AA7C39);min-width:1.4em">${dejaNum?'':((i+1)+'.')}</span>
      <span style="font-size:.9rem;color:#4a3a32;line-height:1.4">${esc(e.replace(/^\d+[\.\)]\s*/,''))}</span>
    </div>`).join('');
  return `<div style="margin:8px 0">
    <button type="button" onclick="(function(b){var p=document.getElementById('${id}');var open=p.style.display!=='none';p.style.display=open?'none':'block';b.querySelector('.iv-chev').style.transform=open?'rotate(0)':'rotate(90deg)';})(this)"
      style="appearance:none;width:100%;text-align:left;background:#faf6ee;border:1px solid #e8dcc0;border-radius:10px;padding:9px 12px;cursor:pointer;font-weight:600;color:var(--bordeaux);display:flex;align-items:center;gap:8px">
      <span class="iv-chev" style="display:inline-block;transition:transform .2s">▸</span>📋 Mode opératoire <span style="font-weight:400;color:#9a8a82;font-size:.82rem">(${etapes.length} étape${etapes.length>1?'s':''})</span></button>
    <div id="${id}" style="display:none;padding:4px 12px 8px">${liste}</div>
  </div>`;
}
async function renderRecipes(){
  const recipes = await db.recipes.orderBy('produitNom').toArray();
  const mats = await db.materials.toArray();
  const matName = id => (mats.find(m=>m.id===id)||{}).nom||'(supprimée)';
  const matUnit = id => (mats.find(m=>m.id===id)||{}).unite||'';
  // Coût de revient + rentabilité par parfum (indicateur visuel sur la fiche)
  const _lots = await db.materialLots.toArray();
  const _orders = await db.orders.toArray();
  const _markets = await db.markets.toArray();
  const _marketMoves = await db.marketMoves.toArray();
  const _productions = await db.productions.toArray();
  const _recipeItems = await db.recipeItems.toArray();
  const _settings = getSettings();
  // [v1432] Consommations matière réelles : c'est la source du coût MESURÉ par parfum.
  const _prodConso = await db.prodConsumption.toArray().catch(()=>[]);
  // Mode 'mesuré' : on précharge le temps de production lissé (brique 1) pour nourrir le coût de revient.
  let _mesureMin = null;
  let _mesureParRec = null;
  if(_settings.laborSource==='mesure' && _settings.laborEnabled){
    try{ const tl = await prodTempsLissePerMacaron(90); if(tl.fiable) _mesureMin = tl.minParMacaron; }catch(e){ console.error('tempsLisse',e); }
    // Temps RÉEL par recette (distingue GF/classique). Repli géré côté analyse si une recette manque de données.
    try{ _mesureParRec = await prodTempsParParfum(90); }catch(e){ console.error('tempsParParfum',e); }
  }
  const _A = analyzeFlavorProfitability({recipes, recipeItems:_recipeItems, lots:_lots, mats, orders:_orders, markets:_markets, marketMoves:_marketMoves, productions:_productions, prodConsumption:_prodConso, settings:_settings, minParMacaronMesure:_mesureMin, minParRecMesure:_mesureParRec});
  const _rowByRec = {}; _A.rows.forEach(r=>{ _rowByRec[r.recipeId]=r; });
  _recipeMultCache = {}; // {recipeId: {rendement, items:[{nom,unite,qteParBatch(affichée),base}]}}
  // Affichage : denrées (kg) → grammes ; autres → unité native.
  const dispOf = id => { const u=matUnit(id); const m=(mats.find(x=>x.id===id)||{}); const kg=(m.categorie!=='emballage'&&u==='kg'); return kg?{u:'g',f:1000}:{u,f:1}; };
  const blocks=[];
  for(const r of recipes){
    const items = await db.recipeItems.where('recipeId').equals(r.id).toArray();
    // Texte cherchable de la recette : nom + tous les noms d'ingrédients + tous les allergènes.
    // Permet une recherche discriminante (« œufs » → recettes en contenant ; « sulfite » → idem).
    const _searchTxt = _recNorm([
      r.produitNom||'',
      ...items.map(it=>matName(it.materialId)),
      ...((r.allergenes||[])),
      ...items.map(it=>it.etiquette||'')
    ].join(' '));
    _recipeMultCache[r.id] = { rendement:+r.rendement||1,
      items: items.map(it=>{ const d=dispOf(it.materialId); return {nom:matName(it.materialId), unite:d.u, qteParBatch:round3((+it.qteParBatch||0)*d.f)}; }) };
    const rows = items.map((it,idx)=>{ const d=dispOf(it.materialId); const shown=round3((+it.qteParBatch||0)*d.f);
      const tags=[it.partie||'', it.etiquette||''].filter(Boolean).join(' · ');
      return `<div class="ing-row">
        <div class="ing-nom">${esc(matName(it.materialId))}${tags?`<span class="ing-tag">${esc(tags)}</span>`:''}</div>
        <div class="ing-qtes">
          <span class="ing-base">${qty(shown)} ${esc(d.u)}</span>
          <span class="ing-mult" id="mult_${r.id}_${idx}"><b>${qty(shown)}</b> ${esc(d.u)}</span>
        </div>
      </div>`; }).join('');
    blocks.push(`<div class="panel rec-card" data-search="${esc(_searchTxt)}"><h2>${esc(r.produitNom)} ${r.grandFormat?'<span class="tag" style="background:#8a6d3b;color:#fff;font-size:.62rem">🍪 grand format</span> ':''}${(function(){const cc=recCoqueColors(r);return cc.length?`<span class="tag" style="background:#fff;border:1px solid #e5d8c8;color:#7a6a60;font-size:.62rem">${cc.map(k=>coqueCouleurPastille(k)).join('')}${cc.map(k=>coqueCouleurLabel(k)).join(' + ')}</span> `:'';})()}${r.coquesCongelObligatoire?'<span class="tag" style="background:#3b6ea5;color:#fff;font-size:.62rem">❄️ coques congelées</span> ':''}${(r.ganacheDelaiH!=null&&+r.ganacheDelaiH>0)?`<span class="tag" style="background:#8a6d3b;color:#fff;font-size:.62rem">⏱ ganache ${r.ganacheDelaiH}h</span> `:''}${(r.maturationH!=null)?`<span class="tag" style="background:#5b8a72;color:#fff;font-size:.62rem">🧊 matur. ${r.maturationH}h</span> `:''}${r.congelObligatoire?'<span class="tag" style="background:#3b6ea5;color:#fff;font-size:.62rem">❄️ congel. obligatoire</span> ':''}${r.jourJUniquement?'<span class="tag" style="background:#a5453b;color:#fff;font-size:.62rem">📅 jour J</span> ':''}${(r.heuresMaxSortie!=null&&+r.heuresMaxSortie>0)?`<span class="tag" style="background:#a5453b;color:#fff;font-size:.62rem">⏳ ${r.heuresMaxSortie}h max</span> `:''}<span style="font-weight:400;font-size:.85rem;color:#9a8a82">— rendement ${r.rendement} / batch</span>
      <span><span class="act" onclick="recForm(${r.id})">Modifier</span><span class="act del" onclick="delRec(${r.id})">Suppr.</span></span></h2>
      ${(()=>{ const rr=_rowByRec[r.id]; if(!rr) return ''; const c=rr.cost;
        return `<div class="sum-box" style="margin:0 0 8px"><span>Coût de revient ${euro(c.coutRevientUnit)}/pc ${kpiI('cout_revient_rec')}${rr.prixVenteMoyen!=null?` · vente moy. ${euro(rr.prixVenteMoyen)} · marge ${rr.margeUnit!=null?euro(rr.margeUnit):'—'}`:''}</span>
          <b><span class="tag" style="background:${rr.scale.col};color:#fff">${rr.scale.dot} ${rr.tauxMarge!=null?rr.tauxMarge+'%':'coût seul'}</span>${rr.tauxMarge!=null?' '+kpiI('taux_marge_rec'):''}</b></div>${coutRevientBar(c)}`; })()}
      ${(r.allergenes&&r.allergenes.length)?`<div class="note" style="margin:0 0 8px"><b>Allergènes :</b> ${r.allergenes.map(a=>esc(a)).join(' · ')}</div>`:'<div class="note" style="margin:0 0 8px;color:#b08a3a">⚠ Allergènes non renseignés</div>'}
      ${instructionsVoletHtml(r.instructions, 'rec'+r.id)}
      ${items.length?`
      <div class="mult-bar">
        <label>Quantité voulue</label>
        <input type="number" min="1" step="1" id="multQ_${r.id}" value="${r.rendement}" oninput="recipeMultiply(${r.id},this.value)">
        <span class="note" style="margin:0">pièce(s)</span>
        <span style="flex:1"></span>
        ${[0.5,1,2,3].map(m=>`<button type="button" class="btn ghost sm" onclick="recipeMultiplyFactor(${r.id},${m})">×${m}</button>`).join('')}
      </div>
      <div class="ing-list">
        <div class="ing-head"><span class="ing-nom-h">Matière</span><div class="ing-qtes"><span class="ing-base">Par batch</span><span class="ing-mult" id="multHead_${r.id}">Pour ${r.rendement} pc</span></div></div>
        ${rows}
      </div>
      <p class="note">Recalcul à la volée selon la quantité voulue — la recette de base n'est jamais modifiée.</p>`
      :`<div class="empty">Aucun ingrédient défini.</div>`}</div>`);
  }
  document.getElementById('main').innerHTML=`
   <div class="topbar"><div><h1>Recettes (BOM)</h1><p>${recipes.length} recette(s) — nomenclature matières</p></div>
     <button class="btn" onclick="recForm()">+ Nouvelle recette</button><button class="btn ghost" onclick="ouvrirFusionRecettes()">🔗 Fusionner des doublons</button></div>
   ${recipes.length?`<div class="panel"><input class="search" id="recSearch" style="width:100%;margin-bottom:8px" placeholder="Parfum, ingrédient (ex. « œufs »), allergène (ex. « sulfite »)…" value="${esc(recSearch||'')}" oninput="filterRecipes(this.value)" autocomplete="off" autocapitalize="off" autocorrect="off">
     <p class="note" id="recSearchInfo" style="margin:0">Cherche dans les noms, les ingrédients et les allergènes.</p></div>`:''}
   <div id="recList">${recipes.length?blocks.join(''):`<div class="panel"><div class="empty">Aucune recette. Une recette définit les matières consommées par batch (le « Bill of Materials »).</div></div>`}</div>`;
  if(recSearch) filterRecipes(recSearch);   // ré-applique le filtre courant après re-render
}
// Cache des recettes pour le multiplicateur dynamique (lecture seule, aucune écriture en base)
let _recipeMultCache={};
// Normalisation pour la recherche recettes : comme normTxt + gère les ligatures françaises
// (œ→oe, æ→ae) pour que « oeufs » trouve « œufs », et retire l'apostrophe.
function _recNorm(s){ return normTxt(s).replace(/œ/g,'oe').replace(/æ/g,'ae').replace(/['’]/g,' '); }
// Filtre les cartes recette par recherche libre (nom, ingrédients, allergènes). Discriminant :
// chaque mot tapé doit être présent (logique ET) → « œufs » ne montre que les recettes en
// contenant ; « sulfite » ne montre que celles avec cet allergène.
function filterRecipes(q){
  recSearch = q||'';
  const terms = _recNorm(q||'').split(/\s+/).filter(Boolean);
  const cards = document.querySelectorAll('#recList .rec-card');
  let visibles = 0;
  cards.forEach(card=>{
    const hay = card.getAttribute('data-search')||'';
    const ok = terms.every(t=>hay.includes(t));   // tous les mots présents
    card.style.display = ok ? '' : 'none';
    if(ok) visibles++;
  });
  const info = document.getElementById('recSearchInfo');
  if(info){
    info.textContent = terms.length
      ? `${visibles} recette(s) correspondante(s).`
      : 'Cherche dans les noms, les ingrédients et les allergènes.';
  }
}
// Recalcule les poids d'ingrédients pour une quantité cible (en pièces).
function recipeMultiply(recipeId, targetQ){
  const rec=_recipeMultCache[recipeId]; if(!rec) return;
  const target=Math.max(0,+targetQ||0);
  const factor = rec.rendement>0 ? target/rec.rendement : 0;
  rec.items.forEach((it,idx)=>{
    const cell=document.getElementById(`mult_${recipeId}_${idx}`);
    if(cell){ cell.innerHTML=`<b>${qty(round3(it.qteParBatch*factor))}</b> ${esc(it.unite)}`; }
  });
  const head=document.getElementById(`multHead_${recipeId}`);
  if(head) head.textContent = `Pour ${qty(target)} pièce(s)`;
}
// Applique un facteur multiplicateur (×0.5, ×2, ×3…) relatif au rendement de base.
function recipeMultiplyFactor(recipeId, factor){
  const rec=_recipeMultCache[recipeId]; if(!rec) return;
  const target=round3(rec.rendement*factor);
  const input=document.getElementById(`multQ_${recipeId}`);
  if(input) input.value=target;
  recipeMultiply(recipeId, target);
}
let bomDraft=[];
