/* ============================================================
   COMMANDES  (+ liaison aux batchs = traçabilité aval)
   ============================================================ */
// Normalise l'ancien statut « En cours » vers la nouvelle structure
function normStatus(st){ return st==='En cours' ? 'À préparer' : (st || 'À préparer'); }
// Pastille colorée selon le statut
// ── GARDE-FOU LIVRAISON (couverture de traçabilité) ─────────────────────────
// Passer une commande en « Livrée » exige que CHAQUE parfum ait ses lots reliés,
// et que la SOMME des quantités liées couvre la quantité commandée (par parfum).
//  - Le décompte du stock se fait à la LIAISON (picking ou « Lier des batchs »),
//    pas ici : cette fonction ne fait que CONTRÔLER la couverture.
//  - Les lots de migration (histo) sont éligibles, mais sélectionnés manuellement
//    comme les autres (ils apparaissent déjà dans la fenêtre « Lier des batchs »).
//  - Si la couverture est incomplète → on OUVRE « Lier des batchs » pour compléter.
// Retourne true si la livraison est autorisée (couverture complète), false sinon.
/* RDTRACE:PURE:BEGIN */
// [TRAÇABILITÉ LIVRAISON] Imputation PURE des lots liés aux besoins par parfum.
// Corrige deux défauts historiques qui faisaient croire à une PERTE des liaisons :
//  1. les lots LIBRES (reprise/découverte) comptaient pour zéro (nom lu uniquement via la
//     recette, jamais via produitLibre) → blocage « 0/xx » partout alors que tout était lié ;
//  2. l'imputation gloutonne envoyait TOUT un lot sur le premier parfum qui matchait par
//     inclusion (« Chocolat » absorbait le lot « Chocolat framboise ») → faux manques.
// Désormais : nom du lot = produitLibre si libre, sinon nom de recette (aligné sur le scan
// et prodNomComplet) ; répartition en DEUX PASSES (correspondance exacte d'abord, inclusion
// ensuite) avec PLAFOND au besoin restant. Fonction pure (zéro DB/DOM) → testable en Node.
function _traceImputeLots(needs, links, prodsById, recById){
  const recName = id => (recById[id]||{}).produitNom||'';
  const prodNom = p => p.libre ? (p.produitLibre||'') : recName(p.recipeId);
  const flavorsNeeded = Object.keys(needs).filter(f=>needs[f]>0);
  const gfOk = (needKey, p) => isGFKey(needKey) === !!(recById[p.recipeId] && recById[p.recipeId].grandFormat);
  const matchExact = (k,p) => gfOk(k,p) && normTxt(gfBase(k))===normTxt(prodNom(p));
  const matchLarge = (k,p) => gfOk(k,p) && pickFlavorMatch(gfBase(k), prodNom(p));
  const couvert={}; flavorsNeeded.forEach(f=>couvert[f]=0);
  const restes=[]; const recap=[];
  for(const lk of links){
    const p = prodsById[lk.productionId];
    if(!p) continue;
    restes.push({qte:round3(+lk.qte||0), p});
    recap.push({nom:prodNom(p)||'(sans nom)', lot:p.lotProduction||('#'+p.id), qte:round3(+lk.qte||0)});
  }
  for(const match of [matchExact, matchLarge]){
    for(const r of restes){
      for(const f of flavorsNeeded){
        if(r.qte<=0) break;
        const m = round3(needs[f]-couvert[f]);
        if(m<=0 || !match(f, r.p)) continue;
        const take = Math.min(r.qte, m);
        couvert[f] = round3(couvert[f]+take);
        r.qte = round3(r.qte-take);
      }
    }
  }
  const nonImpute = round3(restes.reduce((s2,r)=>s2+r.qte,0));
  const manques = flavorsNeeded
    .filter(f => round3(couvert[f]) + 1e-9 < round3(needs[f]))
    .map(f => ({flavor:f, manque:round3(needs[f]-couvert[f]), besoin:round3(needs[f]), lie:round3(couvert[f])}));
  return {couvert, manques, recap, nonImpute};
}
// Récapitulatif HTML des lots déjà liés : affiché dans les modals de blocage pour que
// l'utilisateur voie que RIEN n'est perdu (et ne refasse pas la liaison = double décompte).
function _traceRecapHtml(recap){
  if(!recap || !recap.length) return '';
  return `<div class="sum-box" style="flex-direction:column;align-items:stretch;gap:4px;margin-top:10px">
    <span style="font-size:.74rem;color:#7a6a62;text-transform:uppercase;font-weight:600">Lots déjà liés — rien n'est perdu</span>
    ${recap.map(r=>`<div style="display:flex;justify-content:space-between;font-size:.84rem"><span>${esc(r.nom)} <span style="color:#9a8a82">· ${esc(r.lot)}</span></span><b>× ${qty(r.qte)}</b></div>`).join('')}
    <p class="note" style="margin:4px 0 0">⚠ Ces lots restent réservés à cette commande : ne les relie PAS une seconde fois, complète uniquement ce qui manque.</p>
  </div>`;
}
// [DIAG TRAÇABILITÉ] Encart de diagnostic VISIBLE (temporaire) : montre l'état brut en base
// pour cette commande — nombre de liaisons trouvées pour cet orderId, leur somme, et le nombre
// TOTAL de liaisons dans la base (pour détecter d'éventuelles liaisons mal rattachées).
// But : rendre la vérité observable sur l'appareil de l'utilisateur (au lieu de deviner).
async function _traceDiag(orderId, links){
  try{
    const nLoc = (links||[]).length;
    const sLoc = round3((links||[]).reduce((s,e)=>s+(+e.qte||0),0));
    const allItems = await db.orderItems.toArray().catch(()=>[]);
    const nAll = allItems.length;
    const autres = allItems.filter(it=>+it.orderId!==+orderId).length;
    return `<div style="margin-top:10px;padding:8px 10px;border:1px dashed #b08a3a;border-radius:10px;background:#fbf5ea;font-size:.72rem;color:#7a6a52;line-height:1.5">
      <b>🔎 Diagnostic (temporaire)</b><br>
      commande n° <b>${orderId}</b> · liaisons trouvées : <b>${nLoc}</b> (somme ${qty(sLoc)})<br>
      total liaisons en base : <b>${nAll}</b> · rattachées à d'autres commandes : <b>${autres}</b><br>
      <span style="color:#9a8576">Si ce nombre est 0 alors qu'un batch a bien été lié, envoie cette capture à ton dev.</span>
    </div>`;
  }catch(e){ return ''; }
}
/* RDTRACE:PURE:END */
async function ensureOrderDecremented(orderId){
  const o = await db.orders.get(orderId);
  if(!o) return false;
  // Les commandes « historiques » (migration) n'exigent ni production ni picking.
  if(o.histo===true) return true;
  // [v1421] Idem pour une commande MÈRE rangée (paiement en avance, retraits échelonnés) : la
  // traçabilité est portée par ses commandes filles, chacune au jour de son retrait. Exiger en
  // plus une couverture de lots sur la mère reviendrait à demander DEUX fois la même preuve.
  if(o.mereEnAttente===true) return true;

  // Nombre TOTAL de macarons de la commande, indépendamment du détail des parfums
  // (coffret → taille, événement → evQte, vrac/don → parfums, grand format → items).
  // Sert de filet quand les parfums ne sont pas détaillés ligne par ligne.
  let totMac = 0;
  orderToLines(o).forEach(ln=>{
    if(ln.type==='coffret') totMac += +ln.taille||0;
    else if(ln.type==='evenement') totMac += +ln.evQte||0;
    else if(ln.type==='vrac'||ln.type==='sachet') totMac += (ln.parfums||[]).reduce((s,p)=>s+(+p.qte||0),0) + (+ln.sansParfum||0);
    else if(ln.type==='don'){ totMac += (ln.parfums||[]).reduce((s,p)=>s+(+p.qte||0),0) + (ln.items||[]).reduce((s,p)=>s+(+p.qte||0),0); }
    else if(ln.type==='grand') totMac += (ln.items||[]).reduce((s,p)=>s+(+p.qte||0),0);
  });
  if(round3(totMac) <= 0) return true;

  // Besoins par parfum (clé GF marquée pour les grands formats : stock séparé).
  const needs = orderFlavorNeeds(o);
  const flavorsNeeded = Object.keys(needs).filter(f=>needs[f]>0);

  // CAS PARTICULIER : la commande contient des macarons mais SANS détail de parfums
  // (parfums non renseignés sur les lignes). On ne peut pas contrôler par parfum, mais on
  // exige quand même une couverture GLOBALE : la somme des lots liés doit atteindre le total.
  if(!flavorsNeeded.length){
    const links0 = await db.orderItems.where('orderId').equals(orderId).toArray().catch(()=>[]);
    const lieTotal = links0.reduce((s,e)=>s+(+e.qte||0),0);
    if(round3(lieTotal) + 1e-9 >= round3(totMac)) return true;   // couverture globale suffisante
    // Récapitulatif transparent des lots déjà liés (évite de croire que tout est perdu).
    const _rec0 = await db.recipes.toArray().catch(()=>[]);
    const _recById0 = {}; _rec0.forEach(r=>{ _recById0[r.id]=r; });
    const _prodsById0 = {};
    for(const lk of links0){ if(!(lk.productionId in _prodsById0)) _prodsById0[lk.productionId] = await db.productions.get(lk.productionId).catch(()=>null); }
    const _recap0 = _traceImputeLots({}, links0, _prodsById0, _recById0).recap;
    const _diagG = await _traceDiag(orderId, links0);
    openModal(`<h3 style="color:#b3261e">⛔ Traçabilité incomplète</h3>
      <p style="margin-top:8px">Cette commande contient <b>${qty(totMac)} macaron(s)</b> mais seulement <b>${qty(lieTotal)}</b> sont reliés à des lots.</p>
      ${_traceRecapHtml(_recap0)}
      ${_diagG}
      <p class="note">Relie des batchs pour couvrir toute la commande (les lots de reprise sont sélectionnables ici).</p>
      <div class="modal-actions">
        <button class="btn ghost" onclick="closeModal()">Annuler</button>
        <button class="btn gold" onclick="cmdLink(${orderId})">Lier des batchs →</button>
      </div>`);
    return false;
  }

  const recipes = await db.recipes.toArray();
  const recById = {}; recipes.forEach(r=>{ recById[r.id]=r; });

  const links = await db.orderItems.where('orderId').equals(orderId).toArray().catch(()=>[]);
  const prodsById = {};
  for(const lk of links){
    if(!(lk.productionId in prodsById)) prodsById[lk.productionId] = await db.productions.get(lk.productionId).catch(()=>null);
  }
  // Imputation par la fonction PURE (lots libres reconnus, répartition exacte puis inclusive,
  // plafond au besoin). Voir _traceImputeLots pour le détail des corrections.
  const {manques, recap, nonImpute} = _traceImputeLots(needs, links, prodsById, recById);

  if(manques.length){
    const dispName = k => isGFKey(k) ? (gfBase(k)+' (grand format)') : k;
    const detail = manques.map(m=>`${esc(dispName(m.flavor))} : ${qty(m.lie)}/${qty(m.besoin)} (manque ${qty(m.manque)})`).join('<br>');
    const avertNonImpute = nonImpute>0
      ? `<p class="note" style="color:#b08a3a">ℹ️ ${qty(nonImpute)} macaron(s) déjà lié(s) n'ont pas pu être rattachés à un parfum de la commande (nom différent) — vérifie que les parfums saisis correspondent bien aux lots.</p>`
      : '';
    openModal(`<h3 style="color:#b3261e">⛔ Traçabilité incomplète</h3>
      <p style="margin-top:8px">Avant de livrer, chaque parfum doit avoir ses lots reliés (la somme doit couvrir la quantité commandée) :</p>
      ${flavorPills(manques.map(m=>({nom:dispName(m.flavor),suffix:qty(m.lie)+'/'+qty(m.besoin)+' (manque '+qty(m.manque)+')',state:'manque'})))}
      ${avertNonImpute}
      ${_traceRecapHtml(recap)}
      ${await _traceDiag(orderId, links)}
      <p class="note">Les lots de reprise (migration) sont sélectionnables ici comme les autres.</p>
      <div class="modal-actions">
        <button class="btn ghost" onclick="closeModal()">Annuler</button>
        <button class="btn gold" onclick="cmdLink(${orderId})">Lier des batchs →</button>
      </div>`);
    return false;
  }
  return true;   // couverture complète → livraison autorisée
}

// Changement rapide : passe au statut suivant (À préparer → Terminée → Livrée → …)
// Définit un statut précis (depuis la fiche détail)
async function setOrderStatus(id, statut){
  if(statut==='Livrée'){
    const ok = await ensureOrderDecremented(id);
    if(!ok){ renderCmd(); return; }   // bloqué : statut inchangé
  }
  await db.orders.update(id, {statut});
  closeModal(); renderCmd(); toast('Statut : '+statut);
}

/* ============================================================
   BBC — PAIEMENT RAPIDE
   ============================================================ */
// ---- TRAÇABILITÉ DES PAIEMENTS (registre + solde) ----
// Chaque commande porte un registre paiements:[{date, montant, moyen}].
// Le solde dû et le statut dérivent de ce registre + du montant total.
function orderPaid(o){
  if((!o.paiements || !o.paiements.length) && o.paiement==='Payé'){ return money2(o.montant); } // rétro-compat
  return money2((o.paiements||[]).reduce((s,p)=>s+((+p.montant)||0),0));
}
function orderBalance(o){ return money2(((+o.montant)||0) - orderPaid(o)); }
// Statut dérivé : Payé (solde ≤ 0), Partiel (encaissé > 0), sinon En attente.
function orderPayStatus(o){
  // [v1407] Une commande FILLE (commandeMereId renseigné) est réputée PAYÉE : son argent a déjà
  // été encaissé, une seule fois, sur la commande mère. Sans ce cas particulier, elle
  // apparaîtrait « En attente » partout dans l'app (listes, bouton « Solder »…) alors qu'elle
  // est en réalité déjà réglée — source de confusion et de double-encaissement par erreur.
  if(o && o.commandeMereId!=null) return 'Payé';
  const total=(+o.montant)||0, paid=orderPaid(o);
  if(total>0 && paid+1e-9>=total) return 'Payé';
  if(paid>0) return 'Partiel';
  return 'En attente';
}
// Synchronise les champs hérités (paiement/datePaiement/reglement) à partir du registre,
// pour rester cohérent avec tous les lecteurs existants (liste, export, stats, prévisionnel).
// ════════════════════════════════════════════════════════════════════════════
// [v1342] FIGER LE COÛT MATIÈRE À L'ENCAISSEMENT — on éteint la dette.
//
// LE CONSTAT : `estimateOrderMaterialCost()` est RECALCULÉ à chaque affichage, sur les lots
// RESTANTS aujourd'hui (`coutMatiereFifoReel` filtre sur qteRestante > 0). Un lot acheté en
// décembre et consommé depuis a qteRestante = 0 : il est filtré, il a DISPARU. Le coût matière
// d'une vente passée n'est donc pas conservé — il est reconstruit, et de plus en plus faux à
// mesure que les lots d'époque s'épuisent.
//
// On ne peut pas réparer hier. On peut arrêter de perdre demain : à chaque encaissement, on
// ÉCRIT le coût matière estimé À CET INSTANT, avec les lots de cet instant. Dans quelques mois,
// « ma marge de janvier » aura une vraie réponse — mesurée, pas reconstituée.
//
// TROIS PRÉCAUTIONS, chacune payée par un bug de cette série :
//  • On n'écrase JAMAIS un `coutMatFige` existant (v1339 : un statut réécrit finit par mentir).
//  • On horodate (`coutMatFigeLe`) : un chiffre sans date est un chiffre qu'on ne peut plus auditer.
//  • En cas d'échec, on ne met PAS 0 — on laisse `undefined`. La v1326 a gravé que METTRE 0 N'EST
//    PAS S'ABSTENIR : c'est affirmer que la matière était gratuite. `undefined` dit « je ne sais pas ».
async function figerCoutMatiere(o){
  try{
    if(!o || o.coutMatFige != null) return o;              // déjà figé → on ne réécrit jamais
    // [v1351] BUG CRITIQUE TROUVÉ EN RELISANT LE MODULE DU GÉNÉRATEUR : `db.lots` N'EXISTE PAS
    // dans le schéma (la table réelle est `materialLots`, ligne 300 de db.version(1).stores).
    // `db.lots.toArray()` levait une exception Dexie à CHAQUE appel depuis la v1342, avalée par
    // le catch ci-dessous : AUCUN symptôme visible, AUCUNE commande n'a jamais été figée. Le
    // principe gravé en v1342 (« on éteint la dette pour l'avenir ») n'a jamais été appliqué en
    // pratique — deux vagues de silence, jusqu'à ce que la relecture du code du générateur (qui
    // avait la MÊME faute de frappe) le révèle par ricochet.
    const [recipes, recipeItems, lots] = await Promise.all([
      db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray()
    ]);
    const c = estimateOrderMaterialCost(o, recipes, recipeItems, lots);
    if(c == null || !isFinite(c)) return o;                // échec → on laisse VIDE, jamais 0
    o.coutMatFige   = money2(c);
    o.coutMatFigeLe = today();
    return o;
  }catch(e){ swallow(e,'figerCoutMatiere'); return o; }    // jamais bloquer un encaissement pour ça
}
function syncPaymentFields(o){
  o.paiements = (o.paiements||[]).filter(p=>p && (+p.montant)||p.moyen||p.date);
  const st=orderPayStatus(o);
  o.paiement = (st==='Payé') ? 'Payé' : 'En attente'; // lecteurs binaires : Partiel compte comme non soldé
  o.statutPaiement = st;                               // statut fin (3 états) pour l'affichage
  o.soldeDu = orderBalance(o);
  o.montantEncaisse = orderPaid(o);
  if(o.paiements.length){
    const last=o.paiements[o.paiements.length-1];
    // datePaiement = date du dernier règlement (ou la plus tardive si soldé). Jamais auto-générée.
    o.datePaiement = (st==='Payé') ? (o.paiements.reduce((d,p)=>p.date&&p.date>d?p.date:d,'')) : (last.date||'');
    o.reglement = last.moyen || o.reglement || '';
  }
  return o;
}

// Réglage : automatisation du statut de paiement quand un règlement est saisi.
// Stocké dans localStorage, activé par défaut, désactivable par l'utilisateur.
function autoPayEnabled(){ return true; } // toujours actif : auto-solde automatique à l'encaissement (plus de case)

// Applique le paiement sur un objet commande (mutation en place) de façon cohérente :
// si un règlement est présent ET l'auto-paiement actif → Payé + date du jour.
// Garantit l'absence de conflit règlement/paiement.

// Action « Solder » : ouvre un encaissement du solde, SANS date auto — l'utilisateur saisit date + mode.
// [AUDIT-2026-07 · A2-opt] Bascule l'affichage de la rentabilité entre « avec MO » et « sans MO ».
// Pur DOM : lit les valeurs pré-calculées (data-*) posées par cmdView, sans recalcul ni persistance.
// Le calcul sous-jacent reste TOUJOURS au coût complet (cohérence entre écrans) ; ceci n'est qu'une VUE.
function toggleMargeMO(id){
  const blk=document.getElementById('margeMOBlock_'+id);
  const btn=document.getElementById('moToggleBtn_'+id);
  if(!blk||!btn) return;
  const avecMO = btn.getAttribute('data-mo')==='1';   // état courant : true = on affiche AVEC MO
  const next = !avecMO;                                 // on bascule
  const g=(k)=>blk.getAttribute(k);
  const euroFmt=(typeof euro==='function')?euro:(v=>((+v||0).toFixed(2))+' €');
  const cm  = next ? g('data-cmavec') : g('data-cmsans');
  const mb  = next ? g('data-mbavec') : g('data-mbsans');
  const txb = next ? g('data-txbavec'): g('data-txbsans');
  const mn  = next ? g('data-mnavec') : g('data-mnsans');
  const txn = next ? g('data-txnavec'): g('data-txnsans');
  const vCoutmat=blk.querySelector('.v-coutmat'); if(vCoutmat) vCoutmat.textContent=euroFmt(cm);
  const vMb=blk.querySelector('.v-mb'); if(vMb) vMb.textContent=euroFmt(mb)+' ('+txb+'%)';
  const vMn=blk.querySelector('.v-mn'); if(vMn){ vMn.textContent=euroFmt(mn)+' ('+txn+'%)'; vMn.style.color=(+mn<0?'#b3261e':'#2e7d32'); }
  const lbl=blk.querySelector('.mo-lbl'); if(lbl) lbl.textContent = next ? '(par parfum, avec MO)' : '(par parfum, hors MO)';
  const moOnly=blk.querySelector('.mo-only'); if(moOnly) moOnly.style.display = next ? '' : 'none';
  btn.setAttribute('data-mo', next?'1':'0');
  btn.textContent = next ? 'Voir sans main-d\'œuvre' : 'Voir avec main-d\'œuvre';
}
async function markPaid(id, fromModal){
  const o=await db.orders.get(id); if(!o) return;
  if(orderPayStatus(o)==='Payé'){ toast('Déjà soldée'); return; }
  const reste=orderBalance(o);
  if(reste<=0){ toast('Rien à encaisser'); return; }
  openModal(`<h3>Encaisser le solde</h3>
    <p class="note">Solde restant dû : <b>${euro(reste)}</b>. Renseignez la date réelle du règlement (libre) et le mode.</p>
    <div class="field"><label>Montant encaissé (€)</label><input type="number" step="0.01" min="0" id="solde_mt" value="${reste}"></div>
    <div class="field"><label>Date de règlement</label><input type="date" id="solde_date" value=""></div>
    <div class="field"><label>Mode de paiement</label>
      <select id="solde_moyen"><option value="">— mode —</option>${PAY_METHODS.map(m=>`<option>${m}</option>`).join('')}</select></div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="confirmMarkPaid(${id},${fromModal?1:0})">Enregistrer l'encaissement</button>
    </div>`);
}
async function confirmMarkPaid(id, fromModal){
  const mt=money2(+(document.getElementById('solde_mt')?.value)||0);
  const date=document.getElementById('solde_date')?.value||'';
  const moyen=document.getElementById('solde_moyen')?.value||'';
  if(mt<=0){ toast('Montant requis'); return; }
  if(!date){ toast('Date de règlement obligatoire'); return; }
  if(!moyen){ toast('Mode de paiement obligatoire'); return; }
  const o=await db.orders.get(id); if(!o) return;
  o.paiements=(o.paiements||[]).concat([{date, montant:mt, moyen}]);
  syncPaymentFields(o);
  await figerCoutMatiere(o);   // [v1342] idem — UN SEUL point de gel, appelé aux DEUX écritures (règle C, v1340)
  await db.orders.update(id, {paiements:o.paiements, paiement:o.paiement, statutPaiement:o.statutPaiement,
    soldeDu:o.soldeDu, montantEncaisse:o.montantEncaisse, datePaiement:o.datePaiement, reglement:o.reglement,
    coutMatFige:o.coutMatFige, coutMatFigeLe:o.coutMatFigeLe});
  closeModal();
  renderCmd();
  toast('Encaissement enregistré ✓ ('+euro(mt)+' le '+fmtDate(date)+')');
}
let cmdSearch='';
// [COCKPIT — filtre jour] Date ISO (AAAA-MM-JJ) sur laquelle filtrer les commandes (sur o.date),
// ou null = pas de filtre. Positionné par le Copilote (« commandes de demain ») ou effaçable à la main.
let cmdJourFiltre=null;
let _cmdCache=null;
// --- Filtres par tags libres empilables (cumul en ET, par-dessus la recherche texte) ---
// Un tag = une facette structurée "categorie:valeur" (ex. "format:8", "parfum:framboise",
// "annee:2026", "type:coffret", "paiement:paye"). Les tags ne s'affichent PAS dans le tableau :
// ils servent uniquement au filtrage. L'ensemble actif est conservé entre les frappes.
let cmdTags = new Set();
// Calcule les facettes d'une commande à partir de ses lignes déjà résolues.
// Retourne un tableau de {cat, val, label} — cat/val normalisés (filtrage), label lisible (pastille).
function orderFacets(o, lignes, client){
  const out=[]; const seen=new Set();
  const add=(cat,val,label)=>{ const key=cat+':'+normTxt(String(val)); if(!seen.has(key)){ seen.add(key); out.push({cat, val:normTxt(String(val)), label, key}); } };
  // Année (depuis la date de commande)
  const an=(o.date||'').slice(0,4); if(an) add('annee', an, an);
  // Mois (libellé court FR) — utile pour retrouver « décembre », « juin »…
  if(o.date){ const mo=new Date(o.date); if(!isNaN(mo)){ const ml=mo.toLocaleDateString('fr-FR',{month:'long'}); add('mois', ml, ml.charAt(0).toUpperCase()+ml.slice(1)); } }
  lignes.forEach(ln=>{
    // Type de ligne
    if(ln.type) add('type', ln.type, ln.type==='coffret'?'Coffret':ln.type==='grand'?'Grand format':ln.type==='evenement'?'Événement':ln.type);
    // Format (taille) pour les coffrets
    if(ln.type==='coffret' && ln.taille) add('format', ln.taille, 'Coffret '+ln.taille);
    // Parfums (coffrets + événements)
    (ln.parfums||[]).forEach(p=>{ if(p && p.nom) add('parfum', p.nom, p.nom); });
    // Produits (grands formats)
    (ln.items||[]).forEach(p=>{ if(p && p.nom) add('parfum', p.nom, p.nom); });
    // Personnalisation couleur présente sur la ligne
    if(ln.persoCouleurs && (Array.isArray(ln.persoCouleurs)?ln.persoCouleurs.length:ln.persoCouleurs)) add('option', 'perso', 'Perso couleur');
  });
  // Statut de paiement (réutilise la logique existante)
  const st = orderPayStatus(o);
  if(st) add('paiement', st, st);
  // Statut de commande (à préparer / prête / livrée) — pour retrouver vite ce qui reste à faire.
  const sc = normStatus(o.statut);
  if(sc) add('statut', sc, sc==='Terminée'?'Prête':sc);
  // Remise appliquée (globale ou de ligne)
  const aRemise = (+o.remiseGlobale>0) || (lignes||[]).some(l=>+l.remisePct>0 || +l.remiseEuro>0);
  if(aRemise) add('remise', 'oui', 'Avec remise');
  // Type de client (pro / particulier), si renseigné
  if(client && client.type){ const t=normTxt(client.type); if(t.includes('pro')) add('client','pro','Client pro'); else add('client','particulier','Client particulier'); }
  return out;
}
// Une commande (entrée de cache) satisfait-elle TOUS les tags actifs ? (ET logique)
function cmdMatchTags(entry){
  if(!cmdTags.size) return true;
  const facetKeys = new Set((entry._facets||[]).map(f=>f.key));
  for(const t of cmdTags){ if(!facetKeys.has(t)) return false; }
  return true;
}
function cmdToggleTag(key){
  if(cmdTags.has(key)) cmdTags.delete(key); else cmdTags.add(key);
  _cmdRenderTagBar();
  cmdFilter(cmdSearch);
}
function cmdClearTags(){ cmdTags.clear(); _cmdRenderTagBar(); cmdFilter(cmdSearch); }

// ════════════════════════════════════════════════════════════════════════
//  RÉCAP MACARONS PAR PARFUM SUR UNE PÉRIODE (écran Commandes)
//  Compte les macarons commandés par parfum entre deux dates (filtre sur la
//  date d'événement/livraison), avec un sélecteur de statut. Aide à anticiper
//  la production et repérer les parfums qui tournent.
// ════════════════════════════════════════════════════════════════════════
let _cmdPeriodOpen = false;
function cmdPeriodToggle(){
  _cmdPeriodOpen = !_cmdPeriodOpen;
  const z=document.getElementById('cmdPeriodBox');
  if(z) z.style.display = _cmdPeriodOpen ? 'block' : 'none';
  if(_cmdPeriodOpen && !document.getElementById('cmdPeriodResult').dataset.done){ cmdPeriodCompute(); }
}
// Date retenue pour le filtre : date d'événement si présente, sinon date de commande.
function _orderRefDate(o){ return o.dateEvenement || o.date || ''; }
async function cmdPeriodCompute(){
  const d1 = (document.getElementById('cmdPeriodFrom')||{}).value || '';
  const d2 = (document.getElementById('cmdPeriodTo')||{}).value || '';
  const stFilter = (document.getElementById('cmdPeriodStatut')||{}).value || 'tous';
  const res = document.getElementById('cmdPeriodResult');
  if(!res) return;
  const orders = (await db.orders.toArray()).filter(o=>!o.histo);
  // filtre période (sur date d'événement/livraison) + statut
  const inRange = orders.filter(o=>{
    const dt=_orderRefDate(o); if(!dt) return false;
    if(d1 && dt<d1) return false;
    if(d2 && dt>d2) return false;
    if(stFilter!=='tous' && normStatus(o.statut)!==stFilter) return false;
    return true;
  });
  // agrégation par parfum
  const parParfum={}; let totalMac=0; let nbCmd=0;
  inRange.forEach(o=>{
    let dem={}; try{ dem=_orderParfumDemand(o)||{}; }catch(e){ dem={}; }
    let cmdHasMac=false;
    Object.entries(dem).forEach(([nom,q])=>{ if(+q>0){ parParfum[nom]=(parParfum[nom]||0)+(+q); totalMac+=(+q); cmdHasMac=true; } });
    if(cmdHasMac) nbCmd++;
  });
  const lignes = Object.entries(parParfum).sort((a,b)=>b[1]-a[1]);
  // libellé période lisible
  const fmtP = s => s ? fmtDate(s) : '…';
  const periodeLbl = `${fmtP(d1)} → ${fmtP(d2)}`;
  if(!lignes.length){
    res.innerHTML = `<p class="note" style="margin-top:8px">Aucun macaron commandé sur cette période (${esc(periodeLbl)})${stFilter!=='tous'?` au statut « ${esc(stFilter)} »`:''}.</p>`;
    res.dataset.done='1'; return;
  }
  const maxQ = lignes[0][1];
  const rows = lignes.map(([nom,q])=>{
    const pct = totalMac>0 ? Math.round(q/totalMac*100) : 0;
    const barW = maxQ>0 ? Math.round(q/maxQ*100) : 0;
    return `<div style="margin:6px 0">
      <div style="display:flex;justify-content:space-between;font-size:.86rem">
        <span style="color:#5a4a42">${esc(nom)}</span>
        <b style="color:var(--bordeaux)">${qty(q)} <span style="color:#9a8a82;font-weight:400">· ${pct}%</span></b></div>
      <div style="height:7px;background:#f0e9de;border-radius:4px;overflow:hidden;margin-top:2px">
        <div style="height:100%;width:${barW}%;background:#AA7C39;border-radius:4px"></div></div>
    </div>`;
  }).join('');
  res.innerHTML = `
    <div style="display:flex;justify-content:space-between;border-bottom:1px solid #e8dccd;padding-bottom:6px;margin:8px 0">
      <span style="font-size:.82rem;color:#7a6a60">${esc(periodeLbl)}${stFilter!=='tous'?` · ${esc(stFilter)}`:''}</span>
      <span style="font-size:.82rem;color:#7a6a60">${nbCmd} commande(s)</span>
    </div>
    ${rows}
    <div style="display:flex;justify-content:space-between;border-top:2px solid #e8dccd;margin-top:8px;padding-top:6px">
      <b>Total macarons</b><b style="color:var(--bordeaux);font-size:1.05rem">${qty(totalMac)}</b></div>`;
  res.dataset.done='1';
}

async function renderCmd(){
  _cmdSel = new Set();   // sélection réinitialisée à chaque ouverture de l'écran
  cmdTags = new Set();   // filtres par tags réinitialisés à chaque ouverture
  // [COCKPIT — étape 3] Filtre jour : réinitialisé par défaut, mais positionné si le Copilote nous a
  // envoyés ici avec un focus date (« commandes de demain » → 📋 Commandes du JJ/MM).
  cmdJourFiltre = null;
  try{
    const f = window._viewFocus;
    if(f && f.view==='commandes' && f.type==='jour' && f.val){
      cmdJourFiltre = String(f.val);
      window._viewFocus = null;
    }
  }catch(e){swallow(e,'renderCmd')}
  // Les commandes "historiques" (reprise/migration) ne s'affichent pas ici :
  // elles comptent dans le CA mais ne sont pas opérationnelles.
  // [v1425] LES MÈRES RANGÉES RESTENT DANS LE CACHE. La v1421 les excluait ICI, à la source — donc
  // aussi de la RECHERCHE, des tags et du filtre jour, qui se nourrissent tous de `_cmdCache`.
  // Résultat : une mère devenait introuvable autrement qu'en passant par une de ses filles. Ranger
  // n'est pas effacer. Le tri se fait maintenant à l'AFFICHAGE (cmdFilter) : hors du fil
  // opérationnel, mais dans un repli « Commandes mères rangées » et atteignable par recherche.
  const orders = (await db.orders.toArray()).filter(o=>!o.histo).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  const clients = await db.clients.toArray();
  // [v1431] Les MARCHÉS OUVERTS sont des engagements de production au même titre qu'une commande :
  // Ben doit les voir dans ce fil, avec la quantité qu'il vise. Ils ne rejoignent PAS `_cmdCache`
  // (ce ne sont pas des commandes : pas de client, pas de montant dû, pas de statut de paiement —
  // les y verser fausserait la recherche, les tags, les totaux à encaisser). Cache séparé, bloc
  // séparé, même écran.
  try{
    _cmdMarketsCache = (await db.markets.toArray().catch(()=>[]))
      .filter(m => m && m.statut !== 'clos')
      .sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));
  }catch(e){ _cmdMarketsCache = []; swallow(e,'renderCmd marchés'); }
  const clById = Object.fromEntries(clients.map(c=>[c.id,c]));
  _cmdClNameMap = Object.fromEntries(clients.map(c=>[c.id, c.nom||'—']));
  const clName = id => (clById[id]||{}).nom||'—';
  // charge TOUS les liens batch en une seule requête (au lieu d'une par commande)
  const allItems = await db.orderItems.toArray();
  const itemsByOrder={}; allItems.forEach(it=>{ (itemsByOrder[it.orderId] ||= []).push(it); });
  // n° de lot des batchs liés, par commande (pour permettre la recherche par lot)
  const allProdsForLots = await db.productions.toArray();
  const prodLotById = {}; allProdsForLots.forEach(p=>{ prodLotById[p.id]=p.lotProduction||''; });
  // [PRODUISIBILITÉ — crédit des liaisons] recettes + index productions pour imputer les lots liés
  // à un parfum de la demande (matching flou), afin de raisonner sur la demande NETTE.
  const _recipesCmd = await db.recipes.toArray();
  const _recByIdCmd = {}; _recipesCmd.forEach(r=>{ _recByIdCmd[r.id]=r; });
  const _prodByIdCmd = {}; allProdsForLots.forEach(p=>{ _prodByIdCmd[p.id]=p; });
  const lotsByOrder={}; allItems.forEach(it=>{ const lot=prodLotById[it.productionId]; if(lot){ (lotsByOrder[it.orderId] ||= []).push(lot); } });
  const lineLabel = ln => {
    if(ln.type==='evenement') return `Événement ${ln.evQte||0} mac. +${ln.equip||0} pyr.`;
    if(ln.type==='grand'){ const n=(ln.items||[]).reduce((s,b)=>s+(+b.qte||0),0); return `Grand format ×${n}`; }
    if(ln.type==='vrac'){ const n=(ln.parfums||[]).reduce((s,b)=>s+(+b.qte||0),0); return `Vrac ${ln.proMode==='nonpro'?'':'pro '}×${n}`; }
    if(ln.type==='sachet'){ const n=(ln.parfums||[]).reduce((s,b)=>s+(+b.qte||0),0)+(+ln.sansParfum||0); return `Sachet ×${n}`; }
    if(ln.type==='don'){ const n=(ln.parfums||[]).reduce((s,b)=>s+(+b.qte||0),0)+(ln.items||[]).reduce((s,b)=>s+(+b.qte||0),0); return `Don ×${n} (offert)`; }
    if(ln.type==='prestation'){
      if(ln.presta==='accompagnement'){ const m=ln.mode==='enligne'?'en ligne':(ln.mode==='presentiel'?'présentiel':''); return `Accompagnement${ln.dureeH?' '+ln.dureeH+'h':''}${m?' ('+m+')':''}`; }
      return `Prestation${ln.libelle?' : '+ln.libelle:''}`;
    }
    return `Coffret ${ln.taille||'?'}`;
  };
  // index de recherche par commande, calculé une seule fois
  // [🥉 PRODUISIBILITÉ] Stock mobilisable par parfum, chargé UNE fois pour toutes les commandes.
  let _mobMapCmd = {}; try{ _mobMapCmd = await stockMobilisableParParfum(); }catch(_){ _mobMapCmd = {}; }
  _cmdCache = orders.map(o=>{
    const lignes = orderToLines(o);
    const resume = lignes.length ? lignes.map(lineLabel).join(' + ') : '—';
    // produits/parfums pour la recherche
    const prodTxt = lignes.flatMap(ln=>[
      ...(ln.parfums||[]).map(p=>p.nom),
      ...(ln.items||[]).map(p=>p.nom),
      ln.type
    ]).join(' ');
    const cl=clById[o.clientId]||{};
    const refCmd = orderNumber(o);   // n° de référence affiché (ex. 2026-030)
    const prim = normTxt([clName(o.clientId), 'cmd'+o.id, refCmd].filter(Boolean).join(' '));
    const _facets = orderFacets(o, lignes, clById[o.clientId]||{});
    const facetTxt = _facets.map(f=>f.label).join(' ');   // labels filtrables via la recherche
    const blob = normTxt([clName(o.clientId), cl.prenom, cl.societe, cl.tel, cl.email, cl.ref,
      resume, prodTxt, o.notes, o.reglement, o.paiement, 'cmd'+o.id, '#'+o.id, refCmd, fmtDate(o.date),
      facetTxt, (lotsByOrder[o.id]||[]).join(' ')].filter(Boolean).join(' '));
    const digits = onlyDigits([o.id, refCmd, cl.tel, o.montant].filter(v=>v!=null&&v!=='').join(' '));
    const _linksCmd = (itemsByOrder[o.id]||[]).map(it=>{ const p=_prodByIdCmd[it.productionId]; const r=p?_recByIdCmd[p.recipeId]:null; return { nom: r?r.produitNom:((p&&p.produitNom)||''), qte:+it.qte||0 }; }).filter(l=>l.nom);
    const produisibilite = (typeof _orderProduisibilite==='function') ? _orderProduisibilite(o, _mobMapCmd, _linksCmd) : null;
    return {o, resume, nbLies:(itemsByOrder[o.id]||[]).length, _prim:prim, _blob:blob, _digits:digits, _facets, produisibilite};
  });
  document.getElementById('main').innerHTML=`
   <div class="topbar"><div><h1>Commandes</h1><p id="cmdCount">${orders.length} commande(s)</p></div>
     <div class="flex" style="gap:8px"><button class="btn ghost sm" onclick="factEmetteurForm()" title="Coordonnées de facturation">🧾 Facturation</button><button class="btn ghost sm" onclick="togglePrivacyMode()" title="Masquer/afficher les données sensibles">${privacyModeEnabled()?'👁️ Afficher':'🙈 Mode discret'}</button>
     <button class="btn ghost sm" onclick="cmdVoirMeresEnAttente()" title="Commandes payées en avance, rangées, qui attendent d'être servies">🔗 Paiements en avance</button>
     <button class="btn" onclick="cmdForm()">+ Nouvelle commande</button></div></div>
   <div class="panel" style="background:#fffdf8;border:1px solid #e8dcc0">
     <button class="btn ghost sm" style="width:100%;text-align:left" onclick="cmdPeriodToggle()">📊 Total macarons par parfum sur une période ▾</button>
     <div id="cmdPeriodBox" style="display:none;margin-top:10px">
       <div class="row2">
         <div class="field"><label>Du</label><input type="date" id="cmdPeriodFrom" onchange="cmdPeriodCompute()"></div>
         <div class="field"><label>Au</label><input type="date" id="cmdPeriodTo" onchange="cmdPeriodCompute()"></div>
       </div>
       <div class="field"><label>Statut des commandes</label>
         <select id="cmdPeriodStatut" onchange="cmdPeriodCompute()">
           <option value="tous">Toutes</option>
           <option value="À préparer">À préparer (pas encore prêtes)</option>
           <option value="Terminée">Terminées (prêtes, pas livrées)</option>
           <option value="Livrée">Livrées</option>
         </select></div>
       <p class="note">Filtre sur la date d'événement/livraison. Compte les macarons commandés par parfum.</p>
       <div id="cmdPeriodResult"></div>
     </div>
   </div>
   <div class="panel">
     <input class="search" id="cmdSearch" style="width:100%;margin-bottom:12px" placeholder="N° commande, client, produit, parfum, mois, statut (prête/livrée), payé, remise…" value="${esc(cmdSearch)}" oninput="cmdFilter(this.value)" autocomplete="off" autocapitalize="off" autocorrect="off">
     <div id="cmdTagBar" class="cmd-tagbar"></div>
     <div id="cmdSelBar" class="sel-bar" style="display:none">
       <span id="cmdSelCount">0 sélectionnée(s)</span>
       <div class="flex" style="gap:6px">
         <button class="btn ghost sm" onclick="cmdSelectAllVisible()">Tout cocher</button>
         <button class="btn ghost sm" onclick="cmdClearSelection()">Tout décocher</button>
         <button class="btn gold sm" onclick="genererFactureMultiple([..._cmdSel])">🧾 Facturer la sélection</button>
         <button class="btn gold sm" onclick="pickBatchCreateFromSelection()">📦 Créer un lot de picking</button>
         <button class="btn ghost sm" onclick="cmdMailSelection()">✉️ Mail au client</button>
         <button class="btn ghost sm" onclick="cmdExportSelection()">⬇ Exporter (TXT)</button>
       </div>
     </div>
     <div id="cmdBody" class="cmd-cards"></div>
     <div id="cmdEmpty" class="empty" style="display:none">Aucune commande.</div>
   </div>`;
  _cmdRenderTagBar();
  cmdFilter(cmdSearch);
  cmdUpdateSelBar();
}
// Dessine la barre de filtres par tags : pastilles groupées par catégorie, dans l'ordre
// Format → Parfum → Année → Type → Paiement. Une pastille active est mise en évidence.
// Les pastilles ne listent que les facettes RÉELLEMENT présentes dans les commandes.
const _FACET_CATS = [
  {cat:'format',   titre:'Format'},
  {cat:'parfum',   titre:'Parfum'},
  {cat:'annee',    titre:'Année'},
  {cat:'type',     titre:'Type'},
  {cat:'paiement', titre:'Paiement'}
];
function _cmdRenderTagBar(){
  const bar=document.getElementById('cmdTagBar'); if(!bar) return;
  // Étiquettes masquées à la demande : le filtrage se fait via la recherche texte
  // (les libellés de facettes sont inclus dans le champ recherchable). Les fonctions de tag
  // restent disponibles si on souhaite les réafficher un jour.
  bar.innerHTML='';
  return;
  // Code d'affichage conservé (inactif) au cas où on réactiverait les étiquettes visuelles :
  // Inventaire des facettes présentes : key -> {cat, label} ; et comptage par key.
  const facetMap=new Map();
  _cmdCache.forEach(e=>(e._facets||[]).forEach(f=>{ if(!facetMap.has(f.key)) facetMap.set(f.key, {cat:f.cat, val:f.val, label:f.label}); }));
  if(!facetMap.size){ bar.innerHTML=''; return; }
  let html='';
  _FACET_CATS.forEach(({cat,titre})=>{
    let facets=[...facetMap.entries()].filter(([k,f])=>f.cat===cat);
    if(!facets.length) return;
    // Tri : formats par taille croissante ; années décroissantes ; le reste alpha.
    facets.sort((a,b)=>{
      if(cat==='format') return (parseInt(a[1].val,10)||0)-(parseInt(b[1].val,10)||0);
      if(cat==='annee')  return b[1].val.localeCompare(a[1].val);
      return a[1].label.localeCompare(b[1].label);
    });
    const pills=facets.map(([key,f])=>{
      const on=cmdTags.has(key);
      return `<button type="button" class="cmd-tag${on?' on':''}" onclick="cmdToggleTag('${escJs(key)}')">${esc(f.label)}</button>`;
    }).join('');
    html += `<div class="cmd-tag-grp"><span class="cmd-tag-cat">${titre}</span>${pills}</div>`;
  });
  if(cmdTags.size){
    html += `<button type="button" class="cmd-tag-clear" onclick="cmdClearTags()">✕ Réinitialiser (${cmdTags.size})</button>`;
  }
  bar.innerHTML = html;
}
// [🥉 PRODUISIBILITÉ COMMANDE] Calcule, pour une commande, si elle est couvrable par le stock ACTUEL.
// Croise sa demande par parfum (_orderParfumDemand, noms bruts) avec le stock mobilisable
// (stockMobilisableParParfum, clés aiNormalize) → on normalise pour faire le pont.
// Statut le PLUS CONTRAIGNANT de ses parfums :
//   • 'stock'    : tous les parfums couverts par des macarons FINIS en stock.
//   • 'montable' : au moins un parfum nécessite un assemblage (coques+ganache dispo), tout est couvrable.
//   • 'produire' : au moins un parfum manque même en comptant le mobilisable → il faut produire.
// IMPORTANT : indication sur le stock TOTAL (pas de réservation entre commandes) — comme le plan.
// Renvoie { statut, manqueTotal } ou null si commande livrée / sans demande.
function _orderProduisibilite(o, mobMap, linkList){
  if(!o || (typeof normStatus==='function' && normStatus(o.statut)==='Livrée')) return null;
  const dem = (typeof _orderParfumDemand==='function') ? _orderParfumDemand(o) : {};
  const noms = Object.keys(dem);
  if(!noms.length) return null;
  // [A — crédit des liaisons] Chaque lot DÉJÀ LIÉ est imputé à un parfum de la demande (matching
  // flou, comme l'affectation), et on raisonne sur la demande NETTE. Pas de double comptage : lier
  // a déjà décrémenté le stock, donc « demande nette vs stock actuel » est cohérent.
  const linkedByFlavor = {};
  (linkList||[]).forEach(l=>{
    if(!l || (+l.qte||0)<=0) return;
    const key = (typeof pickFlavorMatch==='function') ? noms.find(n=>pickFlavorMatch(n, l.nom)) : null;
    if(key) linkedByFlavor[key] = (linkedByFlavor[key]||0) + (+l.qte||0);
  });
  const net = {}; let netTotal = 0;
  noms.forEach(n=>{ const v = Math.max(0, (+dem[n]||0) - (linkedByFlavor[n]||0)); net[n]=v; netTotal += v; });
  // [B — commande couverte] Toute la demande est couverte par des lots liés → plus rien à faire.
  if(netTotal <= 0) return { statut:'lie', manqueTotal:0 };
  const _k = nom => (typeof aiNormalize==='function') ? aiNormalize(nom||'') : String(nom||'').toLowerCase().trim();
  let besoinAssemblage = false, manqueTotal = 0;
  noms.forEach(nom=>{
    const besoin = net[nom]||0; if(besoin<=0) return;                 // demande NETTE (liaisons déduites)
    const b = mobMap[_k(nom)] || null;
    const finis = b ? (+b.finis||0) : 0;
    const assemblable = b ? (+b.assemblable||0) : 0;
    if(finis >= besoin) return;                      // couvert par les finis
    const apresFinis = besoin - finis;
    if(assemblable >= apresFinis){ besoinAssemblage = true; return; }   // couvert en montant
    manqueTotal += (apresFinis - assemblable);       // reste à produire
  });
  if(manqueTotal > 0) return { statut:'produire', manqueTotal };
  if(besoinAssemblage) return { statut:'montable', manqueTotal:0 };
  return { statut:'stock', manqueTotal:0 };
}

function _cmdRow(row, grp){
  const o=row.o;
  const checked = _cmdSel.has(o.id) ? 'checked' : '';
  const st = orderPayStatus(o); const solde = orderBalance(o);
  grp = grp||{};
  // Repère mois (bandeau de séparation) au-dessus de la carte.
  let periodeBandeau = '';
  if(grp.newMonth && o.date){
    const mk=o.date.slice(0,7); const [yy,mm]=mk.split('-'); const idx=(+mm||1)-1;
    const col=_SEP_COLORS[idx % _SEP_COLORS.length];
    periodeBandeau += `<div class="cmd-period-month" style="background:${col}">${_MOIS_FR[idx]||''} ${yy||''}</div>`;
  }
  // Statut commande : À préparer (orange) / Prête (bleu) / Livrée (vert).
  const curStatut = normStatus(o.statut);
  const statutClass = curStatut==='Livrée'?'st-livree':(curStatut==='Terminée'?'st-prete':'st-prepa');
  const statutSelect = `<select class="cmd-statut-select ${statutClass}" onchange="setOrderStatusInline(${o.id}, this.value)" title="Changer le statut">
    ${ORDER_STATUS.map(s=>`<option value="${s}" ${s===curStatut?'selected':''}>${s==='Terminée'?'Prête':esc(s)}</option>`).join('')}
  </select>`;
  // Paiement : En attente (rouge) / Payé (vert).
  const payBtn = st==='Payé'
    ? `<button class="cmd-pill pay-ok" onclick="cmdView(${o.id})" title="Payé">✓ Payé</button>`
    : `<button class="cmd-pill pay-due" onclick="markPaid(${o.id})" title="Encaisser le solde">● En attente${solde>0?' ('+euro(solde)+')':''}</button>`;

  const clientNom = o.clientId ? nameP(_cmdClName(o.clientId)) : '—';
  const adresse = o.lieuLivraison ? nameP(o.lieuLivraison) : '';

  // [🥉 PRODUISIBILITÉ] Badge indiquant si la commande est couvrable par le stock actuel.
  // Indication sur le stock total (pas de réservation entre commandes).
  const prod = row.produisibilite;
  const prodBadge = prod
    ? (prod.statut==='lie'
        ? '<span class="tag ok" title="Commande entièrement liée à des lots — couverture assurée, rien à produire">✓ couverte</span>'
      : prod.statut==='stock'
        ? '<span class="tag ok" title="Tous les parfums sont disponibles en macarons finis (stock total, sans réservation entre commandes)">📦 en stock</span>'
      : prod.statut==='montable'
        ? '<span class="tag" style="background:#3b6ea5;color:#fff" title="Couvrable en assemblant les coques + ganache déjà en stock">🔧 à monter</span>'
        : `<span class="tag warn" title="Il manque ${prod.manqueTotal} macaron(s) à produire">🍳 à produire${prod.manqueTotal?' '+prod.manqueTotal:''}</span>`)
    : '';

  return `${periodeBandeau}<div class="cmd-card">
    <div class="cmd-card-head">
      <div class="cmd-client">
        <b>${clientNom}</b>${o.clientId?` <span class="jump-arrow" onclick="clientPopup(${o.clientId})" title="Fiche client">→</span>`:''}
        <div class="cmd-meta">${fmtDate(o.date)}${o.heureLivraison?' · '+esc(o.heureLivraison):''}</div>
        ${adresse?`<div class="cmd-meta">📍 ${adresse}</div>`:''}
      </div>
      <input type="checkbox" class="cmd-check" ${checked} onclick="cmdToggleOne(${o.id},this.checked)" title="Sélectionner">
    </div>
    <div class="cmd-contenu">${esc(row.resume)}${o.perso?' <span class="tag event">perso</span>':''}${prodBadge?' '+prodBadge:''}</div>
    <div class="cmd-primary">
      <button class="cmd-pill detail" onclick="cmdView(${o.id})" title="Voir le détail">👁 Détails</button>
      <span class="cmd-montant">${euro(+o.montant)}</span>
      ${statutSelect}
    </div>
    <div class="cmd-secondary">
      <button class="qa edit" onclick="cmdForm(${o.id})" title="Modifier">✎ Modifier</button>
      ${payBtn}
      <button class="qa" onclick="cmdLink(${o.id})" title="Lier à une production">🔗 Lier</button>
      <button class="qa" onclick="traceOrder(${o.id})" title="Traçabilité de la commande">🔎 Tracer</button>
      <button class="qa gold" onclick="genererFacture(${o.id})" title="Générer la facture">🧾 Facturer</button>
      <button class="qa del-full" onclick="cmdDelete(${o.id})" title="Supprimer la commande">🗑 Supprimer</button>
    </div>
  </div>`;
}
// Changement de statut depuis le menu déroulant de la liste (sans fermer de modale).
async function setOrderStatusInline(id, statut){
  if(statut==='Livrée'){
    const ok = await ensureOrderDecremented(id);
    if(!ok){ renderCmd(); return; }   // bloqué : statut inchangé (le select est réinitialisé au rendu)
  }
  await db.orders.update(id, {statut});
  renderCmd();
  toast('Statut : '+(statut==='Terminée'?'Prête':statut));
}
// ---- Solder une commande depuis la liste (encaisse le solde, daté du jour) ----
// ---- Sélection multiple ----
let _cmdSel = new Set();
// [v1284] Sélection multiple sur l'écran Documents, scopée aux DEVIS (pas les factures — un
// devis groupé n'a de sens qu'à partir de devis, pas de factures déjà émises/verrouillées).
let _docSel = new Set();
function docToggleOne(id, on){ if(on) _docSel.add(id); else _docSel.delete(id); docUpdateSelBar(); }
function docClearSelection(){ _docSel.clear(); if(view==='documents') renderDocuments(); }
function docUpdateSelBar(){
  const bar=document.getElementById('docSelBar'); if(!bar) return;
  const n=_docSel.size;
  bar.style.display = n>0 ? 'flex' : 'none';
  const c=document.getElementById('docSelCount'); if(c) c.textContent = n+' sélectionné(s)';
}
function cmdToggleOne(id, on){ if(on) _cmdSel.add(id); else _cmdSel.delete(id); cmdUpdateSelBar(); }
function cmdSelectAllVisible(){ cmdToggleAllVisible(true); }
function cmdToggleAllVisible(on){
  // agit sur les commandes actuellement filtrées/affichées
  const rows = searchRank(_cmdCache||[], cmdSearch);
  rows.forEach(r=>{ if(on) _cmdSel.add(r.o.id); else _cmdSel.delete(r.o.id); });
  cmdFilter(cmdSearch); cmdUpdateSelBar();
}
function cmdClearSelection(){ _cmdSel.clear(); const h=document.getElementById('cmdSelHead'); if(h)h.checked=false; cmdFilter(cmdSearch); cmdUpdateSelBar(); }
function cmdUpdateSelBar(){
  const bar=document.getElementById('cmdSelBar'), cnt=document.getElementById('cmdSelCount');
  if(!bar) return;
  const body=document.getElementById('cmdBody');
  if(_cmdSel.size>0){
    bar.style.display='flex'; if(cnt) cnt.textContent=`${_cmdSel.size} sélectionnée(s)`;
    // Le bandeau est en position:fixed au-dessus de la liste ; on réserve dessous un espace égal
    // à sa hauteur réelle (+ marge) pour que la dernière ligne reste toujours atteignable/cochable.
    if(body){
      requestAnimationFrame(()=>{
        const h = bar.offsetHeight || 120;
        body.style.paddingBottom = (h + 28) + 'px';
      });
    }
  } else {
    bar.style.display='none';
    if(body) body.style.paddingBottom='';
  }
}
let _cmdClNameMap={};
let _cmdMarketsCache=[];   // [v1431] marchés non clos, affichés dans le fil des commandes
function _cmdClName(id){ return _cmdClNameMap[id]||'—'; }
// Ligne SIMPLIFIÉE pour les sections repliées (terminées / à encaisser) :
// client + montant + œil pour le détail. `distinctif` ajoute un marqueur visuel (à encaisser).
function _cmdRowMini(row, opts){
  opts=opts||{};
  const o=row.o;
  const checked = _cmdSel.has(o.id) ? 'checked' : '';
  const clientNom = (privacyModeEnabled()?'•••':( _cmdClNameMap[o.clientId] || o.histoLabel || '—'));
  const reste = (typeof orderBalance==='function') ? orderBalance(o) : 0;
  const montant = (+o.montant)||0;
  const marqueur = opts.distinctif
    ? `<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#d98324;flex:none" title="Reste à encaisser"></span>`
    : '';
  // "reste" affiché UNIQUEMENT en cas de paiement partiel (reste différent du montant total).
  // Si rien n'a été payé (reste = montant) c'est redondant → on ne l'affiche pas.
  const estPartiel = opts.distinctif && reste>0 && Math.abs(reste-montant)>0.01;
  const resteTxt = estPartiel
    ? `<span style="color:#d98324;font-weight:600;font-size:.8rem;white-space:nowrap">reste ${euro(reste)}</span>`
    : '';
  // Couleur du montant dans "À encaisser" : rouge si totalement dû (rien payé), orange si partiel.
  let montantColor='';
  if(opts.distinctif && reste>0){
    montantColor = estPartiel ? 'color:#d98324' : 'color:#b3261e';   // orange partiel · rouge totalement dû
  }
  return `<div style="display:flex;align-items:center;gap:10px;padding:9px 12px;border-bottom:1px solid var(--hair)">
    <input type="checkbox" ${checked} onchange="cmdToggleOne(${o.id}, this.checked)" style="flex:none" onclick="event.stopPropagation()">
    ${marqueur}
    <span style="flex:1;min-width:0;display:flex;flex-direction:column">
      <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.9rem">${esc(clientNom)}</span>
      <span style="color:#8a7a72;font-size:.74rem;white-space:nowrap">${fmtDate(o.date)}</span>
    </span>
    ${resteTxt}
    <b style="font-size:.9rem;white-space:nowrap;${montantColor}">${privacyModeEnabled()?'•••':euro(o.montant)}</b>
    <button class="cmd-pill detail" style="flex:none" onclick="cmdView(${o.id})" title="Voir le détail">👁</button>
    <button class="cmd-pill detail" style="flex:none" onclick="traceOrder(${o.id})" title="Traçabilité">🔎</button>
  </div>`;
}
// [COCKPIT] Positionne (ou enlève si null) le filtre jour des commandes, puis rafraîchit la liste.
function cmdSetJourFiltre(dateIso){
  cmdJourFiltre = dateIso || null;
  if(typeof cmdFilter==='function') cmdFilter(cmdSearch);
}
// ============================================================================
//  [v1340] LE MONTANT TOTAL *ET* LE RESTE DÛ — demandé par Benjamin.
// ----------------------------------------------------------------------------
//  L'encart « À venir » n'affichait que le montant total (« 5 · 1 022,40 € »). Or une partie est
//  souvent déjà encaissée en acompte : ce total ne dit donc PAS ce qu'il reste à percevoir, qui
//  est pourtant le chiffre qui compte pour la trésorerie.
//
//  DEUX RÈGLES, et la seconde est celle qui évite un mensonge discret :
//
//   1. LES TROIS CHIFFRES SE RECOMPOSENT : total = déjà encaissé + reste dû, AU CENTIME.
//      Un encart où les nombres ne se recomposent pas oblige Benjamin à vérifier à la calculette
//      — et un chiffre qu'on doit vérifier est un chiffre auquel on ne fait plus confiance.
//
//   2. UN TROP-PERÇU NE PAIE PAS LA COMMANDE D'À CÔTÉ. Si un client a versé 120 € pour une
//      commande de 100 €, les 20 € en trop ne viennent PAS réduire le reste dû d'un autre client.
//      Sommer bêtement (Σ montant − Σ encaissé) ferait exactement ça, et sous-estimerait le reste
//      à percevoir. On plafonne donc commande par commande, et on expose le trop-perçu À PART.
// ============================================================================
function cmdTotauxLot(rows){
  const res = { total:0, encaisse:0, reste:0, tropPercu:0, nbAvecAcompte:0, nb:0 };
  (rows || []).forEach(r => {
    const o = (r && r.o) ? r.o : r;
    if(!o) return;
    const montant = Math.max(0, +o.montant || 0);
    const paye = (typeof orderPaid === 'function') ? Math.max(0, orderPaid(o)) : 0;

    // Ce qui s'applique RÉELLEMENT à cette commande (jamais plus que son montant).
    const applique = Math.min(paye, montant);
    const du = money2(montant - applique);          // ≥ 0 par construction
    const trop = money2(Math.max(0, paye - montant));

    res.nb++;
    res.total    = money2(res.total + montant);
    res.encaisse = money2(res.encaisse + applique);
    res.reste    = money2(res.reste + du);
    res.tropPercu = money2(res.tropPercu + trop);
    if(applique > 0) res.nbAvecAcompte++;
  });
  return res;
}

function cmdFilter(q){  cmdSearch=q||'';
  if(!_cmdCache) return;
  const body=document.getElementById('cmdBody'); if(!body) return;
  // 0) [COCKPIT] filtre JOUR (sur o.date) s'il est actif, AVANT tags et recherche.
  const sourceCache = cmdJourFiltre
    ? _cmdCache.filter(e=> (e.o && e.o.date) === cmdJourFiltre)
    : _cmdCache;
  // 1) filtre par tags actifs (ET logique), 2) puis recherche texte sur le sous-ensemble.
  const base = cmdTags.size ? sourceCache.filter(cmdMatchTags) : sourceCache;
  const rows=searchRank(base, q);
  const cnt=document.getElementById('cmdCount');
  if(cnt){
    const total=_cmdCache.length;
    const filtre=(q&&q.trim()) || cmdTags.size;
    if(!filtre){ cnt.textContent = `${total} commande(s)`; }
    else if(cmdTags.size && (q&&q.trim())){ cnt.textContent = `${rows.length} / ${base.length} filtrée(s) · ${cmdTags.size} tag(s)`; }
    else if(cmdTags.size){ cnt.textContent = `${rows.length} / ${total} · ${cmdTags.size} tag(s)`; }
    else { cnt.textContent = `${rows.length} / ${total} commande(s)`; }
  }
  const empty=document.getElementById('cmdEmpty');
  if(!rows.length){ body.innerHTML=''; if(empty) empty.style.display='block'; return; }
  if(empty) empty.style.display='none';
  // Pendant une recherche, le tri est par pertinence → pas de séparateurs temporels.
  const grouper = !((q && q.trim()) || cmdTags.size);
  const LIMIT=300;
  const shown = rows.slice(0,LIMIT);
  // Répartition en 3 groupes :
  //  - enCours : pas encore livrée (opérationnel) → cartes complètes
  //  - aEncaisser : livrée AVEC un solde réellement dû (montant>0 et non soldé) → section distincte
  //  - terminees : livrée et soldée, OU sans montant dû (0 €) → repli simple ("archivées")
  const enCours=[], aEncaisser=[], terminees=[], meresRangees=[];
  shown.forEach(r=>{
    const o=r.o;
    // [v1425] Une MÈRE RANGÉE ne rejoint aucun des trois groupes opérationnels : elle n'est ni à
    // préparer (ses filles le sont), ni à encaisser (son argent est rentré), ni « terminée » (il
    // reste peut-être des macarons à retirer). La ranger dans « Terminées » aurait été le mensonge
    // le plus commode. Elle a son propre repli, toujours présent, toujours atteignable.
    if(estMereRangee(o)){ meresRangees.push(r); return; }
    const livree = normStatus(o.statut)==='Livrée';
    const reste = (typeof orderBalance==='function') ? orderBalance(o) : ((+o.montant)||0);
    const aDuRestant = (+o.montant)>0 && reste>0.01;   // un vrai montant reste à encaisser
    if(!livree) enCours.push(r);
    else if(aDuRestant) aEncaisser.push(r);
    else terminees.push(r);   // soldée OU montant à 0 € → terminées (archivées)
  });
  let html='';
  // 1) EN COURS — on distingue la SEMAINE COURANTE (+ retards) des SEMAINES À VENIR.
  //    • Semaine courante ou passée non livrée → carte complète, dépliée (opérationnel du moment).
  //    • Semaines futures → encart « À venir » (déplié par défaut, une ligne par commande),
  //      d'où chaque commande BASCULE automatiquement en carte dès que sa semaine arrive.
  //    Le regroupement semaine/futur n'a de sens que hors recherche/tags (tri par pertinence sinon).
  const _wkNow = (typeof _isoWeekKey==='function') ? _isoWeekKey(today()) : null;
  const courant=[], aVenir=[];
  enCours.forEach(r=>{
    const d=r.o.date||'';
    const wk = (grouper && d && _wkNow) ? _isoWeekKey(d) : null;
    // « À venir » = date renseignée ET semaine strictement postérieure à la semaine courante.
    if(wk && wk>_wkNow) aVenir.push(r); else courant.push(r);
  });

  // 1a) SEMAINE COURANTE (+ retards) — cartes complètes, séparateurs de mois conservés.
  let lastMonth=null;
  courant.forEach(r=>{
    let newMonth=false;
    if(grouper){
      const mk=(r.o.date||'').slice(0,7);
      if(mk && mk!==lastMonth){ lastMonth=mk; newMonth=true; }
    }
    html += _cmdRow(r, {newMonth, newWeek:false});
  });
  if(!courant.length && !aVenir.length){ html += `<div class="empty" style="padding:14px">Aucune commande en cours.</div>`; }
  else if(!courant.length){ html += `<div class="empty" style="padding:14px">Aucune commande cette semaine — voir « À venir » ci-dessous.</div>`; }

  // 1b) À VENIR — encart déplié par défaut, une ligne par commande (comme « À encaisser »),
  //     regroupé par semaine (de la plus proche à la plus lointaine), dates croissantes dedans.
  // [v1431] BLOC « MARCHÉS À VENIR » — un marché ouvert est un engagement de production, il a sa
  // place dans le fil. On montre la quantité VISÉE et, si Ben l'a renseignée, sa ventilation par
  // parfum ; sinon on le dit et on offre le bouton qui la calcule. Un marché sans quantité visée
  // n'alimente PAS le rétroplanning : le signaler ici est plus utile que de le laisser muet.
  if(_cmdMarketsCache.length){
    const _mkLignes = _cmdMarketsCache.map(m=>{
      const j = daysTo(m.date);
      const q = +m.prevuQte||0;
      const par = Array.isArray(m.prevuParfums) ? m.prevuParfums.filter(x=>x && +x.qte>0) : [];
      const somme = par.reduce((s,x)=>s+(+x.qte||0),0);
      const jTxt = (j===null) ? '' : (j<0 ? `il y a ${-j} j` : j===0 ? "aujourd'hui" : `dans ${j} j`);
      const etat = q<=0
        ? `<span style="color:#b3261e;font-weight:600;font-size:.78rem">aucune quantité visée</span>`
        : par.length
          ? `<span style="color:#3f7d52;font-weight:600;font-size:.78rem">${par.length} parfum${par.length>1?'s':''} · ${qty(somme)} pc</span>`
          : `<span style="color:#b5701a;font-weight:600;font-size:.78rem">parfums à définir</span>`;
      return `<div style="display:flex;align-items:center;gap:10px;padding:9px 12px;border-bottom:1px solid var(--hair)">
        <span style="flex:1;min-width:0;display:flex;flex-direction:column">
          <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.9rem">${esc(m.nom||'Marché')}</span>
          <span style="color:#8a7a72;font-size:.74rem;white-space:nowrap">${fmtDate(m.date)}${jTxt?' · '+jTxt:''}${m.lieu?' · '+esc(m.lieu):''}</span>
        </span>
        ${etat}
        <b style="font-size:.9rem;white-space:nowrap">${q>0?qty(q)+' pc':'—'}</b>
        <button class="cmd-pill detail" style="flex:none" onclick="marketForm(${m.id})" title="Ouvrir le marché">✏️</button>
      </div>`;
    }).join('');
    const _mkTotal = _cmdMarketsCache.reduce((s,m)=>s+(+m.prevuQte||0),0);
    html += `<details open style="margin:8px 0 4px;border:1px solid #cfd9c9;border-radius:12px;overflow:hidden;background:#f8faf6">
      <summary style="cursor:pointer;padding:11px 13px;font-weight:600;color:#3f6b45;background:#eef4ea">
        ⛺ Marchés à venir <span style="font-weight:400;color:#6a7a68">(${_cmdMarketsCache.length})${_mkTotal>0?` · ${qty(_mkTotal)} macarons visés`:''}</span></summary>
      <div>${_mkLignes}</div>
      <div style="padding:9px 12px;font-size:.76rem;color:#6a7a68">La quantité visée alimente le rétroplanning (<b>Plan de production</b>). Sans elle, le marché n'y apparaît pas.</div>
    </details>`;
  }
  if(aVenir.length){
    // Regroupe par clé de semaine ISO.
    const parSem={};
    aVenir.forEach(r=>{ const wk=_isoWeekKey(r.o.date)||'?'; (parSem[wk] ||= []).push(r); });
    const semaines=Object.keys(parSem).sort();   // ISO 'AAAA-Www' se trie chronologiquement en string
    const _libSemaine=(wk)=>{
      // Reconstitue le lundi de la semaine à partir d'une date membre, pour l'afficher.
      const ref=parSem[wk][0].o.date;
      const d=new Date(ref); if(isNaN(d)) return 'Semaine '+((wk.split('-W')[1])||'');
      const day=(d.getDay()+6)%7; const lundi=new Date(d); lundi.setDate(d.getDate()-day);
      const dim=new Date(lundi); dim.setDate(lundi.getDate()+6);
      const f=x=>x.toLocaleDateString('fr-FR',{day:'2-digit',month:'short'});
      const num=(wk.split('-W')[1])||'';
      return `Semaine ${num} · ${f(lundi)} → ${f(dim)}`;
    };
    const corps=semaines.map(wk=>{
      const lot=parSem[wk].slice().sort((a,b)=>(a.o.date||'').localeCompare(b.o.date||''));  // dates croissantes
      // [v1340] La semaine affiche le total ET, s'il y a eu des acomptes, ce qu'il RESTE à percevoir.
      // [v1424] CORRIGÉ — Ben : « une commande à venir qui n'a aucun acompte doit afficher la somme
      // totale […] et juste à droite en rouge le montant restant à encaisser ». La v1340 ne montrait
      // le reste QUE si un acompte existait, en le jugeant redondant avec le total. Il ne l'est pas :
      // « 100 € » dit ce que vaut la semaine, « reste 100 € » dit ce qui n'est pas encore rentré —
      // et c'est le second chiffre qui pilote la trésorerie. Une semaine entièrement réglée d'avance
      // affiche « soldé » en vert plutôt qu'un « reste 0,00 € » en rouge, qui alertait pour rien.
      const T=cmdTotauxLot(lot);
      const _resteSem = (T.reste > 0.01)
        ? ` · <b style="color:#b3261e">reste ${euro(T.reste)}</b>`
        : (T.encaisse > 0 ? ` · <b style="color:#3f7d52">soldé</b>` : '');
      const enTete=`<div style="padding:8px 12px;background:var(--creme-2);border-bottom:1px solid var(--hair);font-size:.76rem;font-weight:600;color:#6a5a52;display:flex;justify-content:space-between;gap:8px">
        <span>${esc(_libSemaine(wk))}</span><span style="font-weight:500;color:#9a8a82">${lot.length} · ${euro(T.total)}${_resteSem}</span></div>`;
      return enTete + lot.map(r=>_cmdRowMini(r,{distinctif:false})).join('');
    }).join('');
    // [v1340] LE CHIFFRE QUI COMPTE POUR LA TRÉSORERIE : ce qu'il RESTE à percevoir.
    // Le total seul ne le disait pas — une partie est souvent déjà encaissée en acompte.
    const AV = cmdTotauxLot(aVenir);
    const _bandeau = AV.encaisse > 0
      ? `<div style="padding:9px 13px;background:#f0f5fa;border-bottom:1px solid #dbe6f2;font-size:.8rem;color:#4a5a6a;display:flex;justify-content:space-between;flex-wrap:wrap;gap:6px">
           <span>Total <b>${euro(AV.total)}</b></span>
           <span>− déjà encaissé <b style="color:#3f7d52">${euro(AV.encaisse)}</b> <span style="color:#9a8a82">(${AV.nbAvecAcompte} acompte${AV.nbAvecAcompte>1?'s':''})</span></span>
           <span>= <b style="color:#b3261e">reste ${euro(AV.reste)}</b></span>
         </div>
         ${AV.tropPercu>0?`<div style="padding:7px 13px;background:#fff6e5;border-bottom:1px solid #e5d3b3;font-size:.75rem;color:#6a5a52">⚠️ ${euro(AV.tropPercu)} de trop-perçu sur ces commandes. Il n'est PAS déduit du reste dû : un trop-perçu ne paie pas la commande d'à côté.</div>`:''}`
      : '';
    // [v1424] Même règle qu'en tête de semaine : le reste s'affiche même sans acompte. Laisser
    // l'en-tête du bloc muet pendant que chaque semaine annonce son reste serait un demi-correctif —
    // deux lignes du même panneau qui ne répondent pas à la même question.
    const _resteAVenir = (AV.reste > 0.01)
      ? ` · <b style="color:#b3261e">reste ${euro(AV.reste)}</b>`
      : (AV.encaisse > 0 ? ` · <b style="color:#3f7d52">soldé</b>` : '');
    html += `<details open style="margin:12px 0 4px;border:1px solid #c9d6e8;border-radius:12px;overflow:hidden;background:#f7fafd">
      <summary style="cursor:pointer;padding:11px 13px;font-weight:700;color:#3b6ea5;background:#eaf1f9">
        📅 À venir <span style="font-weight:500">(${aVenir.length}) · ${euro(AV.total)}${_resteAVenir}</span></summary>
      ${_bandeau}
      <div>${corps}</div>
    </details>`;
  }
  // 2) À ENCAISSER — section distincte, dépliée par défaut (à ne pas oublier)
  if(aEncaisser.length){
    // [v1340] Même règle unique que « À venir » : cette section affichait le reste dû sans jamais
    // dire de quel MONTANT TOTAL il provenait — impossible de savoir si 139 € de reste portaient
    // sur 150 € ou sur 3 000 € de commandes. Une seule fonction calcule désormais les deux.
    const AE = cmdTotauxLot(aEncaisser);
    const totReste = AE.reste;
    html += `<details open style="margin:12px 0 4px;border:1px solid #f0c89a;border-radius:12px;overflow:hidden;background:#fffaf3">
      <summary style="cursor:pointer;padding:11px 13px;font-weight:700;color:#b5701a;background:#fdf0dd">
        💰 À encaisser <span style="font-weight:500">(${aEncaisser.length}) · ${euro(AE.total)} · <b>reste ${euro(AE.reste)}</b>${AE.encaisse>0?` <span style="color:#9a8a82">(${euro(AE.encaisse)} déjà encaissé)</span>`:''}</span></summary>
      <div>${aEncaisser.map(r=>_cmdRowMini(r,{distinctif:true})).join('')}</div>
    </details>`;
  }
  // 3) TERMINÉES — repli simple (livrées + soldées)
  if(terminees.length){
    html += `<details style="margin:8px 0 4px;border:1px solid var(--hair);border-radius:12px;overflow:hidden">
      <summary style="cursor:pointer;padding:11px 13px;font-weight:600;color:#6a5a52;background:var(--creme-2)">
        ✓ Terminées <span style="font-weight:400;color:#9a8a82">(${terminees.length})</span></summary>
      <div>${terminees.map(r=>_cmdRowMini(r,{distinctif:false})).join('')}</div>
    </details>`;
  }
  // 4) [v1425] COMMANDES MÈRES RANGÉES — repli toujours présent dans la vue commande.
  //    Ben : « la commande mère doit être archivée […] tout en restant accessible à tout moment ».
  //    Rangée ≠ introuvable. Le repli s'OUVRE automatiquement dès qu'un filtre est actif : si Ben
  //    tape un nom de client, il ne doit pas avoir à deviner que le résultat se cache derrière un
  //    triangle fermé. Le chiffre montré est celui qui compte ici : ce qu'il RESTE à retirer.
  if(meresRangees.length){
    const _tousOrders = (_cmdCache||[]).map(e=>e.o);
    const _rel = o => (typeof reliquatCommandeMere==='function')
      ? reliquatCommandeMere(o, _tousOrders)
      : { reste:0, nbFilles:0, entierementRetiree:false };
    const resteTotal = money2(meresRangees.reduce((s,r)=> s + _rel(r.o).reste, 0));
    const lignes = meresRangees.map(r=>{
      const o=r.o, rel=_rel(o);
      const nom = privacyModeEnabled()?'•••':(_cmdClNameMap[o.clientId] || o.histoLabel || '—');
      const etat = rel.entierementRetiree
        ? `<span style="color:#3f7d52;font-weight:600;font-size:.78rem;white-space:nowrap">✓ tout retiré</span>`
        : `<span style="color:#b5701a;font-weight:600;font-size:.78rem;white-space:nowrap">reste ${euro(rel.reste)} à retirer</span>`;
      return `<div style="display:flex;align-items:center;gap:10px;padding:9px 12px;border-bottom:1px solid var(--hair)">
        <span style="flex:1;min-width:0;display:flex;flex-direction:column">
          <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.9rem">${esc(nom)}</span>
          <span style="color:#8a7a72;font-size:.74rem;white-space:nowrap">${fmtDate(o.date)} · ${rel.nbFilles} retrait${rel.nbFilles>1?'s':''}</span>
        </span>
        ${etat}
        <b style="font-size:.9rem;white-space:nowrap">${privacyModeEnabled()?'•••':euro(o.montant)}</b>
        <button class="cmd-pill detail" style="flex:none" onclick="cmdView(${o.id})" title="Voir le détail">👁</button>
        <button class="cmd-pill detail" style="flex:none" onclick="cmdForm(${o.id})" title="Modifier">✏️</button>
      </div>`;
    }).join('');
    html += `<details ${grouper?'':'open'} style="margin:8px 0 4px;border:1px solid #cfc4dd;border-radius:12px;overflow:hidden;background:#faf8fd">
      <summary style="cursor:pointer;padding:11px 13px;font-weight:600;color:#5b3a78;background:#f1ebf7">
        🧺 Commandes mères rangées <span style="font-weight:400;color:#7a6a8a">(${meresRangees.length})${resteTotal>0.01?` · <b style="color:#b5701a">reste ${euro(resteTotal)} à retirer</b>`:''}</span></summary>
      <div>${lignes}</div>
      <div style="padding:9px 12px;font-size:.76rem;color:#7a6a8a">Paiement encaissé en avance : la traçabilité est portée par chaque retrait, pas par cette commande.</div>
    </details>`;
  }
  if(rows.length>LIMIT) html += `<div class="note" style="text-align:center">… ${rows.length-LIMIT} autre(s) résultat(s). Affinez la recherche.</div>`;
  // [COCKPIT] Bandeau filtre jour actif (avec bouton pour l'enlever).
  if(cmdJourFiltre){
    const lbl = (typeof fmtDate==='function') ? fmtDate(cmdJourFiltre) : cmdJourFiltre;
    html = `<div style="display:flex;align-items:center;gap:8px;background:#f3eef7;border:1px solid #d9c9e6;border-radius:10px;padding:7px 11px;margin-bottom:10px;font-size:.82rem;color:#5b3a78">
      <span style="flex:1">📅 Commandes du <b>${esc(lbl)}</b></span>
      <button class="btn ghost sm" onclick="cmdSetJourFiltre(null)">✕ Tout afficher</button>
    </div>` + html;
  }
  body.innerHTML = html;
}
// Ligne séparatrice colorée par mois/année (couleur dérivée du mois → contraste entre groupes).
const _MOIS_FR=['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
const _SEP_COLORS=['#52252F','#AA7C39','#6aa3a0','#7a6a9a','#b07a4a','#3f7d52','#9a6a82','#5a7a9a','#a98b3d','#7a8a5a','#8a5a6a','#5a8a7a'];
// Clé d'année-semaine ISO (ex "2026-W24") pour regrouper par semaine.
function _isoWeekKey(dateStr){
  if(!dateStr) return null;
  const d=new Date(dateStr); if(isNaN(d)) return null;
  const t=new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const day=(t.getUTCDay()+6)%7;            // lundi=0
  t.setUTCDate(t.getUTCDate()-day+3);        // jeudi de la semaine ISO
  const firstThu=new Date(Date.UTC(t.getUTCFullYear(),0,4));
  const fday=(firstThu.getUTCDay()+6)%7;
  firstThu.setUTCDate(firstThu.getUTCDate()-fday+3);
  const week=1+Math.round((t-firstThu)/(7*86400000));
  return t.getUTCFullYear()+'-W'+String(week).padStart(2,'0');
}
