// Convertit une ancienne commande mono-type en lignes (rétro-compat).
// Renvoie les lignes SOUS FORME DE STOCKAGE : parfums/items en TABLEAU [{nom,qte}].
// (Forme attendue par les lecteurs : liste commandes, analytics, besoins matières, détail.)
// [AUDIT-2026-07 · A4] DÉFINITION UNIQUE d'une REPRISE d'historique (commande de migration).
// Deux marqueurs possibles : commande-niveau (o.histo===true) OU une ligne de type 'histo'.
// Centralisé ici pour que le Dashboard (caDuMois) et la Compta (computeAccounting) partagent
// EXACTEMENT la même règle d'exclusion — sinon les deux écrans redivergent.
function estReprise(o){
  if(!o) return false;
  if(o.histo===true) return true;
  try{ return orderToLines(o).some(l=>l && l.type==='histo'); }catch(e){ return false; }
}
function orderToLines(o){
  if(Array.isArray(o.lignes) && o.lignes.length) return JSON.parse(JSON.stringify(o.lignes));
  // ancien format : un seul type
  if(o.type==='evenement'){
    const parfums=[]; (o.parfums||[]).forEach(p=>{if(p.qte>0)parfums.push({nom:p.nom,qte:p.qte});});
    return [{type:'evenement', evQte:o.evQte||EVENT_MIN, equip:o.equip||0, parfums, sansParfum:(+o.sansParfum||0), pyraVendue:!!o.pyraVendue, pyraPrixVente:(o.pyraPrixVente!=null?+o.pyraPrixVente:null), pyraCoutAchat:(o.pyraCoutAchat!=null?+o.pyraCoutAchat:null), accessoireDeco:!!o.accessoireDeco}];
  }
  if(o.type==='grand'){
    const items=[]; (o.bigItems||[]).forEach(p=>{if(p.qte>0)items.push({nom:p.nom,qte:p.qte});});
    return [{type:'grand', tarif:o.tarif||'particulier', items}];
  }
  if(o.type==='coffret' || o.taille){
    const parfums=[]; (o.parfums||[]).forEach(p=>{if(p.qte>0)parfums.push({nom:p.nom,qte:p.qte});});
    return [{type:'coffret', taille:o.taille||6, parfums}];
  }
  return [];
}
// Modèle d'ÉDITION en mémoire : parfums/items en OBJET {nom:qte}. Utilisé uniquement par le
// formulaire de commande (drawLines & co). Corrige la perte des parfums à la réouverture.
function _parfumsToObj(p){
  if(!p) return {};
  if(Array.isArray(p)){ const o={}; p.forEach(x=>{ if(x && x.nom && +x.qte>0) o[x.nom]=+x.qte; }); return o; }
  if(typeof p==='object'){ const o={}; Object.keys(p).forEach(k=>{ if(+p[k]>0) o[k]=+p[k]; }); return o; }
  return {};
}
function _lineToEdit(ln){
  const t=ln.type;
  if(t==='coffret') return {type:'coffret', taille:ln.taille||6, parfums:_parfumsToObj(ln.parfums), sansParfum:(+ln.sansParfum||0), spMode:ln.spMode||'assortiment', spNbParfums:(+ln.spNbParfums||0), remisePct:+ln.remisePct||0, prixUnitaireApplique: (ln.prixUnitaireApplique!=null?+ln.prixUnitaireApplique:null), embMode:ln.embMode||'standard', embMatId:ln.embMatId||null};
  if(t==='evenement') return {type:'evenement', evQte:ln.evQte||EVENT_MIN, equip:(ln.equip!=null?ln.equip:EVENT_MIN_EQUIP), evFiltrePyr:(ln.evFiltrePyr!=null?ln.evFiltrePyr:null), parfums:_parfumsToObj(ln.parfums), sansParfum:(+ln.sansParfum||0), spMode:ln.spMode||'assortiment', spNbParfums:(+ln.spNbParfums||0), remisePct:+ln.remisePct||0, pyraVendue:!!ln.pyraVendue, pyraPrixVente:(ln.pyraPrixVente!=null?+ln.pyraPrixVente:null), pyraCoutAchat:(ln.pyraCoutAchat!=null?+ln.pyraCoutAchat:null), accessoireDeco:!!ln.accessoireDeco, _configChoisie:!!ln._configChoisie};
  if(t==='grand') return {type:'grand', tarif:ln.tarif||'particulier', items:_parfumsToObj(ln.items), remisePct:+ln.remisePct||0, embMode:ln.embMode||'reutilisable', embMatId:ln.embMatId||null};
  if(t==='vrac') return {type:'vrac', proMode:ln.proMode==='nonpro'?'nonpro':'pro', parfums:_parfumsToObj(ln.parfums), sansParfum:(+ln.sansParfum||0), spMode:ln.spMode||'assortiment', spNbParfums:(+ln.spNbParfums||0), remisePct:+ln.remisePct||0};
  if(t==='sachet') return {type:'sachet', parfums:_parfumsToObj(ln.parfums), sansParfum:(+ln.sansParfum||0), spMode:ln.spMode||'assortiment', spNbParfums:(+ln.spNbParfums||0), remisePct:+ln.remisePct||0};
  if(t==='don') return {type:'don', parfums:_parfumsToObj(ln.parfums), items:_parfumsToObj(ln.items), donEmbMode:ln.donEmbMode||'sans', embMatId:(ln.donEmbMode==='autre'?(ln.embMatId||null):null), sacMatId:(+ln.sacMatId>0?+ln.sacMatId:null), sacNb:(+ln.sacNb>0?+ln.sacNb:0)};
  if(t==='prestation') return {type:'prestation', presta:ln.presta||'', libelle:ln.libelle||'', montantHT:+ln.montantHT||0, dureeH:+ln.dureeH||0, mode:ln.mode||'', detail:ln.detail||'', remiseType:ln.remiseType||'pct', remisePct:+ln.remisePct||0, remiseEuro:+ln.remiseEuro||0, ...(ln.isLivraison?{isLivraison:true}:{})};
  return {...ln};
}
// Charge une commande dans le modèle d'édition (objet) sans rien perdre.
function orderToEditLines(o){ return orderToLines(o).map(_lineToEdit); }

let _cmdDevisMode = false;   // le formulaire de commande est-il en train de créer/éditer un devis ?
let _cmdDevisId = null;      // id du devis édité (registre documents)
async function cmdForm(id, opts){
  opts = opts || {};
  _cmdEditingId = id || 0;               // id de la commande en cours d'édition (0 = nouvelle) — sert aux
                                         // modales intermédiaires (composition, client rapide) pour rouvrir
                                         // le formulaire sans le détruire (keepLines).
  _cmdDevisMode = !!opts.devis;          // true = on crée/édite un DEVIS (enregistré dans documents)
  _cmdDevisId = opts.devisId || null;    // id du devis en cours d'édition (sinon nouveau)
  _privacySuspend=1; // saisie de commande toujours en clair, même en mode discret
  cmdClientsCache = await db.clients.toArray();
  cmdProductsCache = (await db.products.toArray()).filter(p=>p.actif!==false).sort((a,b)=>(+a.taille)-(+b.taille));
  // Emballages disponibles pour le choix par coffret : uniquement les contenants ayant une CAPACITÉ
  // (vraies boîtes). On exclut les consommables sans capacité comme le film étirable, le papier, etc.
  cmdEmballagesCache = (await db.materials.toArray()).filter(m=>m.categorie==='emballage' && +m.capacite>0).sort((a,b)=>(+a.capacite||0)-(+b.capacite||0));
  // Modèles de SACS (emballage usage:'sac') proposables sur la commande (quantité saisie à la main).
  cmdSacsCache = (await db.materials.toArray()).filter(m=>m.categorie==='emballage' && m.usage==='sac').sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  cmdEmbLotsCache = await db.materialLots.toArray().catch(()=>[]);   // lots pour calculer le coût unitaire emballage (dons)
  // caches pour le calcul de marge en direct (impact livraison + rentabilité)
  _cmdMarginCache = {
    recipes: await db.recipes.toArray(),
    recipeItems: await db.recipeItems.toArray(),
    lots: await db.materialLots.toArray()
  };
  // Contexte main-d'œuvre mesurée (temps réel par parfum × taux horaire) rafraîchi ici pour
  // que la part MO du coût de revient soit à jour dès le premier affichage du bloc rentabilité.
  try{ if(typeof refreshMoCtx==='function') await refreshMoCtx(); }catch(e){ console.error('cmdForm moCtx', e); }
  let o;
  if(_cmdDevisMode && _cmdDevisId){
    const dv = await db.documents.get(_cmdDevisId);
    o = dv ? {clientId:dv.clientId, date:dv.date, lignes:dv.lignes||[], remiseGlobale:dv.remiseGlobale||0, remiseGlobaleEur:(dv.remiseGlobaleEur!=null?+dv.remiseGlobaleEur:null),
              heureLivraison:dv.heureLivraison||'', lieuLivraison:dv.lieuLivraison||'', dateEvenement:dv.dateEvenement||'', dateEvtReel:dv.dateEvtReel||'', notes:dv.notes||'',
              distanceKm:dv.distanceKm||0, prixCarburant:dv.prixCarburant||0,
              tempsLivraisonMin:dv.tempsLivraisonMin||0, consoVehicule:(dv.consoVehicule!=null?dv.consoVehicule:null),
              fraisLivraison:dv.fraisLivraison||0, sacMatId:dv.sacMatId||0, sacNb:dv.sacNb||0,
              perso:!!(dv.perso||+dv.persoMacarons>0), persoMacarons:+dv.persoMacarons||0, persoCouleurs:Array.isArray(dv.persoCouleurs)?dv.persoCouleurs:[], persoRemiseEur:+dv.persoRemiseEur||0, acompteMention:(dv.acompteMention!==false),
              statut:'À préparer', paiement:'En attente'}
            : {date:today(),statut:'À préparer',paiement:'En attente',perso:false};
  } else {
    o = id ? await db.orders.get(id) : {date:today(),statut:'À préparer',paiement:'En attente',perso:false};
  }
  // Préserver les lignes en cours si on rouvre après ajout d'un client
  if(opts.keepLines && Array.isArray(cmdLines)){ /* cmdLines déjà en mémoire, on le garde */ }
  else { cmdLines = orderToEditLines(o); }   // forme objet, parfums conservés
  // [REMISE GLOBALE] Référence en euros. Si l'enregistrement porte déjà un montant € fixe, on le reprend.
  // Sinon (ancien format % uniquement), on le convertit UNE fois en euros à partir de la base courante,
  // ce qui fige le montant et évite qu'un « −30 % » ne se réapplique sur un sous-total différent.
  if(!opts.keepLines){
    if(o && o.remiseGlobaleEur!=null && +o.remiseGlobaleEur>0){
      _cmdRemiseGlobaleEur = money2(+o.remiseGlobaleEur);
    } else {
      const _st = addMoney(...cmdLines.map(ln=>lineTotal(ln)));
      const _perso = money2(((o&&o.persoMacarons)||0)*(typeof PERSO_PRIX_UNIT!=='undefined'?PERSO_PRIX_UNIT:0));
      const _base = money2(_st + _perso);
      const _pct = Math.max(0, Math.min(100, +(o&&o.remiseGlobale)||0));
      // [RÉTROCOMPAT REMISE €] Ancienne commande/devis sans remiseGlobaleEur : on privilégie
      // la remise € RÉELLE déduite du montant stocké (déjà net) plutôt que base×%, car le %
      // a pu être figé sur un ancien sous-total. On ne reconstruit base×% qu'en dernier recours.
      if(o && o.montant!=null && +o.montant>=0 && _base>0){
        const _rEff = money2(Math.max(0, Math.min(_base, _base - money2(+o.montant))));
        _cmdRemiseGlobaleEur = _rEff;
      } else {
        _cmdRemiseGlobaleEur = money2(_base*_pct/100);
      }
    }
    // [REMISE PERSO] Reprise de la remise perso stockée (euros fixes), plafonnée au supplément perso.
    const _persoSupOpen = money2(((o&&o.persoMacarons)||0)*(typeof PERSO_PRIX_UNIT!=='undefined'?PERSO_PRIX_UNIT:0));
    _cmdPersoRemiseEur = money2(Math.max(0, Math.min(_persoSupOpen, +(o&&o.persoRemiseEur)||0)));
  }
  const preselect = opts.clientId || o.clientId || 0;
  // trier les clients par nom pour un défilement lisible même à plusieurs centaines
  cmdClientsCache.sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  const clOpts = '<option value="0">— aucun —</option>'+sortByName(cmdClientsCache,'nom').map(c=>`<option value="${c.id}" ${preselect===c.id?'selected':''}>${esc(c.nom)}${c.tel?' · '+esc(c.tel):''}</option>`).join('');
  const curStatut = o.statut==='En cours' ? 'À préparer' : (o.statut||'À préparer');
  const stOpts = ORDER_STATUS.map(s=>`<option ${curStatut===s?'selected':''}>${s}</option>`).join('');
  const regOpts = `<option value="">—</option>`+PAY_METHODS.map(s=>`<option ${o.reglement===s?'selected':''}>${s}</option>`).join('');
  // Suggestions de lieux de livraison : presets + lieux des commandes passées.
  const places = await usualDeliveryPlaces();
  window.__placesCache = places;   // pour l'autocomplete personnalisé
  openModal(`<h3>${_cmdDevisMode?(_cmdDevisId?'Modifier le devis':'Nouveau devis'):(id?'Modifier':'Nouvelle')+' commande'}</h3>
   <div class="field"><label>Client</label>
     <input class="search" id="f_clsearch" placeholder="Rechercher par nom ou téléphone…" oninput="filterCmdClients(this.value)" value="" autocomplete="off">
     <div id="f_clResults" style="display:none;border:1px solid var(--hair);border-radius:10px;margin-top:4px;max-height:220px;overflow-y:auto;background:#fff"></div>
     <select id="f_cl" style="margin-top:6px" onchange="cmdSuggestClientAddress()">${clOpts||'<option value="0">— aucun —</option>'}</select>
     <button class="btn ghost sm" style="margin-top:6px" onclick="quickClient(${id||0})">+ Nouveau client</button>
   </div>
   <div class="field"><label>Date</label><input type="date" id="f_date" value="${o.date||today()}" oninput="cmdFeasibilityRecalc()"></div>
   <div class="field"><label>Heure de livraison <span style="color:#9a8a82;font-weight:400">— pour vérifier les délais (repos ganache, maturation)</span></label><input type="time" id="f_heure" value="${esc(o.heureLivraison||'')}" oninput="cmdSyncHeure(this.value);cmdFeasibilityRecalc()"></div>
   <div id="feasibility" class="feasibility" style="display:none"></div>

   <label style="font-size:.82rem;color:#7a6a62;font-weight:500;display:block;margin-bottom:6px">Produits de la commande</label>
   <div id="linesWrap"></div>
   <div class="add-line-row">
     <button class="btn ghost sm" onclick="addLine('coffret')">+ Coffret</button>
     <button class="btn ghost sm" onclick="addLine('sachet')">+ Sachet</button>
     <button class="btn ghost sm" onclick="addLine('evenement')">+ Événement</button>
     <button class="btn ghost sm" onclick="addLine('grand')">+ Grand format</button>
     <button class="btn ghost sm" onclick="addLine('vrac')">+ Vrac</button>
     <button class="btn ghost sm" onclick="addLine('prestation')">+ Prestation / Coaching</button>
     <button class="btn ghost sm" onclick="addLine('don')">+ Don (0 €)</button>
   </div>

   <div class="field"><label>Statut commande</label><select id="f_st">${stOpts}</select></div>

   <div class="field" id="sacBlock">
     <label>🛍️ Sac (optionnel) <span style="color:#9a8a82;font-weight:400">— ajouté au transport, décompté du stock</span></label>
     ${cmdSacsCache.length?`<div class="row2" style="align-items:end">
       <div class="field" style="margin:0"><label style="font-size:.78rem">Modèle</label>
         <select id="f_sacMat">
           <option value="0">— aucun —</option>
           ${cmdSacsCache.map(m=>`<option value="${m.id}" ${(+o.sacMatId===+m.id)?'selected':''}>${esc(m.nom)}${m.marque?' · '+esc(m.marque):''}</option>`).join('')}
         </select></div>
       <div class="field" style="margin:0"><label style="font-size:.78rem">Nombre</label>
         <input type="number" min="0" step="1" id="f_sacNb" value="${o.sacNb!=null&&+o.sacNb>0?esc(o.sacNb):''}" placeholder="ex : 2"></div>
     </div>
     <p class="note" style="margin-top:4px">Saisis le nombre de sacs utilisés pour cette commande. Le coût réel sera imputé à la validation.</p>`
     :`<p class="note">Aucun modèle de sac enregistré. Crée-en un dans <b>Matières & emballages</b> (type « 🛍️ Sac ») pour pouvoir l'ajouter ici.</p>`}
   </div>

   <div class="collapse-sec" id="livBlock">
     <button type="button" class="collapse-head" onclick="toggleLivBlock()">
       <span>🚚 Livraison <span class="collapse-hint">— horaire, adresse, trajet (optionnel)</span></span>
       <span class="collapse-arrow" id="livArrow">▸</span>
     </button>
     <div class="collapse-body" id="livBody" style="display:none">
       <div class="field"><label>Date de livraison <span style="color:#9a8a82;font-weight:400">— la date qui pilote la fabrication (à noter toujours)</span></label><input type="date" id="f_dateEvenement" value="${esc(o.dateEvenement||'')}"></div>
       <div class="field"><label>Date de l'événement <span style="color:#9a8a82;font-weight:400">— facultatif · jour de la prestation (mariage, réception…), si différent de la livraison</span></label><input type="date" id="f_dateEvtReel" value="${esc(o.dateEvtReel||'')}"></div>
       <div class="field"><label>Heure de livraison <span style="color:#9a8a82;font-weight:400">— aussi accessible en haut du formulaire</span></label><input type="time" id="f_heureBas" value="${esc(o.heureLivraison||'')}" oninput="cmdSyncHeure(this.value,true);cmdFeasibilityRecalc()"></div>
       <div class="field"><label>Adresse / lieu de livraison <span style="color:#9a8a82;font-weight:400">— tapez pour rechercher (clients, lieux habituels)</span></label>
         <div class="ac-wrap">
           <input class="search" id="f_lieu" autocomplete="off" autocapitalize="words" placeholder="Tapez une adresse, un nom de client ou un lieu…" value="${esc(o.lieuLivraison||'')}"
             oninput="acFilter(this.value);cmdTrajetProposeDiff()" onfocus="acFilter(this.value)">
           <div id="acList" class="ac-list" style="display:none"></div>
         </div>
       </div>
       <div id="trajetPropo" style="display:none;margin-bottom:8px"></div>
       <div class="row2">
         <div class="field"><label>Distance aller (km) <span style="color:#9a8a82;font-weight:400">— l'aller-retour est calculé</span></label>
           <input type="number" min="0" step="0.1" id="f_distKm" value="${o.distanceKm!=null?esc(o.distanceKm):''}" placeholder="ex : 8" oninput="cmdDeliveryRecalc()"></div>
         <div class="field"><label>Prix carburant (€/L)</label>
           <input type="number" min="0" step="0.001" id="f_carbu" value="${o.prixCarburant!=null?esc(o.prixCarburant):''}" placeholder="ex : 1.85" oninput="cmdDeliveryRecalc()"></div>
       </div>
       <div class="field"><label>Temps de trajet aller (min) <span style="color:#9a8a82;font-weight:400">— l'aller-retour est calculé (×2)</span></label>
         <input type="number" min="0" step="1" id="f_tempsLiv" value="${o.tempsLivraisonMin!=null?esc(o.tempsLivraisonMin):''}" placeholder="ex : 15" oninput="cmdDeliveryRecalc()"></div>
       <div class="field"><label>Consommation réelle du véhicule (L/100 km) <span style="color:#9a8a82;font-weight:400">— laisser vide = réglage par défaut (${getSettings().vehicleConso} L)</span></label>
         <input type="number" min="0" step="0.1" id="f_conso" value="${o.consoVehicule!=null&&o.consoVehicule!==''?esc(o.consoVehicule):''}" placeholder="ex : 7.2" oninput="cmdDeliveryRecalc()"></div>
       <div class="sum-box" id="deliveryImpact" style="display:none;flex-direction:column;align-items:stretch;gap:4px"></div>
     </div>
   </div>
   <label class="switch-row"><input type="checkbox" id="f_perso" ${o.perso||+o.persoMacarons>0?'checked':''} onchange="cmdPersoToggle()"> Personnalisation des couleurs (+0,25 €/macaron)</label>
   <div class="field" id="f_persoWrap" style="${(o.perso||+o.persoMacarons>0)?'':'display:none'}"><label>Nombre de macarons personnalisés <span style="color:#9a8a82;font-weight:400">— pas forcément le total de la commande</span></label>
     <input type="number" min="0" step="1" id="f_persoNb" value="${o.persoMacarons||''}" placeholder="ex : 24" oninput="cmdRecalc()">
     <div class="row2" style="margin-top:8px">
       <div class="field" style="margin:0"><label style="font-weight:400;color:#7a6a60">Remise perso (€)</label>
         <input type="number" min="0" step="0.01" id="f_persoRemEur" value="${+o.persoRemiseEur>0?money2(+o.persoRemiseEur):''}" placeholder="ex : 6" oninput="cmdPersoRemiseFromEuro()"></div>
       <div class="field" style="margin:0"><label style="font-weight:400;color:#7a6a60">Remise perso (%)</label>
         <input type="number" min="0" max="100" step="1" id="f_persoRemPct" placeholder="ex : 100 = offert" oninput="cmdPersoRemiseFromPct()"></div>
     </div>
     <div style="margin-top:8px"><label style="font-weight:400;color:#7a6a60">Détail couleur \u2194 parfum <span style="color:#9a8a82">— apparaît dans un encadré sur le devis et la facture (facultatif)</span></label>
       <div id="f_persoCoulList">${cmdPersoCoulRows(o.persoCouleurs)}</div>
       <button type="button" class="btn ghost" style="margin-top:4px;padding:5px 12px;font-size:.8rem" onclick="cmdPersoCoulAdd()">+ Ajouter une couleur</button>
     </div></div>
   <div class="row2">
     <div class="row2" style="align-items:end">
       <div class="field" style="margin:0"><label>Remise globale (€)</label><input type="number" min="0" step="0.01" id="f_remisegEur" placeholder="0" oninput="cmdGlobalRemiseFromEuro(this.value)"></div>
       <div class="field" style="margin:0"><label>Remise globale (%) <span style="color:#9a8a82;font-weight:400">— indicatif</span></label><input type="number" min="0" max="100" step="1" id="f_remiseg" placeholder="0" oninput="cmdGlobalRemiseFromPct(this.value)"></div>
     </div>
     <div class="field"><label>Prix total (€) <span style="color:#9a8a82;font-weight:400">— auto, modifiable</span></label><input type="number" step="0.01" id="f_mt" value="${o.montant||''}" oninput="_cmdPriceManual=true;this.dataset.auto='0';cmdRecalc()"></div>
   </div>
   <div class="sum-box" id="priceBreak" style="display:none"></div>

   <!-- RENTABILITÉ EN DIRECT : coût de revient réel + marge, recalculé à chaque frappe.
        En-tête cliquable (verdict + revient + marge toujours visibles) ; détail au tap. -->
   <div class="sum-box" id="cmdRentaBox" style="display:none;flex-direction:column;align-items:stretch;gap:6px;margin-top:8px">
     <div id="cmdRentaHead" onclick="cmdRentaToggle()" style="display:flex;justify-content:space-between;align-items:center;gap:8px;cursor:pointer">
       <span style="display:inline-flex;align-items:center;gap:6px;font-weight:600;color:var(--bordeaux)">
         <span id="cmdRentaChev" style="display:inline-block;transition:transform .15s;color:#b39a86">▶</span>
         Rentabilité
       </span>
       <span id="cmdRentaSum" style="font-size:.9rem;text-align:right"></span>
     </div>
     <div id="cmdRentaBody" style="display:none;font-size:.9rem"></div>
   </div>

   <label class="switch-row" style="margin-top:10px"><input type="checkbox" id="f_acompteMention" ${o.acompteMention!==false?'checked':''}> Afficher la mention « acompte de 75 % requis » sur le devis <span style="color:#9a8a82;font-weight:400">— décoche pour la masquer sur cette commande</span></label>

   <div class="field" style="margin-top:14px" id="cmdMereBlock"></div>

   <div class="pay-ledger" style="margin-top:14px">
     <div style="margin-bottom:6px">
       <label style="font-weight:600;color:var(--bordeaux)">Paiements encaissés</label>
     </div>
     <div id="payList"></div>
     <button type="button" class="btn ghost sm" onclick="cmdAddPayment()">＋ Ajouter un paiement</button>
     <div class="pay-summary" id="paySummary" style="margin-top:8px"></div>
     <div class="field" style="margin-top:8px"><label>Date prévue du règlement final <span style="color:#9a8a82;font-weight:400">— acomptes / événements</span></label>
       <input type="date" id="f_dateFinal" value="${esc(o.dateReglementFinal||'')}"></div>
   </div>
   <input type="hidden" id="f_pay" value="${esc(o.paiement||'En attente')}">

   <div class="field" style="margin-top:14px"><label>Notes</label><textarea id="f_notes" rows="2" placeholder="Allergies, livraison, demande spéciale…">${esc(o.notes||'')}</textarea></div>

   <p class="note" style="font-size:.78rem;color:#7a6a62;display:flex;gap:6px;align-items:center;margin-top:4px">📅 <span>Cette commande est ajoutée automatiquement au calendrier${(o.dateEvenement||o.date) ? ` le ${fmtDate(o.dateEvenement||o.date)}` : ''}.</span></p>
   <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button><button class="btn" onclick="saveCmd(${id||0})">Enregistrer</button></div>`);
  await cmdRenderMereBlock(id||0, o.commandeMereId||null);
  // initialise le registre de paiements en mémoire (copie de travail)
  // Initialise le registre d'édition. Pour une ancienne commande « Payé » sans registre,
  // on reconstitue une ligne à partir des données réellement enregistrées (date/mode si connus),
  // sans jamais inventer une date.
  cmdPayments = JSON.parse(JSON.stringify(
    (o.paiements && o.paiements.length) ? o.paiements
    : (o.paiement==='Payé' ? [{date:o.datePaiement||'', montant:+o.montant||0, moyen:o.reglement||''}] : [])
  ));
  const mt=document.getElementById('f_mt');
  // [PRIX] Mode AUTO par défaut : le total se recalcule quand on change les produits.
  // EXCEPTION : si la commande a été enregistrée avec un PRIX MANUEL (o.prixManuel),
  // on respecte ce prix à la réouverture — on ne le recalcule pas, on ne l'écrase pas.
  // Un prix tapé à la main est ainsi mémorisé d'une session d'édition à l'autre.
  _cmdPriceManual = !!(o && o.prixManuel);
  // [GARDE-FOU PRIX MANUEL] Même si le flag prixManuel n'a pas été persisté (anciennes commandes,
  // ou perte du flag), on le redéduit : si le montant enregistré diffère du total recalculé depuis
  // les lignes (remises/perso inclus), c'est forcément un prix forcé à la main → on le respecte.
  // Sans ça, la réouverture réafficherait le prix « auto » des lignes et écraserait la correction.
  if(!_cmdPriceManual && o && +o.montant>0){
    try{
      const _st = (cmdLines||[]).reduce((a,ln)=>a+(typeof lineTotalStored==='function'?lineTotalStored(ln):(typeof lineTotal==='function'?lineTotal(ln):0)),0);
      const _gpct = Math.max(0, Math.min(100, +o.remiseGlobale||0));
      const _rg = money2(_st*_gpct/100);
      const _perso = money2(((o.persoMacarons||0))*(typeof PERSO_PRIX_UNIT!=='undefined'?PERSO_PRIX_UNIT:0));
      const _autoTotal = Math.max(0, money2(_st - _rg + _perso));
      if(Math.abs(_autoTotal - money2(+o.montant)) > 0.01){ _cmdPriceManual = true; }
    }catch(e){ /* en cas de doute, on ne force rien */ }
  }
  if(mt) mt.dataset.auto = _cmdPriceManual ? '0' : '1';
  drawPayments();
  _cmdOpening = true;   // [v1216] on charge la commande : ni drawLines ni cmdRecalc ne doivent écraser le prix manuel
  drawLines();
  cmdRecalc();
  _cmdOpening = false;
  // [v1382] Proposer le trajet dès l'ouverture : à ce stade le lieu et le client sont posés.
  // Sur une commande déjà chiffrée, rien n'est écrasé — le bandeau dit seulement d'où viendrait
  // le chiffre, ce qui permet de repérer une saisie aberrante.
  if(typeof cmdTrajetPropose==='function') cmdTrajetPropose();
  // [v1206] Le bloc livraison reste REPLIÉ par défaut, même si la commande a déjà des infos de
  // livraison. L'utilisateur l'ouvre au clic s'il veut les voir/modifier ; les valeurs restent
  // actives (l'encart de résultat livraison s'affiche quand même). Demande : moins de bruit visuel.
}
// Registre de paiements en cours d'édition (copie de travail, écrit en base au save)
let cmdPayments=[];
// [v1407] Dessine le bloc de rattachement mère/fille dans le formulaire commande.
//   - Commande NEUVE ou SANS filles ⇒ champ « Rattacher à une commande mère » (sélection libre
//     parmi les commandes existantes, la commande courante exclue de la liste).
//   - Commande MÈRE (a déjà ≥1 fille) ⇒ liste des filles + reliquat, PAS de champ de
//     rattachement (une mère ne peut pas être elle-même une fille — évite les cycles).
async function cmdRenderMereBlock(id, mereIdActuel){
  const zone = document.getElementById('cmdMereBlock');
  if(!zone) return;
  const orders = await db.orders.toArray().catch(()=>[]);
  const filles = id ? commandesFillesDe(id, orders) : [];

  if(filles.length){
    // [v1407] Vue MÈRE : le montant vient du champ f_mt (et NON f_montant, qui n'existe pas —
    // bug de la première version : le reliquat affichait toujours 0 €).
    const mereFictive = { id, montant: (+((document.getElementById('f_mt')||{}).value)||0) };
    const r = reliquatCommandeMere(mereFictive, orders);
    const paiements = paiementsDe(orders.find(o=>+o.id===+id) || {});
    const resumePaiement = paiements.length
      ? paiements.map(p=>`${qty(p.montant)} € en ${esc(p.moyen||'—')} le ${fmtDate(p.date)}`).join(' · ')
      : '<span style="color:#b3261e">aucun paiement enregistré sur cette commande mère</span>';
    zone.innerHTML = `
      <div style="border:2px solid var(--bordeaux);border-radius:12px;padding:12px 14px;background:#fdfaf6">
        <label style="font-weight:600;color:var(--bordeaux);display:block;margin-bottom:6px">🔗 Commande mère · ${filles.length} sous-commande${filles.length>1?'s':''} rattachée${filles.length>1?'s':''}</label>
        <div style="font-size:.82rem;color:#5a4a52;margin-bottom:4px">💶 Encaissé ici : <b>${resumePaiement}</b></div>
        <div style="font-size:.82rem;color:#5a4a52;margin-bottom:10px">
          Déjà retiré : <b>${qty(r.montantCouvertParFilles)} €</b> · Reste à retirer : <b style="color:${r.reste>0?'#b3261e':'#3d7a3d'}">${qty(r.reste)} €</b> sur ${qty(r.montantTotal)} €
          ${r.entierementRetiree ? ' <span style="color:#3d7a3d;font-weight:600">✓ Entièrement retirée</span>' : ''}
        </div>
        <div style="display:flex;flex-direction:column;gap:5px">
          ${filles.map(f=>`<div style="font-size:.8rem;padding:7px 10px;background:#fff;border:1px solid #eadfd4;border-radius:8px;display:flex;justify-content:space-between;align-items:center">
            <span>#${f.id} · retiré le ${fmtDate(f.date)} · <b>${qty(+f.montant||0)} €</b></span>
            <button type="button" class="btn ghost sm" style="padding:2px 10px" onclick="cmdForm(${f.id})">Ouvrir</button>
          </div>`).join('')}
        </div>
      </div>`;
    return;
  }

  // Vue FILLE (ou commande libre) : recherche intelligente + remontée du paiement de la mère.
  // [v1409] Plus de <select> avec tout l'historique : une barre de recherche « avril 2026
  // David Siempé ». Et une mère reste proposée TANT QUE son reliquat n'est pas épuisé.
  const cmdCourante = id ? orders.find(o=>+o.id===+id) : null;
  const dejaMere = !!(cmdCourante && cmdCourante.mereEnAttente);
  const mereActuelle = mereIdActuel ? orders.find(o=>+o.id===+mereIdActuel) : null;
  zone.innerHTML = `
    <label class="switch-row" style="margin-bottom:8px">
      <input type="checkbox" id="f_mereEnAttente" data-initial="${dejaMere?'1':'0'}" ${dejaMere?'checked':''} onchange="cmdToggleMereEnAttente()">
      🔗 Commande mère — paiement encaissé en avance
      <span style="color:#9a8a82;font-weight:400">— sera rangée dans les archives dès l'enregistrement, et servira des sous-commandes au fil des retraits</span>
    </label>
    <div id="cmdMereRattachZone">
      <label>Rattacher cette commande à une commande mère <span style="color:#9a8a82;font-weight:400">— optionnel, pour un paiement déjà réglé ailleurs</span></label>
      <input type="hidden" id="f_commandeMereId" value="${mereIdActuel||''}">
      <input type="text" id="f_mereRech" placeholder="Rechercher : avril 2026 David Siempé…"
             oninput="cmdChercherMere(${id||0})" autocomplete="off"
             style="width:100%;margin-bottom:6px">
      <div id="cmdMereResultats"></div>
      <div id="cmdMereInfo"></div>
      <div id="cmdMereAlerte"></div>
    </div>`;
  cmdToggleMereEnAttente();
  if(mereActuelle) await cmdRenderInfoMere();
}

// [v1411] Une commande ne peut pas être à la fois mère (paiement en avance) et fille
// (rattachée à une autre) — ce serait une chaîne à deux niveaux, source de double comptage.
// Cocher « commande mère » masque donc le bloc de rattachement, et vice-versa.
function cmdToggleMereEnAttente(){
  const chk = document.getElementById('f_mereEnAttente');
  const zone = document.getElementById('cmdMereRattachZone');
  if(!chk || !zone) return;
  zone.style.display = chk.checked ? 'none' : '';
  if(chk.checked){
    const hid = document.getElementById('f_commandeMereId');
    if(hid) hid.value = '';   // on ne peut pas être fille en même temps
  }
}

// [v1409] Recherche des mères candidates et rendu de la liste (max 12 résultats — jamais
// tout l'historique). Chaque résultat montre le client, la date, le montant ET le reste à
// retirer : c'est ce reste qui indique d'un coup d'œil si la mère peut encore accueillir
// une sous-commande.
async function cmdChercherMere(idCourant){
  const zone = document.getElementById('cmdMereResultats');
  const champ = document.getElementById('f_mereRech');
  if(!zone || !champ) return;
  const [orders, clients] = await Promise.all([
    db.orders.toArray().catch(()=>[]),
    db.clients.toArray().catch(()=>[]),
  ]);
  const q = champ.value || '';
  const res = filtrerCommandesMere(q, orders, clients, idCourant, 12);
  const nomDe = cid => { const c=clients.find(x=>+x.id===+cid); return c?(c.nom||'—'):'—'; };
  const selId = +((document.getElementById('f_commandeMereId')||{}).value)||0;

  if(!res.length){
    zone.innerHTML = `<p class="note" style="font-size:.8rem;color:#9a8a82;padding:6px 0">
      ${q.trim() ? 'Aucune commande mère disponible pour cette recherche.' : 'Tape un nom de client, un mois ou une année pour trouver la commande mère.'}
      <br><span style="font-size:.74rem">Seules les commandes dont le montant n'est pas entièrement retiré peuvent recevoir une sous-commande.</span></p>`;
    return;
  }
  zone.innerHTML = res.map(o=>{
    const r = reliquatCommandeMere(o, orders);
    const actif = (+o.id===selId);
    return `<div onclick="cmdChoisirMere(${o.id},${idCourant})"
      style="cursor:pointer;padding:8px 10px;margin-bottom:4px;border-radius:9px;font-size:.84rem;
             border:2px solid ${actif?'var(--bordeaux)':'#eadfd4'};background:${actif?'#fdf2f4':'#fff'}">
      <div style="display:flex;justify-content:space-between;gap:8px">
        <b>${esc(nomDe(o.clientId))}</b><span style="color:#7a6a62">${fmtDate(o.date)}</span>
      </div>
      <div style="font-size:.78rem;color:#5a4a52;margin-top:2px">
        #${o.id} · total ${qty(r.montantTotal)} € · reste à retirer <b style="color:#b3261e">${qty(r.reste)} €</b>
        ${r.nbFilles ? ` · déjà ${r.nbFilles} sous-commande${r.nbFilles>1?'s':''}` : ''}
        ${actif ? ' <span style="color:var(--bordeaux);font-weight:700">✓ sélectionnée</span>' : ''}
      </div></div>`;
  }).join('');
}

// Sélectionne une mère depuis la liste de résultats.
function cmdChoisirMere(mereId, idCourant){
  const hid = document.getElementById('f_commandeMereId');
  if(!hid) return;
  hid.value = (+hid.value===+mereId) ? '' : mereId;   // re-cliquer désélectionne
  cmdChercherMere(idCourant);
  cmdOnMereChange();
}

// [v1407] Bandeau vert sur une commande FILLE : rappelle d'où vient l'argent, de façon
// explicite et datée — « Payé en espèces le 12/07/2026 sur la commande mère #42 ».
// Sans ça, une sous-commande semblait payée sans qu'on sache ni quand, ni comment, ni où.
async function cmdRenderInfoMere(){
  const zone = document.getElementById('cmdMereInfo');
  const sel = document.getElementById('f_commandeMereId');
  if(!zone || !sel) return;
  if(!sel.value){ zone.innerHTML=''; return; }
  const mere = await db.orders.get(+sel.value).catch(()=>null);
  if(!mere){ zone.innerHTML=''; return; }
  const paiements = paiementsDe(mere);
  const orders = await db.orders.toArray().catch(()=>[]);
  const r = reliquatCommandeMere(mere, orders);
  const lignes = paiements.length
    ? paiements.map(p=>`Payé ${qty(p.montant)} € en <b>${esc(p.moyen||'—')}</b> le <b>${fmtDate(p.date)}</b>`).join('<br>')
    : '<span style="color:#b3261e">⚠ Aucun paiement enregistré sur la commande mère #'+mere.id+'</span>';
  zone.innerHTML = `
    <div style="margin-top:8px;padding:10px 12px;background:#eef6ee;border:1px solid #7bb07b;border-radius:10px;font-size:.82rem;color:#2f5c2f">
      <b>✓ Déjà réglé sur la commande mère #${mere.id}</b><br>
      ${lignes}
      <div style="margin-top:6px;color:#4a6a4a">Cette sous-commande n'est donc <b>pas encaissée à nouveau</b>. Reste à retirer sur la mère : <b>${qty(r.reste)} €</b>.</div>
      <button type="button" class="btn ghost sm" style="margin-top:6px;padding:2px 10px" onclick="cmdForm(${mere.id})">Ouvrir la commande mère</button>
    </div>`;
}

// Réagit au choix d'une mère : affiche l'avertissement rouge si CETTE commande (la future fille)
// a déjà des paiements enregistrés — sans jamais bloquer (Ben garde la main).
function cmdOnMereChange(){
  const sel = document.getElementById('f_commandeMereId');
  const alerteZone = document.getElementById('cmdMereAlerte');
  if(!sel || !alerteZone) return;
  if(!sel.value){ alerteZone.innerHTML=''; cmdRenderInfoMere(); return; }
  const alerte = alerteRattachementFille({ paiements: (typeof cmdPayments!=='undefined' ? cmdPayments : []) });
  alerteZone.innerHTML = alerte
    ? `<p style="color:#b3261e;font-size:.78rem;margin-top:6px;padding:8px;background:#fdf0ee;border-radius:8px">${alerte.message}</p>`
    : '';
  cmdRenderInfoMere();
}

// [v1411] Vue « Paiements en avance » : les commandes mères rangées hors du fil, qui attendent
// encore d'être servies. Sans cet écran, une mère archivée deviendrait invisible — on ne saurait
// plus ce qu'on doit à qui. Chaque ligne montre le reste à retirer, le vrai chiffre utile.
async function cmdVoirMeresEnAttente(){
  const [orders, clients] = await Promise.all([
    db.orders.toArray().catch(()=>[]),
    db.clients.toArray().catch(()=>[]),
  ]);
  const meres = commandesMeresEnAttente(orders);
  const nomDe = cid => { const c=clients.find(x=>+x.id===+cid); return c?(c.nom||'—'):'—'; };

  if(!meres.length){
    openModal(`<h3>🔗 Paiements en avance</h3>
      <p class="note">Aucune commande mère en attente.</p>
      <p class="note" style="font-size:.8rem">Pour en créer une : ouvre une commande, coche « Commande mère — paiement encaissé en avance », enregistre. Elle sera rangée automatiquement et réapparaîtra ici tant qu'il restera des macarons à retirer.</p>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  const totalDu = money2(meres.reduce((s,m)=> s + reliquatCommandeMere(m, orders).reste, 0));
  openModal(`<h3>🔗 Paiements en avance</h3>
    <p class="note">${meres.length} commande${meres.length>1?'s':''} payée${meres.length>1?'s':''} d'avance, rangée${meres.length>1?'s':''} hors du fil, en attente d'être servie${meres.length>1?'s':''}.</p>
    <div class="sum-box" style="margin-bottom:10px"><span>Reste à livrer au total</span><b>${euro(totalDu)}</b></div>
    <div style="max-height:55vh;overflow:auto">
      ${meres.map(m=>{
        const r = reliquatCommandeMere(m, orders);
        return `<div style="padding:10px 12px;margin-bottom:6px;border:1px solid #eadfd4;border-radius:10px;background:#fff">
          <div style="display:flex;justify-content:space-between;gap:8px;align-items:baseline">
            <b>${esc(nomDe(m.clientId))}</b><span style="color:#7a6a62;font-size:.82rem">${fmtDate(m.date)}</span>
          </div>
          <div style="font-size:.82rem;color:#5a4a52;margin:4px 0 6px">
            #${m.id} · payé ${euro(r.montantTotal)} · déjà retiré ${euro(r.montantCouvertParFilles)}
            ${r.nbFilles ? ` (${r.nbFilles} sous-commande${r.nbFilles>1?'s':''})` : ''}
            · <b style="color:#b3261e">reste ${euro(r.reste)}</b>
          </div>
          <button class="btn ghost sm" onclick="closeModal();cmdView(${m.id})">Ouvrir</button>
        </div>`;
      }).join('')}
    </div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}

function cmdAddPayment(){
  const reste=cmdCurrentBalance();
  // Aucune donnée auto-générée : date et mode vides, à saisir manuellement.
  // Seul le montant est pré-suggéré au solde restant (modifiable, et zéro accepté tant que non validé).
  cmdPayments.push({date:'', montant: reste>0?reste:'', moyen:''});
  drawPayments(); cmdRecalc();
}
function cmdRemovePayment(i){ cmdPayments.splice(i,1); drawPayments(); cmdRecalc(); }
function setPayField(i,field,v){
  if(!cmdPayments[i]) return;
  cmdPayments[i][field] = field==='montant' ? (v===''?'':money2(+v||0)) : v;
  // redessine seulement pour la validation visuelle des champs date/mode ; le montant garde le focus
  if(field==='montant') cmdUpdatePaySummary(); else drawPayments();
}
// Total commande courant (depuis le champ montant)
function cmdCurrentTotal(){ return money2(+(document.getElementById('f_mt')?.value)||0); }
function cmdCurrentPaid(){ return money2(cmdPayments.reduce((s,p)=>s+((+p.montant)||0),0)); }
function cmdCurrentBalance(){ return money2(cmdCurrentTotal()-cmdCurrentPaid()); }
const PAY_METHODS_LIST = PAY_METHODS;
// Une ligne d'encaissement est valide si montant>0 ET date ET mode renseignés.
function payRowValid(p){ return (+p.montant)>0 && !!p.date && !!p.moyen; }
function drawPayments(){
  const box=document.getElementById('payList'); if(!box) return;
  box.innerHTML = cmdPayments.length ? cmdPayments.map((p,i)=>{
    const missing = !payRowValid(p);
    return `
    <div class="pay-row${missing?' pay-row-err':''}">
      <input type="date" value="${esc(p.date||'')}" onchange="setPayField(${i},'date',this.value)" title="Date de règlement (obligatoire)" ${!p.date?'style="border-color:var(--red,#b3261e)"':''}>
      <input type="number" step="0.01" min="0" value="${p.montant===''?'':p.montant}" placeholder="€" oninput="setPayField(${i},'montant',this.value)" title="Montant encaissé (obligatoire)" ${!((+p.montant)>0)?'style="border-color:var(--red,#b3261e)"':''}>
      <select onchange="setPayField(${i},'moyen',this.value)" title="Mode de paiement (obligatoire)" ${!p.moyen?'style="border-color:var(--red,#b3261e)"':''}>
        <option value="" ${!p.moyen?'selected':''}>— mode —</option>
        ${PAY_METHODS_LIST.map(m=>`<option ${p.moyen===m?'selected':''}>${m}</option>`).join('')}</select>
      <button type="button" class="act del" onclick="cmdRemovePayment(${i})" title="Retirer">✕</button>
    </div>`;
  }).join('') : '<p class="note" style="margin:4px 0">Aucun encaissement. Cliquez « Ajouter un paiement » pour enregistrer un règlement (partiel ou total).</p>';
  const anyMissing = cmdPayments.some(p=>!payRowValid(p));
  if(anyMissing){ box.insertAdjacentHTML('beforeend', '<p class="note" style="color:var(--red,#b3261e);margin-top:4px">⚠ Chaque encaissement exige un montant, une date et un mode de paiement.</p>'); }
  cmdUpdatePaySummary();
}
function cmdUpdatePaySummary(){
  const box=document.getElementById('paySummary'); if(!box) return;
  const total=cmdCurrentTotal(), paid=cmdCurrentPaid(), reste=money2(total-paid);
  // Trop-perçu : encaissé > total (pourboire, arrondi, geste commercial). Signalé, pas bloquant.
  const trop = paid > total + 1e-9;
  const st = trop ? 'Trop-perçu' : (total>0 && paid+1e-9>=total ? 'Payé' : (paid>0?'Partiel':'En attente'));
  const col = st==='Payé'?'#3f7d52':(st==='Trop-perçu'?'#d98324':(st==='Partiel'?'var(--caramel)':'var(--red,#b3261e)'));
  // Libellé de la ligne de solde : « restant dû » si on doit encore, « excédent » si trop-perçu.
  const ligneLbl = trop ? 'Excédent encaissé' : 'Solde restant dû';
  const ligneVal = trop ? money2(paid-total) : reste;
  const ligneCol = trop ? '#d98324' : (reste>0?'var(--red,#b3261e)':'#3f7d52');
  box.innerHTML = `<div style="display:flex;justify-content:space-between"><span>Encaissé</span><b>${euro(paid)}</b></div>
    <div style="display:flex;justify-content:space-between"><span>Total commande</span><b>${euro(total)}</b></div>
    <div style="display:flex;justify-content:space-between;border-top:1px solid #e8dccd;margin-top:4px;padding-top:4px">
      <span><b>${ligneLbl}</b> <span class="tag" style="background:${col};color:#fff">${st}</span></span><b style="color:${ligneCol}">${euro(ligneVal)}</b></div>
    ${trop?`<p class="note" style="color:#d98324;margin-top:4px">⚠ Tu as encaissé ${euro(paid-total)} de plus que le total. Normal si pourboire/arrondi ; sinon vérifie le prix ou le paiement.</p>`:''}`;
  const hid=document.getElementById('f_pay'); if(hid) hid.value = (st==='Payé'||st==='Trop-perçu')?'Payé':'En attente';
}

// Compat. : ces helpers existaient pour l'ancien toggle ; le registre de paiements les remplace.

// Recherche client instantanée dans le formulaire de commande (nom ou téléphone)
function filterCmdClients(q){
  const sel=document.getElementById('f_cl'); if(!sel)return;
  const cur=sel.value;
  const term=normTxt((q||'').trim());
  const norm=s=>normTxt(s||'');
  const digits=s=>(s||'').replace(/[^0-9]/g,'');
  const qd=digits(q);
  const matches = !term ? cmdClientsCache : cmdClientsCache.filter(c=>{
    const byName = norm(c.nom).includes(term);
    const byTel = qd && digits(c.tel).includes(qd);
    return byName || byTel;
  });
  // 1) garde le <select> synchronisé (utilisé par le reste du code pour lire le choix)
  sel.innerHTML='<option value="0">— aucun —</option>'+matches.map(c=>`<option value="${c.id}" ${String(c.id)===cur?'selected':''}>${esc(c.nom)}${c.tel?' · '+esc(c.tel):''}</option>`).join('');
  // 2) affiche une liste VISIBLE et cliquable sous le champ (ergonomie : pas besoin de dérouler)
  const box=document.getElementById('f_clResults');
  if(box){
    if(!term){ box.style.display='none'; box.innerHTML=''; }
    else if(!matches.length){
      box.style.display='block';
      box.innerHTML=`<div style="padding:10px 12px;color:#9a8a82;font-size:.85rem">Aucun client trouvé — utilisez « + Nouveau client ».</div>`;
    } else {
      box.style.display='block';
      box.innerHTML=matches.slice(0,40).map(c=>
        `<div onclick="pickCmdClient(${c.id})" style="padding:10px 12px;border-bottom:1px solid var(--hair);cursor:pointer;font-size:.9rem">
          <b>${esc(c.nom)}</b>${c.tel?`<span style="color:#9a8a82"> · ${esc(c.tel)}</span>`:''}</div>`
      ).join('');
    }
  }
  // si un seul résultat, le présélectionner pour gagner un clic
  if(matches.length===1){ sel.value=String(matches[0].id); cmdSuggestClientAddress(); }
}
// Sélectionne un client depuis la liste de résultats visible.
function pickCmdClient(id){
  const sel=document.getElementById('f_cl'); if(sel){ sel.value=String(id); }
  const cl=(cmdClientsCache||[]).find(c=>c.id===id);
  const search=document.getElementById('f_clsearch'); if(search&&cl){ search.value=cl.nom||''; }
  const box=document.getElementById('f_clResults'); if(box){ box.style.display='none'; box.innerHTML=''; }
  cmdSuggestClientAddress();
}

// Quand un client est choisi, propose son adresse comme lieu de livraison —
// uniquement si le champ lieu est encore vide (ne jamais écraser une saisie manuelle).
function toggleLivBlock(){
  const body=document.getElementById('livBody'), arrow=document.getElementById('livArrow');
  if(!body) return;
  const open = body.style.display==='none';
  body.style.display = open ? 'block' : 'none';
  if(arrow) arrow.textContent = open ? '▾' : '▸';
}
function cmdSuggestClientAddress(){
  const sel=document.getElementById('f_cl'); const lieu=document.getElementById('f_lieu');
  if(!sel || !lieu) return;
  if((lieu.value||'').trim()) return; // l'utilisateur a déjà renseigné un lieu
  const cid=+sel.value||0; if(!cid) return;
  const cl=(cmdClientsCache||[]).find(c=>c.id===cid);
  if(cl && (cl.adresse||'').trim()){
    lieu.value=cl.adresse.trim();
    // ouvrir le bloc livraison s'il est replié, pour montrer l'adresse pré-remplie
    const body=document.getElementById('livBody');
    if(body && body.style.display==='none') toggleLivBlock();
  }
  // [v1382] Le client est connu : ses livraisons passées peuvent donner le trajet, même si
  // l'adresse ne correspond à rien du carnet. C'est le cas courant que l'ancien code ratait.
  if(typeof cmdTrajetPropose==='function') cmdTrajetPropose();
}

// Anti-rebond de la frappe : la proposition relit les commandes, inutile à chaque touche.
let _trajetPropoTimer=null;
function cmdTrajetProposeDiff(){
  clearTimeout(_trajetPropoTimer);
  _trajetPropoTimer=setTimeout(()=>{ if(typeof cmdTrajetPropose==='function') cmdTrajetPropose(); }, 350);
}

// Ajout rapide d'un client SANS quitter la commande (popup → retour avec client sélectionné)
let _quickClientReturnId = 0;
function quickClient(orderId){
  _quickClientReturnId = orderId||0;
  openModal(`<h3>Nouveau client</h3>
    <p class="note">Saisie rapide. Vous pourrez compléter la fiche plus tard depuis l'onglet Clients.</p>
    <div class="field"><label>Nom / Entreprise *</label><input id="qc_nom" placeholder="ex : Marie Dupont"></div>
    <div class="field"><label>Téléphone *</label><input id="qc_tel" type="tel" inputmode="tel" placeholder="ex : 06 12 34 56 78"></div>
    <div class="field"><label>Type</label><select id="qc_type"><option>Particulier</option><option>Pro</option></select></div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="cmdForm(${orderId||0},{keepLines:true})">Annuler</button>
      <button class="btn" onclick="saveQuickClient()">Ajouter et sélectionner</button>
    </div>`);
  setTimeout(()=>{const n=document.getElementById('qc_nom'); if(n)n.focus();},100);
}
async function saveQuickClient(){
  const nom=(val('qc_nom')||'').trim();
  const tel=(val('qc_tel')||'').trim();
  const type=val('qc_type')||'Particulier';
  if(!nom){ toast('Le nom est requis'); return; }
  if(!tel){ toast('Le téléphone est requis'); return; }
  // Anti-doublon : même nom + même téléphone (chiffres) → on réutilise, on ne crée pas
  const digits=s=>(s||'').replace(/[^0-9]/g,'');
  const existing=(await db.clients.toArray()).find(c=>
    (c.nom||'').trim().toLowerCase()===nom.toLowerCase() && digits(c.tel)===digits(tel));
  let cid;
  if(existing){
    cid=existing.id;
    toast('Client déjà existant — sélectionné');
  } else {
    cid=await db.clients.add(withSync({nom, tel, type, email:'', adresse:'', notes:''},'app'));
    toast('Client ajouté ✓');
  }
  // rouvrir la commande en préservant les lignes et en sélectionnant le client
  await cmdForm(_quickClientReturnId, {clientId:cid, keepLines:true});
}

function addLine(type){
  if(type==='coffret') cmdLines.push({type:'coffret', taille:6, parfums:{}});
  else if(type==='evenement') cmdLines.push({type:'evenement', evQte:EVENT_MIN, equip:0, evFiltrePyr:0, parfums:{}});
  else if(type==='grand') cmdLines.push({type:'grand', tarif:'particulier', items:{}});
  else if(type==='vrac') cmdLines.push({type:'vrac', parfums:{}});
  else if(type==='sachet') cmdLines.push({type:'sachet', parfums:{}});
  else if(type==='don') cmdLines.push({type:'don', parfums:{}, items:{}});
  else if(type==='prestation') cmdLines.push({type:'prestation', libelle:'', montantHT:0, remiseType:'pct', remisePct:0, remiseEuro:0});
  drawLines();
}
function removeLine(i){ cmdLines.splice(i,1); drawLines(); }

function drawLines(){
  const wrap=document.getElementById('linesWrap'); if(!wrap)return;
  if(!cmdLines.length){ wrap.innerHTML='<p class="note">Ajoute au moins un produit ci-dessous (coffret, sachet, événement, grand format, prestation ou don).</p>'; cmdRecalc(); return; }
  wrap.innerHTML = cmdLines.map((ln,i)=>{
    if(ln.type==='coffret') return drawCoffretLine(ln,i);
    if(ln.type==='evenement') return drawEventLine(ln,i);
    if(ln.type==='grand') return drawBigLine(ln,i);
    if(ln.type==='vrac') return drawVracLine(ln,i);
    if(ln.type==='sachet') return drawSachetLine(ln,i);
    if(ln.type==='don') return drawDonLine(ln,i);
    if(ln.type==='prestation') return drawPrestationLine(ln,i);
    return '';
  }).join('');
  cmdRecalc();
}

function drawCoffretLine(ln,i){
  const boxOpts = cmdProductsCache.map(p=>`<option value="${p.taille}" data-prix="${p.prix}" ${(+ln.taille===+p.taille)?'selected':''}>${esc(p.nom)} — ${euro(p.prix)}</option>`).join('');
  const limit = BOX_FLAVOR_LIMIT[ln.taille]||0;
  // sélecteur de quantité 0..taille pour chaque parfum
  const flavRows = FLAVORS.map((f,fi)=>{
    const q=ln.parfums[f]||0;
    const maxq = ln.taille||25;
    return flavorPickRow(f, q, `setCoffretParfum(${i},${fi},VAL)`, maxq);
  }).join('');
  // [v1188 — FIX parfum fantôme] La génération de compo écrit dans ln.parfums des noms issus des RECETTES
  // / preps R&D (ex. « Macaron caramel »), qui ne sont pas toujours dans FLAVORS. La grille n'itérant que
  // sur FLAVORS, ces parfums devenaient INVISIBLES mais restaient comptés dans totQ → un « 1/6 » fantôme
  // impossible à décocher. On rend donc une ligne pour TOUT parfum présent dans ln.parfums hors FLAVORS,
  // avec un setter PAR NOM (supprimable). L'affichage redevient fidèle à la donnée réelle.
  const horsCatalogue = Object.keys(ln.parfums).filter(nom => (+ln.parfums[nom]||0) > 0 && !FLAVORS.includes(nom));
  const extraRows = horsCatalogue.map(nom => {
    const q = +ln.parfums[nom]||0;
    const maxq = ln.taille||25;
    // setter par nom (encodage pour survivre à l'interpolation onclick)
    const enc = escJs(encodeURIComponent(nom));
    return flavorPickRow(nom, q, `setCoffretParfumNom(${i},'${enc}',VAL)`, maxq);
  }).join('');
  const nbDiff = Object.values(ln.parfums).filter(q=>q>0).length;
  const sansParfum = +ln.sansParfum||0;
  const totQ = Object.values(ln.parfums).reduce((s,q)=>s+(+q||0),0) + sansParfum;
  const cap = +ln.taille||25;
  const over = Math.max(0, nbDiff-limit);
  // Compteur de remplissage coloré : vert si pile, rouge si dépasse, neutre si en dessous.
  const rempliCol = totQ===cap ? '#2e7d32' : (totQ>cap ? '#b3261e' : '#7a6a62');
  const rempliTxt = totQ>cap ? `${totQ}/${cap} — dépasse de ${totQ-cap} !` : `${totQ}/${cap}`;
  // Case « sans parfum déterminé », intégrée dans la grille au même style qu'un parfum.
  const spOn = sansParfum>0;
  let spOpts=''; for(let n=1;n<=cap;n++) spOpts+=`<option value="${n}" ${sansParfum===n?'selected':''}>${n}</option>`;
  const sansParfumRow = `<div onclick="setCoffretSansParfum(${i}, ${spOn?0:1})"
      style="display:flex;align-items:center;gap:12px;padding:12px 14px;margin:4px 0;cursor:pointer;
      border:1px solid var(--hair);border-radius:12px;
      background:${spOn?'#f0ece4':'#fbf8f3'};${spOn?'border-color:#cdbfa8':''}">
    <span style="width:22px;height:22px;border-radius:50%;background:repeating-linear-gradient(45deg,#cbb,#cbb 3px,#ddd 3px,#ddd 6px);flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.06);${spOn?'outline:2px solid #8a7a62;outline-offset:1px':''}"></span>
    <span style="flex:1;font-size:1rem;color:${spOn?'var(--bordeaux)':'#6a5a52'};font-weight:${spOn?'600':'400'}">Sans parfum déterminé <span style="font-size:.72rem;color:#9a8a82;font-weight:400">— à définir plus tard</span></span>
    ${spOn
      ? `<select onclick="event.stopPropagation()" onchange="setCoffretSansParfum(${i},+this.value)" style="font-size:1rem;padding:4px 8px">${spOpts}</select>`
      : `<span style="color:#9a8a82;font-size:.9rem">+ ajouter</span>`}
  </div>`;
  return `<div class="cmd-line">
    <div class="line-head"><span class="line-type">Coffret <span class="line-sub">jusqu'à ${limit} parfum(s) inclus</span></span><span class="line-del" onclick="removeLine(${i})">✕ retirer</span></div>
    <div class="field"><label>Taille</label><select onchange="setCoffretTaille(${i},this.value)">${boxOpts}</select></div>
    ${(()=>{
      const mode = ln.embMode || 'standard';
      const embOpts = cmdEmballagesCache.map(m=>`<option value="${m.id}" ${(+ln.embMatId===+m.id)?'selected':''}>${esc(m.nom)}${m.capacite?` (${m.capacite} mac.)`:''}</option>`).join('');
      return `<div class="field"><label>Emballage <span style="color:#9a8a82;font-weight:400">— ajuste le coût</span></label>
        <select onchange="setCoffretEmbMode(${i},this.value)">
          <option value="standard" ${mode==='standard'?'selected':''}>Standard (selon la taille)</option>
          <option value="reutilisable" ${mode==='reutilisable'?'selected':''}>Réutilisable (0 € — le client rapporte sa boîte)</option>
          <option value="autre" ${mode==='autre'?'selected':''}>Autre emballage (choisir dans ma liste)</option>
        </select>
        ${mode==='autre'?`<select style="margin-top:6px" onchange="setCoffretEmbMat(${i},this.value)">
          <option value="">— choisir un emballage —</option>${embOpts}
        </select>${!cmdEmballagesCache.length?'<p class="note" style="color:var(--red)">Aucun emballage créé. Ajoute-en dans Stock → Matières (catégorie emballage).</p>':''}`:''}
      </div>`;
    })()}
    <div style="margin:8px 0 6px"><button class="btn gold sm" onclick="proposerCompositionLigne(${i})" style="font-size:.84rem;width:100%">💡 Proposer une composition selon mes stocks</button></div>
    <label style="font-size:.78rem;color:#7a6a62">Parfums (quantité par parfum)</label>
    <div class="flav-grid">${flavRows}${extraRows}${sansParfumRow}</div>
    ${sansParfum>0 ? `<p class="note" style="margin:6px 0 2px;color:#9a7d3a">🎯 Les ${sansParfum} macaron${sansParfum>1?'s':''} sans parfum seront à déterminer au démarrage de la production — l'app te le proposera au bon moment, avec le stock réel de ce jour-là.</p>
    ${cmdSpModeBlock(ln,i)}` : ''}
    <div class="sum-box" style="border:2px solid ${rempliCol};background:${totQ===cap?'#eef6ee':(totQ>cap?'#fdf2f1':'#fbf8f3')}">
      <span>${nbDiff} parfum(s)${sansParfum?` + ${sansParfum} sans parfum`:''}</span>
      <b style="color:${rempliCol};font-size:1.1rem">${rempliTxt}${totQ===cap?' ✓':''}</b></div>
    ${over?`<p class="note">${over} parfum(s) au-delà de l'inclus → +${euro(over*FLAVOR_SURCHARGE)}</p>`:''}
    ${lineRemiseRow(ln,i)}
  </div>`;
}
function setCoffretSansParfum(i,v){ const q=Math.max(0,+v||0); if(q>0) cmdLines[i].sansParfum=q; else delete cmdLines[i].sansParfum; drawLines(); }
// [PARFUMS NON SPÉCIFIÉS — LIBELLÉ DOCUMENT] Quand une ligne a des macarons « sans parfum »,
// on choisit comment ils apparaissent sur le devis/facture : « Assortiment » (nb de parfums
// optionnel) OU « Parfum(s) à déterminer ». Modes exclusifs. spMode: 'assortiment' | 'adeterminer'.
// N'affecte PAS la production (toujours sansParfum macarons à définir), seulement l'affichage.
function cmdSpModeBlock(ln,i){
  const mode = ln.spMode || 'assortiment';
  const nb = +ln.spNbParfums||0;
  const opt = (val,lbl)=>`<label style="display:inline-flex;align-items:center;gap:6px;margin-right:14px;cursor:pointer;font-size:.86rem;color:#6a5a52">
    <input type="radio" name="spMode_${i}" value="${val}" ${mode===val?'checked':''} onchange="setSpMode(${i},'${val}')"> ${lbl}</label>`;
  let nbField='';
  if(mode==='assortiment'){
    nbField = `<div class="field" style="margin:6px 0 0"><label style="font-weight:400;color:#7a6a60">Nombre de parfums de l'assortiment <span style="color:#9a8a82">— facultatif ; 1 = « 1 parfum » (pas un assortiment)</span></label>
      <input type="number" min="0" step="1" value="${nb>0?nb:''}" placeholder="ex : 4" oninput="setSpNbParfums(${i},this.value)" style="max-width:140px"></div>`;
  }
  return `<div style="margin:4px 0 2px;padding:8px 10px;background:#faf7f1;border:1px solid var(--hair);border-radius:10px">
    <div style="font-size:.78rem;color:#7a6a62;margin-bottom:4px">Affichage sur le devis / la facture :</div>
    ${opt('assortiment','Assortiment')}${opt('adeterminer','Parfum(s) à déterminer')}
    ${nbField}
  </div>`;
}
function setSpMode(i,v){ if(!cmdLines[i]) return; cmdLines[i].spMode = (v==='adeterminer')?'adeterminer':'assortiment'; if(v==='adeterminer') delete cmdLines[i].spNbParfums; drawLines(); }
function setSpNbParfums(i,v){ if(!cmdLines[i]) return; const n=Math.max(0,Math.round(+v||0)); if(n>0) cmdLines[i].spNbParfums=n; else delete cmdLines[i].spNbParfums; }
function setCoffretTaille(i,v){ cmdLines[i].taille=+v;
  cmdLines[i].prixUnitaireApplique=null; // taille changée → re-tarifer au prix courant du catalogue
  // [v1452] Ben : « L'emballage par défaut est la boîte blanche de 8/10 macarons. Assure toi de
  // rendre les autres emballages selectionnables aussi telle que c'est déjà le cas aujourd'hui. »
  // On pré-sélectionne donc « Autre emballage » + la boîte blanche pour le format 10 — un DÉFAUT,
  // pas un verrou : les 3 modes (standard / réutilisable / autre) et toute la liste d'emballages
  // restent disponibles exactement comme avant. Ne s'applique qu'au CHANGEMENT de taille : rouvrir
  // une commande déjà enregistrée conserve le choix qui y avait été fait (_lineToEdit).
  if(+v===COFFRET10_TAILLE){
    const emb = (cmdEmballagesCache||[]).find(m =>
      (m.nom||'').trim().toLowerCase()===COFFRET10_EMB_NOM.toLowerCase());
    if(emb){ cmdLines[i].embMode='autre'; cmdLines[i].embMatId=+emb.id; }
  }
  // purge les parfums au-delà de la nouvelle taille
  const max=+v; Object.keys(cmdLines[i].parfums).forEach(k=>{ if(cmdLines[i].parfums[k]>max) cmdLines[i].parfums[k]=max; }); drawLines(); }
function setCoffretParfum(i,fi,v){ const f=FLAVORS[fi]; const q=+v||0; if(q>0)cmdLines[i].parfums[f]=q; else delete cmdLines[i].parfums[f]; drawLines(); }
// [v1188] Setter PAR NOM : pour les parfums hors FLAVORS (issus d'une génération : noms de recettes/preps).
// Même logique que setCoffretParfum mais indexé par nom exact, ce qui permet de les modifier ET de les
// retirer (q=0 → delete), corrigeant le « parfum fantôme » non supprimable.
function setCoffretParfumNom(i, encNom, v){
  if(!cmdLines[i] || !cmdLines[i].parfums) return;
  let nom; try{ nom = decodeURIComponent(encNom); }catch(_){ nom = encNom; }
  const q=+v||0;
  if(q>0) cmdLines[i].parfums[nom]=q; else delete cmdLines[i].parfums[nom];
  drawLines();
}
function setCoffretEmbMode(i,v){ cmdLines[i].embMode=v; if(v!=='autre') cmdLines[i].embMatId=null; drawLines(); }
function setCoffretEmbMat(i,v){ cmdLines[i].embMatId = v?+v:null; drawLines(); }

// [SUGGESTION PARFUMS — UI] Point d'entrée historique conservé pour compatibilité. Depuis v1182,
// il REDIRIGE vers le moteur unifié (proposerCompositionLigne → genererCompositionsCoffret), qui
// intègre stock + surplus mutualisable + relance faisable avec toutes les dépendances temporelles.
// L'ancien corps (moteur A : stock dormant + catalogue au plus rentable, SANS dépendances de temps)
// est déprécié et sera retiré une fois le moteur B validé en conditions réelles.
async function suggererParfumsLigne(i){
  const ln = cmdLines[i]; if(!ln) return;
  // Redirection vers le moteur unifié.
  if(typeof proposerCompositionLigne==='function'){ return proposerCompositionLigne(i); }
  // — repli historique (moteur A) ci-dessous, atteint seulement si B indisponible —
  const sansParfum = +ln.sansParfum||0;
  if(sansParfum<=0) return;
  const taille = +ln.taille||25;
  const parfumsPresents = Object.keys(ln.parfums||{}).filter(k=> (+ln.parfums[k]||0)>0);
  const dateLiv = (typeof val==='function' ? val('f_dateEvenement') : '') || '';
  openModal(`<h3>🎯 Suggestion de parfums</h3><div style="padding:14px;text-align:center;color:#9a8576">⏳ Analyse du stock et des coûts…</div>`);
  try{
    const res = await suggererParfumsCommande(sansParfum, taille, parfumsPresents, dateLiv, {paliers:true, parfumsAutorises:FLAVORS});
    if(!res || !res.ok || !res.repartition.length){
      openModal(`<h3>🎯 Suggestion de parfums</h3>
        <div class="banner" style="background:#fdf8e9;border-color:#e8d09a">📋 <div>${esc((res&&res.note)||'Aucune suggestion possible (ni stock dormant, ni recette disponible).')}</div></div>
        <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
      return;
    }
    // Regroupe par source pour l'affichage.
    const stockRows = res.repartition.filter(r=>r.source==='stock');
    const prodRows  = res.repartition.filter(r=>r.source==='production');
    const bloc = (titre, rows, col, ico) => rows.length ? `
      <div style="margin-top:8px">
        <div style="font-size:.78rem;font-weight:700;color:${col};margin-bottom:3px">${ico} ${titre}</div>
        ${rows.map(r=>`<div style="display:flex;justify-content:space-between;font-size:.86rem;padding:2px 0">
          <span style="text-transform:capitalize">${esc(r.nom)}</span><b>${r.qte} mac</b></div>`).join('')}
      </div>` : '';
    const payload = escJs(encodeURIComponent(JSON.stringify(res.repartition)));
    openModal(`<h3>🎯 Suggestion de parfums</h3>
      <p class="note" style="margin-bottom:6px">Pour les <b>${sansParfum}</b> macaron${sansParfum>1?'s':''} sans parfum de ce coffret (plafond ${res.plafond} parfums).</p>
      ${bloc('Puisé dans ton stock dormant', stockRows, '#3f7d52', '📦')}
      ${bloc('À produire (au plus rentable)', prodRows, '#c97a2a', '🏭')}
      ${res.reste>0?`<p class="note" style="color:var(--red);margin-top:6px">${esc(res.note)}</p>`:''}
      <div class="modal-actions">
        <button class="btn ghost" style="margin-right:auto" onclick="closeModal()">Annuler</button>
        <button class="btn gold" onclick="appliquerSuggestionParfums(${i},'${payload}')">Appliquer</button>
      </div>`);
  }catch(e){
    console.error('suggererParfumsLigne', e);
    openModal(`<h3>🎯 Suggestion de parfums</h3>
      <div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⛔ <div>Erreur pendant l'analyse.</div></div>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
  }
}

// Applique la répartition suggérée : ajoute les parfums à la ligne et consomme le « sans parfum ».
function appliquerSuggestionParfums(i, payload){
  const ln = cmdLines[i]; if(!ln) return;
  let rep; try{ rep = JSON.parse(decodeURIComponent(payload)); }catch(e){ rep = []; }
  if(!Array.isArray(rep) || !rep.length){ closeModal(); return; }
  ln.parfums = ln.parfums || {};
  let totalApplique = 0;
  rep.forEach(r=>{
    const nom = r.nom, q = Math.max(0, +r.qte||0);
    if(!nom || q<=0) return;
    ln.parfums[nom] = (+ln.parfums[nom]||0) + q;   // cumule si le parfum existait déjà
    totalApplique += q;
  });
  // Consomme le « sans parfum » à hauteur de ce qui a été attribué (le reste éventuel demeure).
  const reste = Math.max(0, (+ln.sansParfum||0) - totalApplique);
  if(reste>0) ln.sansParfum = reste; else delete ln.sansParfum;
  closeModal();
  drawLines();
}

// ═══════════════════════════════════════════════════════════════════════════
// COMPOSITIONS ALTERNATIVES DE COFFRET — UI (modale)
// Déclenchée par le bouton « 💡 Proposer une composition » d'une ligne coffret,
// et proposable automatiquement quand le verdict de faisabilité est 🔴/🟡.
// S'appuie sur le moteur pur genererCompositionsCoffret (3 sources classées).
// Réutilise la mécanique éprouvée de suggererParfumsLigne (openModal → Appliquer).
// ═══════════════════════════════════════════════════════════════════════════
let _compoModeCourant = 'flexible';   // mémorise le dernier mode choisi (strict/flexible)
let _compoParfumsEnPlus = 0;          // mode STRICT : nb de parfums choisis EN PLUS de la règle (chacun +3 €)
// [v1191] Parfums VALIDÉS (verrouillés) par ligne : { [i]: { nomParfum: qte } }. Conservés d'une
// suggestion à l'autre : « Nouvelle suggestion » recompose UNIQUEMENT les parfums non validés.
let _compoValides = {};
// [v1191] Compteur d'itérations par ligne → fait varier les propositions à chaque « Nouvelle suggestion »
// (rotation des candidats de même facilité, sans jamais dégrader la priorité stock).
let _compoSeed = {};

async function proposerCompositionLigne(i, mode, parfumsEnPlus){
  const ln = cmdLines[i]; if(!ln || ln.type!=='coffret') return;
  // [v1191] Changer de mode remet la variation à zéro (on repart sur la proposition la plus simple).
  if(mode && mode!==_compoModeCourant){ _compoSeed[i] = 0; }
  if(mode) _compoModeCourant = (mode==='strict'?'strict':'flexible');
  // Le nb de parfums en plus n'a de sens qu'en STRICT ; on le réinitialise en basculant sur Flexible.
  if(mode==='flexible') _compoParfumsEnPlus = 0;
  if(parfumsEnPlus!=null) _compoParfumsEnPlus = Math.max(0, +parfumsEnPlus||0);
  const taille = +ln.taille||6;
  const dateLiv = (typeof val==='function' ? (val('f_date')||'') : '') || '';
  const heureLiv = (typeof val==='function' ? (val('f_heure')||'') : '') || '';
  // Parfums souhaités = ceux déjà saisis sur la ligne (base du mode STRICT).
  const parfumsSouhaites = Object.keys(ln.parfums||{})
    .filter(k=>(+ln.parfums[k]||0)>0)
    .map(k=>({nom:k, qte:+ln.parfums[k]}));

  openModal(`<h3>💡 Compositions alternatives</h3>
    <div style="padding:14px;text-align:center;color:#9a8576">⏳ Analyse du stock, des batchs à venir et de la production faisable…</div>`);

  try{
    // [v1191] Parfums VALIDÉS pour cette ligne → imposés au moteur ; seed → variation « nouvelle suggestion ».
    const imposes = Object.entries(_compoValides[i]||{})
      .filter(([n,q])=>(+q||0)>0).map(([n,q])=>({nom:n, qte:+q}));
    const seed = +_compoSeed[i]||0;
    const res = await genererCompositionsCoffret(taille, dateLiv, heureLiv,
      {mode:_compoModeCourant, parfumsSouhaites, parfumsEnPlus: _compoModeCourant==='strict' ? _compoParfumsEnPlus : 0, imposes, seed,
       typeFiltre:'standard'});   // [v1192] un COFFRET n'accueille QUE des macarons standard : jamais de grands formats.
    _renderCompositionsModale(i, res, taille, dateLiv);
  }catch(e){
    console.error('proposerCompositionLigne', e);
    openModal(`<h3>💡 Compositions alternatives</h3>
      <div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⛔ <div>Erreur pendant l'analyse des compositions.</div></div>
      <div class="modal-actions"><button class="btn ghost" onclick="fermerCompositionModale()">Fermer</button></div>`);
  }
}

// [v1206] RENTABILITÉ D'UNE COMPOSITION PROPOSÉE.
// À prix de coffret égal, deux compositions n'ont pas le même coût de revient (parfums plus ou
// moins coûteux / longs à produire). On calcule ici, avec le MÊME moteur central que la fiche
// commande (computeOrderMargins) et les MÊMES caches synchrones (_cmdMarginCache), le coût de
// revient et la marge de la composition — pour éclairer le choix. Aucun chargement Dexie : la
// modale s'ouvre depuis le formulaire commande, où ces caches sont déjà remplis.
// Retourne null si le calcul n'est pas fiable (caches absents), pour ne rien afficher de faux.
function _compoRentabilite(taille, lignesCompo){
  try{
    const c = (typeof _cmdMarginCache!=='undefined') ? _cmdMarginCache : null;
    if(!c || !Array.isArray(c.recipes)) return null;
    // Mapping nom → libellé catalogue, IDENTIQUE à appliquerCompositionCoffret (cohérence coût).
    const _kf = x => (typeof aiNormalize==='function') ? aiNormalize(x) : String(x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
    const _flavByKey = {}; (typeof FLAVORS!=='undefined'?FLAVORS:[]).forEach(f=>{ _flavByKey[_kf(f)] = f; });
    // computeOrderMargins/_coutReelParfums attendent parfums sous forme de TABLEAU [{nom, qte}]
    // (il fait .forEach). On agrège d'abord par nom canonique, puis on émet le tableau.
    const agg = {};
    (lignesCompo||[]).forEach(l=>{
      const q=Math.max(0,+l.qte||0); if(!l.nom||q<=0) return;
      const canon = _flavByKey[_kf(l.nom)] || l.nom;
      agg[canon] = (+agg[canon]||0) + q;
    });
    const parfums = Object.entries(agg).map(([nom,qte])=>({nom, qte}));
    // Ligne coffret draft au format attendu par le moteur (parfums = tableau).
    const lnDraft = { type:'coffret', taille:+taille||0, parfums };
    const prix = (typeof coffretUnitPrice==='function') ? coffretUnitPrice(lnDraft) : 0;
    // prixUnitaireApplique : évite que lineTotalStored/coffretUnitPrice reparte sur un autre tarif.
    lnDraft.prixUnitaireApplique = prix;
    const o = { lignes:[lnDraft], montant:prix };
    const m = computeOrderMargins(o, c.recipes||[], c.recipeItems||[], c.lots||[]);
    const coutRevient = money2(m.coutMat + m.coutEmb);
    return { coutRevient, prix:m.ca, margeNette:m.margeNette, tauxNet:m.tauxNet,
             nonResolus:m.piecesNonResolues||0 };
  }catch(e){ console.error('_compoRentabilite', e); return null; }
}

// Rendu de la modale à partir du résultat du moteur. Séparé pour pouvoir re-render au switch de mode
// sans relancer une analyse (le moteur est rapide, mais on garde la logique claire).
function _renderCompositionsModale(i, res, taille, dateLiv){
  const props = (res && res.propositions) || [];
  const fallback = (res && res.fallback) || [];
  const mode = (res && res.meta && res.meta.mode) || _compoModeCourant;

  // Toggle Strict / Flexible.
  const toggle = `<div style="display:inline-flex;border:1px solid var(--hair);border-radius:999px;overflow:hidden;font-size:.8rem">
    ${['flexible','strict'].map(m=>`<span onclick="proposerCompositionLigne(${i},'${m}')"
      style="padding:5px 13px;cursor:pointer;${mode===m?'background:var(--bordeaux,#52252F);color:#fff;font-weight:600':'color:#7a6a62'}">
      ${m==='flexible'?'Flexible':'Strict'}</span>`).join('')}
  </div>`;

  // Rendu d'une proposition : titre selon le coût, ventilation par source, bouton Appliquer.
  const carteProp = (p, rang) => {
    const v = p.ventilation;
    // Libellé de niveau selon la source la plus coûteuse mobilisée.
    const niveau = p.cout===0 ? {ico:'✅', txt:'Le plus simple — 100 % disponible maintenant', col:'#3f7d52'}
                 : p.cout===1 ? {ico:'♻️', txt:'Disponible via tes batchs déjà prévus', col:'#c97a2a'}
                 : {ico:'🔧', txt:'Complet avec une relance de production', col:'#8a6d3b'};
    // Ventilation lisible : « 6 en stock · 3 mutualisés · 3 à produire ».
    const bouts = [];
    if(v.stock>0)     bouts.push(`<b>${v.stock}</b> en stock`);
    if(v.mutualise>0) bouts.push(`<b>${v.mutualise}</b> mutualisé${v.mutualise>1?'s':''} (batch déjà prévu)`);
    if(v.relance>0)   bouts.push(`<b>${v.relance}</b> à produire (faisable pour ta date)`);
    const ventil = bouts.join(' · ');
    // [v1191] Détail des parfums : chaque parfum reçoit un SYMBOLE clair de facilité + un bouton « valider ».
    //   🟢 en stock (rien à faire) · ♻️ mutualisé (batch déjà prévu) · 🔺 à produire (course en cuisine).
    // Le symbole reflète la source DOMINANTE de la ligne (relance > mutualisé > stock).
    const detailParfums = p.lignes.map(l=>{
      const estRelance = l.relance>0;
      const estMut = !estRelance && l.mutualise>0;
      const sym = estRelance ? '🔺' : estMut ? '♻️' : '🟢';
      const symTitle = estRelance ? 'À produire (repos ganache à prévoir)' : estMut ? 'Disponible via un batch déjà prévu' : 'En stock — disponible immédiatement';
      const bg = estRelance ? '#fdf6ec' : estMut ? '#fbf3ea' : '#eef6ee';
      const bd = estRelance ? '#e8cfa3' : estMut ? '#e3c8a8' : '#bcd9c6';
      const dejaValide = !!((_compoValides[i]||{})[l.nom]);
      // [FIX v1329] LES DEUX COUCHES, ET DANS CET ORDRE.
      // encodeURIComponent est l'encodage de TRANSPORT : la fonction réceptrice fait un
      // decodeURIComponent. Le retirer casserait l'aller-retour (« Chocolat 70% » → URIError).
      // Mais il N'ENCODE PAS L'APOSTROPHE :
      //     encodeURIComponent("Fleur d'oranger") → "Fleur%20d'oranger"   ← elle survit !
      // …et c'est elle qui ferme la chaîne JS du onclick. Le bouton « valider » était donc mort
      // sur tout parfum apostrophé. En pâtisserie française, c'est la norme, pas l'exception.
      // Il faut DONC les deux : transport (encodeURIComponent) PUIS chaîne JS (escJs).
      const encNom = escJs(encodeURIComponent(l.nom));
      const valBtn = dejaValide
        ? `<span title="Parfum validé — conservé à la prochaine suggestion" style="color:#3f7d52;font-weight:700;font-size:.8rem">✓ validé</span>`
        : `<span onclick="compoValiderParfum(${i},'${encNom}',${l.qte})" title="Valider ce parfum : il sera conservé quand tu régénères" style="cursor:pointer;color:var(--bordeaux,#52252F);font-size:.72rem;font-weight:600;border:1px solid var(--hair);border-radius:6px;padding:1px 6px;margin-left:4px">＋ valider</span>`;
      return `<span style="display:inline-flex;align-items:center;background:${bg};border:1px solid ${bd};border-radius:8px;padding:2px 6px 2px 8px;margin:2px 3px 0 0;font-size:.84rem">
        <span title="${symTitle}" style="margin-right:4px">${sym}</span><span style="text-transform:capitalize">${esc(l.nom)} ×${l.qte}</span>${valBtn}</span>`;
    }).join('');
    const etat = p.complet
      ? `<span style="color:#3f7d52;font-weight:600">Coffret ${p.taille} complet</span>`
      : `<span style="color:#c97a2a;font-weight:600">${p.total}/${p.taille} — il manque ${p.manque}</span>`;
    const payload = escJs(encodeURIComponent(JSON.stringify({taille:p.taille, lignes:p.lignes})));
    // [v1206] Rentabilité de CETTE composition (même moteur que la fiche commande). À prix de coffret
    // égal, une composition de parfums coûteux/longs rapporte moins — ce bandeau aide à choisir.
    let rentaBloc = '';
    const _r = (typeof _compoRentabilite==='function') ? _compoRentabilite(p.taille, p.lignes) : null;
    if(_r){
      const _ps = (typeof profitScale==='function') ? profitScale(_r.tauxNet) : {col:'#7a6a62', label:''};
      const _dot = _r.tauxNet>=30 ? '🟢' : (_r.tauxNet>=15 ? '🟡' : '🔴');
      rentaBloc = `<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;background:#faf7f1;border:1px solid #ece0cf;border-radius:9px;padding:6px 10px;margin:2px 0 8px;font-size:.82rem">
        <span style="color:#8a7a72">Revient <b style="color:var(--bordeaux,#52252F)">${euro(_r.coutRevient)}</b></span>
        <span style="color:#cbb9ac">·</span>
        <span style="color:#8a7a72">Marge <b style="color:${_ps.col}">${euro(_r.margeNette)}</b> <span style="color:${_ps.col}">(${_dot} ${_r.tauxNet}%)</span></span>
      </div>`;
    }
    return `<div style="border:1px solid var(--hair);border-radius:12px;padding:11px 13px;margin:9px 0;background:#fff">
      <div style="font-size:.8rem;font-weight:700;color:${niveau.col};margin-bottom:4px">${niveau.ico} ${niveau.txt}</div>
      <div style="margin-bottom:6px">${etat}</div>
      <div style="margin-bottom:6px">${detailParfums}</div>
      ${ventil?`<div style="font-size:.8rem;color:#7a6a62;margin-bottom:8px">↳ ${ventil}</div>`:''}
      ${rentaBloc}
      <button class="btn ${p.complet?'gold':'ghost'} sm" onclick="appliquerCompositionCoffret(${i},'${payload}')">
        ${p.complet?'Utiliser cette composition':'Utiliser (coffret partiel)'}</button>
    </div>`;
  };

  // [v1191] Bandeau des parfums VALIDÉS (verrouillés) : rappel visuel + retrait individuel.
  const valides = Object.entries(_compoValides[i]||{}).filter(([n,q])=>(+q||0)>0);
  let validesBloc = '';
  if(valides.length){
    const puces = valides.map(([n,q])=>{
      const enc = escJs(encodeURIComponent(n));
      return `<span style="display:inline-flex;align-items:center;background:#eef6ee;border:1px solid #bcd9c6;border-radius:8px;padding:2px 4px 2px 8px;margin:2px 3px 0 0;font-size:.84rem">
        <span style="color:#3f7d52;margin-right:3px">✓</span><span style="text-transform:capitalize">${esc(n)} ×${q}</span>
        <span onclick="compoDevaliderParfum(${i},'${enc}')" title="Retirer ce parfum des validés" style="cursor:pointer;color:#b3261e;font-weight:700;margin-left:6px;padding:0 3px">✕</span></span>`;
    }).join('');
    validesBloc = `<div style="background:#f3f8f3;border:1px solid #cfe6d5;border-radius:11px;padding:8px 10px;margin:2px 0 8px">
      <div style="font-size:.78rem;color:#3f7d52;font-weight:600;margin-bottom:4px">🔒 Parfums validés — conservés à chaque nouvelle suggestion</div>
      <div>${puces}</div>
    </div>`;
  }
  // [v1191] Bouton « Nouvelle suggestion » : incrémente le seed → recompose en gardant les validés,
  // et propose d'autres parfums pour le reste. Légende des symboles pour lecture en un coup d'œil.
  const legende = `<div style="font-size:.72rem;color:#8a7a6e;margin:2px 0 6px">🟢 en stock · ♻️ batch déjà prévu · 🔺 à produire</div>`;
  const nouvelleSuggBtn = `<button class="btn ghost sm" onclick="compoNouvelleSuggestion(${i})" style="font-size:.82rem">🎲 Nouvelle suggestion</button>`;

  let corps='';
  if(!props.length){
    corps = `<div class="banner" style="background:#fdf8e9;border-color:#e8d09a">📋 <div>Aucune composition possible pour ce format à cette date${mode==='strict'?' (essaie le mode Flexible)':''}${valides.length?' avec les parfums validés (essaie d\'en retirer)':''}.</div></div>`;
  } else {
    corps = props.slice(0,4).map((p,n)=>carteProp(p,n)).join('');
  }

  // Fallback taille : proposer une taille plus petite qui débloque un coffret complet.
  let fbHtml='';
  if(fallback.length){
    fbHtml = fallback.map(f=>{
      const p = f.propositions[0]; if(!p) return '';
      const payload = escJs(encodeURIComponent(JSON.stringify({taille:f.taille, lignes:p.lignes, changeTaille:true})));
      const noms = p.lignes.map(l=>`${l.nom} ×${l.qte}`).join(', ');
      return `<div style="border:1px dashed #cbb89a;border-radius:12px;padding:10px 12px;margin:9px 0;background:#faf7f1">
        <div style="font-size:.8rem;font-weight:700;color:#8a6d3b;margin-bottom:4px">↓ Si tu réduis la taille</div>
        <div style="font-size:.86rem;margin-bottom:6px"><b>Coffret ${f.taille}</b> complet : <span style="text-transform:capitalize">${esc(noms)}</span></div>
        <button class="btn ghost sm" onclick="appliquerCompositionCoffret(${i},'${payload}')">Passer au coffret ${f.taille}</button>
      </div>`;
    }).join('');
  }

  // [PARFUMS EN +] Bloc visible UNIQUEMENT en mode strict : rappelle la règle (nb de parfums inclus
  // pour la taille) et permet d'ajouter volontairement des parfums supplémentaires, chacun facturé
  // FLAVOR_SURCHARGE (3 €). Le surcoût affiché reprend la tarification réelle de la ligne coffret.
  let strictExtraBloc = '';
  if(mode==='strict'){
    const limite = (res && res.meta && res.meta.limiteReglementaire!=null)
      ? res.meta.limiteReglementaire
      : ((typeof BOX_FLAVOR_LIMIT!=='undefined' && BOX_FLAVOR_LIMIT[taille]!=null) ? BOX_FLAVOR_LIMIT[taille] : null);
    const extra = (res && res.meta && res.meta.parfumsEnPlus) ? +res.meta.parfumsEnPlus : 0;
    const surco = (typeof FLAVOR_SURCHARGE!=='undefined' ? FLAVOR_SURCHARGE : 3);
    const maxExtra = Math.max(0, (taille - (limite||0)));   // pas plus de parfums que de macarons
    const surcoutTxt = extra>0
      ? `<span style="color:var(--caramel,#AA7C39);font-weight:600">+${(typeof euro==='function')?euro(extra*surco):(extra*surco)+' €'}</span> (${extra}×${surco} €)`
      : `<span style="color:#9a8a82">aucun supplément</span>`;
    const btn = (delta, lbl, dis) => `<button class="btn ghost sm" ${dis?'disabled style="opacity:.4"':''}
      onclick="proposerCompositionLigne(${i},'strict',${Math.max(0,Math.min(maxExtra, extra+delta))})"
      style="min-width:34px;padding:4px 9px;font-size:1rem;line-height:1">${lbl}</button>`;
    strictExtraBloc = `<div style="background:#faf7f1;border:1px solid var(--hair);border-radius:11px;padding:9px 11px;margin:2px 0 8px">
      <div style="font-size:.8rem;color:#6a5a52;margin-bottom:5px">
        Ce format inclut <b>${limite!=null?limite:'—'} parfum${(limite||0)>1?'s':''}</b>. Tu peux en ajouter (chacun <b>+${surco} €</b>).
      </div>
      <div style="display:flex;align-items:center;gap:10px">
        ${btn(-1,'−', extra<=0)}
        <span style="font-size:.9rem;min-width:90px;text-align:center">Parfums en + : <b>${extra}</b></span>
        ${btn(1,'+', extra>=maxExtra)}
        <span style="margin-left:auto;font-size:.82rem">${surcoutTxt}</span>
      </div>
    </div>`;
  }

  const dateTxt = dateLiv ? ((typeof fmtDate==='function')?fmtDate(dateLiv):dateLiv) : 'la date choisie';
  openModal(`<h3>💡 Compositions alternatives</h3>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:4px">
      <p class="note" style="margin:0">Coffret <b>${taille}</b> pour le <b>${esc(dateTxt)}</b> — du plus simple au plus engageant.</p>
      ${toggle}
    </div>
    ${legende}
    ${validesBloc}
    ${strictExtraBloc}
    ${corps}
    ${fbHtml}
    <div style="display:flex;gap:8px;align-items:center;margin-top:8px;flex-wrap:wrap">
      ${nouvelleSuggBtn}
      <span class="note" style="margin:0;font-size:.74rem;color:#9a8a82">Valide les parfums qui te plaisent, puis relance : seuls les autres changent.</span>
    </div>
    <div class="modal-actions"><button class="btn ghost" onclick="fermerCompositionModale()">Fermer</button></div>`);
}

// [v1191] Valide (verrouille) un parfum : conservé tel quel aux prochaines suggestions.
function compoValiderParfum(i, encNom, qte){
  let nom; try{ nom=decodeURIComponent(encNom); }catch(_){ nom=encNom; }
  if(!nom) return;
  _compoValides[i] = _compoValides[i] || {};
  _compoValides[i][nom] = Math.max(1, Math.round(+qte||1));
  proposerCompositionLigne(i);   // re-render : le parfum passe en « validé »
}
// [v1191] Retire un parfum des validés.
function compoDevaliderParfum(i, encNom){
  let nom; try{ nom=decodeURIComponent(encNom); }catch(_){ nom=encNom; }
  if(_compoValides[i]){ delete _compoValides[i][nom]; }
  proposerCompositionLigne(i);
}
// [v1191] Nouvelle suggestion : incrémente le seed → recompose en gardant les validés, varie le reste.
function compoNouvelleSuggestion(i){
  _compoSeed[i] = (+_compoSeed[i]||0) + 1;
  proposerCompositionLigne(i);
}

// Applique une composition à la ligne coffret : REMPLACE les parfums de la ligne (et la taille si
// le fallback l'a changée). On remplace plutôt qu'on cumule : la compo proposée EST le coffret voulu.
function appliquerCompositionCoffret(i, payload){
  // En cas de sortie précoce (ligne invalide, payload cassé), on ROUVRE le formulaire plutôt que de
  // le fermer : sinon la commande en cours d'édition serait perdue (le formulaire est une modale).
  const _reopen = () => cmdForm(_cmdEditingId||0, {keepLines:true});
  const ln = cmdLines[i]; if(!ln || ln.type!=='coffret'){ _reopen(); return; }
  let data; try{ data = JSON.parse(decodeURIComponent(payload)); }catch(e){ data=null; }
  if(!data || !Array.isArray(data.lignes)){ _reopen(); return; }
  // Changement de taille (fallback) : on adopte la nouvelle taille et on re-tarife.
  if(data.changeTaille && +data.taille){ ln.taille = +data.taille; ln.prixUnitaireApplique = null; }
  // Remplacement des parfums.
  ln.parfums = {};
  // [v1188] Le générateur renvoie des noms de RECETTES / preps R&D. Quand un nom correspond (à la casse,
  // aux accents et aux espaces près) à un parfum du catalogue FLAVORS, on adopte le libellé FLAVORS : la
  // grille l'affiche alors sur sa ligne native (pas en « hors catalogue ») et on évite les doublons. Sinon
  // on garde le nom tel quel — il reste affiché et supprimable via la ligne hors-catalogue (fix fantôme).
  const _kf = s => (typeof aiNormalize==='function') ? aiNormalize(s) : String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
  const _flavByKey = {}; FLAVORS.forEach(f=>{ _flavByKey[_kf(f)] = f; });
  data.lignes.forEach(l=>{
    const q=Math.max(0,+l.qte||0); if(!l.nom || q<=0) return;
    const canon = _flavByKey[_kf(l.nom)] || l.nom;   // libellé catalogue si match, sinon nom d'origine
    ln.parfums[canon]=(+ln.parfums[canon]||0)+q;
  });
  // Le total attribué couvre-t-il la taille ? Le reste devient « sans parfum » (à définir plus tard).
  const total = Object.values(ln.parfums).reduce((s,q)=>s+(+q||0),0);
  const reste = Math.max(0, (+ln.taille||0) - total);
  if(reste>0) ln.sansParfum = reste; else delete ln.sansParfum;
  // [FIX modale] Le formulaire de commande EST une modale ; la modale de composition a écrasé son
  // contenu. Un simple closeModal() fermerait donc le formulaire ET perdrait les lignes non enregistrées.
  // On ROUVRE le formulaire en préservant cmdLines (keepLines) — comme le fait quickClient — pour que
  // le choix reste visible et que l'utilisateur puisse continuer puis Enregistrer normalement.
  // [v1191] La composition est appliquée : on repart d'un état propre pour cette ligne (validés + seed).
  delete _compoValides[i]; delete _compoSeed[i];
  cmdForm(_cmdEditingId||0, {keepLines:true});
}

// [FIX modale] Fermeture de la modale de composition SANS perdre la commande : le formulaire est une
// modale que la composition a écrasée. « Fermer » doit donc ROUVRIR le formulaire (lignes préservées),
// pas simplement vider la modale (ce qui ferait disparaître la commande en cours d'édition).
function fermerCompositionModale(){
  // [v1191] On sort de l'assistant compo : on oublie les validés/seed temporaires de cette session.
  if(typeof _cmdEditingId!=='undefined'){ /* rien de spécifique à retenir */ }
  _compoValides = {}; _compoSeed = {};
  cmdForm(_cmdEditingId||0, {keepLines:true});
}

function drawEventLine(ln,i){
  const flavRows = FLAVORS.map((f,fi)=>{
    const q=ln.parfums[f]||0;
    return flavorPickRow(f, q, `setEventParfum(${i},${fi},VAL)`, Math.max(ln.evQte,50));
  }).join('');
  // [v1080] « Sans parfum déterminé » sur l'événement, comme pour les coffrets : une partie (ou tout)
  // des macarons reste à définir plus tard. Compté dans le total au même titre qu'un parfum attribué.
  const evSansParfum = +ln.sansParfum||0;
  const totQ = Object.values(ln.parfums).reduce((s,q)=>s+(+q||0),0) + evSansParfum;
  const evCap = Math.max(1, +ln.evQte||0);
  const evSpOn = evSansParfum>0;
  let evSpOpts=''; for(let n=1;n<=evCap;n++) evSpOpts+=`<option value="${n}" ${evSansParfum===n?'selected':''}>${n}</option>`;
  const evSansParfumRow = `<div onclick="setEventSansParfum(${i}, ${evSpOn?0:1})"
      style="display:flex;align-items:center;gap:12px;padding:12px 14px;margin:4px 0;cursor:pointer;
      border:1px solid var(--hair);border-radius:12px;
      background:${evSpOn?'#f0ece4':'#fbf8f3'};${evSpOn?'border-color:#cdbfa8':''}">
    <span style="width:22px;height:22px;border-radius:50%;background:repeating-linear-gradient(45deg,#cbb,#cbb 3px,#ddd 3px,#ddd 6px);flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.06);${evSpOn?'outline:2px solid #8a7a62;outline-offset:1px':''}"></span>
    <span style="flex:1;font-size:1rem;color:${evSpOn?'var(--bordeaux)':'#6a5a52'};font-weight:${evSpOn?'600':'400'}">Sans parfum déterminé <span style="font-size:.72rem;color:#9a8a82;font-weight:400">— à définir plus tard</span></span>
    ${evSpOn
      ? `<select onclick="event.stopPropagation()" onchange="setEventSansParfum(${i},+this.value)" style="font-size:1rem;padding:4px 8px">${evSpOpts}</select>`
      : `<span style="color:#9a8a82;font-size:.9rem">+ ajouter</span>`}
  </div>`;
  // --- Logique pyramide intégrée ---
  const hasPyra=(+ln.equip||0)>0;                 // une pyramide est présente
  const prixMac = hasPyra ? PYRA_PRICE : EVENT_PRICE;   // 1,60€ conditionné à la pyramide
  const totalLigne = (+ln.evQte||0)*prixMac + pyraTotalLigne(ln) + accessoireDecoTotal(ln);

  return `<div class="cmd-line">
    <div class="line-head"><span class="line-type">Événement <span class="line-sub">${hasPyra?`${euro(PYRA_PRICE)}/macaron (pyramide)`:`${euro(EVENT_PRICE)}/macaron`} · min ${EVENT_MIN} · ≥1 pyramide</span></span><span class="line-del" onclick="removeLine(${i})">✕ retirer</span></div>
    <div class="row2">
      <div class="field"><label>Nombre de macarons</label><input type="number" min="${EVENT_MIN}" value="${ln.evQte}" oninput="setEventQte(${i},this.value)"></div>
      <div class="field"><label>Pyramides / présentoirs <span style="font-weight:400;color:#9a8a82;font-size:.74rem">(max)</span></label><input type="number" min="0" inputmode="numeric" value="${(()=>{const f=(ln.evFiltrePyr!=null?+ln.evFiltrePyr:+ln.equip||0);return f>0?f:'';})()}" placeholder="toutes les options" oninput="setEventEquip(${i},this.value)"></div>
    </div>
    <div id="pyraOpts_${i}">${eventPyraOptsHtml(i, (ln.evDemande!=null?+ln.evDemande:+ln.evQte||0), +ln.evQte||0, (ln.evFiltrePyr!=null?+ln.evFiltrePyr:+ln.equip||0), +ln.equip||0)}</div>
    ${(+ln.equip||0)>0?`<div style="background:#faf7f2;border:1px solid var(--hair);border-radius:11px;padding:10px 12px;margin:4px 0">
      <div style="font-size:.78rem;color:#7a6a62;font-weight:600;margin-bottom:6px">Pyramide${(+ln.equip||0)>1?'s':''} : louée${(+ln.equip||0)>1?'s':''} ou vendue${(+ln.equip||0)>1?'s':''} ?</div>
      <div style="display:flex;gap:6px">
        <button class="btn ${!pyraEstVente(ln)?'':'ghost'} sm" style="flex:1" onclick="setPyraMode(${i},false)">🔄 Location <span style="font-size:.72rem;opacity:.8">(${euro(EQUIP_PRICE)})</span></button>
        <button class="btn ${pyraEstVente(ln)?'':'ghost'} sm" style="flex:1" onclick="setPyraMode(${i},true)">🛍 Vente</button>
      </div>
      ${pyraEstVente(ln)?`<div class="row2" style="margin-top:8px">
        <div class="field"><label>Prix de vente / pyramide</label><input type="number" min="0" step="0.01" inputmode="decimal" value="${ln.pyraPrixVente!=null?ln.pyraPrixVente:''}" placeholder="0,00" oninput="setPyraPrix(${i},this.value)"></div>
        <div class="field"><label>Coût d'achat / pyramide <span style="font-weight:400;color:#9a8a82;font-size:.72rem">(pour ta marge)</span></label><input type="number" min="0" step="0.01" inputmode="decimal" value="${ln.pyraCoutAchat!=null?ln.pyraCoutAchat:''}" placeholder="0,00" oninput="setPyraCout(${i},this.value)"></div>
      </div>
      <p class="note" style="margin:4px 2px 0;font-size:.72rem">Vendue, la pyramide compte comme <b>marchandise</b> (et non comme prestation de service) — ${(+ln.equip||0)} × ${euro(+ln.pyraPrixVente||0)} = <b>${euro(pyraTotalLigne(ln))}</b>.</p>`
      :`<p class="note" style="margin:6px 2px 0;font-size:.72rem">Louée, la pyramide est une <b>prestation de service</b>, à retourner après l'événement.</p>`}
    </div>`:''}
    ${(+ln.equip||0)>0?(()=>{
      // [v1246] Option accessoire décoratif (ruban + déco LOVE au sommet), en LOCATION, par pyramide.
      const on = accessoireDecoActif(ln);
      const nb = +ln.equip||0;
      const tot = accessoireDecoTotal(ln);
      return `<div onclick="setAccessoireDeco(${i},${on?'false':'true'})" style="display:flex;align-items:center;gap:10px;cursor:pointer;background:${on?'#f6eef1':'#faf7f2'};border:1px solid ${on?'var(--bordeaux,#52252F)':'var(--hair)'};border-radius:11px;padding:10px 12px;margin:4px 0">
        <span style="width:22px;height:22px;flex:0 0 auto;border-radius:6px;border:2px solid ${on?'var(--bordeaux,#52252F)':'#c9bcb2'};background:${on?'var(--bordeaux,#52252F)':'#fff'};color:#fff;display:flex;align-items:center;justify-content:center;font-size:.8rem;font-weight:700">${on?'✓':''}</span>
        <span style="flex:1">
          <span style="display:block;font-size:.92rem;color:${on?'var(--bordeaux,#52252F)':'#6a5a52'};font-weight:${on?'600':'500'}">🎀 Accessoire décoratif <span style="font-weight:400;color:#9a8a82;font-size:.74rem">— ruban + déco LOVE (location)</span></span>
          <span style="display:block;font-size:.72rem;color:#9a8a82;margin-top:2px">${euro(ACCESS_DECO_PRICE)} / pyramide${on&&nb>1?` · ${nb} × ${euro(ACCESS_DECO_PRICE)} = ${euro(tot)}`:''}</span>
        </span>
        ${on?`<b style="color:var(--bordeaux,#52252F);font-size:.95rem">${euro(tot)}</b>`:`<span style="color:#9a8a82;font-size:.9rem">+ ajouter</span>`}
      </div>`;
    })():''}
    <label style="font-size:.78rem;color:#7a6a62">Parfums (optionnel)</label>
    <div class="flav-grid">${flavRows}${evSansParfumRow}</div>
    ${evSansParfum>0 ? `<p class="note" style="margin:6px 0 2px;color:#9a7d3a">🎯 Les ${evSansParfum} macaron${evSansParfum>1?'s':''} sans parfum seront à déterminer au démarrage de la production — l'app te le proposera au bon moment, avec le stock réel de ce jour-là.</p>` : ''}
    ${(()=>{
      // Compteur de remplissage des parfums, même logique que les coffrets : vert si pile,
      // rouge si au-dessus, orange (neutre) en dessous. En gras, s'incrémente à la saisie.
      const cible = +ln.evQte||0;
      const col = totQ===cible ? '#2e7d32' : (totQ>cible ? '#b3261e' : '#c77d2e');
      const bg  = totQ===cible ? '#eef6ee' : (totQ>cible ? '#fdf2f1' : '#fbf8f3');
      const nbDiff = Object.values(ln.parfums).filter(q=>+q>0).length;
      const txt = totQ>cible ? `${totQ}/${cible} — dépasse de ${totQ-cible} !`
                : totQ===cible ? `${totQ}/${cible} ✓`
                : `${totQ}/${cible}${totQ>0?` — ${cible-totQ} sans parfum`:''}`;
      return `<div class="sum-box" style="border:2px solid ${col};background:${bg}">
        <span>${nbDiff} parfum(s) attribué(s)${evSansParfum?` + ${evSansParfum} sans parfum`:''}</span>
        <b style="color:${col};font-size:1.1rem">${txt}</b></div>`;
    })()}
    <div class="sum-box"><span>${ln.evQte} macarons${hasPyra?` × ${euro(PYRA_PRICE)}`:''} · ${ln.equip} pyramide(s)</span><b>${euro(totalLigne)}</b></div>
    ${lineRemiseRow(ln,i)}
  </div>`;
}
// HTML du bloc options : la liste se base sur la DEMANDE client (stable),
// l'option mise en avant est la quantité RETENUE (choisie). Les deux sont dissociées.
// [v1078] La config retenue est identifiée par le COUPLE (total, nb pyramides) : deux configs peuvent
// avoir le même total de macarons (ex. 105 = 1× Matfer OU 3× Bloc 35) — il faut donc aussi comparer
// le nombre de pyramides, sinon plusieurs lignes s'affichent « choisi » en même temps.
function eventPyraOptsHtml(i, demande, choisi, nbPyr, nChoisi){
  nbPyr = +nbPyr||0;
  const multiOpt = pyraOptions(demande||0, undefined, nbPyr);
  const boxes = (choisi>0) ? pyraBoxes(choisi) : null;  // boîtes calculées sur la quantité retenue
  const filtreTxt = nbPyr>0 ? ` · max ${nbPyr} pyramide${nbPyr>1?'s':''}` : '';
  // nombre de pyramides de la config retenue : fourni explicitement, sinon on prend l'equip courant.
  const nRetenu = (nChoisi!=null) ? (+nChoisi||0) : (+cmdLines[i]?.equip||0);
  let corps;
  if(multiOpt.opts.length){
    // une seule option est « la choisie » : même total ET même nombre de pyramides.
    const estChoisie = (o)=> o.total===choisi && (nRetenu>0 ? o.n===nRetenu : true);
    // si plusieurs options matchent encore (nRetenu non décisif), on n'en marque qu'UNE (la 1re).
    let dejaMarque = false;
    corps = multiOpt.opts.map((o,idx)=>{
      const sel = estChoisie(o) && !dejaMarque;
      if(sel) dejaMarque = true;
      // Badge de nature : équilibré (présentoirs identiques) vs combiné (2 modèles/hauteurs).
      const badge = o.kind==='combo'
        ? '<span class="tag" style="background:#e7dcc6;color:#7a5c20;font-size:.58rem">combiné</span>'
        : (o.n>=2 ? '<span class="tag" style="background:#dfe9df;color:#3f6d4a;font-size:.58rem">équilibré</span>' : '');
      // Signal si la config est un peu SOUS la demande.
      const sousDemande = (o.manque>0)
        ? `<span style="color:#b08a3a;font-size:.72rem"> · manque ${o.manque}</span>`
        : '';
      return `
      <div style="display:flex;align-items:center;gap:8px;padding:7px 9px;border-radius:8px;margin-bottom:4px;background:${sel?'#eef6ef':'#fff'};border:1px solid ${sel?'#3f7d52':'var(--hair)'}">
        <span style="flex:1;font-size:.86rem"><b style="color:var(--bordeaux)">${o.total}</b> ${badge} <span style="color:#6a5a52">— ${esc(o.desc)}</span>${sousDemande}</span>
        ${sel?'<span class="tag" style="background:#3f7d52;color:#fff;font-size:.62rem">choisi</span>':`<button class="btn ghost sm" onclick="pickEventConfig(${i},${o.total},${o.n})">Choisir</button>`}
      </div>`;
    }).join('');
  } else if(nbPyr>0){
    corps = `<p class="note" style="margin:0;color:#b08a3a">Aucune configuration jusqu'à <b>${nbPyr} pyramide(s)</b> pour une demande de ${demande} (jusqu'à ${Math.ceil((demande||0)*1.1)}). Augmente le nombre de pyramides, ou mets <b>0</b> pour voir toutes les options.</p>`;
  } else {
    corps = `<p class="note" style="margin:0;color:#b08a3a">Aucune configuration à +10% de ${demande}. Ajuste la demande.</p>`;
  }
  const optsHtml = `<div style="background:#faf7f2;border:1px solid var(--hair);border-radius:11px;padding:11px 13px;margin:4px 0">
    <div style="font-size:.74rem;color:#7a6a62;font-weight:600;text-transform:uppercase;margin-bottom:6px">Configurations possibles ${demande>0?`<br><span style="font-weight:400;text-transform:none;font-size:.92em;color:#9a8a82">Demande : ${demande} macarons${filtreTxt} · propositions jusqu'à ${multiOpt.plafond}</span>`:''}</div>
    ${corps}
  </div>
  ${boxes?`<div class="sum-box" style="background:#faf7f2"><span>📦 Transport : ${boxes.g>0?`${boxes.g}× grande`:''}${boxes.g>0&&boxes.p>0?' + ':''}${boxes.p>0?`${boxes.p}× petite`:''}</span><b>${boxes.nb} boîte(s)</b></div>`:''}`;
  return optsHtml;
}
// Choix d'une configuration : reporte la quantité retenue ET le nombre de pyramides,
// SANS toucher la demande client (la liste d'options reste stable).
function pickEventConfig(i, total, n){
  cmdLines[i].evQte = +total||0;
  cmdLines[i].equip = +n||1;             // nombre de pyramides RETENU (sert au prix, à l'emballage, à la facture)
  cmdLines[i]._configChoisie = true;     // [v1078] marque qu'un choix explicite a eu lieu
  // On NE touche PAS evFiltrePyr : le filtre des options reste celui que l'utilisateur a saisi,
  // pour qu'il puisse encore voir et choisir une autre config (ex. passer de 1× Matfer à 3× Bloc 35).
  if(cmdLines[i].evFiltrePyr==null) cmdLines[i].evFiltrePyr = 0;  // 0 = toutes les options
  drawLines();                    // redessine : champ pyramides + surbrillance + prix
  cmdRecalc();
}
function setEventQte(i,v){
  // Saisie au clavier = nouvelle DEMANDE client → régénère la liste d'options.
  const val=+v||0;
  cmdLines[i].evDemande = val;
  cmdLines[i].evQte = val;        // par défaut la quantité retenue suit la demande tant qu'on n'a pas choisi
  const box=document.getElementById('pyraOpts_'+i);
  // On rafraîchit dès que le bloc existe (même si filtre=0 : le filtre 0 montre toutes les options).
  if(box) box.innerHTML=eventPyraOptsHtml(i, val, val, +cmdLines[i].evFiltrePyr||0, +cmdLines[i].equip||0);
  cmdRecalc();
}
function setEventEquip(i,v){
  const raw=(v==null?'':String(v)).trim();
  const n=+raw||0;                       // vide ou 0 → 0 (= aucun filtre, toutes les options)
  const prev=+cmdLines[i].evFiltrePyr||0;
  // [v1078] Le champ « Pyramides » est un MAXIMUM (filtre des options), dissocié du nombre RETENU
  // (cmdLines[i].equip, fixé en choisissant une config). Ainsi, choisir une config ne fait pas
  // disparaître les autres : le filtre reste celui que tu as tapé.
  cmdLines[i].evFiltrePyr = n;
  // Si aucune config n'a encore été retenue, on aligne le retenu sur le filtre (compat. prix/emballage).
  if(!cmdLines[i]._configChoisie){ cmdLines[i].equip = n; }
  else if(n>0){
    // [v1215 FIX] Une config était choisie ET l'utilisateur change le nombre de pyramides : son intention
    // est « je veux maintenant ce nombre de présentoirs ». On RE-SÉLECTIONNE en direct la meilleure config
    // à exactement n pyramides, ce qui met à jour evQte (donc le compteur « X / utile ») en temps réel.
    // Sans ça, evQte restait figé sur l'ancien choix → compteur périmé → blocage au save (somme>evQte).
    const demandeRef=(cmdLines[i].evDemande!=null?+cmdLines[i].evDemande:+cmdLines[i].evQte||0);
    const res=pyraOptions(demandeRef, undefined, n);
    // meilleure config à EXACTEMENT n présentoirs (sinon la plus proche que le filtre laisse passer).
    const exact=res.opts.filter(o=>o.n===n);
    const pick=(exact.length?exact:res.opts)[0];
    if(pick){ cmdLines[i].evQte=+pick.total||0; cmdLines[i].equip=pick.n; }
    else { cmdLines[i].equip=n; }   // aucune config à n pyramides : on garde le nombre demandé, evQte inchangé
  }
  // On redessine TOUTE la ligne (pas seulement la liste d'options) pour que le compteur « X / utile »,
  // le prix et la répartition parfums reflètent immédiatement le nouveau evQte.
  drawLines();
  cmdRecalc();
}
function setEventParfum(i,fi,v){ const f=FLAVORS[fi]; const q=+v||0; if(q>0)cmdLines[i].parfums[f]=q; else delete cmdLines[i].parfums[f]; drawLines(); }
// [v1080] « Sans parfum déterminé » sur l'événement (même mécanique que les coffrets).
function setEventSansParfum(i,v){ const q=Math.max(0,+v||0); if(q>0) cmdLines[i].sansParfum=q; else delete cmdLines[i].sansParfum; drawLines(); }
// [v1079] Pyramide : bascule location/vente + saisie prix de vente et coût d'achat.
function setPyraMode(i, vendue){
  cmdLines[i].pyraVendue = !!vendue;
  if(vendue && cmdLines[i].pyraPrixVente==null) cmdLines[i].pyraPrixVente = 0;
  drawLines();   // redessine : affiche/masque les champs prix+coût et met à jour le total
  cmdRecalc();
}
function setPyraPrix(i, v){
  cmdLines[i].pyraPrixVente = Math.max(0, +String(v).replace(',', '.')||0);
  // mise à jour discrète du total sans tout redessiner (on garde le focus sur le champ)
  cmdRecalc();
  const box=document.getElementById('pyraOpts_'+i);
  // on rafraîchit juste la note de total via un redraw léger de la ligne si nécessaire
}
function setPyraCout(i, v){
  cmdLines[i].pyraCoutAchat = Math.max(0, +String(v).replace(',', '.')||0);
  cmdRecalc();
}
// [v1246] Accessoire décoratif (ruban + déco LOVE) : bascule on/off. Location par pyramide.
function setAccessoireDeco(i, on){
  cmdLines[i].accessoireDeco = !!on;
  drawLines();   // redessine la ligne (case + total) et met à jour le récap
  cmdRecalc();
}

function drawBigLine(ln,i){
  const pu=bigPrice(ln.tarif);
  const bigRows = BIG_FORMATS.map((f,fi)=>{
    const q=ln.items[f]||0;
    return flavorPickRow(f, q, `setBigItem(${i},${fi},VAL)`, 50);
  }).join('');
  // [v1193] Grands formats présents dans ln.items mais HORS BIG_FORMATS (ex. recette GF ajoutée après
  // coup, ou proposée par la génération) : on les rend quand même, avec un setter par NOM (supprimable),
  // pour qu'aucune pièce comptée ne reste invisible — même robustesse que la grille coffret.
  const _kf = s => (typeof aiNormalize==='function') ? aiNormalize(s) : String(s||'').toLowerCase().trim();
  const horsCat = Object.keys(ln.items||{}).filter(nom => (+ln.items[nom]||0)>0 && !BIG_FORMATS.some(f=>_kf(f)===_kf(nom)));
  const extraRows = horsCat.map(nom => {
    const enc = escJs(encodeURIComponent(nom));
    return flavorPickRow(nom, +ln.items[nom]||0, `setBigItemNom(${i},'${enc}',VAL)`, 50);
  }).join('');
  const tot=Object.values(ln.items).reduce((s,q)=>s+(+q||0),0);
  return `<div class="cmd-line">
    <div class="line-head"><span class="line-type">Grand format</span><span class="line-del" onclick="removeLine(${i})">✕ retirer</span></div>
    <div class="field"><label>Tarif</label><select onchange="setBigTarif(${i},this.value)">
      <option value="particulier" ${ln.tarif!=='pro'?'selected':''}>Particulier — ${euro(bigPrice('particulier'))}/pièce</option>
      <option value="pro" ${ln.tarif==='pro'?'selected':''}>Pro — ${euro(bigPrice('pro'))}/pièce</option>
    </select></div>
    <label style="font-size:.78rem;color:#7a6a62">Produits (quantité)</label>
    <div style="margin:6px 0"><button class="btn gold sm" onclick="proposerGrandFormatLigne(${i})" style="font-size:.84rem;width:100%">💡 Proposer selon mes stocks (grands formats)</button></div>
    <div class="flav-grid">${bigRows}${extraRows}</div>
    ${(()=>{
      const mode = ln.embMode || 'reutilisable';   // défaut GF : pas de boîte facturée
      const embOpts = cmdEmballagesCache.map(m=>`<option value="${m.id}" ${(+ln.embMatId===+m.id)?'selected':''}>${esc(m.nom)}${m.capacite?` (${m.capacite} mac.)`:''}</option>`).join('');
      return `<div class="field"><label>Emballage <span style="color:#9a8a82;font-weight:400">— ajuste le coût</span></label>
        <select onchange="setBigEmbMode(${i},this.value)">
          <option value="reutilisable" ${mode==='reutilisable'?'selected':''}>Réutilisable (0 € — le client rapporte sa boîte)</option>
          <option value="autre" ${mode==='autre'?'selected':''}>Boîte blanche / autre (choisir dans ma liste)</option>
        </select>
        ${mode==='autre'?`<select style="margin-top:6px" onchange="setBigEmbMat(${i},this.value)">
          <option value="">— choisir un emballage —</option>${embOpts}
        </select>${!cmdEmballagesCache.length?'<p class="note" style="color:var(--red)">Aucun emballage créé. Ajoute-en dans Stock → Matières (catégorie emballage).</p>':''}`:''}
      </div>`;
    })()}
    <div class="sum-box"><span>${tot} pièce(s) × ${euro(pu)}</span><b>${euro(tot*pu)}</b></div>
    ${lineRemiseRow(ln,i)}
  </div>`;
}
function setBigTarif(i,v){ cmdLines[i].tarif=v; drawLines(); }
function setBigItem(i,fi,v){ const f=BIG_FORMATS[fi]; const q=+v||0; if(q>0)cmdLines[i].items[f]=q; else delete cmdLines[i].items[f]; drawLines(); }
// [v1193] Setter PAR NOM pour un grand format hors BIG_FORMATS (proposé par la génération ou recette
// ajoutée après coup) : permet de modifier ET de retirer (q=0 → delete), comme setCoffretParfumNom.
function setBigItemNom(i, encNom, v){
  if(!cmdLines[i] || !cmdLines[i].items) return;
  let nom; try{ nom = decodeURIComponent(encNom); }catch(_){ nom = encNom; }
  const q=+v||0;
  if(q>0) cmdLines[i].items[nom]=q; else delete cmdLines[i].items[nom];
  drawLines();
}
function setBigEmbMode(i,v){ cmdLines[i].embMode=v; if(v!=='autre') cmdLines[i].embMatId=null; drawLines(); }
function setBigEmbMat(i,v){ cmdLines[i].embMatId = v?+v:null; drawLines(); }

// ═══════════════════════════════════════════════════════════════════════════
// [v1193] PROPOSITION GRAND FORMAT — indépendante du coffret standard.
// Un grand format se commande À LA PIÈCE (pas un assortiment en boîte de taille N).
// On ne réutilise donc PAS le moteur coffret (round-robin/taille) : on liste simplement
// les grands formats DISPONIBLES, avec la même sémantique de facilité que le coffret :
//   🟢 en stock · ♻️ batch déjà prévu · 🔺 à produire (relance faisable pour la date).
// Source = _collecterDisponibilites(..., {typeFiltre:'grand'}) : STRICTEMENT les GF, jamais
// un parfum standard. Ajout direct à ln.items (format objet { nom: qte }, comme setBigItem).
// ═══════════════════════════════════════════════════════════════════════════
async function proposerGrandFormatLigne(i){
  const ln = cmdLines[i]; if(!ln || ln.type!=='grand') return;
  const dateLiv = (typeof val==='function' ? (val('f_date')||'') : '') || '';
  const heureLiv = (typeof val==='function' ? (val('f_heure')||'') : '') || '';
  openModal(`<h3>💡 Grands formats selon tes stocks</h3>
    <div style="padding:14px;text-align:center;color:#9a8576">⏳ Analyse du stock, des batchs à venir et de la production faisable…</div>`);
  try{
    // Uniquement l'univers GRAND FORMAT — le filtre exclut tout parfum standard (case grandFormat).
    const { parfums } = await _collecterDisponibilites(dateLiv, heureLiv, { typeFiltre:'grand' });
    _renderGrandFormatModale(i, parfums, dateLiv);
  }catch(e){
    console.error('proposerGrandFormatLigne', e);
    openModal(`<h3>💡 Grands formats selon tes stocks</h3>
      <div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⛔ <div>Erreur pendant l'analyse des grands formats.</div></div>
      <div class="modal-actions"><button class="btn ghost" onclick="fermerGrandFormatModale()">Fermer</button></div>`);
  }
}

function _renderGrandFormatModale(i, parfums, dateLiv){
  const ln = cmdLines[i] || {items:{}};
  const norm = n => (typeof aiNormalize==='function') ? aiNormalize(n||'') : String(n||'').toLowerCase().trim();
  // Liste des GF disponibles, triés par FACILITÉ (stock pur → mutualisé → relance seule).
  const list = Object.values(parfums||{}).map(p=>({
    nom: p.nom,
    stock: Math.floor(Math.max(0, +p.stock||0)),
    mutualise: Math.floor(Math.max(0, +p.mutualise||0)),
    relanceOk: !!p.relanceOk
  })).sort((a,b)=>
    (b.stock - a.stock) || (b.mutualise - a.mutualise) || ((b.relanceOk?1:0)-(a.relanceOk?1:0))
    || norm(a.nom).localeCompare(norm(b.nom))
  );

  const legende = `<div style="font-size:.72rem;color:#8a7a6e;margin:2px 0 8px">🟢 en stock · ♻️ batch déjà prévu · 🔺 à produire</div>`;
  const dateTxt = dateLiv ? ((typeof fmtDate==='function')?fmtDate(dateLiv):dateLiv) : 'la date choisie';

  let corps;
  if(!list.length){
    corps = `<div class="banner" style="background:#fdf8e9;border-color:#e8d09a">📋 <div>Aucun grand format disponible ni relançable pour le ${esc(dateTxt)}.</div></div>`;
  } else {
    corps = list.map(p=>{
      // Symbole de facilité selon la meilleure source dispo (stock > mutualisé > relance).
      const dispoImmediat = p.stock + p.mutualise;
      const estRelanceSeule = dispoImmediat<=0 && p.relanceOk;
      const estMut = p.stock<=0 && p.mutualise>0;
      const sym = estRelanceSeule ? '🔺' : estMut ? '♻️' : (p.stock>0 ? '🟢' : '🔺');
      const bg = estRelanceSeule ? '#fdf6ec' : estMut ? '#fbf3ea' : (p.stock>0 ? '#eef6ee' : '#fdf6ec');
      const bd = estRelanceSeule ? '#e8cfa3' : estMut ? '#e3c8a8' : (p.stock>0 ? '#bcd9c6' : '#e8cfa3');
      // Ventilation lisible de la dispo.
      const bouts = [];
      if(p.stock>0)     bouts.push(`<b>${p.stock}</b> en stock`);
      if(p.mutualise>0) bouts.push(`<b>${p.mutualise}</b> mutualisé${p.mutualise>1?'s':''}`);
      if(dispoImmediat<=0 && p.relanceOk) bouts.push(`à produire (faisable)`);
      const ventil = bouts.join(' · ') || '—';
      const dejaCmd = +((ln.items||{})[p.nom]||0);
      const enc = escJs(encodeURIComponent(p.nom));
      return `<div style="display:flex;align-items:center;gap:10px;background:${bg};border:1px solid ${bd};border-radius:10px;padding:8px 10px;margin:5px 0">
        <span title="${p.stock>0?'En stock':estMut?'Batch déjà prévu':'À produire'}" style="font-size:1rem">${sym}</span>
        <div style="flex:1;min-width:0">
          <div style="text-transform:capitalize;font-weight:600;color:var(--bordeaux,#52252F)">${esc(p.nom)}</div>
          <div style="font-size:.74rem;color:#7a6a62">${ventil}</div>
        </div>
        ${dejaCmd>0?`<span style="font-size:.78rem;color:#3f7d52;font-weight:600">${dejaCmd} ajouté${dejaCmd>1?'s':''}</span>`:''}
        <button class="btn ghost sm" onclick="gfAjouterItem(${i},'${enc}',1)" style="padding:4px 10px;font-size:1rem;line-height:1" title="Ajouter une pièce">＋</button>
      </div>`;
    }).join('');
  }

  openModal(`<h3>💡 Grands formats selon tes stocks</h3>
    <p class="note" style="margin:0 0 4px">Pour le <b>${esc(dateTxt)}</b> — à la pièce, du plus simple au plus engageant.</p>
    ${legende}
    ${corps}
    <div class="modal-actions">
      <button class="btn ghost" onclick="fermerGrandFormatModale()">Fermer</button>
      <button class="btn gold" onclick="fermerGrandFormatModale()">Terminé</button>
    </div>`);
}

// Ajoute `n` pièce(s) d'un grand format à la ligne (format objet ln.items[nom], comme setBigItem),
// puis re-render la modale pour refléter la quantité ajoutée (compteur « ajouté »).
function gfAjouterItem(i, encNom, n){
  const ln = cmdLines[i]; if(!ln || ln.type!=='grand') return;
  let nom; try{ nom = decodeURIComponent(encNom); }catch(_){ nom = encNom; }
  if(!nom) return;
  // [v1193] La grille de la ligne GF (drawBigLine) itère sur BIG_FORMATS : on adopte le libellé exact
  // de BIG_FORMATS quand il correspond (casse/accents près), pour que la pièce ajoutée s'affiche bien
  // sur sa ligne native. Sinon on garde le nom d'origine (au pire il reste comptabilisé dans le total).
  const _kf = s => (typeof aiNormalize==='function') ? aiNormalize(s) : String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
  const canon = (typeof BIG_FORMATS!=='undefined' ? BIG_FORMATS.find(f=>_kf(f)===_kf(nom)) : null) || nom;
  ln.items = ln.items || {};
  ln.items[canon] = (+ln.items[canon]||0) + Math.max(1, Math.round(+n||1));
  proposerGrandFormatLigne(i);
}

// Fermeture : réaffiche le formulaire de commande en préservant les lignes (comme la modale coffret).
function fermerGrandFormatModale(){ cmdForm(_cmdEditingId||0, {keepLines:true}); }

// Ligne VRAC PRO : macarons standards en boîte réutilisable (non facturée), au tarif pro/macaron.
function drawVracLine(ln,i){
  if(!ln.parfums) ln.parfums={};
  if(!ln.proMode) ln.proMode='pro';
  const pu=vracPrixMacaron(ln);
  const rows = FLAVORS.map((f,fi)=>{
    const q=ln.parfums[f]||0;
    return flavorPickRow(f, q, `setVracParfum(${i},${fi},VAL)`, 120);
  }).join('');
  const tot=Object.values(ln.parfums).reduce((s,q)=>s+(+q||0),0);
  const sansParfum=+ln.sansParfum||0;
  const spOn=sansParfum>0;
  const sansParfumRow=`<div onclick="setVracSansParfum(${i}, ${spOn?0:1})"
      style="display:flex;align-items:center;gap:12px;padding:12px 14px;margin:4px 0;cursor:pointer;
      border:1px solid var(--hair);border-radius:12px;
      background:${spOn?'#f0ece4':'#fbf8f3'};${spOn?'border-color:#cdbfa8':''}">
    <span style="width:22px;height:22px;border-radius:50%;background:repeating-linear-gradient(45deg,#cbb,#cbb 3px,#ddd 3px,#ddd 6px);flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.06);${spOn?'outline:2px solid #8a7a62;outline-offset:1px':''}"></span>
    <span style="flex:1;font-size:1rem;color:${spOn?'var(--bordeaux)':'#6a5a52'};font-weight:${spOn?'600':'400'}">Sans parfum déterminé <span style="font-size:.72rem;color:#9a8a82;font-weight:400">— à définir plus tard</span></span>
    ${spOn
      ? `<input type="number" min="1" step="1" onclick="event.stopPropagation()" value="${sansParfum}" oninput="setVracSansParfumLive(${i},this.value)" onchange="setVracSansParfum(${i},this.value)" style="max-width:90px;font-size:1rem;padding:4px 8px" placeholder="nb">`
      : `<span style="color:#9a8a82;font-size:.9rem">+ ajouter</span>`}
  </div>`;
  const proSel = `<div class="seg" style="display:flex;gap:6px;margin:6px 0">
    <button type="button" class="btn ${ln.proMode==='pro'?'gold':'ghost'} sm" style="flex:1" onclick="setVracMode(${i},'pro')">Pro (${euro(+getSettings().prixMacaronProStd||0)})</button>
    <button type="button" class="btn ${ln.proMode==='nonpro'?'gold':'ghost'} sm" style="flex:1" onclick="setVracMode(${i},'nonpro')">Non pro (${euro(money2((BOX_PRICES[6]||12)/6))})</button>
  </div>`;
  return `<div class="cmd-line">
    <div class="line-head"><span class="line-type">Vrac <span class="line-sub">boîte réutilisable, non facturée</span></span><span class="line-del" onclick="removeLine(${i})">✕ retirer</span></div>
    ${proSel}
    <div class="sum-box"><span>Tarif ${ln.proMode==='nonpro'?'particulier (prix coffret)':'pro'}</span><b>${euro(pu)}/macaron</b></div>
    <label style="font-size:.78rem;color:#7a6a62">Parfums (quantité)</label>
    <div class="flav-grid">${rows}${sansParfumRow}</div>
    ${sansParfum>0 ? `<p class="note" style="margin:6px 0 2px;color:#9a7d3a">🎯 Les ${sansParfum} macaron${sansParfum>1?'s':''} sans parfum seront à déterminer au démarrage de la production.</p>
    ${cmdSpModeBlock(ln,i)}` : ''}
    <div class="sum-box"><span>${tot}${sansParfum?` + ${sansParfum} sans parfum`:''} macaron(s) × ${euro(pu)}</span><b>${euro((tot+sansParfum)*pu)}</b></div>
    ${lineRemiseRow(ln,i)}
  </div>`;
}
// Bascule le mode tarifaire d'une ligne vrac (pro / non pro) et rafraîchit le formulaire.
function setVracMode(i, mode){
  if(!cmdLines[i]) return;
  cmdLines[i].proMode = (mode==='nonpro')?'nonpro':'pro';
  if(typeof drawLines==='function') drawLines();
  else if(typeof renderCmdForm==='function') renderCmdForm();
}
function setVracParfum(i,fi,v){ const f=FLAVORS[fi]; const q=+v||0; if(q>0)cmdLines[i].parfums[f]=q; else delete cmdLines[i].parfums[f]; drawLines(); }
function setVracSansParfum(i,v){ if(!cmdLines[i]) return; const q=Math.max(0,Math.round(+v||0)); if(q>0) cmdLines[i].sansParfum=q; else delete cmdLines[i].sansParfum; drawLines(); }
// Variante « live » pendant la frappe : met à jour la donnée et les totaux SANS redessiner
// la ligne (sinon le champ est recréé à chaque touche et le focus saute). Le redraw complet
// (qui fait apparaître le bloc assortiment/à déterminer) est déclenché au blur via onchange.
function setVracSansParfumLive(i,v){ if(!cmdLines[i]) return; const q=Math.max(0,Math.round(+v||0)); if(q>0) cmdLines[i].sansParfum=q; else delete cmdLines[i].sansParfum; if(typeof cmdRecalc==='function') cmdRecalc(); }

// [v1452] SACHET — Ben : « un sachet pouvant contenir de 1 à 3 macarons. Prix : 2,5€ par
// macaron. » Même « compteur de remplissage » que le coffret (vert pile, rouge dépassé) : ce
// langage visuel existe déjà dans l'app, le réutiliser ici évite d'en inventer un second pour la
// même idée (une capacité à respecter). SACHET_MAX borne l'AFFICHAGE et la VALIDATION à la
// sauvegarde (cmdValidateLines) — pas la saisie elle-même, comme flavorPickRow le fait déjà pour
// le coffret (v1087 : un champ libre, pas un plafond dur, pour ne jamais bloquer la frappe).
function drawSachetLine(ln,i){
  if(!ln.parfums) ln.parfums={};
  const rows = FLAVORS.map((f,fi)=>{
    const q=ln.parfums[f]||0;
    return flavorPickRow(f, q, `setSachetParfum(${i},${fi},VAL)`, SACHET_MAX);
  }).join('');
  // Même filet que le coffret (v1188) : un parfum hors catalogue FLAVORS (issu d'une recette/prep)
  // resterait invisible et indécochable sans cette ligne dédiée.
  const horsCatalogue = Object.keys(ln.parfums).filter(nom => (+ln.parfums[nom]||0) > 0 && !FLAVORS.includes(nom));
  const extraRows = horsCatalogue.map(nom => {
    const q = +ln.parfums[nom]||0;
    const enc = escJs(encodeURIComponent(nom));
    return flavorPickRow(nom, q, `setSachetParfumNom(${i},'${enc}',VAL)`, SACHET_MAX);
  }).join('');
  const sansParfum = +ln.sansParfum||0;
  const totQ = Object.values(ln.parfums).reduce((s,q)=>s+(+q||0),0) + sansParfum;
  const rempliCol = totQ===SACHET_MAX ? '#2e7d32' : (totQ>SACHET_MAX ? '#b3261e' : '#7a6a62');
  const rempliTxt = totQ>SACHET_MAX ? `${totQ}/${SACHET_MAX} — dépasse de ${totQ-SACHET_MAX} !` : `${totQ}/${SACHET_MAX}`;
  const spOn = sansParfum>0;
  let spOpts=''; for(let n=1;n<=SACHET_MAX;n++) spOpts+=`<option value="${n}" ${sansParfum===n?'selected':''}>${n}</option>`;
  const sansParfumRow = `<div onclick="setSachetSansParfum(${i}, ${spOn?0:1})"
      style="display:flex;align-items:center;gap:12px;padding:12px 14px;margin:4px 0;cursor:pointer;
      border:1px solid var(--hair);border-radius:12px;
      background:${spOn?'#f0ece4':'#fbf8f3'};${spOn?'border-color:#cdbfa8':''}">
    <span style="width:22px;height:22px;border-radius:50%;background:repeating-linear-gradient(45deg,#cbb,#cbb 3px,#ddd 3px,#ddd 6px);flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.06);${spOn?'outline:2px solid #8a7a62;outline-offset:1px':''}"></span>
    <span style="flex:1;font-size:1rem;color:${spOn?'var(--bordeaux)':'#6a5a52'};font-weight:${spOn?'600':'400'}">Sans parfum déterminé <span style="font-size:.72rem;color:#9a8a82;font-weight:400">— à définir plus tard</span></span>
    ${spOn
      ? `<select onclick="event.stopPropagation()" onchange="setSachetSansParfum(${i},+this.value)" style="font-size:1rem;padding:4px 8px">${spOpts}</select>`
      : `<span style="color:#9a8a82;font-size:.9rem">+ ajouter</span>`}
  </div>`;
  return `<div class="cmd-line">
    <div class="line-head"><span class="line-type">Sachet <span class="line-sub">1 à ${SACHET_MAX} macarons</span></span><span class="line-del" onclick="removeLine(${i})">✕ retirer</span></div>
    <p class="note" style="margin:-2px 0 4px">${euro(SACHET_PRIX_MACARON)} par macaron.</p>
    <label style="font-size:.78rem;color:#7a6a62">Parfums (quantité)</label>
    <div class="flav-grid">${rows}${extraRows}${sansParfumRow}</div>
    ${sansParfum>0 ? `<p class="note" style="margin:6px 0 2px;color:#9a7d3a">🎯 Les ${sansParfum} macaron${sansParfum>1?'s':''} sans parfum seront à déterminer au démarrage de la production — l'app te le proposera au bon moment, avec le stock réel de ce jour-là.</p>
    ${cmdSpModeBlock(ln,i)}` : ''}
    <div class="sum-box" style="border:2px solid ${rempliCol};background:${totQ===SACHET_MAX?'#eef6ee':(totQ>SACHET_MAX?'#fdf2f1':'#fbf8f3')}">
      <span>Macarons</span>
      <b style="color:${rempliCol};font-size:1.1rem">${rempliTxt}${totQ===SACHET_MAX?' ✓':''}</b></div>
    <div class="sum-box"><span>${totQ} × ${euro(SACHET_PRIX_MACARON)}</span><b>${euro(totQ*SACHET_PRIX_MACARON)}</b></div>
    ${lineRemiseRow(ln,i)}
  </div>`;
}
function setSachetParfum(i,fi,v){ const f=FLAVORS[fi]; const q=+v||0; if(q>0)cmdLines[i].parfums[f]=q; else delete cmdLines[i].parfums[f]; drawLines(); }
function setSachetParfumNom(i, encNom, v){
  if(!cmdLines[i] || !cmdLines[i].parfums) return;
  let nom; try{ nom = decodeURIComponent(encNom); }catch(_){ nom = encNom; }
  const q=+v||0;
  if(q>0) cmdLines[i].parfums[nom]=q; else delete cmdLines[i].parfums[nom];
  drawLines();
}
function setSachetSansParfum(i,v){ if(!cmdLines[i]) return; const q=Math.max(0,+v||0); if(q>0) cmdLines[i].sansParfum=q; else delete cmdLines[i].sansParfum; drawLines(); }

function drawDonLine(ln,i){
  if(!ln.parfums) ln.parfums={}; if(!ln.items) ln.items={};
  const parfRows = FLAVORS.map((f,fi)=>{
    const q=ln.parfums[f]||0;
    return flavorPickRow(f, q, `setDonParfum(${i},${fi},VAL)`, 60);
  }).join('');
  const bigRows = BIG_FORMATS.map((f,fi)=>{
    const q=ln.items[f]||0;
    return flavorPickRow(f+' (GF)', q, `setDonItem(${i},${fi},VAL)`, 30);
  }).join('');
  const totP=Object.values(ln.parfums).reduce((s,q)=>s+(+q||0),0);
  const totB=Object.values(ln.items).reduce((s,q)=>s+(+q||0),0);
  // Emballage du don : 'sans' (0 €) ou 'autre' (un emballage choisi dans la liste, coût unique).
  const embMode = ln.donEmbMode || 'sans';
  const embOpts = cmdEmballagesCache.map(m=>`<option value="${m.id}" ${(+ln.embMatId===+m.id)?'selected':''}>${esc(m.nom)}${m.capacite?` (${m.capacite} mac.)`:''}</option>`).join('');
  const embCout = (embMode==='autre' && ln.embMatId!=null) ? embMatUnitCost(ln.embMatId, cmdEmballagesCache, cmdEmbLotsCache||[]) : 0;
  const embBloc = `<label style="font-size:.78rem;color:#7a6a62;display:block;margin-top:8px">Emballage offert avec le don</label>
    <select onchange="setDonEmbMode(${i},this.value)">
      <option value="sans" ${embMode==='sans'?'selected':''}>Sans emballage (0 €)</option>
      <option value="autre" ${embMode==='autre'?'selected':''}>Choisir dans ma liste</option>
    </select>
    ${embMode==='autre'?`<select style="margin-top:6px" onchange="setDonEmbMat(${i},this.value)"><option value="">— choisir un emballage —</option>${embOpts}</select>
      ${ln.embMatId!=null?`<div class="sum-box" style="font-size:.82rem"><span>Coût emballage</span><b>${euro(embCout)}</b></div>`:''}`:''}`;
  // Sac offert avec le don (séparé de l'emballage boîte). Décompté du stock + imputé au coût des dons.
  const sacOpts = cmdSacsCache.map(m=>`<option value="${m.id}" ${(+ln.sacMatId===+m.id)?'selected':''}>${esc(m.nom)}${m.marque?' · '+esc(m.marque):''}</option>`).join('');
  const sacCout = (ln.sacMatId!=null) ? embMatUnitCost(ln.sacMatId, cmdSacsCache, cmdEmbLotsCache||[]) : 0;
  const sacBloc = cmdSacsCache.length ? `<label style="font-size:.78rem;color:#7a6a62;display:block;margin-top:8px">🛍️ Sac offert avec le don</label>
    <div class="row2" style="align-items:end">
      <div class="field" style="margin:0"><select onchange="setDonSacMat(${i},this.value)"><option value="">— aucun —</option>${sacOpts}</select></div>
      <div class="field" style="margin:0"><input type="number" min="0" step="1" value="${ln.sacNb!=null&&+ln.sacNb>0?esc(ln.sacNb):''}" placeholder="nb" oninput="setDonSacNbLive(${i},this.value)" onchange="setDonSacNb(${i},this.value)"></div>
    </div>
    ${(+ln.sacMatId>0&&+ln.sacNb>0)?`<div class="sum-box" style="font-size:.82rem"><span>Coût sac (${qty(ln.sacNb)}×)</span><b>${euro(money2(sacCout*(+ln.sacNb||0)))}</b></div>`:''}` : '';
  return `<div class="cmd-line">
    <div class="line-head"><span class="line-type">Don <span class="line-sub">offert · 0 € · décrémente le stock</span></span><span class="line-del" onclick="removeLine(${i})">✕ retirer</span></div>
    <label style="font-size:.78rem;color:#7a6a62">Macarons offerts (par parfum)</label>
    <div class="flav-grid">${parfRows}</div>
    <label style="font-size:.78rem;color:#7a6a62;display:block;margin-top:8px">Grands formats offerts (optionnel)</label>
    <div class="flav-grid">${bigRows}</div>
    ${embBloc}
    ${sacBloc}
    <div class="sum-box"><span>${totP+totB} macaron(s) offert(s)${embMode==='autre'&&ln.embMatId!=null?' + emballage':''}${+ln.sacMatId>0&&+ln.sacNb>0?' + sac':''}</span><b>${euro(0)}</b></div>
  </div>`;
}
// Setters emballage du don
function setDonEmbMode(i,v){ cmdLines[i].donEmbMode = v; if(v==='sans') cmdLines[i].embMatId=null; drawLines(); }
function setDonEmbMat(i,v){ cmdLines[i].embMatId = v?+v:null; drawLines(); }
function setDonSacMat(i,v){ cmdLines[i].sacMatId = v?+v:null; if(!v){ cmdLines[i].sacNb=0; } else if(!(+cmdLines[i].sacNb>0)){ cmdLines[i].sacNb=1; } drawLines(); }
function setDonSacNb(i,v){ cmdLines[i].sacNb = Math.max(0, Math.round(+v||0)); drawLines(); }
// Variante live (voir setVracSansParfumLive) : pas de redraw pendant la frappe.
function setDonSacNbLive(i,v){ if(!cmdLines[i]) return; cmdLines[i].sacNb = Math.max(0, Math.round(+v||0)); if(typeof cmdRecalc==='function') cmdRecalc(); }
function drawPrestationLine(ln,i){
  if(ln.remiseType==null) ln.remiseType='pct';
  const base=money2(+ln.montantHT||0);
  const net=lineTotal(ln);
  const isAccomp = ln.presta==='accompagnement';
  const accompFields = isAccomp ? `
    <div class="row2">
      <div class="field" style="margin:6px 0 0"><label>Durée (heures)</label>
        <input type="number" step="0.5" min="0" value="${ln.dureeH||''}" placeholder="3" oninput="setPrestaField(${i},'dureeH',this.value)"></div>
      <div class="field" style="margin:6px 0 0"><label>Format</label>
        <select onchange="setPrestaField(${i},'mode',this.value)">
          <option value="presentiel" ${ln.mode==='presentiel'?'selected':''}>📍 En présentiel</option>
          <option value="enligne" ${ln.mode==='enligne'?'selected':''}>💻 En ligne</option>
        </select></div>
    </div>
    <div class="field" style="margin:6px 0 0"><label>Détail de l'accompagnement <span style="color:#9a8a82;font-weight:400">— libre</span></label>
      <textarea rows="2" placeholder="ex : techniques de macaronnage, recettes, conseils gestion…" oninput="setPrestaField(${i},'detail',this.value)" style="width:100%;resize:vertical">${esc(ln.detail||'')}</textarea></div>` : '';
  return `<div class="cmd-line">
    <div class="line-head"><span class="line-type">${isAccomp?'🎓 Accompagnement / formation':'Prestation / Coaching'} <span class="line-sub">service · charges sociales ${getSettings().socialService}%</span></span><span class="line-del" onclick="removeLine(${i})">✕ retirer</span></div>
    <div class="field" style="margin:6px 0"><label>${isAccomp?'Intitulé':'Libellé de la prestation'}</label>
      <input value="${esc(ln.libelle||'')}" placeholder="ex : Coaching macarons (2 h), déplacement…" oninput="setPrestaField(${i},'libelle',this.value)"></div>
    ${accompFields}
    <div class="row2">
      <div class="field" style="margin:6px 0 0"><label>Montant (€)</label>
        <input type="number" step="0.01" min="0" value="${ln.montantHT||''}" placeholder="0" oninput="setPrestaField(${i},'montantHT',this.value)"></div>
      <div class="field" style="margin:6px 0 0"><label>Type de remise</label>
        <select onchange="setPrestaField(${i},'remiseType',this.value)">
          <option value="pct" ${ln.remiseType==='pct'?'selected':''}>Pourcentage (%)</option>
          <option value="euro" ${ln.remiseType==='euro'?'selected':''}>Fixe (€)</option>
        </select></div>
    </div>
    <div class="field" style="margin:6px 0 0">
      ${ln.remiseType==='euro'
        ? `<label>Remise (€)</label><input type="number" step="0.01" min="0" value="${ln.remiseEuro||''}" placeholder="0" oninput="setPrestaField(${i},'remiseEuro',this.value)">`
        : `<label>Remise (%)</label><input type="number" step="1" min="0" max="100" value="${ln.remisePct||''}" placeholder="0" oninput="setPrestaField(${i},'remisePct',this.value)">`}
    </div>
    <div class="sum-box">${(base!==net)?`<span>Avant remise ${euro(base)}</span><b>${euro(net)}</b>`:`<span>Montant ${isAccomp?'accompagnement':'prestation'}</span><b>${euro(base)}</b>`}</div>
  </div>`;
}
function setPrestaField(i,field,v){
  if(!cmdLines[i]) return;
  if(field==='montantHT'||field==='remiseEuro') cmdLines[i][field]=money2(+v||0);
  else if(field==='remisePct'){ let p=+v||0; cmdLines[i][field]=Math.max(0,Math.min(100,p)); }
  else cmdLines[i][field]=v;
  if(field==='remiseType') drawLines(); else cmdRecalc();
}
function setDonParfum(i,fi,v){ const f=FLAVORS[fi]; const q=+v||0; if(q>0)cmdLines[i].parfums[f]=q; else delete cmdLines[i].parfums[f]; drawLines(); }
function setDonItem(i,fi,v){ const f=BIG_FORMATS[fi]; const q=+v||0; if(q>0)cmdLines[i].items[f]=q; else delete cmdLines[i].items[f]; drawLines(); }

// Prix d'une ligne AVANT remise de ligne (arrondi strict au centime)
function lineTotalBase(ln){
  if(ln.type==='coffret'){
    const base = coffretUnitPrice(ln);
    const nbDiff = Object.values(ln.parfums||{}).filter(q=>q>0).length;
    const limit = BOX_FLAVOR_LIMIT[ln.taille]||0;
    const over = Math.max(0, nbDiff-limit);
    return money2(base + over*FLAVOR_SURCHARGE);
  }
  if(ln.type==='evenement') return addMoney(addMoney(mulMoney(ln.evQte||0,eventUnitPrice(ln)), pyraTotalLigne(ln)), accessoireDecoTotal(ln));
  if(ln.type==='grand'){ const pu=bigPrice(ln.tarif); const tot=Object.values(ln.items||{}).reduce((s,q)=>s+(+q||0),0); return mulMoney(tot,pu); }
  if(ln.type==='vrac'){ const pu=vracPrixMacaron(ln); const tot=Object.values(ln.parfums||{}).reduce((s,q)=>s+(+q||0),0) + (+ln.sansParfum||0); return mulMoney(tot,pu); }
  if(ln.type==='sachet'){ const tot=Object.values(ln.parfums||{}).reduce((s,q)=>s+(+q||0),0) + (+ln.sansParfum||0); return mulMoney(tot,SACHET_PRIX_MACARON); }
  if(ln.type==='don') return 0;
  if(ln.type==='prestation') return money2(+ln.montantHT||0);
  return 0;
}
// Prix unitaire d'un coffret, par ordre de priorité :
//  1) prix SCELLÉ sur la ligne (prixUnitaireApplique) — protège les commandes passées
//  2) catalogue dynamique (db.products via cmdProductsCache) — priorité aux tarifs saisis dans l'app
//  3) constante BOX_PRICES — repli historique uniquement
function coffretUnitPrice(ln){
  if(ln && ln.prixUnitaireApplique!=null && +ln.prixUnitaireApplique>=0) return +ln.prixUnitaireApplique;
  const cat = (typeof cmdProductsCache!=='undefined' ? cmdProductsCache : []).find(p=>+p.taille===+(ln&&ln.taille));
  if(cat && cat.prix!=null) return +cat.prix;
  return (BOX_PRICES[ln&&ln.taille]!=null) ? BOX_PRICES[ln.taille] : 0;
}
// Remise de ligne en € — gère les deux modes (€ fixe ou %) pour TOUS les types de ligne.
// remiseType:'euro' → montant fixe (borné au prix de base) ; sinon → pourcentage (0–100 %).
function lineRemiseEuro(ln){
  const base=lineTotalBase(ln);
  if(ln.remiseType==='euro') return Math.min(base, money2(+ln.remiseEuro||0));
  const pct=Math.max(0,Math.min(100,+ln.remisePct||0));
  return money2(base*pct/100);
}
// Prix d'une ligne APRÈS remise de ligne
function lineTotal(ln){
  return Math.max(0, subMoney(lineTotalBase(ln), lineRemiseEuro(ln)));
}
// Bloc « remise de ligne » : deux champs synchronisés € et %.
// Saisir l'un recalcule l'autre et le total, en direct. La référence stockée reste remisePct
// (% de la base) pour rester compatible avec tous les calculs en aval (CA, marges, export).
function lineRemiseRow(ln,i){
  if(ln.type==='don') return '';
  const base=lineTotalBase(ln);
  const pct=Math.max(0,Math.min(100,+ln.remisePct||0));
  const eur=money2(base*pct/100);
  const net=lineTotal(ln);
  return `<div class="row2" style="align-items:end">
      <div class="field" style="margin:0"><label>Remise ligne (€)</label>
        <input type="number" min="0" step="0.01" id="remEur_${i}" value="${eur>0?eur:''}" placeholder="0"
          oninput="setLineRemiseEuro(${i},this.value)"></div>
      <div class="field" style="margin:0"><label>Remise ligne (%)</label>
        <input type="number" min="0" max="100" step="1" id="remPct_${i}" value="${pct>0?pct:''}" placeholder="0"
          oninput="setLineRemisePct(${i},this.value)"></div>
    </div>
    <div class="sum-box" id="remSum_${i}" style="margin:6px 0 0">${(pct>0)
      ? `<span>Avant ${euro(base)} · −${pct}% (${euro(eur)})</span><b>${euro(net)}</b>`
      : `<span>Montant ligne</span><b>${euro(base)}</b>`}</div>`;
}
// HTML interne du récap de remise d'une ligne (réutilisé pour le rafraîchissement temps réel).
function lineRemiseSumInner(ln){
  const base=lineTotalBase(ln);
  const pct=Math.max(0,Math.min(100,+ln.remisePct||0));
  const eur=money2(base*pct/100);
  const net=lineTotal(ln);
  return (pct>0)
    ? `<span>Avant ${euro(base)} · −${pct}% (${euro(eur)})</span><b>${euro(net)}</b>`
    : `<span>Montant ligne</span><b>${euro(base)}</b>`;
}
// Saisie en POURCENTAGE → borne 0–100, met à jour le champ € jumeau, recalcule.
function setLineRemisePct(i,v){
  let p=+v||0; if(p<0)p=0; if(p>100)p=100;
  cmdLines[i].remiseType='pct'; cmdLines[i].remisePct=p; delete cmdLines[i].remiseEuro;
  const base=lineTotalBase(cmdLines[i]);
  const eurEl=document.getElementById('remEur_'+i);
  if(eurEl && document.activeElement!==eurEl){ const e=money2(base*p/100); eurEl.value=e>0?e:''; }
  const sum=document.getElementById('remSum_'+i); if(sum) sum.innerHTML=lineRemiseSumInner(cmdLines[i]);
  cmdRecalc();
}
// Saisie en EUROS → convertie en % de la base (référence canonique), met à jour le champ % jumeau.
function setLineRemiseEuro(i,v){
  let e=money2(+v||0); if(e<0)e=0;
  const base=lineTotalBase(cmdLines[i]);
  if(e>base) e=base;
  const p = base>0 ? Math.max(0,Math.min(100, money2(e/base*100))) : 0;
  cmdLines[i].remiseType='pct'; cmdLines[i].remisePct=p; delete cmdLines[i].remiseEuro;
  const pctEl=document.getElementById('remPct_'+i);
  if(pctEl && document.activeElement!==pctEl){ pctEl.value=p>0?p:''; }
  const sum=document.getElementById('remSum_'+i); if(sum) sum.innerHTML=lineRemiseSumInner(cmdLines[i]);
  cmdRecalc();
}
// Normalise les lignes d'édition (cmdLines) vers la forme stockée (tableaux parfums/items).
// Réutilisé par saveCmd ET par le calcul de marge en direct (impact livraison).
function cmdLinesToStored(){
  return (cmdLines||[]).map(ln=>{
    const rp = Math.max(0,Math.min(100,+ln.remisePct||0));
    if(ln.type==='coffret') return {type:'coffret', taille:ln.taille, remisePct:rp, prixUnitaireApplique: coffretUnitPrice(ln), embMode:ln.embMode||'standard', embMatId:ln.embMatId||null, sansParfum:(+ln.sansParfum||0)||undefined, spMode:((+ln.sansParfum||0)>0?(ln.spMode||'assortiment'):undefined), spNbParfums:((+ln.sansParfum||0)>0&&ln.spMode!=='adeterminer'&&+ln.spNbParfums>0?+ln.spNbParfums:undefined), parfums:Object.keys(ln.parfums).filter(k=>ln.parfums[k]>0).map(nom=>({nom,qte:ln.parfums[nom]}))};
    if(ln.type==='evenement') return {type:'evenement', evQte:ln.evQte, equip:ln.equip, remisePct:rp, sansParfum:(+ln.sansParfum||0)||undefined, spMode:((+ln.sansParfum||0)>0?(ln.spMode||'assortiment'):undefined), spNbParfums:((+ln.sansParfum||0)>0&&ln.spMode!=='adeterminer'&&+ln.spNbParfums>0?+ln.spNbParfums:undefined), pyraVendue:!!ln.pyraVendue, pyraPrixVente:(ln.pyraPrixVente!=null?+ln.pyraPrixVente:null), pyraCoutAchat:(ln.pyraCoutAchat!=null?+ln.pyraCoutAchat:null), accessoireDeco:(ln.accessoireDeco?true:undefined), parfums:Object.keys(ln.parfums).filter(k=>ln.parfums[k]>0).map(nom=>({nom,qte:ln.parfums[nom]}))};
    if(ln.type==='grand') return {type:'grand', tarif:ln.tarif, remisePct:rp, embMode:ln.embMode||'reutilisable', embMatId:ln.embMatId||null, items:Object.keys(ln.items).filter(k=>ln.items[k]>0).map(nom=>({nom,qte:ln.items[nom]}))};
    if(ln.type==='vrac') return {type:'vrac', proMode:ln.proMode==='nonpro'?'nonpro':'pro', remisePct:rp, sansParfum:(+ln.sansParfum||0)||undefined, spMode:((+ln.sansParfum||0)>0?(ln.spMode||'assortiment'):undefined), spNbParfums:((+ln.sansParfum||0)>0&&ln.spMode!=='adeterminer'&&+ln.spNbParfums>0?+ln.spNbParfums:undefined), parfums:Object.keys(ln.parfums||{}).filter(k=>ln.parfums[k]>0).map(nom=>({nom,qte:ln.parfums[nom]}))};
    if(ln.type==='sachet') return {type:'sachet', remisePct:rp, sansParfum:(+ln.sansParfum||0)||undefined, spMode:((+ln.sansParfum||0)>0?(ln.spMode||'assortiment'):undefined), spNbParfums:((+ln.sansParfum||0)>0&&ln.spMode!=='adeterminer'&&+ln.spNbParfums>0?+ln.spNbParfums:undefined), parfums:Object.keys(ln.parfums||{}).filter(k=>ln.parfums[k]>0).map(nom=>({nom,qte:ln.parfums[nom]}))};
    if(ln.type==='don') return {type:'don', donEmbMode:ln.donEmbMode||'sans', embMatId:(ln.donEmbMode==='autre'?(ln.embMatId||null):null), sacMatId:(+ln.sacMatId>0?+ln.sacMatId:null), sacNb:(+ln.sacMatId>0?Math.max(0,Math.round(+ln.sacNb||0)):0), parfums:Object.keys(ln.parfums||{}).filter(k=>ln.parfums[k]>0).map(nom=>({nom,qte:ln.parfums[nom]})), items:Object.keys(ln.items||{}).filter(k=>ln.items[k]>0).map(nom=>({nom,qte:ln.items[nom]}))};
    if(ln.type==='prestation') return {type:'prestation', libelle:ln.libelle||'', montantHT:money2(+ln.montantHT||0), remiseType:ln.remiseType||'pct', remisePct:Math.max(0,Math.min(100,+ln.remisePct||0)), remiseEuro:money2(+ln.remiseEuro||0), ...(ln.isLivraison?{isLivraison:true}:{})};
  }).filter(Boolean);
}
function cmdPersoToggle(){
  const on=document.getElementById('f_perso')?.checked;
  const w=document.getElementById('f_persoWrap'); if(w) w.style.display=on?'block':'none';
  if(!on){ const n=document.getElementById('f_persoNb'); if(n) n.value=''; }
  cmdRecalc();
}
const PERSO_PRIX_UNIT = 0.25;   // surcoût personnalisation des couleurs, €/macaron
function cmdPersoCount(){
  const on=document.getElementById('f_perso')?.checked;
  return on ? Math.max(0, +(document.getElementById('f_persoNb')?.value)||0) : 0;
}
// --- Détail couleur \u2194 parfum de la personnalisation (encadré devis/facture) ---
// Stocké dans o.persoCouleurs = [{couleur:'Rose pâle', parfum:'Framboise'}, ...].
// Saisie libre, purement descriptive : n'entre PAS dans le total (le montant reste
// persoMacarons \u00d7 0,25 \u20ac, géré par la ligne « Macarons personnalisés »).
function cmdPersoCoulRows(list){
  const arr = Array.isArray(list) ? list : [];
  const rows = arr.length ? arr : [{couleur:'',parfum:''}];
  return rows.map(r=>cmdPersoCoulRowHtml(r.couleur||'', r.parfum||'')).join('');
}
function cmdPersoCoulRowHtml(couleur, parfum){
  return `<div class="perso-coul-row" style="display:flex;gap:6px;margin-top:4px;align-items:center">`
    + `<input type="text" class="pc-coul" value="${esc(couleur)}" placeholder="Couleur (ex : Rose pâle)" style="flex:1">`
    + `<span style="color:#b09a86">\u2192</span>`
    + `<input type="text" class="pc-parf" value="${esc(parfum)}" placeholder="Parfum" style="flex:1">`
    + `<button type="button" class="btn ghost" style="padding:4px 9px;font-size:.85rem" onclick="this.closest('.perso-coul-row').remove()">\u00d7</button>`
    + `</div>`;
}
function cmdPersoCoulAdd(){
  const box=document.getElementById('f_persoCoulList'); if(!box) return;
  box.insertAdjacentHTML('beforeend', cmdPersoCoulRowHtml('',''));
}
// Relit les lignes saisies → tableau nettoyé (on ignore les lignes entièrement vides).
function cmdPersoCoulCollect(){
  const box=document.getElementById('f_persoCoulList'); if(!box) return [];
  const out=[];
  box.querySelectorAll('.perso-coul-row').forEach(row=>{
    const c=(row.querySelector('.pc-coul')?.value||'').trim();
    const p=(row.querySelector('.pc-parf')?.value||'').trim();
    if(c||p) out.push({couleur:c, parfum:p});
  });
  return out;
}
// Encadré HTML « Personnalisation » pour les documents (devis + facture).
// Rendu compact à droite du contenu. Renvoie '' si rien à afficher.
// nbPerso : nombre de macarons personnalisés ; coul : tableau {couleur,parfum}.
// --- Pastille de couleur d'après le NOM tapé à la main (devis/facture) ---
// Map des couleurs françaises courantes vers une teinte. Tolérant aux accents,
// pluriels et nuances (« bleu ciel », « rose pâle », « vert d'eau »...).
const PERSO_COULEURS = {
  'blanc':'#f4f1ea','creme':'#f0e6cf','ivoire':'#efe6d2','beige':'#e0cfae',
  'jaune':'#f0dc94','or':'#d9bd6a','dore':'#d9bd6a','moutarde':'#d3b46a',
  'orange':'#e3a366','corail':'#e89a83','saumon':'#eaa893','peche':'#f0c3a3',
  'rouge':'#cf7a73','bordeaux':'#9a5560','framboise':'#d76b86','cerise':'#c76a7e',
  'rose':'#e0a0b8','fuchsia':'#d489a6','magenta':'#cf85a3',
  'violet':'#a78bc0','mauve':'#bca6cf','lavande':'#c4b6dd','parme':'#cdbcd9','prune':'#9a7088',
  'bleu':'#7fa8cf','bleu ciel':'#a7cae6','ciel':'#a7cae6','turquoise':'#7ac3bf','cyan':'#86c2cc',
  'marine':'#5f7196','indigo':'#7681b3','petrole':'#5a8f95','canard':'#5a9197',
  'vert':'#9bc081','vert d eau':'#bcdcca','menthe':'#b4dcc7','olive':'#a8a86e','kaki':'#9a9772','emeraude':'#6aa98c','anis':'#cdd98a','pistache':'#acc792',
  'marron':'#a07a5c','chocolat':'#8a6a52','cafe':'#9a7a5c','caramel':'#cf9a52','noisette':'#c79a6a',
  'gris':'#b0aaa0','argent':'#cfcfcf','anthracite':'#7a7a7a','noir':'#5a5450','taupe':'#b3a594'
};
function _persoNorm(s){ return (s==null?'':String(s)).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z\s]/g,' ').replace(/\s+/g,' ').trim(); }
// Renvoie la teinte d'un nom de couleur libre, ou null si non reconnu.
function couleurNomToHex(nom){
  const n=_persoNorm(nom);
  if(!n) return null;
  if(PERSO_COULEURS[n]) return PERSO_COULEURS[n];
  // Cherche la clé la plus spécifique contenue dans le texte (ex « rose pale » -> « rose »).
  let best=null,bestLen=0;
  for(const k in PERSO_COULEURS){ if((' '+n+' ').includes(' '+k+' ') && k.length>bestLen){ best=PERSO_COULEURS[k]; bestLen=k.length; } }
  if(best) return best;
  // mot à mot
  for(const w of n.split(' ')){ if(PERSO_COULEURS[w]) return PERSO_COULEURS[w]; }
  return null;
}
// Détecte un libellé bicolore et renvoie [hexA, hexB] si deux couleurs sont trouvées, sinon null.
function couleurBicolore(nom){
  // On découpe le texte BRUT sur les séparateurs (/ - + , « et ») AVANT toute
  // normalisation, car _persoNorm retire la ponctuation. On enlève juste « bicolore ».
  const raw=(nom==null?'':String(nom)).replace(/bicolore/ig,' ');
  const parts = raw.split(/\s*(?:\/|\+|\-|,|\bet\b)\s*/i).map(p=>p.trim()).filter(Boolean);
  if(parts.length>=2){
    const a=couleurNomToHex(parts[0]); const b=couleurNomToHex(parts[1]);
    if(a&&b&&a!==b) return [a,b];
  }
  return null;
}
// Génère la pastille HTML : disque plein (une couleur) ou disque coupé VERTICALEMENT
// en deux (bicolore : moitié gauche couleur A, moitié droite couleur B).
// Repli : si rien n'est reconnu, on garde le gris neutre habituel.
function persoPastille(nomCouleur){
  const bi=couleurBicolore(nomCouleur);
  if(bi){
    return `<span class="perso-dot perso-dot-bi" style="background:linear-gradient(90deg, ${bi[0]} 0 50%, ${bi[1]} 50% 100%)"></span>`;
  }
  const hex=couleurNomToHex(nomCouleur) || '#cbb89f';
  return `<span class="perso-dot" style="background:${hex}"></span>`;
}
function factPersoBox(nbPerso, coul){
  // Encadré descriptif : uniquement le détail couleur \u2192 parfum. Le montant de la
  // personnalisation figure désormais comme une LIGNE du tableau (factPersoLigne),
  // donc il entre dans le total brut et subit la remise globale.
  const lignes = Array.isArray(coul) ? coul.filter(c=>c && (c.couleur||c.parfum)) : [];
  if(!lignes.length) return '';
  const items = lignes.map(c=>{
    const parf = c.parfum||'';
    // « Sans personnalisation » (et variantes) : libellé neutre, sans gras.
    const isNS = /sans\s+personnalisation/i.test(parf.normalize('NFD').replace(/[\u0300-\u036f]/g,''));
    const parfCls = isNS ? 'perso-parf perso-parf-ns' : 'perso-parf';
    return `<div class="perso-li">`
      + persoPastille(c.couleur||'')
      + `<span class="perso-coul">${esc(c.couleur||'')}</span>`
      + (parf?`<span class="perso-arr">\u2192</span><span class="${parfCls}">${esc(parf)}</span>`:'')
      + `</div>`;
  }).join('');
  return `<div class="perso-box">`
    + `<div class="perso-titre">\ud83c\udfa8 Personnalisation</div>`
    + items
    + `</div>`;
}
// Ligne de tableau « Personnalisation des couleurs » : n \u00d7 0,25 \u20ac = montant.
// Renvoie '' si pas de macaron personnalisé. Sert au devis et aux factures.
function factPersoLigne(nbPerso, remiseEur, hideRemise){
  const n = Math.max(0, +nbPerso||0);
  if(n<=0) return '';
  const PU = (typeof PERSO_PRIX_UNIT!=='undefined') ? PERSO_PRIX_UNIT : 0.25;
  const brut = money2(n*PU);
  const rem = money2(Math.max(0, Math.min(brut, +remiseEur||0)));
  const desc = `<span class="ln-main">Personnalisation des couleurs</span>`
    + `<span class="ln-sub">${n} macaron${n>1?'s':''} \u00d7 ${euro(money2(PU))}</span>`;
  let out = `<tr><td class="desc">${desc}</td><td class="mt">${euro(brut)}</td></tr>`;
  if(rem>0 && !hideRemise){
    const pct = brut>0 ? Math.max(0, Math.min(100, money2(rem/brut*100))) : 0;
    const sub = `<span class="ln-main" style="color:#3f7d52">Remise personnalisation${pct>0?` (\u2212${pct}%)`:''}</span>`;
    out += `<tr><td class="desc">${sub}</td><td class="mt" style="color:#3f7d52">\u2212${euro(rem)}</td></tr>`;
  }
  return out;
}
// Montant NET de la personnalisation (brut − remise perso). Entre dans le total imposable à la remise globale.
function persoMontant(nbPerso, remiseEur){
  const n = Math.max(0, +nbPerso||0);
  const PU = (typeof PERSO_PRIX_UNIT!=='undefined') ? PERSO_PRIX_UNIT : 0.25;
  const brut = money2(n*PU);
  const rem = money2(Math.max(0, Math.min(brut, +remiseEur||0)));
  return money2(brut - rem);
}
// [REMISE GLOBALE — RÉFÉRENCE EN EUROS FIXES]
// La référence stockée est désormais un MONTANT € (remiseGlobaleEur), qui reste stable même
// si le sous-total change (un « −210 € » reste −210 €, il ne se retransforme pas en « 100 % »
// de ce qu'il reste). Le champ % est un confort de saisie : il DÉRIVE l'euro, sans être figé.
// Rétrocompat : les anciennes commandes/devis n'ont que remiseGlobale (%). La helper ci-dessous
// résout la remise € effective à partir de l'un ou l'autre, en plafonnant à la base imposable.
function globalRemiseEuro(o, base){
  base = money2(+base||0);
  if(o && o.remiseGlobaleEur!=null && +o.remiseGlobaleEur>0){
    return Math.min(base, money2(+o.remiseGlobaleEur));   // euros fixes prioritaires
  }
  const pct = Math.max(0, Math.min(100, +(o&&o.remiseGlobale)||0));
  return money2(base*pct/100);                            // ancien mode % (héritage)
}
// [v1194] SOURCE UNIQUE du total d'une commande, TOUJOURS dérivée des lignes stockées.
// Reproduit à l'identique la formule de saveCmd (base = Σ lignes après remises de ligne
// + personnalisation nette, puis remise globale résolue via globalRemiseEuro). Sert de
// vérité de référence pour détecter les o.montant figés qui auraient divergé (édition par
// un chemin autre que saveCmd : migration, réaffectation, correction HACCP…).
// NB : une commande à PRIX MANUEL (o.prixManuel) peut légitimement s'écarter de ce recalcul
// — c'est un ajustement assumé, PAS une anomalie. Les appelants qui diagnostiquent doivent
// exclure o.prixManuel. Cette fonction NE modifie jamais la commande : lecture seule.
function orderMontantRecalcule(o){
  if(!o) return 0;
  const lignes = Array.isArray(o.lignes) ? o.lignes : [];
  const sousTotal  = money2(lignes.reduce((a,ln)=>a+lineTotalStored(ln),0));
  const persoSup   = money2((+o.persoMacarons||0)*PERSO_PRIX_UNIT);
  const persoRem   = money2(Math.max(0, Math.min(persoSup, +o.persoRemiseEur||0)));
  const persoNette = money2(Math.max(0, persoSup - persoRem));
  const base       = money2(sousTotal + persoNette);
  const remiseG    = globalRemiseEuro(o, base);
  return Math.max(0, money2(base - remiseG));
}
// Écart signé entre le montant stocké et le recalcul. >0 : stocké TROP HAUT ; <0 : trop bas.
// null si la commande est à prix manuel (écart légitime, non diagnosticable).
function _cmdSousTotalAvantGlobal(){
  // base imposable à la remise globale = lignes (après remises de ligne) + personnalisation,
  // cohérente avec cmdRecalc/saveCmd.
  const st = addMoney(...cmdLines.map(ln=>lineTotal(ln)));
  const persoSup = money2((typeof cmdPersoCount==='function'?cmdPersoCount():0)*(typeof PERSO_PRIX_UNIT!=='undefined'?PERSO_PRIX_UNIT:0));
  return money2(st + persoSup);
}
// [REMISE PERSO] Référence canonique en euros fixes (comme la remise globale), plafonnée au
// supplément perso brut (nb macarons × 0,25 €). Le % n'est qu'une saisie alternative synchronisée.
let _cmdPersoRemiseEur = 0;
function _cmdPersoSupBrut(){
  return money2((typeof cmdPersoCount==='function'?cmdPersoCount():0)*(typeof PERSO_PRIX_UNIT!=='undefined'?PERSO_PRIX_UNIT:0));
}
function cmdPersoRemiseFromEuro(){
  const el=document.getElementById('f_persoRemEur');
  let e=money2(+(el&&el.value)||0); if(e<0)e=0;
  const sup=_cmdPersoSupBrut(); if(e>sup) e=sup;
  _cmdPersoRemiseEur=e;
  const p= sup>0 ? Math.max(0,Math.min(100, money2(e/sup*100))) : 0;
  const pctEl=document.getElementById('f_persoRemPct');
  if(pctEl && document.activeElement!==pctEl){ pctEl.value = p>0?p:''; }
  cmdRecalc();
}
function cmdPersoRemiseFromPct(){
  const el=document.getElementById('f_persoRemPct');
  let p=+(el&&el.value)||0; if(p<0)p=0; if(p>100)p=100;
  const sup=_cmdPersoSupBrut();
  const e=money2(sup*p/100);
  _cmdPersoRemiseEur=e;
  const eurEl=document.getElementById('f_persoRemEur');
  if(eurEl && document.activeElement!==eurEl){ eurEl.value = e>0?e:''; }
  cmdRecalc();
}
function cmdGlobalRemiseFromPct(v){
  let p=+v||0; if(p<0)p=0; if(p>100)p=100;
  const st=_cmdSousTotalAvantGlobal();
  const e=money2(st*p/100);
  const eurEl=document.getElementById('f_remisegEur');
  if(eurEl && document.activeElement!==eurEl){ eurEl.value=e>0?e:''; }
  // la référence canonique est l'euro : on la mémorise dès la saisie en %
  _cmdRemiseGlobaleEur = e;
  cmdRecalc();
}
function cmdGlobalRemiseFromEuro(v){
  let e=money2(+v||0); if(e<0)e=0;
  const st=_cmdSousTotalAvantGlobal();
  if(e>st) e=st;
  _cmdRemiseGlobaleEur = e;                               // référence canonique = euros fixes
  const p = st>0 ? Math.max(0,Math.min(100, money2(e/st*100))) : 0;
  const pctEl=document.getElementById('f_remiseg');
  if(pctEl && document.activeElement!==pctEl){ pctEl.value = p>0?p:''; }   // % dérivé, affichage seulement
  cmdRecalc();
}
function cmdRecalc(){
  // [v1216 FIX temps réel] cmdRecalc() est LE point de convergence : il est appelé après chaque
  // modification (via drawLines ou directement par les setXxx montant/remise/quantité). Hors ouverture
  // de commande (_cmdOpening) et hors saisie directe dans le champ prix (f_mt actif), toute invocation
  // signifie « le contenu a changé » → on rebascule le prix en AUTO pour que le total suive en direct.
  // Un prix tapé à la main reste respecté tant que l'utilisateur est dans f_mt ; il ne se re-fige plus
  // définitivement après coup, ce qui était la cause du total qui ne bougeait plus.
  if(!_cmdOpening){
    const _mt0=document.getElementById('f_mt');
    if(_mt0 && document.activeElement!==_mt0 && _mt0.dataset.auto!=='1'){
      _mt0.dataset.auto='1'; _cmdPriceManual=false;
    }
  }
  const sousTotal = addMoney(...cmdLines.map(ln=>lineTotal(ln))); // après remises de ligne
  const persoNb = cmdPersoCount();
  const persoSup = money2(persoNb*PERSO_PRIX_UNIT);
  // [REMISE PERSO] remise en euros fixes plafonnée au supplément perso ; perso nette = sup − remise.
  const persoRem = money2(Math.max(0, Math.min(persoSup, +_cmdPersoRemiseEur||0)));
  const persoNet = money2(Math.max(0, persoSup - persoRem));
  const persoPct = persoSup>0 ? Math.max(0, Math.min(100, money2(persoRem/persoSup*100))) : 0;
  // synchro affichage des deux champs remise perso (sauf celui en cours de saisie)
  const prEurEl=document.getElementById('f_persoRemEur');
  if(prEurEl && document.activeElement!==prEurEl){ prEurEl.value = persoRem>0?persoRem:''; }
  const prPctEl=document.getElementById('f_persoRemPct');
  if(prPctEl && document.activeElement!==prPctEl){ prPctEl.value = persoPct>0?persoPct:''; }
  // La personnalisation (NETTE de sa remise) entre dans la base imposable à la remise globale.
  const baseAvantGlobal = addMoney(sousTotal, persoNet);
  // [REMISE GLOBALE EN EUROS FIXES] La référence est _cmdRemiseGlobaleEur (montant €), plafonnée à la base.
  // On ne la recalcule PAS depuis le % à chaque frappe : elle reste stable même si le sous-total change.
  let remiseGTot = money2(Math.max(0, Math.min(baseAvantGlobal, +_cmdRemiseGlobaleEur||0)));
  // % dérivé (affichage/synchro du champ %), jamais figé.
  const gpct = baseAvantGlobal>0 ? Math.max(0, Math.min(100, money2(remiseGTot/baseAvantGlobal*100))) : 0;
  // garde les deux champs cohérents avec la référence € (sauf celui en cours de saisie)
  const gEurEl=document.getElementById('f_remisegEur');
  if(gEurEl && document.activeElement!==gEurEl){ gEurEl.value = remiseGTot>0?remiseGTot:''; }
  const gPctEl=document.getElementById('f_remiseg');
  if(gPctEl && document.activeElement!==gPctEl){ gPctEl.value = gpct>0?gpct:''; }
  const total = Math.max(0, subMoney(baseAvantGlobal, remiseGTot));
  const mt=document.getElementById('f_mt');
  if(mt && mt.dataset.auto==='1'){ mt.value = total?total.toFixed(2):''; }
  const brk=document.getElementById('priceBreak');
  if(brk){
    if(cmdLines.length || persoNb){
      brk.style.display='block';
      const remiseLignes = addMoney(...cmdLines.map(ln=>lineRemiseEuro(ln)));
      brk.innerHTML =
        `<div style="display:flex;justify-content:space-between"><span>Sous-total (${cmdLines.length} produit(s))</span><b>${euro(addMoney(...cmdLines.map(ln=>lineTotalBase(ln))))}</b></div>`+
        (remiseLignes>0?`<div style="display:flex;justify-content:space-between;color:#3f7d52"><span>Remises de ligne</span><b>−${euro(remiseLignes)}</b></div>`:'')+
        (persoNb>0?`<div style="display:flex;justify-content:space-between;color:var(--caramel)"><span>Personnalisation couleurs (${persoNb}×0,25 €)</span><b>+${euro(persoSup)}</b></div>`:'')+
        (persoRem>0?`<div style="display:flex;justify-content:space-between;color:#3f7d52"><span>Remise perso couleurs${persoPct>0?` (−${persoPct}%)`:''}</span><b>−${euro(persoRem)}</b></div>`:'')+
        (remiseGTot>0?`<div style="display:flex;justify-content:space-between;color:#3f7d52"><span>Remise globale (−${gpct}%)</span><b>−${euro(remiseGTot)}</b></div>`:'')+
        `<div style="display:flex;justify-content:space-between;border-top:1px solid #e8dccd;margin-top:4px;padding-top:4px"><span><b>Total TTC</b></span><b>${euro(total)}</b></div>`;
    } else brk.style.display='none';
  }
  if(typeof cmdUpdatePaySummary==='function') cmdUpdatePaySummary();
  if(typeof cmdDeliveryRecalc==='function') cmdDeliveryRecalc();
  if(typeof cmdRentabiliteRecalc==='function') cmdRentabiliteRecalc();
  if(typeof cmdFeasibilityRecalc==='function') cmdFeasibilityRecalc();
}

// Synchronise les deux champs "heure de livraison" (le champ canonique du haut #f_heure et
// son miroir #f_heureBas dans la section Livraison repliée). fromBas=true quand la saisie vient
// du bas → on écrit en haut, et inversement. Évite toute divergence entre les deux vues.
function cmdSyncHeure(v, fromBas){
  const haut=document.getElementById('f_heure'), bas=document.getElementById('f_heureBas');
  if(fromBas){ if(haut && haut.value!==v) haut.value=v; }
  else { if(bas && bas.value!==v) bas.value=v; }
}

// Verdict instantané de faisabilité de la commande en cours d'édition.
// Combine la demande par parfum (lignes), le stock actuel, la date/heure de
// livraison et le temps réellement disponible (planning bi-hebdomadaire).
let _feasTimer=null, _feasRun=0;
function cmdFeasibilityRecalc(){
  const box=document.getElementById('feasibility'); if(!box) return;
  const date=document.getElementById('f_date')?.value;
  const heure=document.getElementById('f_heure')?.value;
  // demande par parfum à partir des lignes en cours
  let needs={};
  try{ const o={lignes: cmdLinesToStored()}; needs=_orderParfumDemand(o); }catch(e){ needs={}; }
  const totalDemande=Object.values(needs).reduce((s,x)=>s+(+x||0),0);
  if(!date || totalDemande<=0){ box.style.display='none'; return; }
  // feedback immédiat pendant le calcul contextuel (lit stock + planning en base)
  box.style.display='block'; box.style.background='#f6f2ea'; box.style.borderColor='#e0d5c5';
  box.innerHTML='<div class="feas-msg" style="color:#8a7a72">⏳ Analyse de la faisabilité…</div>';
  // debounce + garde anti-résultat périmé (un recalcul plus récent invalide l'ancien)
  const myRun = ++_feasRun;
  if(_feasTimer) clearTimeout(_feasTimer);
  _feasTimer=setTimeout(async()=>{
    let r; try{ r=await assessOrderFeasibility(needs, date, heure); }catch(e){ if(myRun===_feasRun) box.style.display='none'; return; }
    if(myRun!==_feasRun) return;   // périmé : un recalcul plus récent a démarré
    const col = r.statut==='ok' ? 'var(--green,#3f7d52)' : r.statut==='tendu' ? 'var(--caramel,#AA7C39)' : 'var(--red,#b3261e)';
    const bg  = r.statut==='ok' ? '#eef6ee' : r.statut==='tendu' ? '#fbf4e9' : '#fdf3f2';
    let detail='';
    if(!r.stockSuffit && r.statut!=='inconnu'){
      const fmtH = m=>{ const h=Math.floor(m/60), mm=Math.round(m%60); return `${h?h+'h':''}${h?String(mm).padStart(2,'0'):mm+' min'}`; };
      detail=`<div class="feas-meta"><span>🏭 ${r.nbBatchs} batch(s) · ${r.nbMeringues} meringue(s)</span>
        <span>⏱ ${fmtH(r.besoinMin)} requis / ${fmtH(r.dispoMin)} dispo</span></div>`;
    }
    // [ALTERNATIVES] Sur un verdict tendu (🟡) ou infaisable (🔴), si la commande contient un coffret,
    // on propose un accès direct au générateur de compositions alternatives (stock/mutualisé/relance).
    let altLink='';
    if((r.statut==='tendu'||r.statut==='ko')){
      const idxCoffret = (cmdLines||[]).findIndex(ln=>ln && ln.type==='coffret');
      if(idxCoffret>=0){
        altLink=`<div style="margin-top:8px"><button class="btn ghost sm" style="font-size:.82rem" onclick="proposerCompositionLigne(${idxCoffret})">💡 Voir des compositions alternatives</button></div>`;
      }
    }
    box.style.display='block';
    box.style.background=bg; box.style.borderColor=col;
    box.innerHTML=`<div class="feas-msg" style="color:${col}">${r.msg}</div>${detail}${altLink}`;
  }, 250);
}

// Recalcule en direct l'impact de la livraison sur la marge de la commande
// et propose un prix de livraison qui couvre le coût ET préserve le taux de marge.
function cmdDeliveryRecalc(){
  const box=document.getElementById('deliveryImpact'); if(!box) return;
  // commande de travail à partir des lignes en cours + saisies livraison
  const o={
    lignes: cmdLinesToStored(),
    remiseGlobale: Math.max(0,Math.min(100,+(document.getElementById('f_remiseg')?.value)||0)),
    distanceKm: +val('f_distKm')||0,
    prixCarburant: +val('f_carbu')||0,
    tempsLivraisonMin: +val('f_tempsLiv')||0,
    consoVehicule: val('f_conso')!==''?+val('f_conso'):null
  };
  const liv = computeDeliveryCost(o);
  if(!liv.actif){ box.style.display='none'; return; }
  const c=_cmdMarginCache||{};
  const m = computeOrderMargins(o, c.recipes||[], c.recipeItems||[], c.lots||[]);
  const baisse = Math.max(0, m.tauxNet - m.tauxNetApresLiv);
  const defConso = getSettings().vehicleConso;
  box.style.display='flex';
  box.innerHTML =
    `<div style="display:flex;justify-content:space-between"><span>🚚 Coût livraison (A/R ${liv.distAR} km${liv.minutes?` · ${liv.minutes} min`:''})</span><b>${euro(liv.total)}</b></div>`+
    `<div style="display:flex;justify-content:space-between;color:#8a7a72;font-size:.82rem"><span>dont carburant / temps</span><span>${euro(liv.coutCarburant)} · ${euro(liv.coutTemps)}</span></div>`+
    `<div style="display:flex;justify-content:space-between;color:#8a7a72;font-size:.78rem"><span>conso retenue</span><span>${liv.conso} L/100${(o.consoVehicule&&o.consoVehicule!=defConso)?' (réelle)':' (défaut)'}</span></div>`+
    `<div style="display:flex;justify-content:space-between;border-top:1px solid #e8dccd;margin-top:4px;padding-top:4px" title="Marge avant la tournée — point de comparaison, pas le gain réel si tu livres."><span>Marge nette <b>hors</b> livraison <span style="color:#9a8a82">(référence)</span></span><b style="color:#8a7a72">${euro(m.margeNette)} (${m.tauxNet}%)</b></div>`+
    `<div style="display:flex;justify-content:space-between" title="Marge réelle une fois la tournée payée. C'est le chiffre à retenir pour juger la rentabilité."><span>✅ Marge nette <b>après</b> livraison <span style="color:#9a8a82">(à retenir)</span></span><b style="color:${m.margeNetteApresLiv<0?'#b3261e':(baisse>0?'#d98324':'#2e7d32')}">${euro(m.margeNetteApresLiv)} (${m.tauxNetApresLiv}%)</b></div>`+
    (baisse>0?`<div style="display:flex;justify-content:space-between;color:#b3261e;font-size:.82rem"><span>Impact sur le taux de marge</span><b>−${baisse.toFixed(1)} pt</b></div>`:'')+
    (function(){
      // Trois paliers de prix de livraison, du plus généreux au plus protecteur.
      // 1) Carburant seul · 2) Coût réel (carburant + temps) · 3) Coût réel + charges (zéro perte).
      const s=getSettings();
      // Taux de charges sociales moyen pondéré (marchandise/prestation) appliqué à cette commande.
      const partService = m.ca>0 ? (m.caService||0)/m.ca : 0;
      const chargeMoy = (s.socialGoods/100)*(1-partService) + (s.socialService/100)*partService;
      const carburant = liv.coutCarburant;
      const reel = liv.total;
      // Pour que le « zéro perte » soit vraiment neutre, on compense les charges prélevées sur ce qu'on facture.
      const zeroPerte = money2(reel / Math.max(0.0001, 1 - chargeMoy));
      const palier = (label, montant, hint, col)=>
        `<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:5px">
           <div style="font-size:.84rem"><b style="color:${col}">${euro(montant)}</b> <span style="color:#8a7a72">${label}</span>${hint?`<br><span style="color:#a89a90;font-size:.74rem">${hint}</span>`:''}</div>
           <button type="button" class="btn ghost sm" onclick="cmdApplyDeliveryFee(${montant})">Ajouter</button>
         </div>`;
      return `<div style="margin-top:7px;padding-top:7px;border-top:1px dashed #e0d5c5">
          <div style="font-size:.86rem;margin-bottom:2px">💡 Pour préserver ta marge, facture la livraison :</div>
          ${palier('Carburant seul', carburant, 'geste commercial', '#2e7d32')}
          ${palier('Coût réel (carburant + temps)', reel, 'déplacement neutre', '#AA7C39')}
          ${palier('Coût réel + charges', zeroPerte, 'zéro perte après cotisations', 'var(--bordeaux)')}
        </div>`;
    })();
}

// ============================================================================
// RENTABILITÉ EN DIRECT (Commande / Devis) — bloc repliable sous le prix.
// Réutilise EXACTEMENT le même moteur que le bloc livraison (computeOrderMargins)
// et le même cache synchrone (_cmdMarginCache) → source unique de vérité, aucun
// chargement Dexie à la frappe, aucune divergence possible entre les modules.
// L'en-tête (toujours visible) porte le VERDICT 🟢/🟡/🔴 + coût de revient + marge
// nette. Le corps déplié détaille matière / emballage / main-d'œuvre. Fermé par
// défaut. Branché sur cmdRecalc → recalcul instantané à chaque modification.
// ----------------------------------------------------------------------------
// Bascule l'ouverture du bloc (chevron + corps). Ne touche JAMAIS au résumé de
// valeurs (réécrit à chaque frappe par cmdRentabiliteRecalc) : uniquement la
// structure cliquable, pour ne pas entrer en conflit avec le recalcul temps réel.
function cmdRentaToggle(){
  const body = document.getElementById('cmdRentaBody');
  const chev = document.getElementById('cmdRentaChev');
  if(!body) return;
  const open = body.style.display==='none' || !body.style.display;
  body.style.display = open ? 'block' : 'none';
  if(chev) chev.style.transform = open ? 'rotate(90deg)' : 'rotate(0deg)';
}

// Recalcule et affiche la rentabilité de la commande en cours de saisie.
// Draft reconstruit depuis l'état vivant du formulaire (mêmes lignes que la
// livraison + prix/remise/sacs pour un CA net exact). Robuste aux états
// transitoires (formulaire vide, ligne sans parfum) : try/catch + moteur qui
// encaisse un draft incomplet (coût 0). Aucun chiffre « tombé du ciel » : chaque
// poste vient d'un calcul du moteur central, montré dans le décomposé.
function cmdRentabiliteRecalc(){
  const box  = document.getElementById('cmdRentaBox');
  const head = document.getElementById('cmdRentaSum');   // résumé de valeurs (en-tête, hors zone cliquable)
  const body = document.getElementById('cmdRentaBody');
  if(!box || !head) return;
  try{
    const lignes = cmdLinesToStored();
    // Rien de vendable saisi → on masque le bloc (pas de rentabilité à afficher).
    if(!lignes || !lignes.length){ box.style.display='none'; return; }
    box.style.display='block';

    // Prix de vente en cours : le champ « Prix total » (auto ou manuel). Sert de CA
    // de référence au moteur (réconciliation o.montant, cf. computeOrderMargins).
    const montant = money2(+val('f_mt')||0);
    const o = {
      lignes,
      montant,
      remiseGlobale:    Math.max(0,Math.min(100,+(document.getElementById('f_remiseg')?.value)||0)),
      remiseGlobaleEur: Math.max(0, +_cmdRemiseGlobaleEur||0),
      // livraison : mêmes saisies que le bloc livraison (impacte la marge après tournée,
      // pas le coût de revient produit — on n'affiche ici que la marge nette AVANT livraison).
      distanceKm:      +val('f_distKm')||0,
      prixCarburant:   +val('f_carbu')||0,
      tempsLivraisonMin:+val('f_tempsLiv')||0,
      consoVehicule:   val('f_conso')!==''?(+val('f_conso')||0):null,
      fraisLivraison:  (function(){ const mt=document.getElementById('f_mt'); return mt&&mt.dataset.fraisLivraison? +mt.dataset.fraisLivraison : 0; })(),
      sacMatId:        +val('f_sacMat')||0,
      sacNb:           Math.max(0, Math.round(+val('f_sacNb')||0)),
      perso:           !!document.getElementById('f_perso')?.checked,
      persoMacarons:   (typeof cmdPersoCount==='function'?cmdPersoCount():0)
    };

    const c = _cmdMarginCache||{};
    const m = computeOrderMargins(o, c.recipes||[], c.recipeItems||[], c.lots||[]);

    const coutRevient = money2(m.coutMat + m.coutEmb);   // coût complet : matière+conso+MO (coutMat) + emballage
    const coutMO      = +m.coutMOD||0;                    // part main-d'œuvre isolée (incluse dans coutMat)
    const coutMatiere = money2(m.coutMat - coutMO);       // matière + consommables (hors MO)
    const ps          = profitScale(m.tauxNet);           // verdict 🟢/🟡/🔴 sur la marge nette

    // -- EN-TÊTE (toujours visible) : verdict + coût de revient + marge nette --
    const dot = m.tauxNet>=30 ? '🟢' : (m.tauxNet>=15 ? '🟡' : '🔴');
    head.innerHTML =
      `<span style="display:inline-flex;align-items:center;gap:6px">`+
        `<span>${dot}</span>`+
        `<span style="color:#8a7a72">Revient</span> <b>${euro(coutRevient)}</b>`+
        `<span style="color:#cbb9ac">·</span>`+
        `<span style="color:#8a7a72">Marge</span> <b style="color:${ps.col}">${euro(m.margeNette)}</b>`+
        `<span style="color:${ps.col};font-size:.82rem">(${m.tauxNet}%)</span>`+
      `</span>`;

    // -- CORPS (au tap) : décomposé complet, un seul fil de lecture --
    if(body){
      const row = (label, val, opts)=>{
        opts = opts||{};
        return `<div style="display:flex;justify-content:space-between;${opts.top?'border-top:1px solid #e8dccd;margin-top:4px;padding-top:4px;':''}${opts.small?'font-size:.82rem;color:#8a7a72;':''}">`+
               `<span>${label}</span><b style="${opts.col?`color:${opts.col}`:''}">${val}</b></div>`;
      };
      let html = '';
      html += row('Matière + consommables', euro(coutMatiere));
      if(coutMO>0) html += row("Main-d'œuvre (temps réel × taux horaire)", euro(coutMO));
      else         html += row("Main-d'œuvre", '<span style="color:#a89a90;font-weight:400">non mesurée</span>', {small:true});
      html += row('Emballage'+(m.coutEmbEstime>0?' <span style="color:#a89a90;font-weight:400;font-size:.78rem">(dont estimé)</span>':''), euro(m.coutEmb));
      html += row('Coût de revient total', euro(coutRevient), {top:true, col:'var(--bordeaux)'});
      html += row('Prix de vente (net de remises)', euro(m.ca), {top:true});
      html += row('Marge brute', `${euro(m.margeBrute)} (${m.tauxBrut}%)`, {small:true});
      html += row('Charges sociales', '−'+euro(m.chargesSociales), {small:true});
      html += row(`${dot} Marge nette`, `${euro(m.margeNette)} (${m.tauxNet}%)`, {top:true, col:ps.col});
      html += `<div style="margin-top:5px;font-size:.78rem;color:${ps.col}">${ps.label}</div>`;
      // Signal visible : parfums sans recette rattachée → coût partiellement au coût moyen.
      if(m.piecesNonResolues>0){
        html += `<div style="margin-top:6px;padding-top:6px;border-top:1px dashed #e0d5c5;font-size:.78rem;color:#b3261e">`+
                `⚠️ ${m.piecesNonResolues} macaron(s) sans recette rattachée — coût estimé à la moyenne`+
                (m.parfumsNonResolus&&m.parfumsNonResolus.length?` (${m.parfumsNonResolus.map(esc).join(', ')})`:'')+
                `. À corriger dans les recettes pour un coût exact.</div>`;
      }
      body.innerHTML = html;
    }
  }catch(e){
    console.error('cmdRentabiliteRecalc', e);
    if(box) box.style.display='none';
  }
}
// Ajoute le supplément livraison suggéré au prix total de la commande (champ manuel).
// La livraison facturée est ajoutée comme une LIGNE DE PRESTATION « Frais de livraison ».
// Avantages : elle s'affiche clairement sur le devis ET la facture (les lignes prestation
// y sont déjà rendues), elle est comptée comme prestation de service (charges sociales),
// et le montant reste ajustable à la main comme n'importe quelle prestation.
// Si une ligne livraison existe déjà (isLivraison), on la met à jour au lieu d'en empiler.
function cmdApplyDeliveryFee(montant){
  const mt = montant!=null ? money2(+montant||0) : 0;
  if(!(mt>0)){ toast('Montant de livraison invalide'); return; }
  let ln = cmdLines.find(l=>l.type==='prestation' && l.isLivraison);
  if(ln){
    ln.montantHT = mt;
  }else{
    cmdLines.push({type:'prestation', isLivraison:true, libelle:'Frais de livraison',
                   montantHT:mt, remiseType:'pct', remisePct:0, remiseEuro:0});
  }
  // Le prix total redevient AUTO : il intègre la nouvelle ligne via le recalcul normal.
  const mtEl=document.getElementById('f_mt');
  if(mtEl){ mtEl.dataset.auto='1'; delete mtEl.dataset.fraisLivraison; }
  _cmdPriceManual=false;
  drawLines();   // ré-affiche les lignes (la ligne livraison apparaît, éditable)
  cmdRecalc();
  toast(`Livraison ${euro(mt)} ajoutée en prestation`);
}

// [v1394] SOURCE UNIQUE de l'événement-calendrier d'une commande. TOUT chemin qui crée ou
// modifie une commande (saveCmd, docConvertToOrder…) appelle CECI — jamais sa propre logique.
// Ainsi une commande apparaît TOUJOURS au calendrier, sans case ni condition, et il est impossible
// qu'un chemin oublie de la noter. Recrée l'événement (supprime l'ancien d'abord) pour rester
// idempotent : ré-enregistrer une commande ne crée pas de doublon.
async function syncOrderEvent(oid){
  const o = await db.orders.get(oid).catch(()=>null);
  if(!o) return;
  await db.events.where('refId').equals(oid).delete().catch(()=>{});
  const cl = o.clientId ? await db.clients.get(o.clientId).catch(()=>null) : null;
  // Nombre de produits : les lignes vivent dans o.lignes (modèle réel). Repli sur orderItems
  // au cas où un chemin l'utiliserait, mais o.lignes est la source de vérité.
  let nbLignes = Array.isArray(o.lignes) ? o.lignes.length : 0;
  if(!nbLignes){
    try{ nbLignes = (await db.orderItems.where('orderId').equals(oid).toArray()).length; }catch(e){ swallow(e,'syncOrderEvent'); }
  }
  const dateEv = o.dateEvenement || o.date;
  if(!dateEv) return;   // sans date, rien à poser au calendrier (cas limite)
  await db.events.add({
    date: dateEv,
    titre: 'Cmd ' + (cl?cl.nom:'') + ` (${nbLignes} produit${nbLignes>1?'s':''})`,
    type: 'cmd', refId: oid
  }).catch(()=>{});
}

async function saveCmd(id){
  // validations par ligne
  if(!cmdLines.length){ toast('Ajoute au moins un produit'); return; }
  for(const ln of cmdLines){
    if(ln.type==='evenement'){
      if((ln.evQte||0)<EVENT_MIN){ toast(`Événement : minimum ${EVENT_MIN} macarons`); return; }
      if((ln.equip||0)<EVENT_MIN_EQUIP){ toast(`Événement : au moins ${EVENT_MIN_EQUIP} pyramide obligatoire`); return; }
      // [v1079] Si pyramide vendue : un prix de vente > 0 est requis (sinon la vente n'a pas de sens).
      if(ln.pyraVendue && (+ln.pyraPrixVente||0)<=0){ toast('Pyramide vendue : indique un prix de vente'); return; }

      // Parfums : on autorise le partiel. Le « sans parfum déterminé » explicite compte dans le total.
      const totParf=Object.values(ln.parfums||{}).reduce((s,q)=>s+(+q||0),0);
      const totSP=+ln.sansParfum||0;
      const totAttribue=totParf+totSP;          // [v1080] parfums choisis + sans parfum explicite
      if(totAttribue>(ln.evQte||0)){ toast(`Trop de macarons attribués : ${totAttribue} pour ${ln.evQte} (max ${ln.evQte})`); return; }
      // Reste non spécifié = ce qui n'est NI un parfum choisi NI marqué « sans parfum ».
      if(totAttribue>0 && totAttribue<(ln.evQte||0)){
        const reste=(ln.evQte||0)-totAttribue;
        if(!confirm(`${reste} macaron(s) ne sont ni attribués ni marqués « sans parfum ». Ils seront comptés « non spécifié ». Continuer ?`)) return;
      }
    }
    if(ln.type==='grand'){
      const tot=Object.values(ln.items||{}).reduce((s,q)=>s+(+q||0),0);
      if(!tot){ toast('Grand format : sélectionne au moins une pièce'); return; }
    }
    if(ln.type==='coffret' && !ln.taille){ toast('Coffret : choisis une taille'); return; }
    if(ln.type==='sachet'){
      const tot=Object.values(ln.parfums||{}).reduce((s,q)=>s+(+q||0),0) + (+ln.sansParfum||0);
      if(!tot){ toast('Sachet : indique au moins 1 macaron'); return; }
      if(tot>SACHET_MAX){ toast(`Sachet : maximum ${SACHET_MAX} macarons (${tot} indiqués)`); return; }
    }
    if(ln.type==='don'){
      const tot=Object.values(ln.parfums||{}).reduce((s,q)=>s+(+q||0),0)+Object.values(ln.items||{}).reduce((s,q)=>s+(+q||0),0);
      if(!tot){ toast('Don : indique au moins un macaron offert'); return; }
    }
  }
  // normaliser les lignes (parfums/items en tableaux pour stockage propre), remise de ligne conservée
  const lignes = cmdLinesToStored();
  // [REMISE GLOBALE EN EUROS FIXES] La référence est le montant €, plafonné à la base imposable
  // (lignes après remises de ligne + personnalisation). Le % est DÉRIVÉ et stocké pour compat aval.
  const _sousTotalRG = lignes.reduce((a,ln)=>a+lineTotalStored(ln),0);
  const _persoSupRG = money2((typeof cmdPersoCount==='function'?cmdPersoCount():0)*(typeof PERSO_PRIX_UNIT!=='undefined'?PERSO_PRIX_UNIT:0));
  const _persoRemRG = money2(Math.max(0, Math.min(_persoSupRG, +_cmdPersoRemiseEur||0)));
  const _persoRG = money2(Math.max(0, _persoSupRG - _persoRemRG));   // perso NETTE de sa remise
  const _baseRG = money2(_sousTotalRG + _persoRG);
  const remiseGlobaleEur = money2(Math.max(0, Math.min(_baseRG, +_cmdRemiseGlobaleEur||0)));
  const remiseGlobale = _baseRG>0 ? Math.max(0, Math.min(100, money2(remiseGlobaleEur/_baseRG*100))) : 0;
  // Registre de paiements : chaque encaissement exige montant>0 + date + mode. AUCUNE date auto-générée.
  // On considère "entamé" tout encaissement où au moins un champ a été touché.
  const touched = (cmdPayments||[]).filter(p=> (+p.montant)>0 || p.date || p.moyen);
  for(const p of touched){
    if(!((+p.montant)>0)){ toast('Chaque encaissement doit avoir un montant > 0'); return; }
    if(!p.date){ toast('Chaque encaissement doit avoir une date de règlement'); return; }
    if(!p.moyen){ toast('Chaque encaissement doit avoir un mode de paiement'); return; }
  }
  const paiements = touched.map(p=>({ date:p.date, montant:money2(+p.montant||0), moyen:p.moyen }));
  // Montant : on lit le champ « Prix total » (modifiable). Si mode AUTO (pas de prix manuel),
  // on RECALCULE depuis les lignes en appliquant la remise globale EN EUROS FIXES (base − remise €).
  // Si prix manuel (_cmdPriceManual), on respecte la valeur du champ. Filet final : jamais 0 € par accident.
  let montant = money2(+val('f_mt')||0);
  if(!_cmdPriceManual){
    montant = Math.max(0, money2(_baseRG - remiseGlobaleEur));
  }
  if(montant<=0){
    const recalc = Math.max(0, money2(_baseRG - remiseGlobaleEur));
    if(recalc>0) montant = recalc;
  }
  const o={
    clientId:+val('f_cl')||0, date:val('f_date'),
    heureLivraison: val('f_heure')||'', lieuLivraison: val('f_lieu')||'', dateEvenement: val('f_dateEvenement')||'', dateEvtReel: val('f_dateEvtReel')||'',
    distanceKm: +val('f_distKm')||0, prixCarburant: +val('f_carbu')||0, tempsLivraisonMin: +val('f_tempsLiv')||0,
    fraisLivraison: (function(){ const mt=document.getElementById('f_mt'); return mt&&mt.dataset.fraisLivraison? +mt.dataset.fraisLivraison : 0; })(),
    consoVehicule: val('f_conso')!==''?(+val('f_conso')||0):null,
    lignes, remiseGlobale, remiseGlobaleEur,
    perso:document.getElementById('f_perso').checked,
    persoMacarons: cmdPersoCount(),
    persoCouleurs: cmdPersoCoulCollect(),
    persoRemiseEur: _persoRemRG,
    acompteMention: !document.getElementById('f_acompteMention') || document.getElementById('f_acompteMention').checked,
    sacMatId: +val('f_sacMat')||0,                    // modèle de sac choisi (matière emballage usage:'sac'), 0 = aucun
    sacNb: Math.max(0, Math.round(+val('f_sacNb')||0)),// nombre de sacs saisi à la main
    montant,
    paiements,
    dateReglementFinal: val('f_dateFinal')||'',
    statut:val('f_st'), notes:val('f_notes'),
    // [v1407] Rattachement à une commande mère (paiement déjà encaissé ailleurs). Champ absent
    // du formulaire (commande déjà mère, avec des filles) ⇒ on NE TOUCHE PAS à une éventuelle
    // valeur existante, pour ne jamais casser un rattachement en rouvrant/resauvant la fiche.
    ...(document.getElementById('f_commandeMereId')
        ? { commandeMereId: val('f_commandeMereId') ? +val('f_commandeMereId') : null }
        : {}),
    // [v1411] « Commande mère — paiement en avance » : elle est RANGÉE (histo) dès
    // l'enregistrement pour ne pas encombrer le fil des commandes, tout en restant trouvable
    // dans la recherche de mère (cf commandeMereEligible). Décocher la case la fait ressortir.
    // GARDE-FOU : on ne remet histo:false QUE si la case était cochée à l'ouverture — sinon
    // enregistrer une vieille commande archivée (reprise/migration) la ferait resurgir.
    // [v1421] ⚠️ ON N'ÉCRIT PLUS `histo:true` ICI. C'était l'erreur de la v1411 : `histo` ne veut
    // pas dire « rangée », il veut dire REPRISE D'HISTORIQUE (CA d'avant l'app, déjà déclaré).
    // ~30 lecteurs s'en servent pour EXCLURE la commande du chiffre d'affaires : caEncaisseParMois
    // (`if(o.histo) return;`), estReprise → computeMonthlyBilan (qui la classait en « reprise »,
    // hors base URSSAF), computeAccounting, le net dans la poche… Ranger une mère la faisait donc
    // DISPARAÎTRE du CA réel, pendant que ses filles en fabriquaient un faux. L'argent était au
    // mauvais endroit des deux côtés à la fois.
    // Désormais `mereEnAttente` est le SEUL marqueur de rangement : la mère sort du fil des
    // commandes (renderCmd) et n'exige aucune traçabilité, mais elle reste une vente ordinaire
    // pour toute la comptabilité — comptée UNE fois, au mois de son encaissement réel.
    ...(function(){
      const c = document.getElementById('f_mereEnAttente');
      if(!c) return {};
      if(c.checked) return { mereEnAttente: true };
      // Décochée : on lève le rangement, et on efface l'ancien `histo:true` posé par la v1411
      // (uniquement si la case était cochée à l'ouverture — jamais sur une vraie reprise).
      return c.dataset.initial === '1'
        ? { mereEnAttente: false, histo: false }
        : { mereEnAttente: false };
    })(),
    prixManuel: !!_cmdPriceManual,   // mémorise un prix forcé à la main (respecté à la réouverture)
    // on neutralise les anciens champs mono-type
    type:'multi', taille:0, parfums:[], evQte:0, equip:0, tarif:'', bigItems:[]
  };
  // dérive paiement/statutPaiement/soldeDu/montantEncaisse/datePaiement/reglement depuis le registre
  syncPaymentFields(o);
  if(o.montant<0){toast('Le prix ne peut pas être négatif');return;}
  // garde-fou : un encaissement sans date ne doit jamais passer (traçabilité)
  // [v1407] EXCEPTION : une commande fille est réputée « Payé » (cf orderPayStatus) alors qu'elle
  // n'a PAS de datePaiement propre — c'est normal, son encaissement vit sur la commande mère.
  // Sans cette exception, le garde-fou bloquerait toute sauvegarde de sous-commande.
  if(o.commandeMereId==null && orderPayStatus(o)!=='En attente' && !o.datePaiement){ toast('Date de paiement manquante'); return; }
  // === MODE DEVIS : on enregistre dans le registre 'documents', pas dans les commandes ===
  if(_cmdDevisMode){
    const numero = _cmdDevisId ? (await db.documents.get(_cmdDevisId)||{}).numero : await nextDocNumero('devis');
    // [v1269] Validité du devis pilotée par la deadline réelle de la prestation (date de LIVRAISON = o.dateEvenement).
    // Règle : si la livraison est à moins d'UN MOIS calendaire de l'émission, le devis n'est valable
    // que jusqu'à 10 jours AVANT la livraison (au lieu des 30 jours habituels). Au-delà d'un mois pile,
    // on garde la validité normale de 30 jours. Option A : la date de validité ne descend jamais avant
    // la date d'émission — un devis créé à moins de 10 j de la livraison reste valable au moins le jour même.
    const _emis = new Date();
    let exp = new Date(_emis); exp.setDate(exp.getDate()+30);   // défaut : 30 jours
    const _livStr = (o.dateEvenement||'').slice(0,10);
    if(_livStr){
      // Comparaison en JOURS PLEINS (on ignore l'heure) : livraison et seuil ramenés à minuit local.
      const _p = _livStr.split('-');
      const _livJour = new Date(+_p[0], +_p[1]-1, +_p[2]);                 // livraison à 00:00 local
      const _emisJour = new Date(_emis.getFullYear(), _emis.getMonth(), _emis.getDate());
      // Seuil « moins d'un mois » : même quantième un mois plus tard, à minuit.
      // À 1 mois PILE, _livJour === _seuil → NON strictement inférieur → validité normale (30 j) conservée.
      const _seuil = new Date(_emisJour.getFullYear(), _emisJour.getMonth()+1, _emisJour.getDate());
      if(_livJour < _seuil){
        // Validité = livraison − 10 jours, jamais avant l'émission (plafond bas = jour d'émission). [option A]
        const _dixAvant = new Date(_livJour); _dixAvant.setDate(_dixAvant.getDate()-10);
        exp = (_dixAvant < _emisJour) ? _emisJour : _dixAvant;
      }
    }
    // Jours de validité effectifs (émission → expiration), pour que le texte du devis reste exact.
    const _msJour = 24*3600*1000;
    const _emisJour2 = new Date(_emis.getFullYear(), _emis.getMonth(), _emis.getDate());
    const _expJour = new Date(exp.getFullYear(), exp.getMonth(), exp.getDate());
    const _validiteJours = Math.max(0, Math.round((_expJour - _emisJour2)/_msJour));
    const today=_emis;
    const docObj = {
      type:'devis', statut:'en_attente', numero,
      clientId:o.clientId, date:o.date||ymdLocal(today), // [A12]
      montant:o.montant,
      lignes:o.lignes,                      // lignes détaillées (coffrets, pyramides, parfums…)
      remiseGlobale:o.remiseGlobale, remiseGlobaleEur:o.remiseGlobaleEur,
      heureLivraison:o.heureLivraison, lieuLivraison:o.lieuLivraison, dateEvenement:o.dateEvenement||'', dateEvtReel:o.dateEvtReel||'',
      // Livraison (transport) : conservés pour les retrouver à la réouverture et au calcul de coût.
      distanceKm:o.distanceKm||0, prixCarburant:o.prixCarburant||0,
      tempsLivraisonMin:o.tempsLivraisonMin||0, consoVehicule:(o.consoVehicule!=null?o.consoVehicule:null),
      fraisLivraison:o.fraisLivraison||0,
      // Sacs / emballages choisis sur la commande.
      sacMatId:o.sacMatId||0, sacNb:o.sacNb||0,
      // Personnalisation des couleurs : conservée pour l'encadré du devis/facture.
      perso:!!(o.perso||+o.persoMacarons>0), persoMacarons:+o.persoMacarons||0, persoCouleurs:Array.isArray(o.persoCouleurs)?o.persoCouleurs:[], persoRemiseEur:+o.persoRemiseEur||0, acompteMention:(o.acompteMention!==false),
      notes:o.notes,
      acompte: 0,                           // acompte reçu (déclenche la conversion une fois > 0)
      validiteJours:_validiteJours, expiration:ymdLocal(exp), // [v1269] validité pilotée par la deadline de livraison
      orderId:null, createdAt:Date.now()
    };
    if(_cmdDevisId){ await db.documents.update(_cmdDevisId, docObj); }
    else { await db.documents.add(docObj); }
    _cmdDevisMode=false; _cmdDevisId=null;
    closeModal(); toast('Devis '+numero+' enregistré ✓');
    if(view==='documents') renderDocuments();
    return;
  }
  let oid=id;
  // GARDE-FOU LIVRAISON aussi depuis le formulaire d'édition : si l'utilisateur choisit
  // « Livrée » ici, on n'autorise le passage que si la couverture de traçabilité est complète.
  // On écrit d'abord la commande en « Terminée » (pour que les besoins/liens soient lisibles
  // en base), puis on tente le passage en « Livrée » via ensureOrderDecremented.
  // [v1421] Une commande MÈRE rangée ne réclame JAMAIS de traçabilité : ce sont ses filles qui la
  // portent, retrait par retrait. Sans cette exemption, la mère ouvrirait « Lier des batchs » pour
  // la totalité de la commande alors qu'aucun lot ne lui sera jamais rattaché en propre.
  const _wantLivree = (o.statut==='Livrée') && (o.histo!==true) && (o.mereEnAttente!==true);
  if(_wantLivree) o.statut = 'Terminée';
  if(id) await db.orders.update(id,o); else oid=await db.orders.add(withSync(o,'app'));
  if(_wantLivree){
    const ok = await ensureOrderDecremented(oid);
    if(ok){ await db.orders.update(oid, {statut:'Livrée'}); }
    // si !ok : la commande reste « Terminée » et ensureOrderDecremented a ouvert « Lier des batchs ».
  }
  // [v1421] ARCHIVAGE AUTOMATIQUE DE LA MÈRE — demande de Ben : « une commande, lorsqu'elle est
  // définie comme commande mère, ne doit pas rester dans la vue commande ». Jusqu'ici le rangement
  // dépendait de la case v1411 : une mère créée en rattachant simplement une fille (le geste
  // naturel, sans passer par la case) restait dans le fil et réclamait sa traçabilité.
  // Désormais, enregistrer une fille range sa mère, quel que soit le chemin. On ne repasse jamais
  // dessus si elle est déjà rangée (on n'écrase pas un choix de Ben qui l'aurait ressortie).
  let _mereRangee = 0;
  if(o.commandeMereId!=null){
    try{
      const _mere = await db.orders.get(+o.commandeMereId);
      if(_mere && _mere.mereEnAttente!==true){
        await db.orders.update(+_mere.id, {mereEnAttente:true});
        _mereRangee = +_mere.id;
      }
    }catch(e){ swallow(e,'archivage auto commande mère'); }   // jamais bloquer l'enregistrement pour ça
  }
  // [v1377] Devis accepté lié à cette commande : le marquer « périmé » si le contenu ne correspond
  // plus (lignes ou montant), ou lever le drapeau s'il correspond de nouveau (ex : après régénération).
  // On ne touche JAMAIS au contenu du devis — juste le signal. Ben régénère et renvoie quand il veut.
  if(id){
    try{
      const dvs = (await db.documents.toArray()).filter(x => x.type === 'devis' && x.orderId === id);
      for(const dv of dvs){
        const per = _devisPerime(dv, o);
        if(!!dv.perimeCommande !== per) await db.documents.update(dv.id, { perimeCommande: per });
      }
    }catch(e){ swallow(e, 'perime devis'); }
  }
  markUnsaved();
  // calendrier : recréer l'événement lié
  // [v1394] CALENDRIER AUTOMATIQUE via la source unique. Chaque commande apparaît TOUJOURS au
  // calendrier, sans condition ni case. L'ancien code dépendait de getElementById('f_cal').checked
  // — donc de la présence de la case dans le DOM au moment de la sauvegarde ; par un chemin sans
  // formulaire affiché, cb était null → aucun événement, même case « cochée ». C'était la cause des
  // commandes cochées mais absentes. syncOrderEvent recrée l'événement systématiquement.
  await syncOrderEvent(oid);
  // [v1382] La commande vient d'être écrite : si Ben a chiffré ou corrigé le trajet, le carnet
  // doit l'apprendre TOUT DE SUITE. Sans ça, il proposerait encore l'ancienne médiane.
  if(typeof _trajetInvalideCache==='function') _trajetInvalideCache();
  // [v1421] Le rangement de la mère est une décision de l'app : on le DIT. Une action invisible
  // sur les commandes de Ben, c'est une action qu'il découvrira trop tard, en cherchant sa mère
  // dans un fil où elle n'est plus.
  closeModal(); renderCmd();
  toast(_mereRangee ? ('Commande enregistrée ✓ · commande mère #'+_mereRangee+' rangée') : 'Commande enregistrée ✓');
  // Vérification prévisionnelle immédiate : la commande crée-t-elle un risque sous 8 jours ?
  // [v1087] protégé : une erreur de prévisionnel ne doit JAMAIS faire croire que l'enregistrement a échoué.
  try{ await checkForecastForOrder(oid); }catch(e){ console.error('checkForecastForOrder', e); }
}

// Contrôle ciblé après création/modif : alerte si CETTE commande (livraison < 8 j) est en stock insuffisant.
async function checkForecastForOrder(orderId){
  try{
    const o = await db.orders.get(orderId);
    if(!o || !o.date) return;
    const dans = daysTo(o.date);
    if(dans===null || dans>=8 || normStatus(o.statut)==='Livrée') return; // hors fenêtre d'alerte
    const f = await computeForecast({horizon:8, skipFaisabilite:true});
    const dem = _orderParfumDemand(o);
    // y a-t-il un parfum de cette commande en rupture prévisionnelle ?
    const concernes = f.lignes.filter(l=> dem[l.parfum] && l.soldePrev<0);
    if(!concernes.length) return;
    const lignes = concernes.map(l=>`<div class="sum-box"><span>⚠ <b>${esc(l.parfum)}</b></span><b style="color:var(--red,#b3261e)">manque ${qty(l.manque)}</b></div>`).join('');
    openModal(`<h3>⚠ Stock insuffisant pour cette commande</h3>
      <p class="note">Livraison ${dans<=0?"aujourd'hui":'dans '+dans+' jour(s)'} (${fmtDate(o.date)}). Le stock fini actuel ne couvre pas les commandes à venir pour :</p>
      ${lignes}
      <div class="modal-actions">
        <button class="btn ghost" onclick="closeModal()">OK</button>
        <button class="btn gold" onclick="closeModal();view='previsionnel';setActiveView&&setActiveView('previsionnel');renderForecast()">Voir le prévisionnel</button>
      </div>`);
  }catch(e){ /* silencieux */ }
}
// Suppression de commande avec RAISON obligatoire (confirmation explicite).
const DELETE_REASONS_ORDER = ['Annulation client','Erreur de saisie','Doublon','Non honorée','Report / remplacée','Autre'];
const DELETE_REASONS_PROD = ['Erreur de saisie','Ratée / non conforme','Doublon','Test / essai','Périmée','Autre'];
async function cmdDelete(id){
  const o=await db.orders.get(id); if(!o){ toast('Commande introuvable'); return; }
  const items = await db.orderItems.where('orderId').equals(id).toArray();
  const totBatch = items.reduce((s,it)=>s+(+it.qte||0),0);
  const cl = o.clientId ? await db.clients.get(o.clientId) : null;
  const opts = DELETE_REASONS_ORDER.map(r=>`<option>${esc(r)}</option>`).join('');
  openModal(`<h3>🗑 Supprimer la commande</h3>
    <p style="margin-bottom:8px">${cl?`<b>${esc(cl.nom)}</b> · `:''}${fmtDate(o.date)} · ${euro(o.montant)}</p>
    ${totBatch?`<div class="banner">↩ <div>${totBatch} macaron(s) de batch(s) lié(s) seront <b>recrédités au stock</b>.</div></div>`:''}
    ${o.pkgDecremented===true?`<div class="banner">📦 <div>Les <b>emballages</b> de cette commande (boîtes / sacs) seront <b>recrédités au stock</b>.</div></div>`:''}
    <div class="field"><label>Raison de la suppression *</label><select id="f_delReason">${opts}</select></div>
    <div class="field"><label>Précision (facultatif)</label><input id="f_delNote" placeholder="détail…"></div>
    <p class="note">La suppression est définitive. La raison est enregistrée dans le journal des suppressions.</p>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn danger" onclick="cmdDeleteConfirm(${id})">Confirmer la suppression</button></div>`);
}
async function cmdDeleteConfirm(id){
  const reason=val('f_delReason')||DELETE_REASONS_ORDER[0];
  const note=val('f_delNote')||'';
  const o=await db.orders.get(id);

  // ════════════════════════════════════════════════════════════════════════
  // [v1359] VERROU LÉGAL — INALTÉRABILITÉ DES ENCAISSEMENTS (art. 286-I-3° bis CGI, NF525).
  //
  // C'ÉTAIT LE TROU. Cette fonction supprimait la commande AVEC ses paiements. `logDeletion`
  // gardait une trace dans localStorage, mais L'ENCAISSEMENT DISPARAISSAIT DE LA COMPTABILITÉ :
  // le CA du mois changeait rétroactivement, sans écriture inverse, sans piste d'audit.
  //
  // Une commande SANS encaissement reste librement supprimable (décision de Ben : rien n'a été
  // encaissé, il n'y a rien à protéger). Le verrou ne se déclenche QUE s'il y a de l'argent.
  //
  // RÈGLE GRAVÉE (v1359) : ON NE SUPPRIME PAS UN ENCAISSEMENT. ON LE CONTREPASSE.
  // ════════════════════════════════════════════════════════════════════════
  const _blocage = blocageSuppressionEncaissement(o);
  if(_blocage){
    closeModal();
    openModal(`<h3>🔒 Suppression impossible</h3>
      <p class="note" style="color:#b3261e">${_blocage.message}</p>
      <div class="modal-actions">
        <button class="btn ghost" onclick="closeModal()">Fermer</button>
        <button class="btn" onclick="closeModal(); corrigerEncaissementForm(${id})">Corriger un encaissement</button>
      </div>`);
    return;
  }
  const items = await db.orderItems.where('orderId').equals(id).toArray();
  const evs = await db.events.where('refId').equals(id).toArray().catch(()=>[]);
  const totBatch = items.reduce((s,it)=>s+(+it.qte||0),0);
  // Emballages à restituer (seulement si le décompte avait bien eu lieu sur cette commande).
  // On résout les materialId AVANT la transaction (lire db.materials dedans est interdit).
  const embRestock = [];   // [{materialId, nb}]
  if(o && o.pkgDecremented===true){
    const _allMats = await db.materials.toArray();
    const pack = orderPackaging(o);
    for(const taille in pack.boxes){
      const nb=+pack.boxes[taille]||0; if(nb<=0) continue;
      const mat=_allMats.find(m=>m.categorie==='emballage' && +m.capacite===+taille);
      if(mat) embRestock.push({materialId:mat.id, nb});
    }
    if(+o.sacMatId>0 && +o.sacNb>0) embRestock.push({materialId:+o.sacMatId, nb:+o.sacNb});
    (o.lignes||[]).forEach(ln=>{ if(ln && ln.type==='don' && +ln.sacMatId>0 && +ln.sacNb>0) embRestock.push({materialId:+ln.sacMatId, nb:+ln.sacNb}); });
  }
  // snapshot pour annulation
  const snap = { order:o?{...o}:null, items:items.map(x=>({...x})), events:evs.map(e=>({...e})), embRestock:embRestock.map(x=>({...x})) };
  const _recCacheDel = await db.recipes.toArray().catch(()=>[]);
  const _mvRestock=[]; // [JOURNAL STOCK] recrédits à journaliser hors transaction
  await db.transaction('rw',db.orders,db.orderItems,db.productions,db.events,db.materialLots,async()=>{
    for(const it of items){
      const prod = await db.productions.get(it.productionId);
      if(prod){
        await db.productions.update(prod.id,{qteRestante: addQty(prod.qteRestante, it.qte)});
        _mvRestock.push({ parfumNom: prodNomComplet(prod, _recCacheDel), composant:'macaron', sens:+1,
          qte:round3(+it.qte||0), type:'recredit', productionId:prod.id, orderId:id, note:'suppression commande' });
      }
    }
    // re-crédit des emballages (boîtes + sac)
    for(const e of embRestock){ await restockLotsByMaterial(e.materialId, e.nb); }
    await db.orderItems.where('orderId').equals(id).delete();
    await db.events.where('refId').equals(id).delete();
    await db.orders.delete(id);
  });
  // [JOURNAL STOCK] recrédite le stock fini des batchs liés (commande supprimée).
  for(const mv of _mvRestock){ await logStockMove(mv); }
  logDeletion('commande', id, reason, note, o?`${fmtDate(o.date)} · ${euro(o.montant)}`:'');
  try{ await db.packagingConsumption.where('orderId').equals(id).delete(); }catch(e){swallow(e,'cmdDeleteConfirm')}
  closeModal(); renderCmd();
  // annulation rapide : restaure la commande, ses liens, son événement, et ré-décrémente le stock
  showUndoToast(totBatch?`Commande supprimée — ${totBatch} recrédité(s)`:'Commande supprimée', async ()=>{
    const _mvUndo=[];
    await db.transaction('rw',db.orders,db.orderItems,db.productions,db.events,db.materialLots,async()=>{
      if(snap.order) await db.orders.put(snap.order);
      for(const it of snap.items){ await db.orderItems.put(it);
        const prod=await db.productions.get(it.productionId);
        if(prod){
          await db.productions.update(prod.id,{qteRestante: subQty(prod.qteRestante, it.qte)});
          _mvUndo.push({ parfumNom: prodNomComplet(prod, _recCacheDel), composant:'macaron', sens:-1,
            qte:round3(+it.qte||0), type:'recredit', productionId:prod.id, orderId:id, note:'annulation suppression (undo)' });
        } }
      // ré-décrémente les emballages recrédités (on annule la restitution)
      for(const e of (snap.embRestock||[])){ await decrementLotsByMaterial(e.materialId, e.nb); }
      for(const e of snap.events){ await db.events.put(e); }
    });
    // [JOURNAL STOCK] miroir : l'undo annule le recrédit (re-sortie du stock).
    for(const mv of _mvUndo){ await logStockMove(mv); }
    renderCmd();
  });
}
// Journal léger des suppressions (localStorage, pour mémoire/traçabilité interne).
// ════════════════════════════════════════════════════════════════════════════
//  [v1359] INALTÉRABILITÉ DES ENCAISSEMENTS — exigence légale
//
//  Ben : « Tu empêches toute suppression de montant encaissé. Et tu proposes une correction avec
//  journal de suivi en cas d'erreur. On doit aussi pouvoir exporter facilement un historique
//  reprenant tous les encaissements sur une période donnée. »
//
//  LE CADRE : article 286-I-3° bis du CGI (inaltérabilité, sécurisation, conservation, archivage
//  des données de règlement) et norme NF525. UN ENCAISSEMENT ENREGISTRÉ NE PEUT PAS DISPARAÎTRE.
//  Il ne peut qu'être ANNULÉ par une écriture INVERSE, elle-même tracée. C'est le principe de
//  l'écriture comptable : on ne gomme pas, on contrepasse.
//
//  CE QUE J'AI TROUVÉ EN AUDITANT LE CODE (et qui est plus grave que ce que Ben soupçonnait) :
//
//   1. Il n'existe AUCUN bouton pour supprimer un paiement — bonne nouvelle, mais…
//   2. `db.orders.delete()` est appelé à TROIS endroits. Supprimer une commande ENCAISSÉE
//      efface ses paiements AVEC elle. L'argent encaissé disparaît de la comptabilité.
//   3. Pire : ligne 8615 (« repasser en devis ») supprime la commande SANS AUCUN JOURNAL.
//      Une commande payée repassée en devis = un encaissement évaporé, sans trace.
//
//  RÈGLE GRAVÉE (v1359) : ON NE SUPPRIME PAS UN ENCAISSEMENT. ON LE CONTREPASSE.
//  Une donnée comptable effacée est une donnée qu'aucun contrôle ne peut reconstituer — et
//  l'absence de trace ne prouve pas l'absence de fraude : elle EST le problème.
// ════════════════════════════════════════════════════════════════════════════

// ---------------------------------------------------------------------------
// LE VERROU. Toute commande portant au moins un encaissement est INSUPPRIMABLE.
// Renvoie null si la suppression est permise, sinon le motif du refus.
// ---------------------------------------------------------------------------
function encaissementsDe(o){
  if(!o || !Array.isArray(o.paiements)) return [];
  return o.paiements.filter(p => p && (+p.montant) > 0);
}

function totalEncaisseDe(o){
  return money2(encaissementsDe(o).reduce((s, p) => s + (+p.montant || 0), 0));
}

// [v1359] LE GARDE-FOU CENTRAL. Appelé AVANT tout db.orders.delete().
// Un seul point de contrôle : si je le duplique, une des copies finira par diverger (règle v1358).
function blocageSuppressionEncaissement(o){
  const enc = encaissementsDe(o);
  if(!enc.length) return null;   // aucun encaissement → suppression libre
  const total = totalEncaisseDe(o);
  return {
    nb: enc.length,
    total,
    // Le message dit POURQUOI, et propose la SORTIE LÉGALE — un blocage sans échappatoire
    // pousse à contourner l'outil (règle v1357).
    message: `Cette commande porte <b>${enc.length} encaissement(s)</b> pour <b>${euro(total)}</b>.<br><br>
      La loi (art. 286-I-3° bis du CGI) interdit de <b>supprimer</b> une donnée de règlement enregistrée.
      Un encaissement ne s'efface pas : il se <b>contrepasse</b> par une écriture inverse, tracée et datée.<br><br>
      Si tu as fait une erreur, utilise <b>« Corriger un encaissement »</b> : l'écriture d'origine reste,
      une écriture d'annulation s'y ajoute, et le journal en garde la preuve.`
  };
}

// ---------------------------------------------------------------------------
// LA CORRECTION TRACÉE. On n'efface JAMAIS l'écriture d'origine : on ajoute une écriture
// d'annulation (montant négatif) qui la neutralise, plus une écriture corrective si besoin.
//
// C'est EXACTEMENT le mécanisme de la contrepassation comptable. Le solde final est juste, et
// l'historique complet reste lisible : on voit l'erreur ET sa correction. C'est ce que demande
// un contrôle fiscal — pas un registre propre, un registre HONNÊTE.
// ---------------------------------------------------------------------------
async function corrigerEncaissement(orderId, index, nouveauMontant, motif){
  const o = await db.orders.get(+orderId);
  if(!o){ toast('Commande introuvable'); return false; }
  const paiements = Array.isArray(o.paiements) ? o.paiements.slice() : [];
  const orig = paiements[+index];
  if(!orig){ toast('Encaissement introuvable'); return false; }
  if(orig.annule){ toast('Cet encaissement est déjà annulé'); return false; }

  const m = (motif || '').trim();
  if(!m){ toast('Motif obligatoire'); return false; }   // sans motif, la trace ne vaut rien

  const ancien = money2(+orig.montant || 0);
  const neuf   = (nouveauMontant == null || nouveauMontant === '') ? 0 : money2(+nouveauMontant);
  if(neuf < 0){ toast('Montant négatif impossible'); return false; }
  if(neuf === ancien){ toast('Le montant est inchangé'); return false; }

  const ts = new Date().toISOString();

  // [v1359] L'ÉCRITURE D'ORIGINE EST CONSERVÉE À L'IDENTIQUE. On la MARQUE annulée — on ne la
  // modifie pas, on ne la retire pas. Le montant reste celui qui a été saisi ce jour-là.
  paiements[+index] = Object.assign({}, orig, { annule:true, annuleTs:ts, annuleMotif:m });

  // L'écriture d'ANNULATION : montant négatif, égal et opposé. Le solde redevient exact.
  paiements.push({
    date: today(), montant: -ancien, moyen: orig.moyen || null,
    correction: true, corrigeIndex: +index, motif: m, ts,
    libelle: `Annulation de l'encaissement du ${fmtDate(orig.date || o.date)}`
  });

  // L'écriture CORRECTIVE, si Ben a saisi un nouveau montant (une correction, pas une annulation sèche).
  if(neuf > 0){
    paiements.push({
      date: today(), montant: neuf, moyen: orig.moyen || null,
      correction: true, corrigeIndex: +index, motif: m, ts,
      libelle: `Correction : ${euro(ancien)} → ${euro(neuf)}`
    });
  }

  const o2 = Object.assign({}, o, { paiements });
  syncPaymentFields(o2);

  await db.orders.update(+orderId, {
    paiements: o2.paiements,
    paiement: o2.paiement, statutPaiement: o2.statutPaiement,
    soldeDu: o2.soldeDu, montantEncaisse: o2.montantEncaisse
  });

  // [v1359] LE JOURNAL COMPTABLE — en BASE, jamais en localStorage.
  //
  // `logDeletion` (qui existe déjà) écrit dans `localStorage`. Pour une trace LÉGALE, c'est
  // inacceptable : vider le cache du navigateur effacerait la preuve. Une trace qu'un geste
  // anodin peut détruire n'est pas une trace — c'est une illusion de trace.
  //
  // On écrit donc dans `db.journalCompta`, qui part dans les sauvegardes avec le reste des
  // données comptables. AUCUNE fonction de l'app ne supprime de ligne de cette table.
  try{
    await db.journalCompta.add({
      orderId: +orderId,
      type: (neuf > 0 ? 'correction' : 'annulation'),
      ts,
      dateOrigine: orig.date || o.date || null,
      montantAvant: ancien,
      montantApres: neuf,
      moyen: orig.moyen || null,
      motif: m,
      commandeRef: (typeof orderNumber === 'function') ? orderNumber(o) : ('#' + orderId)
    });
  }catch(e){
    // [v1359] Si le journal échoue, on ANNULE TOUT. Une correction sans trace est exactement ce
    // que la loi interdit — mieux vaut refuser la correction que de la faire sans preuve.
    swallow(e, 'corrigerEncaissement journal');
    await db.orders.update(+orderId, { paiements: o.paiements });   // restaure l'état d'origine
    toast('Journal indisponible — correction annulée');
    return false;
  }

  toast(`Encaissement corrigé ✓ (écriture d'annulation tracée)`);
  return true;
}

// ════════════════════════════════════════════════════════════════════════════
// ---------------------------------------------------------------------------
// [v1359] L'UI DE CORRECTION. Liste les encaissements d'une commande et permet de corriger
// celui qui est erroné — avec MOTIF OBLIGATOIRE (sans motif, la trace ne vaut rien).
// ---------------------------------------------------------------------------
async function corrigerEncaissementForm(orderId){
  const o = await db.orders.get(+orderId);
  if(!o){ toast('Commande introuvable'); return; }
  const paiements = Array.isArray(o.paiements) ? o.paiements : [];
  const reels = paiements.map((p, i) => ({ p, i })).filter(x => x.p && (+x.p.montant) > 0 && !x.p.correction);

  if(!reels.length){ toast('Aucun encaissement à corriger'); return; }

  const lignes = reels.map(({p, i}) => {
    const annule = !!p.annule;
    return `<div class="sum-box" style="flex-direction:column;align-items:flex-start;gap:2px;${annule?'opacity:.5':''}">
      <div style="display:flex;justify-content:space-between;width:100%">
        <span><b>${euro(+p.montant)}</b> · ${esc(p.moyen || '—')}</span>
        <span style="font-size:.78rem;color:#9a8a82">${esc(fmtDate(p.date || o.date))}</span>
      </div>
      ${annule
        ? `<span style="font-size:.74rem;color:#b3261e">ANNULÉ — ${esc(p.annuleMotif || '')}</span>`
        : `<button class="btn ghost sm" style="font-size:.76rem;margin-top:4px" onclick="corrigerEncaissementSaisie(${orderId},${i})">Corriger</button>`}
    </div>`;
  }).join('');

  openModal(`<h3>🧾 Corriger un encaissement</h3>
    <p class="note">L'écriture d'origine <b>ne sera pas supprimée</b>. Une écriture d'annulation s'y ajoutera,
    et le journal comptable en gardera la preuve — c'est ce qu'exige la loi.</p>
    ${lignes}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}

function corrigerEncaissementSaisie(orderId, index){
  openModal(`<h3>🧾 Correction</h3>
    <div class="field"><label>Nouveau montant (0 = annulation pure)</label>
      <input type="number" step="0.01" min="0" id="ce_montant" placeholder="ex : 45.00"></div>
    <div class="field"><label>Motif <b style="color:#b3261e">*</b></label>
      <input id="ce_motif" placeholder="ex : erreur de saisie, chèque impayé…"></div>
    <p class="note" style="font-size:.76rem">Le motif est <b>obligatoire</b> : une correction sans justification
    n'a aucune valeur probante devant un contrôle.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="corrigerEncaissementValider(${orderId},${index})">Enregistrer la correction</button>
    </div>`);
}

async function corrigerEncaissementValider(orderId, index){
  const montant = val('ce_montant');
  const motif = val('ce_motif');
  const ok = await corrigerEncaissement(+orderId, +index, montant, motif);
  if(ok){
    closeModal();
    if(typeof renderCmd === 'function') renderCmd();
  }
}

// ---------------------------------------------------------------------------
// ════════════════════════════════════════════════════════════════════════════
//  [v1360] LE LIVRE DES RECETTES — complet, chaîné, vérifiable
//
//  Ben : « Je veux avoir quelque chose de très solide à montrer en cas de contrôle, sans
//  contestation possible. »
//
//  ⚠️ CE QUE JE NE PEUX PAS PROMETTRE, ET QUE JE LUI AI DIT :
//  « sans contestation possible » suppose une CERTIFICATION NF525, délivrée par un organisme
//  accrédité (AFNOR, LNE) — pas par du code. Je ne peux pas la fabriquer.
//
//  CE QUE JE PEUX FAIRE, ET QUI EST FAIT ICI : un registre COMPLET, COHÉRENT et TECHNIQUEMENT
//  INALTÉRABLE — au point qu'une contestation devrait porter sur la certification, jamais sur
//  les données elles-mêmes.
//
//  ═══ LE DÉFAUT QUI INVALIDAIT TOUT (v1359) ═══
//  Mon export ne lisait que `db.orders`. LES VENTES MARCHÉ N'Y ÉTAIENT PAS.
//  Un livre des recettes qui omet un canal de vente entier n'est pas incomplet : il est FAUX.
//  Et l'incomplétude est précisément ce qu'un contrôle cherche.
//
//  C'est la MÊME faute que la v1336 (les marchés oubliés du CA) et la v1355 (les marchés absents
//  des volumes). Troisième fois. Le canal marché est mon angle mort structurel : il ne passe pas
//  par `orders`, donc je l'oublie à chaque fois que je pars des commandes.
//
//  RÈGLE GRAVÉE (v1360) : QUAND JE PARS DE `db.orders`, JE DOIS ME DEMANDER OÙ SONT LES MARCHÉS.
//  Ce n'est plus une erreur, c'est un réflexe manquant.
// ════════════════════════════════════════════════════════════════════════════

// ---------------------------------------------------------------------------
// LE CHAÎNAGE D'INTÉGRITÉ. Chaque écriture porte le hash de la précédente.
//
// CE QUE ÇA APPORTE : toute modification a posteriori d'une ligne CASSE la chaîne, et devient
// DÉTECTABLE. On ne peut pas retirer discrètement une recette : le hash suivant ne correspondrait
// plus. C'est le principe du registre chaîné (art. 286-I-3° bis : « inaltérabilité »).
//
// CE QUE ÇA N'APPORTE PAS, ET JE LE DIS : ce n'est PAS une certification NF525. Un tiers
// malveillant ayant accès au code pourrait recalculer toute la chaîne. Ça rend l'altération
// DÉTECTABLE, pas IMPOSSIBLE — et c'est déjà considérable pour un registre de micro-entreprise.
// Prétendre le contraire serait le genre de mensonge que cette série entière traque.
// ---------------------------------------------------------------------------
function _lrHash(str){
  // FNV-1a 32 bits, doublé sur deux graines pour réduire les collisions. Pas de dépendance
  // externe (l'app est hors-ligne), pas de crypto-API (indisponible en contexte non sécurisé).
  let h1 = 0x811c9dc5, h2 = 0x01000193;
  for(let i = 0; i < str.length; i++){
    const c = str.charCodeAt(i);
    h1 ^= c; h1 = Math.imul(h1, 0x01000193);
    h2 ^= c; h2 = Math.imul(h2, 0x85ebca6b);
  }
  const u = n => (n >>> 0).toString(16).padStart(8, '0');
  return u(h1) + u(h2);
}

// Le hash d'une ligne = hash(contenu de la ligne + hash de la ligne précédente).
// C'est ce lien qui rend la chaîne infalsifiable ligne à ligne.
function _lrHashLigne(l, hashPrec){
  const socle = [
    l.date, l.piece, l.client, String(l.montant), l.moyen, l.nature, l.statut, l.motif || ''
  ].join('|');
  return _lrHash(socle + '|' + (hashPrec || 'GENESE'));
}

// ---------------------------------------------------------------------------
// LE LIVRE DES RECETTES. Toutes les recettes, TOUS CANAUX, triées par date.
//
// MENTIONS OBLIGATOIRES (art. L102 B du LPF, art. 286-I-3° du CGI) :
//   • date · montant · mode de règlement · identité du client
//   • référence de la pièce justificative · nature de la prestation
// ---------------------------------------------------------------------------
async function livreDesRecettes(depuis, jusqu){
  const lignes = [];

  // ════════════════════════════════════════════════════════════════════════
  // [v1366] NORMALISATION DU MOYEN DE PAIEMENT — un seul libellé par moyen réel.
  //
  // DEUX BUGS que Ben a vus dans son livre, et qui ont la MÊME nature : un moyen de paiement
  // écrit sous plusieurs formes finit ventilé en plusieurs colonnes, alors que c'est le même.
  //
  //  1. « Carte bancaire » (ma faute v1360, sur les marchés) VS « Carte » (partout ailleurs,
  //     PAY_METHODS). Deux libellés, un seul moyen → deux lignes au lieu d'une.
  //
  //  2. « Acompte » qui réapparaît dans la colonne MOYEN. Le v1362 neutralisait `p.moyen==='Acompte'`,
  //     mais PAS `o.reglement`. Sur les vieilles commandes converties, `o.reglement` valait lui-même
  //     « Acompte » : en repli, « Acompte » revenait par la fenêtre. Un statut, JAMAIS un moyen (v1362).
  //
  // RÈGLE (v1366) : un même moyen n'a qu'UN libellé. La normalisation se fait À LA LECTURE — sinon
  // l'historique déjà enregistré resterait scindé, même après correction de l'écriture.
  const _normMoyen = (m) => {
    const v = (m == null ? '' : String(m)).trim();
    if(!v) return null;
    // « Acompte » est un STATUT, pas un moyen : il ne doit jamais peupler la colonne moyen.
    if(/^acompte$/i.test(v)) return null;
    // Un seul libellé pour la carte, quel que soit le canal.
    if(/^carte(\s+bancaire)?$/i.test(v) || /^cb$/i.test(v)) return 'Carte';
    return v;
  };

  // ═══ CANAL 1 : LES COMMANDES ═══
  const orders  = await db.orders.toArray().catch(() => []);
  const clients = await db.clients.toArray().catch(() => []);
  const nomClient = id => {
    const c = clients.find(x => +x.id === +id);
    return c ? (c.nom || '') : '';
  };

  (orders || []).forEach(o => {
    if(!o) return;
    // [v1421] COMMANDE FILLE : la recette a DÉJÀ été inscrite au livre, à la ligne de sa mère, au
    // jour de l'encaissement réel. La réinscrire au jour du retrait ajouterait une recette qui
    // n'existe pas — le livre gonflerait au-delà des déclarations, et l'écart sauterait aux yeux
    // d'un contrôleur. Ce n'est PAS une exclusion comptable au sens de la v1361 (rien n'est
    // dissimulé : la recette EST au livre, une seule fois, à sa vraie date) — c'est un anti-doublon.
    if(o.commandeMereId != null) return;

    // ════════════════════════════════════════════════════════════════════════
    // [v1361] BEN A RAISON, ET MON ERREUR ÉTAIT GRAVE.
    //
    // J'écrivais `if(o.histo) return;` — « les reprises d'historique ne sont pas des recettes de
    // l'exercice ». C'EST FAUX. Ce sont des VENTES RÉELLES, ENCAISSÉES, qui font partie de son CA.
    // Les exclure du livre des recettes, c'est DISSIMULER DU CHIFFRE D'AFFAIRES — et un contrôleur
    // qui compare le livre à la déclaration verrait l'écart immédiatement.
    //
    // J'AI CONFONDU DEUX CHOSES :
    //   • « saisi rétroactivement dans l'app » → une caractéristique TECHNIQUE
    //   • « ne fait pas partie du CA »         → une affirmation COMPTABLE, et elle est FAUSSE
    //
    // C'est le principe que je venais de graver en v1360 (« l'omission d'un canal rend le livre
    // FAUX »), violé dans la ligne suivante. Ben l'a vu : « le dissimuler serait mentir ».
    //
    // RÈGLE GRAVÉE (v1361) : UNE CARACTÉRISTIQUE TECHNIQUE N'EST JAMAIS UNE JUSTIFICATION COMPTABLE.
    // Le mode de saisie d'une recette ne change RIEN à son existence.
    //
    // LE PIÈGE TECHNIQUE, plus retors : une commande historique a `paiement:'Payé'` mais
    // `paiements:[]` — un tableau VIDE. Retirer le filtre `o.histo` n'aurait donc RIEN changé :
    // la boucle sur `paiements` ne trouve rien. La recette serait restée absente, mais SILENCIEUSEMENT.
    // On applique la même rétro-compatibilité que `orderPaid()` : pas d'écriture de paiement +
    // statut « Payé » ⇒ la recette vaut le montant de la commande, à sa date.
    // ════════════════════════════════════════════════════════════════════════
    const paiements = Array.isArray(o.paiements) ? o.paiements : [];
    const sansEcriture = !paiements.some(p => p && (+p.montant));

    if(sansEcriture && o.paiement === 'Payé' && (+o.montant) > 0){
      const d = (o.datePaiement || o.date || '').slice(0, 10);
      if((!depuis || d >= depuis) && (!jusqu || d <= jusqu)){
        lignes.push({
          date: d,
          piece: o.factureNumero || ((typeof orderNumber === 'function') ? orderNumber(o) : ('CMD-' + o.id)),
          client: o.clientNom || nomClient(o.clientId) || 'Client non identifié',
          montant: money2(+o.montant || 0),
          moyen: o.reglement || 'Non précisé',
          // La nature dit la VÉRITÉ sur l'origine de la ligne — sans la cacher, et sans la
          // disqualifier. Une recette reprise reste une recette.
          nature: o.histo
            ? `Vente de macarons — reprise d'historique${o.histoLabel ? ' (' + o.histoLabel + ')' : ''}`
            : 'Vente de macarons — commande',
          canal: o.histo ? 'Reprise historique' : 'Commande',
          statut: 'Encaissement',
          motif: ''
        });
      }
    }

    paiements.forEach((p, i) => {
      if(!p || !(+p.montant)) return;
      const d = (p.date || o.date || '').slice(0, 10);
      if(depuis && d < depuis) return;
      if(jusqu  && d > jusqu)  return;

      let statut = 'Encaissement';
      if(p.annule)          statut = 'ANNULÉ';
      else if(p.correction) statut = ((+p.montant) < 0) ? 'Annulation' : 'Correction';
      else if(p.acompte || p.moyen === 'Acompte') statut = 'Acompte';

      // [v1362] LE LEGACY. Les acomptes saisis AVANT ce correctif portent `moyen:'Acompte'` — un
      // STATUT logé dans le champ MOYEN. On ne peut pas deviner le vrai moyen a posteriori : on
      // affiche « Non précisé », qui est la VÉRITÉ, plutôt que « Acompte », qui est une catégorie
      // de règlement N'EXISTANT PAS. Le STATUT est conservé (ligne ci-dessus) : l'information
      // n'est pas perdue — elle est remise dans la BONNE COLONNE.
      // [v1366] on normalise le moyen ET le repli o.reglement — « Acompte » ne doit revenir
      // par aucun des deux, et « Carte bancaire »/« CB » deviennent « Carte ».
      const _moyenReel = _normMoyen(p.moyen);

      lignes.push({
        date: d,
        // [v1360] LA PIÈCE JUSTIFICATIVE. La loi exige une RÉFÉRENCE — le n° de facture s'il existe,
        // sinon le n° de commande, qui est la pièce réellement émise. On ne fabrique pas un numéro
        // qui n'existe pas : on référence celui qui existe.
        piece: o.factureNumero || ((typeof orderNumber === 'function') ? orderNumber(o) : ('CMD-' + o.id)),
        client: o.clientNom || nomClient(o.clientId) || 'Client non identifié',
        montant: money2(+p.montant || 0),
        moyen: _moyenReel || _normMoyen(o.reglement) || 'Non précisé',
        nature: o.histo
          ? `Vente de macarons — reprise d'historique${o.histoLabel ? ' (' + o.histoLabel + ')' : ''}`
          : 'Vente de macarons — commande',
        canal: o.histo ? 'Reprise historique' : 'Commande',
        statut,
        motif: p.motif || p.annuleMotif || ''
      });
    });
  });

  // ═══ CANAL 2 : LES MARCHÉS — CE QUI MANQUAIT, ET QUI INVALIDAIT TOUT ═══
  //
  // Un marché CLOS est une recette encaissée LE JOUR MÊME. Chaque mode de règlement (espèces,
  // CB, autre) est une LIGNE DISTINCTE : la loi exige la ventilation par mode de règlement.
  //
  // LE FOND DE CAISSE EST DÉDUIT DES ESPÈCES — sinon on déclarerait comme recette de l'argent
  // qui était déjà là le matin. C'est la règle qu'applique déjà `caMarcheEncaisse()`, et je
  // passe par ELLE plutôt que de refaire le calcul (règle v1358 : un second chemin diverge).
  const markets = await db.markets.toArray().catch(() => []);
  (markets || []).forEach(mk => {
    if(!mk || mk.statut !== 'clos') return;   // un marché non clos n'a pas de recette arrêtée
    const d = (mk.date || '').slice(0, 10);
    if(depuis && d < depuis) return;
    if(jusqu  && d > jusqu)  return;

    const ca = mk.ca || {};
    const fond = money2(+mk.fondCaisse || 0);
    const esp  = money2(Math.max(0, (+ca.especes || 0) - fond));   // fond de caisse déduit
    const cb   = money2(+ca.cb || 0);
    const autre= money2(+ca.autre || 0);

    const base = {
      date: d,
      piece: `MARCHE-${mk.id}`,
      client: 'Ventes au comptant (marché)',   // pas d'identité client : vente au détail
      nature: `Vente de macarons — marché${mk.nom ? ' ' + mk.nom : ''}`,
      canal: 'Marché',
      statut: 'Encaissement',
      motif: ''
    };
    if(esp   > 0) lignes.push(Object.assign({}, base, { montant: esp,   moyen: _normMoyen('Espèces') || 'Espèces' }));
    if(cb    > 0) lignes.push(Object.assign({}, base, { montant: cb,    moyen: 'Carte' }));   // [v1366] libellé canonique (PAY_METHODS)
    if(autre > 0) lignes.push(Object.assign({}, base, { montant: autre, moyen: 'Autre' }));
  });

  // Tri chronologique — l'ordre du livre EST l'ordre des recettes.
  lignes.sort((a, b) =>
    (a.date || '').localeCompare(b.date || '') ||
    (a.piece || '').localeCompare(b.piece || '')
  );

  // ═══ LE CHAÎNAGE ═══ appliqué APRÈS le tri : la chaîne suit l'ordre du registre.
  let prec = null;
  lignes.forEach((l, i) => {
    l.num = i + 1;
    l.hash = _lrHashLigne(l, prec);
    l.hashPrec = prec || 'GENESE';
    prec = l.hash;
  });

  return lignes;
}

// ---------------------------------------------------------------------------
// VÉRIFICATION DE LA CHAÎNE. Recalcule tous les hashes et signale la PREMIÈRE rupture.
// C'est ce qu'on montre à un contrôleur : « voici la preuve que rien n'a bougé ».
// ---------------------------------------------------------------------------
function verifierChaine(lignes){
  let prec = null;
  for(let i = 0; i < lignes.length; i++){
    const attendu = _lrHashLigne(lignes[i], prec);
    if(lignes[i].hash !== attendu){
      return { intacte: false, ligne: i + 1, piece: lignes[i].piece };
    }
    prec = lignes[i].hash;
  }
  return { intacte: true, ligne: null, piece: null };
}

// ---------------------------------------------------------------------------
// [v1360] L'EXPORT CSV — pour le comptable.
// ---------------------------------------------------------------------------
function livreRecettesCsv(lignes, depuis, jusqu){
  const q = v => {
    const s = (v == null ? '' : String(v));
    return /[";\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const num = n => String(money2(n)).replace('.', ',');

  const head = ['N°', 'Date', 'Pièce', 'Client', 'Nature', 'Montant', 'Règlement', 'Canal', 'Statut', 'Motif', 'Empreinte'];
  const body = lignes.map(l => [
    l.num, l.date, l.piece, l.client, l.nature, num(l.montant), l.moyen, l.canal, l.statut, l.motif, l.hash
  ].map(q).join(';'));

  const total = money2(lignes.reduce((s, l) => s + (+l.montant || 0), 0));
  const parCanal = {};
  lignes.forEach(l => { parCanal[l.canal] = money2((parCanal[l.canal] || 0) + (+l.montant || 0)); });

  const chaine = verifierChaine(lignes);

  const pied = [''];
  pied.push(['', '', '', '', 'TOTAL NET', num(total), '', '', '', '', ''].map(q).join(';'));
  Object.keys(parCanal).forEach(c => {
    pied.push(['', '', '', '', 'dont ' + c, num(parCanal[c]), '', '', '', '', ''].map(q).join(';'));
  });
  pied.push('');
  pied.push(q(`Période : ${depuis || 'origine'} au ${jusqu || 'ce jour'}`));
  pied.push(q(`Écritures : ${lignes.length}`));
  pied.push(q(`Intégrité de la chaîne : ${chaine.intacte ? 'INTACTE — aucune altération détectée' : 'ROMPUE à la ligne ' + chaine.ligne}`));
  pied.push(q(`Édité le ${fmtDate(today())}`));

  return '\uFEFF' + [head.join(';')].concat(body).concat(pied).join('\r\n');
}

// ---------------------------------------------------------------------------
// [v1360] L'ÉDITION PAPIER — c'est CE document qu'on présente à un contrôle.
// Un CSV n'est pas un livre : c'est un fichier. Le livre se lit, se date, se signe.
// ---------------------------------------------------------------------------
async function imprimerLivreRecettes(depuis, jusqu){
  const lignes = await livreDesRecettes(depuis, jusqu);
  if(!lignes.length){ toast('Aucune recette sur cette période'); return; }

  const total = money2(lignes.reduce((s, l) => s + (+l.montant || 0), 0));
  const parCanal = {};
  const parMoyen = {};
  lignes.forEach(l => {
    parCanal[l.canal] = money2((parCanal[l.canal] || 0) + (+l.montant || 0));
    parMoyen[l.moyen] = money2((parMoyen[l.moyen] || 0) + (+l.montant || 0));
  });
  const chaine = verifierChaine(lignes);
  const S = (typeof getSettings === 'function') ? getSettings() : {};

  const rows = lignes.map(l => `<tr${l.statut === 'ANNULÉ' ? ' class="ann"' : ''}>
    <td>${l.num}</td>
    <td>${esc(fmtDate(l.date))}</td>
    <td>${esc(l.piece)}</td>
    <td>${esc(l.client)}</td>
    <td>${esc(l.nature)}</td>
    <td class="r"><b>${euro(l.montant)}</b></td>
    <td>${esc(l.moyen)}</td>
    <td>${esc(l.statut)}${l.motif ? `<br><span class="mot">${esc(l.motif)}</span>` : ''}</td>
  </tr>`).join('');

  const html = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8">
  <title>Livre des recettes</title>
  <style>
    @page { size: A4; margin: 14mm; }
    body { font-family: Helvetica, Arial, sans-serif; font-size: 9pt; color: #1a1a1a; }
    h1 { font-size: 15pt; margin: 0 0 2mm; letter-spacing: .06em; }
    .ent { border-bottom: 2px solid #000; padding-bottom: 3mm; margin-bottom: 5mm; }
    .ent p { margin: 1mm 0; font-size: 8.5pt; }
    table { width: 100%; border-collapse: collapse; font-size: 8pt; }
    th { background: #1a1a1a; color: #fff; padding: 2mm; text-align: left; font-size: 7.5pt; }
    td { padding: 1.6mm 2mm; border-bottom: .4px solid #ccc; }
    .r { text-align: right; }
    .ann { color: #999; text-decoration: line-through; }
    .ann .mot { text-decoration: none; }
    .mot { font-size: 7pt; color: #666; font-style: italic; }
    .tot { margin-top: 6mm; border-top: 2px solid #000; padding-top: 3mm; }
    .tot table { font-size: 9pt; }
    .tot td { border: none; padding: 1mm 3mm 1mm 0; }
    .big { font-size: 13pt; font-weight: bold; }
    .integ { margin-top: 6mm; padding: 3mm; border: 1px solid #000; font-size: 8pt; }
    .ok { color: #0a6b2e; font-weight: bold; }
    .ko { color: #b3261e; font-weight: bold; }
    .sig { margin-top: 10mm; font-size: 8.5pt; }
    .sig div { margin-top: 8mm; border-top: .5px solid #000; width: 60mm; padding-top: 1mm; }
    /* [v1367] Barre d'actions — visible à l'écran, MASQUÉE à l'impression. C'est la SORTIE de secours :
       sur iPhone en PWA, window.open('_blank') ne donne pas de barre de navigateur, donc sans ce
       bouton Ben était piégé et devait fermer l'app entière. Une page sans issue est un cul-de-sac. */
    .lr-bar { position: sticky; top: 0; display: flex; gap: 10px; justify-content: flex-end;
      background: #f7f3ee; padding: 10px 12px; border-bottom: 1px solid #d9cec6; margin: -8px -8px 12px; }
    .lr-bar button { font-size: 11pt; padding: 8px 18px; border-radius: 8px; border: 1px solid #b08d57;
      background: #fff; color: #4a2318; cursor: pointer; }
    .lr-bar button.pri { background: #4a2318; color: #fff; border-color: #4a2318; }
    @media print { .lr-bar { display: none !important; } }
  </style></head><body>
  <div class="lr-bar">
    <button onclick="try{window.close();}catch(e){};try{history.back();}catch(e){}">✕ Fermer</button>
    <button class="pri" onclick="window.print()">🖨 Imprimer</button>
  </div>
  <div class="ent">
    <h1>LIVRE DES RECETTES</h1>
    <p><b>${esc(S.entrepriseNom || 'Sensations Macarons')}</b>${S.siret ? ` — SIRET ${esc(S.siret)}` : ''}</p>
    <p>Période du <b>${esc(fmtDate(depuis || lignes[0].date))}</b> au <b>${esc(fmtDate(jusqu || lignes[lignes.length-1].date))}</b>
       · ${lignes.length} écriture(s)</p>
    <p style="font-size:7.5pt;color:#555">Recettes enregistrées à la date d'encaissement, tous canaux confondus
       (commandes et ventes au comptant sur marchés). Les écritures annulées et leurs corrections figurent
       intégralement — conformément au principe d'inaltérabilité.</p>
  </div>

  <table>
    <tr><th>N°</th><th>Date</th><th>Pièce</th><th>Client</th><th>Nature de la recette</th>
        <th class="r">Montant</th><th>Règlement</th><th>Statut</th></tr>
    ${rows}
  </table>

  <div class="tot">
    <table>
      <tr><td class="big">TOTAL NET DES RECETTES</td><td class="big r">${euro(total)}</td></tr>
      ${Object.keys(parCanal).map(c => `<tr><td>dont ${esc(c)}</td><td class="r">${euro(parCanal[c])}</td></tr>`).join('')}
      <tr><td colspan="2" style="padding-top:3mm"><b>Ventilation par mode de règlement</b></td></tr>
      ${Object.keys(parMoyen).map(m => `<tr><td>${esc(m)}</td><td class="r">${euro(parMoyen[m])}</td></tr>`).join('')}
    </table>
  </div>

  <div class="integ">
    <b>CONTRÔLE D'INTÉGRITÉ</b><br>
    Chaque écriture porte une empreinte calculée à partir de son contenu <i>et de l'empreinte de
    l'écriture précédente</i>. Toute modification, suppression ou insertion rompt la chaîne et devient
    détectable.<br><br>
    État de la chaîne : <span class="${chaine.intacte ? 'ok' : 'ko'}">
      ${chaine.intacte ? 'INTACTE — aucune altération détectée' : ('ROMPUE à l&rsquo;écriture n°' + chaine.ligne)}
    </span><br>
    Empreinte de clôture : <code>${esc(lignes[lignes.length - 1].hash)}</code>
  </div>

  <div class="sig">
    <p>Édité le ${esc(fmtDate(today()))}</p>
    <div>Signature</div>
  </div>
  </body></html>`;

  try{
    const w = window.open('', '_blank');
    if(!w){ toast('Autorise les fenêtres pop-up pour imprimer'); return; }
    // [v1367] La page se ferme d'elle-même après impression — et une barre « Fermer / Imprimer »
    // (dans le HTML) donne TOUJOURS une sortie, même si Ben n'imprime pas. On n'appelle plus
    // print() automatiquement : sur iPhone, la boîte d'impression forcée pouvait re-piéger.
    const htmlAvecSortie = html.replace('</body>',
      '<script>window.onafterprint=function(){window.close();};<\/script></body>');
    w.document.write(htmlAvecSortie);
    w.document.close();
  }catch(e){
    swallow(e, 'imprimerLivreRecettes');
    toast('Impression impossible');
  }
}

async function exporterLivreRecettesCsv(depuis, jusqu){
  const lignes = await livreDesRecettes(depuis, jusqu);
  if(!lignes.length){ toast('Aucune recette sur cette période'); return; }
  const csv = livreRecettesCsv(lignes, depuis, jusqu);
  try{
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `livre_recettes_${depuis || 'debut'}_${jusqu || 'fin'}.csv`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast(`${lignes.length} recette(s) exportée(s) ✓`);
  }catch(e){ swallow(e, 'exporterLivreRecettesCsv'); toast('Export impossible'); }
}


// [v1359] L'UI D'EXPORT. Mois courant, mois précédent, ou bornes libres.
// ---------------------------------------------------------------------------
function exportEncaissementsForm(){
  const now = new Date();
  const ym  = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
  const prem = ym + '-01';
  const dern = ymdLocal(new Date(now.getFullYear(), now.getMonth() + 1, 0));

  openModal(`<h3>📕 Livre des recettes</h3>
    <p class="note">Toutes les recettes de la période, <b>tous canaux</b> : commandes <b>et</b> ventes
    au comptant sur marchés. Les <b>annulations</b> et <b>corrections</b> y figurent intégralement —
    la loi exige un registre <b>honnête</b>, pas un registre propre.</p>
    <p class="note" style="font-size:.76rem">Chaque écriture porte une <b>empreinte chaînée</b> :
    toute modification a posteriori rompt la chaîne et devient détectable.</p>
    <div class="row2">
      <div class="field"><label>Du</label><input type="date" id="ex_depuis" value="${prem}"></div>
      <div class="field"><label>Au</label><input type="date" id="ex_jusqu" value="${dern}"></div>
    </div>
    <div style="margin:8px 0">
      <button class="btn ghost sm" onclick="exportEncPreset('mois')">Ce mois</button>
      <button class="btn ghost sm" onclick="exportEncPreset('moisPrec')">Mois dernier</button>
      <button class="btn ghost sm" onclick="exportEncPreset('annee')">Cette année</button>
    </div>
    <div class="modal-actions" style="flex-wrap:wrap;gap:6px">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn ghost" onclick="livreCsvLancer()">⤓ CSV (comptable)</button>
      <button class="btn gold" onclick="livreImprimerLancer()">🖨 Imprimer le livre</button>
    </div>`);
}

async function livreImprimerLancer(){
  const d = val('ex_depuis') || null, f = val('ex_jusqu') || null;
  closeModal();
  await imprimerLivreRecettes(d, f);
}
async function livreCsvLancer(){
  const d = val('ex_depuis') || null, f = val('ex_jusqu') || null;
  closeModal();
  await exporterLivreRecettesCsv(d, f);
}

function exportEncPreset(quoi){
  const now = new Date();
  let d, f;
  if(quoi === 'mois'){
    d = ymdLocal(new Date(now.getFullYear(), now.getMonth(), 1));
    f = ymdLocal(new Date(now.getFullYear(), now.getMonth() + 1, 0));
  } else if(quoi === 'moisPrec'){
    d = ymdLocal(new Date(now.getFullYear(), now.getMonth() - 1, 1));
    f = ymdLocal(new Date(now.getFullYear(), now.getMonth(), 0));
  } else {
    d = ymdLocal(new Date(now.getFullYear(), 0, 1));
    f = ymdLocal(new Date(now.getFullYear(), 11, 31));
  }
  const a = document.getElementById('ex_depuis'), b = document.getElementById('ex_jusqu');
  if(a) a.value = d;
  if(b) b.value = f;
}

async function exportEncLancer(){
  const d = val('ex_depuis') || null;
  const f = val('ex_jusqu')  || null;
  await exporterEncaissementsCsv(d, f);
  closeModal();
}

// [v1359] L'EXPORT DES ENCAISSEMENTS — par mois ou entre deux dates.
//
// Ben : « On doit aussi pouvoir exporter facilement un historique reprenant tous les encaissements
// sur une période donnée (par mois ou entre deux périodes précises). »
//
// CE QUE L'EXPORT DOIT MONTRER, ET QUE BEAUCOUP D'OUTILS CACHENT :
// les écritures ANNULÉES et les CORRECTIONS y figurent. Un export qui ne montrerait que le solde
// net serait un export MAQUILLÉ — il donnerait un registre propre là où la loi exige un registre
// HONNÊTE. Un contrôleur doit pouvoir voir l'erreur ET sa correction.
//
// On réutilise `_aiPeriodeCible` (v1342) : mois, semaine ISO, ou bornes explicites — le parseur
// existe déjà, il n'y a rien à réécrire.
// ════════════════════════════════════════════════════════════════════════════
async function exporterEncaissements(depuis, jusqu){
  const orders = await db.orders.toArray();
  const lignes = [];

  (orders || []).forEach(o => {
    if(!o || !Array.isArray(o.paiements)) return;
    o.paiements.forEach((p, i) => {
      if(!p || !(+p.montant)) return;   // une écriture à 0 n'est pas un encaissement
      const d = (p.date || o.date || '').slice(0, 10);
      if(depuis && d < depuis) return;
      if(jusqu  && d > jusqu)  return;

      // [v1359] LE STATUT EST EXPLICITE. Un encaissement annulé reste dans l'export, MARQUÉ.
      // Le masquer produirait un registre plus propre — et faux.
      let statut = 'Encaissement';
      if(p.annule)          statut = 'ANNULÉ';
      else if(p.correction) statut = ((+p.montant) < 0) ? 'Annulation' : 'Correction';

      lignes.push({
        date: d,
        commande: (typeof orderNumber === 'function') ? orderNumber(o) : ('#' + o.id),
        client: o.clientNom || '',
        montant: money2(+p.montant || 0),
        moyen: p.moyen || o.reglement || '—',
        statut,
        motif: p.motif || p.annuleMotif || '',
        libelle: p.libelle || ''
      });
    });
  });

  lignes.sort((a, b) => (a.date || '').localeCompare(b.date || '') || a.commande.localeCompare(b.commande));
  return lignes;
}

// Génère le CSV. Séparateur `;` (Excel FR), virgule décimale, BOM UTF-8 pour les accents.
function encaissementsCsv(lignes){
  const esc = v => {
    const s = (v == null ? '' : String(v));
    return /[";\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const num = n => String(money2(n)).replace('.', ',');   // Excel FR attend la virgule
  const head = ['Date', 'Commande', 'Client', 'Montant', 'Moyen', 'Statut', 'Motif', 'Libellé'];
  const body = lignes.map(l => [
    l.date, l.commande, l.client, num(l.montant), l.moyen, l.statut, l.motif, l.libelle
  ].map(esc).join(';'));

  // Le TOTAL NET : la somme inclut les montants négatifs des annulations. C'est le montant
  // réellement encaissé sur la période — et il est vérifiable ligne à ligne, ce qui est le point.
  const total = money2(lignes.reduce((s, l) => s + (+l.montant || 0), 0));
  body.push('');
  body.push(['', '', 'TOTAL NET', num(total), '', '', '', ''].map(esc).join(';'));

  return '\uFEFF' + [head.join(';')].concat(body).join('\r\n');
}

async function exporterEncaissementsCsv(depuis, jusqu){
  const lignes = await exporterEncaissements(depuis, jusqu);
  if(!lignes.length){ toast('Aucun encaissement sur cette période'); return; }
  const csv = encaissementsCsv(lignes);
  const nom = `encaissements_${depuis || 'debut'}_${jusqu || 'fin'}.csv`;
  try{
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = nom;
    document.body.appendChild(a); a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast(`${lignes.length} encaissement(s) exporté(s) ✓`);
  }catch(e){
    swallow(e, 'exporterEncaissementsCsv');
    toast('Export impossible');
  }
}


function logDeletion(type, id, reason, note, label){
  try{
    const key='sm_deletionLog';
    const arr=JSON.parse(localStorage.getItem(key)||'[]');
    arr.unshift({type, id, reason, note:note||'', label:label||'', ts:new Date().toISOString()});
    localStorage.setItem(key, JSON.stringify(arr.slice(0,300)));
  }catch(e){swallow(e,'logDeletion')}
}
// ============================================================
//  LIER DES BATCHS À LA COMMANDE — recherche + filtre + suggestion FIFO
//  Réutilise le moteur d'affectation existant (allocateBatches) : la suggestion
//  « à prélever en premier » (le plus ancien) et son emplacement sont EXACTEMENT
//  ce que ferait l'écran Picking. Aucune logique FIFO dupliquée.
//    - Filtre par défaut : parfums de la commande (orderFlavorNeeds). Aucun parfum
//      renseigné (« saveurs à définir ») → tout le stock fini.
//    - Recherche (champ texte) : porte sur TOUT le stock, accents ignorés (normTxt).
//    - Tri FIFO : reprises d'abord, puis DLC croissante (id en départage) — le même
//      ordre que allocateBatches, pour que la suggestion colle au tri affiché.
//    - Quantité pré-remplie = besoin restant du parfum (déjà affecté déduit), plafonné
//      au lot ; ajustable avant de valider.
// ============================================================
let _cmdLinkState = null;
const _LNK_CSS = `
.lnk-list{ max-height:46vh; overflow-y:auto; margin-top:4px; -webkit-overflow-scrolling:touch; }
.lnk-sec{ font-size:.7rem; text-transform:uppercase; letter-spacing:.04em; color:#9a8a82; margin:9px 2px 4px; }
.lnk-row{ display:flex; align-items:center; gap:8px; padding:8px 6px; border-bottom:1px solid #f0e8da; }
.lnk-row.sugg{ background:#fbf6ee; border-left:3px solid #AA7C39; padding-left:6px; border-radius:2px; }
.lnk-main{ flex:1; min-width:0; }
.lnk-top{ display:flex; align-items:center; gap:6px; flex-wrap:wrap; }
.lnk-top b{ color:#490F25; }
.lnk-old{ font-size:.64rem; background:#AA7C39; color:#fff; border-radius:6px; padding:1px 6px; white-space:nowrap; }
.lnk-meta{ font-size:.74rem; color:#7a6a60; margin-top:1px; }
.lnk-loc{ font-size:.74rem; color:#8a5a2a; margin-top:1px; }
.lnk-act{ display:flex; align-items:center; gap:6px; flex:0 0 auto; }
.lnk-q{ width:54px; padding:6px; text-align:center; border:1px solid #d8c8b8; border-radius:6px; font-size:.85rem; }
.lnk-btn{ padding:6px 12px; font-size:.82rem; }
.lnk-details{ margin-top:6px; }
.lnk-details summary{ cursor:pointer; font-size:.78rem; color:#8a5a2a; padding:6px 2px; list-style:none; }
.lnk-details summary::-webkit-details-marker{ display:none; }
.lnk-details summary::before{ content:'▸ '; }
.lnk-details[open] summary::before{ content:'▾ '; }
.cpf-list{ display:flex; flex-direction:column; gap:2px; }
.cpf-row{ display:flex; justify-content:space-between; align-items:baseline; gap:8px; padding:3px 2px; border-bottom:1px dotted #eaded0; }
.cpf-nom{ color:#490F25; font-weight:600; font-size:.86rem; }
.cpf-q{ color:#7a5a3a; font-size:.86rem; white-space:nowrap; }
.cpf-q small{ color:#8a7a70; font-weight:400; }
`;
// Reconstruit la liste (#f_list) selon la recherche courante + le filtre par défaut.
function _cmdLinkRenderList(){
  const st = _cmdLinkState; if(!st) return;
  const box = document.getElementById('f_list'); if(!box) return;
  const el = document.getElementById('f_search');
  const q = normTxt((el && el.value) || '');
  const rowHtml = r => `
    <div class="lnk-row${r.sugg>0?' sugg':''}">
      <div class="lnk-main">
        <div class="lnk-top"><b>${esc(r.flavor)}</b>${r.sugg>0?'<span class="lnk-old">⭐ le + ancien</span>':''}</div>
        <div class="lnk-meta">lot ${esc(r.lot)} · reste ${qty(r.reste)}</div>
        <div class="lnk-loc">${r.empIcon||'📍'} ${esc(r.empLettre)} ${esc(r.empNom)}${r.jDlc!=null?` · DLC ${r.jDlc<=0?'<b style="color:#b3261e">expirée</b>':r.jDlc+' j'}`:''}</div>
      </div>
      <div class="lnk-act">
        <input type="number" id="lq_${r.prodId}" class="lnk-q" value="${r.sugg>0?r.sugg:''}" placeholder="${qty(r.reste)}" min="0" max="${r.reste}" inputmode="numeric">
        <button class="btn gold lnk-btn" onclick="_cmdLinkDo(${st.orderId},${r.prodId})">Lier</button>
      </div>
    </div>`;
  let html = '';
  if(q){
    // Recherche active : liste à plat de TOUT le stock correspondant, FIFO.
    const rows = st.rows.filter(r => normTxt(r.flavor).includes(q));
    html = rows.length ? rows.map(rowHtml).join('') : '<p class="note" style="padding:8px 4px">Aucun parfum ne correspond à « '+esc(q)+' ».</p>';
  } else if(st.hasNeeds){
    // Vue par défaut avec parfums attendus : section « commande » + « autres » repliés.
    const need = st.rows.filter(r => r.inNeeds);
    const autres = st.rows.filter(r => !r.inNeeds);
    html = `<div class="lnk-sec">Parfums de la commande</div>` +
      (need.length ? need.map(rowHtml).join('') : '<p class="note" style="padding:8px 4px">Aucun batch en stock pour les parfums de la commande.</p>');
    if(autres.length){
      html += `<details class="lnk-details"><summary>Autres batchs en stock (${autres.length})</summary>${autres.map(rowHtml).join('')}</details>`;
    }
  } else {
    // Commande sans parfums renseignés : tout le stock, à plat, FIFO.
    html = st.rows.length ? st.rows.map(rowHtml).join('') : '<p class="note" style="padding:8px 4px">Aucun batch fini en stock.</p>';
  }
  box.innerHTML = html;
}
// Lie un batch précis avec la quantité saisie sur sa ligne, puis rouvre la modale
// (mêmes garde-fous transactionnels que l'ancien saveLink : contrôle stock DANS la
// transaction, journal de stock hors transaction).
async function _cmdLinkDo(orderId, prodId){
  const q = +val('lq_'+prodId);
  if(!q || q<=0){ toast('Quantité invalide'); return; }
  let _mvLink = null;
  try{
    await db.transaction('rw', db.orderItems, db.productions, async()=>{
      const prod = await db.productions.get(prodId);
      if(!prod) throw new Error('Batch introuvable');
      if(round3(q) > round3(+prod.qteRestante)) throw new Error('Quantité > stock du batch');
      await db.orderItems.add({ orderId, productionId:prodId, qte:round3(q) });
      await db.productions.update(prodId, { qteRestante: subQty(prod.qteRestante, q) });
      _mvLink = { parfumNom: prodNomComplet(prod), composant:'macaron', sens:-1, qte:round3(q),
        type:'livraison', productionId:prodId, orderId, note:'liaison manuelle' };
    });
  }catch(err){ toast(err.message || 'Erreur de liaison'); return; }
  if(_mvLink) await logStockMove(_mvLink);
  renderCmd(); toast('Batch lié à la commande ✓'); cmdLink(orderId);
}
// Lier une commande à des batchs (décrémente le stock de produits finis)
async function cmdLink(orderId){
  const prods = await db.productions.toArray();
  const recipes = await db.recipes.toArray();
  window._allRecipesCache = recipes; // garde le fallback de prodNomComplet à jour
  const recById = {}; recipes.forEach(r=>{ recById[r.id]=r; });
  const recName = id => (recById[id]||{}).produitNom || '?';
  // Ne proposer QUE des produits finis (macarons entiers) : vendables (complet/assemblé) et
  // dégustation/dons. On exclut les sous-lots coques, ganache et crémeux, qui ne se livrent pas
  // en l'état.
  const estProduitFini = p => { const c=prodComposant(p); return c==='complet' || c==='assemble' || c==='degustation'; };
  const dispoRaw = prods.filter(p=>round3(+p.qteRestante)>0 && estProduitFini(p));
  // Tri FIFO d'affichage : reprises d'abord, puis DLC croissante, id en départage.
  // Cohérent avec l'ordre utilisé par allocateBatches (dlcProduit croissante).
  const fifoKey = p => (p.repriseStock?'0':'1') + (p.dlcProduit || '9999-12-31');
  dispoRaw.sort((a,b)=> fifoKey(a).localeCompare(fifoKey(b)) || ((+a.id||0)-(+b.id||0)));
  const existing = await db.orderItems.where('orderId').equals(orderId).toArray();
  const ord = await db.orders.get(orderId);
  // total de macarons de la commande (coffrets + événement + dons ; grands formats à part)
  const lignes = orderToLines(ord||{});
  let totMac=0, totDon=0;
  lignes.forEach(ln=>{
    if(ln.type==='coffret') totMac += +ln.taille||0;
    else if(ln.type==='evenement') totMac += +ln.evQte||0;
    else if(ln.type==='sachet'){ totMac += (ln.parfums||[]).reduce((s,p)=>s+(+p.qte||0),0) + (+ln.sansParfum||0); }
    else if(ln.type==='don'){ const n=(ln.parfums||[]).reduce((s,p)=>s+(+p.qte||0),0); totMac+=n; totDon+=n; }
  });
  const dejaLie = existing.reduce((s,e)=>s+(+e.qte||0),0);

  // Besoins par parfum, puis besoins RESTANTS (déjà affecté déduit, par parfum).
  const needs = orderFlavorNeeds(ord||{});
  // Crédit du « déjà lié » PAR PARFUM DE LA COMMANDE. Le nom d'un lot peut différer légèrement
  // de celui saisi sur la commande (« Praliné noisette » vs « Praliné noisettes ») : on impute
  // donc chaque lot au parfum de la commande qui CORRESPOND — même matching flou que l'affectation
  // (pickFlavorMatch + même statut grand format) — plutôt qu'une égalité stricte de chaîne, qui
  // laissait le parfum non crédité (pas de vert + re-suggestion à tort d'un besoin déjà couvert).
  const _needKeys = Object.keys(needs);
  const linkedByFlavor = {};
  existing.forEach(e=>{
    const p = prods.find(x=>x.id===e.productionId); if(!p) return;
    const r = recById[p.recipeId];
    const prodNom = r ? r.produitNom : (p.produitNom||'');
    const prodGF = !!(r && r.grandFormat);
    let key = _needKeys.find(k => isGFKey(k)===prodGF && pickFlavorMatch(gfBase(k), prodNom));
    if(!key) key = prodGF ? prodNom+GF_MARK : prodNom;   // repli : conserve l'info sans correspondance
    linkedByFlavor[key] = round3((linkedByFlavor[key]||0) + (+e.qte||0));
  });
  const remainingNeeds = {};
  Object.keys(needs).forEach(k=>{ const r=round3((needs[k]||0)-(linkedByFlavor[k]||0)); if(r>0) remainingNeeds[k]=r; });
  const hasNeeds = Object.keys(needs).length>0;

  // Suggestion FIFO via le moteur d'affectation existant → quantité suggérée par batch.
  const alloc = allocateBatches(remainingNeeds, prods, recipes);
  const suggByProd = {};
  (alloc.plan||[]).forEach(pk=>{ suggByProd[pk.prodId] = round3((suggByProd[pk.prodId]||0) + (+pk.qte||0)); });

  // Bases de parfums attendus (sans marqueur GF), pour classer « commande » vs « autres ».
  const neededBases = [...new Set(Object.keys(needs).map(k=>gfBase(k)))];
  const _today = today();
  const jDlcOf = d => { if(!d) return null; const dd = new Date(/T/.test(d)?d:(d+'T00:00')); if(isNaN(dd)) return null; return Math.round((dd - new Date(_today+'T00:00'))/86400000); };

  const rows = dispoRaw.map(p=>{
    const flavor = recName(p.recipeId);
    const emp = p.emplacement||'';
    const ei = empInfo(emp);
    return {
      prodId: p.id, flavor, lot: p.lotProduction || ('#'+p.id), reste: round3(+p.qteRestante),
      emp, empIcon: ei.icon, empLettre: ei.lettre, empNom: ei.nom, freezer: isFreezer(emp),
      dlc: p.dlcProduit||'', jDlc: jDlcOf(p.dlcProduit||''),
      sugg: round3(suggByProd[p.id]||0),
      inNeeds: neededBases.length ? neededBases.some(b=> pickFlavorMatch(b, flavor)) : false
    };
  });

  _cmdLinkState = { orderId, rows, hasNeeds };

  openModal(`<h3>Lier des batchs à la commande</h3>
    <div class="sum-box"><span>Macarons de la commande${totDon?` (dont ${totDon} offert${totDon>1?'s':''})`:''}</span><b>${totMac||'—'}</b></div>
    ${totMac?`<div class="sum-box"><span>Déjà affecté depuis le stock</span><b>${dejaLie} / ${totMac}</b></div>`:''}
    ${hasNeeds?`<div class="field" style="margin-top:10px"><label>Parfums de la commande</label>
      ${flavorPills(Object.keys(needs).map(k=>{const ord=round3(needs[k]||0),aff=round3(linkedByFlavor[k]||0),rst=round3(Math.max(0,ord-aff));let st='',sfx=null;if(aff>0&&rst<=0){st='ok';sfx='✓';}else if(aff>0){sfx='· reste '+rst;}return {nom:isGFKey(k)?gfBase(k)+' (grand format)':k,qte:ord,state:st,suffix:sfx};}))}
    </div>`:`<p class="note" style="margin-top:8px">Commande sans parfums d\u00e9taill\u00e9s (\u00ab saveurs \u00e0 d\u00e9finir \u00bb).</p>`}
    ${existing.length?`<div class="field" style="margin-top:10px"><label>Batchs déjà liés</label>
      ${existing.map(e=>{const p=prods.find(x=>x.id===e.productionId);
        return `<div class="sum-box"><span>${p?esc(recName(p.recipeId)):'?'} — ${p?esc(p.lotProduction||''):'(supprimé)'} × ${e.qte}</span>
          <span class="act del" onclick="unlinkBatch(${e.id},${orderId})">Détacher</span></div>`;}).join('')}
      </div>`:''}
    ${dispoRaw.length?`
    <div class="field" style="margin-top:12px">
      <label>Ajouter un batch — cherche un parfum, prélève le plus ancien</label>
      <input type="text" id="f_search" placeholder="${hasNeeds?'Filtrer un parfum (ex. chocolat)…':'Rechercher un parfum (ex. chocolat)…'}" oninput="_cmdLinkRenderList()" autocomplete="off">
    </div>
    <div id="f_list" class="lnk-list"></div>`
    :'<p class="note">Aucun batch disponible à ajouter. Lance une production d\'abord.</p>'}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>
    <style>${_LNK_CSS}</style>`);
  if(dispoRaw.length) _cmdLinkRenderList();
}
async function unlinkBatch(itemId, orderId){
  const item = await db.orderItems.get(itemId);
  if(!item){ cmdLink(orderId); return; }
  let _mvUnlink=null; // [JOURNAL STOCK] recrédit à journaliser hors transaction
  await db.transaction('rw',db.orderItems,db.productions,async()=>{
    const prod = await db.productions.get(item.productionId);
    if(prod){
      await db.productions.update(prod.id,{qteRestante: addQty(prod.qteRestante, item.qte)});
      _mvUnlink={ parfumNom: prodNomComplet(prod), composant:'macaron', sens:+1, qte:round3(+item.qte||0),
        type:'recredit', productionId:prod.id, orderId, note:'déliaison batch' };
    }
    await db.orderItems.delete(itemId);
  });
  if(_mvUnlink) await logStockMove(_mvUnlink);
  toast('Batch détaché — stock fini restitué'); cmdLink(orderId);
}
async function saveLink(orderId){
  const prodId=+val('f_prod'), q=+val('f_q');
  if(!q||q<=0){toast('Quantité invalide');return;}
  let _mvLink=null; // [JOURNAL STOCK] mouvement à journaliser hors transaction (stockMoves non déclaré dans la transaction rw)
  try{
    await db.transaction('rw',db.orderItems,db.productions,async()=>{
      // lecture + contrôle + écriture DANS la transaction : aucun état asymétrique possible
      const prod=await db.productions.get(prodId);
      if(!prod) throw new Error('Batch introuvable');
      if(round3(q) > round3(+prod.qteRestante)) throw new Error('Quantité > stock du batch');
      await db.orderItems.add({orderId,productionId:prodId,qte:round3(q)});
      await db.productions.update(prodId,{qteRestante: subQty(prod.qteRestante, q)});
      _mvLink={ parfumNom: prodNomComplet(prod), composant:'macaron', sens:-1, qte:round3(q),
        type:'livraison', productionId:prodId, orderId, note:'liaison manuelle' };
    });
  }catch(err){ toast(err.message||'Erreur de liaison'); return; }
  if(_mvLink) await logStockMove(_mvLink);
  closeModal(); renderCmd(); toast('Batch lié à la commande ✓');
}

/* ============================================================
   CALENDRIER
   ============================================================ */
let calRef=new Date();

/* ============================================================
   COMPTABILITÉ — moteur en TRÉSORERIE (cash basis)
   Principe clé : le CA est comptabilisé à la DATE RÉELLE D'ENCAISSEMENT
   (date de chaque ligne de paiement), pas à la date de commande/livraison.
   Indépendant des modules Commandes/Stocks : ne lit que les données brutes.
   ============================================================ */
// monthKey() : voir utils.js
// monthLabel() : voir utils.js
// Période sélectionnée pour la comptabilité (schéma de flux).
let _comptaPeriode = 'tout';
let _comptaDateDebut = '';  // dates personnalisées (mode 'perso')
let _comptaDateFin = '';
const COMPTA_PERIODES = [
  {k:'tout',   lib:'Tout'},
  {k:'annee',  lib:'Cette année'},
  {k:'6mois',  lib:'6 mois'},
  {k:'90j',    lib:'90 jours'},
  {k:'mois',   lib:'Dernier mois'},
  {k:'semaine',lib:'Cette semaine'},
  {k:'perso',  lib:'📅 Dates précises'}
];
// Applique les dates personnalisées saisies et relance le calcul.
function comptaSetDates(){
  const d=document.getElementById('comptaDateDebut'); const f=document.getElementById('comptaDateFin');
  _comptaDateDebut = d?d.value:''; _comptaDateFin = f?f.value:'';
  _comptaPeriode='perso';
  renderCompta();
}
// Renvoie la date de début (incluse) pour une période, ou null pour "tout".
function comptaPeriodeStart(k){
  if(k==='perso') return _comptaDateDebut||null;
  const now=new Date();
  const d=new Date(now.getFullYear(), now.getMonth(), now.getDate());
  if(k==='annee') return `${now.getFullYear()}-01-01`;
  if(k==='6mois'){ const x=new Date(d); x.setMonth(x.getMonth()-6); return ymdLocal(x); }
  if(k==='90j'){ const x=new Date(d); x.setDate(x.getDate()-90); return ymdLocal(x); }
  if(k==='mois'){ const x=new Date(d); x.setMonth(x.getMonth()-1); return ymdLocal(x); }
  if(k==='semaine'){ const x=new Date(d); x.setDate(x.getDate()-7); return ymdLocal(x); }
  return null; // tout
}
// Date de fin d'une période ('perso' = date saisie, sinon aujourd'hui implicite donc null).
function comptaPeriodeEnd(k){ return k==='perso' ? (_comptaDateFin||null) : null; }
function comptaSetPeriode(k){ _comptaPeriode=k; renderCompta(); }
// Libellé lisible des dates couvertes par une période (ex : « du 16 mai au 15 juin 2026 »).
function comptaPeriodeDatesLabel(k){
  const start=comptaPeriodeStart(k);
  const f = (typeof fmtDate==='function') ? fmtDate : (s=>s);
  if(k==='perso'){
    if(!start && !_comptaDateFin) return 'dates non saisies';
    return `du ${start?f(start):'début'} au ${_comptaDateFin?f(_comptaDateFin):"aujourd'hui"}`;
  }
  const todayStr=today();
  if(!start) return 'toutes les données';
  return `du ${f(start)} au ${f(todayStr)}`;
}
// ════════════════════════════════════════════════════════════════════════════
//  [v1368] LE DÉTECTEUR D'ANOMALIES COMPTABLES — « traquer toute déviance, tout mensonge »
//
//  Ben : « Ma plus grande frustration est d'avoir une app qui crée des mensonges en douce, des
//  données non traçables. Si les chiffres mentent c'est la fin de la confiance. Construisons l'outil
//  permettant de tracer à chaque instant toute déviance. »
//
//  LE PRINCIPE, ET IL EST FONDATEUR : ce détecteur NE RECALCULE PAS la compta. Il vérifie qu'elle
//  ne SE CONTREDIT PAS. Un chiffre comptable ne peut pas mentir sans laisser une trace — il suffit
//  de vérifier qu'il RETOMBE SUR SES LIGNES. Chaque contrôle est un INVARIANT : une égalité qui
//  DOIT tenir. Si elle ne tient pas, l'anomalie désigne un mensonge précis, avec sa pièce et sa règle.
//
//  CE QU'IL NE FAIT PAS : il ne corrige rien tout seul. Réparer en douce serait un mensonge de plus.
//  Il MONTRE, il localise, il nomme la règle violée — Ben décide.
//
//  RÈGLE (v1368) : quand un total ne retombe pas sur la somme de ses lignes, ce n'est pas un détail
//  d'affichage — c'est le signe qu'une donnée a été inventée quelque part. On la traque jusqu'à sa pièce.
// ════════════════════════════════════════════════════════════════════════════

// Chaque anomalie : { gravite, code, piece, message, regle, ecart }
//  gravite : 'critique' (le CA est faux) | 'alerte' (donnée incohérente) | 'info' (à surveiller)
function _auditAnomalie(gravite, code, piece, message, regle, ecart){
  return { gravite, code, piece, message, regle, ecart: (ecart==null?null:money2(ecart)) };
}

async function auditComptable(opts){
  opts = opts || {};
  const depuis = opts.depuis || null;
  const jusqu  = opts.jusqu  || null;
  const _in = d => { const s=(d||'').slice(0,10); if(depuis && s<depuis) return false; if(jusqu && s>jusqu) return false; return true; };

  const anomalies = [];
  const orders  = await db.orders.toArray().catch(()=>[]);
  const markets = await db.markets.toArray().catch(()=>[]);

  // ── INVARIANT 1 : la somme des paiements d'une commande ≤ son montant ────────────
  // Un encaissement supérieur au dû est soit une double-saisie, soit un montant inventé.
  // (On tolère l'égalité : payé = dû. On signale le DÉPASSEMENT.)
  orders.forEach(o=>{
    if(estReprise && estReprise(o)) return;   // les reprises ont leur propre invariant (n°5)
    const pays = paiementsDe(o);
    if(!pays.length) return;
    const encaisse = money2(pays.reduce((s,p)=>s+((+p.montant)||0),0));
    const du = money2(+o.montant||0);
    if(encaisse > du + 0.01){
      anomalies.push(_auditAnomalie('critique','ENCAISSE_SUP_DU',
        (typeof orderNumber==='function'?orderNumber(o):('CMD-'+o.id)),
        `Encaissé ${euro(encaisse)} pour une commande de ${euro(du)} — ${euro(encaisse-du)} de trop.`,
        'La somme des paiements ne peut pas dépasser le montant de la commande.',
        encaisse-du));
    }
  });

  // ── INVARIANT 2 : une commande « Payé » a un encaissement réel ───────────────────
  // « Payé » sans aucune écriture ET sans montant, c'est un statut qui ment.
  // (La rétro-compat orderPaid tolère paiements:[] + Payé SI o.montant>0 : c'est une vraie recette.
  //  L'anomalie, c'est Payé + montant 0 + aucun paiement : rien n'a été encaissé, le statut est faux.)
  orders.forEach(o=>{
    const pays = paiementsDe(o);
    const aEcriture = pays.some(p=>(+p.montant));
    if(o.paiement==='Payé' && !aEcriture && !(+o.montant>0)){
      anomalies.push(_auditAnomalie('alerte','PAYE_SANS_MONTANT',
        (typeof orderNumber==='function'?orderNumber(o):('CMD-'+o.id)),
        `Commande marquée « Payé » mais aucun encaissement et montant nul.`,
        'Un statut « Payé » doit correspondre à une recette réelle.', 0));
    }
  });

  // ── INVARIANT 3 : tout encaissement porte une DATE et un MOYEN ───────────────────
  // Une recette sans date ne peut être ventilée sur aucun mois → elle disparaît du CA d'un mois.
  // Un moyen « Acompte » (ou vide) est un moyen inventé/manquant (leçon v1362/v1366).
  orders.forEach(o=>{
    paiementsDe(o).forEach(p=>{
      if(!p || !(+p.montant)) return;
      const ref = (typeof orderNumber==='function'?orderNumber(o):('CMD-'+o.id));
      if(!p.date && !o.date){
        anomalies.push(_auditAnomalie('critique','ENCAISSE_SANS_DATE', ref,
          `Encaissement de ${euro(+p.montant)} sans aucune date — invisible dans le CA mensuel.`,
          'Toute recette doit être datée pour tomber dans un mois.', +p.montant));
      }
      const moyen = (p.moyen||'').trim();
      if(/^acompte$/i.test(moyen)){
        anomalies.push(_auditAnomalie('alerte','MOYEN_EST_STATUT', ref,
          `Encaissement de ${euro(+p.montant)} dont le moyen est « Acompte » — un statut, pas un moyen.`,
          'Le moyen de paiement et le statut sont deux dimensions distinctes (v1362).', null));
      }
    });
  });

  // ── INVARIANT 4 : cohérence du solde (dû = encaissé + reste) ─────────────────────
  // orderBalance doit toujours valoir montant - encaissé. Si le statut dit « Payé » mais qu'il
  // reste un solde positif réel, le statut ment (ou l'inverse).
  orders.forEach(o=>{
    if(estReprise && estReprise(o)) return;
    const solde = orderBalance(o);
    const ref = (typeof orderNumber==='function'?orderNumber(o):('CMD-'+o.id));
    if(o.paiement==='Payé' && solde > 0.01){
      anomalies.push(_auditAnomalie('critique','PAYE_MAIS_SOLDE', ref,
        `Marquée « Payé » mais il reste ${euro(solde)} à encaisser.`,
        'Une commande « Payé » a un solde nul.', solde));
    }
  });

  // ── INVARIANT 5 : une reprise d'historique EST une recette, datée et chiffrée ─────
  // (leçon v1361 : les reprises font partie du CA. Ici on vérifie qu'elles sont exploitables.)
  orders.forEach(o=>{
    if(!(estReprise && estReprise(o))) return;
    const ref = (typeof orderNumber==='function'?orderNumber(o):('CMD-'+o.id));
    if(!(+o.montant>0)){
      anomalies.push(_auditAnomalie('alerte','REPRISE_SANS_MONTANT', ref,
        `Reprise d'historique sans montant — elle ne contribue à aucun CA.`,
        'Une reprise déclarée doit porter le montant réellement encaissé à l’époque.', 0));
    }
    if(!o.date){
      anomalies.push(_auditAnomalie('alerte','REPRISE_SANS_DATE', ref,
        `Reprise d'historique sans date — impossible à rattacher à un exercice.`,
        'Une reprise doit être datée pour être rattachée à son exercice.', +o.montant||0));
    }
  });

  // ── INVARIANT 6 : un marché clos est cohérent (fond de caisse ≤ espèces) ──────────
  // Si le fond de caisse dépasse les espèces comptées, la recette espèces calculée serait NÉGATIVE
  // ou tronquée à 0 → du CA marché s'évapore (leçon v1360 : le fond se déduit des espèces).
  markets.forEach(mk=>{
    if(mk.statut!=='clos') return;
    if(!_in(mk.date)) return;
    const ca = mk.ca||{};
    const fond = money2(+mk.fondCaisse||0);
    const esp  = money2(+ca.especes||0);
    const ref = 'MARCHE-'+mk.id+(mk.nom?(' '+mk.nom):'');
    if(fond > esp + 0.01){
      anomalies.push(_auditAnomalie('critique','FOND_SUP_ESPECES', ref,
        `Fond de caisse ${euro(fond)} > espèces comptées ${euro(esp)} — la recette espèces serait faussée.`,
        'Le fond de caisse se déduit des espèces ; il ne peut pas les dépasser.', fond-esp));
    }
    const totalCa = money2((+ca.especes||0)+(+ca.cb||0)+(+ca.autre||0));
    if(mk.statut==='clos' && totalCa<=0){
      anomalies.push(_auditAnomalie('info','MARCHE_CLOS_VIDE', ref,
        `Marché clos sans aucune recette enregistrée.`,
        'Un marché clos porte normalement une recette.', 0));
    }
  });

  // ── INVARIANT 7 : le livre des recettes retombe sur le CA encaissé ───────────────
  // LE contrôle-maître : deux chemins de calcul INDÉPENDANTS doivent donner le MÊME total.
  // Le livre (livreDesRecettes) et la compta (computeAccounting) partent des mêmes données mais
  // par des routes différentes. S'ils divergent, l'un des deux ment — et c'est invisible sans ça.
  try{
    const lignes = await livreDesRecettes(depuis, jusqu);
    const totalLivre = money2(lignes.reduce((s,l)=>s+(+l.montant||0),0));
    const compta = await computeAccounting(depuis||jusqu?{periodeStart:depuis,periodeEnd:jusqu}:{});
    const totalCA = money2(compta.totalEncaisse||0);
    // Le livre inclut les reprises (v1361), la compta les exclut (A4). On compare donc le livre
    // SANS reprises au CA encaissé — même périmètre, sinon l'écart serait normal et trompeur.
    const totalLivreSansReprises = money2(lignes
      .filter(l=>l.canal!=='Reprise historique')
      .reduce((s,l)=>s+(+l.montant||0),0));
    const ecart = money2(totalLivreSansReprises - totalCA);
    if(Math.abs(ecart) > 0.01){
      anomalies.push(_auditAnomalie('critique','LIVRE_VS_CA',
        'Période '+(depuis||'origine')+' → '+(jusqu||'ce jour'),
        `Le livre des recettes (${euro(totalLivreSansReprises)} hors reprises) et le CA encaissé `
        +`(${euro(totalCA)}) divergent de ${euro(Math.abs(ecart))}.`,
        'Deux calculs indépendants des recettes doivent donner le même total.', ecart));
    }
  }catch(e){ swallow(e,'auditComptable livre-vs-ca'); }

  // Tri : critique d'abord, puis alerte, puis info.
  const rang = { critique:0, alerte:1, info:2 };
  anomalies.sort((a,b)=> (rang[a.gravite]-rang[b.gravite]) || a.code.localeCompare(b.code));
  return anomalies;
}

