// [v1368] L'ÉCRAN D'AUDIT. Un bouton, une passe sur les vraies données, la vérité brute.
// ---------------------------------------------------------------------------
async function auditComptableForm(){
  const now = new Date();
  const anneeDebut = now.getFullYear()+'-01-01';
  openModal(`<h3>🔍 Contrôle de cohérence</h3>
    <p class="note">Cet outil ne recalcule rien — il vérifie que tes données <b>ne se contredisent pas</b> :
    comptabilité, chaîne de décrémentation du stock, et temps par recette.
    Chaque anomalie pointe une pièce précise et la règle qu'elle enfreint. Rien n'est corrigé
    automatiquement : <b>tu décides</b>.</p>
    <div class="row2">
      <div class="field"><label>Du</label><input type="date" id="au_depuis" value="${anneeDebut}"></div>
      <div class="field"><label>Au</label><input type="date" id="au_jusqu" value=""></div>
    </div>
    <p class="note" style="font-size:.75rem">Laisse les dates vides pour auditer <b>tout l'historique</b>.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="auditCompletLancer()">Lancer le contrôle complet</button>
    </div>`);
}

async function auditComptableLancer(){
  const depuis = val('au_depuis')||null;
  const jusqu  = val('au_jusqu')||null;
  openModal(`<h3>🔍 Contrôle en cours…</h3><p class="note">Lecture de la base…</p>`);
  let anomalies=[];
  try{ anomalies = await auditComptable({depuis, jusqu}); }
  catch(e){ swallow(e,'auditComptableLancer'); toast('Contrôle impossible'); return; }

  const nCrit = anomalies.filter(a=>a.gravite==='critique').length;
  const nAlerte = anomalies.filter(a=>a.gravite==='alerte').length;
  const nInfo = anomalies.filter(a=>a.gravite==='info').length;

  if(!anomalies.length){
    openModal(`<h3>✅ Aucune anomalie</h3>
      <p class="note">Sur la période analysée, <b>tous les contrôles de cohérence passent</b> :
      les encaissements retombent sur leurs commandes, le livre des recettes et le CA encaissé
      concordent, les marchés sont cohérents.</p>
      <p class="note" style="font-size:.78rem">C'est ça, la confiance : non pas une app qui promet
      de ne jamais se tromper, mais une app capable de <b>se contrôler elle-même</b>.</p>
      <div class="modal-actions"><button class="btn gold" onclick="closeModal()">Fermer</button></div>`);
    return;
  }

  const couleur = g => g==='critique'?'#b3261e':(g==='alerte'?'#b06a1e':'#7a6a3b');
  const label = g => g==='critique'?'CRITIQUE':(g==='alerte'?'ALERTE':'INFO');

  const bloc = anomalies.map(a=>`
    <div style="border-left:4px solid ${couleur(a.gravite)};background:#faf7f4;padding:8px 10px;margin:6px 0;border-radius:0 8px 8px 0">
      <div style="display:flex;justify-content:space-between;align-items:baseline;gap:8px">
        <b style="color:${couleur(a.gravite)};font-size:.72rem;letter-spacing:.04em">${label(a.gravite)}</b>
        <span style="font-size:.74rem;color:#9a8a82">${esc(a.piece)}</span>
      </div>
      <div style="margin:3px 0;font-size:.9rem">${esc(a.message)}</div>
      <div style="font-size:.74rem;color:#7a6a62;font-style:italic">Règle : ${esc(a.regle)}</div>
    </div>`).join('');

  openModal(`<h3>🔍 ${anomalies.length} anomalie(s)</h3>
    <div style="display:flex;gap:8px;margin-bottom:8px;flex-wrap:wrap">
      ${nCrit?`<span style="background:#b3261e;color:#fff;padding:2px 10px;border-radius:12px;font-size:.78rem">${nCrit} critique(s)</span>`:''}
      ${nAlerte?`<span style="background:#b06a1e;color:#fff;padding:2px 10px;border-radius:12px;font-size:.78rem">${nAlerte} alerte(s)</span>`:''}
      ${nInfo?`<span style="background:#7a6a3b;color:#fff;padding:2px 10px;border-radius:12px;font-size:.78rem">${nInfo} info(s)</span>`:''}
    </div>
    <p class="note" style="font-size:.76rem">Les anomalies <b>critiques</b> faussent un chiffre comptable.
    Les <b>alertes</b> signalent une donnée incohérente. Les <b>infos</b> sont à surveiller.</p>
    <div style="max-height:52vh;overflow:auto">${bloc}</div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="auditComptableForm()">◂ Autre période</button>
      <button class="btn gold" onclick="closeModal()">Fermer</button>
    </div>`);
}


// ════════════════════════════════════════════════════════════════════════════
//  [v1369] LE DÉTECTEUR ÉTENDU AU STOCK ET AU TEMPS
//
//  Ben : « Poursuis en développant cet outil dans les stocks, en particulier la décrémentation des
//  matières premières consommées à mesure que je produis. Applique-le aussi à l'atelier chrono et au
//  calcul du temps réel par recette produite. »
//
//  LA DIFFÉRENCE AVEC LA COMPTA : en compta, un total doit retomber sur ses lignes. En stock, c'est
//  une CHAÎNE qui doit rester CONTINUE — chaque prélèvement correspond à une matière qui EXISTAIT, en
//  quantité suffisante, au moment de la production. Un maillon rompu, et la traçabilité HACCP ment.
//
//  Pour le TEMPS, le mensonge est différent : un temps par recette est un RATIO (minutes ÷ macarons).
//  Un ratio ment quand un de ses termes est absent ou non représentatif — du temps sans production,
//  de la production sans temps, ou une moyenne calculée sur trop peu pour vouloir dire quelque chose.
//
//  MÊME DISCIPLINE QUE v1368 : on ne recalcule pas, on VÉRIFIE LA COHÉRENCE. On ne corrige rien —
//  on montre, on localise, on nomme la règle. Ben décide.
// ════════════════════════════════════════════════════════════════════════════

// ---------------------------------------------------------------------------
// AUDIT STOCK — la chaîne de décrémentation FIFO doit rester continue.
// ---------------------------------------------------------------------------
async function auditStock(){
  const anomalies = [];
  const lots   = await db.materialLots.toArray().catch(()=>[]);
  const conso  = (await db.prodConsumption.toArray().catch(()=>[])).filter(c=>!c.annuleeInventaire);
  const prods  = await db.productions.toArray().catch(()=>[]);
  const mats   = await db.materials.toArray().catch(()=>[]);
  // [v1370] Les pertes formelles (casse, péremption) décrémentent le stock SANS consommation.
  // S3 doit les déduire, sinon un lot où on a jeté de la matière paraît « incohérent ».
  const pertes = await db.materialLosses.toArray().catch(()=>[]);
  const perteParLot = {};
  (pertes||[]).forEach(pl=>{ if(pl.lotId!=null) perteParLot[pl.lotId] = round3((perteParLot[pl.lotId]||0) + (+pl.qte||0)); });

  const lotById  = id => lots.find(l=>+l.id===+id);
  const prodById = id => prods.find(p=>+p.id===+id);
  const matNom   = id => { const m=mats.find(x=>+x.id===+id); return m?(m.nom||('#'+id)):('#'+id); };

  // ── INVARIANT S1 : toute consommation pointe un lot QUI EXISTE ───────────────────
  // Une conso rattachée à un lot supprimé = un prélèvement fantôme. La matière a été « consommée »
  // sur rien : la traçabilité (d'où vient ce macaron ?) est rompue.
  conso.forEach(c=>{
    if(c.materialLotId==null) return;   // conso sans lot (matière libre) : hors périmètre chaîne
    if(!lotById(c.materialLotId)){
      const p = prodById(c.productionId);
      anomalies.push(_auditAnomalie('critique','CONSO_LOT_FANTOME',
        p?(p.lotProduction||('PROD-'+p.id)):('PROD-'+c.productionId),
        `Une production a prélevé ${qty(+c.qteConsommee||0)} sur un lot de matière qui n'existe plus.`,
        'Toute consommation doit pointer un lot réel — sinon la traçabilité est rompue.',
        null));
    }
  });

  // ── INVARIANT S2 : la somme consommée sur un lot ≤ sa quantité initiale ───────────
  // Si un lot a livré plus que ce qu'il contenait, une décrémentation FIFO a débordé : du stock
  // a été prélevé là où il n'y en avait pas. C'est LE bug que Ben redoute — la conso « en douce »
  // sur le mauvais stock.
  const consoParLot = {};
  conso.forEach(c=>{ if(c.materialLotId!=null) consoParLot[c.materialLotId] = round3((consoParLot[c.materialLotId]||0) + (+c.qteConsommee||0)); });
  Object.keys(consoParLot).forEach(lotId=>{
    const lot = lotById(lotId); if(!lot) return;   // déjà couvert par S1
    const initiale = round3(+lot.qteInitiale||0);
    const consomme = consoParLot[lotId];
    if(consomme > initiale + 0.001){
      anomalies.push(_auditAnomalie('critique','LOT_SURCONSOMME',
        `Lot ${matNom(lot.materialId)} #${lot.id}`,
        `Ce lot a livré ${qty(consomme)} alors qu'il n'en contenait que ${qty(initiale)} — `
        +`${qty(consomme-initiale)} prélevé(s) sur du stock inexistant.`,
        'La somme consommée sur un lot ne peut pas dépasser sa quantité initiale.',
        null));
    }
  });

  // ── INVARIANT S3 : qteRestante = initiale − conso − pertes − ajustements ──────────
  // LE contrôle-maître du stock — mais il ne vaut QUE s'il connaît TOUT ce qui décrémente un lot
  // légitimement. Un lot baisse par TROIS chemins : la consommation (production), la perte formelle
  // (casse/péremption, `materialLosses`), et l'ajustement d'inventaire (`ajustInventaire`, tracé
  // depuis v1370). S3 déduit les trois.
  //
  // POURQUOI C'EST CAPITAL (leçon apprise en production, sur 65 faux positifs) : un contrôle qui crie
  // au loup sur des ajustements LÉGITIMES détruit la confiance aussi sûrement qu'un vrai mensonge —
  // Ben finirait par ignorer toutes les alertes, y compris les vraies. Un faux positif n'est pas un
  // désagrément mineur : c'est du bruit qui masque le signal.
  //
  // L'HONNÊTETÉ SUR LA LIMITE : les ajustements d'inventaire ANTÉRIEURS à v1370 ne sont pas tracés
  // (le champ n'existait pas). Pour ces lots, l'écart est INEXPLICABLE par les données — pas parce
  // que le stock ment, mais parce que la trace manque. On NE crie donc PAS « incohérence » : on
  // classe en INFO « écart non tracé », et seulement si l'affiché est INFÉRIEUR à l'attendu (un
  // ajustement à la baisse non tracé). Un affiché SUPÉRIEUR à l'attendu, lui, reste une vraie alerte :
  // du stock est apparu de nulle part.
  lots.forEach(lot=>{
    const initiale = round3(+lot.qteInitiale||0);
    const consomme = consoParLot[lot.id] || 0;
    const perte    = perteParLot[lot.id] || 0;
    const ajust    = round3(+lot.ajustInventaire||0);
    const attendu  = round3(initiale - consomme - perte - ajust);
    const affiche  = round3(+lot.qteRestante||0);
    const ecart    = round3(affiche - attendu);
    if(Math.abs(ecart) <= 0.01) return;   // cohérent une fois tout déduit

    if(ecart > 0.01){
      // Affiché > attendu : du stock est apparu sans justification → vraie alerte.
      anomalies.push(_auditAnomalie('alerte','RESTANT_SUPERIEUR',
        `Lot ${matNom(lot.materialId)} #${lot.id}`,
        `Stock affiché ${qty(affiche)} SUPÉRIEUR à l'attendu ${qty(attendu)} `
        +`(initiale ${qty(initiale)} − conso ${qty(consomme)}${perte?` − perte ${qty(perte)}`:''}${ajust?` − ajust. ${qty(ajust)}`:''}). `
        +`${qty(ecart)} de trop.`,
        'Un lot ne peut pas afficher plus que son initiale moins ce qui en est sorti.',
        null));
    } else {
      // Affiché < attendu : très probablement un ajustement d'inventaire non tracé (historique).
      // INFO, pas alerte : ce n'est pas un mensonge, c'est une trace manquante.
      anomalies.push(_auditAnomalie('info','ECART_NON_TRACE',
        `Lot ${matNom(lot.materialId)} #${lot.id}`,
        `Stock affiché ${qty(affiche)}, inférieur de ${qty(-ecart)} à l'attendu ${qty(attendu)} — `
        +`probablement un ajustement d'inventaire antérieur au suivi (non tracé sur ce lot).`,
        'Écart à la baisse sans trace : ajustement d\'inventaire probable, à confirmer.',
        null));
    }
  });

  // ── INVARIANT S4 : pas de restant négatif ────────────────────────────────────────
  // Un stock négatif est impossible physiquement — c'est le symptôme franc d'une sur-décrémentation.
  lots.forEach(lot=>{
    const r = round3(+lot.qteRestante||0);
    if(r < -0.001){
      anomalies.push(_auditAnomalie('critique','RESTANT_NEGATIF',
        `Lot ${matNom(lot.materialId)} #${lot.id}`,
        `Stock restant NÉGATIF : ${qty(r)}. Une décrémentation a prélevé plus que disponible.`,
        'Un stock ne peut pas être négatif.', null));
    }
  });

  // ── INVARIANT S5 : une production « faite » a consommé de la matière ──────────────
  // Une production terminée avec une recette et des pièces, mais SANS aucune consommation, n'a rien
  // décrémenté : le stock n'a pas bougé alors que la matière a bien été utilisée. Info (pas critique :
  // certains lots anciens sont pré-migration), mais à surveiller — c'est du stock qui ne se vide pas.
  const consoParProd = {};
  conso.forEach(c=>{ consoParProd[c.productionId] = (consoParProd[c.productionId]||0) + 1; });
  prods.forEach(p=>{
    if(p.histo) return;                       // reprises : pas de conso attendue
    if(p.recipeId==null || p.libre) return;   // production libre : pas de recette liée
    const q = (+p.qteReelle||+p.qteProduite||0);
    if(!(q>0)) return;
    const faite = (p.statut==='Terminée' || p.rangee || (+p.qteReelle>0));
    if(faite && !consoParProd[p.id]){
      anomalies.push(_auditAnomalie('info','PROD_SANS_CONSO',
        (p.lotProduction||('PROD-'+p.id)),
        `Production terminée (${qty(q)}) sans aucune consommation de matière enregistrée.`,
        'Une production avec recette décrémente normalement de la matière.', null));
    }
  });

  return anomalies;
}

// ---------------------------------------------------------------------------
// AUDIT TEMPS — le temps par recette est un ratio ; ses deux termes doivent être réels.
// ---------------------------------------------------------------------------
async function auditTemps(jours){
  jours = +jours || 90;
  const anomalies = [];

  const sessions = (typeof prodSessLoad==='function') ? prodSessLoad() : [];
  const prods    = await db.productions.toArray().catch(()=>[]);
  const recipes  = await db.recipes.toArray().catch(()=>[]);
  const recNom   = rid => { const r=recipes.find(x=>+x.id===+rid); return r?(r.produitNom||('recette #'+rid)):('recette #'+rid); };

  // ── INVARIANT T1 : une tâche chrono a un début ET une fin cohérents ───────────────
  // Une tâche dont la fin précède le début produit une durée NÉGATIVE, qui empoisonne toute moyenne
  // où elle entre. Une tâche sans fin (jamais arrêtée) n'est pas mesurée mais peut fausser l'affichage.
  sessions.forEach(s=>{
    (s.tasks||[]).forEach(t=>{
      if(!t.start) return;
      if(t.end && (new Date(t.end) < new Date(t.start))){
        anomalies.push(_auditAnomalie('critique','TACHE_DUREE_NEGATIVE',
          `${recNom(t.recipeId)} · ${(s.date||'').slice(0,10)}`,
          `Une tâche d'atelier finit avant d'avoir commencé — durée négative, moyenne faussée.`,
          'La fin d’une tâche doit être postérieure à son début.', null));
      }
    });
  });

  // ── INVARIANT T2 : le temps par recette n'est présenté que s'il est FIABLE ────────
  // prodTempsParParfum expose un flag `fiable` (assez de temps ET de pièces). Un temps NON fiable
  // affiché comme une mesure est un mensonge par excès de confiance (leçon v1337 : zéro/peu n'est
  // pas une mesure). On signale les recettes dont le temps existe mais n'est pas fiable.
  let parRec = {};
  try{ parRec = await prodTempsParParfum(jours); }catch(e){ swallow(e,'auditTemps tpp'); }
  Object.keys(parRec).forEach(rid=>{
    const e = parRec[rid];
    if(e && e.minParMac>0 && !e.fiable){
      anomalies.push(_auditAnomalie('info','TEMPS_NON_FIABLE',
        recNom(rid),
        `Temps mesuré (${(e.minParMac).toFixed(2)} min/macaron) mais sur trop peu de données pour être fiable `
        +`(${e.minAtelier} min d'atelier, ${qty(e.nbMac)} macarons).`,
        'Un temps par recette n’est fiable qu’avec assez d’atelier et de pièces mesurés.', null));
    }
  });

  // ── INVARIANT T3 : du temps d'atelier sur une recette SANS production mesurée ──────
  // Si une recette a du temps d'atelier cumulé mais zéro macaron produit sur la fenêtre, le ratio est
  // indéfini (division par zéro) : le temps existe mais ne se rattache à aucune sortie. Le temps est
  // « perdu » comptablement — il ne coûtera à aucun macaron, faussant la rentabilité par parfum.
  const msParRec = {};
  const since = new Date(); since.setDate(since.getDate()-jours);
  const sinceStr = (typeof ymdLocal==='function') ? ymdLocal(since) : since.toISOString().slice(0,10);
  sessions.filter(s=>(s.date||'').slice(0,10) >= sinceStr).forEach(s=>{
    if(typeof prodSessTempsParRecette!=='function') return;
    const parRecSession = prodSessTempsParRecette(s);
    Object.keys(parRecSession).forEach(rid=>{ msParRec[rid] = (msParRec[rid]||0) + parRecSession[rid]; });
  });
  const macParRec = {};
  prods.forEach(p=>{
    const c = p.composant||'complet';
    if(c!=='complet' && c!=='assemble' && c!=='coques') return;
    if(p.libre || p.recipeId==null) return;
    const d = (p.date || (p.prodTimestamp||'').slice(0,10) || '');
    if(String(d).slice(0,10) < sinceStr) return;
    const q = (+p.qteReelle||+p.qteProduite||0); if(!(q>0)) return;
    const macEq = (c==='coques') ? (q / (typeof COQUES_PAR_MACARON!=='undefined'?COQUES_PAR_MACARON:2)) : q;
    macParRec[p.recipeId] = (macParRec[p.recipeId]||0) + macEq;
  });
  Object.keys(msParRec).forEach(rid=>{
    const minAtelier = msParRec[rid]/60000;
    if(minAtelier >= 20 && !(macParRec[rid]>0)){
      anomalies.push(_auditAnomalie('alerte','TEMPS_SANS_PRODUCTION',
        recNom(rid),
        `${Math.round(minAtelier)} min d'atelier mesurées mais aucun macaron produit sur ${jours} j — `
        +`ce temps ne se rattache à aucune sortie.`,
        'Du temps d’atelier doit correspondre à une production, sinon la rentabilité par parfum est faussée.',
        null));
    }
  });

  return anomalies;
}

// ---------------------------------------------------------------------------
// [v1369] AUDIT GLOBAL — compta + stock + temps, en une passe.
// ---------------------------------------------------------------------------
async function auditComplet(opts){
  opts = opts || {};
  const out = { compta:[], stock:[], temps:[] };
  try{ out.compta = await auditComptable(opts); }catch(e){ swallow(e,'auditComplet compta'); }
  try{ out.stock  = await auditStock(); }catch(e){ swallow(e,'auditComplet stock'); }
  try{ out.temps  = await auditTemps(opts.jours||90); }catch(e){ swallow(e,'auditComplet temps'); }
  return out;
}

function _auditRenderBloc(titre, anomalies){
  if(!anomalies.length){
    return `<div style="margin:8px 0"><b>${esc(titre)}</b> — <span style="color:#3f7d52">✓ aucune anomalie</span></div>`;
  }
  const couleur = g => g==='critique'?'#b3261e':(g==='alerte'?'#b06a1e':'#7a6a3b');
  const label = g => g==='critique'?'CRITIQUE':(g==='alerte'?'ALERTE':'INFO');
  const items = anomalies.map(a=>`
    <div style="border-left:4px solid ${couleur(a.gravite)};background:#faf7f4;padding:7px 9px;margin:5px 0;border-radius:0 8px 8px 0">
      <div style="display:flex;justify-content:space-between;gap:8px">
        <b style="color:${couleur(a.gravite)};font-size:.7rem;letter-spacing:.04em">${label(a.gravite)}</b>
        <span style="font-size:.72rem;color:#9a8a82">${esc(a.piece)}</span>
      </div>
      <div style="margin:2px 0;font-size:.88rem">${esc(a.message)}</div>
      <div style="font-size:.72rem;color:#7a6a62;font-style:italic">Règle : ${esc(a.regle)}</div>
    </div>`).join('');
  return `<div style="margin:10px 0"><b>${esc(titre)}</b> — ${anomalies.length} anomalie(s)</div>${items}`;
}

async function auditCompletLancer(){
  const depuis = val('au_depuis')||null;
  const jusqu  = val('au_jusqu')||null;
  openModal(`<h3>🔍 Contrôle en cours…</h3><p class="note">Lecture de la base (compta, stock, temps)…</p>`);
  let R = {compta:[],stock:[],temps:[]};
  try{ R = await auditComplet({depuis, jusqu, jours:90}); }
  catch(e){ swallow(e,'auditCompletLancer'); toast('Contrôle impossible'); return; }

  const tout = [...R.compta, ...R.stock, ...R.temps];
  const nCrit = tout.filter(a=>a.gravite==='critique').length;
  const nAlerte = tout.filter(a=>a.gravite==='alerte').length;
  const nInfo = tout.filter(a=>a.gravite==='info').length;

  if(!tout.length){
    openModal(`<h3>✅ Aucune anomalie</h3>
      <p class="note">Sur la période analysée, <b>tous les contrôles passent</b> : la comptabilité
      concorde, la chaîne de décrémentation du stock est continue, et les temps par recette sont fiables.</p>
      <p class="note" style="font-size:.78rem">C'est ça, la confiance : une app capable de
      <b>se contrôler elle-même</b>.</p>
      <div class="modal-actions"><button class="btn gold" onclick="closeModal()">Fermer</button></div>`);
    return;
  }

  openModal(`<h3>🔍 ${tout.length} anomalie(s)</h3>
    <div style="display:flex;gap:8px;margin-bottom:8px;flex-wrap:wrap">
      ${nCrit?`<span style="background:#b3261e;color:#fff;padding:2px 10px;border-radius:12px;font-size:.78rem">${nCrit} critique(s)</span>`:''}
      ${nAlerte?`<span style="background:#b06a1e;color:#fff;padding:2px 10px;border-radius:12px;font-size:.78rem">${nAlerte} alerte(s)</span>`:''}
      ${nInfo?`<span style="background:#7a6a3b;color:#fff;padding:2px 10px;border-radius:12px;font-size:.78rem">${nInfo} info(s)</span>`:''}
    </div>
    <div style="max-height:56vh;overflow:auto">
      ${_auditRenderBloc('📊 Comptabilité', R.compta)}
      ${_auditRenderBloc('📦 Stock & décrémentation', R.stock)}
      ${_auditRenderBloc('⏱ Temps par recette', R.temps)}
    </div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="auditComptableForm()">◂ Autre période</button>
      <button class="btn gold" onclick="closeModal()">Fermer</button>
    </div>`);
}


async function computeAccounting(opts){
  opts=opts||{};
  const _periodeStart = opts.periodeStart || null; // filtre optionnel par date de début
  const _periodeEnd = opts.periodeEnd || null;     // filtre optionnel par date de fin (incluse)
  const _inRange = (dateStr) => {
    const d = dateStr||'';
    if(_periodeStart && d < _periodeStart) return false;
    if(_periodeEnd && d > _periodeEnd) return false;
    return true;
  };
  const allOrders = await db.orders.toArray();
  // Filtre par période. IMPORTANT : pour le CA ENCAISSÉ (cash basis), une commande doit être
  // retenue dès qu'un de ses PAIEMENTS tombe dans la période — même si sa date de commande est
  // hors période (ex. commande de septembre payée en mai). On inclut donc une commande si sa
  // date de commande OU au moins un paiement est dans la plage. Chaque sous-calcul refiltre
  // ensuite par sa propre date (paiement par date de paiement, facturé par date de commande).
  const _orderPayDates = (o)=> paiementsDe(o).map(p=>p && p.date).filter(Boolean);
  const _orderInRange = (o)=>{
    if(_inRange(o.date)) return true;                       // date de commande dans la plage
    return _orderPayDates(o).some(d=>_inRange(d));          // ou un paiement dans la plage
  };
  // [AUDIT-2026-07 · A4] Une REPRISE d'historique (migration) ne compte PAS dans le CA encaissé ni les
  // cotisations : c'est un CA passé, déjà déclaré à l'époque — le réintégrer serait une double
  // déclaration URSSAF. Le Dashboard (caDuMois) les exclut déjà ; on aligne la Compta via le MÊME
  // prédicat partagé estReprise (couvre o.histo ET une ligne type 'histo').
  const ordersInRange = (_periodeStart||_periodeEnd) ? allOrders.filter(_orderInRange) : allOrders;
  const orders = ordersInRange.filter(o=>!estReprise(o));   // CA/cotisations : reprises exclues
  const allCharges = await (db.charges?db.charges.toArray():Promise.resolve([])).catch(()=>[]);
  const charges = (_periodeStart||_periodeEnd) ? allCharges.filter(c=> _inRange(c.date)) : allCharges;
  const recipes = await db.recipes.toArray();
  const recipeItems = await db.recipeItems.toArray();
  const lots = await db.materialLots.toArray();
  const allMarkets = await (db.markets?db.markets.toArray():Promise.resolve([])).catch(()=>[]);
  const markets = (_periodeStart||_periodeEnd) ? allMarkets.filter(k=> _inRange(k.date)) : allMarkets;

  // 1) ENCAISSEMENTS par date réelle de paiement (cash basis)
  //    Chaque ligne de paiement {date, montant, moyen} compte au mois de SA date.
  const encByMonth={};      // 'YYYY-MM' -> total encaissé
  const encByMethod={};     // moyen -> total
  let totalEncaisse=0;
  // CA FACTURÉ (accrual) : montant total de la commande, à la date de commande.
  // Une commande "En attente de paiement" est facturée mais PAS encaissée → exclue du CA encaissé.
  const factByMonth={}; let totalFacture=0;
  orders.forEach(o=>{
    // CA facturé : à la date de COMMANDE, et uniquement si celle-ci est dans la période.
    // (une commande incluse seulement via un paiement hors période ne doit pas gonfler le facturé)
    if(_inRange(o.date)){
      const mF=monthKey(o.date); const tot=money2(o.montant);
      if(mF && tot>0){ factByMonth[mF]=money2((factByMonth[mF]||0)+tot); totalFacture=money2(totalFacture+tot); }
    }
    const list = paiementsDe(o);
    list.forEach(p=>{
      const m=monthKey(p.date); if(!m) return;
      if((_periodeStart||_periodeEnd) && !_inRange(p.date)) return;   // paiement hors période → ignoré
      const v=money2(p.montant);
      encByMonth[m]=money2((encByMonth[m]||0)+v);
      encByMethod[p.moyen||'—']=money2((encByMethod[p.moyen||'—']||0)+v);
      totalEncaisse=money2(totalEncaisse+v);
    });
  });

  // 1b) VENTES DE MARCHÉ (clôturées) : encaissement immédiat → facturé = encaissé au mois de clôture.
  //     Réparti par mode de paiement (Espèces / Carte / Autre). Évite tout double comptage :
  //     les ventes de marché ne passent jamais par la table orders.
  let totalMarches=0;
  markets.forEach(mk=>{
    if(mk.statut!=='clos') return;
    const ca=mk.ca||{}; const fond=money2(+mk.fondCaisse||0);
    const esp=money2(Math.max(0,(+ca.especes||0)-fond)), cb=money2(ca.cb||0), au=money2(ca.autre||0);
    const tot=money2(esp+cb+au); if(tot<=0) return;
    const m=monthKey(mk.date); if(!m) return;
    encByMonth[m]=money2((encByMonth[m]||0)+tot);
    factByMonth[m]=money2((factByMonth[m]||0)+tot);
    totalEncaisse=money2(totalEncaisse+tot); totalFacture=money2(totalFacture+tot); totalMarches=money2(totalMarches+tot);
    if(esp>0) encByMethod['Espèces']=money2((encByMethod['Espèces']||0)+esp);
    if(cb>0) encByMethod['Carte']=money2((encByMethod['Carte']||0)+cb);
    if(au>0) encByMethod['Autre (marché)']=money2((encByMethod['Autre (marché)']||0)+au);
  });

  // 1c) [v1283 · JOURNAL D'AVOIRS] Remboursements émis : DÉDUITS du CA encaissé ET facturé, au
  // mois d'ÉMISSION de l'avoir (règle comptable standard — pas rétroactif sur le mois de la
  // commande d'origine, qui reste un fait historique inchangé). Sans cette déduction, un CA
  // remboursé resterait compté dans la base URSSAF → cotisations sur-estimées (cf. audit externe).
  // Ne modifie JAMAIS o.paiements[] : l'avoir est une écriture symétrique séparée.
  let totalAvoirs=0;
  const allAvoirs = await (db.documents?db.documents.where('type').equals('avoir').toArray():Promise.resolve([])).catch(()=>[]);
  const avoirsEmis = allAvoirs.filter(a=>a.statut==='emis' || a.statut==='enregistre');
  avoirsEmis.forEach(a=>{
    if((_periodeStart||_periodeEnd) && !_inRange(a.date)) return;
    const m=monthKey(a.date); const v=money2(+a.montant||0); if(!m || v<=0) return;
    encByMonth[m]=money2((encByMonth[m]||0)-v);
    factByMonth[m]=money2((factByMonth[m]||0)-v);
    totalEncaisse=money2(totalEncaisse-v); totalFacture=money2(totalFacture-v); totalAvoirs=money2(totalAvoirs+v);
  });

  // 2) CHARGES par mois (date de la charge) + par catégorie
  const chargeByMonth={}, chargeByCat={};
  let totalCharges=0;
  charges.forEach(c=>{
    const m=monthKey(c.date); const v=money2(c.montant);
    if(m) chargeByMonth[m]=money2((chargeByMonth[m]||0)+v);
    chargeByCat[c.categorie||'Autre']=money2((chargeByCat[c.categorie||'Autre']||0)+v);
    totalCharges=money2(totalCharges+v);
  });

  // 3) Coût matières des commandes (pour marge brute indicative) — au mois d'encaissement
  //    On rattache le coût matière estimé d'une commande au(x) mois où elle est encaissée,
  //    au prorata du montant encaissé.
  const costByMonth={};
  orders.forEach(o=>{
    const total=money2(o.montant); if(total<=0) return;
    const coutMat = estimateOrderMaterialCost(o, recipes, recipeItems, lots);
    const pays = paiementsDe(o);
    pays.forEach(p=>{
      const m=monthKey(p.date); if(!m) return;
      if((_periodeStart||_periodeEnd) && !_inRange(p.date)) return;   // paiement hors période → ignoré
      const ratio=total>0?(money2(p.montant)/total):0;
      costByMonth[m]=money2((costByMonth[m]||0)+coutMat*ratio);
    });
  });

  // 3b) Coûts des marchés clôturés (matière des vendus + emballages delta), au mois de clôture.
  const avgUnitMat = avgMacaronCost(recipes, recipeItems, lots);
  // (chargement des mouvements pour le coût matière marché)
  const allMoves = await (db.marketMoves?db.marketMoves.toArray():Promise.resolve([])).catch(()=>[]);
  const movesByMk={}; allMoves.forEach(mv=>{ (movesByMk[mv.marketId] ||= []).push(mv); });
  let totalCoutMarches=0;
  markets.forEach(mk=>{
    if(mk.statut!=='clos') return;
    const T=marketTotals(mk, movesByMk[mk.id]||[], avgUnitMat);
    const m=monthKey(mk.date); if(!m) return;
    const c=money2(T.coutMat+T.coutEmb+(T.coutMarche||0));
    costByMonth[m]=money2((costByMonth[m]||0)+c);
    totalCoutMarches=money2(totalCoutMarches+c);
  });

  // 4) Série mensuelle consolidée
  const months=[...new Set([...Object.keys(encByMonth),...Object.keys(chargeByMonth),...Object.keys(factByMonth)])].sort();
  const serie=months.map(m=>{
    const ca=encByMonth[m]||0, fact=factByMonth[m]||0, ch=chargeByMonth[m]||0, cout=costByMonth[m]||0;
    return {mois:m, ca, caFacture:fact, charges:ch, coutMatieres:money2(cout),
      margeBrute:money2(ca-cout), resultat:money2(ca-ch-cout)};
  });

  // 5) Solde clients dû (créances) = total commandes − encaissé, pour les non soldées
  let creances=0;
  orders.forEach(o=>{ const b=orderBalance(o); if(b>0) creances=money2(creances+b); });

  const totalCout=money2(serie.reduce((s,x)=>s+x.coutMatieres,0));
  // Part des commandes migrées (reprise) : leur coût matières est estimé grossièrement
  // (pas de détail produit), donc la marge est moins fiable. On le signale.
  // [A4] Reprises EXCLUES du CA de la période : on les compte ici pour transparence (migCA = CA mis de
  // côté). Calculé sur ordersInRange (avant exclusion), avec le même prédicat que le filtre ci-dessus.
  let migCount=0, migCA=0;
  ordersInRange.forEach(o=>{
    if(estReprise(o)){ migCount++; migCA=money2(migCA+(+o.montant||0)); }
  });
  // Valeur des pertes / casse déclarées (coût de revient des pièces jetées) — imputée au résultat.
  // [AUDIT-2026-07 · A25] AVANT : lossesAll non filtré → le résultat du mois M incluait les pertes
  // de TOUT l'historique (ex. pertes de migration 2024 déduites d'un résultat de juin 2026). On filtre
  // désormais par _inRange, comme les charges/marchés/paiements (comptabilité d'engagement : perte
  // rattachée à sa date). En mode « tout » (pas de période), comportement inchangé.
  const lossesAll = await db.losses.toArray().catch(()=>[]);
  const losses = (_periodeStart||_periodeEnd) ? lossesAll.filter(l=> _inRange(l.date)) : lossesAll;
  const totalPertes = money2(losses.reduce((s,l)=>s+(+l.coutTotal||0),0));
  return {
    serie, encByMethod, chargeByCat,
    totalEncaisse, totalFacture, totalCharges, totalCoutMatieres:totalCout,
    totalMarches, totalPertes,
    margeBrute: money2(totalEncaisse-totalCout),
    resultat: money2(totalEncaisse-totalCharges-totalCout-totalPertes),
    creances,
    migCount, migCA,
    // [v1283 · JOURNAL D'AVOIRS] Total des remboursements émis sur la période (déjà déduit
    // ci-dessus de totalEncaisse/totalFacture) — exposé pour affichage transparent.
    totalAvoirs, nbAvoirs: avoirsEmis.length,
    // [A11-display] CA activité globale = CA fiscal (hors reprises) + reprises (déjà déclarées ailleurs).
    caActiviteTotale: money2(totalFacture + migCA),
    nbCharges: charges.length
  };
}

// ============================================================
//  [v1283] TRÉSORERIE PROSPECTIVE — solde saisi + projection J+30/60/90.
//  Solde bancaire saisi à la main (getSettings().soldeBancaire, mis à jour périodiquement),
//  projeté à l'aide de :
//    + créances clients (commandes non soldées), datées par dateLivraison (proxy : le solde
//      d'une commande devient généralement exigible à la livraison/l'événement) ou o.date à
//      défaut. Reprises exclues (estReprise) — même règle que partout ailleurs : un CA passé
//      déjà réglé n'est pas une créance future.
//    − charges déjà engagées et non payées (aucune notion de "payée" sur une charge dans le
//      modèle actuel → toute charge future datée compte comme sortie, cf. limite documentée).
//    − charges récurrentes actives (modèles), projetées sur leurs prochaines échéances
//      (jourMois) non encore matérialisées dans db.charges.
//  Ne modifie AUCUN calcul existant (Compta, URSSAF) — moteur additif en lecture seule.
// ============================================================
async function computeTresorerie(){
  const s = getSettings();
  const solde = s.soldeBancaire;
  const soldeDate = s.soldeBancaireDate;
  const today0 = today();
  const jAujourdhui = new Date(today0+'T00:00:00');

  const allOrders = await db.orders.toArray().catch(()=>[]);
  const clientsAll = await db.clients.toArray().catch(()=>[]);
  const _cliNom = id => { const c=clientsAll.find(x=>+x.id===+id); return c?(c.nom||c.prenom||'Client'):'Client'; };
  const orders = allOrders.filter(o=>!estReprise(o));
  // [v1283 · JOURNAL D'AVOIRS] Un avoir émis sur une commande PAS ENCORE soldée réduit d'autant
  // la créance restante (ex. annulation partielle avant paiement complet). orderBalance() seul
  // ne le sait pas (il ne lit que o.paiements[], jamais modifié par un avoir) → on soustrait ici
  // les avoirs déjà émis par commande, sans jamais toucher au registre de paiements lui-même.
  const allAvoirsT = await (db.documents?db.documents.where('type').equals('avoir').toArray():Promise.resolve([])).catch(()=>[]);
  const avoirsParCommande = {};
  allAvoirsT.forEach(a=>{
    if(a.statut!=='emis' && a.statut!=='enregistre') return;
    if(!a.orderId) return;
    avoirsParCommande[a.orderId] = money2((avoirsParCommande[a.orderId]||0) + (+a.montant||0));
  });
  // Créances : solde restant dû par commande, datées par dateLivraison (proxy d'exigibilité).
  const creances = [];
  orders.forEach(o=>{
    const balBrut = orderBalance(o);
    const bal = money2(Math.max(0, balBrut - (avoirsParCommande[o.id]||0)));
    if(bal<=0) return;
    const d = o.dateLivraison || o.date || today0;
    creances.push({ label: (o.clientId ? _cliNom(o.clientId) : (o.histoLabel||('Commande #'+o.id))), date:d, montant:bal, orderId:o.id });
  });

  // Charges à venir : ponctuelles déjà saisies avec une date future, + prochaines échéances
  // des modèles récurrents actifs (non encore matérialisées).
  const allCharges = await (db.charges?db.charges.toArray():Promise.resolve([])).catch(()=>[]);
  const chargesFutures = allCharges.filter(c=>(c.date||'')>today0)
    .map(c=>({label:c.libelle||c.categorie||'Charge', date:c.date, montant:money2(+c.montant||0)}));

  const models = getRecurringCharges().filter(m=>m.actif!==false && +m.montant>0);
  const chargesRecurrentesFutures = [];
  models.forEach(m=>{
    const jour = Math.min(28, Math.max(1, +m.jourMois||1));
    // Prochaines échéances sur les 3 prochains mois (largement suffisant pour un horizon 90j).
    const base = new Date(jAujourdhui.getFullYear(), jAujourdhui.getMonth(), jour);
    for(let i=0;i<4;i++){
      const d = new Date(base.getFullYear(), base.getMonth()+i, jour);
      const ymd = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
      if(ymd<=today0) continue;   // déjà passée ou déjà matérialisée en charge ponctuelle
      chargesRecurrentesFutures.push({label:m.libelle||'Charge récurrente', date:ymd, montant:money2(+m.montant||0)});
    }
  });

  const jalons = [30,60,90].map(nbJours=>{
    const limite = new Date(jAujourdhui); limite.setDate(limite.getDate()+nbJours);
    const limiteStr = limite.getFullYear()+'-'+String(limite.getMonth()+1).padStart(2,'0')+'-'+String(limite.getDate()).padStart(2,'0');
    const dansPeriode = (d)=> d>today0 ? d<=limiteStr : true;   // créances déjà en retard comptent quand même (à venir "dès que possible")
    const detailCreances = creances.filter(c=>dansPeriode(c.date));
    const detailChargesP = chargesFutures.filter(c=>c.date<=limiteStr);
    const detailChargesR = chargesRecurrentesFutures.filter(c=>c.date<=limiteStr);
    const totCreances = money2(detailCreances.reduce((s,c)=>s+c.montant,0));
    const totCharges = money2(detailChargesP.reduce((s,c)=>s+c.montant,0) + detailChargesR.reduce((s,c)=>s+c.montant,0));
    const solveur = (solde!=null) ? money2(solde + totCreances - totCharges) : null;
    return { nbJours, limite:limiteStr, totCreances, totCharges, solveur,
      detail:{creances:detailCreances, chargesPonctuelles:detailChargesP, chargesRecurrentes:detailChargesR} };
  });

  return { solde, soldeDate, today:today0, jalons, totalCreances: money2(creances.reduce((s,c)=>s+c.montant,0)) };
}
// Enregistre/actualise le solde bancaire saisi à la main.
function saveSoldeBancaire(montant){
  const s = getSettings();
  s.soldeBancaire = money2(+montant||0);
  s.soldeBancaireDate = today();
  saveSettings(s);
}

// ============================================================
//  [v1283] MODULE SCÉNARIOS — impact d'un changement de PRIX sur CA/marge/runway.
//  Base : totals.{ca, pieces, margeNette} d'analyzeFlavorProfitability sur une période
//  choisie (donc AUCUN nouveau calcul de coût — on réutilise le moteur de marge existant,
//  seule source de vérité). Deux modes de volume :
//    'constant' : le nombre de pièces vendues ne change pas (effet prix pur, cas le plus
//                 simple à lire — "si j'avais vendu pareil à ce nouveau prix").
//    'ajuste'   : Ben saisit lui-même l'estimation d'impact volume (ex. +5% prix → -10% volume),
//                 car aucune élasticité mesurée n'existe dans les données de l'app.
//  Le résultat ne modifie AUCUNE donnée réelle : c'est une simulation pure, en mémoire.
// ============================================================
async function computeScenarioPrix(opts){
  opts = opts||{};
  const periodeStart = opts.periodeStart||null, periodeEnd = opts.periodeEnd||null;
  const pctPrix = +opts.pctPrix||0;         // ex. +5 = hausse de 5%, -10 = baisse de 10%
  const pctVolume = opts.mode==='ajuste' ? (+opts.pctVolume||0) : 0;   // 0 en mode 'constant'

  const [orders, markets, marketMoves, recipes, recipeItems, lots, mats, productions] = await Promise.all([
    db.orders.toArray().catch(()=>[]),
    (db.markets?db.markets.toArray():Promise.resolve([])).catch(()=>[]),
    (db.marketMoves?db.marketMoves.toArray():Promise.resolve([])).catch(()=>[]),
    db.recipes.toArray().catch(()=>[]),
    db.recipeItems.toArray().catch(()=>[]),
    db.materialLots.toArray().catch(()=>[]),
    db.materials.toArray().catch(()=>[]),
    db.productions.toArray().catch(()=>[])
  ]);
  const inRange = (d)=>{ if(!d) return false; if(periodeStart && d<periodeStart) return false; if(periodeEnd && d>periodeEnd) return false; return true; };
  const ordersP = orders.filter(o=>!estReprise(o) && inRange(o.date));
  const marketsP = markets.filter(k=>inRange(k.date));
  const settings = getSettings();

  const An = analyzeFlavorProfitability({recipes, recipeItems, lots, mats, orders:ordersP, markets:marketsP, marketMoves, productions, settings});
  const T = (An && An.totals) ? An.totals : {ca:0, pieces:0, margeNette:0};
  const piecesBase = T.pieces||0;
  const caBase = T.ca||0;
  const margeBase = (T.margeApresDons!=null?T.margeApresDons:T.margeNette)||0;
  if(piecesBase<=0){
    return { ok:false, raison:'Aucune vente sur la période choisie — impossible de simuler.' };
  }
  const prixMoyenBase = money2(caBase / piecesBase);
  const coutMoyenParPiece = money2((caBase - margeBase) / piecesBase);   // déduit du moteur de marge existant

  // Simulation : nouveau prix moyen, nouveau volume (selon mode), marge recalculée.
  const prixMoyenSim = money2(prixMoyenBase * (1 + pctPrix/100));
  const piecesSim = round3(piecesBase * (1 + pctVolume/100));
  const caSim = money2(prixMoyenSim * piecesSim);
  // Le coût matière/production par pièce est supposé stable (hypothèse standard à volume
  // raisonnable) ; seules les charges sociales varient avec le CA (même taux que la réalité,
  // approximé via le taux marchandise — cohérent avec le fait qu'un macaron standard = vente).
  const margeSimAvantCharges = money2(caSim - coutMoyenParPiece*piecesSim);
  const chargesSocialesSim = money2(caSim * (+settings.socialGoods||0)/100);
  const margeSim = money2(margeSimAvantCharges - chargesSocialesSim);
  const chargesSocialesBase = money2(caBase * (+settings.socialGoods||0)/100);
  const margeBaseApresCharges = money2(margeBase - chargesSocialesBase);

  // Nombre de mois couverts par la période choisie, pour ramener à un rythme mensuel.
  const nbJours = (periodeStart && periodeEnd) ? Math.max(1, Math.round((new Date(periodeEnd)-new Date(periodeStart))/86400000)+1) : 30;
  const moisEquiv = Math.max(0.1, nbJours/30.44);
  const deltaCaMois = money2((caSim-caBase)/moisEquiv);
  const deltaMargeMois = money2((margeSim-margeBaseApresCharges)/moisEquiv);
  const deltaCaAn = money2(deltaCaMois*12);
  const deltaMargeAn = money2(deltaMargeMois*12);

  // Impact runway : injecte le delta de marge mensuelle comme charge récurrente VIRTUELLE
  // (positive = charge en moins / recette en plus) dans une projection de trésorerie parallèle,
  // sans jamais rien écrire en base (simulation pure).
  let runwayImpact = null;
  try{
    const Rbase = await computeTresorerie();
    if(Rbase.solde!=null){
      const s2 = Object.assign({}, settings, { soldeBancaire: Rbase.solde, soldeBancaireDate: Rbase.soldeDate });
      const modelsVirtuel = getRecurringCharges().slice();
      if(deltaMargeMois!==0){
        // Charge (positive ou négative) au 15 du mois, montant = -delta (une hausse de marge = moins de "charge").
        const jourVirtuel = new Date(); jourVirtuel.setDate(15);
        modelsVirtuel.push({ id:'scenario-virtuel', libelle:'Impact scénario prix', montant:-deltaMargeMois, jourMois:15, actif:true });
      }
      const RsimJalons = await _computeTresorerieAvec(s2, modelsVirtuel);
      const j30base = Rbase.jalons.find(j=>j.nbJours===30), j30sim = RsimJalons.find(j=>j.nbJours===30);
      runwayImpact = { avant: j30base?j30base.solveur:null, apres: j30sim?j30sim.solveur:null };
    }
  }catch(e){ console.error('runwayImpact scenario', e); runwayImpact=null; }

  return {
    ok:true, piecesBase, prixMoyenBase, coutMoyenParPiece, caBase, margeBaseApresCharges,
    prixMoyenSim, piecesSim, caSim, margeSim,
    deltaCa: money2(caSim-caBase), deltaMarge: money2(margeSim-margeBaseApresCharges),
    deltaCaMois, deltaMargeMois, deltaCaAn, deltaMargeAn, moisEquiv, runwayImpact
  };
}
// Variante paramétrable de computeTresorerie (settings + modèles récurrents injectés),
// utilisée UNIQUEMENT pour la simulation d'impact runway d'un scénario (jamais pour l'écran réel).
async function _computeTresorerieAvec(settingsOverride, recurringOverride){
  const s = settingsOverride;
  const solde = s.soldeBancaire;
  const today0 = today();
  const jAujourdhui = new Date(today0+'T00:00:00');
  const allOrders = await db.orders.toArray().catch(()=>[]);
  const orders = allOrders.filter(o=>!estReprise(o));
  const creances = [];
  orders.forEach(o=>{
    const bal = orderBalance(o); if(bal<=0) return;
    const d = o.dateLivraison || o.date || today0;
    creances.push({date:d, montant:bal});
  });
  const allCharges = await (db.charges?db.charges.toArray():Promise.resolve([])).catch(()=>[]);
  const chargesFutures = allCharges.filter(c=>(c.date||'')>today0).map(c=>({date:c.date, montant:money2(+c.montant||0)}));
  const models = (recurringOverride||[]).filter(m=>m.actif!==false && +m.montant!==0);
  const chargesRecurrentesFutures = [];
  models.forEach(m=>{
    const jour = Math.min(28, Math.max(1, +m.jourMois||1));
    const base = new Date(jAujourdhui.getFullYear(), jAujourdhui.getMonth(), jour);
    for(let i=0;i<4;i++){
      const d = new Date(base.getFullYear(), base.getMonth()+i, jour);
      const ymd = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
      if(ymd<=today0) continue;
      chargesRecurrentesFutures.push({date:ymd, montant:money2(+m.montant||0)});
    }
  });
  return [30,60,90].map(nbJours=>{
    const limite = new Date(jAujourdhui); limite.setDate(limite.getDate()+nbJours);
    const limiteStr = limite.getFullYear()+'-'+String(limite.getMonth()+1).padStart(2,'0')+'-'+String(limite.getDate()).padStart(2,'0');
    const dansPeriode = (d)=> d>today0 ? d<=limiteStr : true;
    const totCreances = money2(creances.filter(c=>dansPeriode(c.date)).reduce((s2,c)=>s2+c.montant,0));
    const totCharges = money2(chargesFutures.filter(c=>c.date<=limiteStr).reduce((s2,c)=>s2+c.montant,0) + chargesRecurrentesFutures.filter(c=>c.date<=limiteStr).reduce((s2,c)=>s2+c.montant,0));
    const solveur = (solde!=null) ? money2(solde + totCreances - totCharges) : null;
    return { nbJours, solveur };
  });
}

// ============================================================
//  BILAN MENSUEL — ventilation marchandise / prestation de service
//  sur les ENCAISSEMENTS du mois (base trésorerie = base déclaration
//  micro-entreprise URSSAF) + prédiction des cotisations.
// ============================================================
// [v1325] LA PART « PRESTATION DE SERVICE » D'UNE COMMANDE (0..1).
// Règle unique, désormais partagée par computeMonthlyBilan (base URSSAF) ET le revenu horaire.
// Elle vivait auparavant enfouie dans computeMonthlyBilan, et nulle part ailleurs : le revenu
// horaire, lui, appliquait le taux MARCHANDISE (12,3 %) à TOUT le CA — prestations comprises,
// alors qu'elles cotisent à 25,6 %. Deux écrans, deux vérités, sur la même commande.
// Pure : ne lit aucune base, dépend seulement de la commande.
// ════════════════════════════════════════════════════════════════════════════════════════════
// [v1436] LA PART « SERVICE » D'UNE LIGNE — un seul point de vérité, enfin complet.
// Ben : « certaines locations de pyramides ne passent pas en prestation de service […] la
// ventilation ne remonte pas systématiquement l'ensemble des commandes avec une location ».
//
// LA RÉPONSE À SA QUESTION DIRECTE : le lien se fait bien À LA SOURCE. Une pyramide LOUÉE est
// correctement marquée (`ligneALocation`, `pyraTotalLigne`), et son montant est bien inclus dans
// le total de la ligne événement. Le bug est ENTIÈREMENT EN AVAL — dans l'agrégation qui décide
// ce qui compte comme service.
//
// LA CAUSE : `partServiceCommande` (créée en v1325, précisément pour être LE point de vérité
// partagé et mettre fin aux divergences) ne reconnaissait que les lignes `type==='prestation'`.
// Elle ignorait totalement les lignes `type==='evenement'` — où vit pourtant la location de
// pyramide et l'accessoire décoratif. Résultat : une commande AVEC pyramide louée mais SANS
// ligne prestation séparée remontait à 100 % en marchandise. Une commande qui avait LES DEUX
// remontait en partie service — mais seulement à hauteur de la prestation, jamais de la
// location. D'où le symptôme exact de Ben : « pas systématiquement » — ça dépendait de la
// présence, par ailleurs, d'une ligne prestation, jamais de la location elle-même.
//
// ET LA VRAIE RÈGLE EXISTAIT DÉJÀ, ailleurs : `computeAccounting` (l'écran de rentabilité
// annuelle) sait depuis toujours que la pyramide LOUÉE est un service et que la pyramide VENDUE
// est une marchandise. La fonction censée être « LE » point de vérité partagé n'était donc pas
// la seule vérité — computeAccounting en portait une seconde, plus complète. Deux écrans, deux
// vérités : exactement ce que la v1325 disait vouloir éliminer.
//
// PURE. Montant d'UNE ligne qui relève du régime social « service ».
function montantServiceLigne(ln){
  if(!ln) return 0;
  if(ln.type==='prestation') return money2(lineTotalStored(ln));
  if(ln.type==='evenement'){
    let svc = 0;
    if(!pyraEstVente(ln)) svc = money2(svc + pyraTotalLigne(ln));       // louée → service ; vendue → marchandise (déjà exclue)
    if(accessoireDecoActif(ln)) svc = money2(svc + accessoireDecoTotal(ln));
    return svc;
  }
  return 0;
}

function partServiceCommande(o){
  const total = money2(+((o&&o.montant)||0));
  if(!(total > 0)) return 0;
  // [v1436] Toutes les lignes qui portent du service — plus seulement les lignes prestation.
  let svc = 0;
  (orderToLines(o) || []).forEach(ln => { svc = money2(svc + montantServiceLigne(ln)); });
  return Math.min(1, svc / total);
}

async function computeMonthlyBilan(ym){
  // ym = 'YYYY-MM'. Sépare le CA encaissé du mois en marchandise vs service.
  const s=getSettings();
  const orders = await db.orders.toArray();
  const markets = await (db.markets?db.markets.toArray():Promise.resolve([])).catch(()=>[]);
  // [v1419] Le nom du client dans le détail : demandé par Ben. Sans lui, les lignes n'affichaient
  // qu'un « commande #123 » anonyme, illisible pour vérifier une déclaration URSSAF.
  const _clientsBilan = await (db.clients?db.clients.toArray():Promise.resolve([])).catch(()=>[]);
  const _nomClientDe = cid => {
    const c = _clientsBilan.find(x=>+x.id===+cid);
    return c ? (c.nom||'') : '';
  };
  let goods=0, service=0;            // encaissé du mois, ventilé (reprises exclues, cf. A11-fix)
  const detailGoods=[], detailService=[];
  // [A11-display] On CUMULE aussi le montant encaissé du mois issu des REPRISES d'historique,
  // pour l'afficher séparément (hors URSSAF, déjà déclaré). N'entre JAMAIS dans goods/service/cotis.
  let reprisesEnc=0, reprisesCount=0; const detailReprises=[];
  // Pour chaque commande, on connaît la part service vs marchandise (lignes prestation = service).
  orders.forEach(o=>{
    // [AUDIT-2026-07 · A11-fix] Une REPRISE d'historique (migration) = CA d'avant l'app, déjà déclaré à
    // l'époque. On ne le recompte JAMAIS dans la base URSSAF, sinon double déclaration. Même prédicat
    // partagé estReprise que computeAccounting (couvre o.histo ET ligne type 'histo') → les deux écrans
    // calculent l'URSSAF sur la MÊME base : uniquement le CA saisi au fil de l'eau.
    if(estReprise(o)){
      // Reprise : hors URSSAF, mais on trace son encaissement du mois pour l'afficher séparément.
      let encR=0;
      paiementsDe(o).forEach(p=>{ if(monthKey(p.date)===ym) encR=money2(encR+money2(p.montant)); });
      if(encR>0){ reprisesEnc=money2(reprisesEnc+encR); reprisesCount++;
        detailReprises.push({label:(o.histoLabel||('reprise #'+o.id)), montant:encR}); }
      return;
    }
    const total=money2(+o.montant||0); if(total<=0) return;
    // [v1325] Règle de ventilation extraite en fonction PURE partagée (partServiceCommande).
    // Elle était écrite ici, et NULLE PART ailleurs : le revenu horaire, lui, appliquait le taux
    // marchandise à TOUT le CA, prestations comprises. Deux écrans, deux vérités. Une seule règle
    // désormais — dupliquer la règle, c'est fabriquer la divergence de demain.
    const partSvc = partServiceCommande(o);   // proportion service de la commande (0..1)
    // encaissements du mois pour cette commande
    // [v1194] Source unique paiementsDe : capte le legacy « Payé » même sans datePaiement (daté sur
    // o.date), IDENTIQUE au dashboard et à computeAccounting. L'ancien repli le ratait → le bilan
    // mensuel (goods/service, base URSSAF) pouvait diverger du CA encaissé affiché ailleurs.
    let encMois=0, dateEncMois='';
    paiementsDe(o).forEach(p=>{ if(monthKey(p.date)===ym){ encMois=money2(encMois+money2(p.montant)); if(!dateEncMois || (p.date||'')>dateEncMois) dateEncMois=p.date||o.date||''; } });
    if(encMois<=0) return;
    const sPart=money2(encMois*partSvc), gPart=money2(encMois-sPart);
    if(gPart>0){ goods=money2(goods+gPart); }
    if(sPart>0){ service=money2(service+sPart); }
    const cl=o.histoLabel||'';
    // [v1412] date + oid ajoutés : sans eux, le détail affiché au clic ne pouvait ni se trier
    // chronologiquement ni ouvrir la commande d'origine — cf retour de Ben sur ce point.
    // [v1419] `client` exposé à part : l'affichage le montre en tête de ligne, et il reste
    // disponible sans re-résoudre le clientId côté écran.
    const _nomCl = _nomClientDe(o.clientId);
    const _libelle = cl || (_nomCl ? _nomCl : '') || ('commande #'+o.id);
    if(gPart>0) detailGoods.push({label:_libelle, client:_nomCl, montant:gPart, date:dateEncMois, oid:o.id});
    if(sPart>0) detailService.push({label:_libelle, client:_nomCl, montant:sPart, date:dateEncMois, oid:o.id});
  });
  // Marchés clôturés du mois = vente de marchandise.
  markets.forEach(mk=>{
    if(mk.statut!=='clos') return;
    if(!_dansPeriode(mk.date, ym)) return;   // [v1342] mois OU semaine
    const ca=mk.ca||{}; const fond=money2(+mk.fondCaisse||0);
    const esp=money2(Math.max(0,(+ca.especes||0)-fond)), cb=money2(ca.cb||0), au=money2(ca.autre||0);
    const tot=money2(esp+cb+au); if(tot<=0) return;
    goods=money2(goods+tot);
    detailGoods.push({label:'Marché : '+(mk.nom||mk.lieu||'—'), montant:tot, date:mk.date||''});
  });

  // [v1283 · JOURNAL D'AVOIRS] Avoirs émis CE MOIS : déduits de la base URSSAF (goods/service),
  // ventilés selon la nature de la commande d'ORIGINE (même logique marchandise/service que pour
  // un encaissement normal). Sans cette déduction, un remboursement laisserait une cotisation
  // due sur un CA qui n'existe plus (risque identifié : sur-cotisation après un avoir).
  let avoirsDeduits=0;
  const allAvoirsBilan = await (db.documents?db.documents.where('type').equals('avoir').toArray():Promise.resolve([])).catch(()=>[]);
  for(const a of allAvoirsBilan){
    if((a.statut!=='emis' && a.statut!=='enregistre') || monthKey(a.date)!==ym) continue;
    const v = money2(+a.montant||0); if(v<=0) continue;
    const oOrig = a.orderId ? await db.orders.get(a.orderId).catch(()=>null) : null;
    let partSvcOrig = 0;
    if(oOrig && !estReprise(oOrig)){
      const totOrig = money2(+oOrig.montant||0);
      let svcOrig=0; orderToLines(oOrig).forEach(ln=>{ if(ln.type==='prestation') svcOrig=money2(svcOrig+lineTotalStored(ln)); });
      partSvcOrig = totOrig>0 ? Math.min(1, svcOrig/totOrig) : 0;
    }
    const sDed=money2(v*partSvcOrig), gDed=money2(v-sDed);
    if(gDed>0){ goods=money2(goods-gDed); detailGoods.push({label:'Avoir'+(a.numero?' '+a.numero:'')+' (déduction)', montant:-gDed}); }
    if(sDed>0){ service=money2(service-sDed); detailService.push({label:'Avoir'+(a.numero?' '+a.numero:'')+' (déduction)', montant:-sDed}); }
    avoirsDeduits=money2(avoirsDeduits+v);
  }

  const caTotal=money2(goods+service);
  // Cotisations URSSAF micro-entreprise : taux distincts marchandise / service.
  const tauxGoods=+s.socialGoods||0, tauxService=+s.socialService||0;
  const cotisGoods=money2(goods*tauxGoods/100);
  const cotisService=money2(service*tauxService/100);
  const cotisTotal=money2(cotisGoods+cotisService);
  return {ym, goods, service, caTotal, tauxGoods, tauxService, cotisGoods, cotisService, cotisTotal,
    detailGoods, detailService,
    // [v1283 · JOURNAL D'AVOIRS] Total des avoirs déduits ce mois (déjà retiré de goods/service ci-dessus).
    avoirsDeduits,
    // [A11-display] Reprises du mois (hors URSSAF) + CA activité globale (fil de l'eau + reprises).
    reprisesEnc, reprisesCount, detailReprises,
    caActiviteTotale: money2(caTotal + reprisesEnc)};
}

// ============================================================
//  PRÉVISION DE REVENU — [v1072] « combien vais-je gagner le mois prochain ? »
//  Méthode honnête, croisant DEUX signaux complémentaires :
//   1) TENDANCE : moyenne pondérée du CA encaissé des derniers mois (poids ↑ aux mois récents).
//   2) CARNET : montant des commandes DÉJÀ enregistrées dont la livraison tombe sur le mois visé
//      (signal concret, plancher minimal — ces commandes existent vraiment).
//  On présente une FOURCHETTE [carnet ... max(tendance, carnet)] plutôt qu'un faux chiffre précis :
//  on ne peut pas deviner les commandes pas encore passées, mais on montre le plancher et la projection.
// ============================================================
function _ymAddMonths(ym, n){
  // ym = 'YYYY-MM' → renvoie la clé du mois décalé de n (n peut être négatif).
  const [y,m]=ym.split('-').map(Number);
  const d=new Date(y, (m-1)+n, 1);
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
}
async function computePrevisionRevenu(ymCible){
  // Mois visé : par défaut le mois PROCHAIN (par rapport à aujourd'hui).
  const now=new Date();
  const ymCourant = now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
  const cible = ymCible || _ymAddMonths(ymCourant, 1);

  // 1) TENDANCE : on prend jusqu'à 4 mois précédant le mois visé qui ont de l'activité.
  const moisActifs = await _listeMoisAvecActivite();           // triés ? on re-trie par sécurité
  const histo = moisActifs.filter(m=>m < cible).sort();        // antérieurs au mois visé
  const derniers = histo.slice(-4);                            // au plus 4 mois récents
  const bilans=[];
  for(const ym of derniers){ const B=await computeMonthlyBilan(ym); bilans.push({ym, ca:B.caTotal}); }
  // Moyenne pondérée : le mois le plus récent pèse le plus (poids 1,2,3,4…).
  let tendance=0, sommePoids=0;
  bilans.forEach((b,i)=>{ const poids=i+1; tendance=money2(tendance+b.ca*poids); sommePoids+=poids; });
  tendance = sommePoids>0 ? money2(tendance/sommePoids) : 0;

  // 2) CARNET : commandes dont la livraison tombe sur le mois visé. On somme le RESTE À ENCAISSER
  //    (montant total − déjà encaissé) car les acomptes déjà payés sont comptés dans un autre mois.
  const orders = await db.orders.toArray().catch(()=>[]);
  let carnet=0, nbCmd=0;
  orders.forEach(o=>{
    if(!o || o.histo) return;                                  // ignore reprises d'historique
    const dLiv = o.dateLivraison || o.date || '';
    if(monthKey(dLiv)!==cible) return;
    const total=money2(+o.montant||0); if(total<=0) return;
    // [v1194] Déjà encaissé = orderPaid(o), source unique (registre + repli legacy « Payé »).
    // Remplace un 3e repli hybride divergent ((paiement||reglement)&&datePaiement) par la définition
    // canonique, alignée sur orderBalance / le dashboard / la compta.
    const dejaEnc=orderPaid(o);
    const reste=money2(Math.max(0, total-dejaEnc));
    if(reste>0){ carnet=money2(carnet+reste); nbCmd++; }
  });

  // Synthèse : plancher = carnet (sûr) ; estimation haute = max(tendance, carnet).
  const bas = carnet;
  const haut = money2(Math.max(tendance, carnet));
  // Estimation « centrale » : si on a une tendance et un carnet, on prend le max des deux comme point
  // de mire (le carnet ne peut que monter d'ici la fin du mois). Sinon ce qu'on a.
  const central = haut;
  return {
    cible, libelle: monthLabel(cible),
    tendance, carnet, nbCmd, bas, haut, central,
    nbMoisHisto: bilans.length, bilans,
    aTendance: bilans.length>0, aCarnet: carnet>0
  };
}

// ============================================================
//  FREINS AU REVENU — [v1072] « qu'est-ce qui m'empêche de gagner plus ? »
//  Diagnostic factuel : cherche les trous CONCRETS dans les données et les chiffre.
//  Chaque frein = { cle, titre, montant?, detail, gravite('haut'|'moyen'|'info'), action? }.
//  On ne fabrique JAMAIS un frein qui n'existe pas : si rien n'est détecté, on le dit.
// ============================================================
async function computeFreinsRevenu(){
  const orders = await db.orders.toArray().catch(()=>[]);
  const markets = await (db.markets?db.markets.toArray():Promise.resolve([])).catch(()=>[]);
  const freins=[];
  const _stat = (typeof normStatus==='function') ? normStatus : (s=>s||'');

  // 1) COMMANDES LIVRÉES NON SOLDÉES : livrées mais reste à encaisser → argent dû, le plus prioritaire.
  let duLivre=0, nbDuLivre=0;
  // 2) ARGENT EN ATTENTE GLOBAL : reste à encaisser sur toute commande non historique (livrée ou non).
  let enAttente=0, nbAttente=0;
  orders.forEach(o=>{
    if(!o || o.histo) return;
    const total=money2(+o.montant||0); if(total<=0) return;
    const enc=(typeof paiementsDe==='function'?paiementsDe(o):[]).reduce((s,p)=>money2(s+money2(+p.montant||0)),0);
    const reste=money2(total-enc);
    if(reste>0.01){
      enAttente=money2(enAttente+reste); nbAttente++;
      if(_stat(o.statut)==='Livrée'){ duLivre=money2(duLivre+reste); nbDuLivre++; }
    }
  });
  if(duLivre>0.01){
    freins.push({ cle:'livre_non_paye', titre:'Des commandes livrées ne sont pas encore payées',
      montant:duLivre, gravite:'haut',
      detail:`${nbDuLivre} commande${nbDuLivre>1?'s':''} déjà livrée${nbDuLivre>1?'s':''} mais pas soldée${nbDuLivre>1?'s':''}. Cet argent t'est dû — une relance suffit souvent.`,
      action:{label:'💸 Voir les impayés', intent:'query_paiements_dus'} });
  }
  // l'argent en attente NON livré (commandes à venir non payées) = info, pas un frein dur
  const attenteNonLivre = money2(enAttente - duLivre);
  if(attenteNonLivre>0.01 && duLivre<=0.01){
    freins.push({ cle:'attente', titre:'De l\'argent est en attente d\'encaissement',
      montant:attenteNonLivre, gravite:'moyen',
      detail:`${nbAttente} commande${nbAttente>1?'s':''} avec un reste à encaisser. Normal si elles ne sont pas encore livrées, mais à suivre.`,
      action:{label:'💸 Voir les paiements dus', intent:'query_paiements_dus'} });
  }

  // 3) PART DU SERVICE (coaching) : sur les mois récents, quel poids a le service ? Faible = levier,
  //    car le coaching est plus margé (abattement 50% mais aucun coût matière/production).
  const moisActifs = await _listeMoisAvecActivite();
  const derniers = moisActifs.slice(-3);
  let g=0, s=0;
  for(const ym of derniers){ const B=await computeMonthlyBilan(ym); g=money2(g+B.goods); s=money2(s+B.service); }
  const caRecent=money2(g+s);
  const partSvc = caRecent>0 ? Math.round(s/caRecent*100) : 0;
  if(caRecent>0 && partSvc<10){
    freins.push({ cle:'peu_service', titre:'Très peu de coaching dans ton activité',
      gravite:'moyen',
      detail:`Sur tes 3 derniers mois, le coaching ne pèse que ${partSvc}% de ton CA. Une prestation ne coûte ni matière ni production : c'est souvent le levier de marge le plus rapide.`,
      action:null });
  }

  // 4) INVENDUS MARCHÉS : sur les marchés clos récents, des invendus chiffrés = production perdue.
  let nbMarchesInv=0, totalInv=0;
  markets.forEach(mk=>{
    if(mk.statut!=='clos') return;
    const inv=mk.invendus||mk.invendu||null;
    if(inv && typeof inv==='object'){
      const n=Object.values(inv).reduce((a,v)=>a+(+v||0),0);
      if(n>0){ nbMarchesInv++; totalInv+=n; }
    }
  });
  if(totalInv>0){
    freins.push({ cle:'invendus', titre:'Des invendus sur tes marchés',
      gravite:'info',
      detail:`Environ ${totalInv} macaron${totalInv>1?'s':''} invendus sur tes derniers marchés clos. Ajuster les quantités produites par parfum réduit cette perte.`,
      action:{label:'🏪 Voir les marchés', view:'marches'} });
  }

  // Tri par gravité (haut > moyen > info) puis par montant décroissant.
  const ordre={haut:0, moyen:1, info:2};
  freins.sort((a,b)=> (ordre[a.gravite]-ordre[b.gravite]) || ((b.montant||0)-(a.montant||0)));
  return { freins, enAttente, duLivre, partSvc, caRecent };
}

// ============================================================
//  SUGGESTION DE PARFUMS — [v1072] « quel parfum lancer pour cet automne ? »
//  Force de proposition HONNÊTE : on ne « crée » pas un parfum par magie, on RECOMMANDE des pistes
//  argumentées à partir de ta base aromatique R&D (familles, intensité, déjà au catalogue ou non) et
//  d'une table de saisonnalité (connaissance pâtissière de base). On explique POURQUOI chaque piste.
// ============================================================
// Familles aromatiques qui « collent » à chaque saison (pondération : 2 = cœur de saison, 1 = possible).
const SAISON_FAMILLES = {
  printemps: { floral:2, agrume:2, fruite_rouge:2, herbace:2, exotique:1, lacte:1 },
  ete:       { fruite_rouge:2, fruite_jaune:2, agrume:2, exotique:2, floral:1, herbace:1 },
  automne:   { fruit_coque:2, epice:2, torrefie:2, lacte:1, fruite_jaune:1, umami:1 },
  hiver:     { epice:2, torrefie:2, fruit_coque:2, agrume:1, lacte:1, exotique:1 }
};
const SAISON_LABEL = { printemps:'le printemps', ete:'l\'été', automne:'l\'automne', hiver:'l\'hiver' };
function _saisonDepuisTexte(t){
  if(/\bprintemps\b/.test(t)) return 'printemps';
  if(/\b(ete|estival)\b/.test(t)) return 'ete';
  if(/\b(automne|automnal)\b/.test(t)) return 'automne';
  if(/\b(hiver|hivernal|noel|fetes?)\b/.test(t)) return 'hiver';
  // sinon, saison courante (hémisphère nord)
  const m=new Date().getMonth()+1;
  if(m>=3&&m<=5) return 'printemps'; if(m>=6&&m<=8) return 'ete'; if(m>=9&&m<=11) return 'automne'; return 'hiver';
}
const FAMILLE_LABEL = {
  floral:'floral', agrume:'agrume', fruite_rouge:'fruit rouge', fruite_jaune:'fruit jaune',
  exotique:'exotique', herbace:'herbacé', fruit_coque:'fruit à coque', epice:'épicé',
  torrefie:'torréfié', lacte:'lacté', umami:'umami', vegetal_sale:'végétal salé',
  lacte_sale:'lacté salé', texture_croquant:'croquant', texture_onctueux:'onctueux',
  texture_gelifie:'gélifié', texture_fondant:'fondant', texture_coulant:'coulant'
};
async function computeSuggestionParfums(saison){
  saison = saison || _saisonDepuisTexte('');
  const fams = SAISON_FAMILLES[saison] || SAISON_FAMILLES.automne;
  // Base aromatique : DB enrichie si dispo, sinon seed.
  let base=[];
  try{ base = await db.rdIngredients.toArray(); }catch(e){swallow(e,'computeSuggestionParfums')}
  if(!base || !base.length) base = (typeof RD_SEED_INGREDIENTS!=='undefined') ? RD_SEED_INGREDIENTS : [];
  // On ne propose que des parfums « sucrés » plausibles en macaron, PAS déjà au catalogue.
  const candidats = base.filter(x=> x && x.registre==='sucre' && fams[x.famille] && +x.auCatalogue!==1);
  // Score = poids saison de la famille × (1 + intensité normalisée). Les parfums marquants ressortent.
  candidats.forEach(c=>{ c._score = (fams[c.famille]||1) * (1 + (Math.min(5,+c.intensite||3)/5)); });
  candidats.sort((a,b)=> b._score - a._score);
  // On évite de proposer 5 fois la même famille : on diversifie (max 2 par famille).
  const parFam={}; const retenus=[];
  for(const c of candidats){
    const n=parFam[c.famille]||0; if(n>=2) continue;
    parFam[c.famille]=n+1; retenus.push(c);
    if(retenus.length>=5) break;
  }
  // Parfums déjà au catalogue de ces familles (pour dire « tu es déjà fort sur X »).
  const dejaCat = base.filter(x=> x && +x.auCatalogue===1 && fams[x.famille]).map(x=>x.nom);
  return {
    saison, saisonLabel: SAISON_LABEL[saison]||saison,
    familles: Object.keys(fams).map(f=>({cle:f, label:FAMILLE_LABEL[f]||f, poids:fams[f]})),
    suggestions: retenus.map(c=>({nom:c.nom, famille:c.famille, familleLabel:FAMILLE_LABEL[c.famille]||c.famille, intensite:+c.intensite||3})),
    dejaCatalogue: dejaCat
  };
}

// ============================================================
//  NET DANS LA POCHE — [v1067] le KPI ultime
//  À partir du CA ENCAISSÉ ventilé marchandise/service, déduit cotisations sociales
//  URSSAF, impôt sur le revenu (micro-entreprise, barème progressif via taux marginal
//  saisi, après abattement forfaitaire), puis charges réelles de la période.
//  Granularité : période = { type:'mois'|'annee'|'tout', ym?, year? }.
//  IMPORTANT : les charges réelles réduisent la POCHE mais PAS l'imposable (en micro,
//  l'abattement forfaitaire remplace la déduction des charges réelles — on ne cumule pas).
// ============================================================
function _moisDeLannee(year){ const a=[]; for(let m=1;m<=12;m++) a.push(year+'-'+String(m).padStart(2,'0')); return a; }
async function _listeMoisAvecActivite(){
  // tous les mois 'YYYY-MM' où il y a au moins un encaissement ou une charge
  const set=new Set();
  const orders=await db.orders.toArray();
  orders.forEach(o=>{
    // [v1194] paiementsDe : mêmes dates d'encaissement que la compta → aucun mois d'activité oublié
    // (l'ancien repli ratait le legacy « Payé » sans datePaiement, pouvant masquer un mois entier).
    paiementsDe(o).forEach(p=>{ if(p&&p.date) set.add(monthKey(p.date)); });
  });
  const markets=await (db.markets?db.markets.toArray():Promise.resolve([])).catch(()=>[]);
  markets.forEach(mk=>{ if(mk.statut==='clos'&&mk.date) set.add(monthKey(mk.date)); });
  const charges=await (db.charges?db.charges.toArray():Promise.resolve([])).catch(()=>[]);
  charges.forEach(c=>{ if(c&&c.date) set.add(monthKey(c.date)); });
  return [...set].filter(Boolean).sort();
}
async function _chargesPeriode(moisList){
  // somme des charges réelles sur la liste de mois (par catégorie + total + par nature)
  const charges=await (db.charges?db.charges.toArray():Promise.resolve([])).catch(()=>[]);
  const inSet=new Set(moisList);
  let total=0, invest=0, recurrent=0; const parCat={}; const investParCat={}, recurrentParCat={};
  charges.forEach(c=>{ if(!c||!c.date) return; if(!inSet.has(monthKey(c.date))) return;
    const v=money2(+c.montant||0); if(v<=0) return; total=money2(total+v);
    const cat=c.categorie||'Autre'; parCat[cat]=money2((parCat[cat]||0)+v);
    if(chargeNature(cat)==='invest'){ invest=money2(invest+v); investParCat[cat]=money2((investParCat[cat]||0)+v); }
    else { recurrent=money2(recurrent+v); recurrentParCat[cat]=money2((recurrentParCat[cat]||0)+v); }
  });
  return { total, parCat, invest, recurrent, investParCat, recurrentParCat };
}
async function computeNetPoche(periode){
  periode=periode||{type:'mois'};
  const s=getSettings();
  // 1) Déterminer la liste des mois concernés
  let moisList=[];
  if(periode.type==='mois'){ moisList=[periode.ym || monthKey(today())]; }
  else if(periode.type==='annee'){ moisList=_moisDeLannee(periode.year || (new Date().getFullYear())); }
  else { moisList=await _listeMoisAvecActivite(); if(!moisList.length) moisList=[monthKey(today())]; }
  // 2) Agréger les bilans mensuels (CA encaissé ventilé + cotisations)
  let goods=0, service=0, cotisGoods=0, cotisService=0;
  for(const ym of moisList){
    const B=await computeMonthlyBilan(ym);
    goods=money2(goods+B.goods); service=money2(service+B.service);
    cotisGoods=money2(cotisGoods+B.cotisGoods); cotisService=money2(cotisService+B.cotisService);
  }
  const caTotal=money2(goods+service);
  const cotisTotal=money2(cotisGoods+cotisService);
  // 3) Base imposable = CA après abattement forfaitaire (jamais négatif), avec minimum légal
  const abG=+s.irAbattementGoods||0, abS=+s.irAbattementService||0;
  let baseGoods=money2(goods*(1-abG/100));
  let baseService=money2(service*(1-abS/100));
  let baseImposable=money2(baseGoods+baseService);
  // abattement minimum (305 € / an) : la base ne peut pas dépasser CA - minAbattement.
  // Appliqué seulement sur une période annuelle ou « tout » pour rester fidèle au calcul légal.
  const abMin=+s.irAbattementMin||0;
  if((periode.type==='annee'||periode.type==='tout') && abMin>0 && caTotal>0){
    const baseMax=money2(Math.max(0, caTotal-abMin));
    if(baseImposable>baseMax) baseImposable=baseMax;
  }
  // 4) Impôt sur le revenu = base imposable × taux marginal (tranche du foyer)
  const tranche=+s.irTrancheMarginale||0;
  const impotRevenu=money2(baseImposable*tranche/100);
  // 5) Charges réelles de la période (énergie, etc.) — réduisent la poche, pas l'imposable
  const ch=await _chargesPeriode(moisList);
  const chargesReelles=ch.total;
  // 6) Net dans la poche
  const netAvantCharges=money2(caTotal - cotisTotal - impotRevenu);
  const netPoche=money2(netAvantCharges - chargesReelles);
  // 7) Indicateurs de synthèse
  const totalPonctions=money2(cotisTotal + impotRevenu + chargesReelles);
  const tauxPonction = caTotal>0 ? money2(totalPonctions/caTotal*100) : 0;
  const tauxNet = caTotal>0 ? money2(netPoche/caTotal*100) : 0;
  return {
    periode, moisList, nbMois:moisList.length,
    goods, service, caTotal,
    cotisGoods, cotisService, cotisTotal, tauxGoods:+s.socialGoods||0, tauxService:+s.socialService||0,
    abG, abS, baseGoods, baseService, baseImposable, abMinApplique:(periode.type==='annee'||periode.type==='tout')&&abMin>0,
    tranche, impotRevenu,
    chargesReelles, chargesParCat:ch.parCat,
    chargesInvest:ch.invest, chargesRecurrent:ch.recurrent,
    chargesInvestParCat:ch.investParCat, chargesRecurrentParCat:ch.recurrentParCat,
    netAvantCharges, netPoche,
    totalPonctions, tauxPonction, tauxNet
  };
}

// ============================================================
//  SEUILS FISCAUX — [v1069] surveillance micro-entreprise (CA 2026)
//  Compare le CA encaissé annuel (ventilé vente/service) aux seuils légaux 2026 :
//   - franchise de TVA : vente 85 000 (base) / 93 500 (majoré) ; service 37 500 / 41 250
//   - régime micro : vente 203 100 ; service 83 600 ; global mixte 203 100 (dont 83 600 service max)
//  Calcule la position, la distance au seuil, et une projection de fin d'année au rythme actuel.
//  NB : pas de conseil — uniquement des repères factuels. Les coachings = service, les macarons = vente.
// ============================================================
// [v1284] Seuils fiscaux — valeurs LÉGALES figées pour une année de référence donnée (2026).
// anneeValidite documente jusqu'à quelle année ces montants sont réputés exacts. Ces seuils
// évoluent chaque année (revalorisation) : à date, l'app n'a AUCUN moyen de connaître les
// nouveaux montants (pas de connexion), donc computeSeuilsFiscaux compare l'année demandée à
// anneeValidite et ajoute un flag `perimes` si on la dépasse — pour afficher un avertissement
// explicite plutôt que d'utiliser silencieusement des seuils obsolètes. Mettre à jour à la fois
// les montants ET anneeValidite dès que les seuils N+1 sont publiés (fin d'année/début d'année).
const SEUILS_FISCAUX_2026 = {
  anneeValidite: 2026,
  tvaVenteBase:85000, tvaVenteMajore:93500,
  tvaServiceBase:37500, tvaServiceMajore:41250,
  microVente:203100, microService:83600, microGlobal:203100
};
async function computeSeuilsFiscaux(year){
  year = year || new Date().getFullYear();
  const moisList=_moisDeLannee(year);
  let goods=0, service=0;
  const parMois=[];
  // [v1069] séries cumulées pour le graphique de trajectoire
  const cumulGoods=[], cumulService=[], cumulTotal=[];
  for(const ym of moisList){
    const B=await computeMonthlyBilan(ym);
    goods=money2(goods+B.goods); service=money2(service+B.service);
    parMois.push({ym, goods:B.goods, service:B.service});
    cumulGoods.push(goods); cumulService.push(service); cumulTotal.push(money2(goods+service));
  }
  const caTotal=money2(goods+service);
  // Projection fin d'année : extrapolation linéaire au rythme des mois écoulés AVEC activité.
  const now=new Date();
  const moisEcoules = (year < now.getFullYear()) ? 12 : (year > now.getFullYear() ? 0 : (now.getMonth()+1));
  const proj = (val)=> moisEcoules>0 ? money2(val/moisEcoules*12) : 0;
  const projGoods=proj(goods), projService=proj(service), projTotal=money2(projGoods+projService);
  // Mois projeté d'atteinte d'un seuil au rythme actuel (null si jamais atteint sur l'année).
  const moisAtteinte = (valActuel, seuil)=>{
    if(moisEcoules<=0 || valActuel<=0) return null;
    const rythme = valActuel/moisEcoules;            // par mois
    if(rythme<=0) return null;
    const moisNec = seuil/rythme;                    // nb de mois pour atteindre le seuil
    if(moisNec>12) return null;                       // pas atteint dans l'année
    return Math.ceil(moisNec);                        // n° de mois (1-12)
  };
  // Statut d'une jauge : 'ok' (<70%), 'attention' (70-90%), 'proche' (90-100%), 'depasse' (>=100%)
  const statut = (val, seuil)=>{
    const r = seuil>0 ? val/seuil : 0;
    if(r>=1) return 'depasse'; if(r>=0.9) return 'proche'; if(r>=0.7) return 'attention'; return 'ok';
  };
  const jauge = (label, val, seuil, type, projVal)=>({
    label, val, seuil, type,
    pct: seuil>0 ? Math.min(100, Math.round(val/seuil*100)) : 0,
    pctReel: seuil>0 ? Math.round(val/seuil*100) : 0,
    reste: money2(Math.max(0, seuil-val)),
    statut: statut(val, seuil),
    projection: projVal,
    projStatut: statut(projVal, seuil),
    moisAtteinte: moisAtteinte(val, seuil)
  });
  return {
    year, goods, service, caTotal, moisEcoules,
    projGoods, projService, projTotal,
    parMois, cumulGoods, cumulService, cumulTotal,
    S: SEUILS_FISCAUX_2026,
    // [v1284] Seuils potentiellement obsolètes si l'année demandée dépasse anneeValidite —
    // l'app conserve les derniers seuils connus (mieux qu'une absence de repère), mais le signale.
    seuilsAnneeValidite: SEUILS_FISCAUX_2026.anneeValidite,
    seuilsPerimes: year > SEUILS_FISCAUX_2026.anneeValidite,
    // Jauges TVA (les plus proches/sensibles)
    tvaVente: jauge('TVA · vente (macarons)', goods, SEUILS_FISCAUX_2026.tvaVenteBase, 'tva_vente', projGoods),
    tvaService: jauge('TVA · service (coachings)', service, SEUILS_FISCAUX_2026.tvaServiceBase, 'tva_service', projService),
    // Jauges régime micro
    microVente: jauge('Régime micro · vente', goods, SEUILS_FISCAUX_2026.microVente, 'micro_vente', projGoods),
    microService: jauge('Régime micro · service', service, SEUILS_FISCAUX_2026.microService, 'micro_service', projService),
    microGlobal: jauge('Régime micro · global', caTotal, SEUILS_FISCAUX_2026.microGlobal, 'micro_global', projTotal)
  };
}
// [PILOTAGE CA] Cockpit de pilotage : objectif mensuel, projection expliquée, leviers simulables
// (valeurs unitaires tirées des vraies données), et suggestions chiffrées. Réutilise le CA cumulé
// du moteur des seuils fiscaux (même source, donc toujours cohérent et auto-adaptatif).
async function computePilotageCA(year){
  year = year || new Date().getFullYear();
  const R = await computeSeuilsFiscaux(year);      // fournit cumulTotal, parMois, projTotal, moisEcoules…
  const now = new Date();
  const isCurrentYear = (year === now.getFullYear());
  const moisEcoules = R.moisEcoules;               // nb de mois écoulés avec activité potentielle
  const moisRestants = Math.max(0, 12 - moisEcoules);
  const caCumul = R.caTotal;                        // CA encaissé cumulé de l'année
  const rythmeMensuel = moisEcoules>0 ? money2(caCumul/moisEcoules) : 0;   // €/mois moyen réel
  const projFin = R.projTotal;                     // projection fin d'année au rythme actuel

  // --- Valeurs unitaires réelles des leviers (moyennes observées), avec repli raisonnable ---
  const orders = await db.orders.toArray().catch(()=>[]);
  const markets = await db.markets.toArray().catch(()=>[]);
  const yStr = String(year);
  const inYear = d => (d||'').slice(0,4)===yStr;

  // marché moyen : CA net moyen d'un marché clos de l'année (repli : moyenne tous marchés clos)
  const mkClos = markets.filter(m=>m.statut==='clos');
  const mkClosYear = mkClos.filter(m=>inYear(m.date));
  const avgOf = (arr,f)=> arr.length? money2(arr.reduce((s,x)=>s+f(x),0)/arr.length):0;
  const marcheMoyen = mkClosYear.length? avgOf(mkClosYear, m=>marketNetCA(m))
                     : (mkClos.length? avgOf(mkClos, m=>marketNetCA(m)) : 250);

  // commande moyenne (hors marché, HORS ÉVÉNEMENT) : montant moyen d'une commande "courante" de
  // l'année. [v1284-fix] Une commande événement (mariage, réception...) peut peser plusieurs
  // centaines d'euros et gonfle artificiellement la moyenne si elle est mélangée aux coffrets
  // classiques — même précaution déjà appliquée ailleurs dans l'app (panierMoyenHorsEvent, module
  // CRM client) via orderIsEvent, désormais reprise ici pour que le "panier moyen" affiché en
  // Pilotage représente vraiment une commande courante, pas un mélange coffret+mariage.
  const ordVal = o => +o.montant||0;
  const ordYear = orders.filter(o=>!o.histo && !orderIsEvent(o) && inYear(o.date) && ordVal(o)>0);
  const ordAll  = orders.filter(o=>!o.histo && !orderIsEvent(o) && ordVal(o)>0);
  const coffretMoyen = ordYear.length? avgOf(ordYear, ordVal) : (ordAll.length? avgOf(ordAll, ordVal) : 35);

  // animation / prestation moyenne : montant moyen des lignes prestation observées (repli 150)
  let presTot=0, presN=0;
  orders.forEach(o=>{ if(o.histo) return; (o.lignes||[]).forEach(l=>{ if(l.type==='prestation'){ const v=+l.montantHT||0; if(v>0){ presTot+=v; presN++; } } }); });
  const animationMoyenne = presN? money2(presTot/presN) : 150;

  // --- Mois creux (mois avec le CA le plus faible, sur les mois écoulés avec activité) ---
  const moisAvecCA = R.parMois.map((m,i)=>({ym:m.ym, ca:money2(m.goods+m.service), idx:i}))
                              .filter(m=> isCurrentYear ? m.idx < moisEcoules : true);
  const moisCreux = moisAvecCA.filter(m=>m.ca>0).sort((a,b)=>a.ca-b.ca)[0] || null;
  const moisFort  = moisAvecCA.slice().sort((a,b)=>b.ca-a.ca)[0] || null;

  return {
    R, year, isCurrentYear, moisEcoules, moisRestants,
    caCumul, rythmeMensuel, projFin,
    leviers: { marcheMoyen, coffretMoyen, animationMoyenne },
    moisCreux, moisFort,
    // compteurs pour les suggestions
    nbMarchesClosYear: mkClosYear.length, nbCmdYear: ordYear.length
  };
}
// Construit le texte du bilan mensuel (export .txt).
function buildBilanText(B){
  const L=[];
  L.push('SENSATIONS MACARONS — BILAN MENSUEL');
  L.push('Mois : '+monthLabel(B.ym));
  L.push('Édité le '+fmtDate(today()));
  L.push('========================================');
  L.push('');
  L.push('CHIFFRE D\'AFFAIRES ENCAISSÉ : '+euro(B.caTotal));
  if(+B.reprisesEnc>0){
    L.push('  (+ reprises hors URSSAF : '+euro(B.reprisesEnc)+' — déjà déclaré indépendamment)');
    L.push('  = ACTIVITÉ GLOBALE DU MOIS : '+euro(B.caActiviteTotale));
  }
  L.push('');
  L.push('VENTILATION');
  L.push('  • Vente de marchandise : '+euro(B.goods));
  L.push('  • Prestation de service : '+euro(B.service));
  L.push('');
  L.push('COTISATIONS URSSAF (estimation)');
  L.push('  • Marchandise : '+euro(B.goods)+' × '+B.tauxGoods+'%  = '+euro(B.cotisGoods));
  L.push('  • Service     : '+euro(B.service)+' × '+B.tauxService+'%  = '+euro(B.cotisService));
  L.push('  ----------------------------------------');
  L.push('  À PAYER (estimé) : '+euro(B.cotisTotal));
  L.push('');
  if(B.detailGoods.length){
    L.push('DÉTAIL MARCHANDISE');
    B.detailGoods.forEach(d=>L.push('  - '+d.label+' : '+euro(d.montant)));
    L.push('');
  }
  if(B.detailService.length){
    L.push('DÉTAIL PRESTATIONS');
    B.detailService.forEach(d=>L.push('  - '+d.label+' : '+euro(d.montant)));
    L.push('');
  }
  if(B.detailReprises && B.detailReprises.length){
    L.push('REPRISES D\'HISTORIQUE (HORS URSSAF — déjà déclaré indépendamment)');
    B.detailReprises.forEach(d=>L.push('  - '+d.label+' : '+euro(d.montant)));
    L.push('  Sous-total reprises : '+euro(B.reprisesEnc));
    L.push('');
  }
  L.push('========================================');
  L.push('Base : encaissements du mois (trésorerie).');
  L.push('Estimation indicative — vérifiez auprès de l\'URSSAF / votre comptable.');
  L.push('Sensations Macarons — Le Mans');
  return L.join('\n');
}
async function exportBilanMois(ym){
  const B=await computeMonthlyBilan(ym);
  const txt=buildBilanText(B);
  const name='bilan-'+ym+'.txt';
  let copied=false;
  try{ if(navigator.clipboard&&navigator.clipboard.writeText){ await navigator.clipboard.writeText(txt); copied=true; } }catch(e){swallow(e,'exportBilanMois')}
  const blob=new Blob([txt],{type:'text/plain;charset=utf-8'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; a.click();
  openModal(`<h3>Bilan ${monthLabel(ym)}</h3>
    <p class="note">${copied?'Copié dans le presse-papier ✓.':'Fichier .txt téléchargé.'} <span class="act" onclick="closeModal();exportBilanMoisPDF('${ym}')">📄 Version PDF (présentable au comptable) ›</span></p>
    <textarea rows="16" style="width:100%;font-family:monospace;font-size:.76rem;white-space:pre">${esc(txt)}</textarea>
    <div class="modal-actions"><button class="btn ghost" style="margin-right:auto" onclick="closeModal()">Fermer</button>
      <button class="btn" onclick="(function(){const t=this.closest('.modal').querySelector('textarea');t.select();try{document.execCommand('copy');}catch(e){swallow(e,'exportBilanMois')} toast('Copié ✓');}).call(this)">⧉ Copier</button></div>`);
}
