// ── Copie presse-papier autonome (robuste PWA iOS) ──
// Utilise scCopier si le module Studio Com est présent, sinon fallback intégré.
function compoCopier(btn){
  if(typeof scCopier==='function'){ return scCopier(btn); }
  const txt = btn && btn.getAttribute ? (btn.getAttribute('data-copy')||'') : '';
  const done = ()=>{ if(typeof toast==='function') toast('📋 Copié'); };
  try{
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(txt).then(done).catch(()=>compoCopierFallback(txt,done));
    } else compoCopierFallback(txt, done);
  }catch(e){ compoCopierFallback(txt, done); }
}
function compoCopierFallback(txt, done){
  try{ const ta=document.createElement('textarea'); ta.value=txt; ta.style.position='fixed'; ta.style.opacity='0';
    document.body.appendChild(ta); ta.focus(); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); done&&done(); }
  catch(e){ if(typeof toast==='function') toast('Copie impossible — sélectionne le texte'); }
}

// ── État de la composition en cours ──
const _compo = { objet:'vente', cible:'b2c', kwAccroche:'', kwTexte:'', accrocheId:null, texteId:null, ctaId:null, ctaType:null, kwCta:'' };

// ── Anti-répétition : IDs d'accroches/textes déjà utilisés dans des posts
//    programmés ou publiés. Rempli avant chaque rendu du Compositeur. ──
const _compoUsed = { accroches:new Set(), textes:new Set(), ctas:new Set() };
async function compoChargerUsage(){
  _compoUsed.accroches.clear(); _compoUsed.textes.clear(); _compoUsed.ctas.clear();
  if(typeof db==='undefined' || !db.posts) return;
  try{
    const posts = await db.posts.toArray();
    for(const p of posts){
      // On ne compte que ce qui est engagé : programmé ou publié.
      if(p.statut!=='programme' && p.statut!=='publie') continue;
      const sd = p.sourceData;
      if(sd){
        if(sd.accrocheId) _compoUsed.accroches.add(sd.accrocheId);
        if(sd.texteId) _compoUsed.textes.add(sd.texteId);
        if(sd.ctaId) _compoUsed.ctas.add(sd.ctaId);
      }
      // Filet : si pas de sourceData (posts anciens), on repère par texte exact.
      else if(p.texte){
        const first = p.texte.split('\n')[0].trim();
        const acc = SC_ACCROCHES.find(a=>a.texte===first); if(acc) _compoUsed.accroches.add(acc.id);
      }
    }
  }catch(e){ /* silencieux : l'anti-répétition est un confort, pas un bloquant */ }
}

const AXE_EMOJI = { douleur:'😣', desir:'✨', situation:'📍', objection:'🛡️', transformation:'🔁', valeurs:'💛' };

function compoSetObjet(o){ _compo.objet=o; _compo.accrocheId=null; _compo.texteId=null; _compo.ctaId=null; renderCompositeur(); }
function compoSetCible(c){ _compo.cible=c; _compo.accrocheId=null; _compo.texteId=null; _compo.ctaId=null; renderCompositeur(); }
function compoSearchAccroche(v){ _compo.kwAccroche=v; compoRefreshAccroches(); }
function compoSearchTexte(v){ _compo.kwTexte=v; compoRefreshTexte(); }
function compoPickAccroche(id){ _compo.accrocheId=id; renderCompositeur(); }
function compoPickTexte(id){
  _compo.texteId=id;
  // Suggestion auto de CTA à partir du texte choisi (si l'utilisateur n'a rien fixé).
  if(!_compo.ctaId){
    const sug = (typeof scSuggererCTA==='function') ? scSuggererCTA() : null;
    if(sug && sug.banqueId) _compo.ctaId = sug.banqueId;
  }
  renderCompositeur();
}
// ── CTA (5e brique) ──
function compoSetCtaType(t){ _compo.ctaType = (t===_compo.ctaType?null:(t||null)); compoRefreshCta(); }
function compoSearchCta(v){ _compo.kwCta=v; compoRefreshCta(); }
function compoPickCta(id){ _compo.ctaId = (id===_compo.ctaId?null:id); renderCompositeur(); }
function compoCtaAuto(){
  const sug = (typeof scSuggererCTA==='function') ? scSuggererCTA() : null;
  if(sug && sug.banqueId){ _compo.ctaId=sug.banqueId; toast('✨ CTA suggéré appliqué'); }
  else toast('Choisissez d\'abord un texte pour la suggestion');
  renderCompositeur();
}
function compoRefreshCta(){
  const box=document.getElementById('compoCtaList'); if(!box) return;
  box.innerHTML = compoCtaHtml();
}

// Rafraîchit uniquement la liste des accroches (barre 3) sans tout redessiner
function compoRefreshAccroches(){
  const box = document.getElementById('compoAccrochesList'); if(!box) return;
  box.innerHTML = compoAccrochesHtml();
}
function compoRefreshTexte(){
  const box = document.getElementById('compoTextesList'); if(!box) return;
  box.innerHTML = compoTextesHtml();
}

function compoAccrochesHtml(){
  let list = scFiltrerAccroches(_compo.objet, _compo.cible, _compo.kwAccroche);
  if(!list.length) return '<p class="note">Aucune accroche pour ces mots-clés. Essayez un terme plus large.</p>';
  // On repousse en bas de liste ce qui a déjà été publié/programmé (sans le cacher).
  list = list.slice().sort((a,b)=> (_compoUsed.accroches.has(a.id)?1:0) - (_compoUsed.accroches.has(b.id)?1:0));
  return list.slice(0,40).map(a=>{
    const sel = _compo.accrocheId===a.id;
    const used = _compoUsed.accroches.has(a.id);
    return `<div class="sum-box lnk" style="${sel?'background:#f6efe4;border-left:4px solid #52252F':''}${used?';opacity:.62':''}" onclick="compoPickAccroche('${a.id}')">
      <span>${AXE_EMOJI[a.axe]||''} ${esc(a.texte)}${used?' <b style="color:#9a8576;font-size:.68rem;font-weight:600">· déjà publié</b>':''}</span>${sel?'<b>✓</b>':''}</div>`;
  }).join('') + (list.length>40?`<p class="note">… et ${list.length-40} autres. Affine avec un mot-clé.</p>`:'');
}
function compoTextesHtml(){
  let list = scFiltrerTextes(_compo.objet, _compo.cible, _compo.kwTexte);
  if(!list.length) return '<p class="note">Aucun texte pour ces mots-clés. Essayez un terme plus large.</p>';
  list = list.slice().sort((a,b)=> (_compoUsed.textes.has(a.id)?1:0) - (_compoUsed.textes.has(b.id)?1:0));
  return list.slice(0,30).map(t=>{
    const sel = _compo.texteId===t.id;
    const used = _compoUsed.textes.has(t.id);
    return `<div class="sum-box lnk" style="flex-direction:column;align-items:stretch;gap:4px;${sel?'background:#f6efe4;border-left:4px solid #52252F':''}${used?';opacity:.62':''}" onclick="compoPickTexte('${t.id}')">
      <div style="display:flex;justify-content:space-between"><span style="flex:1">${AXE_EMOJI[t.axe]||''} ${esc(t.texte.slice(0,90))}${t.texte.length>90?'…':''}${used?' <b style="color:#9a8576;font-size:.68rem;font-weight:600">· déjà publié</b>':''}</span>${sel?'<b>✓</b>':''}</div>
      <div class="note" style="font-size:.72rem">CTA : ${esc(t.cta)}</div></div>`;
  }).join('') + (list.length>30?`<p class="note">… et ${list.length-30} autres. Affine avec un mot-clé.</p>`:'');
}

// Liste filtrée des CTA (5e brique). Marque le CTA choisi et signale la suggestion auto.
function compoCtaHtml(){
  const list = scFiltrerCTA(_compo.objet, _compo.cible, _compo.ctaType, _compo.kwCta);
  const sug = (typeof scSuggererCTA==='function') ? scSuggererCTA() : null;
  const sugId = sug ? sug.banqueId : null;
  if(!list.length) return '<p class="note">Aucun CTA pour ce filtre. Élargis le type ou les mots-clés.</p>';
  return list.slice(0,40).map(c=>{
    const sel = _compo.ctaId===c.id;
    const isSug = (sugId===c.id && !sel);
    const ty = CTA_TYPES[c.type] || {emoji:'',label:c.type};
    return `<div class="sum-box lnk" style="${sel?'background:#f6efe4;border-left:4px solid #52252F':(isSug?'border-left:4px solid #AA7C39':'')}" onclick="compoPickCta('${c.id}')">
      <span>${ty.emoji} ${esc(c.texte)}</span>${sel?'<b>✓</b>':(isSug?'<b style="color:#AA7C39;font-size:.72rem">suggéré</b>':'')}</div>`;
  }).join('') + (list.length>40?`<p class="note">… et ${list.length-40} autres. Affine avec un mot-clé.</p>`:'');
}

// Assemble accroche + texte choisis en un post final
function compoResultat(){
  const a = _compo.accrocheId ? SC_ACCROCHES.find(x=>x.id===_compo.accrocheId) : null;
  const t = _compo.texteId ? SC_TEXTES.find(x=>x.id===_compo.texteId) : null;
  const cChoisi = _compo.ctaId ? SC_CTA.find(x=>x.id===_compo.ctaId) : null;
  if(!a && !t && !cChoisi) return null;
  const parts = [];
  if(a) parts.push(a.texte);
  if(t) parts.push(t.texte);
  // CTA final : le CTA explicitement choisi prime ; sinon celui embarqué dans le texte.
  const ctaFinal = cChoisi ? cChoisi.texte : (t && t.cta ? t.cta : null);
  if(ctaFinal) parts.push(ctaFinal);
  return parts.join('\n\n');
}

async function renderCompositeur(){
  const main = document.getElementById('main'); if(!main) return;
  await compoChargerUsage();   // anti-répétition : marque le déjà-publié
  const seg = (val, cur, onclick, label) =>
    `<button class="btn ${cur===val?'gold':'ghost'} sm" style="margin:2px" onclick="${onclick}">${label}</button>`;

  const resultat = compoResultat();
  const nbA = scFiltrerAccroches(_compo.objet, _compo.cible, _compo.kwAccroche).length;
  const nbT = scFiltrerTextes(_compo.objet, _compo.cible, _compo.kwTexte).length;
  const nbCta = scFiltrerCTA(_compo.objet, _compo.cible, _compo.ctaType, _compo.kwCta).length;
  // Segments de type d'action présents pour l'objet/cible courants.
  const typesDispo = [...new Set(SC_CTA.filter(c=>scMatchObjetCible(c,_compo.objet,_compo.cible)).map(c=>c.type))];
  const segCtaTypes = typesDispo.map(ty=>{
    const meta = CTA_TYPES[ty]||{emoji:'',label:ty}; const on=_compo.ctaType===ty;
    return `<button class="btn ${on?'gold':'ghost'} sm" style="margin:2px" onclick="compoSetCtaType('${ty}')">${meta.emoji} ${meta.label}</button>`;
  }).join('');

  main.innerHTML =
    `<div class="topbar"><div><h1>🧩 Composer un contenu</h1><p>Filtre en cascade : objet → cible → accroche → texte → CTA</p></div></div>

     <div class="panel">
       <h2>1 · Objet</h2>
       <div>${seg('vente',_compo.objet,"compoSetObjet('vente')",'🛒 Vente')}${seg('coaching',_compo.objet,"compoSetObjet('coaching')",'🎯 Coaching')}</div>
       <h2 style="margin-top:10px">2 · Cible</h2>
       <div>${seg('b2c',_compo.cible,"compoSetCible('b2c')",'👤 B2C (particuliers)')}${seg('b2b',_compo.cible,"compoSetCible('b2b')",'🏢 B2B (pros/événementiel)')}</div>
     </div>

     <div class="panel">
       <h2>3 · Accroche <span class="tag">${nbA}</span></h2>
       <input id="compoKwAccroche" placeholder="Mots-clés (ex : cadeau, four, mariage…)" value="${esc(_compo.kwAccroche)}"
              oninput="compoSearchAccroche(this.value)" style="width:100%;margin-bottom:6px">
       <div id="compoAccrochesList" style="max-height:260px;overflow-y:auto">${compoAccrochesHtml()}</div>
     </div>

     <div class="panel">
       <h2>4 · Texte <span class="tag">${nbT}</span></h2>
       <input id="compoKwTexte" placeholder="Mots-clés (ex : local, personnalisé, collerette…)" value="${esc(_compo.kwTexte)}"
              oninput="compoSearchTexte(this.value)" style="width:100%;margin-bottom:6px">
       <div id="compoTextesList" style="max-height:300px;overflow-y:auto">${compoTextesHtml()}</div>
     </div>

     <div class="panel">
       <h2>5 · Appel à l'action <span class="tag">${nbCta}</span></h2>
       <div style="display:flex;flex-wrap:wrap;align-items:center;gap:2px;margin-bottom:6px">
         ${segCtaTypes}
         <button class="btn ghost sm" style="margin:2px" onclick="compoCtaAuto()">✨ Suggérer</button>
       </div>
       <input id="compoKwCta" placeholder="Mots-clés (ex : devis, réserver, DM, atelier…)" value="${esc(_compo.kwCta)}"
              oninput="compoSearchCta(this.value)" style="width:100%;margin-bottom:6px">
       <div id="compoCtaList" style="max-height:240px;overflow-y:auto">${compoCtaHtml()}</div>
       <p class="note">Le CTA choisi remplace celui du texte. Sans choix, on garde le CTA d'origine du texte.</p>
     </div>

     <div class="panel" style="border:2px solid #52252F">
       <h2>✅ Ton contenu</h2>
       ${resultat
         ? `<div style="white-space:pre-line;padding:8px 0">${esc(resultat)}</div>
            ${(()=>{ const an=compoAnalysePersuasion(resultat); const cons=compoConseilsPersuasion(an);
               const jauge=an.principes.map(p=>`<span title="${esc(p.label)}" style="opacity:${p.ok?1:0.28};font-size:1rem">${p.emoji}</span>`).join(' ');
               return `<div class="sum-box" style="flex-direction:column;align-items:stretch;gap:6px">
                 <div style="display:flex;justify-content:space-between;align-items:center"><b>Force de persuasion</b><span class="tag" style="background:${an.score>=6?'#3f7d52':(an.score>=4?'#AA7C39':'#b0552f')};color:#fff">${an.score}/8</span></div>
                 <div>${jauge}</div>
                 ${cons.length?`<div class="note" style="line-height:1.5">${cons.map(c=>esc(c)).join('<br>')}</div>`:''}
               </div>`; })()}
            <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">
              <button class="btn ghost" style="flex:1" onclick="compoCopier(this)" data-copy="${esc(resultat)}">📋 Copier</button>
              <button class="btn gold" style="flex:1" onclick="compoEnregistrer()">💾 Au planning</button>
            </div>
            <button class="btn ghost" style="width:100%;margin-top:6px" onclick="cvDepuisCompositeur()">🎨 Créer le carrousel narratif (6–10 slides)</button>
            <button class="btn ghost" style="width:100%;margin-top:6px" onclick="cvPostSimple()">🖼️ Créer un post à visuel unique</button>
            <button class="btn ghost" style="width:100%;margin-top:6px" onclick="commSwitch('video')">🎬 En faire un scénario vidéo</button>`
         : '<p class="note">Choisissez une accroche et/ou un texte ci-dessus pour composer votre contenu.</p>'}
     </div>`;

  // Restaure le focus/caret dans les champs de recherche après re-render
  requestAnimationFrame(()=>{
    const fa=document.getElementById('compoKwAccroche'); const ft=document.getElementById('compoKwTexte');
    if(fa && _compo._focus==='a'){ fa.focus(); fa.setSelectionRange(fa.value.length,fa.value.length); }
    if(ft && _compo._focus==='t'){ ft.focus(); ft.setSelectionRange(ft.value.length,ft.value.length); }
  });
  commEnsureTabBar();
}

async function compoEnregistrer(){
  const resultat = compoResultat(); if(!resultat) return;
  if(typeof scAjouterPost==='function'){
    await scAjouterPost({
      titre: resultat.split('\n')[0].slice(0,60),
      texte: resultat,
      canal:'instagram', offre:(_compo.objet==='coaching'?'coaching':(_compo.cible==='b2b'?'b2b':'vente')),
      statut:'pret',
      sourceData:{ accrocheId:_compo.accrocheId, texteId:_compo.texteId, ctaId:_compo.ctaId },
    });
    toast('✅ Ajouté au planning (statut : Prêt)');
    if(typeof _scTab!=='undefined'){ _scTab='calendrier'; }
    commGotoPlanning();
  } else {
    toast('Contenu prêt — copie-le');
  }
}

