VID_STRUCTURES.push(...VID_STRUCTURES_LOT);


// ── État du module vidéo ──
const _vid = {
  objet:'vente', cible:'b2c', objectif:'vente', reseau:'reels',
  duree:'court', emotion:'gourmandise', produit:'', structureId:null,
  wizStep:0,   // étape courante de l'assistant guidé (0-based)
};

// ── Anti-répétition vidéo : structures déjà utilisées dans des scénarios
//    programmés ou publiés. Rempli avant chaque rendu du module. ──
const _vidUsed = new Set();
async function vidChargerUsage(){
  _vidUsed.clear();
  if(typeof db==='undefined' || !db.posts) return;
  try{
    const posts = await db.posts.toArray();
    for(const p of posts){
      if(p.statut!=='programme' && p.statut!=='publie') continue;
      if(p.sourceData && p.sourceData.vidStructureId){ _vidUsed.add(p.sourceData.vidStructureId); }
      // Filet pour d'anciens posts vidéo sans sourceData : on repère par le libellé du titre.
      else if(p.titre && p.titre.indexOf('🎬')>=0){
        const st = VID_STRUCTURES.find(x=>p.titre.indexOf(x.label)>=0);
        if(st) _vidUsed.add(st.id);
      }
    }
  }catch(e){ /* confort, pas bloquant */ }
}

function vidSet(k,val){ _vid[k]=val; if(k==='objectif'||k==='emotion'){ _vid.structureId=null; } renderVideo(); }
function vidSetProduit(v){ _vid.produit=v; }
function vidPickStructure(id){ _vid.structureId=(id===_vid.structureId?null:id); renderVideo(); }

// Recommandation : structures triées par pertinence (match objectif + émotion).
function vidStructuresRecommandees(){
  return VID_STRUCTURES.map(s=>{
    let score=0;
    if(s.objectifs.includes(_vid.objectif)) score+=2;
    if(s.emotions.includes(_vid.emotion)) score+=2;
    // Coaching : privilégier erreur/avant-après/témoignage.
    if(_vid.objet==='coaching' && ['erreur_frequente','avant_apres','temoignage'].includes(s.id)) score+=1;
    // Anti-répétition : une structure déjà utilisée (programmée/publiée) est
    // pénalisée pour laisser passer de la variété, sans être exclue.
    if(typeof _vidUsed!=='undefined' && _vidUsed.has(s.id)) score-=3;
    return {s,score};
  }).sort((a,b)=>b.score-a.score);
}

// Contexte d'injection : dérive des variables lisibles à partir des choix.
function vidContexte(){
  const cibleLabel = _vid.cible==='b2b' ? 'les pros et organisateurs' : (_vid.objet==='coaching' ? 'ceux qui ratent leurs macarons' : 'les gourmands');
  const produit = (_vid.produit||'').trim() || VID_PRODUIT_DEFAUT;
  const emo = VID_EMOTIONS[_vid.emotion]||{label:''};
  // Bénéfice/émotion/objection/moment dérivés de l'objet + émotion (banque courte).
  const benefBy = {
    vente:'Moins de sucre, plus de sensation — le vrai goût à chaque bouchée',
    coaching:'Enfin des coques lisses, brillantes, réussies à tous les coups',
    notoriete:'Un savoir-faire artisanal, fait main ici à Le Mans',
    lancement:'Un nouveau parfum de saison, à savourer maintenant',
    fidelisation:'La qualité qui donne envie de revenir',
    education:'Comprendre enfin le pourquoi de chaque geste',
  };
  const objBy = _vid.objet==='coaching' ? "Je n'ai pas la main pour ça" : "Je n'aime pas les macarons, c'est trop sucré";
  const douBy = _vid.objet==='coaching' ? "vos collerettes craquellent ou penchent" : "vous ne savez jamais quel dessert apporter";
  const momBy = {
    gourmandise:'une pause café rien qu\'à vous', nostalgie:'un souvenir à partager',
    fierte:'offrir ce que vous avez fait vous-même', surprise:'surprendre vos invités',
    confiance:'un cadeau qui ne déçoit jamais', desir:'vous faire vraiment plaisir',
    humour:'un moment léger entre amis',
  };
  return {
    produit, cibleLabel,
    objectif:_vid.objectif, emotion:_vid.emotion, emotionLabel:emo.label,
    reseau:_vid.reseau, duree:_vid.duree,
    benefice: benefBy[_vid.objectif]||benefBy.vente,
    objection: objBy, douleur: douBy, moment: momBy[_vid.emotion]||'un bon moment',
    cta: _vid.objet==='coaching' ? 'Réservez votre séance — lien en bio 🎯' : 'Commandez — lien en bio 📩',
  };
}

// Résout une valeur de beat qui peut être une fonction(v) ou une string (avec ${v.x}).
function _vidResolve(val, v){
  if(typeof val==='function'){ try{ return val(v)||''; }catch(e){ return ''; } }
  if(typeof val==='string' && val.indexOf('${')>=0){
    return val.replace(/\$\{v\.(\w+)\}/g, (m,k)=> (v[k]!=null?v[k]:''));
  }
  return val||'';
}

// Assemble le scénario complet à partir de la structure choisie.
function vidGenererScenario(){
  const st = _vid.structureId ? VID_STRUCTURES.find(x=>x.id===_vid.structureId) : vidStructuresRecommandees()[0].s;
  if(!st) return null;
  const v = vidContexte();
  const dur = VID_DUREES[_vid.duree]||VID_DUREES.court;
  const totalSec = dur.sec;
  // Durées de plans proportionnelles à part[], normalisées sur totalSec.
  const somme = st.beats.reduce((a,b)=>a+b.part,0);
  let acc=0;
  const plans = st.beats.map((b,i)=>{
    const secBrut = totalSec*(b.part/somme);
    const debut = acc; acc+=secBrut;
    return {
      n:i+1,
      role:b.role,
      debut:debut, fin:acc, duree:secBrut,
      cadrage:_vidResolve(b.cadrage,v),
      cam:_vidResolve(b.cam,v),
      visu:_vidResolve(b.visu,v),
      texteEcran:_vidResolve(b.texteEcran,v),
      voix:_vidResolve(b.voix,v),
      son:_vidResolve(b.son,v),
      intention:_vidResolve(b.intention,v),
    };
  });
  return {
    structure:st, v,
    concept:_vidResolve(st.concept,v),
    message:_vidResolve(st.message,v),
    hook:_vidResolve(st.hook,v),
    objectifLabel:(VID_OBJECTIFS[_vid.objectif]||{}).label||'',
    emotionLabel:v.emotionLabel,
    reseauLabel:(VID_RESEAUX[_vid.reseau]||{}).label||'',
    ratio:(VID_RESEAUX[_vid.reseau]||{}).ratio||'9:16',
    dureeLabel:dur.label, totalSec,
    plans,
    cta:v.cta,
  };
}

// Formatte le scénario en texte copiable / storyboard.
function vidScenarioTexte(sc){
  if(!sc) return '';
  const L=[];
  L.push(`🎬 SCÉNARIO — ${sc.structure.label}`);
  L.push(`Réseau : ${sc.reseauLabel} (${sc.ratio}) · Durée : ${sc.dureeLabel} (~${Math.round(sc.totalSec)}s)`);
  L.push('');
  L.push(`• Concept : ${sc.concept}`);
  L.push(`• Message principal : ${sc.message}`);
  L.push(`• Objectif : ${sc.objectifLabel} · Émotion dominante : ${sc.emotionLabel}`);
  L.push(`• Hook (0-3s) : ${sc.hook}`);
  L.push('');
  L.push('— DÉCOUPAGE PLAN PAR PLAN —');
  sc.plans.forEach(p=>{
    L.push('');
    L.push(`PLAN ${p.n} · ${p.role} · ${p.debut.toFixed(1)}→${p.fin.toFixed(1)}s (${p.duree.toFixed(1)}s)`);
    L.push(`  Cadrage : ${p.cadrage}`);
    L.push(`  Caméra : ${p.cam}`);
    if(p.visu) L.push(`  Image : ${p.visu}`);
    if(p.texteEcran) L.push(`  Texte à l'écran : « ${p.texteEcran} »`);
    if(p.voix) L.push(`  Voix / dialogue : « ${p.voix} »`);
    if(p.son) L.push(`  Son : ${p.son}`);
    L.push(`  Intention : ${p.intention}`);
  });
  L.push('');
  L.push(`👉 CTA final : ${sc.cta}`);
  return L.join('\n');
}

// ── Voix off : extrait UNIQUEMENT les répliques à dire (le champ `voix` de
//    chaque plan) + le CTA final, assemblées en un script fluide et continu,
//    prêt à coller dans un outil de synthèse vocale (ex. Gradium, voix clonée).
//    On retire les indications techniques et les guillemets de storyboard.
function vidVoixOffTexte(sc){
  if(!sc) return '';
  const lignes = [];
  sc.plans.forEach(p=>{
    if(p.voix && p.voix.trim()){
      // Nettoie les guillemets typographiques éventuels autour de la réplique.
      let v = p.voix.trim().replace(/^[«"']\s*/,'').replace(/\s*[»"']$/,'').trim();
      if(v) lignes.push(v);
    }
  });
  // Le CTA final se dit aussi (souvent la dernière phrase de la vidéo).
  if(sc.cta && sc.cta.trim()){
    let c = sc.cta.trim().replace(/^[«"']\s*/,'').replace(/\s*[»"']$/,'').trim();
    if(c && lignes[lignes.length-1]!==c) lignes.push(c);
  }
  // Assemble en petites phrases séparées : une réplique par ligne, ce qui donne
  // un débit naturel à la lecture (les moteurs TTS respectent les sauts de ligne).
  return lignes.join('\n');
}

/* ── Rendu de la vue vidéo : ASSISTANT GUIDÉ (5 étapes) ── */
// Définition des étapes : titre + test de validité (peut-on continuer ?).
const VID_WIZ = [
  { titre:'Que veux-vous communiquer ?', valid:()=> !!_vid.objet && !!_vid.cible && !!_vid.objectif },
  { titre:'Format de la vidéo',        valid:()=> !!_vid.reseau && !!_vid.duree && !!_vid.emotion },
  { titre:'Votre sujet',                 valid:()=> true },   // produit optionnel
  { titre:'La structure narrative',    valid:()=> true },   // une reco existe toujours
  { titre:'Votre scénario',              valid:()=> true },
];
function vidWizGo(i){ _vid.wizStep = Math.max(0, Math.min(VID_WIZ.length-1, i)); renderVideo(); }
function vidWizNext(){ if(VID_WIZ[_vid.wizStep].valid()) vidWizGo(_vid.wizStep+1); }
function vidWizPrev(){ vidWizGo(_vid.wizStep-1); }

async function renderVideo(){
  const main=document.getElementById('main'); if(!main) return;
  await vidChargerUsage();   // anti-répétition : marque les structures déjà utilisées
  const step = Math.max(0, Math.min(VID_WIZ.length-1, _vid.wizStep||0));
  _vid.wizStep = step;

  // Boutons de choix (style wizard). Sélectionne _vid[k]=val puis re-rend.
  const opt=(k,val,label,emoji)=>`<button class="wiz-opt ${_vid[k]===val?'on':''}" onclick="vidSet('${k}','${val}');renderVideo()">${emoji?`<span class="wiz-opt-ico">${emoji}</span>`:''}${label}</button>`;

  // Aperçu compact (sticky) : rappelle les choix + le scénario visé.
  const sc = vidGenererScenario();
  const chips = [
    _vid.objet && `<span class="wiz-chip">${_vid.objet==='vente'?'🛒 Vente':'🎯 Coaching'}</span>`,
    _vid.cible && `<span class="wiz-chip">${_vid.cible==='b2c'?'👤 B2C':'🏢 B2B'}</span>`,
    (step>=1 && _vid.reseau) && `<span class="wiz-chip">${esc((VID_RESEAUX[_vid.reseau]||{}).label||_vid.reseau)}</span>`,
    (step>=1 && _vid.duree) && `<span class="wiz-chip">~${sc?Math.round(sc.totalSec):''}s</span>`,
    (step>=2 && _vid.produit) && `<span class="wiz-chip">🧁 ${esc(_vid.produit)}</span>`,
    (step>=3 && sc) && `<span class="wiz-chip">🎬 ${esc(sc.structure.label)}</span>`,
  ].filter(Boolean).join('');
  const apercu = `<div class="wiz-preview"><div class="wiz-preview-title">Votre vidéo en bref</div>${chips||'<span class="note">Faites vos premiers choix…</span>'}</div>`;

  // ---- Contenu de l'étape courante ----
  let body='';
  if(step===0){
    body = `<p class="wiz-hint">On commence par le fond : quel est le but de cette vidéo, et pour qui ?</p>
      <label class="note" style="font-weight:600;display:block">Objet</label>
      <div class="wiz-choice" style="margin:6px 0 12px">${opt('objet','vente','Vente','🛒')}${opt('objet','coaching','Coaching','🎯')}</div>
      <label class="note" style="font-weight:600;display:block">Cible</label>
      <div class="wiz-choice" style="margin:6px 0 12px">${opt('cible','b2c','Particuliers (B2C)','👤')}${opt('cible','b2b','Professionnels (B2B)','🏢')}</div>
      <label class="note" style="font-weight:600;display:block">Objectif marketing</label>
      <div class="wiz-choice" style="margin:6px 0 0">${Object.entries(VID_OBJECTIFS).map(([k,o])=>opt('objectif',k,o.label,o.emoji)).join('')}</div>`;
  } else if(step===1){
    body = `<p class="wiz-hint">Le format donne le rythme : où sera publiée la vidéo, sa durée, et l'émotion qu'elle doit dégager.</p>
      <label class="note" style="font-weight:600;display:block">Réseau</label>
      <div class="wiz-choice" style="margin:6px 0 12px">${Object.entries(VID_RESEAUX).map(([k,r])=>opt('reseau',k,r.label,r.emoji)).join('')}</div>
      <label class="note" style="font-weight:600;display:block">Durée</label>
      <div class="wiz-choice" style="margin:6px 0 12px">${Object.entries(VID_DUREES).map(([k,d])=>opt('duree',k,d.label)).join('')}</div>
      <label class="note" style="font-weight:600;display:block">Émotion dominante</label>
      <div class="wiz-choice" style="margin:6px 0 0">${Object.entries(VID_EMOTIONS).map(([k,e])=>opt('emotion',k,e.label,e.emoji)).join('')}</div>`;
  } else if(step===2){
    body = `<p class="wiz-hint">Quel produit met-on en avant ? C'est optionnel, mais ça rend le scénario plus concret (le nom sera glissé dans les plans).</p>
      <label class="note" style="font-weight:600;display:block">Produit mis en avant</label>
      <input id="vidProduit" value="${esc(_vid.produit)}" oninput="vidSetProduit(this.value)" placeholder="ex : macaron citron-basilic, coffret découverte…" style="width:100%;margin-top:6px">
      <p class="note">Vous pouvez laisser vide : le scénario restera générique et parlera de « vos macarons ».</p>`;
  } else if(step===3){
    const reco = vidStructuresRecommandees();
    const structsHtml = reco.map(({s})=>{
      const sel=_vid.structureId===s.id;
      const best=(!_vid.structureId && s.id===reco[0].s.id);
      const used=(typeof _vidUsed!=='undefined' && _vidUsed.has(s.id));
      return `<div class="sum-box lnk" style="flex-direction:column;align-items:stretch;gap:3px;${sel?'background:#f6efe4;border-left:4px solid #52252F':(best?'border-left:4px solid #AA7C39':'')}${used?';opacity:.6':''}" onclick="vidPickStructure('${s.id}');renderVideo()">
        <div style="display:flex;justify-content:space-between;align-items:center"><b>${s.emoji} ${s.label}</b>${sel?'<b>✓</b>':(used?'<b style="color:#9a8576;font-size:.68rem;font-weight:600">déjà utilisée</b>':(best?'<b style="color:#AA7C39;font-size:.7rem">recommandé</b>':''))}</div>
        <div class="note" style="font-size:.72rem">${esc(s.mecanique)}</div></div>`;
    }).join('');
    body = `<p class="wiz-hint">Voici la structure recommandée (liseré caramel) selon vos choix. Gardez-la, ou choisissez-en une autre — chacune raconte différemment.</p>
      ${structsHtml}`;
  } else if(step===4){
    const scTexte = vidScenarioTexte(sc);
    const planHtml = sc ? sc.plans.map(p=>`
       <div class="sum-box" style="flex-direction:column;align-items:stretch;gap:2px">
         <div style="display:flex;justify-content:space-between"><b>Plan ${p.n} · ${esc(p.role)}</b><span class="note">${p.debut.toFixed(1)}→${p.fin.toFixed(1)}s</span></div>
         <div class="note" style="font-size:.74rem;line-height:1.5">
           🎥 <b>Cadrage</b> ${esc(p.cadrage)} · <b>Caméra</b> ${esc(p.cam)}<br>
           ${p.visu?`🖼️ ${esc(p.visu)}<br>`:''}
           ${p.texteEcran?`🔤 <b>À l'écran :</b> « ${esc(p.texteEcran)} »<br>`:''}
           ${p.voix?`🎙️ <b>Voix :</b> « ${esc(p.voix)} »<br>`:''}
           ${p.son?`🔊 ${esc(p.son)}<br>`:''}
           💡 <i>${esc(p.intention)}</i>
         </div>
       </div>`).join('') : '';
    body = sc ? `<div class="sum-box" style="flex-direction:column;align-items:stretch;gap:4px">
         <div class="note"><b>Réseau</b> ${esc(sc.reseauLabel)} (${sc.ratio}) · <b>Durée</b> ~${Math.round(sc.totalSec)}s · <b>Émotion</b> ${esc(sc.emotionLabel)}</div>
         <div><b>Concept :</b> ${esc(sc.concept)}</div>
         <div><b>Message :</b> ${esc(sc.message)}</div>
         <div><b>Hook (0-3s) :</b> ${esc(sc.hook)}</div>
       </div>
       <h3 style="margin:12px 0 4px;color:var(--bordeaux)">Découpage plan par plan</h3>
       ${planHtml}
       <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:12px">
         <button class="btn ghost" style="flex:1" onclick="vidCopier(this)" data-copy="${esc(scTexte)}">📋 Copier le scénario</button>
         <button class="btn gold" style="flex:1" onclick="vidAuPlanning()">🗓️ Au planning</button>
       </div>
       <div class="sum-box" style="flex-direction:column;align-items:stretch;gap:6px;margin-top:10px;background:#faf6ee;border:1px solid #e8dcc0">
         <div style="display:flex;justify-content:space-between;align-items:center">
           <b style="color:var(--bordeaux)">🎙️ Voix off (texte à dire)</b>
           <button class="btn ghost sm" onclick="vidCopier(this)" data-copy="${esc(vidVoixOffTexte(sc))}">📋 Copier</button>
         </div>
         <div class="note" style="font-size:.72rem;white-space:pre-line;background:#fff;border-radius:8px;padding:8px;border:1px solid #ece3d6">${esc(vidVoixOffTexte(sc))||'—'}</div>
         <p class="note" style="font-size:.68rem;margin:0">Seulement les répliques à dire, sans les indications techniques. À coller dans votre outil de synthèse vocale (voix clonée), puis à monter sur votre Reel.</p>
       </div>`
      : '<p class="note">Complétez les étapes précédentes pour générer votre scénario.</p>';
  }

  // Navigation : à la dernière étape, pas de « Continuer » (on est au résultat).
  const nav = (step < VID_WIZ.length-1)
    ? wizNav('vidWizPrev','vidWizNext', VID_WIZ[step].valid(), { first: step===0 })
    : `<div class="wiz-nav"><button class="btn ghost" onclick="vidWizPrev()">← Retour</button><button class="btn ghost" onclick="vidWizGo(0)">↻ Recommencer</button></div>`;

  main.innerHTML=
    `<div class="topbar"><div><h1>🎬 Scénario vidéo</h1><p>Assistant guidé — un pas à la fois</p></div></div>
     ${wizProgress(VID_WIZ.length, step, 'vidWizGo')}
     <div class="wiz-card">
       ${wizHead(step, VID_WIZ.length, VID_WIZ[step].titre)}
       ${body}
       ${nav}
     </div>
     ${apercu}`;
  commEnsureTabBar();
}

function vidCopier(btn){ if(typeof scCopier==='function') return scCopier(btn); const t=btn&&btn.getAttribute?btn.getAttribute('data-copy'):''; try{navigator.clipboard&&navigator.clipboard.writeText(t).then(()=>toast('📋 Copié'));}catch(e){toast('Copie manuelle');} }

async function vidAuPlanning(){
  const sc=vidGenererScenario(); if(!sc){ toast('Rien à enregistrer'); return; }
  if(typeof scAjouterPost!=='function'){ toast('Planning indisponible'); return; }
  const canal = (_vid.reseau==='story')?'stories':'reels';
  await scAjouterPost({
    titre:'🎬 '+sc.structure.label+' — '+sc.reseauLabel,
    texte:vidScenarioTexte(sc),
    canal, offre:(_vid.objet==='coaching'?'coaching':(_vid.cible==='b2b'?'b2b':'vente')),
    statut:'a_rediger',
    sourceData:{ vidStructureId: sc.structure.id },
  });
  toast('✅ Scénario au planning');
  if(typeof _scTab!=='undefined'){ _scTab='calendrier'; }
  commGotoPlanning();
}

