/* ===== MODULE VENTILATION PAR MODE D'ENCAISSEMENT (v1218) ===== */
/* ============================================================================
 *  MODULE « VENTILATION PAR MODE D'ENCAISSEMENT » — v1218
 *  Sensations Macarons · Pilotage PWA — rubrique Comptabilité
 *  Ventile/filtre le CA encaissé par mode (Virement/Carte/Espèces/Chèque/PayPal),
 *  croisé par mois, avec détail cliquable et export CSV.
 *  Réutilise les règles EXACTES de computeAccounting → zéro divergence.
 * ==========================================================================*/

const VENTIL_ACCENT = '#52252F';
const VENTIL_COLORS = {
  'Virement':'#3a6ea5', 'Carte':'#AA7C39', 'Espèces':'#3f7d52',
  'Chèque':'#7a5c8e', 'PayPal':'#2a9d9d', 'Autre (marché)':'#9a8576', '—':'#b0a396',
};
function ventilColor(m){ return VENTIL_COLORS[m] || VENTIL_ACCENT; }

// Logique pure (testée : 13/13). Retourne modes, croisé mode×mois, détail, total.
function ventilationEncaissements(orders, markets, opts){
  opts = opts || {};
  const start = opts.periodeStart || null, end = opts.periodeEnd || null;
  const filtreMode = opts.mode || null;
  const inRange = d => { if(!d) return false; if(start && d<start) return false; if(end && d>end) return false; return true; };
  const modes = {}, parModeEtMois = {}, detail = {}, moisSet = new Set();
  const add = (mode, ym, montant, src, ref, date) => {
    if(filtreMode && mode !== filtreMode) return;
    modes[mode] = money2((modes[mode]||0) + montant);
    parModeEtMois[mode] = parModeEtMois[mode] || {};
    parModeEtMois[mode][ym] = money2((parModeEtMois[mode][ym]||0) + montant);
    moisSet.add(ym);
    (detail[mode] = detail[mode] || []).push({ date, montant, source:src, ref });
  };
  (orders||[]).forEach(o => {
    if(o.histo) return;
    paiementsDe(o).forEach(p => {
      if((start||end) && !inRange(p.date)) return;
      const ym = monthKey(p.date); if(!ym) return;
      add(p.moyen || '—', ym, money2(p.montant), 'commande', o.id, p.date);
    });
  });
  (markets||[]).forEach(mk => {
    if(mk.statut !== 'clos') return;
    if((start||end) && !inRange(mk.date)) return;
    const ym = monthKey(mk.date); if(!ym) return;
    const ca = mk.ca || {}; const fond = money2(+mk.fondCaisse||0);
    const esp = money2(Math.max(0, (+ca.especes||0) - fond)), cb = money2(ca.cb||0), au = money2(ca.autre||0);
    if(esp>0) add('Espèces', ym, esp, 'marché', mk.id, mk.date);
    if(cb>0)  add('Carte', ym, cb, 'marché', mk.id, mk.date);
    if(au>0)  add('Autre (marché)', ym, au, 'marché', mk.id, mk.date);
  });
  const total = money2(Object.values(modes).reduce((s,v)=>s+v, 0));
  return { modes, parModeEtMois, mois:[...moisSet].sort(), detail, total };
}

let _ventilMode = null;
function ventilSetMode(m){ _ventilMode = (m === _ventilMode) ? null : (m || null); renderVentilation(); }

async function renderVentilation(){
  const main = document.getElementById('main'); if(!main) return;
  const orders = await db.orders.toArray().catch(()=>[]);
  const markets = await db.markets.toArray().catch(()=>[]);

  const periode = (typeof _comptaPeriode !== 'undefined') ? _comptaPeriode : null;
  const usePeriode = periode && periode !== 'tout' && typeof comptaPeriodeStart === 'function';
  const baseOpts = usePeriode ? { periodeStart:comptaPeriodeStart(periode), periodeEnd:comptaPeriodeEnd(periode) } : {};

  const global = ventilationEncaissements(orders, markets, baseOpts);
  const V = _ventilMode ? ventilationEncaissements(orders, markets, Object.assign({}, baseOpts, {mode:_ventilMode})) : global;

  const pct = (v,d)=> d>0 ? Math.round(v/d*100) : 0;
  const modesTries = Object.entries(global.modes).sort((a,b)=>b[1]-a[1]);

  const chip = (label, actif, onclick) =>
    `<button class="btn ${actif?'gold':'ghost'} sm" style="margin:2px" onclick="${onclick}">${esc(label)}</button>`;
  const filtres =
    chip('Tous', !_ventilMode, "ventilSetMode(null)") +
    modesTries.map(([mode])=>chip(mode, _ventilMode===mode, `ventilSetMode('${escJs(mode)}')`)).join('');

  const cartes = modesTries.map(([mode,val])=>{
    const actif = _ventilMode===mode;
    return `<div class="sum-box lnk" style="border-left:4px solid ${ventilColor(mode)};${actif?'background:#f6efe4':''}"
                 onclick="ventilSetMode('${escJs(mode)}')">
       <span>${esc(mode)}</span>
       <b>${euro(val)} <span style="color:#9a8a82;font-weight:400">(${pct(val, global.total)}%)</span></b></div>`;
  }).join('');

  let tableau = '';
  if(V.mois.length){
    const modesAffiches = _ventilMode ? [_ventilMode] : modesTries.map(([mode])=>mode);
    const entete = `<tr><th style="text-align:left">Mode</th>${V.mois.map(ym=>`<th>${esc(monthLabel(ym))}</th>`).join('')}<th>Total</th></tr>`;
    const lignes = modesAffiches.map(mode=>{
      const parMois = V.parModeEtMois[mode] || {};
      const tot = Object.values(parMois).reduce((s,x)=>s+x,0);
      if(tot<=0) return '';
      const cells = V.mois.map(ym=>`<td style="text-align:right">${parMois[ym]?euro(parMois[ym]):'<span style="color:#cbb9ab">–</span>'}</td>`).join('');
      return `<tr><td style="border-left:3px solid ${ventilColor(mode)};padding-left:6px">${esc(mode)}</td>${cells}<td style="text-align:right;font-weight:600">${euro(money2(tot))}</td></tr>`;
    }).join('');
    const totMois = V.mois.map(ym=>{
      const t = Object.keys(V.parModeEtMois).reduce((s,mode)=>s+((V.parModeEtMois[mode]||{})[ym]||0),0);
      return `<td style="text-align:right;font-weight:700">${euro(money2(t))}</td>`;
    }).join('');
    tableau = `<div class="table-wrap"><table>
      <thead>${entete}</thead><tbody>${lignes}
      <tr style="border-top:2px solid ${VENTIL_ACCENT}"><td style="font-weight:700">Total</td>${totMois}<td style="text-align:right;font-weight:700">${euro(V.total)}</td></tr>
      </tbody></table></div>`;
  }

  let detailBloc = '';
  if(_ventilMode && V.detail[_ventilMode]){
    const lignes = V.detail[_ventilMode].slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''))
      .map(d=>`<div class="sum-box"><span>${esc(fmtDate(d.date))} · ${d.source==='marché'?'⛺ Marché':'🧾 Commande'} #${esc(String(d.ref))}</span><b>${euro(d.montant)}</b></div>`).join('');
    detailBloc = `<h3 style="margin-top:14px;color:${ventilColor(_ventilMode)}">Détail — ${esc(_ventilMode)} (${V.detail[_ventilMode].length} encaissement(s))</h3>${lignes}`;
  }

  main.innerHTML =
    `<div class="topbar"><div><h1>💳 Encaissements par mode</h1><p>Ventile et filtre ton CA encaissé par moyen de paiement${usePeriode?` · période « ${esc(periode)} »`:" · tout l'historique"}</p></div></div>
     <div class="banner" style="background:#f6efe4;border-color:#e0d3bf"><div>Ces chiffres reprennent EXACTEMENT les règles de ta comptabilité (encaissement réel, marchés clôturés espèces nettes du fond de caisse). Le total ci-dessous doit être égal au « Total encaissé » de la compta sur la même période.</div></div>
     <div style="margin:8px 0">${filtres}</div>
     <div class="sum-box" style="background:#f6efe4"><span><b>Total encaissé${_ventilMode?` (${esc(_ventilMode)})`:''}</b></span><b>${euro(V.total)}</b></div>
     ${_ventilMode?'':cartes}
     ${tableau || '<div class="panel"><p class="note">Aucun encaissement sur la période.</p></div>'}
     ${detailBloc}
     <button class="btn ghost" style="width:100%;margin-top:12px" onclick="ventilExportCSV()">⬇️ Exporter en CSV</button>`;
}

async function ventilExportCSV(){
  const orders = await db.orders.toArray().catch(()=>[]);
  const markets = await db.markets.toArray().catch(()=>[]);
  const periode = (typeof _comptaPeriode !== 'undefined') ? _comptaPeriode : null;
  const usePeriode = periode && periode !== 'tout' && typeof comptaPeriodeStart === 'function';
  const opts = usePeriode ? { periodeStart:comptaPeriodeStart(periode), periodeEnd:comptaPeriodeEnd(periode) } : {};
  const V = ventilationEncaissements(orders, markets, opts);
  if(!V.mois.length){ toast('Rien à exporter'); return; }
  const sep = ';';
  const head = ['Mode', ...V.mois.map(ym=>monthLabel(ym)), 'Total'].join(sep);
  const modesTries = Object.keys(V.modes).sort((a,b)=>V.modes[b]-V.modes[a]);
  const rows = modesTries.map(mode=>{
    const pm = V.parModeEtMois[mode]||{};
    const tot = Object.values(pm).reduce((s,x)=>s+x,0);
    return [mode, ...V.mois.map(ym=>(pm[ym]||0).toFixed(2).replace('.',',')), money2(tot).toFixed(2).replace('.',',')].join(sep);
  });
  const totLine = ['Total', ...V.mois.map(ym=>{
    const t = modesTries.reduce((s,mode)=>s+((V.parModeEtMois[mode]||{})[ym]||0),0);
    return money2(t).toFixed(2).replace('.',',');
  }), money2(V.total).toFixed(2).replace('.',',')].join(sep);
  const csv = '\uFEFF' + [head, ...rows, totLine].join('\n');
  try{
    const blob = new Blob([csv], {type:'text/csv;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `encaissements-par-mode${usePeriode?'-'+periode:''}.csv`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url), 1000);
    toast('📄 CSV exporté');
  }catch(e){ toast('Export impossible sur ce navigateur'); }
}

/* ===== FIN MODULE VENTILATION ===== */

// Change la granularité du graphique manque à gagner et redessine juste cette zone.
function gapSetGran(g){
  _gapGran = g;
  // Met à jour l'état visuel des boutons sans tout re-render.
  ['jour','semaine','mois'].forEach(k=>{
    const btns=[...document.querySelectorAll('#gapPanel .btn.sm')];
    const b=btns.find(x=>x.textContent.trim().toLowerCase()===k);
    if(b){ b.classList.toggle('gold', k===g); b.classList.toggle('ghost', k!==g); }
  });
  gapRenderChart();
}
// Construit le graphique double courbe + l'encart de synthèse dans #gapChartZone.
// [A13-fix] Le rendu HTML est isolé dans buildGapChartHTML (pur, synchrone) pour permettre
// une injection SYNCHRONE dans renderCompta (données pré-calculées avant le paint) — même
// stratégie que buildDashProductionHTML/A14. Fini le remplissage différé et le min-height magique.
function buildGapChartHTML(data){
  if(!data || !data.keys.length){
    return '<div class="empty">Aucune livraison renseignée pour le moment. Renseignez la distance/temps de livraison sur vos commandes pour suivre le manque à gagner.</div>';
  }
  const xfmt = x => {
    if(_gapGran==='mois') return monthLabel ? monthLabel(x) : x;
    if(_gapGran==='semaine') return x.replace('-S',' · S');
    return x.slice(8)+'/'+x.slice(5,7);   // JJ/MM
  };
  const chart = lineChart(data.series, {zero:true, xlabel:xfmt, fmt:v=>Math.round(v)+'€'});
  const s = data.synth;
  const encart = `
      <div class="panel" style="margin-top:14px;background:#fbf7f0;border-color:#ecdfc9">
        <div class="flex" style="justify-content:space-between;flex-wrap:wrap;gap:14px">
          <div style="min-width:120px">
            <div style="font-size:.72rem;color:#9a8a82;text-transform:uppercase;letter-spacing:.04em">Votre CA réel</div>
            <div style="font-size:1.4rem;font-weight:700;color:#AA7C39">${euro(s.ca)}</div>
          </div>
          <div style="min-width:120px">
            <div style="font-size:.72rem;color:#9a8a82;text-transform:uppercase;letter-spacing:.04em">Manque à gagner</div>
            <div style="font-size:1.4rem;font-weight:700;color:#a5453b">${euro(s.manque)}</div>
            <div style="font-size:.72rem;color:#9a8a82">soit ${s.pctManque}% de votre CA</div>
          </div>
          <div style="min-width:120px">
            <div style="font-size:.72rem;color:#9a8a82;text-transform:uppercase;letter-spacing:.04em">CA potentiel</div>
            <div style="font-size:1.4rem;font-weight:700;color:#3f7d52">${euro(s.potentiel)}</div>
          </div>
        </div>
        <p class="note" style="margin-top:10px;margin-bottom:0">
          <b>${s.nbNonFact}</b> livraison(s) non facturée(s) représentent <b>${euro(s.manque)}</b> de CA non perçu.
          <b>${s.nbFact}</b> livraison(s) facturée(s) (marquées d'un <b style="color:#AA7C39">+</b> sur la courbe).
          ${s.manque>0 ? 'Facturer vos livraisons rapprocherait la courbe dorée (CA réel) de la verte (potentiel).' : 'Bravo : aucune livraison non facturée sur cette vue.'}
        </p>
      </div>`;
  return chart + encart;
}
// Remplit #gapChartZone de façon asynchrone. Utilisé au CHANGEMENT de granularité (gapSetGran),
// où un recalcul post-paint est inévitable ; le premier rendu, lui, passe par l'injection synchrone.
async function gapRenderChart(){
  const zone=document.getElementById('gapChartZone');
  if(!zone) return;
  try{
    const data = await deliveryGapData(_gapGran);
    zone.innerHTML = buildGapChartHTML(data);
  }catch(e){
    console.error('gapRenderChart', e);
    zone.innerHTML='<div class="empty">Erreur lors du calcul du manque à gagner.</div>';
  }
}
// Liste détaillée des charges (gestion : éditer / supprimer)
/* ============================================================
   CHARGES RÉCURRENTES MENSUELLES (assurance, hébergement web, abos…)
   Modèles stockés en localStorage ; chaque mois, on matérialise une vraie
   charge dans db.charges (idempotent) → elle alimente la compta normalement.
   ============================================================ */
const RECUR_KEY = 'sm_recurringCharges';
function getRecurringCharges(){
  try{ const a=JSON.parse(localStorage.getItem(RECUR_KEY)||'[]'); return Array.isArray(a)?a:[]; }catch(e){ return []; }
}
function saveRecurringCharges(a){ localStorage.setItem(RECUR_KEY, JSON.stringify(a||[])); }
// Liste des mois "AAAA-MM" entre le mois de début (ou 12 mois en arrière) et le mois courant.
function _monthsUpToNow(startYM){
  const now=new Date(); const cur=new Date(now.getFullYear(), now.getMonth(), 1);
  let d;
  if(startYM && /^\d{4}-\d{2}$/.test(startYM)){ const [y,m]=startYM.split('-').map(Number); d=new Date(y, m-1, 1); }
  else { d=new Date(now.getFullYear(), now.getMonth()-11, 1); }   // par défaut : 12 derniers mois
  const out=[];
  while(d<=cur){ out.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')); d.setMonth(d.getMonth()+1); }
  return out;
}
// Matérialise les charges récurrentes manquantes (une par mois et par modèle actif).
// Idempotent : on tague chaque charge générée (recurId+ym) pour ne jamais doublonner.
async function materializeRecurringCharges(){
  const models = getRecurringCharges().filter(m=>m.actif!==false && +m.montant>0);
  if(!models.length) return 0;
  const existing = await db.charges.toArray();
  const seen = new Set(existing.filter(c=>c.recurId).map(c=>c.recurId+'|'+(c.date||'').slice(0,7)));
  let created=0;
  for(const m of models){
    const jour = Math.min(28, Math.max(1, +m.jourMois||1));   // 28 pour éviter les mois courts
    for(const ym of _monthsUpToNow(m.debut)){
      const key=m.id+'|'+ym;
      if(seen.has(key)) continue;
      const date = ym+'-'+String(jour).padStart(2,'0');
      await db.charges.add({date, categorie:m.categorie||'Autre', libelle:m.libelle||'Charge récurrente',
        montant:money2(+m.montant||0), recurId:m.id});
      seen.add(key); created++;
    }
  }
  return created;
}
// Éditeur des charges récurrentes (modèles).
async function recurringChargesForm(){
  const models = getRecurringCharges();
  const rows = models.map((m,i)=>`<div class="sum-box" style="flex-direction:column;align-items:stretch;gap:4px">
    <div style="display:flex;justify-content:space-between"><b>${esc(m.libelle||'—')}</b><b>${euro(m.montant)}/mois</b></div>
    <div style="display:flex;justify-content:space-between;font-size:.8rem;color:#9a8a82">
      <span>${esc(m.categorie||'Autre')} · le ${m.jourMois||1} du mois${m.actif===false?' · ⏸ en pause':''}</span>
      <span><span class="act" onclick="recurEdit(${i})">Modifier</span> <span class="act del" onclick="recurDel(${i})">Suppr.</span></span></div>
  </div>`).join('');
  openModal(`<h3>Charges mensuelles récurrentes</h3>
    <p class="note">Assurance pro, hébergement du site, abonnements… Saisies une fois, elles sont reportées automatiquement chaque mois dans la comptabilité.</p>
    <button class="btn gold sm" style="margin-bottom:8px" onclick="recurEdit(-1)">＋ Nouvelle charge récurrente</button>
    ${rows||'<p class="note">Aucune charge récurrente.</p>'}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button>
      <button class="btn" onclick="recurApplyNow()">Reporter maintenant</button></div>`);
}
function recurEdit(i){
  const models=getRecurringCharges();
  const m = i>=0 ? models[i] : {libelle:'', categorie:'Assurance professionnelle', montant:'', jourMois:1, debut:today().slice(0,7), actif:true};
  openModal(`<h3>${i>=0?'Modifier':'Nouvelle'} charge récurrente</h3>
    <div class="field"><label>Libellé *</label><input id="rc_lib" value="${esc(m.libelle||'')}" placeholder="ex : Assurance pro, Hébergement site web"></div>
    <div class="field"><label>Catégorie</label><select id="rc_cat">${CHARGE_CATS.map(x=>`<option ${m.categorie===x?'selected':''}>${x}</option>`).join('')}</select></div>
    <div class="row2">
      <div class="field"><label>Montant mensuel (€) *</label><input type="number" step="0.01" min="0" id="rc_mt" value="${m.montant||''}"></div>
      <div class="field"><label>Jour du mois</label><input type="number" min="1" max="28" id="rc_jour" value="${m.jourMois||1}"></div>
    </div>
    <div class="field"><label>À partir de (mois)</label><input type="month" id="rc_debut" value="${esc(m.debut||today().slice(0,7))}"></div>
    <label class="switch-row"><input type="checkbox" id="rc_actif" ${m.actif!==false?'checked':''}> Active (décochez pour mettre en pause)</label>
    <div class="modal-actions"><button class="btn ghost" onclick="recurringChargesForm()">Annuler</button>
      <button class="btn" onclick="recurSave(${i})">Enregistrer</button></div>`);
}
async function recurSave(i){
  const models=getRecurringCharges();
  const lib=val('rc_lib'), mt=money2(+val('rc_mt')||0);
  if(!lib){ toast('Libellé requis'); return; }
  if(mt<=0){ toast('Montant requis'); return; }
  const m={ id: (i>=0 && models[i].id) ? models[i].id : ('rc'+Date.now()),
    libelle:lib, categorie:val('rc_cat'), montant:mt,
    jourMois: Math.min(28,Math.max(1,+val('rc_jour')||1)), debut:val('rc_debut')||today().slice(0,7),
    actif: document.getElementById('rc_actif').checked };
  if(i>=0) models[i]=m; else models.push(m);
  saveRecurringCharges(models);
  const n=await materializeRecurringCharges();
  closeModal(); recurringChargesForm(); toast(`Charge récurrente enregistrée ✓${n?` · ${n} mois reporté(s)`:''}`);
}
async function recurDel(i){
  const models=getRecurringCharges();
  if(!confirm('Supprimer ce modèle ? Les charges déjà reportées dans la compta sont conservées.')) return;
  models.splice(i,1); saveRecurringCharges(models);
  recurringChargesForm(); toast('Modèle supprimé');
}
async function recurApplyNow(){
  const n=await materializeRecurringCharges();
  closeModal(); renderCompta(); toast(n?`${n} charge(s) reportée(s) ✓`:'Tout est déjà à jour ✓');
}

async function renderChargesList(){
  const charges = (await db.charges.toArray()).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  openModal(`<h3>Charges / dépenses</h3>
    <div class="flex" style="gap:6px;margin-bottom:8px"><button class="btn gold sm" onclick="chargeForm()">＋ Nouvelle charge</button>
      <button class="btn ghost sm" onclick="recurringChargesForm()">🔁 Charges récurrentes</button></div>
    ${charges.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Catégorie</th><th>Libellé</th><th>Montant</th><th></th></tr></thead>
      <tbody>${charges.map(c=>`<tr><td>${fmtDate(c.date)}</td><td>${esc(c.categorie||'—')}</td><td>${esc(c.libelle||'')}${c.recurId?' <span class="tag" style="background:#7a6a9a;color:#fff">🔁</span>':''}</td><td>${euro(c.montant)}</td>
        <td style="text-align:right"><span class="act" onclick="chargeForm(${c.id})">Modifier</span><span class="act del" onclick="delCharge(${c.id})">Suppr.</span></td></tr>`).join('')}</tbody></table></div>`
      :'<p class="note">Aucune charge enregistrée.</p>'}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}
async function chargeForm(id){
  const c = id ? await db.charges.get(id) : {};
  // [v1453] Ben : « je veux pouvoir supprimer des charges en cas d'erreur de saisie ». La
  // suppression existe déjà (delCharge, via l'écran « Voir / gérer les charges ») — mais nulle
  // part DANS cette fiche, là où on repère justement l'erreur en la relisant. On ajoute le bouton
  // ici, au bon endroit, plutôt que d'expliquer un détour par un autre écran.
  const noteRecur = c.recurId
    ? `<p class="note" style="color:#8a6d3b;margin-top:-4px">🔁 Cette charge vient d'un modèle <b>récurrent</b>. La supprimer n'efface que <b>ce mois-ci</b> — si la date de départ ou le montant du modèle est faux, corrige-le plutôt dans <a href="#" onclick="closeModal();recurringChargesForm();return false;">Charges mensuelles récurrentes</a>, sinon l'erreur reviendra chaque mois.</p>`
    : '';
  openModal(`<h3>${id?'Modifier':'Nouvelle'} charge</h3>
    <p class="note">Les charges sont les dépenses <b>hors stock</b> (assurance, hébergement, loyer, stand…). Les <b>matières premières et emballages</b> se saisissent en réception de lot, pas ici.</p>
    ${noteRecur}
    <div class="field"><label>Date *</label><input type="date" id="ch_date" value="${esc(c.date||'')}"></div>
    <div class="field"><label>Catégorie *</label><select id="ch_cat">${(c.categorie && !CHARGE_CATS.includes(c.categorie)?[c.categorie]:[]).concat(CHARGE_CATS).map(x=>`<option ${c.categorie===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div>
    <div class="field"><label>Libellé</label><input id="ch_lib" value="${esc(c.libelle||'')}" placeholder="ex : Assurance pro, hébergement site…"></div>
    <div class="field"><label>Montant (€) *</label><input type="number" step="0.01" min="0" id="ch_mt" value="${c.montant||''}"></div>
    <div class="modal-actions">
      ${id?`<button class="btn ghost" style="color:#b3261e;border-color:#e3b8b3" onclick="delCharge(${id})">🗑 Supprimer</button>`:''}
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="saveCharge(${id||0})">Enregistrer</button>
    </div>`);
}
async function saveCharge(id){
  const date=val('ch_date'), categorie=val('ch_cat'), libelle=val('ch_lib'), montant=money2(+val('ch_mt')||0);
  if(!date){ toast('Date obligatoire'); return; }
  if(montant<=0){ toast('Montant obligatoire'); return; }
  const o={date, categorie, libelle, montant};
  if(id) await db.charges.update(id,o); else await db.charges.add(o);
  closeModal(); renderCompta(); toast('Charge enregistrée ✓');
}
async function delCharge(id){
  if(!confirm('Supprimer cette charge ?')) return;
  await db.charges.delete(id); closeModal(); renderCompta(); toast('Charge supprimée');
}

