// DIAGNOSTIC : décompose le CA total des commandes par catégorie de ligne, pour comprendre
// l'écart entre le CA total (tableau de bord) et le CA ventilé par parfum (rentabilité).
function diagFlavorCAGap(orders, markets, marketMoves){
  // IMPORTANT : ce diagnostic suit EXACTEMENT la même logique que buildFlavorSales (v339+),
  // pour que les chiffres soient cohérents. Le CA est calé sur le montant réel encaissé ;
  // la part macarons va aux parfums, la part prestation reste à part.
  const TYPES_MACARON = ['coffret','evenement','vrac','grand','histo'];
  const lineParfumsOf = ln => (ln.type==='grand' ? (ln.items||[]) : (ln.parfums||[])).filter(p=>+p.qte>0);
  const cat = { total:0, ventileParfum:0, prestation:0, marches:0, marchesNonVentiles:0,
                sansParfum:0, pyramides:0 };
  const nb = { prestation:0, sansParfum:0, marchesNonVentiles:0 };
  let totalCmd=0;
  (orders||[]).forEach(o=>{
    const montant = money2(+o.montant||0);
    totalCmd += montant;
    const lignes = orderToLines(o);
    if(!lignes.length){ cat.sansParfum += montant; nb.sansParfum++; return; }
    // Valeur catalogue macarons vs prestation (même calcul que buildFlavorSales).
    let valMac=0, valPresta=0, totalPiecesMac=0;
    lignes.forEach(ln=>{
      if(ln.type==='prestation'){ valPresta += money2(lineTotalStored(ln)); }
      else if(TYPES_MACARON.includes(ln.type)){
        valMac += money2(lineTotalStored(ln));
        lineParfumsOf(ln).forEach(p=>totalPiecesMac+=+p.qte);
      }
      if(ln.type==='evenement'){ cat.pyramides += pyraTotalLigne(ln) + accessoireDecoTotal(ln); }
    });
    if(totalPiecesMac<=0){ cat.sansParfum += montant; nb.sansParfum++; return; }
    // Répartition du montant réel entre macarons (→ parfums) et prestation (→ à part).
    let caMacaron;
    if(valPresta>0 && valMac>0) caMacaron = money2(montant * valMac/(valMac+valPresta));
    else if(valPresta>0 && valMac<=0) caMacaron = 0;
    else caMacaron = montant;
    cat.ventileParfum += caMacaron;
    const partPresta = money2(montant - caMacaron);
    if(partPresta>0.005){ cat.prestation += partPresta; nb.prestation++; }
  });
  // Marchés clos.
  const movesByMk={}; (marketMoves||[]).forEach(mv=>{ (movesByMk[mv.marketId] ||= []).push(mv); });
  (markets||[]).filter(mk=>mk.statut==='clos').forEach(mk=>{
    const caMk = (typeof marketNetCA==='function') ? marketNetCA(mk) : (+mk.montant||0);
    if(caMk<=0) return;
    const mv = movesByMk[mk.id]||[];
    // Pièces réellement vendues = sorties - retours - dons - pertes (ce qui sert à ventiler).
    let vendu=0;
    mv.forEach(m=>{ const q=+m.qte||0; if(m.type==='sortie') vendu+=q; else if(m.type==='retour'||m.type==='don'||m.type==='perte') vendu-=q; });
    cat.marches += caMk;
    if(vendu>0){ /* ventilé via buildFlavorSales */ }
    else { cat.marchesNonVentiles += caMk; nb.marchesNonVentiles++; }
  });
  cat.total = money2(totalCmd + cat.marches);
  cat.totalCmd = money2(totalCmd);
  cat.totalMarches = money2(cat.marches);
  Object.keys(cat).forEach(k=>{ if(typeof cat[k]==='number') cat[k]=money2(cat[k]); });
  cat._nb = nb;
  return cat;
}
// Compte les coffrets vendus par taille (nombre + CA réel encaissé), pour l'indicateur.
function coffretsParTaille(orders){
  const map = {};   // taille -> {nb, ca, pieces}
  (orders||[]).forEach(o=>{
    orderToLines(o).forEach(ln=>{
      if(ln.type!=='coffret') return;
      const t = +ln.taille||0; if(t<=0) return;
      const m = (map[t] ||= {taille:t, nb:0, ca:0, pieces:0});
      m.nb += 1;
      m.pieces += t;
      m.ca = money2(m.ca + money2(lineTotalStored(ln)));
    });
  });
  const list = Object.values(map).sort((a,b)=>b.nb-a.nb);
  const totNb = list.reduce((s,x)=>s+x.nb,0);
  const totCA = money2(list.reduce((s,x)=>s+x.ca,0));
  return { list, totNb, totCA, best: list[0]||null };
}
// Rentabilité des GRANDS FORMATS (gros macarons à l'unité).
// Compte les ventes par produit (type 'grand'), CA réel encaissé, et marge si la recette existe.
function bigFormatStats(orders, recipes, recipeItems, lots, settings, mesureParRec, mesureGlobal){
  const recByNorm={}; (recipes||[]).forEach(r=>{ recByNorm[aiNormalize(r.produitNom)]=r; });
  const map={};   // nom -> {nom, qte, ca, recipe, coutUnit}
  (orders||[]).forEach(o=>{
    orderToLines(o).forEach(ln=>{
      if(ln.type!=='grand') return;
      const items=(ln.items||[]).filter(p=>+p.qte>0);
      const totPieces=items.reduce((s,p)=>s+(+p.qte||0),0);
      if(totPieces<=0) return;
      const caLigne=money2(lineTotalStored(ln));            // CA réel de la ligne
      const caParPiece=totPieces>0?caLigne/totPieces:0;
      items.forEach(p=>{
        const m=(map[p.nom] ||= {nom:p.nom, qte:0, ca:0, recipe:null, coutUnit:null});
        m.qte += +p.qte;
        m.ca = money2(m.ca + caParPiece*(+p.qte));
      });
    });
  });
  // Coût de revient par produit, si une recette grand format correspond.
  Object.values(map).forEach(m=>{
    const r=recByNorm[aiNormalize(m.nom)];
    if(r && r.grandFormat){
      m.recipe=r;
      try{ const _opt=(typeof _optMesureRecette==='function')?_optMesureRecette(r, settings, mesureParRec, mesureGlobal):undefined; const cr=coutRevientRecette(r, recipeItems, lots, settings, _opt); m.coutUnit=+cr.coutRevientUnit||0; }catch(e){ m.coutUnit=null; }
    }
  });
  const list=Object.values(map).map(m=>{
    const prixMoyen = m.qte>0 ? money2(m.ca/m.qte) : 0;
    const coutTot = (m.coutUnit!=null) ? money2(m.coutUnit*m.qte) : null;
    const marge = (coutTot!=null) ? money2(m.ca-coutTot) : null;
    const tauxMarge = (marge!=null && m.ca>0) ? Math.round(marge/m.ca*1000)/10 : null;
    return {...m, prixMoyen, coutTot, marge, tauxMarge};
  }).sort((a,b)=>b.qte-a.qte);
  const totQte=list.reduce((s,x)=>s+x.qte,0);
  const totCA=money2(list.reduce((s,x)=>s+x.ca,0));
  const totMarge=list.some(x=>x.marge!=null) ? money2(list.reduce((s,x)=>s+(x.marge||0),0)) : null;
  return { list, totQte, totCA, totMarge, best:list[0]||null };
}
async function renderParfums(){
  const [recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions] = await Promise.all([
    db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray(), db.materials.toArray(),
    db.orders.toArray(), db.markets.toArray(), db.marketMoves.toArray(), db.productions.toArray()
  ]);
  const s = getSettings();
  const prodConsumption = await db.prodConsumption.toArray().catch(()=>[]);   // [v1432] coût mesuré
  const data = {recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions, prodConsumption, settings:s};

  if(!recipes.length){
    document.getElementById('main').innerHTML=`
      <div class="topbar"><div><h1>Rentabilité parfums</h1><p>Coûts de revient & marges par parfum</p></div></div>
      <div class="panel"><div class="empty">Aucune recette. Créez vos recettes (BOM) — chaque recette correspond à un parfum — puis réceptionnez des lots avec prix pour activer l'analyse.</div></div>`;
    return;
  }

  const A = analyzeFlavorProfitability(data);
  _parfumsA = A;   // mémorisé pour les popups détaillés (marges, prix moyen, stock)
  const hikes = flavorCostHikeAlerts(data, A);
  const recs = flavorRecommendations(A, data);

  // [v1432] D'OÙ VIENT CHAQUE COÛT — bandeau d'honnêteté. Sans lui, la correction serait invisible
  // et Ben lirait des marges estimées comme des marges mesurées. Le CA dont le coût est inconnu est
  // chiffré : c'est la part du classement sur laquelle il ne faut RIEN conclure.
  const _T = A.totals || {};
  const _srcParts = [];
  if(_T.nbCoutMesure>0)  _srcParts.push(`<b>${_T.nbCoutMesure}</b> mesuré${_T.nbCoutMesure>1?'s':''} sur tes batchs réels`);
  if(_T.nbCoutRecette>0) _srcParts.push(`<b>${_T.nbCoutRecette}</b> d'après la recette`);
  if(_T.nbCoutAtelier>0) _srcParts.push(`<b>${_T.nbCoutAtelier}</b> estimé${_T.nbCoutAtelier>1?'s':''} (médiane atelier ${euro(_T.medianeCoutMatiereAtelier||0)}/pc de matière)`);
  const _coutBandeau = (_srcParts.length || _T.nbCoutInconnu>0) ? `
    <div class="panel" style="background:#fbf9f4;border-color:#e0d6c4">
      <h2 style="font-size:.98rem">🏷️ D'où vient le coût de chaque parfum</h2>
      ${_srcParts.length?`<p class="note" style="margin:0 0 4px">${_srcParts.join(' · ')}.</p>`:''}
      ${_T.nbCoutInconnu>0?`<p class="note" style="margin:0;color:#b3261e">⚠ <b>${_T.nbCoutInconnu}</b> parfum(s) sans coût connu — ${euro(_T.caSansCout||0)} de CA <b>exclu</b> des marges ci-dessous. Un coût nul afficherait 100 % de marge : mieux vaut un blanc qu'un chiffre faux. Renseigne les ingrédients de ces recettes, ou produis-en un batch réel.</p>`:''}
      <p class="note" style="margin:4px 0 0;font-size:.74rem">Un lot de <b>reprise</b> ne consomme aucune matière : il ne peut pas servir de mesure. Le coût est alors pris sur la recette, sinon estimé à la médiane de l'atelier — et signalé comme tel sur chaque ligne.</p>
    </div>` : '';

  // tri
  const rows=[...A.rows];
  const sorters={
    marge:(a,b)=>(b.margeBrute==null?-Infinity:b.margeBrute)-(a.margeBrute==null?-Infinity:a.margeBrute),   // [v1432] coût inconnu → en bas
    ca:(a,b)=>b.ca-a.ca,
    pieces:(a,b)=>b.piecesVendues-a.piecesVendues,
    taux:(a,b)=>(b.tauxMarge==null?-1:b.tauxMarge)-(a.tauxMarge==null?-1:a.tauxMarge),
    stock:(a,b)=>(b.valStockCout||0)-(a.valStockCout||0),
    nom:(a,b)=>a.nom.localeCompare(b.nom)
  };
  rows.sort(sorters[_parfumSort]||sorters.marge);

  // Pareto 80/20 (sur marge brute, parfums vendus uniquement)
  const sold=A.rows.filter(r=>r.piecesVendues>0 && r.margeBrute>0).sort((a,b)=>b.margeBrute-a.margeBrute);
  const totMargeSold=sold.reduce((s2,r)=>s2+r.margeBrute,0);
  let cum=0; const pareto=[]; let seuil80=null;
  sold.forEach((r,i)=>{ cum+=r.margeBrute; const pct=totMargeSold>0?cum/totMargeSold*100:0; pareto.push({...r, cumPct:pct}); if(seuil80===null && pct>=80) seuil80=i+1; });

  // classements
  const best=A.rows.filter(r=>r.tauxMarge!=null).sort((a,b)=>b.tauxMarge-a.tauxMarge).slice(0,5);
  const worst=A.rows.filter(r=>r.tauxMarge!=null).sort((a,b)=>a.tauxMarge-b.tauxMarge).slice(0,5);

  // KPI
  const avgP = computeAvgSellPrice(data);
  _parfumsAvgP = avgP;
  // Indicateur : rentabilité des grands formats (gros macarons).
  const _moBF = await _chargeMesuresMO(s);
  const bf = bigFormatStats(orders, recipes, recipeItems, lots, s, _moBF.mesureParRec, _moBF.mesureGlobal);
  const bigBox = bf.totQte>0 ? `<div class="panel" style="margin-bottom:12px">
    <h2>🍪 Rentabilité grands formats</h2>
    ${bf.best?`<div class="banner" style="background:#f6f1e8;border-color:#8a6d3b;margin:4px 0 10px"><div>🏆 Le plus vendu : <b>${esc(bf.best.nom)}</b> — ${bf.best.qte} vendu${bf.best.qte>1?'s':''} (${euro(bf.best.ca)})</div></div>`:''}
    <table style="width:100%;border-collapse:collapse;font-size:.88rem">
      <thead><tr style="text-align:left;color:#9a8a82;font-size:.78rem">
        <th style="padding:4px 5px">Produit</th><th style="padding:4px 5px;text-align:right">Vendus</th><th style="padding:4px 5px;text-align:right">CA</th><th style="padding:4px 5px;text-align:right">Marge</th></tr></thead>
      <tbody>
        ${bf.list.map(b=>`<tr style="border-top:1px solid var(--hair)">
          <td style="padding:6px 5px"><b>${esc(b.nom)}</b>${b.coutUnit==null?`<br><button class="btn ghost" style="font-size:.7rem;padding:2px 8px;margin-top:3px" onclick="recForm(null,{nom:${JSON.stringify(b.nom).replace(/"/g,'&quot;')},grandFormat:true})">+ créer la recette</button>`:''}</td>
          <td style="padding:6px 5px;text-align:right">${b.qte}</td>
          <td style="padding:6px 5px;text-align:right">${euro(b.ca)}</td>
          <td style="padding:6px 5px;text-align:right">${b.marge!=null?`<b style="color:#3f7d52">${euro(b.marge)}</b>${b.tauxMarge!=null?`<br><span style="font-size:.72rem;color:#9a8a82">${b.tauxMarge}%</span>`:''}`:'<span style="color:#c9bfb5">—</span>'}</td></tr>`).join('')}
      </tbody>
      <tfoot><tr style="border-top:2px solid var(--bordeaux);font-weight:600">
        <td style="padding:6px 5px">Total</td><td style="padding:6px 5px;text-align:right">${bf.totQte}</td>
        <td style="padding:6px 5px;text-align:right">${euro(bf.totCA)}</td>
        <td style="padding:6px 5px;text-align:right">${bf.totMarge!=null?euro(bf.totMarge):'—'}</td></tr></tfoot>
    </table>
    ${bf.list.some(b=>b.coutUnit==null)?`<p class="note" style="margin-top:6px;color:#b08a3a">Certaines marges sont indisponibles : crée la recette grand format correspondante (même nom) pour calculer le coût et la marge.</p>`:'<p class="note" style="margin-top:6px">Vendus à l\'unité. Marge = CA réel − coût de revient de la recette.</p>'}
  </div>` : '';
  // Indicateur : coffrets vendus par taille (nombre + CA, meilleur format mis en avant).
  const cof = coffretsParTaille(orders);
  const coffretsBox = cof.totNb>0 ? `<div class="panel" style="margin-bottom:12px">
    <h2>📦 Coffrets vendus par taille</h2>
    ${cof.best?`<div class="banner" style="background:#eef6ef;border-color:#3f7d52;margin:4px 0 10px"><div>🏆 Format le plus vendu : <b>coffret ${cof.best.taille}</b> — ${cof.best.nb} vendu${cof.best.nb>1?'s':''} (${euro(cof.best.ca)})</div></div>`:''}
    <table style="width:100%;border-collapse:collapse;font-size:.9rem">
      <thead><tr style="text-align:left;color:#9a8a82;font-size:.8rem">
        <th style="padding:4px 6px">Format</th><th style="padding:4px 6px;text-align:right">Vendus</th><th style="padding:4px 6px;text-align:right">CA</th><th style="padding:4px 6px;text-align:right">Part</th></tr></thead>
      <tbody>
        ${cof.list.map(c=>`<tr style="border-top:1px solid var(--hair)">
          <td style="padding:6px"><b>Coffret ${c.taille}</b></td>
          <td style="padding:6px;text-align:right">${c.nb}</td>
          <td style="padding:6px;text-align:right">${euro(c.ca)}</td>
          <td style="padding:6px;text-align:right;color:#9a8a82">${cof.totNb>0?Math.round(c.nb/cof.totNb*100):0}%</td></tr>`).join('')}
      </tbody>
      <tfoot><tr style="border-top:2px solid var(--bordeaux);font-weight:600">
        <td style="padding:6px">Total</td><td style="padding:6px;text-align:right">${cof.totNb}</td>
        <td style="padding:6px;text-align:right">${euro(cof.totCA)}</td><td></td></tr></tfoot>
    </table>
    <p class="note" style="margin-top:6px">Coffrets des commandes. Le « format le plus vendu » est classé par nombre de coffrets.</p>
  </div>` : '';
  // Diagnostic de l'écart entre le CA total (toutes commandes) et le CA ventilé par parfum.
  const gap = diagFlavorCAGap(orders, markets, marketMoves);
  const caVentile = A.totals.ca;
  // Écart résiduel = ce que le total ne couvre pas via les catégories connues (pertes, remises, arrondi).
  const expliqué = money2(caVentile + gap.prestation + gap.marchesNonVentiles + gap.sansParfum);
  const residuel = money2(gap.total - expliqué);
  const diagBox = `<details style="margin-bottom:12px"><summary style="cursor:pointer;color:#7a6a62;font-size:.84rem;font-weight:600">🔎 Où va le CA total ?</summary>
    <div class="panel" style="margin-top:8px;font-size:.86rem">
      <div style="display:flex;justify-content:space-between;padding:3px 0"><span>CA total (commandes + marchés)</span><b>${euro(gap.total)}</b></div>
      <div style="display:flex;justify-content:space-between;padding:1px 0;font-size:.78rem;color:#9a8a82"><span>&nbsp;&nbsp;· dont commandes</span><span>${euro(gap.totalCmd)}</span></div>
      <div style="display:flex;justify-content:space-between;padding:1px 0;font-size:.78rem;color:#9a8a82"><span>&nbsp;&nbsp;· dont marchés</span><span>${euro(gap.totalMarches)}</span></div>
      <div style="border-top:1px solid var(--hair);margin:6px 0"></div>
      <div style="display:flex;justify-content:space-between;padding:3px 0;color:#3f7d52"><span>✓ Ventilé sur les parfums</span><b>${euro(caVentile)}</b></div>
      <div style="display:flex;justify-content:space-between;padding:1px 0;font-size:.78rem;color:#9a8a82"><span>&nbsp;&nbsp;· dont commandes</span><span>${euro(A.totals.caCmdVentile||0)}</span></div>
      <div style="display:flex;justify-content:space-between;padding:1px 0;font-size:.78rem;color:#9a8a82"><span>&nbsp;&nbsp;· dont marchés</span><span>${euro(A.totals.caMarcheVentile||0)}</span></div>
      ${gap.pyramides>0?`<div style="display:flex;justify-content:space-between;padding:2px 0;color:#7a4b82;font-size:.82rem"><span>&nbsp;&nbsp;dont pyramides redistribuées</span><b>${euro(gap.pyramides)} (${caVentile>0?Math.round(gap.pyramides/caVentile*100):0}%)</b></div>`:''}
      ${gap.prestation>0?`<div style="display:flex;justify-content:space-between;padding:3px 0;color:#7a6a62"><span>↔ Prestations / services (à part, ${gap._nb.prestation})</span><b>${euro(gap.prestation)}</b></div>`:''}
      ${gap.marchesNonVentiles>0?`<div style="display:flex;justify-content:space-between;padding:3px 0;color:#b3261e"><span>⚠ Marchés sans détail de ventes (${gap._nb.marchesNonVentiles})</span><b>${euro(gap.marchesNonVentiles)}</b></div>`:''}
      ${gap.sansParfum>0?`<div style="display:flex;justify-content:space-between;padding:3px 0"><span>Commandes sans parfum (${gap._nb.sansParfum})</span><b>${euro(gap.sansParfum)}</b></div>`:''}
      ${Math.abs(residuel)>0.5?`<div style="display:flex;justify-content:space-between;padding:3px 0;color:#9a8a82"><span>Écart résiduel (pertes, remises, arrondis)</span><b>${euro(residuel)}</b></div>`:''}
      <div style="border-top:1px solid var(--hair);margin:6px 0"></div>
      <p class="note" style="color:#9a8a82">Le « ventilé sur les parfums » inclut désormais tes commandes (coffrets, événements, vrac, grands formats et migrées) au montant réellement encaissé. Seules les prestations et les marchés non détaillés restent hors du CA par parfum.</p>
      ${gap.marchesNonVentiles>0?`<p class="note" style="color:#b3261e;margin-top:6px">⚠ ${euro(gap.marchesNonVentiles)} de CA sur ${gap._nb.marchesNonVentiles} marché(s) ne sont pas répartis par parfum : il manque le détail des ventes (sorties − retours par parfum). Pour les ventiler, édite ces marchés et renseigne ce que tu as emporté et rapporté pour chaque parfum.</p>`:''}
    </div></details>`;
  const kpis=`<div class="kpi-grid">
    <div class="kpi"><span>CA encaissé (parfums) ${kpiI('ca_encaisse')}</span><b>${euro(A.totals.ca)}</b><span>${qty(A.totals.pieces)} pièces vendues</span></div>
    <div class="kpi lnk" onclick="parfumMargesPopup(false)"><span>Marge brute totale ${INFO_I}</span><b style="color:${A.totals.margeBrute>=0?'#3f7d52':'#b3261e'}">${euro(A.totals.margeBrute)}</b><span>${A.totals.tauxMargeGlobal!=null?A.totals.tauxMargeGlobal+'% de marge':'—'}</span></div>
    <div class="kpi lnk" onclick="parfumMargesPopup(true)"><span>Marge nette estimée ${INFO_I}</span><b style="color:${A.totals.margeNette>=0?'#3f7d52':'#b3261e'}">${euro(A.totals.margeNette)}</b><span>après charges ${s.socialGoods}%</span></div>
    <div class="kpi lnk" onclick="parfumPrixMoyenPopup()"><span>Prix moyen pondéré ${INFO_I}</span><b>${euro(avgP.prix)}</b><span>${avgP.source==='ventes'?'d\'après les ventes':'grille (pas de vente)'}</span></div>
    <div class="kpi lnk" onclick="parfumStockPopup()"><span>Stock immobilisé ${INFO_I}</span><b>${euro(A.totals.valStock)}</b><span>au coût de revient</span></div>
  </div>`;

  // bannière d'incohérence CA : encaissé vs attendu (pièces × prix moyen)
  const ecT=A.totals.ecartTheo, theoT=A.totals.caTheo;
  const incohBanner = (theoT>0 && Math.abs(ecT)>=Math.max(5, theoT*0.05))
    ? `<div class="banner" style="background:${ecT<0?'#fdf3f2':'#fff8ec'};border-color:${ecT<0?'#e5b4ae':'#e8cfa0'}">🔎 <div><b>Écart CA encaissé vs attendu : ${ecT>0?'+':''}${euro(ecT)}</b> (encaissé ${euro(A.totals.ca)} · attendu ${euro(theoT)} au prix moyen ${euro(avgP.prix)}). ${ecT<0?'L\'encaissé est sous l\'attendu : pertes/dons non saisis, remises, ou erreur de caisse.':'Ventes au-dessus du tarif moyen, ou grille de prix à réajuster.'}</div></div>`
    : '';

  // alertes hausse de coût
  const hikeBanner = hikes.length?`<div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">📈 <div><b>Hausse de coût matière détectée</b> : ${hikes.slice(0,4).map(h=>`${esc(h.mat)} +${h.varPct}% (impacte ${h.parfums.map(esc).join(', ')})`).join(' · ')}${hikes.length>4?` … +${hikes.length-4}`:''}. Vérifiez les prix de vente des parfums concernés.</div></div>`:'';

  // tableau principal
  const sortBtn=(k,lib)=>`<button class="btn ghost sm" style="${_parfumSort===k?'border-color:var(--caramel);font-weight:600':''}" onclick="_parfumSort='${k}';renderParfums()">${lib}</button>`;
  // [v1432] Marqueur d'origine du coût, sur CHAQUE ligne. Un coût estimé qui ressemble à un coût
  // mesuré est précisément ce qui faisait mentir l'écran.
  const _srcTag = r => {
    if(r.coutSource==='mesure')  return `<span class="tag" style="background:#e7f0e9;color:#3f6b45;font-size:.62rem" title="Coût matière calculé sur ${r.coutNbBatchs} batch(s) réellement produits">✓ mesuré</span>`;
    if(r.coutSource==='recette') return `<span class="tag" style="background:#eef1f6;color:#4a5b74;font-size:.62rem" title="Coût calculé d'après les ingrédients de la recette">recette</span>`;
    if(r.coutSource==='atelier') return `<span class="tag" style="background:#fbf0e0;color:#8a6d3b;font-size:.62rem" title="Aucune donnée propre à ce parfum : estimation à la médiane de l'atelier">≈ estimé</span>`;
    return `<span class="tag" style="background:#f6e3e0;color:#b3261e;font-size:.62rem" title="Aucun coût connu : les marges de cette ligne ne sont pas calculées">coût inconnu</span>`;
  };
  const mainTable=`<div style="display:flex;flex-direction:column;gap:10px">${rows.map(r=>{
      const taux=r.tauxMarge;
      const tauxClamp=taux!=null?Math.max(0,Math.min(100,taux)):0;
      const col=(typeof flavorColor==='function')?flavorColor(r.nom):'#ccc';
      return `<div onclick="parfumDetail(${r.recipeId})" style="cursor:pointer;background:#fff;border:1px solid var(--hair);border-left:4px solid ${r.scale.col};border-radius:14px;padding:13px 15px;box-shadow:var(--sh-1)">
        <div style="display:flex;align-items:center;gap:9px;margin-bottom:10px">
          <span style="width:20px;height:20px;border-radius:50%;background:${col};flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08)"></span>
          <b style="flex:1;font-size:1rem;color:var(--bordeaux);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(r.nom)}${r.cost.pertePct>0?` <span style="color:#9a8a82;font-size:.7rem;font-weight:400">· pertes ${r.cost.pertePct}%</span>`:''}</b>
          ${_srcTag(r)}
          <span class="tag" style="background:${r.scale.col};color:#fff;font-size:.66rem">${r.scale.dot} ${r.scale.label||''}</span>
        </div>
        <div style="display:flex;gap:6px;text-align:center;margin-bottom:10px">
          <div style="flex:1"><div style="font-size:.6rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Coût/pc</div><div style="font-weight:700;color:var(--bordeaux);font-size:.88rem">${r.coutUnitRetenu!=null?euro(r.coutUnitRetenu):'—'}</div></div>
          <div style="flex:1;border-left:1px solid var(--hair)"><div style="font-size:.6rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Vente/pc</div><div style="font-weight:700;color:var(--bordeaux);font-size:.88rem">${r.prixVenteMoyen!=null?euro(r.prixVenteMoyen):'—'}</div></div>
          <div style="flex:1;border-left:1px solid var(--hair)"><div style="font-size:.6rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Vendus</div><div style="font-weight:700;color:var(--bordeaux);font-size:.88rem">${r.piecesVendues>0?qty(r.piecesVendues):'0'}</div></div>
          <div style="flex:1;border-left:1px solid var(--hair)"><div style="font-size:.6rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Marge brute</div><div style="font-weight:700;font-size:.88rem;color:${r.margeBrute==null?'#9a8a82':(r.margeBrute>=0?'#3f7d52':'#b3261e')}">${r.margeBrute!=null?euro(r.margeBrute):'—'}</div></div>
        </div>
        <div style="display:flex;align-items:center;gap:8px">
          <span style="font-size:.66rem;color:#9a8a82;flex:none">taux net</span>
          <div style="flex:1;height:8px;background:#f0e9de;border-radius:5px;overflow:hidden"><div style="width:${tauxClamp}%;height:100%;background:${r.scale.col}"></div></div>
          <span style="font-size:.78rem;font-weight:700;color:${r.scale.col};flex:none">${taux!=null?taux+'%':'—'}</span>
        </div>
      </div>`;
    }).join('')}</div>
    <p class="note">Touchez une carte pour le détail (coque/garniture, simulation de prix, seuil de rentabilité). Base de calcul = <b>CA encaissé</b> réel (commandes + marchés), réparti par parfum selon les pièces vendues. Coût de revient = matières (prix courant) + pertes + consommables${s.laborEnabled?' + main-d\'œuvre':''}.</p>`;

  // parfums sans recette (vendus mais non rattachés)
  const unmatchedBlock=A.unmatched.length?`<div class="panel"><h2>Parfums vendus sans recette <span class="tag warn">${A.unmatched.length}</span></h2>
     <p class="note">Ces parfums apparaissent dans les ventes mais n'ont pas de recette correspondante — impossible de calculer leur coût/marge. <b>Touche un parfum pour créer sa recette</b> (le nom est pré-rempli) :</p>
     <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px">
       ${A.unmatched.map(u=>`<button class="btn ghost sm" onclick="recForm(null,{nom:${JSON.stringify(u.nom).replace(/"/g,'&quot;')}})">+ ${esc(u.nom)} <span style="color:#9a8a82">(${qty(u.piecesVendues+u.piecesDon)} pc)</span></button>`).join('')}
     </div>
     <button class="btn ghost sm" style="margin-top:10px" onclick="fixFlavorTypos()">🔤 Corriger les doublons d'orthographe</button>
     <p class="note" style="margin-top:4px;font-size:.78rem;color:#9a8a82">Certains de ces noms sont peut-être de simples fautes de frappe (ex : Raffaello vs Rafaello). Ce bouton les uniformise sur tes parfums officiels.</p></div>`:'';

  // Pareto
  const paretoBlock = sold.length?`<div class="panel"><h2>Analyse Pareto 80/20</h2>
     ${seuil80?`<div class="banner"><div><b>${seuil80} parfum(s)</b> sur ${sold.length} génèrent <b>80%</b> de votre marge brute. Concentrez vos efforts (appro, mise en avant, production) sur eux.</div></div>`:''}
     <div class="table-wrap"><table><thead><tr><th>#</th><th>Parfum</th><th>Marge brute</th><th>% cumulé</th></tr></thead><tbody>
       ${pareto.map((r,i)=>`<tr${seuil80&&i<seuil80?' style="background:#f3f8f4"':''}><td>${i+1}</td><td><b>${esc(r.nom)}</b></td><td>${euro(r.margeBrute)}</td>
         <td><span class="tag ${r.cumPct<=80?'ok':''}">${r.cumPct.toFixed(0)}%</span></td></tr>`).join('')}
     </tbody></table></div></div>`:'';

  // classements
  const rankBlock=`<div class="panel"><h2>Classement par rentabilité</h2>
     <div class="row2">
       <div><h3 style="font-size:.92rem;margin:6px 0;color:#3f7d52">🟢 Les plus rentables</h3>
         ${best.length?best.map(r=>`<div class="sum-box"><span>${esc(r.nom)}</span><b style="color:#3f7d52">${r.tauxMarge}% · ${euro(r.margeUnit||0)}/pc</b></div>`).join(''):'<p class="note">—</p>'}</div>
       <div><h3 style="font-size:.92rem;margin:6px 0;color:#b3261e">🔴 Les moins rentables</h3>
         ${worst.length?worst.map(r=>`<div class="sum-box"><span>${esc(r.nom)}</span><b style="color:${r.tauxMarge<0?'#b3261e':'#d98324'}">${r.tauxMarge}% · ${euro(r.margeUnit||0)}/pc</b></div>`).join(''):'<p class="note">—</p>'}</div>
     </div></div>`;

  // recommandations
  const recBlock=`<div class="panel"><h2>Recommandations intelligentes</h2>
     ${recs.map(r=>`<div class="sum-box" style="align-items:flex-start"><span style="font-size:1.1rem">${r.icon}</span><b style="font-weight:500;color:${r.col};text-align:left;flex:1;margin-left:8px">${r.txt}</b></div>`).join('')}</div>`;

  // CONSEIL MARGE PAR PARFUM — panneau honnête (confiance + procureur). Interprète A, ne recalcule rien.
  const cm = conseilMargeParfum(A, s, data);
  const confDot = c => c.niveau==='solide'?'🟢':(c.niveau==='correcte'?'🟠':(c.niveau==='mince'?'🔴':'⚪'));
  const conseilBlock=`<div class="panel" style="border-left:4px solid #7b1e2b">
     <h2 style="color:#7b1e2b">⚖️ Conseil marge — parfums sous-margés</h2>
     <div class="banner" style="background:#faf4f4;border-color:#e0c4c4;margin:2px 0 10px"><div>${esc(cm.synthese)}</div></div>
     ${cm.sousMarges.map(x=>`<div class="sum-box" style="flex-direction:column;align-items:stretch;gap:6px">
        <div style="display:flex;align-items:center;gap:8px">
          <b style="flex:1;color:${x.tauxMarge<0?'#b3261e':(x.ferme?'#7b1e2b':'#d98324')}">${confDot(x.confiance)} ${esc(x.nom)} — marge ${x.tauxMarge}%${x.ferme?' · <span style="color:#2e7d32">action fondée</span>':(x.tauxMarge<0?'':' · <span style="color:#9a8a82">à confirmer</span>')}</b>
        </div>
        <div style="font-size:.86rem;color:#4a3f3a;text-align:left">${esc(x.action)}</div>
        ${x.procureur.length?`<details style="font-size:.8rem;color:#7a6a62"><summary style="cursor:pointer;color:#a8841f">🔍 Le procureur (${x.procureur.length} objection${x.procureur.length>1?'s':''})</summary><ul style="margin:4px 0 0 16px;padding:0">${x.procureur.map(o=>`<li style="margin:2px 0">${esc(o)}</li>`).join('')}</ul></details>`:''}
      </div>`).join('')}
     <div style="margin-top:10px;padding:8px 10px;background:#f6f2ea;border-radius:8px;font-size:.82rem;color:#6a5a52">
       <b>Ce que ce conseil ignore volontairement :</b>
       <ul style="margin:4px 0 0 16px;padding:0">${cm.ignore.map(i=>`<li style="margin:2px 0">${esc(i)}</li>`).join('')}</ul>
     </div>
   </div>`;

  // évolution de la rentabilité dans le temps (marge brute mensuelle, par CA - coût des ventes)
  const evolBlock = await buildFlavorEvolutionBlock(data, A);

  // outils de prévision
  const prevBlock=`<div class="panel"><h2>Prévisions & aide à la décision</h2>
     <div class="flex" style="gap:8px;flex-wrap:wrap">
       <button class="btn ghost sm" onclick="parfumBatchSim()">🧮 Marge prévisionnelle d'un batch</button>
       <button class="btn ghost sm" onclick="parfumMixOptim()">🎯 Mix de parfums optimal</button>
       <button class="btn ghost sm" onclick="parfumMarketGain()">⛺ Gain estimé d'un marché</button>
     </div>
     <p class="note">Calculs basés sur vos coûts de revient et l'historique de vente. Aucune donnée ne quitte l'appareil.</p></div>`;

  document.getElementById('main').innerHTML=`
   <div class="topbar"><div><h1>Rentabilité parfums</h1><p>Coûts de revient, marges & recommandations par parfum</p></div>
     <button class="btn ghost sm" onclick="parfumSettingsForm()">⚙ Coûts & MO</button></div>
   ${hikeBanner}
   ${incohBanner}
   ${_coutBandeau}
   ${diagBox}
   ${kpis}
   ${coffretsBox}
   ${bigBox}
   <div class="panel"><h2>Synthèse par parfum</h2>
     <div class="flex" style="gap:6px;flex-wrap:wrap;margin-bottom:8px"><span style="font-size:.8rem;color:#9a8a82;align-self:center">Trier :</span>
       ${sortBtn('marge','Marge')} ${sortBtn('ca','CA')} ${sortBtn('pieces','Volume')} ${sortBtn('taux','Taux')} ${sortBtn('stock','Stock')} ${sortBtn('nom','A→Z')}</div>
     ${mainTable}</div>
   ${unmatchedBlock}
   ${conseilBlock}
   ${recBlock}
   ${paretoBlock}
   ${rankBlock}
   ${evolBlock}
   ${prevBlock}`;

  // dessine la courbe d'évolution si présente
  drawFlavorEvolutionChart(data, A);
}

// Bloc HTML pour l'évolution mensuelle de la marge (placeholder de conteneur).
async function buildFlavorEvolutionBlock(data, A){
  return `<div class="panel"><h2>Évolution de la rentabilité <span style="font-weight:400;font-size:.8rem;color:#9a8a82">— marge brute mensuelle</span></h2>
     <div id="flavorEvolChart"></div>
     <p class="note">CA mensuel (commandes + marchés clos) − coût de revient des pièces vendues le mois.</p></div>`;
}

// Calcule et dessine la courbe d'évolution (CA, coût, marge) par mois.
function drawFlavorEvolutionChart(data, A){
  const el=document.getElementById('flavorEvolChart'); if(!el) return;
  const {recipes, recipeItems, lots, orders, markets, marketMoves, productions, settings}=data;
  const s=settings||getSettings();
  const costByRecipe=A.costByRecipe;
  const units=Object.values(costByRecipe).map(c=>c.coutRevientUnit).filter(x=>x>0);
  const avgUnit=units.length?units.reduce((a,b)=>a+b,0)/units.length:0;
  // retrouver la recette d'un parfum/mouvement
  const recByNorm={}; recipes.forEach(r=>{recByNorm[aiNormalize(r.produitNom)]=r;});
  const prodById={}; (productions||[]).forEach(p=>{prodById[p.id]=p;});
  const recName=rid=>(recipes.find(r=>r.id===rid)||{}).produitNom||'';
  const unitCostForParfum=nom=>{ const r=recByNorm[aiNormalize(nom)]; return r&&costByRecipe[r.id]?costByRecipe[r.id].coutRevientUnit:avgUnit; };
  const moveParfum=m=>{ if(m.parfum) return m.parfum; if(m.productionId!=null && prodById[m.productionId]) return recName(prodById[m.productionId].recipeId)||''; return ''; };

  // pièces vendues par mois + CA par mois (commandes)
  const caByMonth={}, coutByMonth={};
  (orders||[]).forEach(o=>{
    const k=ymKey(o.date); if(!k) return;
    caByMonth[k]=money2((caByMonth[k]||0)+(+o.montant||0));
    // pièces de la commande × coût moyen (approche globale mensuelle)
    const lignes=orderToLines(o);
    let pieces=0;
    lignes.forEach(ln=>{
      if(ln.type==='coffret') pieces+=+ln.taille||0;
      else if(ln.type==='don') pieces+=(ln.parfums||[]).reduce((a,p)=>a+(+p.qte||0),0);
      else if(ln.type==='evenement') pieces+=+ln.evQte||0;
      else if(ln.type==='grand') pieces+=(ln.items||[]).reduce((a,p)=>a+(+p.qte||0),0);
      // [v1452] Sachet compté ici comme les autres pièces vendues. Le vrac l'était déjà, mais par
      // omission : il manquait à cette liste — même forme (parfums + sansParfum), même traitement.
      else if(ln.type==='vrac'||ln.type==='sachet') pieces+=(ln.parfums||[]).reduce((a,p)=>a+(+p.qte||0),0) + (+ln.sansParfum||0);
    });
    coutByMonth[k]=money2((coutByMonth[k]||0)+pieces*avgUnit);
  });
  // marchés clos : CA = ENCAISSÉ (base de calcul) ; coût = pièces × coût DU PARFUM
  const movesByMk={}; (marketMoves||[]).forEach(mv=>{(movesByMk[mv.marketId] ||= []).push(mv);});
  (markets||[]).filter(mk=>mk.statut==='clos').forEach(mk=>{
    const k=ymKey(mk.date); if(!k) return;
    const ca=mk.ca||{}; caByMonth[k]=money2((caByMonth[k]||0)+marketNetCA(mk));
    const mv=movesByMk[mk.id]||[];
    const byParfum={};
    mv.forEach(m=>{ const nom=moveParfum(m)||'(parfum ?)'; const b=(byParfum[nom] ||= {sortie:0,retour:0,don:0,perte:0});
      if(m.type==='sortie')b.sortie+=+m.qte||0; else if(m.type==='retour')b.retour+=+m.qte||0; else if(m.type==='don')b.don+=+m.qte||0; else if(m.type==='perte')b.perte+=+m.qte||0; });
    let coutMk=0;
    Object.keys(byParfum).forEach(nom=>{ const b=byParfum[nom]; const v=Math.max(0,b.sortie-b.retour-b.don-b.perte); if(v<=0) return;
      coutMk=money2(coutMk+v*unitCostForParfum(nom)); });
    coutByMonth[k]=money2((coutByMonth[k]||0)+coutMk);
  });
  const keys=[...new Set([...Object.keys(caByMonth),...Object.keys(coutByMonth)])].sort().slice(-12);
  if(!keys.length){ el.innerHTML='<div class="empty">Pas encore de ventes datées pour tracer la courbe.</div>'; return; }
  const sCA={label:'CA', color:'#3f7d52', points:keys.map(k=>({x:k,y:caByMonth[k]||0}))};
  const sCout={label:'Coût de revient', color:'#b04a3e', points:keys.map(k=>({x:k,y:coutByMonth[k]||0}))};
  const sMarge={label:'Marge brute', color:'#AA7C39', points:keys.map(k=>({x:k,y:money2((caByMonth[k]||0)-(coutByMonth[k]||0))}))};
  el.innerHTML=lineChart([sCA,sCout,sMarge],{fmt:v=>euro(v),xlabel:ymLabel,zero:true});
}

// DÉTAIL d'un parfum : ventilation coque/garniture, coût détaillé, simulation de prix, seuil de rentabilité.
// Barre décomposée propre à la rentabilité par parfum : à partir du prix de vente,
// montre visuellement la part de chaque coût (matières, main-d'œuvre, charges) et la marge restante.
function parfumMargeBar(row, c){
  if(privacyModeEnabled()) return '';
  const prix = row.prixVenteMoyen;
  if(prix==null || prix<=0) return ''; // pas de vente → pas de décomposition pertinente
  const mat = (c.coutMatUnit||0) + (c.coutConsoUnit||0); // matières + consommables
  const mo  = c.coutMODUnit||0;                           // main-d'œuvre
  const charges = row.chargesSoc!=null ? row.chargesSoc : 0; // charges sociales / pièce
  // [FIX v1322 — LES PERTES ÉTAIENT CACHÉES] AVANT : `Math.max(0, prix - mat - mo - charges)`.
  // Un parfum vendu À PERTE affichait une marge de 0 € au lieu de son déficit réel. Pire, le filtre
  // `.filter(s=>s.v>0)` plus bas faisait alors DISPARAÎTRE le segment « Marge nette » de la barre ET
  // de la légende : la barre se remplissait de coûts, sans le moindre signal de perte. C'est l'exact
  // contraire de ce que doit faire un outil de pilotage — et le risque est réel maintenant que le
  // coût de la main-d'œuvre est correctement compté (v1319) : des parfums peuvent basculer en déficit.
  const margeReelle = money2(prix - mat - mo - charges);   // peut être NÉGATIVE : on l'assume
  const enPerte = margeReelle < 0;
  const coutTotal = money2(mat + mo + charges);
  const marge = Math.max(0, margeReelle);
  const segs=[
    {lbl:'Matières', v:mat, col:'#b3261e'},
    {lbl:'Main-d\'œuvre', v:mo, col:'#d98324'},
    {lbl:'Charges', v:charges, col:'#c9a227'},
    {lbl:'Marge nette', v:marge, col:'#3f7d52'}
  ].filter(s=>s.v>0);
  const pct=v=> prix>0 ? Math.round(v/prix*100) : 0;
  // [v1322] En cas de perte, les coûts dépassent 100 % du prix. On rapporte donc les largeurs au
  // COÛT TOTAL (et non au prix) pour que la barre reste lisible, et on matérialise le dépassement.
  const base = enPerte ? coutTotal : prix;
  const barre2 = segs.map(s=>`<div style="width:${Math.max(2,s.v/base*100)}%;background:${s.col}" title="${s.lbl} : ${euro(s.v)}"></div>`).join('')
    + (enPerte ? `<div style="width:${Math.max(2, Math.abs(margeReelle)/base*100)}%;background:repeating-linear-gradient(45deg,#b3261e,#b3261e 4px,#8c1d17 4px,#8c1d17 8px)" title="Perte : ${euro(margeReelle)}"></div>` : '');
  const legende = segs.map(s=>`<span style="display:inline-flex;align-items:center;gap:4px;font-size:.72rem;color:#6a5a52">
      <span style="width:10px;height:10px;border-radius:2px;background:${s.col};display:inline-block"></span>${s.lbl} ${euro(s.v)} <span style="color:#9a8a82">(${pct(s.v)}%)</span></span>`).join('')
    + (enPerte ? `<span style="display:inline-flex;align-items:center;gap:4px;font-size:.72rem;color:#b3261e;font-weight:700">
      <span style="width:10px;height:10px;border-radius:2px;background:#b3261e;display:inline-block"></span>Perte ${euro(margeReelle)} <span style="color:#9a8a82;font-weight:400">(${pct(Math.abs(margeReelle))}%)</span></span>` : '');
  return `<div style="background:${enPerte?'#fdf5f4':'#fcfaf6'};border:1px solid ${enPerte?'#b3261e':'var(--hair)'};border-radius:12px;padding:11px 13px;margin-bottom:12px">
    <div style="font-size:.78rem;color:#7a6a62;margin-bottom:6px">Sur <b>${euro(prix)}</b> de prix de vente, voici où va chaque centime :</div>
    <div style="display:flex;height:22px;border-radius:6px;overflow:hidden;background:#eee">${barre2}</div>
    <div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:8px">${legende}</div>
    ${enPerte?`<div style="margin-top:10px;padding:9px 11px;background:#fdecea;border-left:3px solid #b3261e;border-radius:6px">
      <div style="font-size:.84rem;font-weight:700;color:#b3261e">⚠️ Vendu à perte : ${euro(margeReelle)} par macaron</div>
      <div style="font-size:.75rem;color:#6a5a52;margin-top:3px">Tes coûts (<b>${euro(coutTotal)}</b>) dépassent ton prix de vente (<b>${euro(prix)}</b>). Prix d'équilibre : <b>${euro(coutTotal)}</b> — soit <b>${euro(money2(coutTotal - prix))}</b> de plus qu'aujourd'hui.</div>
    </div>`:''}
  </div>`;
}
async function parfumDetail(recipeId){
  const [recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions]=await Promise.all([
    db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray(), db.materials.toArray(),
    db.orders.toArray(), db.markets.toArray(), db.marketMoves.toArray(), db.productions.toArray()
  ]);
  const s=getSettings();
  const data={recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions, settings:s};
  const r=recipes.find(x=>x.id===recipeId); if(!r){ toast('Recette introuvable'); return; }
  const A=analyzeFlavorProfitability(data);
  const row=A.rows.find(x=>x.recipeId===recipeId); if(!row){ toast('Données indisponibles'); return; }
  const c=row.cost;
  const vent=ventilationCoqueGarniture(c, mats);
  const matName=id=>(mats.find(m=>m.id===id)||{}).nom||'—';
  const matUnit=id=>(mats.find(m=>m.id===id)||{}).unite||'';

  const detailRows=c.detail.filter(d=>d.cout>0).sort((a,b)=>b.cout-a.cout).map(d=>`<tr>
     <td>${esc(matName(d.materialId))}</td><td>${qtyDisp(d.qteParBatch, d.materialId)} ${esc(dispUnit(d.materialId).u)}</td>
     <td>${euro(d.pu)}/${esc(matUnit(d.materialId))}</td><td>${euro(money2(d.cout))}</td></tr>`).join('');

  // valeur de référence pour la simulation : prix de vente moyen constaté, sinon prix unitaire global
  const prixRef = row.prixVenteMoyen!=null ? row.prixVenteMoyen : (+s.prixVenteUnitaire||money2((BOX_PRICES[6]||12)/6));
  // seuil de rentabilité : à ce prix de référence, combien de pièces pour couvrir un batch (MO+conso inclus)
  const margeRefUnit = money2(prixRef - c.coutRevientUnit);

  openModal(`<h3>${esc(r.produitNom)} <span class="tag" style="background:${row.scale.col};color:#fff">${row.scale.dot} ${row.scale.label}</span></h3>
    ${parfumMargeBar(row, c)}
    <div class="sum-box"><span>Coût de revient / pièce</span><b>${euro(c.coutRevientUnit)}</b></div>
    <div class="sum-box"><span>· dont matières</span><b>${euro(c.coutMatUnit)}</b></div>
    <div class="sum-box"><span>· dont coque (estim.)</span><b>${euro(vent.coqueUnit)}</b></div>
    <div class="sum-box"><span>· dont garniture (estim.)</span><b>${euro(vent.garnitureUnit)}</b></div>
    ${c.coutConsoUnit>0?`<div class="sum-box"><span>· dont consommables</span><b>${euro(c.coutConsoUnit)}</b></div>`:''}
    ${c.laborOn?`<div class="sum-box"><span>· dont main-d'œuvre</span><b>${euro(c.coutMODUnit)}</b></div>`:''}
    <div class="sum-box"><span>Rendement utile / batch</span><b>${qty(c.piecesUtiles)}${c.pertePct>0?` <span style="color:#9a8a82;font-weight:400">(−${c.pertePct}% pertes)</span>`:''}</b></div>
    <div class="sum-box"><span>Coût de revient / batch</span><b>${euro(c.coutRevientBatch)}</b></div>
    <hr style="border:none;border-top:1px solid #ece2d4;margin:10px 0">
    <div class="sum-box"><span>Prix de vente moyen constaté</span><b>${row.prixVenteMoyen!=null?euro(row.prixVenteMoyen):'— pas de vente —'}</b></div>
    <div class="sum-box"><span>Marge / pièce</span><b style="color:${row.margeUnit!=null?(row.margeUnit>=0?'#3f7d52':'#b3261e'):'#9a8a82'}">${row.margeUnit!=null?euro(row.margeUnit)+' ('+row.tauxMarge+'%)':'—'}</b></div>
    <div class="sum-box"><span>Vendus / CA / marge brute</span><b>${qty(row.piecesVendues)} · ${euro(row.ca)} · ${euro(row.margeBrute)}</b></div>
    ${row.stock>0?`<div class="sum-box"><span>Stock immobilisé</span><b>${qty(row.stock)} pc · ${euro(row.valStockCout)}</b></div>`:''}

    <details style="margin-top:10px"><summary style="cursor:pointer;color:var(--caramel,#AA7C39);font-weight:600">Détail des matières (par batch)</summary>
      ${detailRows?`<div class="table-wrap" style="margin-top:6px"><table><thead><tr><th>Matière</th><th>Qté</th><th>Prix</th><th>Coût</th></tr></thead><tbody>${detailRows}</tbody></table></div>`:'<p class="note">Aucune matière avec prix.</p>'}
    </details>

    <h3 style="font-size:.98rem;margin:14px 0 6px">Simulation de prix</h3>
    <div class="field"><label>Prix de vente / pièce (€)</label>
      <input type="number" step="0.05" min="0" id="simPrix" value="${prixRef}" oninput="parfumSimUpdate(${recipeId},${c.coutRevientUnit},${row.piecesVendues||0})"></div>
    <div id="simOut"></div>
    <p class="note">Le seuil de rentabilité est atteint dès que le prix dépasse le coût de revient (${euro(c.coutRevientUnit)}/pc).</p>

    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button>
      <button class="btn" onclick="closeModal();recForm(${recipeId})">✎ Modifier la recette</button></div>`);
  parfumSimUpdate(recipeId, c.coutRevientUnit, row.piecesVendues||0);
}

// Met à jour la simulation de prix dans la fiche parfum.
function parfumSimUpdate(recipeId, coutUnit, piecesHist){
  const out=document.getElementById('simOut'); if(!out) return;
  const prix=+(document.getElementById('simPrix')?.value)||0;
  const marge=money2(prix-coutUnit);
  const taux=prix>0?Math.round(marge/prix*1000)/10:0;
  const sc=flavorScale(taux);
  const projMarge = piecesHist>0 ? money2(marge*piecesHist) : null;
  out.innerHTML=`
    <div class="sum-box"><span>Marge / pièce à ce prix</span><b style="color:${marge>=0?'#3f7d52':'#b3261e'}">${euro(marge)} (${taux}%)</b></div>
    <div class="sum-box"><span>Note de rentabilité</span><b><span class="tag" style="background:${sc.col};color:#fff">${sc.dot} ${sc.label}</span></b></div>
    ${projMarge!=null?`<div class="sum-box"><span>Marge brute si volume = historique (${qty(piecesHist)} pc)</span><b style="color:${projMarge>=0?'#3f7d52':'#b3261e'}">${euro(projMarge)}</b></div>`:''}`;
}

// PRÉVISION : marge prévisionnelle d'un batch (avant production).
async function parfumBatchSim(){
  const [recipes, recipeItems, lots]=await Promise.all([db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray()]);
  if(!recipes.length){ toast('Crée d\'abord une recette'); return; }
  const s=getSettings();
  // [COÛT + MO MESURÉE] précharge les mesures d'atelier (si MO mesurée activée) pour un coût complet.
  const _mo = await _chargeMesuresMO(s);
  const opts=sortByName(recipes,'produitNom').map(r=>`<option value="${r.id}">${esc(r.produitNom)}</option>`).join('');
  openModal(`<h3>🧮 Marge prévisionnelle d'un batch</h3>
    <div class="field"><label>Parfum</label><select id="bs_rec" onchange="parfumBatchSimUpdate()">${opts}</select></div>
    <div class="row2">
      <div class="field"><label>Nombre de batchs</label><input type="number" min="1" step="1" id="bs_n" value="1" oninput="parfumBatchSimUpdate()"></div>
      <div class="field"><label>Prix de vente / pièce (€)</label><input type="number" min="0" step="0.05" id="bs_prix" value="${s.prixVenteUnitaire||2.50}" oninput="parfumBatchSimUpdate()"></div>
    </div>
    <div id="bs_out"></div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
  // stocke les données pour le calcul live
  window._bsData={recipes, recipeItems, lots, settings:s, mesureParRec:_mo.mesureParRec, mesureGlobal:_mo.mesureGlobal};
  // pré-remplit le prix avec le prix de vente moyen si dispo
  parfumBatchSimUpdate();
}
function parfumBatchSimUpdate(){
  const d=window._bsData; if(!d) return;
  const out=document.getElementById('bs_out'); if(!out) return;
  const rid=+val('bs_rec'); const n=Math.max(1,+val('bs_n')||1); const prix=+val('bs_prix')||0;
  const r=d.recipes.find(x=>x.id===rid); if(!r){ out.innerHTML=''; return; }
  const _opt=_optMesureRecette(r, d.settings, d.mesureParRec, d.mesureGlobal);
  const c=coutRevientRecette(r, d.recipeItems, d.lots, d.settings, _opt);
  const pieces=round3(c.piecesUtiles*n);
  const coutTotal=money2(c.coutRevientBatch*n);
  const ca=money2(prix*pieces);
  const margeBrute=money2(ca-coutTotal);
  const chargesSoc=money2(ca*d.settings.socialGoods/100);
  const margeNette=money2(margeBrute-chargesSoc);
  const taux=ca>0?Math.round(margeBrute/ca*1000)/10:0;
  const sc=flavorScale(taux);
  out.innerHTML=`
    <div class="sum-box"><span>Pièces vendables (${n} batch)</span><b>${qty(pieces)}${c.pertePct>0?` <span style="color:#9a8a82;font-weight:400">(−${c.pertePct}%)</span>`:''}</b></div>
    <div class="sum-box"><span>Coût de revient total</span><b>${euro(coutTotal)}</b> <span style="color:#9a8a82;font-size:.72rem">(${euro(c.coutRevientUnit)}/pc)</span></div>
    <div class="sum-box"><span>CA prévisionnel (tout vendu)</span><b>${euro(ca)}</b></div>
    <div class="sum-box"><span>Marge brute prévisionnelle</span><b style="color:${margeBrute>=0?'#3f7d52':'#b3261e'}">${euro(margeBrute)} (${taux}%)</b></div>
    <div class="sum-box"><span>Marge nette estimée</span><b style="color:${margeNette>=0?'#3f7d52':'#b3261e'}">${euro(margeNette)}</b> <span style="color:#9a8a82;font-size:.72rem">après charges ${d.settings.socialGoods}%</span></div>
    <div class="sum-box"><span>Note</span><b><span class="tag" style="background:${sc.col};color:#fff">${sc.dot} ${sc.label}</span></b></div>`;
}

// PRÉVISION : mix de parfums optimal pour maximiser le bénéfice attendu.
async function parfumMixOptim(){
  const [recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions]=await Promise.all([
    db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray(), db.materials.toArray(),
    db.orders.toArray(), db.markets.toArray(), db.marketMoves.toArray(), db.productions.toArray()
  ]);
  const s=getSettings();
  const data={recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions, settings:s};
  const A=analyzeFlavorProfitability(data);
  const sold=A.rows.filter(r=>r.piecesVendues>0 && r.margeUnit!=null);
  if(!sold.length){ openModal(`<h3>🎯 Mix de parfums optimal</h3><p class="note">Pas assez d'historique de vente. Enregistrez des commandes et des marchés pour estimer la demande et la marge par parfum.</p><div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`); return; }

  // poids de demande = part des pièces vendues ; score = marge unitaire × demande relative
  const totPieces=sold.reduce((x,r)=>x+r.piecesVendues,0);
  const scored=sold.map(r=>({...r, demandePct: totPieces>0?r.piecesVendues/totPieces*100:0,
    score: money2(r.margeUnit * (r.piecesVendues/Math.max(1,totPieces)))}))
    .sort((a,b)=>b.score-a.score);

  // recommandation pour un volume cible (ex : 300 pièces) réparti au prorata marge×demande
  const cible=300;
  const sumScore=scored.reduce((x,r)=>x+Math.max(0,r.margeUnit)*r.piecesVendues,0);
  const mix=scored.map(r=>{
    const part=sumScore>0?(Math.max(0,r.margeUnit)*r.piecesVendues)/sumScore:0;
    const q=Math.round(cible*part);
    return {...r, q, margeAttendue:money2(q*r.margeUnit)};
  }).filter(m=>m.q>0);
  const margeTot=money2(mix.reduce((x,m)=>x+m.margeAttendue,0));
  // [v1322] Les parfums VENDUS À PERTE sont (à juste titre) exclus du mix : on ne recommande pas
  // de produire à perte. Mais ils disparaissaient SILENCIEUSEMENT — impossible de savoir pourquoi
  // un parfum n'apparaît pas. On les liste désormais explicitement, avec leur déficit.
  const deficitaires = scored.filter(r => r.margeUnit < 0).sort((a,b)=>a.margeUnit-b.margeUnit);

  openModal(`<h3>🎯 Mix de parfums optimal</h3>
    <p class="note">Répartition conseillée pour <b>${cible} pièces</b>, pondérée par la marge unitaire et la demande historique. Maximise le bénéfice attendu pour un volume donné.</p>
    <div class="table-wrap"><table><thead><tr><th>Parfum</th><th>Part conseillée</th><th>Marge/pc</th><th>Marge attendue</th></tr></thead><tbody>
      ${mix.map(m=>`<tr><td><b>${esc(m.nom)}</b><br><span style="color:#9a8a82;font-size:.7rem">demande ${m.demandePct.toFixed(0)}%</span></td>
        <td>${m.q} pc</td><td style="color:${m.margeUnit>=0?'#3f7d52':'#b3261e'}">${euro(m.margeUnit)}</td>
        <td style="font-weight:600">${euro(m.margeAttendue)}</td></tr>`).join('')}
    </tbody></table></div>
    <div class="sum-box" style="margin-top:8px"><span><b>Marge brute attendue (${cible} pc)</b></span><b style="color:#3f7d52">${euro(margeTot)}</b></div>
    ${deficitaires.length?`<div style="margin-top:10px;padding:9px 11px;background:#fdecea;border-left:3px solid #b3261e;border-radius:6px">
      <div style="font-size:.82rem;font-weight:700;color:#b3261e">⚠️ ${deficitaires.length} parfum${deficitaires.length>1?'s':''} exclu${deficitaires.length>1?'s':''} du mix : vendu${deficitaires.length>1?'s':''} à perte</div>
      <div style="font-size:.75rem;color:#6a5a52;margin-top:4px">${deficitaires.map(r=>`<b>${esc(r.nom)}</b> ${euro(r.margeUnit)}/pc`).join(' · ')}</div>
      <div style="font-size:.72rem;color:#9a8a82;margin-top:4px">Chaque pièce produite te fait perdre de l'argent. Augmente le prix, réduis le coût, ou arrête ${deficitaires.length>1?'ces parfums':'ce parfum'}.</div>
    </div>`:''}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}

// PRÉVISION : gain estimé d'un marché d'après l'historique.
async function parfumMarketGain(){
  const [markets, marketMoves, recipes, recipeItems, lots]=await Promise.all([
    db.markets.toArray(), db.marketMoves.toArray(), db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray()
  ]);
  const clos=markets.filter(m=>m.statut==='clos');
  if(!clos.length){ openModal(`<h3>⛺ Gain estimé d'un marché</h3><p class="note">Aucun marché clôturé dans l'historique. Clôturez au moins un marché pour obtenir une estimation.</p><div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`); return; }
  const avgUnit=avgMacaronCost(recipes, recipeItems, lots);
  const movesByMk={}; marketMoves.forEach(mv=>{(movesByMk[mv.marketId] ||= []).push(mv);});
  let caTot=0, margeTot=0, venduTot=0;
  clos.forEach(mk=>{ const T=marketTotals(mk, movesByMk[mk.id]||[], avgUnit); caTot+=T.caTotal; margeTot+=T.margeNette; venduTot+=T.vendu; });
  const caMoy=money2(caTot/clos.length), margeMoy=money2(margeTot/clos.length), venduMoy=round3(venduTot/clos.length);
  openModal(`<h3>⛺ Gain estimé d'un marché</h3>
    <p class="note">Moyenne sur ${clos.length} marché(s) clôturé(s).</p>
    <div class="sum-box"><span>CA moyen / marché</span><b>${euro(caMoy)}</b></div>
    <div class="sum-box"><span>Pièces vendues / marché</span><b>${qty(venduMoy)}</b></div>
    <div class="sum-box"><span>Marge nette moyenne / marché</span><b style="color:${margeMoy>=0?'#3f7d52':'#b3261e'}">${euro(margeMoy)}</b></div>
    <p class="note">Estimation indicative : les ventes réelles dépendent de la météo, de l'affluence et du mix de parfums embarqué.</p>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}

// Réglages coûts & main-d'œuvre (raccourci vers les paramètres pertinents).
function parfumSettingsForm(){
  const s=getSettings();
  const grid=s.prixParFormat||{};
  const fmtKeys=[...new Set([...BOX_SIZES, ...Object.keys(grid).map(Number)])].filter(n=>n>0).sort((a,b)=>a-b);
  openModal(`<h3>⚙ Prix, coûts & main-d'œuvre</h3>
    <p class="note">Le CA réel reste toujours le CA encaissé. La grille ci-dessous (prix dégressif par format) sert à estimer un prix moyen pondéré et à détecter les incohérences de CA.</p>
    <label style="font-weight:600;font-size:.9rem">Prix de vente par format (€ / macaron)</label>
    <div class="row2" style="margin-top:6px">
      ${fmtKeys.map(k=>`<div class="field"><label>Coffret ${k} macarons</label><input type="number" step="0.01" min="0" id="ps_pf_${k}" value="${grid[k]!=null?grid[k]:''}" placeholder="€/pièce"></div>`).join('')}
    </div>
    <input type="hidden" id="ps_pf_keys" value="${fmtKeys.join(',')}">
    <div class="field" style="margin-top:8px"><label>Tarif PRO — macaron standard (€ / macaron) <span style="color:#9a8a82;font-weight:400">— vrac en boîte réutilisable</span></label>
      <input type="number" step="0.01" min="0" id="ps_propstd" value="${s.prixMacaronProStd!=null?s.prixMacaronProStd:1.40}" placeholder="1.40"></div>
    <div class="field"><label>Tarif PRO — macaron grand format (€ / pièce)</label>
      <input type="number" step="0.01" min="0" id="ps_progf" value="${s.prixGrandFormatPro!=null?s.prixGrandFormatPro:3.20}" placeholder="3.20"></div>
    <hr style="border:none;border-top:1px solid #ece2d4;margin:12px 0">
    <div class="field"><label class="pay-opt" style="display:flex;align-items:center;gap:8px"><input type="checkbox" id="ps_labor" ${s.laborEnabled?'checked':''}> <span>Inclure la main-d'œuvre dans le coût de revient</span></label></div>
    <div class="field"><label>Taux horaire main-d'œuvre (€/h)</label><input type="number" step="0.5" min="0" id="ps_rate" value="${s.laborRate}"></div>
    <div class="field"><label>Source du temps de main-d'œuvre</label>
      <select id="ps_laborsrc">
        <option value="manuel" ${s.laborSource!=='mesure'?'selected':''}>Temps saisi par recette (min/batch)</option>
        <option value="mesure" ${s.laborSource==='mesure'?'selected':''}>Temps mesuré à l'atelier (lissé 90 j)</option>
      </select>
      <p class="note">En mode « mesuré », le coût de revient utilise ton temps de production réel moyen par macaron (atelier, 90 derniers jours). Si les données mesurées sont insuffisantes, le temps saisi par recette est utilisé en repli.</p>
    </div>
    <div class="row2">
      <div class="field"><label>Charges sociales — marchandise (%)</label><input type="number" step="0.1" id="ps_sg" value="${s.socialGoods}"></div>
      <div class="field"><label>Charges sociales — prestation (%)</label><input type="number" step="0.1" id="ps_ss" value="${s.socialService}"></div>
    </div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button><button class="btn" onclick="parfumSettingsSave()">Enregistrer</button></div>`);
}
function parfumSettingsSave(){
  const s=getSettings();
  const keys=(val('ps_pf_keys')||'').split(',').map(Number).filter(n=>n>0);
  const grid={}; keys.forEach(k=>{ const v=+val('ps_pf_'+k); if(v>0) grid[k]=money2(v); });
  if(Object.keys(grid).length) s.prixParFormat=grid;
  // prix de repli = moyenne simple de la grille
  const vals=Object.values(s.prixParFormat||{}).map(Number).filter(x=>x>0);
  if(vals.length) s.prixVenteUnitaire=money2(vals.reduce((a,b)=>a+b,0)/vals.length);
  { const pp=+val('ps_propstd'); if(pp>0) s.prixMacaronProStd=money2(pp); }
  { const pg=+val('ps_progf'); if(pg>0) s.prixGrandFormatPro=money2(pg); }
  s.laborEnabled=document.getElementById('ps_labor')?.checked||false;
  s.laborRate=Math.max(0,+val('ps_rate')||0);
  s.laborSource=val('ps_laborsrc')==='mesure'?'mesure':'manuel';
  s.socialGoods=Math.max(0,+val('ps_sg')||0);
  s.socialService=Math.max(0,+val('ps_ss')||0);
  saveSettings(s);
  closeModal(); renderParfums(); toast('Paramètres enregistrés ✓');
}

// [LEVIERS DE MARGE] Construit l'encart « ce qui fait monter/baisser ta marge nette / macaron ».
// S'appuie ENTIÈREMENT sur analyzeFlavorProfitability (même source que la carte d'accueil) pour
// rester cohérent. Décompose le coût d'un macaron moyen + facteurs transverses + recommandations.
function _margeLeviersHtml(A, recs){
  if(!A || !A.totals || !(A.totals.pieces>0)){
    return `<div class="panel"><h2>🎯 Leviers de ta marge</h2><p class="empty">Pas encore assez de ventes pour analyser les leviers. Enregistre des commandes et clôture des marchés.</p></div>`;
  }
  const t=A.totals;
  const pieces=t.pieces;
  const par = v => money2((+v||0)/pieces);          // ramène un total à l'unité (€/macaron)
  // Décomposition du prix de vente moyen en €/macaron
  const pvMoyen = par(t.ca);
  const coutRevient = par(t.ca - t.margeBrute);      // matières + emballages + temps rattachés aux ventes
  const charges = par(t.margeBrute - t.margeNette);  // charges sociales
  const margeNette = par(t.margeNette);
  // Facteurs transverses (en €/macaron) qui rognent la marge
  const donsParPiece = t.coutDons>0 ? par(t.coutDons) : 0;
  // Barre de composition (part de chaque poste dans le prix de vente)
  const pct = v => pvMoyen>0 ? Math.max(0,Math.min(100,Math.round((+v||0)/pvMoyen*100))) : 0;
  const seg = (lib,val,col)=>`<div style="display:flex;justify-content:space-between;font-size:.82rem;padding:2px 0">
      <span>${lib}</span><b style="color:${col}">${euro(money2(val))} <span style="color:#9a8a82;font-weight:400">· ${pct(val)}%</span></b></div>`;
  // Sélection des 3 recommandations les plus « actionnables » (perte, faible marge/fort volume, stock mort)
  const prioIcons = {'🛑':0,'⚠️':1,'📦':2,'💎':3,'🏆':4};
  const recTop = (recs||[]).slice().sort((a,b)=>(prioIcons[a.icon]??9)-(prioIcons[b.icon]??9)).slice(0,3);
  const recHtml = recTop.length ? recTop.map(r=>`<div style="display:flex;gap:8px;padding:6px 0;border-top:1px solid #f0e9e2">
      <span style="flex:none">${r.icon}</span><span style="font-size:.84rem;color:#5a4a42">${r.txt}</span></div>`).join('') : '';
  return `<div class="panel" style="border:1px solid #e8dcc0;background:#fffdf8">
    <h2 style="margin-bottom:2px">🎯 Leviers de ta marge nette / macaron</h2>
    <p class="note" style="margin-bottom:10px">Sur la base de <b>${qty(pieces)}</b> macaron(s) vendu(s). Voici ce qui compose ton prix moyen et ce qui pèse sur ta marge.</p>
    <div class="sum-box" style="flex-direction:column;align-items:stretch;gap:0;background:#faf6ee">
      ${seg('Prix de vente moyen', pvMoyen, '#2e6b3f')}
      ${seg('− Coût de revient (matières, emballage, temps)', -coutRevient, '#b3261e')}
      ${seg('− Charges sociales', -charges, '#b3261e')}
      <div style="display:flex;justify-content:space-between;border-top:2px solid #e8dccd;margin-top:4px;padding-top:5px">
        <span><b>= Marge nette / macaron</b></span><b style="color:${margeNette>=0?'#2e6b3f':'#b3261e'};font-size:1.02rem">${euro(margeNette)}</b></div>
    </div>
    ${donsParPiece>0?`<p class="note" style="margin-top:8px">🎁 Les dons coûtent en moyenne <b>${euro(donsParPiece)}</b> par macaron vendu (marge après dons : <b>${euro(par(t.margeApresDons))}</b>/macaron).</p>`:''}
    ${(t.nbLivraisons>0)?`<p class="note" style="margin-top:4px">🚚 Livraisons (${t.nbLivraisons}) : coût des tournées <b style="color:#b3261e">${euro(t.coutLivraisonBrut)}</b>${t.fraisLivFactures>0?` · facturé aux clients <b>${euro(t.fraisLivFactures)}</b>`:''} → impact net sur la marge <b style="color:${t.livBeneficeNet>=0?'#2e6b3f':'#b3261e'}">${t.livBeneficeNet>=0?'+':''}${euro(t.livBeneficeNet)}</b>. Marge après dons & livraison : <b>${euro(t.margeApresLivraison)}</b>.</p>`:''}
    ${t.ecartTheo!=null && Math.abs(t.ecartTheo)>=0.5?`<p class="note" style="margin-top:4px">${t.ecartTheo<0?'📉':'📈'} Écart prix encaissé vs attendu : <b style="color:${t.ecartTheo<0?'#b3261e':'#2e6b3f'}">${t.ecartTheo>0?'+':''}${euro(t.ecartTheo)}</b> au total (remises, arrondis, prix manuels).</p>`:''}
    ${recHtml?`<div style="margin-top:10px"><div style="font-weight:600;font-size:.86rem;color:#52252F;margin-bottom:2px">Pistes prioritaires</div>${recHtml}</div>`:''}
    <button class="btn ghost sm" style="margin-top:10px;width:100%" onclick="goView('rentaparfum')">🎯 Voir le détail par parfum & toutes les recommandations ›</button>
  </div>`;
}

// ════════════════════════════════════════════════════════════════════════
//  MINI-CRM B2B — Prospection professionnelle (restaurants, hôtels, CE…)
//  Transforme « plein de pros à démarcher » en clients signés : suivi des
//  cibles, relances, tarifs négociés, et pense-bête de démarchage.
// ════════════════════════════════════════════════════════════════════════
const PROSPECT_CATS = {
  resto:      {label:'Restaurant',        ico:'🍽️', pitch:"desserts à l'assiette, mignardises café gourmand, fin de repas signature"},
  hotel:      {label:'Hôtel',             ico:'🏨', pitch:"petits-déjeuners, plateaux d'accueil chambre, séminaires"},
  salon_the:  {label:'Salon de thé',      ico:'🫖', pitch:"vitrine sucrée, accord thé/macaron, gamme tournante"},
  ce:         {label:'Comité d\'entreprise', ico:'🏢', pitch:"événements internes, cadeaux clients/salariés, fêtes de fin d'année"},
  traiteur:   {label:'Traiteur',          ico:'🥂', pitch:"buffets, cocktails, mariages — volumes et sous-traitance sucrée"},
  epicerie:   {label:'Épicerie fine',     ico:'🛍️', pitch:"dépôt-vente, coffrets cadeaux, produit local d'artisan"},
  fleuriste:  {label:'Fleuriste',         ico:'💐', pitch:"coffrets cadeaux associés aux bouquets (fête des mères, St-Valentin)"},
  autre:      {label:'Autre',             ico:'📍', pitch:"toute structure susceptible de commander en volume régulier"}
};
const PROSPECT_STATUTS = {
  a_contacter: {label:'À contacter', ico:'🎯', col:'#9a8a82', ordre:0},
  contacte:    {label:'Contacté',    ico:'📞', col:'#c9a227', ordre:1},
  relance:     {label:'Relancé',     ico:'🔁', col:'#d98324', ordre:2},
  rdv:         {label:'RDV / dégustation', ico:'🤝', col:'#5a7a9a', ordre:3},
  client:      {label:'Client signé',ico:'✅', col:'#2e7d32', ordre:4},
  abandonne:   {label:'Abandonné',   ico:'🚫', col:'#b3261e', ordre:5}
};
// Pense-bête de démarchage : étapes concrètes, adaptées à un artisan qui débute.
const PROSPECT_PITCH = [
  {t:'Avant d\'y aller', l:["Repère 5 cibles proches à pied/en voiture.","Préparez une petite boîte de 4-6 macarons à offrir (l'échantillon vend mieux qu'un discours).","Choisis tes 2 parfums les plus bluffants visuellement et gustativement."]},
  {t:'L\'accroche (30 secondes)', l:["« Bonjour, je suis Benjamin, pâtissier-macaronnier au Mans (Sensations Macarons). »","« Je travaille avec des [restaurants/hôtels…] pour leurs [desserts/petits-déjeuners…]. »","« Je vous ai apporté quelques macarons à goûter — qui est la bonne personne pour en parler ? »"]},
  {t:'Ce qui les intéresse', l:["Régularité et fiabilité (tu livres quand tu dis).","Produit local et artisanal = argument de vente pour EUX auprès de leurs clients.","Personnalisation possible (parfum signature à leur nom, à leur enseigne)."]},
  {t:'Lever les objections', l:["« C'est cher » → propose un format/par­fum adapté à leur marge, ou un volume dégressif.","« On a déjà un fournisseur » → « gardez mon contact pour un dépannage ou une nouveauté ».","« Il faut que je voie » → laisse l'échantillon + une carte, et NOTE une date de relance."]},
  {t:'Toujours finir par', l:["Repartir avec un nom + un contact (téléphone ou mail).","Fixer la prochaine étape (« je vous rappelle jeudi », « je repasse avec un devis »).","Le noter ICI tout de suite, avec une date de relance — c'est ce qui fait signer."]}
];

let _prospectFilter = 'tous';
async function renderProspects(){
  const list = await db.prospects.orderBy('majTs').reverse().toArray().catch(()=>[]);
  // Stats par statut
  const parStatut = {};
  Object.keys(PROSPECT_STATUTS).forEach(k=>parStatut[k]=0);
  list.forEach(p=>{ if(parStatut[p.statut]!=null) parStatut[p.statut]++; });
  const total = list.length;
  const clients = parStatut.client||0;
  // Relances dues (prochaineSuite <= aujourd'hui, statut non terminal)
  const todayStr = today();
  const relancesDues = list.filter(p=>p.prochaineSuite && p.prochaineSuite<=todayStr && !['client','abandonne'].includes(p.statut));

  // Filtres par statut
  const filtChips = ['tous', ...Object.keys(PROSPECT_STATUTS)].map(k=>{
    const actif = _prospectFilter===k;
    const lbl = k==='tous' ? `Tous (${total})` : `${PROSPECT_STATUTS[k].ico} ${PROSPECT_STATUTS[k].label} (${parStatut[k]||0})`;
    return `<button class="btn ${actif?'gold':'ghost'} sm" style="margin:2px" onclick="_prospectFilter='${k}';renderProspects()">${lbl}</button>`;
  }).join('');

  const visibles = _prospectFilter==='tous' ? list : list.filter(p=>p.statut===_prospectFilter);
  // Tri : relance due d'abord, puis par statut, puis récent
  visibles.sort((a,b)=>{
    const ra = (a.prochaineSuite && a.prochaineSuite<=todayStr && !['client','abandonne'].includes(a.statut))?0:1;
    const rb = (b.prochaineSuite && b.prochaineSuite<=todayStr && !['client','abandonne'].includes(b.statut))?0:1;
    if(ra!==rb) return ra-rb;
    return (PROSPECT_STATUTS[a.statut]?.ordre||0)-(PROSPECT_STATUTS[b.statut]?.ordre||0);
  });

  const cards = visibles.length ? visibles.map(_prospectCard).join('') : '<div class="empty">Aucun prospect dans cette catégorie. Ajoute ta première cible !</div>';

  document.getElementById('main').innerHTML = `
   <div class="topbar"><div><h1>Prospection B2B</h1><p>Tes cibles pros : démarche, relance, signe</p></div>
     <button class="btn ghost sm" onclick="prospectPitchSheet()">💬 Pense-bête</button></div>
   <div class="banner">🤝 <div>Un seul client pro régulier (resto, hôtel, CE…) pèse plus que des dizaines de ventes au détail. Note ici chaque cible et surtout <b>la date de relance</b> — c'est ce qui fait signer.</div></div>
   ${relancesDues.length?`<div class="panel" style="border:1px solid #e5b4ae;background:#fdf6f5"><h2 style="color:#b3261e">🔔 ${relancesDues.length} relance(s) à faire</h2>${relancesDues.map(_prospectCard).join('')}</div>`:''}
   <div style="display:flex;gap:8px;margin:10px 0">
     <button class="btn gold" style="flex:1" onclick="prospectForm(-1)">＋ Nouveau prospect</button>
   </div>
   <div style="display:flex;flex-wrap:wrap;margin-bottom:8px">${filtChips}</div>
   <div style="display:flex;flex-direction:column;gap:10px">${cards}</div>
   ${total===0?`<div class="panel" style="margin-top:12px"><h2>💡 Par où commencer ?</h2><p class="note">Ajoute 5 cibles proches de chez toi. Pour chaque catégorie, voici l'angle qui marche :</p>${Object.entries(PROSPECT_CATS).map(([k,c])=>`<div style="padding:6px 0;border-top:1px solid #f0e9e2;font-size:.86rem"><b>${c.ico} ${c.label}</b> — ${esc(c.pitch)}</div>`).join('')}</div>`:''}`;
}
function _prospectCard(p){
  const cat = PROSPECT_CATS[p.categorie]||PROSPECT_CATS.autre;
  const st = PROSPECT_STATUTS[p.statut]||PROSPECT_STATUTS.a_contacter;
  const todayStr = today();
  const relanceDue = p.prochaineSuite && p.prochaineSuite<=todayStr && !['client','abandonne'].includes(p.statut);
  const pot = (+p.potentiel||0);
  const potStr = pot>0 ? '⭐'.repeat(pot) : '';
  return `<div style="background:#fff;border:1px solid var(--hair);border-left:4px solid ${st.col};border-radius:14px;padding:13px 15px;box-shadow:var(--sh-1)">
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
      <span style="flex:none;font-size:1.1rem">${cat.ico}</span>
      <b style="flex:1;color:var(--bordeaux);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(p.nom||'(sans nom)')}</b>
      <span class="tag" style="background:${st.col};color:#fff;font-size:.64rem">${st.ico} ${st.label}</span>
    </div>
    <div style="font-size:.78rem;color:#7a6a60;margin-bottom:6px">${cat.label}${potStr?` · ${potStr}`:''}${p.contact?` · 👤 ${esc(p.contact)}`:''}</div>
    ${(p.tel||p.email)?`<div style="font-size:.78rem;color:#7a6a60;margin-bottom:6px">${p.tel?`📞 ${esc(p.tel)}`:''}${p.tel&&p.email?' · ':''}${p.email?`✉️ ${esc(p.email)}`:''}</div>`:''}
    ${p.tarifPro?`<div style="font-size:.78rem;color:#5a4a42;margin-bottom:6px">💰 ${esc(p.tarifPro)}</div>`:''}
    ${relanceDue?`<div style="font-size:.78rem;color:#b3261e;font-weight:600;margin-bottom:6px">🔔 Relance prévue le ${fmtDate(p.prochaineSuite)}</div>`:(p.prochaineSuite?`<div style="font-size:.78rem;color:#9a8a82;margin-bottom:6px">📅 Prochaine étape : ${fmtDate(p.prochaineSuite)}</div>`:'')}
    <div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:4px">
      <button class="btn ghost sm" onclick="prospectAdvance(${p.id})" title="Faire avancer dans le tunnel">▶ Avancer</button>
      <button class="btn ghost sm" onclick="prospectLogForm(${p.id})" title="Noter une action (appel, visite…)">📝 Action</button>
      <button class="btn ghost sm" onclick="prospectForm(${p.id})">✎ Éditer</button>
      ${p.statut==='client'&&!p.clientId?`<button class="btn ghost sm" style="color:#2e7d32" onclick="prospectToClient(${p.id})" title="Créer la fiche client">➕ En client</button>`:''}
    </div>
  </div>`;
}

// Formulaire d'ajout / édition d'un prospect.
async function prospectForm(id){
  const p = id>=0 ? await db.prospects.get(id) : null;
  const isNew = !p;
  const v = p || {nom:'', categorie:'resto', statut:'a_contacter', contact:'', tel:'', email:'', adresse:'', tarifPro:'', frequence:'', potentiel:2, notes:'', prochaineSuite:''};
  const catOpts = Object.entries(PROSPECT_CATS).map(([k,c])=>`<option value="${k}" ${v.categorie===k?'selected':''}>${c.ico} ${esc(c.label)}</option>`).join('');
  const statOpts = Object.entries(PROSPECT_STATUTS).map(([k,sObj])=>`<option value="${k}" ${v.statut===k?'selected':''}>${sObj.ico} ${esc(sObj.label)}</option>`).join('');
  openModal(`<h3>${isNew?'➕ Nouveau prospect':'✎ '+esc(v.nom)}</h3>
    <div class="field"><label>Nom de l'établissement *</label>
      <input id="pr_nom" value="${esc(v.nom)}" placeholder="ex : Le Bistrot des Halles"></div>
    <div class="row2">
      <div class="field"><label>Catégorie</label><select id="pr_cat">${catOpts}</select></div>
      <div class="field"><label>Statut</label><select id="pr_stat">${statOpts}</select></div>
    </div>
    <div class="row2">
      <div class="field"><label>Contact (personne)</label><input id="pr_contact" value="${esc(v.contact)}" placeholder="ex : Mme Durand, chef"></div>
      <div class="field"><label>Potentiel</label><select id="pr_pot">
        <option value="1" ${+v.potentiel===1?'selected':''}>⭐ Faible</option>
        <option value="2" ${+v.potentiel===2?'selected':''}>⭐⭐ Moyen</option>
        <option value="3" ${+v.potentiel===3?'selected':''}>⭐⭐⭐ Fort</option>
      </select></div>
    </div>
    <div class="row2">
      <div class="field"><label>Téléphone</label><input id="pr_tel" value="${esc(v.tel)}" placeholder="02 .. .. .. .."></div>
      <div class="field"><label>Email</label><input id="pr_email" value="${esc(v.email)}" placeholder="contact@..."></div>
    </div>
    <div class="field"><label>Adresse</label><input id="pr_adr" value="${esc(v.adresse)}" placeholder="rue, ville"></div>
    <div class="field"><label>Tarif pro négocié <span style="color:#9a8a82;font-weight:400">— note libre</span></label>
      <input id="pr_tarif" value="${esc(v.tarifPro)}" placeholder="ex : 1,30 €/macaron dès 100 pièces"></div>
    <div class="field"><label>Fréquence envisagée</label>
      <input id="pr_freq" value="${esc(v.frequence)}" placeholder="ex : ~150/mois, ponctuel événements"></div>
    <div class="field"><label>📅 Prochaine relance / étape</label>
      <input type="date" id="pr_suite" value="${esc(v.prochaineSuite||'')}"></div>
    <div class="field"><label>Notes</label>
      <textarea id="pr_notes" rows="2" placeholder="contexte, ce qui a été dit, objections…">${esc(v.notes)}</textarea></div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      ${!isNew?`<button class="btn ghost" style="color:#b3261e" onclick="prospectDelete(${id})">🗑 Supprimer</button>`:''}
      <button class="btn gold" onclick="prospectSave(${id})">${isNew?'Ajouter':'Enregistrer'}</button>
    </div>`);
}
async function prospectSave(id){
  const nom=(document.getElementById('pr_nom').value||'').trim();
  if(!nom){ toast('Indique au moins le nom'); return; }
  const data={
    nom,
    categorie: document.getElementById('pr_cat').value,
    statut: document.getElementById('pr_stat').value,
    contact:(document.getElementById('pr_contact').value||'').trim(),
    tel:(document.getElementById('pr_tel').value||'').trim(),
    email:(document.getElementById('pr_email').value||'').trim(),
    adresse:(document.getElementById('pr_adr').value||'').trim(),
    tarifPro:(document.getElementById('pr_tarif').value||'').trim(),
    frequence:(document.getElementById('pr_freq').value||'').trim(),
    potentiel:+document.getElementById('pr_pot').value||2,
    prochaineSuite: document.getElementById('pr_suite').value||'',
    notes:(document.getElementById('pr_notes').value||'').trim(),
    majTs: Date.now()
  };
  if(id>=0){ await db.prospects.update(id, data); toast('Prospect mis à jour ✓'); }
  else { data.createdTs=Date.now(); data.histo=[]; await db.prospects.add(data); toast('Prospect ajouté ✓'); }
  closeModal();
  renderProspects();
}
async function prospectDelete(id){
  const p=await db.prospects.get(id);
  if(!p) return;
  if(!confirm(`Supprimer « ${p.nom} » de tes prospects ?`)) return;
  await db.prospects.delete(id);
  closeModal();
  toast('Prospect supprimé');
  renderProspects();
}
// Fait avancer le prospect au statut suivant logique.
async function prospectAdvance(id){
  const p=await db.prospects.get(id); if(!p) return;
  const ordre=['a_contacter','contacte','relance','rdv','client'];
  const i=ordre.indexOf(p.statut);
  // depuis 'relance' on peut re-relancer ; sinon on avance d'un cran
  const next = (i<0||i>=ordre.length-1) ? p.statut : ordre[i+1];
  const histo=(p.histo||[]).concat([{ts:Date.now(), action:`Statut : ${PROSPECT_STATUTS[p.statut]?.label||p.statut} → ${PROSPECT_STATUTS[next]?.label||next}`}]);
  await db.prospects.update(id, {statut:next, majTs:Date.now(), histo});
  toast(`${PROSPECT_STATUTS[next]?.ico||''} ${PROSPECT_STATUTS[next]?.label||next}`);
  renderProspects();
}
// Noter une action (appel, visite, dégustation…) + fixer la prochaine relance.
async function prospectLogForm(id){
  const p=await db.prospects.get(id); if(!p) return;
  const histo=(p.histo||[]).slice().reverse();
  const histoHtml = histo.length ? histo.map(h=>`<div style="font-size:.78rem;padding:5px 0;border-top:1px solid #f0e9e2"><span style="color:#9a8a82">${fmtDate(ymdLocal(new Date(h.ts)))}</span> · ${esc(h.action)}</div>`).join('') : '<p class="note">Aucune action notée pour l\'instant.</p>';
  openModal(`<h3>📝 Action — ${esc(p.nom)}</h3>
    <div class="field"><label>Qu'as-tu fait ?</label>
      <select id="pr_act_type">
        <option value="Appel téléphonique">📞 Appel téléphonique</option>
        <option value="Visite sur place">🚶 Visite sur place</option>
        <option value="Échantillons déposés">🎁 Échantillons déposés</option>
        <option value="Dégustation faite">😋 Dégustation faite</option>
        <option value="Devis envoyé">📄 Devis envoyé</option>
        <option value="Email envoyé">✉️ Email envoyé</option>
        <option value="Relance">🔁 Relance</option>
        <option value="Autre">📍 Autre</option>
      </select></div>
    <div class="field"><label>Détail (optionnel)</label>
      <input id="pr_act_note" placeholder="ce qui a été dit, prochaine étape convenue…"></div>
    <div class="field"><label>📅 Prochaine relance</label>
      <input type="date" id="pr_act_suite" value="${esc(p.prochaineSuite||'')}"></div>
    <div class="panel" style="margin-top:8px;background:#faf6ee"><div style="font-weight:600;font-size:.84rem;margin-bottom:2px">Historique</div>${histoHtml}</div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button><button class="btn gold" onclick="prospectLogSave(${id})">Enregistrer l'action</button></div>`);
}
async function prospectLogSave(id){
  const p=await db.prospects.get(id); if(!p) return;
  const type=document.getElementById('pr_act_type').value;
  const note=(document.getElementById('pr_act_note').value||'').trim();
  const suite=document.getElementById('pr_act_suite').value||'';
  const action = note ? `${type} — ${note}` : type;
  const histo=(p.histo||[]).concat([{ts:Date.now(), action}]);
  await db.prospects.update(id, {histo, prochaineSuite:suite, majTs:Date.now()});
  closeModal();
  toast('Action enregistrée ✓');
  renderProspects();
}
// Convertit un prospect « client signé » en vraie fiche client de l'app.
async function prospectToClient(id){
  const p=await db.prospects.get(id); if(!p) return;
  if(p.clientId){ toast('Déjà lié à une fiche client'); return; }
  if(!confirm(`Créer une fiche client pour « ${p.nom} » ?`)) return;
  const clientId = await db.clients.add(withSync({
    nom:p.nom, tel:p.tel||'', email:p.email||'', adresse:p.adresse||'',
    type:'pro', notes:[p.tarifPro?`Tarif pro : ${p.tarifPro}`:'', p.frequence?`Fréquence : ${p.frequence}`:'', p.notes||''].filter(Boolean).join('\n')
  },'app'));
  await db.prospects.update(id, {clientId, majTs:Date.now()});
  toast('Fiche client créée ✓');
  renderProspects();
}
// Pense-bête de démarchage (sheet).
function prospectPitchSheet(){
  const blocs = PROSPECT_PITCH.map(b=>`<div style="margin-bottom:12px"><div style="font-weight:700;color:var(--bordeaux);margin-bottom:4px">${esc(b.t)}</div>${b.l.map(x=>`<div style="font-size:.86rem;color:#5a4a42;padding:3px 0 3px 14px;position:relative"><span style="position:absolute;left:0">•</span>${esc(x)}</div>`).join('')}</div>`).join('');
  openModal(`<h3>💬 Pense-bête : démarcher un pro</h3>
    <p class="note" style="margin-bottom:10px">Ton meilleur argument, c'est le goût. Apporte toujours des échantillons.</p>
    ${blocs}
    <div class="modal-actions"><button class="btn gold" onclick="closeModal()">C'est parti 💪</button></div>`);
}


// ════════════════════════════════════════════════════════════════════════
//  PERSONAS MARKETING — Connaître son client pour viser juste
//  Fiches-types riches (identité, motivations, canaux, ton, offres,
//  démarchage), construites à la main et/ou nourries par les vraies données
//  clients. Un moteur suggère la stratégie de com selon le profil.
// ════════════════════════════════════════════════════════════════════════
const PERSONA_ARCHETYPES = {
  gourmand_quartier: {emoji:'🧁', label:'Le gourmand du quartier', profil:'B2C', desc:"achète pour le plaisir, régulièrement, en petites quantités"},
  offreur_cadeau:    {emoji:'🎁', label:"L'offreur de cadeaux", profil:'B2C', desc:"achète pour offrir : coffrets soignés, occasions spéciales"},
  evenementiel:      {emoji:'💍', label:"Le client événement", profil:'B2C', desc:"mariage, baptême, anniversaire : gros volume ponctuel"},
  pro_resto:         {emoji:'🍽️', label:'Le restaurateur', profil:'B2B', desc:"desserts, mignardises, café gourmand en volume régulier"},
  pro_hotel:         {emoji:'🏨', label:"L'hôtelier", profil:'B2B', desc:"petits-déjeuners, accueils, séminaires"},
  pro_ce:            {emoji:'🏢', label:'Le comité d\'entreprise', profil:'B2B', desc:"événements internes, cadeaux clients/salariés"},
  pro_revendeur:     {emoji:'🛍️', label:'Le revendeur', profil:'B2B', desc:"épicerie fine, salon de thé : dépôt-vente, coffrets"},
  autre:             {emoji:'👤', label:'Autre profil', profil:'B2C', desc:"à définir librement"}
};
const PERSONA_CANAUX = ['Instagram','Facebook','Bouche-à-oreille','Marché','Boutique/vitrine','Flyers locaux','Email','Téléphone','LinkedIn','Site web / Google'];
const PERSONA_OCCASIONS = ['Plaisir perso','Cadeau','Anniversaire','Mariage','Fêtes (Noël, Pâques…)','Événement pro','Réception','Saint-Valentin','Fête des mères'];

// MOTEUR DE SUGGESTIONS : propose canaux, ton, offres, démarchage selon le profil saisi.
// Déterministe (règles métier), pas d'IA — cohérent et explicable.
function personaSuggest(p){
  const arch = PERSONA_ARCHETYPES[p.archetype] || PERSONA_ARCHETYPES.autre;
  const estPro = (p.profil||arch.profil)==='B2B';
  const age = p.age||'';
  const budget = +p.budgetNum||0;
  const occ = p.occasions||[];
  const canaux=[], messages=[], offres=[]; let ton='';
  let demarchage='';

  if(estPro){
    canaux.push('Téléphone','Email','Visite en personne (échantillons)');
    if(p.archetype==='pro_ce') canaux.push('LinkedIn');
    ton = "Professionnel, fiable, orienté bénéfice pour LEUR activité. Mets en avant la régularité, le local et la personnalisation.";
    messages.push("« Un produit artisanal et local qui valorise votre carte / vos événements. »",
      "« Je m'engage sur la régularité et la fraîcheur — vous savez ce que vous servez. »",
      "« On peut créer un parfum signature à votre enseigne. »");
    offres.push('Tarif dégressif par volume','Parfum signature personnalisé','Contrat de livraison récurrente','Dépôt-vente / coffrets co-brandés');
    demarchage = "Apporte des échantillons, demande la bonne personne (chef, gérant, RH), repars avec un contact + une date de relance. Note tout dans Prospection B2B.";
  } else {
    // B2C : adapte selon âge & occasions
    if(age==='18-30'){ canaux.push('Instagram','Bouche-à-oreille','Marché'); ton="Jeune, visuel, spontané. Photos gourmandes, stories, tendances, emojis."; }
    else if(age==='30-50'){ canaux.push('Instagram','Facebook','Marché','Boutique/vitrine'); ton="Chaleureux et qualitatif. Met en avant l'artisanat, les parfums, le fait-maison."; }
    else if(age==='50+'){ canaux.push('Facebook','Bouche-à-oreille','Boutique/vitrine','Flyers locaux'); ton="Rassurant, authentique, proximité. Valorise le savoir-faire et la tradition."; }
    else { canaux.push('Instagram','Facebook','Marché','Bouche-à-oreille'); ton="Chaleureux, gourmand, authentique."; }

    if(occ.includes('Cadeau')||occ.includes('Fêtes (Noël, Pâques…)')||occ.includes('Saint-Valentin')||occ.includes('Fête des mères')){
      offres.push('Coffrets cadeaux soignés','Éditions limitées de saison','Carte-cadeau');
      messages.push("« Offrez un cadeau gourmand et original, fait main au Mans. »");
    }
    if(occ.includes('Mariage')||occ.includes('Réception')||occ.includes('Événement pro')){
      offres.push('Pièce montée de macarons','Devis sur mesure','Dégustation préalable');
      messages.push("« Sublimez votre événement avec une pyramide de macarons personnalisée. »");
    }
    if(occ.includes('Plaisir perso')||occ.length===0){
      offres.push('Formule fidélité (10e boîte offerte)','Box découverte mensuelle','Assortiment du moment');
      messages.push("« Votre petit plaisir de la semaine, toujours frais et fait main. »");
    }
    if(budget>0 && budget<15){ offres.push('Petits formats accessibles (ballotin 6)'); }
    else if(budget>=30){ offres.push('Grands coffrets / assortiments premium'); }
  }
  // déduplique
  const uniq=a=>[...new Set(a)];
  return {canaux:uniq(canaux), ton, messages:uniq(messages), offres:uniq(offres), demarchage};
}

// Vue liste des personas.
async function renderPersonas(){
  const list = await db.personas.orderBy('majTs').reverse().toArray().catch(()=>[]);
  const cards = list.length ? list.map(_personaCard).join('') : '';
  document.getElementById('main').innerHTML = `
   <div class="topbar"><div><h1>Personas clients</h1><p>Connais tes clients pour viser juste</p></div></div>
   <div class="banner">🎯 <div>Un persona, c'est un client-type. Plus tu le connais (qui il est, ce qui le motive, où le toucher), plus ta com et tes offres font mouche. Crée-les à la main ou à partir de tes vrais clients.</div></div>
   <div style="display:flex;gap:8px;margin:10px 0;flex-wrap:wrap">
     <button class="btn gold" style="flex:1;min-width:160px" onclick="personaForm(-1)">＋ Nouveau persona</button>
     <button class="btn ghost" style="flex:1;min-width:160px" onclick="personaFromClientPicker()">👥 Depuis un vrai client</button>
   </div>
   ${list.length ? `<div style="display:flex;flex-direction:column;gap:10px">${cards}</div>`
     : `<div class="panel"><h2>💡 Pourquoi des personas ?</h2><p class="note">Au lieu de parler « à tout le monde » (donc à personne), tu adaptes ton message à chaque type de client. Exemples utiles pour toi :</p>
        ${Object.entries(PERSONA_ARCHETYPES).filter(([k])=>k!=='autre').map(([k,a])=>`<div style="padding:6px 0;border-top:1px solid #f0e9e2;font-size:.86rem"><b>${a.emoji} ${esc(a.label)}</b> <span class="tag" style="font-size:.6rem;background:${a.profil==='B2B'?'#5a7a9a':'#AA7C39'};color:#fff">${a.profil}</span><br><span style="color:#7a6a60">${esc(a.desc)}</span></div>`).join('')}
        <button class="btn gold" style="width:100%;margin-top:10px" onclick="personaForm(-1)">Créer mon premier persona</button></div>`}`;
}
function _personaCard(p){
  const arch=PERSONA_ARCHETYPES[p.archetype]||PERSONA_ARCHETYPES.autre;
  const col=p.couleur||'#AA7C39';
  const estPro=(p.profil||arch.profil)==='B2B';
  return `<div onclick="personaDetail(${p.id})" style="cursor:pointer;background:#fff;border:1px solid var(--hair);border-left:4px solid ${col};border-radius:14px;padding:13px 15px;box-shadow:var(--sh-1)">
    <div style="display:flex;align-items:center;gap:9px">
      <span style="font-size:1.4rem;flex:none">${p.emoji||arch.emoji}</span>
      <div style="flex:1;overflow:hidden">
        <b style="color:var(--bordeaux);display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(p.nom||arch.label)}</b>
        <span style="font-size:.76rem;color:#7a6a60">${esc(arch.label)}${p.age?` · ${esc(p.age)}`:''}</span>
      </div>
      <span class="tag" style="font-size:.62rem;background:${estPro?'#5a7a9a':'#AA7C39'};color:#fff">${estPro?'B2B':'B2C'}</span>
    </div>
    ${p.sourceClientId?`<div style="font-size:.72rem;color:#2e7d32;margin-top:6px">👥 nourri par un vrai client</div>`:''}
  </div>`;
}

// Fiche détaillée d'un persona, avec suggestions de stratégie.
async function personaDetail(id){
  const p=await db.personas.get(id); if(!p){ toast('Persona introuvable'); return; }
  const arch=PERSONA_ARCHETYPES[p.archetype]||PERSONA_ARCHETYPES.autre;
  const sug=personaSuggest(p);
  const chips=(arr,col)=>(arr&&arr.length)?arr.map(x=>`<span class="tag" style="background:${col||'#f0e9de'};color:${col?'#fff':'#5a4a42'};font-size:.7rem;margin:2px">${esc(x)}</span>`).join(''):'<span class="note">—</span>';
  const liste=(arr)=>(arr&&arr.length)?arr.map(x=>`<div style="font-size:.84rem;padding:3px 0 3px 14px;position:relative;color:#5a4a42"><span style="position:absolute;left:0">•</span>${esc(x)}</div>`).join(''):'<span class="note">—</span>';
  // fusion suggestions + saisies manuelles (manuel prioritaire à l'affichage, suggestions en complément)
  const canaux = (p.canaux&&p.canaux.length)?p.canaux:sug.canaux;
  const offres = (p.offres&&p.offres.length)?p.offres:sug.offres;
  const ton = p.ton||sug.ton;
  const messages = (p.messages&&p.messages.length)?p.messages:sug.messages;
  const demarchage = p.demarchage||sug.demarchage;
  openModal(`<div style="max-height:78vh;overflow:auto;padding-right:2px">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
      <span style="font-size:2rem">${p.emoji||arch.emoji}</span>
      <div><h3 style="margin:0">${esc(p.nom||arch.label)}</h3><span style="font-size:.78rem;color:#7a6a60">${esc(arch.label)} · ${(p.profil||arch.profil)}</span></div>
    </div>
    ${p.sourceClientId?`<p class="note" style="color:#2e7d32">👥 Ce persona a été nourri par les données d'un vrai client.</p>`:''}

    <div class="panel" style="margin:8px 0"><div style="font-weight:700;color:var(--bordeaux);margin-bottom:4px">🧍 Identité</div>
      <div style="font-size:.84rem;color:#5a4a42">${[p.age?`Âge : ${esc(p.age)}`:'', p.budget?`Budget : ${esc(p.budget)}`:'', p.frequenceType?`Fréquence : ${esc(p.frequenceType)}`:''].filter(Boolean).join(' · ')||'—'}</div>
      ${(p.occasions&&p.occasions.length)?`<div style="margin-top:6px">${chips(p.occasions)}</div>`:''}
      ${(p.parfumsAimes&&p.parfumsAimes.length)?`<div style="margin-top:6px"><span style="font-size:.74rem;color:#9a8a82">Parfums aimés : </span>${chips(p.parfumsAimes,'#c9a227')}</div>`:''}
    </div>

    ${(p.motivations&&p.motivations.length)||(p.freins&&p.freins.length)?`<div class="panel" style="margin:8px 0"><div style="font-weight:700;color:var(--bordeaux);margin-bottom:4px">💭 Motivations & freins</div>
      ${(p.motivations&&p.motivations.length)?`<div style="font-size:.74rem;color:#2e7d32;font-weight:600;margin-top:4px">Ce qui le motive</div>${liste(p.motivations)}`:''}
      ${(p.freins&&p.freins.length)?`<div style="font-size:.74rem;color:#b3261e;font-weight:600;margin-top:4px">Ses freins</div>${liste(p.freins)}`:''}
    </div>`:''}

    <div class="panel" style="margin:8px 0;background:#fffdf8;border:1px solid #e8dcc0"><div style="font-weight:700;color:#AA7C39;margin-bottom:4px">📣 Stratégie de com suggérée</div>
      <div style="font-size:.74rem;color:#9a8a82;margin-bottom:2px">Où le toucher</div><div style="margin-bottom:6px">${chips(canaux,'#5a7a9a')}</div>
      <div style="font-size:.74rem;color:#9a8a82;margin-bottom:2px">Le bon ton</div><div style="font-size:.84rem;color:#5a4a42;margin-bottom:6px">${esc(ton)||'—'}</div>
      <div style="font-size:.74rem;color:#9a8a82;margin-bottom:2px">Messages qui marchent</div>${liste(messages)}
    </div>

    <div class="panel" style="margin:8px 0"><div style="font-weight:700;color:var(--bordeaux);margin-bottom:4px">🛍️ Offres adaptées</div>${liste(offres)}</div>

    ${demarchage?`<div class="panel" style="margin:8px 0"><div style="font-weight:700;color:var(--bordeaux);margin-bottom:4px">🤝 Angle de démarchage</div><div style="font-size:.84rem;color:#5a4a42">${esc(demarchage)}</div></div>`:''}

    ${p.notes?`<div class="panel" style="margin:8px 0"><div style="font-weight:700;color:var(--bordeaux);margin-bottom:4px">📝 Notes</div><div style="font-size:.84rem;color:#5a4a42;white-space:pre-wrap">${esc(p.notes)}</div></div>`:''}
    </div>
    <div class="modal-actions">
      <button class="btn ghost" style="color:#b3261e" onclick="personaDelete(${id})">🗑</button>
      <button class="btn ghost" onclick="personaForm(${id})">✎ Éditer</button>
      <button class="btn gold" onclick="closeModal()">Fermer</button>
    </div>`);
}

// Atelier guidé : formulaire de création / édition d'un persona.
async function personaForm(id){
  const p = id>=0 ? await db.personas.get(id) : null;
  const isNew=!p;
  const v = p || {nom:'', emoji:'', archetype:'gourmand_quartier', profil:'B2C', age:'', budget:'', budgetNum:'', frequenceType:'', occasions:[], parfumsAimes:[], motivations:[], freins:[], canaux:[], ton:'', messages:[], offres:[], demarchage:'', notes:'', couleur:'#AA7C39'};
  // parfums dispo pour cocher les préférés
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const archOpts=Object.entries(PERSONA_ARCHETYPES).map(([k,a])=>`<option value="${k}" ${v.archetype===k?'selected':''}>${a.emoji} ${esc(a.label)}</option>`).join('');
  const occChecks=PERSONA_OCCASIONS.map(o=>`<label style="display:inline-flex;align-items:center;gap:4px;font-size:.8rem;margin:2px 6px 2px 0"><input type="checkbox" class="pe_occ" value="${esc(o)}" ${(v.occasions||[]).includes(o)?'checked':''}> ${esc(o)}</label>`).join('');
  const canChecks=PERSONA_CANAUX.map(c=>`<label style="display:inline-flex;align-items:center;gap:4px;font-size:.8rem;margin:2px 6px 2px 0"><input type="checkbox" class="pe_can" value="${esc(c)}" ${(v.canaux||[]).includes(c)?'checked':''}> ${esc(c)}</label>`).join('');
  const parfChecks=recipes.map(r=>`<label style="display:inline-flex;align-items:center;gap:4px;font-size:.8rem;margin:2px 6px 2px 0"><input type="checkbox" class="pe_parf" value="${esc(r.produitNom)}" ${(v.parfumsAimes||[]).includes(r.produitNom)?'checked':''}> ${esc(r.produitNom)}</label>`).join('');
  openModal(`<div style="max-height:78vh;overflow:auto;padding-right:2px">
    <h3>${isNew?'➕ Nouveau persona':'✎ '+esc(v.nom||'Persona')}</h3>
    <p class="note" style="margin-bottom:8px">Remplis ce que tu sais. L'app suggérera automatiquement canaux, ton et offres — tu pourras compléter.</p>
    <div class="row2">
      <div class="field"><label>Nom du persona *</label><input id="pe_nom" value="${esc(v.nom)}" placeholder="ex : Sophie, la maman gourmande"></div>
      <div class="field"><label>Emoji</label><input id="pe_emoji" value="${esc(v.emoji)}" placeholder="🧁" maxlength="4"></div>
    </div>
    <div class="row2">
      <div class="field"><label>Type de client</label><select id="pe_arch" onchange="_personaArchSync()">${archOpts}</select></div>
      <div class="field"><label>Profil</label><select id="pe_profil">
        <option value="B2C" ${v.profil==='B2C'?'selected':''}>Particulier (B2C)</option>
        <option value="B2B" ${v.profil==='B2B'?'selected':''}>Professionnel (B2B)</option>
      </select></div>
    </div>
    <div class="row2">
      <div class="field"><label>Tranche d'âge</label><select id="pe_age">
        ${['','18-30','30-50','50+'].map(a=>`<option value="${a}" ${v.age===a?'selected':''}>${a||'—'}</option>`).join('')}
      </select></div>
      <div class="field"><label>Fréquence</label><input id="pe_freq" value="${esc(v.frequenceType)}" placeholder="ex : hebdo, mensuel, ponctuel"></div>
    </div>
    <div class="row2">
      <div class="field"><label>Budget (texte)</label><input id="pe_budget" value="${esc(v.budget)}" placeholder="ex : 15-25 €/achat"></div>
      <div class="field"><label>Budget moyen (€, pour suggestions)</label><input type="number" id="pe_budgetnum" value="${esc(v.budgetNum||'')}" placeholder="ex : 20"></div>
    </div>
    <div class="field"><label>Occasions d'achat</label><div style="display:flex;flex-wrap:wrap">${occChecks}</div></div>
    ${recipes.length?`<div class="field"><label>Parfums qu'il aime</label><div style="display:flex;flex-wrap:wrap">${parfChecks}</div></div>`:''}
    <div class="field"><label>Ce qui le motive <span style="color:#9a8a82;font-weight:400">— une idée par ligne</span></label><textarea id="pe_motiv" rows="2" placeholder="le plaisir, l'originalité, le local…">${esc((v.motivations||[]).join('\n'))}</textarea></div>
    <div class="field"><label>Ses freins <span style="color:#9a8a82;font-weight:400">— une idée par ligne</span></label><textarea id="pe_freins" rows="2" placeholder="le prix, la distance, méconnaissance…">${esc((v.freins||[]).join('\n'))}</textarea></div>
    <div class="field"><label>Canaux pour le toucher <span style="color:#9a8a82;font-weight:400">— laisse vide pour suggestion auto</span></label><div style="display:flex;flex-wrap:wrap">${canChecks}</div></div>
    <div class="field"><label>Ton de com <span style="color:#9a8a82;font-weight:400">— vide = suggestion auto</span></label><textarea id="pe_ton" rows="2" placeholder="chaleureux, jeune, pro…">${esc(v.ton)}</textarea></div>
    <div class="field"><label>Notes libres</label><textarea id="pe_notes" rows="2">${esc(v.notes)}</textarea></div>
    </div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="personaSave(${id})">${isNew?'Créer':'Enregistrer'}</button>
    </div>`);
}
// Quand on change d'archétype, aligne le profil par défaut.
function _personaArchSync(){
  const k=document.getElementById('pe_arch').value;
  const a=PERSONA_ARCHETYPES[k]; if(a){ const sel=document.getElementById('pe_profil'); if(sel) sel.value=a.profil; }
}
async function personaSave(id){
  const nom=(document.getElementById('pe_nom').value||'').trim();
  if(!nom){ toast('Donne un nom à ton persona'); return; }
  const lines=el=>{const t=(document.getElementById(el).value||'').trim();return t?t.split('\n').map(x=>x.trim()).filter(Boolean):[];};
  const checks=cls=>Array.from(document.querySelectorAll('.'+cls+':checked')).map(c=>c.value);
  const data={
    nom,
    emoji:(document.getElementById('pe_emoji').value||'').trim(),
    archetype:document.getElementById('pe_arch').value,
    profil:document.getElementById('pe_profil').value,
    age:document.getElementById('pe_age').value,
    frequenceType:(document.getElementById('pe_freq').value||'').trim(),
    budget:(document.getElementById('pe_budget').value||'').trim(),
    budgetNum:+document.getElementById('pe_budgetnum').value||'',
    occasions:checks('pe_occ'),
    parfumsAimes:checks('pe_parf'),
    motivations:lines('pe_motiv'),
    freins:lines('pe_freins'),
    canaux:checks('pe_can'),
    ton:(document.getElementById('pe_ton').value||'').trim(),
    notes:(document.getElementById('pe_notes').value||'').trim(),
    majTs:Date.now()
  };
  if(id>=0){ await db.personas.update(id,data); toast('Persona mis à jour ✓'); }
  else { data.createdTs=Date.now(); data.couleur='#AA7C39'; await db.personas.add(data); toast('Persona créé ✓'); }
  closeModal();
  renderPersonas();
}
async function personaDelete(id){
  const p=await db.personas.get(id); if(!p) return;
  if(!confirm(`Supprimer le persona « ${p.nom}» ?`)) return;
  await db.personas.delete(id);
  closeModal(); toast('Persona supprimé'); renderPersonas();
}
// Sélecteur : choisir un vrai client pour pré-remplir un persona avec ses données.
async function personaFromClientPicker(){
  const clients=await db.clients.toArray().catch(()=>[]);
  if(!clients.length){ toast('Aucun client enregistré pour l\'instant'); return; }
  const rows=clients.map(c=>`<div class="sum-box lnk" style="cursor:pointer" onclick="personaFromClient(${c.id})"><span>👤 ${esc(c.nom)}</span><b>›</b></div>`).join('');
  openModal(`<h3>👥 Créer un persona depuis un client</h3>
    <p class="note" style="margin-bottom:8px">Choisis un client : l'app pré-remplit le persona avec son panier moyen, son parfum préféré et sa fréquence réelle.</p>
    <div style="max-height:60vh;overflow:auto">${rows}</div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button></div>`);
}
async function personaFromClient(clientId){
  let d=null;
  try{ d=await getClientDashboardData(clientId); }catch(e){ toast('Impossible de lire ce client'); return; }
  const c=d.client;
  // Devine l'archétype : pro si type 'pro', sinon gourmand/offreur selon panier
  const estPro=(c.type==='pro');
  let archetype = estPro ? 'pro_resto' : (d.panierMoyen>=40 ? 'offreur_cadeau' : 'gourmand_quartier');
  const data={
    nom:`${c.nom} (type)`,
    emoji: estPro?'🍽️':'🧁',
    archetype, profil: estPro?'B2B':'B2C',
    age:'', frequenceType: d.frequenceTxt||'',
    budget: d.panierMoyen?`~${euro(d.panierMoyen)}/commande`:'',
    budgetNum: d.panierMoyen?Math.round(d.panierMoyen):'',
    occasions:[], parfumsAimes: d.parfumPrefere?[d.parfumPrefere]:[],
    motivations:[], freins:[], canaux:[], ton:'', messages:[], offres:[],
    notes:`Nourri depuis le client « ${c.nom} » : ${d.nbCommandes} commande(s), CA ${euro(d.caTotal)}${d.badge?`, ${d.badge.label}`:''}.`,
    sourceClientId:clientId, couleur:'#2e7d32', createdTs:Date.now(), majTs:Date.now()
  };
  const id=await db.personas.add(data);
  closeModal();
  toast('Persona créé depuis le client ✓');
  personaForm(id);   // ouvre l'édition pour compléter/affiner
}

// [v1323] POINT MORT — la question la plus fondamentale d'une activité, et elle n'existait nulle part.
// L'app savait dire « ce parfum est rentable à l'unité », mais jamais « combien dois-je vendre chaque
// mois pour ne pas perdre d'argent ». Or Benjamin a des charges FIXES (assurance, abonnements, énergie,
// matériel) qui tombent que le mois soit bon ou mauvais.
//
// Principe (comptabilité de base) :
//     point mort (en macarons) = charges fixes mensuelles ÷ marge de contribution unitaire
// où la marge de contribution = prix de vente − coûts VARIABLES (matières, consommables, main-d'œuvre,
// charges sociales). C'est ce que chaque macaron vendu « rapporte » pour éponger les charges fixes.
//
// Renvoie tout ce qu'il faut pour VÉRIFIER le chiffre à la main (exigence de traçabilité) :
//   { chargesFixesMensuelles, margeUnitaire, macaronsParMois, macaronsParJour, caMinimum, atteignable }
function computePointMort(chargesFixesMensuelles, margeUnitaire, prixVenteMoyen){
  const fixes = Math.max(0, +chargesFixesMensuelles || 0);
  const marge = +margeUnitaire || 0;

  // Marge de contribution nulle ou négative → aucun volume ne peut couvrir les charges fixes.
  // Vendre PLUS aggraverait même la perte. Il faut d'abord corriger le prix ou les coûts.
  if(!(marge > 0)){
    return { chargesFixesMensuelles: fixes, margeUnitaire: marge,
             macaronsParMois: null, macaronsParJour: null, caMinimum: null,
             atteignable: false,
             raison: marge < 0
               ? 'Chaque macaron vendu te fait PERDRE de l\'argent : aucun volume ne couvrira tes charges fixes.'
               : 'Marge unitaire nulle : impossible de couvrir la moindre charge fixe.' };
  }
  if(fixes === 0){
    return { chargesFixesMensuelles: 0, margeUnitaire: marge,
             macaronsParMois: 0, macaronsParJour: 0, caMinimum: 0,
             atteignable: true, raison: 'Aucune charge fixe déclarée.' };
  }

  const macaronsParMois = Math.ceil(fixes / marge);
  const px = +prixVenteMoyen || 0;
  return {
    chargesFixesMensuelles: money2(fixes),
    margeUnitaire: money2(marge),
    macaronsParMois,
    macaronsParJour: Math.ceil(macaronsParMois / 30),
    caMinimum: px > 0 ? money2(macaronsParMois * px) : null,
    atteignable: true,
    raison: null
  };
}

// Total des charges FIXES mensuelles : somme des charges récurrentes actives.
// (Une charge récurrente est, par définition, un engagement qui tombe chaque mois.)
function chargesFixesMensuelles(){
  try{
    const models = (typeof getRecurringCharges==='function') ? getRecurringCharges() : [];
    return money2(models
      .filter(m => m && m.actif !== false && (+m.montant || 0) > 0)
      .reduce((s, m) => s + (+m.montant || 0), 0));
  }catch(e){ swallow(e,'chargesFixesMensuelles'); return 0; }
}

// ============================================================================
//  [v1324] LE POINT MORT DISAIT LA MOITIÉ DE LA VÉRITÉ — trois coûts oubliés.
// ----------------------------------------------------------------------------
//  Le point mort de v1323 divisait les charges fixes par `margeUnit`. Or, dans
//  analyzeFlavorProfitability :
//        margeUnit = prixVenteMoyen − coutRevientUnit
//  et coutRevientUnit = matières + consommables + main-d'œuvre D'ATELIER. C'est tout.
//  Le texte explicatif affirmait pourtant que les charges sociales étaient déduites :
//  elles ne l'étaient PAS. Le point mort affiché était donc SOUS-ESTIMÉ, et sa
//  justification était fausse — le pire des deux mondes pour un chiffre qu'on doit
//  pouvoir refaire à la main.
//
//  TROIS COÛTS BIEN RÉELS manquaient à l'appel, tous payés par Benjamin, aucun compté :
//
//   1. LES CHARGES SOCIALES (URSSAF). Elles se prélèvent sur CHAQUE EURO ENCAISSÉ.
//      C'est donc un coût VARIABLE, proportionnel aux ventes : sa place est dans la
//      marge de contribution, pas ailleurs.
//
//   2. L'IMPÔT SUR LE REVENU. En micro-BIC, la base imposable est un pourcentage
//      forfaitaire du CA (CA × (1 − abattement)), puis la tranche marginale s'applique.
//      Résultat : l'IR aussi est PROPORTIONNEL AU CA. C'est un coût variable, et il
//      sort du compte en banque comme les autres.
//
//   3. LES HEURES HORS-ATELIER. Le coût de revient ne paie que la main-d'œuvre de
//      PRODUCTION. Mais l'administratif, les courses, les déplacements, la prospection
//      et la préparation des marchés — que la pointeuse mesure fidèlement — ne sont
//      payés NULLE PART : ni dans le coût de revient, ni dans les charges fixes. Ces
//      heures sont, littéralement, du bénévolat. Ce sont pourtant des charges de
//      structure aussi réelles qu'une assurance.
//
//  On ne remplace pas l'ancien chiffre par un nouveau tombé du ciel : on affiche une
//  CASCADE, où chaque marche ajoute UN oubli et montre ce qu'il coûte en macarons. Le
//  saut est ainsi entièrement attribuable, marche par marche (exigence de traçabilité).
//  `computePointMort` (v1323) n'est PAS modifiée : elle reste le moteur, on lui donne
//  simplement des entrées enfin honnêtes.
// ============================================================================

// BRIQUE 1 — la marge de contribution RÉELLE d'un macaron.
// Ce qui reste vraiment pour éponger les charges fixes, une fois payés TOUS les coûts
// qui suivent la vente (matière, temps d'atelier, URSSAF, impôt).
function margeContributionUnitaire(prixVenteMoyen, coutRevientUnit, tauxSocialPct, abattementIrPct, trancheIrPct){
  const px  = Math.max(0, +prixVenteMoyen || 0);
  const cr  = Math.max(0, +coutRevientUnit || 0);
  const tS  = Math.max(0, +tauxSocialPct || 0);
  const ab  = Math.min(100, Math.max(0, +abattementIrPct || 0));
  const tIR = Math.max(0, +trancheIrPct || 0);

  const margeBrute     = money2(px - cr);                 // ce que v1323 utilisait (à tort, seul)
  const coutSocialUnit = money2(px * tS / 100);           // URSSAF : % du CA → variable
  const baseIrUnit     = money2(px * (1 - ab / 100));     // micro-BIC : base forfaitaire
  const coutIrUnit     = money2(baseIrUnit * tIR / 100);  // IR : % de la base → variable aussi
  const margeContribution = money2(margeBrute - coutSocialUnit - coutIrUnit);

  return {
    prixVenteMoyen: money2(px), coutRevientUnit: money2(cr), margeBrute,
    tauxSocialPct: tS, coutSocialUnit,
    abattementIrPct: ab, baseIrUnit, trancheIrPct: tIR, coutIrUnit,
    margeContribution
  };
}

// [v1332] En dessous de ce seuil, le temps hors-atelier pointé est jugé IMPLAUSIBLE — non pas faux,
// mais trop maigre pour porter un point mort qui se prétend complet. 8 h/mois, c'est 2 h par semaine
// pour l'administratif + les courses + les déplacements + la prospection + la prépa marché réunis :
// un plancher déjà très généreux. En dessous, on avertit plutôt que de laisser croire.
const SEUIL_HEURES_HORS_ATELIER = 8;

// BRIQUE 2 — le coût mensuel du TEMPS HORS-ATELIER (pointeuse).
// Pure : reçoit les sessions, ne lit aucune base. N'INVENTE RIEN — si rien n'est pointé,
// elle le dit franchement plutôt que de rendre 0 € (0 € serait un mensonge : ces heures
// existent, elles ne sont simplement pas mesurées).
// Le taux retenu est celui SAISI sur la session ; à défaut, le taux horaire des réglages.
function coutTempsHorsProdMensuel(sessions, tauxHoraireDefaut){
  const tauxDef = Math.max(0, +tauxHoraireDefaut || 0);
  const heuresDe = s => (+s.dureeHeures > 0) ? +s.dureeHeures : ((+s.dureeMin || 0) / 60);
  const list = (sessions || []).filter(s => s && heuresDe(s) > 0);

  if(!list.length){
    return { fiable:false, heuresTotal:0, coutTotal:0, moisObserves:0, heuresParMois:0,
             coutParMois:0, parActivite:[], nbSessions:0,
             raison:'Aucun temps hors-atelier pointé. Ces heures existent pourtant (administratif, courses, déplacements, prospection) et ne sont payées nulle part : ton point mort réel est donc PLUS HAUT que celui affiché, d\'un montant qu\'on ne peut pas encore chiffrer.' };
  }

  // Fenêtre réellement observée : du premier au dernier jour pointé (minimum 1 mois, pour
  // ne pas transformer 3 jours de pointage en un « coût mensuel » démesuré par extrapolation).
  const dates = list.map(s => (s.date || '').slice(0, 10)).filter(Boolean).sort();
  let moisObserves = 1;
  if(dates.length){
    const d0 = new Date(dates[0] + 'T00:00:00');
    const d1 = new Date(dates[dates.length - 1] + 'T00:00:00');
    const jours = Math.round((d1 - d0) / 86400000) + 1;
    moisObserves = Math.max(1, Math.round(jours / 30 * 100) / 100);
  }

  let heuresTotal = 0, coutTotal = 0;
  const parAct = {};
  list.forEach(s => {
    const h = heuresDe(s);
    const taux = (+s.tauxHoraire > 0) ? +s.tauxHoraire : tauxDef;
    const c = h * taux;
    heuresTotal += h; coutTotal += c;
    const k = s.activite || 'Non précisé';
    (parAct[k] ||= { activite:k, heures:0, cout:0 });
    parAct[k].heures += h; parAct[k].cout += c;
  });

  const parActivite = Object.values(parAct)
    .map(a => ({ activite:a.activite, heures:round3(a.heures), cout:money2(a.cout) }))
    .sort((a, b) => b.cout - a.cout);

  const heuresParMois = round3(heuresTotal / moisObserves);

  // [v1332] LA PLAUSIBILITÉ, pas seulement la présence.
  // AVANT : `fiable:true` dès qu'UNE SEULE session était pointée. Le point mort se présentait
  // alors comme « tout payé »… en reposant sur presque rien. Chez Benjamin : 3 h 20 par mois pour
  // TOUT l'administratif, les courses, les déplacements, la prospection et la prépa marché.
  // C'est moins de 50 minutes par semaine : manifestement sous-pointé.
  // Or un chiffre bâti sur une mesure dérisoire n'est pas « fiable » — il est juste PRÉSENT.
  // Confondre les deux, c'est fabriquer exactement la fausse confiance que cette série traque.
  const plausible = heuresParMois >= SEUIL_HEURES_HORS_ATELIER;

  return {
    fiable:true, raison:null,
    heuresTotal: round3(heuresTotal), coutTotal: money2(coutTotal),
    moisObserves, nbSessions: list.length,
    heuresParMois,
    coutParMois: money2(coutTotal / moisObserves),
    plausible,
    alerte: plausible ? null
      : `Seulement ${heuresParMois} h par mois sont pointées hors atelier. Pour TOUT l'administratif, les courses, les déplacements, la prospection et la prépa marché, c'est très peu — ces heures existent, mais elles ne sont pas mesurées. Ton point mort réel est donc PLUS HAUT que celui affiché.`,
    parActivite
  };
}

// BRIQUE 3 — LA CASCADE. Quatre marches, du chiffre confortable au chiffre vrai.
// Chaque marche ajoute UN oubli et montre ce qu'il coûte, pour que le saut final soit
// entièrement attribuable (et donc vérifiable à la main).
function computePointMortVerite(p){
  p = p || {};
  const fixes = Math.max(0, +p.chargesFixesMensuelles || 0);
  const tempsHorsProd = Math.max(0, +p.coutTempsHorsProdMensuel || 0);
  const M = margeContributionUnitaire(p.prixVenteMoyen, p.coutRevientUnit,
                                      p.tauxSocialPct, p.abattementIrPct, p.trancheIrPct);
  const px = M.prixVenteMoyen;

  // Marche 1 — ce que l'app affichait (v1323) : charges fixes ÷ marge BRUTE.
  const etape1 = computePointMort(fixes, M.margeBrute, px);
  // Marche 2 — on déduit l'URSSAF de la marge (coût variable oublié).
  const margeApresSocial = money2(M.margeBrute - M.coutSocialUnit);
  const etape2 = computePointMort(fixes, margeApresSocial, px);
  // Marche 3 — on déduit l'impôt sur le revenu (variable lui aussi).
  const etape3 = computePointMort(fixes, M.margeContribution, px);
  // Marche 4 — on paie enfin les heures hors-atelier (charge de structure oubliée).
  const coutStructure = money2(fixes + tempsHorsProd);
  const etape4 = computePointMort(coutStructure, M.margeContribution, px);

  const ancien = etape1;   // le chiffre rassurant
  const reel   = etape4;   // le chiffre vrai

  // [v1332] LE TAUX DE SENSIBILITÉ — l'inconnue devient exploitable.
  // Le temps hors-atelier est le poste le plus sous-mesuré (Benjamin ne pointe pas ses courses).
  // Plutôt que de subir cette incertitude, on la CHIFFRE : combien de macarons chaque heure NON
  // POINTÉE ajoute-t-elle au point mort ? Réponse : taux horaire ÷ marge de contribution.
  // À 12 €/h pour 1,07 € de marge, une heure oubliée = 12 macarons de point mort escamotés.
  // Benjamin peut alors faire le calcul lui-même : « je passe plutôt 15 h/mois → +140 macarons ».
  // C'est le contraire d'un chiffre inventé : c'est un TAUX exact, appliqué à SON estimation.
  const tauxH = Math.max(0, +p.tauxHoraire || 0);
  const macaronsParHeureHorsAtelier = (M.margeContribution > 0 && tauxH > 0)
    ? Math.ceil(tauxH / M.margeContribution) : null;
  const ecartMacarons = (reel.atteignable && ancien.atteignable
                          && reel.macaronsParMois != null && ancien.macaronsParMois != null)
    ? (reel.macaronsParMois - ancien.macaronsParMois) : null;

  return {
    marge: M,
    chargesFixesMensuelles: money2(fixes),
    coutTempsHorsProdMensuel: money2(tempsHorsProd),
    coutStructureMensuel: coutStructure,
    cascade: [
      { cle:'brut',   label:'Charges fixes ÷ marge brute',                 marge:M.margeBrute,         charges:money2(fixes), pm:etape1, oubli:null },
      { cle:'social', label:'… en payant les charges sociales URSSAF',     marge:margeApresSocial,     charges:money2(fixes), pm:etape2, oubli:M.coutSocialUnit },
      { cle:'ir',     label:'… en payant l\'impôt sur le revenu',          marge:M.margeContribution,  charges:money2(fixes), pm:etape3, oubli:M.coutIrUnit },
      { cle:'temps',  label:'… en payant tes heures hors-atelier',         marge:M.margeContribution,  charges:coutStructure, pm:etape4, oubli:money2(tempsHorsProd) }
    ],
    ancien, reel, ecartMacarons,
    tauxHoraire: tauxH,
    macaronsParHeureHorsAtelier,   // [v1332] ce qu'UNE heure non pointée coûte au point mort
    atteignable: reel.atteignable, raison: reel.raison
  };
}

async function renderProfit(){
  const [orders, clients, recipes, recipeItems, lots, _mats, _markets, _mm, _prods] = await Promise.all([
    db.orders.toArray(), db.clients.toArray(), db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray(),
    db.materials.toArray().catch(()=>[]),
    db.markets.toArray().catch(()=>[]),
    (db.marketMoves?db.marketMoves.toArray():Promise.resolve([])).catch(()=>[]),
    db.productions.toArray().catch(()=>[])
  ]);
  const clName=id=>(clients.find(c=>c.id===id)||{}).nom||'—';
  // Analyse de marge (même moteur que la carte d'accueil) → encart « leviers ».
  let _leviersHtml='';
  try{
    const _A = analyzeFlavorProfitability({recipes, recipeItems, lots, mats:_mats, orders, markets:_markets, marketMoves:_mm, productions:_prods, settings:getSettings()});
    const _recs = flavorRecommendations(_A, {recipes, recipeItems, lots, mats:_mats, orders, markets:_markets, marketMoves:_mm, productions:_prods, settings:getSettings()});
    _leviersHtml = _margeLeviersHtml(_A, _recs);
  }catch(e){ console.error('leviers marge', e); _leviersHtml=''; }

  // marge par commande (toutes commandes confirmées)
  const withM = orders.map(o=>({o, m:computeOrderMargins(o, recipes, recipeItems, lots)}));

  // --- par client ---
  const byClient={};
  withM.forEach(({o,m})=>{
    const k=o.clientId||0;
    (byClient[k] ||= {clientId:k, nom:clName(k), ca:0, nb:0, brute:0, nette:0, aReprise:false});
    const c=byClient[k]; c.ca=money2(c.ca+m.ca); c.nb++; c.brute=money2(c.brute+m.margeBrute); c.nette=money2(c.nette+m.margeNette);
    if((orderToLines(o)||[]).some(l=>l.type==='histo')) c.aReprise=true;
  });
  const clientRows=Object.values(byClient).map(c=>{
    c.panier=c.nb>0?money2(c.ca/c.nb):0;
    c.tauxNet=c.ca>0?Math.round(c.nette/c.ca*1000)/10:0;
    c.scale=profitScale(c.tauxNet);
    return c;
  }).sort((a,b)=>b.ca-a.ca);

  // --- par événement ---
  const eventsM = withM.filter(({o})=>orderIsEvent(o)).map(({o,m})=>{
    const sc=profitScale(m.tauxNet);
    return {o, m, sc, nom:clName(o.clientId)};
  }).sort((a,b)=>b.m.ca-a.m.ca);

  const clientTable = clientRows.length?`<div style="display:flex;flex-direction:column;gap:10px">${clientRows.map((c,idx)=>{
      const tauxClamp=Math.max(0,Math.min(100,c.tauxNet||0));
      const medaille = idx===0?'🥇':idx===1?'🥈':idx===2?'🥉':`<span style="display:inline-flex;width:22px;height:22px;align-items:center;justify-content:center;background:#f0e9de;border-radius:50%;font-size:.72rem;color:#9a8a82;font-weight:700">${idx+1}</span>`;
      return `<div onclick="${c.clientId?`clientFiche(${c.clientId})`:''}" style="${c.clientId?'cursor:pointer;':''}background:#fff;border:1px solid var(--hair);border-left:4px solid ${c.scale.col};border-radius:14px;padding:13px 15px;box-shadow:var(--sh-1)">
        <div style="display:flex;align-items:center;gap:9px;margin-bottom:10px">
          <span style="flex:none">${medaille}</span>
          <b style="flex:1;font-size:1rem;color:var(--bordeaux);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.nom)}${c.aReprise?` <span style="color:#9a8a82;font-size:.66rem;font-weight:400" title="Contient des commandes de reprise : marge estimée">~ estimé</span>`:''}</b>
          <span class="tag" style="background:${c.scale.col};color:#fff;font-size:.66rem">${c.scale.label}</span>
        </div>
        <div style="display:flex;gap:6px;text-align:center;margin-bottom:10px">
          <div style="flex:1"><div style="font-size:.62rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">CA</div><div style="font-weight:700;color:var(--bordeaux);font-size:.92rem">${euro(c.ca)}</div></div>
          <div style="flex:1;border-left:1px solid var(--hair)"><div style="font-size:.62rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Cmd</div><div style="font-weight:700;color:var(--bordeaux);font-size:.92rem">${c.nb}</div></div>
          <div style="flex:1;border-left:1px solid var(--hair)"><div style="font-size:.62rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Panier</div><div style="font-weight:700;color:var(--bordeaux);font-size:.92rem">${euro(c.panier)}</div></div>
          <div style="flex:1;border-left:1px solid var(--hair)"><div style="font-size:.62rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Marge nette</div><div style="font-weight:700;font-size:.92rem;color:${c.nette>=0?'#3f7d52':'#b3261e'}">${euro(c.nette)}</div></div>
        </div>
        <div style="display:flex;align-items:center;gap:8px">
          <div style="flex:1;height:8px;background:#f0e9de;border-radius:5px;overflow:hidden"><div style="width:${tauxClamp}%;height:100%;background:${c.scale.col}"></div></div>
          <span style="font-size:.78rem;font-weight:700;color:${c.scale.col};flex:none">${c.tauxNet}%</span>
        </div>
      </div>`;
    }).join('')}</div>`
    :'<div class="empty">Aucune commande.</div>';

  const eventCards = eventsM.length?eventsM.map(({o,m,sc,nom})=>`<div class="panel" style="margin:8px 0;border-left:4px solid ${sc.col}">
      <div style="display:flex;justify-content:space-between;align-items:flex-start"><div><b>${esc(nom)}</b> <span style="color:#9a8a82;font-size:.8rem">· n°${esc(orderNumber(o))} · ${fmtDate(o.date)}</span></div>
        <span class="tag" style="background:${sc.col};color:#fff">${sc.label}</span></div>
      <div class="sum-box"><span>Chiffre d'affaires</span><b>${euro(m.ca)}</b></div>
      <div class="sum-box"><span>Coût production (matières + emballages)</span><b>${euro(money2(m.coutMat+m.coutEmb))}</b></div>
      <div class="sum-box"><span>Marge brute</span><b>${euro(m.margeBrute)} <span style="color:#9a8a82;font-weight:400">(${m.tauxBrut}%)</span></b></div>
      <div class="sum-box"><span>Charges sociales</span><b>−${euro(m.chargesSociales)}</b></div>
      <div class="sum-box"><span><b>Marge nette</b></span><b style="color:${m.margeNette>=0?'#3f7d52':'var(--red,#b3261e)'}">${euro(m.margeNette)} (${m.tauxNet}%)</b></div>
    </div>`).join('')
    :'<p class="note">Aucune commande événementielle.</p>';

  // [v1324] POINT MORT — LA CASCADE. Le chiffre de v1323 oubliait l'URSSAF, l'impôt et tes
  // heures hors-atelier. On ne le remplace pas en silence : on montre les quatre marches, du
  // chiffre rassurant au chiffre vrai, pour que chaque euro d'écart soit attribuable.
  // Moyennes PONDÉRÉES par les ventes (un parfum vendu 500 fois ne pèse pas comme un vendu 5 fois).
  let _pmHtml = '';
  try{
    const _s   = getSettings();
    const _fx  = chargesFixesMensuelles();
    const _ws  = await db.workSessions.toArray().catch(()=>[]);
    const _tps = coutTempsHorsProdMensuel(_ws, _s.laborRate);

    const _A2 = analyzeFlavorProfitability({recipes, recipeItems, lots, mats:_mats, orders, markets:_markets, marketMoves:_mm, productions:_prods, settings:_s});
    const _vendus = (_A2.rows||[]).filter(r=>r.piecesVendues>0 && r.prixVenteMoyen!=null);
    const _totPieces = _vendus.reduce((s,r)=>s+r.piecesVendues, 0);
    const _prixMoy = _totPieces>0
      ? money2(_vendus.reduce((s,r)=>s + (r.prixVenteMoyen||0)*r.piecesVendues, 0) / _totPieces) : 0;
    const _coutMoy = _totPieces>0
      ? money2(_vendus.reduce((s,r)=>s + ((r.cost&&r.cost.coutRevientUnit)||0)*r.piecesVendues, 0) / _totPieces) : 0;

    const V = computePointMortVerite({
      chargesFixesMensuelles: _fx,
      coutTempsHorsProdMensuel: _tps.fiable ? _tps.coutParMois : 0,
      prixVenteMoyen: _prixMoy,
      coutRevientUnit: _coutMoy,
      tauxHoraire: _s.laborRate,          // [v1332] pour chiffrer le coût d'une heure NON pointée
      tauxSocialPct: _s.socialGoods,
      abattementIrPct: _s.irAbattementGoods,
      trancheIrPct: _s.irTrancheMarginale
    });
    const M = V.marge, pm = V.reel;

    if(_totPieces > 0 && (_fx > 0 || _tps.coutParMois > 0 || !pm.atteignable)){
      // Les marches de la cascade : chaque ligne dit ce qu'un oubli coûte, en macarons.
      const _marches = V.cascade.map((m,i)=>{
        const prev = i>0 ? V.cascade[i-1].pm : null;
        const nb   = m.pm.atteignable ? m.pm.macaronsParMois : null;
        const nbP  = (prev && prev.atteignable) ? prev.macaronsParMois : null;
        const delta = (nb!=null && nbP!=null) ? (nb - nbP) : null;
        return `<div style="display:flex;align-items:baseline;gap:8px;padding:7px 0;${i?'border-top:1px dashed var(--hair)':''}">
          <span style="flex:1;font-size:.78rem;color:${i===0?'#9a8a82':'#6a5a52'}">${i===0?'':'<b style="color:var(--bordeaux)">＋</b> '}${esc(m.label)}${m.oubli!=null&&m.cle!=='temps'?` <span style="color:#9a8a82">(−${euro(m.oubli)}/macaron)</span>`:''}${m.cle==='temps'&&m.oubli>0?` <span style="color:#9a8a82">(+${euro(m.oubli)}/mois)</span>`:''}</span>
          <b style="flex:none;font-size:.9rem;color:${nb==null?'#b3261e':(i===V.cascade.length-1?'var(--bordeaux)':'#6a5a52')}">${nb==null?'∞':nb+' mac.'}</b>
          ${delta!=null&&delta!==0?`<span style="flex:none;font-size:.72rem;color:#b3261e;font-weight:700;min-width:44px;text-align:right">+${delta}</span>`:'<span style="flex:none;min-width:44px"></span>'}
        </div>`;
      }).join('');

      _pmHtml = `<div class="panel" style="border-left:4px solid ${pm.atteignable?'var(--caramel)':'#b3261e'}">
        <h2>🎯 Ton point mort</h2>
        ${pm.atteignable ? `
          <p class="note" style="margin:-4px 0 10px">Le volume minimum à vendre chaque mois pour ne rien perdre — <b>une fois TOUT payé</b> : matières, ton temps d'atelier, l'URSSAF, l'impôt, tes charges fixes et tes heures hors-atelier.</p>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
            <div class="sum-box" style="display:block;background:linear-gradient(135deg,#52252F,#3d1a22);color:#fff">
              <div style="font-size:.72rem;opacity:.85;text-transform:uppercase">À vendre par mois</div>
              <div style="font-size:1.7rem;font-weight:700">${pm.macaronsParMois} macarons</div>
              <div style="font-size:.74rem;opacity:.8">soit ~${pm.macaronsParJour}/jour${pm.caMinimum!=null?` · ${euro(pm.caMinimum)} de CA`:''}</div>
            </div>
            <div class="sum-box" style="display:block">
              <div style="font-size:.72rem;color:#9a8a82;text-transform:uppercase">Coût de structure</div>
              <div style="font-size:1.7rem;font-weight:700">${euro(V.coutStructureMensuel)}<span style="font-size:.8rem;font-weight:400">/mois</span></div>
              <div style="font-size:.74rem;color:#9a8a82">${euro(V.chargesFixesMensuelles)} de charges fixes${V.coutTempsHorsProdMensuel>0?` + ${euro(V.coutTempsHorsProdMensuel)} de temps hors-atelier`:''}</div>
            </div>
          </div>
          ${V.ecartMacarons>0?`<div style="padding:9px 12px;background:#fff6e5;border-radius:8px;margin-bottom:10px;font-size:.8rem;color:#6a5a52;line-height:1.55">
            ⚠️ <b>Avant</b>, l'app t'annonçait <b>${V.ancien.macaronsParMois} macarons</b> — elle oubliait l'URSSAF, l'impôt et tes heures hors-atelier.<br>
            <b>La réalité, c'est ${pm.macaronsParMois}</b> <span style="color:#9a8a82">(soit ${V.ecartMacarons} de plus)</span>. Le détail ci-dessous montre d'où vient chaque marche.
          </div>`:''}
          ${(!_tps.plausible && _tps.fiable)?`<div style="padding:10px 12px;background:#fdecea;border-radius:8px;margin-bottom:10px;font-size:.8rem;color:#6a5a52;line-height:1.55">
            <div style="font-weight:700;color:#b3261e">⏱ Attention : ce chiffre est probablement SOUS-ESTIMÉ.</div>
            ${esc(_tps.alerte||'')}
            ${V.macaronsParHeureHorsAtelier?`<br><br><b>Le taux qui compte :</b> chaque heure hors-atelier que tu ne pointes pas escamote environ <b>${V.macaronsParHeureHorsAtelier} macarons</b> de ton point mort.<br>
            <span style="color:#9a8a82">Tu es à ${_tps.heuresParMois} h/mois pointées. Si tu en passes réellement 15, ton vrai point mort tourne plutôt autour de <b>${pm.macaronsParMois + Math.round((15 - _tps.heuresParMois) * V.macaronsParHeureHorsAtelier)} macarons</b>. Je ne l'affiche pas comme un fait : je te donne le taux, l'estimation des heures n'appartient qu'à toi.</span>`:''}
          </div>`:''}
        ` : `
          <div style="padding:10px 12px;background:#fdecea;border-radius:8px;margin-bottom:10px">
            <div style="font-weight:700;color:#b3261e;font-size:.9rem">⚠️ Aucun volume ne peut te rendre rentable</div>
            <div style="font-size:.8rem;color:#6a5a52;margin-top:4px">${esc(pm.raison||'')}<br>
            Une fois l'URSSAF, l'impôt et ton temps payés, chaque macaron vendu te coûte de l'argent : en vendre davantage ne ferait qu'<b>aggraver</b> la perte. Il faut d'abord <b>augmenter tes prix</b> ou <b>réduire tes coûts</b>.</div>
          </div>
        `}
        <details ${pm.atteignable?'':'open'} style="margin-top:4px">
          <summary style="cursor:pointer;font-size:.8rem;color:var(--caramel);font-weight:600">🔎 D'où vient ce chiffre ? — les 4 marches</summary>
          <div style="margin-top:8px">
            ${_marches}
            <div style="margin-top:10px;padding-top:9px;border-top:1px solid var(--hair);font-size:.78rem;color:#6a5a52;line-height:1.65">
              <b>Ce que devient un macaron vendu ${euro(M.prixVenteMoyen)} :</b><br>
              − ${euro(M.coutRevientUnit)} de coût de revient <span style="color:#9a8a82">(matières + consommables + ton temps d'atelier)</span><br>
              − ${euro(M.coutSocialUnit)} de charges sociales <span style="color:#9a8a82">(${M.tauxSocialPct}% du prix, URSSAF)</span><br>
              − ${euro(M.coutIrUnit)} d'impôt sur le revenu <span style="color:#9a8a82">(base ${euro(M.baseIrUnit)} après abattement de ${M.abattementIrPct}%, × tranche ${M.trancheIrPct}%)</span><br>
              <b style="color:${M.margeContribution>0?'#3f7d52':'#b3261e'}">= ${euro(M.margeContribution)} qui restent pour éponger tes charges fixes.</b><br>
              <span style="color:#9a8a82">${pm.atteignable?`Soit ${euro(V.coutStructureMensuel)} ÷ ${euro(M.margeContribution)} = <b>${pm.macaronsParMois} macarons</b> par mois. Chaque macaron vendu au-delà est du bénéfice net — vraiment net, cette fois.`:'Aucune marche ne peut être franchie : la marge est épuisée avant même d\'atteindre tes charges fixes.'}</span>
            </div>
            ${_tps.fiable ? `
              <div style="margin-top:10px;padding-top:9px;border-top:1px solid var(--hair);font-size:.78rem;color:#6a5a52;line-height:1.6">
                <b>Tes heures hors-atelier</b> — ${_tps.heuresParMois} h/mois en moyenne (${_tps.heuresTotal} h pointées sur ${_tps.moisObserves} mois, ${_tps.nbSessions} session${_tps.nbSessions>1?'s':''}) :<br>
                ${_tps.parActivite.map(a=>`<span style="color:#9a8a82">· ${esc(a.activite)} : ${a.heures} h → ${euro(a.cout)}</span>`).join('<br>')}
                <br><span style="color:#9a8a82">Ces heures ne sont payées ni par le coût de revient (qui ne compte que l'atelier), ni par les charges fixes. Sans cette ligne, elles restent du bénévolat.</span>
              </div>`
            : `
              <div style="margin-top:10px;padding:9px 12px;background:#fff6e5;border-radius:8px;font-size:.78rem;color:#6a5a52;line-height:1.5">
                ⏱ <b>Ton temps hors-atelier n'est pas mesuré.</b> ${esc(_tps.raison||'')}<br>
                <span style="color:#9a8a82">Utilise la pointeuse pour tes courses, ton administratif et tes déplacements : ce point mort deviendra alors complet.</span>
              </div>`}
          </div>
        </details>
      </div>`;
    }
  }catch(e){ swallow(e,'pointMortVerite'); }

  document.getElementById('main').innerHTML=`
   <div class="topbar"><div><h1>Analyse de rentabilité</h1><p>Marge brute & nette · classement par rentabilité</p></div>
     <button class="btn ghost sm" onclick="settingsForm()">⚙ Paramètres</button></div>
   <div class="banner">📈 <div>Marge brute = prix de vente − matières − emballages. Marge nette = marge brute − charges sociales (${getSettings().socialGoods}% marchandise, ${getSettings().socialService}% prestation). L'échelle de rentabilité se base sur le taux de marge nette.</div></div>
   ${_pmHtml}
   ${_leviersHtml}
   <div class="panel"><h2>Classement clients par rentabilité</h2>${clientTable}</div>
   <h2 style="font-family:'Bellota',serif;color:var(--bordeaux);margin:18px 0 4px;font-size:1.2rem">Rentabilité par événement</h2>
   ${eventCards}`;
}

// Paramètres : taux de charges sociales + coûts d'emballage par taille de coffret.
// ============================================================
//  CARNET D'ADRESSES DE LIVRAISON (distance + temps + note)
//  Stocké dans les réglages. Pré-remplit la livraison des commandes.
// ============================================================
// [v1382] L'ancien écran est devenu un ALIAS. Il rendait sa propre liste, sans le point de
// départ ni les trajets appris : après un ajout ou une suppression, Ben y retombait et perdait
// la moitié de l'information. Deux écrans pour la même chose, c'est deux vérités (v1331) —
// il n'en reste qu'un. Le nom est conservé : tous les retours existants continuent de marcher.
function openAddressBook(){ return openCarnetTrajets(); }
function addressBookForm(idx){
  const s=getSettings(); const book=s.addressBook||[];
  const a = idx>=0 ? book[idx] : {libelle:'', km:'', min:'', note:''};
  openModal(`<h3>${idx>=0?'Modifier':'Nouvelle'} adresse</h3>
    <div class="field"><label>Libellé du lieu</label>
      <input id="ab_lib" value="${esc(a.libelle||'')}" placeholder="ex : Marché de Pontlieue, Chez Paulette…"></div>
    <div class="row2">
      <div class="field"><label>Distance aller (km)</label>
        <input type="number" min="0" step="0.1" id="ab_km" value="${a.km!=null?esc(a.km):''}" placeholder="ex : 8"></div>
      <div class="field"><label>Temps aller (min)</label>
        <input type="number" min="0" step="1" id="ab_min" value="${a.min!=null?esc(a.min):''}" placeholder="ex : 15"></div>
    </div>
    <div class="field"><label>Note <span style="color:#9a8a82;font-weight:400">— étage, code, créneau…</span></label>
      <textarea id="ab_note" rows="2" placeholder="ex : 2e étage, code 12B4, livrer avant 9h">${esc(a.note||'')}</textarea></div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="openAddressBook()">Annuler</button>
      <button class="btn" onclick="addressBookSave(${idx})">Enregistrer</button>
    </div>`);
}
function addressBookSave(idx){
  const s=getSettings(); const book=s.addressBook||[];
  const entry={
    libelle: val('ab_lib')||'',
    km: val('ab_km')!==''?+val('ab_km'):null,
    min: val('ab_min')!==''?+val('ab_min'):null,
    note: val('ab_note')||''
  };
  if(!entry.libelle.trim()){ toast('Donnez un libellé à l\'adresse'); return; }
  if(idx>=0) book[idx]=entry; else book.push(entry);
  s.addressBook=book; saveSettings(s);
  toast('Adresse enregistrée ✓');
  openAddressBook();
}
function addressBookDelete(idx){
  const s=getSettings(); const book=s.addressBook||[];
  if(!book[idx]) return;
  if(!confirm(`Supprimer « ${book[idx].libelle||'cette adresse'} » du carnet ?`)) return;
  book.splice(idx,1); s.addressBook=book; saveSettings(s);
  toast('Adresse supprimée');
  openAddressBook();
}

// ============================================================
//  COMPARATEUR DE MARGE PAR EMBALLAGE (étape 1)
//  Montre, côte à côte, la marge brute de chaque format de boîte.
//  Marge brute = prix de vente − coût des macarons − coût de l'emballage.
//  Données : packTypes (nom, coût, capacité) + coffrets standards.
// ============================================================
// Déplie/replie le comparateur intégré et le charge sur place (pas de changement d'écran).
async function togglePmcBlock(){
  const body=document.getElementById('pmcBody'), arrow=document.getElementById('pmcArrow');
  if(!body) return;
  const open = body.style.display==='none';
  body.style.display = open?'block':'none';
  if(arrow) arrow.textContent = open?'▾':'▸';
  if(!open) return;                 // on replie : rien d'autre à faire
  // À l'ouverture : recalcule les lignes d'emballage DEPUIS les champs en cours de saisie
  // (pour refléter ce que l'utilisateur vient de taper, même non enregistré).
  await pmcBuildAndFill();
}
// Construit la liste des emballages à comparer en lisant les champs actuels + coffrets standards,
// récupère le coût macaron réel, puis remplit le bloc intégré.
async function pmcBuildAndFill(){
  const s=getSettings();
  // 1) coffrets standards (avec leur prix d'emballage réglé)
  const rows=[];
  BOX_SIZES.forEach(t=>rows.push({ nom:'Coffret '+t, cap:t, coutEmb:(s.packaging&&s.packaging[t]!=null)?+s.packaging[t]:0 }));
  // 2) types d'emballage : on lit les LIGNES SAISIES à l'écran (live), pas seulement l'enregistré
  const n=+val('set_pt_n')||0;
  const seenPmc=new Set();
  const stdCapsPmc=new Set(BOX_SIZES.map(t=>+t));   // capacités déjà couvertes par les coffrets standards
  for(let i=0;i<n;i++){
    const nom=(val('set_pt_n_'+i)||'').trim(); if(!nom) continue;
    const cap=Math.max(0,+val('set_pt_cap_'+i)||0), coutEmb=money2(+val('set_pt_c_'+i)||0);
    // Doublon d'un coffret standard : un packType générique "Boîte N" ou "Coffret N" dont la
    // capacité N est un format standard (6/8/16/25) fait double emploi avec le coffret déjà
    // affiché en haut → on le masque ICI uniquement (aucune donnée touchée, comptage marché intact).
    // On épargne les emballages au nom spécifique (ex: "Boîte blch 10/16pcs") même si cap=16.
    const nomNorm=nom.toLowerCase().replace(/\s+/g,' ').trim();
    const estGenerique = new RegExp('^(bo[iî]te|coffret)\\s*'+escapeRe(String(cap))+'$').test(nomNorm);   // [v1328] échappé
    if(stdCapsPmc.has(cap) && estGenerique) continue;
    const key=nom.toLowerCase()+'|'+cap+'|'+coutEmb;
    if(seenPmc.has(key)) continue;   // doublon entre types restants
    seenPmc.add(key);
    rows.push({ nom, cap, coutEmb });
  }
  // 3) coût macaron réel (moyenne des recettes)
  let coutAuto=null;
  try{
    const [recipes, recipeItems, lots] = await Promise.all([db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray()]);
    if(recipes.length){ const v=avgMacaronCost(recipes, recipeItems, lots); if(v>0) coutAuto=money2(v); }
  }catch(e){ console.error('pmc coutAuto', e); }
  const coutPiece = coutAuto!=null ? coutAuto : (s._packCompCoutPiece!=null ? s._packCompCoutPiece : 0.11);
  const pieceInput=document.getElementById('pmc_piece'); if(pieceInput) pieceInput.value=coutPiece;
  const noteEl=document.getElementById('pmcAutoNote');
  if(noteEl) noteEl.innerHTML = coutAuto!=null
    ? `<span style="color:#3f7d52;font-weight:500">✓ d'après tes recettes</span>`
    : `<span style="color:#9a8a82">à saisir</span>`;
  // 4) remplir la liste
  const list=document.getElementById('pmcList'); if(!list) return;
  list.innerHTML = rows.map((r,i)=>`<div class="pmc-card">
      <div class="pmc-card-top">
        <span class="pmc-card-nom">${esc(r.nom)}</span>
        <span class="pmc-card-cap">${r.cap?r.cap+' macarons':'—'}</span>
      </div>
      <div class="pmc-card-inputs">
        <div class="pmc-in">
          <span class="pmc-in-lbl">Coût emballage</span>
          <div class="pmc-in-box"><input type="number" step="0.01" min="0" id="pmc_emb_${i}" value="${r.coutEmb||''}" placeholder="0" oninput="pmcRecalc()"><span class="pmc-in-unit">€</span></div>
        </div>
        <div class="pmc-in">
          <span class="pmc-in-lbl">Prix de vente</span>
          <div class="pmc-in-box"><input type="number" step="0.01" min="0" id="pmc_vente_${i}" placeholder="0" oninput="pmcRecalc()"><span class="pmc-in-unit">€</span></div>
        </div>
      </div>
      <div class="pmc-card-res" id="pmc_res_${i}"><span class="pmc-empty">Saisis le prix de vente ↑</span></div>
    </div>`).join('');
  window.__pmcRows = rows;
  setTimeout(pmcRecalc, 0);
}
function pmcRecalc(){
  const rows = window.__pmcRows||[];
  const coutPiece = +val('pmc_piece')||0;
  // mémorise le coût pièce
  const s=getSettings(); s._packCompCoutPiece=coutPiece; saveSettings(s);
  rows.forEach((r,i)=>{
    const emb = +val('pmc_emb_'+i)||0;
    const vente = +val('pmc_vente_'+i)||0;
    const resEl = document.getElementById('pmc_res_'+i);
    if(!resEl) return;
    if(vente<=0){ resEl.innerHTML='<span class="pmc-empty">Saisis le prix de vente ↑</span>'; return; }
    const coutMaca = money2((r.cap||0)*coutPiece);
    const marge = money2(vente - coutMaca - emb);
    const taux = vente>0 ? Math.round(marge/vente*1000)/10 : 0;
    const col = taux>=60?'#2e7d32':(taux>=40?'#3f7d52':(taux>=25?'#caa23b':'#d4671f'));
    resEl.innerHTML = `
      <div class="pmc-res-line">
        <span class="pmc-res-marge" style="color:${col}">${euro(marge)}</span>
        <span class="pmc-res-taux" style="background:${col}">${taux}%</span>
      </div>
      <div class="pmc-res-detail">${euro(vente)} vente − ${euro(coutMaca)} macarons − ${euro(emb)} boîte</div>`;
  });
}
async function settingsForm(){
  const s=getSettings();
  // Matières d'emballage (boîtes + sacs) du stock, pour rattacher chaque type marché à une matière
  // réelle (permet le décompte de stock — étape suivante). Liste optionnelle par type.
  const _embMatsForLink = (await db.materials.toArray()).filter(m=>m.categorie==='emballage')
    .sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  const _embLinkOpts = (sel)=>'<option value="">— non rattaché —</option>'+sortByName(_embMatsForLink,'nom').map(m=>`<option value="${m.id}" ${(+sel===+m.id)?'selected':''}>${m.usage==='sac'?'🛍️ ':'📦 '}${esc(m.nom)}</option>`).join('');
  window._embLinkOptsHtml = _embLinkOpts(0);   // pour addPackTypeRow (nouvelle ligne)
  // Coût RÉEL d'emballage par format, calculé sur les lots effectivement reçus (factures).
  let realMap=new Map();
  let _settingsLots=[];
  let _settingsMats=[];
  try{
    const [mats, lots] = await Promise.all([db.materials.toArray(), db.materialLots.toArray()]);
    realMap = realPackagingCostMap(mats, lots);
    _settingsLots = lots;
    _settingsMats = mats;
  }catch(e){ console.error('settingsForm realMap', e); }
  openModal(`<h3>Paramètres de gestion</h3>
    <p class="note">Charges sociales appliquées au calcul de la marge nette.</p>
    <div class="row2">
      <div class="field"><label>Charges sociales — marchandise (%)</label><input type="number" step="0.1" id="set_sg" value="${s.socialGoods}"></div>
      <div class="field"><label>Charges sociales — prestation (%)</label><input type="number" step="0.1" id="set_ss" value="${s.socialService}"></div>
    </div>
    <p class="note" style="margin-top:8px"><b>Coût emballage par coffret.</b> <span style="color:#9a8a82">Le coût <b>réel</b> est calculé automatiquement sur tes <b>lots d'emballage reçus</b> (moyenne pondérée d'après tes factures). Le tarif saisi ci-dessous ne sert que de <b>repli</b> si aucun lot chiffré n'existe pour ce format.</span></p>
    <div style="margin:6px 0"><button class="btn ghost sm" type="button" onclick="createBoitesBlanches()">＋ Créer les 2 boîtes blanches (8/10 et 10/16)</button></div>
    <div class="row2">
      ${BOX_SIZES.map(t=>{ const reel=realMap.get(+t); const manuel=s.packaging[t]!=null?s.packaging[t]:0;
        return `<div class="field"><label>Coffret ${t}</label>
          <input type="number" step="0.01" id="set_pk_${t}" value="${manuel}">
          ${reel!=null
            ? `<div style="font-size:.72rem;color:#2e7d32;margin-top:3px">✓ réel (lots reçus) : <b>${euro(reel)}</b> <span style="color:#9a8a82">— utilisé dans les calculs</span></div>`
            : `<div style="font-size:.72rem;color:#b07a4a;margin-top:3px">⚠ aucun lot chiffré — c'est le tarif saisi qui est utilisé</div>`}
        </div>`; }).join('')}
    </div>
    <div class="field" style="margin-top:8px">
      <label>Taille de coffret de référence <span style="color:#9a8a82;font-weight:400">— pour estimer l'emballage des commandes de reprise</span></label>
      <select id="set_embHistoTaille">
        ${BOX_SIZES.map(t=>`<option value="${t}" ${(+s.embHistoTailleRef===+t)?'selected':''}>Coffret ${t}</option>`).join('')}
      </select>
      <div style="font-size:.72rem;color:#9a8a82;margin-top:3px">Les commandes migrées n'ont pas le détail de leurs coffrets. Leur coût d'emballage est estimé d'après cette taille (ratio réel de tes coffrets ${s.embHistoTailleRef} si disponible, sinon le tarif ci-dessus). Choisis ta taille la plus vendue.</div>
    </div>
    ${(()=>{
      // Autres emballages à capacité (ex : boîtes blanches) qui ne sont pas des coffrets standards.
      // Affichés ici pour une vue d'ensemble ; leur coût vient de leurs lots ou de leur prix de
      // référence (modifiable sur la fiche matière), pas du tableau ci-dessus.
      const _src = (_settingsMats && _settingsMats.length) ? _settingsMats : (window._allMatsCache||[]);
      const mats = _src.filter(m=>m.categorie==='emballage' && +m.capacite>0 && !BOX_SIZES.includes(+m.capacite));
      // on inclut aussi les emballages de capacité standard mais au nom NON-coffret (ex: boîte blanche cap 16)
      const matsStdCap = _src.filter(m=>m.categorie==='emballage' && BOX_SIZES.includes(+m.capacite) && !/^coffret\b/i.test((m.nom||'').trim()));
      const autres = mats.concat(matsStdCap);
      if(!autres.length) return '';
      const rows = autres.sort((a,b)=>(+a.capacite||0)-(+b.capacite||0)).map(m=>{
        const res = embCostHierarchie(m, _settingsLots||[], s);
        return `<div class="field"><label>${esc(m.nom)} <span style="color:#9a8a82;font-weight:400">(cap ${m.capacite})</span></label>
          <div class="sum-box" style="margin:0"><span style="font-size:.78rem">coût ${res.source}</span><b>${euro(res.cout)}</b></div></div>`;
      }).join('');
      return `<p class="note" style="margin-top:10px"><b>Autres emballages</b> (boîtes blanches, formats spécifiques). <span style="color:#9a8a82">Leur prix se règle sur la fiche matière (prix de référence) ou via leurs lots reçus.</span></p>
        <div class="row2">${rows}</div>`;
    })()}
    <p class="note" style="margin-top:6px;color:#9a8a82">Pour obtenir un coût réel, réceptionne tes emballages comme des lots (avec leur prix de facture) : <b>Matières → ↘ Réception lot</b>, en choisissant une matière de catégorie « emballage » dont la <b>capacité</b> correspond au format (6, 8, 16 ou 25).</p>
    <button type="button" class="btn ghost sm" style="margin-top:6px" onclick="applyPackaging202511()" title="Remplit les champs avec les tarifs reçus le 28/11/2025">↺ Appliquer les tarifs du 28/11/2025 (6→1,26 · 8→2,18 · 16→1,90 · 25→2,32)</button>
    <div id="pkgDiag" style="margin-top:8px;font-size:.74rem;color:#9a8a82;background:#f7f3ee;border:1px solid #ece3d6;border-radius:8px;padding:8px 10px;line-height:1.6">
      ${(()=>{ try{ const raw=JSON.parse(localStorage.getItem('sm_settings')||'{}'); const st=raw.packaging||{}; const ef=getSettings().packaging;
        return `🔎 <b>Diagnostic</b> — valeurs réellement en mémoire :<br>`
          + `Stocké : ${BOX_SIZES.map(t=>`${t}→${st[t]!=null?st[t]:'∅'}`).join(' · ')}<br>`
          + `Effectif : ${BOX_SIZES.map(t=>`${t}→${ef[t]}`).join(' · ')}<br>`
          + `Date réf. stockée : ${raw.packagingDate||'∅'}`;
      }catch(e){ return 'Diagnostic indisponible'; } })()}
    </div>
    <p class="note" style="margin-top:8px">Types d'emballage pour le comptage avant/après en marché : nom, coût unitaire €, et <b>capacité</b> (nb de macarons par boîte — sert à reconstituer le CA par format). Pour un <b>🛍️ sac</b> ou un consommable <b>sans capacité</b>, laisse la capacité <b>vide ou 0</b> : il sera compté pour son coût mais exclu du CA par format. Le champ <b>↳ Stock</b> permet de <b>rattacher</b> ce type à une matière de ton inventaire (le décompte automatique du stock en marché arrive à l'étape suivante). Laisse le nom vide pour retirer une ligne.</p>
    <div class="pay-row" style="font-weight:600;color:#9a8a82;font-size:.8rem"><span style="flex:1">Nom</span><span style="width:90px">€/u</span><span style="width:70px">Capacité</span></div>
    <div id="set_pktypes">
      ${(s.packTypes||[]).concat([{nom:'',cout:'',capacite:''}]).map((t,i)=>`<div class="pt-line" style="margin-bottom:8px"><div class="pay-row"><input id="set_pt_n_${i}" value="${esc(t.nom||'')}" placeholder="nom (ex: Boîte 6 ou 🛍️ Sac)" style="flex:1"><input type="number" step="0.01" min="0" id="set_pt_c_${i}" value="${t.cout!==''&&t.cout!=null?t.cout:''}" placeholder="€/u" style="width:90px"><input type="number" step="1" min="0" id="set_pt_cap_${i}" value="${t.capacite!==''&&t.capacite!=null?t.capacite:''}" placeholder="pc / vide=sac" style="width:70px"></div>
        <div style="display:flex;align-items:center;gap:6px;margin-top:3px"><span class="note" style="white-space:nowrap">↳ Stock :</span><select id="set_pt_mat_${i}" style="flex:1">${_embLinkOpts(t.materialId)}</select></div></div>`).join('')}
    </div>
    <button type="button" class="btn ghost sm" style="margin-top:6px" onclick="addPackTypeRow()">＋ Ajouter une ligne</button>
    <div class="collapse-sec" id="pmcBlock" style="margin-top:12px">
      <button type="button" class="collapse-head" onclick="togglePmcBlock()">
        <span>📊 Marge par emballage <span class="collapse-hint">— compare le gain selon la boîte</span></span>
        <span class="collapse-arrow" id="pmcArrow">▸</span>
      </button>
      <div class="collapse-body" id="pmcBody" style="display:none">
        <p class="note">Saisis le prix de vente de chaque boîte : la marge brute se calcule en direct (coût macarons + emballage déduits).</p>
        <div class="field" style="margin:8px 0"><label>Coût d'un macaron nu (€/pièce) <span id="pmcAutoNote" style="color:#9a8a82;font-weight:400">— chargement…</span></label>
          <input type="number" step="0.01" min="0" id="pmc_piece" value="0.11" oninput="pmcRecalc()"></div>
        <div class="pmc-list" id="pmcList"><p class="note">Déplie pour charger…</p></div>
        <p class="note" style="margin-top:8px">Marge brute = prix de vente − (nb macarons × coût/pièce) − emballage. Hors charges sociales et livraison.</p>
      </div>
    </div>
    <p class="note" style="margin-top:8px">Livraison : sert à chiffrer le carburant (aller-retour) et le coût du temps de livraison.</p>
    <div class="row2">
      <div class="field"><label>Consommation véhicule (L/100 km)</label><input type="number" step="0.1" min="0" id="set_conso" value="${s.vehicleConso}"></div>
      <div class="field"><label>Coût horaire main-d'œuvre (€/h)</label><input type="number" step="0.5" min="0" id="set_rate" value="${s.laborRate}"></div>
    </div>
    <div class="field" style="margin-top:8px"><label>🏠 Adresse du labo <span style="color:#9a8a82;font-weight:400">— ton point de départ : toutes les distances du carnet sont mesurées depuis ici</span></label>
      <input id="set_adrLabo" value="${esc(s.adresseLabo||'')}" placeholder="ex : 12 rue des Acacias, Le Mans"></div>
    ${s.adresseLabo&&s.adresseLaboDepuis?`<p class="note" style="margin:-4px 0 8px">Point de départ inchangé depuis le ${esc(fmtDate(s.adresseLaboDepuis))}. Si tu le modifies, les trajets mesurés avant seront signalés (jamais effacés).</p>`:''}
    <div class="field" style="margin-top:8px">
      <button type="button" class="btn ghost" style="width:100%" onclick="openCarnetTrajets()">📍 Carnet des trajets <span style="color:#9a8a82;font-weight:400">(${(s.addressBook||[]).length} à la main + appris)</span></button>
    </div>
    <input type="hidden" id="set_pt_n" value="${(s.packTypes||[]).length+1}">
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button><button class="btn" onclick="saveSettingsForm()">Enregistrer</button></div>`);
}
// Ajoute dynamiquement une ligne de type d'emballage (sans avoir à enregistrer entre chaque).
function addPackTypeRow(){
  const box=document.getElementById('set_pktypes'); if(!box) return;
  const counter=document.getElementById('set_pt_n');
  const i = box.querySelectorAll('.pt-line').length;   // prochain index libre (1 pt-line par type)
  const row=document.createElement('div');
  row.className='pt-line';
  row.style.marginBottom='8px';
  row.innerHTML=`<div class="pay-row"><input id="set_pt_n_${i}" value="" placeholder="nom (ex: Boîte pro ou 🛍️ Sac)" style="flex:1"><input type="number" step="0.01" min="0" id="set_pt_c_${i}" value="" placeholder="€/u" style="width:90px"><input type="number" step="1" min="0" id="set_pt_cap_${i}" value="" placeholder="pc / vide=sac" style="width:70px"></div>
    <div style="display:flex;align-items:center;gap:6px;margin-top:3px"><span class="note" style="white-space:nowrap">↳ Stock :</span><select id="set_pt_mat_${i}" style="flex:1">${window._embLinkOptsHtml||'<option value="">— non rattaché —</option>'}</select></div>`;
  box.appendChild(row);
  if(counter) counter.value = String(i+1);   // la sauvegarde lira jusqu'à cet index
  const nameInput=row.querySelector('input'); if(nameInput) nameInput.focus();
}
function saveSettingsForm(){
  const s=getSettings();
  s.socialGoods=Math.max(0,+val('set_sg')||0);
  s.socialService=Math.max(0,+val('set_ss')||0);
  s.vehicleConso=Math.max(0,+val('set_conso')||0);
  s.laborRate=Math.max(0,+val('set_rate')||0);
  // [v1382] Changer le point de départ invalide les distances mesurées avant : on HORODATE
  // le changement pour pouvoir les signaler (v1339 : jamais remplacer un chiffre en silence).
  { const _adrAvant=(s.adresseLabo||'').trim(); const _adrApres=(val('set_adrLabo')||'').trim();
    if(_adrApres!==_adrAvant){ s.adresseLabo=_adrApres; s.adresseLaboDepuis=_adrApres?today():'';
      if(_adrAvant && _adrApres) toast('Point de départ modifié — tes trajets d\'avant seront signalés dans le carnet'); }
    if(typeof _trajetInvalideCache==='function') _trajetInvalideCache(); }
  // Si un tarif d'emballage change, on horodate la nouvelle grille à aujourd'hui (date de réception).
  const oldPack=JSON.stringify(s.packaging||{});
  s.packaging={}; BOX_SIZES.forEach(t=>{ s.packaging[t]=money2(+val('set_pk_'+t)||0); });
  { const _et=+val('set_embHistoTaille')||0; if(_et>0) s.embHistoTailleRef=_et; }   // [A6/A18] taille de réf pour l'estimation emballage des reprises
  if(JSON.stringify(s.packaging)!==oldPack) s.packagingDate=today();
  // types d'emballage (on lit toutes les lignes, on garde celles avec un nom, sans doublon)
  const n=+val('set_pt_n')||0; const pts=[]; const seenSave=new Set();
  for(let i=0;i<n;i++){
    const nom=(val('set_pt_n_'+i)||'').trim(); if(!nom) continue;
    const cout=money2(+val('set_pt_c_'+i)||0), capacite=Math.max(0,+val('set_pt_cap_'+i)||0);
    const materialId=+val('set_pt_mat_'+i)||0;   // rattachement à une matière emballage (0 = non rattaché)
    const key=nom.toLowerCase()+'|'+capacite+'|'+cout;
    if(seenSave.has(key)) continue;   // doublon → on ne l'enregistre pas
    seenSave.add(key);
    pts.push(materialId>0 ? {nom, cout, capacite, materialId} : {nom, cout, capacite});
  }
  s.packTypes=pts.length?pts:SETTINGS_DEFAULTS.packTypes;
  saveSettings(s);
  closeModal();
  if(view==='rentabilite') renderProfit(); else if(view==='compta') renderCompta(); else if(view==='marches') renderMarkets(); else toast('Paramètres enregistrés ✓');
  toast('Paramètres enregistrés ✓');
}

/* ============================================================
   MARCHÉS / VENTES ITINÉRANTES — écrans
   ============================================================ */
// Mémoire (marchés clos + leurs totaux) pour les popups détaillés.
let _marketsPer = [];

// Popup générique listant les marchés clos selon une métrique, avec code couleur vert/rouge.
function _marketPopup(opts){
  const per=_marketsPer||[];
  if(!per.length){ openModal(`<h3>${opts.titre}</h3><p class="note">Aucun marché clôturé pour le moment.</p><div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`); return; }
  const items=per.map(({mk,T})=>({nom:mk.nom||mk.lieu||'—', date:mk.date, v:opts.val(T)}));
  // moyenne de référence pour le code couleur (sauf si métrique « plus bas = mieux »)
  const moy=items.reduce((s,x)=>s+x.v,0)/items.length;
  items.sort((a,b)=> opts.asc ? a.v-b.v : b.v-a.v);
  const body=items.map(x=>{
    // « bon » = au-dessus de la moyenne, sauf pour les invendus où c'est l'inverse
    const bon = opts.lowerIsBetter ? x.v<=moy : x.v>=moy;
    const col=bon?'#2e7d32':'#b3261e'; const dot=bon?'🟢':'🔴';
    return `<div class="sum-box" style="border-left:3px solid ${col}"><span>${dot} ${esc(x.nom)} <span style="color:#9a8a82;font-size:.74rem">${x.date?fmtDate(x.date):''}</span></span><b style="color:${col}">${opts.fmt(x.v)}</b></div>`;
  }).join('');
  openModal(`<h3>${opts.titre}</h3>
    <p class="note" style="margin-bottom:10px">${opts.note}</p>
    <div style="max-height:48vh;overflow:auto">${body}</div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}
function marketCAPopup(){ _marketPopup({titre:'⛺ CA par marché clôturé', note:'Chiffre d\'affaires encaissé de chaque marché, du plus gros au plus petit. 🟢 au-dessus de la moyenne, 🔴 en dessous.', val:T=>T.caTotal, fmt:v=>euro(v)}); }
function marketMargePopup(){ _marketPopup({titre:'⛺ Marge nette par marché', note:'Marge nette après coûts (matière, emballage, stand, déplacement) et charges sociales. 🟢 rentable, 🔴 à surveiller.', val:T=>T.margeNette, fmt:v=>euro(v)}); }
function marketInvendusPopup(){ _marketPopup({titre:'⛺ Taux d\'invendus par marché', note:'Part des macarons embarqués non vendus (retour + don + perte). Ici 🟢 = peu d\'invendus (mieux), 🔴 = beaucoup (à corriger : moins produire ou mieux vendre).', val:T=>T.tauxInvendus, fmt:v=>v+'%', lowerIsBetter:true, asc:true}); }
// ÉTAPE 1 — Modale du gaspillage chiffré (retours jetés × coût complet).
function _gaspDismissed(){ try{ return localStorage.getItem('sm_gasp_ready_dismiss')==='1'; }catch(e){ return false; } }
function _gaspDismiss(){ try{ localStorage.setItem('sm_gasp_ready_dismiss','1'); }catch(e){swallow(e,'_gaspDismiss')} if(typeof renderDash==='function' && view==='dash') renderDash(); toast('Rappel masqué — tu retrouveras le gaspillage dans l\'écran Marchés'); }
let _gaspPeriode = 'tout';
async function gaspillagePopup(){
  const start = _gaspPeriode==='tout' ? null : comptaPeriodeStart(_gaspPeriode);
  let G;
  try{ G = await computeGaspillage({start}); }
  catch(e){ console.error('gaspillage',e); toast('Erreur lors du calcul du gaspillage'); return; }
  const periodeLbl = _gaspPeriode==='tout' ? 'tout l\'historique' : comptaPeriodeDatesLabel(_gaspPeriode);
  // Jauge de fiabilité : combien de marchés bien renseignés, et l'étape 2 est-elle débloquable ?
  const R = await gaspillageDataReadiness();
  const jauge = `<div class="banner" style="background:${R.ready?'#eef6ef':'#f6f1e7'};border-color:${R.ready?'#bcd9c4':'#e3d4b5'};margin-bottom:10px">
    ${R.ready?'✅':'📊'} <div style="font-size:.82rem">
      <b>Fiabilité des données de gaspillage : ${R.nbVentiles}/${R.seuil} marché(s) bien renseigné(s)</b>
      <div style="background:#e8ddca;border-radius:6px;height:8px;margin:5px 0;overflow:hidden"><div style="background:${R.ready?'#3f7d52':'#c9a227'};height:100%;width:${R.pct}%"></div></div>
      ${R.ready
        ? `Tes données sont assez représentatives. <b>L'aide à la quantité optimale (étape 2) peut être activée</b> — dis-le-moi quand tu veux qu'on la branche.`
        : `Continue à <b>ventiler tes invendus</b> à chaque retour de marché (❄️ Congélateur / 🧊 Frigo / 🗑 Écarté). Encore ${R.seuil-R.nbVentiles} marché(s) pour débloquer l'aide aux quantités.`}
      ${R.nbClosSansVentil>0?`<br><span style="color:#b3261e">⚠ ${R.nbClosSansVentil} marché(s) clôturé(s) sans invendus qualifiés : pense à marquer « 🗑 Écarté » ce que tu jettes.</span>`:''}
    </div></div>`;
  const tabs = [['tout','Tout'],['90j','90 j'],['mois','30 j'],['semaine','7 j']]
    .map(([k,l])=>`<button class="btn ${_gaspPeriode===k?'gold':'ghost'} sm" onclick="_gaspPeriode='${k}';gaspillagePopup()">${l}</button>`).join('');
  const lignes = G.lignes.length ? G.lignes.map(l=>`<div class="sum-box">
      <span>${esc(l.parfum)} <span style="color:#9a8a82">· ${qty(l.qte)} jeté(s)</span><br>
        <span style="font-size:.72rem;color:#9a8a82">matière ${euro(l.coutMat)} + main d'œuvre ${euro(l.coutMod)} + trajet ${euro(l.coutDep)}</span></span>
      <b style="color:#b3261e">${euro(l.total)}</b></div>`).join('')
    : '<p class="note">Aucun macaron jeté sur cette période 🎉 (seuls les retours « 🗑 Écarté » sont comptés).</p>';
  openModal(`<h3>🗑 Gaspillage chiffré</h3>
    <p class="note">Coût réel des invendus <b>jetés</b> (retours « écartés »), chiffré matière + main-d'œuvre + quote-part trajet. Période : ${esc(periodeLbl)}.</p>
    ${jauge}
    <div class="flex" style="gap:6px;margin-bottom:10px">${tabs}</div>
    ${G.totQte>0?`<div class="sum-box" style="background:#fdeaea;border:1px solid #e8a9a3">
      <span><b>Total jeté : ${qty(G.totQte)} macaron(s)</b><br><span style="font-size:.72rem;color:#9a8a82">mat. ${euro(G.totMat)} + M.O. ${euro(G.totMod)} + trajet ${euro(G.totDep)}</span></span>
      <b style="color:#b3261e;font-size:1.1rem">${euro(G.totalEuro)}</b></div>`:''}
    ${lignes}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}
function marketVendusPopup(){ _marketPopup({titre:'⛺ Macarons vendus par marché', note:'Volume vendu sur chaque marché. 🟢 au-dessus de la moyenne, 🔴 en dessous.', val:T=>T.vendu, fmt:v=>qty(v)+' pc'}); }

async function renderMarkets(){
  const markets=(await db.markets.toArray()).sort((a,b)=>{
    // Les marchés d'un même groupe (multi-jours) restent ensemble : on trie par la date du
    // groupe (date du jour 1), puis par numéro de jour, puis par date pour les marchés simples.
    const ka = a.mkGroup ? (a.mkGroup+'#'+(a.mkGroupDay||0)) : (a.date||'');
    const kb = b.mkGroup ? (b.mkGroup+'#'+(b.mkGroupDay||0)) : (b.date||'');
    // clé de tri principale = date la plus récente du marché ou de son groupe (ordre décroissant)
    const da = a.date||'', dbb = b.date||'';
    if(da!==dbb) return dbb.localeCompare(da);
    return ka.localeCompare(kb);
  });
  const moves=await db.marketMoves.toArray();
  const movesByMarket={}; moves.forEach(mv=>{ (movesByMarket[mv.marketId] ||= []).push(mv); });
  const [recipes, recipeItems, lots] = await Promise.all([db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray()]);
  const avgUnit = avgMacaronCost(recipes, recipeItems, lots);

  // tableau de bord global
  let caTotal=0, venduTotal=0, nbClos=0, sumInvendus=0, margeNetteTotal=0;
  const perMarket=markets.map(mk=>{ const T=marketTotals(mk, movesByMarket[mk.id]||[], avgUnit);
    if(mk.statut==='clos'){ caTotal=addMoney(caTotal,T.caTotal); venduTotal=round3(venduTotal+T.vendu); nbClos++; sumInvendus+=T.tauxInvendus; margeNetteTotal=addMoney(margeNetteTotal,T.margeNette); }
    return {mk,T}; });
  const caMoyen = nbClos>0?money2(caTotal/nbClos):0;
  const invMoyen = nbClos>0?Math.round(sumInvendus/nbClos*10)/10:0;
  _marketsPer = perMarket.filter(x=>x.mk.statut==='clos');   // pour les popups détaillés

  const rows=perMarket.map(({mk,T})=>`<tr${mk.mkGroup?' style="box-shadow:inset 3px 0 0 #c9a227"':''}>
     <td>${fmtDate(mk.date)}</td>
     <td><b>${esc(mk.nom||'—')}</b>${mk.histo?' <span class="tag" style="background:#eef2fb;color:#3b6ea5">📥 Hist.</span>':''}${mk.mkGroup?` <span class="tag" style="background:#f3ecdd;color:#8a6d3b">📅 Jour ${mk.mkGroupDay||'?'}/${mk.mkGroupTotal||'?'}</span>`:''}<br><span style="color:#9a8a82;font-size:.75rem">${esc(mk.lieu||'')}</span></td>
     <td>${mk.statut==='clos'?`<span class="tag done">Clos</span>`:`<span class="tag todo">Ouvert</span>`}</td>
     <td>${mk.statut==='clos'?euro(T.caTotal):'—'}</td>
     <td>${T.vendu>0||mk.statut==='clos'?qty(T.vendu):'—'}</td>
     <td>${mk.statut==='clos'?T.tauxInvendus+'%':'—'}</td>
     <td style="text-align:right"><span class="act" onclick="marketDetail(${mk.id})">Ouvrir</span><span class="act del" onclick="delMarket(${mk.id})">Suppr.</span></td></tr>`).join('');

  document.getElementById('main').innerHTML=`
   <div class="topbar"><div><h1>Marchés</h1><p>${markets.length} marché(s) · ventes itinérantes</p></div>
     <div class="flex" style="gap:8px"><button class="btn ghost sm" onclick="renderMarketStats()">📊 Statistiques</button>
     <button class="btn" onclick="marketForm()">+ Nouveau marché</button></div></div>
   ${nbClos>0?`<div class="kpi-grid">
     <div class="kpi lnk" onclick="marketCAPopup()"><span>CA marchés (clos) ${INFO_I}</span><b>${euro(caTotal)}</b><span>${nbClos} marché(s)</span></div>
     <div class="kpi"><span>CA moyen / marché</span><b>${euro(caMoyen)}</b></div>
     <div class="kpi lnk" onclick="marketMargePopup()"><span>Marge nette marchés ${INFO_I}</span><b style="color:${margeNetteTotal>=0?'#3f7d52':'var(--red,#b3261e)'}">${euro(margeNetteTotal)}</b></div>
     <div class="kpi lnk" onclick="marketVendusPopup()"><span>Macarons vendus ${INFO_I}</span><b>${qty(venduTotal)}</b></div>
     <div class="kpi lnk" onclick="marketInvendusPopup()"><span>Taux d'invendus moyen ${INFO_I}</span><b>${invMoyen}%</b></div>
     <div class="kpi lnk" onclick="gaspillagePopup()"><span>🗑 Gaspillage chiffré</span><b style="color:#b3261e">voir →</b></div>
   </div>`:''}
   <div class="panel">
   ${markets.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Marché</th><th>Statut</th><th>CA</th><th>Vendus</th><th>Invendus</th><th></th></tr></thead>
     <tbody>${rows}</tbody></table></div>`:`<div class="empty">Aucun marché. Créez une fiche avant votre prochain marché pour suivre stocks, ventes et performances.</div>`}
   </div>
   <div class="flex" style="gap:8px;margin-top:12px"><button class="btn ghost" onclick="renderMarketForecast()">🔮 Prévisions de production marché</button><button class="btn ghost" onclick="showMarketSelection()">🎯 Sélection optimale des parfums</button></div>`;
}

async function marketForm(id){
  const mk = id ? await db.markets.get(id) : {date:today(), statut:'ouvert'};

  // ══════════════════════════════════════════════════════════════════════════════════════════
  // [v1431] PARFUMS VISÉS À L'OUVERTURE DU MARCHÉ — demande de Ben : « la quantité visée doit
  // être renseignée à l'ouverture du marché avec les parfums souhaités. Ceci permet aussi
  // d'approvisionner en donnée le rétroplanning ».
  //
  // Le rétroplanning consommait DÉJÀ les marchés non clos (buildProductionPlan), mais il DEVINAIT
  // la ventilation par parfum d'après l'historique — et retombait sur une ligne fourre-tout
  // « Marché (parfums à définir) » quand il n'y avait pas d'historique. Deviner est utile par
  // défaut ; ce n'est pas une décision. Ici Ben décide, et sa décision doit primer.
  //
  // ON NE RÉÉCRIT AUCUN MOTEUR : le bouton « Répartir automatiquement » appelle `marketForecast`
  // + `marketCrossPlan` + `marketVentilation` — exactement la chaîne de l'écran Plan de production
  // et du copilote. La saisie manuelle reste souveraine : la suggestion PRÉ-REMPLIT, elle n'impose
  // rien, et rien n'est écrit tant que Ben n'enregistre pas.
  let _mkParfumsBloc = '';
  try{
    const _recs = await db.recipes.toArray().catch(()=>[]);
    const _noms = [...new Set(_recs.map(r=>r && r.produitNom).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
    const _dejaSaisi = {};
    (Array.isArray(mk.prevuParfums)?mk.prevuParfums:[]).forEach(x=>{ if(x && x.parfum) _dejaSaisi[x.parfum]=+x.qte||0; });
    // Suggestion : la même ventilation que celle du Plan de production, sur la quantité visée.
    let _sugg = {};
    try{
      const _fc = await marketForecast();
      const _st = (typeof getSettings==='function') ? getSettings() : {};
      const _cible = Array.isArray(_st.marketMix) ? _st.marketMix : [];
      const _q = +mk.prevuQte||0;
      const _v = marketVentilation(_cible, (_fc && _fc.repartition)||[], _q, {mode:'croise'});
      (_v.lignes||[]).forEach(l=>{ if(l && l.parfum && l.pieces>0) _sugg[l.parfum]=l.pieces; });
      window._mkVentilSuggeree = _sugg;
      window._mkVentilSource = _v.sourceUtilisee || 'aucune';
    }catch(e){ window._mkVentilSuggeree = {}; window._mkVentilSource='aucune'; swallow(e,'marketForm ventilation'); }
    if(_noms.length){
      const _rows = _noms.map(n=>{
        const v = _dejaSaisi[n]!=null ? _dejaSaisi[n] : '';
        const sg = _sugg[n];
        return `<div style="display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid var(--hair)">
          <span style="flex:1;min-width:0;font-size:.86rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(n)}</span>
          ${sg>0?`<span style="font-size:.72rem;color:#8a7a72;white-space:nowrap">sugg. ${sg}</span>`:''}
          <input type="number" min="0" step="1" style="width:78px;text-align:right" class="mk-parf" data-parfum="${esc(n)}" value="${v}" oninput="mkParfumsTotal()">
        </div>`;
      }).join('');
      const _src = { cible:'ta cible de répartition', historique:'ton historique de ventes',
                     croise:'ta cible croisée avec ton historique' }[window._mkVentilSource] || null;
      _mkParfumsBloc = `<details ${Object.keys(_dejaSaisi).length?'open':''} style="margin:2px 0 8px;border:1px solid #cfd9c9;border-radius:12px;overflow:hidden;background:#f8faf6">
        <summary style="cursor:pointer;padding:10px 12px;font-weight:600;color:#3f6b45;background:#eef4ea">🎯 Parfums visés <span style="font-weight:400;color:#6a7a68" id="mk_parfSum">—</span></summary>
        <div style="padding:8px 12px">
          <p class="note" style="margin:0 0 6px">Ce que tu vises par parfum. C'est cette ventilation que le <b>Plan de production</b> utilisera — à défaut, il devine d'après ton historique.</p>
          ${_src?`<button type="button" class="btn ghost sm" style="width:100%;margin-bottom:6px" onclick="mkAppliquerVentilation()">🎯 Répartir automatiquement (${esc(_src)})</button>`:`<p class="note" style="margin:0 0 6px;color:#b5701a">Aucune répartition à proposer : définis une cible dans <b>Plan de production</b> ou accumule de l'historique de marché.</p>`}
          ${_rows}
        </div>
      </details>`;
    }
  }catch(e){ swallow(e,'marketForm parfums'); }

  openModal(`<h3>${id?'Modifier':'Nouveau'} marché</h3>
    <div class="field"><label>Nom du marché *</label><input id="mk_nom" value="${esc(mk.nom||'')}" placeholder="ex : Marché de Noël du Mans"></div>
    <div class="row2">
      <div class="field"><label>Date *</label><input type="date" id="mk_date" value="${esc(mk.date||today())}"></div>
      <div class="field"><label>Lieu</label><input id="mk_lieu" value="${esc(mk.lieu||'')}" placeholder="Place, ville"></div>
    </div>
    <div class="row2">
      <div class="field"><label>Horaires${id?'':' (jour 1)'}</label><input id="mk_horaires" value="${esc(mk.horaires||'')}" placeholder="ex : 10h–19h"></div>
      <div class="field"><label>Durée (heures)</label><input type="number" step="0.5" min="0" id="mk_heures" value="${mk.heures||''}" placeholder="ex : 8"></div>
    </div>
    ${id?'':`
    <label class="opt-row" style="margin:4px 0 2px"><input type="checkbox" id="mk_2jours" onchange="document.getElementById('mk_j2zone').style.display=this.checked?'block':'none'"> <span class="opt-main"><b>📅 Marché sur 2 jours consécutifs</b><br><span style="font-size:.78rem;color:#9a8a82">Crée deux fiches liées (une par jour), chacune avec sa caisse. Le stand est réparti moitié-moitié ; le trajet est compté chaque jour.</span></span></label>
    <div id="mk_j2zone" style="display:none">
      <div class="row2">
        <div class="field"><label>Date jour 2 *</label><input type="date" id="mk_date2" value=""></div>
        <div class="field"><label>Horaires (jour 2)</label><input id="mk_horaires2" value="" placeholder="ex : 10h–18h"></div>
      </div>
      <div class="field"><label>Durée jour 2 (heures)</label><input type="number" step="0.5" min="0" id="mk_heures2" value="" placeholder="ex : 8"></div>
    </div>`}
    <div class="field"><label>Météo (optionnel)</label><input id="mk_meteo" value="${esc(mk.meteo||'')}" placeholder="ex : Ensoleillé, 18°C"></div>
    <div class="field"><label>Fond de caisse au départ (€) <span style="color:#9a8a82;font-weight:400">— déduit automatiquement du résultat</span></label>
      <input type="number" min="0" step="1" id="mk_fond" value="${mk.fondCaisse!=null?esc(mk.fondCaisse):''}" placeholder="ex : 50"></div>
    <h4 style="margin:14px 0 4px;color:var(--bordeaux)">Charges du marché</h4>
    <div class="field"><label>Prix du stand / emplacement (€)</label>
      <input type="number" min="0" step="0.5" id="mk_stand" value="${mk.coutStand!=null?esc(mk.coutStand):''}" placeholder="ex : 25"></div>
    <div class="row2">
      <div class="field"><label>Distance aller (km) <span style="color:#9a8a82;font-weight:400">— A/R calculé</span></label>
        <input type="number" min="0" step="0.1" id="mk_dist" value="${mk.distanceKm!=null?esc(mk.distanceKm):''}" placeholder="ex : 18"></div>
      <div class="field"><label>Prix carburant (€/L)</label>
        <input type="number" min="0" step="0.001" id="mk_carbu" value="${mk.prixCarburant!=null?esc(mk.prixCarburant):''}" placeholder="ex : 1.85"></div>
    </div>
    <div class="field"><label>Temps de route aller (min) <span style="color:#9a8a82;font-weight:400">— l'aller-retour est calculé (×2), valorisé au taux horaire</span></label>
      <input type="number" min="0" step="1" id="mk_route" value="${mk.tempsRouteMin!=null?esc(mk.tempsRouteMin):''}" placeholder="ex : 30"></div>
    <div class="field"><label>Consommation réelle du véhicule (L/100 km) <span style="color:#9a8a82;font-weight:400">— vide = défaut (${getSettings().vehicleConso} L)</span></label>
      <input type="number" min="0" step="0.1" id="mk_conso" value="${mk.consoVehicule!=null&&mk.consoVehicule!==''?esc(mk.consoVehicule):''}" placeholder="ex : 7.2"></div>
    <div class="field"><label>Quantité prévue à emporter (macarons) <span style="color:#9a8a82;font-weight:400">— pour la planification intelligente</span></label>
      <input type="number" min="0" step="10" id="mk_prevu" value="${mk.prevuQte!=null?esc(mk.prevuQte):''}" placeholder="ex : 300">
      <p class="note" id="mk_prevuHint" style="margin-top:4px"></p></div>
    ${_mkParfumsBloc}
    <div class="field"><label>Commentaires</label><textarea id="mk_notes" rows="2">${esc(mk.notes||'')}</textarea></div>
    <label class="opt-row" style="margin:4px 0 2px"><input type="checkbox" id="mk_histo" ${mk.histo?'checked':''}> <span class="opt-main"><b>📥 Marché historique (migration)</b><br><span style="font-size:.78rem;color:#9a8a82">Saisie de données passées pour les statistiques, <b>sans impact sur le stock</b>. Les sorties/retours ne décrémentent ni n'incrémentent tes productions.</span></span></label>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button><button class="btn" onclick="saveMarket(${id||0})">Enregistrer</button></div>`);
  // suggestion intelligente basée sur l'historique des marchés clos
  marketPrevuSuggestion();
  mkParfumsTotal();
}
// Propose une quantité prévisionnelle d'après la moyenne des ventes des marchés passés.
// [v1431] Total vivant du bloc « Parfums visés », comparé à la quantité visée. Un écart n'est pas
// bloquant — Ben peut vouloir ventiler seulement une partie — mais il doit se VOIR : deux chiffres
// qui divergent sans le dire, c'est le défaut qu'on vient de corriger deux fois (v1429, v1430).
function mkParfumsTotal(){
  const box=document.getElementById('mk_parfSum'); if(!box) return;
  let tot=0, n=0;
  document.querySelectorAll('.mk-parf').forEach(el=>{ const v=+el.value||0; if(v>0){ tot+=v; n++; } });
  const cible=+((document.getElementById('mk_prevu')||{}).value)||0;
  if(!n){ box.textContent='— non renseignés'; box.style.color='#6a7a68'; return; }
  const ecart = cible>0 ? (tot-cible) : 0;
  box.innerHTML = `(${n} parfum${n>1?'s':''} · ${tot} pc${cible>0&&ecart!==0?` <b style="color:${ecart>0?'#b5701a':'#b3261e'}">${ecart>0?'+':''}${ecart} vs ${cible} visés</b>`:''})`;
  box.style.color='#6a7a68';
}
// [v1431] Pré-remplit les parfums avec la ventilation calculée par les moteurs existants.
// Écrase les valeurs affichées, jamais la base : rien n'est enregistré avant « Enregistrer ».
function mkAppliquerVentilation(){
  const sugg = window._mkVentilSuggeree || {};
  document.querySelectorAll('.mk-parf').forEach(el=>{
    const n = el.dataset.parfum;
    el.value = (sugg[n]>0) ? sugg[n] : '';
  });
  mkParfumsTotal();
  const nb = Object.keys(sugg).filter(k=>sugg[k]>0).length;
  toast(nb ? `Réparti sur ${nb} parfum(s) ✓` : 'Aucune répartition disponible');
}
async function marketPrevuSuggestion(){
  const hint=document.getElementById('mk_prevuHint'); if(!hint) return;
  try{
    const fc = await marketForecast();
    // [v1430] La moyenne dit sur COMBIEN de marchés elle se calcule, et ce qui a été mis de côté.
    // Une moyenne dont on ignore l'assiette n'est pas vérifiable — et c'est en la comparant au max
    // que Ben a repéré que quelque chose n'allait pas. Autant le lui dire d'emblée.
    const _ecartes = [];
    if(fc.nbSansDonnee>0) _ecartes.push(`${fc.nbSansDonnee} sans mouvement saisi`);
    if(fc.nbAVerifier>0)  _ecartes.push(`${fc.nbAVerifier} à vérifier (retours non comptés)`);
    const _note = _ecartes.length
      ? `<br><span style="color:#b5701a">⚠ ${_ecartes.join(' · ')} — écarté${_ecartes.length>1||fc.nbSansDonnee>1||fc.nbAVerifier>1?'s':''} du calcul sur ${fc.nbClos} marché(s) clos.</span>`
      : '';
    if(fc.nbMarches>0){
      hint.innerHTML = `💡 D'après ${fc.nbMarches} marché(s) exploitable(s) : ~<b>${fc.moyenneVendu}</b> macarons vendus en moyenne (max ${fc.maxVendu}). `+
        `<span class="act" onclick="document.getElementById('mk_prevu').value=${fc.suggestion}">Utiliser ${fc.suggestion}</span>${_note}`;
    } else if(fc.nbClos>0){
      // Des marchés clos, mais aucun exploitable : ne rien suggérer plutôt que suggérer n'importe
      // quoi. Un chiffre inventé sur du vide vaut moins que l'absence de chiffre.
      hint.innerHTML = `⚠ ${fc.nbClos} marché(s) clos, mais aucun exploitable pour une moyenne : `+
        `${fc.nbSansDonnee>0?`${fc.nbSansDonnee} sans mouvement saisi`:''}${fc.nbSansDonnee>0&&fc.nbAVerifier>0?', ':''}`+
        `${fc.nbAVerifier>0?`${fc.nbAVerifier} avec des retours non comptés`:''}. Complète les sorties/retours d'un marché passé pour obtenir une suggestion fiable.`;
    } else {
      hint.textContent = 'Aucun historique de marché pour le moment — la suggestion s’affinera après tes premiers marchés clôturés.';
    }
  }catch(e){ /* silencieux */ }
}
async function saveMarket(id){
  const nom=val('mk_nom'), date=val('mk_date');
  if(!nom){ toast('Nom obligatoire'); return; }
  if(!date){ toast('Date obligatoire'); return; }
  const o={nom, date, lieu:val('mk_lieu'), horaires:val('mk_horaires'), heures:+val('mk_heures')||0,
    meteo:val('mk_meteo'), notes:val('mk_notes'), prevuQte:+val('mk_prevu')||0, fondCaisse:+val('mk_fond')||0,
    coutStand:+val('mk_stand')||0, distanceKm:+val('mk_dist')||0, prixCarburant:+val('mk_carbu')||0, tempsRouteMin:+val('mk_route')||0, consoVehicule: val('mk_conso')!==''?(+val('mk_conso')||0):null};
  o.histo = !!document.getElementById('mk_histo')?.checked;
  // [v1431] Parfums visés. On n'enregistre QUE les lignes renseignées : une liste pleine de zéros
  // ferait croire au rétroplanning qu'une ventilation existe alors qu'elle dit « rien pour ce
  // parfum ». Tableau vide = pas de choix de Ben = le plan devine, comme avant.
  {
    const _pf = [];
    document.querySelectorAll('.mk-parf').forEach(el=>{
      const n = el.dataset.parfum, q = Math.round(+el.value||0);
      if(n && q>0) _pf.push({parfum:n, qte:q});
    });
    o.prevuParfums = _pf;
  }
  // --- Mode marché sur 2 jours consécutifs (création uniquement) ---
  const deux = !id && !!document.getElementById('mk_2jours')?.checked;
  if(deux){
    const date2 = val('mk_date2');
    if(!date2){ toast('Date du jour 2 obligatoire'); return; }
    if(date2 < date){ toast('La date du jour 2 doit être après le jour 1'); return; }
    const groupId = 'g'+Date.now();   // identifiant de regroupement des 2 fiches
    // Stand réparti moitié-moitié ; trajet (distance, carburant, temps) compté chaque jour (inchangé).
    const standMoit = money2((+val('mk_stand')||0)/2);
    const baseCommune = {
      nom, lieu:val('mk_lieu'), meteo:val('mk_meteo'), notes:val('mk_notes'),
      prevuQte:+val('mk_prevu')||0, fondCaisse:+val('mk_fond')||0,
      coutStand:standMoit, distanceKm:+val('mk_dist')||0, prixCarburant:+val('mk_carbu')||0,
      tempsRouteMin:+val('mk_route')||0, consoVehicule: val('mk_conso')!==''?(+val('mk_conso')||0):null,
      histo:o.histo, statut:'ouvert', ca:{especes:0,cb:0,autre:0}, mkGroup:groupId
    };
    const j1={...baseCommune, date, horaires:val('mk_horaires'), heures:+val('mk_heures')||0, mkGroupDay:1, mkGroupTotal:2};
    const j2={...baseCommune, date:date2, horaires:val('mk_horaires2'), heures:+val('mk_heures2')||0, mkGroupDay:2, mkGroupTotal:2};
    const id1=await db.markets.add(j1);
    const id2=await db.markets.add(j2);
    // Calendrier : un événement par jour.
    await db.events.add({date:j1.date, titre:'⛺ '+nom+' (J1/2)', type:'marche', refId:'mk'+id1}).catch(()=>{});
    await db.events.add({date:j2.date, titre:'⛺ '+nom+' (J2/2)', type:'marche', refId:'mk'+id2}).catch(()=>{});
    closeModal(); renderMarkets(); toast('Marché sur 2 jours créé ✓');
    return;
  }
  if(id){ await db.markets.update(id,o); }
  else { o.statut='ouvert'; o.ca={especes:0,cb:0,autre:0}; id=await db.markets.add(o); }
  // Connexion calendrier : un marché planifié apparaît dans l'agenda (type 'marche').
  const evRef='mk'+id;
  await db.events.where('refId').equals(evRef).delete().catch(()=>{});
  await db.events.add({date:o.date, titre:'⛺ '+nom+(o.prevuQte?` (${o.prevuQte} prévus)`:''), type:'marche', refId:evRef}).catch(()=>{});
  closeModal(); renderMarkets(); toast('Marché enregistré ✓');
}
async function delMarket(id){
  if(!confirm('Supprimer ce marché et son historique ? Les invendus non retournés ne seront pas recrédités.')) return;
  await doDelMarket(id);
}
async function doDelMarket(id){
  const mk=await db.markets.get(id);
  const moves=await db.marketMoves.where('marketId').equals(id).toArray().catch(()=>[]);
  const evs=await db.events.where('refId').equals('mk'+id).toArray().catch(()=>[]);
  const snap={market:mk?{...mk}:null, moves:moves.map(m=>({...m})), events:evs.map(e=>({...e}))};
  await db.transaction('rw', db.markets, db.marketMoves, async()=>{
    await db.marketMoves.where('marketId').equals(id).delete();
    await db.markets.delete(id);
  });
  await db.events.where('refId').equals('mk'+id).delete().catch(()=>{});
  renderMarkets();
  if(snap.market) showUndoToast('Marché supprimé', async()=>{
    await db.transaction('rw', db.markets, db.marketMoves, db.events, async()=>{
      await db.markets.put(snap.market);
      for(const m of snap.moves){ await db.marketMoves.put(m); }
      for(const e of snap.events){ await db.events.put(e); }
    });
    renderMarkets();
  });
  else toast('Marché supprimé ✓');
}

