function renderAssistant(){
  _aiPhotoPreview=null;   // aucune pièce jointe ne persiste entre deux visites
  document.getElementById('main').innerHTML=`
   <div class="topbar"><div><h1>Copilote</h1><p>Pose ta question, enchaîne la discussion</p></div></div>
   <div id="aiThread" style="min-height:38vh;max-height:62vh;overflow-y:auto;padding:4px 2px 8px"></div>
   <div id="aiOut"></div>
   <div class="panel" style="position:sticky;bottom:0;background:var(--paper,#fbf7f1);padding-top:10px">
     <div id="aiAttachWrap" style="display:none;margin-bottom:8px"></div>
     <input type="file" id="aiFileInput" accept=".txt,.csv,.md,.text,.pdf,text/plain,text/csv,text/markdown,application/pdf,image/*" style="display:none" onchange="aiAttachFile(this.files)">
     <div class="field" style="margin-bottom:6px">
       <input id="aiInput" type="text" inputmode="text" enterkeyhint="send" autocomplete="off"
         placeholder="Écris ta demande…" onkeydown="aiInputKey(event)" style="width:100%">
     </div>
     <div class="flex" style="gap:8px;flex-wrap:wrap">
       <button class="btn ghost" onclick="document.getElementById('aiFileInput').click()" title="Joindre un fichier .txt/PDF ou une photo">📎 Joindre</button>
       <button class="btn ghost" onclick="aiClearThread()">🗑️ Nouveau fil</button>
     </div>
   </div>`;
  // [v1065] Restauration du fil : si on revient sur le copilote après avoir suivi un raccourci
  // (ou navigué ailleurs), on retrouve la discussion telle qu'on l'a laissée — question, réponse
  // et raccourcis. Sinon (1re ouverture ou « Nouveau fil »), message d'accueil habituel.
  const _save = window._assistantThreadSave;
  if(_save && (_save.thread || _save.out)){
    const _th=document.getElementById('aiThread');
    const _ou=document.getElementById('aiOut');
    if(_th && _save.thread!=null) _th.innerHTML=_save.thread;
    if(_ou && _save.out!=null) _ou.innerHTML=_save.out;
    window._assistantThreadSave=null;   // consommé une fois
    // défilement en bas du fil restauré
    requestAnimationFrame(()=>{ if(_th) _th.scrollTop=_th.scrollHeight; });
    return;
  }
  // Message d'accueil discret dans le fil (épuré, pas de briefing proactif).
  aiPush('bot', `<p style="margin:0">Bonjour 👋 Je suis ton copilote de pilotage. Demande-moi un conseil, un stock, une recette, tes commandes… <span class="note">Je fonctionne hors-ligne ; toute action critique te demande validation.</span></p>${(typeof aiHabitsHTML==='function')?aiHabitsHTML():''}`);
}
// [CHAT — D1] Auto-agrandissement de l'input (1 à ~5 lignes), pour un ressenti de chat.
// Lance une suggestion rapide : remplit l'input et envoie.
var _aiOutThread='aiThread', _aiInField='aiInput', _palOpen=false;
function aiQuick(s){ const ta=document.getElementById(_aiInField); if(ta){ ta.value=s; } aiRun(); }
// Repart sur un fil vierge (non persistant : on vide simplement l'affichage).
function aiClearThread(){ window._assistantThreadSave=null; const t=document.getElementById('aiThread'); if(t){ t.innerHTML=''; } aiClarifyPending=null; aiPending=null; window._aiCurrentIntent=null; window._aiCurrentParams=null; renderAssistant(); }

// [LA VOIX] Rendu de l'encart de conseil proactif (écran Assistant).
