// TABLEAU DE BORD PROACTIF — « À faire aujourd'hui ».
// Agrège les signaux actionnables et les présente en tête de l'Assistant, classés par urgence.
// N'effectue AUCUNE action : observe, priorise et propose. Réutilise les détecteurs existants.
async function assistantBriefing(){
  const items=[]; // {prio:0 urgent|1 important|2 info, ico, titre, detail, action:{label,view}}
  const todayStr=today();
  const inDays=(dateStr)=>{ const j=daysTo(dateStr); return j; };

  // 1) COMMANDES proches (aujourd'hui / demain) non terminées
  try{
    const orders=await db.orders.toArray();
    const clients=await db.clients.toArray();
    const nm=id=>{ const c=clients.find(x=>x.id===id); return c?c.nom:'client'; };
    orders.forEach(o=>{
      const st=(typeof normStatus==='function')?normStatus(o.statut):o.statut;
      if(st==='Livrée'||st==='Terminée') return;
      const j=inDays(o.date); if(j===null) return;
      if(j<0){ items.push({prio:0, ico:'📦', titre:`Commande en retard — ${nm(o.clientId)}`, detail:`Retrait prévu ${fmtDate(o.date)} (${-j} j de retard).`, action:{label:'Voir les commandes', view:'commandes'}}); }
      else if(j===0){ items.push({prio:0, ico:'📦', titre:`Commande à préparer aujourd'hui — ${nm(o.clientId)}`, detail:`Retrait prévu aujourd'hui.`, action:{label:'Préparer', view:'commandes'}}); }
      else if(j===1){ items.push({prio:1, ico:'📦', titre:`Commande demain — ${nm(o.clientId)}`, detail:`Retrait prévu ${fmtDate(o.date)}.`, action:{label:'Voir', view:'commandes'}}); }
    });
  }catch(e){ console.error('briefing orders',e); }

  // 2) ANTI-GASPI : matières à DLC proche (réutilise le détecteur existant)
  try{
    const sugg=await generateProductionSuggestions(7);
    sugg.slice(0,5).forEach(s=>{
      const urgent=s.joursAvantDLC<=2;
      items.push({prio:urgent?0:1, ico:'♻️',
        titre:`À écouler : ${s.matiere}`,
        detail:`Produis des ${s.produitNom} — DLC ${s.joursAvantDLC<=0?'atteinte':'dans '+s.joursAvantDLC+' j'} (stock fini ${qty(s.stockFini)}).`,
        action:{label:'Lancer la production', view:'productions'}});
    });
  }catch(e){ console.error('briefing gaspi',e); }

  // 3) RUPTURES prédictives (réutilise computeSalesVelocity)
  try{
    const v=await computeSalesVelocity({months:3, horizonDays:14});
    if(v.hasData){ v.alertes.slice(0,5).forEach(a=>{
      const urgent=a.joursRestants<=7;
      items.push({prio:urgent?0:1, ico:'⚠️',
        titre:`Rupture prévue : ${a.parfum}`,
        detail:`~${a.joursRestants} j de stock au rythme actuel${a.dateRupture?` (vers ${fmtDate(a.dateRupture)})`:''}.`,
        action:{label:'Produire', view:'productions'}});
    }); }
  }catch(e){ console.error('briefing velocity',e); }

  // 4) DLC PRODUITS FINIS proches (lots finis qui périment)
  try{
    const prods=await db.productions.toArray();
    prods.forEach(p=>{
      if(round3(+p.qteRestante)<=0 || !p.dlcProduit) return;
      const c=p.composant||'complet'; if(c!=='complet'&&c!=='assemble') return;
      const j=daysTo(p.dlcProduit); if(j===null||j>3) return;
      items.push({prio:j<=1?0:1, ico:'🧊',
        titre:`Stock fini à DLC proche`,
        detail:`${qty(p.qteRestante)} pièce(s)${p.lotProduction?` (lot ${p.lotProduction})`:''} — DLC ${j<=0?'atteinte':'dans '+j+' j'}.`,
        action:{label:'Voir le stock', view:'stockparfums'}});
    });
  }catch(e){ console.error('briefing dlc',e); }

  items.sort((a,b)=>a.prio-b.prio);
  return items;
}


// ============================================================
//  PLAN DE PRODUCTION INTELLIGENT
//  Croise commandes + ruptures + anti-gaspi + réassort, chiffre les quantités (horizon 14 j),
//  estime le temps de chaque production via le temps lissé (brique 1), et cale dans le temps
//  dispo saisi par l'utilisateur. Ordre de priorité réordonnable et mémorisé.
// ============================================================
const PLAN_PRIO_KEY = 'sm_planPrioOrder';
const PLAN_PRIO_DEFAULT = ['commande','rupture','antigaspi','reassort'];
const PLAN_PRIO_LABEL = {commande:'Commandes fermes', rupture:'Ruptures imminentes', antigaspi:'Anti-gaspi (DLC matières)', reassort:'Réassort de confort'};
function planPrioOrder(){
  try{ const a=JSON.parse(localStorage.getItem(PLAN_PRIO_KEY)||'null');
    if(Array.isArray(a) && a.length===4 && PLAN_PRIO_DEFAULT.every(k=>a.includes(k))) return a; }catch(e){swallow(e,'planPrioOrder')}
  return [...PLAN_PRIO_DEFAULT];
}
function planPrioSave(arr){ try{ localStorage.setItem(PLAN_PRIO_KEY, JSON.stringify(arr)); }catch(e){swallow(e,'planPrioSave')} }

// Coques en stock par parfum, en NOMBRE DE COQUES (pas en macarons).
// 1 macaron = 2 coques. Le plan déduira ces coques du besoin de coques (besoin macarons × 2).
async function coquesStockByParfum(){
  const prods = await db.productions.toArray().catch(()=>[]);
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recName = rid => (recipes.find(r=>r.id===rid)||{}).produitNom||'';
  const map = {}; // parfum normalisé -> {parfum, coques}
  prods.forEach(p=>{
    if(prodComposant(p)!=='coques') return;
    const reste = round3(+p.qteRestante||0); if(reste<=0) return;  // reste = nb de coques
    const nom = prodNomComplet(p);
    if(!nom) return;
    const k = aiNormalize(nom);
    if(!map[k]) map[k]={parfum:nom, coques:0};
    map[k].coques += reste;
  });
  return map;
}

// [CONNEXION #2] Stock de COMPOSANTS déjà produits, par parfum : coques cuites et garnitures
// (ganache/crémeux) prêtes. Permet au cerveau de savoir ce qui est déjà fait pour ne pas
// faire reproduire inutilement. Renvoie { parfumNormalisé: {parfum, coques, garniture} }.
// - coques    : nombre de coques en stock (2 coques = 1 macaron)
// - garniture : nombre de doses de garniture en stock (1 dose = 1 macaron)
async function composantsStockByParfum(){
  const prods = await db.productions.toArray().catch(()=>[]);
  const map = {};
  prods.forEach(p=>{
    const comp = (typeof prodComposant==='function') ? prodComposant(p) : 'complet';
    const reste = round3(+p.qteRestante||0);
    if(reste<=0) return;
    // On ne s'intéresse qu'aux composants intermédiaires terminés (coques, ganache/crémeux),
    // pas aux produits finis (gérés par enStock du plan) ni aux composants catalogue mutualisés.
    if(comp!=='coques' && comp!=='ganache') return;
    if(p.composantCatalogue===true) return;   // chantache & co : réserve mutualisée, pas par parfum
    const fini = (typeof prodStatut==='function') ? prodStatut(p)==='termine' : true;
    if(!fini) return;
    const nom = (typeof prodNomComplet==='function') ? prodNomComplet(p) : '';
    if(!nom || nom==='(recette supprimée)') return;
    const k = (typeof aiNormalize==='function') ? aiNormalize(nom) : nom.toLowerCase();
    if(!map[k]) map[k]={parfum:nom, coques:0, garniture:0};
    if(comp==='coques') map[k].coques += reste;       // reste = nb de coques
    else if(comp==='ganache') map[k].garniture += reste; // reste = nb de doses
  });
  return map;
}
// Construit la liste des productions conseillées (avant calage temps).
// ============================================================================
// ORDONNANCEUR DE PRODUCTION — moteur d'optimisation des meringues (validé)
// Règles : meringue standard = 120 macarons / 3 parfums max ; grand format = 24
// gros macarons / 2 parfums max ; complément unique (3 plus gros restes) si total
// des restes >= 40, sinon "à décider" ; ganache par parfum en une fois = total
// planifié ; ganache vanille-coco partagée Mangue passion + Myrtille framboise.
// Fonctions PURES → rejouables à chaque ajustement.
// ============================================================================
const ORDO = { STD_CAP:120, STD_MAXP:3, GF_CAP:24, GF_MAXP:2, COMPLEMENT_MIN:40 };

// [v1251] ---- VUE COULEUR DU RÉTROPLANNING (en parallèle, sans toucher au moteur parfum) ----
// Convertit des besoins PAR PARFUM [{nom, qte}] en besoins EN COQUES PAR COULEUR, en tenant compte
// des recettes : un parfum monochrome (ex. chocolat = marron foncé ×2) demande 2 coques de sa couleur
// par macaron ; un bicolore (ex. praliné = marron foncé + blanc) demande 1 coque de chaque couleur.
// Renvoie [{nom:'Marron foncé (std)', couleur, gf, qte(coques), parfums:{parfum:coques}}].
function ordoBesoinsCouleur(besoinsParfum, recByNom){
  recByNom = recByNom || {};
  const parCouleur = {};   // clé "gf|couleur" -> {couleur, gf, coques, parfums:{}}
  (besoinsParfum||[]).forEach(b=>{
    const q = +b.qte||0; if(q<=0) return;
    const rec = recByNom[aiNormalize(b.nom)];
    const colors = recCoqueColors(rec);
    if(!colors.length) return;                    // parfum sans couleur définie → pas dans la vue couleur
    const gf = !!(rec && rec.grandFormat);
    // Comptabilise les coques par couleur : une couleur qui apparaît 2× dans la recette → 2 coques/macaron.
    const mult = {};
    colors.forEach(c=>{ mult[c] = (mult[c]||0) + 1; });
    Object.keys(mult).forEach(c=>{
      const coques = q * mult[c];                 // nb de coques de CETTE couleur pour q macarons
      const k = (gf?'1|':'0|')+c;
      const slot = parCouleur[k] || (parCouleur[k] = {couleur:c, gf, coques:0, parfums:{}});
      slot.coques += coques;
      slot.parfums[b.nom] = (slot.parfums[b.nom]||0) + coques;
    });
  });
  // On planifie les fournées en ÉQUIVALENT-MACARONS (comme le moteur parfum : cap = macarons).
  // 1 macaron standard = 2 coques ; on convertit donc les coques en « équivalent-macarons » pour
  // réutiliser ordoPackFull tel quel (capacité 120 = 120 macarons = 240 coques std).
  const items = Object.keys(parCouleur).map(k=>{
    const s = parCouleur[k];
    return {
      nom: coqueCouleurLabel(s.couleur)+(s.gf?' (GF)':''),
      couleur: s.couleur, gf: s.gf,
      coques: round3(s.coques),
      qte: Math.ceil(round3(s.coques)/COQUES_PAR_MACARON),   // équivalent-macarons pour le packing
      parfums: s.parfums
    };
  });
  return items;
}
// Construit le plan de fournées PAR COULEUR : standard et GF séparés, chacun packé sous sa capacité.
// Réutilise ordoPackFull/ordoPackAll (mécanique de capacité éprouvée). maxP = max 3 couleurs / fournée.
function ordoPlanCouleur(besoinsParfum, recByNom){
  const items = ordoBesoinsCouleur(besoinsParfum, recByNom);
  const std = items.filter(i=>!i.gf);
  const gf  = items.filter(i=> i.gf);
  const packStd = ordoPackFull(std, ORDO.STD_CAP, ORDO.STD_MAXP);
  const compStd = ordoComplement(packStd.restes, ORDO.STD_CAP, ORDO.STD_MAXP, ORDO.COMPLEMENT_MIN);
  const packGF  = ordoPackAll(gf, ORDO.GF_CAP, ORDO.GF_MAXP);
  // Ré-attache la couleur/parfums à chaque part (ordoPackFull ne connaît que nom+qte).
  const metaByNom = {}; items.forEach(i=>metaByNom[i.nom]=i);
  const enrich = m => { m.parts.forEach(p=>{ const meta=metaByNom[p.nom]; if(meta){ p.couleur=meta.couleur; p.gf=meta.gf; p.parfums=meta.parfums; } }); return m; };
  (packStd.meringues||[]).forEach(enrich);
  if(compStd.meringue) compStd.meringue.forEach(enrich);
  (packGF||[]).forEach(enrich);
  return {
    items,
    standard:{ meringuesPleines:packStd.meringues, complement:compStd.meringue, restes:compStd.restes },
    grandFormat:{ meringues:packGF }
  };
}


// Remplit des meringues PLEINES (capacité atteinte) pour minimiser leur nombre ; renvoie les restes.
function ordoPackFull(besoins, cap, maxP){
  let items=besoins.filter(b=>b.qte>0).map(b=>({nom:b.nom,reste:b.qte}));
  const meringues=[];
  while(true){
    const tot=items.reduce((s,it)=>s+it.reste,0);
    if(tot<cap) break;
    const m={cap,libre:cap,parts:[]};
    while(m.libre>0 && m.parts.length<maxP){
      const cand=items.filter(it=>it.reste>0 && !m.parts.some(p=>p.nom===it.nom)).sort((a,b)=>b.reste-a.reste)[0];
      if(!cand) break;
      const pris=Math.min(cand.reste,m.libre);
      m.parts.push({nom:cand.nom,qte:pris}); cand.reste-=pris; m.libre-=pris;
    }
    m.utilise=m.cap-m.libre;
    if(m.libre>0){ meringues.push(m); break; }
    meringues.push(m);
    if(meringues.length>500) break;
  }
  return {meringues, restes:items.filter(it=>it.reste>0).map(it=>({nom:it.nom,qte:it.reste}))};
}

// Empile tout (sans exiger des meringues pleines) — pour les grands formats.
function ordoPackAll(besoins, cap, maxP){
  let items=besoins.filter(b=>b.qte>0).map(b=>({nom:b.nom,reste:b.qte}));
  const meringues=[];
  while(items.some(it=>it.reste>0)){
    const m={cap,libre:cap,parts:[]};
    while(m.libre>0 && m.parts.length<maxP){
      const cand=items.filter(it=>it.reste>0 && !m.parts.some(p=>p.nom===it.nom)).sort((a,b)=>b.reste-a.reste)[0];
      if(!cand) break;
      const pris=Math.min(cand.reste,m.libre);
      m.parts.push({nom:cand.nom,qte:pris}); cand.reste-=pris; m.libre-=pris;
    }
    m.utilise=m.cap-m.libre; meringues.push(m);
    if(meringues.length>500) break;
  }
  return meringues;
}

// UNE meringue de complément avec les 3 plus gros restes ; le surplus passe "à décider".
function ordoComplement(restes, cap, maxP, seuil){
  const tot=restes.reduce((s,r)=>s+r.qte,0);
  if(tot===0) return {meringue:null, restes:[], total:0};
  if(tot<seuil) return {meringue:null, restes:restes.slice(), total:tot};
  const tries=restes.slice().sort((a,b)=>b.qte-a.qte);
  const retenus=tries.slice(0,maxP), exclus=tries.slice(maxP);
  const m={cap,libre:cap,parts:[]}; const surplus=[];
  retenus.forEach(r=>{
    const pris=Math.min(r.qte,m.libre);
    if(pris>0){ m.parts.push({nom:r.nom,qte:pris}); m.libre-=pris; }
    if(r.qte-pris>0) surplus.push({nom:r.nom,qte:r.qte-pris});
  });
  m.utilise=m.cap-m.libre;
  return {meringue:[m], restes:exclus.concat(surplus), total:tot};
}

// Moteur principal : besoins standards + grands formats → plan optimisé complet.
function ordonnancer(besoinsStd, besoinsGF){
  const std=ordoPackFull(besoinsStd, ORDO.STD_CAP, ORDO.STD_MAXP);
  const comp=ordoComplement(std.restes, ORDO.STD_CAP, ORDO.STD_MAXP, ORDO.COMPLEMENT_MIN);
  const planParfums={};
  std.meringues.forEach(m=>m.parts.forEach(p=>{ planParfums[p.nom]=(planParfums[p.nom]||0)+p.qte; }));
  if(comp.meringue) comp.meringue.forEach(m=>m.parts.forEach(p=>{ planParfums[p.nom]=(planParfums[p.nom]||0)+p.qte; }));
  const ganaches=Object.entries(planParfums).map(([nom,qte])=>({nom,portions:qte}));
  const gf=ordoPackAll(besoinsGF, ORDO.GF_CAP, ORDO.GF_MAXP);
  const planGF={}; gf.forEach(m=>m.parts.forEach(p=>{ planGF[p.nom]=(planGF[p.nom]||0)+p.qte; }));
  const ganacheVanilleCoco=(planGF['Mangue passion']||0)+(planGF['Myrtille framboise']||0);
  return {
    standard:{ meringuesPleines:std.meringues, complement:comp.meringue,
               restesADecider:comp.restes, totalRestes:comp.total, ganaches },
    grandFormat:{ meringues:gf, planParfums:planGF, ganacheVanilleCoco }
  };
}

// Prépare les besoins par parfum (standards / grands formats) selon le mode choisi.
// mode 'fermes' = commandes fermes − stock ; mode 'reassort' = commandes + réassort − stock ;
// mode 'marches' = commandes + marchés programmés − stock.
// La PROVENANCE de chaque besoin (commande ferme / marché / réassort) est tracée séparément
// pour être affichée sans ambiguïté (jamais de mélange opaque).
async function ordoBuildNeeds(mode, horizon){
  const H=horizon||14;
  const recipes=await db.recipes.toArray().catch(()=>[]);
  const recByNom={}; recipes.forEach(r=>recByNom[aiNormalize(r.produitNom)]=r);
  const isGF=nom=>{ const r=recByNom[aiNormalize(nom)]; return !!(r&&r.grandFormat); };
  const besoins={};   // nom -> qte (macarons)
  const provenance={};  // nom -> {cmd, marche, reassort}
  const _prov=(nom)=> (provenance[nom] ||= {cmd:0, marche:0, reassort:0});
  const add=(nom,q,src)=>{ if(!nom||q<=0) return; besoins[nom]=(besoins[nom]||0)+q; if(src) _prov(nom)[src]+=q; };

  // 1) Commandes fermes non livrées dans l'horizon (toujours incluses).
  try{
    const orders=await db.orders.toArray();
    orders.forEach(o=>{
      const st=(typeof normStatus==='function')?normStatus(o.statut):o.statut;
      if(st==='Livrée') return;
      const j=(typeof daysTo==='function')?daysTo(o.date):null;
      if(j!==null && j>H) return;
      orderToLines(o).forEach(ln=>{
        const parfums = ln.type==='grand' ? (ln.items||[]) : (ln.parfums||[]);
        parfums.forEach(p=>{ if(+p.qte>0) add(p.nom, +p.qte, 'cmd'); });
      });
    });
  }catch(e){ console.error('ordo orders',e); }

  // [v1435] MARCHÉS PROGRAMMÉS — DANS TOUS LES MODES.
  // Avant : `if(mode==='marches' || mode==='auto')`. Or l'écran ne propose que « Commandes
  // fermes » et « Commandes + réassort » : aucun bouton ne passait jamais par ici. C'était la
  // réponse à la question de Ben — le code marchait, il n'était jamais atteint.
  // Un marché programmé est une échéance ferme : on ne s'y présente pas les mains vides.
  try{
    const mks = await db.markets.toArray().catch(()=>[]);
    const rep = await (async()=>{ try{ const mf=await marketForecast(); return (mf&&mf.repartition)||[]; }catch(e){ return []; } })();
    const besoinMk = besoinMarchesParParfum(mks, rep, besoins, {horizonJours:H});
    for(const nom in besoinMk){ add(nom, besoinMk[nom], 'marche'); }
  }catch(e){ console.error('ordo marchés',e); }

  // 2) Réassort (vélocité − stock) seulement en mode 'reassort'.
  if(mode==='reassort'){
    try{
      const v=await computeSalesVelocity({months:3, horizonDays:H});
      if(v.hasData){ (v.lignes||[]).forEach(l=>{
        if(l.perDay<=0) return;
        const besoin=Math.ceil(l.perDay*H - l.stock);
        if(besoin>0) add(l.parfum, besoin, 'reassort');
      }); }
    }catch(e){ console.error('ordo velocity',e); }
  }

  // 3) Note : en mode réassort, le stock est déjà déduit via la vélocité (perDay*H − stock).
  //    En mode 'fermes', on produit ce qui est commandé (le stock fini sert d'abord les commandes).

  // 3) Déduire les COQUES déjà en stock (typées par parfum) : on ne reproduit pas la meringue
  //    pour des coques qu'on a déjà. On trace la déduction pour l'affichage.
  const coquesInfo={};   // nom -> {demande, coquesMac, aProduire}
  try{
    const coquesMap = await coquesStockByParfum();   // {normalisé:{parfum, coques}}
    Object.keys(besoins).forEach(nom=>{
      const k=aiNormalize(nom);
      const coques = coquesMap[k] ? +coquesMap[k].coques||0 : 0;
      const coquesMac = Math.floor(coques / COQUES_PAR_MACARON);   // coques → macarons assemblables
      if(coquesMac>0){
        const demande = besoins[nom];
        const aProduire = Math.max(0, demande - coquesMac);
        coquesInfo[nom] = { demande, coquesMac, aProduire };
        besoins[nom] = aProduire;
      }
    });
  }catch(e){ console.error('ordo coques',e); }

  // 3b) GARNITURES (ganache/crémeux) déjà en stock par parfum : ne réduisent PAS le besoin de
  // macarons (donc pas les meringues/coques), mais réduiront le besoin de GANACHE à produire.
  const garnitureStock={};   // nom normalisé -> {parfum, doses}
  try{
    const compMap = await composantsStockByParfum();   // {normalisé:{parfum, coques, garniture}}
    Object.keys(compMap).forEach(k=>{
      const g = +compMap[k].garniture||0;
      if(g>0) garnitureStock[k] = { parfum:compMap[k].parfum, doses:g };
    });
  }catch(e){ console.error('ordo garniture',e); }

  // Sépare standards / grands formats.
  const std=[], gf=[];
  Object.entries(besoins).forEach(([nom,qte])=>{ if(qte>0){ (isGF(nom)?gf:std).push({nom,qte:Math.round(qte)}); } });

  // ANTI-GASPI : on SIGNALE les parfums dont une matière approche de sa DLC (sans imposer de
  // quantité — à toi de saisir). Affiché toujours, même si le parfum a déjà une commande.
  let antigaspi=[];
  try{
    const sugg = (typeof generateProductionSuggestions==='function') ? await generateProductionSuggestions(7) : [];
    const vus=new Set();
    (sugg||[]).forEach(s=>{
      const k=aiNormalize(s.produitNom);
      if(vus.has(k)) return; vus.add(k);
      antigaspi.push({ parfum:s.produitNom, matiere:s.matiere, joursAvantDLC:s.joursAvantDLC, cremeOuverte:!!s.cremeOuverte });
    });
    antigaspi.sort((a,b)=>(a.joursAvantDLC??99)-(b.joursAvantDLC??99));
  }catch(e){ console.error('ordo antigaspi',e); }

  // 3c) COMPOSANTS CATALOGUE des grands formats (chantache & co) : suivi GLOBAL mutualisé.
  // 1 pièce GF = 1 dose de chacun de ses composants requis (componentRefs). On agrège le besoin
  // sur tous les GF planifiés, on le compare au stock de composant disponible, on chiffre le manque.
  let composantsGF=[];
  try{
    const refsParRec = {};   // nom normalisé -> [componentId,...]
    recipes.forEach(r=>{
      if(r.grandFormat && Array.isArray(r.componentRefs) && r.componentRefs.length){
        const vus=new Set(), ids=[];
        r.componentRefs.forEach(ref=>{ const cid=+ref.componentId; if(cid && !vus.has(cid)){ vus.add(cid); ids.push(cid); } });
        if(ids.length) refsParRec[aiNormalize(r.produitNom)] = ids;
      }
    });
    // besoin par composant = somme des pièces GF qui le requièrent
    const besoinParComp={};
    gf.forEach(g=>{
      const ids = refsParRec[aiNormalize(g.nom)];
      if(!ids) return;
      ids.forEach(cid=>{ besoinParComp[cid]=(besoinParComp[cid]||0)+g.qte; });
    });
    if(Object.keys(besoinParComp).length){
      const comps = await db.components.toArray().catch(()=>[]);
      const compNom={}; comps.forEach(c=>compNom[+c.id]=c.nom||'composant');
      const prodsAll = await db.productions.toArray().catch(()=>[]);
      // stock mutualisé par composant = somme des qteRestante des productions composantCatalogue
      const stockComp={};
      prodsAll.forEach(p=>{
        if(p.composantCatalogue!==true) return;
        const cid=+p.componentId; if(!cid) return;
        const fini=(typeof prodStatut==='function')?prodStatut(p)==='termine':true;
        if(!fini) return;
        stockComp[cid]=(stockComp[cid]||0)+round3(+p.qteRestante||0);
      });
      for(const cid in besoinParComp){
        const besoin=besoinParComp[cid];
        const dispo=+stockComp[cid]||0;
        composantsGF.push({ componentId:+cid, nom:compNom[cid]||'composant',
          besoin, dispo, manque:Math.max(0, round3(besoin-dispo)) });
      }
    }
  }catch(e){ console.error('ordo composants GF',e); }

  return {std, gf, coquesInfo, provenance, antigaspi, garnitureStock, composantsGF};
}

let _ordoState=null;   // {mode, std:[...], gf:[...]} — pour l'ajustement (étape 3)

// Affiche le plan optimisé dans un conteneur, à partir des besoins (recalcul pur à chaque appel).
function ordoRenderPlan(containerId){
  const box=document.getElementById(containerId); if(!box||!_ordoState) return;
  const plan=ordonnancer(_ordoState.std, _ordoState.gf);
  const s=plan.standard, gf=plan.grandFormat;
  const meringueHTML=(m,label,col)=>`<div class="sum-box" style="border-left:3px solid ${col};margin:4px 0">
    <span style="flex:1"><b>${label}</b> <span style="color:#9a8a82">${m.utilise}/${m.cap} macarons</span><br>
    <span style="font-size:.85rem">${m.parts.map(p=>`${esc(p.nom)} <b>${p.qte}</b>`).join(' &nbsp;·&nbsp; ')}</span>
    ${m.libre>0?`<br><span style="font-size:.74rem;color:#9a8a82">reste ${m.libre} place(s) libre(s)</span>`:''}</span></div>`;

  let html='<div class="panel"><h2>🔥 Plan de production optimisé</h2>';
  // Mode actif + bascule
  html+=`<div style="display:flex;gap:6px;margin-bottom:10px;flex-wrap:wrap">
    <button class="btn ${_ordoState.mode==='fermes'?'gold':'ghost'} sm" onclick="ordoSwitchMode('fermes')">Commandes fermes</button>
    <button class="btn ${_ordoState.mode==='marches'?'gold':'ghost'} sm" onclick="ordoSwitchMode('marches')">Commandes + marchés</button>
    <button class="btn ${_ordoState.mode==='reassort'?'gold':'ghost'} sm" onclick="ordoSwitchMode('reassort')">Commandes + réassort</button>
  </div>`;

  // VENTILATION par origine (commande ferme / marché / réassort) — jamais de mélange opaque.
  const prov=_ordoState.provenance||{};
  const provList=Object.entries(prov).filter(([n,v])=>v && (v.cmd>0||v.marche>0||v.reassort>0));
  if(provList.length){
    html+=`<div class="banner" style="background:#f7f4fb;border-color:#d8c9e6;margin-bottom:10px">🧭 <div><b>D'où vient chaque besoin :</b><br>${
      provList.map(([nom,v])=>{
        const parts=[];
        if(v.cmd>0) parts.push(`<span style="color:#7a4b82">cmd ${Math.round(v.cmd)}</span>`);
        if(v.marche>0) parts.push(`<span style="color:#AA7C39">marché ${Math.round(v.marche)}</span>`);
        if(v.reassort>0) parts.push(`<span style="color:#d98324">réassort ${Math.round(v.reassort)}</span>`);
        return `${esc(nom)} — ${parts.join(' + ')}`;
      }).join('<br>')
    }</div></div>`;
  }

  // ANTI-GASPI : signalement des parfums à produire en priorité pour écouler une matière
  // dont la DLC approche (sans quantité imposée — info complémentaire).
  const ag=_ordoState.antigaspi||[];
  if(ag.length){
    html+=`<div class="banner" style="background:#eef5f0;border-color:#bcd9c4;margin-bottom:10px">♻️ <div><b>Anti-gaspi — pense à écouler :</b><br>${
      ag.map(a=>`${esc(a.parfum)} <span style="color:#7a6a62;font-size:.85rem">— ${esc(a.matiere)}${a.cremeOuverte?' (entamé)':''}, DLC ${a.joursAvantDLC<=0?'atteinte':'J−'+a.joursAvantDLC}</span>`).join('<br>')
    }<br><span style="font-size:.78rem;color:#7a6a62">À intégrer librement à tes fournées si tu produis ces parfums.</span></div></div>`;
  }

  // 3e ÉLÉMENT des grands formats (chantache & co) : suivi GLOBAL mutualisé.
  const cgf=_ordoState.composantsGF||[];
  if(cgf.length){
    const manquants=cgf.filter(c=>c.manque>0);
    const couleur = manquants.length ? '#b3261e' : '#3f7d52';
    const fond = manquants.length ? '#fdf3f2' : '#eef5f0';
    const bord = manquants.length ? '#f0c9c4' : '#bcd9c4';
    html+=`<div class="banner" style="background:${fond};border-color:${bord};margin-bottom:10px">🧩 <div><b>3ᵉ élément des grands formats :</b><br>${
      cgf.map(c=>{
        const etat = c.manque>0
          ? `<span style="color:#b3261e">manque ${c.manque}</span> (besoin ${c.besoin}, en stock ${round3(c.dispo)})`
          : `<span style="color:#3f7d52">✓ couvert</span> (besoin ${c.besoin}, en stock ${round3(c.dispo)})`;
        return `${esc(c.nom)} — ${etat}`;
      }).join('<br>')
    }</div></div>`;
  }

  // Coques déjà en stock, déduites du besoin (signalé clairement).
  const cInfo=_ordoState.coquesInfo||{};
  const cList=Object.entries(cInfo).filter(([n,v])=>v.coquesMac>0);
  if(cList.length){
    html+=`<div class="banner" style="background:#eef5f0;border-color:#bcd9c4;margin-bottom:10px">🟤 <div><b>Coques déjà en stock déduites :</b><br>${cList.map(([nom,v])=>`${esc(nom)} — ${v.demande} demandé(s), ${v.coquesMac} en coques → <b>${v.aProduire} à produire</b>`).join('<br>')}</div></div>`;
  }

  // --- Standards ---
  const nbStd=s.meringuesPleines.length+(s.complement?s.complement.length:0);
  if(nbStd===0 && !s.restesADecider.length){
    html+='<p class="note">Aucun besoin standard à produire.</p>';
  } else {
    html+=`<h3 style="font-size:.95rem;margin:8px 0 4px">Macarons standards — ${nbStd} meringue(s)</h3>`;
    s.meringuesPleines.forEach((m,i)=>{ html+=meringueHTML(m,`Meringue ${i+1}`,'#3f7d52'); });
    if(s.complement) s.complement.forEach((m,i)=>{ html+=meringueHTML(m,`Meringue complément`,'#d98324'); });
    if(s.restesADecider.length){
      html+=`<div class="banner" style="background:#fdecec;border-color:#e0a0a0;margin-top:6px">⚠ <div><b>À décider</b> — ${s.restesADecider.map(r=>`${esc(r.nom)} ${r.qte}`).join(', ')}.<br><span style="font-size:.82rem">Ces restes ne remplissent pas une meringue de complément (max 3 parfums). Abandonne-les, ou ajuste les quantités pour les intégrer.</span></div></div>`;
    }
    // Ganaches
    if(s.ganaches.length){
      const gStock=_ordoState.garnitureStock||{};
      const lignesGan=[]; const dejaCouvert=[];
      s.ganaches.forEach(g=>{
        const k=(typeof aiNormalize==='function')?aiNormalize(g.nom):(g.nom||'').toLowerCase();
        const dispo = gStock[k] ? +gStock[k].doses||0 : 0;
        const net = Math.max(0, g.portions - dispo);
        if(dispo>0) dejaCouvert.push(`${esc(g.nom)} ${Math.min(dispo,g.portions)}/${g.portions}`);
        if(net>0) lignesGan.push(`${esc(g.nom)} <b>${net}</b>`);
      });
      if(lignesGan.length){
        html+=`<p style="font-size:.85rem;margin-top:8px"><b>🍫 Ganaches à produire</b> (chacune en une fois) : ${lignesGan.join(' · ')}</p>`;
      }
      if(dejaCouvert.length){
        html+=`<p style="font-size:.8rem;margin-top:2px;color:#3f7d52">🍫 Déjà en stock (garniture déduite) : ${dejaCouvert.join(' · ')}</p>`;
      }
      if(!lignesGan.length && dejaCouvert.length){
        html+=`<p style="font-size:.8rem;color:#3f7d52">✓ Toutes les garnitures nécessaires sont déjà en stock.</p>`;
      }
    }
  }

  // --- Grands formats ---
  if(gf.meringues.length){
    html+=`<h3 style="font-size:.95rem;margin:12px 0 4px">Grands formats — ${gf.meringues.length} meringue(s)</h3>`;
    gf.meringues.forEach((m,i)=>{ html+=meringueHTML(m,`Meringue GF ${i+1}`,'#8a6d3b'); });
    if(gf.ganacheVanilleCoco>0){
      html+=`<p style="font-size:.85rem;margin-top:6px"><b>🍦 Ganache vanille-coco partagée</b> (Mangue passion + Myrtille framboise) : <b>${gf.ganacheVanilleCoco}</b> portions.</p>`;
    }
  }

  // Ajustement
  // TEMPS DE PRODUCTION estimé (par parfum) vs disponibilité du planning.
  const ti=_ordoState.tempsInfo;
  if(ti && ti.totMin>0){
    const fmtH = min => { const h=Math.floor(min/60), m=Math.round(min%60); return h>0?`${h} h${m>0?' '+m:''}`:`${m} min`; };
    const sourceTxt = ti.nbParfumsTempsPropre>0
      ? `${ti.nbParfumsTempsPropre}/${ti.nbParfums} parfum(s) avec ton temps réel appris, le reste sur ta moyenne`
      : `estimé sur ta moyenne globale`;
    let dispoTxt='', fond='#eef5f0', bord='#bcd9c4';
    if(ti.planningRenseigne && ti.dispoMin!=null){
      if(ti.depasse){ fond='#fdf3f2'; bord='#f0c9c4';
        dispoTxt = `<br><b style="color:#b3261e">⚠ Dépasse ta dispo de ${fmtH(ti.totMin-ti.dispoMin)}</b> (dispo ${fmtH(ti.dispoMin)} sur 14 j).`;
      } else {
        dispoTxt = `<br><span style="color:#3f7d52">✓ Tient dans ta dispo</span> (${fmtH(ti.dispoMin)} sur 14 j).`;
      }
    } else {
      dispoTxt = `<br><span style="color:#9a8a82">Renseigne ton planning pour comparer à ta dispo.</span>`;
    }
    html+=`<div class="banner" style="background:${fond};border-color:${bord};margin-top:10px">⏱ <div><b>Temps de production estimé : ${fmtH(ti.totMin)}</b> pour ${qty(ti.totMac)} macaron(s)<br><span style="font-size:.82rem;color:#7a6a62">${sourceTxt}${ti.minParMacMoyen?` · ~${ti.minParMacMoyen} min/macaron`:''}.</span>${dispoTxt}</div></div>`;
  }

  // MATIÈRES PREMIÈRES nécessaires à ce plan (+ bouton liste de courses si manque).
  const mc=_ordoState.matCheck;
  if(mc){
    if(mc.ok){
      html+=`<div class="banner" style="background:#eef6ee;border-color:#bcdcc0;margin-top:10px">✅ <div><b>Matières premières : tout est en stock</b> pour réaliser ce plan.</div></div>`;
    } else {
      html+=`<div class="banner" style="background:#fdf3f2;border-color:#f0c9c4;margin-top:10px">🛒 <div><b>Matières manquantes pour ce plan :</b><br>${
        mc.manques.map(m=>`${esc(m.nom)} <span style="color:#9a8a82">stock ${qty(m.stockAff)} ${esc(m.unite)} · besoin ${qty(m.besoinAff)} ${esc(m.unite)}</span> — <b style="color:#b3261e">manque ${qty(m.manqueAff)} ${esc(m.unite)}</b>`).join('<br>')
      }<div style="margin-top:8px"><button class="btn ghost sm" onclick="ordoShoppingFromPlan()">🛒 Ajouter à la liste de courses</button></div></div></div>`;
    }
  }

  html+=`<div style="margin-top:12px"><button class="btn ghost sm" onclick="ordoAjuster()">✏️ Ajuster les quantités</button></div>`;
  html+='</div>';

  // [v1251] VUE COULEUR (parallèle) — regroupe les besoins par couleur de coque et propose des fournées
  // de meringue où une même fournée peut contenir plusieurs couleurs (sous la capacité max).
  try{
    const recByNom = _ordoState.recByNom || {};
    const planC = ordoPlanCouleur([...(_ordoState.std||[]), ...(_ordoState.gf||[])], recByNom);
    const sansCouleur = ((_ordoState.std||[]).concat(_ordoState.gf||[]))
      .filter(b=>+b.qte>0 && !recCoqueColors(recByNom[aiNormalize(b.nom)]).length)
      .map(b=>b.nom);
    if(planC.items.length){
      const merHTML=(m,label,col)=>`<div class="sum-box" style="border-left:3px solid ${col};margin:4px 0">
        <span style="flex:1"><b>${label}</b> <span style="color:#9a8a82">${m.utilise}/${m.cap} (équiv. macarons)</span><br>
        <span style="font-size:.85rem">${m.parts.map(p=>`${p.couleur?coqueCouleurPastille(p.couleur):''}${esc(p.nom)} <b>${p.qte}</b>`).join(' &nbsp;·&nbsp; ')}</span>
        ${m.parts.map(p=>{
          if(!p.parfums) return '';
          const det=Object.keys(p.parfums).map(nm=>`${esc(nm)} (${qty(p.parfums[nm])} coques)`).join(', ');
          return `<br><span style="font-size:.72rem;color:#9a8a82">↳ ${esc(p.nom)} → ${det}</span>`;
        }).join('')}
        ${m.libre>0?`<br><span style="font-size:.74rem;color:#9a8a82">reste ${m.libre} place(s)</span>`:''}</span></div>`;
      let cHtml=`<div class="panel enc-collapsible" id="enc-ordocouleur" style="border:1.5px solid #d8c9e6;background:#f9f6fc;margin-top:12px">
        <div class="enc-head" onclick="encToggle('enc-ordocouleur')"><h2 style="color:#6a4b82;margin:0">🎨 Vue par couleur de coques <span style="font-weight:400;font-size:.8rem;color:#9a8a82">— fournées mutualisées (aperçu, n'affecte pas le plan ci-dessus)</span></h2><span class="enc-chev">▸</span></div>
        <div class="enc-body" style="display:none">
        <p class="note" style="margin-bottom:8px">Une meringue peut regrouper jusqu'à ${ORDO.STD_MAXP} couleurs sous la capacité de ${ORDO.STD_CAP}. Les coques d'une couleur servent ensuite tous les parfums de cette couleur.</p>`;
      (planC.standard.meringuesPleines||[]).forEach((m,i)=> cHtml+=merHTML(m, `Fournée couleur #${i+1}`, '#8e6fb0'));
      if(planC.standard.complement) planC.standard.complement.forEach((m,i)=> cHtml+=merHTML(m, `Fournée complément`, '#b79fd0'));
      if(planC.standard.restes && planC.standard.restes.length){
        cHtml+=`<div class="sum-box" style="background:#fff"><span style="flex:1;font-size:.8rem;color:#9a8a82">Restes à décider : ${planC.standard.restes.map(r=>esc(r.nom)+' '+r.qte).join(' · ')}</span></div>`;
      }
      if(planC.grandFormat.meringues && planC.grandFormat.meringues.length){
        cHtml+=`<p class="note" style="margin:10px 0 4px"><b>Grands formats</b> (réserve séparée) :</p>`;
        planC.grandFormat.meringues.forEach((m,i)=> cHtml+=merHTML(m, `Fournée GF #${i+1}`, '#8a6d3b'));
      }
      if(sansCouleur.length){
        cHtml+=`<p class="note" style="margin-top:8px;color:#b0791f">⚠ Sans couleur définie (non pris en compte ici) : ${sansCouleur.map(esc).join(', ')} — renseigne leur couleur dans la fiche recette.</p>`;
      }
      cHtml+='</div></div>';
      html+=cHtml;
    }
  }catch(e){ console.error('ordo vue couleur',e); }

  box.innerHTML=html;
}

// Lance l'ordonnanceur : choisit le mode, calcule les besoins, affiche.
async function ordoLancer(mode){
  const box=document.getElementById('ordoZone'); if(box) box.innerHTML='<div class="panel"><p class="note">Calcul du plan optimisé…</p></div>';
  const needs=await ordoBuildNeeds(mode, 14);
  _ordoState={mode, std:needs.std, gf:needs.gf, coquesInfo:needs.coquesInfo||{}, provenance:needs.provenance||{}, antigaspi:needs.antigaspi||[], garnitureStock:needs.garnitureStock||{}, composantsGF:needs.composantsGF||[]};
  // [v1251] Index recettes par nom normalisé pour la VUE COULEUR (parallèle, ne modifie pas le plan parfum).
  try{ const _recs=await db.recipes.toArray(); const _m={}; _recs.forEach(r=>_m[aiNormalize(r.produitNom)]=r); _ordoState.recByNom=_m; }catch(e){ _ordoState.recByNom={}; }
  // Vérification des matières premières nécessaires à CE plan (réutilise mrpCheckMatieres).
  try{ _ordoState.matCheck = await ordoCheckMatieres(needs); }catch(e){ console.error('ordo matières',e); _ordoState.matCheck=null; }
  // Estimation du TEMPS de production (temps appris PAR PARFUM si fiable, sinon moyenne globale)
  // confronté à la disponibilité du planning — même logique que le conseil du chef.
  try{ _ordoState.tempsInfo = await ordoEstimeTemps(needs); }catch(e){ console.error('ordo temps',e); _ordoState.tempsInfo=null; }
  ordoRenderPlan('ordoZone');
}

// Estime le temps total de production du plan ordonnanceur, parfum par parfum (temps propre
// si fiable, sinon moyenne lissée), et le compare à la dispo cumulée sur l'horizon (14 j).
async function ordoEstimeTemps(needs){
  let minParMac=null, lisseFiable=false, tppMap={};
  try{ const tl=await prodTempsLissePerMacaron(90); minParMac=(tl&&tl.minParMacaron)?tl.minParMacaron:null; lisseFiable=!!(tl&&tl.fiable); }catch(e){swallow(e,'ordoEstimeTemps')}
  try{ tppMap=(typeof prodTempsParParfum==='function')?await prodTempsParParfumParNom(90):{}; }catch(e){ tppMap={}; }
  if(minParMac==null && !Object.keys(tppMap).length) return null;   // aucune donnée de temps
  const minParMacDe = parfum=>{
    const k=aiNormalize(parfum);
    const tp=tppMap[k];
    return (tp && tp.fiable && tp.minParMac>0) ? tp.minParMac : minParMac;
  };
  const lignes=[...(needs.std||[]),...(needs.gf||[])];
  let totMac=0, totMin=0, nbParfumsTempsPropre=0;
  lignes.forEach(l=>{
    const m=minParMacDe(l.nom);
    totMac+=(+l.qte||0);
    if(m!=null) totMin+=(+l.qte||0)*m;
    if(tppMap[aiNormalize(l.nom)] && tppMap[aiNormalize(l.nom)].fiable) nbParfumsTempsPropre++;
  });
  // Dispo cumulée sur l'horizon (14 j) depuis le planning.
  let dispoMin=null, planningRenseigne=false;
  try{
    const conf=(typeof getAvailability==='function')?getAvailability():null;
    const hasSlot=m=>m&&Object.values(m).some(arr=>Array.isArray(arr)&&arr.length>0);
    planningRenseigne=!!(conf&&(hasSlot(conf.weekA)||hasSlot(conf.weekB)));
    if(typeof availableMinutesUntil==='function'){
      const fin=new Date(); fin.setDate(fin.getDate()+14);
      dispoMin=availableMinutesUntil(ymdLocal(fin),'23:59',conf);
    }
  }catch(e){swallow(e,'ordoEstimeTemps')}
  return {
    totMac, totMin:Math.round(totMin),
    minParMacMoyen: totMac>0 ? Math.round(totMin/totMac*10)/10 : null,
    nbParfumsTempsPropre, nbParfums:lignes.length,
    dispoMin: dispoMin!=null?Math.round(dispoMin):null, planningRenseigne,
    depasse: (dispoMin!=null && totMin>dispoMin)
  };
}

// Convertit les besoins de l'ordonnanceur ({std, gf}) en lignes {recipeId, nbBatchs} puis
// délègue à mrpCheckMatieres (source unique de vérité pour le calcul matières du plan).
async function ordoCheckMatieres(needs){
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recByNom = {}; recipes.forEach(r=>recByNom[aiNormalize(r.produitNom)]=r);
  const lignes = [];
  [...(needs.std||[]), ...(needs.gf||[])].forEach(b=>{
    const rec = recByNom[aiNormalize(b.nom)];
    if(!rec || !(b.qte>0)) return;
    const rdt = +rec.rendement>0 ? +rec.rendement : 1;
    lignes.push({ recipeId: rec.id, nbBatchs: Math.max(1, Math.ceil(b.qte / rdt)) });
  });
  if(!lignes.length) return {manques:[], ok:true, details:[]};
  return await mrpCheckMatieres({lignes});
}

// Alimente la liste de courses à partir des manques matières du plan de l'ordonnanceur.
// Réutilise la même mécanique que mrpShoppingFromPlan (meilleur fournisseur + modale courses).
async function ordoShoppingFromPlan(){
  const check = _ordoState && _ordoState.matCheck;
  if(!check || !Array.isArray(check.manques) || !check.manques.length){
    toast('Aucun manque matière à acheter pour ce plan'); return;
  }
  const [mats, lots, suppliers] = await Promise.all([db.materials.toArray(), db.materialLots.toArray(), db.suppliers.toArray()]);
  const supName = id => (suppliers.find(s=>s.id===id)||{}).nom || '—';
  const matById = id => mats.find(m=>m.id===id) || null;
  function bestSupplier(materialId){
    const perSup = new Map();
    for(const l of lots){
      if(l.materialId!==materialId || !l.supplierId) continue;
      const cur = perSup.get(l.supplierId);
      const newer = !cur || (l.dateReception||'') > (cur.dateReception||'')
        || ((l.dateReception||'')===(cur.dateReception||'') && (l.id||0)>(cur.id||0));
      if(newer) perSup.set(l.supplierId, l);
    }
    const offres=[];
    for(const [sid,lot] of perSup){ const pu=lotPU(lot); if(pu>0) offres.push({sid,pu,date:lot.dateReception||''}); }
    if(!offres.length) return null;
    offres.sort((a,b)=>a.pu-b.pu);
    return { nom:supName(offres[0].sid), pu:offres[0].pu, date:offres[0].date,
             nbAutres:offres.length-1, ecart: offres.length>1 ? money2(offres[offres.length-1].pu-offres[0].pu) : 0 };
  }
  const lignes = check.manques.map(m=>{
    const mat = matById(m.materialId) || {};
    return { nom:m.nom, unite:m.unite, cat:mat.categorie||'denree',
      stock:m.stockAff, seuil:m.besoinAff, manque:m.manqueAff, low:true,
      best:bestSupplier(m.materialId), _planContext:true };
  });
  openShoppingListModal(lignes, lignes.length);
}
function ordoSwitchMode(mode){ if(_ordoState){ ordoLancer(mode); } }

// Étape 3 — ajustement : formulaire éditable des quantités ; au changement, on RECALCULE tout.
function ordoAjuster(){
  if(!_ordoState) return;
  const champ=(arr,titre,prefix)=>arr.length?`<h4 style="margin:8px 0 4px;font-size:.9rem">${titre}</h4>`+arr.map((b,i)=>`
    <div style="display:flex;align-items:center;gap:8px;margin:3px 0">
      <span style="flex:1">${esc(b.nom)}</span>
      <input type="number" min="0" step="1" value="${b.qte}" id="${prefix}_${i}" style="width:90px;text-align:right">
    </div>`).join(''):'';
  openModal(`<h3>✏️ Ajuster les quantités</h3>
    <p class="note">Modifie les besoins puis recalcule : l'ordonnanceur réoptimise entièrement le plan à partir de tes nouvelles quantités.</p>
    ${champ(_ordoState.std,'Macarons standards','ordoStd')}
    ${champ(_ordoState.gf,'Grands formats','ordoGf')}
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="ordoApplyAjust()">Recalculer le plan</button>
    </div>`);
}
function ordoApplyAjust(){
  if(!_ordoState) return;
  _ordoState.std=_ordoState.std.map((b,i)=>({nom:b.nom, qte:Math.max(0,+(document.getElementById('ordoStd_'+i)?.value)||0)})).filter(b=>b.qte>0);
  _ordoState.gf=_ordoState.gf.map((b,i)=>({nom:b.nom, qte:Math.max(0,+(document.getElementById('ordoGf_'+i)?.value)||0)})).filter(b=>b.qte>0);
  closeModal();
  ordoRenderPlan('ordoZone');
}

// [FUSION — Étape 1] Cache court du plan : évite de recalculer buildProductionPlan
// plusieurs fois dans le même cycle d'affichage (ex. l'écran Plan l'appelle, et la voix
// via atelierBrain l'appelle aussi). Le calcul lourd n'est fait qu'une fois par fenêtre
// de quelques secondes, pour le même horizon. Aucune logique d'appel ne change.
let _planCache = { horizon:null, data:null, ts:0 };
const _PLAN_CACHE_MS = 3000;
async function buildProductionPlan(horizonDays){
  const H = horizonDays||14;
  const now = Date.now();
  if(_planCache.data && _planCache.horizon===H && (now - _planCache.ts) < _PLAN_CACHE_MS){
    return _planCache.data;
  }
  const data = await _buildProductionPlanRaw(H);
  _planCache = { horizon:H, data, ts:Date.now() };
  return data;
}
async function _buildProductionPlanRaw(horizonDays){
  const H = horizonDays||14;
  const items=[]; // {type, recipeId, produitNom, qte, raison, prioRang}
  const order = planPrioOrder();
  const rang = t => { const i=order.indexOf(t); return i<0?9:i; };

  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recById = {}; recipes.forEach(r=>recById[r.id]=r);
  const recByNom = {}; recipes.forEach(r=>recByNom[r.produitNom]=r);

  // 1) COMMANDES fermes + MARCHÉS programmés, dans l'horizon : besoin par parfum,
  // déduit du stock fini déjà disponible. C'est la PRIORITÉ n°1 (honorer les échéances).
  const _besoinCmd = {};   // parfum -> pièces demandées (commandes + marchés) dans l'horizon
  try{
    const orders = await db.orders.toArray();
    orders.forEach(o=>{
      const st=(typeof normStatus==='function')?normStatus(o.statut):o.statut;
      if(st==='Livrée') return;
      const j=daysTo(o.date); if(j===null||j>H) return;
      const dem = (typeof _orderParfumDemand==='function') ? _orderParfumDemand(o) : {};
      for(const nom in dem){ if(+dem[nom]>0) _besoinCmd[nom]=(_besoinCmd[nom]||0)+(+dem[nom]); }
    });
  }catch(e){ console.error('plan orders',e); }
  // [v1435] Marchés programmés : même règle que partout ailleurs, via le point de vérité unique.
  try{
    const mks = await db.markets.toArray().catch(()=>[]);
    let rep=[]; try{ const mf=await marketForecast(); rep=(mf&&mf.repartition)?mf.repartition:[]; }catch(e){ rep=[]; }
    const besoinMk = besoinMarchesParParfum(mks, rep, _besoinCmd, {horizonJours:H});
    for(const nom in besoinMk){ _besoinCmd[nom] = (_besoinCmd[nom]||0) + besoinMk[nom]; }
  }catch(e){ console.error('plan marchés',e); }
  // Déduit le stock fini disponible et crée les items « commande » (besoin net > 0).
  let _stockCmd = {};
  try{ const sc = await mrpCurrentStockByParfum(); _stockCmd = sc.stock || {}; }catch(e){ _stockCmd = {}; }
  // Le stock est indexé par produitNom de recette, le besoin par nom de parfum commandé :
  // on rapproche les deux via une normalisation souple (même logique que mrpFindRecipe).
  const _normP = s => (typeof aiNormalize==='function') ? aiNormalize(s) : String(s||'').toLowerCase().trim();
  const _stockNorm = {};
  for(const k in _stockCmd){ _stockNorm[_normP(k)] = (_stockNorm[_normP(k)]||0) + _stockCmd[k]; }
  const _stockPourParfum = nom => {
    const kn = _normP(nom);
    if(_stockNorm[kn]!=null) return _stockNorm[kn];
    // repli : correspondance partielle (le nom de parfum est contenu dans le nom de recette ou l'inverse)
    for(const k in _stockNorm){ if(k && (k.includes(kn) || kn.includes(k))) return _stockNorm[k]; }
    return 0;
  };
  for(const nom in _besoinCmd){
    const net = Math.max(0, round3(_besoinCmd[nom] - _stockPourParfum(nom)));
    if(net<=0) continue;
    const rec = recByNom[nom];
    items.push({
      type:'commande', recipeId: rec?rec.id:null, produitNom:nom, qte:net,
      rendement: rec&&+rec.rendement>0 ? +rec.rendement : null,
      raison:'Commandes / marchés à honorer',
      prioRang: rang('commande')
    });
  }

  // 2) RUPTURES + 4) RÉASSORT : via la vélocité de ventes (besoin sur H jours)
  try{
    const v=await computeSalesVelocity({months:3, horizonDays:H});
    if(v.hasData){
      (v.lignes||[]).forEach(l=>{
        if(l.perDay<=0) return;
        // ne pas ré-ajouter un parfum déjà couvert par une commande/marché (priorité 1)
        if(items.some(it=>it.type==='commande' && it.produitNom===l.parfum)) return;
        const besoin = Math.ceil(l.perDay*H - l.stock);
        if(besoin<=0) return;
        const rec = recByNom[l.parfum];
        const estRupture = l.joursRestants!=null && l.joursRestants<=7;
        items.push({
          type: estRupture?'rupture':'reassort',
          recipeId: rec?rec.id:null, produitNom: l.parfum, qte: besoin,
          rendement: rec&&+rec.rendement>0 ? +rec.rendement : null,
          raison: estRupture ? `Rupture dans ~${l.joursRestants} j` : `Réassort ${H} j (vélocité ${l.perMonth}/mois)`,
          prioRang: rang(estRupture?'rupture':'reassort')
        });
      });
    }
  }catch(e){ console.error('plan velocity',e); }

  // 3) ANTI-GASPI : matières à DLC proche
  try{
    const sugg=await generateProductionSuggestions(7);
    sugg.forEach(s=>{
      if(items.some(it=>it.recipeId===s.recipeId)) return; // déjà couvert
      items.push({
        type:'antigaspi', recipeId:s.recipeId, produitNom:s.produitNom,
        qte: null, // quantité libre (selon matière) — on suggère "à écouler"
        raison:`Matière ${s.matiere} à DLC ${s.joursAvantDLC<=0?'atteinte':'J−'+s.joursAvantDLC}`,
        prioRang: rang('antigaspi')
      });
    });
  }catch(e){ console.error('plan gaspi',e); }

  items.sort((a,b)=> a.prioRang-b.prioRang || (b.qte||0)-(a.qte||0));
  return items;
}

// ============================================================
//  ORDONNANCEUR UNIFIÉ — ÉTAPE 1 : MOTEUR DE BESOINS
//  Règle validée : besoin(parfum) = commandes fermes (s'ajoutent, ponctionnent le stock à
//  leur date) + max(besoin vélocité 14 j, réassort) − stock actuel.
//  Chaque parfum garde la RAISON la plus urgente et la plus proche échéance.
// ============================================================
async function buildUnifiedNeeds(opts){
  opts=opts||{};
  const horizon = opts.horizon||14;          // jours de couverture (vélocité/réassort)
  const horizonCmd = opts.horizonCmd||horizon; // fenêtre de prise en compte des commandes
  const todayStr = today();

  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recByNom = {}; recipes.forEach(r=>{ recByNom[aiNormalize(r.produitNom)]=r; });
  const findRec = nom => recByNom[aiNormalize(nom)] || mrpFindRecipe(recipes, nom);

  // 1) STOCK actuel par parfum
  const {stock} = await mrpCurrentStockByParfum();

  // 2) COMMANDES fermes non livrées, dans la fenêtre → s'ADDITIONNENT, avec la date la plus proche
  const cmdByParfum = {};   // nom -> {qte, dateMin}
  try{
    const orders = await db.orders.toArray();
    orders.forEach(o=>{
      if(normStatus(o.statut)==='Livrée') return;
      const j = daysTo(o.date); if(j===null || j>horizonCmd) return;
      const dem = _orderParfumDemand(o);
      for(const nom in dem){
        if(!cmdByParfum[nom]) cmdByParfum[nom]={qte:0, dateMin:o.date};
        cmdByParfum[nom].qte += dem[nom];
        if(o.date < cmdByParfum[nom].dateMin) cmdByParfum[nom].dateMin=o.date;
      }
    });
  }catch(e){ console.error('unifiedNeeds orders',e); }

  // 3) VÉLOCITÉ → besoin de couverture sur l'horizon + détection rupture
  const veloByParfum = {};  // nom -> {besoin, joursRestants, perMonth, rupture}
  try{
    const v = await computeSalesVelocity({months:3, horizonDays:horizon});
    if(v.hasData){
      (v.lignes||[]).forEach(l=>{
        if(l.perDay<=0) return;
        const besoinCouv = Math.max(0, Math.ceil(l.perDay*horizon - l.stock));
        veloByParfum[l.parfum] = {
          besoin: besoinCouv,
          joursRestants: l.joursRestants,
          perMonth: l.perMonth,
          rupture: (l.joursRestants!=null && l.joursRestants<=7)
        };
      });
    }
  }catch(e){ console.error('unifiedNeeds velocity',e); }

  // 4) ANTI-GASPI : matières à DLC proche → parfums à produire (raison prioritaire si DLC très proche)
  const gaspiByParfum = {}; // nom -> {joursAvantDLC, matiere}
  try{
    const sugg = await generateProductionSuggestions(7);
    sugg.forEach(s=>{
      const cur = gaspiByParfum[s.produitNom];
      if(!cur || s.joursAvantDLC < cur.joursAvantDLC) gaspiByParfum[s.produitNom]={joursAvantDLC:s.joursAvantDLC, matiere:s.matiere};
    });
  }catch(e){ console.error('unifiedNeeds gaspi',e); }

  // 5) FUSION par parfum
  const allNoms = new Set([...Object.keys(cmdByParfum), ...Object.keys(veloByParfum), ...Object.keys(gaspiByParfum)]);
  const needs = [];
  allNoms.forEach(nom=>{
    const cmd = cmdByParfum[nom];
    const velo = veloByParfum[nom];
    const gaspi = gaspiByParfum[nom];
    const enStock = +stock[nom]||0;

    const qCmd = cmd ? cmd.qte : 0;
    const qCouv = velo ? velo.besoin : 0;          // déjà net de stock dans computeSalesVelocity
    // besoin = commande (s'ajoute) + couverture flux (max vélocité/réassort, déjà calculé) − stock dispo pour la commande
    // la couverture est nette de stock ; la commande ponctionne le stock en premier.
    const stockPourCmd = Math.min(enStock, qCmd);
    const besoinCmdNet = Math.max(0, qCmd - stockPourCmd);
    const besoinTotal = besoinCmdNet + qCouv;
    if(besoinTotal<=0 && !gaspi) return;

    // raison + priorité (type) : la plus urgente l'emporte
    let type='reassort', raison='', echeance=null;
    if(velo && velo.rupture){ type='rupture'; raison=`Rupture dans ~${velo.joursRestants} j`; }
    else if(qCouv>0){ type='reassort'; raison=`Réassort ${horizon} j${velo?` (${velo.perMonth}/mois)`:''}`; }
    if(gaspi){ // anti-gaspi peut surclasser si DLC très proche
      if(type==='reassort' || gaspi.joursAvantDLC<=2){ type='antigaspi'; raison=`Matière ${gaspi.matiere} à DLC ${gaspi.joursAvantDLC<=0?'atteinte':'J−'+gaspi.joursAvantDLC}`; }
    }
    if(cmd){ type='commande'; raison=`Commande${besoinCmdNet>0?` (${qty(besoinCmdNet)} à produire)`:''} pour le ${fmtDate(cmd.dateMin)}${qCouv>0?` + réassort ${qty(qCouv)}`:''}`; echeance=cmd.dateMin; }

    const rec = findRec(nom);
    needs.push({
      parfum: nom, recipeId: rec?rec.id:null,
      besoin: besoinTotal>0?besoinTotal:(gaspi?0:besoinTotal),
      besoinCommande: besoinCmdNet, besoinCouverture: qCouv,
      enStock, type, raison, echeance,
      joursRestants: velo?velo.joursRestants:null,
      dlcMatiere: gaspi?gaspi.joursAvantDLC:null,
      sansRecette: !rec
    });
  });

  // tri par urgence d'échéance (commandes datées d'abord), puis besoin décroissant
  const typeRank = {commande:0, rupture:1, antigaspi:2, reassort:3};
  needs.sort((a,b)=> (typeRank[a.type]-typeRank[b.type]) || ((a.echeance||'9999')<(b.echeance||'9999')?-1:1) || (b.besoin-a.besoin));
  return needs;
}

let _planTempsDispoMin = 180; // défaut : 3 h
let _planAlloueMin = null;    // temps que l'utilisateur veut consacrer à la production (null = tout le dispo)

/* ============================================================
   COPILOTE D'ATELIER — LE CERVEAU (agrégation des données)
   Rassemble en UN SEUL état vérifié toutes les sources déjà calculées :
   - productions dues sous 14 j (commandes) + réassort/rupture/anti-gaspi
   - stock (ce qui est déjà produit vs à produire) et matières premières
   - temps réel nécessaire (chrono d'atelier) vs temps disponible (planning)
   - rétroplanning (délais incompressibles) + conflits de créneaux
   - optimisation des fournées (batch plein plutôt que micro-production)
   NE PRODUIT AUCUN TEXTE NI HTML : seulement des faits chiffrés et reliés.
   Règle d'or : tout champ provient d'un calcul réel ; rien n'est inventé.
   ============================================================ */

/* [CONNEXION #1+] CROISEMENT MARCHÉ — transparent et modulable.
   Pour un marché à venir, croise TON chiffre (prevuQte) avec la PRÉDICTION
   historique (marketForecast) pour établir le VOLUME TOTAL à emmener.
   Ce volume est ensuite RÉPARTI (et non augmenté) :
     - une part FRAÎCHE (non congelée) = fraisPct % du volume total
     - le reste vient du CONGÉLATEUR
   Exemple : 300 à emmener, fraisPct=30 → 90 frais + 210 congelés. Total = 300.
   La déduction du stock congelé déjà en réserve se fait dans le cerveau
   (cette fonction pure ne connaît pas le stock).
   Paramètres modulables :
     - mode : 'croise' (défaut) | 'mien'  → quelle base de volume total
     - fraisPct : part fraîche en % du volume total (défaut 30)
*/
function marketCrossPlan(prevuQte, forecast, opts){
  opts = opts||{};
  const mode = opts.mode==='mien' ? 'mien' : 'croise';
  const fraisPct = (opts.fraisPct!=null) ? Math.min(100,Math.max(0,+opts.fraisPct)) : 30;
  const mien = Math.max(0, +prevuQte||0);
  const predit = (forecast && forecast.nbMarches>0) ? Math.max(0, +forecast.suggestion||0) : 0;
  const aHistorique = !!(forecast && forecast.nbMarches>0);

  // VOLUME TOTAL à emmener, avec explication explicite (transparence).
  let volume, source, explication;
  if(mode==='mien'){
    volume = mien; source='mien';
    explication = `Volume basé sur ton seul chiffre (${mien} pièces), comme demandé.`;
  } else if(!aHistorique && mien>0){
    volume = mien; source='mien-faute-historique';
    explication = `Pas encore d'historique de marché : volume basé sur ton chiffre (${mien} pièces). La prédiction s'affinera après tes premiers marchés clôturés.`;
  } else if(aHistorique && mien<=0){
    volume = predit; source='predit-faute-saisie';
    explication = `Tu n'as pas renseigné de quantité : volume basé sur la prédiction historique (${predit} pièces, moyenne de tes ${forecast.nbMarches} marché(s) passé(s)).`;
  } else if(aHistorique && mien>0){
    volume = Math.round((mien+predit)/2); source='croise';
    explication = `Volume croisé : moyenne entre ton chiffre (${mien}) et la prédiction historique (${predit}, sur ${forecast.nbMarches} marché(s) passé(s)) = ${volume} pièces.`;
  } else {
    volume = 0; source='aucune-donnee';
    explication = `Aucune donnée : ni quantité saisie, ni historique. Renseigne une quantité prévue pour ce marché.`;
  }

  // RÉPARTITION du volume (découpe, pas d'ajout) : part fraîche + part congelée.
  const frais = Math.round(volume * fraisPct/100);
  const congele = Math.max(0, volume - frais);

  return {
    mien, predit, aHistorique, nbMarchesHisto: aHistorique?forecast.nbMarches:0,
    mode, volume, source, explication,
    fraisPct, frais, congele,
    // detail pédagogique pour l'affichage
    detail: {
      tonChiffre: mien,
      prediction: predit,
      volumeAEmmener: volume,
      partFraiche: frais,
      partCongelee: congele
    }
  };
}

/* [CONNEXION #1++] VENTILATION MARCHÉ PAR PARFUM — croisement transparent.
   Croise TA CIBLE de répartition (% par parfum, définie dans les réglages) avec
   la RÉPARTITION HISTORIQUE (marketForecast().repartition, issue des ventes réelles),
   puis applique les pourcentages croisés au volume total du marché pour obtenir
   un nombre de pièces par parfum.
   - cible      : [{parfum, pct}]  (ta cible ; peut être vide)
   - historique : [{parfum, pct}]  (issu de marketForecast ; peut être vide)
   - volume     : nombre total de pièces à emmener (déjà croisé en amont)
   - mode       : 'croise' (défaut) | 'mienne' (ma cible seule) | 'histo' (historique seul)
   Renvoie une ventilation détaillée et transparente, sans rien inventer :
   si aucune donnée, renvoie une ventilation vide (le cerveau le signalera).
*/
// ════════════════════════════════════════════════════════════════════════════════════════════
// [v1435] LE BESOIN DE PRODUCTION D'UN MARCHÉ — UN SEUL POINT DE VÉRITÉ.
// Ben : « le plan de travail appelé planning de production ne prend pas en compte les marchés
// programmés, pourquoi ? »
//
// LA CAUSE : la même règle était écrite TROIS FOIS, dans trois écrans, et la v1431 n'en avait
// corrigé qu'UNE (`_buildProductionPlanRaw`). Les deux autres — `ordoBuildNeeds` (l'ordonnanceur,
// c'est l'écran que Ben regarde) et `generateProductionOrder` (l'agenda de production) — sont
// restées sur l'ancienne version, qui ignore les parfums visés.
//
// PIRE, ET C'EST LA VRAIE RÉPONSE À SA QUESTION : `ordoBuildNeeds` n'incluait les marchés que si
// `mode==='marches' || mode==='auto'`. Or l'écran ne propose que DEUX boutons — « Commandes
// fermes » et « Commandes + réassort ». Le mode 'marches' n'existe nulle part dans l'interface,
// et 'auto' n'est utilisé que par le copilote. **Aucun bouton accessible à Ben ne déclenchait la
// prise en compte des marchés.** Le code était juste, il n'était simplement jamais appelé.
//
// Un marché programmé est une échéance FERME au même titre qu'une commande : on ne choisit pas
// d'y aller les mains vides. Il entre donc dans tous les modes.
//
// PURE. Renvoie {parfum: pièces}. `besoinBase` sert de prorata de repli et n'est jamais modifié.
function besoinMarchesParParfum(markets, repartition, besoinBase, opts){
  opts = opts||{};
  const H = opts.horizonJours!=null ? +opts.horizonJours : 14;
  const jours = opts.daysTo || (typeof daysTo==='function' ? daysTo : (()=>null));
  const out = {};
  const add = (nom, q) => { if(nom && q>0) out[nom] = (out[nom]||0) + q; };
  const rep = Array.isArray(repartition) ? repartition : [];
  const totPct = rep.reduce((s,r)=>s+(+r.pct||0),0);
  // Prorata de repli : le besoin des commandes DÉJÀ connu, figé avant d'ajouter quoi que ce soit
  // (sinon le premier marché servirait de base au deuxième, et la répartition dériverait).
  const baseNoms = Object.keys(besoinBase||{});
  const baseTot  = baseNoms.reduce((s,n)=>s+(+besoinBase[n]||0),0);

  (markets||[]).forEach(m=>{
    if(!m || m.statut==='clos') return;
    const q = +m.prevuQte||0; if(q<=0) return;
    const j = jours(m.date);
    // `j>=0` : un marché PASSÉ mais jamais clôturé n'est plus un besoin de production. Sans ce
    // test (absent des trois versions d'origine), il resterait indéfiniment dans le plan.
    if(j===null || j<0 || j>H) return;

    // ① LE CHOIX DE BEN D'ABORD (v1431) : les parfums visés saisis à l'ouverture du marché.
    const visee = Array.isArray(m.prevuParfums) ? m.prevuParfums.filter(x=>x && x.parfum && +x.qte>0) : [];
    if(visee.length){ visee.forEach(x=>add(x.parfum, +x.qte||0)); return; }
    // ② sinon la répartition apprise des marchés passés
    if(rep.length && totPct>0){
      let cumule=0;
      rep.forEach((r,i)=>{
        const part = (i===rep.length-1) ? (q-cumule) : Math.round(q*(+r.pct||0)/totPct);
        if(i!==rep.length-1) cumule += part;
        add(r.parfum, part);
      });
      return;
    }
    // ③ sinon au prorata des commandes en cours
    if(baseTot>0){
      let c=0;
      baseNoms.forEach((n,i)=>{
        const part = (i===baseNoms.length-1) ? (q-c) : Math.round(q*(+besoinBase[n]||0)/baseTot);
        if(i!==baseNoms.length-1) c += part;
        add(n, part);
      });
      return;
    }
    // ④ dernier recours : une ligne honnête plutôt qu'un chiffre inventé
    add('Marché (parfums à définir)', q);
  });
  return out;
}

function marketVentilation(cible, historique, volume, opts){
  opts = opts||{};
  const mode = ['croise','mienne','histo'].includes(opts.mode) ? opts.mode : 'croise';
  volume = Math.max(0, +volume||0);
  const norm = s => (typeof aiNormalize==='function') ? aiNormalize(s) : String(s||'').toLowerCase().trim();

  // Indexer les deux sources par parfum normalisé.
  const cibleMap = {}, histoMap = {}, labels = {};
  (cible||[]).forEach(c=>{ const k=norm(c.parfum); if(!k) return; cibleMap[k]=Math.max(0,+c.pct||0); labels[k]=c.parfum; });
  (historique||[]).forEach(h=>{ const k=norm(h.parfum); if(!k) return; histoMap[k]=Math.max(0,+h.pct||0); if(!labels[k]) labels[k]=h.parfum; });

  const aCible = Object.keys(cibleMap).length>0;
  const aHisto = Object.keys(histoMap).length>0;

  // Choix des pourcentages par parfum selon le mode (et les données disponibles).
  const keys = Array.from(new Set([...Object.keys(cibleMap), ...Object.keys(histoMap)]));
  let pctBrut = {}, sourceUtilisee, explication;

  const useCible = (mode==='mienne') || (mode==='croise' && aCible && !aHisto) || (aCible && !aHisto);
  const useHisto = (mode==='histo') || (mode==='croise' && aHisto && !aCible) || (aHisto && !aCible);

  if(mode==='mienne' || (useCible && !useHisto && aCible)){
    keys.forEach(k=> pctBrut[k]=cibleMap[k]||0);
    sourceUtilisee='cible'; explication='Ventilation basée sur ta cible de répartition.';
  } else if(mode==='histo' || (useHisto && !useCible && aHisto)){
    keys.forEach(k=> pctBrut[k]=histoMap[k]||0);
    sourceUtilisee='historique'; explication='Ventilation basée sur ton historique de ventes.';
  } else if(aCible && aHisto){
    // CROISEMENT : moyenne des deux pourcentages par parfum.
    keys.forEach(k=> pctBrut[k]=((cibleMap[k]||0)+(histoMap[k]||0))/2);
    sourceUtilisee='croise'; explication='Ventilation croisée : moyenne entre ta cible et ton historique, parfum par parfum.';
  } else {
    sourceUtilisee='aucune'; explication='Aucune ventilation disponible : définis une cible de répartition ou accumule de l’historique de marché.';
    return {lignes:[], sourceUtilisee, explication, aCible, aHisto, volume, totalVentile:0, reste:volume};
  }

  // Normaliser les pourcentages pour qu'ils somment à 100 (robuste si la saisie ne tombe pas juste).
  const sommePct = keys.reduce((s,k)=>s+(pctBrut[k]||0),0);
  const lignes = keys.map(k=>{
    const pctNorm = sommePct>0 ? (pctBrut[k]/sommePct*100) : 0;
    const pieces = Math.round(volume * pctNorm/100);
    return { parfum: labels[k], pct: Math.round(pctNorm*10)/10, pieces,
             pctCible: cibleMap[k]!=null?cibleMap[k]:null, pctHisto: histoMap[k]!=null?histoMap[k]:null };
  }).filter(l=>l.pieces>0 || l.pct>0)
    .sort((a,b)=>b.pieces-a.pieces);

  const totalVentile = lignes.reduce((s,l)=>s+l.pieces,0);
  // Ajustement d'arrondi : on recale la plus grosse ligne pour que la somme = volume exact.
  if(lignes.length && totalVentile!==volume){
    lignes[0].pieces += (volume - totalVentile);
    if(lignes[0].pieces<0) lignes[0].pieces=0;
  }
  const totalFinal = lignes.reduce((s,l)=>s+l.pieces,0);

  return { lignes, sourceUtilisee, explication, aCible, aHisto, volume, totalVentile:totalFinal, reste: Math.max(0, volume-totalFinal) };
}

/* [CONNEXION #4] RETARDS DE LANCEMENT. Pour chaque commande à venir non livrée, on calcule
   son rétroplanning et on repère les étapes de TRAVAIL dont la date de lancement est déjà
   passée (« tu aurais dû commencer la ganache hier »). C'est l'alerte du chef d'atelier.
   Renvoie [{orderId, client, dateLivraison, retards:[{cle,label,date,retardH}], plusUrgent}].
   - On ne signale que les jalons type:'travail' (actions à déclencher), pas les attentes.
   - Une commande déjà entièrement produite (assez de stock fini) n'est pas en retard.
*/
async function commandesEnRetard(opts){
  opts = opts||{};
  const horizon = opts.horizon || 21;   // on regarde un peu plus loin que 14 j pour anticiper
  const now = new Date();
  const startStr = today();
  const endStr = (()=>{ const d=new Date(startStr); d.setDate(d.getDate()+horizon); return ymdLocal(d); })();

  const [orders, recipes, clients] = await Promise.all([
    db.orders.toArray().catch(()=>[]),
    db.recipes.toArray().catch(()=>[]),
    db.clients.toArray().catch(()=>[])
  ]);
  const clientNom = id => (clients.find(c=>c.id===id)||{}).nom || '';

  const out = [];
  orders.forEach(o=>{
    // Commande à honorer : a une date de livraison dans la fenêtre, pas livrée, pas déjà produite.
    const dateLiv = o.dateEvenement || o.date || '';
    if(!dateLiv) return;
    if(dateLiv < startStr || dateLiv > endStr) return;
    const st = (typeof normStatus==='function') ? normStatus(o.statut) : (o.statut||'');
    // 'Livrée' = finie. 'Terminée' = déjà produite → plus de lancement à faire, donc pas en retard.
    if(st==='Livrée' || st==='Terminée') return;

    // Rétroplanning de la commande.
    let rp = null;
    try{ rp = (typeof retroplanningCommande==='function') ? retroplanningCommande(o, recipes) : null; }catch(e){swallow(e,'commandesEnRetard')}
    if(!rp || rp.error || !Array.isArray(rp.jalons)) return;

    // Jalons de TRAVAIL dont la date de lancement est déjà passée.
    const retards = [];
    rp.jalons.forEach(j=>{
      if(j.type!=='travail') return;
      const d = (j.date instanceof Date) ? j.date : new Date(j.date);
      if(isNaN(d)) return;
      if(d < now){
        const retardH = Math.max(0, Math.round((now - d)/3600000));
        retards.push({ cle:j.cle, label:j.label, date:d, retardH });
      }
    });
    if(!retards.length) return;

    // Trier les retards par ancienneté (le plus en retard d'abord).
    retards.sort((a,b)=>a.date-b.date);
    out.push({
      orderId: o.id,
      client: clientNom(o.clientId) || o.histoLabel || '(client ?)',
      // On transmet la date de livraison COMPLÈTE (avec l'heure) calculée par le rétroplanning,
      // pour que l'affichage montre la vraie heure de livraison et non minuit (bug fuseau).
      dateLivraison: (rp && rp.livraison instanceof Date) ? rp.livraison : dateLiv,
      retards,
      plusUrgent: retards[0],   // le jalon le plus anciennement dépassé
      nbRetards: retards.length
    });
  });

  // Trier les commandes : la plus proche de la livraison en premier (la plus pressante).
  out.sort((a,b)=>(a.dateLivraison||'').localeCompare(b.dateLivraison||''));
  return out;
}

/* [CONNEXION #5] DLC DES PRODUITS FINIS. Repère les macarons DÉJÀ FABRIQUÉS (finis, en stock)
   qui approchent de leur date limite, pour les écouler en priorité avant qu'ils ne périment.
   Pendant de la connexion #2 (ne pas reproduire l'existant) côté "ne pas gaspiller l'existant".
   Renvoie [{parfum, lot, dlc, joursAvantDLC, qte, emplacement, urgent}], trié par urgence.
   - On ne garde que les produits FINIS (complet/assemble) avec stock restant et une DLC connue.
   - Seuil par défaut : alerte si DLC dans <= 4 jours (configurable via opts.seuilJours).
*/
async function produitsFinisDlc(opts){
  opts = opts||{};
  const seuilJours = (opts.seuilJours!=null) ? +opts.seuilJours : 4;
  const prods = await db.productions.toArray().catch(()=>[]);
  const recipes = await db.recipes.toArray().catch(()=>[]);

  const out = [];
  prods.forEach(p=>{
    // Produit FINI uniquement (pas coques/ganache/dégustation).
    const comp = (typeof prodComposant==='function') ? prodComposant(p) : 'complet';
    if(comp!=='complet' && comp!=='assemble') return;
    const reste = round3(+p.qteRestante||0);
    if(reste<=0) return;
    if(!p.dlcProduit) return;
    const j = (typeof daysTo==='function') ? daysTo(p.dlcProduit) : null;
    if(j===null) return;
    if(j > seuilJours) return;   // pas encore dans la fenêtre d'alerte

    const nom = (typeof prodNomComplet==='function') ? prodNomComplet(p, recipes) : '';
    out.push({
      parfum: nom || '(parfum ?)',
      lot: p.lotProduction || ('#'+p.id),
      dlc: p.dlcProduit,
      joursAvantDLC: j,
      qte: reste,
      emplacement: p.emplacement || '',
      urgent: (j<=1)              // urgent si DLC aujourd'hui/demain ou dépassée
    });
  });

  // Tri : le plus urgent d'abord (DLC la plus proche), puis la plus grosse quantité.
  out.sort((a,b)=> (a.joursAvantDLC-b.joursAvantDLC) || (b.qte-a.qte));
  return out;
}

/* [FUSION] Commandes proches du RETRAIT (aujourd'hui / demain / en retard de retrait).
   Distinct des retards de LANCEMENT (production) : ici c'est la date de remise au client.
   Réutilise la logique exacte de l'ancien briefing, pour que le cerveau couvre tout. */
async function commandesProchesRetrait(opts){
  opts = opts||{};
  const seuilJours = (opts.seuilJours!=null) ? +opts.seuilJours : 1;   // aujourd'hui + demain par défaut
  const orders = await db.orders.toArray().catch(()=>[]);
  const clients = await db.clients.toArray().catch(()=>[]);
  const nm = id => { const c=clients.find(x=>x.id===id); return c?c.nom:'client'; };
  const out = [];
  orders.forEach(o=>{
    const st = (typeof normStatus==='function') ? normStatus(o.statut) : o.statut;
    if(st==='Livrée' || st==='Terminée') return;
    const j = (typeof daysTo==='function') ? daysTo(o.date) : null;
    if(j===null) return;
    if(j<=seuilJours){
      out.push({
        orderId: o.id,
        client: nm(o.clientId) || o.histoLabel || 'client',
        date: o.date,
        joursAvantRetrait: j,
        etat: j<0 ? 'retard' : j===0 ? 'aujourdhui' : 'demain'
      });
    }
  });
  out.sort((a,b)=> a.joursAvantRetrait - b.joursAvantRetrait);
  return out;
}
async function atelierBrain(opts){
  opts = opts || {};
  const horizon = opts.horizon || 14;
  const startStr = today();
  const endStr = (()=>{ const d=new Date(startStr); d.setDate(d.getDate()+horizon); return ymdLocal(d); })();

  // --- 1) PLAN : que faut-il produire sous 14 j ? (commandes, réassort, rupture, anti-gaspi)
  let planItems = [];
  try{ planItems = await buildProductionPlan(horizon) || []; }catch(e){ console.error('brain.plan',e); }

  // --- 2) RECETTES (rendement, délais) pour convertir macarons → batchs
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recById = id => recipes.find(r=>r.id===id) || null;
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;

  // Construire les "lignes" attendues par mrpCheckMatieres (recipeId + nbBatchs) à partir du plan.
  const lignesPlan = [];
  planItems.forEach(it=>{
    if(!it.recipeId || it.qte==null || !(it.qte>0)) return;
    const rec = recById(it.recipeId);
    const rendement = (rec && rec.rendement>0) ? rec.rendement : TB;
    const nbBatchs = Math.max(1, Math.ceil(it.qte / rendement));
    lignesPlan.push({ parfum:it.produitNom, recipeId:it.recipeId, qte:it.qte, nbBatchs, besoinNet:it.qte, type:it.type, raison:it.raison });
  });

  // --- 2 bis) [CONNEXION #2] STOCK DE COMPOSANTS déjà produits (coques + garnitures) par parfum.
  // Pour chaque ligne, on indique ce qui est DÉJÀ fait, donc ce qu'il reste vraiment à produire.
  let compStock = {};
  try{ compStock = (typeof composantsStockByParfum==='function') ? await composantsStockByParfum() : {}; }catch(e){ console.error('brain.compstock',e); }
  const CQ_PAR_MAC = (typeof COQUES_PAR_MACARON!=='undefined') ? COQUES_PAR_MACARON : 2;
  lignesPlan.forEach(l=>{
    const k = (typeof aiNormalize==='function') ? aiNormalize(l.parfum) : (l.parfum||'').toLowerCase();
    const cs = compStock[k];
    if(cs){
      const coquesStock = +cs.coques||0;        // nb de coques
      const garnStock = +cs.garniture||0;       // nb de doses (1 dose = 1 macaron)
      const macParCoques = Math.floor(coquesStock / CQ_PAR_MAC);   // macarons assemblables côté coques
      // macarons immédiatement assemblables = min(coques dispo, garniture dispo)
      const assemblablesSansRien = Math.max(0, Math.min(macParCoques, garnStock));
      l.coquesStock = coquesStock;
      l.garnitureStock = garnStock;
      l.assemblablesSansRien = Math.min(assemblablesSansRien, l.qte);
      // Reste à produire en tenant compte des composants déjà là (indicatif, n'altère pas le besoin matières).
      l.coquesAprod = Math.max(0, l.qte*CQ_PAR_MAC - coquesStock);
      l.garnitureAprod = Math.max(0, l.qte - garnStock);
    } else {
      l.coquesStock = 0; l.garnitureStock = 0; l.assemblablesSansRien = 0;
      l.coquesAprod = l.qte*CQ_PAR_MAC; l.garnitureAprod = l.qte;
    }
  });

  // --- 3) MATIÈRES : de quoi manque-t-il pour exécuter ce plan ?
  let matCheck = {manques:[], ok:true, details:[]};
  try{ matCheck = await mrpCheckMatieres({lignes:lignesPlan}) || matCheck; }catch(e){ console.error('brain.mat',e); }
  // [DIAG → rubrique technique] Origine de chaque matière à acheter : quels parfums du PLAN (horizon
  // complet) la réclament, avec leur type (commande/marché/réassort) et leur raison. Prouve que la liste
  // « à acheter » couvre TOUT l'horizon, pas seulement l'ordre du jour affiché « ci-dessus ».
  try{
    const _itemsD = await db.recipeItems.toArray().catch(()=>[]);
    const _trace = (matCheck.manques||[]).slice(0,12).map(m=>{
      const contrib = (lignesPlan||[]).filter(l=> l.recipeId && (+l.nbBatchs>0)
        && _itemsD.some(it=> it.recipeId===l.recipeId && it.materialId===m.materialId && (+it.qteParBatch>0)));
      const detail = contrib.map(l=> `${l.parfum||'?'} [${l.type||'?'}${l.raison?' · '+l.raison:''}]`).join(' + ') || 'AUCUN parfum ?!';
      return `${m.nom} (${m.manqueAff||0}${m.unite||''}) ← ${detail}`;
    });
    diagPublish('matieres', '🛒 Matières à acheter — origine', {
      'Périmètre': 'horizon '+horizon+' j ('+(lignesPlan?lignesPlan.length:0)+' lignes de production)',
      'Nb matières à acheter': (matCheck.manques||[]).length,
      'Origine par matière': _trace,
      'Note': 'Type « commande » = besoin d\'une commande ferme ; « marche » = prévision marché ; « reassort » = batch arrondi.'
    });
  }catch(ex){ diagPublish('matieres','🛒 Matières — erreur', {erreur:String(ex&&ex.message||ex)}); }

  // --- 4) TEMPS : besoin estimé (chrono) vs dispo (planning d'aujourd'hui)
  let minParMac = null;
  let tempsLisseFiable = false;
  try{ const tl = await prodTempsLissePerMacaron(90); minParMac = (tl && tl.minParMacaron) ? tl.minParMacaron : null; tempsLisseFiable = !!(tl && tl.fiable); }catch(e){ console.error('brain.temps',e); }
  // [TEMPS PAR PARFUM] Temps propre à chaque parfum (si assez de données), sinon repli moyenne globale.
  let tppMap = {};
  try{ tppMap = (typeof prodTempsParParfum==='function') ? await prodTempsParParfumParNom(90) : {}; }catch(e){ console.error('brain.tpp',e); }
  // minParMac d'une ligne : son temps parfum si fiable, sinon la moyenne globale.
  const minParMacDe = (parfum)=>{
    const k = (typeof aiNormalize==='function') ? aiNormalize(parfum) : (parfum||'').toLowerCase();
    const tp = tppMap[k];
    return (tp && tp.fiable && tp.minParMac>0) ? tp.minParMac : minParMac;
  };
  // Combien de parfums du plan bénéficient d'un temps propre fiable (transparence).
  let nbParfumsTempsPropre = 0;
  lignesPlan.forEach(l=>{ const k=(typeof aiNormalize==='function')?aiNormalize(l.parfum):(l.parfum||'').toLowerCase(); if(tppMap[k] && tppMap[k].fiable) nbParfumsTempsPropre++; });
  // Total de macarons à produire (hors anti-gaspi qui est "à écouler", qte null).
  const totMacAprod = lignesPlan.reduce((s,l)=>s+(+l.qte||0),0);
  // Besoin temps commandes/réassort : somme des temps PAR PARFUM (temps propre si fiable, sinon moyenne).
  const besoinMinCmd = (minParMac!=null)
    ? Math.round(lignesPlan.reduce((s,l)=>{ const m=minParMacDe(l.parfum); return s + (m!=null ? (+l.qte||0)*m : 0); },0))
    : null;
  // Dispo aujourd'hui depuis le planning renseigné.
  let dispoAujMin = null, dispoHorizonMin = null, planningRenseigne = false;
  try{
    const now=new Date();
    const conf = (typeof getAvailability==='function') ? getAvailability() : null;
    // Planning renseigné = au moins une plage horaire dans la semaine A ou B.
    const hasSlot = m => m && Object.values(m).some(arr=>Array.isArray(arr)&&arr.length>0);
    planningRenseigne = !!(conf && (hasSlot(conf.weekA) || hasSlot(conf.weekB)));
    if(typeof availMinutesOnDay==='function'){
      dispoAujMin = availMinutesOnDay(now, now.getHours()*60+now.getMinutes(), null, conf);
    }
    // [CONNEXION #3] Dispo cumulée sur tout l'horizon (et pas seulement aujourd'hui).
    if(typeof availableMinutesUntil==='function'){
      dispoHorizonMin = availableMinutesUntil(endStr, '23:59', conf);
    }
  }catch(e){ console.error('brain.dispo',e); }

  // --- 5) CONFLITS : tâches de travail qui se chevauchent sur l'horizon
  let conf = {conflits:[], taches:[], nbCommandes:0};
  try{ conf = await retroConflicts(startStr, endStr) || conf; }catch(e){ console.error('brain.conf',e); }

  // --- 5 quater) [CONNEXION #4] RETARDS DE LANCEMENT : commandes dont une étape de travail
  // aurait déjà dû démarrer (le rétroplanning connaît la date de début de chaque étape).
  let retardsLancement = [];
  try{ retardsLancement = (typeof commandesEnRetard==='function') ? await commandesEnRetard({horizon:21}) : []; }catch(e){ console.error('brain.retards',e); }

  // --- 5 quinquies) [CONNEXION #5] DLC DES PRODUITS FINIS : macarons déjà faits qui approchent
  // de leur date limite, à écouler en priorité avant péremption.
  let dlcFinis = [];
  try{ dlcFinis = (typeof produitsFinisDlc==='function') ? await produitsFinisDlc({seuilJours:4}) : []; }catch(e){ console.error('brain.dlcfinis',e); }

  // --- 5 sexies) [FUSION] COMMANDES PROCHES DU RETRAIT : à remettre au client aujourd'hui/demain.
  // Distinct des retards de lancement (production). Permet au cerveau de couvrir le briefing.
  let cmdProches = [];
  try{ cmdProches = (typeof commandesProchesRetrait==='function') ? await commandesProchesRetrait({seuilJours:1}) : []; }catch(e){ console.error('brain.cmdproches',e); }

  // --- 5 bis) [CONNEXION #1] MARCHÉS À VENIR dans l'horizon : charge de production.
  // Un marché compte s'il est daté dans [aujourd'hui, +horizon], pas clos, pas historique.
  // Pour chaque marché : on CROISE ton chiffre (prevuQte) avec la prédiction historique pour
  // obtenir le VOLUME à emmener, puis on le RÉPARTIT en part fraîche (à produire à neuf) et
  // part congelée (à produire SAUF ce qu'on a déjà en stock congelé).
  let marches = [];
  const mkMode    = (opts.marketMode==='mien') ? 'mien' : 'croise';
  const mkFraisPct= (opts.marketFraisPct!=null) ? Math.min(100,Math.max(0,+opts.marketFraisPct)) : 30;
  let mkForecast = null;
  try{ mkForecast = (typeof marketForecast==='function') ? await marketForecast() : null; }catch(e){ console.error('brain.forecast',e); }

  // Stock de produits finis CONGELÉS (global, toutes recettes) — sert de réserve pour la part congelée.
  let stockCongeleGlobal = 0;
  try{
    const prodsAll = await db.productions.toArray().catch(()=>[]);
    prodsAll.forEach(p=>{
      // produit fini assemblé, encore en stock, situé dans un congélateur
      const fini = (typeof prodComposant==='function') ? (prodComposant(p)==null || prodComposant(p)==='') : true;
      const reste = +p.qteRestante||0;
      const auCongel = (typeof isFreezer==='function') ? isFreezer(p.emplacement) : false;
      if(reste>0 && auCongel && fini && !p.venuDuCongelateur) stockCongeleGlobal += reste;
    });
  }catch(e){ console.error('brain.stockcongele',e); }

  try{
    const allMk = await db.markets.toArray().catch(()=>[]);
    marches = allMk.filter(mk=> mk && mk.date && mk.date>=startStr && mk.date<=endStr
                                 && mk.statut!=='clos' && !mk.histo)
      .map(mk=>{
        const cross = (typeof marketCrossPlan==='function')
          ? marketCrossPlan(+mk.prevuQte||0, mkForecast, {mode:mkMode, fraisPct:mkFraisPct})
          : {volume:+mk.prevuQte||0, frais:0, congele:+mk.prevuQte||0, mien:+mk.prevuQte||0, predit:0, source:'brut', explication:''};
        return { id:mk.id, nom:mk.nom||'Marché', date:mk.date, prevuQte:+mk.prevuQte||0, cross,
                 mkMix: Array.isArray(mk.mkMix)?mk.mkMix:null };
      })
      .sort((a,b)=>(a.date||'').localeCompare(b.date||''));
  }catch(e){ console.error('brain.marches',e); }

  // Agrégats marché (volume, frais, congelé) avant déduction du stock.
  const totMarcheVolume = marches.reduce((s,m)=>s+(+(m.cross&&m.cross.volume)||0),0);
  const totMarcheFrais  = marches.reduce((s,m)=>s+(+(m.cross&&m.cross.frais)||0),0);
  const totMarcheCongele= marches.reduce((s,m)=>s+(+(m.cross&&m.cross.congele)||0),0);
  // La part FRAÎCHE est toujours à produire à neuf. La part CONGELÉE est à produire SAUF
  // ce qu'on a déjà en réserve congelée (déduction globale, faute de ventilation par parfum).
  const congeleAProduire = Math.max(0, totMarcheCongele - stockCongeleGlobal);
  const stockCongeleUtilise = Math.min(stockCongeleGlobal, totMarcheCongele);
  // Net marché RÉELLEMENT à produire = part fraîche + part congelée non couverte par le stock.
  const totMacMarches = totMarcheFrais + congeleAProduire;
  // Besoin temps TOTAL = commandes/réassort (déjà estimé PAR PARFUM dans besoinMinCmd)
  // + net marché à produire (à la moyenne globale, la ventilation marché par parfum venant après).
  const besoinMinMarche = (minParMac!=null) ? Math.round(totMacMarches*minParMac) : null;
  const besoinMin = (besoinMinCmd!=null && besoinMinMarche!=null) ? (besoinMinCmd + besoinMinMarche)
                  : (besoinMinCmd!=null ? besoinMinCmd : besoinMinMarche);

  // --- 5 ter) [CONNEXION #1++] VENTILATION MARCHÉ PAR PARFUM, MARCHÉ PAR MARCHÉ.
  // Pour chaque marché : si un ajustement propre (mkMix) existe, il est PRIORITAIRE ;
  // sinon on applique la cible globale (croisée avec l'historique) à son volume net.
  // On agrège ensuite les pièces par parfum sur l'ensemble des marchés.
  const mkMixMode = ['croise','mienne','histo'].includes(opts.marketMixMode) ? opts.marketMixMode : 'croise';
  let marketCible = [];
  try{ const st=(typeof getSettings==='function')?getSettings():{}; marketCible = Array.isArray(st.marketMix)?st.marketMix:[]; }catch(e){swallow(e,'atelierBrain')}
  const marketHisto = (mkForecast && Array.isArray(mkForecast.repartition)) ? mkForecast.repartition : [];

  // Net à produire par marché = sa part du net total, au prorata de son volume.
  const totMarcheVolumeForProrata = totMarcheVolume>0 ? totMarcheVolume : 1;
  const ventilParParfum = {};   // parfum normalisé -> {parfum, pieces}
  let nbMarchesAjustes = 0;
  marches.forEach(m=>{
    const volM = +(m.cross&&m.cross.volume)||0;
    if(volM<=0) return;
    // Net à produire attribué à ce marché (prorata du net total).
    const netM = Math.round(totMacMarches * (volM/totMarcheVolumeForProrata));
    if(netM<=0) return;
    let lignesM = [];
    if(m.mkMix && m.mkMix.length){
      // Ajustement propre : on respecte ses proportions, ramenées au net à produire de ce marché.
      nbMarchesAjustes++;
      const totMix = m.mkMix.reduce((s,x)=>s+(+x.mac||0),0);
      if(totMix>0) lignesM = m.mkMix.map(x=>({ parfum:x.parfum, pieces: Math.round(netM*(+x.mac||0)/totMix) }));
    } else {
      // Pas d'ajustement : cible globale croisée appliquée au net de ce marché.
      try{ const v=marketVentilation(marketCible, marketHisto, netM, {mode:mkMixMode}); lignesM=v.lignes||[]; }catch(e){swallow(e,'atelierBrain')}
    }
    lignesM.forEach(l=>{
      const k=(typeof aiNormalize==='function')?aiNormalize(l.parfum):(l.parfum||'').toLowerCase();
      if(!k) return;
      if(!ventilParParfum[k]) ventilParParfum[k]={parfum:l.parfum, pieces:0};
      ventilParParfum[k].pieces += (+l.pieces||0);
    });
  });
  const ventilation = {
    lignes: Object.values(ventilParParfum).filter(l=>l.pieces>0).sort((a,b)=>b.pieces-a.pieces),
    sourceUtilisee: nbMarchesAjustes>0 ? 'marche-par-marche' : 'cible-globale',
    nbMarchesAjustes,
    explication: nbMarchesAjustes>0
      ? `${nbMarchesAjustes} marché(s) avec répartition ajustée, le reste via ta cible.`
      : 'Ventilation via ta cible globale croisée avec l\'historique.'
  };

  // Check matières ENRICHI : on ajoute les pièces marché ventilées aux lignes du plan, par recette.
  let matCheckAvecMarche = matCheck;
  if(ventilation.lignes && ventilation.lignes.length){
    const recByNom = nom => recipes.find(r=> (typeof aiNormalize==='function'?aiNormalize(r.produitNom):r.produitNom)===(typeof aiNormalize==='function'?aiNormalize(nom):nom)) || null;
    const lignesAvecMarche = lignesPlan.map(l=>({...l}));   // copie
    ventilation.lignes.forEach(v=>{
      const rec = recByNom(v.parfum); if(!rec) return;
      const rendement = (rec.rendement>0) ? rec.rendement : TB;
      const exist = lignesAvecMarche.find(l=>l.recipeId===rec.id);
      if(exist){ exist.qte += v.pieces; exist.nbBatchs = Math.max(1, Math.ceil(exist.qte/rendement)); }
      else lignesAvecMarche.push({ parfum:rec.produitNom, recipeId:rec.id, qte:v.pieces, nbBatchs:Math.max(1,Math.ceil(v.pieces/rendement)), besoinNet:v.pieces, type:'marche', raison:'Marché ventilé' });
    });
    try{ matCheckAvecMarche = await mrpCheckMatieres({lignes:lignesAvecMarche}) || matCheck; }catch(e){ console.error('brain.mat2',e); }
  }

  // --- 6) OPTIMISATION FOURNÉES : repérer les micro-productions à arrondir au batch plein.
  // Une ligne dont la quantité est bien < 1 batch plein est candidate au "complète le batch
  // pour refaire du stock". On chiffre le complément.
  const optimisations = [];
  lignesPlan.forEach(l=>{
    const rec = recById(l.recipeId);
    const rendement = (rec && rec.rendement>0) ? rec.rendement : TB;
    if(l.qte>0 && l.qte < rendement){
      optimisations.push({
        parfum:l.parfum, recipeId:l.recipeId,
        qteCommande:l.qte, rendement,
        complementStock: rendement - l.qte,   // ce qu'on produirait en plus en lançant un batch plein
        type:l.type
      });
    }
  });

  // --- SYNTHÈSE D'ÉTAT (faits seulement) ---
  const commandes = lignesPlan.filter(l=>l.type==='commande');
  const etat = {
    horizon, periode:{start:startStr, end:endStr},
    // Productions
    plan: lignesPlan,
    nbProductions: lignesPlan.length,
    nbCommandes: commandes.length,
    totMacAprod,
    // Stock de composants déjà produits (par parfum) — évite de reproduire l'existant.
    composantsStock: lignesPlan.filter(l=> (l.coquesStock>0 || l.garnitureStock>0)).map(l=>({
      parfum:l.parfum, coquesStock:l.coquesStock, garnitureStock:l.garnitureStock,
      assemblablesSansRien:l.assemblablesSansRien, coquesAprod:l.coquesAprod, garnitureAprod:l.garnitureAprod
    })),
    totAssemblablesSansRien: lignesPlan.reduce((s,l)=>s+(+l.assemblablesSansRien||0),0),
    // Marchés à venir (volume croisé, réparti frais/congelé, net à produire)
    marches, nbMarches: marches.length,
    marketMode: mkMode, marketFraisPct: mkFraisPct,
    marcheVolume: totMarcheVolume,        // total à emmener (tous marchés)
    marcheFrais: totMarcheFrais,          // part fraîche (à produire à neuf)
    marcheCongele: totMarcheCongele,      // part congelée souhaitée
    stockCongeleGlobal,                   // réserve congelée disponible
    stockCongeleUtilise,                  // part de la réserve mobilisée
    congeleAProduire,                     // congelé restant à produire après déduction
    totMacMarches,                        // net marché réellement à produire (frais + congelé non couvert)
    marketForecastGlobal: mkForecast,     // {nbMarches, moyenneVendu, maxVendu, suggestion, repartition}
    // Ventilation marché par parfum (croisement cible × historique)
    marketVentil: ventilation,            // {lignes:[{parfum,pieces,pct,pctCible,pctHisto}], sourceUtilisee, explication}
    marketMixMode: mkMixMode,
    // Matières — le check ENRICHI inclut désormais les marchés ventilés (par parfum).
    matieresOk: matCheckAvecMarche.ok,
    manquesMatieres: matCheckAvecMarche.manques,
    matieresCouvreMarches: (ventilation.lignes && ventilation.lignes.length>0),
    matieresNote: (totMacMarches>0 && !(ventilation.lignes && ventilation.lignes.length))
      ? `Le volume marché à produire (${totMacMarches} pièces) n'a pas pu être ventilé par parfum (ni cible ni historique) : il n'est pas inclus dans l'alerte matières. Définis une cible de répartition pour l'activer.`
      : '',
    // Détail matières commandes seules (sans marché), pour comparaison/transparence.
    manquesMatieresCmd: matCheck.manques,
    // Temps (inclut la charge marchés dans besoinMin)
    minParMac, besoinMin, besoinMinCmd, dispoAujMin, dispoHorizonMin, planningRenseigne,
    // Fiabilité de l'estimation de temps (assez de chronos mesurés ?).
    tempsLisseFiable,
    // Transparence temps par parfum : combien de parfums du plan ont un temps propre fiable.
    nbParfumsTempsPropre, nbLignesPlan: lignesPlan.length,
    tempsParParfumActif: (nbParfumsTempsPropre>0),
    // Faisabilité AUJOURD'HUI : ce que tu peux avancer dans le temps dispo du jour.
    tempsSuffisantAuj: (besoinMin!=null && dispoAujMin!=null) ? (besoinMin<=dispoAujMin) : null,
    // Faisabilité sur l'HORIZON (14 j) : la vraie question — la charge tient-elle dans la dispo des 14 j ?
    tempsSuffisant: (besoinMin!=null && dispoHorizonMin!=null) ? (besoinMin<=dispoHorizonMin) : null,
    tempsManquantMin: (besoinMin!=null && dispoHorizonMin!=null && besoinMin>dispoHorizonMin) ? (besoinMin-dispoHorizonMin) : 0,
    // Taux de charge sur l'horizon (part du temps dispo consommée par la production).
    tauxChargeHorizon: (besoinMin!=null && dispoHorizonMin>0) ? Math.round(besoinMin/dispoHorizonMin*100) : null,
    // Conflits
    conflits: conf.conflits,
    nbConflits: conf.conflits.length,
    // [CONNEXION #4] Retards de lancement : commandes dont une étape aurait dû démarrer.
    retardsLancement,
    nbCommandesEnRetard: retardsLancement.length,
    aDesRetards: retardsLancement.length>0,
    // [CONNEXION #5] Produits finis proches DLC : à écouler en priorité.
    dlcFinis,
    nbDlcFinis: dlcFinis.length,
    aDesDlcProches: dlcFinis.length>0,
    nbDlcUrgents: dlcFinis.filter(d=>d.urgent).length,
    // [FUSION] Commandes proches du retrait (à remettre au client aujourd'hui/demain).
    commandesProches: cmdProches,
    nbCommandesProches: cmdProches.length,
    aDesCommandesProches: cmdProches.length>0,
    // Optimisation
    optimisations,
    // Méta : ce que le cerveau a pu calculer (pour que la "voix" ne parle que du sûr)
    dispo:{
      temps: (minParMac!=null),
      planning: (dispoAujMin!=null),
      matieres: true,
      conflits: true
    }
  };
  return etat;
}

/* ============================ LA VOIX ============================
   atelierVoix() : transforme les calculs d'atelierBrain en un CONSEIL PARLÉ,
   priorisé et actionnable. Affiché en tête du Plan de production ET sur l'accueil.
   Principe cardinal : ne parler QUE de ce qui est calculé (jamais d'invention).
   Renvoie une chaîne HTML (l'encart de conseil), ou un encart neutre si rien à dire.
*/
async function atelierVoix(opts){
  opts = opts||{};
  let b;
  try{ b = await atelierBrain(); }catch(e){ console.error('voix.brain',e); return ''; }
  if(!b) return '';

  const esc2 = s => (typeof esc==='function') ? esc(String(s==null?'':s)) : String(s==null?'':s);
  const fmtHM = m => { m=Math.round(+m||0); const h=Math.floor(m/60), mm=m%60; return `${h?h+'h ':''}${String(mm).padStart(2,'0')}min`; };
  const sections = [];

  // --- 1) URGENCES (retards de lancement + DLC produits finis) ---
  const urgences = [];
  if(b.aDesRetards && Array.isArray(b.retardsLancement)){
    b.retardsLancement.slice(0,3).forEach(r=>{
      const quoi = r.plusUrgent ? r.plusUrgent.label : 'une étape';
      const lien = r.orderId ? ` <button class="btn ghost sm" style="padding:1px 8px;font-size:.72rem" onclick="cmdView(${r.orderId})">🔎 Voir</button>` : '';
      urgences.push(`La commande <b>${esc2(r.client)}</b> : l'étape « ${esc2(quoi)} » aurait déjà dû démarrer. À lancer sans tarder.${lien}`);
    });
  }
  if(b.aDesDlcProches && Array.isArray(b.dlcFinis)){
    b.dlcFinis.filter(d=>d.urgent).slice(0,3).forEach(d=>{
      const q = (typeof qty==='function') ? qty(d.qte) : d.qte;
      const when = d.joursAvantDLC<0 ? 'a dépassé sa DLC' : d.joursAvantDLC===0 ? 'périme aujourd\'hui' : 'périme demain';
      const lien = ` <button class="btn ghost sm" style="padding:1px 8px;font-size:.72rem" onclick="goView('stockparfums')">🔎 Stock</button>`;
      urgences.push(`<b>${q} ${esc2(d.parfum)}</b> (lot ${esc2(d.lot)}) ${when} — à écouler en priorité.${lien}`);
    });
  }
  if(urgences.length){
    sections.push(`<div style="margin-bottom:10px">
      <div style="font-weight:700;color:#b3261e;margin-bottom:4px">⚠️ À traiter en priorité</div>
      ${urgences.map(u=>`<div style="font-size:.86rem;margin:3px 0;padding-left:4px">• ${u}</div>`).join('')}
    </div>`);
  }

  // --- 1bis) COMMANDES À RETIRER (aujourd'hui / demain) ---
  if(b.aDesCommandesProches && Array.isArray(b.commandesProches)){
    const lignes = b.commandesProches.slice(0,5).map(c=>{
      const when = c.etat==='retard' ? `<span style="color:#b3261e">en retard de ${-c.joursAvantRetrait} j</span>`
                 : c.etat==='aujourdhui' ? '<span style="color:#d98324">aujourd\'hui</span>'
                 : 'demain';
      const lien = c.orderId ? ` <button class="btn ghost sm" style="padding:1px 8px;font-size:.72rem" onclick="cmdView(${c.orderId})">🔎 Voir</button>` : '';
      return `<div style="font-size:.86rem;margin:3px 0;padding-left:4px">• <b>${esc2(c.client)}</b> — à remettre ${when}${lien}</div>`;
    }).join('');
    sections.push(`<div style="margin-bottom:10px">
      <div style="font-weight:700;color:#5a3a2a;margin-bottom:4px">📦 Commandes à remettre</div>
      ${lignes}
    </div>`);
  }

  // --- 2) À PRODUIRE (le plan, top 4) ---
  if(Array.isArray(b.plan) && b.plan.length){
    // On n'affiche que les lignes avec un VRAI nom de produit (un tiret nu n'aide personne).
    const planNomme = b.plan.filter(it=> it.produitNom && String(it.produitNom).trim() && !/^recette #/i.test(String(it.produitNom)));
    const top = planNomme.slice(0,4);
    if(top.length){
      const items = top.map((it,i)=>{
        const q = (it.qte!=null) ? `${(typeof qty==='function')?qty(it.qte):it.qte} pièces` : 'à écouler';
        const pour = it.type==='commande' ? ' <span style="color:#9a8a82">(commande)</span>'
                   : it.type==='rupture' ? ' <span style="color:#9a8a82">(réassort)</span>'
                   : it.type==='reassort' ? ' <span style="color:#9a8a82">(réassort)</span>'
                   : it.type==='antigaspi' ? ' <span style="color:#9a8a82">(anti-gaspi)</span>' : '';
        // Boutons d'action : produire (pré-rempli) + voir la recette, si la recette est connue.
        let actions='';
        if(it.recipeId){
          const qteProd = (it.qte!=null && it.qte>0) ? Math.round(it.qte) : 1;
          actions = ` <button class="btn ghost sm" style="padding:1px 8px;font-size:.72rem" onclick="prodForm({recipeId:${it.recipeId}, qte:${qteProd}})">⚙ Produire</button>`
                  + ` <button class="btn ghost sm" style="padding:1px 8px;font-size:.72rem" onclick="recForm(${it.recipeId})">📖 Recette</button>`;
        }
        return `<div style="font-size:.86rem;margin:5px 0">${i+1}. <b>${esc2(it.produitNom)}</b> — ${q}${pour}${actions}</div>`;
      }).join('');
      const reste = planNomme.length>top.length ? `<div style="font-size:.78rem;color:#9a8a82;margin-top:2px">+ ${planNomme.length-top.length} autre(s)</div>` : '';
      // Astuce stock déjà produit (si une ligne a des coques en stock)
      let astuce='';
      if(Array.isArray(b.lignesPlan)){
        const avecCoques = b.lignesPlan.find(l=>l.coquesStock>0 && l.qte>0);
        if(avecCoques){ astuce = `<div style="font-size:.78rem;color:#3f7d52;margin-top:4px">💡 Tu as déjà des coques en stock pour ${esc2(avecCoques.parfum)} → tu peux en produire moins.</div>`; }
      }
      sections.push(`<div style="margin-bottom:10px">
        <div style="font-weight:700;color:#5a3a2a;margin-bottom:4px">🍩 À produire ${planNomme.length?`<span style="font-weight:400;color:#9a8a82;font-size:.8rem">(${planNomme.length} conseil${planNomme.length>1?'s':''}, 14 j)</span>`:''}</div>
        ${items}${reste}${astuce}
      </div>`);
    }
  }

  // --- 3) TEMPS (ça tient ?) — seulement si calculé ---
  if(b.dispo && b.dispo.temps && b.dispo.planning && b.tempsSuffisant!=null){
    const fiable = b.tempsLisseFiable;
    const nuance = fiable ? '' : ` <span style="color:#9a8a82">(estimation encore approximative — chronomètre plus de productions pour l'affiner)</span>`;
    if(b.tempsSuffisant){
      sections.push(`<div style="font-size:.84rem;margin-bottom:8px;color:#3f7d52;border-left:3px solid #bcd9c4;padding-left:8px">⏱ <b>Temps de fabrication.</b> Produire tes commandes et réassorts des 14 prochains jours représente <b>${fmtHM(b.besoinMin)}</b> de travail, soit ${b.tauxChargeHorizon!=null?`${b.tauxChargeHorizon}% de`:'une petite part de'} tes disponibilités sur 14 j — <b>ça tient largement</b>. <span style="color:#9a8a82">(ne compte pas les lots à écouler ci-dessus, qui sont juste à vendre, pas à fabriquer)</span>${nuance}</div>`);
    } else {
      sections.push(`<div style="font-size:.84rem;margin-bottom:8px;color:#d98324;border-left:3px solid #e8cfa6;padding-left:8px">⏱ <b>Attention au temps de fabrication.</b> Produire tes commandes et réassorts des 14 prochains jours demande environ <b>${fmtHM(b.tempsManquantMin)}</b> de plus que tes disponibilités sur 14 j. Pense à étaler ou élargir tes créneaux.${nuance}</div>`);
    }
  }

  // --- 4) MATIÈRES (manques chiffrés) — seulement si manques ---
  if(b.matieresOk===false && Array.isArray(b.manquesMatieres) && b.manquesMatieres.length){
    const liste = b.manquesMatieres.slice(0,4).map(m=>{
      const nom = m.nom || '(matière ?)';
      const manque = (m.besoinAff!=null && m.stockAff!=null) ? (m.besoinAff - m.stockAff) : null;
      const q = (manque!=null && manque>0) ? ` (${(typeof qty==='function')?qty(manque):Math.round(manque*1000)/1000}${m.unite?' '+m.unite:''})` : '';
      return `${esc2(nom)}${q}`;
    }).join(', ');
    sections.push(`<div style="font-size:.84rem;margin-bottom:8px;color:#b3261e">🛒 <b>À acheter</b> pour honorer tes commandes et réassorts des ${b.horizon||14} prochains jours : ${liste}.</div>`);
  }

  // --- 5) MARCHÉS (conseil de production marché) — seulement si pertinent ---
  if(b.marketVentil && Array.isArray(b.marketVentil.lignes) && b.marketVentil.lignes.length){
    const top3 = b.marketVentil.lignes.slice(0,3).map(l=>`${(typeof qty==='function')?qty(l.pieces):l.pieces} ${esc2(l.parfum)}`).join(', ');
    sections.push(`<div style="font-size:.84rem;margin-bottom:4px;color:#5a3a2a">📅 <b>Pour tes marchés à venir</b> : ${top3}${b.marketVentil.lignes.length>3?'…':''}</div>`);
  }

  // --- Assemblage ---
  if(!sections.length){
    return `<div class="banner" style="background:#eef5f0;border-color:#bcd9c4">🧭 <div><b>Rien d'urgent pour le moment.</b> Pas de commande en retard, pas de production pressante. Tu peux avancer sereinement.</div></div>`;
  }
  // Bouton "Plus de détails" : visible seulement s'il y a matière à détailler
  // (des retards à expliquer OU un manque de temps à organiser).
  const aDuDetail = b.aDesRetards || (b.tempsSuffisant===false);
  const boutonDetail = aDuDetail
    ? `<div style="margin-top:6px"><button class="btn ghost sm" onclick="voixToggleDetails(this)">▾ Plus de détails</button>
        <div class="voix-details" style="display:none;margin-top:8px"><p class="note">Calcul des explications…</p></div></div>`
    : '';
  return `<div class="panel" style="border-left:4px solid var(--bordeaux)">
    <div style="display:flex;align-items:center;gap:6px;margin-bottom:8px">
      <span style="font-size:1.05rem">🧭</span><b style="color:var(--bordeaux);font-size:1rem">Ce que je te conseille maintenant</b>
    </div>
    ${sections.join('')}
    ${boutonDetail}
  </div>`;
}

// Bascule l'affichage du détail de la voix ; le génère à la demande (calcul paresseux).
async function voixToggleDetails(btn){
  const wrap = btn.parentElement.querySelector('.voix-details');
  if(!wrap) return;
  if(wrap.style.display==='none'){
    wrap.style.display='block';
    btn.textContent='▴ Moins de détails';
    // Générer le détail une seule fois.
    if(!wrap.dataset.loaded){
      try{
        const html = await voixGenererDetails();
        wrap.innerHTML = html || '<p class="note">Aucun détail supplémentaire.</p>';
        wrap.dataset.loaded='1';
      }catch(e){ console.error('voixDetails',e); wrap.innerHTML='<p class="note">Détails indisponibles.</p>'; }
    }
  } else {
    wrap.style.display='none';
    btn.textContent='▾ Plus de détails';
  }
}

// Génère le contenu détaillé : raisonnement de chaque retard + conseils d'organisation.
async function voixGenererDetails(){
  let b;
  try{ b = await atelierBrain(); }catch(e){ return ''; }
  if(!b) return '';
  const blocs=[];

  // 1) Détail des retards (le "pourquoi" + quoi faire).
  if(b.aDesRetards && Array.isArray(b.retardsLancement) && b.retardsLancement.length){
    const details=[];
    for(const r of b.retardsLancement.slice(0,5)){
      try{ const d = await voixDetailRetard(r.orderId); if(d) details.push(d); }catch(e){swallow(e,'voixGenererDetails')}
    }
    if(details.length){
      blocs.push(`<div style="margin-bottom:6px"><div style="font-weight:700;color:#b3261e;margin-bottom:2px">Pourquoi ces étapes sont en retard</div>${details.join('')}</div>`);
    }
  }

  // 2) Conseils d'organisation face au manque de temps.
  const orga = voixDetailOrganisation(b);
  if(orga) blocs.push(orga);

  return blocs.join('');
}

/* [LA VOIX — DÉTAIL] Génère l'explication détaillée d'un retard (le "pourquoi" remonté
   du rétroplanning) + le conseil d'action. Et le bloc d'organisation face au manque de temps. */

// Convertit un nb d'heures de retard en texte lisible (j / h).
function _voixRetardTexte(h){
  h = Math.round(+h||0);
  if(h < 24) return `${h} h de retard`;
  const j = Math.floor(h/24), r = h%24;
  return r>0 ? `${j} j et ${r} h de retard` : `${j} j de retard`;
}

// Explique POURQUOI une étape devait démarrer à telle date (délais incompressibles en jeu).
function _voixPourquoiEtape(cle, rp){
  const delais = [];
  if(rp){
    if(rp.maturationH>0) delais.push(`maturation de ${rp.maturationH} h avant livraison`);
    if(cle==='ganache' && rp.reposGanacheH>0) delais.push(`repos de la ganache de ${rp.reposGanacheH} h avant le montage`);
    if(cle==='cremeux' && rp.cremeuxCongelH>0) delais.push(`congélation du crémeux de ${rp.cremeuxCongelH} h`);
    if(rp.decongelH>0) delais.push(`décongélation de ${rp.decongelH} h au frigo`);
  }
  if(!delais.length) return `En remontant depuis la date de livraison, cette étape devait déjà être lancée pour tenir les délais.`;
  return `En cause : ${delais.join(', ')}. En remontant depuis la livraison, cette étape devait démarrer à la date indiquée.`;
}

// Détail complet d'UN retard, avec conseil d'action et report concret si calculable.
async function voixDetailRetard(orderId){
  const o = await db.orders.get(orderId);
  if(!o) return '';
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const rp = (typeof retroplanningCommande==='function') ? retroplanningCommande(o, recipes) : null;
  const cale = (typeof retroplanningCale==='function') ? await retroplanningCale(orderId).catch(()=>null) : null;

  const cl = o.clientId ? await db.clients.get(o.clientId).catch(()=>null) : null;
  const clNom = cl ? cl.nom : (o.histoLabel || 'Commande');
  const fmtDT = d => d ? new Date(d).toLocaleString('fr-FR',{weekday:'long',day:'2-digit',month:'long',hour:'2-digit',minute:'2-digit'}) : '—';

  // Retrouver l'étape la plus en retard via commandesEnRetard (cohérence avec la voix).
  let retard=null;
  try{
    const all = (typeof commandesEnRetard==='function') ? await commandesEnRetard({horizon:21}) : [];
    retard = all.find(r=>r.orderId===orderId) || null;
  }catch(e){swallow(e,'voixDetailRetard')}
  if(!retard || !retard.plusUrgent) return '';

  const pu = retard.plusUrgent;
  const pourquoi = _voixPourquoiEtape(pu.cle, rp);

  // Conseil d'action : si la production est encore possible aujourd'hui, le dire ; sinon report.
  // On s'appuie sur le calage : si le début de production calé est déjà passé, c'est tendu.
  let conseil='';
  const now = new Date();
  if(cale && cale.ok && cale.debutProduction){
    const debutProd = new Date(cale.debutProduction);
    if(debutProd < now){
      // Production aurait dû commencer : estimer le report nécessaire.
      const retardJ = Math.ceil((now - debutProd)/86400000);
      const reportTxt = retardJ<=0 ? 'quelques heures' : retardJ===1 ? 'une demi-journée à une journée' : `environ ${retardJ} jour(s)`;
      conseil = `<div style="margin-top:4px;color:#b3261e"><b>Que faire :</b> lance cette étape <b>dès aujourd'hui</b>. Si ce n'est pas possible, prévois de proposer au client un report de <b>${reportTxt}</b> sur la livraison.</div>`;
    } else {
      conseil = `<div style="margin-top:4px;color:#3f7d52"><b>Que faire :</b> lance cette étape aujourd'hui et tu tiens la livraison sans report.</div>`;
    }
  } else {
    conseil = `<div style="margin-top:4px;color:#b3261e"><b>Que faire :</b> lance cette étape sans tarder pour limiter le retard.</div>`;
  }

  return `<div style="font-size:.82rem;border-left:3px solid #e5b4ae;padding-left:8px;margin:8px 0">
    <div><b>${(typeof esc==='function')?esc(clNom):clNom}</b> — livraison ${fmtDT(retard.dateLivraison)}</div>
    <div style="margin-top:2px">• Étape en retard : <b>${(typeof esc==='function')?esc(pu.label):pu.label}</b> (prévue ${fmtDT(pu.date)}, ${_voixRetardTexte(pu.retardH)})</div>
    <div style="margin-top:2px;color:#6b5d54">• ${pourquoi}</div>
    ${conseil}
    <div style="margin-top:4px"><button class="btn ghost sm" style="padding:1px 8px;font-size:.72rem" onclick="cmdView(${orderId})">🔎 Voir la commande</button></div>
  </div>`;
}

// Bloc d'organisation face au manque de temps (quoi décaler, quoi garder, créneau à ajouter).
function voixDetailOrganisation(b){
  if(!b || b.tempsSuffisant!==false) return '';   // seulement si le temps NE tient PAS
  const fmtHM = m => { m=Math.round(+m||0); const h=Math.floor(m/60), mm=m%60; return `${h?h+'h ':''}${String(mm).padStart(2,'0')}min`; };
  const manque = b.tempsManquantMin||0;

  // Distinguer le datable-reportable (réassort/anti-gaspi) du non-négociable (commandes).
  const plan = Array.isArray(b.plan) ? b.plan : [];
  const reportables = plan.filter(it=> it.type==='reassort' || it.type==='rupture' || it.type==='antigaspi')
    .filter(it=> it.produitNom && String(it.produitNom).trim());
  const commandes = plan.filter(it=> it.type==='commande' && it.produitNom && String(it.produitNom).trim());

  const lignes=[];
  if(reportables.length){
    const noms = reportables.slice(0,4).map(it=>`${(typeof esc==='function')?esc(it.produitNom):it.produitNom}${it.qte?` (${(typeof qty==='function')?qty(it.qte):it.qte})`:''}`).join(', ');
    lignes.push(`<b>Décale d'abord</b> ce qui n'a pas de date imposée : ${noms}${reportables.length>4?'…':''}. Ce sont des réassorts, ils peuvent attendre.`);
  }
  if(commandes.length){
    lignes.push(`<b>Garde en priorité</b> les commandes datées : elles ont un client et une échéance ferme.`);
  }
  lignes.push(`<b>Ou ajoute un créneau</b> : environ ${fmtHM(manque)} de travail en plus sur tes 14 jours suffirait à tout produire. <button class="btn ghost sm" style="padding:1px 8px;font-size:.72rem" onclick="availEditor()">🗓 Mes disponibilités</button>`);

  return `<div style="font-size:.82rem;background:#fdf6ec;border:1px solid #e5cfa0;border-radius:8px;padding:8px;margin-top:8px">
    <div style="font-weight:700;color:#d98324;margin-bottom:4px">⏱ Comment t'organiser (il manque ${fmtHM(manque)})</div>
    ${lignes.map(l=>`<div style="margin:3px 0">• ${l}</div>`).join('')}
  </div>`;
}
// [FIX v1297 — « Plan de production » renvoyait à l'accueil]
// Le bouton de menu « Plan de production » porte data-v="mrp", mais 'mrp' n'avait JAMAIS été
// enregistré dans la table VIEWS. Résultat : render() faisait `VIEWS['mrp'] || renderDash` et
// retombait donc sur le tableau de bord (l'accueil) — exactement le symptôme rapporté. Par ailleurs
// le vrai rendu de cet écran, renderProductionPlan(), écrit dans un conteneur #mrpConseil (ou #aiOut)
// et RETURN aussitôt si aucun n'existe : il n'a jamais été con\u00e7u comme une vue autonome montée dans
// #main. Ce wrapper corrige les deux points : il installe le conteneur dans #main PUIS délègue au
// moteur existant, sans rien dupliquer de sa logique.
async function renderMrp(){
  const main=document.getElementById('main'); if(!main) return;
  main.innerHTML = `<div class="topbar"><div><h1>Plan de production</h1><p>Ce que l'assistant te conseille de produire, calé dans ton temps disponible</p></div></div>
    <div id="mrpConseil"><div class="panel"><p class="note">⏳ Calcul du plan…</p></div></div>`;
  try{ await renderProductionPlan(); }
  catch(e){ console.error('renderMrp', e); const b=document.getElementById('mrpConseil'); if(b) b.innerHTML='<div class="panel"><p class="note">Erreur de calcul du plan de production.</p></div>'; }
}
async function renderProductionPlan(){
  const box=document.getElementById('mrpConseil') || document.getElementById('aiOut'); if(!box) return;
  box.innerHTML=`<div class="panel"><h2>🧭 Plan de production</h2><p class="note">Calcul en cours…</p></div>`;
  let plan, tl;
  try{ plan=await buildProductionPlan(14); tl=await prodTempsLissePerMacaron(90); }
  catch(e){ console.error('plan',e); box.innerHTML=`<div class="panel"><p class="note">Erreur de calcul du plan.</p></div>`; return; }
  const minParMac = (tl && tl.minParMacaron) ? tl.minParMacaron : null;
  const estMin = qte => (minParMac!=null && qte) ? Math.round(qte*minParMac) : null;
  // Coques déjà en stock par parfum (en macarons assemblables) : déduites du besoin de coques.
  let _coquesStock = {};
  try{ _coquesStock = await coquesStockByParfum(); }catch(e){swallow(e,'renderProductionPlan')}

  // Temps disponible AUJOURD'HUI, lu depuis ton planning (disponibilité bi-hebdomadaire).
  let dispoPlanning = null;
  try{
    const now=new Date();
    dispoPlanning = availMinutesOnDay(now, now.getHours()*60+now.getMinutes(), null, getAvailability());
  }catch(e){ console.error('plan dispo planning',e); }
  // Si le planning donne une valeur, on l'utilise comme temps dispo de référence (sinon le champ manuel).
  if(dispoPlanning!=null && dispoPlanning>0 && _planAlloueMin===null){ _planTempsDispoMin = dispoPlanning; }
  // Le temps réellement calé = temps ALLOUÉ à la production (≤ dispo). Par défaut = tout le dispo.
  const alloue = (_planAlloueMin!=null) ? _planAlloueMin : _planTempsDispoMin;

  // calage dans le temps ALLOUÉ
  let budget=alloue, cumul=0;
  const dansLeTemps=[], horsTemps=[];
  plan.forEach(it=>{
    const m=estMin(it.qte);
    if(m!=null && cumul+m<=budget){ cumul+=m; dansLeTemps.push({...it,min:m}); }
    else horsTemps.push({...it,min:m});
  });

  const fmtHM = m => { const h=Math.floor(m/60), mm=m%60; return `${h?h+'h ':''}${String(mm).padStart(2,'0')}min`; };
  const prioBtns = planPrioOrder().map((k,i)=>`<span class="tag" style="background:#efe7da;color:#6b5d54;margin:2px">${i+1}. ${esc(PLAN_PRIO_LABEL[k])}</span>`).join(' ');
  const ligne = it => {
    let q;
    if(it.qte!=null){
      q = `${qty(it.qte)} pièces`;
      // Équivalent en batches (pour quelqu'un qui produit par fournée).
      if(it.rendement && it.rendement>0){
        const nb = it.qte/it.rendement;
        const nbTxt = nb<1 ? nb.toFixed(1).replace('.',',') : (Math.round(nb*10)/10).toString().replace('.',',');
        q += ` <span style="color:#8a6d3b">≈ ${nbTxt} batch${nb>=2?'es':''}</span>`;
      }
    } else { q='à écouler'; }
    const col = it.type==='commande'?'#b3261e':it.type==='rupture'?'#d98324':it.type==='antigaspi'?'#7a6a9a':'#3f7d52';
    const mTxt = (it.min!=null)?`<b style="white-space:nowrap;color:#6b5d54">${it.min} min</b>`:'';
    // Coques déjà en stock pour ce parfum → conseil d'assemblage différé.
    let coquesTxt='';
    if(it.qte!=null && it.qte>0){
      const cs = _coquesStock[aiNormalize(it.produitNom)];
      if(cs && cs.coques>0){
        const besoinCoques = it.qte * COQUES_PAR_MACARON;      // 1 macaron = 2 coques
        const dispoCoques = Math.min(cs.coques, besoinCoques);  // coques utilisables ici
        const coquesAprod = Math.max(0, besoinCoques - dispoCoques);
        coquesTxt = `<br><span style="font-size:.74rem;color:#3f7d52">🟤 ${cs.coques} coque(s) en stock → produis ${coquesAprod>0?`seulement ${coquesAprod} coque(s)`:'AUCUNE coque'} (au lieu de ${besoinCoques}), ganache pour ${it.qte} macaron(s), puis assemble.</span>`;
      }
    }
    return `<div class="sum-box" style="border-left:3px solid ${col}">
      <span style="flex:1"><b>${esc(it.produitNom)}</b> <span style="color:#9a8a82">— ${q}</span><br>
        <span style="font-size:.78rem;color:#9a8a82">${esc(it.raison)}</span>${coquesTxt}</span>
      ${mTxt}</div>`;
  };

  // Deux modes d'affichage : avec temps mesuré (calage) ou sans (simple liste priorisée).
  const sansTemps = (minParMac==null);
  const listeComplete = [...dansLeTemps, ...horsTemps];

  box.innerHTML=`<div class="panel">
    <h2>🧭 Ce que l'assistant te conseille de produire</h2>
    ${dispoPlanning!=null?`<div class="sum-box" style="background:#eef5f0"><span>📅 Temps dispo aujourd'hui (planning)</span><b>${dispoPlanning>0?fmtHM(dispoPlanning):'aucune plage'}</b></div>`:''}
    <div class="field"><label>Temps que je veux allouer à la production (minutes)</label>
      <input type="number" min="0" step="15" id="plan_alloue" value="${alloue}" onchange="_planAlloueMin=Math.max(0,+this.value||0);renderProductionPlan()">
      <p class="note">Pré-rempli avec ton temps disponible du jour. Réduis-le si une partie va à l'administratif, aux courses, etc.${dispoPlanning!=null&&_planAlloueMin!=null&&_planAlloueMin<dispoPlanning?` (tu réserves ${fmtHM(dispoPlanning-_planAlloueMin)} hors production)`:''}</p></div>
    <p class="note">Priorité : ${prioBtns} <button class="btn ghost sm" onclick="planPrioForm()">Réordonner</button></p>
    ${sansTemps
      ? `<div class="banner" style="background:#fdf6ec;border-color:#e5cfa0">⏱ <div>Durées non estimées (temps par macaron pas encore mesuré). La liste ci-dessous reste classée par priorité. Lance tes chronos d'atelier pour activer le calage horaire.</div></div>
         ${listeComplete.length?`<h2 style="font-size:1rem;margin-top:10px">📋 À produire, par ordre de priorité</h2>${listeComplete.map(ligne).join('')}`:''}`
      : `<div class="sum-box" style="background:#eef5f0"><span><b>Tient dans le temps alloué</b> (${cumul} / ${budget} min)</span><b>${dansLeTemps.length} production(s)</b></div>
         ${dansLeTemps.length?`<h2 style="font-size:1rem;margin-top:10px">✅ À produire maintenant</h2>${dansLeTemps.map(ligne).join('')}`:''}
         ${horsTemps.length?`<h2 style="font-size:1rem;margin-top:10px">⏳ Si tu as plus de temps</h2>${horsTemps.map(ligne).join('')}`:''}`}
    ${(!listeComplete.length)?`<div class="banner" style="background:#eef6ee;border-color:#bcdcc0">✅ <div>Rien à produire en priorité : commandes, stocks et DLC sont sous contrôle.</div></div>`:''}
    <div class="panel" style="margin-top:12px;background:#fbf7f0">
      <h2 style="font-size:1rem">🔥 Ordonnancement intelligent</h2>
      <p class="note">Optimise tes fournées : regroupe les parfums dans des meringues (240 coques = 120 macarons, 3 parfums max) pour minimiser le nombre de productions. Choisis le périmètre :</p>
      <div style="display:flex;gap:6px;margin:8px 0">
        <button class="btn gold sm" onclick="ordoLancer('fermes')">Commandes fermes</button>
        <button class="btn gold sm" onclick="ordoLancer('reassort')">Commandes + réassort</button>
      </div>
      <div id="ordoZone"></div>
    </div>
    ${(()=>{
      // Provenance des estimations de temps : lien explicite avec l'Atelier (chronos).
      if(tl && tl.fiable && tl.minParMacaronArrondi!=null){
        return `<div class="sum-box" style="background:#eef5f0;margin-top:8px"><span>⏱ Estimations basées sur tes chronos d'atelier : <b>${tl.minParMacaronArrondi} min/macaron</b> <span style="color:#9a8a82">(${fmtHM(tl.minAtelier)} mesurées sur ${qty(tl.nbMacarons)} pièces, 90 j)</span></span></div>`;
      } else if(tl && tl.minAtelier>0){
        return `<div class="banner" style="background:#fdf6ec;border-color:#e5cfa0">⏱ <div>Estimations encore <b>indicatives</b> : seulement ${fmtHM(tl.minAtelier)} chronométrées${tl.nbMacarons?` sur ${qty(tl.nbMacarons)} pièces`:''}. Chronomètre quelques productions pour fiabiliser le calage horaire. <span class="act" onclick="goView('atelier')">Ouvrir l'Atelier →</span></div></div>`;
      } else {
        return `<div class="banner" style="background:#fdf6ec;border-color:#e5cfa0">⏱ <div>Aucun temps mesuré pour l'instant : les durées ne peuvent pas être estimées. <b>Chronomètre tes tâches dans l'Atelier</b> pour que le plan cale tes productions dans le temps. <span class="act" onclick="goView('atelier')">Ouvrir l'Atelier →</span></div></div>`;
      }
    })()}
    <p class="note" style="margin-top:8px">Conseil indicatif basé sur tes commandes, ta vélocité de ventes (14 j) et tes DLC. Les quantités sont des suggestions à ajuster.</p>
  </div>`;
  // La voix proactive ne vit plus ici : elle est centralisée dans l'écran Copilote.
}
// Réordonnancement de la priorité (simple : monter/descendre).
function planPrioForm(){
  const order=planPrioOrder();
  const rows=order.map((k,i)=>`<div class="sum-box"><span style="flex:1"><b>${i+1}.</b> ${esc(PLAN_PRIO_LABEL[k])}</span>
    <span style="display:flex;gap:4px">
      <button class="btn ghost sm" ${i===0?'disabled':''} onclick="planPrioMove(${i},-1)">▲</button>
      <button class="btn ghost sm" ${i===order.length-1?'disabled':''} onclick="planPrioMove(${i},1)">▼</button>
    </span></div>`).join('');
  openModal(`<h3>Ordre de priorité de production</h3>
    <p class="note">Détermine quoi produire en premier quand le temps est limité.</p>
    ${rows}
    <div class="modal-actions"><button class="btn" onclick="closeModal();renderProductionPlan()">Terminé</button></div>`);
}
function planPrioMove(i,dir){
  const order=planPrioOrder(); const j=i+dir;
  if(j<0||j>=order.length) return;
  [order[i],order[j]]=[order[j],order[i]];
  planPrioSave(order); planPrioForm();
}

// Prévisionnel marché intelligent : suggestion de quantités d'après l'historique.
async function renderMarketForecastBox(){
  const box=document.getElementById('marketForecast'); if(!box) return;
  let fc; try{ fc=await marketForecast(); }catch(e){ box.innerHTML=''; return; }
  const st=(typeof getSettings==='function')?getSettings():{};
  const cible=Array.isArray(st.marketMix)?st.marketMix:[];
  const cibleTotal = cible.reduce((s,c)=>s+(+c.pct||0),0);
  const cibleRows = cible.length
    ? cible.slice().sort((a,b)=>b.pct-a.pct).map(c=>{
        const reel = cibleTotal>0 ? (c.pct/cibleTotal*100) : 0;
        const normTxt = (Math.abs(cibleTotal-100)>1) ? ` <span style="color:#3f7d52;font-size:.78rem">→ ${Math.round(reel*10)/10}%</span>` : '';
        return `<div class="sum-box"><span>${esc(c.parfum)}</span><b>${c.pct}%${normTxt}</b></div>`;
      }).join('')
    : '';
  const cibleTotalTxt = (cible.length && Math.abs(cibleTotal-100)>1)
    ? `<p class="note" style="margin:4px 0 0;color:#8a6d3b">Total ${Math.round(cibleTotal)} (devrait faire 100). Le % réel à droite montre la part effective de chaque parfum. Modifie ta cible pour atteindre 100.</p>` : '';
  const cibleBloc = `<div class="panel" style="margin-top:10px;background:#fbf7f0">
      <h2 style="font-size:1rem">🎯 Ma cible de répartition</h2>
      ${cible.length
        ? `<p class="note" style="margin-top:0">Le cerveau croise cette cible avec ton historique pour ventiler tes marchés.</p>${cibleRows}${cibleTotalTxt}`
        : `<p class="note" style="margin-top:0">Aucune cible définie. Le cerveau utilise ton historique seul. Définis une cible pour affiner.</p>`}
      <div style="margin-top:8px"><button class="btn gold sm" onclick="marketMixForm()">${cible.length?'Modifier ma cible':'🎯 Définir ma cible'}</button></div>
    </div>`;
  if(!fc.nbMarches){
    // Pas d'historique : on n'affiche pas le prévisionnel, mais on permet quand même de définir la cible.
    box.innerHTML = cibleBloc;
    return;
  }
  const rep=fc.repartition.map(r=>`<div class="sum-box"><span>${esc(r.parfum||'Autre')}</span><b>${r.pct}% · ${qty(r.vendu)} vendus</b></div>`).join('');
  const sansParfum = (fc.venduSansParfum>0)
    ? `<p class="note" style="margin:8px 0 0;color:#8a6d3b">ℹ ${qty(fc.venduSansParfum)} vente(s) sans parfum identifié sont exclues de cette répartition (mais comptées dans tes volumes). Renseigne le parfum lors de tes sorties de marché pour affiner.</p>`
    : '';
  box.innerHTML=`<div class="panel"><h2>📊 Prévisionnel marché <span style="font-weight:400;font-size:.82rem;color:#9a8a82">— d'après ${fc.nbMarches} marché(s) passé(s)</span></h2>
    <div class="sum-box"><span>Ventes moyennes par marché</span><b>${qty(fc.moyenneVendu)} macarons</b></div>
    <div class="sum-box"><span>Record</span><b>${qty(fc.maxVendu)} macarons</b></div>
    <div class="sum-box"><span>💡 Quantité conseillée à prévoir</span><b style="color:var(--bordeaux)">${qty(fc.suggestion)} macarons</b></div>
    ${rep?`<p class="note" style="margin:10px 0 4px">Répartition observée par parfum <span style="color:#9a8a82">(sur ${qty(fc.venduIdentifie||0)} ventes au parfum identifié)</span> :</p>${rep}`:''}
    ${sansParfum}
  </div>${cibleBloc}`;
}

// [UI cible marché] Formulaire pour définir TA cible de répartition par parfum (marketMix).
// Pré-remplit avec l'historique si la cible est vide (point de départ naturel et transparent).
async function marketMixForm(){
  const [recipes, st] = await Promise.all([
    db.recipes.toArray().catch(()=>[]),
    Promise.resolve((typeof getSettings==='function')?getSettings():{})
  ]);
  let fc=null; try{ fc=(typeof marketForecast==='function')?await marketForecast():null; }catch(e){swallow(e,'marketMixForm')}
  const histo = (fc && Array.isArray(fc.repartition)) ? fc.repartition : [];
  const histoPct = {};
  histo.forEach(h=>{ histoPct[aiNormalize(h.parfum)] = h.pct; });
  const cible = Array.isArray(st.marketMix) ? st.marketMix : [];
  const ciblePct = {};
  cible.forEach(c=>{ ciblePct[aiNormalize(c.parfum)] = c.pct; });

  // Parfums proposés : ceux des recettes, triés (les plus vendus en historique d'abord).
  const parfums = recipes.map(r=>r.produitNom).filter(Boolean)
    .sort((a,b)=> (histoPct[aiNormalize(b)]||0) - (histoPct[aiNormalize(a)]||0) || a.localeCompare(b));

  // Volume de référence : quantité conseillée (modifiable). Sert de base à la saisie en macarons.
  const volRef = (fc && fc.suggestion>0) ? fc.suggestion : ((fc && fc.moyenneVendu>0) ? fc.moyenneVendu : 200);
  window._mixVolRef = volRef;

  const rows = parfums.map(p=>{
    const k=aiNormalize(p);
    // Valeur pré-remplie EN MACARONS : proportion (cible si définie, sinon historique) × volume réf.
    const pct = (ciblePct[k]!=null) ? ciblePct[k] : (histoPct[k]!=null ? histoPct[k] : null);
    const valMac = (pct!=null) ? Math.round(volRef*pct/100) : '';
    const histoTxt = histoPct[k]!=null ? `<span style="color:#9a8a82;font-size:.74rem">historique ${histoPct[k]}%</span>` : `<span style="color:#c9bcae;font-size:.74rem">pas d'historique</span>`;
    return `<div class="sum-box" style="align-items:center">
      <span style="flex:1">${esc(p)}<br>${histoTxt} <span id="mixnorm_${k}" style="font-size:.78rem;color:#3f7d52;font-weight:600"></span></span>
      <span style="display:flex;align-items:center;gap:4px">
        <input type="number" min="0" step="1" id="mix_${k}" value="${valMac}" style="width:62px;text-align:right" oninput="marketMixSum()" inputmode="numeric">
        <span style="color:#9a8a82;font-size:.8rem">mac.</span></span></div>`;
  }).join('');

  openModal(`<h3>🎯 Ma cible de répartition marché</h3>
    <p class="note">Répartis tes macarons par parfum, en partant du volume prévu. Le <b>pourcentage</b> de chaque parfum s'affiche à droite. C'est cette répartition (en %) qui sera réutilisée pour tous tes marchés, quel que soit leur volume.</p>
    <div class="field" style="margin-bottom:8px"><label>Volume de référence (macarons à répartir)</label>
      <input type="number" min="1" step="10" id="mix_volref" value="${volRef}" oninput="marketMixVolRefChange()" inputmode="numeric">
      <p class="note" style="margin-top:2px">Pré-rempli avec ta quantité conseillée — ajuste-le si tu veux raisonner sur un autre volume.</p></div>
    <div class="sum-box" style="background:#eef5f0"><span><b>Total réparti</b></span><b id="mix_total">0</b></div>
    <p class="note" id="mix_hint" style="margin:4px 0 10px"></p>
    ${rows || '<p class="note">Aucune recette. Crée des recettes pour définir une cible.</p>'}
    <div class="modal-actions">
      <button class="btn ghost" style="margin-right:auto" onclick="closeModal()">Annuler</button>
      <button class="btn ghost" onclick="marketMixUseHisto()" title="Repartir de l'historique">↺ Historique</button>
      <button class="btn gold" onclick="marketMixSave()">Enregistrer</button>
    </div>`);
  // Liste des parfums mémorisée pour la sauvegarde.
  window._mixParfums = parfums;
  marketMixSum();
}

// Recalcule le total réparti (en macarons) et le % de chaque parfum sur ce total.
function marketMixSum(){
  const parfums = window._mixParfums||[];
  const volRef = window._mixVolRef||0;
  let tot=0;
  parfums.forEach(p=>{ const el=document.getElementById('mix_'+aiNormalize(p)); const v=el?Math.max(0,+el.value||0):0; tot+=v; });
  const totEl=document.getElementById('mix_total'); if(totEl) totEl.textContent = `${Math.round(tot)} mac.`;
  const hint=document.getElementById('mix_hint');
  if(hint){
    if(tot===0) hint.innerHTML='<span style="color:#9a8a82">Répartis tes macarons par parfum. Le % de chacun s’affiche à droite.</span>';
    else if(!volRef) hint.innerHTML=`<span style="color:#3f7d52">${Math.round(tot)} macarons répartis.</span>`;
    else if(Math.abs(tot-volRef)<=2) hint.innerHTML=`<span style="color:#3f7d52">✓ ${Math.round(tot)} macarons répartis — tu colles au volume de référence (${volRef}).</span>`;
    else if(tot<volRef) hint.innerHTML=`<span style="color:#8a6d3b">${Math.round(tot)} répartis sur ${volRef} — il reste ${Math.round(volRef-tot)} macarons à placer. <span style="color:#9a8a82">(Pas obligatoire : seule la répartition compte.)</span></span>`;
    else hint.innerHTML=`<span style="color:#8a6d3b">${Math.round(tot)} répartis, soit ${Math.round(tot-volRef)} de plus que le volume de référence (${volRef}). <span style="color:#9a8a82">(Ça reste une proportion, c’est OK.)</span></span>`;
  }
  // % de chaque parfum sur le total réparti (affiché en permanence).
  parfums.forEach(p=>{
    const k=aiNormalize(p);
    const normEl=document.getElementById('mixnorm_'+k);
    if(!normEl) return;
    const el=document.getElementById('mix_'+k);
    const v=el?Math.max(0,+el.value||0):0;
    if(v>0 && tot>0){
      const pct = v/tot*100;
      normEl.textContent = `→ ${Math.round(pct*10)/10}%`;
    } else {
      normEl.textContent='';
    }
  });
}

// Recalcule les macarons quand on change le volume de référence : on garde les % et on
// recalcule les nombres de macarons en conséquence (la répartition reste, le volume change).
function marketMixVolRefChange(){
  const parfums = window._mixParfums||[];
  const volEl=document.getElementById('mix_volref');
  const newVol=volEl?Math.max(0,+volEl.value||0):0;
  // % actuels (sur l'ancien total) → appliqués au nouveau volume.
  let oldTot=0; const cur={};
  parfums.forEach(p=>{ const el=document.getElementById('mix_'+aiNormalize(p)); const v=el?Math.max(0,+el.value||0):0; cur[aiNormalize(p)]=v; oldTot+=v; });
  if(oldTot>0 && newVol>0){
    parfums.forEach(p=>{ const k=aiNormalize(p); const el=document.getElementById('mix_'+k);
      if(el){ const pct=cur[k]/oldTot; el.value=Math.round(newVol*pct); } });
  }
  window._mixVolRef=newVol;
  marketMixSum();
}

// Recharge les champs avec l'historique, converti EN MACARONS sur le volume de référence.
async function marketMixUseHisto(){
  let fc=null; try{ fc=await marketForecast(); }catch(e){swallow(e,'marketMixUseHisto')}
  const histo=(fc&&Array.isArray(fc.repartition))?fc.repartition:[];
  const hp={}; histo.forEach(h=>hp[aiNormalize(h.parfum)]=h.pct);
  const volRef=window._mixVolRef||200;
  (window._mixParfums||[]).forEach(p=>{ const k=aiNormalize(p); const el=document.getElementById('mix_'+k);
    if(el){ el.value = (hp[k]!=null) ? Math.round(volRef*hp[k]/100) : ''; } });
  marketMixSum();
}

// Enregistre la cible dans les réglages (settings.marketMix), STOCKÉE EN PROPORTION (%).
// L'utilisateur saisit en macarons ; on convertit en % pour que la cible soit réutilisable
// sur tous les marchés quel que soit leur volume.
function marketMixSave(){
  const parfums = window._mixParfums||[];
  // 1) Lire les macarons saisis par parfum + le total réparti.
  const macs=[]; let tot=0;
  parfums.forEach(p=>{
    const el=document.getElementById('mix_'+aiNormalize(p));
    const m=el?Math.max(0,+el.value||0):0;
    if(m>0){ macs.push({parfum:p, mac:m}); tot+=m; }
  });
  // 2) Convertir en proportions (%) sur le total réparti.
  const mix = (tot>0) ? macs.map(x=>({parfum:x.parfum, pct: Math.round(x.mac/tot*1000)/10})) : [];
  const st=(typeof getSettings==='function')?getSettings():{};
  st.marketMix=mix;
  if(typeof saveSettings==='function') saveSettings(st);
  closeModal();
  toast(mix.length?`Cible enregistrée (${mix.length} parfum(s)) ✓`:'Cible vidée');
  if(typeof renderMarketForecastBox==='function') renderMarketForecastBox();
}

/* [NIVEAU 2] AJUSTEMENT DE RÉPARTITION PAR MARCHÉ.
   Part de ta cible proportionnelle (modèle réutilisable) appliquée au VOLUME de CE marché,
   et te laisse ajuster les nombres réels pour ce marché précis — sans toucher à la cible modèle.
   Stocké sur le marché dans mk.mkMix = [{parfum, mac}] (macarons ajustés pour ce marché).
*/
async function marketAdjustForm(id){
  const mk = await db.markets.get(id);
  if(!mk){ toast('Marché introuvable'); return; }
  const [recipes, st] = await Promise.all([
    db.recipes.toArray().catch(()=>[]),
    Promise.resolve((typeof getSettings==='function')?getSettings():{})
  ]);
  let fc=null; try{ fc=(typeof marketForecast==='function')?await marketForecast():null; }catch(e){swallow(e,'marketAdjustForm')}
  const histo = (fc && Array.isArray(fc.repartition)) ? fc.repartition : [];
  const cible = Array.isArray(st.marketMix) ? st.marketMix : [];

  // Volume de CE marché.
  const volume = +mk.prevuQte||0;
  // Ajustement déjà enregistré pour ce marché ?
  const mkMix = Array.isArray(mk.mkMix) ? mk.mkMix : null;
  const mkMixByParfum = {};
  if(mkMix) mkMix.forEach(x=>{ mkMixByParfum[aiNormalize(x.parfum)] = +x.mac||0; });

  // Ventilation de DÉPART = cible × historique appliquée au volume (ce que le cerveau propose).
  let ventil = {lignes:[]};
  try{ ventil = marketVentilation(cible, histo, volume, {mode:'croise'}); }catch(e){swallow(e,'marketAdjustForm')}
  const ventilByParfum = {};
  (ventil.lignes||[]).forEach(l=>{ ventilByParfum[aiNormalize(l.parfum)] = l.pieces; });

  // Parfums : ceux de la ventilation + ceux des recettes (pour pouvoir en ajouter).
  const parfums = recipes.map(r=>r.produitNom).filter(Boolean)
    .sort((a,b)=> (ventilByParfum[aiNormalize(b)]||0) - (ventilByParfum[aiNormalize(a)]||0) || a.localeCompare(b));

  window._mkAdjustId = id;
  window._mkAdjustVol = volume;
  window._mkAdjustParfums = parfums;

  const rows = parfums.map(p=>{
    const k=aiNormalize(p);
    // Valeur pré-remplie : ajustement marché si présent, sinon la proposition du cerveau.
    const propose = ventilByParfum[k]||0;
    const val = (mkMixByParfum[k]!=null) ? mkMixByParfum[k] : (propose>0 ? propose : '');
    const proposeTxt = propose>0 ? `<span style="color:#9a8a82;font-size:.74rem">proposé ${propose}</span>` : `<span style="color:#c9bcae;font-size:.74rem">—</span>`;
    return `<div class="sum-box" style="align-items:center">
      <span style="flex:1">${esc(p)}<br>${proposeTxt} <span id="mkadj_pct_${k}" style="font-size:.78rem;color:#3f7d52;font-weight:600"></span></span>
      <span style="display:flex;align-items:center;gap:4px">
        <input type="number" min="0" step="1" id="mkadj_${k}" value="${val}" style="width:62px;text-align:right" oninput="marketAdjustSum()" inputmode="numeric">
        <span style="color:#9a8a82;font-size:.8rem">mac.</span></span></div>`;
  }).join('');

  openModal(`<h3>🎯 Répartition de ce marché</h3>
    <p class="note">Voici la répartition que le cerveau propose pour <b>${esc(mk.nom||'ce marché')}</b> (volume prévu : <b>${volume}</b> macarons), à partir de ta cible. <b>Ajuste librement</b> pour ce marché précis — ta cible modèle n'est pas modifiée.</p>
    <div class="sum-box" style="background:#eef5f0"><span><b>Total réparti</b></span><b id="mkadj_total">0</b></div>
    <p class="note" id="mkadj_hint" style="margin:4px 0 10px"></p>
    ${rows || '<p class="note">Aucune recette.</p>'}
    <div class="modal-actions">
      <button class="btn ghost" style="margin-right:auto" onclick="closeModal()">Annuler</button>
      <button class="btn ghost" onclick="marketAdjustReset()" title="Repartir de la proposition du cerveau">↺ Proposition</button>
      <button class="btn gold" onclick="marketAdjustSave()">Enregistrer</button>
    </div>`);
  marketAdjustSum();
}

// Total + % par parfum pour l'ajustement marché.
function marketAdjustSum(){
  const parfums = window._mkAdjustParfums||[];
  const vol = window._mkAdjustVol||0;
  let tot=0;
  parfums.forEach(p=>{ const el=document.getElementById('mkadj_'+aiNormalize(p)); tot += el?Math.max(0,+el.value||0):0; });
  const totEl=document.getElementById('mkadj_total'); if(totEl) totEl.textContent=`${Math.round(tot)} mac.`;
  const hint=document.getElementById('mkadj_hint');
  if(hint){
    if(tot===0) hint.innerHTML='<span style="color:#9a8a82">Répartis les macarons de ce marché par parfum.</span>';
    else if(!vol) hint.innerHTML=`<span style="color:#3f7d52">${Math.round(tot)} macarons répartis.</span>`;
    else if(Math.abs(tot-vol)<=2) hint.innerHTML=`<span style="color:#3f7d52">✓ ${Math.round(tot)} macarons — tu colles au volume prévu (${vol}).</span>`;
    else if(tot<vol) hint.innerHTML=`<span style="color:#8a6d3b">${Math.round(tot)} répartis sur ${vol} prévus — il reste ${Math.round(vol-tot)} à placer.</span>`;
    else hint.innerHTML=`<span style="color:#8a6d3b">${Math.round(tot)} répartis, soit ${Math.round(tot-vol)} de plus que prévu (${vol}).</span>`;
  }
  parfums.forEach(p=>{
    const k=aiNormalize(p); const pctEl=document.getElementById('mkadj_pct_'+k);
    if(!pctEl) return;
    const el=document.getElementById('mkadj_'+k); const v=el?Math.max(0,+el.value||0):0;
    pctEl.textContent = (v>0 && tot>0) ? `→ ${Math.round(v/tot*1000)/10}%` : '';
  });
}

// Repart de la proposition du cerveau (réinitialise l'ajustement).
async function marketAdjustReset(){
  const id=window._mkAdjustId; if(id==null) return;
  const mk=await db.markets.get(id); if(!mk) return;
  // On vide l'ajustement enregistré puis on rouvre (repart de la proposition).
  if(mk.mkMix){ delete mk.mkMix; await db.markets.update(id, {mkMix:null}); }
  closeModal(); marketAdjustForm(id);
}

// Enregistre l'ajustement sur le marché (mk.mkMix), en macarons.
async function marketAdjustSave(){
  const id=window._mkAdjustId; if(id==null) return;
  const parfums=window._mkAdjustParfums||[];
  const mkMix=[];
  parfums.forEach(p=>{ const el=document.getElementById('mkadj_'+aiNormalize(p)); const m=el?Math.max(0,+el.value||0):0; if(m>0) mkMix.push({parfum:p, mac:m}); });
  await db.markets.update(id, {mkMix});
  closeModal();
  toast(`Répartition du marché enregistrée (${mkMix.length} parfum(s)) ✓`);
  if(typeof marketDetail==='function') marketDetail(id);
}
// Rafraîchit la jauge périodiquement tant que l'onglet Assistant est affiché
// (background check), et au retour au premier plan. S'auto-arrête sinon.
let _serenityTimer=null;
// Jauge de sérénité (barre colorée dynamique) — recalculée à chaque ouverture
// et rafraîchie en arrière-plan tant que l'onglet Assistant est affiché.
async function renderSerenityGauge(){
  const box=document.getElementById('serenityBox'); if(!box) return;
  let g; try{ g=await calculateSerenityScore({horizon:15}); }catch(e){ box.innerHTML=''; return; }
  box.innerHTML=`<div class="panel serenity">
    <div class="ser-head"><span class="ser-title">🧘 Jauge de sérénité</span>
      <span class="ser-score" style="color:${g.col}">${g.score}% · ${g.label}</span></div>
    <div class="ser-bar"><span style="width:${g.score}%;background:linear-gradient(90deg,#b3261e,#d98324,#caa23b,#7faa4f,#3f7d52);"></span>
      <i style="left:calc(${g.score}% - 1px)"></i></div>
    <div class="ser-meta">
      <span>${g.nbCommandes} commande(s)${g.nbMarches?` · ${g.nbMarches} marché(s)`:''} sur ${g.horizon} j</span>
      <span>${g.aProduire>0?`À produire : <b>${qty(g.aProduire)}</b> · charge ~${g.chargeTxt}`:'Tout est couvert par le stock ✓'}</span>
    </div>
    ${g.marches&&g.marches.length?`<div class="ser-markets">${g.marches.map(m=>`<span class="tag event">⛺ ${esc(m.nom||'Marché')} · ${m.dans!=null?(m.dans<=0?"auj.":'J−'+m.dans):''} · ${qty(m.prevu)} prévus</span>`).join(' ')}</div>`:''}
    ${g.urgenceCritique?`<p class="note" style="color:var(--red,#b3261e);margin-top:6px">⚠ Échéance critique sous 3 jours non couverte par le stock — lance une production en priorité.</p>`:''}
  </div>`;
}
// Cartes d'alerte Anti-Gaspi (matières dont la DLC approche).
// Affiche, en haut de l'assistant, les alertes de rupture PRÉDICTIVES (rythme de ventes).
// ============================================================================================
// [COCKPIT — raccourcis contextuels génériques] À chaque intention de l'assistant, on associe un ou
// plusieurs raccourcis qui amènent à l'écran (ou l'objet précis) concerné. Principe : une réponse de
// l'assistant ne doit pas être un cul-de-sac — elle propose toujours « et ensuite, va agir ici ».
// Chaque raccourci : { label, view, cible? (objet précis), action? (fonction directe au lieu d'un goView) }.
// Étape 1 : on démarre avec query_revenue seul, pour valider le mécanisme avant de généraliser.
// [COCKPIT] Actions rapides déclenchables depuis les raccourcis du copilote.
// Certaines nécessitent navigation PUIS action (ex. lancer une session depuis l'atelier) :
// on encapsule ça ici pour que le raccourci reste un simple appel de fonction.
function aiActNouvelleCommande(){ if(typeof cmdForm==='function') cmdForm(); }
function aiActNouveauClient(){ if(typeof clientForm==='function') clientForm(); }
function aiActNouvelleMatiere(){ if(typeof matForm==='function') matForm(); }
function aiActNouvelleRecette(){ if(typeof recForm==='function') recForm(); }
function aiActLancerSession(){
  // va à l'atelier puis démarre une session de chrono (si pas déjà en cours)
  try{ goView('atelier'); }catch(e){swallow(e,'aiActLancerSession')}
  setTimeout(()=>{ try{ if(typeof prodSessActive==='function' && !prodSessActive() && typeof prodSessionStart==='function'){ prodSessionStart(); } if(typeof prodRenderBoard==='function') prodRenderBoard(); }catch(e){swallow(e,'aiActLancerSession')} }, 120);
}

