// [LOT 2] RENTABILITÉ — par parfum (analyzeFlavorProfitability) ou par client (computeOrderMargins).
// Réutilise les MÊMES moteurs que les écrans dédiés (source unique), ne recalcule rien de neuf.
// Donne le top/flop en réponse directe + un raccourci vers l'écran complet.
async function aiQueryRentabilite(params){
  params = params || {};
  let cible = params.cible;
  if(!cible){
    return aiSay(`<p>Tu veux la rentabilité <b>par parfum</b> ou <b>par client</b> ?</p>
      <p class="note">Dis par exemple : « le parfum le plus rentable » ou « quel client me fait gagner le plus ».</p>`);
  }
  const sensPire = (params.sens==='pire');
  try{
    if(cible==='parfum'){
      const [recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions] = await Promise.all([
        db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray(), db.materials.toArray(),
        db.orders.toArray(), db.markets.toArray(), db.marketMoves.toArray(), db.productions.toArray()
      ]);
      const data = {recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions, settings:getSettings()};
      const A = analyzeFlavorProfitability(data);
      const vendus = A.rows.filter(r=>r.tauxMarge!=null && r.piecesVendues>0);
      if(!vendus.length) return aiSay(`<p class="note">Pas encore assez de ventes avec coût de revient connu pour classer la rentabilité des parfums.</p>`);
      const tri = [...vendus].sort((a,b)=> sensPire ? a.tauxMarge-b.tauxMarge : b.tauxMarge-a.tauxMarge);
      const head = tri[0];
      const liste = tri.slice(0,6).map((x,i)=>`<div class="sum-box"><span>${i+1}. <b>${esc(x.nom)}</b></span><b style="color:${x.tauxMarge>=0?'#3f7d52':'var(--red,#b3261e)'}">${x.tauxMarge}% · ${euro(x.margeBrute)}</b></div>`).join('');
      return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">${sensPire?'Parfums les MOINS rentables':'Parfums les plus rentables'} <span style="font-weight:400;font-size:.78rem;color:#9a8a82">(taux de marge brute)</span></h3>
        <div style="font-size:.86rem;margin-bottom:8px">${sensPire?'Le moins rentable':'Ton plus rentable'} : <b>${esc(head.nom)}</b> — ${head.tauxMarge}% de marge (${euro(head.margeBrute)} sur ${qty(head.piecesVendues)} pièces).</div>
        ${liste}`);
    }
    // cible === 'client'
    const [orders, recipes, recipeItems, lots, clients] = await Promise.all([
      db.orders.toArray(), db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray(), db.clients.toArray()
    ]);
    const clName=(id)=>{ const c=clients.find(x=>x.id===id); return c?c.nom:'Client'; };
    // [v1421] `commandeMereId==null` : une fille dupliquerait le CA et la marge de sa mère sur le même client.
    const paid = orders.filter(o=> !o.histo && o.commandeMereId==null && (+o.montant>0) && (typeof orderPaid==='function') && orderPaid(o)+1e-9 >= (+o.montant));
    if(!paid.length) return aiSay(`<p class="note">Aucune commande payée pour calculer la rentabilité par client.</p>`);
    const byClient={};
    paid.forEach(o=>{ const m=computeOrderMargins(o,recipes,recipeItems,lots); const k=o.clientId||0;
      (byClient[k] ||= {id:k, nom:clName(k), ca:0, nette:0, n:0}); const c=byClient[k];
      c.ca=Math.round((c.ca+m.ca)*100)/100; c.nette=Math.round((c.nette+m.margeNette)*100)/100; c.n++; });
    const rows=Object.values(byClient).map(c=>({...c, tauxNet:c.ca>0?Math.round(c.nette/c.ca*1000)/10:0}));
    if(!rows.length) return aiSay(`<p class="note">Pas assez de données de marge par client.</p>`);
    const tri=[...rows].sort((a,b)=> sensPire ? a.nette-b.nette : b.nette-a.nette);
    const head=tri[0];
    const liste=tri.slice(0,6).map((x,i)=>`<div class="sum-box"><span>${i+1}. ${x.id?`<span class="link-name" onclick="clientFiche(${x.id})">${esc(x.nom)}</span>`:esc(x.nom)}</span><b style="color:${x.nette>=0?'#3f7d52':'var(--red,#b3261e)'}">${euro(x.nette)} · ${x.tauxNet}%</b></div>`).join('');
    return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">${sensPire?'Clients les MOINS rentables':'Clients les plus rentables'} <span style="font-weight:400;font-size:.78rem;color:#9a8a82">(marge nette)</span></h3>
      <div style="font-size:.86rem;margin-bottom:8px">${sensPire?'Le moins rentable':'Ton client le plus rentable'} : <b>${esc(head.nom)}</b> — ${euro(head.nette)} de marge nette sur ${head.n} commande(s).</div>
      ${liste}`);
  }catch(e){
    console.error('aiQueryRentabilite', e);
    return aiSay(`<p class="note">Impossible de calculer la rentabilité (données incomplètes).</p>`);
  }
}
// [COCKPIT] TOP PARFUM : « quel est le parfum le plus vendu (depuis 6 mois) ». Réutilise computeStats
// (source unique) en filtrant les commandes sur la période demandée. Ne recalcule rien : filtre + trie.
// ════════════════════════════════════════════════════════════════════════════
//  [v1343 — VAGUE 64] CE QUE LES CLIENTS ASSOCIENT — et ce que Ben a composé
//
//  CE QUE J'AI CRU, ET QUI ÉTAIT FAUX
//  Le document de cadrage annonçait un « data gap » : la composition des coffrets ne serait
//  pas stockée. Je l'ai répété à Ben — sans vérifier. C'EST FAUX. `o.lignes[].parfums` est
//  déjà un tableau [{nom, qte}], et `marketMoves.parfum` trace chaque mouvement de marché.
//  RIEN N'EST PERDU, rien ne l'a jamais été. J'ai affirmé une règle sans la confronter au réel :
//  exactement le péché que ces 63 vagues traquent. La correction est due, et elle est ici.
//
//  LE VRAI PIÈGE, LUI, EST INVISIBLE
//  `sansParfum` compte les macarons que le client N'A PAS choisis — ceux que BEN compose
//  (mode « assortiment »). Les compter comme des associations client transformerait les
//  décisions de Ben en préférences de ses clients, puis les lui recommanderait comme des
//  découvertes. Une boucle où l'app confirme à Ben ses propres choix en les déguisant en
//  données. C'est la v1341 (les pyramides) au carré.
//
//  RÈGLE GRAVÉE (v1343) : UNE DONNÉE PRODUITE PAR BEN NE DOIT JAMAIS REVENIR VERS LUI
//  DÉGUISÉE EN DONNÉE PRODUITE PAR SES CLIENTS.
// ════════════════════════════════════════════════════════════════════════════

// ---------------------------------------------------------------------------
// LES PANIERS. Un panier = une ligne de commande où le CLIENT a choisi ses parfums.
// On EXCLUT : sansParfum (composé par Ben), les dons (0 €), les reprises d'historique
// (o.histo — données d'avant l'app), et les lignes à un seul parfum (une association
// a besoin de DEUX parfums : un coffret mono-parfum n'associe rien).
//
// LES MARCHÉS SONT EXCLUS, ET C'EST UN CHOIX, PAS UN OUBLI : `marketMoves` enregistre ce
// qui SORT du stock, parfum par parfum — mais un marché entier forme UN SEUL mouvement par
// parfum. On ne sait pas QUI a acheté quoi ENSEMBLE. Traiter un marché comme un panier
// dirait « tous les parfums vendus ce jour-là vont ensemble » : une association fabriquée
// par le calendrier, pas par un client. La v1336 a appris à ne pas OUBLIER les marchés ;
// celle-ci apprend à ne pas les FAIRE PARLER là où ils sont muets.
// ---------------------------------------------------------------------------
function paniersClients(orders, opts){
  opts = opts || {};
  const paniers = [];
  // [v1347] On compte aussi les COMMANDES VUES et RETENUES. Ben a 110 commandes et n'en voit
  // que 63 arriver dans le calcul : l'app savait pourquoi (elle comptait déjà ses rejets) mais
  // ne le DISAIT PAS. Un moteur qui écarte 43 % de tes données sans te dire lesquelles ni
  // pourquoi te demande une confiance qu'il n'a pas méritée.
  //
  // RÈGLE GRAVÉE (v1347) : UN FILTRE SILENCIEUX EST UN MENSONGE PAR OMISSION.
  // Tout ce qui est écarté doit être COMPTÉ, NOMMÉ et MONTRÉ — sinon l'utilisateur ne peut pas
  // savoir si le chiffre qu'il lit repose sur ses données ou sur un dixième d'entre elles.
  const rejets = { sansParfum:0, monoParfum:0, dons:0, histo:0, assortimentPur:0, pro:0,
                   commandesVues:0, commandesRetenues:0, sansLigne:0 };

  // [v1346] EXCLURE LES CLIENTS PRO — et NON les « grands formats ».
  //
  // Ben a signalé que Myrtille framboise + Chocolat + Mangue passion (lift ×4,58 !) n'était PAS
  // une affinité de goût : c'est son salon de thé qui recommande toujours les mêmes grands formats.
  // Il a d'abord dit « les grands formats sont à 98 % des commandes pro »… « mais ça va changer ».
  //
  // FILTRER SUR LE FORMAT AURAIT ÉTÉ LE PIÈGE : la règle serait devenue fausse le jour où un
  // particulier commande un grand format — et fausse EN SILENCE, en jetant de vrais choix clients.
  // Une règle vraie « à 98 % aujourd'hui » est une règle qui pourrira à une date inconnue.
  // On filtre donc sur ce qui porte réellement le biais : LE CLIENT (client.type contient 'pro').
  //
  // RÈGLE GRAVÉE (v1346) : FILTRER SUR LA CAUSE, JAMAIS SUR SON SYMPTÔME DU MOMENT.
  // Le symptôme (le format) change ; la cause (un acheteur pro qui répète sa commande) reste.
  const clientsPro = new Set();
  (opts.clients || []).forEach(c => {
    if(c && c.type && String(c.type).toLowerCase().includes('pro')) clientsPro.add(c.id);
  });

  (orders || []).forEach(o => {
    if(!o) return;
    rejets.commandesVues++;                                      // [v1347]
    if(o.histo){ rejets.histo++; return; }                       // reprise : pas une vente observée ici
    if(o.clientId != null && clientsPro.has(o.clientId)){ rejets.pro++; return; }   // [v1346]

    const lignes = (typeof orderToLines === 'function') ? orderToLines(o) : (o.lignes || []);
    // [v1348, CORRIGÉ EN v1349] Le journal ne tombait pas juste — mais dans l'AUTRE SENS que
    // je l'avais cru : 133 rejets+retenues pour 128 vues, un SURPLUS de 5, pas un manque.
    // Mon v1348 traitait le mauvais symptôme (les commandes sans format, qui EXISTENT mais
    // n'étaient qu'un trou théorique — sansLigne valait 0 chez Ben).
    //
    // LA VRAIE CAUSE : `dons`, `monoParfum`, `assortimentPur` et `sansParfum` comptent des
    // LIGNES, alors que `commandesVues` / `commandesRetenues` comptent des COMMANDES. Une
    // commande à PLUSIEURS lignes qui tombe dans un motif à chaque ligne (ex. deux lignes à
    // 0 €) incrémente `rejets.dons` deux fois — pour UNE seule commande vue. La somme des
    // rejets peut donc dépasser le nombre de commandes qu'ils sont censés expliquer.
    //
    // LA LEÇON : j'ai eu le bon réflexe (ajouter une auto-vérification) mais je n'ai pas
    // laissé le SIGNE de l'écart me guider vers la bonne cause — j'ai réparé le premier trou
    // que j'ai vu, pas celui que l'écart désignait. Un déséquilibre en TROP et un déséquilibre
    // en MOINS ne sont jamais la même maladie, même quand ils partagent une magnitude.
    //
    // LE CORRECTIF : chaque commande n'est comptée QU'UNE FOIS dans le journal, sur le PREMIER
    // motif qui s'applique — jamais une fois par ligne. C'est la seule granularité cohérente
    // avec `commandesVues`, qui compte des commandes depuis le début.
    if(!lignes || lignes.length === 0){ rejets.sansLigne++; return; }
    let _retenue = false;                                        // [v1347]
    let _rejetCommande = null;                                   // [v1349] premier motif rencontré, UNE fois
    (lignes || []).forEach(ln => {
      if(!ln) return;
      // 'grand' range ses parfums dans `items` — même sens, autre clé (dette historique).
      const src = (ln.type === 'grand') ? (ln.items || []) : (ln.parfums || []);
      const choisis = src.filter(p => p && p.nom && +p.qte > 0);

      // Un don (0 €) n'est pas un choix d'achat : le client n'a rien arbitré.
      const estDon = (+o.montant || 0) <= 0;
      // [v1349, corrigé] Le garde « une ligne déjà retenue suffit » ne doit couper QUE le
      // classement en motif de rejet — jamais l'accumulation de `sansParfum`, qui est un
      // TOTAL DE MACARONS sur TOUTES les lignes, indépendant du statut de la commande. Mon
      // premier correctif avait placé le `return` trop tôt et faisait disparaître les
      // macarons d'assortiment des lignes suivant une ligne déjà exploitable — un sous-
      // comptage NEUF, introduit en réparant le survomptage. Deux compteurs, deux granularités,
      // ne partagent jamais un seul `return`.
      if(estDon){ if(!_retenue && !_rejetCommande) _rejetCommande = 'dons'; return; }

      // ────────────────────────────────────────────────────────────────────────
      // [v1344 — DÉCISION DE BEN, GRAVÉE] LES COMMANDES NON PAYÉES SONT COMPTÉES,
      // ET **NE SONT PAS DISTINGUÉES** DES COMMANDES SOLDÉES.
      //
      // NE « CORRIGE » PAS CECI EN CROYANT ALIGNER LES ASSOCIATIONS SUR LA COMPTA.
      // Tout le reste de l'app raisonne en ENCAISSÉ (cash basis, v1331). Ici, non — et ce
      // n'est ni un oubli ni une incohérence : UN CHOIX DE PARFUM ET UN ENCAISSEMENT
      // MESURENT DEUX RÉALITÉS DIFFÉRENTES. Le client qui a composé « Café + Praliné » a
      // exprimé cette préférence, que sa facture soit réglée ou non. Filtrer sur le paiement
      // laisserait la COMPTABILITÉ corrompre une mesure COMPORTEMENTALE : on perdrait des
      // choix réels pour une raison qui n'a rien à voir avec le comportement mesuré.
      //
      // On ne l'affiche même pas comme une réserve à l'écran : signaler « attention, des
      // impayés sont inclus » laisserait croire que le chiffre est DÉGRADÉ par eux, alors
      // qu'il n'a simplement rien à voir avec eux. Une inquiétude injustifiée est aussi
      // trompeuse qu'un chiffre faux.
      //
      // RÈGLE GRAVÉE (v1344) : DEUX MESURES DE NATURES DIFFÉRENTES NE DOIVENT PAS S'ANNULER
      // L'UNE L'AUTRE. Aligner par réflexe de cohérence, c'est détruire l'une au nom de l'autre.
      // ────────────────────────────────────────────────────────────────────────

      // [v1349] `sansParfum` s'accumule INCONDITIONNELLEMENT, sur TOUTE ligne non-don — même
      // une ligne d'une commande déjà « retenue » par une autre ligne. C'est un TOTAL DE
      // MACARONS, pas un verdict par commande : il ne partage AUCUN garde avec `_retenue` /
      // `_rejetCommande`, qui eux ne comptent la commande qu'UNE fois.
      const nSansParfum = +ln.sansParfum || 0;
      if(nSansParfum > 0) rejets.sansParfum += nSansParfum;      // COMPTÉ, mais jamais utilisé

      if(_retenue) return;   // [v1349] le VERDICT de la commande est déjà « retenue » : rien de plus à décider

      if(choisis.length === 0){ if(!_rejetCommande) _rejetCommande = 'assortimentPur'; return; } // 100 % composé par Ben
      if(choisis.length === 1){ if(!_rejetCommande) _rejetCommande = 'monoParfum'; return; }     // rien à associer
      _rejetCommande = null;                                      // [v1349] une ligne exploitable efface tout rejet en attente

      _retenue = true;                                            // [v1347]
      paniers.push({
        orderId: o.id,
        date: o.date || '',
        clientId: o.clientId || null,
        parfums: choisis.map(p => ({ nom: p.nom, qte: +p.qte })),
        // On garde la trace de ce qu'on a IGNORÉ dans ce panier. Un panier « 3 choisis +
        // 5 assortiment » est un choix PARTIEL : le dire, c'est permettre de le pondérer.
        nSansParfum
      });
    });
    // [v1349] Une commande est comptée UNE FOIS : soit retenue (au moins une ligne exploitable),
    // soit sur le PREMIER motif de rejet rencontré parmi ses lignes. Jamais les deux, jamais
    // plusieurs fois — c'est ce qui garantit que rejets + retenues == vues, TOUJOURS.
    if(_retenue) rejets.commandesRetenues++;
    else if(_rejetCommande) rejets[_rejetCommande]++;
  });
  return { paniers, rejets };
}

// ---------------------------------------------------------------------------
// LA CO-OCCURRENCE. Pour chaque PAIRE de parfums, combien de paniers les contiennent
// tous les deux. On compte des PANIERS, jamais des PIÈCES : 10 caramel + 2 vanille dans
// un coffret, c'est UNE association, pas dix. Compter les pièces ferait exploser le score
// des parfums achetés en gros — et confondrait « souvent ensemble » avec « souvent beaucoup ».
//
// SEUIL DE SIGNIFICATIVITÉ. Avec ~9 mois d'historique, une paire vue 2 fois n'est pas une
// tendance : c'est un hasard. On EXIGE `minPaniers` (défaut 5) et on DIT combien de paniers
// soutiennent chaque chiffre. Un pourcentage sans son effectif est un mensonge poli :
// « 100 % des acheteurs de X prennent Y » sur 2 paniers, c'est du bruit présenté comme une loi.
// ---------------------------------------------------------------------------
function coOccurrenceParfums(paniers, opts){
  opts = opts || {};
  const minPaniers = (opts.minPaniers != null) ? +opts.minPaniers : 5;

  const nPaniers = (paniers || []).length;
  const compte = {};        // nom -> nb de paniers le contenant
  const paires = {};        // 'A||B' (trié) -> nb de paniers contenant les deux
  const clientsDe = {};     // 'A||B' -> Set des clients distincts  [v1346]

  (paniers || []).forEach(p => {
    const noms = [...new Set(p.parfums.map(x => x.nom))].sort();   // dédoublonné : un panier compte 1
    noms.forEach(n => { compte[n] = (compte[n] || 0) + 1; });
    for(let i = 0; i < noms.length; i++){
      for(let j = i + 1; j < noms.length; j++){
        const k = noms[i] + '||' + noms[j];
        paires[k] = (paires[k] || 0) + 1;
        // [v1346] COMBIEN DE CLIENTS DISTINCTS soutiennent cette paire ?
        // Le lift corrige la POPULARITÉ D'UN PARFUM, mais il est AVEUGLE à la CONCENTRATION
        // SUR UN CLIENT. Un acheteur unique qui répète 17 fois la même commande fabrique une
        // paire au lift écrasant — statistiquement irréfutable, et humainement vide de sens :
        // elle ne dit rien des GOÛTS, elle décrit une ROUTINE. C'est exactement ce que Ben a
        // repéré à l'œil nu sur son salon de thé, et que le moteur n'avait aucun moyen de voir.
        (clientsDe[k] ||= new Set()).add(p.clientId != null ? p.clientId : ('anon:' + p.orderId));
      }
    }
  });

  const rows = Object.keys(paires).map(k => {
    const [a, b] = k.split('||');
    const ab = paires[k];
    const na = compte[a] || 0, nb = compte[b] || 0;

    // Confiance CONDITIONNELLE, dans les DEUX SENS — elles ne sont PAS symétriques.
    // « 80 % des acheteurs de Café prennent du Caramel » ne dit rien de la réciproque si
    // le Caramel est acheté par tout le monde. Ne montrer qu'un sens, c'est laisser croire
    // à un lien qui n'est peut-être qu'une popularité.
    const confAB = na > 0 ? Math.round(ab / na * 1000) / 10 : null;   // P(B | A)
    const confBA = nb > 0 ? Math.round(ab / nb * 1000) / 10 : null;   // P(A | B)

    // LIFT — le seul chiffre qui distingue une VRAIE association d'une simple popularité.
    // lift = P(A et B) / (P(A) × P(B)).  > 1 : ils s'attirent.  ≈ 1 : indépendants (le lien
    // n'est qu'un effet de leur popularité respective).  < 1 : ils se repoussent.
    // SANS le lift, le parfum le plus vendu apparaît en tête de TOUTES les paires — et on
    // « découvre » qu'il se marie avec tout. C'est le piège classique du market basket, et
    // c'est exactement le genre de faux insight sur lequel Ben changerait sa gamme.
    const pA = nPaniers > 0 ? na / nPaniers : 0;
    const pB = nPaniers > 0 ? nb / nPaniers : 0;
    const pAB = nPaniers > 0 ? ab / nPaniers : 0;
    const lift = (pA > 0 && pB > 0) ? Math.round(pAB / (pA * pB) * 100) / 100 : null;

    const nClients = (clientsDe[k] ? clientsDe[k].size : 0);   // [v1346]
    return {
      a, b, paniers: ab, nA: na, nB: nb, confAB, confBA, lift, nClients,
      // [v1346] UNE PAIRE PORTÉE PAR UN SEUL CLIENT N'EST PAS UNE TENDANCE — c'est une habitude.
      // On ne la SUPPRIME pas (cacher le faible, c'est nier son existence — v1337) : on la
      // DÉCLASSE, et on dit pourquoi. Ben doit pouvoir la voir ET savoir qu'elle ne vaut rien
      // comme signal de gamme.
      monoClient: nClients <= 1,
      // Un chiffre sous le seuil n'est pas SUPPRIMÉ : il est MARQUÉ. Cacher les données
      // faibles, c'est laisser croire qu'elles n'existent pas (v1337 : l'incertitude se propage).
      significatif: ab >= minPaniers && nClients >= (opts.minClients != null ? +opts.minClients : 3)
    };
  });

  rows.sort((x, y) => (y.lift || 0) - (x.lift || 0) || y.paniers - x.paniers);
  return { rows, nPaniers, compte, minPaniers };
}

// ---------------------------------------------------------------------------
// LA COMPÉTENCE COPILOTE. « quels parfums vont ensemble », « co-occurrence », « associations ».
// ---------------------------------------------------------------------------
// ════════════════════════════════════════════════════════════════════════════
//  [v1350 — VAGUE 65] LE GÉNÉRATEUR DE COFFRETS
//
//  Ben : « je dois être capable de choisir un critère ou deux ou trois. Combinés ou séparés. »
//  Pas un algorithme qui décide à sa place — un OUTIL DE SCORING dont Ben choisit les poids.
//
//  TROIS CRITÈRES, TROIS SOURCES DÉJÀ MESURÉES — RIEN DE NOUVEAU N'EST INVENTÉ :
//   • ASSOCIATION : coOccurrenceParfums() (v1343-v1346) — lift + nombre de CLIENTS distincts.
//   • RENTABILITÉ : analyzeFlavorProfitability().rows — margeUnit, tauxMarge, RÉELS (coûts FIFO
//     actuels — même limite temporelle qu'ailleurs, jamais cachée).
//   • PRODUCTION : mesureParRec[recipeId].minParMac — temps RÉEL mesuré par macaron. Un parfum
//     'fiable:false' n'a PAS de mesure exploitable : il est exclu du critère PRODUCTION plutôt
//     que noté sur une estimation qu'on ferait passer pour une mesure (v1337).
//
//  CE QUE CE MODULE NE FAIT JAMAIS :
//   • Il ne crée AUCUN produit dans le catalogue de lui-même. Il propose ; Ben confirme.
//   • Il ne mélange pas des parfums dont l'association n'atteint pas le seuil de signifiance
//     (v1346 : minPaniers ET minClients) — sauf si Ben choisit EXPLICITEMENT de désactiver le
//     critère association (auquel cas la proposition est un ASSEMBLAGE, pas une « tendance »,
//     et le texte le dit).
// ════════════════════════════════════════════════════════════════════════════

// ---------------------------------------------------------------------------
// LE SCORE COMBINÉ. Chaque critère est normalisé sur [0,1] AVANT combinaison — sinon un lift
// de ×4 et une marge de 0,80 € ne sont pas comparables, et le critère à la plus grande échelle
// écraserait silencieusement les autres. Normaliser, c'est rendre les poids de Ben SIGNIFIANTS :
// sans ça, « 50 % association + 50 % rentabilité » ne voudrait rien dire de fiable.
// ---------------------------------------------------------------------------
function _normalise(valeurs){
  const v = valeurs.filter(x => x != null && isFinite(x));
  if(!v.length) return () => null;
  const min = Math.min(...v), max = Math.max(...v);
  if(max === min) return (x) => (x == null) ? null : 0.5;   // toutes égales : ex æquo, pas de biais
  return (x) => (x == null || !isFinite(x)) ? null : (x - min) / (max - min);
}

// ---------------------------------------------------------------------------
// GÉNÈRE DES PROPOSITIONS DE COFFRET à partir des paires d'association significatives (v1346),
// étendues à des groupes de `taille` parfums en cherchant, pour chaque paire de base, les
// parfums qui s'accordent le mieux avec LES DEUX déjà retenus (moyenne du lift aux deux membres).
// C'est un algorithme glouton — pas une recherche exhaustive : au-delà de 4-5 parfums, le nombre
// de combinaisons explose, et Ben ne demande pas l'optimum théorique, il demande une PISTE.
//
// `criteres` : { association: 0..1|null, rentabilite: 0..1|null, production: 0..1|null }
// Un critère à `null` est DÉSACTIVÉ (n'entre pas dans le score, et son absence est dite).
// Les poids fournis sont RENORMALISÉS pour sommer à 1 — Ben peut donner 2, 5, 100 : seul le
// RATIO entre eux compte, jamais leur échelle absolue.
// ---------------------------------------------------------------------------
function genererPropositionsCoffret(opts){
  opts = opts || {};
  const { coOccurrence, flavorRows, mesureParRec, taille } = opts;
  const criteresIn = opts.criteres || { association: 1, rentabilite: 1, production: 1 };
  const tailleCible = taille || 6;

  const actifs = Object.keys(criteresIn).filter(k => criteresIn[k] != null && +criteresIn[k] > 0);
  if(!actifs.length) return { propositions: [], erreur: 'Aucun critère actif : choisis au moins association, rentabilité ou production.' };
  const sommePoids = actifs.reduce((s,k) => s + (+criteresIn[k]), 0);
  const poids = {}; actifs.forEach(k => { poids[k] = (+criteresIn[k]) / sommePoids; });   // renormalisé à somme = 1

  // Paires SIGNIFICATIVES uniquement (v1346 : seuil paniers ET clients). Une paire en dessous
  // du seuil n'est pas une base fiable pour construire une offre — elle n'a même pas franchi
  // la barre de « ce n'est pas du hasard ».
  const paires = (coOccurrence && coOccurrence.rows || []).filter(r => r.significatif);
  if(actifs.includes('association') && !paires.length){
    return { propositions: [], erreur: 'Aucune association assez solide pour construire un coffret sur ce critère. Baisse le poids "association" ou attends plus de données.' };
  }

  // Index rentabilité et production par NOM de parfum (les deux sources utilisent le nom recette).
  const rentaByNom = {}; (flavorRows || []).forEach(r => { rentaByNom[r.nom] = r; });
  const prodByNom = {};
  (flavorRows || []).forEach(r => {
    const m = mesureParRec && r.recipeId != null ? mesureParRec[r.recipeId] : null;
    if(m && m.fiable && m.minParMac > 0) prodByNom[r.nom] = m.minParMac;   // sinon : PAS de valeur, jamais estimée
  });

  // Normalisateurs, un par critère, construits sur les valeurs RÉELLEMENT disponibles.
  const normLift = _normalise(paires.map(p => p.lift));
  const normMarge = _normalise(Object.values(rentaByNom).map(r => r.margeUnit).filter(x => x != null));
  // Production : MOINS de minutes = MIEUX. On inverse après normalisation (1 - x) pour que
  // le score aille dans le même sens que les deux autres (plus haut = plus désirable).
  const normTemps = _normalise(Object.values(prodByNom));

  // Score d'une PAIRE (a,b) : combine les critères actifs. Un critère dont l'un des deux
  // parfums n'a pas de donnée (ex. pas de mesure de temps fiable) ne s'applique PAS à cette
  // paire — le score se recalcule sur les critères restants plutôt que de pénaliser une absence
  // de mesure comme si c'était une mauvaise mesure (encore v1337 : l'absence n'est pas un zéro).
  function scorerPaire(p){
    const parts = {}; let poidsUtilise = 0, score = 0;
    if(poids.association != null && actifs.includes('association')){
      const s = normLift(p.lift);
      if(s != null){ parts.association = s; score += s * poids.association; poidsUtilise += poids.association; }
    }
    if(actifs.includes('rentabilite')){
      const ra = rentaByNom[p.a], rb = rentaByNom[p.b];
      const ma = ra ? normMarge(ra.margeUnit) : null, mb = rb ? normMarge(rb.margeUnit) : null;
      const vals = [ma, mb].filter(x => x != null);
      if(vals.length){ const s = vals.reduce((x,y)=>x+y,0) / vals.length;
        parts.rentabilite = s; score += s * poids.rentabilite; poidsUtilise += poids.rentabilite; }
    }
    if(actifs.includes('production')){
      const ta = prodByNom[p.a], tb = prodByNom[p.b];
      const na = ta != null ? normTemps(ta) : null, nb = tb != null ? normTemps(tb) : null;
      const vals = [na, nb].filter(x => x != null);
      if(vals.length){ const s = 1 - (vals.reduce((x,y)=>x+y,0) / vals.length);   // inversé : moins de temps = mieux
        parts.production = s; score += s * poids.production; poidsUtilise += poids.production; }
    }
    // Score RENORMALISÉ sur le poids effectivement utilisé — sinon une paire où seul un
    // critère sur trois a une donnée serait injustement défavorisée face à une paire complète.
    return { score: poidsUtilise > 0 ? score / poidsUtilise : 0, parts, couverture: poidsUtilise };
  }

  // On part de la meilleure paire, puis on ÉTEND gloutonnement jusqu'à `tailleCible` parfums,
  // en ajoutant à chaque étape le parfum qui maximise le score MOYEN avec le groupe déjà formé.
  const scored = paires.map(p => ({ ...p, ...scorerPaire(p) })).sort((x,y) => y.score - x.score);
  const propositions = [];
  const parfumsDejaUtilises = new Set();   // on évite qu'un même parfum domine toutes les propositions

  for(const base of scored){
    if(propositions.length >= 3) break;               // 3 pistes, pas 30 : Ben demande une piste, pas un rapport
    if(parfumsDejaUtilises.has(base.a) || parfumsDejaUtilises.has(base.b)) continue;

    let groupe = [base.a, base.b];
    let scoreGroupe = base.score;
    const detailCriteres = [base.parts];

    while(groupe.length < tailleCible){
      // Candidats : tout parfum lié à AU MOINS UN membre du groupe par une paire significative.
      const candidats = paires.filter(p =>
        (groupe.includes(p.a) && !groupe.includes(p.b)) || (groupe.includes(p.b) && !groupe.includes(p.a))
      );
      if(!candidats.length) break;   // aucune extension possible : le groupe reste tel quel

      let meilleur = null, meilleurScore = -1, meilleurParts = null;
      candidats.forEach(c => {
        const nouveau = groupe.includes(c.a) ? c.b : c.a;
        const s = scorerPaire(c);
        if(s.score > meilleurScore){ meilleurScore = s.score; meilleur = nouveau; meilleurParts = s.parts; }
      });
      if(meilleur == null) break;
      groupe.push(meilleur);
      scoreGroupe = (scoreGroupe * (groupe.length - 1) + meilleurScore) / groupe.length;   // moyenne courante
      detailCriteres.push(meilleurParts);
    }

    groupe.forEach(n => parfumsDejaUtilises.add(n));

    // Agrégats du groupe, pour l'affichage : marge totale estimée, temps total estimé, effectif
    // client minimal (le maillon le plus faible du groupe — une seule paire fragile fragilise tout).
    const margeTotale = groupe.reduce((s,n) => s + (rentaByNom[n] ? (rentaByNom[n].margeUnit||0) : 0), 0);
    const clientsMin = Math.min(...groupe.map(n => {
      const ps = paires.filter(p => p.a===n || p.b===n);
      return ps.length ? Math.max(...ps.map(p=>p.nClients)) : 0;
    }));

    propositions.push({
      parfums: groupe,
      score: Math.round(scoreGroupe * 100) / 100,
      margeUnitTotale: money2(margeTotale),
      clientsAppui: clientsMin,
      criteresUtilises: actifs,
      poids
    });
  }

  return { propositions, erreur: null };
}


// ---------------------------------------------------------------------------
// [v1350] LA COMPÉTENCE COPILOTE. « propose-moi un coffret », « génère un coffret rentable ».
// Ben choisit ses critères (association / rentabilité / production), seuls ou combinés.
// Produit une SUGGESTION à lire — la création réelle en produit catalogue passe par une
// CONFIRMATION explicite (aiConfirmerCreationCoffret), jamais automatique.
// ---------------------------------------------------------------------------
async function aiQueryGenererCoffret(params){
  params = params || {};
  const orders  = await db.orders.toArray();
  const clients = await db.clients.toArray().catch(()=>[]);
  const { paniers } = paniersClients(orders, { clients });
  if(!paniers.length){
    return aiSay(`${aiHero('—', 'Générateur de coffrets')}${aiSynth(`Je n'ai pas assez de paniers exploitables pour proposer un coffret fondé sur tes données. Vérifie d'abord « quels parfums vont ensemble » pour voir où ça bloque.`, {icon:'📭'})}`);
  }
  const co = coOccurrenceParfums(paniers, {});

  const recipes = await db.recipes.toArray();
  const recipeItems = await db.recipeItems.toArray();
  // [v1351] BUG TROUVÉ À LA RELECTURE, AVANT MÊME LE RETOUR DE BEN : `lots` doit venir de
  // `materialLots` (la table réelle des lots matière), pas d'une table `db.lots` qui n'existe
  // PAS dans le schéma (voir db.version(1).stores, ligne 300 : `materialLots`, jamais `lots`).
  // db.lots.toArray() aurait levé une exception Dexie — probablement LA cause de l'échec de Ben.
  const lots = await db.materialLots.toArray().catch(()=>[]);
  const mats = await db.materials.toArray().catch(()=>[]);
  const markets = await db.markets.toArray().catch(()=>[]);
  const marketMoves = await (db.marketMoves?db.marketMoves.toArray():Promise.resolve([])).catch(()=>[]);
  const productions = await db.productions.toArray().catch(()=>[]);
  const settings = getSettings();

  // [v1351] LE CRITÈRE PRODUCTION ÉTAIT STRUCTURELLEMENT MORT. `mesureParRec` était déclaré et
  // JAMAIS assigné — même si `analyzeFlavorProfitability` l'avait calculé en interne, je ne le
  // récupérais pas en sortie. Et je ne lui passais même pas `minParRecMesure` en entrée : la
  // vraie source est `prodTempsParParfum(90)`, utilisée ailleurs (renderRecipes) SEULEMENT
  // quand `settings.laborSource==='mesure'` est actif. Sans ce branchement, le critère
  // production ne pouvait produire AUCUNE donnée, quelle que soit la demande de Ben.
  let mesureMin = null, mesureParRec = null;
  if(settings.laborSource==='mesure' && settings.laborEnabled){
    try{ const tl = await prodTempsLissePerMacaron(90); if(tl && tl.fiable) mesureMin = tl.minParMacaron; }catch(e){ swallow(e,'aiQueryGenererCoffret tempsLisse'); }
    try{ mesureParRec = await prodTempsParParfum(90); }catch(e){ swallow(e,'aiQueryGenererCoffret tempsParParfum'); }
  }

  let flavorRows = [];
  try{
    const A = analyzeFlavorProfitability({recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions, settings, minParMacaronMesure:mesureMin, minParRecMesure:mesureParRec});
    flavorRows = A.rows || [];
  }catch(e){ swallow(e,'aiQueryGenererCoffret analyse'); }

  // [v1351] SI LE MODE MESURÉ N'EST PAS ACTIF : le critère production n'a structurellement
  // aucune donnée. Ce n'est pas une absence à cacher — Ben doit savoir POURQUOI, pas juste
  // constater que ses coffrets "production" sortent toujours vides ou identiques aux autres.
  const productionIndisponible = !(settings.laborSource==='mesure' && settings.laborEnabled);

  // [v1353] UN CRITÈRE PAR DÉFAUT N'EST PAS UN CRITÈRE DEMANDÉ. La distinction est capitale, et
  // son absence a produit le pire garde-fou possible : Ben tape « génère-moi un coffret » sans
  // préciser de critère → le code applique les trois par défaut → constate que « production » est
  // indisponible → et REFUSE TOUT. Je bloquais une génération parfaitement faisable sur deux
  // critères solides, à cause d'un troisième que Ben n'avait JAMAIS demandé.
  //
  // RÈGLE GRAVÉE (v1353) : UN GARDE-FOU NE DOIT JAMAIS PUNIR L'UTILISATEUR POUR UNE DÉCISION
  // QUE LE CODE A PRISE À SA PLACE. Le garde-fou était juste ; sa PORTÉE était fausse.
  const criteresExplicites = !!params.criteres;
  const criteres = params.criteres || { association:1, rentabilite:1, production:1 };
  const taille = params.taille || 6;

  // Si le critère production est indisponible ET qu'il vient du DÉFAUT (pas d'une demande de Ben),
  // on le retire silencieusement du calcul et on DÉGRADE GRACIEUSEMENT sur les deux autres — en
  // le DISANT ensuite, jamais en le cachant (v1347 : un filtre silencieux est un mensonge par omission).
  let productionRetiree = false;
  if(productionIndisponible && criteres.production != null && +criteres.production > 0){
    if(criteresExplicites){
      // Ben a EXPLICITEMENT demandé le critère production : là, refuser est la bonne réponse.
      // Générer en l'ignorant serait lui donner un résultat qui ne répond pas à sa question.
      return aiSay(`${aiHero('—', 'Générateur de coffrets')}${aiSynth(`Le critère <b>production</b> a besoin du mode « temps mesuré » (réglages → main-d'œuvre), qui n'est pas actif. Je ne peux pas le calculer sans lui — active-le, ou relance sans ce critère.`, {icon:'⚠️', tone:'warn'})}`);
    }
    // Sinon : il vient du défaut. On l'écarte et on continue avec ce qu'on a.
    criteres.production = null;
    productionRetiree = true;
  }

  const { propositions, erreur } = genererPropositionsCoffret({
    coOccurrence: co, flavorRows, mesureParRec, taille, criteres
  });

  if(erreur){
    return aiSay(`${aiHero('—', 'Générateur de coffrets')}${aiSynth(erreur, {icon:'⚠️', tone:'warn'})}`);
  }

  const _labelCriteres = { association:'associations mesurées', rentabilite:'rentabilité', production:'temps de production' };
  const actifsLabel = Object.keys(criteres).filter(k=>criteres[k]!=null && +criteres[k]>0).map(k=>_labelCriteres[k]||k).join(' + ');

  // [v1353] On DIT ce qu'on a retiré. Remplacer un blocage bruyant par une omission silencieuse
  // serait pire que le bug d'origine : Ben croirait que ses coffrets tiennent compte du temps de
  // production alors que non.
  const noteProduction = productionRetiree
    ? `${aiSynth(`Le critère <b>temps de production</b> n'a pas pu être pris en compte : il demande le mode « temps mesuré » (réglages → main-d'œuvre), qui n'est pas actif. Ces propositions reposent donc uniquement sur les <b>${esc(actifsLabel)}</b>.`, {icon:'ℹ️'})}`
    : '';

  const blocs = propositions.map((p,i) => {
    const idx = i+1;
    return `<div class="sum-box" style="flex-direction:column;align-items:flex-start;gap:4px">
      <div style="display:flex;justify-content:space-between;width:100%">
        <b>Coffret ${idx} — ${esc(p.parfums.join(' + '))}</b>
        <span style="color:#9a8a82;font-size:.78rem">score ${p.score}</span>
      </div>
      <span style="font-size:.82rem;color:#9a8a82">Marge estimée ${euro(p.margeUnitTotale)}/coffret · appuyé par ${p.clientsAppui} client(s) minimum</span>
      <button onclick="aiConfirmerCreationCoffret(${idx-1})" style="margin-top:4px;padding:6px 14px;border-radius:8px;background:var(--bordeaux);color:#fff;border:none;font-size:.82rem">Créer ce coffret dans le catalogue</button>
    </div>`;
  }).join('');

  window._propositionsCoffretEnCours = propositions;   // pour la confirmation

  return aiSay(`${aiHero(String(propositions.length), 'Proposition(s) de coffret', {sub:`basé sur ${actifsLabel}`, color:'var(--bordeaux)'})}
    ${aiSynth(`Calculé sur <b>${paniers.length} paniers</b> exploitables, uniquement des associations qui passent le seuil de signifiance (5 paniers, 3 clients).`, {icon:'🧺'})}
    ${noteProduction}
    ${blocs}
    ${aiSynth(`Rien n'est créé automatiquement. Touche <b>« Créer ce coffret »</b> pour l'ajouter au catalogue — je te demanderai confirmation une dernière fois.`, {icon:'🎯'})}`);
}

// [v1350] CONFIRMATION EXPLICITE avant toute création de produit. Ben a demandé « les deux,
// avec confirmation avant création » — ce n'est pas négociable : le générateur SUGGÈRE, il ne
// DÉCIDE jamais à la place de Ben.
async function aiConfirmerCreationCoffret(index){
  const props = window._propositionsCoffretEnCours || [];
  const p = props[index];
  if(!p) return aiSay(aiSynth(`Cette proposition n'est plus disponible — relance la génération.`, {icon:'⚠️'}));
  return aiSay(`${aiSynth(`Créer le coffret <b>${esc(p.parfums.join(' + '))}</b> dans ton catalogue (taille ${p.parfums.length >= 6 ? 6 : p.parfums.length}) ?`, {icon:'❓'})}
    <div style="display:flex;gap:8px;margin-top:8px">
      <button onclick="aiExecuterCreationCoffret(${index})" style="padding:8px 16px;border-radius:8px;background:var(--bordeaux);color:#fff;border:none">Oui, créer</button>
      <button onclick="aiSay(aiSynth('Annulé — rien n\'a été créé.', {icon:'✔️'}))" style="padding:8px 16px;border-radius:8px;background:#eee;border:none">Annuler</button>
    </div>`);
}

async function aiExecuterCreationCoffret(index){
  const props = window._propositionsCoffretEnCours || [];
  const p = props[index];
  if(!p) return aiSay(aiSynth(`Cette proposition n'est plus disponible.`, {icon:'⚠️'}));
  try{
    const taille = p.parfums.length >= 6 ? 6 : p.parfums.length;
    await db.products.add({ taille, prix: BOX_PRICES && BOX_PRICES[taille] || 0, actif:true,
      nomSuggere: p.parfums.join(' + '), origineCoffretGenere: true });
    return aiSay(aiSynth(`Coffret <b>${esc(p.parfums.join(' + '))}</b> créé dans ton catalogue.`, {icon:'✅'}));
  }catch(e){
    swallow(e,'aiExecuterCreationCoffret');
    return aiSay(aiSynth(`La création a échoué — rien n'a été ajouté.`, {icon:'⚠️'}));
  }
}

async function aiQueryAssociations(params){
  params = params || {};
  const orders  = await db.orders.toArray();
  const clients = await db.clients.toArray().catch(()=>[]);       // [v1346] pour exclure les pros
  const { paniers, rejets } = paniersClients(orders, { clients });

  // AVANT TOUT CHIFFRE : ai-je de quoi parler ? La v1337 a gravé que l'absence de mesure
  // n'est pas un zéro. Ici, l'absence de paniers n'est pas « aucune affinité » : c'est
  // « je ne sais pas ». Le dire AVANT, pas en note de bas de page.
  if(paniers.length === 0){
    // [v1347] Le cas « zéro panier » est CELUI où l'explication compte le plus. Répondre « je n'ai
    // rien » sans dire ce qui a été jeté, c'est laisser Ben croire que ses clients ne choisissent
    // pas — alors que c'est peut-être un FILTRE qui les mange.
    const _z = [];
    if(rejets.pro>0)            _z.push(`<b>${rejets.pro}</b> commande(s) d'un client pro`);
    if(rejets.monoParfum>0)     _z.push(`<b>${rejets.monoParfum}</b> ligne(s) à un seul parfum`);
    if(rejets.assortimentPur>0) _z.push(`<b>${rejets.assortimentPur}</b> ligne(s) en assortiment complet (tes choix)`);
    if(rejets.dons>0)           _z.push(`<b>${rejets.dons}</b> ligne(s) à 0 €`);
    if(rejets.histo>0)          _z.push(`<b>${rejets.histo}</b> reprise(s) d'historique`);
    if(rejets.sansLigne>0)      _z.push(`<b>${rejets.sansLigne}</b> commande(s) sans format reconnu`);   // [v1348]
    return aiSay(`${aiHero('—', 'Associations de parfums')}
      ${aiSynth(`Je n'ai <b>aucun panier exploitable</b> sur tes <b>${rejets.commandesVues}</b> commandes. Une association a besoin d'une commande où <b>le client</b> a choisi <b>au moins deux</b> parfums.${_z.length?`<br><br>Ce qui a été écarté :<br>· ${_z.join('<br>· ')}`:''}`, {icon:'📭'})}`);
  }

  const { rows, nPaniers, minPaniers } = coOccurrenceParfums(paniers, { minPaniers: params.minPaniers });
  const forts = rows.filter(r => r.significatif && r.lift != null && r.lift > 1.2);

  // L'HONNÊTETÉ STATISTIQUE EN TÊTE, PAS EN BAS DE PAGE. Avec ~9 mois d'historique, l'effectif
  // est le chiffre le PLUS important de l'écran — plus que n'importe quel pourcentage. Un
  // « 68 % » sur 4 paniers a l'air d'une loi et n'est qu'un hasard. Ben doit voir COMBIEN de
  // paniers soutiennent ce qu'il lit AVANT de lire quoi que ce soit.
  // [v1347] LE JOURNAL DES EXCLUSIONS. Ben : « j'ai 110 commandes, le calcul se fait sur 63.
  // Pourquoi ? » L'app COMPTAIT déjà ses rejets — elle ne les MONTRAIT pas. Un filtre silencieux
  // est un mensonge par omission : Ben ne pouvait pas savoir si son chiffre reposait sur ses
  // données ou sur un tiers d'entre elles. On détaille donc, ligne par ligne, ce qui n'entre pas.
  const _ecart = Math.max(0, (rejets.commandesVues||0) - (rejets.commandesRetenues||0));
  const _l = [];
  if(rejets.pro>0)            _l.push(`<b>${rejets.pro}</b> commande(s) d'un <b>client pro</b> — sa routine n'est pas une tendance`);
  if(rejets.monoParfum>0)     _l.push(`<b>${rejets.monoParfum}</b> ligne(s) à <b>un seul parfum</b> — il faut être deux pour s'associer`);
  if(rejets.assortimentPur>0) _l.push(`<b>${rejets.assortimentPur}</b> ligne(s) en <b>assortiment complet</b> — c'est toi qui composes`);
  if(rejets.dons>0)           _l.push(`<b>${rejets.dons}</b> ligne(s) à <b>0 €</b> — un don n'est pas un choix d'achat`);
  if(rejets.histo>0)          _l.push(`<b>${rejets.histo}</b> <b>reprise(s) d'historique</b> — données d'avant l'app`);
  if(rejets.sansLigne>0)      _l.push(`<b>${rejets.sansLigne}</b> commande(s) <b>sans format reconnu</b> — ni coffret, ni grand format, ni événement : je ne sais pas les lire`);   // [v1348]

  // [v1348] AUTO-VÉRIFICATION. Le premier journal (v1347) affichait un total qui NE TOMBAIT PAS
  // JUSTE (85 rejets + 48 retenues = 133 pour 128 vues) sans jamais s'en apercevoir lui-même —
  // Ben l'a vu, pas le code. Un journal cense garantir l'exhaustivité doit vérifier sa PROPRE
  // arithmétique, sinon il peut mentir avec la même assurance que le chiffre qu'il corrigeait.
  const _sommeRejets = (rejets.pro||0)+(rejets.monoParfum||0)+(rejets.assortimentPur||0)+(rejets.dons||0)+(rejets.histo||0)+(rejets.sansLigne||0);
  const _controle = (_sommeRejets + rejets.commandesRetenues) === rejets.commandesVues;
  const _alerteIncoherence = !_controle ? `${aiSynth(`⚠️ Mon propre décompte ne tombe pas juste (${rejets.commandesRetenues} retenues + ${_sommeRejets} écartées ≠ ${rejets.commandesVues} vues). Ne fais <b>pas confiance</b> à ce journal tant que je n'ai pas trouvé l'écart — préviens-moi.`, {icon:'🐞', tone:'warn'})}` : '';

  const journal = (_ecart>0 || _alerteIncoherence) ? `${aiSynth(`<b>${rejets.commandesRetenues} de tes ${rejets.commandesVues} commandes</b> entrent dans ce calcul. Voici <b>précisément</b> pourquoi les autres n'y sont pas :<br>· ${_l.join('<br>· ')}<br><br>Si ce total te surprend, dis-le-moi : c'est <b>le filtre</b> qu'il faut corriger, pas le chiffre.`, {icon:'🔍'})}${_alerteIncoherence}` : '';

  const socle = `${aiSynth(`Calculé sur <b>${nPaniers} panier(s)</b> où <b>le client</b> a choisi au moins deux parfums lui-même.${rejets.sansParfum>0?` Les <b>${rejets.sansParfum} macarons d'assortiment</b> que <b>tu</b> composes en sont <b>exclus</b> : ce sont tes choix, pas les leurs.`:''}`, {icon:'🧺'})}${journal}`;

  if(!forts.length){
    return aiSay(`${aiHero(String(nPaniers), 'Paniers analysés')}${socle}
      ${aiSynth(`<b>Aucune association ne se détache</b> pour l'instant. Ce n'est pas « tes clients n'associent rien » : c'est que rien ne dépasse encore le seuil de ${minPaniers} paniers. Avec ${nPaniers} panier(s), une paire vue 2 ou 3 fois reste du <b>hasard</b>. Je préfère te le dire que de te vendre du bruit comme une tendance.`, {icon:'⏳'})}`);
  }

  const li = forts.slice(0, 6).map(r => {
    // On affiche la confiance dans le SENS LE PLUS FORT, mais on donne toujours l'effectif :
    // un pourcentage sans son dénominateur est un mensonge poli.
    const sensAB = (r.confAB || 0) >= (r.confBA || 0);
    const [x, y] = sensAB ? [r.a, r.b] : [r.b, r.a];
    const conf = sensAB ? r.confAB : r.confBA;
    const nX = sensAB ? r.nA : r.nB;
    return `<div class="sum-box"><span><b>${esc(x)}</b> + <b>${esc(y)}</b><br>
      <span style="font-size:.76rem;color:#9a8a82">${conf}% de ceux qui prennent ${esc(x)} prennent aussi ${esc(y)} — sur ${nX} panier(s), <b>${r.nClients} client(s)</b></span></span>
      <b>×${r.lift}</b></div>`;
  }).join('');

  return aiSay(`${aiHero(String(forts.length), 'Association(s) qui se détachent', {sub:`sur ${nPaniers} paniers`, color:'var(--bordeaux)'})}
    ${socle}
    ${li}
    ${aiSynth(`Le <b>×</b> est le <b>lift</b> : au-delà de 1, les deux parfums s'attirent <b>vraiment</b>. À 1, ils sont simplement <b>populaires chacun de leur côté</b>.<br><br>Le <b>nombre de clients</b> compte autant : une paire vue 17 fois mais chez <b>un seul</b> client n'est pas une tendance, c'est <b>son habitude</b>. Je ne retiens que celles portées par <b>au moins 3 clients différents</b>.`, {icon:'🎯'})}`);
}


// ════════════════════════════════════════════════════════════════════════════
//  [v1354] LE TABLEAU DE BORD PAR PARFUM — ce qui manquait pour composer la gamme
//
//  Ben : « L'outil ne semble pas donner toutes les tendances par parfums. À côté des
//  associations j'ai besoin de savoir ce qui se vend le mieux pour composer au mieux ma
//  nouvelle offre. Oublie pas que j'ai 15 parfums en standard. »
//
//  IL A RAISON, ET C'EST UN MANQUE GRAVE. Je lui donnais des ASSOCIATIONS sans jamais lui dire
//  QUELS PARFUMS SE VENDENT. Un parfum peut avoir un lift magnifique et ne quasiment jamais
//  partir : le mettre en gamme sur cette seule base serait une erreur commerciale.
//
//  PIRE : toutes ces données EXISTAIENT DÉJÀ (`analyzeFlavorProfitability` calcule piecesVendues,
//  ca, margeUnit, tauxMarge par parfum). Le générateur les utilisait EN INTERNE pour scorer — sans
//  jamais les MONTRER à Ben. Il devait faire confiance à un score de 0.38 sans voir ce qu'il y avait
//  derrière.
//
//  RÈGLE GRAVÉE (v1354) : UN SCORE QU'ON NE PEUT PAS DÉCOMPOSER EST UN SCORE QU'ON NE PEUT PAS
//  CONTESTER. Montrer les composantes n'est pas un luxe d'affichage — c'est ce qui permet à Ben
//  de voir que je me trompe (comme il l'a fait pour Coco Rafaello en "Fraîcheur").
//
//  ET : `aiQueryTopParfum` tronquait à 10. Ben a 15 parfums. Une gamme se compose sur TOUS ses
//  parfums, pas sur les 10 premiers — les 5 derniers sont précisément ceux qu'il faut décider de
//  garder ou de sortir.
// ════════════════════════════════════════════════════════════════════════════

async function aiQueryTendancesParfums(params){
  params = params || {};

  const orders  = await db.orders.toArray();
  const clients = await db.clients.toArray().catch(()=>[]);

  // ── 1. VOLUME : combien de pièces vendues par parfum (tous canaux)
  // [v1355] BUG : `computeStats` retourne `{global, parClient, nbValides}` — les volumes par parfum
  // sont dans `R.global.parfums`, PAS dans `R.parfums`. J'ai lu la mauvaise clé : `volumes` était
  // TOUJOURS un objet vide, donc TOUS les parfums tombaient à 0 pièce et atterrissaient dans
  // « JAMAIS VENDUS ». Ben avait 128 commandes sous les yeux et l'app lui affichait 0.
  //
  // Ce qui rend l'erreur pernicieuse : la marge et les associations s'affichaient CORRECTEMENT
  // (elles viennent d'autres sources). Seul le volume était faux — un tableau à moitié juste est
  // plus dangereux qu'un tableau vide : il inspire confiance.
  //
  // [v1355] Et un SECOND bug, plus grave : computeStats filtre `o.paiement==='Payé'`. Or Ben a
  // tranché en v1344 : « ce sont deux notions bien distinctes qui ne doivent pas s'annuler l'une
  // l'autre ». Un macaron VENDU est un macaron vendu, réglé ou non — le volume mesure ce qui SORT,
  // pas ce qui RENTRE. On recompte donc les volumes NOUS-MÊMES, sur les mêmes commandes que les
  // associations, pour que les deux colonnes du tableau parlent du MÊME périmètre.
  const volumes = {};
  (orders || []).forEach(o => {
    if(!o || o.histo) return;
    (orderToLines(o) || []).forEach(ln => {
      if(!ln) return;
      const src = (ln.type === 'grand') ? (ln.items || []) : (ln.parfums || []);
      src.forEach(p => { if(p && p.nom && +p.qte > 0) volumes[p.nom] = (volumes[p.nom] || 0) + (+p.qte); });
    });
  });

  // ── 2. RENTABILITÉ : marge unitaire et taux, par parfum
  const recipes      = await db.recipes.toArray();
  const recipeItems  = await db.recipeItems.toArray();
  const lots         = await db.materialLots.toArray().catch(()=>[]);
  const mats         = await db.materials.toArray().catch(()=>[]);
  const markets      = await db.markets.toArray().catch(()=>[]);
  const marketMoves  = await db.marketMoves.toArray().catch(()=>[]);
  const productions  = await db.productions.toArray().catch(()=>[]);
  const settings     = getSettings();

  let flavorRows = [];
  try{
    const A = analyzeFlavorProfitability({recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions, settings});
    flavorRows = A.rows || [];
  }catch(e){ swallow(e,'aiQueryTendancesParfums analyse'); }
  const renta = {}; flavorRows.forEach(r => { renta[r.nom] = r; });

  // ── 3. ASSOCIATIONS : le meilleur partenaire de chaque parfum (significatif uniquement)
  const { paniers } = paniersClients(orders, { clients });
  const co = coOccurrenceParfums(paniers, {});
  const meilleurPartenaire = {};
  (co.rows || []).filter(r => r.significatif).forEach(r => {
    [[r.a, r.b], [r.b, r.a]].forEach(([x, y]) => {
      if(!meilleurPartenaire[x] || r.lift > meilleurPartenaire[x].lift){
        meilleurPartenaire[x] = { avec: y, lift: r.lift, nClients: r.nClients };
      }
    });
  });

  // ── 4. TOUS les parfums du catalogue — y compris ceux à ZÉRO vente.
  // Un parfum qui ne se vend PAS est une information de gamme aussi importante qu'un best-seller :
  // c'est un candidat à la sortie. L'omettre du tableau reviendrait à le cacher (v1337 : l'absence
  // de mesure n'est pas l'absence de fait).
  const tous = (typeof FLAVORS !== 'undefined' && FLAVORS.length) ? FLAVORS.slice() : Object.keys(volumes);

  const lignes = tous.map(nom => {
    const vol = +volumes[nom] || 0;
    const r   = renta[nom] || null;
    const mp  = meilleurPartenaire[nom] || null;
    return {
      nom,
      volume: vol,
      ca:        r && r.ca != null ? r.ca : null,
      margeUnit: r && r.margeUnit != null ? r.margeUnit : null,
      tauxMarge: r && r.tauxMarge != null ? r.tauxMarge : null,
      partenaire: mp
    };
  });

  const totalVol = lignes.reduce((s,l) => s + l.volume, 0);

  // Tri par VOLUME décroissant : Ben compose sa gamme, il veut voir ses locomotives en premier.
  lignes.sort((a,b) => b.volume - a.volume);

  // Médianes, pour situer chaque parfum (au-dessus / en-dessous) sans jargon statistique.
  const volsNonNuls   = lignes.map(l=>l.volume).filter(v=>v>0).sort((a,b)=>a-b);
  const margesNonNull = lignes.map(l=>l.margeUnit).filter(m=>m!=null).sort((a,b)=>a-b);
  const medVol   = volsNonNuls.length   ? volsNonNuls[Math.floor(volsNonNuls.length/2)] : 0;
  const medMarge = margesNonNull.length ? margesNonNull[Math.floor(margesNonNull.length/2)] : 0;

  // ── 5. LES QUATRE QUADRANTS (volume × marge) — le vrai outil de décision de gamme.
  // Ce n'est PAS une matrice BCG plaquée : c'est la seule façon de voir qu'un parfum qui se vend
  // beaucoup peut te faire perdre de l'argent, et qu'un parfum discret peut être ta meilleure marge.
  // [v1356] UNE MARGE INCONNUE N'EST PAS UNE MAUVAISE MARGE.
  //
  // Le bug : `(l.margeUnit != null) && (l.margeUnit >= medMarge)` renvoyait `false` sur un `null`.
  // Praliné noisettes (96 pces) et Chocolat noir (94 pces) atterrissaient donc dans « À QUESTIONNER
  // — faible volume ET faible marge », avec une marge affichée « — ». Ben aurait pu SORTIR DE SA
  // GAMME deux parfums qui vendent près de 100 pièces, sur la foi d'une marge qu'on n'a jamais mesurée.
  //
  // C'est EXACTEMENT le péché gravé en v1337 (« zéro n'est pas une mesure, c'est une affirmation »),
  // que je viens de commettre à nouveau, 19 vagues plus tard. Un `null` traité comme un `false` est
  // un jugement déguisé en donnée.
  //
  // POURQUOI ces marges sont nulles : `analyzeFlavorProfitability` calcule `margeUnit` à partir de
  // `piecesVendues`, qui filtre `paiement === 'Payé'`. J'ai contourné ce filtre pour MES volumes en
  // v1355 (décision de Ben, v1344 : payé et non payé sont deux notions distinctes) — mais PAS dans
  // le moteur de rentabilité. Ces deux parfums ont donc 96 et 94 pièces SORTIES, et 0 pièce PAYÉE.
  //
  // Ce ne sont pas des parfums sans marge : ce sont des parfums dont les commandes ne sont pas
  // encore réglées. La donnée manque, et on le DIT — on ne la remplace pas par un verdict.
  const quadrant = (l) => {
    if(l.volume === 0)      return 'dormant';
    if(l.margeUnit == null) return 'marge_inconnue';   // [v1356] jamais 'poids_mort' par défaut
    const hautVol    = l.volume   >= medVol;
    const hauteMarge = l.margeUnit >= medMarge;
    if(hautVol && hauteMarge)   return 'pilier';
    if(hautVol && !hauteMarge)  return 'locomotive';
    if(!hautVol && hauteMarge)  return 'pepite';
    return 'poids_mort';
  };
  lignes.forEach(l => { l.quadrant = quadrant(l); });

  // [v1356] LE VOCABULAIRE, PAS LA MATHS. La médiane de Ben est à 125 pièces — Popcorn (101 pces)
  // tombe donc SOUS la médiane, et le calcul est juste. Mais lui dire « faible volume » pour
  // 101 pièces vendues est TROMPEUR : ce n'est pas faible dans l'absolu, c'est « en dessous de la
  // moitié de ta gamme ». Un seuil relatif décrit une POSITION, jamais une VALEUR — et confondre
  // les deux ferait sortir de la gamme des parfums qui vendent une centaine de pièces.
  const LIB = {
    pilier:     { t:'PILIERS',      d:`au-dessus de la médiane sur les DEUX axes (${qty(medVol)} pces / ${euro(medMarge)}) — le cœur de ta gamme` },
    locomotive: { t:'LOCOMOTIVES',  d:'gros volume, marge sous la médiane — ils attirent, ils enrichissent moins' },
    pepite:     { t:'PÉPITES',      d:'volume sous la médiane, marge au-dessus — à pousser' },
    poids_mort: { t:'SOUS LA MÉDIANE SUR LES DEUX AXES', d:'ni le volume ni la marge ne dépassent la moitié de ta gamme — à questionner, pas à condamner' },
    dormant:    { t:'JAMAIS VENDUS',d:'aucune vente enregistrée' },
    marge_inconnue: { t:'MARGE NON MESURÉE', d:'ils se vendent, mais aucune commande réglée : impossible de calculer leur marge' }
  };

  const ligneHtml = (l) => {
    const pct = totalVol > 0 ? Math.round(l.volume / totalVol * 1000)/10 : 0;
    const asso = l.partenaire
      ? `<span style="color:#9a8a82">↔ ${esc(l.partenaire.avec)} <b>×${l.partenaire.lift}</b></span>`
      : `<span style="color:#c4b8b0">aucune association mesurée</span>`;
    const marge = l.margeUnit != null ? `${euro(l.margeUnit)}/pce` : '<span style="color:#c4b8b0">—</span>';
    return `<div class="sum-box" style="flex-direction:column;align-items:flex-start;gap:2px;padding:8px 10px">
      <div style="display:flex;justify-content:space-between;width:100%">
        <b>${esc(l.nom)}</b>
        <span><b>${qty(l.volume)}</b> <span style="color:#9a8a82;font-size:.78rem">pces · ${pct}%</span></span>
      </div>
      <div style="font-size:.78rem;display:flex;justify-content:space-between;width:100%">
        <span>marge ${marge}</span>
        ${asso}
      </div>
    </div>`;
  };

  const blocs = ['pilier','locomotive','pepite','marge_inconnue','poids_mort','dormant'].map(q => {
    const grp = lignes.filter(l => l.quadrant === q);
    if(!grp.length) return '';
    return `<p style="margin:12px 0 4px;font-weight:700;font-size:.82rem;letter-spacing:.04em">${LIB[q].t}
      <span style="font-weight:400;color:#9a8a82">— ${LIB[q].d}</span></p>
      ${grp.map(ligneHtml).join('')}`;
  }).join('');

  return aiSay(`${aiHero(String(lignes.length), 'Parfums au catalogue', {sub:`${qty(totalVol)} pièces vendues au total`, color:'var(--bordeaux)'})}
    ${aiSynth(`Chaque parfum, classé par <b>volume</b>, avec sa <b>marge</b> et sa <b>meilleure association</b> mesurée. Les seuils « fort/faible » sont les <b>médianes</b> de ta propre gamme — pas des valeurs absolues.`, {icon:'📊'})}
    ${blocs}
    ${aiSynth(`Les seuils sont <b>relatifs à ta gamme</b> : la médiane est à <b>${qty(medVol)} pièces</b> et <b>${euro(medMarge)}/pce</b>. « Sous la médiane » ne veut pas dire « mauvais » — Popcorn à 101 pièces reste un vrai volume, il est juste dans la moitié basse <b>de tes propres parfums</b>.<br><br>Un parfum à <b>fort lift</b> mais <b>petit volume</b> reste un pari : l'association est réelle, elle repose sur peu de ventes.`, {icon:'🎯'})}`);
}


async function aiQueryTopParfum(params){
  const periode = (params && params.periode) || {depuis:null, label:'sur tout ton historique'};
  let orders = await db.orders.toArray();
  const clients = await db.clients.toArray();
  // [FIX v1335] La borne HAUTE était ignorée : le filtre n'avait qu'un « depuis ». Avec un mois
  // nommé (« en mai »), l'app aurait donc renvoyé mai + juin + juillet — un chiffre juste pour une
  // période que Benjamin n'a jamais demandée.
  if(periode.depuis){ orders = orders.filter(o=> (o.date||'') >= periode.depuis); }
  if(periode.jusqu){  orders = orders.filter(o=> (o.date||'').slice(0,10) <= periode.jusqu); }
  const R = computeStats(orders, clients, orderToLines);
  const rank = Object.keys(R.parfums||{})
    .map(nom=>({nom, n:R.parfums[nom]}))
    .filter(x=>x.n>0).sort((a,b)=>b.n-a.n).slice(0,10);
  if(!rank.length){
    return aiSay(`${aiHero('—', 'Parfum le plus vendu')}${aiSynth(`Aucune vente enregistrée ${esc(periode.label)}.`, {icon:'📭'})}`);
  }
  const top = rank[0];
  const total = rank.reduce((s,x)=>s+x.n,0);
  const pct = total>0 ? Math.round(top.n/total*100) : 0;
  aiSay(`${aiHero(esc(top.nom), 'Ton parfum nº 1', {color:'var(--caramel)', sub:`${qty(top.n)} macarons · ${pct}% du top 10`})}
    ${aiSynth(`En tête ${esc(periode.label)}${rank[1]?`, devant <b>${esc(rank[1].nom)}</b>`:''}.`, {icon:'🏆'})}
    ${aiDetails(rank.map((x,i)=>`<div class="sum-box"><span>${i+1}. <b>${esc(x.nom)}</b></span><b>${qty(x.n)} mac.</b></div>`).join(''), 'Voir le classement complet')}
    ${aiSuite([{label:'📈 Et le plus rentable ?', ask:'quel parfum est le plus rentable'}])}`);
}
// [COCKPIT] RECETTE (éventuellement mise à l'échelle) : « la recette des macarons citron pour 25 pièces ».
// Lit la recette du parfum + ses ingrédients (recipeItems), met à l'échelle au prorata du rendement.
// Ne modifie rien : lecture + règle de trois.
// [V937] QUANTITÉ D'UN INGRÉDIENT POUR N PIÈCES D'UN PARFUM. Réutilise EXACTEMENT le calcul de mise à
// l'échelle de la recette (recipeItems × pieces/rendement), filtré sur l'ingrédient demandé. Source unique.
// [V938] Helper : retrouve la recette d'un parfum (par nom normalisé).
async function _aiRecetteParfum(flavor){
  const recipes = await db.recipes.toArray();
  const n=(s)=>(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  return recipes.find(r=>n(r.produitNom)===n(flavor))
      || recipes.find(r=>n(r.produitNom).includes(n(flavor)) || n(flavor).includes(n(r.produitNom))) || null;
}

// [V938] TEMPS DE PRODUCTION (estimation du montage) pour N macarons d'un parfum, ou pour une commande.
// [V939] Calcule le temps de production COMPLET et détaillé par étape pour un volume de macarons.
// Réutilise le vrai modèle de durées de l'app (getMrpTimes + _dureesLignePlan) : coques (par meringue),
// ganache (1×/parfum), montage (fixe+variable/batch), vaisselle (/batch), entretien (1×/session).
async function _aiTempsProdDetail(nMac, parfum){
  const TB  = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const MM  = (typeof MACARONS_PAR_MERINGUE!=='undefined') ? MACARONS_PAR_MERINGUE : 120;
  const times = (typeof getMrpTimes==='function') ? getMrpTimes() : {coques:{estimatedTime:35},montage:{estimatedTime:15},ganache:{estimatedTime:12},vaisselle:{estimatedTime:10},entretien:{estimatedTime:15}};
  const n = Math.max(0, Math.round(+nMac||0));
  const nbBatchs    = Math.max(1, Math.ceil(n/TB));
  const nbMeringues = Math.max(1, Math.ceil(n/MM));
  // Recette du parfum (pour des durées spécifiques mesurées/saisies si dispo).
  let rec=null;
  try{ const recipes=await db.recipes.toArray(); rec=(typeof mrpFindRecipe==='function')?mrpFindRecipe(recipes,parfum):null; }catch(e){swallow(e,'_aiTempsProdDetail')}
  let tEtape=null; try{ tEtape=await prodTempsParEtapeParParfum(90); }catch(e){swallow(e,'_aiTempsProdDetail')}
  // Montage + ganache via le modèle officiel.
  let tMontage, tGanache;
  try{ const d=_dureesLignePlan(parfum, n, nbBatchs, rec, times, tEtape); tMontage=d.tMontage; tGanache=d.tGanache; }
  catch(_){ tMontage=(typeof _montageMinutes==='function')?_montageMinutes(n,null,'défaut'):nbBatchs*15; tGanache=times.ganache.estimatedTime; }
  const tCoques    = nbMeringues * (times.coques.estimatedTime||35);
  const tVaisselle = nbBatchs    * (times.vaisselle.estimatedTime||10);
  const tEntretien = (times.entretien.estimatedTime||15);     // une session
  const total = Math.round(tCoques + tGanache + tMontage + tVaisselle + tEntretien);
  return { n, nbBatchs, nbMeringues, tCoques, tGanache, tMontage, tVaisselle, tEntretien, total,
           etapes:[
             {nom:'Coques (meringue + pochage + cuisson)', min:tCoques, detail:`${nbMeringues} meringue${nbMeringues>1?'s':''}`},
             {nom:'Ganache', min:tGanache, detail:'une préparation'},
             {nom:'Montage (assemblage)', min:tMontage, detail:`${nbBatchs} fournée${nbBatchs>1?'s':''}`},
             {nom:'Vaisselle / nettoyage poste', min:tVaisselle, detail:''},
             {nom:'Mise en place / entretien', min:tEntretien, detail:'une session'}
           ] };
}
function _aiFmtDuree(min){ min=Math.round(min); if(min<60) return `${min} min`; const h=Math.floor(min/60), m=min%60; return m?`${h} h ${m} min`:`${h} h`; }

// [V938→V939] TEMPS DE PRODUCTION COMPLET (toutes étapes) pour N macarons d'un parfum, ou une commande.
async function aiQueryTempsProd(params){
  params=params||{};
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  // Cas commande d'un client : somme des macarons de sa dernière commande, tous parfums.
  if(params.client){
    const orders=await db.orders.toArray();
    const cmds=orders.filter(o=>o.clientId===params.client.id && o.date).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
    if(!cmds.length) return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Temps de production — ${esc(params.client.nom||'')}</h3><p class="note">Aucune commande pour ce client.</p>`);
    const last=cmds[0];
    // Regroupe par parfum pour un calcul correct (ganache 1×/parfum).
    const parParfum={};
    (orderToLines(last)||[]).forEach(ln=>{ const p=ln.parfums||ln.items||{}; Object.entries(p).forEach(([nom,q])=>{ parParfum[nom]=(parParfum[nom]||0)+(+q||0); }); });
    const noms=Object.keys(parParfum); const totMac=Object.values(parParfum).reduce((s,q)=>s+q,0);
    if(!totMac) return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Temps de production — commande ${esc(params.client.nom||'')}</h3><p class="note">Je n'arrive pas à compter les macarons de cette commande.</p>`);
    let total=0; const blocs=[];
    for(const nom of noms){ const d=await _aiTempsProdDetail(parParfum[nom], nom); total+=d.total;
      blocs.push(`<div class="sum-box"><span>${esc(nom)} <span style="color:#9a8a82;font-size:.74rem">(${qty(parParfum[nom])} pc)</span></span><b>${_aiFmtDuree(d.total)}</b></div>`); }
    return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Temps de production — commande ${esc(params.client.nom||'')}</h3>
      ${aiHero(_aiFmtDuree(total), 'Temps total estimé', {sub:`${qty(totMac)} macarons · ${noms.length} parfum${noms.length>1?'s':''}`})}
      ${aiDetails(blocs.join(''), 'Détail par parfum')}
      <p class="note">Temps de travail estimé (toutes étapes). Le repos de la ganache (12 h) et la maturation s'ajoutent en temps d'attente, pas de travail.</p>`);
  }
  // [v1061] Temps GÉNÉRIQUE d'un batch (aucun parfum/client précisé) : estimation moyenne sur un
  // batch standard, en s'appuyant sur le détail d'étapes du moteur. Invite à préciser un parfum.
  if(params.generique){
    const d = await _aiTempsProdDetail(TB, null);
    const lignes = (d.etapes||[]).map(e=>`<div class="sum-box"><span>${esc(e.nom)}${e.detail?` <span style="color:#9a8a82;font-size:.74rem">(${esc(e.detail)})</span>`:''}</span><b>${_aiFmtDuree(e.min)}</b></div>`).join('');
    return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Temps de production — un batch</h3>
      ${aiHero(_aiFmtDuree(d.total), 'Temps de travail estimé', {sub:`pour une fournée standard de ${qty(TB)} macarons`})}
      ${lignes?aiDetails(lignes, 'Détail étape par étape'):''}
      <p class="note">Estimation moyenne pour un batch (toutes étapes actives). Le temps réel varie selon le parfum — précise-le pour un calcul exact (ex. « temps pour produire la pistache »). Le repos ganache (12 h) et la maturation (24 h) sont des temps d'attente, pas de manipulation.</p>`);
  }
  // Cas parfum + nombre.
  if(!params.flavor) return aiSay(`<p>Pour quel parfum (et combien de macarons) veux-tu le temps de production ?</p>`);
  const n = params.pieces || TB;
  const d = await _aiTempsProdDetail(n, params.flavor);
  const lignes = d.etapes.map(e=>`<div class="sum-box"><span>${esc(e.nom)}${e.detail?` <span style="color:#9a8a82;font-size:.74rem">(${esc(e.detail)})</span>`:''}</span><b>${_aiFmtDuree(e.min)}</b></div>`).join('');
  return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Temps de production — ${esc(params.flavor)}</h3>
    ${aiHero(_aiFmtDuree(d.total), 'Temps de travail estimé', {sub:`${qty(d.n)} macarons · ${d.nbBatchs} fournée${d.nbBatchs>1?'s':''}`})}
    ${aiDetails(lignes, 'Détail étape par étape')}
    <p class="note">Temps de travail actif. À part : le repos ganache (12 h) et la maturation (24 h) sont des temps d'attente, pas de manipulation. Affine ces durées dans Production en chronométrant.</p>`);
}

// [V938] NOMBRE DE BATCHS / FOURNÉES pour N macarons.
async function aiQueryNbBatchs(params){
  params=params||{};
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const n = params.pieces;
  if(!n) return aiSay(`<p>Combien de macarons veux-tu produire ? (et de quel parfum si pertinent)</p>`);
  // Rendement spécifique de la recette si dispo, sinon taille de batch standard.
  let rendement = TB, recNom=null;
  if(params.flavor){ const rec=await _aiRecetteParfum(params.flavor); if(rec){ recNom=rec.produitNom; if(+rec.rendement>0) rendement=+rec.rendement; } }
  const nb = Math.max(1, Math.ceil(n/rendement));
  const dernier = n % rendement;
  return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Fournées${recNom?` — ${esc(recNom)}`:''}</h3>
    <div class="sum-box"><span>Quantité visée</span><b>${qty(n)} macarons</b></div>
    <div class="sum-box"><span>Par fournée</span><b>${qty(rendement)}</b></div>
    <div class="sum-box" style="border-top:2px solid var(--bordeaux)"><span><b>Nombre de fournées</b></span><b style="color:var(--bordeaux)">${nb}</b></div>
    ${(dernier>0 && nb>1)?`<p class="note">La dernière fournée ne sera remplie qu'à ${qty(dernier)}/${qty(rendement)}. Arrondir à ${qty(nb*rendement)} optimiserait le four.</p>`:'<p class="note">Les fournées tombent juste.</p>'}`);
}

// [V938] CONVERSION GRAND FORMAT ↔ STANDARD (équivalent coques).
async function aiQueryConversionGF(params){
  params=params||{};
  const ratio = (typeof GF_COQUE_RATIO!=='undefined') ? GF_COQUE_RATIO : 3.5;
  const nb = params.nb || 1;
  const eq = nb * ratio;
  return aiSay(`${aiHero(`≈ ${qty(Math.round(eq*10)/10)} coques`, `${qty(nb)} grand${nb>1?'s':''} format${nb>1?'s':''} équivaut à`, {color:'var(--caramel)'})}
    ${aiSynth(`1 grand format ≈ ${ratio} coques standard en charge de production. Utile pour estimer le temps de four.`, {icon:'🍪'})}`);
}

// [V938] MARGE SUR UNE COMMANDE PRÉCISE (dernière commande du client).
async function aiQueryMargeCommande(params){
  params=params||{};
  if(!params.client) return aiSay(`<p>La marge sur la commande de quel client ?</p>`);
  const [orders, recipes, recipeItems, lots]=await Promise.all([db.orders.toArray(), db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray()]);
  const cmds=orders.filter(o=>o.clientId===params.client.id && o.date).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  if(!cmds.length) return aiSay(`${aiHero('—', `Marge — ${esc(params.client.nom||'')}`)}${aiSynth('Aucune commande pour ce client.', {icon:'📭'})}`);
  const last=cmds[0];
  const M=computeOrderMargins(last, recipes, recipeItems, lots);
  const col = M.margeNette>=0?'#2e7d32':'var(--red,#b3261e)';
  return aiSay(`${aiHero(`${euro(M.margeNette)}`, `Marge nette — ${esc(params.client.nom||'')}`, {color:col, sub: M.tauxNet!=null?`taux ${M.tauxNet}% · ${fmtDate(last.date)}`:fmtDate(last.date)})}
    ${aiSynth(`${M.margeNette>=0?'Cette commande est rentable':'Attention, cette commande est à perte'} après matières, emballage et charges sociales.`, {icon: M.margeNette>=0?'✅':'⚠️', tone: M.margeNette>=0?'ok':'warn'})}
    ${aiDetails(`
      <div class="sum-box"><span>Chiffre d'affaires</span><b>${euro(M.ca)}</b></div>
      <div class="sum-box"><span>Coût matières</span><b>${euro(M.coutMat)}</b></div>
      <div class="sum-box"><span>Marge brute</span><b>${euro(M.margeBrute)}</b></div>`, 'Détail du calcul')}
    ${aiCleLecture('Ce qu\'il te <b>reste</b> sur cette commande après matières, emballage et charges — pas son chiffre d\'affaires.', {voisins:[{label:'🏭 Coût matière', ask:`coût de la commande de ${esc(params.client.nom||'')}`}]})}`);
}

// [V938] COÛT MATIÈRE D'UNE COMMANDE.
async function aiQueryCoutCommande(params){
  params=params||{};
  if(!params.client) return aiSay(`<p>Le coût matière de la commande de quel client ?</p>`);
  const [orders, recipes, recipeItems, lots]=await Promise.all([db.orders.toArray(), db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray()]);
  const cmds=orders.filter(o=>o.clientId===params.client.id && o.date).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  if(!cmds.length) return aiSay(`${aiHero('—', `Coût matière — ${esc(params.client.nom||'')}`)}${aiSynth('Aucune commande pour ce client.', {icon:'📭'})}`);
  const last=cmds[0];
  const M=computeOrderMargins(last, recipes, recipeItems, lots);
  const _pctCout = M.ca>0 ? Math.round(M.coutMat/M.ca*100) : null;
  return aiSay(`${aiHero(euro(M.coutMat), `Coût matière — ${esc(params.client.nom||'')}`, {sub:`${_pctCout!=null?`${_pctCout}% du CA · `:''}${fmtDate(last.date)}`})}
    ${aiSynth(`Coût des matières consommées pour cette commande${_pctCout!=null?`, soit ${_pctCout}% de son chiffre d'affaires (${euro(M.ca)})`:''}.`, {icon:'🏭'})}
    ${aiDetails(`<div class="sum-box"><span>Matières premières</span><b>${euro(M.coutMat)}</b></div>
    ${M.coutEmb!=null?`<div class="sum-box"><span>Emballage</span><b>${euro(M.coutEmb)}</b></div>`:''}
    <div class="sum-box"><span>CA de la commande</span><b>${euro(M.ca)}</b></div>`, 'Détail')}
    ${aiCleLecture('Seulement le coût des <b>matières</b> (et emballage) consommées — pas ce qu\'il te reste au final.', {voisins:[{label:'📈 Marge sur cette commande', ask:`marge sur la commande de ${esc(params.client.nom||'')}`}]})}
    ${aiSuite([{label:'📈 Quelle marge sur cette commande ?', ask:`marge sur la commande de ${params.client.nom||''}`}])}`);
}

// [V938] PARFUMS COMPATIBLES AVEC UN ALLERGÈNE (sans X). Inverse de query_allergenes.
async function aiQueryParfumsSans(params){
  params=params||{};
  // [v1061] MODE « sans recette » : parfums qui apparaissent dans les ventes/commandes mais n'ont
  // aucune recette définie (impossible de calculer coût/marge, ni d'intégrer leurs besoins matières).
  if(params.mode==='recette'){
    const recipes = await db.recipes.toArray();
    const norm = (s)=>(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
    const recSet = new Set(recipes.map(r=>norm(r.produitNom)).filter(Boolean));
    // parfums « connus » = ceux apparaissant dans les commandes (lignes) + la liste FLAVORS de référence.
    const orders = await db.orders.toArray();
    const venduSet = new Map(); // norm → libellé d'origine
    orders.forEach(o=>{
      let lignes=[]; try{ lignes = (typeof orderToLines==='function') ? orderToLines(o) : []; }catch(e){ lignes=[]; }
      lignes.forEach(l=>{ const nom=l.parfum||l.flavor||l.nom; if(nom){ const k=norm(nom); if(!venduSet.has(k)) venduSet.set(k, nom); } });
    });
    if(typeof FLAVORS!=='undefined') FLAVORS.forEach(f=>{ const k=norm(f); if(!venduSet.has(k)) venduSet.set(k, f); });
    const sansRecette=[];
    venduSet.forEach((libelle,k)=>{ if(!recSet.has(k)) sansRecette.push(libelle); });
    sansRecette.sort((a,b)=>a.localeCompare(b));
    if(!sansRecette.length){
      return aiSay(`${aiHero('0', 'Parfum sans recette', {color:'var(--vert,#3f7d52)'})}
        ${aiSynth('Tous tes parfums vendus ont une recette définie. Rien à compléter.', {tone:'ok', icon:'✅'})}`);
    }
    return aiSay(`${aiHero(`${sansRecette.length} <span style="font-size:1rem;font-weight:600">parfum${sansRecette.length>1?'s':''}</span>`, 'Sans recette définie', {color:'var(--red)'})}
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin:2px 0 8px">${sansRecette.map(p=>`<span class="tag" style="background:#fdecea;color:#b3261e;border:1px solid #efc4bd;font-size:.8rem">${esc(p)}</span>`).join('')}</div>
      ${aiSynth('Ces parfums apparaissent dans tes ventes mais n\'ont pas de recette — impossible de calculer leur coût/marge ni leurs besoins matières. Crée-leur une recette.', {icon:'📖', tone:'warn'})}`,
      [{ label:'➕ Nouvelle recette', action:'aiActNouvelleRecette' }, { label:'🗂 Ouvrir les recettes', view:'recettes' }]);
  }
  if(!params.allergene) return aiSay(`<p>Sans quel allergène ? (ex. « quels parfums sont sans gluten »)</p>`);
  const recipes = await db.recipes.toArray();
  const n=(s)=>(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const cible=n(params.allergene);
  const ok=[], avec=[];
  const noms = recipes.length ? recipes.map(r=>r.produitNom).filter(Boolean) : (typeof FLAVORS!=='undefined'?FLAVORS:[]);
  noms.forEach(nom=>{
    const rec = recipes.find(r=>r.produitNom===nom);
    let allerg = (rec && rec.allergenes && rec.allergenes.length) ? rec.allergenes : (allergenesPourNom(nom)||[]);
    const contient = allerg.some(a=>n(a)===cible);
    if(contient) avec.push(nom); else ok.push(nom);
  });
  if(!ok.length && !avec.length) return aiSay(`<p class="note">Aucune recette pour évaluer la compatibilité.</p>`);
  return aiSay(`${aiHero(`${ok.length} <span style="font-size:1rem;font-weight:600">parfum${ok.length>1?'s':''}</span>`, `Sans ${esc(params.allergene)}`, {color: ok.length?'#2e7d32':'var(--red)'})}
    ${ok.length?`<div style="display:flex;flex-wrap:wrap;gap:6px;margin:2px 0 8px">${ok.map(p=>`<span class="tag" style="background:#eef6ef;color:#2e7d32;border:1px solid #bcdcc2;font-size:.8rem">✓ ${esc(p)}</span>`).join('')}</div>`:''}
    ${aiSynth(ok.length?`Compatibles sans ${esc(params.allergene.toLowerCase())}.${avec.length?` À éviter : ${avec.map(esc).join(', ')}.`:''} Vérifie toujours l'étiquetage avant remise.`:`Aucun parfum sans ${esc(params.allergene.toLowerCase())}.`, {icon:'🏷️', tone: ok.length?'ok':'warn'})}`);
}

async function aiQueryIngredientPour(params){
  params = params || {};
  const mat = params.material, flavor = params.flavor, pieces = params.pieces;
  if(!mat) return aiSay(`<p>De quel ingrédient veux-tu connaître la quantité ?</p>`);
  if(!flavor) return aiSay(`<p>Pour quel parfum veux-tu la quantité de ${esc(mat.nom)} ?</p>`);
  const recipes = await db.recipes.toArray();
  const norm = (s)=>(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const rec = recipes.find(r=>norm(r.produitNom)===norm(flavor))
           || recipes.find(r=>norm(r.produitNom).includes(norm(flavor)) || norm(flavor).includes(norm(r.produitNom)));
  if(!rec) return aiSay(`<p class="note">Je n'ai pas trouvé de recette « ${esc(flavor)} ». Vérifie le nom dans l'onglet Recettes.</p>`);
  const items = await db.recipeItems.where('recipeId').equals(rec.id).toArray();
  if(!items.length) return aiSay(`${aiHero('—', `Recette ${esc(rec.produitNom)}`)}${aiSynth('Aucun ingrédient renseigné pour cette recette.', {tone:'warn', icon:'⚠️'})}`);
  const rendement = (+rec.rendement>0) ? +rec.rendement : null;
  const facteur = (pieces && rendement) ? (pieces/rendement) : 1;
  // On filtre les lignes correspondant à l'ingrédient demandé (une recette peut l'utiliser à plusieurs endroits).
  const lignesMat = items.filter(it=>it.materialId===mat.id);
  if(!lignesMat.length){
    return aiSay(`${aiHero('0', `${esc(mat.nom)} — ${esc(rec.produitNom)}`)}${aiSynth(`La recette « ${esc(rec.produitNom)} » n'utilise pas ${esc(mat.nom)}.`, {icon:'🤷'})}`);
  }
  const total = lignesMat.reduce((s,it)=>s+((+it.qteParBatch||0)*facteur),0);
  const fmtQ = q => (q>=1 ? Math.round(q*1000)/1000 : Math.round(q*10000)/10000);
  const sousTitre = (pieces && rendement)
    ? `pour <b>${pieces} ${pieces>1?'macarons':'macaron'}</b> (recette de base : ${rendement} pièces/batch)`
    : (rendement ? `pour <b>1 batch = ${rendement} pièces</b>` : `pour un batch`);
  // Détail par partie si l'ingrédient apparaît dans plusieurs (ganache, coques…).
  const detail = lignesMat.length>1
    ? lignesMat.map(it=>`<div class="sum-box"><span>${esc(it.partie||'—')}</span><b>${fmtQ((+it.qteParBatch||0)*facteur)} ${esc(mat.unite||'kg')}</b></div>`).join('')
    : '';
  const sousTitrePlain = (pieces && rendement) ? `pour ${pieces} ${pieces>1?'macarons':'macaron'}` : (rendement ? `pour 1 batch (${rendement} pièces)` : `pour un batch`);
  return aiSay(`${aiHero(`${fmtQ(total)} <span style="font-size:1rem;font-weight:600">${esc(mat.unite||'kg')}</span>`, `${esc(mat.nom)} — ${esc(rec.produitNom)}`, {color:'var(--bordeaux)', sub:sousTitrePlain})}
    ${aiSynth(`Quantité de ${esc(mat.nom)} nécessaire ${sousTitrePlain}, calculée depuis ta recette.`, {icon:'⚖️'})}
    ${detail?aiDetails(detail, 'Détail par partie'):''}
    ${aiSuite([{label:'🍋 Voir toute la recette', ask:`la recette ${rec.produitNom}${pieces?` pour ${pieces} pièces`:''}`}])}`);
}
async function aiQueryRecipe(params){
  const flavor = params && params.flavor;
  const pieces = params && params.pieces;
  if(!flavor){
    const recs = await db.recipes.toArray();
    const noms = recs.map(r=>r.produitNom).filter(Boolean).slice(0,12);
    return aiSay(`<p class="note">Pour quelle recette ? Par exemple : « la recette du citron pour 25 pièces ».${noms.length?`<br>Tes recettes : ${noms.map(esc).join(', ')}.`:''}</p>`);
  }
  const recipes = await db.recipes.toArray();
  const norm = s => (typeof aiNormalize==='function') ? aiNormalize(s) : String(s||'').toLowerCase();
  const k = norm(flavor);
  let rec = recipes.find(r=> norm(r.produitNom)===k)
         || recipes.find(r=>{ const rn=norm(r.produitNom); return rn && (rn.includes(k) || k.includes(rn)); });
  if(!rec){
    return aiSay(`<p class="note">Je n'ai pas trouvé de recette « ${esc(flavor)} ». Vérifie le nom dans l'onglet Recettes.</p>`);
  }
  const items = await db.recipeItems.where('recipeId').equals(rec.id).toArray();
  if(!items.length){
    return aiSay(`${aiHero('—', `Recette ${esc(rec.produitNom)}`)}${aiSynth('Aucun ingrédient renseigné pour cette recette. Complète-la dans l\'onglet Recettes.', {tone:'warn', icon:'⚠️'})}`);
  }
  const mats = await db.materials.toArray();
  const matById = Object.fromEntries(mats.map(m=>[m.id,m]));
  const rendement = (+rec.rendement>0) ? +rec.rendement : null;
  // Facteur d'échelle : si on demande N pièces et qu'on connaît le rendement → N/rendement, sinon 1 batch.
  const facteur = (pieces && rendement) ? (pieces/rendement) : 1;
  const lignes = items.map(it=>{
    const m = matById[it.materialId] || {nom:'Matière #'+it.materialId, unite:''};
    const q = (+it.qteParBatch||0) * facteur;
    return { nom:m.nom, unite:m.unite||'kg', q, partie:it.partie||'' };
  });
  // Regroupement par partie (ganache, coques…) si renseigné.
  const parParties = {};
  lignes.forEach(l=>{ (parParties[l.partie||'—'] ||= []).push(l); });
  const fmtQ = q => (q>=1 ? (Math.round(q*1000)/1000) : (Math.round(q*10000)/10000));
  const corps = Object.keys(parParties).map(partie=>{
    const head = partie!=='—' ? `<div style="font-weight:600;font-size:.85rem;margin:8px 0 3px;text-transform:capitalize">${esc(partie)}</div>` : '';
    return head + parParties[partie].map(l=>
      `<div class="sum-box"><span>${esc(l.nom)}</span><b>${fmtQ(l.q)} ${esc(l.unite)}</b></div>`).join('');
  }).join('');
  const sousTitre = (pieces && rendement)
    ? `pour <b>${pieces} pièces</b> (recette de base : ${rendement} pièces/batch)`
    : (rendement ? `pour <b>1 batch = ${rendement} pièces</b>` : `quantités d'un batch`);
  const heroQ = (pieces && rendement) ? `${pieces} pièces` : (rendement ? `${rendement} pièces` : '1 batch');
  aiSay(`${aiHero(heroQ, `Recette ${esc(rec.produitNom)}`, {color:'var(--caramel)', sub: (pieces&&rendement)?`mise à l'échelle (base ${rendement}/batch)`:(rendement?'1 batch':'quantités d\'un batch')})}
    ${corps}
    ${(pieces && !rendement)?aiSynth('Rendement non renseigné : impossible de mettre à l\'échelle, quantités d\'un batch affichées.', {tone:'warn', icon:'⚠️'}):''}
    ${aiSuite([{label:'💰 Combien me coûte ce parfum ?', ask:`combien me coûte un macaron ${rec.produitNom}`}])}`);
}
// [COCKPIT] FAISABILITÉ D'AJOUT (simulation) : « si je rajoute 25 macarons café jeudi, c'est faisable ? »
// Compare la charge de la semaine AVANT et APRÈS l'ajout fictif, via _faisabiliteSemaine (qui réutilise
// generateProductionOrder avec un besoin additionnel). Ne crée RIEN : simulation pure en mémoire.
async function aiQueryFaisabiliteAjout(params){
  const nb = params && +params.nb;
  if(!nb || nb<=0) return aiSay(`<p class="note">Précise un nombre de macarons, par ex. « si je rajoute 25 macarons jeudi, c'est faisable ? ».</p>`);
  const fmtH = m => { m=Math.round(+m||0); const h=Math.floor(m/60), mm=m%60; return `${h?h+'h ':''}${String(mm).padStart(2,'0')}min`; };
  const date = (params && params.date) || today();
  const wk = (typeof _isoWeekKey==='function') ? _isoWeekKey(date) : null;
  if(!wk) return aiSay(`<p class="note">Je n'ai pas pu situer la date « ${esc(String(date))} » dans une semaine de production.</p>`);
  const conf = (typeof getAvailability==='function') ? getAvailability() : null;
  // Parfum cible : celui demandé, sinon le parfum le plus présent (à défaut « À définir »).
  const flavor = (params && params.flavor) ? params.flavor : 'À définir';
  const besoinAdd = { [flavor]: nb };
  let avant, apres;
  try{
    avant = await _faisabiliteSemaine(wk, conf);
    apres = await _faisabiliteSemaine(wk, conf, besoinAdd);
  }catch(e){ console.error('faisabilite.ajout',e); }
  if(!avant || !apres){
    return aiSay(`<p class="note">La semaine du ${esc(fmtDate(date))} est passée ou hors planning : je ne peux pas simuler l'ajout. Renseigne tes disponibilités pour cette semaine.</p>`);
  }
  const dispo = apres.tempsDispo||0;
  const surcout = Math.max(0, (apres.tempsTotal||0) - (avant.tempsTotal||0));
  const tient = dispo>0 ? !apres.depassement : null;
  const depassMin = apres.debordementMin||0;
  let verdict, couleur, bg, bord;
  if(dispo<=0){
    verdict = `Tes disponibilités ne sont pas renseignées pour la semaine du ${fmtDate(date)} — je ne peux pas trancher. La production demandée passerait à <b>${fmtH(apres.tempsTotal)}</b>.`;
    couleur='#6a5a52'; bg='#f4f1ec'; bord='#e0d8cc';
  } else if(tient){
    verdict = `✅ <b>Oui, c'est faisable.</b> Ajouter ${nb} macarons${params.flavor?' '+esc(params.flavor):''} porte ta charge à <b>${fmtH(apres.tempsTotal)}</b> sur <b>${fmtH(dispo)}</b> dispo (${apres.chargePct}%). Il te reste de la marge.`;
    couleur='#2f6040'; bg='#eef5f0'; bord='#bcd9c4';
  } else {
    verdict = `⚠️ <b>Ça déborde.</b> Avec ${nb} macarons en plus, la charge passe à <b>${fmtH(apres.tempsTotal)}</b> pour <b>${fmtH(dispo)}</b> dispo — il manque <b>${fmtH(depassMin)}</b>. Il faudrait étaler, élargir tes créneaux, ou reporter une autre production.`;
    couleur='#b3261e'; bg='#fdeceb'; bord='#f0b8b3';
  }
  aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">🧮 Simulation — +${nb} macarons${params.flavor?' '+esc(params.flavor):''} <span style="font-weight:400;font-size:.78rem;color:#9a8a82">(semaine du ${esc(fmtDate(date))})</span></h3>
    <div style="background:${bg};border:1px solid ${bord};border-radius:10px;padding:9px 11px;margin-bottom:8px;font-size:.86rem;color:${couleur}">${verdict}</div>
    <div class="sum-box"><span>Charge actuelle</span><b>${fmtH(avant.tempsTotal)}</b></div>
    <div class="sum-box"><span>Avec ton ajout</span><b>${fmtH(apres.tempsTotal)}</b></div>
    <div class="sum-box"><span>Surcoût de l'ajout</span><b>+${fmtH(surcout)}</b></div>
    ${dispo>0?`<div class="sum-box"><span>Disponible cette semaine</span><b>${fmtH(dispo)}</b></div>`:''}
    <p class="note" style="margin-top:6px">Simulation indicative — rien n'est créé ni modifié.</p>`);
}
// [COCKPIT] STOCK MATIÈRE SUFFISANT POUR UNE ÉCHÉANCE : « assez de lait pour ma commande de demain ? »
// Réutilise besoinMatieresPrevisionnel (source unique) sur l'horizon jusqu'à la date, et compare le
// besoin de la matière visée à son stock. Ne modifie rien.
async function aiQueryStockPour(params){
  const mat = params && params.material;
  if(!mat) return aiSay(`<p class="note">Quelle matière ? Par exemple : « est-ce qu'il me reste assez de lait pour demain ? ».</p>`);
  // Horizon en jours jusqu'à la date demandée (demain = 1). Par défaut : 1 jour (demain).
  let horizon = 1;
  if(params.date){
    const d = (typeof daysTo==='function') ? daysTo(params.date) : null;
    if(d!=null) horizon = Math.max(1, d);
  }
  let res;
  try{ res = await besoinMatieresPrevisionnel(horizon); }catch(e){ console.error('stockPour',e); }
  if(!res || !Array.isArray(res.lignes)){
    return aiSay(`<p class="note">Je n'ai pas pu calculer le besoin en ${esc(mat.nom)} sur cette période.</p>`);
  }
  const norm = s => (typeof aiNormalize==='function') ? aiNormalize(s) : String(s||'').toLowerCase();
  const k = norm(mat.nom);
  const ligne = res.lignes.find(l=> (l.materialId===mat.id) || norm(l.nom)===k || norm(l.nom).includes(k) || k.includes(norm(l.nom)));
  const fmtQ = q => Math.round((+q||0)*1000)/1000;
  // Cas : la matière n'est requise par aucune production sur l'horizon (donc pas de besoin).
  if(!ligne){
    return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">🧀 ${esc(mat.nom)}</h3>
      <div style="background:#eef5f0;border:1px solid #bcd9c4;border-radius:10px;padding:9px 11px;font-size:.86rem;color:#2f6040">✅ Aucune production prévue d'ici là n'a besoin de ${esc(mat.nom)} — donc pas de souci de ce côté.</div>`);
  }
  const besoin = +ligne.besoin||0, stock = +ligne.stock||0, manque = +ligne.manque||0, unite = ligne.unite||'';
  const echeance = params.date ? ` pour le ${fmtDate(params.date)}` : ' pour demain';
  let verdict, bg, bord, col;
  if(manque>0){
    verdict = `⚠️ <b>Non, il en manque.</b> Il te faut <b>${fmtQ(besoin)} ${esc(unite)}</b> de ${esc(mat.nom)}${echeance}, tu en as <b>${fmtQ(stock)} ${esc(unite)}</b> → il manque <b>${fmtQ(manque)} ${esc(unite)}</b>. Pense à réapprovisionner.`;
    bg='#fdeceb'; bord='#f0b8b3'; col='#b3261e';
  } else {
    const marge = stock - besoin;
    verdict = `✅ <b>Oui, tu en as assez.</b> Besoin de <b>${fmtQ(besoin)} ${esc(unite)}</b>${echeance}, tu en as <b>${fmtQ(stock)} ${esc(unite)}</b> (marge de ${fmtQ(marge)} ${esc(unite)}).`;
    bg='#eef5f0'; bord='#bcd9c4'; col='#2f6040';
  }
  aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">🧀 ${esc(mat.nom)}${params.date?` <span style="font-weight:400;font-size:.78rem;color:#9a8a82">(d'ici le ${esc(fmtDate(params.date))})</span>`:''}</h3>
    <div style="background:${bg};border:1px solid ${bord};border-radius:10px;padding:9px 11px;margin-bottom:8px;font-size:.86rem;color:${col}">${verdict}</div>
    <div class="sum-box"><span>Besoin estimé</span><b>${fmtQ(besoin)} ${esc(unite)}</b></div>
    <div class="sum-box"><span>En stock</span><b>${fmtQ(stock)} ${esc(unite)}</b></div>
    <p class="note" style="margin-top:6px">Besoin calculé pour la production restant à faire d'ici là.</p>`);
}
// [COCKPIT] Résumé d'un CLIENT précis (« la fiche de X », « les commandes d'Emma »). Affiche nom,
// type, contact et nombre de commandes, puis aiSay accole le raccourci vers sa fiche (focus client).
async function aiQueryClient(params){
  const c = params && params.client;
  if(!c) return aiSay(`<p class="note">Je n'ai pas identifié de client précis. Essaie « la fiche de [nom] ».</p>`);
  let nbCmd = 0, dernier = null;
  try{
    const orders = await db.orders.toArray();
    const siens = orders.filter(o=> +o.clientId === +c.id);
    nbCmd = siens.length;
    dernier = siens.map(o=>o.date).filter(Boolean).sort().slice(-1)[0] || null;
  }catch(e){swallow(e,'aiQueryClient')}
  const contact = [c.tel, c.email, c.societe].filter(Boolean).map(x=>esc(x)).join(' · ');
  aiSay(`<h3 style="font-size:1rem;margin-bottom:8px">${esc(c.nom)} <span style="font-weight:400;font-size:.78rem;color:#9a8a82">(${esc(c.type||'Particulier')})</span></h3>
    ${contact?`<div class="sum-box"><span>Contact</span><b style="font-weight:500">${contact}</b></div>`:''}
    <div class="sum-box"><span>Commandes</span><b>${nbCmd}</b></div>
    ${dernier?`<div class="sum-box"><span>Dernière commande</span><b>${esc(dernier)}</b></div>`:''}`);
}
// [COCKPIT] ÉCHÉANCE DE LIVRAISON d'un client : « quand dois-je livrer la commande d'Emma ? ».
// Source unique pour la date de référence : _orderRefDate (dateEvenement || date). Montre les
// commandes NON livrées à venir, avec date, « dans X jours », heure et lieu si renseignés, et contenu.
// [V942] LA PROCHAINE LIVRAISON à venir, tous clients confondus. Réutilise les helpers de aiQueryDelivery
// (_orderRefDate, normStatus, daysTo) pour rester cohérent. Réponse ciblée : la commande la plus proche.
// [V944] CHARGES DU MOIS. Source : computeAccounting (charges de la période courante).
// ============================================================================
//  [v1334] TROIS COMPÉTENCES QUI AVOUAIENT — elles savent maintenant.
// ----------------------------------------------------------------------------
//  La v1333 a posé la règle : « une compétence qui ne sait pas filtrer par mois le DIT, au lieu
//  d'ignorer le paramètre en silence ». C'était honnête, mais ce n'était pas résolu — et j'avais
//  écrit noir sur blanc que ça ne l'était pas.
//  Ici, les trois compétences qui avouaient apprennent à faire : les charges, le gaspillage et le
//  bilan marché. L'aveu n'était qu'une étape, pas une destination.
// ============================================================================

// La date d'un marché — règle UNIQUE, extraite (elle était recopiée à deux endroits).
const marcheDate = mk => ((mk && (mk.date || mk.dateCloture)) || '');

// PURE. Les marchés d'un mois donné (clé AAAA-MM). `ym` nul → tous les marchés.
function marchesDuMois(markets, ym){
  const list = (markets || []).filter(Boolean);
  if(!ym) return list;
  return list.filter(mk => (marcheDate(mk) || '').slice(0, 7) === ym);
}

// PURE. Le gaspillage (dons + pertes) sur un mois, ou sur tout l'historique si `ym` est nul.
// Les mouvements sont datés par le MARCHÉ auquel ils appartiennent : un don n'a pas de date propre,
// il appartient au marché où il a eu lieu. Dater autrement inventerait une chronologie.
function gaspillageMarches(markets, moves, ym){
  const marches = marchesDuMois(markets, ym);
  const ids = new Set(marches.map(m => m.id));
  let don = 0, perte = 0, retour = 0;
  (moves || []).forEach(mv => {
    if(!mv || !ids.has(mv.marketId)) return;
    const q = +mv.qte || 0;
    if(mv.type === 'don') don += q;
    else if(mv.type === 'perte') perte += q;
    else if(mv.type === 'retour') retour += q;
  });
  return {
    don: round3(don), perte: round3(perte), retour: round3(retour),
    total: round3(don + perte),          // le GASPILLAGE = ce qui est perdu pour de bon
    nbMarches: marches.length,           // 0 marché sur le mois → « aucun marché », pas « aucun gaspillage »
    ym: ym || null
  };
}

async function aiQueryCharges(params){
  let A=null; try{ A=await computeAccounting(); }catch(e){swallow(e,'aiQueryCharges')}
  let charges=[]; try{ charges=await (db.charges?db.charges.toArray():Promise.resolve([])).catch(()=>[]); }catch(e){swallow(e,'aiQueryCharges')}
  // [FIX v1334] Le mois était CODÉ EN DUR (le mois courant). « Mes charges de mai » répondait
  // juillet — et depuis la v1333, l'app l'AVOUAIT au moins. Elle sait faire, maintenant.
  params = params || {};
  let mk = monthKey(today()), _lblM = 'du mois';
  if(/^\d{4}-\d{2}$/.test(params.periode||'')){ mk = params.periode; _lblM = 'de ' + monthLabel(mk); }
  else if(params.periode==='moisDernier'){ const d=new Date(); d.setMonth(d.getMonth()-1); mk=monthKey(d); _lblM='du mois dernier'; }
  const duMois=charges.filter(c=>c.date && monthKey(c.date)===mk);
  const total=duMois.reduce((s,c)=>s+(+c.montant||0),0);
  if(!duMois.length){
    return aiSay(`${aiHero(euro(0), `Charges ${_lblM}`)}${aiSynth(`Aucune charge enregistrée ${_lblM==='du mois'?'ce mois-ci':_lblM}. Saisis tes dépenses (loyer, énergie, matériel…) dans Compta.`,{icon:'🧾'})}`);
  }
  // Regroupe par catégorie.
  const parCat={};
  duMois.forEach(c=>{ const k=c.categorie||'Autre'; parCat[k]=(parCat[k]||0)+(+c.montant||0); });
  const cats=Object.entries(parCat).sort((a,b)=>b[1]-a[1]);
  return aiSay(`${aiHero(euro(total), 'Charges du mois', {sub:`${duMois.length} dépense${duMois.length>1?'s':''} ce mois`, color:'#b3261e'})}
    ${aiSynth(`Principal poste : <b>${esc(cats[0][0])}</b> (${euro(cats[0][1])}). Hors cotisations et coût matière.`, {icon:'🧾'})}
    ${aiDetails(cats.map(([k,v])=>`<div class="sum-box"><span>${esc(k)}</span><b>${euro(v)}</b></div>`).join(''),'Par catégorie')}
    ${aiSuite([{label:'🧮 Mes cotisations URSSAF', ask:'mes cotisations urssaf'}])}`);
}

// [V944] COUVERTURE DE STOCK (autonomie globale). Source : analyzeStockCoverage.
async function aiQueryCouvertureStock(){
  let C=null; try{ const orders=await db.orders.toArray(); C=await analyzeStockCoverage(orders); }catch(e){swallow(e,'aiQueryCouvertureStock')}
  if(!C) return aiSay(`${aiHero('—', 'Couverture de stock')}${aiSynth('Calcul indisponible pour le moment.', {icon:'⏳'})}`);
  const recipes=C.recipes||[]; const fini=C.finiByRecipe||{}; const demande=C.demande60j||{};
  // Pour chaque recette : stock fini vs demande 60j → ratio de couverture.
  const lignes=recipes.map(r=>{
    const stock=+fini[r.id]||0; const dem=+demande[r.id]||0;
    const couv = dem>0 ? stock/dem : (stock>0?Infinity:0);
    return {nom:r.produitNom, stock, dem, couv};
  }).filter(l=>l.dem>0 || l.stock>0);
  const sousCouverts=lignes.filter(l=>l.dem>0 && l.couv<1).sort((a,b)=>a.couv-b.couv);
  const totStock=lignes.reduce((s,l)=>s+l.stock,0);
  const totDem=lignes.reduce((s,l)=>s+l.dem,0);
  const couvGlobale = totDem>0 ? Math.round(totStock/totDem*100) : null;
  const tone = (couvGlobale==null)?'':couvGlobale>=100?'ok':couvGlobale>=60?'':'warn';
  return aiSay(`${aiHero(couvGlobale!=null?`${couvGlobale}%`:'—', 'De la demande à 60 jours', {sub:`${qty(totStock)} en stock · ${qty(totDem)} demandés`, color: couvGlobale==null?'var(--bordeaux)':couvGlobale>=100?'#2e7d32':couvGlobale>=60?'var(--bordeaux)':'#b3261e'})}
    ${sousCouverts.length?aiSynth(`${sousCouverts.length} parfum${sousCouverts.length>1?'s':''} à renforcer, à commencer par <b>${esc(sousCouverts[0].nom)}</b> (${Math.round(sousCouverts[0].couv*100)}%).`,{icon:'⚠️',tone:'warn'}):aiSynth('Ton stock couvre la demande connue des 60 prochains jours.',{icon:'✅',tone:'ok'})}
    ${sousCouverts.length?aiDetails(sousCouverts.slice(0,8).map(l=>`<div class="sum-box"><span>${esc(l.nom)}</span><b>${qty(l.stock)}/${qty(l.dem)} <span style="color:#9a8a82;font-weight:400">(${Math.round(l.couv*100)}%)</span></b></div>`).join(''),'Parfums à renforcer'):''}
    ${sousCouverts.length?aiSuite([{label:'🏭 Calculer mes besoins', ask:'qu\'est-ce que je dois produire'}]):''}`);
}

// [V944] RENTABILITÉ D'UNE LIVRAISON. Source : computeDeliveryCost (carburant + temps).
async function aiQueryRentaLivraison(params){
  params=params||{};
  const orders=await db.orders.toArray();
  let cible=null;
  if(params.client){
    const siennes=orders.filter(o=>+o.clientId===+params.client.id && (+o.distanceKm>0||+o.tempsLivraisonMin>0)).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
    cible=siennes[0];
    if(!cible){
      return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Rentabilité livraison — ${esc(params.client.nom||'')}</h3>${aiSynth(`Aucune commande de ${esc(params.client.nom||'ce client')} avec distance ou temps de livraison renseignés.`,{icon:'🚗'})}<p class="note">Renseigne la distance et le temps dans la commande pour estimer le coût.</p>`);
    }
  } else {
    // Pas de client : moyenne sur les commandes livrées récentes.
    const avecLiv=orders.filter(o=>(+o.distanceKm>0||+o.tempsLivraisonMin>0));
    if(!avecLiv.length) return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Rentabilité d'une livraison</h3>${aiSynth('Aucune commande avec livraison chiffrée (distance/temps).',{icon:'🚗'})}`);
    // Coût moyen + part dans le CA moyen.
    let totCout=0, totCA=0, n=0;
    avecLiv.forEach(o=>{ try{ const d=computeDeliveryCost(o); if(d.actif){ totCout+=d.total; totCA+=(+o.montant||0); n++; } }catch(e){swallow(e,'aiQueryRentaLivraison')} });
    const moyCout=n?totCout/n:0; const part=totCA>0?Math.round(totCout/totCA*100):null;
    const subMoy = `sur ${n} livraison${n>1?'s':''}` + (part!=null?` · ${part}% du CA livré`:'');
    const colMoy = (part!=null&&part>15)?'#b3261e':'var(--bordeaux)';
    return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Rentabilité de mes livraisons</h3>
      ${aiHero(euro(moyCout), 'Coût moyen par livraison', {sub:subMoy, color:colMoy})}
      ${part!=null?aiSynth(part>15?`Tes livraisons grignotent ${part}% du chiffre livré — surveille les longues distances.`:`Tes livraisons représentent ${part}% du CA livré, c'est raisonnable.`,{icon: part>15?'⚠️':'✅', tone: part>15?'warn':'ok'}):''}
      <p class="note">Coût = carburant (aller-retour) + temps valorisé à ton taux horaire.</p>`);
  }
  const d=computeDeliveryCost(cible);
  const ca=+cible.montant||0;
  const part=ca>0?Math.round(d.total/ca*100):null;
  const reste=ca-d.total;
  const colLiv = (part!=null&&part>15)?'#b3261e':'var(--bordeaux)';
  const subLiv = `${d.distAR} km A/R · ${d.minutes} min`;
  return aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">Rentabilité livraison — ${esc(params.client.nom||'')}</h3>
    ${aiHero(euro(d.total), 'Coût de la livraison', {sub:subLiv, color:colLiv})}
    ${part!=null?aiSynth(`Sur une commande de ${euro(ca)}, la livraison coûte ${part}% (${euro(d.total)}). Il te reste ${euro(reste)} avant matière.`,{icon: part>20?'⚠️':'📊', tone: part>20?'warn':''}):''}
    ${aiDetails(`
      <div class="sum-box"><span>Carburant (A/R)</span><b>${euro(d.coutCarburant)}</b></div>
      <div class="sum-box"><span>Temps (${d.minutes} min)</span><b>${euro(d.coutTemps)}</b></div>`,'Détail du coût')}
    <p class="note">Estimation : carburant + temps valorisé. Hors coût des macarons eux-mêmes.</p>`);
}

// [V944] REVENU HORAIRE. Source : revenuHoraireCalcul.
// [v1327] LA QUESTION plutôt que la réponse fausse.
// On expose l'intention que parseIntent avait retenue EN PREMIER (transparence : Benjamin voit ce
// que le copilote allait faire), puis les rivales. Aucune n'est présentée comme « la bonne » —
// on ne prétend pas savoir : on constate qu'on ne peut pas trancher, et on le dit.
function aiDemanderPrecision(intentRetenu, rivaux){
  const lbl = i => AI_INTENT_LABELS[i] || i;
  const choix = [intentRetenu, ...(rivaux||[])];
  const btns = choix.map((i, k) => `<button class="ai-suite-btn${k===0?'':''}" onclick="aiForcerIntent('${i}')" style="margin:3px 4px 0 0">${esc(lbl(i))}</button>`).join('');
  return aiSay(`${aiSynth('Ta demande peut vouloir dire plusieurs choses, et je préfère te le demander plutôt que de te répondre à côté sans le dire.', {icon:'🤔'})}
    <div style="margin-top:8px;font-size:.85rem;color:#6a5a52">Tu veux dire&nbsp;:</div>
    <div style="margin-top:6px">${btns}</div>
    <div style="margin-top:8px;font-size:.72rem;color:#9a8a82">Ces indicateurs sont proches mais ne mesurent pas la même chose — te donner le mauvais serait pire que te poser la question.</div>`);
}

// Force une intention choisie par Benjamin : on court-circuite parseIntent (qui vient justement
// d'hésiter) et on appelle directement la compétence. Aucune ré-analyse du texte : ce serait
// retomber dans le même détournement.
async function aiForcerIntent(intent){
  try{
    aiPush('user', AI_INTENT_LABELS[intent] || intent);
    await _aiDispatch({ intent, params:{}, critical:false }, '', {});
  }catch(e){ swallow(e,'aiForcerIntent'); }
}

