async function aiQueryRevenuHoraire(){
  let R=null; try{ R=await revenuHoraireCalcul(90); }catch(e){swallow(e,'aiQueryRevenuHoraire')}
  if(!R || R.heures==null || R.heures<=0){
    return aiSay(`${aiHero('—', 'Mon revenu horaire')}${aiSynth('Pas encore assez d\'heures pointées. Utilise la pointeuse pendant tes sessions : le calcul se construira tout seul.',{icon:'⏳'})}`);
  }
  // [v1082] Si le temps pointé ne couvre pas la période, on s'abstient plutôt que d'afficher un chiffre faux.
  if(R.calculable===false){
    return aiSay(`${aiHero('—', 'Mon revenu horaire')}${aiSynth(`Je préfère ne pas avancer de chiffre : tes ${Math.round(R.heures)} h pointées ne couvrent pas la période de ton chiffre d'affaires (≈ ${(R.moisActivite||0).toFixed(1)} mois). Diviser des mois de marge par quelques heures donnerait un résultat trompeur.`,{icon:'⏸', tone:'warn'})}${aiSynth('Pour le débloquer : pointe ton temps régulièrement, ou demande-moi le revenu horaire « sur 30 jours ».',{icon:'💡'})}`);
  }
  // [v1325] Le copilote annonçait « ce que tu peux te verser » avec le chiffre AVANT IMPÔT. Il
  // promettait donc un revenu que Benjamin ne touche jamais. On annonce désormais le NET (URSSAF +
  // impôt payés) — le seul comparable à un salaire — et on détaille les paliers en dessous.
  const net=R.revHoraireNet, apres=R.revHoraireApresCotis, avant=R.revHoraireAvantCotis;
  const val = net!=null ? net : (apres!=null ? apres : avant);
  const tone = val==null?'':val>=15?'ok':val>=10?'':'warn';
  return aiSay(`${aiHero(val!=null?`${euro(val)}/h`:'—', 'Ce que tu te verses vraiment', {sub:`net d'URSSAF et d'impôt · sur ${Math.round(R.heures)} h pointées (90 j)`, color: val==null?'var(--bordeaux)':val>=15?'#2e7d32':val>=10?'var(--bordeaux)':'#b3261e'})}
    ${aiSynth(val!=null&&val>=15?'Un bon niveau, ton travail est correctement valorisé.':val!=null&&val>=10?'Correct, mais il y a de la marge pour mieux te rémunérer.':'Faible pour l\'instant — tes ventes ou tes prix ne couvrent pas encore bien ton temps.', {icon:'⏱️', tone: val!=null&&val>=15?'ok':val!=null&&val<10?'warn':''})}
    ${aiDetails(`
      <div class="sum-box"><span>Avant prélèvements</span><b>${avant!=null?euro(avant)+'/h':'—'}</b></div>
      <div class="sum-box"><span>Après cotisations URSSAF</span><b>${apres!=null?euro(apres)+'/h':'—'}</b></div>
      <div class="sum-box"><span><b>Après impôt — ce qu'il te reste</b></span><b>${net!=null?euro(net)+'/h':'—'}</b></div>
      <div class="sum-box"><span>Marge avant rému.</span><b>${euro(R.margeAvantRemu||0)}</b></div>
      <div class="sum-box"><span>Charges fixes</span><b>${euro(R.chargesFixes||0)}</b></div>`,'Détail du calcul')}
    ${aiSuite([{label:'📈 Comment gagner plus ?', ask:'comment je peux gagner plus'}])}`);
}

// [V944] SEUIL DE RENTABILITÉ / POINT MORT. Source : revenuHoraireCalcul (chargesFixes + cotisations).
async function aiQuerySeuilRentabilite(params){
  params = params || {};
  let R=null; try{ R=await revenuHoraireCalcul(30); }catch(e){swallow(e,'aiQuerySeuilRentabilite')}
  if(!R) return aiSay(`${aiHero('—', 'Seuil de rentabilité')}${aiSynth('Calcul indisponible pour le moment.', {icon:'⏳'})}`);
  let charges=+R.chargesFixes||0;

  // [v1342] POINT MORT SUR UNE SEMAINE — charges fixes PRORATISÉES (convention de Ben).
  // Les charges (URSSAF, IR, abonnements) sont MENSUELLES : un point mort hebdomadaire n'a de sens
  // qu'avec une convention de proratisation. Elle est APPLIQUÉE ET AFFICHÉE — jamais silencieuse.
  // Une convention qu'on n'écrit pas à l'écran devient, six mois plus tard, un chiffre qu'on ne sait
  // plus lire (et qu'on finit par croire mesuré).
  //
  // Le prorata est calculé JOUR PAR JOUR : une semaine ISO peut chevaucher deux mois (S40-2025 =
  // 29 sept → 5 oct), dont les charges n'ont aucune raison d'être égales. Prendre « le mois du lundi »
  // serait plus simple et faux une semaine sur quatre (testé : 70 € au lieu de 120 €, soit 42 % d'écart).
  let _prorataNote = '';
  const _iv = params.intervalle;
  if(_iv && _iv.kind === 'semaine'){
    const _cpm = {};
    try{ _cpm[_iv.depuis.slice(0,7)] = charges; _cpm[_iv.jusqu.slice(0,7)] = charges; }catch(e){swallow(e,'seuil prorata');}
    const P = _aiProrataChargesFixes(_iv.depuis, _iv.jusqu, _cpm);
    charges = P.total;
    _prorataNote = `<p class="note" style="margin-top:8px">Charges <b>proratisées</b> sur la ${esc(_iv.label)} : ${euro(charges)}${P.moisChevauches>1?` (la semaine chevauche ${P.moisChevauches} mois — chaque jour porte la charge quotidienne de <b>son</b> mois)`:''}. Tes charges sont mensuelles : ce point mort hebdomadaire repose sur cette convention, pas sur une mesure.</p>`;
  }
  // Marge unitaire moyenne par macaron : prix de vente moyen − coût matière moyen.
  const prix=(typeof computeAvgSellPrice==='function')?(computeAvgSellPrice({orders:[], markets:[], settings:getSettings()}).prix||2):2;
  // Estimation simple du coût matière unitaire via le ratio coûts/CA observé.
  const ca=+R.caEncaisse||0; const coutMat=+R.coutMatieres||0;
  const ratioMat = ca>0 ? coutMat/ca : 0.25;
  const margeUnit = Math.max(0.01, prix*(1-ratioMat));
  const seuilPieces = margeUnit>0 ? Math.ceil(charges/margeUnit) : null;
  const heroSeuil = seuilPieces!=null?`${qty(seuilPieces)} macarons`:'—';
  const subSeuil = (_iv && _iv.kind==='semaine') ? `charges proratisées ${euro(charges)}` : `charges du mois ${euro(charges)}`;
  return aiSay(`${aiHero(heroSeuil, 'À vendre pour couvrir tes charges', {sub:subSeuil, color:'var(--bordeaux)'})}
    ${aiSynth(`Au-delà de ${seuilPieces!=null?qty(seuilPieces):'?'} macarons vendus ${(_iv&&_iv.kind==='semaine')?`sur la ${esc(_iv.label)}`:'ce mois'}, chaque vente commence à te rémunérer.`,{icon:'🎯'})}
    ${_prorataNote}
    ${aiDetails(`
      <div class="sum-box"><span>Charges fixes du mois</span><b>${euro(charges)}</b></div>
      <div class="sum-box"><span>Marge par macaron (est.)</span><b>${euro(margeUnit)}</b></div>
      <div class="sum-box"><span>Prix de vente moyen</span><b>${euro(prix)}</b></div>
      <p class="note" style="margin-top:6px">Estimation : charges fixes ÷ marge unitaire. La marge matière vient de ton ratio coûts/CA.</p>`,'Détail du calcul')}
    ${aiSuite([{label:'⏱️ Mon revenu horaire', ask:'mon revenu horaire'}])}`);
}

