// [V943] PRÉVISION DE VENTES (ce qui va partir) — réutilise computeSalesVelocity (vélocité = demande).
async function aiQueryPrevision(){
  let V=null; try{ V=await computeSalesVelocity({months:3, horizonDays:14}); }catch(e){swallow(e,'aiQueryPrevision')}
  const lignes=(V&&V.lignes)?V.lignes.filter(l=>l.perDay>0).sort((a,b)=>b.perDay-a.perDay):[];
  if(!lignes.length) return aiSay(`${aiHero('—', 'Prévision de ventes')}${aiSynth('Pas encore assez d\'historique de ventes pour prévoir la demande.',{icon:'📈'})}`);
  const top=lignes.slice(0,6);
  const t0=top[0];
  return aiSay(`${aiHero(esc(t0.parfum), 'Va le plus se vendre', {color:'var(--caramel)', sub:`~${t0.perMonth}/mois`})}
    ${aiSynth(`Au rythme actuel, c'est <b>${esc(t0.parfum)}</b> qui partira le plus vite${top[1]?`, suivi de <b>${esc(top[1].parfum)}</b>`:''}.`, {icon:'📈'})}
    ${aiDetails(top.map(l=>`<div class="sum-box"><span>${esc(l.parfum)}</span><b>~${l.perMonth}/mois <span style="color:#9a8a82;font-weight:400;font-size:.74rem">(${l.perDay}/j)</span></b></div>`).join(''), 'Voir la prévision complète')}
    ${aiSuite([{label:'📦 Vais-je en manquer ?', ask:'qu\'est-ce qui va bientôt me manquer'}])}`);
}

// [V943] COFFRETS / BOÎTES EN STOCK. Source : catalogue produits (coffrets) + stock éventuel.
async function aiQueryStockBoites(params){
  params=params||{};
  let produits=[]; try{ produits=await db.products.toArray(); }catch(e){swallow(e,'aiQueryStockBoites')}
  // On cherche les coffrets/boîtes avec un stock renseigné.
  const boites = produits.filter(p=>/(coffret|boite|boîte)/i.test((p.type||'')+(p.nom||'')) );
  const avecStock = boites.filter(b=>(+b.stock||0)>0 || (+b.qteStock||0)>0);
  const lire = b => (+b.stock||+b.qteStock||0);
  if(!boites.length){
    return aiSay(`${aiSynth('Le stock de coffrets/boîtes n\'est pas suivi dans le catalogue. Gère-le depuis l\'écran Coffrets / Consommables.',{icon:'📦'})}`);
  }
  if(params.taille){
    const hit=boites.find(b=>String(b.nom||'').includes(String(params.taille)) || (+b.taille===+params.taille));
    const q=hit?lire(hit):0;
    return aiSay(`${aiHero(`${qty(q)}`, hit?esc(hit.nom):`Coffret ${params.taille}`,{sub:'en stock', color:q>0?'var(--bordeaux)':'var(--red)'})}${aiSynth(q>0?`Coffrets de ${qty(params.taille)} disponibles.`:`Plus de coffret ${params.taille} en stock.`,{icon:q>0?'📦':'⚠️', tone:q>0?'':'warn'})}`);
  }
  if(!avecStock.length){
    return aiSay(`${aiHero('0', 'Coffrets en stock', {color:'var(--red)'})}${aiSynth('Aucun stock de coffret renseigné. Mets-le à jour depuis l\'écran Coffrets.',{tone:'warn', icon:'📦'})}`);
  }
  const totBoites = avecStock.reduce((sum,b)=>sum+lire(b),0);
  return aiSay(`${aiHero(`${qty(totBoites)} <span style="font-size:1rem;font-weight:600">coffret${totBoites>1?'s':''}</span>`, 'En stock', {color:'var(--bordeaux)'})}
    ${aiSynth(`${avecStock.length} format${avecStock.length>1?'s':''} disponible${avecStock.length>1?'s':''}.`, {icon:'📦'})}
    ${aiDetails(avecStock.map(b=>`<div class="sum-box"><span>${esc(b.nom)}</span><b>${qty(lire(b))}</b></div>`).join(''), 'Voir par format')}
    ${aiSuite([{label:'📦 Gérer les coffrets', view:'boites'}])}`);
}

// [V943] PANIER MOYEN (par client ou global). Source : getClientDashboardData / agrégat commandes.
async function aiQueryPanierMoyen(params){
  params=params||{};
  if(params.client){
    let D=null; try{ D=await getClientDashboardData(params.client.id); }catch(e){swallow(e,'aiQueryPanierMoyen')}
    if(!D || !D.nbCommandes) return aiSay(`${aiHero('—', `Panier moyen — ${esc(params.client.nom||'')}`)}${aiSynth('Aucune commande pour ce client pour l\'instant.', {icon:'📭'})}`);
    return aiSay(`${aiHero(euro(D.panierMoyen), `Panier moyen — ${esc(params.client.nom||'')}`, {sub:`sur ${D.nbCommandes} commande${D.nbCommandes>1?'s':''}`})}
      ${aiSynth(`Montant moyen d'une commande de ${esc(params.client.nom||'ce client')}.`, {icon:'🧺'})}
      ${aiSuite([{label:'👤 Voir sa fiche', ask:`parle-moi de ${params.client.nom||''}`}])}`);
  }
  // Global : moyenne sur toutes les commandes.
  // [FIX v1335] Aucun filtre temporel : « mon panier moyen en mai » renvoyait la moyenne de TOUT
  // l'historique. La v1334 l'avouait au moins ; ici, l'app sait faire.
  // BASE : la date de COMMANDE. Un panier moyen décrit un COMPORTEMENT D'ACHAT — quand le client a
  // commandé — et non une trésorerie. La date d'encaissement serait ici la mauvaise règle : elle
  // rangerait une commande de mai dans le mois où le chèque a été déposé.
  const orders=await db.orders.toArray();
  let _pmYm = null, _pmLbl = '';
  if(/^\d{4}-\d{2}$/.test(params.periode||'')){ _pmYm = params.periode; _pmLbl = ' — ' + monthLabel(_pmYm); }
  // [v1421] Filles exclues : un retrait n'est pas une commande de plus, il écraserait le panier moyen vers le bas.
  const valides=orders.filter(o=>!o.histo && o.commandeMereId==null && (+o.montant||0)>0
                                 && (!_pmYm || (o.date||'').slice(0,7) === _pmYm));
  if(_pmYm && !valides.length){
    return aiSay(`${aiHero('—', `Panier moyen${_pmLbl}`)}${aiSynth(`Aucune commande passée en ${esc(monthLabel(_pmYm))}. Le mois existe, il est simplement vide.`, {icon:'📭'})}`);
  }
  if(!valides.length) return aiSay(`${aiHero('—', 'Panier moyen')}${aiSynth('Pas encore de commandes chiffrées.', {icon:'📭'})}`);
  const total=valides.reduce((s,o)=>s+(+o.montant||0),0);
  const moy=total/valides.length;
  return aiSay(`${aiHero(euro(moy), `Panier moyen${_pmLbl}`, {sub:`sur ${valides.length} commandes`})}
    ${aiSynth('Montant moyen d\'une commande, tous clients confondus.', {icon:'🧺'})}
    ${aiCleLecture('Moyenne sur <b>toutes</b> tes commandes chiffrées (payées ou non), pas seulement les réglées.', {voisins:[{label:'📈 Mon CA', ask:'mon chiffre d\'affaires'},{label:'⭐ Meilleurs clients', ask:'mes meilleurs clients'}]})}
    ${aiSuite([{label:'⭐ Mes meilleurs clients', ask:'mes meilleurs clients'}])}`);
}

// [V943] DONS ET PERTES (gaspillage). Source : marketMoves type don/perte (+ retours = invendus ramenés).
async function aiQueryGaspillage(params){
  params = params || {};
  const [markets, moves] = await Promise.all([
    db.markets.toArray().catch(()=>[]),
    (db.marketMoves?db.marketMoves.toArray():Promise.resolve([])).catch(()=>[])
  ]);
  // [FIX v1334] Le gaspillage agrégeait TOUS les marchés depuis toujours, sans aucune notion de
  // période. « Mon gaspillage en mai » renvoyait donc le cumul de l'historique — et depuis la
  // v1333, l'app l'avouait. Elle sait filtrer, maintenant.
  let ym = null, lbl = 'sur tous tes marchés';
  if(/^\d{4}-\d{2}$/.test(params.periode||'')){ ym = params.periode; lbl = 'en ' + monthLabel(ym); }
  else if(params.periode==='moisCourant'){ ym = monthKey(today()); lbl = 'ce mois-ci'; }
  else if(params.periode==='moisDernier'){ const d=new Date(); d.setMonth(d.getMonth()-1); ym=monthKey(d); lbl='le mois dernier'; }

  const G = gaspillageMarches(markets, moves, ym);

  // DISTINCTION CAPITALE : « aucun marché ce mois-là » n'est PAS « aucun gaspillage ». Le premier
  // est une absence de données, le second une performance. Les confondre serait te féliciter pour
  // un mois où tu n'as simplement rien vendu.
  if(ym && G.nbMarches === 0){
    return aiSay(`${aiSynth(`Tu n'as tenu <b>aucun marché</b> ${lbl}. Il n'y a donc rien à gaspiller — ce n'est pas un bon score, c'est une absence de données.`, {icon:'📭'})}`);
  }
  if(!ym && !moves.length){
    return aiSay(`${aiSynth('Aucun mouvement de marché enregistré : pas de don ni de perte à signaler.',{icon:'♻️',tone:'ok'})}`);
  }

  const total = G.total;
  const tone = total===0?'ok':total<20?'':'warn';
  return aiSay(`${aiHero(`${qty(total)}`, `Macarons donnés ou perdus${ym?' — '+monthLabel(ym):''}`, {sub: total>0?`${qty(G.don)} dons · ${qty(G.perte)} pertes`:'aucun gaspillage', color: total===0?'#2e7d32':(total<20?'var(--bordeaux)':'#b3261e')})}
    ${aiSynth(total===0?`Aucun gaspillage ${lbl}, bravo.`:`${lbl.charAt(0).toUpperCase()+lbl.slice(1)} : ${qty(G.don)} donnés, ${qty(G.perte)} perdus${G.retour>0?`, ${qty(G.retour)} récupérés`:''}.`, {icon:'♻️', tone})}
    ${aiDetails(`<div class="sum-box"><span>Marchés concernés</span><b>${G.nbMarches}</b></div>
      <div class="sum-box"><span>🎁 Dons</span><b>${qty(G.don)}</b></div>
      <div class="sum-box"><span>🗑 Pertes</span><b>${qty(G.perte)}</b></div>
      ${G.retour>0?`<div class="sum-box"><span>↩️ Récupérés</span><b>${qty(G.retour)}</b></div>`:''}`, 'Le détail')}
    <p class="note">Les dons valorisent les invendus (associations) ; les pertes sont du gâchis sec à réduire. Les retours, eux, sont récupérés : ils ne sont PAS du gaspillage.</p>`);
}

async function aiQueryProchaineLivraison(){
  const orders = await db.orders.toArray();
  const clients = await db.clients.toArray().catch(()=>[]);
  const clName = id => (clients.find(c=>c.id===id)||{}).nom || 'Client';
  const aVenir = orders
    .filter(o=> !o.histo && normStatus(o.statut)!=='Livrée')
    .map(o=>({o, ref:_orderRefDate(o)}))
    .filter(x=>x.ref)
    .sort((a,b)=> a.ref.localeCompare(b.ref));
  // On ne garde que les livraisons d'aujourd'hui ou futures (les passées non livrées = retards, traités ailleurs).
  const td = today();
  const futures = aVenir.filter(x=> x.ref >= td);
  if(!futures.length){
    // Peut-être des commandes en retard ? On le signale plutôt que de dire « rien ».
    const retards = aVenir.filter(x=> x.ref < td);
    if(retards.length){
      const r=retards[retards.length-1]; // la plus récente échue
      const dans=(typeof daysTo==='function')?daysTo(r.ref):null;
      return aiSay(`        ${aiSynth(`Aucune livraison à venir, mais <b>${retards.length} commande${retards.length>1?'s'  :''} en retard</b> ${retards.length>1?'restent':'reste'} à livrer.`, {icon:'⚠️', tone:'warn'})}
        <p class="note">La plus ancienne : ${esc(clName(r.o.clientId))}, prévue le ${fmtDate(r.ref)}${dans!=null?` (il y a ${-dans} j)`:''}.</p>`);
    }
    return aiSay(`      ${aiSynth(`Aucune livraison programmée pour le moment.`, {icon:'📦'})}`);
  }
  const p = futures[0];
  const dans = (typeof daysTo==='function') ? daysTo(p.ref) : null;
  const quand = dans==null ? '' : dans===0 ? "aujourd'hui" : dans===1 ? 'demain' : `dans ${dans} jours`;
  const col = dans!=null && dans<=1 ? '#b3261e' : dans!=null && dans<=3 ? '#caa23b' : 'var(--bordeaux)';
  const heure = p.o.heureLivraison ? ` à ${esc(p.o.heureLivraison)}` : '';
  const lieu  = p.o.lieuLivraison ? `${esc(p.o.lieuLivraison)}` : '';
  let contenu=''; try{ const ls=orderToLines(p.o); contenu = ls.length ? ls.map(lineLabel).join(' + ') : ''; }catch(e){swallow(e,'aiQueryProchaineLivraison')}
  // Combien d'autres livraisons suivent, pour le contexte.
  const autres = futures.length-1;
  return aiSay(`    ${aiHero(quand?quand.charAt(0).toUpperCase()+quand.slice(1):fmtDate(p.ref), `${esc(clName(p.o.clientId))}`, {color:col, sub:`${fmtDate(p.ref)}${heure}${lieu?` · ${lieu}`:''}`})}
    ${contenu?`<div class="sum-box"><span>À livrer</span><b style="font-weight:600">${esc(contenu)}</b></div>`:''}
    ${autres>0?`<p class="note">${autres} autre${autres>1?'s':''} livraison${autres>1?'s':''} ${autres>1?'suivent':'suit'} ensuite.</p>`:'<p class="note">C\'est ta seule livraison programmée.</p>'}
    ${aiSuite([{label:'📋 Toutes mes commandes', view:'commandes'},{label:'🏭 Suis-je dans les temps ?', ask:'est-ce que je suis dans les temps'}])}`);
}
async function aiQueryDelivery(params){
  const c = params && params.client;
  if(!c) return aiSay(`<p class="note">Je n'ai pas identifié de client. Essaie « quand livrer la commande de [nom] ».</p>`);
  const orders = await db.orders.toArray();
  const td = today();
  // Commandes du client, non livrées, triées par date de référence (livraison/événement).
  const siennes = orders
    .filter(o=> +o.clientId === +c.id && normStatus(o.statut)!=='Livrée')
    .map(o=>({o, ref:_orderRefDate(o)}))
    .filter(x=>x.ref)
    .sort((a,b)=> a.ref.localeCompare(b.ref));
  if(!siennes.length){
    return aiSay(`<h3 style="font-size:1rem">Livraisons — ${esc(c.nom)}</h3><p class="note">Aucune commande à livrer pour ${esc(c.nom)} (tout est livré, ou aucune commande enregistrée).</p>`);
  }
  const lignesHtml = siennes.map(({o,ref})=>{
    const dans = (typeof daysTo==='function') ? daysTo(ref) : null;
    const quand = dans==null ? '' : (dans<0 ? `<span style="color:#b3261e;font-weight:600">en retard de ${-dans} j</span>`
                  : dans===0 ? `<span style="color:#b3261e;font-weight:600">aujourd'hui</span>`
                  : dans===1 ? `<span style="color:#b5701a;font-weight:600">demain</span>`
                  : `dans ${dans} j`);
    const heure = o.heureLivraison ? ` à ${esc(o.heureLivraison)}` : '';
    const lieu = o.lieuLivraison ? ` · ${esc(o.lieuLivraison)}` : '';
    let contenu=''; try{ const ls=orderToLines(o); contenu = ls.length ? ls.map(lineLabel).join(' + ') : ''; }catch(e){swallow(e,'aiQueryDelivery')}
    return `<div class="sum-box" style="flex-direction:column;align-items:stretch;gap:2px">
      <div style="display:flex;justify-content:space-between"><span><b>${fmtDate(ref)}</b>${heure}${lieu}</span><span>${quand}</span></div>
      ${contenu?`<div style="font-size:.8rem;color:#6a5a52">${esc(contenu)}</div>`:''}</div>`;
  }).join('');
  const prochaine = siennes[0];
  const dansP = (typeof daysTo==='function') ? daysTo(prochaine.ref) : null;
  const phrase = dansP==null ? '' :
    (dansP<0 ? `La commande de ${esc(c.nom)} était à livrer le ${fmtDate(prochaine.ref)} (en retard).`
     : dansP===0 ? `À livrer aujourd'hui pour ${esc(c.nom)}.`
     : dansP===1 ? `À livrer demain pour ${esc(c.nom)}.`
     : `Prochaine livraison pour ${esc(c.nom)} : le ${fmtDate(prochaine.ref)} (dans ${dansP} j).`);
  aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">📦 Livraisons — ${esc(c.nom)}</h3>
    ${phrase?`<div style="font-size:.86rem;margin-bottom:8px;color:#3f3a44">${phrase}</div>`:''}
    ${lignesHtml}`);
}
// [COCKPIT] CONSEIL MARCHÉ — branche le Copilote sur les moteurs marché existants (sources uniques) :
// marketForecast (historique appris) → marketCrossPlan (volume + argumentaire) → marketVentilation
// (pièces par parfum). Trouve le prochain marché à venir (ou celui de la date demandée). Ne recalcule
// rien : compose les moteurs et explique le « pourquoi » de chaque chiffre.
async function aiQueryMarketAdvice(params){
  const markets = await db.markets.toArray().catch(()=>[]);
  const td = today();
  // Marchés à venir non clos, triés par date croissante.
  const aVenir = markets.filter(m=> m.date && m.date>=td && m.statut!=='clos')
                        .sort((a,b)=>(a.date||'').localeCompare(b.date||''));
  // Cible : marché à la date demandée si fournie, sinon le plus proche à venir.
  let mk = null;
  if(params && params.date){ mk = aVenir.find(m=>m.date===params.date) || null; }
  if(!mk) mk = aVenir[0] || null;
  if(!mk){
    return aiSay(`<p class="note">Aucun marché à venir n'est programmé${params&&params.date?` pour le ${fmtDate(params.date)}`:''}. Crée un marché dans l'onglet Marchés pour obtenir un conseil de préparation.</p>`);
  }
  // Moteurs (sources uniques, déjà éprouvés).
  let fc=null; try{ fc = await marketForecast(); }catch(e){swallow(e,'aiQueryMarketAdvice')}
  const settings = (typeof getSettings==='function') ? getSettings() : {};
  const cible = Array.isArray(settings.marketMix) ? settings.marketMix : [];
  const histo = (fc && Array.isArray(fc.repartition)) ? fc.repartition : [];
  const cross = marketCrossPlan(+mk.prevuQte||0, fc, {mode:'croise', fraisPct:30});
  const ventil = marketVentilation(cible, histo, cross.volume, {mode:'croise'});
  const lignes = (ventil.lignes||[]).filter(l=>l.pieces>0);

  const lieu = mk.lieu ? ` · ${esc(mk.lieu)}` : '';
  const titre = `${esc(mk.nom||'Marché')}${lieu} — ${fmtDate(mk.date)}`;

  // Détail par parfum, avec l'origine de chaque pourcentage (transparence = ton argumentaire).
  const detailParfums = lignes.length
    ? lignes.map(l=>{
        const src = (l.pctCible!=null && l.pctHisto!=null)
          ? `ta cible ${l.pctCible}% × historique ${l.pctHisto}%`
          : (l.pctHisto!=null ? `historique ${l.pctHisto}%` : (l.pctCible!=null ? `ta cible ${l.pctCible}%` : ''));
        return `<div class="sum-box"><span><b>${esc(l.parfum)}</b> <span style="color:#9a8a82;font-size:.78rem">${src?`(${src})`:''}</span></span><b>${l.pieces} pc</b></div>`;
      }).join('')
    : `<p class="note">Pas encore de répartition par parfum (définis ta cible dans les réglages Marchés, ou clôture quelques marchés pour bâtir l'historique).</p>`;

  aiSay(`<h3 style="font-size:1rem;margin-bottom:6px">🛒 Conseil pour ${titre}</h3>
    <div style="background:#f3eef7;border:1px solid #d9c9e6;border-radius:10px;padding:9px 11px;margin-bottom:8px">
      <div style="font-size:1.05rem;font-weight:700;color:#5b3a78">À emmener : ${cross.volume} pièces</div>
      <div style="font-size:.8rem;color:#6a5a72;margin-top:3px">dont ${cross.frais} frais + ${cross.congele} congelés</div>
    </div>
    <div style="font-size:.82rem;color:#5a4a52;margin-bottom:8px">💡 ${esc(cross.explication)}</div>
    <div style="font-weight:600;font-size:.9rem;margin:8px 0 4px">Répartition conseillée par parfum</div>
    ${detailParfums}
    ${fc&&fc.nbMarches>0?`<p class="note" style="margin-top:8px">Basé sur tes <b>${fc.nbMarches}</b> marché(s) passé(s) (moyenne ${fc.moyenneVendu} pc/marché).</p>`:''}`);
}
// [v1070] ---- RÉPONSES CONVERSATIONNELLES (small talk) ----
// Variation aléatoire des formulations pour un ton vivant, pas robotique.
function _aiPick(arr){ return arr[Math.floor(Math.random()*arr.length)]; }
async function aiQueryGreeting(){
  const h = new Date().getHours();
  const moment = h<6?'':(h<12?'Bonne matinée':(h<18?'Bel après-midi':'Bonne soirée'));
  const saluts = ['Salut Benjamin !','Hello Benjamin !','Coucou !','Bonjour !'];
  const relances = [
    'Qu\'est-ce que je peux faire pour toi ?',
    'On regarde quoi aujourd\'hui ?',
    'Dis-moi ce qu\'il te faut.',
    'Par quoi on commence ?'
  ];
  return aiSay(`${aiSynth(`${_aiPick(saluts)} ${moment?moment+'. ':''}${_aiPick(relances)}`, {icon:'👋'})}
    <p class="note" style="margin-top:6px">Tu peux me demander tes ventes, ton stock, ce qui est en retard, ce qu'il te reste dans la poche, où tu en es des seuils… en langage normal.</p>`,
    [{label:'📋 Ma journée', view:'assistant', ask:'par quoi je commence'},{label:'💰 Mon net', view:'netpoche'}]);
}
