/* ============================================================
   IMPRESSION D'ÉTIQUETTES THERMIQUES 50×25 mm via AirPrint
   Architecture : buildLabelData (données) → renderLabelHTML (1 étiquette)
   → printLabelSheet (feuille de N étiquettes, 1 par page 50×25).
   Web Bluetooth volontairement écarté : non supporté par Safari iOS.
   Un backend Bluetooth/ESC-POS pourra se brancher ici plus tard (Android/desktop).
   ============================================================ */
// Prépare les données d'étiquette d'un batch de production.

/* ===== ÉTIQUETTE → IMAGE PARTAGEABLE (pour l'app Phomemo) =====
   Le Bluetooth direct est impossible depuis une PWA iOS. On génère donc l'étiquette
   comme une IMAGE PNG haute résolution (format 50×25 mm), que l'utilisateur partage
   vers l'app Phomemo (qui gère elle-même l'impression Bluetooth de l'imprimante). */

// Dessine une étiquette sur un canvas et renvoie le canvas (50×25 mm @ ~12 px/mm = 600×300).
async function labelToCanvas(d){
  // Format Phomemo D520BT : 105 × 55 mm à 203 dpi (résolution réelle de l'imprimante).
  // Taille pixel EXACTE → Labelife imprime sans recadrage ni réglage de dimensions.
  const DPI = 203;
  const mm = v => Math.round(v / 25.4 * DPI);
  const W = mm(105), H = mm(55);   // 839 × 440
  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  const ctx = cv.getContext('2d');
  ctx.fillStyle = '#fff'; ctx.fillRect(0,0,W,H);
  ctx.fillStyle = '#000';
  const pad = mm(4), gap = mm(4);
  // QR à gauche, carré 30 mm, centré verticalement.
  const qr = mm(30), qrY = Math.round((H - qr)/2);
  if(d.qr){
    await new Promise(res=>{
      const img = new Image();
      img.onload = ()=>{ ctx.imageSmoothingEnabled=false; ctx.drawImage(img, pad, qrY, qr, qr); res(); };
      img.onerror = ()=>res();
      img.src = d.qr;
    });
  }
  // Zone texte à droite (large : ~63 mm).
  const tx = pad + qr + gap;
  const tw = W - tx - pad;
  let y = mm(7);
  const drawLine = (txt, sizeMm, bold, gapAfterMm)=>{
    ctx.font = `${bold?'bold ':''}${mm(sizeMm)}px Arial, Helvetica, sans-serif`;
    let s = String(txt==null?'':txt);
    while(s.length>1 && ctx.measureText(s).width > tw){ s = s.slice(0,-1); }
    if(s.length<String(txt==null?'':txt).length && s.length>1){ s = s.slice(0,-1)+'…'; }
    ctx.fillText(s, tx, y);
    y += mm(sizeMm) + mm(gapAfterMm!=null?gapAfterMm:2);
  };
  ctx.textBaseline = 'top';
  // TITRE : nom (vrai stade du batch) + pastille emplacement, AUTO-RÉTRÉCI pour tout afficher
  // (police 7 mm réduite jusqu'à 4.2 mm si besoin, sans jamais tronquer le nom).
  const titre = d.produit + (d.empLettre?'  ['+d.empLettre+']':'');
  let titleMm = 7;
  ctx.font = 'bold '+mm(titleMm)+'px Arial, Helvetica, sans-serif';
  while(titleMm > 4.2 && ctx.measureText(titre).width > tw){
    titleMm -= 0.2;
    ctx.font = 'bold '+mm(titleMm)+'px Arial, Helvetica, sans-serif';
  }
  ctx.fillText(titre, tx, y);
  y += mm(titleMm) + mm(4);
  // [v1458] BANDEAU « RETOUR MARCHÉ » — placé juste sous le nom, avant le lot : c'est la première
  // chose à savoir sur ces macarons (revenus d'un marché, provenance non identifiée). En haut et
  // en gras, il reste lisible même si l'étiquette est en partie masquée dans une pile.
  if(d.retourMarche) drawLine('↩ RETOUR MARCHÉ', 5, true, 3);
  drawLine('Lot : '+d.lot, 4.5, false, 3);
  if(d.nbPieces!=null) drawLine((typeof qty==='function'?qty(d.nbPieces):d.nbPieces)+' pièces', 4.5, false, 3);
  if(d.emplacement) drawLine('Empl. : '+d.emplacement, 4.5, false, 3);
  drawLine('Fab. : '+d.fab, 4.5, false, 4);
  // DLC en gras (info critique, en évidence).
  drawLine('DLC : '+d.dlc, 6, true, 0);
  return cv;
}

// Génère l'image d'étiquette d'un batch et la partage (ou la télécharge en repli).
// ===================== ÉTIQUETTE EN PDF (pour partage direct vers Labelife) =====================
// Labelife (app Phomemo) accepte l'import d'un PDF via le partage iOS — mais souvent PAS une image PNG.
// On enrobe donc le canvas d'étiquette (105×55 mm) dans un PDF minimal valide, sans dépendance externe,
// puis on le partage via navigator.share. Si Labelife apparaît dans la feuille de partage, l'envoi est direct.

// ====================================================================================
async function _htmlToA4Canvases(htmlDoc, opts){
  opts = opts || {};
  const A4_W_MM = 210, A4_H_MM = 297;
  const SCALE = opts.scale || 2;                 // densité (2 = ~150 dpi, bon compromis netteté/poids)
  const pxW = Math.round(A4_W_MM / 25.4 * 96 * SCALE);   // largeur cible en px
  const pxPageH = Math.round(A4_H_MM / 25.4 * 96 * SCALE);

  // 1) On rend le HTML dans un conteneur hors-écran à la bonne largeur (en px CSS, avant scale).
  const cssW = Math.round(A4_W_MM / 25.4 * 96);  // 793 px ≈ A4 à 96 dpi
  const holder = document.createElement('div');
  holder.style.cssText = `position:fixed;left:-99999px;top:0;width:${cssW}px;background:#fff;z-index:-1`;
  // On extrait le <body> du document fourni (le HTML complet contient <html><head><style>…).
  // Pour conserver les styles, on injecte le doc entier dans une iframe, puis on mesure sa hauteur.
  const iframe = document.createElement('iframe');
  iframe.style.cssText = `position:fixed;left:-99999px;top:0;width:${cssW}px;height:10px;border:0;background:#fff`;
  document.body.appendChild(iframe);
  const idoc = iframe.contentWindow.document;
  idoc.open(); idoc.write(htmlDoc); idoc.close();
  // Laisser le navigateur poser la mise en page et charger la police embarquée.
  await new Promise(r=> setTimeout(r, opts.delay||350));
  const body = idoc.body;
  const fullH = Math.max(body.scrollHeight, body.offsetHeight, idoc.documentElement.scrollHeight);

  // 2) Sérialiser le contenu rendu en XHTML pour le <foreignObject>.
  //    On clone le <html> de l'iframe (avec ses styles) dans le SVG.
  const htmlClone = idoc.documentElement.cloneNode(true);
  // s'assurer du namespace XHTML
  htmlClone.setAttribute('xmlns','http://www.w3.org/1999/xhtml');
  const serialized = new XMLSerializer().serializeToString(htmlClone);

  // 3) Découpe en pages A4 : on rasterise des bandes successives de hauteur = 1 page.
  const pageHcss = Math.round(A4_H_MM / 25.4 * 96);   // hauteur d'une page A4 en px CSS (~1122)
  const nbPages = Math.max(1, Math.ceil(fullH / pageHcss));
  const canvases = [];
  for(let p=0; p<nbPages; p++){
    const yOff = p * pageHcss;
    // SVG qui décale le contenu vers le haut de yOff, dans une fenêtre de la taille d'une page.
    const svg =
      `<svg xmlns="http://www.w3.org/2000/svg" width="${cssW}" height="${pageHcss}">`+
      `<foreignObject x="0" y="${-yOff}" width="${cssW}" height="${fullH}">`+
      serialized+
      `</foreignObject></svg>`;
    const img = new Image();
    const svgBlob = new Blob([svg], {type:'image/svg+xml;charset=utf-8'});
    const url = URL.createObjectURL(svgBlob);
    try{
      await new Promise((res,rej)=>{
        const to = setTimeout(()=>rej(new Error('svg img timeout')), 6000);  // [v1084] anti-blocage iOS
        img.onload=()=>{ clearTimeout(to); res(); };
        img.onerror=()=>{ clearTimeout(to); rej(new Error('svg img load')); };
        img.src=url;
      });
      const cv = document.createElement('canvas');
      cv.width = pxW; cv.height = pxPageH;
      const ctx = cv.getContext('2d');
      ctx.fillStyle = '#fff'; ctx.fillRect(0,0,cv.width,cv.height);
      ctx.drawImage(img, 0, 0, pxW, pxPageH);
      canvases.push(cv);
    } finally { URL.revokeObjectURL(url); }
  }
  document.body.removeChild(iframe);
  return { canvases, A4_W_MM, A4_H_MM };
}

// Génère un Blob PDF (A4, 1+ pages) à partir d'un document HTML. Retourne {blob, fileName?}.
async function htmlToPdfBlob(htmlDoc, opts){
  opts = opts || {};
  const { canvases, A4_W_MM, A4_H_MM } = await _htmlToA4Canvases(htmlDoc, opts);
  if(!canvases.length) throw new Error('rendu vide');
  const jpegList = canvases.map(cv=> _dataURLtoBytes(cv.toDataURL('image/jpeg', opts.quality||0.9)));
  const pxW = canvases[0].width, pxH = canvases[0].height;
  const pdfBytes = (jpegList.length===1)
    ? _buildSingleImagePDF(jpegList[0], A4_W_MM, A4_H_MM, pxW, pxH)
    : _buildMultiImagePDF(jpegList, A4_W_MM, A4_H_MM, pxW, pxH);
  return new Blob([pdfBytes], {type:'application/pdf'});
}

// Partage un document HTML en PDF (mail/AirDrop/…) avec un OBJET maîtrisé (= titre du partage).
// Fallback : téléchargement du PDF si le partage de fichier n'est pas disponible.
async function sharePdfFromHtml(htmlDoc, fileName, shareTitle, shareText){
  let etape = 'init';
  try{
    if(!htmlDoc || typeof htmlDoc!=='string' || htmlDoc.length<20){
      throw new Error('document HTML vide ou invalide');
    }
    etape = 'rendu PDF';
    const blob = await htmlToPdfBlob(htmlDoc, {});
    etape = 'fichier';
    const safeName = (fileName||'document').replace(/[^\w.-]/g,'_').replace(/\.pdf$/i,'')+'.pdf';
    const file = new File([blob], safeName, {type:'application/pdf'});
    if(navigator.canShare && navigator.canShare({files:[file]})){
      try{
        etape = 'partage';
        await navigator.share({ files:[file], title: shareTitle||safeName, text: shareText||'' });
        return true;
      }catch(eShare){ if(eShare && eShare.name==='AbortError') return false; }
    }
    // Repli : téléchargement direct (l'utilisateur joint ensuite le PDF à son mail).
    etape = 'téléchargement';
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href=url; a.download=safeName;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url), 2000);
    toast('PDF enregistré ✓ joins-le à ton mail');
    return true;
  }catch(e){
    console.error('sharePdfFromHtml @'+etape, e);
    const msg = (e && (e.message||e.name)) ? (e.name?e.name+' : ':'')+(e.message||'') : 'inconnue';
    toast('Erreur PDF ('+etape+') — '+msg);
    return false;
  }
}
// ====================================================================================
function _buildSingleImagePDF(jpegBytes, wMm, hMm, pxW, pxH){
  // 1 mm = 72/25.4 points PDF
  const ptW = (wMm * 72 / 25.4), ptH = (hMm * 72 / 25.4);
  const enc = s => { const out=new Uint8Array(s.length); for(let i=0;i<s.length;i++) out[i]=s.charCodeAt(i)&0xff; return out; };
  const parts = [];
  const offsets = [];
  let pos = 0;
  const push = (bytes) => { parts.push(bytes); pos += bytes.length; };
  const pushStr = (s) => push(enc(s));

  pushStr('%PDF-1.4\n');

  // obj 1 : Catalog
  offsets[1]=pos; pushStr('1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');
  // obj 2 : Pages
  offsets[2]=pos; pushStr('2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n');
  // obj 3 : Page
  offsets[3]=pos; pushStr('3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+ptW.toFixed(2)+' '+ptH.toFixed(2)+
    '] /Resources << /XObject << /Im0 5 0 R >> >> /Contents 4 0 R >>\nendobj\n');
  // obj 4 : Contents (place l'image plein cadre)
  const content = 'q\n'+ptW.toFixed(2)+' 0 0 '+ptH.toFixed(2)+' 0 0 cm\n/Im0 Do\nQ\n';
  offsets[4]=pos; pushStr('4 0 obj\n<< /Length '+content.length+' >>\nstream\n'+content+'endstream\nendobj\n');
  // obj 5 : Image XObject (JPEG = DCTDecode)
  offsets[5]=pos;
  pushStr('5 0 obj\n<< /Type /XObject /Subtype /Image /Width '+pxW+' /Height '+pxH+
    ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+jpegBytes.length+' >>\nstream\n');
  push(jpegBytes);
  pushStr('\nendstream\nendobj\n');

  // xref
  const xrefPos = pos;
  let xref = 'xref\n0 6\n0000000000 65535 f \n';
  for(let i=1;i<=5;i++){ xref += String(offsets[i]).padStart(10,'0')+' 00000 n \n'; }
  pushStr(xref);
  pushStr('trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+xrefPos+'\n%%EOF');

  // concat
  let total=0; parts.forEach(p=>total+=p.length);
  const out=new Uint8Array(total); let o=0;
  parts.forEach(p=>{ out.set(p,o); o+=p.length; });
  return out;
}

// Décode un dataURL base64 (jpeg) en Uint8Array.
function _dataURLtoBytes(dataURL){
  const b64 = dataURL.split(',')[1];
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
  return bytes;
}


// ════════════════════════════════════════════════════════════════════════════
// [v1389] MOTEUR DE RANGEMENT UNIQUE — une seule source de vérité (demande Ben).
//
// RÈGLE ABSOLUE : il n'existe QU'UN moteur de mise en boîte, `prodPreparerBoites`
// (système B), et QU'UNE porte d'entrée UI, `ouvrirRangement`. Tout bouton, menu,
// raccourci ou écran qui veut « ranger / mettre en boîtes » appelle `ouvrirRangement`
// — JAMAIS sa propre logique. Toute 2e voie qui réapparaît est un doublon à refuser
// (garde-fou : tests/v1389-moteur-rangement-unique.test.js).
//
// `ouvrirRangement(prodId)` = LA porte UI. Ouvre l'éditeur d'étiquettes (le point
// d'entrée que Ben préfère), qui appelle le moteur unique à la validation.
// [v1417] LES BOÎTES D'UN MÊME LOT. Un lot mis en boîtes devient : le lot PARENT (qui garde
// l'éventuel reste non réparti) + des lignes-filles portant `etiquetteDe = id du parent`.
// Depuis n'importe laquelle de ces lignes, cette fonction reconstitue la FAMILLE complète —
// c'est ce qui permet à l'écran « Ranger » de montrer TOUTES les boîtes et leur emplacement,
// au lieu de la seule ligne cliquée. Les boîtes absorbées par fusion sont exclues (leur contenu
// vit ailleurs). PURE.
function boitesDuLot(prod, prods){
  if(!prod) return [];
  const parentId = (prod.etiquetteDe!=null) ? +prod.etiquetteDe : +prod.id;
  const famille = (prods||[]).filter(x=>{
    if(!x || prodEstFusionnee(x)) return false;
    if(+x.id === parentId) return round3(+x.qteRestante||0) > 0;   // parent : seulement s'il reste du non-réparti
    return +x.etiquetteDe === parentId;
  });
  // Le parent d'abord (le reste en vrac), puis les boîtes dans l'ordre de leur lot.
  famille.sort((a,b)=>{
    const pa = (+a.id===parentId)?0:1, pb = (+b.id===parentId)?0:1;
    if(pa!==pb) return pa-pb;
    return String(a.lotProduction||'').localeCompare(String(b.lotProduction||''));
  });
  return famille;
}

async function ouvrirRangement(prodId){
  // [v1417] Si ce lot est DÉJÀ en boîtes, on montre d'abord la vue d'ensemble : toutes les
  // boîtes, leur emplacement, et quoi faire de chacune. Sinon (lot encore en vrac), on va
  // directement au formulaire de mise en boîtes — le comportement historique.
  const p = await db.productions.get(prodId).catch(()=>null);
  if(!p){ toast('Lot introuvable'); return; }
  const prods = await db.productions.toArray().catch(()=>[]);
  const famille = boitesDuLot(p, prods);
  const aDesBoites = famille.some(x=>+x.id!==((p.etiquetteDe!=null)?+p.etiquetteDe:+p.id));
  if(aDesBoites) return vueBoitesDuLot(prodId);
  return prodEtiquetteBoites(prodId);
}

// [v1417] VUE D'ENSEMBLE DES BOÎTES D'UN LOT. Demande de Ben : en cliquant « Ranger » depuis
// les DLC de l'accueil, voir TOUTES les boîtes avec leur emplacement et décider quoi faire de
// chacune — au lieu du seul formulaire de découpe de la ligne cliquée.
async function vueBoitesDuLot(prodId){
  const p = await db.productions.get(prodId).catch(()=>null);
  if(!p){ toast('Lot introuvable'); return; }
  const [prods, recipes] = await Promise.all([
    db.productions.toArray().catch(()=>[]),
    db.recipes.toArray().catch(()=>[]),
  ]);
  const famille = boitesDuLot(p, prods);
  // [v1422] Filet : un lot dont il ne reste rien (parent à 0, aucune boîte vivante) donnerait une
  // famille VIDE, donc un écran sans une seule ligne — Ben ne saurait pas s'il a mal cliqué ou si
  // le lot est épuisé. On affiche alors la ligne cliquée telle quelle : elle dit la vérité.
  if(!famille.length) famille.push(p);
  const nom = (typeof prodNomComplet==='function') ? prodNomComplet(p, recipes) : '(produit)';
  const parentId = (p.etiquetteDe!=null) ? +p.etiquetteDe : +p.id;
  const total = round3(famille.reduce((s,x)=>s+(+x.qteRestante||0),0));
  // [v1422] Un lot JAMAIS mis en boîtes a une famille d'UNE ligne : le lot lui-même. On l'affiche
  // quand même (Ben arrive ici depuis une alerte DLC, il doit voir où est son stock), mais sans le
  // vocabulaire des boîtes — parler de « reste non mis en boîte » quand il n'y a pas de boîte
  // décrirait une répartition qui n'existe pas.
  const aDesBoites = famille.some(x=>+x.id!==parentId);
  // Répartition par emplacement, pour lire d'un coup d'œil où est le lot.
  const parEmp = {};
  famille.forEach(x=>{ const k=x.emplacement||'?'; parEmp[k]=(parEmp[k]||0)+1; });
  const repartition = Object.keys(parEmp).map(k=>`${parEmp[k]}×${empLettre(k)}`).join(' · ');
  // Boîtes fusionnables : il faut au moins deux lignes-filles ayant encore du stock (le lot
  // parent n'en est pas une — _fusionValide refuse une ligne sans etiquetteDe, et c'est voulu).
  const fusionnables = famille.filter(x=>x.etiquetteDe!=null && round3(+x.qteRestante||0)>0);

  const lignes = famille.map(x=>{
    const estParent = (+x.id===parentId);
    const dlc = (typeof prodDlcEffective==='function') ? prodDlcEffective(x) : x.dlcProduit;
    // [v1422] On vient des alertes DLC : le nombre de jours restants est L'INFORMATION qui a
    // amené Ben ici. L'afficher sur chaque boîte évite d'avoir à repartir de l'accueil pour
    // savoir LAQUELLE des boîtes est celle qui expire.
    const j = (dlc && typeof daysTo==='function') ? daysTo(dlc) : null;
    const badge = (j==null) ? ''
      : (j<=0 ? ' · <b style="color:#b3261e">DLC dépassée</b>'
              : ` · <b style="color:${j<=2?'#b3261e':'#8a6d3b'}">J−${j}</b>`);
    const peutFusionner = (x.etiquetteDe!=null) && fusionnables.some(y=>+y.id!==+x.id);
    return `<div style="border:1px solid var(--hair,#e7ddd2);border-radius:11px;padding:10px;margin-bottom:7px;background:${estParent&&aDesBoites?'#fdf7ee':'#fff'}">
      <div style="display:flex;justify-content:space-between;gap:8px;align-items:baseline">
        <b style="font-size:.9rem">${esc(x.lotProduction||('#'+x.id))}</b>
        <span style="font-size:.86rem"><b>${qty(x.qteRestante)}</b> pièce(s)</span>
      </div>
      <div style="font-size:.8rem;color:#7a6a62;margin:3px 0 7px">
        ${empIcon(x.emplacement)} ${esc(empNom(x.emplacement))} (${empLettre(x.emplacement)})
        ${dlc?` · DLC ${fmtDate(dlc)}`:''}${badge}
        ${estParent&&aDesBoites?' · <span style="color:#8a6d3b">reste non mis en boîte</span>':''}
      </div>
      <div style="display:flex;gap:5px;flex-wrap:wrap;align-items:center">
        <select id="mv_${x.id}" style="padding:6px;border:1px solid var(--hair,#e7ddd2);border-radius:8px;font-size:.8rem">
          ${_etiqOptionsEmp(x.emplacement)}
        </select>
        <button class="btn ghost sm" onclick="boiteDeplacer(${x.id},${prodId})">↔ Déplacer</button>
        ${peutFusionner?`<button class="btn ghost sm" onclick="boiteFusionner(${x.id},${prodId})">🔀 Fusionner</button>`:''}
        ${peutFusionner?`<button class="btn ghost sm" onclick="boiteTransfererForm(${x.id},${prodId})">⇄ Transférer</button>`:''}
        <button class="btn ghost sm" onclick="closeModal();prodEtiquetteBoites(${x.id})">📦 ${aDesBoites?'Re-répartir':'Mettre en boîtes'}</button>
        <button class="btn ghost sm" onclick="closeModal();traceProd(${x.id})">🕘 Traçabilité</button>
        <button class="btn ghost sm" onclick="closeModal();shareLabelImage(${x.id})" title="Réimprimer l'étiquette avec la quantité et la DLC à jour">🖨 Étiquette</button>
        <button class="btn ghost sm" style="color:#b3261e" onclick="closeModal();declareLossForm(${x.id})">⚠ Perte</button>
      </div>
    </div>`;
  }).join('');

  const entete = aDesBoites
    ? `<b>${famille.length}</b> boîte(s) · <b>${qty(total)}</b> pièce(s) au total${repartition?` · ${esc(repartition)}`:''}.
       Choisis un emplacement puis « Déplacer », ou agis boîte par boîte.`
    : `<b>${qty(total)}</b> pièce(s) · ce lot n'a pas encore été mis en boîtes.
       « Mettre en boîtes » le répartit ; les boîtes créées apparaîtront ensuite ici.`;

  openModal(`<h3>📦 ${aDesBoites?'Boîtes du lot':'Lot'} — ${esc(nom)}</h3>
    <p class="note" style="margin-bottom:10px">${entete}</p>
    ${lignes}
    <div class="modal-actions">
      <button class="btn ghost" style="margin-right:auto" onclick="closeModal({fromPop:true});voirLotDansProductions(${prodId})">📋 Voir dans Productions</button>
      <button class="btn ghost" onclick="closeModal()">Fermer</button>
    </div>`);
}

// [v1422] Fusionner DEPUIS la vue d'ensemble. On ne réécrit pas de moteur : on entre dans le flux
// de fusion existant (v1376) à son étape 2, qui liste les autres boîtes du même lot, valide par
// _fusionValide et exécute par fusionnerBoites. On mémorise seulement PAR OÙ REVENIR, pour que
// Ben retombe sur sa vue d'ensemble une fois la fusion faite au lieu d'un écran vide.
// Le retour est PASSÉ DE MAIN EN MAIN (étape 2 → confirmation → exécution) plutôt que posé dans
// une variable globale : un marqueur global survivrait à une annulation et rouvrirait plus tard
// un écran sans rapport, au milieu d'une fusion lancée depuis un autre endroit.
async function boiteFusionner(boiteId, retourId){
  return fusionEtape2(boiteId, +retourId);
}

// [v1455] FORMULAIRE DE TRANSFERT PARTIEL. Une quantité, une boîte de destination — rien d'autre.
// Le retour est passé de main en main (même raison qu'en fusion ci-dessus : pas de variable
// globale, qui survivrait à une annulation et rouvrirait plus tard un écran sans rapport).
async function boiteTransfererForm(boiteId, retourId){
  const src = await db.productions.get(+boiteId).catch(()=>null);
  if(!src){ toast('Boîte introuvable'); return; }
  const soeurs = await _fusionBoitesDuLot(src.etiquetteDe, +boiteId);
  if(!soeurs.length){ toast('Aucune autre boîte de ce lot pour recevoir le transfert'); return; }
  const dispo = round3(Math.max(0, +src.qteRestante||0));
  const opts = soeurs.map(b=>`<option value="${b.id}">${esc(b.lotProduction||('#'+b.id))} — ${qty(round3(+b.qteRestante||0))} pc · ${esc(empNom(b.emplacement))}</option>`).join('');
  openModal(`<h3>⇄ Transférer des pièces</h3>
    <p class="note">Depuis <b>${esc(src.lotProduction||('#'+src.id))}</b> (${qty(dispo)} pièce(s) disponibles).
    Sert à corriger une erreur de répartition. La DLC de la boîte d'arrivée devient la plus courte des deux.</p>
    <div class="field"><label>Quantité à transférer</label>
      <input type="number" id="tr_qte" min="1" step="1" max="${dispo}" value="1"></div>
    <div class="field"><label>Vers quelle boîte</label>
      <select id="tr_dest">${opts}</select></div>
    <p class="note" style="color:#8a6d3b">Si tu transfères la totalité, la boîte de départ sera archivée (son historique reste consultable).</p>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="boiteTransfererGo(${+boiteId},${retourId!=null?+retourId:'null'})">Transférer</button></div>`);
}
async function boiteTransfererGo(boiteId, retourId){
  const q = +val('tr_qte');
  const dest = +val('tr_dest');
  const r = await transfererEntreBoites(+boiteId, dest, q);
  if(!r.ok){ toast(r.raison || 'Transfert impossible'); return; }
  closeModal();
  toast(r.sourceVidee ? `${qty(r.qte)} pièce(s) transférée(s) ✓ — boîte de départ archivée` : `${qty(r.qte)} pièce(s) transférée(s) ✓`);
  if(retourId!=null && typeof vueBoitesDuLot==='function') vueBoitesDuLot(+retourId);
}

// Déplace UNE boîte vers l'emplacement choisi dans son menu, puis rafraîchit la vue d'ensemble.
async function boiteDeplacer(boiteId, retourId){
  const sel = document.getElementById('mv_'+boiteId);
  if(!sel){ toast('Emplacement introuvable'); return; }
  const ok = await doMoveEmplacement(boiteId, sel.value, {});
  if(ok){ toast('Boîte déplacée ✓'); vueBoitesDuLot(retourId); }
}

// `rangerLot(prodId, boites, opts)` = alias programmatique fin. Tout appelant qui
// range SANS passer par l'UI (plan auto, batch) tape ICI, donc le MÊME moteur.
// Jamais d'écriture placements ailleurs : cette fonction ne fait que déléguer.
async function rangerLot(prodId, boites, opts){
  return prodPreparerBoites(prodId, boites, opts);
}

// ---- UI : définir les boîtes (quantités + destination) avant impression ----
async function prodEtiquetteBoites(prodId){
  const p = await db.productions.get(prodId).catch(()=>null);
  if(!p){ toast('Lot introuvable'); return; }
  const dispo = round3(+p.qteRestante||0);
  if(dispo<=0){ toast('Ce lot n\'a plus de stock à étiqueter'); return; }
  window._etiqDraft = {prodId, dispo, rows:[{qte:dispo, destination:p.emplacement||'frigo'}]};
  _etiqRenderForm();
}
function _etiqOptionsEmp(sel){
  return EMPLACEMENTS.map(e=>`<option value="${e.key}" ${e.key===sel?'selected':''}>${e.icon} ${esc(e.nom)}</option>`).join('');
}
function _etiqRenderForm(){
  const d = window._etiqDraft; if(!d) return;
  const total = round3(d.rows.reduce((s,r)=>s+(+r.qte||0),0));
  const reste = round3(d.dispo-total);
  const rows = d.rows.map((r,i)=>`
    <div style="display:flex;gap:6px;align-items:center;margin-bottom:6px">
      <input type="number" min="0" step="1" value="${r.qte}" style="width:70px;padding:8px;border:1px solid var(--hair,#e7ddd2);border-radius:9px" onchange="_etiqSetQte(${i},this.value)">
      <select style="flex:1;padding:8px;border:1px solid var(--hair,#e7ddd2);border-radius:9px" onchange="_etiqSetDest(${i},this.value)">${_etiqOptionsEmp(r.destination)}</select>
      ${d.rows.length>1?`<button class="btn ghost sm" onclick="_etiqDelRow(${i})">✕</button>`:''}
    </div>`).join('');
  const complet = Math.abs(reste)<1e-9 && total>0;
  openModal(`<h3>🏷 Étiquettes — boîte(s)</h3>
    <p class="note" style="margin-bottom:10px">Stock disponible : <b>${qty(d.dispo)}</b> pièce(s). Répartis en boîtes ; chaque boîte peut aller vers une destination différente (la DLC suit sa vraie destination).</p>
    ${rows}
    <button class="btn ghost sm" onclick="_etiqAddRow()">➕ Ajouter une boîte</button>
    <div class="prlv-sum" style="margin-top:10px;border-top:2px solid var(--hair,#e7ddd2);font-weight:700">
      <span>Réparti ${qty(total)} / ${qty(d.dispo)}</span>
      <b style="color:${complet||reste>0?'#3f7d52':'#b3261e'}">${complet?'✓ complet':reste>0?'reste '+qty(reste)+' (non étiqueté)':'⛔ dépasse le stock'}</b></div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" ${reste<0?'disabled style="opacity:.45"':''} onclick="_etiqValiderGo()">🏷 Étiqueter</button>
    </div>`);
}
function _etiqSetQte(i,v){ const d=window._etiqDraft; if(d&&d.rows[i]){ d.rows[i].qte=round3(+v||0); _etiqRenderForm(); } }
function _etiqSetDest(i,v){ const d=window._etiqDraft; if(d&&d.rows[i]){ d.rows[i].destination=v; } }
function _etiqAddRow(){ const d=window._etiqDraft; if(!d) return; const reste=round3(d.dispo-d.rows.reduce((s,r)=>s+(+r.qte||0),0));
  d.rows.push({qte:Math.max(0,reste), destination:d.rows[d.rows.length-1].destination}); _etiqRenderForm(); }
function _etiqDelRow(i){ const d=window._etiqDraft; if(!d||d.rows.length<=1) return; d.rows.splice(i,1); _etiqRenderForm(); }

async function _etiqValiderGo(){
  const d = window._etiqDraft; if(!d) return;
  const sim = await prodPreparerBoites(d.prodId, d.rows, {simuler:true});
  if(!sim.ok){ toast(sim.raison||'Répartition invalide'); return; }
  try{ await snapshotBackup('avant-etiquette-boites'); }catch(e){swallow(e,'_etiqValiderGo')}
  const res = await prodPreparerBoites(d.prodId, d.rows, {});
  // [v1375] NE PAS fermer le modal ici : `_etiqResultats` REMPLACE son contenu en place. Le
  // `closeModal()` d'avant déclenchait un `history.back()` dont le `popstate` différé refermait le
  // modal de résultats juste après son ouverture — Ben voyait le toast de validation mais « aucun
  // menu » pour imprimer/enregistrer. (Voir la règle gravée dans `_etiqResultats`.)
  window._etiqDraft=null;
  if(!res.ok){ closeModal(); toast(res.raison||'Échec'); return; }
  if(res.simple){
    // cas simple : rien créé, on imprime le lot tel quel comme avant.
    toast('Prêt à imprimer');
    _etiqResultats(res.boxes);
    return;
  }
  if(typeof renderProductionsV2==='function' && view==='productionsv2') renderProductionsV2();
  showUndoToast(`${res.boxes.length} boîte(s) créée(s)`, async ()=>{
    await db.transaction('rw', db.productions, async()=>{
      for(const b of res.boxes){ await db.productions.delete(b.id); }
      const src=await db.productions.get(d.prodId);
      await db.productions.update(d.prodId, {qteRestante: round3((+src.qteRestante||0)+res.boxes.reduce((s,b)=>s+b.qte,0))});
    });
    toast('Boîtes annulées · stock restauré');
    if(typeof renderProductionsV2==='function' && view==='productionsv2') renderProductionsV2();
  });
  _etiqResultats(res.boxes);
}
// Écran de résultats : une ligne par boîte, avec ses boutons d'impression PROPRES
// (réutilise shareLabelPDF/shareLabelImage tels quels — chaque id lit sa propre DLC).
async function _etiqResultats(boxes){
  const rows=[];
  for(const b of boxes){
    const pb = await db.productions.get(b.id).catch(()=>null);
    const e = pb ? empInfo(pb.emplacement) : null;
    const dlc = pb ? (typeof prodDlcEffective==='function'?prodDlcEffective(pb):pb.dlcProduit) : '';
    rows.push(`<div class="prlv-card">
      <div class="prlv-line"><span class="prlv-nom">${e?e.icon+' '+esc(e.nom):''}</span><b>${qty(b.qte)} pc</b></div>
      <span class="prlv-chip">DLC ${dlc?fmtDate(dlc):'—'}</span>
      <div class="prlv-acts">
        <button class="btn ghost sm" onclick="shareLabelPDF(${b.id})">📄 PDF</button>
        <button class="btn ghost sm" onclick="shareLabelImage(${b.id})">🖼 Image</button>
      </div></div>`);
  }
  const html = `<h3>🏷 Étiquettes prêtes</h3>${rows.join('')}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`;
  // ════════════════════════════════════════════════════════════════════════════
  // [v1375] RÈGLE GRAVÉE : ON NE FERME-PUIS-ROUVRE PAS UN MODAL À TRAVERS UN SAUT ASYNC.
  // Quand le formulaire d'étiquetage est déjà ouvert (le cas normal), on REMPLACE son contenu en
  // place plutôt que d'appeler openModal après un closeModal. Sinon le `history.back()` de
  // closeModal émet un `popstate` DIFFÉRÉ qui se déclenche après la ré-ouverture et referme le
  // modal de résultats — le menu Imprimer/Enregistrer disparaissait sous les doigts de Ben.
  // (Cousin direct de v1363 : on n'empile pas les modals ; ici, on ne les fait pas clignoter.)
  // ════════════════════════════════════════════════════════════════════════════
  if(overlay && overlay.classList.contains('show') && modal){ modal.innerHTML = html; }
  else openModal(html);
}

async function shareLabelPDF(prodId){
  try{
    const d = await buildLabelData(prodId);
    if(!d){ toast('Batch introuvable'); return; }
    const cv = await labelToCanvas(d);
    // JPEG (DCTDecode) pour un PDF léger et compatible ; fond blanc déjà dessiné par labelToCanvas.
    const dataURL = cv.toDataURL('image/jpeg', 0.92);
    const jpegBytes = _dataURLtoBytes(dataURL);
    const pdfBytes = _buildSingleImagePDF(jpegBytes, 105, 55, cv.width, cv.height);
    const blob = new Blob([pdfBytes], {type:'application/pdf'});
    const fileName = 'etiquette-'+(d.lot||'lot').replace(/[^\w-]/g,'_')+'.pdf';
    const file = new File([blob], fileName, {type:'application/pdf'});
    if(navigator.canShare && navigator.canShare({files:[file]})){
      try{
        await navigator.share({ files:[file], title:'Étiquette '+d.lot });
        return;
      }catch(eShare){ if(eShare && eShare.name==='AbortError') return; }
    }
    // Repli : téléchargement du PDF (à ouvrir ensuite dans Labelife via « Importer un PDF »).
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = fileName;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url), 2000);
    toast('PDF enregistré — ouvre-le dans Labelife (Importer un PDF)');
  }catch(e){ console.error('shareLabelPDF',e); toast('Erreur lors de la génération du PDF'); }
}
// =============================================================================

// ===================== ÉTIQUETTES GROUPÉES → PDF MULTI-PAGES (pour Labelife) =====================
// Génère UN SEUL PDF de plusieurs étiquettes (1 page = 1 étiquette, 105×55 mm). On ne récupère le
// fichier qu'UNE fois dans Labelife pour imprimer toute la série. Chaque lot : nb d'étiquettes (copies)
// et nb de pièces affiché (override) réglables indépendamment.

// Construit un PDF multi-pages à partir d'une liste d'images JPEG (Uint8Array), toutes au même format mm.
function _buildMultiImagePDF(jpegList, wMm, hMm, pxW, pxH){
  const ptW = (wMm * 72 / 25.4), ptH = (hMm * 72 / 25.4);
  const enc = s => { const out=new Uint8Array(s.length); for(let i=0;i<s.length;i++) out[i]=s.charCodeAt(i)&0xff; return out; };
  const parts=[]; const offsets=[]; let pos=0;
  const push=b=>{ parts.push(b); pos+=b.length; };
  const pushStr=s=>push(enc(s));
  const n = jpegList.length;

  pushStr('%PDF-1.4\n');
  // Numérotation des objets :
  // 1 = Catalog, 2 = Pages, puis pour chaque page i (0..n-1) :
  //   page obj   = 3 + i*3
  //   content    = 4 + i*3
  //   image      = 5 + i*3
  const pageObjNum = i => 3 + i*3;
  const contentObjNum = i => 4 + i*3;
  const imageObjNum = i => 5 + i*3;

  offsets[1]=pos; pushStr('1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');
  // Pages : liste des kids
  let kids='';
  for(let i=0;i<n;i++) kids += pageObjNum(i)+' 0 R ';
  offsets[2]=pos; pushStr('2 0 obj\n<< /Type /Pages /Kids ['+kids.trim()+'] /Count '+n+' >>\nendobj\n');

  for(let i=0;i<n;i++){
    const pn=pageObjNum(i), cn=contentObjNum(i), imn=imageObjNum(i);
    // Page
    offsets[pn]=pos;
    pushStr(pn+' 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+ptW.toFixed(2)+' '+ptH.toFixed(2)+
      '] /Resources << /XObject << /Im'+i+' '+imn+' 0 R >> >> /Contents '+cn+' 0 R >>\nendobj\n');
    // Content
    const content='q\n'+ptW.toFixed(2)+' 0 0 '+ptH.toFixed(2)+' 0 0 cm\n/Im'+i+' Do\nQ\n';
    offsets[cn]=pos;
    pushStr(cn+' 0 obj\n<< /Length '+content.length+' >>\nstream\n'+content+'endstream\nendobj\n');
    // Image
    const jpeg=jpegList[i];
    offsets[imn]=pos;
    pushStr(imn+' 0 obj\n<< /Type /XObject /Subtype /Image /Width '+pxW+' /Height '+pxH+
      ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+jpeg.length+' >>\nstream\n');
    push(jpeg);
    pushStr('\nendstream\nendobj\n');
  }

  const totalObjs = 2 + n*3;
  const xrefPos=pos;
  let xref='xref\n0 '+(totalObjs+1)+'\n0000000000 65535 f \n';
  for(let i=1;i<=totalObjs;i++){ xref += String(offsets[i]||0).padStart(10,'0')+' 00000 n \n'; }
  pushStr(xref);
  pushStr('trailer\n<< /Size '+(totalObjs+1)+' /Root 1 0 R >>\nstartxref\n'+xrefPos+'\n%%EOF');

  let total=0; parts.forEach(p=>total+=p.length);
  const out=new Uint8Array(total); let o=0; parts.forEach(p=>{ out.set(p,o); o+=p.length; });
  return out;
}

// items : [{prodId, copies, nbPieces}]. Génère et partage le PDF groupé.
async function buildLabelsPDF(items){
  if(!items || !items.length){ toast('Aucune étiquette sélectionnée'); return; }
  const jpegList=[]; let pxW=839, pxH=440;
  for(const it of items){
    const d = await buildLabelData(it.prodId);
    if(!d) continue;
    if(it.nbPieces!=null && it.nbPieces!=='' && !isNaN(+it.nbPieces)) d.nbPieces = +it.nbPieces; // override pièces/boîte
    const cv = await labelToCanvas(d);
    pxW=cv.width; pxH=cv.height;
    const dataURL = cv.toDataURL('image/jpeg', 0.92);
    const bytes = _dataURLtoBytes(dataURL);
    const copies = Math.max(1, +it.copies||1);
    for(let c=0;c<copies;c++) jpegList.push(bytes);
  }
  if(!jpegList.length){ toast('Rien à générer'); return; }
  const pdfBytes = _buildMultiImagePDF(jpegList, 105, 55, pxW, pxH);
  const blob = new Blob([pdfBytes], {type:'application/pdf'});
  const fileName = 'etiquettes-'+jpegList.length+'-'+(today())+'.pdf';
  const file = new File([blob], fileName, {type:'application/pdf'});
  if(navigator.canShare && navigator.canShare({files:[file]})){
    try{ await navigator.share({ files:[file], title:'Étiquettes ('+jpegList.length+')' }); return; }
    catch(eShare){ if(eShare && eShare.name==='AbortError') return; }
  }
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href=url; a.download=fileName;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url), 2000);
  toast(jpegList.length+' étiquette(s) dans le PDF — ouvre-le dans Labelife');
}
// =============================================================================

// ----- UI : sélection des lots pour le PDF d'étiquettes groupées -----

// ════════════════════════════════════════════════════════════════════════════
//  [v1358] ÉTIQUETTES → BOÎTES → RANGEMENT, EN UN SEUL GESTE
//
//  Ben : « J'aimerais pouvoir choisir autant de boîtes que nécessaire pour chaque parfum. […]
//  En remplissant ces cases ça recréerait automatiquement les boîtes qui vont avec ! Le rangement
//  serait aussi ajouté à côté de chaque ligne. […] Dans le cas de lignes ayant plusieurs impressions
//  (3×20), au moment d'imprimer, demander confirmation que les 3 boîtes vont au même endroit.
//  Si non, proposer un dispatch individuel. »
//
//  CE QUE ÇA CHANGE : l'écran d'étiquettes n'imprime plus seulement — il RANGE. C'est le même geste
//  physique (on étiquette la boîte au moment où on la remplit), donc c'est le même geste dans l'app.
//
//  CE QUE JE RÉUTILISE, ET POURQUOI C'EST CAPITAL :
//   • `p.placements[]` — le modèle prévoit DÉJÀ le multi-boîtes (ligne 8981 : « ⊟ dispatché »).
//     Le besoin de Ben n'est pas une nouveauté du modèle : il était juste inaccessible depuis ici.
//   • `doMoveEmplacement()` — porte les règles de SÉCURITÉ ALIMENTAIRE (anti-recongélation, chaîne
//     du froid). Écrire un second chemin de rangement qui les contourne serait la pire régression
//     possible de toute cette série : un bug de données se corrige, une recongélation non.
//
//  RÈGLE (v1358) : UN SECOND CHEMIN VERS LA MÊME ÉCRITURE FINIT TOUJOURS PAR DIVERGER DU PREMIER.
//  On ne duplique pas `partFlowApply` : on écrit dans `placements[]` par le MÊME modèle, et on
//  passe par `doMoveEmplacement` pour tout déplacement — jamais par un `db.productions.update` direct
//  sur `emplacement`.
// ════════════════════════════════════════════════════════════════════════════

// État du batch : une entrée par LIGNE (pas par lot — un lot peut avoir plusieurs lignes).
// { uid, prodId, copies, pieces, equipKey }
let _lbLignes = [];
let _lbUid = 1;

// Ajoute une ligne sous un lot. Chaque ligne = une SÉRIE de boîtes identiques (copies × pieces).
function lbAddLigne(prodId){
  _lbLignes.push({ uid: _lbUid++, prodId: +prodId, copies: 1, pieces: null, equipKey: null });
  lbRenderLignes(+prodId);
}

function lbDelLigne(uid){
  _lbLignes = _lbLignes.filter(l => l.uid !== +uid);
  lbRenderLignes();
}

// [v1358] LE TOTAL EST LE GARDE-FOU. Ben range 3×20 = 60 coques sur un lot de 120 : les 60 restantes
// « restent en attente » (sa décision). Mais si les lignes dépassent le total du lot, on l'ARRÊTE —
// sinon l'app enregistrerait plus de coques rangées qu'il n'en existe. Un stock qui ment est pire
// qu'un stock incomplet.
function lbTotalLigne(l){ return Math.max(0, (+l.copies || 0)) * Math.max(0, (+l.pieces || 0)); }

function lbTotalLot(prodId){
  return _lbLignes.filter(l => l.prodId === +prodId).reduce((s, l) => s + lbTotalLigne(l), 0);
}

// Rend les lignes d'un lot (ou de tous si prodId omis).
function lbRenderLignes(prodId){
  const ids = prodId ? [+prodId] : [...new Set(_lbLignes.map(l => l.prodId))];
  ids.forEach(pid => {
    const zone = document.getElementById('lblignes_' + pid);
    if(!zone) return;
    const lignes = _lbLignes.filter(l => l.prodId === pid);
    const prod = (window._lbProds || []).find(p => +p.id === pid);
    const dispo = prod ? round3(+prod.qteRestante || 0) : 0;
    const place = lbTotalLot(pid);
    const reste = round3(dispo - place);
    const trop = reste < -0.001;

    zone.innerHTML = lignes.map(l => {
      const tot = lbTotalLigne(l);
      const emp = l.equipKey ? (EMP_BY_KEY[l.equipKey] || null) : null;
      const multi = (+l.copies || 0) > 1;
      return `<div class="lb-ligne" style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:6px 0;border-top:1px dashed #e6ddd6">
        <label style="font-size:.78rem">Étiq. <input type="number" min="1" value="${l.copies}" class="lb-num"
          style="width:52px" onchange="lbSetLigne(${l.uid},'copies',this.value)"></label>
        <label style="font-size:.78rem">Pcs/boîte <input type="number" min="1" value="${l.pieces != null ? l.pieces : ''}"
          class="lb-num" style="width:64px" placeholder="auto" onchange="lbSetLigne(${l.uid},'pieces',this.value)"></label>
        <button class="btn ${l.equipKey ? 'gold' : 'ghost'} sm" style="font-size:.75rem"
          onclick="lbPickEmp(${l.uid})">${emp ? `${emp.lettre} · ${esc(emp.nom)}` : '📍 Emplacement'}</button>
        ${tot > 0 ? `<span style="font-size:.72rem;color:#9a8a82">= ${qty(tot)}${multi ? ` (${l.copies} boîtes)` : ''}</span>` : ''}
        <button class="btn ghost sm" style="font-size:.75rem;color:#b3261e" onclick="lbDelLigne(${l.uid})">✕</button>
        ${l._empOuvert ? `<div style="flex-basis:100%;padding:6px 0 2px">
          ${EMPLACEMENTS.map(e => `<button class="btn ${l.equipKey === e.key ? 'gold' : 'ghost'} sm"
            style="font-size:.74rem;margin:2px 4px 2px 0;display:inline-flex;align-items:center;gap:5px"
            onclick="lbSetEmp(${l.uid},'${e.key}')">
            <b style="background:${e.type === 'frigo' ? '#6aa3a0' : '#3b6ea5'};color:#fff;border-radius:5px;padding:0 5px">${e.lettre}</b>
            ${e.icon} ${esc(e.nom)}${l.equipKey === e.key ? ' ✓' : ''}</button>`).join('')}
        </div>` : ''}
      </div>`;
    }).join('') +
    `<div style="display:flex;justify-content:space-between;align-items:center;margin-top:6px">
      <button class="btn ghost sm" style="font-size:.78rem" onclick="lbAddLigne(${pid})">+ Ajouter une boîte</button>
      <span style="font-size:.74rem;color:${trop ? '#b3261e' : '#9a8a82'}">
        ${trop
          ? `⚠️ ${qty(-reste)} de trop (le lot n'a que ${qty(dispo)})`
          : `${qty(place)} rangé(s) · ${qty(reste)} en attente`}
      </span>
    </div>`;
  });
}

function lbSetLigne(uid, champ, valeur){
  const l = _lbLignes.find(x => x.uid === +uid);
  if(!l) return;
  l[champ] = (valeur === '' || valeur == null) ? null : Math.max(0, Math.round(+valeur || 0));
  lbRenderLignes(l.prodId);
}

// Sélecteur d'emplacement pour UNE ligne. Réutilise EMPLACEMENTS (la source unique).
// ════════════════════════════════════════════════════════════════════════════
// [v1363] LE CRASH : UN MODAL PAR-DESSUS UN MODAL DÉTRUIT LE PREMIER.
//
// Ben : « En créant les boîtes dans l'onglet étiquettes groupées je subis un crash au moment
// d'appuyer sur chaque bouton emplacement. À l'issue du crash je perds toutes les informations
// qui étaient en attente de validation et dois recommencer depuis zéro. »
//
// LA CAUSE, ET ELLE EST ENTIÈREMENT DE MON FAIT : l'écran « Étiquettes groupées » EST LUI-MÊME
// UN MODAL (`labelsBatchForm` appelle `openModal`). Mon `lbPickEmp` appelait `openModal` À SON
// TOUR — or `openModal` fait `modal.innerHTML = html`. Il ÉCRASE le contenu du modal existant.
//
// Résultat : l'écran des étiquettes est DÉTRUIT. En fermant le sélecteur, Ben retrouve un modal
// vide, et toutes ses lignes en attente sont perdues. Exactement ce qu'il décrit.
//
// RÈGLE GRAVÉE (v1363) : ON N'EMPILE PAS LES MODALS. `openModal` n'est pas une pile, c'est un
// REMPLACEMENT — l'appeler depuis un modal ouvert détruit le contexte de travail en cours.
// Un sélecteur qui interrompt une saisie doit s'afficher DANS la saisie, jamais par-dessus.
//
// LE CORRECTIF : le sélecteur s'affiche EN PLACE, dans la ligne, sans jamais toucher au modal.
// ════════════════════════════════════════════════════════════════════════════
function lbPickEmp(uid){
  const l = _lbLignes.find(x => x.uid === +uid);
  if(!l) return;
  // On bascule l'affichage du sélecteur de CETTE ligne (et on referme les autres).
  _lbLignes.forEach(x => { if(x.uid !== +uid) x._empOuvert = false; });
  l._empOuvert = !l._empOuvert;
  lbRenderLignes(l.prodId);
}

function lbSetEmp(uid, key){
  const l = _lbLignes.find(x => x.uid === +uid);
  if(!l) return;
  l.equipKey = key;
  l._empOuvert = false;   // on referme le sélecteur, on ne ferme PAS le modal
  lbRenderLignes(l.prodId);
}

// ════════════════════════════════════════════════════════════════════════════
// [v1358] LA CONFIRMATION DE DISPATCH — la demande précise de Ben.
//
// « Dans le cas de lignes ayant plusieurs impressions (3×20), au moment d'imprimer, demander
//   confirmation que les 3 boîtes vont au même endroit. Si la réponse est non, proposer un
//   dispatch individuel. »
//
// POURQUOI C'EST JUSTE : 3 étiquettes = 3 boîtes PHYSIQUES. Rien ne dit qu'elles tiennent au même
// endroit — un congélateur peut être plein après la deuxième. Supposer qu'elles vont ensemble, c'est
// écrire dans la base un rangement que Ben n'a pas fait. Il retrouverait une boîte qui n'est pas là.
//
// ON DEMANDE. On ne suppose pas.
// ════════════════════════════════════════════════════════════════════════════
async function lbRangerEtImprimer(){
  const actives = _lbLignes.filter(l => lbTotalLigne(l) > 0 && l.equipKey);
  const sansEmp = _lbLignes.filter(l => lbTotalLigne(l) > 0 && !l.equipKey);

  if(!actives.length && !sansEmp.length){ toast('Ajoute au moins une boîte'); return; }
  if(sansEmp.length){ toast(`${sansEmp.length} ligne(s) sans emplacement`); return; }

  // [v1358] GARDE-FOU : on ne range JAMAIS plus que ce que le lot contient.
  // Sans ce contrôle, l'app enregistrerait un stock qui n'existe pas — et un stock qui MENT est
  // pire qu'un stock incomplet : Ben irait chercher des coques qui ne sont nulle part.
  const parLot = {};
  actives.forEach(l => { parLot[l.prodId] = (parLot[l.prodId] || 0) + lbTotalLigne(l); });
  for(const pid of Object.keys(parLot)){
    const prod = (window._lbProds || []).find(p => +p.id === +pid);
    const dispo = prod ? round3(+prod.qteRestante || 0) : 0;
    if(parLot[pid] > dispo + 0.001){
      toast(`Trop de pièces pour ${prod ? esc(prod.lotProduction || '#' + pid) : '#' + pid}`);
      return;
    }
  }

  // Les lignes à PLUSIEURS boîtes : demander si elles vont bien toutes au même endroit.
  const multi = actives.filter(l => (+l.copies || 0) > 1);
  if(multi.length){
    const l = multi[0];   // on traite une ligne à la fois, séquentiellement
    const prod = (window._lbProds || []).find(p => +p.id === l.prodId);
    const emp = EMP_BY_KEY[l.equipKey];
    const nom = prod ? (prod.lotProduction || '#' + l.prodId) : '#' + l.prodId;
    openModal(`<h3>📦 ${l.copies} boîtes — même emplacement ?</h3>
      <p class="note">Le lot <b>${esc(nom)}</b> produit <b>${l.copies} boîtes</b> de ${qty(l.pieces)} pièces.
      Vont-elles <b>toutes</b> en <b>${esc(emp ? emp.nom : l.equipKey)}</b> ?</p>
      <p class="note" style="font-size:.76rem;color:#9a8a82">Si tu réponds non, tu choisiras l'emplacement de chaque boîte séparément.</p>
      <div class="modal-actions">
        <button class="btn ghost" onclick="lbDispatchIndividuel(${l.uid})">Non — dispatcher</button>
        <button class="btn" onclick="lbConfirmMulti(${l.uid})">Oui, toutes ici</button>
      </div>`);
    return;
  }

  await lbExecuter();
}

// « Oui, toutes au même endroit » → on marque la ligne comme confirmée et on repasse au contrôle.
// [v1363] La confirmation de dispatch ÉCRASE l'écran des étiquettes (openModal = remplacement).
// On ne peut donc PAS y revenir avec un simple `lbRenderLignes()` : le DOM n'existe plus.
// Les lignes vivent dans `_lbLignes` (en mémoire, intactes) — il faut RECONSTRUIRE l'écran.
function lbConfirmMulti(uid){
  const l = _lbLignes.find(x => x.uid === +uid);
  if(l) l._confirme = true;
  // On retire la ligne confirmée du lot de vérification en la scindant en boîtes identiques.
  if(l){
    const n = +l.copies || 1;
    l.copies = 1;
    l._boites = n;         // n boîtes, toutes au même endroit
    l._confirme = true;
  }
  lbRangerEtImprimer();    // relance : les autres lignes multi seront traitées à leur tour
}

// [v1358] LE DISPATCH INDIVIDUEL. Une ligne de 3 boîtes devient 3 lignes de 1 boîte, chacune avec
// son propre emplacement. Ben choisit boîte par boîte — c'est exactement ce qu'il a demandé.
function lbDispatchIndividuel(uid){
  const l = _lbLignes.find(x => x.uid === +uid);
  if(!l) return;
  const n = +l.copies || 1;
  const pieces = +l.pieces || 0;
  const pid = l.prodId;
  // On remplace la ligne par N lignes de 1 boîte. La première garde l'emplacement déjà choisi ;
  // les suivantes sont VIDES — Ben doit les renseigner, et le bouton refusera tant qu'elles le sont.
  _lbLignes = _lbLignes.filter(x => x.uid !== +uid);
  for(let i = 0; i < n; i++){
    _lbLignes.push({ uid: _lbUid++, prodId: pid, copies: 1, pieces,
                     equipKey: (i === 0 ? l.equipKey : null), _boites: 1, _confirme: true });
  }
  // [v1363] L'écran a été écrasé par la modale de confirmation : on le RECONSTRUIT.
  // `_lbLignes` est intact (il vit en mémoire, pas dans le DOM) — Ben retrouve TOUTES ses lignes,
  // avec les N boîtes désormais éclatées. Sans ça, il tombait sur un écran vide et devait tout
  // ressaisir : exactement le crash qu'il a signalé.
  lbRestaurerEcran(pid, `${n} boîtes à placer individuellement`);
}

// [v1363] Reconstruit l'écran « Étiquettes groupées » après une modale qui l'a écrasé, en
// restaurant les lignes et les cases cochées depuis `_lbLignes` (la source de vérité).
async function lbRestaurerEcran(prodIdFocus, msg){
  // [v1363] PIÈGE : `labelsBatchForm()` fait `_lbLignes = []` (repartir propre à chaque ouverture).
  // Si on l'appelle sans précaution, il EFFACE exactement ce qu'on cherche à restaurer.
  // On sauvegarde donc les lignes AVANT, et on les remet APRÈS. Ce correctif contenait lui-même
  // le bug qu'il corrigeait — la réinitialisation légitime d'une fonction devient destructrice
  // quand on la rappelle dans un contexte qu'elle n'a pas prévu.
  const _sauvegarde = _lbLignes.slice();
  const _uidSauve = _lbUid;
  await labelsBatchForm();          // rouvre l'écran — MAIS remet _lbLignes à []
  _lbLignes = _sauvegarde;          // …on restaure
  _lbUid = _uidSauve;
  // Re-cocher les lots qui ont des lignes, et re-rendre celles-ci.
  const pids = [...new Set(_lbLignes.map(l => l.prodId))];
  pids.forEach(pid => {
    const cb = document.querySelector('.lb-sel[data-prod="' + pid + '"]');
    if(cb){ cb.checked = true; }
    const f = document.getElementById('lbf_' + pid);
    if(f) f.style.display = 'flex';
    lbRenderLignes(pid);
  });
  if(msg) toast(msg);
}

// ════════════════════════════════════════════════════════════════════════════
// [v1358] L'EXÉCUTION — création des boîtes + écriture des placements.
//
// TROIS RÈGLES QUE JE NE CONTOURNE PAS :
//
// 1. LES BOÎTES SONT CRÉÉES SI ELLES N'EXISTENT PAS (la demande de Ben : « ça recréerait
//    automatiquement les boîtes qui vont avec »). Mais on ne crée QUE ce qui manque : une boîte
//    de 20 déjà en base est RÉUTILISÉE, jamais dupliquée. Sinon la liste de boîtes deviendrait
//    un cimetière de doublons en trois semaines.
//
// 2. TOUT DÉPLACEMENT PASSE PAR `doMoveEmplacement()`. Cette fonction porte les règles de SÉCURITÉ
//    ALIMENTAIRE : interdiction de recongeler après décongélation, chaîne du froid. Un
//    `db.productions.update({emplacement})` direct les contournerait EN SILENCE. Un bug de données
//    se corrige ; une recongélation, non.
//
// 3. LE MODÈLE `placements[]` EST CELUI QUI EXISTE (v1358 n'invente rien). Un lot avec plusieurs
//    placements est déjà affiché « ⊟ dispatché » ailleurs dans l'app — le besoin de Ben était
//    prévu par le modèle, il n'était simplement pas accessible depuis cet écran.
// ════════════════════════════════════════════════════════════════════════════
// [v1389] VIDÉ de sa logique de rangement. Cet écran (« Étiquettes groupées ») ne DOIT
// plus écrire placements ni créer de boîtes-catalogue lui-même (c'était le système C, une
// 3e implémentation parallèle du boxing). Décision Ben : il ne fait plus que générer le PDF,
// et TOUT rangement passe par le moteur unique via `rangerLot` (→ prodPreparerBoites).
// Chaque ligne active devient une boîte { qte, destination } confiée au moteur : mêmes règles
// froid/DLC, mêmes lignes-filles, aucune divergence. Zéro `db.productions.update({placements})`.
async function lbExecuter(){
  const actives = _lbLignes.filter(l => lbTotalLigne(l) > 0 && l.equipKey);
  if(!actives.length){ toast('Rien à ranger'); return; }

  // Regroupe par lot : chaque lot est confié UNE fois au moteur unique avec la liste de ses boîtes.
  const parLot = {};
  actives.forEach(l => { (parLot[l.prodId] = parLot[l.prodId] || []).push(l); });

  let nbBoites = 0, nbLots = 0;
  const echecs = [];

  for(const pid of Object.keys(parLot)){
    // Traduit les lignes de CET écran en boîtes { qte, destination } — le SEUL vocabulaire
    // que le moteur comprend. Une ligne = `_boites` (ou `copies`) boîtes identiques.
    const boites = [];
    for(const l of parLot[pid]){
      const cap = +l.pieces || 0;
      if(cap <= 0) continue;
      const n = Math.max(1, +l._boites || +l.copies || 1);
      for(let i = 0; i < n; i++){ boites.push({ qte: cap, destination: l.equipKey }); nbBoites++; }
    }
    if(!boites.length) continue;

    // UN SEUL moteur. Aucune écriture placements ici : rangerLot → prodPreparerBoites porte
    // toute la logique (scission en lignes-filles, doMoveEmplacement, DLC, chaîne du froid).
    const res = await rangerLot(+pid, boites);
    if(!res || !res.ok){ echecs.push({ pid, raison: res && res.raison }); continue; }
    nbLots++;
  }

  closeModal();
  if(typeof renderProductions === 'function') renderProductions();
  if(echecs.length){
    toast(`${nbLots} lot(s) rangé(s) · ${echecs.length} refusé(s) (${esc(echecs[0].raison||'règle froid/DLC')})`);
  } else {
    toast(`${nbBoites} boîte(s) rangée(s) sur ${nbLots} lot(s) ✓`);
  }
  _lbLignes = [];
}


async function labelsBatchForm(){
  const prods = await db.productions.orderBy('date').reverse().toArray().catch(()=>[]);
  const recipes = await db.recipes.toArray().catch(()=>[]);
  let lots = prods.filter(p=>p.lotProduction);
  if(typeof sortProdsRecent==='function') lots = sortProdsRecent(lots);
  lots = lots.slice(0, 200);
  if(!lots.length){ toast('Aucun lot à étiqueter'); return; }

  // [v1358] Les lots sont exposés pour le module de rangement — SANS ça, `qteRestante` serait
  // toujours 0, et le garde-fou anti-dépassement ne mordrait JAMAIS : Ben pourrait enregistrer
  // 200 coques rangées sur un lot qui n'en contient que 120. Un stock qui ment est pire qu'un
  // stock incomplet — il envoie chercher des boîtes qui ne sont nulle part.
  window._lbProds = lots;
  _lbLignes = [];   // repartir propre à chaque ouverture, sinon des lignes d'une session précédente
                    // seraient rangées à l'insu de Ben.

  const recName = id => { const r=recipes.find(x=>+x.id===+id); return r?r.produitNom:''; };
  const todayStr = today();  // [A1] réutilise la globale today() (désormais locale)
  const lotDay = p => ((p.prodTermineTs||p.date||'')+'').slice(0,10);

  // Rendu d'une ligne lot (commun à toutes les sections).
  const rowOf = p => {
    const nom = p.libre ? (p.produitLibre||'(libre)') : (recName(p.recipeId)|| (typeof prodNomEpure==='function'?prodNomEpure(p,recipes):''));
    const comp = (typeof prodComposant==='function')?prodComposant(p):'';
    const compLbl = ({coques:'Coques',ganache:'Ganache',assemble:'Assemblé',degustation:'Dégust.',complet:''})[comp]||'';
    const nbDef = (p.qteReelle!=null)?p.qteReelle:(p.qteProduite!=null?p.qteProduite:'');
    const fab = p.prodTermineTs ? fmtDate(p.prodTermineTs) : (p.date?fmtDate(p.date):'');
    return `<div class="lb-row" data-prod="${p.id}">
      <label class="lb-check"><input type="checkbox" class="lb-sel" data-prod="${p.id}" onchange="lbRowToggle(${p.id})"> <span class="lb-nom">${esc((compLbl?compLbl+' ':'')+nom)}</span></label>
      <div class="lb-lot">${esc(p.lotProduction)}${fab?' · '+esc(fab):''}</div>
      <div class="lb-fields" id="lbf_${p.id}" style="display:none;flex-direction:column">
        <div id="lblignes_${p.id}"></div>
      </div>
    </div>`;
  };

  // Famille d'un lot pour le regroupement.
  const familyOf = p => {
    const c = (typeof prodComposant==='function')?prodComposant(p):'complet';
    if(c==='coques') return 'coques';
    if(c==='ganache') return 'ganache';
    if(c==='degustation') return 'degust';
    return 'finis'; // complet / assemblé
  };

  // Une section repliable. open=true pour la déplier par défaut.
  let _sid = 0;
  const section = (titre, lotsArr, open) => {
    if(!lotsArr.length) return '';
    const id = 'lbsec_'+(_sid++);
    return `<div class="lb-sec">
      <div class="lb-sec-head" onclick="lbSecToggle('${id}')"><span class="lb-sec-chev" id="${id}_chev">${open?'▾':'▸'}</span> <b>${esc(titre)}</b> <span class="lb-sec-n">${lotsArr.length}</span></div>
      <div class="lb-sec-body" id="${id}" style="display:${open?'block':'none'}">${lotsArr.map(rowOf).join('')}</div>
    </div>`;
  };

  // 1) Lots du jour (toutes familles confondues), dépliés.
  const dujour = lots.filter(p=>lotDay(p)===todayStr);
  // 2) Par famille — on EXCLUT les lots du jour (déjà dans la section Aujourd'hui) pour éviter
  //    des identifiants dupliqués et une double sélection du même lot.
  const reste = lots.filter(p=>lotDay(p)!==todayStr);
  const coques = reste.filter(p=>familyOf(p)==='coques');
  const ganache = reste.filter(p=>familyOf(p)==='ganache');
  const finis  = reste.filter(p=>familyOf(p)==='finis');
  const degust = reste.filter(p=>familyOf(p)==='degust');

  const sections =
    section("📅 Aujourd'hui", dujour, true) +
    section('🟤 Coques', coques, false) +
    section('🍫 Ganache', ganache, false) +
    section('🍬 Macarons finis', finis, false) +
    section('🥄 Dégustation', degust, false);

  openModal(`<h3>📄 Étiquettes groupées (PDF)</h3>
    <p class="note" style="margin-bottom:8px">Coche les lots, règle le <b>nombre d'étiquettes</b> et les <b>pièces par boîte</b> à afficher. L'app crée <b>un seul PDF</b> : tu ne le récupères qu'une fois dans Labelife pour imprimer toute la série.</p>
    <div class="lb-list">${sections}</div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn ghost" onclick="lbRangerEtImprimer()">📦 Créer les boîtes et ranger</button>
      <button class="btn gold" onclick="lbGenerate()">📄 Générer le PDF</button>
    </div>`);
}

// Replie / déplie une section de l'écran d'étiquettes groupées.
function lbSecToggle(id){
  const body=document.getElementById(id); const chev=document.getElementById(id+'_chev');
  if(!body) return;
  const open=body.style.display!=='none';
  body.style.display=open?'none':'block';
  if(chev) chev.textContent=open?'▸':'▾';
}

// Affiche/masque les réglages d'un lot selon sa case.
function lbRowToggle(prodId){
  const cb = document.querySelector('.lb-sel[data-prod="'+prodId+'"]');
  const f = document.getElementById('lbf_'+prodId);
  const coche = !!(cb && cb.checked);
  if(f) f.style.display = coche ? 'flex' : 'none';
  // [v1358] Cocher un lot crée sa PREMIÈRE ligne (une boîte). Ben ajoute les suivantes avec
  // « + Ajouter une boîte ». Décocher retire toutes les lignes du lot — sinon des lignes fantômes
  // resteraient dans `_lbLignes` et seraient rangées sans que Ben les voie.
  if(coche){
    if(!_lbLignes.some(l => l.prodId === +prodId)){
      const p = (window._lbProds || []).find(x => +x.id === +prodId);
      const def = p ? (p.qteReelle != null ? p.qteReelle : (p.qteProduite != null ? p.qteProduite : null)) : null;
      _lbLignes.push({ uid: _lbUid++, prodId: +prodId, copies: 1, pieces: def, equipKey: null });
    }
  } else {
    _lbLignes = _lbLignes.filter(l => l.prodId !== +prodId);
  }
  lbRenderLignes(+prodId);
}

async function lbGenerate(){
  // ════════════════════════════════════════════════════════════════════════════
  // [v1375] LE BUG : cette fonction lisait `document.getElementById('lbcopies_'+id)` et
  // `'lbpieces_'+id` — des identifiants qui N'EXISTENT DANS AUCUN élément du DOM (les champs
  // rendus par `lbRenderLignes` n'ont pas d'`id`, ils écrivent dans `_lbLignes` via `lbSetLigne`).
  //
  // Conséquence, exactement ce que Ben décrivait : `getElementById(...)` renvoie null →
  // `(null||{}).value` → undefined → `+undefined || 1` force **copies = 1**, et `nbPieces` reste
  // **null** → en aval `buildLabelsPDF` NE POSE PAS l'override et retombe sur la quantité du lot
  // (« l'ancienne valeur en dur »). Tout ce que Ben tapait était donc ignoré au moment de générer.
  //
  // LE CORRECTIF : lire la SOURCE DE VÉRITÉ `_lbLignes`, exactement comme le font déjà le rangement
  // (`lbExecuter`, `lbRangerEtImprimer`). Bonus : `_lbLignes` porte PLUSIEURS lignes par lot avec
  // des pièces/boîte différentes — le PDF les honore désormais (l'écran laissait déjà les saisir,
  // seul le générateur ne les lisait pas).
  //
  // RÈGLE GRAVÉE (v1375) : L'ÉCRAN ET LE GÉNÉRATEUR LISENT LE MÊME MODÈLE. Un bouton qui relit le
  // DOM par des `id` hérités d'une version antérieure du balisage produit un TROISIÈME chiffre
  // (v1339 / v1374 : le lecteur et le modèle ne doivent jamais diverger). Prouvé par la garde
  // v1375 (le motif `lbcopies_`/`lbpieces_` est banni du fichier).
  // ════════════════════════════════════════════════════════════════════════════
  // On imprime une ligne dès qu'elle a AU MOINS une étiquette (copies > 0). Le nombre de pièces par
  // boîte peut, lui, rester vide (« auto ») : nbPieces=null → buildLabelsPDF retombe sur la quantité
  // du lot (comportement historique de l'écran). NB : le rangement, lui, exige un total réel — d'où
  // son filtre `lbTotalLigne > 0` DIFFÉRENT : on ne range pas une quantité inconnue, mais on peut
  // l'imprimer. Même modèle `_lbLignes`, critères d'inclusion propres à chaque usage.
  const lignes = _lbLignes.filter(l => (+l.copies || 0) > 0);
  if(!lignes.length){ toast('Coche un lot et indique un nombre d\'étiquettes'); return; }
  // Une entrée PDF par ligne (chaque ligne = une série de boîtes identiques).
  const items = lignes.map(l => ({
    prodId: l.prodId,
    copies: Math.max(1, +l.copies || 1),
    nbPieces: (l.pieces != null ? +l.pieces : null)
  }));
  closeModal();
  await buildLabelsPDF(items);
}
// =============================================================================

async function shareLabelImage(prodId){
  try{
    const d = await buildLabelData(prodId);
    if(!d){ toast('Batch introuvable'); return; }
    const cv = await labelToCanvas(d);
    const blob = await new Promise(res=> cv.toBlob(res, 'image/png'));
    if(!blob){ toast('Impossible de générer l\'image'); return; }
    const fileName = 'etiquette-'+(d.lot||'lot').replace(/[^\w-]/g,'_')+'.png';
    const file = new File([blob], fileName, {type:'image/png'});
    // Partage natif iOS (vers l'app Phomemo, Photos, etc.) si disponible et compatible fichiers.
    if(navigator.canShare && navigator.canShare({files:[file]})){
      try{
        await navigator.share({ files:[file], title:'Étiquette '+d.lot });
        return;
      }catch(eShare){ if(eShare && eShare.name==='AbortError') return; /* annulé par l'utilisateur */ }
    }
    // Repli : téléchargement de l'image (l'utilisateur l'ouvre ensuite dans Phomemo).
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = fileName;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url), 2000);
    toast('Image enregistrée — ouvre-la dans l\'app Phomemo');
  }catch(e){ console.error('shareLabelImage',e); toast('Erreur lors de la génération de l\'étiquette'); }
}

// ── TRAÇABILITÉ DESCENDANTE D'UNE COMMANDE ──────────────────────────────────
// À partir d'une commande, remonte pour chaque parfum la chaîne de fabrication :
//   coques → ganache/crémeux → (composants) → macaron assemblé,
// avec le lot ET l'emplacement de chacun. S'appuie sur le champ `assembleFrom`
// enregistré à l'assemblage (cf. prodAssembleSave) qui mémorise les lots sources.
async function buildOrderTraceability(orderId){
  const o = await db.orders.get(orderId);
  if(!o) return null;
  const recipes = await db.recipes.toArray();
  const links = await db.orderItems.where('orderId').equals(orderId).toArray().catch(()=>[]);
  const ref = orderNumber(o);

  // Petit cache des productions déjà chargées (pour l'emplacement des lots sources).
  const cacheProd = {};
  const getProd = async id => {
    if(id==null) return null;
    if(cacheProd[id]!==undefined) return cacheProd[id];
    const p = await db.productions.get(id).catch(()=>null);
    cacheProd[id] = p || null;
    return cacheProd[id];
  };
  const empOf = p => {
    if(!p || !p.emplacement) return { nom:'', lettre:'', icon:'' };
    return { nom: empNom(p.emplacement), lettre: empLettre(p.emplacement), icon: empIcon(p.emplacement) };
  };

  // Regroupement par parfum (nom complet du macaron assemblé).
  const parParfum = {};   // nom -> { nom, assembles:[...], coques:[...], garniture:[...], composants:[...] }
  const ensure = nom => (parParfum[nom] ||= { nom, assembles:[], coques:[], garniture:[], composants:[] });

  for(const it of links){
    const pid = it.productionId;
    if(pid==null) continue;
    const asm = await getProd(pid);
    if(!asm) continue;
    const nomParfum = prodNomComplet(asm, recipes) || '(parfum ?)';
    const grp = ensure(nomParfum);
    const empA = empOf(asm);
    grp.assembles.push({ lot: asm.lotProduction||'—', emp:empA, qte:asm.qteProduite, dlc:asm.dlcProduit||'' });

    // Lots sources mémorisés à l'assemblage.
    const from = Array.isArray(asm.assembleFrom) ? asm.assembleFrom : [];
    for(const src of from){
      const sp = await getProd(src.id);
      const emp = empOf(sp);
      const ligne = { lot: src.lot || (sp && sp.lotProduction) || '—', emp, qte: src.qte };
      if(src.composant==='coques') grp.coques.push(ligne);
      else if(src.composant==='ganache'){
        ligne.label = (sp && garnLabel(sp)) || 'ganache';
        grp.garniture.push(ligne);
      }
      else if(src.composant==='garniture-sup'){
        ligne.label = src.parfum || 'composant';
        grp.composants.push(ligne);
      }
    }
  }

  // Dédoublonnage léger (un même lot source peut revenir si plusieurs assemblés).
  const dedup = arr => {
    const vus = new Set(); const out = [];
    for(const x of arr){ const k = x.lot+'|'+(x.emp.lettre||''); if(!vus.has(k)){ vus.add(k); out.push(x); } }
    return out;
  };
  const parfums = Object.values(parParfum).map(g => ({
    nom: g.nom,
    assembles: dedup(g.assembles),
    coques: dedup(g.coques),
    garniture: dedup(g.garniture),
    composants: dedup(g.composants)
  }));

  return { ref, livraison: o.date ? fmtDate(o.date) : '', parfums, nbLies: links.length };
}

// Vue à l'écran de la traçabilité d'une commande, regroupée par parfum.
// En-tête = référence commande (qui centralise client + date). Pour chaque parfum :
// la chaîne coques → ganache/crémeux → (composants) → assemblé, avec lot + emplacement.
async function renderOrderTrace(orderId){
  const t = await buildOrderTraceability(orderId);
  if(!t){ toast('Commande introuvable'); return; }
  if(!t.nbLies){
    openModal(`<h3>🔎 Traçabilité — Commande ${esc(t.ref)}</h3>
      <p class="note" style="margin-top:8px">Aucun lot de production n'est relié à cette commande pour l'instant. Liez d'abord des batchs depuis la commande.</p>
      <div class="modal-actions"><button class="btn" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  const ligneLot = (l, type, color) => `
    <div style="display:flex;align-items:baseline;gap:6px;padding:3px 0;border-bottom:1px dashed #ece5e0">
      <span class="tag" style="background:${color};color:#fff;font-size:.62rem;flex:0 0 auto">${esc(type)}</span>
      <span style="font-weight:600;font-size:.82rem">${esc(l.lot)}</span>
      <span style="margin-left:auto;font-size:.74rem;color:#7a6a62;white-space:nowrap">${l.emp.lettre?`${l.emp.icon||''} ${esc(l.emp.lettre)} · ${esc(l.emp.nom)}`:'—'}</span>
    </div>`;

  const cartes = t.parfums.map(p=>{
    const coques = p.coques.map(l=>ligneLot(l,'Coques','#8a6d3b')).join('');
    const garn = p.garniture.map(l=>ligneLot(l, (l.label==='crémeux'?'Crémeux':'Ganache'), '#a5453b')).join('');
    const comps = p.composants.map(l=>ligneLot(l, l.label||'Composant', '#6d6d6d')).join('');
    const asm = p.assembles.map(l=>ligneLot(l,'Assemblé','#3f7d52')).join('');
    return `
      <div class="panel" style="margin-bottom:10px;padding:10px 12px">
        <div style="font-weight:700;font-size:.95rem;margin-bottom:6px">🧁 ${esc(p.nom)}</div>
        ${coques||garn||comps?'':'<p class="note" style="margin:0 0 6px">Pas de sous-lots tracés (macaron non assemblé via l\'app).</p>'}
        ${coques}${garn}${comps}${asm}
      </div>`;
  }).join('');

  openModal(`
    <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:2px">
      <h3 style="margin:0">🔎 Traçabilité</h3>
      <span style="font-weight:700;font-size:.9rem;color:#8a6d3b">Commande ${esc(t.ref)}</span>
    </div>
    ${t.livraison?`<p class="note" style="margin:0 0 10px">Livraison : ${esc(t.livraison)}</p>`:''}
    ${cartes}
    <div class="modal-actions"><button class="btn" onclick="closeModal()">Fermer</button></div>`);
}

/* Étiquette RÉCAP de commande → image partageable vers Phomemo.
   Reprend les données de buildOrderLabelData (parfums, lots, fab, DLC) et les dessine
   sur un canvas au format thermique (un peu plus haut car plusieurs parfums possibles). */
async function shareOrderRecapImage(orderId){
  try{
    const d = await buildOrderLabelData(orderId);
    if(!d){ toast('Aucun batch lié à cette commande. Liez d\'abord des batchs.'); return; }
    const o = await db.orders.get(orderId).catch(()=>null);
    let clientNom = '';
    if(o && o.clientId){ const c = await db.clients.get(o.clientId).catch(()=>null); clientNom = c?c.nom:''; }

    const PXMM = 12;
    const W = 50*PXMM;
    // Hauteur dynamique : base + une ligne par parfum (mini 25 mm).
    const baseH = 25;
    const extra = Math.max(0, (d.parfums.length - 3)) * 3.2;  // au-delà de 3 parfums, on agrandit
    const extraDlc = (d.mixteFormats && d.dlcParType && d.dlcParType.length>1) ? 3.2 : 0; // 2e ligne DLC
    const H = Math.round((baseH + extra + extraDlc) * PXMM);
    const cv = document.createElement('canvas');
    cv.width = W; cv.height = H;
    const ctx = cv.getContext('2d');
    ctx.fillStyle = '#fff'; ctx.fillRect(0,0,W,H);
    ctx.fillStyle = '#000';
    const pad = 1.5*PXMM;
    let y = pad;
    const line = (txt, sizeMm, bold)=>{
      ctx.font = `${bold?'bold ':''}${sizeMm*PXMM}px Arial, Helvetica, sans-serif`;
      let s = String(txt==null?'':txt);
      const maxW = W - pad*2;
      while(s.length>1 && ctx.measureText(s).width > maxW){ s = s.slice(0,-1); }
      y += sizeMm*PXMM;
      ctx.fillText(s, pad, y);
      y += 0.6*PXMM;
    };
    // En-tête : client + livraison.
    line('Sensations Macarons', 2.5, true);
    if(clientNom) line('Client : '+clientNom, 2.6, false);
    line('Livraison : '+d.livraison, 2.4, false);
    // Parfums avec case à cocher.
    if(d.parfums.length){
      line('Parfums :', 2.4, true);
      d.parfums.forEach(pf=>{
        ctx.font = `${2.5*PXMM}px Arial, Helvetica, sans-serif`;
        y += 2.5*PXMM;
        // case ☐
        const boxS = 2.2*PXMM;
        ctx.strokeStyle = '#000'; ctx.lineWidth = Math.max(1, 0.2*PXMM);
        ctx.strokeRect(pad, y - boxS + 0.4*PXMM, boxS, boxS);
        let s = pf; const maxW = W - pad*2 - boxS - 1*PXMM;
        while(s.length>1 && ctx.measureText(s).width > maxW){ s = s.slice(0,-1); }
        ctx.fillText(s, pad + boxS + 1*PXMM, y);
        y += 0.6*PXMM;
      });
    }
    // Lots, fabrication, DLC.
    if(d.lots && d.lots.length) line('Lots : '+d.lots.join(', '), 2.1, false);
    line('Fab. : '+d.fab, 2.2, false);
    // DLC : une ligne si un seul format, ventilée (grands formats / classiques) si la commande mélange les deux.
    if(d.mixteFormats && d.dlcParType && d.dlcParType.length>1){
      d.dlcParType.forEach(x=> line('DLC '+x.label+' : '+x.dlc, 2.3, true));
    } else {
      line('DLC : '+d.dlc, 2.6, true);
    }

    const blob = await new Promise(res=> cv.toBlob(res, 'image/png'));
    if(!blob){ toast('Impossible de générer l\'image'); return; }
    const fileName = 'recap-commande-'+orderId+'.png';
    const file = new File([blob], fileName, {type:'image/png'});
    if(navigator.canShare && navigator.canShare({files:[file]})){
      try{ await navigator.share({ files:[file], title:'Récap commande #'+orderId }); return; }
      catch(eShare){ if(eShare && eShare.name==='AbortError') return; }
    }
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = fileName;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url), 2000);
    toast('Image enregistrée — ouvre-la dans l\'app Phomemo');
  }catch(e){ console.error('shareOrderRecapImage',e); toast('Erreur lors de la génération du récap'); }
}
/* ============================================================
   ÉTIQUETTES MULTI-BOÎTES — scinde un lot en N sous-productions,
   chacune déplacée réellement vers sa destination (frigo/congélo),
   réutilisant doMoveEmplacement pour hériter de toutes les règles
   de sécurité + le calcul DLC existants. Zéro logique dupliquée.
   ============================================================ */
/* ETIQ:PURE:BEGIN */
// Valide une répartition en boîtes avant toute écriture.
function _etiqValiderBoites(p, boites){
  const list=(boites||[]).map(b=>({qte:round3(+b.qte||0), destination:b.destination}))
    .filter(b=>b.qte>0 && b.destination);
  if(!list.length) return {ok:false, raison:'Ajoute au moins une boîte avec une quantité.'};
  for(const b of list){ if(!EMP_BY_KEY[b.destination]) return {ok:false, raison:'Destination invalide.'}; }
  const total = round3(list.reduce((s,b)=>s+b.qte,0));
  const dispo = round3(+p.qteRestante||0);
  if(total > dispo + 1e-9) return {ok:false, raison:`Le total des boîtes (${qty(total)}) dépasse le stock disponible (${qty(dispo)}).`};
  return {ok:true, list, total, dispo, reste:round3(dispo-total)};
}
/* ETIQ:PURE:END */

// Scinde le lot `prodId` en boîtes réelles. `boites` = [{qte, destination}].
// simuler:true → validation seule (dry-run), aucune écriture.
async function prodPreparerBoites(prodId, boites, opts){
  opts = opts || {};
  const p = await db.productions.get(prodId).catch(()=>null);
  if(!p) return {ok:false, raison:'Lot introuvable.'};
  const v = _etiqValiderBoites(p, boites);
  if(!v.ok) return v;
  // CAS SIMPLE (le plus fréquent) : une seule boîte, tout le stock, même destination que
  // l'emplacement actuel → RIEN à scinder. On garde le comportement historique (impression
  // directe du lot existant), zéro production créée.
  if(v.list.length===1 && v.list[0].destination===p.emplacement && Math.abs(v.reste)<1e-9){
    if(opts.simuler) return {ok:true, simple:true, boxes:[{id:prodId, qte:v.list[0].qte, destination:p.emplacement}]};
    return {ok:true, simple:true, execute:true, boxes:[{id:prodId, qte:v.list[0].qte, destination:p.emplacement}]};
  }
  if(opts.simuler) return {ok:true, simple:false, boxes:v.list, reste:v.reste, total:v.total, dispo:v.dispo};

  const created=[];
  // [v1391] PORTÉE TRANSACTIONNELLE : cette transaction appelle doMoveEmplacement pour chaque
  // boîte, et doMoveEmplacement LIT db.recipes (règle « congélateur obligatoire »). Une transaction
  // Dexie ne voit QUE les tables déclarées dans sa portée : sans `recipes`, l'accès jette
  // « object store not found » et AVORTE toute la transaction (bug v1389→v1390, écran dash cassé
  // à la validation d'étiquettes). On déclare donc TOUTES les tables touchées par la chaîne.
  await db.transaction('rw', db.productions, db.recipes, async()=>{
    const src = await db.productions.get(prodId);
    const baseLot = lotBaseSansSuffixe(src.lotProduction||'');
    let n=0;
    for(const b of v.list){
      n++;
      const lotInitial = lotAvecEmplacement(baseLot+'-B'+n, src.emplacement);
      const childId = await db.productions.add({
        recipeId: src.recipeId, produitLibre: src.produitLibre, libre: src.libre||false,
        composant: src.composant||'complet', degOrigine: src.degOrigine, degDeclasse: src.degDeclasse||false,
        assembleFrom: Array.isArray(src.assembleFrom) ? JSON.parse(JSON.stringify(src.assembleFrom)) : [],
        lotBase: baseLot, lotProduction: lotInitial, date: src.date,
        qteTheorique: b.qte, qteReelle: b.qte, qteProduite: b.qte, qteRestante: b.qte, ecart: 0,
        prodStatut: src.prodStatut, prodDebutTs: src.prodDebutTs, prodTermineTs: src.prodTermineTs,
        prodTimestamp: src.prodTimestamp,                      // ancre de fabrication INCHANGÉE (clé pour la DLC)
        emplacement: src.emplacement, emplacementMaj: src.emplacementMaj,
        histEmplacement: Array.isArray(src.histEmplacement) ? JSON.parse(JSON.stringify(src.histEmplacement)) : [],
        venuDuCongelateur: src.venuDuCongelateur||false,
        dlcAuto: src.dlcAuto, dlcProduit: src.dlcProduit,
        maturation: src.maturation,
        etiquetteDe: prodId                                    // traçabilité de la scission
      });
      created.push({id:childId, qte:b.qte, destination:b.destination});
      await db.productions.update(prodId, {qteRestante: subQty((await db.productions.get(prodId)).qteRestante, b.qte)});
      // Déplacement RÉEL vers la destination choisie : réutilise TOUTES les règles existantes
      // (anti-recongélation, retour <1h, DLC recalculée, renommage du lot). Silencieux (pas de toast/modal).
      if(b.destination !== src.emplacement){
        await doMoveEmplacement(childId, b.destination, {silent:true, confirmedFrigo:true});
      }
    }
  });
  return {ok:true, simple:false, execute:true, boxes:created};
}

// ════════════════════════════════════════════════════════════════════════════
// [v1376] FUSION DE DEUX BOÎTES DU MÊME LOT — regrouper physiquement sans perdre la traçabilité.
//
// LE BESOIN (Ben) : un même lot est souvent réparti en plusieurs boîtes ; quand les stocks
// baissent, il veut les RAPPROCHER facilement. Fusionner deux boîtes = les recombiner en une.
//
// LA RÈGLE MÉTIER, IMPÉRATIVE ET NON NÉGOCIABLE : on ne fusionne QUE deux boîtes du MÊME PARFUM
// et du MÊME LOT. Mélanger deux lots ou deux parfums ferait perdre la TRAÇABILITÉ PHYSIQUE (quel
// lot, quelle DLC, quelle fabrication) — « ni viable ni sérieux » (Ben). Toute autre combinaison
// est REFUSÉE, avec un motif clair. Le garde-fou vaut pour le MOTIF, pas le cas (prouvé par
// réintroduction dans la suite v1376).
//
// COMMENT ON RECONNAÎT « MÊME LOT » : une boîte est une ligne `productions` issue de la scission
// d'un lot (prodPreparerBoites), qui porte `etiquetteDe` = l'id du LOT PARENT. Deux boîtes du même
// lot partagent donc le même `etiquetteDe`. C'est l'identité physique la plus fiable (le champ
// `lotProduction` porte, lui, un suffixe -B1/-B2 différent par boîte). On corrobore par le parfum
// (`recipeId`) et le stade (`composant`) — qui découlent du même parent, mais qu'on vérifie
// explicitement par sécurité.
//
// CE QU'ON PRÉSERVE À LA FUSION :
//   • quantité : la somme des restes (et, en miroir, des quantités produites/réelles pour garder
//     l'invariant « produit − consommé = reste » intact) ;
//   • DLC : la PLUS COURTE des deux (la plus prudente) — deux boîtes rangées à des températures
//     différentes peuvent porter des DLC différentes ;
//   • traçabilité : la boîte gardée conserve son `etiquetteDe`, son `assembleFrom` et son lot ;
//     la boîte absorbée est enregistrée dans un historique `fusionHisto` (id, lot, quantité, DLC).
//   • journal : une entrée d'audit dédiée (« fusion-boite ») en plus des écritures auto (la mise à
//     jour et la suppression sont déjà journalisées par les hooks v1372).
//
// DEUX MODES (comme demandé) : flash QR des deux boîtes, ou sélection manuelle dans la liste des
// lots ayant au moins deux boîtes.
//
// LIMITE DÉCLARÉE : fusionner la boîte-fille d'une boîte déjà fusionnée (scission d'une boîte)
// sort de « même lot » au sens `etiquetteDe` et sera refusée — c'est volontaire : au-delà d'un
// niveau, la provenance physique n'est plus univoque.
// ════════════════════════════════════════════════════════════════════════════

// Deux boîtes appartiennent-elles au même lot physique ? (PURE)
function _fusionMemeLot(a, b){
  return !!(a && b && a.etiquetteDe != null && b.etiquetteDe != null && a.etiquetteDe === b.etiquetteDe);
}

// Valide une demande de fusion AVANT toute écriture (PURE). Retourne { ok, raison } — le motif est
// une PHRASE lisible (elle finit dans le toast). L'ordre des tests va du plus grossier au plus fin.
function _fusionValide(a, b){
  if(!a || !b) return { ok:false, raison:'Boîte introuvable.' };
  if(a.id === b.id) return { ok:false, raison:'Sélectionne DEUX boîtes différentes.' };
  if(a.etiquetteDe == null || b.etiquetteDe == null)
    return { ok:false, raison:'Seules des boîtes issues d\'un lot peuvent être fusionnées.' };
  if(!_fusionMemeLot(a, b))
    return { ok:false, raison:'Lots différents — fusionner mélangerait la traçabilité physique. Refusé.' };
  const compA = a.composant || 'complet', compB = b.composant || 'complet';
  const libA = a.produitLibre || '', libB = b.produitLibre || '';
  if((a.recipeId != null || b.recipeId != null ? a.recipeId !== b.recipeId : libA !== libB) ||
     compA !== compB || (!!a.degDeclasse) !== (!!b.degDeclasse))
    return { ok:false, raison:'Parfums (ou stades) différents — fusion impossible.' };
  const qA = Math.max(0, +a.qteRestante || 0), qB = Math.max(0, +b.qteRestante || 0);
  if(qA + qB <= 0)
    return { ok:false, raison:'Ces boîtes sont vides — rien à fusionner.' };
  return { ok:true };
}

// La DLC la plus courte (la plus prudente) entre deux (PURE). Format 'AAAA-MM-JJ' → l'ordre
// lexicographique EST l'ordre chronologique. null = pas de DLC → l'autre l'emporte.
function _fusionDlcPlusCourte(a, b){
  if(!a) return b || null;
  if(!b) return a || null;
  return (a <= b) ? a : b;
}

// Calcule l'écriture de fusion (PURE) : le patch de la boîte GARDÉE (a) et l'id de la boîte
// ABSORBÉE (b). `round3` est injecté (global à l'exécution) pour arrondir proprement les quantités.
function _fusionCalcul(a, b, round3){
  const r = round3 || (x => x);
  const qB = r(Math.max(0, +b.qteRestante || 0));
  return {
    garde: a.id,
    supprime: b.id,
    patch: {
      qteRestante:  r((+a.qteRestante  || 0) + (+b.qteRestante  || 0)),
      qteReelle:    r((+a.qteReelle    || 0) + (+b.qteReelle    || 0)),
      qteProduite:  r((+a.qteProduite  || 0) + (+b.qteProduite  || 0)),
      qteTheorique: r((+a.qteTheorique || 0) + (+b.qteTheorique || 0)),
      dlcProduit:   _fusionDlcPlusCourte(a.dlcProduit, b.dlcProduit),
      fusionHisto:  (Array.isArray(a.fusionHisto) ? a.fusionHisto.slice() : []).concat([{
        deId: b.id, deLot: b.lotProduction || '', qte: qB,
        dlcAbsorbee: b.dlcProduit || null, ts: Date.now()
      }])
    }
  };
}

// Exécute la fusion. Valide → sauvegarde de sécurité → transaction (mise à jour de la gardée +
// suppression de l'absorbée) → entrée d'audit dédiée. Les hooks v1372 journalisent déjà chaque
// écriture ; l'entrée « fusion-boite » ajoute la LECTURE HUMAINE de l'événement.
async function fusionnerBoites(idA, idB, retourId){
  const A = await db.productions.get(idA).catch(() => null);
  const B = await db.productions.get(idB).catch(() => null);
  const v = _fusionValide(A, B);
  if(!v.ok){ toast(v.raison); return { ok:false, raison:v.raison }; }
  try{ await snapshotBackup('avant-fusion-boites'); }catch(e){ swallow(e, 'fusionnerBoites snapshot'); }
  const calc = _fusionCalcul(A, B, round3);
  try{
    await db.transaction('rw', db.productions, async () => {
      await db.productions.update(idA, calc.patch);
      // [v1416] La boîte absorbée est ARCHIVÉE, pas supprimée (demande de Ben : « archivée et
      // masquée et non supprimée afin de pouvoir remonter la totalité de la traçabilité »).
      // Avant, `db.productions.delete(idB)` détruisait sa fiche : son parcours de conservation
      // et son origine disparaissaient, et aucun lien cliquable vers elle n'était possible.
      // Elle garde donc sa ligne, avec stock à ZÉRO (son contenu vit désormais dans idA) et un
      // marqueur `fusionneeDans` qui la masque partout où l'on liste le stock vivant.
      await db.productions.update(idB, {
        qteRestante: 0,
        fusionneeDans: idA,
        fusionneeTs: Date.now(),
        fusionneeVersLot: A.lotProduction || ('#'+idA),
      });
    });
  }catch(e){ console.error('fusionnerBoites', e); toast('Échec de la fusion'); return { ok:false }; }
  try{
    await db.auditLog.add({ ts:Date.now(), tbl:'productions', op:'fusion-boite', cle:idA,
      resume:_auditResume({
        garde:{ id:idA, lot:A.lotProduction }, absorbee:{ id:idB, lot:B.lotProduction, qte:round3(Math.max(0, +B.qteRestante || 0)) },
        qteRestanteApres:calc.patch.qteRestante, dlcRetenue:calc.patch.dlcProduit }),
      ecran:(typeof view !== 'undefined' && view) ? String(view) : '', v:APP_VERSION });
  }catch(e){ swallow(e, 'audit fusion-boite'); }
  toast('Boîtes fusionnées ✓ · traçabilité conservée');
  if(typeof view !== 'undefined' && view === 'stockparfums' && typeof renderStockParfums === 'function') renderStockParfums();
  // [v1456] Ben : « en cas de fusion de boîte je dois pouvoir réimprimer une étiquette mise à
  // jour ». La fusion est LE cas où l'étiquette en place devient fausse sans recours : la boîte
  // gardée contient d'autres pièces qu'annoncé, et sa DLC a pu raccourcir. Contrairement à un
  // prélèvement (que Ben corrige au stylo), il n'y a rien à corriger à la main ici — et
  // l'étiquette de la boîte absorbée n'a plus d'objet. On PROPOSE donc la réimpression au moment
  // exact où elle devient nécessaire, sans l'imposer.
  // Le retour à la vue d'ensemble est confié à la proposition : ouvrir les deux écrans à la
  // suite ferait disparaître le premier avant qu'on l'ait lu.
  await proposerReimpressionEtiquette(idA, retourId, 'fusion');
  return { ok:true, garde:idA };
}

// [v1456] PROPOSE de réimprimer l'étiquette d'une boîte dont le contenu vient de changer.
// Le NUMÉRO DE LOT ne change pas (décision de l'étiquette recyclable, v1454 : le QR encode l'URL
// bâtie sur ce numéro — le faire varier rendrait mortes toutes les étiquettes déjà imprimées).
// Ce qui change sur le papier, c'est la QUANTITÉ et la DLC : une réimpression, pas une nouvelle
// identité. `retourId` : vue d'ensemble à rouvrir ensuite, passée de main en main (jamais une
// variable globale, qui survivrait à une annulation et rouvrirait un écran sans rapport).
// N'ÉCRIT RIEN en base : elle propose, elle ne modifie pas.
async function proposerReimpressionEtiquette(prodId, retourId, contexte){
  const p = await db.productions.get(+prodId).catch(()=>null);
  const retour = (retourId!=null) ? +retourId : null;
  const _rouvrir = () => { if(retour!=null && typeof vueBoitesDuLot==='function') vueBoitesDuLot(retour); };
  if(!p){ _rouvrir(); return; }
  const q = round3(Math.max(0, +p.qteRestante||0));
  const dlc = (typeof prodDlcEffective==='function') ? prodDlcEffective(p) : p.dlcProduit;
  const motif = contexte==='fusion'
    ? 'Cette boîte contient désormais le contenu des deux — son étiquette n\'est plus à jour.'
    : 'Le contenu de cette boîte a changé — son étiquette n\'est plus à jour.';
  openModal(`<h3>🖨 Réimprimer l'étiquette ?</h3>
    <p class="note">${motif}</p>
    <div class="sum-box"><span>Boîte <b>${esc(p.lotProduction||('#'+p.id))}</b></span>
      <b>${qty(q)} pièce(s)</b></div>
    ${dlc?`<div class="sum-box"><span>DLC à imprimer</span><b>${fmtDate(dlc)}</b></div>`:''}
    <p class="note" style="margin-top:8px">Le numéro de lot et son QR ne changent pas : seule la quantité imprimée est à corriger.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal();${retour!=null?`vueBoitesDuLot(${retour})`:''}">Plus tard</button>
      <button class="btn" onclick="closeModal();shareLabelImage(${+p.id})">🖨 Réimprimer</button>
    </div>`);
}

// [v1455] TRANSFÉRER DES PIÈCES D'UNE BOÎTE À UNE AUTRE (partiel). Ben : « lorsque je les
// répartis en boites une fois garnis je dois pouvoir facilement transférer manuellement un ou
// plusieurs macarons d'une boîte à une autre (pour gérer les erreurs de saisies) ».
//
// DIFFÉRENT DE LA FUSION : la fusion vide entièrement une boîte dans une autre. Ici on déplace
// une QUANTITÉ. Si ce transfert vide la source, on retombe exactement sur une fusion — et on
// l'archive comme telle (`fusionneeDans`), plutôt que de laisser traîner une boîte vide avec une
// étiquette qui ne correspond plus à rien. Règle cohérente avec la décision de Ben : « prélèvement
// qui vide complètement une boîte → pas de nouvelle étiquette, la boîte est archivée ».
//
// MÊME LOT UNIQUEMENT : transférer entre deux lots mélangerait des fabrications distinctes sous
// une même étiquette — c'est ce que `_fusionValide` refuse déjà, et pour la même raison.
// DLC de la destination : la PLUS COURTE des deux (sécurité alimentaire), jamais celle qui arrange.
async function transfererEntreBoites(sourceId, destId, qte){
  const src = await db.productions.get(+sourceId).catch(()=>null);
  const dst = await db.productions.get(+destId).catch(()=>null);
  const q = round3(Math.max(0, +qte||0));
  if(!src || !dst) return { ok:false, raison:'Boîte introuvable.' };
  if(+src.id === +dst.id) return { ok:false, raison:'Choisis deux boîtes différentes.' };
  if(q <= 0) return { ok:false, raison:'Indique une quantité à transférer.' };
  // On réutilise la validation de la fusion : mêmes règles de compatibilité (même lot, même
  // parfum, même stade, pas de boîte orpheline). Elle refuse aussi deux boîtes vides.
  const v = _fusionValide(src, dst);
  if(!v.ok) return { ok:false, raison:v.raison };
  const dispo = round3(Math.max(0, +src.qteRestante||0));
  if(q > dispo + 1e-9) return { ok:false, raison:`Maximum ${qty(dispo)} pièce(s) dans la boîte de départ.` };
  const videLaSource = (q >= dispo - 1e-9);
  try{ await snapshotBackup('avant-transfert-boites'); }catch(e){ swallow(e,'transfererEntreBoites snapshot'); }
  const ts = Date.now();
  const nowIso = new Date().toISOString();
  const entree = { deId:+src.id, deLot:src.lotProduction||'', versId:+dst.id, versLot:dst.lotProduction||'', qte:q, ts };
  try{
    await db.transaction('rw', db.productions, async () => {
      const patchDst = {
        qteRestante: round3((+dst.qteRestante||0) + q),
        dlcProduit: _fusionDlcPlusCourte(dst.dlcProduit, src.dlcProduit),
        transfertHisto: (Array.isArray(dst.transfertHisto)?dst.transfertHisto.slice():[]).concat([Object.assign({sens:'entrant'}, entree)])
      };
      await db.productions.update(+dst.id, patchDst);
      if(videLaSource){
        // Transfert total = fusion. Même archivage que fusionnerBoites (invariant v1416) : la
        // ligne survit, à zéro, avec le marqueur qui la masque des listes de stock vivant.
        await db.productions.update(+src.id, {
          qteRestante: 0, fusionneeDans: +dst.id, fusionneeTs: ts,
          fusionneeVersLot: dst.lotProduction || ('#'+dst.id),
          transfertHisto: (Array.isArray(src.transfertHisto)?src.transfertHisto.slice():[]).concat([Object.assign({sens:'sortant'}, entree)])
        });
      } else {
        await db.productions.update(+src.id, {
          qteRestante: round3(dispo - q),
          transfertHisto: (Array.isArray(src.transfertHisto)?src.transfertHisto.slice():[]).concat([Object.assign({sens:'sortant'}, entree)])
        });
      }
    });
  }catch(e){ console.error('transfererEntreBoites', e); toast('Échec du transfert'); return { ok:false }; }
  try{
    await db.auditLog.add({ ts, tbl:'productions', op:'transfert-boite', cle:+dst.id,
      resume:_auditResume({ de:{ id:+src.id, lot:src.lotProduction }, vers:{ id:+dst.id, lot:dst.lotProduction },
        qte:q, sourceVidee:videLaSource }),
      ecran:(typeof view!=='undefined' && view)?String(view):'', v:APP_VERSION });
  }catch(e){ swallow(e,'audit transfert-boite'); }
  void nowIso;
  return { ok:true, sourceVidee:videLaSource, qte:q };
}

// Les autres boîtes du même lot qu'une boîte donnée (avec stock), hors elle-même.
async function _fusionBoitesDuLot(etiquetteDe, exclureId){
  return (await db.productions.toArray().catch(() => []))
    .filter(p => p.etiquetteDe === etiquetteDe && p.id !== exclureId && round3(+p.qteRestante || 0) > 0);
}

// [v1454] REGROUPER TOUTES LES BOÎTES D'UN LOT EN UNE SEULE. Ben : « si j'ai 200 coques réparties
// en 6 boîtes je dois faire mon assemblage à 6 reprises, alors que dans la réalité je sors
// l'ensemble des coques de leurs boites (à ce stade les boites n'existent plus que sur
// l'application et plus dans la réalité), les dispose sur mon plan de travail et les garnis ».
// Le regroupement DÉCRIT ce qui vient de se passer en atelier — ce n'est pas un artifice pour
// contourner le sélecteur.
//
// Réutilise _fusionValide/_fusionCalcul (éprouvés v1376/v1416) mais en UNE SEULE transaction :
// enchaîner N-1 appels à fusionnerBoites ferait N-1 sauvegardes de sécurité, N-1 toasts et N-1
// entrées d'audit pour UN seul geste métier. Ici : une sauvegarde, une écriture atomique, une
// entrée d'audit qui nomme toutes les boîtes absorbées.
//
// Les boîtes absorbées sont ARCHIVÉES (qteRestante:0 + fusionneeDans), jamais supprimées —
// invariant v1416, c'est ce qui garde la traçabilité de chacune consultable après coup.
async function regrouperBoitesLot(prodId){
  const p = await db.productions.get(+prodId).catch(()=>null);
  if(!p) return { ok:false, raison:'Lot introuvable' };
  const prods = await db.productions.toArray().catch(()=>[]);
  const parentId = (p.etiquetteDe!=null) ? +p.etiquetteDe : +p.id;
  // Seules les BOÎTES (etiquetteDe posé) se fusionnent : le parent porte le reste non réparti et
  // _fusionValide le refuse explicitement. C'est voulu — on ne fusionne pas du vrac dans une boîte.
  const boites = prods.filter(x => x && !prodEstFusionnee(x)
    && x.etiquetteDe != null && +x.etiquetteDe === parentId
    && round3(+x.qteRestante||0) > 0);
  if(boites.length <= 1) return { ok:true, gardeId:(boites[0]? +boites[0].id : +prodId), nbFusionnees:0 };
  // La boîte gardée = la première dans l'ordre des numéros de lot (B1 avant B2) : le numéro qui
  // survit est le plus lisible. La DLC, elle, ne dépend PAS de ce choix — _fusionCalcul retient
  // toujours la plus courte des deux, à chaque étape de la chaîne.
  boites.sort((a,b)=>String(a.lotProduction||'').localeCompare(String(b.lotProduction||'')));
  const garde = boites[0];
  const autres = boites.slice(1);
  let etat = Object.assign({}, garde);
  const archives = [];
  for(const b of autres){
    const v = _fusionValide(etat, b);
    if(!v.ok) return { ok:false, raison:v.raison };
    const calc = _fusionCalcul(etat, b, round3);
    etat = Object.assign({}, etat, calc.patch);
    archives.push({ id:+b.id, lot:b.lotProduction||('#'+b.id), qte:round3(Math.max(0,+b.qteRestante||0)) });
  }
  try{ await snapshotBackup('avant-regroupement-boites'); }catch(e){ swallow(e,'regrouperBoitesLot snapshot'); }
  const patchGarde = {
    qteRestante: etat.qteRestante, qteReelle: etat.qteReelle,
    qteProduite: etat.qteProduite, qteTheorique: etat.qteTheorique,
    dlcProduit: etat.dlcProduit, fusionHisto: etat.fusionHisto
  };
  try{
    await db.transaction('rw', db.productions, async () => {
      await db.productions.update(+garde.id, patchGarde);
      for(const a of archives){
        await db.productions.update(a.id, {
          qteRestante: 0, fusionneeDans: +garde.id, fusionneeTs: Date.now(),
          fusionneeVersLot: garde.lotProduction || ('#'+garde.id)
        });
      }
    });
  }catch(e){ console.error('regrouperBoitesLot', e); toast('Échec du regroupement'); return { ok:false }; }
  try{
    await db.auditLog.add({ ts:Date.now(), tbl:'productions', op:'regroupement-boites', cle:+garde.id,
      resume:_auditResume({ garde:{ id:+garde.id, lot:garde.lotProduction }, absorbees:archives,
        qteRestanteApres:patchGarde.qteRestante, dlcRetenue:patchGarde.dlcProduit }),
      ecran:(typeof view!=='undefined' && view)?String(view):'', v:APP_VERSION });
  }catch(e){ swallow(e,'audit regroupement-boites'); }
  return { ok:true, gardeId:+garde.id, nbFusionnees:archives.length };
}

// [v1454] ASSEMBLER TOUT UN LOT DE COQUES, quelles que soient ses boîtes. Regroupe d'abord (voir
// ci-dessus), puis ouvre le formulaire d'assemblage NORMAL sur la ligne unique qui en résulte.
// Le moteur d'assemblage (prodAssembleSave) n'est pas touché : il continue de voir un seul lot de
// coques, ce qu'il sait déjà faire — y compris le 2e lot bicolore, la chantache et les gardes
// dégustation. Deux mécanismes éprouvés au lieu d'une réécriture du plus délicat.
async function prodAssembleLotEntier(prodId, opts){
  const r = await regrouperBoitesLot(prodId);
  if(!r.ok){ toast(r.raison || 'Regroupement impossible'); return; }
  if(r.nbFusionnees > 0) toast(`${r.nbFusionnees+1} boîtes regroupées ✓ — assemblage sur le lot entier`);
  return prodAssembleForm(r.gardeId, opts);
}

// Petit descriptif d'une boîte pour les écrans de fusion.
function _fusionLigneBoite(p){
  const emp = (typeof empInfo === 'function' && p.emplacement) ? empInfo(p.emplacement) : null;
  const empTxt = emp ? `${emp.icon || ''} ${esc(emp.nom || '')}` : '—';
  return `<b>${qty(round3(+p.qteRestante || 0))} pc</b> · ${empTxt} · DLC ${p.dlcProduit ? fmtDate(p.dlcProduit) : '—'}<br>
    <span style="font-size:.74rem;color:#9a8a82">lot ${esc(p.lotProduction || '—')}</span>`;
}

// ── MODE 1 : SÉLECTION MANUELLE ──────────────────────────────────────────────
// Liste les lots ayant AU MOINS deux boîtes ; dans chaque lot, on coche exactement deux boîtes.
async function fusionOuvrir(){
  const prods = (await db.productions.toArray().catch(() => []))
    .filter(p => p.etiquetteDe != null && round3(+p.qteRestante || 0) > 0);
  const recipes = await db.recipes.toArray().catch(() => []);
  const groupes = {};
  prods.forEach(p => { (groupes[p.etiquetteDe] = groupes[p.etiquetteDe] || []).push(p); });
  const multi = Object.keys(groupes).filter(k => groupes[k].length >= 2);

  const nomLot = g => (typeof prodNomComplet === 'function') ? prodNomComplet(g[0], recipes) : ((recipes.find(r => +r.id === +g[0].recipeId) || {}).produitNom || g[0].produitLibre || 'Lot');
  const blocs = multi.map(k => {
    const g = groupes[k].sort((a, b) => (a.dlcProduit || '9999').localeCompare(b.dlcProduit || '9999'));
    return `<div class="panel" style="margin-bottom:8px">
      <b>${esc(nomLot(g))}</b> <span class="lb-sec-n">${g.length} boîtes</span>
      ${g.map(p => `<label class="sum-box" style="cursor:pointer;align-items:flex-start;gap:8px">
        <input type="checkbox" class="fus-sel-${k}" value="${p.id}" style="width:18px;height:18px;margin-top:3px"
          onchange="fusionMajBouton(${k})">
        <span style="flex:1;font-size:.82rem">${_fusionLigneBoite(p)}</span></label>`).join('')}
      <button class="btn gold" id="fusBtn_${k}" disabled style="opacity:.45;width:100%;margin-top:6px"
        onclick="fusionDepuisSelection(${k})">🔀 Fusionner les 2 boîtes cochées</button>
    </div>`;
  }).join('');

  openModal(`<h3>🔀 Fusionner deux boîtes</h3>
    <p class="note" style="margin-bottom:8px">On ne fusionne que deux boîtes du <b>même parfum et du même lot</b> — c'est la seule façon de garder la traçabilité physique. Coche exactement deux boîtes d'un même lot.</p>
    ${multi.length ? blocs : '<p class="note">Aucun lot n\'a plusieurs boîtes en stock à fusionner pour le moment.</p>'}
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Fermer</button>
      <button class="btn" onclick="fusionScanA()">📷 Scanner les boîtes</button>
    </div>`);
}

// Active le bouton d'un lot dès que DEUX boîtes de CE lot sont cochées (et pas plus).
function fusionMajBouton(grp){
  const n = document.querySelectorAll('.fus-sel-' + grp + ':checked').length;
  const btn = document.getElementById('fusBtn_' + grp);
  if(!btn) return;
  const ok = (n === 2);
  btn.disabled = !ok; btn.style.opacity = ok ? '1' : '.45';
  btn.textContent = n > 2 ? '⚠️ Coche seulement 2 boîtes' : '🔀 Fusionner les 2 boîtes cochées';
}

// Lit la sélection (deux cases d'un même lot) et passe à la confirmation. Même lot GARANTI par
// construction (les cases appartiennent au même groupe).
function fusionDepuisSelection(grp){
  const checked = Array.from(document.querySelectorAll('.fus-sel-' + grp + ':checked'));
  if(checked.length !== 2){ toast('Coche exactement 2 boîtes'); return; }
  fusionConfirme(+checked[0].value, +checked[1].value);
}

// ── MODE 2 : FLASH QR ────────────────────────────────────────────────────────
// Scanne la 1ʳᵉ boîte, puis propose de scanner la 2ᵉ (ou de la choisir parmi le même lot).
function fusionScanA(){
  if(typeof openScanner !== 'function'){ toast('Scanner indisponible'); return; }
  openScanner(async (code) => {
    const a = await _fusionBoiteDepuisScan(code);
    if(a) fusionEtape2(a.id);
  });
}
async function _fusionBoiteDepuisScan(code){
  const lot = _extractLot(code);
  const p = (await db.productions.toArray().catch(() => []))
    .find(x => normTxt(x.lotProduction || '') === normTxt(lot));
  if(!p){ toast('Lot ' + lot + ' introuvable'); return null; }
  if(p.etiquetteDe == null){ toast('Ce QR n\'est pas une boîte issue d\'un lot.'); return null; }
  if(round3(+p.qteRestante || 0) <= 0){ toast('Cette boîte est vide.'); return null; }
  return p;
}
// Après la 1ʳᵉ boîte : on montre les autres boîtes du MÊME lot (tap direct) + l'option de scanner.
async function fusionEtape2(idA, retourId){   // [v1422] retourId : d'où l'on vient, pour y revenir après la fusion
  const A = await db.productions.get(idA).catch(() => null);
  if(!A){ toast('Boîte introuvable'); return; }
  const recipes = await db.recipes.toArray().catch(() => []);
  const nom = (typeof prodNomComplet === 'function') ? prodNomComplet(A, recipes) : '';
  const autres = await _fusionBoitesDuLot(A.etiquetteDe, idA);
  const _ret = (retourId!=null) ? +retourId : 'null';   // [v1422] jamais « undefined » dans un onclick
  const liste = autres.length
    ? autres.map(p => `<label class="sum-box" style="cursor:pointer" onclick="fusionConfirme(${idA},${p.id},${_ret})">
        <span style="flex:1;font-size:.82rem">${_fusionLigneBoite(p)}</span><span>→</span></label>`).join('')
    : '<p class="note">Aucune autre boîte de ce lot n\'a de stock. Scanne une boîte du même lot.</p>';
  openModal(`<h3>🔀 2ᵉ boîte à fusionner</h3>
    <p class="note" style="margin-bottom:8px"><b>${esc(nom)}</b> — 1ʳᵉ boîte : ${_fusionLigneBoite(A)}</p>
    <p class="note" style="margin-bottom:6px">Choisis la 2ᵉ boîte du <b>même lot</b> :</p>
    ${liste}
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="fusionScanB(${idA},${_ret})">📷 Scanner la 2ᵉ boîte</button>
    </div>`);
}
function fusionScanB(idA, retourId){
  if(typeof openScanner !== 'function'){ toast('Scanner indisponible'); return; }
  openScanner(async (code) => {
    const b = await _fusionBoiteDepuisScan(code);
    if(b) fusionConfirme(idA, b.id, retourId);
  });
}

// ── CONFIRMATION (commune aux deux modes) ────────────────────────────────────
async function fusionConfirme(idA, idB, retourId){
  const A = await db.productions.get(idA).catch(() => null);
  const B = await db.productions.get(idB).catch(() => null);
  const v = _fusionValide(A, B);
  if(!v.ok){ toast(v.raison); return; }
  const calc = _fusionCalcul(A, B, round3);
  const recipes = await db.recipes.toArray().catch(() => []);
  const nom = (typeof prodNomComplet === 'function') ? prodNomComplet(A, recipes) : '';
  const empDiff = (A.emplacement || '') !== (B.emplacement || '');
  const dlcDiff = (A.dlcProduit || '') !== (B.dlcProduit || '');
  const empGarde = (typeof empInfo === 'function' && A.emplacement) ? empInfo(A.emplacement) : null;
  const _ret = (retourId!=null) ? +retourId : 'null';   // [v1422]
  openModal(`<h3>🔀 Confirmer la fusion</h3>
    <p class="note"><b>${esc(nom)}</b> — même lot, même parfum.</p>
    <div class="sum-box" style="align-items:flex-start"><span style="flex:1">Boîte A (gardée)<br><span style="font-size:.78rem;color:#9a8a82">${_fusionLigneBoite(A)}</span></span></div>
    <div class="sum-box" style="align-items:flex-start"><span style="flex:1">Boîte B (absorbée)<br><span style="font-size:.78rem;color:#9a8a82">${_fusionLigneBoite(B)}</span></span></div>
    <div class="sum-box" style="background:#faf6ee"><span><b>Après fusion</b></span>
      <b>${qty(calc.patch.qteRestante)} pc · DLC ${calc.patch.dlcProduit ? fmtDate(calc.patch.dlcProduit) : '—'}${empGarde ? ' · ' + esc(empGarde.nom || '') : ''}</b></div>
    ${dlcDiff ? `<p class="note" style="color:#8a6d3b">On garde la DLC la plus courte (la plus prudente).</p>` : ''}
    ${empDiff ? `<p class="note" style="color:#8a6d3b">Les deux boîtes sont à des emplacements différents : la boîte fusionnée reste à celui de la boîte A. Rapproche-les physiquement.</p>` : ''}
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="closeModal(); fusionnerBoites(${idA}, ${idB}, ${_ret})">✓ Fusionner</button>
    </div>`);
}

async function buildLabelData(prodId){
  const p = await db.productions.get(prodId);
  if(!p) return null;
  const rec = p.recipeId!=null ? await db.recipes.get(p.recipeId) : null;
  const tmp = document.createElement('canvas');
  try{ QR.render(tmp, traceUrl(p.lotProduction||''), {scale:6, dark:'#000000', light:'#ffffff'}); }catch(e){swallow(e,'buildLabelData')}
  // Nom AFFICHÉ = vrai stade du batch (un composant n'est pas le produit fini) :
  //  coques → « Coques <parfum> » · ganache/crémeux → « Ganache/Crémeux <parfum> »
  //  complet/assemblé → nom du produit fini.
  const _comp = (typeof prodComposant==='function') ? prodComposant(p) : 'complet';
  const _parfum = rec ? rec.produitNom : (p.produitLibre || 'Produit');
  let _nomAffiche = _parfum;
  if(_comp==='coques')       _nomAffiche = 'Coques ' + _parfum;
  else if(_comp==='ganache') _nomAffiche = ((typeof garnLabel==='function'?garnLabel(p):'ganache').charAt(0).toUpperCase()+ (typeof garnLabel==='function'?garnLabel(p):'ganache').slice(1)) + ' ' + _parfum;
  else if(_comp==='degustation') _nomAffiche = _parfum + ' (dégustation)';
  // sinon (complet/assemble) on garde le nom du produit fini.
  // [v1454] QUANTITÉ IMPRIMÉE = CE QUI RESTE, pas ce qui a été produit. Ben veut une étiquette
  // « recyclée » : il corrige la quantité au stylo à chaque prélèvement, et le QR renvoie à la
  // quantité réelle du moment dans l'app. Une étiquette qui démarre sur la quantité PRODUITE
  // serait déjà fausse à l'impression pour une boîte issue d'un lot entamé — le stylo devrait
  // corriger dès le premier jour. Même règle que v1429 : une information de stock montre le stock.
  // Repli sur la produite pour les lots anciens sans qteRestante (prodQteStock fait déjà ce repli).
  const _nbPieces = (typeof prodQteStock==='function')
    ? prodQteStock(p)
    : ((p.qteReelle!=null)?p.qteReelle:(p.qteProduite!=null?p.qteProduite:(p.qteTheorique!=null?p.qteTheorique:null)));
  return {
    produit: _nomAffiche,
    composant: _comp,
    nbPieces: _nbPieces,
    // [v1458] Ben : « l'app me propose d'editer une étiquette spéciale retour marché ». Ces
    // macarons sont revenus d'un marché, provenance non identifiée : leur étiquette doit se
    // distinguer AU COUP D'ŒIL dans un frigo, sinon rien ne les différencie d'un lot de
    // production normal — et c'est justement leur particularité qu'il faut garder en tête.
    retourMarche: !!p.retourMarche,
    lot: p.lotProduction||'—',
    dlc: (function(){ const d=(typeof prodDlcEffective==='function')?prodDlcEffective(p):p.dlcProduit; return d ? fmtDate(d) : '—'; })(),
    // Fabrication = heure de FIN de production (prodTermineTs).
    // Repli : ancien horodatage de fin, sinon date saisie. Heure au format 00:00.
    fab: (p.prodTermineTs || (prodStatut(p)==='termine' ? p.prodTimestamp : '')) ? fmtDateTime(p.prodTermineTs || p.prodTimestamp) : fmtDate(p.date),
    emplacement: p.emplacement ? empNom(p.emplacement) : '',
    empLettre: p.emplacement ? empLettre(p.emplacement) : '',
    empType: p.emplacement ? empInfo(p.emplacement).type : '',
    qr: tmp.toDataURL('image/png')
  };
}
// HTML d'UNE étiquette (50×25 mm, noir sur blanc, QR à gauche / infos à droite).
// La lettre d'emplacement est affichée dans une pastille pour localiser la production.
function renderLabelHTML(d){
  const pastille = d.empLettre ? `<span class="emp">${esc(d.empLettre)}</span>` : '';
  // [v1458] LA QUANTITÉ MANQUAIT ICI. Elle était calculée (`nbPieces`) et imprimée par le moteur
  // canvas/PDF, mais ce rendu HTML ne l'affichait pas — l'étiquette « recyclable » de Ben (il
  // corrige la quantité au stylo à chaque prélèvement) n'avait donc rien à corriger sur ce chemin.
  const pieces = (d.nbPieces!=null) ? `<div class="row">${esc(typeof qty==='function'?qty(d.nbPieces):String(d.nbPieces))} pièces</div>` : '';
  // Bandeau retour marché : même information que sur le moteur canvas, même place (sous le nom).
  const retour = d.retourMarche ? `<div class="rm">↩ RETOUR MARCHÉ</div>` : '';
  return `<div class="lab">
     <div class="q"><img src="${d.qr}"></div>
     <div class="t">
       <div class="prod">${esc(d.produit)}${pastille}</div>
       ${retour}
       <div class="row">Lot ${esc(d.lot)}</div>
       ${pieces}
       <div class="dlc">DLC ${esc(d.dlc)}</div>
       <div class="row">Fab. ${esc(d.fab)}</div>
     </div>
   </div>`;
}
// Ouvre une fenêtre d'impression contenant une feuille de plusieurs étiquettes.
// `labels` = tableau de données d'étiquette (déjà multiplié par le nombre de copies).
// Format Phomemo D520BT : 50 mm (longueur) × 25 mm (hauteur), QR à gauche, texte à droite.
function printLabelSheet(labels, titre){
  if(!labels || !labels.length){ toast('Aucune étiquette à imprimer'); return; }
  const win = window.open('', '_blank', 'width=420,height=300');
  if(!win){ toast('Autorise les fenêtres pour imprimer'); return; }
  win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(titre||'Étiquettes')}</title>
   <style>
     @page { size: 50mm 25mm; margin: 0; }
     * { margin:0; padding:0; box-sizing:border-box; }
     html,body { background:#fff; }
     .lab { width:50mm; height:25mm; background:#fff; color:#000; padding:1.2mm;
            font-family:Arial,Helvetica,sans-serif; display:flex; gap:1.2mm; align-items:center;
            page-break-after:always; break-after:page; overflow:hidden; }
     .lab:last-child { page-break-after:auto; break-after:auto; }
     /* QR carré calé sur la hauteur utile (25 − 2×1.2 padding ≈ 22.6 mm) */
     .lab .q { width:21mm; height:21mm; flex-shrink:0; }
     .lab .q img { width:21mm; height:21mm; display:block; image-rendering:pixelated; }
     .lab .t { flex:1; min-width:0; line-height:1.15; overflow:hidden; }
     .lab .prod { font-size:2.9mm; font-weight:bold; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
     .lab .prod .emp { display:inline-block; border:0.3mm solid #000; border-radius:1mm; padding:0 0.8mm; margin-left:1mm; font-size:2.6mm; line-height:1; }
     .lab .row { font-size:2.3mm; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
     .lab .dlc { font-size:2.7mm; font-weight:bold; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
     /* [v1458] Bandeau « retour marché » : inversé (noir plein) pour rester lisible sur une
        imprimante thermique monochrome, où une couleur ou une trame disparaîtrait. */
     .lab .rm { font-size:2.4mm; font-weight:bold; background:#000; color:#fff; padding:0.2mm 0.8mm;
                display:inline-block; border-radius:0.6mm; margin:0.3mm 0; }
   </style></head><body>
   ${labels.map(renderLabelHTML).join('')}
   <script>window.onload=function(){setTimeout(function(){window.print();},300);};window.onafterprint=function(){window.close();};<\/script>
   </body></html>`);
  win.document.close();
}
// Impression d'une étiquette unique (compat. bouton existant).
async function printLabel(prodId){
  // v971 : impression sans friction → PNG 105×55 mm + partage natif (plus de popup navigateur).
  return shareLabelImage(prodId);
}
// Impression EN LOT : N copies d'un même batch.
async function printLabelCopies(prodId){
  // v971 : génère UNE image PNG 105×55 mm et la partage. Le nombre d'exemplaires se règle
  // directement dans Labelife au moment d'imprimer (plus fiable qu'une feuille multi-pages).
  const p = await db.productions.get(prodId);
  if(p && prodStatut(p)!=='termine'){
    if(!confirm('Cette production est encore « démarrée » : sa DLC n\'est pas figée. Générer quand même l\'étiquette sans DLC ?')) return;
  }
  return shareLabelImage(prodId);
}
// Impression des étiquettes liées à UNE commande : un batch par produit lié,
// nombre d'étiquettes = quantité de pièces liées (ou 1 par lien selon le choix).
// Données de l'ÉTIQUETTE RÉCAPITULATIVE d'une commande (différente de l'étiquette batch) :
// - liste des PARFUMS lue dans le CONTENU de la commande (o.lignes[].parfums[].nom) → vrais noms
//   (« Mangue passion »…), pas les batchs liés. Chaque parfum aura sa case ☐ + espace quantité.
// - numéros de lot pris sur les batchs réellement liés (orderItems → productions.lotProduction)
// - date de fabrication = fin de production la plus récente parmi les batchs liés
// - DLC = DATE DE LIVRAISON (o.date) + 4 jours, calculée sur la livraison, jamais sur l'impression
async function buildOrderLabelData(orderId){
  const o = await db.orders.get(orderId); if(!o) return null;
  const recipes = await db.recipes.toArray();   // chargé une fois, sert aux noms ET au format (DLC)
  // 1) PARFUMS depuis le contenu de la commande (source de vérité des noms commandés)
  const parfumsOrdre = [];   // garde l'ordre, dédupliqué
  const _seen = new Set();
  (orderToLines(o)||[]).forEach(ln=>{
    (ln.parfums||[]).forEach(pf=>{
      const nom = (pf && pf.nom||'').trim();
      if(nom && +pf.qte>0 && !_seen.has(nom.toLowerCase())){ _seen.add(nom.toLowerCase()); parfumsOrdre.push(nom); }
    });
  });
  // 2) LOTS + date de fabrication depuis les batchs liés (picking)
  const links = await db.orderItems.where('orderId').equals(orderId).toArray();
  const lotsAll = new Set();
  let fabTsMax = '';
  if(links.length){
    const recName = id => (recipes.find(r=>r.id===id)||{}).produitNom||'';
    for(const it of links){
      const p = await db.productions.get(it.productionId); if(!p) continue;
      const lot = p.lotProduction||'';
      if(lot) lotsAll.add(lot);
      const ts = p.prodTermineTs || p.prodTimestamp || (p.date?p.date+'T00:00':'');
      if(ts && ts>fabTsMax) fabTsMax = ts;
      // si le contenu de commande était vide (rare), on complète les parfums via les batchs liés
      if(!parfumsOrdre.length){
        const nom = prodNomComplet(p, recipes);
        if(nom && !_seen.has(nom.toLowerCase())){ _seen.add(nom.toLowerCase()); parfumsOrdre.push(nom); }
      }
    }
  }
  // 3) DLC = date de livraison + N jours (4 j grand format, 6 j classique).
  // Calcul local (sans toISOString → pas de décalage UTC). On VENTILE par type :
  // si la commande mélange grands formats et classiques, on renvoie deux DLC distinctes.
  const pad = n => String(n).padStart(2,'0');
  const dlcDepuisLivraison = jours => {
    if(!o.date) return '';
    const [yy,mm,dd] = o.date.split('-').map(Number);
    const dl = new Date(yy, (mm||1)-1, dd||1);
    dl.setDate(dl.getDate()+jours);
    return `${dl.getFullYear()}-${pad(dl.getMonth()+1)}-${pad(dl.getDate())}`;
  };
  // Quels types de format sont présents dans la commande ?
  let aGrandFormat = false, aStandard = false;
  parfumsOrdre.forEach(nom => {
    const r = recipeForFlavorName(nom, recipes);
    if(r && r.grandFormat) aGrandFormat = true; else aStandard = true;
  });
  // Si aucun parfum identifié (cas limite), on retombe sur la durée standard.
  if(!aGrandFormat && !aStandard) aStandard = true;
  const dlcParType = [];
  if(aGrandFormat){
    const s = dlcDepuisLivraison(DLC_JOURS.grandFormat);
    if(s) dlcParType.push({ type:'grand', label:'Grands formats', dlc: fmtDate(s) });
  }
  if(aStandard){
    const s = dlcDepuisLivraison(DLC_JOURS.standard);
    if(s) dlcParType.push({ type:'std', label:'Classiques', dlc: fmtDate(s) });
  }
  // DLC simple (compat) : la plus courte présente, pour les usages qui n'affichent qu'une valeur.
  const dlcCourte = aGrandFormat ? dlcDepuisLivraison(DLC_JOURS.grandFormat) : dlcDepuisLivraison(DLC_JOURS.standard);
  return {
    parfums: parfumsOrdre,
    lots: [...lotsAll],
    fab: fabTsMax ? fmtDate(fabTsMax.slice(0,10)) : (o.date?fmtDate(o.date):'—'),
    dlc: dlcCourte ? fmtDate(dlcCourte) : '—',   // compat : une seule valeur (la plus courte)
    dlcParType,                                   // ventilation : 1 entrée si un seul type, 2 si mixte
    mixteFormats: aGrandFormat && aStandard,
    livraison: o.date ? fmtDate(o.date) : '—'
  };
}
// HTML d'une étiquette récapitulative de commande (50×25 mm, SANS QR : toute la largeur au texte).
function renderOrderLabelHTML(d){
  const parfRows = d.parfums.map(nom=>`<div class="pf">☐ ${esc(nom)} <span class="qn">___</span></div>`).join('');
  const lotsTxt = d.lots.length ? d.lots.map(esc).join(', ') : '—';
  // DLC : une seule valeur si la commande est d'un seul format ; ventilée si elle mélange
  // grands formats (4 j) et classiques (6 j).
  const mixte = d.mixteFormats && Array.isArray(d.dlcParType) && d.dlcParType.length>1;
  const headDlc = mixte
    ? `<span class="odlc">DLC ↓</span>`
    : `<span class="odlc">DLC ${esc(d.dlc)}</span>`;
  const dlcVentil = mixte
    ? `<div class="odlcv">${d.dlcParType.map(x=>`<span>${esc(x.label)} : <b>${esc(x.dlc)}</b></span>`).join('')}</div>`
    : '';
  return `<div class="olab">
     <div class="ohead"><span class="ofab">Fab. ${esc(d.fab)}</span>${headDlc}</div>
     ${dlcVentil}
     <div class="opf">${parfRows||'<div class="pf">☐ ______ <span class="qn">___</span></div>'}</div>
     <div class="olots">Lots : ${lotsTxt}</div>
   </div>`;
}
