// Imprime N copies de l'étiquette récapitulative d'une commande.
async function printOrderRecapLabel(orderId, copies){
  const d = await buildOrderLabelData(orderId);
  if(!d){ toast('Aucun batch lié à cette commande. Liez d\'abord des batchs.'); return; }
  const n = Math.max(1, Math.min(50, +copies||1));
  const sheet=[]; for(let i=0;i<n;i++) sheet.push(d);
  printOrderLabelSheet(sheet, 'Récap commande #'+orderId);
  toast(`${n} étiquette(s) récap envoyée(s) à l'impression`);
}
async function printOrderLabels(orderId, mode){
  const links = await db.orderItems.where('orderId').equals(orderId).toArray();
  if(!links.length){ toast('Aucun batch lié à cette commande. Liez d\'abord des batchs.'); return; }
  const sheet=[];
  for(const it of links){
    const d = await buildLabelData(it.productionId);
    if(!d) continue;
    const n = (mode==='perPiece') ? Math.max(1, Math.round(+it.qte||1)) : 1;
    for(let i=0;i<n;i++) sheet.push(d);
  }
  if(!sheet.length){ toast('Batchs liés introuvables'); return; }
  printLabelSheet(sheet, 'Étiquettes commande #'+orderId);
  toast(`${sheet.length} étiquette(s) envoyée(s) à l'impression`);
}
// Ouvrir une fiche traçabilité à partir de l'ancre #trace=<lot> (QR scanné)
async function handleTraceAnchor(){
  const h = location.hash || '';
  // Lot de picking scanné (QR global) → ouvre l'écran de picking du lot.
  const mb = h.match(/#batch=(.+)$/);
  if(mb){
    const bid = +decodeURIComponent(mb[1]);
    history.replaceState(null,'',location.pathname);
    if(bid && typeof pickBatchOpen==='function'){
      try{ window._pickClientsCache = await db.clients.toArray(); }catch(e){ window._pickClientsCache=[]; }
      await pickBatchOpen(bid); return true;
    }
    return false;
  }
  // Commande scannée → picking par scan.
  const mo = h.match(/#order=(.+)$/);
  if(mo){
    const oid = +decodeURIComponent(mo[1]);
    history.replaceState(null,'',location.pathname);
    if(oid && typeof pickScanOpen==='function'){ await pickScanOpen(oid); return true; }
    return false;
  }
  const m = h.match(/#trace=(.+)$/);
  if(!m) return false;
  const lot = decodeURIComponent(m[1]);
  history.replaceState(null,'',location.pathname); // nettoie l'URL
  const prod = (await db.productions.toArray()).find(p=>p.lotProduction===lot);
  if(prod){ view='tracabilite'; document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.v==='tracabilite')); await renderTrace(); traceProd(prod.id); return true; }
  toast('Lot '+lot+' introuvable sur cet appareil'); return false;
}


const TABLES = ['suppliers','materials','materialLots','recipes','recipeItems','productions','prodConsumption','clients','orders','orderItems','events','products','charges','markets','marketMoves','losses','workSessions','pmsEquipments','temperatureLogs','pmsTasks','cleaningLogs','prodSessions','storageBoxes','equipmentSpecs','documents','components','packagingConsumption','fixJournal','batches',
  'kv','auditLog'];   // [v1372] stockage unifié + journal d'audit — dans les sauvegardes comme le reste
// [v1372] LISTE FIGÉE des tables telles qu'elles étaient AVANT la v1372. La somme de contrôle
// d'une sauvegarde est calculée sur une liste de tables : si cette liste change en silence,
// TOUTES les sauvegardes passées deviennent « invalides » aux yeux du vérificateur — non parce
// qu'elles sont corrompues, mais parce qu'on a changé de règle sans le dire. Règle gelée :
// UNE SOMME DE CONTRÔLE DONT LE PÉRIMÈTRE BOUGE SANS ÊTRE ÉCRIT DANS LE FICHIER N'EN EST PAS UNE.
// Les nouvelles sauvegardes embarquent donc leur propre périmètre (_checksumTables) ; les
// anciennes, qui n'en ont pas, sont vérifiées sur cette liste-ci, figée à jamais.
const TABLES_CHECKSUM_HERITAGE = ['suppliers','materials','materialLots','recipes','recipeItems','productions','prodConsumption','clients','orders','orderItems','events','products','charges','markets','marketMoves','losses','workSessions','pmsEquipments','temperatureLogs','pmsTasks','cleaningLogs','prodSessions','storageBoxes','equipmentSpecs','documents','components','packagingConsumption','fixJournal','batches'];
const BACKUP_VERSION = 2;
const MAX_BACKUPS = 20; // historique conservé en base (les plus anciens sont purgés)

// --- Compteur de modifications non sauvegardées (protection anti-perte) ---
// Incrémenté à chaque ajout/modif/suppression de données importantes ; remis à 0 après une vraie
// sauvegarde iCloud/export. Une alerte accueil insiste tant qu'il est > 0.
function unsavedCount(){ try{ return parseInt(localStorage.getItem('sm_unsaved')||'0',10)||0; }catch(e){ return 0; } }
function markUnsaved(){ try{ localStorage.setItem('sm_unsaved', String(unsavedCount()+1)); }catch(e){swallow(e,'markUnsaved')} }
function clearUnsaved(){ try{ localStorage.setItem('sm_unsaved','0'); }catch(e){swallow(e,'clearUnsaved')} }

// ---- Construction d'un instantané structuré ----
async function buildDump(){
  const dump={_app:'sensations-macarons',_version:BACKUP_VERSION,_date:new Date().toISOString()};
  for(const t of TABLES) dump[t]=await db.table(t).toArray();
  // FILET DE SÉCURITÉ sessions d'atelier : si la table IndexedDB est vide mais que le cache
  // localStorage contient des sessions (persistance Dexie pas encore faite), on sauvegarde le
  // cache. Évite qu'une sauvegarde ne contienne 0 session alors que l'atelier en a.
  try{
    const cacheSess = JSON.parse(localStorage.getItem(PROD_SESS_KEY)||'[]');
    if(Array.isArray(cacheSess) && cacheSess.length > (dump.prodSessions||[]).length){
      dump.prodSessions = cacheSess;
    }
  }catch(e){swallow(e,'buildDump')}
  dump._localStorage = collectLocalSettings(); // réglages hors IndexedDB (emballages, charges, préférences…)
  dump._checksumTables = TABLES.slice();        // [v1372] le périmètre de la somme voyage AVEC le fichier
  dump._checksum = backupChecksum(dump);        // checksum calculé sur les tables du périmètre uniquement
  return dump;
}
// Clés localStorage incluses dans les sauvegardes (réglages persistants, hors état purement transitoire).
const BACKUP_LS_KEYS = ['sm_settings','sm_autoPay','sm_privacyMode','sm_nav_adv','sm_lastExport','sm_lastICloud','sm_autoBackupDate',
  'sm_facture','sm_recurringCharges','sm_mrp_times','sm_availability','sm_planPrioOrder','sm_pmsEod',
  'sm_navFavoris','sm_navUsage','sm_optimBatch','sm_availExceptions'];
function collectLocalSettings(){
  const o={};
  BACKUP_LS_KEYS.forEach(k=>{ const v=localStorage.getItem(k); if(v!=null) o[k]=v; });
  return o;
}
// Restaure les réglages localStorage depuis un dump (remplacement). Sans effet si absent.
function applyLocalSettings(dump){
  if(!dump || typeof dump._localStorage!=='object' || !dump._localStorage) return;
  BACKUP_LS_KEYS.forEach(k=>{ if(dump._localStorage[k]!=null) localStorage.setItem(k, dump._localStorage[k]); });
}
// Somme de contrôle simple et déterministe (hash 32 bits, type DJB2) sur les données (hors méta).
function backupChecksum(dump){
  // [v1372] Le PÉRIMÈTRE de la somme est celui écrit DANS le fichier (_checksumTables).
  // À défaut (sauvegardes d'avant v1372), on vérifie sur la liste héritée figée — jamais sur
  // TABLES courant : sinon chaque table ajoutée « invaliderait » rétroactivement tout l'historique.
  const perimetre = Array.isArray(dump && dump._checksumTables) ? dump._checksumTables : TABLES_CHECKSUM_HERITAGE;
  let str='';
  for(const t of perimetre){ str += t+':'+JSON.stringify(dump[t]||[])+';'; }
  let h=5381;
  for(let i=0;i<str.length;i++){ h=((h<<5)+h+str.charCodeAt(i))|0; }
  return (h>>>0).toString(16); // non signé, hexadécimal
}
// Compte total d'enregistrements d'un dump.
function dumpRecordCount(dump){ return TABLES.reduce((s,t)=>s+(Array.isArray(dump[t])?dump[t].length:0),0); }

// ---- Vérification d'intégrité d'une sauvegarde ----
// Retourne {ok, raisons:[], checksumOk, structureOk, counts}
function verifyBackup(dump){
  const raisons=[];
  if(!dump || typeof dump!=='object'){ return {ok:false, raisons:['Fichier illisible.'], checksumOk:false, structureOk:false}; }
  const structureOk = dump._app==='sensations-macarons' || TABLES.some(t=>Array.isArray(dump[t]));
  if(!structureOk) raisons.push("Ce fichier n'a pas la structure d'une sauvegarde Sensations Macarons.");
  // chaque table présente doit être un tableau
  TABLES.forEach(t=>{ if(dump[t]!=null && !Array.isArray(dump[t])) raisons.push(`La table « ${t} » est corrompue (format inattendu).`); });
  // contrôle de cohérence référentielle légère
  if(Array.isArray(dump.orders) && Array.isArray(dump.clients)){
    const ids=new Set(dump.clients.map(c=>c.id));
    const orphelins=dump.orders.filter(o=>o.clientId && !ids.has(o.clientId)).length;
    if(orphelins>0) raisons.push(`${orphelins} commande(s) référencent un client absent.`);
  }
  // clés primaires en doublon DANS le fichier : feraient avorter bulkAdd (ConstraintError)
  // et donc tout l'import — on le dit AVANT d'essayer, table par table.
  TABLES.forEach(t=>{
    const rows=dump[t]; if(!Array.isArray(rows)||!rows.length) return;
    const vus=new Set(); const doublons=new Set();
    rows.forEach(r=>{ const id=r&&r.id; if(id==null) return; (vus.has(id)?doublons:vus).add(id); });
    if(doublons.size) raisons.push(`${doublons.size} identifiant(s) en doublon dans « ${t} » (ex : ${[...doublons].slice(0,3).join(', ')}) — l'import échouerait sur cette table.`);
  });
  // somme de contrôle (si présente)
  let checksumOk=true;
  if(dump._checksum){
    const recomputed=backupChecksum(dump);
    checksumOk = recomputed===dump._checksum;
    if(!checksumOk) raisons.push('La somme de contrôle ne correspond pas : la sauvegarde a peut-être été modifiée ou tronquée.');
  }
  // une sauvegarde sans aucune table de données est suspecte
  const total=dumpRecordCount(dump);
  return {ok: structureOk && checksumOk && !raisons.some(r=>r.includes('corrompue')), raisons, checksumOk, structureOk, total};
}

// ---- FUSION d'un dump (AJOUT sans écrasement) ----
// Ajoute les enregistrements d'un dump à la base existante, sans rien effacer.
// Les ID entrants sont ré-attribués automatiquement pour éviter toute collision,
// et les clés étrangères internes au dump sont remappées (clientId, marketId, recipeId, etc.).
// Retourne un récapitulatif {table:nbAjouté}.
async function mergeDump(dump){
  // [v1373] Import-fusion = hooks suspendus (audit + validation) : voir _importEnCours.
  _importEnCours = true;
  const added={};
  // ordre d'insertion : les "parents" d'abord pour pouvoir remapper les enfants
  const order=['suppliers','materials','clients','recipes','products','events',
               'materialLots','recipeItems','productions','prodConsumption',
               'orders','orderItems','charges','markets','marketMoves'];
  const idMap={}; order.forEach(t=>idMap[t]={}); // old id -> new id, par table
  // table parent d'une clé étrangère donnée
  const FK={
    materialLots:{materialId:'materials', supplierId:'suppliers'},
    recipeItems:{recipeId:'recipes', materialId:'materials'},
    productions:{recipeId:'recipes'},
    prodConsumption:{productionId:'productions', materialLotId:'materialLots'},
    orders:{clientId:'clients'},
    orderItems:{orderId:'orders', productionId:'productions'},
    marketMoves:{marketId:'markets', productionId:'productions'}
  };
  await db.transaction('rw',...order.map(t=>db.table(t)),async()=>{
    for(const t of order){
      const rows=dump[t]; if(!Array.isArray(rows)||!rows.length) continue;
      let n=0;
      for(const row of rows){
        const rec=Object.assign({},row);
        const oldId=rec.id; delete rec.id;             // laisse IndexedDB attribuer un nouvel id
        // remap des clés étrangères internes au dump
        const fk=FK[t]||{};
        for(const field in fk){
          const parentTable=fk[field];
          const oldRef=rec[field];
          if(oldRef!=null && idMap[parentTable] && idMap[parentTable][oldRef]!=null){
            rec[field]=idMap[parentTable][oldRef]; // référence remappée vers le nouvel id
          }
          // si la référence ne correspond à rien d'importé, on la laisse telle quelle
          // (ex : marketMoves.productionId sans lot → l'affichage retombe sur le nom du parfum)
        }
        const newId=await db.table(t).add(rec);
        if(oldId!=null) idMap[t][oldId]=newId;
        n++;
      }
      added[t]=n;
    }
  }).finally(()=>{ _importEnCours = false; });
  // UNE entrée récapitulative au journal — la fusion a eu lieu, table par table.
  try{ await db.auditLog.add({ ts:Date.now(), tbl:'*', op:'fusion', cle:null,
    resume:_auditResume(added),
    ecran:(typeof view!=='undefined'&&view)?String(view):'', v:APP_VERSION }); }catch(e){ swallow(e,'audit fusion'); }
  return added;
}

// ---- Application d'un dump à la base (remplacement atomique) ----
async function applyDump(dump){
  // [v1373] Restauration = hooks suspendus (audit + validation) : voir _importEnCours.
  _importEnCours = true;
  try{
  // PROTECTION sessions d'atelier : si le dump importé ne contient PAS de sessions, on préserve
  // celles déjà présentes (cache + base) au lieu de les effacer. Une restauration de sauvegarde
  // ancienne/partielle ne doit jamais détruire des sessions absentes du fichier.
  let sessAvant = [];
  try{ sessAvant = JSON.parse(localStorage.getItem(PROD_SESS_KEY)||'[]'); if(!Array.isArray(sessAvant)) sessAvant=[]; }catch(e){ sessAvant=[]; }
  try{ const enBase = await db.prodSessions.toArray(); if(enBase.length>sessAvant.length) sessAvant = enBase; }catch(e){swallow(e,'applyDump')}
  const dumpAUneSession = Array.isArray(dump.prodSessions) && dump.prodSessions.length>0;

  await db.transaction('rw',...TABLES.map(t=>db.table(t)),async()=>{
    for(const t of TABLES){
      // on ne vide pas prodSessions si le dump n'en contient pas (préservation)
      if(t==='prodSessions' && !dumpAUneSession) continue;
      // [v1372] MÊME RÈGLE pour kv et auditLog : une sauvegarde d'AVANT v1372 ne connaît pas
      // ces tables — la restaurer ne doit pas EFFACER le stockage unifié ni le journal d'audit.
      // Un journal d'audit qu'une restauration peut vider n'est pas un journal d'audit.
      if((t==='kv' || t==='auditLog') && !Array.isArray(dump[t])) continue;
      await db.table(t).clear();
      if(Array.isArray(dump[t]) && dump[t].length) await db.table(t).bulkAdd(dump[t]);
    }
  });
  applyLocalSettings(dump); // réapplique les réglages (emballages, charges, préférence de menu…) si présents
  // [v1372] La table kv vient (peut-être) d'être remplacée par celle du fichier ; localStorage
  // porte encore les valeurs d'AVANT la restauration → on réapplique kv → localStorage pour que
  // les clés métier (modèles de pyramides, compteur de factures, journal copilote…) reflètent
  // bien la sauvegarde restaurée, comme les tables.
  try{ await kvRestaureLSDepuisBase(); }catch(e){ console.error('restore kv→LS', e); }
  // Resynchronise le cache localStorage des sessions. Si le dump n'avait pas de sessions, on
  // réinjecte celles qu'on a préservées (et on les remet en base par sécurité).
  try{
    if(!dumpAUneSession && sessAvant.length){
      localStorage.setItem(PROD_SESS_KEY, JSON.stringify(sessAvant));
      try{ await db.prodSessions.bulkPut(sessAvant); }catch(e){swallow(e,'applyDump')}
    } else {
      const ps=await db.prodSessions.toArray();
      localStorage.setItem(PROD_SESS_KEY, JSON.stringify(ps));
    }
  }catch(e){ console.error('restore prodSess cache', e); }
  // [AUDIT-2026-07 · A22/A23] Après une restauration, les caches dérivés (matières + ratio emballage
  // commandes + ratio emballage marchés) sont périmés → on les reconstruit explicitement, sinon les
  // coûts emballage et estimations resteraient faux jusqu'au prochain refresh manuel.
  try{ await syncAfterMaterialChange(); }catch(e){ console.error('restore sync mats', e); }
  try{ await refreshEmbEstRatioMarches(); }catch(e){ console.error('restore sync marches', e); }
  try{ if(typeof refreshMoCtx==='function') await refreshMoCtx(); }catch(e){ console.error('restore sync moCtx', e); }
  }finally{ _importEnCours = false; }
  // [v1374] Après une restauration, TOUT est potentiellement périmé : on le signale une fois.
  try{ _figSignale(TABLES.slice()); }catch(e){ swallow(e,'fig restauration'); }
  // UNE entrée récapitulative au journal — la restauration a eu lieu, avec son ampleur.
  try{ await db.auditLog.add({ ts:Date.now(), tbl:'*', op:'restauration', cle:null,
    resume:_auditResume({ enregistrements:dumpRecordCount(dump), date:dump._date||null, version:dump._version||null }),
    ecran:(typeof view!=='undefined'&&view)?String(view):'', v:APP_VERSION }); }catch(e){ swallow(e,'audit restauration'); }
}

// ---- EXPORT MANUEL (fichier .json téléchargé) ----
async function exportData(){
  const dump=await buildDump();
  const blob=new Blob([JSON.stringify(dump,null,2)],{type:'application/json'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  const nomFichier='sensations-macarons-sauvegarde-'+today()+'.json';
  a.download=nomFichier; a.click();
  // [v1385 · CHANTIER C] AVANT : on écrivait ici sm_lastExport = today(), c'est-à-dire qu'on
  // AFFIRMAIT une sortie que le commentaire d'à côté reconnaissait ne pas pouvoir vérifier.
  // Un partage annulé éteignait donc le rappel pendant sept jours. Désormais : on enregistre
  // une TENTATIVE (fait observable), et seule une confirmation de Ben vaut sortie.
  sortieMarqueTentee('fichier');
  if(!sortieDemandeConfirmation('fichier', nomFichier)){
    toast('Sortie non confirmée — le rappel reste actif');
    return;
  }
  toast('Sortie confirmée ✓ — garde ce fichier hors de l\'appareil');
}

/* ============================================================
   SAUVEGARDE VERS iCLOUD DRIVE (via la feuille de partage iOS)
   ------------------------------------------------------------
   Une PWA ne peut pas écrire seule dans iCloud Drive (bac à sable du
   navigateur). La seule voie fiable sur iPhone est l'API Web Share avec
   un FICHIER : elle ouvre la feuille de partage native, où l'utilisateur
   choisit « Enregistrer dans Fichiers → iCloud Drive ». Le dossier est
   mémorisé par iOS, donc les fois suivantes ne demandent qu'une validation.
   Repli : si le partage de fichier n'est pas disponible (ex. ordinateur),
   on retombe sur le téléchargement classique (.json).
   ============================================================ */
async function shareBackupToICloud(opts){
  opts = opts || {};
  try{
    const dump = await buildDump();
    const json = JSON.stringify(dump, null, 2);
    const nomFichier = 'sensations-macarons-sauvegarde-'+today()+'.json';
    // 1) Voie idéale iOS : partage d'un vrai fichier
    if(navigator.canShare){
      const file = new File([json], nomFichier, {type:'application/json'});
      if(navigator.canShare({files:[file]})){
        await navigator.share({
          files:[file],
          title:'Sauvegarde Sensations Macarons',
          text:'Sauvegarde du '+fmtDate(today())+' — choisis « Enregistrer dans Fichiers » puis iCloud Drive.'
        });
        // [v1385 · CHANTIER C] navigator.share() qui rend la main ne prouve PAS que le fichier
        // a été enregistré : iOS résout la promesse dès que la feuille de partage est traitée.
        // On note donc une TENTATIVE, puis on demande à Ben ce qu'il a vu.
        sortieMarqueTentee('icloud');
        try{ await snapshotBackup('icloud'); }catch(e){swallow(e,'shareBackupToICloud')}
        const confirmee = sortieDemandeConfirmation('icloud', nomFichier);
        toast(confirmee ? 'Sortie iCloud confirmée ✓' : 'Sortie non confirmée — le rappel reste actif');
        if(typeof renderBackups==='function' && view==='backups') renderBackups();
        return confirmee;
      }
    }
    // 2) Repli : téléchargement classique (ordinateur, ou navigateur sans partage de fichier)
    const blob=new Blob([json],{type:'application/json'});
    const a=document.createElement('a'); a.href=URL.createObjectURL(blob);
    a.download=nomFichier; a.click();
    // [v1385 · CHANTIER C] Même règle sur le repli : produire un fichier n'est pas le mettre à l'abri.
    sortieMarqueTentee('fichier');
    try{ await snapshotBackup('icloud'); }catch(e){swallow(e,'shareBackupToICloud')}
    const confirmeeR = sortieDemandeConfirmation('fichier', nomFichier);
    toast(confirmeeR ? 'Sortie confirmée ✓' : 'Partage direct indisponible : fichier téléchargé, sortie NON confirmée.');
    return confirmeeR;
  }catch(e){
    // l'utilisateur a annulé la feuille de partage, ou erreur : pas grave, on reste silencieux
    if(e && e.name==='AbortError'){ return false; }
    console.error('shareBackupToICloud', e);
    toast('Sauvegarde iCloud annulée ou impossible.');
    return false;
  }
}
// ---- IMPORT MANUEL (depuis un fichier .json) ----
// INSPECTION SEULE : lit un fichier .json et affiche son contenu (commandes, dont migrées) SANS
// rien importer ni modifier. Permet de comparer plusieurs fichiers iCloud en sécurité totale.
async function inspectData(e){
  const f=e.target.files[0]; if(!f)return;
  let obj;
  try{ obj = JSON.parse(await f.text()); }
  catch(err){ toast('Fichier illisible (JSON invalide)'); e.target.value=''; return; }
  const orders = Array.isArray(obj.orders)?obj.orders : [];
  const nbTot = orders.length;
  const nbHisto = orders.filter(o=>o.histo).length;
  const nbVisibles = nbTot - nbHisto;
  const nbClients = Array.isArray(obj.clients)?obj.clients.length:0;
  const nbMarches = Array.isArray(obj.markets)?obj.markets.length:0;
  // Sessions d'atelier (chronos) contenues dans la sauvegarde + total de tâches chronométrées.
  const sessions = Array.isArray(obj.prodSessions)?obj.prodSessions:[];
  const nbSessions = sessions.length;
  const nbTaches = sessions.reduce((a,s)=>a+((s.tasks||[]).length),0);
  const dateInfo = obj._date ? new Date(obj._date).toLocaleString('fr-FR') : '?';
  // dernières commandes non-migrées par date, pour repère visuel
  const recentes = orders.filter(o=>!o.histo).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,5)
    .map(o=>`${esc((o.date||'?'))} · ${euro(+o.montant||0)}`).join('\n');
  alert(`📄 Fichier : ${f.name}\nDate de la sauvegarde : ${dateInfo}\n\n`+
    `• ${nbTot} commande(s) AU TOTAL\n   dont ${nbVisibles} visibles + ${nbHisto} migrées\n`+
    `• ${nbClients} client(s)\n• ${nbMarches} marché(s)\n`+
    `• ${nbSessions} session(s) d'atelier (${nbTaches} tâche(s) chronométrée(s))\n\n`+
    `5 dernières commandes visibles :\n${recentes||'(aucune)'}\n\n`+
    `(Inspection seule — RIEN n'a été importé ni modifié.)`);
  e.target.value='';
}
// ---- Rapport d'erreur d'import LISIBLE : nom + détail réels, publiés en rubrique technique.
// Fini le « Erreur pendant l'import » aveugle : le moteur dit CE qui a cassé et OÙ.
function _importErrRapport(contexte, fichier, err){
  const nom=(err&&err.name)||'Erreur';
  const msg=(err&&err.message)?String(err.message):String(err||'inconnue');
  try{ if(typeof diagPublish==='function') diagPublish('import', 'Import/fusion de sauvegarde',
    { quand:new Date().toISOString(), contexte, fichier, erreur:nom+' — '+msg, stack:(err&&err.stack)||'' }); }catch(e){swallow(e,'_importErrRapport')}
  return nom+' — '+msg;
}
async function importData(e){
  const f=e.target.files[0]; if(!f)return;
  let obj;
  try{ obj = JSON.parse(await f.text()); }
  catch(err){ toast('Fichier illisible (JSON invalide)'); e.target.value=''; return; }
  const v=verifyBackup(obj);
  if(!v.structureOk){ toast('Ce fichier n\'est pas une sauvegarde valide'); e.target.value=''; return; }
  const nbOrders = Array.isArray(obj.orders)?obj.orders.length:0;
  const nbClients = Array.isArray(obj.clients)?obj.clients.length:0;
  const dateInfo = obj._date ? `\nSauvegarde du ${new Date(obj._date).toLocaleString('fr-FR')}` : '';
  const warn = v.raisons.length ? `\n\n⚠ Avertissement(s) :\n- ${v.raisons.join('\n- ')}` : '\n\n✓ Intégrité vérifiée.';
  // [v1384 · CHANTIER B] CONTRÔLE DU CONTENU, avant toute écriture. verifyBackup() ci-dessus ne
  // juge que la FORME (tableaux, doublons d'id, somme de contrôle) : un montant en chaîne ou une
  // date malformée passaient intacts, la validation v1373 étant éteinte par _importEnCours.
  // On répare ici ce qui est non ambigu, on signale le reste, et on le DIT avant de demander.
  const rap = valideDumpAvantImport(obj);
  const rapTxt = (rap.nbReparations || rap.nbAnomalies) ? `\n\n${_impRapportTexte(rap)}` : '';
  if(!confirm(`Importer cette sauvegarde ?${dateInfo}\n\n• ${nbClients} client(s)\n• ${nbOrders} commande(s)${warn}${rapTxt}\n\nToutes les données actuelles seront remplacées (une sauvegarde de sécurité sera prise avant).`)){
    e.target.value=''; return;
  }
  await _impJournaliseRapport(rap, 'remplacement', f.name);
  try{
    // Filet de sécurité AVANT écrasement — son échec a désormais son PROPRE message
    // (cause fréquente : stockage saturé), il ne se déguise plus en « erreur pendant l'import ».
    try{ await snapshotBackup('avant-import'); }
    catch(se){
      const m=_importErrRapport('instantané avant-import', f.name, se);
      if(!confirm(`⚠️ Impossible de prendre la sauvegarde de sécurité avant import :\n${m}\n\n(Cause fréquente : stockage iPhone saturé — libère de l'espace ou purge d'anciens instantanés dans Sauvegarde & sécurité.)\n\nContinuer l'import SANS filet de sécurité ?`)){ e.target.value=''; return; }
    }
    await applyDump(obj);
    render(); toast('Données importées ✓');
  }catch(err){
    console.error('import',err);
    const m=_importErrRapport('applyDump (écriture des tables)', f.name, err);
    alert(`Erreur pendant l'import :\n${m}\n\nRien n'a été perdu : la transaction est annulée en bloc (tout-ou-rien).\nDétail publié dans la rubrique technique (🔧 Diagnostic).`);
  }
  e.target.value='';
}

// ---- IMPORT FUSION (ajoute sans écraser) ----
async function importDataMerge(e){
  const f=e.target.files[0]; if(!f)return;
  let obj;
  try{ obj = JSON.parse(await f.text()); }
  catch(err){ toast('Fichier illisible (JSON invalide)'); e.target.value=''; return; }
  const v=verifyBackup(obj);
  if(!v.structureOk){ toast('Ce fichier n\'est pas un fichier Sensations Macarons valide'); e.target.value=''; return; }
  // récapitulatif de ce qui sera ajouté
  const parts=[];
  TABLES.forEach(t=>{ const n=Array.isArray(obj[t])?obj[t].length:0; if(n>0){
    const labels={clients:'client(s)',orders:'commande(s)',markets:'marché(s)',marketMoves:'mouvement(s) marché',charges:'charge(s)',productions:'production(s)',recipes:'recette(s)',materials:'matière(s)',materialLots:'lot(s) matière',products:'produit(s) catalogue',events:'événement(s)'};
    parts.push(`• ${n} ${labels[t]||t}`); } });
  const dateInfo = obj._date ? `\nFichier du ${new Date(obj._date).toLocaleString('fr-FR')}` : '';
  // [v1384 · CHANTIER B] Même contrôle de contenu qu'en remplacement : la fusion suspend
  // elle aussi la validation (_importEnCours), donc elle a besoin du même filet.
  const rapM = valideDumpAvantImport(obj);
  const rapMTxt = (rapM.nbReparations || rapM.nbAnomalies) ? `\n\n${_impRapportTexte(rapM)}` : '';
  if(!confirm(`Fusionner ce fichier avec vos données ?${dateInfo}\n\nCe contenu sera AJOUTÉ (rien ne sera effacé) :\n${parts.join('\n')||'• (aucune donnée détectée)'}${rapMTxt}\n\nUne sauvegarde de sécurité sera prise avant.`)){
    e.target.value=''; return;
  }
  await _impJournaliseRapport(rapM, 'fusion', f.name);
  try{
    try{ await snapshotBackup('avant-fusion'); }
    catch(se){
      const m=_importErrRapport('instantané avant-fusion', f.name, se);
      if(!confirm(`⚠️ Impossible de prendre la sauvegarde de sécurité avant fusion :\n${m}\n\nContinuer la fusion SANS filet de sécurité ?`)){ e.target.value=''; return; }
    }
    const added=await mergeDump(obj);
    const tot=Object.values(added).reduce((s,n)=>s+n,0);
    render(); toast(`Fusion réussie : ${tot} enregistrement(s) ajouté(s) ✓`);
  }catch(err){
    console.error('merge',err);
    const m=_importErrRapport('mergeDump (fusion)', f.name, err);
    alert(`Erreur pendant la fusion :\n${m}\n\nRien n'a été perdu : la transaction est annulée en bloc (tout-ou-rien).`);
  }
  e.target.value='';
}
// Suppression en masse SÛRE, indépendante de la version de Dexie.
// Certaines builds de Dexie n'exposent pas Table.bulkDelete() → on dégrade proprement.
async function bulkDeleteSafe(table, ids){
  const list = (ids||[]).filter(v=>v!=null);
  if(!list.length) return 0;
  try{
    if(table && typeof table.bulkDelete==='function'){ await table.bulkDelete(list); return list.length; }
    if(table && table.where){ await table.where(':id').anyOf(list).delete(); return list.length; }
  }catch(e){ /* on tente le repli unitaire ci-dessous */ }
  let n=0;
  if(table && typeof table.delete==='function'){
    for(const id of list){ try{ await table.delete(id); n++; }catch(e){swallow(e,'bulkDeleteSafe')} }
  }
  return n;
}
// Enregistre un instantané JSON complet + checksum dans la table backups, puis purge les plus anciens.
async function snapshotBackup(type){
  const dump=await buildDump();
  const payload=JSON.stringify(dump);
  const rec={ date:new Date().toISOString(), type:type||'manuel',
    checksum:dump._checksum, count:dumpRecordCount(dump), size:payload.length, payload };
  const id=await db.backups.add(rec);
  // purge : ne conserver que les MAX_BACKUPS plus récents
  try{
    const all=await db.backups.orderBy('date').reverse().toArray();
    if(all.length>MAX_BACKUPS){
      const surplus=all.slice(MAX_BACKUPS).map(b=>b.id);
      await bulkDeleteSafe(db.backups, surplus);
    }
  }catch(ePurge){ console.warn('snapshotBackup purge (non bloquant)', ePurge); }
  return id;   // l'instantané est déjà écrit : la sauvegarde a réussi même si la purge échoue
}
// Sauvegarde automatique quotidienne (au démarrage, une fois par jour).
async function autoDailyBackup(){
  try{
    if(localStorage.getItem('sm_autoBackupDate')===today()) return;
    // ne pas sauvegarder une base vide (premier lancement)
    const n=await db.clients.count()+await db.orders.count()+await db.materials.count();
    if(n===0){ localStorage.setItem('sm_autoBackupDate', today()); return; }
    await snapshotBackup('auto-quotidienne');
    localStorage.setItem('sm_autoBackupDate', today());
  }catch(e){ console.error('autoBackup',e); }
}
// ============================================================
//  VÉRIFICATEUR D'INTÉGRITÉ DES DONNÉES (lecture seule)
//  Repère les liens cassés / orphelins entre les tables.
//  Ne modifie RIEN : il signale, et propose un nettoyage au choix.
// ============================================================
async function runIntegrityCheck(){
  const [materials, materialLots, suppliers, recipes, recipeItems,
         productions, prodConsumption, clients, orders, orderItems, markets, marketMoves] =
    await Promise.all([
      db.materials.toArray(), db.materialLots.toArray(), db.suppliers.toArray(),
      db.recipes.toArray(), db.recipeItems.toArray(), db.productions.toArray(),
      db.prodConsumption.toArray(), db.clients.toArray(), db.orders.toArray(),
      db.orderItems.toArray(), db.markets.toArray(), db.marketMoves.toArray()
    ]);
  const idset = arr => new Set(arr.map(x=>x.id));
  const S = {
    materials:idset(materials), suppliers:idset(suppliers), recipes:idset(recipes),
    productions:idset(productions), clients:idset(clients), orders:idset(orders),
    materialLots:idset(materialLots), markets:idset(markets)
  };
  const issues = [];
  const add=(table,label,items,fix)=>{ if(items.length) issues.push({table,label,count:items.length,ids:items.map(x=>x.id),fix}); };

  // Commandes → client inexistant
  add('orders','Commande(s) liée(s) à un client supprimé',
    orders.filter(o=>o.clientId && !S.clients.has(o.clientId)), 'detachClient');
  // OrderItems → commande ou production inexistante
  add('orderItems','Ligne(s) de commande liée(s) à une commande supprimée',
    orderItems.filter(it=>!S.orders.has(it.orderId)), 'delete');
  add('orderItems','Ligne(s) de commande liée(s) à une production supprimée',
    orderItems.filter(it=>it.productionId && !S.productions.has(it.productionId)), 'delete');
  // Productions → recette inexistante (hors productions « libres »)
  add('productions','Production(s) liée(s) à une recette supprimée',
    productions.filter(p=>!p.libre && p.recipeId && !S.recipes.has(p.recipeId)), 'none');
  // RecipeItems → recette ou matière inexistante.
  // ATTENTION : un recipeItem peut appartenir soit à une RECETTE (recipeId), soit à un
  // COMPOSANT (componentId, ex. la Chantache). Un ingrédient de composant n'a pas de recipeId
  // valide : il ne faut donc PAS le considérer orphelin tant que son composant existe.
  add('recipeItems','Ingrédient(s) de recette liés à une recette supprimée',
    recipeItems.filter(ri=> ri.componentId==null && !S.recipes.has(ri.recipeId)), 'delete');
  add('recipeItems','Ingrédient(s) de recette liés à une matière supprimée',
    recipeItems.filter(ri=>ri.materialId && !S.materials.has(ri.materialId)), 'delete');
  // Lots → matière ou fournisseur inexistant
  add('materialLots','Lot(s) de matière liés à une matière supprimée',
    materialLots.filter(l=>!S.materials.has(l.materialId)), 'delete');
  add('materialLots','Lot(s) liés à un fournisseur supprimé',
    materialLots.filter(l=>l.supplierId && !S.suppliers.has(l.supplierId)), 'detachSupplier');
  // Consommations → production ou lot inexistant
  add('prodConsumption','Consommation(s) liée(s) à une production supprimée',
    prodConsumption.filter(c=>!S.productions.has(c.productionId)), 'delete');
  add('prodConsumption','Consommation(s) liée(s) à un lot supprimé',
    prodConsumption.filter(c=>c.materialLotId && !S.materialLots.has(c.materialLotId)), 'delete');
  // Mouvements marché → marché ou production inexistant
  add('marketMoves','Mouvement(s) de marché liés à un marché supprimé',
    marketMoves.filter(m=>!S.markets.has(m.marketId)), 'delete');
  add('marketMoves','Mouvement(s) de marché liés à une production supprimée',
    marketMoves.filter(m=>m.productionId && !S.productions.has(m.productionId)), 'delete');

  return issues;
}
// Applique le nettoyage d'une anomalie (avec sauvegarde de sécurité préalable).
async function fixIntegrityIssue(table, ids, fix){
  if(fix==='none'){ toast('À corriger manuellement (recrée la recette ou supprime la production)'); return; }
  // Normalise les ids : Dexie attend les clés primaires exactes (nombres pour les tables '++id').
  const cleanIds = (ids||[]).map(x=> (typeof x==='string' && /^\d+$/.test(x)) ? +x : x).filter(x=>x!=null);
  if(!cleanIds.length){ toast('Aucun élément à nettoyer'); return; }
  let etape='sauvegarde';
  try{
    try{ await snapshotBackup('avant-nettoyage-intégrité'); }
    catch(eBk){ console.error('snapshot avant nettoyage',eBk); /* on continue : la sauvegarde ne doit pas bloquer le nettoyage */ }
    etape='suppression';
    if(fix==='delete'){
      // db.table(name) est la méthode officielle Dexie (plus fiable que l'accès par bracket db[name],
      // qui peut tomber sur une propriété interne et ne pas exposer bulkDelete).
      let tbl=null;
      try{ tbl = (typeof db.table==='function') ? db.table(table) : db[table]; }catch(eT){ tbl = db[table]; }
      if(!tbl || typeof tbl.bulkDelete!=='function'){
        // repli : suppression une par une via delete()
        if(tbl && typeof tbl.delete==='function'){
          for(const id of cleanIds){ await tbl.delete(id); }
        } else { toast('Table inaccessible : '+table); return; }
      } else {
        await tbl.bulkDelete(cleanIds);
      }
    } else if(fix==='detachClient'){
      await db.transaction('rw', db.orders, async()=>{ for(const id of cleanIds) await db.orders.update(id,{clientId:null}); });
    } else if(fix==='detachSupplier'){
      await db.transaction('rw', db.materialLots, async()=>{ for(const id of cleanIds) await db.materialLots.update(id,{supplierId:null}); });
    }
    toast(`${cleanIds.length} anomalie(s) corrigée(s) ✓`);
    renderIntegrity();
  }catch(e){
    console.error('fixIntegrity ['+etape+']',e);
    toast('Erreur pendant le nettoyage ('+etape+') : '+((e&&e.message)?e.message:e));
  }
}
