// ----- UI : formulaire de correction de consommation (rubrique technique) -----

async function consoFixForm(){
  // lots de production rattachés à une recette (sinon pas de BOM → rien à corriger)
  const prods = await db.productions.orderBy('date').reverse().toArray().catch(()=>[]);
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recById = {}; recipes.forEach(r=>recById[+r.id]=r);
  const candidats = sortProdsRecent(prods.filter(p=>p.recipeId && recById[+p.recipeId]));
  if(!candidats.length){ toast('Aucun lot rattaché à une recette'); return; }

  const opts = candidats.slice(0,200).map(p=>{
    const r = recById[+p.recipeId];
    const lot = p.lotProduction || ('#'+p.id);
    const d = p.date ? fmtDate(p.date) : '';
    return `<option value="${p.id}">${esc(r.produitNom)} · lot ${esc(lot)}${d?' · '+esc(d):''}</option>`;
  }).join('');

  openModal(`<h3>🔧 Rattacher une consommation manquante</h3>
    <p class="note" style="margin-bottom:10px">Choisis le lot concerné, puis la matière à rattacher. L'app calcule la quantité depuis la recette corrigée.</p>
    <div class="field"><label>Lot de production</label>
      <select id="cf_prod" onchange="consoFixLoadMats()"><option value="">— choisir —</option>${opts}</select></div>
    <div class="field" id="cf_matWrap" style="opacity:.5"><label>Matière à rattacher</label>
      <select id="cf_mat" onchange="consoFixPreview()" disabled><option value="">— choisir d'abord un lot —</option></select></div>
    <div id="cf_preview"></div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
    </div>`);
}

// Charge les matières du BOM du lot choisi.
async function consoFixLoadMats(){
  const prodId = +val('cf_prod')||0;
  const sel = document.getElementById('cf_mat');
  const wrap = document.getElementById('cf_matWrap');
  const prev = document.getElementById('cf_preview');
  if(prev) prev.innerHTML='';
  if(!prodId){ if(sel){sel.innerHTML='';sel.disabled=true;} if(wrap)wrap.style.opacity='.5'; return; }
  const p = await db.productions.get(prodId);
  const items = await db.recipeItems.where('recipeId').equals(p.recipeId).toArray().catch(()=>[]);
  const mats = await db.materials.toArray().catch(()=>[]);
  const matById = {}; mats.forEach(m=>matById[+m.id]=m);
  const opts = items.map(it=>{
    const m = matById[+it.materialId];
    return `<option value="${it.materialId}">${esc(m?m.nom:('#'+it.materialId))}</option>`;
  }).join('');
  if(sel){ sel.innerHTML = `<option value="">— choisir —</option>${opts}`; sel.disabled=false; }
  if(wrap) wrap.style.opacity='1';
}

// Aperçu : besoin calculé + déjà consommé + lots FIFO disponibles + choix du lot.
async function consoFixPreview(){
  const prodId = +val('cf_prod')||0;
  const materialId = +val('cf_mat')||0;
  const prev = document.getElementById('cf_preview');
  if(!prev) return;
  if(!prodId || !materialId){ prev.innerHTML=''; return; }

  const b = await consoFixBesoin(prodId, materialId);
  if(!b.besoin){ prev.innerHTML=`<p class="note" style="color:#b3261e;margin-top:8px">${esc(b.raison||'Rien à rattacher')}.</p>`; return; }
  const deja = await consoFixDejaConsomme(prodId, materialId);
  const reste = round3(Math.max(0, b.besoin - deja));
  const mat = await db.materials.get(materialId).catch(()=>null);
  const u = mat && mat.unite ? mat.unite : 'g';

  // lots dispo (FIFO)
  const lots = (await db.materialLots.where('materialId').equals(materialId).and(l=>+l.qteRestante>0).toArray().catch(()=>[])).sort(lotFifoCompare);
  const dispoTotal = round3(lots.reduce((s,l)=>s+(+l.qteRestante||0),0));
  const lotOpts = lots.map(l=>`<option value="${l.id}">${esc(l.lotFournisseur||('lot #'+l.id))} · ${qty(l.qteRestante)} ${esc(u)}${l.dlc?' · DLC '+fmtDate(l.dlc):''}</option>`).join('');

  prev.innerHTML = `
    <div class="panel" style="margin-top:10px">
      <div class="sum-box"><span>Besoin théorique (BOM × ${b.qteRef} produits)</span><b>${qty(b.besoin)} ${esc(u)}</b></div>
      ${deja>0?`<div class="sum-box"><span>Déjà consommé par ce lot</span><b>${qty(deja)} ${esc(u)}</b></div>`:''}
      <div class="sum-box"><span><b>À rattacher</b></span><b style="color:var(--bordeaux,#52252F)">${qty(reste)} ${esc(u)}</b></div>
      <div class="sum-box"><span>Stock disponible</span><b style="color:${dispoTotal>=reste?'#3f7d52':'#b3261e'}">${qty(dispoTotal)} ${esc(u)}</b></div>
    </div>
    ${reste<=0?`<p class="note" style="color:#3f7d52;margin-top:8px">✓ Ce lot a déjà toute sa consommation de cette matière. Rien à rattacher.</p>`:`
    <div class="field" style="margin-top:8px"><label>Quantité à rattacher (${esc(u)})</label>
      <input type="number" id="cf_qte" min="0" step="0.1" value="${reste}"></div>
    <div class="field"><label>Prise sur le stock</label>
      <select id="cf_lot"><option value="">FIFO (le plus ancien d'abord) — recommandé</option>${lotOpts}</select></div>
    ${dispoTotal<reste?`<p class="note" style="color:#b3261e">⚠ Stock insuffisant (${qty(dispoTotal)} ${esc(u)}). On rattachera au maximum possible ; le reste sera signalé.</p>`:''}
    <button class="btn" style="margin-top:8px;width:100%" onclick="consoFixGo(${prodId},${materialId})">✓ Rattacher ${qty(reste)} ${esc(u)}</button>`}
  `;
}

async function consoFixGo(prodId, materialId){
  const qte = round3(+val('cf_qte')||0);
  const lotImpose = +val('cf_lot')||0;
  if(qte<=0){ toast('Quantité nulle'); return; }
  const p = await db.productions.get(prodId);
  const nomLot = p ? (p.lotProduction||('#'+p.id)) : '';
  const res = await consoFixApply(prodId, materialId, qte, lotImpose||null);
  closeModal();
  if(res.manque>0){
    toast(`${qty(res.consomme)} rattaché(s) · ${qty(res.manque)} manquant(s) (stock épuisé)`);
  } else {
    toast(`✓ Consommation rattachée au lot ${nomLot} (${qty(res.consomme)})`);
  }
  if(view==='sauvegardes' && typeof renderBackups==='function') renderBackups();
}

// =============================================================================
//  PRÉLÈVEMENTS D'UN BATCH — corriger la quantité / changer de lot / remplacer
//  la matière. Réutilise consoFixApply (prélèvement FIFO + lot imposé) et le
//  vocabulaire d'écart d'inventaire (inventaireConfirm / adjust_stock).
//  Contrat métier (validé Benjamin) : lors d'un REMPLACEMENT, l'app DEMANDE
//  toujours si l'ancienne matière SORT du stock (régul d'inventaire négative)
//  ou REVIENT sur son lot d'origine.
// =============================================================================
/* PRELEV:PURE:BEGIN */
// Consommations réelles d'un batch, regroupées par matière (depuis prodConsumption).
async function prelevListe(prodId){
  const conso = await db.prodConsumption.where('productionId').equals(prodId).toArray().catch(()=>[]);
  const parMat = {};
  for(const c of conso){
    if(c.annuleeInventaire) continue;              // ligne déjà neutralisée : ignorée
    let matId = c.snapMaterialId;
    if(matId==null && c.materialLotId!=null){
      const lot = await db.materialLots.get(c.materialLotId).catch(()=>null);
      matId = lot ? lot.materialId : null;
    }
    if(matId==null) continue;
    (parMat[matId] ||= {materialId:+matId, qte:0, lots:{}});
    parMat[matId].qte = round3(parMat[matId].qte + (+c.qteConsommee||0));
    if(c.materialLotId!=null){
      (parMat[matId].lots[c.materialLotId] ||= 0);
      parMat[matId].lots[c.materialLotId] = round3(parMat[matId].lots[c.materialLotId] + (+c.qteConsommee||0));
    }
  }
  return Object.values(parMat);
}

// Neutralise (sans supprimer) les lignes de conso d'une matière pour ce batch, et
// selon `rendre` : soit REND la quantité sur les lots d'origine (rendre=true),
// soit la laisse sortie = régularisation d'inventaire négative (rendre=false).
// Retourne {annulees, renduTotal}.
async function prelevAnnulerMatiere(prodId, materialId, rendre){
  let annulees = 0, renduTotal = 0;
  const conso = await db.prodConsumption.where('productionId').equals(prodId).toArray().catch(()=>[]);
  const nowIso = new Date().toISOString();
  for(const c of conso){
    if(c.annuleeInventaire) continue;
    let matId = c.snapMaterialId;
    if(matId==null && c.materialLotId!=null){
      const lot = await db.materialLots.get(c.materialLotId).catch(()=>null);
      matId = lot ? lot.materialId : null;
    }
    if(+matId!==+materialId) continue;
    const pris = round3(+c.qteConsommee||0);
    if(rendre && c.materialLotId!=null && pris>0){
      const lot = await db.materialLots.get(c.materialLotId).catch(()=>null);
      if(lot){ await db.materialLots.update(lot.id, {qteRestante: round3((+lot.qteRestante||0)+pris)}); renduTotal = round3(renduTotal+pris); }
    }
    // marqueur : ligne neutralisée (jamais effacée). motif tracé.
    await db.prodConsumption.update(c.id, {annuleeInventaire:true, annuleeTs:nowIso,
      annuleeMotif: rendre ? 'retour-lot-origine' : 'sortie-regul-inventaire'});
    annulees++;
  }
  return {annulees, renduTotal};
}

// --- RÉAFFECTATION RÉTROACTIVE (correction HACCP « vérité terrain ») -----------
// Rebranche les consommations d'un batch depuis le lot X (fantôme) vers le lot Y
// (même matière), en réécrivant le snapshot HACCP. Blocage si Y insuffisant.
// Retourne un PLAN (dry-run) si opts.simuler, sinon exécute dans une transaction.
async function prelevReaffecter(prodId, materialId, lotFromId, lotToIds, opts){
  opts = opts || {};
  // lotToIds : liste ORDONNÉE de lots destination (même matière). Répartition gloutonne :
  // chaque lot absorbe min(reste, qteRestante) dans l'ordre, jusqu'à couvrir le total.
  const toIds = Array.isArray(lotToIds) ? lotToIds.map(Number) : [Number(lotToIds)];
  const from = await db.materialLots.get(lotFromId).catch(()=>null);
  if(!from) return {ok:false, raison:'Lot source introuvable.'};
  if(+from.materialId!==+materialId) return {ok:false, raison:'Le lot source n\'appartient pas à cette matière.'};
  if(toIds.some(id=>+id===+lotFromId)) return {ok:false, raison:'Un lot destination est identique au lot source.'};
  if(new Set(toIds).size!==toIds.length) return {ok:false, raison:'Un même lot destination est renseigné deux fois.'};

  const tos = [];
  for(const id of toIds){
    const l = await db.materialLots.get(id).catch(()=>null);
    if(!l) return {ok:false, raison:'Lot destination introuvable (#'+id+').'};
    if(+l.materialId!==+materialId) return {ok:false, raison:'Tous les lots doivent être de la même matière.'};
    tos.push(l);
  }

  // Lignes de conso de CE batch sur le lot X, encore actives.
  const conso = (await db.prodConsumption.where('productionId').equals(prodId).toArray().catch(()=>[]))
    .filter(c=>+c.materialLotId===+lotFromId && !c.annuleeInventaire);
  const total = round3(conso.reduce((s,c)=>s+(+c.qteConsommee||0),0));
  if(!(total>0)) return {ok:false, raison:'Aucune consommation de ce lot à réaffecter pour ce batch.'};

  // Allocation gloutonne : combien chaque lot destination fournit.
  let reste = total;
  const alloc = [];   // {lot, prend}
  for(const l of tos){
    if(reste<=1e-9) break;
    const prend = round3(Math.min(reste, +l.qteRestante||0));
    if(prend>0){ alloc.push({lot:l, prend}); reste = subQty(reste, prend); }
  }
  const couvert = round3(total - reste);
  const nom = l => l.lotFournisseur||('lot #'+l.id);
  const plan = {ok:true, total, couvert, reste, nbLignes:conso.length,
    fromNom: nom(from),
    repartition: alloc.map(a=>({lotId:a.lot.id, nom:nom(a.lot), prend:a.prend})) };

  // GARDE-FOU : couverture incomplète → on ne bloque pas sèchement, on RENVOIE l'état
  // pour que l'UI propose « ajouter un lot ou annuler ».
  if(reste > 1e-9){
    return {ok:false, incomplet:true, total, couvert, reste, repartition:plan.repartition,
      raison:`Lot impossible à consommer car dépasse la quantité de matière à redistribuer : ${qty(couvert)} couverts sur ${qty(total)}, il reste ${qty(reste)} à affecter.`};
  }
  if(opts.simuler) return plan;

  await db.transaction('rw', db.materialLots, db.prodConsumption, async()=>{
    const nowIso = new Date().toISOString();
    // X ré-abondé du total (le stock fantôme remonte → à régulariser via inventaire ensuite).
    await db.materialLots.update(from.id, {qteRestante: round3((+from.qteRestante||0)+total)});
    // File des allocations à consommer par les lignes (dans l'ordre).
    const file = alloc.map(a=>({lot:a.lot, reste:a.prend}));
    for(const l of tos) await db.materialLots.update(l.id, {qteRestante: subQty(l.qteRestante,
      (alloc.find(a=>+a.lot.id===+l.id)||{prend:0}).prend)});
    // Pour chaque ligne de conso : la découper entre les lots destination selon la file.
    let fi = 0;
    for(const c of conso){
      let q = round3(+c.qteConsommee||0);
      let premier = true;
      while(q > 1e-9 && fi < file.length){
        const slot = file[fi];
        const part = round3(Math.min(q, slot.reste));
        const snap = {
          materialLotId: slot.lot.id, snapMaterialId: materialId,
          snapLotFournisseur: slot.lot.lotFournisseur||'', snapSupplierId: slot.lot.supplierId||0,
          snapDlc: slot.lot.dlc||'', snapDlcOuverture: slot.lot.dlcOuverture||'',
          reaffecteTs: nowIso, reaffecteDe: from.id, reaffecteDeNom: plan.fromNom
        };
        if(premier){
          // la ligne existante est REBRANCHÉE sur le 1er lot (avec sa part)
          await db.prodConsumption.update(c.id, Object.assign({qteConsommee: part}, snap));
          premier = false;
        } else {
          // le reste de la ligne devient une NOUVELLE ligne (split HACCP) sur le lot suivant
          await db.prodConsumption.add(Object.assign(
            {productionId: prodId, qteConsommee: part, reaffecteSplit:true}, snap));
        }
        q = subQty(q, part); slot.reste = subQty(slot.reste, part);
        if(slot.reste<=1e-9) fi++;
      }
    }
  });
  return {ok:true, execute:true, total, nbLignes:conso.length, fromNom:plan.fromNom,
          repartition:plan.repartition, nbLotsDest:alloc.length};
}
/* PRELEV:PURE:END */

// Raccourci depuis la traçabilité : ouvre l'écran Prélèvements sur un batch et déclenche
// immédiatement la réaffectation de lot pour UNE matière précise. On réutilise prelevForm
// (qui peuple _prelevCtx) puis on ouvre le panneau Réaffecter de cette matière — aucune
// duplication du moteur (prelevReaffecter, testé) ni du contexte.
async function prelevOpenReaffect(prodId, materialId){
  await prelevForm(prodId);
  // prelevForm a rendu la modale + _prelevCtx ; on déclenche l'action ciblée.
  if(window._prelevCtx && +window._prelevCtx.prodId===+prodId
     && (window._prelevCtx.liste||[]).some(x=>+x.materialId===+materialId)){
    try{ await prelevActionReaffecter(prodId, materialId); }
    catch(e){ console.error('prelevOpenReaffect', e); }
    // amener le panneau de cette matière à l'écran
    const el = document.getElementById('prlv-panel-'+materialId);
    if(el && el.scrollIntoView) try{ el.scrollIntoView({block:'center'}); }catch(e){swallow(e,'prelevOpenReaffect')}
  } else {
    // La matière est visible en traçabilité mais absente des prélèvements ACTIFS :
    // sa consommation a déjà été remplacée ou réaffectée (ligne neutralisée).
    closeModal();
    openModal(`<h3>Rien à réaffecter ici</h3>
      <p class="note" style="margin:10px 0">La consommation de cette matière sur ce lot a déjà été <b>remplacée ou réaffectée</b> précédemment : il n'y a plus de prélèvement actif à corriger.</p>
      <p class="note" style="margin:10px 0">L'ancienne affectation reste visible en traçabilité, dans « 🕓 Historique des corrections de lot », pour garder la trace de ce qui s'est passé.</p>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal();traceProd(${prodId})">← Retour traçabilité</button></div>`);
  }
}

// ---- UI : ouverte depuis le pop d'un lot (prodV2) --------------------------
async function prelevForm(prodId){
  const p = await db.productions.get(prodId).catch(()=>null);
  if(!p){ toast('Lot introuvable'); return; }
  if(!p.recipeId){ toast('Ce lot n\'est pas rattaché à une recette'); return; }
  const liste = await prelevListe(prodId);
  const mats = await db.materials.toArray().catch(()=>[]);
  const matById = {}; mats.forEach(m=>matById[+m.id]=m);
  const nomLot = p.lotProduction || ('#'+p.id);

  if(!liste.length){
    openModal(`<h3>✎ Prélèvements — lot ${esc(nomLot)}</h3>
      <p class="note">Aucune consommation de matière enregistrée pour ce lot.</p>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  const cards = liste.map(l=>{
    const m = matById[l.materialId]; const u = (m&&m.unite)||'g';
    const lotIds = Object.keys(l.lots);
    const chip = lotIds.length===1
      ? `<span class="prlv-chip" id="prlv-lotname-${l.materialId}">lot #${lotIds[0]}</span>`
      : `<span class="prlv-chip">${lotIds.length} lots</span>`;
    return `<div class="prlv-card">
      <div class="prlv-line"><span class="prlv-nom">${esc(m?m.nom:('#'+l.materialId))}</span><b>${qty(l.qte)} ${esc(u)}</b></div>
      ${chip}
      <div class="prlv-acts">
        <button class="btn ghost sm" onclick="prelevActionQuantite(${prodId},${l.materialId})">✎ Quantité</button>
        <button class="btn ghost sm" onclick="prelevActionLot(${prodId},${l.materialId})">🔀 Changer de lot</button>
        <button class="btn gold sm" onclick="prelevActionRemplacer(${prodId},${l.materialId})">⇄ Remplacer</button>
        <button class="btn ghost sm" onclick="prelevActionReaffecter(${prodId},${l.materialId})" title="Corriger rétroactivement le lot réellement consommé (HACCP)">⇄ Réaffecter le lot</button>
      </div>
      <div id="prlv-panel-${l.materialId}"></div>
    </div>`;
  }).join('');
  window._prelevCtx = {prodId, liste, matById, nomLot};
  openModal(`<h3>✎ Prélèvements — lot ${esc(nomLot)}</h3>
    <style>
    .prlv-card{background:#fff;border:1px solid var(--hair,#e7ddd2);border-radius:12px;padding:11px 12px;margin-bottom:9px}
    .prlv-line{display:flex;justify-content:space-between;align-items:center}
    .prlv-nom{font-weight:700;color:var(--bordeaux,#52252F);font-size:.95rem}
    .prlv-chip{display:inline-block;background:var(--creme-2,#F5F0E8);border-radius:20px;padding:2px 9px;font-size:.72rem;color:#6a5a52;margin-top:4px}
    .prlv-acts{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}
    .btn.sm{padding:6px 10px;font-size:.77rem}
    .prlv-panel{background:var(--creme-2,#F5F0E8);border-radius:10px;padding:10px;margin-top:9px}
    .prlv-lbl{font-size:.7rem;font-weight:700;color:var(--bordeaux,#52252F);text-transform:uppercase;letter-spacing:.03em;margin:8px 0 3px}
    .prlv-sum{display:flex;justify-content:space-between;padding:4px 0;font-size:.82rem;border-bottom:1px solid var(--hair,#e7ddd2)}
    .prlv-warn{background:#fff8ec;border:1px solid #e8cfa0;border-radius:8px;padding:7px 9px;font-size:.75rem;margin-top:7px;color:#7a5a1f}
    </style>
    <p class="note" style="margin-bottom:10px">Corrige ce que ce lot a réellement prélevé. Chaque correction est atomique et tracée ; une sauvegarde est prise avant.</p>
    ${cards}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}

function _prelevPanel(materialId, html){
  const el = document.getElementById('prlv-panel-'+materialId);
  if(el) el.innerHTML = html ? `<div class="prlv-panel">${html}</div>` : '';
}
function _prelevMat(materialId){ return (window._prelevCtx.matById||{})[+materialId]||{}; }

async function _prelevLotsOptions(materialId, exclureLotId){
  const u = _prelevMat(materialId).unite || 'g';
  const lots = (await db.materialLots.where('materialId').equals(+materialId).and(l=>+l.qteRestante>0).toArray().catch(()=>[])).sort(lotFifoCompare);
  return lots.filter(l=>+l.id!==+exclureLotId).map(l=>`<option value="${l.id}">${esc(l.lotFournisseur||('lot #'+l.id))} · ${qty(l.qteRestante)} ${esc(u)}${l.dlc?' · DLC '+fmtDate(l.dlc):''}</option>`).join('');
}

// ── Action 1 : corriger la QUANTITÉ (même matière, FIFO ou lot en place) ──
async function prelevActionQuantite(prodId, materialId){
  const cur = (window._prelevCtx.liste.find(x=>+x.materialId===+materialId)||{}).qte||0;
  const u = _prelevMat(materialId).unite || 'g';
  _prelevPanel(materialId, `
    <div class="prlv-lbl">Nouvelle quantité réellement prélevée (${esc(u)})</div>
    <input type="number" id="prlv_q_${materialId}" class="in" min="0" step="0.1" value="${cur}" style="width:100%;padding:8px 10px;border:1px solid var(--hair,#e7ddd2);border-radius:9px">
    <p class="note" style="margin-top:6px">Si tu baisses la quantité, l'excédent revient sur les lots d'origine ; si tu l'augmentes, le complément est prélevé en FIFO.</p>
    <div class="prlv-acts"><button class="btn ghost sm" onclick="_prelevPanel(${materialId},'')">Annuler</button>
      <button class="btn gold sm" onclick="prelevQuantiteGo(${prodId},${materialId})">✓ Valider</button></div>`);
}
async function prelevQuantiteGo(prodId, materialId){
  const nouvelle = round3(+val('prlv_q_'+materialId)||0);
  const cur = (window._prelevCtx.liste.find(x=>+x.materialId===+materialId)||{}).qte||0;
  if(nouvelle===cur){ toast('Quantité inchangée'); return; }
  try{ await snapshotBackup('avant-prelevement'); }catch(e){swallow(e,'prelevQuantiteGo')}
  // on repart propre : on rend tout à l'origine, puis on reprélève la nouvelle quantité en FIFO
  await db.transaction('rw', db.productions, db.materialLots, db.prodConsumption, async()=>{
    await prelevAnnulerMatiere(prodId, materialId, true);   // rendre à l'origine
  });
  const res = await consoFixApply(prodId, materialId, nouvelle, null); // FIFO
  closeModal(); toast(res.manque>0?`Ajusté · ${qty(res.manque)} manquant(s) (stock épuisé)`:'Quantité corrigée ✓');
  if(typeof renderProductionsV2==='function' && view==='productionsv2') renderProductionsV2();
}

// ── Action 2 : changer de LOT (même matière, même quantité) ──
async function prelevActionLot(prodId, materialId){
  const opts = await _prelevLotsOptions(materialId, null);
  if(!opts){ _prelevPanel(materialId, `<p class="note bad">Aucun autre lot disponible pour cette matière.</p>`); return; }
  const cur = (window._prelevCtx.liste.find(x=>+x.materialId===+materialId)||{}).qte||0;
  const u = _prelevMat(materialId).unite||'g';
  _prelevPanel(materialId, `
    <div class="prlv-lbl">Déplacer le prélèvement (${qty(cur)} ${esc(u)}) vers</div>
    <select id="prlv_lot_${materialId}" class="in" style="width:100%;padding:8px 10px;border:1px solid var(--hair,#e7ddd2);border-radius:9px">${opts}</select>
    <div class="prlv-sum" style="margin-top:8px"><span>↩ Rendu aux lots d'origine</span><b class="good" style="color:#3f7d52">+${qty(cur)} ${esc(u)}</b></div>
    <div class="prlv-sum"><span>↘ Prélevé sur le lot choisi</span><b>−${qty(cur)} ${esc(u)}</b></div>
    <div class="prlv-acts"><button class="btn ghost sm" onclick="_prelevPanel(${materialId},'')">Annuler</button>
      <button class="btn gold sm" onclick="prelevLotGo(${prodId},${materialId})">✓ Valider</button></div>`);
}
async function prelevLotGo(prodId, materialId){
  const lotId = +val('prlv_lot_'+materialId)||0;
  const cur = (window._prelevCtx.liste.find(x=>+x.materialId===+materialId)||{}).qte||0;
  if(!lotId||!(cur>0)){ toast('Lot ou quantité invalide'); return; }
  try{ await snapshotBackup('avant-prelevement'); }catch(e){swallow(e,'prelevLotGo')}
  await db.transaction('rw', db.productions, db.materialLots, db.prodConsumption, async()=>{
    await prelevAnnulerMatiere(prodId, materialId, true);  // rendre à l'origine
  });
  const res = await consoFixApply(prodId, materialId, cur, lotId);  // imposer le lot choisi
  closeModal(); toast(res.manque>0?`Déplacé · ${qty(res.manque)} manquant(s)`:'Lot changé ✓');
  if(typeof renderProductionsV2==='function' && view==='productionsv2') renderProductionsV2();
}

// ── Action 3 : REMPLACER la matière (X → Y), avec la question inventaire ──
async function prelevActionRemplacer(prodId, materialId){
  const mats = (await db.materials.toArray().catch(()=>[])).filter(m=>+m.id!==+materialId).sort((a,b)=>(a.nom||'').localeCompare(b.nom||''));
  const cur = (window._prelevCtx.liste.find(x=>+x.materialId===+materialId)||{}).qte||0;
  const uX = _prelevMat(materialId).unite||'g';
  const opts = mats.map(m=>`<option value="${m.id}">${esc(m.nom)}${m.unite&&m.unite!==uX?` (${esc(m.unite)})`:''}</option>`).join('');
  _prelevPanel(materialId, `
    <div class="prlv-lbl">Remplacer par</div>
    <select id="prlv_y_${materialId}" class="in" style="width:100%;padding:8px 10px;border:1px solid var(--hair,#e7ddd2);border-radius:9px"><option value="">— choisir —</option>${opts}</select>
    <div class="prlv-lbl">Quantité à prélever (${esc(uX)})</div>
    <input type="number" id="prlv_yq_${materialId}" class="in" min="0" step="0.1" value="${cur}" style="width:100%;padding:8px 10px;border:1px solid var(--hair,#e7ddd2);border-radius:9px">
    <div class="prlv-lbl">Prise sur le stock (nouvelle matière)</div>
    <select id="prlv_ylot_${materialId}" class="in" style="width:100%;padding:8px 10px;border:1px solid var(--hair,#e7ddd2);border-radius:9px"><option value="">FIFO — le plus ancien d'abord (recommandé)</option></select>
    <div class="prlv-warn">À la validation, l'app te demandera si l'ancienne matière (${esc(_prelevMat(materialId).nom||'')}) <b>sort du stock</b> (régularisation d'inventaire) ou <b>revient sur son lot d'origine</b>.</div>
    <div class="prlv-acts"><button class="btn ghost sm" onclick="_prelevPanel(${materialId},'')">Annuler</button>
      <button class="btn gold sm" onclick="prelevRemplacerGo(${prodId},${materialId})">⇄ Valider le remplacement</button></div>`);
  // peupler les lots de Y quand on choisit Y
  const sy = document.getElementById('prlv_y_'+materialId);
  if(sy) sy.onchange = async ()=>{
    const yid = +sy.value||0; const sel = document.getElementById('prlv_ylot_'+materialId);
    if(!sel) return;
    if(!yid){ sel.innerHTML = `<option value="">FIFO — le plus ancien d'abord (recommandé)</option>`; return; }
    const opts2 = await _prelevLotsOptions(yid, null);
    sel.innerHTML = `<option value="">FIFO — le plus ancien d'abord (recommandé)</option>${opts2}`;
  };
}
async function prelevActionReaffecter(prodId, materialId){
  const consoLots = new Set((window._prelevCtx.liste.find(x=>+x.materialId===+materialId)||{}).lots
    ? Object.keys((window._prelevCtx.liste.find(x=>+x.materialId===+materialId)||{}).lots).map(Number) : []);
  const lots = (await db.materialLots.where('materialId').equals(+materialId).toArray().catch(()=>[]));
  const u = _prelevMat(materialId).unite||'g';
  const srcOpts = [...consoLots].map(id=>{ const l=lots.find(x=>+x.id===id);
    return `<option value="${id}">${esc(l?l.lotFournisseur||('lot #'+id):('lot #'+id))}</option>`; }).join('');
  const dst = lots.filter(l=>!consoLots.has(+l.id));
  if(!dst.length){ _prelevPanel(materialId, `<p class="note bad">Aucun autre lot de cette matière. Crée le bon lot d'abord (Réception).</p>`); return; }
  // état multi-lots par matière (liste ordonnée d'ids destination)
  window._prelevReaff = window._prelevReaff || {};
  window._prelevReaff[materialId] = { from: [...consoLots][0]||0, to: [] };
  _prelevPanel(materialId, `
    <div class="prlv-warn">Correction rétroactive de traçabilité : rebranche ce que ce batch a « consommé » du mauvais lot vers le(s) vrai(s). Le snapshot HACCP est réécrit ; le stock du mauvais lot remonte (à régulariser ensuite en inventaire).</div>
    <div class="prlv-lbl">Lot enregistré à tort (source)</div>
    <select id="prlv_rfrom_${materialId}" class="in" onchange="prelevReaffRefresh(${prodId},${materialId})" style="width:100%;padding:8px 10px;border:1px solid var(--hair,#e7ddd2);border-radius:9px">${srcOpts}</select>
    <div id="prlv_rbody_${materialId}"></div>`);
  prelevReaffRefresh(prodId, materialId);
}

// Recalcule couverture + rendu de la liste des lots destination + actions contextuelles.
async function prelevReaffRefresh(prodId, materialId){
  const st = (window._prelevReaff||{})[materialId]; if(!st) return;
  st.from = +val('prlv_rfrom_'+materialId)||st.from;
  const u = _prelevMat(materialId).unite||'g';
  // simulation moteur : total à couvrir + répartition + reste
  const sim = await prelevReaffecter(prodId, materialId, st.from, st.to, {simuler:true});
  // total (même si incomplet, le moteur le renvoie)
  const total = (sim.total!=null) ? sim.total : 0;
  const couvert = (sim.couvert!=null) ? sim.couvert : (sim.ok?sim.total:0);
  const reste = (sim.reste!=null) ? sim.reste : 0;
  const rep = sim.repartition||[];
  const lots = (await db.materialLots.where('materialId').equals(+materialId).toArray().catch(()=>[]));
  const nomLot = id => { const l=lots.find(x=>+x.id===+id); return l?(l.lotFournisseur||('lot #'+id)):('lot #'+id); };
  const dispoLot = id => { const l=lots.find(x=>+x.id===+id); return l?round3(+l.qteRestante||0):0; };
  const chips = st.to.map((id,i)=>{
    const part = (rep.find(r=>+r.lotId===+id)||{}).prend||0;
    return `<div class="prlv-sum"><span>${esc(nomLot(id))} <em style="color:#9a8a82">(dispo ${qty(dispoLot(id))} ${esc(u)})</em></span>
      <b>−${qty(part)} ${esc(u)}</b> <span class="prlv-x" onclick="prelevReaffDel(${prodId},${materialId},${i})" style="cursor:pointer;color:#b3261e;margin-left:6px">✕</span></div>`;
  }).join('');
  const complet = reste<=1e-9 && total>0;
  const consoLots = new Set((window._prelevCtx.liste.find(x=>+x.materialId===+materialId)||{}).lots
    ? Object.keys((window._prelevCtx.liste.find(x=>+x.materialId===+materialId)||{}).lots).map(Number) : []);
  const restants = lots.filter(l=>!consoLots.has(+l.id) && +l.id!==+st.from && !st.to.includes(+l.id) && (+l.qteRestante||0)>0);
  const addOpts = restants.map(l=>`<option value="${l.id}">${esc(l.lotFournisseur||('lot #'+l.id))} · ${qty(l.qteRestante)} ${esc(u)}${l.dlc?' · DLC '+fmtDate(l.dlc):''}</option>`).join('');
  const body = document.getElementById('prlv_rbody_'+materialId); if(!body) return;
  body.innerHTML = `
    <div class="prlv-lbl">Vrai(s) lot(s) réellement utilisé(s)</div>
    ${chips||'<p class="note" style="margin:2px 0">Aucun lot ajouté pour l\'instant.</p>'}
    <div class="prlv-sum" style="border-top:2px solid var(--hair,#e7ddd2);font-weight:700">
      <span>Couvert ${qty(couvert)} / ${qty(total)} ${esc(u)}</span>
      <b style="color:${complet?'#3f7d52':'#b3261e'}">${complet?'✓ complet':'reste '+qty(reste)+' '+u}</b></div>
    ${!complet ? `<div class="prlv-warn" style="background:#fdecea;border-color:#f0b7ae;color:#7a2a20">Lot impossible à consommer car dépasse la quantité de matière à redistribuer : renseigne un lot supplémentaire ou annule.</div>` : ''}
    ${addOpts ? `<div class="prlv-lbl">Ajouter un lot existant</div>
      <div style="display:flex;gap:6px">
        <select id="prlv_radd_${materialId}" class="in" style="flex:1;padding:8px 10px;border:1px solid var(--hair,#e7ddd2);border-radius:9px">${addOpts}</select>
        <button class="btn ghost sm" onclick="prelevReaffAdd(${prodId},${materialId})">➕ Ajouter</button>
      </div>` : `<p class="note">Plus aucun autre lot existant de cette matière.</p>`}
    <button class="btn ghost sm" style="margin-top:6px" onclick="prelevReaffNouveauLot(${prodId},${materialId})">➕ Créer / réceptionner un lot</button>
    <div class="prlv-acts" style="margin-top:8px">
      <button class="btn ghost sm" onclick="_prelevPanel(${materialId},'');delete (window._prelevReaff||{})[${materialId}]">Annuler</button>
      <button class="btn gold sm" ${complet?'':'disabled style="opacity:.45"'} onclick="prelevReaffValider(${prodId},${materialId})">⇄ Réaffecter</button>
    </div>`;
}
function prelevReaffAdd(prodId, materialId){
  const st=(window._prelevReaff||{})[materialId]; if(!st) return;
  const id=+val('prlv_radd_'+materialId)||0; if(!id){ toast('Choisis un lot'); return; }
  if(!st.to.includes(id)) st.to.push(id);
  prelevReaffRefresh(prodId, materialId);
}
function prelevReaffDel(prodId, materialId, idx){
  const st=(window._prelevReaff||{})[materialId]; if(!st) return;
  st.to.splice(idx,1); prelevReaffRefresh(prodId, materialId);
}
// Créer/réceptionner un lot puis l'ajouter à la répartition : on réutilise le formulaire
// de réception existant (lotForm) en lui passant la matière ; au retour, on rafraîchit.
function prelevReaffNouveauLot(prodId, materialId){
  // [v1302] Code mort neutralisé : window._prelevReaffPending écrit ici, jamais relu.
  // window._prelevReaffPending = {prodId, materialId};
  if(typeof lotForm==='function'){ closeModal(); lotForm(null, materialId); }
  else toast('Réception de lot indisponible');
}
async function prelevReaffValider(prodId, materialId){
  const st=(window._prelevReaff||{})[materialId]; if(!st) return;
  const sim = await prelevReaffecter(prodId, materialId, st.from, st.to, {simuler:true});
  if(!sim.ok){ toast(sim.raison||'Répartition incomplète'); return; }
  const lots = (await db.materialLots.where('materialId').equals(+materialId).toArray().catch(()=>[]));
  const nomLot = id => { const l=lots.find(x=>+x.id===+id); return l?(l.lotFournisseur||('lot #'+id)):('lot #'+id); };
  const detail = sim.repartition.map(r=>`• ${nomLot(r.lotId)} : ${qty(r.prend)}`).join('\n');
  if(!confirm(`Réaffecter ${qty(sim.total)} depuis « ${nomLot(st.from)} » ?\n\n${detail}\n\n• Snapshot HACCP réécrit par lot\n• Le stock du lot source remonte de ${qty(sim.total)} (à régulariser en inventaire)`)) return;
  try{ await snapshotBackup('avant-reaffectation'); }catch(e){swallow(e,'prelevReaffValider')}
  const res = await prelevReaffecter(prodId, materialId, st.from, st.to, {});
  closeModal(); delete (window._prelevReaff||{})[materialId];
  toast(res.ok ? `Réaffecté ✓ ${qty(res.total)} sur ${res.nbLotsDest} lot(s)` : (res.raison||'Échec'));
  if(typeof renderProductionsV2==='function' && view==='productionsv2') renderProductionsV2();
}
async function prelevRemplacerGo(prodId, materialId){
  const yId = +val('prlv_y_'+materialId)||0;
  const qte = round3(+val('prlv_yq_'+materialId)||0);
  const yLot = +val('prlv_ylot_'+materialId)||0;
  if(!yId){ toast('Choisis la matière de remplacement'); return; }
  if(!(qte>0)){ toast('Quantité invalide'); return; }
  const mX = _prelevMat(materialId);
  // QUESTION SYSTÉMATIQUE (contrat métier) : sortir l'ancienne ou la rendre ?
  const sortir = confirm(`Remplacement de « ${mX.nom||''} ».\n\nL'ancienne matière prélevée doit-elle SORTIR du stock en régularisation d'inventaire ?\n\n• OK = elle sort du stock (le stock affiché était erroné)\n• Annuler = elle revient sur son lot d'origine`);
  try{ await snapshotBackup('avant-prelevement'); }catch(e){swallow(e,'prelevRemplacerGo')}
  // 1) neutraliser la conso de X.
  //    - rendre=false (SORTIR) : on NE rend PAS → le stock reste décrémenté par la conso
  //      initiale, ce qui EST la sortie en régularisation (pas de second retrait, sinon
  //      on décompterait deux fois). La ligne est marquée 'sortie-regul-inventaire'.
  //    - rendre=true (REVENIR) : la quantité remonte sur le lot d'origine.
  await db.transaction('rw', db.productions, db.materialLots, db.prodConsumption, async()=>{
    await prelevAnnulerMatiere(prodId, materialId, /*rendre=*/!sortir);
  });
  // 3) prélever Y (FIFO ou lot imposé)
  const res = await consoFixApply(prodId, yId, qte, yLot||null);
  closeModal();
  toast(res.manque>0 ? `Remplacé · ${qty(res.manque)} manquant(s) sur la nouvelle matière` : (sortir?'Remplacé · ancienne matière sortie en régul ✓':'Remplacé · ancienne matière rendue au stock ✓'));
  if(typeof renderProductionsV2==='function' && view==='productionsv2') renderProductionsV2();
}
