// Coordonnées émetteur (saisies une fois, stockées en local).
function factGetEmetteur(){
  try{ return JSON.parse(localStorage.getItem('sm_facture')||'{}'); }catch(e){ return {}; }
}
function factSaveEmetteur(o){ localStorage.setItem('sm_facture', JSON.stringify(o)); }
// Formulaire des coordonnées de facturation.
function factEmetteurForm(retourOrderId){
  const e=factGetEmetteur();
  openModal(`<h3>🧾 Coordonnées de facturation</h3>
    <p class="note" style="margin-bottom:10px">Ces lignes formeront le bloc sous ton logo. Chaque champ a une longueur max pour un rendu harmonieux. Le nom de l'enseigne n'est pas répété (il est déjà dans le logo).</p>
    <div class="field"><label>Exploitant (nom + prénom) <span style="color:#9a8a82;font-weight:400">— max 40</span></label><input id="fa_exploitant" maxlength="40" value="${esc(e.exploitant||'')}" placeholder="ex : Benjamin Dupont"></div>
    <div class="field"><label>Adresse (n° + rue) <span style="color:#9a8a82;font-weight:400">— max 40</span></label><input id="fa_adresse" maxlength="40" value="${esc(e.adresse||'')}" placeholder="ex : 12 rue des Lilas"></div>
    <div class="field"><label>Code postal + Ville <span style="color:#9a8a82;font-weight:400">— max 35</span></label><input id="fa_cpville" maxlength="35" value="${esc(e.cpville||'')}" placeholder="ex : 72000 Le Mans"></div>
    <div class="row2">
      <div class="field"><label>Téléphone <span style="color:#9a8a82;font-weight:400">— max 20</span></label><input id="fa_tel" maxlength="20" value="${esc(e.tel||'')}" placeholder="ex : 06 12 34 56 78"></div>
      <div class="field"><label>SIRET <span style="color:#9a8a82;font-weight:400">— 14 chiffres</span></label><input id="fa_siret" maxlength="20" value="${esc(e.siret||'')}" placeholder="14 chiffres"></div>
    </div>
    <div class="field"><label>E-mail <span style="color:#9a8a82;font-weight:400">— max 40</span></label><input id="fa_email" maxlength="40" value="${esc(e.email||'')}" placeholder="ex : contact@sensations-macarons.fr"></div>
    <div class="field"><label>Nom commercial (interne, pour le pied de page)</label><input id="fa_nom" value="${esc(e.nom||'Sensations Macarons')}"></div>
    <div class="field"><label>Mentions de paiement (facultatif)</label><input id="fa_paiement" maxlength="80" value="${esc(e.paiement||'Paiement à réception.')}"></div>
    <div class="field"><label>Coordonnées bancaires <span style="color:#9a8a82;font-weight:400">— IBAN / BIC, apparaît en pied de page (facultatif)</span></label><textarea id="fa_iban" maxlength="160" rows="3" placeholder="ex :&#10;IBAN : FR76 1234 5678 9012 3456 7890 123&#10;BIC : ABCDEFGH&#10;Titulaire : Sensations Macarons">${esc(e.iban||'')}</textarea></div>
    <div class="field"><label>Médiateur de la consommation <span style="color:#9a8a82;font-weight:400">— nom + adresse (obligatoire pour les ventes aux particuliers)</span></label><input id="fa_mediateurNom" maxlength="120" value="${esc(e.mediateurNom||'MCP Médiation, 12 square Desnouettes, 75015 Paris')}" placeholder="ex : MCP Médiation, 12 square Desnouettes, 75015 Paris"></div>
    <div class="field"><label>Site du médiateur <span style="color:#9a8a82;font-weight:400">— adresse du site (obligatoire : permet au client de saisir le médiateur)</span></label><input id="fa_mediateurUrl" maxlength="120" value="${esc(e.mediateurUrl||'https://mcpmediation.org')}" placeholder="ex : https://mcpmediation.org"></div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="factSaveEmetteurAndBack(${retourOrderId||0})">Enregistrer</button>
    </div>`);
}
async function factSaveEmetteurAndBack(orderId){
  const o={ nom:val('fa_nom'), exploitant:val('fa_exploitant'), adresse:val('fa_adresse'),
    cpville:val('fa_cpville'), siret:val('fa_siret'), tel:val('fa_tel'), email:val('fa_email'), paiement:val('fa_paiement'), iban:val('fa_iban'),
    mediateurNom:val('fa_mediateurNom'), mediateurUrl:val('fa_mediateurUrl') };
  factSaveEmetteur(o);
  closeModal();
  toast('Coordonnées enregistrées ✓');
  if(orderId) setTimeout(()=>genererFacture(orderId), 200);
}
// Libellé détaillé d'une ligne pour la facture (avec parfums).
function factLineDesc(ln){
  const parfums = (ln.parfums||[]).filter(p=>+p.qte>0).map(p=>`${p.nom} ×${p.qte}`).join(', ');
  const items = (ln.items||[]).filter(p=>+p.qte>0).map(p=>`${p.nom} ×${p.qte}`).join(', ');
  // Mention texte des macarons « sans parfum » selon spMode (voir spLibelle HTML).
  const spTxt = (()=>{
    const nb=+ln.sansParfum||0; if(nb<=0) return '';
    if((ln.spMode||'assortiment')==='adeterminer') return `parfum(s) à déterminer ×${nb}`;
    const n=+ln.spNbParfums||0;
    return (n===1?`1 parfum ×${nb}`:(n>1?`assortiment ${n} parfums ×${nb}`:`assortiment ×${nb}`));
  })();
  const joinP = base => { const parts=[parfums, spTxt].filter(Boolean).join(', '); return parts?base+' — '+parts:base; };
  if(ln.type==='coffret') return joinP(`Coffret ${ln.taille} macarons`);

  if(ln.type==='grand') return `Macarons grand format${items?' — '+items:''}`;
  if(ln.type==='vrac') return joinP(`Macarons`);
  if(ln.type==='sachet') return joinP(`Sachet de macarons`);
  if(ln.type==='don') return `Don (offert)${(parfums||items)?' — '+(parfums||items):''}`;
  if(ln.type==='prestation'){
    if(ln.isLivraison) return ln.libelle || 'Frais de livraison';   // livraison : libellé direct, sans préfixe
    return `Prestation${ln.libelle?' : '+ln.libelle:''}`;
  }
  return 'Article';
}
// Version HTML de la description d'une ligne pour les documents (devis + facture).
// Permet un rendu multi-lignes (parfums un par un, mention de location de matériel).
// Pour l'événement : « Prestation événement : N macarons », puis 1 parfum par ligne,
// puis « location de matériel : N pyramide(s), à retourner sous 48h » si pyramides.
function factLineDescHtml(ln){
  const parfums = (ln.parfums||[]).filter(p=>+p.qte>0);
  const items = (ln.items||[]).filter(p=>+p.qte>0);
  // [PARFUMS NON SPÉCIFIÉS] Libellé document pour les macarons « sans parfum » selon spMode.
  // Assortiment : « assortiment N parfums » (ou « assortiment » si N absent ; « 1 parfum » si N=1,
  // car 1 parfum n'est pas un assortiment). À déterminer : « parfum(s) à déterminer ».
  const spLibelle = (l)=>{
    const nb = +l.sansParfum||0; if(nb<=0) return '';
    const mode = l.spMode || 'assortiment';
    let txt;
    if(mode==='adeterminer'){
      txt = 'parfum(s) à déterminer';
    } else {
      const n = +l.spNbParfums||0;
      txt = n===1 ? '1 parfum' : (n>1 ? `assortiment ${n} parfums` : 'assortiment');
    }
    return `<span class="ln-sub">${esc(txt)} ×${nb}</span>`;
  };
  if(ln.type==='evenement'){
    const tete = `Prestation événement : ${ln.evQte||0} macarons`;
    const lignesParfums = parfums.map(p=>`<span class="ln-sub">${esc(p.nom)} ×${+p.qte}</span>`).join('');
    return `<span class="ln-main">${esc(tete)}</span>${lignesParfums}${spLibelle(ln)}`;
  }
  if(ln.type==='coffret'){
    const tete = `Coffret ${ln.taille} macarons`;
    const lignesParfums = parfums.map(p=>`<span class="ln-sub">${esc(p.nom)} ×${+p.qte}</span>`).join('');
    return `<span class="ln-main">${esc(tete)}</span>${lignesParfums}${spLibelle(ln)}`;
  }
  if(ln.type==='vrac'){
    const lignesParfums = parfums.map(p=>`<span class="ln-sub">${esc(p.nom)} ×${+p.qte}</span>`).join('');
    return `<span class="ln-main">Macarons</span>${lignesParfums}${spLibelle(ln)}`;
  }
  if(ln.type==='sachet'){
    const lignesParfums = parfums.map(p=>`<span class="ln-sub">${esc(p.nom)} ×${+p.qte}</span>`).join('');
    return `<span class="ln-main">Sachet de macarons</span>${lignesParfums}${spLibelle(ln)}`;
  }
  // Autres types : on garde la description texte existante (échappée).
  return esc(factLineDesc(ln));
}
// Lignes de tableau (<tr>) d'un document pour une ligne de commande.
// Cas général : une seule <tr> (description + montant total de la ligne).
// Cas événement avec pyramides : DEUX <tr> — d'abord les macarons (part macarons),
// puis une ligne « Prestation de service — location de pyramide » (quantité × prix unitaire).
// La somme des deux montants reste STRICTEMENT égale au sous-total de la ligne (aucun double comptage).
// [RABAIS TOTAL CONSENTI] Cumule TOUS les rabais du document (remises de ligne + remise perso
// + remise globale) et l'exprime en euros et en % du total BRUT (avant toute remise).
// brutAbsolu = Σ bruts de ligne (avant remise de ligne) + supplément perso BRUT (avant remise perso).
// rabais = brutAbsolu − totalNet (le montant réellement facturé, hors frais de livraison).
function docRabaisTotal(lignes, persoNb, totalNetHorsLivraison){
  const PU = (typeof PERSO_PRIX_UNIT!=='undefined') ? PERSO_PRIX_UNIT : 0.25;
  const brutLignes = (lignes||[]).reduce((s,ln)=>s+lineTotalBrut(ln),0);
  const persoBrut = money2(Math.max(0,+persoNb||0)*PU);
  const brutAbsolu = money2(brutLignes + persoBrut);
  const rabais = money2(Math.max(0, brutAbsolu - money2(+totalNetHorsLivraison||0)));
  const pct = brutAbsolu>0 ? Math.round(rabais/brutAbsolu*1000)/10 : 0;
  return { brutAbsolu, rabais, pct };
}
// Bloc « règlement » d'une facture : lignes « Déjà réglé / Reste à payer » + mention ACQUITTÉE
// (montant restant 0) quand la facture est intégralement soldée. Sert au rendu ET aux réécritures.
function _factReglSlotHtml(total, paye, date, moyen){
  const t=money2(+total||0), p=money2(+paye||0), reste=Math.max(0, money2(t-p));
  let html = p>0 ? `<div class="lg"><span>Déjà réglé</span><span>\u2212${euro(p)}</span></div><div class="lg"><span><b>Reste à payer</b></span><span><b>${euro(reste)}</b></span></div>` : '';
  if(t>0 && p>0 && reste<=0.009){
    html += `<div class="acquit">\u2714 FACTURE ACQUITTÉE \u2014 Réglée${date?` le ${fmtDate(date)}`:''}${moyen?` par ${esc(moyen)}`:''}. Reste à payer : ${euro(0)}.</div>`;
  }
  return html;
}
// Réécrit le bloc règlement dans un HTML de facture déjà mémorisé (idempotent). Gère le format
// récent (marqueurs <!--REGL-->) et l'ancien (insertion juste après « Total à payer »).
function _factPatchRegl(html, total, paye, date, moyen){
  if(!html) return html;
  const slot = _factReglSlotHtml(total, paye, date, moyen);
  if(html.indexOf('<!--REGL-->')!==-1){
    return html.replace(/<!--REGL-->[\s\S]*?<!--\/REGL-->/, `<!--REGL-->${slot}<!--/REGL-->`);
  }
  let h = html.replace(/<div class="lg"><span>Déjà réglé<\/span>[\s\S]*?<div class="lg"><span><b>Reste à payer<\/b><\/span><span><b>[\s\S]*?<\/div>/, '');
  h = h.replace(/<div class="acquit">[\s\S]*?<\/div>/g, '');
  h = h.replace(/(<div class="lg total"><span>Total à payer<\/span><span>[\s\S]*?<\/div>)/, `$1<!--REGL-->${slot}<!--/REGL-->`);
  return h;
}
function factLineRows(ln, brut){
  // brut=true : affiche le montant AVANT remise de ligne (utilisé par le devis, qui montre
  // le prix brut par ligne puis applique la remise une seule fois sur le total).
  const montantLn = brut ? lineTotalBrut(ln) : lineTotalStored(ln);
  // [REMISE DE LIGNE] Sous-ligne discrète « remise −X € » quand une remise de ligne s'applique.
  // Affichée UNIQUEMENT en mode net (brut=false) : en mode brut, la remise est déjà agrégée
  // dans le total « Réductions accordées » en bas, l'afficher par ligne la compterait deux fois.
  const _remLn = (!brut && typeof lineRemiseEuro==='function') ? money2(lineRemiseEuro(ln)) : 0;
  const remiseSub = _remLn>0
    ? `<tr class="ln-remise"><td class="desc"><span class="ln-sub" style="color:#3f7d52">remise de ligne \u2212${euro(_remLn)}</span></td><td class="mt" style="color:#3f7d52">\u2212${euro(_remLn)}</td></tr>`
    : '';
  if(ln.type==='evenement' && (+ln.equip||0)>0){
    const nbPyr = +ln.equip||0;
    const partPyr = pyraTotalLigne(ln);                        // part pyramides (location ou vente)
    const partAcc = accessoireDecoTotal(ln);                   // [v1246] part accessoire décoratif (location)
    // En cas de remise de ligne (montantLn < brut), les parts pyramide et accessoire doivent suivre la
    // même proportion pour garantir l'égalité des <tr> avec le sous-total. On recalcule au prorata si besoin.
    const brutLn = lineTotalBrut(ln);
    const prorata = (brutLn>0 && montantLn!==brutLn) ? (montantLn/brutLn) : 1;
    const partPyrAff = money2(partPyr*prorata);
    const partAccAff = money2(partAcc*prorata);
    const partMaca = money2(montantLn - partPyrAff - partAccAff);  // reste = part macarons (garantit l'égalité)
    const rowMaca = `<tr><td class="desc">${factLineDescHtml(ln)}</td><td class="mt">${euro(partMaca)}</td></tr>`;
    let descPyr;
    if(pyraEstVente(ln)){
      // [v1079] pyramide VENDUE → marchandise, libellé de vente, pas de mention de retour.
      descPyr = `<span class="ln-main">Vente — pyramide / présentoir</span>`+
                `<span class="ln-sub">${nbPyr} pyramide${nbPyr>1?'s':''} × ${euro(pyraPrixUnit(ln))}</span>`;
    } else {
      descPyr = `<span class="ln-main">Prestation de service — location de pyramide</span>`+
                `<span class="ln-sub">${nbPyr} pyramide${nbPyr>1?'s':''} × ${euro(EQUIP_PRICE)}</span>`+
                `<span class="ln-loc">à retourner dans un délai de 48h après l'événement</span>`;
    }
    const rowPyr = `<tr><td class="desc">${descPyr}</td><td class="mt">${euro(partPyrAff)}</td></tr>`;
    // [v1246] Ligne SÉPARÉE « Accessoire décoratif » (ruban + déco LOVE), uniquement si l'option est active.
    let rowAcc = '';
    if(accessoireDecoActif(ln)){
      const descAcc = `<span class="ln-main">Prestation de service — accessoire décoratif</span>`+
                      `<span class="ln-sub">ruban + déco LOVE · ${nbPyr} pyramide${nbPyr>1?'s':''} × ${euro(ACCESS_DECO_PRICE)}</span>`+
                      `<span class="ln-loc">à retourner dans les 48h après votre événement</span>`;
      rowAcc = `<tr><td class="desc">${descAcc}</td><td class="mt">${euro(partAccAff)}</td></tr>`;
    }
    return rowMaca + rowPyr + rowAcc + remiseSub;
  }
  // Si remise de ligne affichée (mode net) : ligne principale au BRUT, puis sous-ligne « remise −X € ».
  const mtPrincipal = _remLn>0 ? lineTotalBrut(ln) : montantLn;
  return `<tr><td class="desc">${factLineDescHtml(ln)}</td><td class="mt">${euro(mtPrincipal)}</td></tr>${remiseSub}`;
}
// Bloc « Coordonnées bancaires » pour le pied de page des documents (devis + facture).
// Renvoie '' si l'émetteur n'a pas renseigné d'IBAN, sinon un bloc HTML échappé multi-lignes.
function factRibBloc(e, compact){
  const raw = (e && e.iban) ? String(e.iban).trim() : '';
  if(!raw) return '';
  let parts = raw.split(/\r?\n/).map(l=>l.trim()).filter(Boolean);
  // En mode compact : regroupe IBAN et BIC sur une seule ligne (gain de hauteur).
  // Sinon : on laisse chaque ligne telle quelle (IBAN et BIC sur des lignes distinctes).
  if(compact){
    const idxIban = parts.findIndex(l=>/^iban/i.test(l));
    const idxBic  = parts.findIndex(l=>/^bic/i.test(l));
    if(idxIban!==-1 && idxBic!==-1){
      parts[idxIban] = parts[idxIban] + '   ·   ' + parts[idxBic];
      parts.splice(idxBic, 1);
    }
  }
  const lignes = parts.map(l=>esc(l)).join('<br>');
  if(compact){
    // Lecture horizontale : titre et coordonnées sur la même ligne.
    return `<div class="rib rib-inline"><span class="rib-titre">Coordonnées bancaires</span> ${lignes}</div>`;
  }
  return `<div class="rib"><span class="rib-titre">Coordonnées bancaires</span><br>${lignes}</div>`;
}
// Bloc « avis Google » : invitation discrète à laisser un commentaire, avec le QR code
// (généré en amont en data-URI, scannable, logo central). S'affiche sous le RIB.
function factAvisBloc(){
  // Disposition « bandeau » : QR à gauche, invitation à droite (compact, intégré sous le RIB).
  return `<div class="avis-bloc avis-h">`
    + `<img class="avis-qr" src="${FACT_GOOGLE_QR}" alt="Avis Google">`
    + `<div class="avis-side">`
    +   `<div class="avis-txt">Les géants ont la pub.<br>Nous, on a vos avis \uD83E\uDD0D</div>`
    +   `<div class="avis-sub">Scannez pour partager votre expérience sur Google</div>`
    + `</div>`
    + `</div>`;
}
// Bloc « bas de document » unifié : Coordonnées bancaires (pleine largeur) puis QR avis
// juste en dessous, le tout solidaire (jamais coupé entre deux pages).
function factRibAvisCol(e){
  // RIB en mode compact (IBAN/BIC sur une ligne) + QR avis, côte à côte sur deux
  // demi-colonnes, dans le prolongement direct de l'encadré d'acompte.
  const rib = factRibBloc(e, true);
  return `<div class="rib-avis-col rib-avis-row">`
    + `<div class="rib-avis-half">${rib}</div>`
    + `<div class="rib-avis-half">${factAvisBloc()}</div>`
    + `</div>`;
}
// === DEVIS : aperçu / impression (→ « Enregistrer en PDF » sur iOS) + envoi par mail ===
// Génère le HTML d'un devis (registre documents, type:'devis') avec le même rendu
// élégant que la facture, puis l'ouvre dans la couche d'impression avec un bouton
// « Envoyer par mail » (mailto pré-rempli vers le client).
// [v1268] Badge « date de l'événement » pour devis/facture.
// `dateEvenement` = date de LIVRAISON (pilote la fabrication). `dateEvtReel` = jour réel de la
// prestation (mariage, réception…). On n'affiche l'événement que s'il est renseigné ET différent
// de la livraison — cas typique d'une livraison la veille. Les deux dates sont comparées sur
// leur partie AAAA-MM-JJ pour ignorer une éventuelle composante horaire.
function cmdEventBadge(o){
  const liv = (o.dateEvenement||'').slice(0,10);
  const evt = (o.dateEvtReel||'').slice(0,10);
  if(!evt || evt===liv) return '';
  return `<span class="cmd-event">📅 Événement : ${fmtDate(evt)}</span>`;
}
async function genererDevisDoc(docId){
  const d = await db.documents.get(docId);
  if(!d || d.type!=='devis'){ toast('Devis introuvable'); return; }
  const e = factGetEmetteur();
  if(!e.nom || !e.siret || !e.adresse){
    toast('Renseigne d\'abord tes coordonnées de facturation');
    factEmetteurForm(0);
    return;
  }
  const client = d.clientId ? await db.clients.get(d.clientId).catch(()=>null) : null;
  const lignes = d.lignes || [];
  const persoMt = persoMontant(d.persoMacarons, d.persoRemiseEur);   // montant NET de la personnalisation
  const gpct = Math.max(0, Math.min(100, +d.remiseGlobale||0));
  // Total = montant stocké du devis si dispo (déjà net, perso incluse, remise appliquée).
  // Sous-total = lignes NETTES (remises de ligne déjà déduites, affichées par ligne) + perso.
  // La remise GLOBALE (gpct) s'applique une fois sur ce sous-total, séparément.
  const totalBrut = money2(lignes.reduce((s,ln)=>s+lineTotalStored(ln),0) + persoMt);
  const total = (d.montant!=null) ? +d.montant : money2(totalBrut - money2(totalBrut*gpct/100));
  const reductions = money2(Math.max(0, totalBrut - total));
  // Pourcentage de remise à afficher : le % global saisi si présent, sinon le % effectif.
  const reducPct = gpct>0 ? gpct : (totalBrut>0 ? Math.round(reductions/totalBrut*1000)/10 : 0);

  const rows = lignes.map(ln=>factLineRows(ln, false)).join('') + cautionRowHtml(lignes);   // false = prix NET par ligne (remise de ligne montrée sous la ligne)
  const section = `
      <div class="cmd-section">
        <div class="cmd-head">
          <span class="cmd-ref">Devis ${esc(d.numero||'')}${cmdEventBadge(d)}</span>
          <span class="cmd-date">${fmtDate(d.date)||''}</span>
        </div>
        <div class="cmd-body">
        <table class="cmd-table">
          <tbody>
            ${rows||'<tr><td>—</td><td class="mt"></td></tr>'}
            ${factPersoLigne(d.persoMacarons, d.persoRemiseEur)}
          </tbody>
        </table>
        ${factPersoBox(d.persoMacarons, d.persoCouleurs)}
        </div>
      </div>`;

  const clientBloc = client
    ? `${esc([client.civilite,client.prenom,client.nom].filter(Boolean).join(' ')||client.nom||'')}${client.societe?'<br>'+esc(client.societe):''}${client.adresse?'<br>'+esc(client.adresse):''}${client.tel?'<br>Tél : '+esc(client.tel):''}${client.email?'<br>'+esc(client.email):''}`
    : 'Client de passage';

  // « Valable jusqu'au » : à partir de l'expiration stockée si présente
  const validiteHtml = d.expiration ? `Valable jusqu'au : <b>${fmtDate(d.expiration)}</b><br>` : '';

  const devisHtml = `<!doctype html><html lang="fr"><head><meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <meta name="format-detection" content="telephone=no, date=no, email=no, address=no">
   <title>Devis ${esc(d.numero||'')}</title>
   ${FACT_STYLE}</head><body>
   <div class="barre noprint"><button onclick="window.print()">🖨 Imprimer / Enregistrer en PDF</button></div>
   <div class="page">
     <div class="entete">
       <img class="logo" src="${FACT_LOGO}" alt="logo">
       <div class="em">
         ${[
           e.exploitant?esc(e.exploitant):'',
           e.adresse?esc(e.adresse):'',
           e.cpville?esc(e.cpville):'',
           e.tel?'Tél. '+esc(e.tel):'',
           e.email?esc(e.email):'',
           e.siret?'SIRET '+esc(e.siret):''
         ].filter(Boolean).map(l=>`<div class="em-l">${l}</div>`).join('')}
       </div>
     </div>
     <div class="corps">
       <div class="ftitre">Devis</div>
       <div class="ftitre-rule"></div>
       <div class="meta">
         <div class="bloc"><div class="lbl">Adressé à</div>${clientBloc}</div>
         <div class="bloc" style="text-align:right">
           <div class="lbl">Détails</div>
           Devis n° : <b>${esc(d.numero||'')}</b><br>
           Date : ${fmtDate(d.date)||fmtDate(today())}<br>
           ${validiteHtml}
         </div>
       </div>
       <div class="meta-rule"></div>
       ${section}
       <div class="grand">
         ${reductions>0?`<div class="lg brut"><span>Total avant réductions</span><span>${euro(totalBrut)}</span></div><div class="lg reduc"><span>Réductions accordées${reducPct>0?` (−${reducPct}%)`:''}</span><span>\u2212${euro(reductions)}</span></div>`:''}
         <div class="lg total"><span>Total du devis</span><span>${euro(total)}</span></div>
         ${(()=>{ const R=docRabaisTotal(lignes, d.persoMacarons, total); return R.rabais>0?`<div class="lg reduc" style="color:#3f7d52;font-size:.9rem"><span>Rabais total consenti${R.pct>0?` (−${R.pct}%)`:''}</span><span>\u2212${euro(R.rabais)}</span></div>`:''; })()}
       </div>
       ${d.acompteMention!==false?`<div class="acompte-mention">⚠ Le versement d'un acompte de 75% (soit ${euro(money2(total*0.75))}) est requis pour valider votre devis.</div>`:''}
       <div class="bas-final">
         ${factRibAvisCol(e)}
         <div class="legal-bloc">
           <div class="tva">TVA non applicable, article 293 B du Code général des impôts.</div>
           <div class="paiement">Devis valable ${d.validiteJours||30} jours à compter de la date d'émission.<br>Bon pour accord — date et signature :</div>
           ${factMentionMediateur(e)}
         </div>
       </div>
       <div class="pied">${esc(e.nom||'')}${e.siret?' · SIRET '+esc(e.siret):''} · Micro-entreprise · Merci de votre confiance 🍬</div>
     </div>
   </div>
   </body></html>`;

  // Bouton « Envoyer par mail » dans la barre d'aperçu (mailto pré-rempli)
  let extraBtns = '';
  const emailCible = client && client.email ? client.email : '';
  const objet = `Devis ${d.numero||''} — ${e.nom||'Sensations Macarons'}`;
  const nomClient = client ? ((client.prenomMail&&client.prenomMail.trim()) ? client.prenomMail.trim() : ((client.politesse==='tu') ? (client.prenom||client.nom||'') : [client.prenom, client.nom].filter(Boolean).join(' '))) : '';
  const montantFmt = money2(total).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2});
  const acompteFmt = money2(total*0.75).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2});
  const signature = [e.exploitant, e.nom].filter(Boolean).join(' — ') || (e.nom||'Sensations Macarons');
  const _tu = client && client.politesse === 'tu';
  const corps = [
    `Bonjour${nomClient ? ' '+nomClient : ''},`,
    '',
    `${_tu?'Tu trouveras':'Veuillez trouver'} ci-dessous ${_tu?'ton':'votre'} devis n° ${d.numero||''} d'un montant de ${montantFmt} €.`,
    ...(d.acompteMention!==false ? [ _tu
        ? `Ta commande sera considérée comme validée une fois ton acompte de ${acompteFmt} € versé (75% du montant total).`
        : `Votre commande sera considérée comme validée une fois votre acompte de ${acompteFmt} € versé (75% du montant total).` ] : []),
    '',
    _tu ? 'En te remerciant par avance.' : 'Vous remerciant par avance.',
    '',
    'Bien cordialement,',
    signature
  ].filter(l=>l!==null && l!==undefined).join('\n');
  const mailto = `mailto:${encodeURIComponent(emailCible)}?subject=${encodeURIComponent(objet)}&body=${encodeURIComponent(corps)}`;
  // [v1084] Données STRUCTURÉES du devis pour le PDF dessiné au canvas (fiable iOS, contrairement
  // à la rasterisation HTML). On reconstruit chaque ligne en {desc, montant} depuis les données brutes.
  const emetteurLignes = [
    e.exploitant||'', e.adresse||'', e.cpville||'',
    e.siret?('SIRET '+e.siret):'', e.tel?('Tél : '+e.tel):'', e.email||''
  ].filter(Boolean);
  const clientLignes = client
    ? [ [client.civilite,client.prenom,client.nom].filter(Boolean).join(' ')||client.nom||'',
        client.societe||'', client.adresse||'', client.tel?('Tél : '+client.tel):'', client.email||'' ].filter(Boolean)
    : ['Client de passage'];
  const docLignes = lignes.map(ln=>({ desc:factLineDesc(ln), montant:lineTotalBrut(ln) }));
  if(persoMt>0) docLignes.push({ desc:'Personnalisation', montant:persoMt });
  const _evtBadgeTxt = (function(){ const liv=(d.dateEvenement||'').slice(0,10), ev=(d.dateEvtReel||'').slice(0,10); return (ev && ev!==liv) ? fmtDate(ev) : ''; })();
  const docData = {
    titre:'DEVIS', ref:`${d.numero||''}`, date:fmtDate(d.date)||'',
    ...(_evtBadgeTxt?{evenement:_evtBadgeTxt}:{}),
    validite: d.expiration?fmtDate(d.expiration):(d.validiteJours?`${d.validiteJours} j après émission`:''),
    emetteur:{ nom:e.nom||'Sensations Macarons', lignes:emetteurLignes },
    client: clientLignes,
    lignes: docLignes,
    sousTotal: totalBrut, remisePct: reducPct, remise: reductions, total: total,
    mentions:[
      ...(d.acompteMention!==false ? [`Le versement d'un acompte de 75% (soit ${euro(money2(total*0.75))}) est requis pour valider ce devis.`] : []),
      'TVA non applicable, article 293 B du Code général des impôts.',
      `Devis valable ${d.validiteJours||30} jours à compter de la date d'émission. Bon pour accord — date et signature :`
    ],
    pied:`${e.nom||''}${e.siret?' · SIRET '+e.siret:''} · Micro-entreprise`
  };
  // [v1302] Code mort neutralisé : _lastDocHtml / _lastDocData étaient prévues pour un « PDF canvas »
  // ([v1084]) qui ne les lit plus (seule _lastDocMeta ci-dessous est vivante — utilisée par le mailto).
  // window._lastDocHtml = devisHtml;
  // window._lastDocData = docData;
  window._lastDocMeta = { fileName:`Devis ${d.numero||''}`, objet, corps, mailto };
  const btnMailto  = `<a class="pv-btn" href="${mailto}" title="Ouvre l'appli mail avec le message pré-rempli">✉️ Envoyer par mail</a>`;
  extraBtns = btnMailto;

  openPrintView(devisHtml, { title:`Devis ${d.numero||''}`, extraButtons: extraBtns });
}

// [v1086] Génère le PDF du dernier document affiché (le VRAI devis/facture HTML) et le partage.
// Le PDF « dessiné au canvas » a été retiré : il changeait la mise en page du devis. On rasterise
// donc le HTML réel (rendu fidèle), avec un délai de sécurité contre tout blocage iOS.

// [v1081] Mémorise le document courant pour l'envoi PDF, avec un objet = libellé (n° facture/devis).
function _prepDocPdfMail(html, libelle, client, montant, opts){
  opts = opts || {};
  const nomClient = client ? ((client.prenomMail&&client.prenomMail.trim()) ? client.prenomMail.trim() : ((client.politesse==='tu') ? (client.prenom||client.nom||'') : [client.prenom, client.nom].filter(Boolean).join(' '))) : '';
  const estFacture = /facture/i.test(libelle);
  const e = (typeof factGetEmetteur==='function') ? factGetEmetteur() : {};
  // Tutoiement si le client le demande, vouvoiement par défaut.
  const tu = client && client.politesse === 'tu';
  // Mention d'acompte sur le devis : reprise du réglage de la commande (true par défaut).
  const acompteMention = opts.acompteMention !== false;
  // Numéro seul (sans le préfixe « Facture »/« Devis ») pour l'objet et le corps.
  const numero = libelle.replace(/^(Facture|Devis)\s*/i,'').trim();
  // Acompte formaté (75% du montant) pour le message devis, si disponible.
  const acompteFmt = (montant!=null && !isNaN(montant))
    ? Number(montant*0.75).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})
    : '';
  // Montant formaté « 1 234,56 » (comme le message du devis). Vide si non fourni.
  const montantFmt = (montant!=null && !isNaN(montant))
    ? Number(montant).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})
    : '';
  // Signature COURTE, identique au message du devis : « {exploitant} — {enseigne} ».
  const signature = [e.exploitant, (e.nom||'Sensations Macarons')].filter(Boolean).join(' — ') || (e.nom||'Sensations Macarons');
  const objet = `${estFacture?'Facture':'Devis'} ${numero} — ${e.nom||'Sensations Macarons'}`;
  // Phrases conjuguées selon tutoiement/vouvoiement.
  const phraseAcompte = tu
    ? `Ta commande sera considérée comme validée une fois ton acompte de ${acompteFmt} € versé (75% du montant total).`
    : `Votre commande sera considérée comme validée une fois votre acompte de ${acompteFmt} € versé (75% du montant total).`;
  const corps = [
    `Bonjour${nomClient ? ' '+nomClient : ''},`, '',
    estFacture
      // Message facture = calque du devis (montant, sans mention d'acompte).
      ? `${tu?'Tu trouveras':'Veuillez trouver'} ci-dessous ${tu?'ta':'votre'} facture n° ${numero}${montantFmt?` d'un montant de ${montantFmt} €`:''}.`.replace(/\s+\./,'.')
      : `${tu?'Tu trouveras':'Veuillez trouver'} ci-dessous ${tu?'ton':'votre'} devis n° ${numero}${montantFmt?` d'un montant de ${montantFmt} €`:''}.`.replace(/\s+\./,'.'),
    // Devis : mention d'acompte seulement si la case n'a pas été décochée ET qu'on a le montant.
    ...(!estFacture && acompteMention && acompteFmt ? [phraseAcompte] : []),
    '',
    tu ? 'En te remerciant par avance.' : 'Vous remerciant par avance.',
    '',
    'Bien cordialement,',
    signature
  ].join('\n');
  // [v1302] Code mort neutralisé (voir plus haut) : seule _lastDocMeta est réellement lue.
  // window._lastDocHtml = html;
  // window._lastDocData = null;
  window._lastDocMeta = { fileName:libelle, objet, corps,
    mailto:`mailto:${client&&client.email?encodeURIComponent(client.email):''}?subject=${encodeURIComponent(objet)}&body=${encodeURIComponent(corps)}` };
}

// Boutons de la barre d'aperçu : envoi PDF (objet maîtrisé) + mail seul (repli).
function _docMailBtns(){
  const m = window._lastDocMeta||{};
  // Envoi PDF automatique retiré : non fiable sur iOS/Safari (canvas tainted → SecurityError).
  // On propose l'ouverture directe du mail (message + signature) ; le PDF se joint via le bouton
  // d'impression natif « Enregistrer en PDF » déjà présent dans cette barre d'aperçu.
  const btnMail = m.mailto ? `<a class="pv-btn" href="${m.mailto}" title="Ouvre l'appli mail avec le message pré-rempli">✉️ Envoyer par mail</a>` : '';
  return btnMail;
}

// Génère et imprime la facture d'une commande (→ « Enregistrer en PDF » sur iOS).
async function genererFacture(orderId){
  // Une facture d'une seule commande utilise désormais le même rendu élégant
  // « en sections » que la facture multi-commandes (style unifié).
  return genererFactureMultiple([orderId]);
}

// [v1088] Mentions légales de paiement obligatoires entre professionnels (Art. L441-10 C. com.).
// Affichées sur TOUTES les factures (décision Benjamin : le plus simple et conforme, l'activité
// étant mixte particuliers/pros). Le taux d'intérêt légal change chaque semestre par arrêté : on
// cite donc la RÈGLE (« 3 fois le taux d'intérêt légal ») sans figer un nombre qui serait vite faux.
function factMentionsRetardB2B(){
  return `<div class="retard">`
    + `En cas de retard de paiement : pénalités au taux de 3 fois le taux d'intérêt légal en vigueur, `
    + `exigibles sans rappel, et indemnité forfaitaire pour frais de recouvrement de 40 €. `
    + `Escompte pour paiement anticipé : néant.`
    + `</div>`;
}

// [v1088] Mention du médiateur de la consommation (Code conso. L.616-1 / R.616-1), obligatoire pour
// les ventes aux particuliers. Ne s'affiche QUE si l'émetteur a renseigné un médiateur (nom + URL),
// car on ne peut pas inventer ces coordonnées sur un document légal : Benjamin doit d'abord adhérer
// à un médiateur agréé, puis saisir nom + site dans ses coordonnées de facturation.
function factMentionMediateur(e){
  const nom=(e&&e.mediateurNom||'').trim();
  const url=(e&&e.mediateurUrl||'').trim();
  if(!nom && !url) return '';
  const detail=[nom, url].filter(Boolean).join(' — ');
  return `<div class="mediateur">Conformément aux articles L.616-1 et R.616-1 du Code de la consommation, en cas de litige le client peut saisir gratuitement le médiateur de la consommation dont relève l'entreprise : ${esc(detail)}.</div>`;
}

// Facture regroupant PLUSIEURS commandes (sélection multiple).
// Chaque commande apparaît avec : sa référence, sa date, le détail de ses lignes,
// ses remises éventuelles et ses frais de livraison s'il y en a. Puis un total général.
// [RÉGÉNÉRATION FACTURE FIGÉE] Contexte optionnel : quand il est posé, genererFactureMultiple
// NE stocke PAS de brouillon et N'affiche RIEN — il renvoie le HTML construit (avec le numéro et
// la date FIGÉS fournis) dans ce contexte, pour une réécriture contrôlée de présentation seulement.
let _factRegenCtx = null;
// ============================================================
//  [v1284] DEVIS GROUPÉ — récapitule plusieurs devis et/ou commandes existantes dans un
//  seul document non engageant (section détaillée par source, total groupé). Pendant naturel
//  de genererFactureMultiple (facture groupée), en amont du cycle devis→commande→facture.
// ============================================================
let _devisGroupeCtx = null;
async function devisGroupeStart(devisIds){
  _devisGroupeCtx = { devisIds: (devisIds||[]).filter(Boolean), orderIds: [] };
  await devisGroupeRender();
}
async function devisGroupeRender(){
  const ctx = _devisGroupeCtx; if(!ctx) return;
  const devisAll = (await db.documents.where('type').equals('devis').toArray().catch(()=>[]))
    .filter(d=>d.statut==='en_attente');
  const clients = await db.clients.toArray().catch(()=>[]);
  const clName = id => (clients.find(c=>c.id===id)||{}).nom || '—';

  const devisRows = devisAll.map(d=>`
    <label class="sum-box" style="cursor:pointer;align-items:center">
      <input type="checkbox" ${ctx.devisIds.includes(d.id)?'checked':''} onchange="devisGroupeToggleDevis(${d.id},this.checked)" style="width:18px;height:18px;margin-right:8px">
      <span style="flex:1">${esc(d.numero||'Brouillon')} · ${esc(clName(d.clientId))}</span>
      <b>${euro(d.montant||0)}</b></label>`).join('');

  const ordersSel = [];
  for(const oid of ctx.orderIds){ const o=await db.orders.get(oid).catch(()=>null); if(o) ordersSel.push(o); }
  const ordersRows = ordersSel.map(o=>`
    <div class="sum-box" style="align-items:center">
      <span style="flex:1">${esc(orderNumber(o))} · ${esc(clName(o.clientId))}</span>
      <b>${euro(o.montant||0)}</b>
      <span class="act del" style="margin-left:8px" onclick="devisGroupeRemoveOrder(${o.id})">✕</span></div>`).join('');

  const total = money2(devisAll.filter(d=>ctx.devisIds.includes(d.id)).reduce((s,d)=>s+(+d.montant||0),0)
    + ordersSel.reduce((s,o)=>s+(+o.montant||0),0));
  const nb = ctx.devisIds.length + ordersSel.length;

  openModal(`<h3>📋 Devis groupé</h3>
    <p class="note">Sélectionne les devis et/ou commandes à récapituler dans un seul document non engageant. Chaque source garde son détail ; un total groupé s'affiche à la fin.</p>
    ${devisAll.length?`<p class="note" style="margin:8px 0 4px"><b>Devis existants</b></p>${devisRows}`:''}
    <p class="note" style="margin:10px 0 4px"><b>Commandes existantes</b> <span class="act" onclick="devisGroupeAddOrderPrompt()">+ ajouter ›</span></p>
    ${ordersRows||'<p class="note" style="color:#9a8a82">Aucune commande ajoutée.</p>'}
    <div class="sum-box" style="margin-top:10px;border-top:2px solid var(--bordeaux)"><span><b>${nb} élément(s) — total groupé</b></span><b style="color:var(--bordeaux)">${euro(total)}</b></div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" ${nb<1?'disabled':''} onclick="devisGroupeGenerate()">Générer le devis groupé</button></div>`);
}
function devisGroupeToggleDevis(id, on){
  const ctx=_devisGroupeCtx; if(!ctx) return;
  if(on){ if(!ctx.devisIds.includes(id)) ctx.devisIds.push(id); } else { ctx.devisIds=ctx.devisIds.filter(x=>x!==id); }
  devisGroupeRender();
}
function devisGroupeRemoveOrder(id){
  const ctx=_devisGroupeCtx; if(!ctx) return;
  ctx.orderIds = ctx.orderIds.filter(x=>x!==id);
  devisGroupeRender();
}
async function devisGroupeAddOrderPrompt(){
  const ctx=_devisGroupeCtx; if(!ctx) return;
  const orders = (await db.orders.toArray().catch(()=>[])).filter(o=>!estReprise(o) && !ctx.orderIds.includes(o.id));
  const clients = await db.clients.toArray().catch(()=>[]);
  const clName = id => (clients.find(c=>c.id===id)||{}).nom || '—';
  orders.sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  const rows = orders.slice(0,60).map(o=>`
    <div class="sum-box lnk" onclick="devisGroupeAddOrder(${o.id})">
      <span>${esc(orderNumber(o))} · ${esc(clName(o.clientId))} · ${fmtDate(o.date)}</span>
      <b>${euro(o.montant||0)}</b></div>`).join('');
  openModal(`<h3>Ajouter une commande</h3>
    ${rows||'<p class="note">Aucune commande disponible.</p>'}
    <div class="modal-actions"><button class="btn ghost" onclick="devisGroupeRender()">‹ Retour</button></div>`);
}
function devisGroupeAddOrder(orderId){
  const ctx=_devisGroupeCtx; if(!ctx) return;
  if(!ctx.orderIds.includes(orderId)) ctx.orderIds.push(orderId);
  devisGroupeRender();
}
async function devisGroupeGenerate(){
  const ctx=_devisGroupeCtx; if(!ctx) return;
  const e = factGetEmetteur();
  if(!e.nom || !e.siret || !e.adresse){ toast('Renseigne d\'abord tes coordonnées de facturation'); factEmetteurForm(0); return; }

  const devisSel = []; for(const id of ctx.devisIds){ const d=await db.documents.get(id).catch(()=>null); if(d) devisSel.push(d); }
  const ordersSel = []; for(const id of ctx.orderIds){ const o=await db.orders.get(id).catch(()=>null); if(o) ordersSel.push(o); }
  if(!devisSel.length && !ordersSel.length){ toast('Aucun élément sélectionné'); return; }

  const clients = await db.clients.toArray().catch(()=>[]);
  const clientIds = [...new Set([...devisSel.map(d=>d.clientId||0), ...ordersSel.map(o=>o.clientId||0)])];
  const client = (clientIds.length===1 && clientIds[0]) ? clients.find(c=>c.id===clientIds[0]) : null;

  let grandTotal = 0;
  // Sections DEVIS (prix NET par ligne — même présentation qu'un devis individuel)
  const sectionsDevis = devisSel.map(d=>{
    const lignes = d.lignes||[];
    const total = (d.montant!=null) ? +d.montant : money2(lignes.reduce((s,ln)=>s+lineTotalStored(ln),0));
    grandTotal += total;
    const rows = lignes.map(ln=>factLineRows(ln, false)).join('') + cautionRowHtml(lignes);
    return `<div class="cmd-section">
      <div class="cmd-head"><span class="cmd-ref">Devis ${esc(d.numero||'brouillon')}${cmdEventBadge(d)}</span><span class="cmd-date">${fmtDate(d.date)||''}</span></div>
      <div class="cmd-body"><table class="cmd-table"><tbody>
        ${rows||'<tr><td>—</td><td class="mt"></td></tr>'}
        ${factPersoLigne(d.persoMacarons, d.persoRemiseEur)}
        <tr class="cmd-total"><td>Total devis ${esc(d.numero||'')}</td><td class="mt">${euro(total)}</td></tr>
      </tbody></table>${factPersoBox(d.persoMacarons, d.persoCouleurs)}</div></div>`;
  }).join('');
  // Sections COMMANDES (même présentation que la facture groupée, prix BRUT + réductions récapitulées)
  const sectionsOrders = ordersSel.map(o=>{
    const lignes = orderToLines(o);
    const persoMt = persoMontant(o.persoMacarons, o.persoRemiseEur);
    const gpct = Math.max(0, Math.min(100, +o.remiseGlobale||0));
    const frais = +o.fraisLivraison||0;
    const brutCmd = money2(lignes.reduce((s,ln)=>s+lineTotalStored(ln),0) + persoMt);
    const totalCmd = (o.montant!=null) ? +o.montant : money2(brutCmd - money2(brutCmd*gpct/100) + frais);
    grandTotal += totalCmd;
    const R = docRabaisTotal(lignes, o.persoMacarons, money2(totalCmd - frais));
    const rows = lignes.map(ln=>factLineRows(ln, true)).join('') + cautionRowHtml(lignes);
    return `<div class="cmd-section">
      <div class="cmd-head"><span class="cmd-ref">Commande ${esc(orderNumber(o))}${cmdEventBadge(o)}</span><span class="cmd-date">${fmtDate(o.date)||''}</span></div>
      <div class="cmd-body"><table class="cmd-table"><tbody>
        ${rows||'<tr><td>—</td><td class="mt"></td></tr>'}
        ${factPersoLigne(o.persoMacarons, o.persoRemiseEur, true)}
        ${R.rabais>0?`<tr class="tc-brut"><td>Total commande sans réduction</td><td class="mt">${euro(R.brutAbsolu)}</td></tr><tr class="tc-remise"><td>Total des remises${R.pct>0?` (−${R.pct}%)`:''}</td><td class="mt">−${euro(R.rabais)}</td></tr>`:''}
        ${frais>0?`<tr class="liv"><td>Frais de livraison</td><td class="mt">${euro(frais)}</td></tr>`:''}
        <tr class="cmd-total"><td>Total commande ${esc(orderNumber(o))}</td><td class="mt">${euro(totalCmd)}</td></tr>
      </tbody></table>${factPersoBox(o.persoMacarons, o.persoCouleurs)}</div></div>`;
  }).join('');

  const clientBloc = client
    ? `${esc([client.civilite,client.prenom,client.nom].filter(Boolean).join(' ')||client.nom||'')}${client.societe?'<br>'+esc(client.societe):''}${client.adresse?'<br>'+esc(client.adresse):''}${client.tel?'<br>Tél : '+esc(client.tel):''}${client.email?'<br>'+esc(client.email):''}`
    : (clientIds.length>1 ? 'Clients multiples' : 'Client de passage');

  // Numéro : un devis groupé n'entre PAS dans la séquence légale des factures (document non
  // engageant, pas de contrainte de continuité numérique) — référence interne horodatée.
  const refInterne = 'DEVIS-GRP-'+today().replace(/-/g,'')+'-'+Date.now().toString().slice(-4);
  const nbElements = devisSel.length + ordersSel.length;

  const devisGroupeHtml = `<!doctype html><html lang="fr"><head><meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <meta name="format-detection" content="telephone=no, date=no, email=no, address=no">
   <title>Devis groupé</title>
   ${FACT_STYLE}</head><body>
   <div class="barre noprint"><button onclick="window.print()">🖨 Imprimer / Enregistrer en PDF</button></div>
   <div class="page">
     <div class="entete">
       <img class="logo" src="${FACT_LOGO}" alt="logo">
       <div class="em">
         ${[e.exploitant?esc(e.exploitant):'', e.adresse?esc(e.adresse):'', e.cpville?esc(e.cpville):'', e.tel?'Tél. '+esc(e.tel):'', e.email?esc(e.email):'', e.siret?'SIRET '+esc(e.siret):'']
           .filter(Boolean).map(l=>`<div class="em-l">${l}</div>`).join('')}
       </div>
     </div>
     <div class="corps">
       <div class="ftitre">Devis groupé</div>
       <div class="ftitre-rule"></div>
       <div class="meta">
         <div class="bloc"><div class="lbl">Destinataire</div>${clientBloc}</div>
         <div class="bloc" style="text-align:right">
           <div class="lbl">Détails</div>
           Référence : <b>${esc(refInterne)}</b><br>
           Date d'émission : ${fmtDate(today())}<br>
           ${nbElements} élément(s) regroupé(s)
         </div>
       </div>
       <div class="meta-rule"></div>
       ${sectionsDevis}${sectionsOrders}
       <div class="grand">
         <div class="lg total"><span>Total groupé (indicatif)</span><span>${euro(grandTotal)}</span></div>
       </div>
       <div class="bas-final">
         ${factRibAvisCol(e)}
         <div class="legal-bloc">
           <div class="tva">TVA non applicable, article 293 B du Code général des impôts.</div>
           <p class="note" style="margin-top:8px;font-size:.76rem;color:#8a7a70">Document récapitulatif non engageant, sans valeur de facture. Chaque élément conserve son statut propre (devis en attente ou commande en cours) jusqu'à conversion/facturation individuelle.</p>
         </div>
       </div>
     </div>
   </div></body></html>`;

  const win = window.open('', '_blank');
  if(!win){ toast('Autorise les fenêtres pour générer le document'); return; }
  win.document.write(devisGroupeHtml); win.document.close();
  closeModal();
  _docSel.clear(); docUpdateSelBar();
  toast('✓ Devis groupé généré');
}

async function genererFactureMultiple(ids){
  ids = (ids||[]).filter(Boolean);
  if(!ids.length){ toast('Sélectionne au moins une commande'); return; }
  const e = factGetEmetteur();
  if(!e.nom || !e.siret || !e.adresse){
    toast('Renseigne d\'abord tes coordonnées de facturation');
    factEmetteurForm(0);
    return;
  }
  // Charge les commandes
  const orders = [];
  for(const id of ids){ const o=await db.orders.get(id); if(o) orders.push(o); }
  if(!orders.length){ toast('Commandes introuvables'); return; }
  // Tri par date puis par numéro
  orders.sort((a,b)=> (a.date||'').localeCompare(b.date||'') || (a.id-b.id));
  // Vérifie qu'elles concernent le même client (sinon on prévient mais on continue)
  const clientIds = [...new Set(orders.map(o=>o.clientId||0))];
  let client = null;
  if(clientIds.length===1 && clientIds[0]){ client = await db.clients.get(clientIds[0]); }

  let grandTotal = 0, grandBrut = 0, grandNetHorsLiv = 0, grandBrutAbsolu = 0, grandRabais = 0, grandFrais = 0;
  // Construit une section par commande
  const sections = orders.map(o=>{
    const lignes = orderToLines(o);
    const persoMt = persoMontant(o.persoMacarons, o.persoRemiseEur);            // montant NET personnalisation
    const gpct = Math.max(0, Math.min(100, +o.remiseGlobale||0));
    const frais = +o.fraisLivraison||0;
    // Sous-total = lignes NETTES (remises de ligne déjà déduites et affichées par ligne) + perso.
    // La remise GLOBALE s'applique une fois sur ce sous-total.
    const brutCmd = money2(lignes.reduce((s,ln)=>s+lineTotalStored(ln),0) + persoMt);
    // total commande = montant stocké (déjà net, perso + remise incluses, livraison en sus) si dispo.
    const totalCmd = (o.montant!=null) ? +o.montant : money2(brutCmd - money2(brutCmd*gpct/100) + frais);
    // Réduction = sous-total net − (total − frais) = remise GLOBALE seule. Le % affiché : global saisi, sinon effectif.
    const reducCmd = money2(Math.max(0, brutCmd - money2(totalCmd - frais)));
    const reducPct = gpct>0 ? gpct : (brutCmd>0 ? Math.round(reducCmd/brutCmd*1000)/10 : 0);
    grandTotal += totalCmd;
    grandBrut += brutCmd;
    grandNetHorsLiv += money2(totalCmd - frais);
    const R = docRabaisTotal(lignes, o.persoMacarons, money2(totalCmd - frais));   // rabais TOTAL (ligne+perso+global)
    grandBrutAbsolu += R.brutAbsolu; grandRabais += R.rabais; grandFrais += frais;
    const rows = lignes.map(ln=>factLineRows(ln, true)).join('') + cautionRowHtml(lignes);   // true = prix BRUT par ligne ; les réductions sont récapitulées sous le total (plus clair)
    return `
      <div class="cmd-section">
        <div class="cmd-head">
          <span class="cmd-ref">Commande ${esc(orderNumber(o))}${cmdEventBadge(o)}</span>
          <span class="cmd-date">${fmtDate(o.date)||''}</span>
        </div>
        <div class="cmd-body">
        <table class="cmd-table">
          <tbody>
            ${rows||'<tr><td>—</td><td class="mt"></td></tr>'}
            ${factPersoLigne(o.persoMacarons, o.persoRemiseEur, true)}
            ${R.rabais>0?`<tr class="tc-brut"><td>Total commande sans réduction</td><td class="mt">${euro(R.brutAbsolu)}</td></tr><tr class="tc-remise"><td>Total des remises${R.pct>0?` (−${R.pct}%)`:''}</td><td class="mt">−${euro(R.rabais)}</td></tr>`:''}
            ${frais>0?`<tr class="liv"><td>Frais de livraison</td><td class="mt">${euro(frais)}</td></tr>`:''}
            <tr class="cmd-total"><td>Total commande ${esc(orderNumber(o))}</td><td class="mt">${euro(totalCmd)}</td></tr>
          </tbody>
        </table>
        ${factPersoBox(o.persoMacarons, o.persoCouleurs)}
        </div>
      </div>`;
  }).join('');

  // Acomptes cumulés
  const totalPaye = orders.reduce((s,o)=>s+paiementsDe(o).reduce((a,p)=>a+(+p.montant||0),0),0); // [v1194] paiementsDe : legacy inclus
  const reste = Math.max(0, Math.round((grandTotal-totalPaye)*100)/100);
  let _lastPayDate='', _lastPayMoyen='';
  orders.forEach(o=>paiementsDe(o).forEach(p=>{ if(p.date && p.date>=_lastPayDate){ _lastPayDate=p.date; _lastPayMoyen=p.moyen||''; } })); // [v1194] paiementsDe : legacy inclus

  const clientBloc = client
    ? `${esc([client.civilite,client.prenom,client.nom].filter(Boolean).join(' ')||client.nom||'')}${client.societe?'<br>'+esc(client.societe):''}${client.adresse?'<br>'+esc(client.adresse):''}${client.tel?'<br>Tél : '+esc(client.tel):''}${client.email?'<br>'+esc(client.email):''}`
    : (clientIds.length>1 ? 'Clients multiples' : 'Client de passage');

  // [v1088] Date de livraison / exécution (Art. 242 nonies A CGI) : obligatoire dès qu'elle
  // diffère de la date d'émission. Pour chaque commande, on retient la date d'événement si
  // renseignée, sinon la date de la commande. Si toutes les commandes partagent UNE même date
  // de livraison et qu'elle diffère de l'émission, on l'affiche explicitement dans les détails.
  // Si les dates diffèrent entre commandes, chaque section porte déjà sa propre date/événement.
  const _emissionISO = today();
  const _livDates = [...new Set(orders.map(o => o.dateEvenement || o.date || '').filter(Boolean))];
  const _dateLivUnique = (_livDates.length === 1 && _livDates[0] !== _emissionISO) ? _livDates[0] : '';

  // Numéro de facture groupée : basé sur la 1re et dernière commande
  // Sur le BROUILLON, on n'affiche pas un numéro légal (il n'est attribué qu'à la validation).
  // On montre le prochain numéro PRÉVU, clairement marqué « (brouillon) » pour éviter toute
  // confusion avec un numéro définitif.
  const numFact = _factRegenCtx ? _factRegenCtx.numero : `${peekFactureNumero()} (brouillon)`;

  const factureHtml = `<!doctype html><html lang="fr"><head><meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <meta name="format-detection" content="telephone=no, date=no, email=no, address=no">
   <title>Facture groupée</title>
   ${FACT_STYLE}</head><body>
   <div class="barre noprint"><button onclick="window.print()">🖨 Imprimer / Enregistrer en PDF</button></div>
   <div class="page">
     <div class="entete">
       <img class="logo" src="${FACT_LOGO}" alt="logo">
       <div class="em">
         ${[
           e.exploitant?esc(e.exploitant):'',
           e.adresse?esc(e.adresse):'',
           e.cpville?esc(e.cpville):'',
           e.tel?'Tél. '+esc(e.tel):'',
           e.email?esc(e.email):'',
           e.siret?'SIRET '+esc(e.siret):''
         ].filter(Boolean).map(l=>`<div class="em-l">${l}</div>`).join('')}
       </div>
     </div>
     <div class="corps">
       <div class="ftitre">Facture</div>
       <div class="ftitre-rule"></div>
       <div class="meta">
         <div class="bloc"><div class="lbl">Facturé à</div>${clientBloc}</div>
         <div class="bloc" style="text-align:right">
           <div class="lbl">Détails</div>
           Facture n° : <b><span id="factNumero">${esc(numFact)}</span></b><br>
           Date d'émission : <span id="factDate">${fmtDate(_factRegenCtx ? _factRegenCtx.date : today())}</span><br>
           ${_dateLivUnique ? `Date de livraison : ${fmtDate(_dateLivUnique)}<br>` : ''}
           ${orders.length>1 ? orders.length+' commande(s) regroupée(s)' : ''}
         </div>
       </div>
       <div class="meta-rule"></div>
       ${sections}
       <div class="grand">
         ${grandRabais>0?(()=>{const p=grandBrutAbsolu>0?Math.round(grandRabais/grandBrutAbsolu*1000)/10:0;return `<div class="lg brut"><span>Total avant réductions</span><span>${euro(grandBrutAbsolu)}</span></div><div class="lg reduc"><span>Total des remises${p>0?` (−${p}%)`:''}</span><span>\u2212${euro(grandRabais)}</span></div>`;})():''}
         ${grandFrais>0?`<div class="lg"><span>Frais de livraison</span><span>${euro(grandFrais)}</span></div>`:''}
         <div class="lg total"><span>Total à payer</span><span>${euro(grandTotal)}</span></div>
         <!--REGL-->${_factReglSlotHtml(grandTotal, totalPaye, _lastPayDate, _lastPayMoyen)}<!--/REGL-->
       </div>
       <div class="bas-final">
         ${factRibAvisCol(e)}
         <div class="legal-bloc">
           <div class="tva">TVA non applicable, article 293 B du Code général des impôts.</div>
           ${e.paiement?`<div class="paiement">${esc(e.paiement)}</div>`:''}
           ${factMentionsRetardB2B()}
           ${factMentionMediateur(e)}
         </div>
       </div>
       <div class="pied">${esc(e.nom||'')}${e.siret?' · SIRET '+esc(e.siret):''} · Micro-entreprise · Merci de votre confiance 🍬</div>
     </div>
   </div>
   </body></html>`;
  // Mode RÉGÉNÉRATION d'une facture figée : on renvoie le HTML + le total recalculé, sans
  // rien stocker ni afficher. Le contrôle des montants et l'écriture auditée se font en aval.
  if(_factRegenCtx){ _factRegenCtx.html = factureHtml; _factRegenCtx.total = money2(grandTotal); return; }
  // === Enregistrement au REGISTRE comme BROUILLON (sans numéro légal) ===
  // Le numéro définitif et le verrouillage n'interviennent qu'à la VALIDATION.
  try{
    const orderIds = orders.map(o=>o.id);

    // Recherche d'un document facture DÉJÀ associé exactement à ce lot de commandes :
    //  - s'il est définitif → on le rouvre (pas de doublon possible) ;
    //  - s'il est encore brouillon → on le met à jour au lieu d'en empiler un second ;
    //  - sinon → on crée un nouveau brouillon.
    // NB : cette variable n'était pas définie auparavant, ce qui levait une ReferenceError
    // avalée par le catch → aucun brouillon n'était enregistré.
    let existing = null;
    try{
      const wanted = [...orderIds].sort((a,b)=>a-b).join(',');
      const facts = await db.documents.where('type').equals('facture').toArray();
      existing = facts.find(f=>{
        const oids = (f.orderIds||(f.orderId?[f.orderId]:[])).slice().sort((a,b)=>a-b).join(',');
        return oids===wanted;
      }) || null;
    }catch(_e){ existing = null; }

    if(existing && docEstDefinitif(existing)){
      if(view==="documents") renderDocuments();
      _prepDocPdfMail(factureHtml, `Facture ${existing.numero}`, client, grandTotal);
      openPrintView(factureHtml, {title:`Facture ${existing.numero}`, extraButtons:_docMailBtns()});
      return;
    }
    const docFact = {
      type:'facture', statut:'brouillon',
      numero:null,                       // pas de numéro légal tant que brouillon
      refInterne:numFact,                // référence interne lisible (basée sur la commande)
      clientId:(client&&client.id)||orders[0].clientId||0,
      date:today(),
      montant:money2(grandTotal),
      totalPaye:money2(totalPaye),
      orderIds, orderId:orderIds[0]||null,
      nbCommandes:orders.length,
      html:factureHtml,                  // aperçu intégral mémorisé
      createdAt:Date.now()
    };
    if(existing){ await db.documents.update(existing.id, docFact); }
    else { await db.documents.add(docFact); }
    if(view==="documents") renderDocuments();
    toast('Brouillon de facture créé — à vérifier puis valider');
  }catch(e){ console.error('genererFactureMultiple/enregistrement', e); toast('⚠️ Le brouillon n\'a pas pu être enregistré : '+(e&&e.message||'erreur')); }
  _prepDocPdfMail(factureHtml, `Facture ${numFact}`, client, grandTotal);
  openPrintView(factureHtml, {title:`Facture (brouillon) ${numFact}`, extraButtons:_docMailBtns()});
}
function orderNumber(o){
  const y = (o.date||today()).slice(0,4);
  return `${y}-${String(o.id||0).padStart(3,'0')}`;
}
// Récupère TOUTES les données d'une commande sous forme structurée (réutilisable tous formats).
async function collectOrderExport(orderId){
  const o = await db.orders.get(orderId);
  if(!o) return null;
  const cl = o.clientId ? await db.clients.get(o.clientId) : null;
  const lignes = orderToLines(o);
  const produits = lignes.map(ln=>{
    if(ln.type==='coffret') return {label:`Coffret ${ln.taille} macarons`, remisePct:+ln.remisePct||0,
      parfums:(ln.parfums||[]).filter(p=>p.qte>0).map(p=>({nom:p.nom,qte:p.qte}))};
    if(ln.type==='evenement') return {label:`Événement : ${ln.evQte||0} macarons + ${ln.equip||0} présentoir(s)${accessoireDecoActif(ln)?' + accessoire décoratif':''}`, remisePct:+ln.remisePct||0,
      parfums:(ln.parfums||[]).filter(p=>p.qte>0).map(p=>({nom:p.nom,qte:p.qte}))};
    if(ln.type==='grand') return {label:`Grand format (${ln.tarif||'particulier'})`, remisePct:+ln.remisePct||0,
      parfums:(ln.items||[]).filter(p=>p.qte>0).map(p=>({nom:p.nom,qte:p.qte}))};
    if(ln.type==='sachet') return {label:'Sachet de macarons', remisePct:+ln.remisePct||0,
      parfums:(ln.parfums||[]).filter(p=>p.qte>0).map(p=>({nom:p.nom,qte:p.qte}))};
    if(ln.type==='don') return {label:'Don (offert)', remisePct:0,
      parfums:[...(ln.parfums||[]).filter(p=>p.qte>0).map(p=>({nom:p.nom,qte:p.qte,offert:true})),
               ...(ln.items||[]).filter(p=>p.qte>0).map(p=>({nom:p.nom+' (GF)',qte:p.qte,offert:true}))]};
    if(ln.type==='prestation') return {label:`Prestation : ${ln.libelle||'service'}`, remisePct:(ln.remiseType==='pct'?+ln.remisePct||0:0), parfums:[]};
    return {label:ln.type, parfums:[]};
  });
  const totalMacarons = lignes.reduce((s,ln)=>{
    if(ln.type==='coffret'||ln.type==='evenement'||ln.type==='don'||ln.type==='sachet') s+=(ln.parfums||[]).reduce((a,p)=>a+(+p.qte||0),0);
    if(ln.type==='evenement' && (!ln.parfums||!ln.parfums.length)) s+=(+ln.evQte||0);
    if(ln.type==='grand'||ln.type==='don') s+=(ln.items||[]).reduce((a,p)=>a+(+p.qte||0),0);
    return s;
  },0);
  return {
    numero: orderNumber(o),
    date: o.date, dateFmt: fmtDate(o.date),
    client: { nom: cl?cl.nom:'—', prenom: cl?cl.prenom:'', societe: cl?cl.societe:'',
      tel: cl?cl.tel:'', email: cl?cl.email:'', ref: cl?cl.ref:'', type: cl?cl.type:'' },
    produits, totalMacarons,
    remiseGlobale: +o.remiseGlobale||0,
    montant: +o.montant||0,
    paiement: orderPayStatus(o), reglement: o.reglement||'',
    paiements: (o.paiements||[]).map(p=>({date:p.date, montant:+p.montant||0, moyen:p.moyen||''})),
    encaisse: orderPaid(o), solde: orderBalance(o),
    statut: normStatus(o.statut),
    notes: o.notes||''
  };
}
// Rendu TEXTE propre et homogène d'une commande, à partir de la structure.
function formatOrderTXT(d){
  const L=[];
  L.push(`Commande n°${d.numero}`);
  L.push('');
  const clLine = [d.client.prenom, d.client.nom].filter(Boolean).join(' ') || d.client.nom;
  L.push('Client : '+clLine + (d.client.societe?` — ${d.client.societe}`:''));
  if(d.client.tel) L.push('Téléphone : '+d.client.tel);
  if(d.client.email) L.push('Email : '+d.client.email);
  L.push('Date : '+d.dateFmt);
  L.push('');
  L.push('Produits :');
  d.produits.forEach(p=>{
    L.push('  - '+p.label + (p.remisePct>0?` (remise ${p.remisePct}%)`:''));
    p.parfums.forEach(f=>L.push(`      ${f.nom} : ${f.qte}`+(f.offert?' (offert)':'')));
  });
  L.push('');
  if(d.remiseGlobale>0) L.push(`Remise globale : −${d.remiseGlobale}%`);
  L.push('Total : '+euro(d.montant));
  // Traçabilité des paiements
  if(d.paiements && d.paiements.length){
    L.push('Paiements :');
    d.paiements.forEach(p=>L.push(`  - ${fmtDate(p.date)} · ${euro(p.montant)} · ${p.moyen||'—'}`));
    L.push(`Encaissé : ${euro(d.encaisse)} · Solde dû : ${euro(d.solde)}`);
  }
  L.push('Statut : '+d.paiement+(d.reglement&&!(d.paiements&&d.paiements.length)?` (${d.reglement})`:''));
  if(d.notes){ L.push(''); L.push('Commentaires : '+d.notes.replace(/\n/g,' / ')); }
  return L.join('\n');
}
// Export TXT d'une sélection de commandes (séparateur homogène entre commandes).
// Construit un e-mail « Livraison du jour » vers le client à partir des commandes sélectionnées.
// Regroupe par client (toutes les commandes cochées doivent concerner le même client), récupère
// l'e-mail via la fiche client, et ouvre la boîte mail (mailto) avec un corps personnalisé.
function factGetSignature(){ try{ return localStorage.getItem('sm_mailSignature')||''; }catch(e){ return ''; } }
function factSaveSignature(v){ try{ localStorage.setItem('sm_mailSignature', v||''); }catch(e){swallow(e,'factSaveSignature')} }

async function cmdMailSelection(){
  const ids=[..._cmdSel];
  if(!ids.length){ toast('Aucune commande sélectionnée'); return; }
  // Récupère les commandes + clients
  const datas=[];
  for(const id of ids){ const d=await collectOrderExport(id); if(d) datas.push(d); }
  if(!datas.length){ toast('Impossible de lire les commandes'); return; }
  // Vérifie qu'elles concernent un seul et même client
  const orders = await Promise.all(ids.map(id=>db.orders.get(id)));
  const clientIds = [...new Set(orders.filter(Boolean).map(o=>o.clientId))];
  if(clientIds.length>1){
    toast('Sélectionne des commandes d\'un seul client pour l\'e-mail');
    return;
  }
  const cl = clientIds[0] ? await db.clients.get(clientIds[0]) : null;
  if(!cl){ toast('Client introuvable'); return; }
  if(!cl.email){
    openModal(`<h3>✉️ Pas d'e-mail pour ce client</h3>
      <p class="note">La fiche de « ${esc(cl.nom||'ce client')} » ne contient pas d'adresse e-mail. Ajoute-la dans sa fiche client, puis réessaie.</p>
      <div class="modal-actions"><button class="btn" onclick="closeModal()">Compris</button></div>`);
    return;
  }
  datas.sort((a,b)=>(a.date||'').localeCompare(b.date||''));
  const sign = factGetSignature();
  // Politesse par défaut = réglage de la fiche client (vouvoiement si absent).
  const tuDefaut = cl.politesse === 'tu';
  // Appellation par défaut : prénom seul en tutoiement, nom complet en vouvoiement.
  openModal(`<h3>✉️ E-mail au client</h3>
    <p class="note">Destinataire : <b>${esc(cl.email)}</b> · ${datas.length} commande(s)</p>
    <div class="field"><label>Formule de politesse</label>
      <select id="mailPol" onchange="cmdMailSyncAppel()">
        <option value="vous" ${!tuDefaut?'selected':''}>Vouvoiement</option>
        <option value="tu" ${tuDefaut?'selected':''}>Tutoiement</option>
      </select></div>
    <div class="field"><label>Appellation dans le message</label>
      <select id="mailAppel">
        <option value="prenom" ${tuDefaut?'selected':''}>Prénom seul${cl.prenom?` (${esc(cl.prenom)})`:''}</option>
        <option value="complet" ${!tuDefaut?'selected':''}>Nom complet${[cl.prenom,cl.nom].filter(Boolean).length?` (${esc([cl.prenom,cl.nom].filter(Boolean).join(' '))})`:''}</option>
      </select></div>
    <div class="field"><label>Signature (ton nom)</label><input id="mailSign" value="${esc(sign)}" placeholder="ex : Benjamin"></div>
    <p class="note">Objet : « Livraison du jour ». Le choix de politesse sera mémorisé sur la fiche client.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="cmdMailOpen(${cl.id})">Ouvrir ma boîte mail</button>
    </div>`);
  // stocke temporairement les données pour cmdMailOpen
  _mailDraft = {cl, datas};
}
let _mailDraft=null;
// Synchronise l'appellation par défaut avec la politesse choisie, tant que l'utilisateur
// n'a pas modifié l'appellation lui-même (heuristique douce : on aligne toujours au changement).
function cmdMailSyncAppel(){
  const pol=document.getElementById('mailPol'), app=document.getElementById('mailAppel');
  if(!pol||!app) return;
  app.value = (pol.value==='tu') ? 'prenom' : 'complet';
}
async function cmdMailOpen(clientId){
  if(!_mailDraft){ closeModal(); return; }
  const {cl, datas}=_mailDraft;
  const sign=(val('mailSign')||'').trim(); factSaveSignature(sign);
  const tu = (val('mailPol')||'vous') === 'tu';
  const appel = (val('mailAppel')||'prenom');
  // Persiste le choix de politesse sur la fiche client (mémorisation demandée).
  const polChoisie = tu ? 'tu' : 'vous';
  if(cl.politesse !== polChoisie){ try{ await db.clients.update(cl.id, {politesse:polChoisie}); }catch(e){swallow(e,'cmdMailOpen')} }
  // Appellation : prénom seul OU nom complet.
  const prenom = cl.prenom || '';
  const nomComplet = [cl.prenom, cl.nom].filter(Boolean).join(' ') || cl.nom || '';
  const appellation = (appel==='prenom' && prenom) ? prenom : nomComplet;
  const salut = `Bonjour ${appellation}`.trim();
  const nb = datas.length;
  // Détail des commandes en texte brut (inchangé).
  const blocs = datas.map(d=>{
    const L=[];
    L.push(`Commande n°${d.numero} — ${d.dateFmt}`);
    d.produits.forEach(p=>{
      L.push(`  • ${p.label}${p.remisePct>0?` (remise ${p.remisePct}%)`:''}`);
      p.parfums.forEach(f=>L.push(`      - ${f.nom} : ${f.qte}${f.offert?' (offert)':''}`));
    });
    L.push(`  Total : ${euro(d.montant)}`);
    return L.join('\n');
  }).join('\n\n');
  // Phrase d'intro conjuguée + accord singulier/pluriel selon le nombre de commandes.
  const intro = tu
    ? (nb>1 ? 'Voici le détail de tes commandes :' : 'Voici le détail de ta commande :')
    : (nb>1 ? 'Voici le détail de vos commandes :' : 'Voici le détail de votre commande :');
  const corps = `${salut},\n\n${intro}\n\n${blocs}\n\nMerci et à bientôt.\n${sign||''}\n— Sensations Macarons`;
  const objet = 'Livraison du jour';
  const mailto = `mailto:${encodeURIComponent(cl.email)}?subject=${encodeURIComponent(objet)}&body=${encodeURIComponent(corps)}`;
  closeModal();
  window.location.href = mailto;
  _mailDraft=null;
}

async function cmdExportSelection(){
  const ids=[..._cmdSel];
  if(!ids.length){ toast('Aucune commande sélectionnée'); return; }
  // ordre chronologique des sélectionnées
  const datas=[];
  for(const id of ids){ const d=await collectOrderExport(id); if(d) datas.push(d); }
  datas.sort((a,b)=>(a.date||'').localeCompare(b.date||''));
  const SEP='\n\n────────────────────────────────────────\n\n';
  const header = `SENSATIONS MACARONS — Export de ${datas.length} commande(s)\n${fmtDate(today())}`;
  const txt = header + SEP + datas.map(formatOrderTXT).join(SEP) + SEP + 'Sensations Macarons — Le Mans';
  const name = `commandes-selection-${today()}.txt`;
  let copied=false;
  try{ if(navigator.clipboard&&navigator.clipboard.writeText){ await navigator.clipboard.writeText(txt); copied=true; } }catch(e){swallow(e,'cmdExportSelection')}
  const blob=new Blob([txt],{type:'text/plain;charset=utf-8'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; a.click();
  openModal(`<h3>Export de ${datas.length} commande(s)</h3>
    <p class="note">${copied?'Copié dans le presse-papier ✓ — collez directement dans un email.':'Fichier .txt téléchargé. Vous pouvez aussi copier ci-dessous.'}</p>
    <textarea id="selTxt" rows="16" style="width:100%;font-family:monospace;font-size:.76rem;white-space:pre">${esc(txt)}</textarea>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Fermer</button>
      <button class="btn" onclick="(function(){const t=document.getElementById('selTxt');t.select();try{document.execCommand('copy');}catch(e){swallow(e,'cmdExportSelection')} toast('Copié ✓');})()">⧉ Copier</button>
    </div>
    <p class="note" style="margin-top:8px;color:#9a8a82">Exports PDF, Excel et envoi e-mail direct : prévus prochainement (même base de données structurée).</p>`);
}

// Export TEXTE d'une commande (détaillé, avec traçabilité des lots) : fichier .txt + copie
async function buildOrderText(orderId){
  const o = await db.orders.get(orderId);
  const cl = o.clientId ? await db.clients.get(o.clientId) : null;
  const lignes = orderToLines(o);
  const L=[];
  L.push('SENSATIONS MACARONS');
  L.push('Commande du '+fmtDate(o.date));
  if(o.heureLivraison || o.lieuLivraison){
    L.push('Livraison : '+[o.heureLivraison, o.lieuLivraison].filter(Boolean).join(' · '));
  }
  L.push('========================================');
  L.push('');
  L.push('CLIENT');
  L.push('  '+(cl?cl.nom:'—')+(cl&&cl.type?' ('+cl.type+')':''));
  if(cl&&cl.email) L.push('  '+cl.email);
  if(cl&&cl.tel) L.push('  '+cl.tel);
  L.push('');
  L.push('PRODUITS');
  if(!lignes.length){ L.push('  (aucun détail enregistré)'); }
  lignes.forEach(ln=>{
    if(ln.type==='coffret'){
      const parfums=(ln.parfums||[]).filter(p=>p.qte>0);
      const totQ=parfums.reduce((s,p)=>s+(+p.qte||0),0);
      const _rem=Math.max(0,Math.min(100,+ln.remisePct||0));
      L.push('  - Coffret '+ln.taille+' macarons'+(totQ?' ('+totQ+' macaron'+(totQ>1?'s':'')+')':'')+(_rem>0?' [remise −'+_rem+'%]':'')+' — '+euro(lineTotalStored(ln)));
      parfums.forEach(p=>L.push('      • '+p.nom+' × '+p.qte));
      if(!parfums.length) L.push('      • (parfums non détaillés)');
    } else if(ln.type==='evenement'){
      const parfums=(ln.parfums||[]).filter(p=>p.qte>0);
      const _rem=Math.max(0,Math.min(100,+ln.remisePct||0));
      L.push('  - Événement : '+(ln.evQte||0)+' macarons + '+(ln.equip||0)+' présentoir(s)'+(accessoireDecoActif(ln)?' + accessoire décoratif (ruban + déco LOVE)':'')+(_rem>0?' [remise −'+_rem+'%]':'')+' — '+euro(lineTotalStored(ln)));
      parfums.forEach(p=>L.push('      • '+p.nom+' × '+p.qte));
    } else if(ln.type==='grand'){
      const items=(ln.items||[]).filter(p=>p.qte>0);
      const totQ=items.reduce((s,p)=>s+(+p.qte||0),0);
      const _rem=Math.max(0,Math.min(100,+ln.remisePct||0));
      L.push('  - Grand format ('+(ln.tarif||'particulier')+')'+(totQ?' — '+totQ+' pièce'+(totQ>1?'s':''):'')+(_rem>0?' [remise −'+_rem+'%]':'')+' — '+euro(lineTotalStored(ln)));
      items.forEach(p=>L.push('      • '+p.nom+' × '+p.qte));
    } else if(ln.type==='vrac'){
      const parfums=(ln.parfums||[]).filter(p=>p.qte>0);
      const totQ=parfums.reduce((s,p)=>s+(+p.qte||0),0);
      const _rem=Math.max(0,Math.min(100,+ln.remisePct||0));
      L.push('  - Vrac pro'+(totQ?' — '+totQ+' macaron'+(totQ>1?'s':''):'')+(_rem>0?' [remise −'+_rem+'%]':'')+' — '+euro(lineTotalStored(ln)));
      parfums.forEach(p=>L.push('      • '+p.nom+' × '+p.qte));
    } else if(ln.type==='sachet'){
      const parfums=(ln.parfums||[]).filter(p=>p.qte>0);
      const totQ=parfums.reduce((s,p)=>s+(+p.qte||0),0) + (+ln.sansParfum||0);
      const _rem=Math.max(0,Math.min(100,+ln.remisePct||0));
      L.push('  - Sachet'+(totQ?' — '+totQ+' macaron'+(totQ>1?'s':''):'')+(_rem>0?' [remise −'+_rem+'%]':'')+' — '+euro(lineTotalStored(ln)));
      parfums.forEach(p=>L.push('      • '+p.nom+' × '+p.qte));
    } else if(ln.type==='don'){
      const parfums=(ln.parfums||[]).filter(p=>p.qte>0);
      const items=(ln.items||[]).filter(p=>p.qte>0);
      L.push('  - Don (offert)');
      parfums.forEach(p=>L.push('      • '+p.nom+' × '+p.qte+' (offert)'));
      items.forEach(p=>L.push('      • '+p.nom+' (grand format) × '+p.qte+' (offert)'));
    } else if(ln.type==='prestation'){
      L.push('  - Prestation / Coaching : '+(ln.libelle||'Prestation')+' — '+euro(lineTotalStored(ln)));
    }
  });
  if(+o.persoMacarons>0){ L.push('  - Personnalisation couleurs : '+o.persoMacarons+' macaron(s)'); }
  // Récapitulatif par parfum (tous coffrets/formats confondus)
  const parfumTot={};
  lignes.forEach(ln=>{ (ln.parfums||[]).forEach(p=>{ if(+p.qte>0) parfumTot[p.nom]=(parfumTot[p.nom]||0)+(+p.qte); });
                       (ln.items||[]).forEach(p=>{ if(+p.qte>0) parfumTot[p.nom]=(parfumTot[p.nom]||0)+(+p.qte); }); });
  const parfumKeys=Object.keys(parfumTot);
  if(parfumKeys.length){
    L.push('');
    L.push('RÉCAP PARFUMS');
    parfumKeys.sort((a,b)=>a.localeCompare(b,'fr')).forEach(k=>L.push('  • '+k+' × '+parfumTot[k]));
  }
  L.push('');
  if(+o.remiseGlobale>0) L.push('Remise globale : −'+o.remiseGlobale+'%');
  L.push('MONTANT : '+euro(o.montant));
  const _livT = computeDeliveryCost(o);
  if(_livT.actif){
    L.push('Livraison : A/R '+_livT.distAR+' km'+(_livT.minutes?' · '+_livT.minutes+' min':'')+' → coût '+euro(_livT.total)+' (carburant '+euro(_livT.coutCarburant)+' + temps '+euro(_livT.coutTemps)+')');
  }
  L.push('Paiement : '+(o.paiement||'En attente')+(o.reglement?' ('+o.reglement+')':''));
  L.push('Statut : '+normStatus(o.statut));
  if(o.notes){ L.push(''); L.push('NOTES'); L.push('  '+o.notes.replace(/\n/g,'\n  ')); }
  // Lots utilisés (traçabilité), si la commande est liée à des batchs
  const items = await db.orderItems.where('orderId').equals(orderId).toArray();
  if(items.length){
    L.push('');
    L.push('LOTS DE PRODUCTION (traçabilité)');
    for(const it of items){
      const prod = await db.productions.get(it.productionId);
      if(!prod) continue;
      const rec = await db.recipes.get(prod.recipeId);
      L.push('  - '+(rec?rec.produitNom:'?')+' · lot '+(prod.lotProduction||'—')+' × '+it.qte
        +(prod.dlcProduit?' · DLC '+fmtDate(prod.dlcProduit):''));
    }
  }
  L.push('');
  L.push('========================================');
  L.push('Sensations Macarons — Le Mans');
  return L.join('\n');
}
async function exportOrderText(orderId){
  const txt = await buildOrderText(orderId);
  const o = await db.orders.get(orderId);
  const cl = o.clientId ? await db.clients.get(o.clientId) : null;
  const slug = (cl?cl.nom:'commande').replace(/[^a-zA-Z0-9]+/g,'-').toLowerCase();
  const name = 'commande-'+slug+'-'+(o.date||'')+'.txt';
  // copie instantanée dans le presse-papier (usage email)
  let copied=false;
  try{ if(navigator.clipboard&&navigator.clipboard.writeText){ await navigator.clipboard.writeText(txt); copied=true; } }catch(e){swallow(e,'exportOrderText')}
  // fichier .txt téléchargeable
  const blob=new Blob([txt],{type:'text/plain;charset=utf-8'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; a.click();
  // aperçu + copie manuelle de secours
  openModal(`<h3>Commande en texte</h3>
    <p class="note">${copied?'Copié dans le presse-papier ✓ — collez directement dans un email.':'Fichier .txt téléchargé. Vous pouvez aussi copier ci-dessous.'} </p>
    <textarea id="orderTxt" rows="14" style="width:100%;font-family:monospace;font-size:.78rem;white-space:pre">${esc(txt)}</textarea>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button>
      <button class="btn" onclick="(function(){const t=document.getElementById('orderTxt');t.select();try{document.execCommand('copy');}catch(e){swallow(e,'exportOrderText')} toast('Copié ✓');})()">⧉ Copier</button></div>`);
}

/* ============================================================
   SEED initial + BOOT
   ============================================================ */
async function seedIfEmpty(){
  const n = await db.materials.count();
  const c = await db.clients.count();
  if(n>0 || c>0) return;
  const fourId = await db.suppliers.add({nom:'nut&me',contact:'nutandme.fr'});
  const mats = [
    {nom:"Poudre d'amande",unite:'kg',seuil:5,prixDefaut:18},
    {nom:'Sucre glace',unite:'kg',seuil:6,prixDefaut:2.5},
    {nom:'Sucre semoule',unite:'kg',seuil:5,prixDefaut:1.8},
    {nom:"Blancs d'œufs",unite:'L',seuil:2,prixDefaut:6},
    {nom:'Chocolat blanc',unite:'kg',seuil:3,prixDefaut:12},
    {nom:'Colorant',unite:'unité',seuil:3,prixDefaut:9},
  ];
  const ids={};
  for(const m of mats) ids[m.nom]=await db.materials.add(m);
  const inDays = n => { const d=new Date(); d.setDate(d.getDate()+n); return ymdLocal(d); };
  await db.materialLots.bulkAdd([
    {materialId:ids["Poudre d'amande"],supplierId:fourId,lotFournisseur:'NM-A-101',qteInitiale:8,qteRestante:8,prix:144,dateReception:today(),dlc:inDays(120)},
    {materialId:ids['Sucre glace'],supplierId:fourId,lotFournisseur:'NM-S-220',qteInitiale:12,qteRestante:12,prix:30,dateReception:today(),dlc:inDays(300)},
    {materialId:ids["Blancs d'œufs"],supplierId:fourId,lotFournisseur:'NM-B-077',qteInitiale:3,qteRestante:3,prix:18,dateReception:today(),dlc:inDays(20)},
  ]);
  const recId = await db.recipes.add({produitNom:'Macaron vanille',rendement:60});
  await db.recipeItems.bulkAdd([
    {recipeId:recId,materialId:ids["Poudre d'amande"],qteParBatch:0.3},
    {recipeId:recId,materialId:ids['Sucre glace'],qteParBatch:0.3},
    {recipeId:recId,materialId:ids["Blancs d'œufs"],qteParBatch:0.12},
  ]);
}

// Catalogue de coffrets — créé une seule fois, indépendamment du reste
// (ainsi les utilisateurs existants l'obtiennent aussi).
async function seedProducts(){
  const n = await db.products.count();
  if(n>0) return;
  for(const t of BOX_SIZES){
    await db.products.add({ taille:t, nom:`Coffret ${t} macarons`, prix:BOX_PRICES[t], actif:true });
  }
}
// [v1452] COFFRET DE 10 À 22 € — Ben : « un coffret de 10 macarons à 22€. L'emballage par défaut
// est la boîte blanche de 8/10 macarons. » IDEMPOTENT et distinct de seedProducts() : celle-ci ne
// s'exécute QUE sur un catalogue vide (`if(n>0) return`), donc la base existante de Ben ne l'aurait
// jamais reçu. On crée aussi la boîte blanche si elle manque — c'est l'emballage par défaut de ce
// format (voir COFFRET10_EMB_NOM / setCoffretTaille), sans elle le défaut n'aurait rien à pointer.
const COFFRET10_TAILLE = 10;
const COFFRET10_PRIX = 22;
const COFFRET10_EMB_NOM = 'Boîte blch 8/10pcs';
async function seedCoffret10(){
  try{
    // 1) La boîte blanche 8/10 (capacité 10) — même définition que createBoitesBlanches().
    const mats = await db.materials.toArray().catch(()=>[]);
    const embExiste = mats.some(m=>m.categorie==='emballage'
      && (m.nom||'').trim().toLowerCase()===COFFRET10_EMB_NOM.toLowerCase());
    if(!embExiste){
      await db.materials.add({nom:COFFRET10_EMB_NOM, unite:'unité', categorie:'emballage',
        capacite:10, seuil:0, prixDefaut:0.14});
      if(typeof syncAfterMaterialChange==='function') await syncAfterMaterialChange();
    }
    // 2) Le coffret de 10 dans le catalogue de l'offre. On ne touche PAS à un coffret 10 déjà
    //    présent : Ben a pu en régler le prix lui-même, l'écraser serait perdre sa saisie.
    const prods = await db.products.toArray().catch(()=>[]);
    if(!prods.some(p=>+p.taille===COFFRET10_TAILLE)){
      await db.products.add({ taille:COFFRET10_TAILLE, nom:`Coffret ${COFFRET10_TAILLE} macarons`,
        prix:COFFRET10_PRIX, actif:true });
    }
  }catch(e){ swallow(e,'seedCoffret10'); }
}

// Rappel d'export automatique (parade à la purge iOS d'IndexedDB).
// Réglable : fréquence en jours. Affiche une MODALE actionnable (pas un simple toast
// qu'on rate). Se déclenche au démarrage si l'export hors-appareil est en retard.
function saveExportReminderDays(v){
  const n=parseInt(v,10);
  if(!n||n<1){ toast('Valeur invalide'); return; }
  const s=getSettings(); s.exportReminderDays=Math.min(60,n); saveSettings(s);
  localStorage.removeItem('sm_exportSnooze');
  toast(`Rappel tous les ${Math.min(60,n)} jour(s) ✓`);
}

// ────────────────────────────────────────────────────────────────────────────
// [v1385] CHANTIER C — SORTIR LES SAUVEGARDES DE LA BOÎTE QU'ELLES PROTÈGENT
// (faille 3 de l'audit du 19 juillet 2026).
//
// LE CONSTAT, en trois faits distincts.
//
// 1) LES INSTANTANÉS SONT DANS LA BOÎTE. snapshotBackup() écrit dans
//    `db.backups` — la MÊME base IndexedDB que les données qu'elle protège.
//    Le danger nommé partout dans l'app (« effacer l'historique Safari supprime
//    aussi la base de l'app ») emporte donc les 20 instantanés AVEC les données.
//    Une sauvegarde qui meurt exactement quand meurt l'original n'est pas une
//    sauvegarde : c'est une copie. La seule protection réelle est un fichier
//    SORTI de l'appareil — et c'est justement celle que l'app mesure le plus mal.
//
// 2) LA SORTIE EST AFFIRMÉE, PAS CONSTATÉE. exportData() faisait :
//        a.click();
//        localStorage.setItem('sm_lastExport', today());
//    Le commentaire juste en dessous admettait déjà : « L'app ne peut PAS savoir
//    si la sauvegarde a été confirmée ». Elle l'écrivait quand même. Conséquence
//    réelle : un partage annulé d'un geste, un « Enregistrer » jamais confirmé,
//    et l'app note une sortie qui n'a pas eu lieu — puis se TAIT sept jours,
//    bannière éteinte, compteur `sm_unsaved` remis à zéro.
//    C'est le motif exact de « 0 refus, 0 suspects » : un écran rassurant dont
//    le calme signifie « le contrôle n'a jamais eu lieu ».
//
// 3) RIEN NE DISTINGUE « SORTIE TENTÉE » DE « SORTIE CONFIRMÉE ». Une seule clé
//    portait les deux sens.
//
// CE QUE FAIT CE CHANTIER — et ce qu'il ne prétend PAS faire.
//
// Ce qu'il NE PEUT PAS faire, déclaré franchement : une PWA iOS ne peut pas
// vérifier qu'un fichier est bien arrivé dans iCloud Drive. Aucune API ne le
// permet. Toute affirmation contraire serait un mensonge de plus. Donc on ne
// remplace pas une supposition optimiste par une autre : on rend la DIFFÉRENCE
// visible et on demande à Ben de trancher, parce que LUI a vu l'écran de partage.
//
// Ce qu'il fait :
//   • DEUX états distincts, jamais confondus :
//       - « tentée »  (sm_lastExportTente)  : le fichier a été produit et remis
//         à iOS. C'est un fait observable côté app.
//       - « confirmée » (sm_lastExport)     : Ben a dit « oui, je l'ai bien
//         enregistré ». C'est le seul état qui éteint le rappel.
//     Le rappel et la bannière ne comptent QUE les sorties confirmées.
//   • Une demande de confirmation après le partage, honnête sur son ignorance.
//     Répondre « non / annulé » ne pénalise rien : on revient simplement à
//     l'état d'avant, la vérité n'a pas bougé.
//   • L'ÂGE RÉEL de la dernière sortie confirmée, affiché en clair, et un
//     décompte « N jours de travail non sortis de l'appareil » qui ne repose
//     sur AUCUNE supposition.
//   • Le rappel ne peut plus être éteint par accident : seule une confirmation
//     explicite l'éteint.
//
// LA RÈGLE FIGÉE : une sauvegarde n'est acquise que lorsqu'elle est SORTIE de
// l'appareil, et une sortie n'est acquise que lorsqu'elle est CONSTATÉE — jamais
// parce qu'on l'a demandée.
// ────────────────────────────────────────────────────────────────────────────

// Les deux clés, et leur sens — délibérément séparées.
const SORTIE_TENTEE_KEY  = 'sm_lastExportTente';   // fait observable : fichier remis à iOS
const SORTIE_CONFIRMEE_KEY = 'sm_lastExport';      // fait CONSTATÉ par Ben (clé historique, conservée)

// Enregistre une TENTATIVE de sortie. N'éteint aucun rappel : une tentative
// n'est pas une sauvegarde. (PURE côté décision ; n'écrit que la trace.)
function sortieMarqueTentee(canal){
  try{
    localStorage.setItem(SORTIE_TENTEE_KEY, JSON.stringify({ date: today(), canal: canal||'fichier', ts: Date.now() }));
  }catch(e){ swallow(e, 'sortieMarqueTentee'); }
}

// Enregistre une sortie CONFIRMÉE par Ben. C'est le SEUL chemin qui éteint le rappel
// et remet le compteur de travail non sauvegardé à zéro.
function sortieMarqueConfirmee(canal){
  try{
    localStorage.setItem(SORTIE_CONFIRMEE_KEY, today());
    if(canal === 'icloud') localStorage.setItem('sm_lastICloud', today());
    localStorage.removeItem('sm_exportSnooze');
    clearUnsaved();
  }catch(e){ swallow(e, 'sortieMarqueConfirmee'); }
  try{
    if(typeof db !== 'undefined' && db.auditLog){
      db.auditLog.add({ ts:Date.now(), tbl:'*', op:'sortie-confirmee', cle:null,
        resume:_auditResume({ canal: canal||'fichier', date: today() }),
        ecran:(typeof view !== 'undefined' && view) ? String(view) : '', v:APP_VERSION })
        .catch(e => swallow(e, 'audit sortie'));
    }
  }catch(e){ swallow(e, 'sortieMarqueConfirmee audit'); }
}

// Lit la dernière tentative non confirmée, s'il y en a une (PURE).
// Retourne null si la dernière tentative a été suivie d'une confirmation le même jour ou après.
function sortieTenteeNonConfirmee(){
  let t = null;
  try{ t = JSON.parse(localStorage.getItem(SORTIE_TENTEE_KEY) || 'null'); }catch(e){ return null; }
  if(!t || !t.date) return null;
  let conf = null;
  try{ conf = localStorage.getItem(SORTIE_CONFIRMEE_KEY); }catch(e){ conf = null; }
  if(conf && String(conf) >= String(t.date)) return null;   // confirmée depuis
  return t;
}

// L'ÉTAT DE SORTIE, en une fonction PURE et testable. Ne suppose RIEN.
// Retour : { confirmee:'AAAA-MM-JJ'|null, jours:int|null, tentee:{...}|null,
//            enRetard:bool, jamais:bool, texte:string }
function sortieEtat(freqJours){
  const freq = (freqJours && freqJours > 0) ? freqJours : 7;
  let conf = null;
  try{ conf = localStorage.getItem(SORTIE_CONFIRMEE_KEY); }catch(e){ conf = null; }
  const tentee = sortieTenteeNonConfirmee();
  if(!conf){
    return { confirmee:null, jours:null, tentee, jamais:true, enRetard:true,
      texte: tentee
        ? `Aucune sortie CONFIRMÉE. Une tentative est enregistrée le ${fmtDate(tentee.date)}, mais l'app ne peut pas vérifier qu'elle a abouti.`
        : `Aucune sauvegarde n'est encore sortie de cet appareil.` };
  }
  const d = daysTo(conf);                       // négatif = dans le passé
  // Une date de sortie ILLISIBLE (stockage corrompu) ne prouve aucune sortie : elle est
  // traitée comme un RISQUE, jamais comme un succès. Sans ça, une clé abîmée éteindrait
  // le rappel en silence — précisément le « 0 refus, 0 suspects » que l'audit dénonce.
  // UN SEUL point de décision pour enRetard. Ma première version le calculait ici PUIS le
  // réaffirmait dans le retour anticipé ci-dessous : casser l'un ne changeait rien, donc la
  // garde ne voyait plus la régression. Une protection en double qui masque un sabotage est
  // pire qu'une protection unique et lisible.
  const jours = (d === null) ? null : Math.abs(d);
  const enRetard = (d === null) ? true : (d <= -freq);
  if(d === null){
    return { confirmee:conf, jours:null, tentee, jamais:false, enRetard,
      texte: `La date de dernière sortie est illisible (« ${String(conf)} ») : impossible de prouver qu'une sauvegarde est sortie de l'appareil. Refais-en une.` };
  }
  const age = (jours === 0) ? "aujourd'hui" : `il y a ${jours} jour(s)`;
  return { confirmee:conf, jours, tentee, jamais:false, enRetard,
    texte: `Dernière sortie confirmée : ${fmtDate(conf)} (${age}).`
         + (tentee ? ` Une tentative plus récente (${fmtDate(tentee.date)}) n'a PAS été confirmée.` : '') };
}

// Demande la confirmation APRÈS un partage/téléchargement. Honnête sur son ignorance.
// Ne ment jamais dans les deux sens : ni « c'est sauvegardé », ni « ça a échoué ».
function sortieDemandeConfirmation(canal, nomFichier){
  const ou = (canal === 'icloud') ? 'dans iCloud Drive (ou Fichiers)' : 'à l\'endroit de ton choix';
  const ok = confirm(
    `Le fichier ${nomFichier ? '« ' + nomFichier +' » ' : ''}a été remis à iOS.\n\n`
  + `L'app ne peut PAS vérifier qu'il a bien été enregistré ${ou} — c'est une limite d'iOS, `
  + `pas une précaution de style.\n\n`
  + `As-tu bien vu l'enregistrement se faire ?\n\n`
  + `• OK  → la sortie est comptée comme CONFIRMÉE, le rappel s'éteint.\n`
  + `• Annuler → rien n'est compté, le rappel reste actif (aucune pénalité).`);
  if(ok){ sortieMarqueConfirmee(canal); return true; }
  return false;
}

function exportReminderDays(){
  const s=getSettings();
  const n=parseInt(s.exportReminderDays,10);
  return (n&&n>0)?n:EXPORT_REMINDER_DAYS_DEFAULT;
}
// Texte d'état de la dernière sauvegarde iCloud (pour l'écran Sauvegarde).
function lastICloudInfo(){
  const last=localStorage.getItem('sm_lastICloud');
  if(!last) return {txt:'Aucune sauvegarde iCloud enregistrée pour le moment.', jours:null};
  const d=daysTo(last);
  const age = (d===0||d===null) ? "aujourd'hui" : `il y a ${Math.abs(d)} j`;
  return {txt:`Dernière sauvegarde iCloud : <b>${fmtDate(last)}</b> (${age}).`, jours:d};
}
async function exportReminder(){
  const freq=exportReminderDays();
  const last = localStorage.getItem('sm_lastExport');
  const snooze = localStorage.getItem('sm_exportSnooze'); // date jusqu'à laquelle on ne redemande pas
  if(snooze){ const ds=daysTo(snooze); if(ds!==null && ds>=0) return; } // encore en sommeil
  // nombre d'enregistrements à risque (donne du poids au message)
  let nb=0; try{ for(const t of ['orders','productions','clients','materialLots']){ nb+=await db.table(t).count(); } }catch(e){swallow(e,'exportReminder')}
  // [v1385 · CHANTIER C] L'état de sortie ne se déduit plus d'une supposition : seules les
  // sorties CONFIRMÉES comptent. Une tentative non confirmée est signalée comme telle.
  const etat = sortieEtat(freq);
  const overdue = etat.enRetard && (etat.jamais ? nb>0 : true);
  const ageTxt = etat.texte;
  if(!overdue) return;
  openModal(`<h3>💾 Sauvegarde recommandée</h3>
    <div class="banner" style="background:#fdf3f2;border-color:#f0c9c4"><div>${ageTxt} iOS peut purger les données de l'app (effacer l'historique Safari supprime aussi la base). Mets une copie à l'abri sur iCloud Drive.</div></div>
    <p class="note" style="margin:8px 0">${nb} enregistrement(s) clés actuellement sur l'appareil.</p>
    <div class="modal-actions" style="flex-direction:column;gap:8px">
      <button class="btn gold" style="width:100%" onclick="closeModal();shareBackupToICloud()">☁️ Sauvegarder sur iCloud</button>
      <button class="btn ghost" style="width:100%" onclick="closeModal();exportData()">⬇ Exporter le fichier (.json)</button>
      <button class="btn ghost" style="width:100%" onclick="closeModal();goView('sauvegardes')">Ouvrir Sauvegarde &amp; sécurité</button>
      <button class="btn ghost" style="width:100%" onclick="exportSnooze(1)">Me le rappeler demain</button>
    </div>`);
}
// Reporte le rappel de n jours.
function exportSnooze(days){
  const d=new Date(); d.setDate(d.getDate()+(days||1));
  localStorage.setItem('sm_exportSnooze', ymdLocal(d));
  closeModal();
  toast('Rappel reporté ✓');
}

/* ============================================================
   SERVICE WORKER — détection de mise à jour + invite « Recharger »
   skipWaiting est piloté par l'utilisateur (pas automatique).
   ============================================================ */
// Numéro de version affiché en bas de l'app : permet de vérifier d'un coup d'œil
// quelle version tourne réellement (utile en cas de doute sur le cache PWA).
window.addEventListener('load', ()=>{
  try{
    if(document.getElementById('appVersionBadge')) return;
    const b=document.createElement('div');
    b.id='appVersionBadge';
    b.textContent=APP_VERSION;
    b.style.cssText='position:fixed;right:6px;bottom:4px;z-index:9999;font-size:.62rem;color:#b8a99f;background:rgba(255,255,255,.6);padding:1px 6px;border-radius:8px;pointer-events:none;font-family:system-ui,sans-serif';
    document.body.appendChild(b);
  }catch(e){swallow(e,'exportSnooze')}
});
let _swReg=null, _swReloading=false;
function showUpdateBanner(worker){
  if(document.getElementById('updateBanner')) return; // déjà affichée
  const div=document.createElement('div');
  div.id='updateBanner';
  div.innerHTML=`<span>Une nouvelle version est disponible.</span>
    <button type="button" id="updateReload">Recharger l'application</button>
    <button type="button" id="updateDismiss" aria-label="Ignorer">✕</button>`;
  document.body.appendChild(div);
  div.querySelector('#updateReload').addEventListener('click', ()=>{
    if(worker){ worker.postMessage({type:'SKIP_WAITING'}); }
    else { location.reload(); }
  });
  div.querySelector('#updateDismiss').addEventListener('click', ()=>div.remove());
}
if('serviceWorker' in navigator){
  window.addEventListener('load', ()=>{
    navigator.serviceWorker.register('./service-worker.js').then(reg=>{
      _swReg=reg;
      reg.update().catch(()=>{}); // vérifie tout de suite s'il existe une version plus récente
      // une version est déjà en attente (installée mais pas active) → proposer le rechargement
      if(reg.waiting && navigator.serviceWorker.controller){ showUpdateBanner(reg.waiting); }
      // une nouvelle version commence à s'installer → l'attendre puis proposer
      reg.addEventListener('updatefound', ()=>{
        const nw=reg.installing; if(!nw) return;
        nw.addEventListener('statechange', ()=>{
          // installée + un contrôleur existe déjà = ce n'est pas la 1ère install → maj dispo
          if(nw.state==='installed' && navigator.serviceWorker.controller){ showUpdateBanner(reg.waiting||nw); }
        });
      });
    }).catch(()=>{});
    // quand le nouveau SW prend le contrôle (après SKIP_WAITING), on recharge une seule fois
    navigator.serviceWorker.addEventListener('controllerchange', ()=>{
      if(_swReloading) return; _swReloading=true; location.reload();
    });
  });
  // vérifie l'existence d'une mise à jour quand l'app revient au premier plan
  document.addEventListener('visibilitychange', ()=>{
    if(document.visibilityState==='visible' && _swReg){ _swReg.update().catch(()=>{}); }
  });
}

// POPUP D'ALERTE PRÉVISIONNELLE — affichée à l'ouverture (1×/jour) et après création/modif de commande.
// Toujours recalculée sur les données réelles du jour.
async function showForecastPopup(opts){
  opts=opts||{};
  // ne pas recouvrir une fenêtre déjà ouverte (ex. alerte de cohérence au démarrage)
  if(overlay && overlay.classList.contains('show')) return;
  let alertes;
  try{ alertes = await forecastAlerts(); }catch(e){ return; }
  if(!alertes || !alertes.length) return;
  // anti-spam : à l'ouverture, une fois par jour seulement (sauf appel forcé après une commande)
  if(opts.daily){
    if(localStorage.getItem('sm_forecastSeen')===today()) return;
    localStorage.setItem('sm_forecastSeen', today());
  }
  const lignes = alertes.slice(0,8).map(a=>{
    const d = a.firstShortDate ? `${fmtDate(a.firstShortDate)}${a.firstShortDans!=null?` (J−${Math.max(0,a.firstShortDans)})`:''}` : '';
    return `<div class="sum-box"><span>⚠ <b>${esc(a.parfum)}</b>${d?` · ${d}`:''}</span><b style="color:var(--red,#b3261e)">manque ${qty(a.manque||0)}</b></div>`;
  }).join('');
  openModal(`<h3>⚠ Risque de rupture</h3>
    <p class="note">${alertes.length} parfum(s) risque(nt) la rupture pour une livraison sous 8 jours, d'après le stock fini actuel et les commandes à venir.</p>
    ${lignes}
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Plus tard</button>
      <button class="btn gold" onclick="closeModal();view='previsionnel';setActiveView&&setActiveView('previsionnel');renderForecast()">Voir le prévisionnel</button>
    </div>`);
}

/* ============================================================
   POINTEUSE DE LABORATOIRE — time tracker global
   100% offline, résilient à la mise en veille PWA.
   Principe : on stocke uniquement le timestamp de DÉMARRAGE dans
   localStorage. Le temps écoulé est TOUJOURS recalculé depuis
   Date.now() − start (jamais d'accumulation via setInterval, qui
   se fige quand iOS suspend l'app). Le tick ne sert qu'à rafraîchir
   l'affichage ; la source de vérité reste le timestamp stocké.
   ============================================================ */
// ===== POINTEUSE MULTI-CHRONOS (sessions parallèles indépendantes) =====
// Chaque chrono : {id, start(ms), activite, pausedAccum(ms), pauseAt(ms|0)}.
// Stocké en JSON dans localStorage. Chacun a sa pause et son stop individuels.
const TT_SESSIONS_KEY = 'sm_ttSessions';
// Anciennes clés (mono-session) — pour migration au démarrage.
const TT_KEY = 'sm_workSession_start';
const TT_PAUSED_KEY = 'sm_workSession_paused';
const TT_PAUSE_AT_KEY = 'sm_workSession_pauseAt';
const TT_ACT_KEY = 'sm_workSession_act';
// Catégories HORS-PRODUCTION : la pointeuse mesure le temps de travail qui ne passe pas
// par l'atelier (lequel gère toute la production). Zéro chevauchement → temps total fiable.
const TT_ACTIVITIES = ['Déplacements / livraisons','Administratif','Courses','Préparation marché','Préparation commande','Relations commerciales / prospection / réseautage','Autre'];

// ============================================================================
//  MODULE PRODUCTION — SOCLE (étape 1 : catalogue de tâches)
//  Module INDÉPENDANT : il observe et documente le temps de travail, sans jamais
//  contraindre les autres modules. Sert à nourrir l'analyse / l'optimisation des KPI.
//
//  Modèle :
//    Session de production (datée) ──contient──> Tâches labellisées (chronos parallèles)
//  Les tâches peuvent se chevaucher dans le temps (ex. cuisson + meringue suivante).
// ============================================================================

// Catalogue des tâches, groupées par phase. La phase porte une couleur (barres du tableau blanc).
// Modifiable : l'utilisateur peut ajouter ses propres tâches (stockées dans les réglages).
const PROD_TASK_CATALOG = [
  { phase:'Préparation ganache', color:'#7a4b2a', tasks:[
    'Pesée des ingrédients',
    'Émulsion',
  ]},
  { phase:'Préparation', color:'#c1a27c', tasks:[
    'Pesée du tant pour tant (poudre d\'amandes + sucre glace)',
    'Pesée des ingrédients meringue (eau, blanc d\'œuf en poudre, sucre semoule)',
  ]},
  { phase:'Meringue', color:'#caa23b', tasks:[
    'Mise en chauffe de la meringue',
    'Foisonnement de la meringue',
    'Rajout colorant',
    'Foisonnement meringue après division',
    'Pesée de la meringue pour division',
  ]},
  { phase:'Macaronnage', color:'#aa7c39', tasks:[
    'Incorporation du tant pour tant à la meringue',
    'Macaronnage',
    'Pochage',
    'Tapage des plaques',
    'Claquage des bulles',
  ]},
  { phase:'Cuisson', color:'#c0392b', tasks:[
    'Cuisson des coques',
    'Refroidissement des coques',
  ]},
  { phase:'Garnissage', color:'#3f7d52', tasks:[
    'Préparation de la ganache pour pochage',
    'Pochage de la ganache',
    'Assemblage des coques (finition macaron)',
  ]},
  { phase:'Finition / Manipulation coques', color:'#9a6f9e', tasks:[
    'Mise en congélation des coques',
    'Appairage des coques',
    'Rangement des coques en boîte',
    'Re-disposition des coques avant garnissage',
  ]},
  { phase:'Entretien', color:'#5a8aa0', tasks:[
    'Vaisselle',
    'Nettoyage des surfaces (plan de maîtrise sanitaire)',
  ]},
];

// ============================================================
// TÂCHES SPÉCIFIQUES À CERTAINES RECETTES
// ------------------------------------------------------------
// Ces tâches n'apparaissent dans le chrono QUE pour les parfums concernés.
// L'association se fait par mot-clé (match partiel sur le nom normalisé via aiNormalize),
// + une règle "grand format" branchée sur le champ existant recipe.grandFormat.
// `phase`/`color` situent la tâche dans le catalogue ; `keywords` = mots-clés de parfums
// concernés ; `grandFormat:true` = s'applique aussi à toute recette grand format.
// ============================================================
const PROD_TASK_SPECIFIQUES = [
  { label:'Chablonnage des coques', phase:'Préparation des coques (avant garnissage)', color:'#d08a4a',
    keywords:['citron creme','citron cremeux','framboise','coco citron vert','chocolat noir valrhona','chocolat noir','valrhona'], grandFormat:true },
  { label:'Préparation des noisettes (couper en deux)', phase:'Préparation', color:'#c1a27c',
    keywords:['cannelle noisette','praline','coco rafaello'], grandFormat:false },
  { label:'Rajout des noisettes dans les coques', phase:'Préparation des coques (avant garnissage)', color:'#d08a4a',
    keywords:['cannelle noisette','praline','coco rafaello'], grandFormat:false },
  { label:'Coup de pinceau de poudre dorée (décor)', phase:'Finition / Manipulation coques', color:'#9a6f9e',
    keywords:['nocciolata'], grandFormat:false },
];

// Ordre de référence des phases (= déroulé d'une production). Sert à trier les groupes
// dans les sélecteurs, y compris les phases qui n'arrivent que via les tâches spécifiques
// (ex. « Préparation des coques (avant garnissage) » entre Cuisson et Garnissage).
const PROD_PHASE_ORDER = [
  'Préparation ganache',
  'Préparation',
  'Meringue',
  'Macaronnage',
  'Cuisson',
  'Préparation des coques (avant garnissage)',
  'Garnissage',
  'Finition / Manipulation coques',
  'Entretien',
  'Personnalisé',
];
function prodPhaseRank(phase){
  const i = PROD_PHASE_ORDER.indexOf(phase);
  return i<0 ? PROD_PHASE_ORDER.length : i;   // phases inconnues à la fin
}
// Trie une liste de noms de phases selon l'ordre de référence.
function prodSortPhases(phases){
  return phases.slice().sort((a,b)=>prodPhaseRank(a)-prodPhaseRank(b));
}

// Retourne les tâches spécifiques applicables à une recette donnée (objet recipe).
// Match partiel : le nom normalisé de la recette CONTIENT le mot-clé.
function prodTachesSpecifiques(recipe){
  if(!recipe) return [];
  const nom = (typeof aiNormalize==='function') ? aiNormalize(recipe.produitNom||'') : (recipe.produitNom||'').toLowerCase();
  const out = [];
  PROD_TASK_SPECIFIQUES.forEach(sp=>{
    let ok = (sp.keywords||[]).some(k=>nom.includes(aiNormalize(k)));
    if(!ok && sp.grandFormat && recipe.grandFormat) ok = true;   // grand format → auto
    if(ok) out.push({label:sp.label, phase:sp.phase, color:sp.color, specifique:true});
  });
  return out;
}

// Variante par recipeId (asynchrone, va chercher la recette).
// Liste à plat de toutes les tâches connues (catalogue + ajouts perso de l'utilisateur).
function prodAllTasks(recipe){
  const custom = (getSettings().prodCustomTasks||[]);
  const base = [];
  PROD_TASK_CATALOG.forEach(g=>g.tasks.forEach(t=>base.push({label:t, phase:g.phase, color:g.color})));
  custom.forEach(c=>{
    if(typeof c==='string') base.push({label:c, phase:'Personnalisé', color:'#8a7a72'});
    else if(c && c.label) base.push({label:c.label, phase:c.phase||'Personnalisé', color:c.color||'#8a7a72'});
  });
  // Tâches spécifiques de la recette courante (n'apparaissent que pour les parfums concernés).
  if(recipe){
    const spec = prodTachesSpecifiques(recipe);
    spec.forEach(sp=>{
      if(!base.some(b=>b.label===sp.label)) base.push({label:sp.label, phase:sp.phase, color:sp.color, specifique:true});
    });
  }
  return base;
}
// Retrouve la couleur/phase d'une tâche par son label (pour les barres).
function prodTaskMeta(label){
  const found = prodAllTasks().find(t=>t.label===label);
  return found || {label:label||'Tâche', phase:'Autre', color:'#8a7a72'};
}
let _ttTick = null;

// ---- Stockage des SESSIONS DE PRODUCTION (indépendant, persistant) ----
// Structure d'une session :
//   { id, date:'YYYY-MM-DD', start:ms, end:ms|null, note:'',
//     tasks:[ { id, label, phase, color, start:ms, end:ms|null,
//               pausedAccum:ms, pauseAt:ms|null } ] }
// Les tâches en cours ont end=null. Une session est « ouverte » tant que end=null.
const PROD_SESS_KEY = 'sm_prodSessions';
// Registre des sessions supprimées VOLONTAIREMENT (tombstones). Sans lui, la réhydratation
// depuis IndexedDB ne distingue pas « session perdue par purge iOS » (à restaurer) de
// « session supprimée exprès » (à ne jamais faire revenir) → la suppression revenait au reboot.
const PROD_SESS_DELETED_KEY = 'sm_prodSessDeleted';
function prodSessDeletedIds(){
  try{ const a=JSON.parse(localStorage.getItem(PROD_SESS_DELETED_KEY)||'[]'); return Array.isArray(a)?a:[]; }
  catch(e){ return []; }
}
function prodSessMarkDeleted(id){
  try{
    const ids=prodSessDeletedIds();
    if(!ids.includes(id)){ ids.push(id); localStorage.setItem(PROD_SESS_DELETED_KEY, JSON.stringify(ids)); }
  }catch(e){swallow(e,'prodSessMarkDeleted')}
}
function prodSessLoad(){
  try{ const a=JSON.parse(localStorage.getItem(PROD_SESS_KEY)||'[]'); return Array.isArray(a)?a:[]; }
  catch(e){ return []; }
}
// Écrit le cache localStorage (synchrone) ET persiste dans IndexedDB (asynchrone, non bloquant).
// IndexedDB est la source de vérité anti-purge ; le localStorage reste un cache rapide pour
// toutes les lectures synchrones existantes (prodSessLoad), inchangées.
function prodSessSave(arr){
  const data = arr||[];
  try{ localStorage.setItem(PROD_SESS_KEY, JSON.stringify(data)); }
  catch(e){ console.error('prodSessSave', e); }
  prodSessPersistDexie(data);
}
// Synchronise l'état complet des sessions vers la table Dexie prodSessions.
// On remplace l'ensemble (bulkPut + suppression des absents) pour rester aligné sur le cache.
// En cas d'échec, on le SIGNALE (les chronos ne seraient alors qu'en localStorage fragile).
async function prodSessPersistDexie(arr){
  try{
    // Garde-fou renforcé : la table doit exister ET avoir ses méthodes. Si la migration de schéma
    // a échoué (base bloquée), db.prodSessions peut exister sans bulkPut → on signale et on sort
    // proprement au lieu de planter, en invitant à réparer la base.
    if(!db.prodSessions || typeof db.prodSessions.bulkPut !== 'function'){
      prodSessFlagDexieKo('base à réparer (migration incomplète)');
      return false;
    }
    const data = arr||[];
    const ids = new Set(data.map(s=>s.id));
    await db.transaction('rw', db.prodSessions, async()=>{
      const existing = await db.prodSessions.toArray();
      const toDelete = existing.filter(s=>!ids.has(s.id)).map(s=>s.id);
      if(toDelete.length) await bulkDeleteSafe(db.prodSessions, toDelete);
      if(data.length) await db.prodSessions.bulkPut(data);
    });
    // Vérification : relire le nombre d'enregistrements pour confirmer l'écriture réelle.
    const count = await db.prodSessions.count();
    if(count < data.length){ prodSessFlagDexieKo('écriture incomplète'); return false; }
    prodSessClearDexieKo();
    return true;
  }catch(e){ console.error('prodSessPersistDexie', e); prodSessFlagDexieKo(e&&e.message||'erreur'); return false; }
}
// Mémorise qu'une persistance Dexie a échoué (affiché en alerte sur l'écran Atelier).
function prodSessFlagDexieKo(motif){ try{ localStorage.setItem('sm_prodSessDexieKo', motif||'1'); }catch(e){swallow(e,'prodSessFlagDexieKo')} }
function prodSessClearDexieKo(){ try{ localStorage.removeItem('sm_prodSessDexieKo'); }catch(e){swallow(e,'prodSessClearDexieKo')} }
function prodSessDexieKo(){ try{ return localStorage.getItem('sm_prodSessDexieKo')||''; }catch(e){ return ''; } }
// RÉPARATION : force la fermeture/réouverture de la base pour relancer la migration de schéma
// (cas d'une base bloquée où prodSessions n'a pas été créée correctement). Préserve les sessions
// du cache localStorage et les réinjecte une fois la table disponible.
async function reparerBaseSessions(){
  if(!confirm('Réparer la base de données ?\nTes sessions en mémoire seront préservées.')) return;
  let sauvegarde=[];
  try{ sauvegarde = JSON.parse(localStorage.getItem(PROD_SESS_KEY)||'[]'); if(!Array.isArray(sauvegarde)) sauvegarde=[]; }catch(e){ sauvegarde=[]; }
  // Test RÉEL de la table : on tente un count(). S'il réussit, la table est opérationnelle —
  // on efface le flag même s'il n'y a aucune session (sinon l'alerte resterait affichée à tort).
  async function tableOK(){
    try{
      if(!db.prodSessions || typeof db.prodSessions.count!=='function') return false;
      await db.prodSessions.count();   // opération réelle : lève si la table n'existe pas vraiment
      return true;
    }catch(e){ return false; }
  }
  try{
    // 1) test direct sans rien fermer (la base est peut-être déjà bonne → faux positif du flag)
    if(await tableOK()){
      if(sauvegarde.length){ try{ await db.prodSessions.bulkPut(sauvegarde); }catch(e){swallow(e,'reparerBaseSessions')} }
      prodSessClearDexieKo();
      toast('Base déjà fonctionnelle ✓ — alerte levée');
      if(typeof renderAtelier==='function') renderAtelier();
      return;
    }
    // 2) sinon, on tente une vraie réouverture pour relancer la migration
    try{ db.close(); }catch(e){swallow(e,'reparerBaseSessions')}
    await db.open();
    if(await tableOK()){
      if(sauvegarde.length){ try{ await db.prodSessions.bulkPut(sauvegarde); }catch(e){swallow(e,'reparerBaseSessions')} }
      prodSessClearDexieKo();
      toast('Base réparée ✓ — sessions préservées');
    } else {
      toast('Migration bloquée : ferme TOTALEMENT l\'app ET Safari, attends 5 s, puis rouvre UNE seule fenêtre');
    }
  }catch(e){
    console.error('reparerBaseSessions', e);
    toast('Ferme complètement l\'app (et Safari) puis rouvre pour finaliser');
  }
  if(typeof renderAtelier==='function') renderAtelier();
}
// Réhydratation au démarrage : si IndexedDB contient des sessions absentes du localStorage
// (cas typique d'une purge iOS du localStorage), on les réinjecte dans le cache.
// IndexedDB fait foi : toute session présente en base mais perdue du cache est restaurée.
async function prodSessHydrate(){
  try{
    if(!db.prodSessions) return;
    const fromDexie = await db.prodSessions.toArray();
    // Si on arrive ici, la table prodSessions répond → elle est opérationnelle. On lève donc
    // tout flag « base à réparer » resté affiché à tort (ex. faux positif sans session à écrire).
    if(typeof prodSessClearDexieKo==='function') prodSessClearDexieKo();
    const cache = prodSessLoad();
    // Migration initiale (1re ouverture en v11) : des sessions existent en localStorage
    // mais la table Dexie est vide → on les y copie pour les mettre à l'abri.
    if(!fromDexie.length){
      if(cache.length) await prodSessPersistDexie(cache);
      return;
    }
    // Cas nominal : IndexedDB fait foi. On fusionne cache + base en gardant, pour chaque id,
    // la version la PLUS RÉCENTE (_ts). Ça restaure les sessions perdues du cache (purge iOS)
    // ET évite qu'une version Dexie périmée n'écrase une modif récente encore en cache.
    // MAIS on ne restaure JAMAIS une session supprimée volontairement (tombstone).
    const deleted = new Set(prodSessDeletedIds());
    const byId = new Map(cache.map(s=>[s.id, s]));
    let restored = 0, refreshed = 0, purged = 0;
    fromDexie.forEach(s=>{
      if(deleted.has(s.id)){
        // session supprimée exprès mais encore présente en base → on la purge de Dexie pour de bon
        try{ if(db.prodSessions && db.prodSessions.delete) db.prodSessions.delete(s.id).catch(()=>{}); }catch(e){swallow(e,'prodSessHydrate')}
        purged++;
        return;
      }
      const cur = byId.get(s.id);
      if(!cur){ byId.set(s.id, s); restored++; }
      else if((+s._ts||0) > (+cur._ts||0)){ byId.set(s.id, s); refreshed++; }
    });
    if(restored>0 || refreshed>0){
      const merged = Array.from(byId.values());
      try{ localStorage.setItem(PROD_SESS_KEY, JSON.stringify(merged)); }catch(e){swallow(e,'prodSessHydrate')}
      // on re-persiste la fusion pour réaligner la base sur la vérité fusionnée
      prodSessPersistDexie(merged);
      console.log('prodSessHydrate: '+restored+' restaurée(s), '+refreshed+' rafraîchie(s), '+purged+' purgée(s)');
    } else if(purged>0){
      console.log('prodSessHydrate: '+purged+' session(s) supprimée(s) purgée(s) de la base');
    }
  }catch(e){ console.error('prodSessHydrate', e); }
}
function prodSessGet(id){ return prodSessLoad().find(s=>s.id===id); }
function prodSessUpsert(sess){
  sess._ts = Date.now();   // horodatage de dernière modification (arbitrage de fraîcheur)
  const a=prodSessLoad(); const i=a.findIndex(s=>s.id===sess.id);
  if(i>=0) a[i]=sess; else a.push(sess);
  prodSessSave(a);
  try{ if(typeof prodTransInvalidate==='function') prodTransInvalidate(); }catch(e){swallow(e,'prodSessUpsert')}
}
function prodSessRemove(id){
  prodSessMarkDeleted(id);                                  // 1) marque comme supprimée définitivement
  prodSessSave(prodSessLoad().filter(s=>s.id!==id));        // 2) retire du cache + re-persiste (bulkDelete des absents)
  // 3) suppression Dexie EXPLICITE (ceinture + bretelles : ne dépend pas du diff de bulkDelete)
  try{
    if(db.prodSessions && typeof db.prodSessions.delete==='function'){
      db.prodSessions.delete(id).catch(()=>{});
    }
  }catch(e){swallow(e,'prodSessRemove')}
}

// ===================== ATELIER — TÂCHES SEMI-PASSIVES & COUPURE INTELLIGENTE =====================
// Une tâche « semi-passive » tourne toute seule (cuisson, repos, foisonnement…) : elle ne se coupe
// JAMAIS au lancement d'une autre tâche. Elle a un minuteur ; à la sonnerie, le chrono se met en pause
// et l'utilisateur choisit de Terminer ou de Prolonger. Une tâche « active » (pesée, pochage…) est
// manuelle : lancer une nouvelle active coupe l'active en cours DU MÊME PARFUM.
//
// Durées par défaut (minutes), modifiables au lancement. La liste est volontairement courte ; tout le
// reste est « actif ». L'utilisateur ajustera à l'usage.
const PROD_PASSIVE_DEFAULTS = {
  'Mise en chauffe de la meringue': 4,
  'Foisonnement de la meringue': 8,
  'Foisonnement meringue après division': 6,
  'Cuisson des coques': 21,
  'Refroidissement des coques': 15,
  'Mise en congélation des coques': 30,
};

// Une tâche est-elle semi-passive ? (par label exact, robustesse via inclusion de mots-clés)
function prodIsPassive(label){
  if(!label) return false;
  if(PROD_PASSIVE_DEFAULTS[label]!=null) return true;
  const l = label.toLowerCase();
  return /cuisson|refroidiss|foisonn|cong[ée]l|cristallis|repos|mise en chauffe/.test(l);
}
// Durée par défaut (minutes) d'une semi-passive, sinon null.
function prodPassiveDefaultMin(label){
  if(PROD_PASSIVE_DEFAULTS[label]!=null) return PROD_PASSIVE_DEFAULTS[label];
  // réglage perso éventuel mémorisé
  try{ const s=getSettings(); const m=(s.prodPassiveMin||{})[label]; if(m!=null) return +m; }catch(e){swallow(e,'prodPassiveDefaultMin')}
  if(prodIsPassive(label)) return 10; // valeur de repli raisonnable
  return null;
}
// Mémorise la durée choisie pour une tâche (devient le défaut la prochaine fois).
function prodPassiveRememberMin(label, min){
  try{ const s=getSettings(); s.prodPassiveMin=s.prodPassiveMin||{}; s.prodPassiveMin[label]=+min; saveSettings(s); }catch(e){swallow(e,'prodPassiveRememberMin')}
}

// Détermine quelles tâches actives en cours doivent être coupées quand on lance `label` pour `recipeId`.
// Règle : on coupe UNIQUEMENT les tâches ACTIVES, non terminées, rattachées au MÊME parfum (recipeId).
// Les semi-passives ne sont jamais coupées ici. Les tâches d'autres parfums ne sont jamais touchées.
// Retourne la liste des taskId à clôturer.
function prodTasksToCutOnStart(session, recipeId){
  if(!session || !Array.isArray(session.tasks)) return [];
  return session.tasks.filter(t=>{
    if(t.end) return false;                          // déjà terminée
    if(prodIsPassive(t.label)) return false;         // semi-passive : on ne coupe pas
    // même parfum ? une tâche sans parfum rattaché est considérée transverse → on la coupe aussi
    const parfs = Array.isArray(t.parfums)?t.parfums:[];
    if(recipeId==null) return parfs.length===0;      // tâche transverse coupe transverse
    return parfs.length===0 || parfs.map(Number).includes(+recipeId);
  }).map(t=>t.id);
}
// =============================================================================


// ===================== ATELIER — ALARME DES TÂCHES SEMI-PASSIVES =====================
// Une semi-passive est lancée avec une durée (minutes). À l'échéance, le chrono se met en PAUSE
// (temps de jugement non compté) et l'état « sonne » s'affiche. L'utilisateur Termine, ou Prolonge
// de N minutes (le minuteur repart, l'échéance recule, le temps additionnel s'ajoutera). Son+vibration
// uniquement quand l'app est ouverte (contrainte iOS assumée).

// Démarre une tâche en gérant la coupure intelligente + l'alarme si semi-passive.
// opts: { recipeId, durMin } (durMin seulement pour semi-passives ; sinon défaut).
function prodTaskStartSmart(label, opts){
  opts = opts||{};
  // Parfums à rattacher : priorité à opts.parfums[] (mode mutualisé / multi), sinon opts.recipeId.
  let parfums = [];
  if(Array.isArray(opts.parfums) && opts.parfums.length){ parfums = opts.parfums.map(Number).filter(r=>Number.isFinite(r)); }
  else if(opts.recipeId!=null){ parfums = [+opts.recipeId]; }
  const parfumPrincipal = parfums.length ? parfums[0] : null;
  const s = prodSessionStart();
  // 1) Coupure : fermer les actives du même parfum (jamais passives / autres parfums)
  const toCut = prodTasksToCutOnStart(s, parfumPrincipal);
  toCut.forEach(id=>{ const t=(s.tasks||[]).find(x=>x.id===id); if(t && !t.end){
    if(prodTaskPaused(t)){ t.pausedAccum=(+t.pausedAccum||0)+Math.max(0,Date.now()-(+t.pauseAt)); t.pauseAt=null; }
    t.end=Date.now();
  }});
  // 2) Créer la nouvelle tâche
  const meta = prodTaskMeta(label);
  const passive = prodIsPassive(label);
  const durMin = passive ? (opts.durMin!=null ? +opts.durMin : prodPassiveDefaultMin(label)) : null;
  const t = { id:prodNewId(), label:meta.label, phase:meta.phase, color:meta.color,
              start:Date.now(), end:null, pausedAccum:0, pauseAt:null,
              passive:passive, durMin:durMin,
              alarmAt: passive ? (Date.now()+durMin*60000) : null,
              ringing:false,
              parfums: parfums.slice() };
  if(passive && opts.durMin!=null) prodPassiveRememberMin(label, opts.durMin);
  s.tasks=s.tasks||[]; s.tasks.push(t);
  prodSessUpsert(s);
  prodStartTicking();
  // Rattachement auto SEULEMENT si aucun parfum n'a été fourni (ni recipeId ni parfums[]).
  if(!parfums.length){ try{ prodTaskAutoRattach(t.id); }catch(e){swallow(e,'prodTaskStartSmart')} }
  return t;
}

// Vérifie les alarmes échues parmi les tâches en cours ; pour chacune, met le chrono en pause de
// jugement et marque ringing. Retourne true si au moins une nouvelle alarme a sonné (→ son/vibration).
function prodCheckAlarms(){
  const s = prodSessActive(); if(!s) return false;
  let rang=false;
  (s.tasks||[]).forEach(t=>{
    if(t.end || !t.passive || t.ringing) return;
    if(t.alarmAt && Date.now()>=t.alarmAt){
      t.ringing = true;
      if(!prodTaskPaused(t)) t.pauseAt = t.alarmAt;  // pause à l'instant exact de l'échéance
      rang=true;
    }
  });
  if(rang) prodSessUpsert(s);
  return rang;
}

// Termine définitivement une tâche qui sonne (durée réelle = temps minuté, pause de jugement exclue).
function prodAlarmFinish(taskId){
  const s = prodSessActive(); if(!s) return;
  const t = (s.tasks||[]).find(x=>x.id===taskId); if(!t) return;
  if(prodTaskPaused(t)){ t.pausedAccum=(+t.pausedAccum||0)+Math.max(0,Date.now()-(+t.pauseAt)); t.pauseAt=null; }
  t.ringing=false; t.end=Date.now();
  prodSessUpsert(s);
  if(!prodAnyRunning()) prodStopTicking();
}

// Prolonge une tâche qui sonne de addMin minutes : le minuteur repart, l'échéance recule, le temps de
// pause de jugement n'est pas compté (on l'ajoute à pausedAccum), le total minuté s'additionnera.
function prodAlarmExtend(taskId, addMin){
  const s = prodSessActive(); if(!s) return;
  const t = (s.tasks||[]).find(x=>x.id===taskId); if(!t) return;
  addMin = Math.max(1, +addMin||1);
  // clore la pause de jugement (ce temps ne compte pas dans la durée réelle)
  if(prodTaskPaused(t)){ t.pausedAccum=(+t.pausedAccum||0)+Math.max(0,Date.now()-(+t.pauseAt)); t.pauseAt=null; }
  t.ringing=false;
  t.alarmAt = Date.now()+addMin*60000;  // nouvelle échéance
  t.durMin = (+t.durMin||0)+addMin;      // durée cible cumulée (pour info)
  prodSessUpsert(s);
  prodStartTicking();
}

// Joue un signal sonore + vibration (app ouverte). Best-effort, silencieux si non supporté.
function prodAlarmBeep(){
  try{
    const Ctx = window.AudioContext||window.webkitAudioContext;
    if(Ctx){
      const ctx = window._prodAudioCtx || (window._prodAudioCtx = new Ctx());
      const beep = (delay)=>{
        const o=ctx.createOscillator(), g=ctx.createGain();
        o.type='sine'; o.frequency.value=880;
        o.connect(g); g.connect(ctx.destination);
        const t0=ctx.currentTime+delay;
        g.gain.setValueAtTime(0.0001,t0);
        g.gain.exponentialRampToValueAtTime(0.3,t0+0.02);
        g.gain.exponentialRampToValueAtTime(0.0001,t0+0.35);
        o.start(t0); o.stop(t0+0.36);
      };
      beep(0); beep(0.45); beep(0.9);
    }
  }catch(e){swallow(e,'prodAlarmBeep')}
  try{ if(navigator.vibrate) navigator.vibrate([200,120,200,120,300]); }catch(e){swallow(e,'prodAlarmBeep')}
}
// =============================================================================


// ===================== ATELIER — MOTEUR D'APPRENTISSAGE DES ENCHAÎNEMENTS =====================
// Apprend, à partir de l'historique réel des sessions (db.prodSessions), dans quel ORDRE l'utilisateur
// enchaîne ses tâches — pondéré par le PARFUM concerné. Sert à proposer la prochaine étape probable
// et à reconstruire la « séquence type » d'une fournée. 100% lecture, aucun effet de bord.
//
// Modèle : pour chaque session, on ordonne les tâches par heure de début (start). Une « transition »
// est un couple (tâche A → tâche B) observé quand B suit immédiatement A. On compte ces transitions
// globalement ET par parfum (recipeId rattaché). On en déduit, pour une tâche donnée, la suite la
// plus fréquente.

// Charge toutes les sessions (table + cache localStorage), tolérant aux absences.
async function prodAllSessions(){
  let sess = [];
  try{ sess = await db.prodSessions.toArray(); }catch(e){ sess = []; }
  // fusion défensive avec le cache local éventuel (certaines sessions peuvent n'être qu'en cache)
  try{
    const raw = localStorage.getItem(PROD_SESS_KEY);
    if(raw){ const cache = JSON.parse(raw)||[]; 
      const ids = new Set(sess.map(s=>s.id));
      cache.forEach(s=>{ if(!ids.has(s.id)) sess.push(s); });
    }
  }catch(e){swallow(e,'prodAllSessions')}
  return sess;
}

// Construit l'index des transitions à partir d'une liste de sessions.
// Retourne { global:{A:{B:n}}, parParfum:{ recipeId:{A:{B:n}} }, freq:{A:n} }.
function prodBuildTransitions(sessions){
  const global = {};      // global[A][B] = nb d'observations A→B
  const parParfum = {};   // parParfum[recipeId][A][B] = nb
  const mutualise = {};   // mutualise[A][B] = nb, sur les tâches rattachées à 2+ parfums
  const freq = {};        // freq[A] = nb total de fois où A a été lancée
  const starts = {};      // starts[A] = nb de fois où A a été la PREMIÈRE tâche d'une session
  const startsMut = {};   // idem, mais première tâche mutualisée (2+ parfums) de la session

  const bump = (obj,a,b)=>{ (obj[a]=obj[a]||{})[b]=(obj[a][b]||0)+1; };

  (sessions||[]).forEach(s=>{
    const tasks = (s.tasks||[]).filter(t=>t && t.label && t.start!=null)
                               .slice().sort((x,y)=>(+x.start||0)-(+y.start||0));
    // Première tâche de la session (démarrage) — apprise à part.
    if(tasks.length){
      starts[tasks[0].label] = (starts[tasks[0].label]||0)+1;
      const firstMut = tasks.find(t=>Array.isArray(t.parfums) && t.parfums.filter(r=>r!=null).length>=2);
      if(firstMut) startsMut[firstMut.label] = (startsMut[firstMut.label]||0)+1;
    }
    for(let i=0;i<tasks.length;i++){
      const a = tasks[i].label;
      freq[a] = (freq[a]||0)+1;
      if(i+1<tasks.length){
        const b = tasks[i+1].label;
        bump(global,a,b);
        const parfs = Array.isArray(tasks[i].parfums)?tasks[i].parfums:[];
        parfs.forEach(rid=>{ parParfum[rid]=parParfum[rid]||{}; bump(parParfum[rid],a,b); });
        if(parfs.filter(r=>r!=null).length>=2){ bump(mutualise,a,b); }
      }
    }
  });
  return { global, parParfum, mutualise, freq, starts, startsMut };
}

// Cache mémoire de l'index (recalculé à la demande). Invalidé après écriture de session.
let _prodTransIndex = null;
async function prodTransIndex(force){
  if(_prodTransIndex && !force) return _prodTransIndex;
  const sessions = await prodAllSessions();
  _prodTransIndex = prodBuildTransitions(sessions);
  return _prodTransIndex;
}
function prodTransInvalidate(){ _prodTransIndex = null; }

// Suggère la/les prochaine(s) tâche(s) probable(s) après `lastLabel`, pour un parfum donné (recipeId).
// Si pas d'historique pour ce parfum, retombe sur le global. Si pas de lastLabel, propose les tâches
// de démarrage les plus fréquentes. Retourne un tableau de labels, ordonné par probabilité décroissante.
async function prodSuggestNext(recipeId, lastLabel, limit, opts){
  limit = limit||3;
  opts = opts||{};
  const idx = await prodTransIndex();
  const pickFrom = (table)=>{
    if(!lastLabel || !table[lastLabel]) return null;
    return Object.entries(table[lastLabel]).sort((a,b)=>b[1]-a[1]).map(e=>e[0]);
  };
  let res = null;
  if(opts.mutualise){
    // contexte mutualisé : 1) transitions mutualisées, 2) sinon global
    res = pickFrom(idx.mutualise) || null;
    if(!res) res = pickFrom(idx.global);
  } else {
    // 1) transitions du parfum, 2) sinon transitions globales
    res = (recipeId!=null && idx.parParfum[recipeId] && pickFrom(idx.parParfum[recipeId])) || null;
    if(!res) res = pickFrom(idx.global);
  }
  // 3) si toujours rien (pas de lastLabel ou inconnu) : suggestion de DÉMARRAGE de session.
  //    a) démarrages réellement appris (première tâche des sessions passées), b) sinon l'ordre
  //    naturel des phases du catalogue (la meringue avant la cuisson) — jamais la simple fréquence
  //    globale, qui faisait remonter des tâches de milieu de fournée (ex : « cuisson des coques »).
  if(!res){
    const startsTable = (opts.mutualise && idx.startsMut && Object.keys(idx.startsMut).length) ? idx.startsMut : idx.starts;
    const appris = startsTable ? Object.entries(startsTable).sort((a,b)=>b[1]-a[1]).map(e=>e[0]) : [];
    if(appris.length){
      res = appris;
    } else {
      // cold start : ordre du catalogue (première phase, première tâche…)
      res = (typeof prodStartSequence==='function') ? prodStartSequence() : Object.entries(idx.freq).sort((a,b)=>b[1]-a[1]).map(e=>e[0]);
    }
  }
  // [CONTEXTE COQUES/GANACHE] Si on connaît la famille de la tâche en cours (opts.contexteFamille),
  // on remonte les suggestions de la MÊME famille et on relègue l'autre en bas. Ex : tournée de coques
  // → les tâches coques d'abord, la ganache (souvent déjà faite) en fin de liste.
  if(res && opts.contexteFamille && opts.contexteFamille!=='autre'){
    const fam = opts.contexteFamille;
    res = res.slice().sort((a,b)=>{
      const fa = prodTaskFamille(a)===fam ? 0 : (prodTaskFamille(a)==='ganache' && fam==='coques' ? 2 : 1);
      const fb = prodTaskFamille(b)===fam ? 0 : (prodTaskFamille(b)==='ganache' && fam==='coques' ? 2 : 1);
      return fa-fb;   // tri stable : conserve l'ordre de probabilité au sein d'un même rang
    });
  }
  return (res||[]).slice(0, limit);
}
// Séquence de démarrage « par défaut » selon l'ordre naturel des phases du catalogue.
// Sert d'amorçage tant que l'app n'a pas assez d'historique pour apprendre tes habitudes.
function prodStartSequence(){
  try{
    const all = prodAllTasks();                 // catalogue à plat, dans l'ordre de définition
    // Amorçage orienté « tournée de coques » : on met la famille coques/meringue en tête et on
    // relègue la ganache en fin (elle est souvent déjà faite quand on démarre les coques). L'ordre
    // interne du catalogue est conservé au sein de chaque famille (préparation → meringue → …).
    const coques = all.filter(t=>prodTaskFamille(t.label)==='coques').map(t=>t.label);
    const autres = all.filter(t=>prodTaskFamille(t.label)==='autre').map(t=>t.label);
    const ganache = all.filter(t=>prodTaskFamille(t.label)==='ganache').map(t=>t.label);
    return [...coques, ...autres, ...ganache];
  }catch(e){ return []; }
}
// [FAMILLE DE TÂCHE] Deux grandes familles de travail dans une fournée :
//  - 'coques'  : tout ce qui touche la meringue et les coques (préparation, meringue, macaronnage,
//                cuisson, manipulation des coques). C'est le fil conducteur d'une tournée de coques.
//  - 'ganache' : la préparation et le pochage de la ganache (garnissage).
// Sert à recontextualiser les suggestions : si tu es sur les coques, on remonte les tâches coques
// et on relègue les tâches ganache en bas (la ganache est souvent déjà faite), sans les cacher.
function prodTaskFamille(label){
  const meta = (typeof prodTaskMeta==='function') ? prodTaskMeta(label) : {phase:''};
  const ph = meta.phase||'';
  if(ph==='Préparation ganache' || ph==='Garnissage') return 'ganache';
  if(ph==='Préparation' || ph==='Meringue' || ph==='Macaronnage' || ph==='Cuisson'
     || ph==='Préparation des coques (avant garnissage)' || ph==='Finition / Manipulation coques') return 'coques';
  return 'autre';
}

// Reconstruit une « séquence type » pour un parfum : on part de la tâche de démarrage la plus
// fréquente puis on suit la transition dominante, sans boucler, jusqu'à épuisement (max 25 étapes).
// =============================================================================

// La session ouverte du jour (end=null), s'il y en a une.
function prodSessActive(){ return prodSessLoad().find(s=>!s.end); }
// Générateur d'id simple et unique.
function prodNewId(){ return 'p'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }

// Durée nette d'une tâche (pauses déduites), en ms. Fonctionne tâche finie ou en cours.
// Plafond de sécurité pour une tâche restée OUVERTE (chrono oublié) : au-delà, on considère
// qu'elle n'a pas été arrêtée et on ne compte pas la durée absurde. Une vraie tâche d'atelier
// (pesée, pochage, cuisson, repos) ne dépasse pas ce seuil. N'affecte PAS les tâches terminées.
const PROD_TASK_OPEN_MAX_MS = 6*60*60*1000; // 6 heures
function prodTaskNet(t){
  const open = !t.end;
  const end = t.end || Date.now();
  let gross = Math.max(0, end - t.start);
  const accum = +t.pausedAccum||0;
  const live = (+t.pauseAt||0)>0 ? Math.max(0, Date.now()-(+t.pauseAt)) : 0;
  let net = Math.max(0, gross - accum - live);
  // Garde-fou : une tâche jamais terminée qui dépasse le plafond = chrono oublié → on borne.
  if(open && net > PROD_TASK_OPEN_MAX_MS) net = PROD_TASK_OPEN_MAX_MS;
  return net;
}
function prodTaskPaused(t){ return t && (+t.pauseAt||0)>0; }
// Durée RÉELLE d'une session (« mur à mur ») : enveloppe des tâches, du début de la première
// au end de la dernière. Reflète le temps réellement passé en tenant compte des CHEVAUCHEMENTS
// (tâches en parallèle), contrairement au cumul qui additionne des minutes superposées.
// On déduit les pauses globales communes à toutes les tâches (pas les chevauchements internes).
function prodSessReelMs(s){
  const tasks=(s&&s.tasks)||[];
  if(!tasks.length) return 0;
  let minStart=Infinity, maxEnd=0;
  tasks.forEach(t=>{
    const st=+t.start||0; const en=+t.end|| Date.now();
    if(st>0 && st<minStart) minStart=st;
    if(en>maxEnd) maxEnd=en;
  });
  if(!isFinite(minStart) || maxEnd<=minStart) return 0;
  return maxEnd-minStart;
}
// Cumul des durées de tâches (somme) : charge de travail si tout était fait à la chaîne.
function prodSessCumulMs(s){
  return ((s&&s.tasks)||[]).reduce((sum,t)=>sum+prodTaskNet(t),0);
}
// Une tâche est-elle en cours (non terminée) ?
function prodTaskRunning(t){ return t && !t.end; }
// Y a-t-il au moins une tâche en cours dans une session ouverte ?
function prodAnyRunning(){
  const s=prodSessActive(); if(!s) return false;
  return (s.tasks||[]).some(prodTaskRunning);
}

// ---- ACTIONS DE PILOTAGE (étape 2) ----
// Ouvre une nouvelle session de production (ou retourne celle déjà ouverte).
function prodSessionStart(note){
  let s = prodSessActive();
  if(s) return s;
  s = { id:prodNewId(), date:today(), start:Date.now(), end:null, note:note||'', tasks:[] };
  prodSessUpsert(s);
  return s;
}
// Clôture la session ouverte : arrête toutes ses tâches encore en cours, fixe l'heure de fin.
function prodSessionEnd(){
  const s = prodSessActive(); if(!s) return;
  const now = Date.now();
  (s.tasks||[]).forEach(t=>{ if(!t.end){ if(prodTaskPaused(t)){ t.pausedAccum=(+t.pausedAccum||0)+Math.max(0,now-(+t.pauseAt)); t.pauseAt=null; } t.end=now; } });
  s.end = now;
  prodSessUpsert(s);
  prodStopTicking();
  // Une session clôturée est une donnée précieuse, vulnérable à une suppression d'app : on
  // déclenche l'alerte « modifications non sauvegardées » pour rappeler de sauvegarder sur iCloud.
  if(typeof markUnsaved==='function') markUnsaved();
  // [TEMPS PAR PARFUM] Proposer la confirmation des parfums produits (croisement pré-coché),
  // une seule fois, à froid. On laisse un court délai pour ne pas heurter la clôture visuelle.
  if(!s.parfumsConfirmes && (s.tasks||[]).some(t=>t.end) && typeof prodSessParfumsConfirm==='function'){
    setTimeout(()=>{ try{ prodSessParfumsConfirm(s.id); }catch(e){ console.error('sessParfums',e); } }, 350);
  }
}
// Démarre une tâche labellisée dans la session (en crée une si besoin). N'interrompt PAS les autres.
function prodTaskStart(label){
  const meta = prodTaskMeta(label);
  let s = prodSessionStart();
  const t = { id:prodNewId(), label:meta.label, phase:meta.phase, color:meta.color,
              start:Date.now(), end:null, pausedAccum:0, pauseAt:null };
  s.tasks = s.tasks||[]; s.tasks.push(t);
  prodSessUpsert(s);
  prodStartTicking();
  // [RATTACHEMENT INTELLIGENT] Si UN SEUL parfum est en cours de production, on rattache la tâche
  // automatiquement (l'algo « comprend » sans rien demander). Si plusieurs → on propose de cocher.
  // Si aucun → tâche transverse (vaisselle…), pas de rattachement auto.
  try{ prodTaskAutoRattach(t.id); }catch(e){ console.error('autoRattach',e); }
  return t;
}
// Renvoie les recipeId DISTINCTS des batchs actuellement en cours de production (statut démarré).
async function prodRecettesEnCours(){
  const prods = await db.productions.toArray().catch(()=>[]);
  const set = new Set();
  prods.forEach(p=>{
    if((p.prodStatut||'termine')!=='demarre') return;
    if(p.libre || p.recipeId==null) return;
    set.add(+p.recipeId);
  });
  return Array.from(set);
}
// Rattache automatiquement une tâche au parfum en cours s'il n'y en a qu'un ; sinon propose un choix.
async function prodTaskAutoRattach(taskId){
  const recs = await prodRecettesEnCours();
  if(recs.length===1){
    // Un seul parfum en production → rattachement direct, silencieux.
    const s = prodSessActive(); if(!s) return;
    const t = (s.tasks||[]).find(x=>x.id===taskId); if(!t) return;
    t.parfums = recs.slice();
    prodSessUpsert(s);
    prodRenderBoard&&prodRenderBoard();
  } else if(recs.length>1){
    // Plusieurs parfums en cours → on propose de cocher (en cas de doute).
    prodTaskRattachPicker(taskId, recs);
  }
  // recs.length===0 → tâche transverse, on ne rattache rien (cochable manuellement plus tard).
}
// Sélecteur de rattachement : coche le(s) parfum(s) concerné(s) par cette tâche.
async function prodTaskRattachPicker(taskId, recsEnCours){
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const s = prodSessActive(); if(!s) return;
  const t = (s.tasks||[]).find(x=>x.id===taskId); if(!t) return;
  // Présélection intelligente : 1) parfums EN COURS de production, puis 2) parfums des LOTS RÉCENTS
  // (dernières 12 h). On pré-coche les deux ; l'utilisateur décoche ce qui ne concerne pas la tâche.
  const enCours = recsEnCours||[];
  let recents = [];
  try{
    const prods = await db.productions.toArray();
    const limite = Date.now() - 12*3600*1000;
    recents = prods.filter(p=>{
      if(p.libre || p.recipeId==null) return false;
      const ts = Date.parse(p.prodDebutTs||p.prodTimestamp||p.date||'')||0;
      return ts>=limite;
    }).map(p=>+p.recipeId);
  }catch(e){swallow(e,'prodTaskRattachPicker')}
  const recentsSet = new Set(recents);
  const enCoursSet = new Set(enCours.map(Number));
  const dejaSet = new Set((Array.isArray(t.parfums)?t.parfums:[]).map(x=>+x));
  // Ordre : en cours d'abord, puis récents, puis le reste — chaque groupe alpha.
  const rang = r => enCoursSet.has(+r.id)?0 : (recentsSet.has(+r.id)?1:2);
  const recsTri = recipes.slice().filter(r=>r.produitNom).sort((a,b)=>{
    return rang(a)-rang(b) || (a.produitNom||'').localeCompare(b.produitNom||'');
  });
  window._taskRattachId = taskId;
  window._taskRattachRecs = recsTri.map(r=>r.id);
  const rows = recsTri.map(r=>{
    // pré-coché si : déjà rattaché, OU en cours, OU lot récent
    const checked = (dejaSet.has(+r.id) || enCoursSet.has(+r.id) || recentsSet.has(+r.id)) ? 'checked' : '';
    const gf = r.grandFormat ? ' <span class="tag" style="background:#8a6d3b;color:#fff;font-size:.62rem">GF</span>' : '';
    let enc='';
    if(enCoursSet.has(+r.id)) enc = ' <span style="color:#3f7d52;font-size:.72rem">en production</span>';
    else if(recentsSet.has(+r.id)) enc = ' <span style="color:#AA7C39;font-size:.72rem">lot récent</span>';
    return `<label class="sum-box" style="align-items:center;cursor:pointer">
      <span style="flex:1">${esc(r.produitNom)}${gf}${enc}</span>
      <input type="checkbox" id="trc_${r.id}" ${checked} style="width:22px;height:22px"></label>`;
  }).join('');
  openModal(`<h3>🎯 Parfum(s) de cette tâche</h3>
    <p class="note">Coche le(s) parfum(s) concerné(s) par « ${esc(t.label)} ». L'app a pré-coché les parfums <b>en cours</b> et des <b>lots récents</b> — décoche ceux qui ne sont pas concernés. Sert à attribuer le temps au bon parfum.</p>
    ${rows}
    <div class="modal-actions">
      <button class="btn ghost" style="margin-right:auto" onclick="closeModal()">Plus tard</button>
      <button class="btn gold" onclick="prodTaskRattachSave()">Valider</button>
    </div>`);
}
function prodTaskRattachSave(){
  const taskId = window._taskRattachId; if(taskId==null) return;
  const recIds = window._taskRattachRecs||[];
  const choisis = recIds.filter(rid=>{ const el=document.getElementById('trc_'+rid); return el&&el.checked; }).map(rid=>+rid);
  const s = prodSessActive(); if(!s){ closeModal(); return; }
  const t = (s.tasks||[]).find(x=>x.id===taskId);
  if(t){ t.parfums = choisis.slice(); prodSessUpsert(s); }
  closeModal();
  prodRenderBoard&&prodRenderBoard();
  toast(choisis.length?`${choisis.length} parfum(s) rattaché(s) ✓`:'Tâche sans parfum (transverse)');
}
// Ouvre le sélecteur de rattachement pour une tâche, à la demande (bouton ✏️). Fonctionne même
// sur une session passée rouverte (cherche la tâche dans la session active).
async function prodTaskRattachManuel(taskId){
  const recs = await prodRecettesEnCours();
  prodTaskRattachPicker(taskId, recs);
}
// [TEMPS PAR RECETTE] Démarre une tâche d'ATELIER (prodSessions) rattachée à un batch de
// production. La tâche porte `parfums:[recipeId]`, ce que prodTempsParParfum() lit pour répartir
// le temps réel par recette. Le label reprend le composant + le parfum (ex. « Coques — Chocolat »).
// Une session d'atelier est ouverte automatiquement si aucune n'est active. Renvoie l'id de tâche
// (mémorisé sur la production pour pouvoir l'arrêter à la fin du batch).
// ════════════════════════════════════════════════════════════════════════════
// HELPER UNIQUE DE LANCEMENT D'UN BATCH (source de vérité du lancement mono-parfum).
// Garantit PAR CONSTRUCTION la séquence complète, dans le bon ordre :
//   1) enregistrerProduction (crée le batch, décompte les matières)
//   2) prodTaskStartForBatch (démarre le chrono d'atelier) + liaison atelierTaskId
//   3) renderProductions (rafraîchit l'écran)
//   4) ficheRecetteProduction (POPUP RECETTE : grammages recalculés au batch) ← TOUJOURS
// Tout point de lancement mono-parfum (formulaire, plan interactif, futurs) DOIT passer
// par ici pour hériter automatiquement de la popup recette. Ne pas dupliquer la séquence.
//
// opts = { recipeId, qteMacarons, composant:'complet'|'coques'|'ganache', lotBase, lot,
//          garnitureType?, date?, qteReelleMacarons?, toastLabel? }
//   - qteMacarons = quantité THÉORIQUE (macarons). qteReelleMacarons : réel si différent (déf = théorique).
//   - Pour 'coques' : on stocke qteMacarons×2 coques, matières calées sur les macarons (facteurQte).
//   - Renvoie le prodId créé (ou lève une erreur, gérée par l'appelant).
async function lancerBatchAvecFiche(opts){
  opts = opts || {};
  const recipeId = +opts.recipeId;
  const qMac = Math.max(0, Math.round(+opts.qteMacarons||0));
  const qMacReel = (opts.qteReelleMacarons==null || opts.qteReelleMacarons==='') ? qMac : Math.max(0, Math.round(+opts.qteReelleMacarons||0));
  const composant = opts.composant || 'complet';
  const date = opts.date || today();
  const lotBase = opts.lotBase || '';
  const lot = opts.lot || lotBase;
  const garnType = opts.garnitureType || undefined;
  if(!recipeId) throw new Error('Recette manquante');
  if(qMac<=0) throw new Error('Quantité invalide');
  // Coques : qteRestante stockée en COQUES (×2) ; matières basées sur les MACARONS (facteurQte).
  let qTh=qMac, qRe=qMacReel, facteurQte=qMac;
  if(composant==='coques'){ qTh=qMac*COQUES_PAR_MACARON; qRe=qMacReel*COQUES_PAR_MACARON; facteurQte=qMac; }
  // 1) création du batch
  const prodId = await enregistrerProduction(recipeId, qTh, qRe, date, lot, '', '',
    {composant, lotBase, facteurQte, garnitureType:garnType});
  // 2) chrono d'atelier rattaché
  try{
    const _rec = await db.recipes.get(recipeId).catch(()=>null);
    const taskId = prodTaskStartForBatch({recipeId, composant, lotBase, parfumNom:_rec?_rec.produitNom:''});
    if(prodId!=null && taskId) await db.productions.update(prodId, {atelierTaskId:taskId});
  }catch(e){ console.error('lancerBatchAvecFiche chrono', e); }
  // 3) rafraîchit l'écran des productions
  try{ if(typeof renderProductions==='function') renderProductions(); }catch(e){swallow(e,'lancerBatchAvecFiche')}
  // toast optionnel AVANT la popup (la popup est modale et masquerait un toast tardif)
  if(opts.toastLabel){ try{ toast(opts.toastLabel); }catch(e){swallow(e,'lancerBatchAvecFiche')} }
  // 4) POPUP RECETTE garantie (grammages recalculés au batch)
  try{ await ficheRecetteProduction(recipeId, facteurQte, composant, lot); }catch(e){ console.error('lancerBatchAvecFiche fiche', e); }
  return prodId;
}

// ════════════════════════════════════════════════════════════════════════════
// PLAN DE TRAVAIL INTERACTIF — clic sur une étape COQUES (meringue) du plan détaillé.
// Une meringue mutualise 1 à 3 parfums (m.repartition = { parfum: nbMacarons }). Cliquer
// lance UN batch coques par parfum, tous reliés par un meringueBatchId commun (comme le mode
// duo de saveProd), démarre un chrono par batch, puis affiche la fiche meringue (multi-parfums)
// — ou la fiche simple si un seul parfum. Confirmation + quantités ajustables AVANT tout.
// Cohérence affiché ↔ action : le résumé liste exactement les parfums/quantités qui seront lancés.
// ────────────────────────────────────────────────────────────────────────────
// Phrase de résumé de l'action meringue, recalculée à partir des quantités saisies.
function _planMeringuePhrase(items){
  // items = [{nom, q}] (déjà filtrés q>0). Affiche « X coques au total · parfum1 N + parfum2 M ».
  const valides = items.filter(it=>+it.q>0);
  if(!valides.length) return 'Aucun parfum à lancer (quantités à 0).';
  const totalMac = valides.reduce((s,it)=>s+(+it.q||0),0);
  const totalCoques = totalMac*COQUES_PAR_MACARON;
  const detail = valides.map(it=>`<b>${esc(it.nom)}</b> ${qty(it.q)}`).join(' + ');
  const nbBatch = valides.length;
  return `Lancer <b>${nbBatch}</b> batch${nbBatch>1?'s':''} de coques (${detail}) = <b>${qty(totalCoques)}</b> coques au total${nbBatch>1?', meringue commune,':''} et démarrer le${nbBatch>1?'s':''} chrono${nbBatch>1?'s':''} ?`;
}
// Met à jour la phrase quand une quantité change. window._planMeringueItems porte la liste courante.
function planMeringueMajPhrase(){
  const items = (window._planMeringueItems||[]).map((it,idx)=>({nom:it.nom, recipeId:it.recipeId, q:Math.max(0,Math.round(+val('f_planMer_'+idx)||0))}));
  window._planMeringueItems = items;
  const el = document.getElementById('planMerPhrase');
  if(el) el.innerHTML = _planMeringuePhrase(items);
}
// Étape 1 : ouvre la confirmation. repartition = objet { nomParfum: nbMacarons }.
// Pont depuis le plan : retrouve la répartition stockée par clé (évite toute sérialisation JSON dans
// l'attribut onclick) puis lance la meringue normalement.
function planLancerMeringueByKey(key, idxMeringue){
  const rep = (window._planMeringueReg||{})[key];
  if(!rep){ toast('Meringue introuvable, rafraîchis le plan'); return; }
  return planLancerMeringue(rep, idxMeringue);
}
async function planLancerMeringue(repartition, idxMeringue){
  let rep = repartition;
  if(typeof rep === 'string'){ try{ rep = JSON.parse(rep); }catch(e){ rep = {}; } }
  const noms = Object.keys(rep||{});
  if(!noms.length){ toast('Meringue vide'); return; }
  // Résout chaque parfum → recette. On signale honnêtement ceux sans recette (non lançables).
  const items = [];
  const manquants = [];
  for(const nom of noms){
    const recette = await _planRecetteParNom(nom);
    if(recette) items.push({ nom, recipeId:recette.id, q:Math.max(0,Math.round(+rep[nom]||0)) });
    else manquants.push(nom);
  }
  if(!items.length){
    openModal(`<h3>Meringue non lançable</h3>
      <p class="note">Aucun parfum de cette meringue n'a de recette associée : ${esc(noms.join(', '))}. Vérifie les recettes.</p>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  window._planMeringueItems = items;
  const champs = items.map((it,idx)=>{
    const col = (typeof flavorColor==='function') ? flavorColor(it.nom) : '#cbb89f';
    return `<div class="field" style="display:flex;align-items:center;gap:8px">
      <span style="display:inline-block;width:13px;height:13px;border-radius:50%;background:${col};flex:none"></span>
      <label style="flex:1;margin:0">${esc(it.nom)}</label>
      <input type="number" id="f_planMer_${idx}" min="0" value="${it.q}" oninput="planMeringueMajPhrase()" style="width:90px;font-size:1.05rem">
    </div>`;
  }).join('');
  const avert = manquants.length
    ? `<p class="note" style="color:#b3261e;margin-top:6px">⚠️ Sans recette (non lancés) : ${esc(manquants.join(', '))}.</p>` : '';
  openModal(`<h3>🥣 Meringue ${idxMeringue!=null?('· '+(idxMeringue+1)):''} — coques</h3>
    <p class="note" style="margin-bottom:8px">Ajuste les quantités (macarons) par parfum. Chaque parfum = un batch de coques ; ils partagent une même meringue.</p>
    ${champs}
    ${avert}
    <div class="sum-box" style="background:#f6f1e7;align-items:flex-start;margin-top:8px">
      <div id="planMerPhrase" style="font-size:.9rem;line-height:1.45">${_planMeringuePhrase(items)}</div>
    </div>
    <p class="note" style="margin-top:8px">Cela créera le(s) batch(s) coques (statut <b>démarré</b>, matières décomptées) et lancera le(s) chrono(s). La fiche de pesée s'affiche ensuite.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="planLancerMeringueConfirm()">✓ Lancer coques + chrono</button>
    </div>`);
}
// Étape 2 : exécute après confirmation. N batchs coques liés par meringueBatchId + chronos + fiche.
async function planLancerMeringueConfirm(){
  const items = (window._planMeringueItems||[])
    .map((it,idx)=>({ ...it, q:Math.max(0,Math.round(+val('f_planMer_'+idx)||0)) }))
    .filter(it=>it.q>0);
  if(!items.length){ toast('Indique au moins une quantité'); return; }
  const date = today();
  // meringueBatchId commun (sauf si un seul parfum : pas de mutualisation).
  const meringueBatchId = items.length>1 ? ('MER-' + lotDateJJMMAA(date) + '-' + genLotCode(3)) : undefined;
  const parts = [];   // pour la fiche meringue
  try{
    for(const it of items){
      const rec = await db.recipes.get(it.recipeId).catch(()=>null);
      if(!rec) continue;
      const base = (lotDateJJMMAA(date) + (typeof flavorCodeRec==='function'?flavorCodeRec(rec):'')).toUpperCase().replace(/\s+/g,'');
      const cleanBase = base || (lotDateJJMMAA(date)+'COQ');
      const lot = cleanBase + '-CO';
      const prodId = await enregistrerProduction(
        it.recipeId, it.q*COQUES_PAR_MACARON, it.q*COQUES_PAR_MACARON, date, lot, '', '',
        { composant:'coques', lotBase:cleanBase, facteurQte:it.q, meringueBatchId }
      );
      try{
        const taskId = prodTaskStartForBatch({recipeId:it.recipeId, composant:'coques', lotBase:cleanBase, parfumNom:rec.produitNom||it.nom});
        if(prodId!=null && taskId) await db.productions.update(prodId, {atelierTaskId:taskId});
      }catch(e){ console.error('plan meringue chrono', e); }
      parts.push({ rid:it.recipeId, q:it.q, lot, rec });
    }
  }catch(err){
    toast(err.message || 'Erreur lancement coques');
    return;
  }
  closeModal();
  if(typeof renderProductions==='function') renderProductions();
  const totalCoques = items.reduce((s,it)=>s+it.q*COQUES_PAR_MACARON,0);
  toast(`🥣 ${items.length>1?'Meringue commune':'Coques'} lancée ✓ — ${qty(totalCoques)} coques · chrono${items.length>1?'s':''} lancé${items.length>1?'s':''}`);
  // Fiche : meringue (multi-parfums, ≥2) ou fiche simple (1 parfum).
  try{
    if(parts.length>=2){ await ficheMeringueProduction(parts, meringueBatchId); }
    else if(parts.length===1){ await ficheRecetteProduction(parts[0].rid, parts[0].q, 'coques', parts[0].lot); }
  }catch(e){ console.error('plan meringue fiche', e); }
}

// ════════════════════════════════════════════════════════════════════════════
// PLAN DE TRAVAIL INTERACTIF — clic sur une étape GANACHE du plan détaillé.
// Objectif (Benjamin) : tout converge vers le plan. Cliquer sur une ganache ouvre une
// confirmation montrant EXACTEMENT ce qui sera lancé (cohérence affiché ↔ action), avec
// quantité ajustable. À la confirmation : crée le batch ganache (statut démarré, matières
// décomptées) ET démarre le chrono d'atelier rattaché — comme un lancement manuel.
// On commence par la GANACHE car c'est le cas 1:1 sans ambiguïté (un parfum = un batch).
// ────────────────────────────────────────────────────────────────────────────
// Retrouve la recette d'un parfum par son nom (normalisé, robuste aux accents/casse).
async function _planRecetteParNom(parfum){
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const k = (typeof aiNormalize==='function') ? aiNormalize(parfum||'') : String(parfum||'').toLowerCase().trim();
  return recipes.find(r => ((typeof aiNormalize==='function')?aiNormalize(r.produitNom||''):String(r.produitNom||'').toLowerCase().trim()) === k) || null;
}
// Phrase de résumé de l'action (réutilisée dans la modale et mise à jour au changement de qté).
function _planGanachePhrase(parfum, qte){
  return `Lancer la production de la ganache <b>${esc(parfum)}</b> (<b>${qty(qte)}</b> macaron${qte>1?'s':''}) et démarrer le chrono d'atelier ?`;
}
// Met à jour la phrase de résumé quand la quantité change dans la modale.
function planGanacheMajPhrase(){
  const parfum = (window._planGanacheCtx||{}).parfum || '';
  const q = Math.max(0, Math.round(+val('f_planGanQte')||0));
  const el = document.getElementById('planGanPhrase');
  if(el) el.innerHTML = _planGanachePhrase(parfum, q);
}
// Étape 1 : ouvre la confirmation. parfum = nom affiché dans le plan ; qteSuggere = quantité du plan.
// Pont depuis le plan : retrouve {parfum, qte} par clé puis ouvre la confirmation ganache.
function planLancerGanacheByKey(key){
  const ctx = (window._planGanacheLanceReg||{})[key];
  if(!ctx){ toast('Ganache introuvable, rafraîchis le plan'); return; }
  return planLancerGanache(ctx.parfum, ctx.qte);
}
async function planLancerGanache(parfum, qteSuggere){
  const rec = await _planRecetteParNom(parfum);
  if(!rec){
    openModal(`<h3>Ganache introuvable</h3>
      <p class="note">Aucune recette ne correspond au parfum « ${esc(parfum)} ». Vérifie le nom de la recette.</p>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  const q0 = Math.max(1, Math.round(+qteSuggere||0));
  const col = (typeof flavorColor==='function') ? flavorColor(parfum) : '#cbb89f';
  // Contexte stocké (comme les coques avec _planMeringueItems) : évite de réinjecter le nom du parfum
  // dans les attributs onclick/oninput — robuste aux apostrophes et guillemets dans les noms.
  window._planGanacheCtx = { recipeId: rec.id, parfum };
  openModal(`<h3><span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:${col};vertical-align:middle;margin-right:6px"></span>🍫 Ganache ${esc(parfum)}</h3>
    <div class="field"><label>Quantité (macarons)</label>
      <input type="number" id="f_planGanQte" min="1" value="${q0}" oninput="planGanacheMajPhrase()" style="font-size:1.1rem"></div>
    <div class="sum-box" style="background:#f6f1e7;align-items:flex-start">
      <div id="planGanPhrase" style="font-size:.9rem;line-height:1.45">${_planGanachePhrase(parfum, q0)}</div>
    </div>
    <p class="note" style="margin-top:8px">Cela créera le batch (statut <b>démarré</b>, matières décomptées) et lancera le chrono d'atelier rattaché. La DLC ne courra qu'à la fin de production.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="planLancerGanacheConfirm()">✓ Lancer ganache + chrono</button>
    </div>`);
}
// Étape 2 : exécute après confirmation. Reproduit fidèlement la chaîne de saveProd (ganache) :
// enregistrerProduction → prodTaskStartForBatch → liaison atelierTaskId → fiche de production.
async function planLancerGanacheConfirm(){
  const ctx = window._planGanacheCtx || {};
  const recipeId = ctx.recipeId, parfum = ctx.parfum;
  if(recipeId==null){ toast('Contexte ganache perdu, réessaie'); return; }
  const q = Math.max(1, Math.round(+val('f_planGanQte')||0));
  if(q<=0){ toast('Quantité invalide'); return; }
  const rec = await db.recipes.get(recipeId).catch(()=>null);
  if(!rec){ toast('Recette introuvable'); return; }
  // N° de lot : JJMMAA + code parfum + suffixe -GA (ganache), comme un lancement manuel.
  const date = today();
  const base = (lotDateJJMMAA(date) + (typeof flavorCodeRec==='function'?flavorCodeRec(rec):'')).toUpperCase().replace(/\s+/g,'');
  const cleanBase = base || (lotDateJJMMAA(date)+'GAN');
  const lot = cleanBase + '-GA';
  try{
    // lancerBatchAvecFiche affiche déjà la FICHE RECETTE (modale) qui remplace ce popup de confirmation.
    // On NE fait donc PAS closeModal() après : cela fermerait la fiche à peine ouverte (bug v810).
    // Le toast est passé en option pour s'afficher AVANT la fiche (sinon masqué par la modale).
    await lancerBatchAvecFiche({ recipeId, qteMacarons:q, composant:'ganache', lotBase:cleanBase, lot, date,
      toastLabel:`Ganache ${parfum} démarrée ✓ · chrono lancé` });
  }catch(err){
    toast(err.message || 'Erreur lancement ganache');
  }
}

// [PLAN INTERACTIF — MONTAGE] Depuis le plan de travail, lancer l'ASSEMBLAGE d'un parfum.
// L'assemblage n'est PAS une production : il CONSOMME un lot coques terminé + un lot garniture
// (ganache/crémeux) terminé pour produire des macarons finis. On ne peut donc pas « tout lancer »
// d'un clic comme une ganache : il faut des sous-lots déjà produits ET terminés. Cette fonction
// retrouve les meilleurs lots du parfum et ouvre le formulaire d'assemblage EXISTANT
// (prodAssembleForm) pré-renseigné — SOURCE UNIQUE : tout le décompte (coques×2 + garniture),
// le chrono d'atelier « Assemblage », la DLC et le journal de stock sont gérés par ce formulaire.
// Si un sous-lot manque, on l'explique clairement au lieu de planter.
// Pont depuis le plan : retrouve {parfum, qte} stockés par clé (pas de nom réinjecté dans l'attribut).
function planLancerMontageByKey(key){
  const ctx = (window._planMontageReg||{})[key];
  if(!ctx){ toast('Montage introuvable, rafraîchis le plan'); return; }
  return planLancerMontage(ctx.parfum, ctx.qte);
}
async function planLancerMontage(parfum, qteSuggere){
  const rec = await _planRecetteParNom(parfum);
  if(!rec){
    openModal(`<h3>Montage impossible</h3>
      <p class="note">Aucune recette ne correspond au parfum « ${esc(parfum)} ». Vérifie le nom de la recette.</p>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  const prods = await db.productions.toArray().catch(()=>[]);
  const dispo = x => (x.prodStatut||'termine')==='termine' && round3(+x.qteRestante)>0;
  // Tri : même lotBase d'abord, puis DLC la plus courte (FIFO), comme prodAssembleForm.
  const triFIFO = (a,b)=> (a.dlcProduit||'9999').localeCompare(b.dlcProduit||'9999') || String(a.date||'').localeCompare(String(b.date||''));
  const coquesLots  = prods.filter(x=> +x.recipeId===+rec.id && prodComposant(x)==='coques'  && dispo(x)).sort(triFIFO);
  const garnitLots  = prods.filter(x=> +x.recipeId===+rec.id && prodComposant(x)==='ganache' && dispo(x)).sort(triFIFO);

  // Diagnostic clair si un composant manque (pas produit, ou pas terminé, ou épuisé).
  if(!coquesLots.length || !garnitLots.length){
    const manques = [];
    if(!coquesLots.length) manques.push('les <b>coques</b>');
    if(!garnitLots.length) manques.push('la <b>garniture</b> (ganache/crémeux)');
    const quoi = manques.join(' et ');
    openModal(`<h3>🔧 Montage ${esc(parfum)} — pas encore possible</h3>
      <div class="sum-box" style="background:#fdf3f1;border-color:#e7c3bd;align-items:flex-start">
        <div style="font-size:.9rem;line-height:1.5">Pour assembler ${esc(parfum)}, il faut un lot de coques <b>terminé</b> ET un lot de garniture <b>terminé</b> en stock.<br>
        Il manque ${quoi} pour ce parfum.</div>
      </div>
      <p class="note" style="margin-top:8px">Lance d'abord ${quoi} depuis le plan (ou la production), <b>termine</b> ${manques.length>1?'ces batchs':'ce batch'}, puis reviens monter.</p>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Compris</button></div>`);
    return;
  }
  // Les deux existent : on ouvre le formulaire d'assemblage éprouvé, pré-renseigné avec
  // le meilleur lot coques (FIFO) et le meilleur lot garniture en « otherId ». L'utilisateur
  // garde la main sur la quantité et la destination ; la confirmation finale reste dans ce form.
  prodAssembleForm(coquesLots[0].id, { otherId: garnitLots[0].id });
}

// [SYNCHRO PRODUCTION ↔ ATELIER] Garantit qu'un batch a démarré son chrono d'atelier (tâche
// « Production » rattachée à son parfum) et qu'il est lié via atelierTaskId. Idempotent : ne fait
// rien si le batch a déjà une tâche liée. Appelé à CHAQUE création de batch (voie normale).
async function prodEnsureBatchChrono(prodId, recipeId, composant){
  try{
    const p = await db.productions.get(prodId); if(!p) return;
    if(p.atelierTaskId) return; // déjà lié → ne pas doubler
    let nom = '';
    if(recipeId!=null){ const r = await db.recipes.get(recipeId).catch(()=>null); nom = r?r.produitNom:''; }
    else if(p.libre){ nom = p.produitLibre||''; }
    const taskId = prodTaskStartForBatch({ recipeId, composant: composant||p.composant||'complet',
                                           lotBase: p.lotBase||'', parfumNom: nom });
    if(taskId) await db.productions.update(prodId, {atelierTaskId: taskId});
  }catch(e){ console.error('prodEnsureBatchChrono', e); }
}

function prodTaskStartForBatch(meta){
  meta = meta || {};
  const compLbl = ({coques:'Coques', ganache:'Ganache', cremeux:'Crémeux', assemble:'Assemblage', complet:'Production'})[meta.composant] || 'Production';
  const label = meta.parfumNom ? `${compLbl} — ${meta.parfumNom}` : compLbl;
  // Phase d'atelier indicative selon le composant (réutilise la palette existante).
  const phaseMap = {coques:'Macaronnage', ganache:'Garnissage', cremeux:'Garnissage', assemble:'Garnissage', complet:'Macaronnage'};
  const phase = phaseMap[meta.composant] || 'Macaronnage';
  const s = prodSessionStart();
  s.tasks = s.tasks||[];
  // ANTI-DOUBLON : si une tâche identique (même recette + même composant) est DÉJÀ en cours
  // (non terminée), on ne crée pas de second chrono. Évite les doublons sur double-tap ou
  // double-appel. On retourne l'id de la tâche existante.
  const rid = (meta.recipeId!=null) ? +meta.recipeId : null;
  const comp = meta.composant||'complet';
  const dejaEnCours = s.tasks.find(t=>!t.end
        && (t.composant||'complet')===comp
        && ((rid!=null && Array.isArray(t.parfums) && t.parfums.map(Number).includes(rid))
            || (rid==null && t.label===label)));
  if(dejaEnCours) return dejaEnCours.id;
  const t = { id:prodNewId(), label, phase, color:'#aa7c39',
              start:Date.now(), end:null, pausedAccum:0, pauseAt:null,
              parfums: (rid!=null ? [rid] : []),
              composant: comp,
              lotBase: meta.lotBase||'',
              fromBatch: true };
  s.tasks.push(t);
  prodSessUpsert(s);
  prodStartTicking();
  if(typeof prodRenderBoard==='function') prodRenderBoard();
  return t.id;
}
// Pause / reprise d'une tâche (sans l'arrêter).
function prodTaskPauseToggle(taskId){
  const s = prodSessActive(); if(!s) return;
  const t = (s.tasks||[]).find(x=>x.id===taskId); if(!t || t.end) return;
  if(prodTaskPaused(t)){
    t.pausedAccum = (+t.pausedAccum||0) + Math.max(0, Date.now()-(+t.pauseAt));
    t.pauseAt = null;
  } else {
    t.pauseAt = Date.now();
  }
  prodSessUpsert(s);
  prodRenderBoard&&prodRenderBoard();
}
// Arrête (termine) une tâche. Les autres continuent.
function prodTaskStop(taskId){
  const s = prodSessActive(); if(!s) return;
  const t = (s.tasks||[]).find(x=>x.id===taskId); if(!t || t.end) return;
  if(prodTaskPaused(t)){ t.pausedAccum=(+t.pausedAccum||0)+Math.max(0,Date.now()-(+t.pauseAt)); t.pauseAt=null; }
  t.end = Date.now();
  prodSessUpsert(s);
  if(!prodAnyRunning()) prodStopTicking();
  prodRenderBoard&&prodRenderBoard();
}

// ─────────────────────────────────────────────────────────────────────────────
// [MERINGUE MUTUALISÉE] Garde-fou contre l'arrêt accidentel d'UN seul parfum en
// tout début de production. Tant qu'on travaille la meringue commune (phases amont
// partagées), terminer le chrono d'un seul parfum n'a pas de sens — c'est presque
// toujours une fausse manip. On intercepte donc l'arrêt et on demande confirmation.
//
// « Suspect » = les 3 conditions réunies :
//   1) la tâche ne porte qu'UN parfum (arrêt ciblé d'un parfum) ;
//   2) ce parfum appartient à une meringue mutualisée ENCORE ACTIVE : plusieurs
//      batchs « coques » démarrés partagent le même meringueBatchId, et au moins un
//      AUTRE parfum de cette fournée est encore en cours (batch non terminé) ;
//   3) on est dans une phase AMONT partagée (avant que la cuisson n'individualise
//      les parfums) : Préparation / Meringue / Macaronnage / Manipulation coques.
// ─────────────────────────────────────────────────────────────────────────────
const _PHASES_AMONT_MUTUALISEE = ['Préparation','Meringue','Macaronnage','Finition / Manipulation coques'];

// Renvoie le meringueBatchId ACTIF (fournée partagée par 2+ parfums, batchs coques
// non terminés) auquel appartient `recipeId`, avec la liste des parfums encore en
// cours — ou null si ce parfum n'est pas sur une meringue mutualisée active.
async function _prodMeringueMutualiseeActive(recipeId){
  try{
    if(recipeId==null) return null;
    const prods = await db.productions.toArray().catch(()=>[]);
    // On ne garde que les batchs coques encore « démarrés » reliés à une fournée commune.
    const coquesActifs = prods.filter(p =>
      p.meringueBatchId &&
      (p.composant==='coques') &&
      (p.prodStatut||'termine')==='demarre');
    if(!coquesActifs.length) return null;
    // Groupe par fournée de meringue.
    const parFournee = {};
    coquesActifs.forEach(p=>{ (parFournee[p.meringueBatchId] ||= []).push(p); });
    // Cherche la fournée qui contient notre parfum ET au moins un autre parfum distinct.
    for(const mbId of Object.keys(parFournee)){
      const lots = parFournee[mbId];
      const rids = [...new Set(lots.map(l=>+l.recipeId))];
      if(rids.includes(+recipeId) && rids.length>=2){
        return { meringueBatchId: mbId, parfums: rids, autres: rids.filter(r=>r!==+recipeId) };
      }
    }
    return null;
  }catch(e){ console.error('_prodMeringueMutualiseeActive', e); return null; }
}

// Décide si l'arrêt de la tâche `t` doit être bloqué (confirmation) plutôt que sec.
// Async car on lit les productions. Renvoie {suspect:bool, info?}.
async function _prodArretSuspectMutualise(t){
  try{
    if(!t || t.end) return { suspect:false };
    const parfs = (typeof _atTaskParfums==='function') ? _atTaskParfums(t) : (Array.isArray(t.parfums)?t.parfums.map(Number):[]);
    // (1) uniquement les tâches ciblant UN seul parfum (l'arrêt global du mutualisé n'est pas visé).
    if(parfs.length!==1) return { suspect:false };
    // (3) phase amont partagée seulement.
    if(!_PHASES_AMONT_MUTUALISEE.includes(t.phase)) return { suspect:false };
    // (2) meringue mutualisée active incluant ce parfum + un autre encore en cours.
    const mut = await _prodMeringueMutualiseeActive(parfs[0]);
    if(!mut) return { suspect:false };
    return { suspect:true, info:mut };
  }catch(e){ console.error('_prodArretSuspectMutualise', e); return { suspect:false }; }
}

// Point d'entrée appelé par le bouton ⏹ de l'onglet mutualisé (et du tableau blanc).
// Si l'arrêt est suspect → modale de confirmation ; sinon → arrêt direct.
// [v1364] ARRÊT DIRECT depuis la fenêtre raccourci (fenêtre flottante).
//
// Ben : « quand je fais mes saisies depuis la fenêtre raccourci j'ai toutes les difficultés à
// arrêter des étapes en cours. Obligé d'ouvrir l'atelier complet. » — LA CAUSE : le bouton ⏹
// appelait `prodTaskStopGuard`, qui pour une meringue partagée ouvrait un `openModal`. Mais la
// fenêtre flottante vit dans sa PROPRE couche (`#chronoFloatHost`) : le modal s'ouvrait DERRIÈRE
// elle, invisible et incliquable. Le bouton semblait « ne rien faire ».
//
// C'est le même défaut que le crash des étiquettes (v1363) : une action qui ouvre un modal depuis
// une couche flottante. RÈGLE (v1363, confirmée ici) : une couche flottante ne déclenche pas de
// modal par-dessus elle.
//
// Ben a tranché : « supprimer la confirmation : arrêter directement ». On arrête SANS garde-fou —
// le chrono se fige, l'étape passe à l'historique, la fenêtre se rafraîchit sur place. Pas de modal,
// donc pas de couche concurrente, donc plus de bouton mort.
function prodTaskStopDirect(taskId){
  try{
    const s = prodSessActive(); if(!s) return;
    const t = (s.tasks||[]).find(x=>String(x.id)===String(taskId));
    if(!t || t.end) return;
    prodTaskStop(taskId);
    if(typeof chronoFloatRenderBody==='function') chronoFloatRenderBody();
    if(typeof prodRenderBoard==='function' && document.getElementById('prodBoardHost')) prodRenderBoard();
  }catch(e){ swallow(e,'prodTaskStopDirect'); }
}

async function prodTaskStopGuard(taskId){
  try{
    const s = prodSessActive(); if(!s){ return; }
    const t = (s.tasks||[]).find(x=>String(x.id)===String(taskId));
    if(!t || t.end){ return; }
    const verdict = await _prodArretSuspectMutualise(t);
    if(!verdict.suspect){
      prodTaskStop(taskId);
      if(typeof chronoFloatRenderBody==='function') chronoFloatRenderBody();
      return;
    }
    // Récupère les noms des autres parfums de la fournée pour un message clair.
    let autresNoms = [];
    try{
      const recs = await Promise.all((verdict.info.autres||[]).map(r=>db.recipes.get(r).catch(()=>null)));
      autresNoms = recs.filter(Boolean).map(r=>r.produitNom||r.nom).filter(Boolean);
    }catch(e){swallow(e,'prodTaskStopGuard')}
    const etape = (typeof atShort==='function') ? atShort(t.label) : (t.label||'cette étape');
    const listeAutres = autresNoms.length
      ? `Les autres parfums de la même meringue (<b>${autresNoms.map(esc).join(', ')}</b>) sont encore en cours.`
      : `Un autre parfum de la même meringue est encore en cours.`;
    openModal(`<h3>⚠ Meringue partagée</h3>
      <p style="margin-bottom:6px">Tu es sur le point d'arrêter le chrono de <b>${esc(etape)}</b> pour <b>un seul parfum</b>, alors que la <b>meringue est commune</b> à cette fournée.</p>
      <p class="note" style="margin-bottom:10px">${listeAutres} À ce stade (avant la cuisson), le travail est partagé : arrêter un seul parfum est presque toujours une fausse manip.</p>
      <div class="modal-actions" style="flex-wrap:wrap;gap:6px">
        <button class="btn gold" onclick="closeModal()">↩ Ne rien arrêter</button>
        <button class="btn ghost" onclick="prodTaskStopConfirme('${escJs(t.id)}')">⏹ Arrêter quand même ce parfum</button>
      </div>`);
  }catch(e){
    console.error('prodTaskStopGuard', e);
    // En cas de pépin, on ne bloque pas l'utilisateur : arrêt normal.
    prodTaskStop(taskId);
    if(typeof chronoFloatRenderBody==='function') chronoFloatRenderBody();
  }
}

// Confirmé depuis la modale : on arrête réellement, puis on rafraîchit l'atelier.
function prodTaskStopConfirme(taskId){
  closeModal();
  prodTaskStop(taskId);
  if(typeof chronoFloatRenderBody==='function') chronoFloatRenderBody();
}
// [FIN DE BATCH] Appelé quand un batch passe en « terminé ». Si une tâche d'atelier lui est
// rattachée (atelierTaskId) et tourne encore, on demande : la FERMER (fin du travail sur cette
// recette) ou la POURSUIVRE (enchaînement, vaisselle… : le temps continue et sera réparti).
// La SESSION d'atelier, elle, reste ouverte tant que tu ne la clôtures pas — c'est elle qui
// porte le temps non distribué à répartir en fin de session.
function prodPromptBatchTaskEnd(taskId, parfumNom){
  const s = prodSessActive(); if(!s){ return; }
  const t = (s.tasks||[]).find(x=>x.id===taskId);
  if(!t || t.end) return;   // pas de tâche liée active : rien à demander
  const ecoule = ttFormat(prodTaskNet(t));
  const nom = parfumNom || t.label || 'cette recette';
  openModal(`<h3>⏱ Chrono atelier — ${esc(nom)}</h3>
    <div class="sum-box"><span>Temps écoulé sur cette tâche</span><b>${ecoule}</b></div>
    <p class="note">Le batch est terminé. Veux-tu <b>arrêter</b> le chrono de cette recette, ou le <b>poursuivre</b> (tu enchaînes une autre recette, de la vaisselle, du nettoyage… : le temps continue et sera réparti en fin de session) ?<br>La session d'atelier, elle, reste ouverte dans tous les cas.</p>
    <div class="modal-actions" style="flex-wrap:wrap;gap:6px">
      <button class="btn ghost" onclick="closeModal();renderProductions()">▶ Poursuivre</button>
      <button class="btn gold" onclick="prodTaskStop('${t.id}');closeModal();renderProductions();toast('Chrono de cette recette arrêté ✓')">⏹ Arrêter cette recette</button>
    </div>`);
}
// ÉDITION DU TEMPS d'une tâche de la SESSION ACTIVE (en cours ou terminée).
// Deux modes synchronisés : (A) durée nette directe en minutes, (B) heures début/fin réelles.
// Garde-fous : fin ≥ début, durée ≥ 0. Les pauses cumulées (pausedAccum) sont préservées.
function prodTaskEditForm(taskId){
  const s = prodSessActive(); if(!s){ toast('Aucune session active'); return; }
  const t = (s.tasks||[]).find(x=>x.id===taskId); if(!t){ toast('Tâche introuvable'); return; }
  const enCours = !t.end;
  const netMin = Math.round(prodTaskNet(t)/60000);
  const fmtHM = ms => { const d=new Date(ms); return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'); };
  const startHM = fmtHM(t.start);
  const endHM = t.end ? fmtHM(t.end) : fmtHM(Date.now());
  const pauseMin = Math.round(((+t.pausedAccum||0))/60000);
  openModal(`<h3>Modifier le temps — ${esc(t.label)}</h3>
    <p class="note">${enCours?'Tâche <b>en cours</b> : ajuste sa durée déjà écoulée.':'Tâche <b>terminée</b> : corrige sa durée ou ses horaires.'}${pauseMin>0?` <br>Pauses déjà déduites : <b>${pauseMin} min</b> (conservées).`:''}</p>
    <div class="field"><label>Durée nette (minutes)</label>
      <input type="number" min="0" step="1" id="pte_dur" value="${netMin}" data-init="${netMin}" inputmode="numeric"></div>
    <details style="margin:6px 0">
      <summary style="cursor:pointer;color:var(--caramel,#AA7C39);font-weight:600">Ou saisir les horaires réels</summary>
      <div class="row2" style="margin-top:8px">
        <div class="field"><label>Heure de début</label><input type="time" id="pte_start" value="${startHM}" data-init="${startHM}"></div>
        <div class="field"><label>Heure de fin${enCours?' (laisser vide si en cours)':''}</label><input type="time" id="pte_end" value="${enCours?'':endHM}" data-init="${enCours?'':endHM}"></div>
      </div>
      <p class="note">Si tu modifies les horaires, ils priment sur la durée. Sinon, c'est la durée en minutes qui s'applique.</p>
    </details>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="prodTaskEditSave('${t.id}')">Enregistrer</button>
    </div>`);
}
function prodTaskEditSave(taskId){
  const s = prodSessActive(); if(!s){ toast('Aucune session active'); return; }
  const t = (s.tasks||[]).find(x=>x.id===taskId); if(!t){ toast('Tâche introuvable'); return; }
  const pauseMs = (+t.pausedAccum||0);
  const startEl=document.getElementById('pte_start'), endEl=document.getElementById('pte_end'), durEl=document.getElementById('pte_dur');
  const startHM = (val('pte_start')||'').trim();
  const endHM = (val('pte_end')||'').trim();
  const durMin = +val('pte_dur');
  // [FIX MODIF DURÉE] On détecte ce que l'utilisateur a RÉELLEMENT changé, en comparant chaque
  // champ à sa valeur initiale (data-init). Sans ça, les horaires pré-remplis primaient toujours
  // sur la durée en minutes → modifier seulement les minutes n'avait aucun effet.
  const startChanged = startEl && startHM!==(startEl.dataset.init||'');
  const endChanged   = endEl   && endHM  !==(endEl.dataset.init||'');
  const durChanged   = durEl   && String(durMin)!==(durEl.dataset.init||'');
  const horairesModifies = startChanged || endChanged;

  // Reconstruit un timestamp à la date de la tâche (on garde le jour de t.start) à partir de "HH:MM".
  const dayBase = new Date(t.start); dayBase.setSeconds(0,0);
  const tsFromHM = hm => {
    const m = /^(\d{1,2}):(\d{2})$/.exec(hm); if(!m) return null;
    const d = new Date(dayBase); d.setHours(+m[1], +m[2], 0, 0); return d.getTime();
  };
  const startTs = tsFromHM(startHM);
  const endTs = endHM ? tsFromHM(endHM) : null;

  // MODE B : horaires — SEULEMENT si l'utilisateur les a réellement modifiés (et pas juste la durée).
  if(horairesModifies && !(durChanged && !startChanged && !endChanged)){
    if(startTs!=null && endHM){
      if(endTs==null){ toast('Heure de fin invalide'); return; }
      if(endTs < startTs){ toast('La fin ne peut pas précéder le début'); return; }
      const net = (endTs - startTs) - pauseMs;
      if(net < 0){ toast('Durée négative : les pauses dépassent l\'intervalle'); return; }
      t.start = startTs; t.end = endTs; t.pauseAt = null;
      prodSessUpsert(s); closeModal(); prodRenderBoard&&prodRenderBoard();
      toast('Temps mis à jour ✓'); return;
    }
    // Cas : seulement le début modifié (tâche reste en cours), pas de fin
    if(startTs!=null && !endHM && !t.end){
      t.start = startTs; t.pauseAt = null;
      prodSessUpsert(s); closeModal(); prodRenderBoard&&prodRenderBoard();
      toast('Début mis à jour ✓'); return;
    }
  }
  // MODE A : durée nette en minutes (défaut — s'applique dès que la durée est valide)
  if(!(durMin>=0) || isNaN(durMin)){ toast('Durée invalide'); return; }
  const durMs = Math.round(durMin*60000);
  if(t.end){
    // terminée : on garde le début, on recale la fin = début + durée + pauses
    t.end = t.start + durMs + pauseMs; t.pauseAt = null;
  } else {
    // en cours : on recale le début pour que la durée écoulée corresponde.
    if(prodTaskPaused(t)){
      t.pausedAccum = (+t.pausedAccum||0) + Math.max(0, Date.now()-(+t.pauseAt));
      t.pauseAt = null;
    }
    const pAccum = (+t.pausedAccum||0);
    t.start = Date.now() - durMs - pAccum;
  }
  prodSessUpsert(s); closeModal(); prodRenderBoard&&prodRenderBoard();
  toast('Temps mis à jour ✓');
}
// Supprime une tâche mais la CONSERVE dans une corbeille de session (s.trash) pour restauration.
// Propose un « Annuler » immédiat, et la tâche reste restaurable via la corbeille tant que la session vit.
function prodTaskDelete(taskId){
  const s = prodSessActive(); if(!s) return;
  const t = (s.tasks||[]).find(x=>x.id===taskId);
  s.tasks = (s.tasks||[]).filter(x=>x.id!==taskId);
  if(t){
    s.trash = s.trash||[];
    s.trash.unshift(Object.assign({}, t, {_deletedAt: Date.now()}));
    if(s.trash.length>50) s.trash = s.trash.slice(0,50);   // borne raisonnable
  }
  prodSessUpsert(s);
  if(!prodAnyRunning()) prodStopTicking();
  prodRenderBoard&&prodRenderBoard();
  if(t && typeof showUndoToast==='function'){
    showUndoToast(`Tâche « ${atShort?atShort(t.label):t.label} » supprimée`, ()=>prodTaskRestore(t.id));
  } else if(t){
    toast('Tâche supprimée — restaurable depuis la corbeille');
  }
}
// Restaure une tâche depuis la corbeille de session vers la liste active.
function prodTaskRestore(taskId){
  const s = prodSessActive(); if(!s) return;
  const idx = (s.trash||[]).findIndex(x=>x.id===taskId);
  if(idx<0){ toast('Tâche introuvable dans la corbeille'); return; }
  const t = s.trash[idx];
  delete t._deletedAt;
  s.trash.splice(idx,1);
  s.tasks = s.tasks||[]; s.tasks.push(t);
  prodSessUpsert(s);
  if(prodTaskRunning && prodTaskRunning(t)) prodStartTicking();
  prodRenderBoard&&prodRenderBoard();
  if(typeof closeModal==='function') closeModal();
  toast('Tâche restaurée ✓');
}
// Vide définitivement la corbeille de session.
function prodTrashPurge(){
  const s = prodSessActive(); if(!s) return;
  if(!(s.trash&&s.trash.length)) return;
  if(!confirm('Vider définitivement la corbeille ? Les tâches supprimées ne pourront plus être restaurées.')) return;
  s.trash = []; prodSessUpsert(s); prodRenderBoard&&prodRenderBoard();
  toast('Corbeille vidée');
}
// Ouvre la corbeille (liste des tâches supprimées, restaurables).
function prodTrashOpen(){
  const s = prodSessActive(); if(!s){ toast('Aucune session active'); return; }
  const items = (s.trash||[]);
  if(!items.length){ openModal(`<h3>Corbeille</h3><p class="note">Aucune tâche supprimée dans cette session.</p><div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`); return; }
  const fmtT = ms => { const d=new Date(ms); return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'); };
  const rows = items.map(t=>`<div class="prodb-done-row" style="align-items:center">
      <span class="prodt-dot" style="background:${t.color||'#ccc'}"></span>
      <span class="pd-label">${esc(t.label)}</span>
      <span class="pd-dur" style="color:#9a8a82">${t.end?prodDurShort(prodTaskNet(t)):'en cours'} · suppr. ${fmtT(t._deletedAt||Date.now())}</span>
      <button class="btn sm" style="margin-left:8px" onclick="prodTaskRestore('${t.id}')">↩ Restaurer</button>
    </div>`).join('');
  openModal(`<h3>Corbeille <span style="font-weight:400;color:#9a8a82">(${items.length})</span></h3>
    <p class="note">Tâches supprimées de cette session. Tu peux les restaurer.</p>
    <div style="max-height:50vh;overflow:auto">${rows}</div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="prodTrashPurge()">Vider la corbeille</button>
      <button class="btn" onclick="closeModal()">Fermer</button>
    </div>`);
}

// ---- Tick (rafraîchit les chronos en cours, 1 s) ----
let _prodTick = null;
function prodStartTicking(){ prodStopTicking(); _prodTick=setInterval(prodBoardTick, 1000); }
function prodStopTicking(){ if(_prodTick){ clearInterval(_prodTick); _prodTick=null; } }
function prodBoardTick(){
  const s = prodSessActive();
  if(!s || !(s.tasks||[]).some(prodTaskRunning)){ prodStopTicking(); }
  // met à jour les chronos affichés sans tout redessiner
  document.querySelectorAll('[data-prodchrono]').forEach(el=>{
    const s2=prodSessActive(); if(!s2) return;
    const t=(s2.tasks||[]).find(x=>x.id===el.getAttribute('data-prodchrono'));
    if(t) el.textContent = prodFmt(prodTaskNet(t));
  });
}
// Format ms → HH:MM:SS.
function prodFmt(ms){
  let s=Math.max(0,Math.floor(ms/1000));
  const h=Math.floor(s/3600); s-=h*3600;
  const m=Math.floor(s/60); s-=m*60;
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
}

/* ============================================================
   MON REVENU HORAIRE — outil évolutif (couches : 0 audit · 1 indicateur · 2 simulateur)
   Objectif : à partir des données réelles (ventes, temps mesuré, charges), estimer
   ce que l'artisan peut espérer se payer de l'heure, et où agir (produire / vendre).
   Couche 0 (présente) : AUDIT DE FIABILITÉ des données, sans calcul de revenu encore.
   ============================================================ */
const REVH_DEFAULT_DAYS = 90;

// BRIQUE 1 — TEMPS DE PRODUCTION LISSÉ PAR MACARON (min/pièce), sur une fenêtre glissante.
// Rapproche le temps total d'atelier (toutes tâches) des macarons FINIS vendables produits
// sur la même période. Lissé → stable, ne saute pas à chaque session (sert au coût de revient).
// Ne compte PAS les étapes intermédiaires comme des pièces (coques/ganache), pour ne pas
// gonfler le dénominateur ; mais leur TEMPS compte (il fait partie de la production).
async function prodTempsLissePerMacaron(jours){
  jours = +jours || REVH_DEFAULT_DAYS;
  const since = new Date(); since.setDate(since.getDate()-jours);
  const sinceStr = ymdLocal(since);

  // 1) Temps d'atelier RÉEL (ms) sur la fenêtre : enveloppe « mur à mur » de chaque session
  // (début 1ère tâche → fin dernière), pour refléter le temps vraiment passé avec chevauchements.
  // On n'additionne PAS les durées de tâches (qui se superposent dans le temps réel).
  const psAll = (typeof prodSessLoad==='function') ? prodSessLoad() : [];
  let msAtelier = 0;
  psAll.filter(s=>(s.date||'').slice(0,10) >= sinceStr).forEach(s=>{
    msAtelier += (typeof prodSessReelMs==='function') ? prodSessReelMs(s) : 0;
  });
  const minAtelier = msAtelier/60000;

  // 2) Macarons produits sur la fenêtre, en MACARONS ÉQUIVALENTS.
  // [FIX v1319 — PÉRIMÈTRE] AVANT : on ne comptait que les lots FINIS ('complet'/'assemble'), alors
  // que le numérateur (temps d'atelier) inclut TOUT le travail — dont la fabrication des COQUES,
  // souvent produites d'avance. En phase de constitution de stock (croissance, gros événement à
  // préparer), le temps montait sans que les macarons finis suivent : le coût de main-d'œuvre par
  // macaron était SURÉVALUÉ, donc les marges SOUS-ESTIMÉES — et ce chiffre alimente TOUTES les marges
  // de l'app (coutMODUnit), donc les décisions de prix.
  // On aligne les périmètres : une fournée de coques compte pour ce qu'elle vaut réellement, soit
  // ses coques ÷ 2 (un macaron = 2 coques). Même règle que l'écran d'analyse des temps.
  const prods = await db.productions.toArray().catch(()=>[]);
  const finis = prods.filter(p=>{
    const c = p.composant || 'complet';
    if(c!=='complet' && c!=='assemble' && c!=='coques') return false;   // exclut ganache/chantache/dégustation
    const d = (p.date || (p.prodTimestamp||'').slice(0,10) || '');
    return String(d).slice(0,10) >= sinceStr;
  });
  const nbMacarons = finis.reduce((a,p)=>{
    const q = (+p.qteReelle||+p.qteProduite||0);
    if(!(q>0)) return a;
    const c = p.composant || 'complet';
    // Conversion en macarons équivalents : les coques sont comptées en pièces (×2 par macaron).
    return a + ((c==='coques') ? (q / COQUES_PAR_MACARON) : q);
  }, 0);

  const minParMacaron = nbMacarons>0 ? (minAtelier/nbMacarons) : null;
  // Fiabilité : un minimum de temps ET de pièces pour que la moyenne ait du sens.
  const fiable = (minAtelier>=60 && nbMacarons>=100);
  return {
    jours, sinceStr,
    minAtelier: Math.round(minAtelier),
    nbMacarons,
    minParMacaron,
    minParMacaronArrondi: minParMacaron!=null ? Math.round(minParMacaron*100)/100 : null,
    fiable
  };
}

/* [RÉPARTITION FINE] Pour UNE session, répartit le temps réel entre les recettes selon le
   principe : à chaque instant, le temps se partage entre les recettes dont une tâche est ACTIVE
   à cet instant. Le temps où AUCUNE tâche-recette n'est active (vaisselle, nettoyage, pauses)
   est « non distribué » et réparti à parts égales, en fin de session, entre TOUTES les recettes
   couvertes. Renvoie { recipeId: ms }.
   Méthode : balayage par événements (sweep line) sur les intervalles [start,end] des tâches qui
   portent un recipeId. Entre deux instants-clés consécutifs, on partage la tranche entre les
   recettes actives sur cette tranche. */
function prodSessTempsParRecette(s, poids){
  const tasks = (s&&s.tasks)||[];
  // Intervalles des tâches portant au moins une recette. Une tâche peut porter plusieurs recettes
  // (meringue mutualisée) → toutes actives en même temps sur cet intervalle.
  const intervals = [];
  const allRecs = new Set();
  tasks.forEach(t=>{
    const recs = (Array.isArray(t.parfums)?t.parfums:[]).map(x=>+x).filter(r=>Number.isFinite(r)&&r>0);
    if(!recs.length) return;
    const st = +t.start||0;
    const en = +t.end || Date.now();
    if(st<=0 || en<=st) return;
    intervals.push({st, en, recs});
    recs.forEach(r=>allRecs.add(r));
  });
  const result = {};
  allRecs.forEach(r=>result[r]=0);
  if(!intervals.length) return result;

  // Points-clés (bornes) du balayage.
  const points = new Set();
  intervals.forEach(iv=>{ points.add(iv.st); points.add(iv.en); });
  const sorted = Array.from(points).sort((a,b)=>a-b);

  let distributed = 0;
  for(let i=0;i<sorted.length-1;i++){
    const a=sorted[i], b=sorted[i+1];
    const dur=b-a; if(dur<=0) continue;
    // Recettes actives sur la tranche [a,b] : union des recs des intervalles couvrant cette tranche.
    const actives = new Set();
    intervals.forEach(iv=>{ if(iv.st<=a && iv.en>=b){ iv.recs.forEach(r=>actives.add(r)); } });
    if(actives.size===0) continue;   // tranche sans tâche-recette (ne devrait pas arriver ici)
    // [v1310] Si des POIDS de production sont fournis, la tranche partagée est répartie AU PRORATA
    // des quantités (règle métier : 300 pièces et 10 pièces sur la même étape ne peuvent pas être
    // coupées 50/50). Sans poids, on conserve STRICTEMENT l'ancien comportement (parts égales) pour
    // ne rien casser des autres appelants (apprentissage MRP, coûts, temps par jour…).
    const arr = Array.from(actives);
    if(poids){
      const { parts } = _partsMutualisation(arr, poids);
      arr.forEach(r=>{ result[r] += dur * (parts[r]||0); });
    } else {
      const part = dur/actives.size;
      arr.forEach(r=>{ result[r]+=part; });
    }
    distributed += dur;
  }

  // Temps NON distribué = temps réel de session (mur à mur) − temps déjà attribué aux tranches.
  // Couvre la vaisselle/nettoyage/pauses où aucune tâche-recette n'était active.
  // [v1310] Ce temps COMMUN reste réparti à PARTS ÉGALES, même en mode prorata : c'est un choix
  // explicite de Benjamin (la vaisselle n'est pas proportionnelle au volume d'un parfum donné).
  const reel = (typeof prodSessReelMs==='function') ? prodSessReelMs(s) : 0;
  const nonDistribue = Math.max(0, reel - distributed);
  if(nonDistribue>0 && allRecs.size>0){
    const part = nonDistribue/allRecs.size;
    allRecs.forEach(r=>{ result[r]+=part; });
  }
  return result;
}

// [v1307] DÉCOMPOSITION TRAÇABLE DU TEMPS ACTIF PAR PARFUM (phase → tâche).
// Objectif : rendre VÉRIFIABLE le « temps actif » affiché par parfum. Pour un recipeId donné, on
// parcourt toutes les tâches chronométrées le concernant sur la fenêtre, on prend leur temps NET
// (pauses déduites, via prodTaskNet), on RÉPARTIT le temps d'une tâche mutualisée entre les parfums
// qu'elle porte (÷ nb de recettes actives — même règle que prodSessTempsParRecette, pour que la somme
// des détails = le total affiché), et on range chaque tâche sous sa PHASE puis son LABEL. Chaque ligne
// porte son nombre de mesures (nb) et son statut actif/passif (repos, cuisson…), pour tracer d'où vient
// chaque minute. Renvoie { total, actif, passif, phases:[{phase, ms, actif, passif, nb,
//   taches:[{label, ms, nb, passive}]}] } trié par temps décroissant.
// [v1316] ÉTAPES PRINCIPALES (règle métier de Benjamin) : une production se structure en 3 étapes
// réelles — confection des COQUES, confection de la GANACHE, et ASSEMBLAGE en produits finis. Tout le
// reste (vaisselle, mise en place) est du support. On réutilise la classification déjà en place
// (prodTaskMrpCategory) pour ne pas créer une 2e vérité qui divergerait.
const _ETAPES_ORDRE = ['Coques', 'Ganache', 'Assemblage', 'Support', 'Autre'];
function _etapePrincipale(task){
  const cat = (typeof prodTaskMrpCategory==='function') ? prodTaskMrpCategory(task) : null;
  if(cat==='coques')  return 'Coques';
  if(cat==='ganache') return 'Ganache';
  if(cat==='montage') return 'Assemblage';
  if(cat==='vaisselle' || cat==='entretien') return 'Support';
  return 'Autre';
}

function _tempsDecompoParParfum(recipeIds, jours, poids){
  // Accepte un id unique OU un ensemble/tableau d'ids (un parfum = parfois plusieurs recettes : GF + classique).
  const rids = new Set((recipeIds instanceof Set ? Array.from(recipeIds) : [].concat(recipeIds)).map(x=>+x).filter(Number.isFinite));
  const since = new Date(); since.setDate(since.getDate() - (+jours||90));
  const sinceStr = ymdLocal(since);
  const sessions = (typeof prodSessLoad==='function') ? prodSessLoad() : [];

  // phase -> { ms, actif, passif, nb, taches: { label -> { ms, nb, passive } } }
  const phases = {};
  // [v1316] étape principale (Coques / Ganache / Assemblage / Support) -> { ms, actif, passif, taches }
  const etapes = {};
  let total = 0, actif = 0, passif = 0;
  let reparti = 'prorata';   // devient 'egal' si au moins une tâche a dû basculer en repli

  sessions.filter(s=>(s.date||'').slice(0,10) >= sinceStr).forEach(s=>{
    // [FIX v1315 — CHRONOS PARALLÈLES] AVANT : on additionnait le temps NET de chaque tâche. Quand
    // deux chronos tournent EN MÊME TEMPS (ex. la cuisson tourne pendant que tu poches), leurs durées
    // s'additionnaient — alors que tu n'as travaillé qu'une heure. Le détail affichait donc le DOUBLE
    // du total de la carte (Framboise : détail 10 h 24 vs carte 5 h 07).
    // Règle métier (Benjamin) : « 2 chronos en parallèle pendant 1 h = 1 h de travail » → TEMPS MURAL.
    // On reprend donc EXACTEMENT le balayage par tranches de prodSessTempsParRecette : le temps d'une
    // tranche est compté UNE fois, puis réparti entre les recettes actives (au prorata des quantités),
    // et enfin ventilé sur les TÂCHES qui portent cette recette dans la tranche. Par construction, la
    // somme du détail redevient égale au total affiché.
    const intervals = [];
    (s.tasks||[]).forEach(t=>{
      const recs = (Array.isArray(t.parfums)?t.parfums:[]).map(x=>+x).filter(r=>Number.isFinite(r)&&r>0);
      if(!recs.length) return;
      const st = +t.start||0;
      const en = +t.end || Date.now();
      if(st<=0 || en<=st) return;
      intervals.push({ st, en, recs, task:t });
    });
    if(!intervals.length) return;

    const pts = new Set();
    intervals.forEach(iv=>{ pts.add(iv.st); pts.add(iv.en); });
    const sorted = Array.from(pts).sort((a,b)=>a-b);

    let distributed = 0;
    for(let i=0;i<sorted.length-1;i++){
      const a=sorted[i], b=sorted[i+1];
      const dur=b-a; if(dur<=0) continue;
      // Tâches réellement actives sur cette tranche (temps MURAL : la tranche ne vaut que `dur`).
      const actifs = intervals.filter(iv=>iv.st<=a && iv.en>=b);
      if(!actifs.length) continue;
      distributed += dur;

      // Recettes actives sur la tranche, et part de chacune (prorata des quantités produites).
      const recsTranche = new Set();
      actifs.forEach(iv=>iv.recs.forEach(r=>recsTranche.add(r)));
      if(!recsTranche.size) continue;
      const arr = Array.from(recsTranche);
      let parts;
      if(poids){
        const res = _partsMutualisation(arr, poids);
        parts = res.parts;
        if(!res.prorata) reparti = 'egal';
      } else {
        parts = {}; arr.forEach(r=>{ parts[r] = 1/arr.length; });
        reparti = 'egal';
      }

      // Pour CHAQUE recette de ce parfum : sa part de la tranche, ventilée sur les tâches qui la portent.
      Array.from(rids).forEach(rid=>{
        if(!recsTranche.has(rid)) return;
        const msRecette = dur * (parts[rid]||0);
        if(!(msRecette>0)) return;
        const porteuses = actifs.filter(iv=>iv.recs.includes(rid));
        if(!porteuses.length) return;

        // [v1316 — RÉPARTITION REPRÉSENTATIVE] Quand plusieurs tâches se chevauchent, le temps mural
        // de la tranche est partagé (on n'additionne pas : le chevauchement est justement le gain de
        // temps). Mais le partager À PARTS ÉGALES serait arbitraire : une tâche de 5 min pèserait
        // autant qu'une de 60 min. On répartit donc AU PRORATA DE LA DURÉE PROPRE de chaque tâche —
        // ce qui reflète la charge de travail réelle qu'elle représente.
        const dureeProp = iv => Math.max(1, (typeof prodTaskNet==='function') ? prodTaskNet(iv.task) : (iv.en - iv.st));
        const sommeDurees = porteuses.reduce((s,iv)=>s + dureeProp(iv), 0) || 1;

        porteuses.forEach(iv=>{
          const t = iv.task;
          const poidsTache = dureeProp(iv) / sommeDurees;
          // Les pauses restent déduites : ratio net/brut de la tâche sur la tranche.
          const brut = Math.max(1, (iv.en - iv.st));
          const net  = (typeof prodTaskNet==='function') ? prodTaskNet(t) : brut;
          const ratio = Math.max(0, Math.min(1, net / brut));
          const parTacheNet = msRecette * poidsTache * ratio;
          if(!(parTacheNet>0)) return;

          const phase = t.phase || 'Autre';
          const label = t.label || 'Tâche';
          const passive = (typeof prodIsPassive==='function') ? prodIsPassive(label) : false;
          // [v1316] ÉTAPE PRINCIPALE (règle métier Benjamin) : les 3 étapes qui structurent réellement
          // une production — confection des COQUES, confection de la GANACHE, ASSEMBLAGE en produits
          // finis. On réutilise la classification déjà existante (prodTaskMrpCategory).
          const etape = _etapePrincipale(t);

          const E = (etapes[etape] ||= { ms:0, actif:0, passif:0, taches:{} });
          E.ms += parTacheNet;
          if(passive) E.passif += parTacheNet; else E.actif += parTacheNet;
          const ET = (E.taches[label] ||= { ms:0, passive, _ids:new Set() });
          ET.ms += parTacheNet; ET._ids.add(t.id);

          const P = (phases[phase] ||= { ms:0, actif:0, passif:0, nb:0, taches:{} });
          P.ms += parTacheNet;
          if(passive) P.passif += parTacheNet; else P.actif += parTacheNet;
          const L = (P.taches[label] ||= { ms:0, nb:0, passive, _ids:new Set() });
          L.ms += parTacheNet;
          L._ids.add(t.id);                      // nb de MESURES = nb de tâches distinctes, pas de tranches
          total += parTacheNet;
          if(passive) passif += parTacheNet; else actif += parTacheNet;
        });
      });
    }

    // [v1307 — COHÉRENCE TRAÇABLE] Le total affiché sur la carte (via prodSessTempsParRecette) inclut
    // aussi le TEMPS NON DISTRIBUÉ de la session : les minutes où AUCUNE tâche rattachée à une recette
    // ne tournait (vaisselle, nettoyage, pauses, mise en place…), réparties à parts égales entre les
    // parfums de la séance. Sans cette ligne, la somme du détail serait INFÉRIEURE au total affiché et
    // le chiffre deviendrait invérifiable. On l'expose donc explicitement, sous son vrai nom.
    const recsSession = new Set();
    intervals.forEach(iv=>iv.recs.forEach(r=>recsSession.add(r)));
    if(recsSession.size && Array.from(rids).some(r=>recsSession.has(r))){
      // `distributed` vient du balayage ci-dessus : c'est le temps MURAL déjà attribué aux tranches.
      const reelSess = (typeof prodSessReelMs==='function') ? prodSessReelMs(s) : 0;
      const nonDistribue = Math.max(0, reelSess - distributed);
      if(nonDistribue>0){
        // Part de CE parfum : le commun (vaisselle, mise en place) est réparti à PARTS ÉGALES entre
        // les parfums de la séance — choix explicite de Benjamin : il ne dépend pas du volume.
        const miennes = Array.from(rids).filter(r=>recsSession.has(r)).length;
        const part2 = nonDistribue * (miennes / recsSession.size);
        if(part2>0){
          const P = (phases['Commun de séance'] ||= { ms:0, actif:0, passif:0, nb:0, taches:{} });
          P.ms += part2; P.actif += part2;
          const L = (P.taches['Vaisselle, nettoyage, mise en place, pauses'] ||= { ms:0, nb:0, passive:false, _ids:new Set() });
          L.ms += part2; L._ids.add('commun-'+s.id);
          // [v1316] Le commun de séance est du SUPPORT (ni coques, ni ganache, ni assemblage).
          const E = (etapes['Support'] ||= { ms:0, actif:0, passif:0, taches:{} });
          E.ms += part2; E.actif += part2;
          const ET = (E.taches['Vaisselle, nettoyage, mise en place, pauses'] ||= { ms:0, passive:false, _ids:new Set() });
          ET.ms += part2; ET._ids.add('commun-'+s.id);
          total += part2; actif += part2;
        }
      }
    }
  });

  const phasesArr = Object.keys(phases).map(nom=>{
    const P = phases[nom];
    const taches = Object.keys(P.taches).map(lbl=>{
      const T = P.taches[lbl];
      return { label:lbl, ms:T.ms, nb:(T._ids ? T._ids.size : (T.nb||0)), passive:T.passive };
    }).sort((a,b)=>b.ms-a.ms);
    const nbPhase = taches.reduce((s,t)=>s+t.nb, 0);
    return { phase:nom, ms:P.ms, actif:P.actif, passif:P.passif, nb:nbPhase, taches };
  }).sort((a,b)=>b.ms-a.ms);

  // [v1316] Étapes principales, dans l'ORDRE MÉTIER (Coques → Ganache → Assemblage → Support),
  // et non par temps décroissant : c'est l'ordre dans lequel Benjamin fabrique.
  const etapesArr = _ETAPES_ORDRE
    .filter(nom => etapes[nom] && etapes[nom].ms > 0)
    .map(nom => {
      const E = etapes[nom];
      const taches = Object.keys(E.taches).map(lbl=>{
        const T = E.taches[lbl];
        return { label:lbl, ms:T.ms, nb:(T._ids ? T._ids.size : 0), passive:T.passive };
      }).sort((a,b)=>b.ms-a.ms);
      return { etape:nom, ms:E.ms, actif:E.actif, passif:E.passif,
               part: total>0 ? (E.ms/total) : 0, taches };
    });

  return { total, actif, passif, phases:phasesArr, etapes:etapesArr, reparti };
}

// [CROISEMENT PHASE × PARFUM] Pour une session, répartit le temps réel par CATÉGORIE D'ÉTAPE
// (coques / ganache / montage) ET par recette (parfum), en réutilisant le balayage temporel de
// prodSessTempsParRecette mais en filtrant les tâches selon prodTaskMrpCategory.
// Permet d'obtenir « temps de ganache de la vanille » distinct de « temps de montage de la vanille ».
// Le temps non distribué (vaisselle, pauses) n'est PAS rattaché aux étapes de production.
// Renvoie { coques:{recipeId:ms}, ganache:{recipeId:ms}, montage:{recipeId:ms} }.
function prodSessTempsParCategorieParRecette(s){
  const tasks = (s&&s.tasks)||[];
  const CATS = ['coques','ganache','montage'];
  const out = { coques:{}, ganache:{}, montage:{} };

  CATS.forEach(cat=>{
    // Intervalles des tâches de CETTE catégorie portant au moins une recette.
    const intervals = [];
    const allRecs = new Set();
    tasks.forEach(t=>{
      const meta = { phase:t.phase, label:t.label };
      const c = (typeof prodTaskMrpCategory==='function') ? prodTaskMrpCategory(meta) : null;
      if(c!==cat) return;
      const recs = (Array.isArray(t.parfums)?t.parfums:[]).map(x=>+x).filter(r=>Number.isFinite(r)&&r>0);
      if(!recs.length) return;
      const st = +t.start||0;
      const en = +t.end || Date.now();
      if(st<=0 || en<=st) return;
      intervals.push({st, en, recs});
      recs.forEach(r=>allRecs.add(r));
    });
    if(!intervals.length) return;

    allRecs.forEach(r=>{ out[cat][r]=0; });
    const points = new Set();
    intervals.forEach(iv=>{ points.add(iv.st); points.add(iv.en); });
    const sorted = Array.from(points).sort((a,b)=>a-b);
    for(let i=0;i<sorted.length-1;i++){
      const a=sorted[i], b=sorted[i+1];
      const dur=b-a; if(dur<=0) continue;
      const actives = new Set();
      intervals.forEach(iv=>{ if(iv.st<=a && iv.en>=b){ iv.recs.forEach(r=>actives.add(r)); } });
      if(actives.size===0) continue;
      const part = dur/actives.size;
      actives.forEach(r=>{ out[cat][r]+=part; });
    }
  });
  return out;
}

// [CROISEMENT PHASE × PARFUM — agrégat fenêtre] Cumule sur N jours le temps mesuré par catégorie
// et par parfum (nom normalisé), avec les pièces produites, pour en déduire un temps fiable par
// (étape, parfum). Sert à alimenter le plan : « ganache vanille = X min (fixe), montage vanille = Y min/batch ».
// Renvoie { ganache:{nom:{minTotal, nbMac, nbSessions, fiable}},
//           montage:{nom:{minTotal, nbMac, nbSessions, fiable}},
//           coques:{nom:{minTotal, nbMac, nbSessions, fiable}} }.
async function prodTempsParEtapeParParfum(jours){
  jours = +jours || 90;
  const since = new Date(); since.setDate(since.getDate()-jours);
  const sinceStr = ymdLocal(since);
  const sessions = (typeof prodSessLoad==='function') ? prodSessLoad() : [];
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recName = rid => (recipes.find(r=>+r.id===+rid)||{}).produitNom || '';
  const norm = nom => (typeof aiNormalize==='function') ? aiNormalize(nom) : String(nom||'').toLowerCase().trim();

  const CATS = ['coques','ganache','montage'];
  // cat -> nomNorm -> { minTotal, nbSessions(Set) }
  const acc = { coques:{}, ganache:{}, montage:{} };
  const sessSet = { coques:{}, ganache:{}, montage:{} };

  sessions.filter(s=>(s.date||'').slice(0,10) >= sinceStr).forEach(s=>{
    const parCat = prodSessTempsParCategorieParRecette(s);
    CATS.forEach(cat=>{
      Object.keys(parCat[cat]||{}).forEach(rid=>{
        const nom = recName(rid); if(!nom) return;
        const k = norm(nom);
        const min = parCat[cat][rid]/60000;
        (acc[cat][k] ||= 0); acc[cat][k] += min;
        (sessSet[cat][k] ||= new Set()).add(s.id||s.date);
      });
    });
  });

  // Macarons produits par parfum (nom normalisé) sur la fenêtre — pour le prorata/fiabilité.
  const prods = await db.productions.toArray().catch(()=>[]);
  const macParNom = {};
  prods.forEach(p=>{
    const c = p.composant || 'complet';
    if(c!=='complet' && c!=='assemble') return;
    if(p.libre || p.recipeId==null) return;
    const d = (p.date || (p.prodTimestamp||'').slice(0,10) || '');
    if(String(d).slice(0,10) < sinceStr) return;
    const nom = recName(p.recipeId); if(!nom) return;
    const k = norm(nom);
    macParNom[k] = (macParNom[k]||0) + (+p.qteReelle||+p.qteProduite||0);
  });

  // [PLANCHER DE PLAUSIBILITÉ — MONTAGE] Garde-fou en attendant que les vraies mesures s'accumulent.
  // Le montage utilise la formule perBatch = minTotal/nbMac × TB. minTotal (temps pointé) et nbMac
  // (macarons produits) viennent de deux sources distinctes : un chrono trop court OU un gros volume
  // produit peut écraser le ratio et donner un perBatch absurde (ex. 1 min pour 60 macarons), qui
  // passe quand même le filtre 'fiable'. Règle métier (Benjamin) : garnir 60 macarons ne peut pas
  // descendre sous 15 min, grand minimum. Sous ce seuil, on REJETTE la mesure (fiable=false) → le
  // calcul retombe sur le fallback recette/défaut déjà prévu. On ne maquille pas le chiffre, on
  // écarte une donnée non crédible. Ne s'applique QU'AU montage (la ganache a une autre formule).
  const TB_PLAUS = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const MONTAGE_PERBATCH_MIN_PLAUSIBLE = 15;   // min/batch plancher (à affiner quand les vraies mesures arriveront)
  const out = { coques:{}, ganache:{}, montage:{} };
  CATS.forEach(cat=>{
    Object.keys(acc[cat]).forEach(k=>{
      const minTotal = acc[cat][k];
      const nbMac = macParNom[k]||0;
      const nbSessions = (sessSet[cat][k]||new Set()).size;
      // Fiable si assez de matière mesurée ET plusieurs sessions (la moyenne a du sens).
      let fiable = (minTotal>=10 && nbMac>=30 && nbSessions>=2);
      let rejetImplausible = false;
      if(cat==='montage' && fiable && nbMac>0){
        const perBatch = minTotal/nbMac*TB_PLAUS;
        if(perBatch < MONTAGE_PERBATCH_MIN_PLAUSIBLE){ fiable = false; rejetImplausible = true; }
      }
      out[cat][k] = { minTotal:Math.round(minTotal*10)/10, nbMac, nbSessions, fiable, rejetImplausible };
    });
  });
  return out;
}


// [ONGLET TEMPS/PARFUM] Affiche les temps réels mesurés à l'atelier, croisés par ÉTAPE et par PARFUM.
// Permet de vérifier que les mesures sont justes avant de s'en servir dans le plan opérationnel.

// ============================================================
// ATELIER — onglet « Mes tâches » : gérer les tâches personnalisées
// Lister, renommer, changer de phase, supprimer, et en créer de nouvelles.
// Les tâches perso sont stockées dans getSettings().prodCustomTasks, sous forme
// de chaîne (ancien format) ou d'objet {label, phase, color}. On normalise à l'écriture.
// ============================================================

// Normalise une entrée perso en objet {label, phase, color}.
function _mtNorm(c){
  if(typeof c==='string') return {label:c, phase:'Personnalisé', color:'#8a7a72'};
  return {label:c.label||'', phase:c.phase||'Personnalisé', color:c.color||'#8a7a72'};
}
// Couleur associée à une phase (reprend celle du catalogue si la phase existe).
function _mtPhaseColor(phase){
  const g = PROD_TASK_CATALOG.find(g=>g.phase===phase);
  if(g) return g.color;
  // phases spécifiques connues
  if(phase==='Préparation des coques (avant garnissage)') return '#d08a4a';
  return '#8a7a72';
}

function prodRenderMesTaches(){
  const host = document.getElementById('prodBoardHost');
  if(!host) return;
  const list = (getSettings().prodCustomTasks||[]).map(_mtNorm);

  const phaseOpts = PROD_PHASE_ORDER.map(p=>`<option value="${esc(p)}">${esc(p)}</option>`).join('');

  let rows;
  if(!list.length){
    rows = `<p class="note" style="text-align:center;padding:16px 0">Aucune tâche personnalisée pour l'instant. Crée-en une ci-dessous, ou lance une tâche personnalisée depuis le chrono.</p>`;
  } else {
    rows = list.map((c,i)=>`
      <div class="mt-row" style="display:flex;align-items:center;gap:8px;padding:11px 12px;border:1px solid var(--hair);border-radius:11px;margin-bottom:7px;background:#fff">
        <span style="width:10px;height:10px;border-radius:50%;background:${_mtPhaseColor(c.phase)};flex:none"></span>
        <div style="min-width:0;flex:1">
          <div style="font-weight:600;color:var(--bordeaux)">${esc(c.label)}</div>
          <div style="font-size:.74rem;color:#9a8a82">${esc(c.phase)}</div>
        </div>
        <button class="btn ghost sm" onclick="mtEdit(${i})" title="Renommer / changer de phase">✎</button>
        <button class="btn ghost sm" style="border-color:#e5b4ae;color:#b04a3e" onclick="mtDelete(${i})" title="Supprimer">🗑</button>
      </div>`).join('');
  }

  host.innerHTML = `
    <div class="card">
      <h3 style="margin:0 0 4px">🛠 Mes tâches personnalisées</h3>
      <p class="note" style="margin:0 0 12px">Renomme, reclasse ou supprime tes tâches. Vous pouvez aussi en créer de nouvelles en choisissant leur phase, pour qu'elles apparaissent au bon endroit dans le déroulé.</p>
      ${rows}
    </div>
    <div class="card">
      <h3 style="margin:0 0 8px">＋ Créer une tâche personnalisée</h3>
      <div class="field"><label>Nom de la tâche</label><input id="mt_new_label" placeholder="Ex. Tamisage de la poudre d'amande"></div>
      <div class="field"><label>Phase (emplacement dans le déroulé)</label>
        <select id="mt_new_phase">${phaseOpts}</select></div>
      <button class="btn gold" onclick="mtCreate()">Créer la tâche</button>
    </div>`;
}

// Écrit la liste normalisée dans les réglages.
function _mtSave(list){
  const s = getSettings();
  s.prodCustomTasks = list;
  saveSettings(s);
  if(typeof markUnsaved==='function') markUnsaved();
}

// ✎ Renommer / changer de phase.
function mtEdit(idx){
  const list = (getSettings().prodCustomTasks||[]).map(_mtNorm);
  const c = list[idx]; if(!c){ toast('Tâche introuvable'); return; }
  const phaseOpts = PROD_PHASE_ORDER.map(p=>`<option value="${esc(p)}"${p===c.phase?' selected':''}>${esc(p)}</option>`).join('');
  openModal(`<h3>Modifier la tâche</h3>
    <div class="field"><label>Nom de la tâche</label><input id="mt_ed_label" value="${esc(c.label)}"></div>
    <div class="field"><label>Phase</label><select id="mt_ed_phase">${phaseOpts}</select></div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="mtEditSave(${idx})">Enregistrer</button>
    </div>`);
}

function mtEditSave(idx){
  const list = (getSettings().prodCustomTasks||[]).map(_mtNorm);
  if(!list[idx]){ toast('Tâche introuvable'); return; }
  const label = (val('mt_ed_label')||'').trim();
  const phase = (val('mt_ed_phase')||'Personnalisé').trim();
  if(!label){ toast('Le nom ne peut pas être vide'); return; }
  // évite un doublon avec une autre entrée perso
  if(list.some((x,j)=>j!==idx && x.label===label)){ toast('Une tâche porte déjà ce nom'); return; }
  list[idx] = {label, phase, color:_mtPhaseColor(phase)};
  _mtSave(list);
  closeModal(); toast('Tâche modifiée ✓'); prodRenderMesTaches();
}

// 🗑 Supprimer.
function mtDelete(idx){
  const list = (getSettings().prodCustomTasks||[]).map(_mtNorm);
  const c = list[idx]; if(!c){ toast('Tâche introuvable'); return; }
  openModal(`<h3>Supprimer cette tâche ?</h3>
    <p class="note">« ${esc(c.label)} » sera retirée de tes tâches personnalisées. Les temps déjà mesurés avec cette tâche ne sont pas affectés.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" style="background:#b04a3e;border-color:#b04a3e" onclick="mtDeleteRun(${idx})">Supprimer</button>
    </div>`);
}

function mtDeleteRun(idx){
  const list = (getSettings().prodCustomTasks||[]).map(_mtNorm);
  if(!list[idx]){ toast('Tâche introuvable'); return; }
  list.splice(idx,1);
  _mtSave(list);
  closeModal(); toast('Tâche supprimée ✓'); prodRenderMesTaches();
}

// ＋ Créer.
function mtCreate(){
  const label = (val('mt_new_label')||'').trim();
  const phase = (val('mt_new_phase')||'Personnalisé').trim();
  if(!label){ toast('Donne un nom à la tâche'); return; }
  const list = (getSettings().prodCustomTasks||[]).map(_mtNorm);
  if(list.some(x=>x.label===label)){ toast('Une tâche porte déjà ce nom'); return; }
  list.push({label, phase, color:_mtPhaseColor(phase)});
  _mtSave(list);
  toast('Tâche créée ✓'); prodRenderMesTaches();
}

async function prodRenderTempsParfum(){
  const host = document.getElementById('prodBoardHost');
  if(!host) return;
  host.innerHTML = `<p class="note">⏳ Calcul des temps mesurés par parfum…</p>`;
  let agg;
  try{ agg = await prodTempsParEtapeParParfum(90); }
  catch(e){ console.error('tempsParEtapeParParfum',e); host.innerHTML='<p class="note" style="color:var(--red)">Erreur de calcul.</p>'; return; }

  const CATS = [
    { cle:'ganache', titre:'🍫 Ganache', col:'#7a4b2a', note:"Temps fixe par parfum (indépendant de la quantité)." },
    { cle:'montage', titre:'🔧 Montage', col:'#3f7d52', note:"Temps qui dépend de la quantité (au prorata des macarons)." },
    { cle:'coques',  titre:'🟤 Coques',  col:'#8a6d3b', note:"Inclut chablonnage et congélation pour les parfums concernés." }
  ];

  const sections = CATS.map(c=>{
    const data = agg[c.cle]||{};
    const noms = Object.keys(data).sort((a,b)=>data[b].minTotal-data[a].minTotal);
    if(!noms.length){
      return `<div class="panel" style="margin-bottom:12px">
        <h3 style="margin:0 0 4px;color:${c.col}">${c.titre}</h3>
        <p class="note" style="margin:0">Aucune mesure pour l'instant. Chronomètre des tâches de cette étape en rattachant le parfum.</p>
      </div>`;
    }
    const lignes = noms.map(nom=>{
      const d = data[nom];
      // Pour le montage : temps ramené à un batch de 60 (comparable au paramètre par défaut).
      const parBatch = (c.cle==='montage' && d.nbMac>0) ? Math.round((d.minTotal/d.nbMac*60)*10)/10 : null;
      const fiabBadge = d.fiable
        ? `<span style="background:#3f7d52;color:#fff;font-size:.56rem;font-weight:600;padding:1px 6px;border-radius:7px">✓ fiable</span>`
        : `<span style="background:#c9a227;color:#fff;font-size:.56rem;font-weight:600;padding:1px 6px;border-radius:7px">~ à confirmer</span>`;
      const detailMontage = parBatch!=null ? ` <span style="color:#9a8576;font-size:.74rem">(≈ ${parBatch} min / 60 mac)</span>` : '';
      return `<div class="sum-box" style="align-items:flex-start">
        <div style="flex:1">
          <div><b style="text-transform:capitalize">${esc(nom)}</b> · <b style="color:${c.col}">${d.minTotal} min</b>${detailMontage} ${fiabBadge}</div>
          <div style="font-size:.74rem;color:#9a8576;margin-top:1px">${d.nbMac} macarons mesurés · ${d.nbSessions} session${d.nbSessions>1?'s':''}</div>
        </div>
      </div>`;
    }).join('');
    return `<div class="panel" style="margin-bottom:12px">
      <h3 style="margin:0 0 2px;color:${c.col}">${c.titre}</h3>
      <p class="note" style="margin:0 0 8px">${c.note}</p>
      ${lignes}
    </div>`;
  }).join('');

  // [TEMPS DE RÉFÉRENCE] Rappel des valeurs utilisées en fallback (recette/défaut) + reset manuel.
  // Ces temps sont auto-appris (moyenne mobile) à chaque session validée. En cas de dérive, le bouton
  // les réinitialise aux valeurs par défaut. Le plancher de plausibilité empêche désormais une nouvelle
  // dérive sous le crédible (montage ≥ 15 min/batch).
  const _tref = getMrpTimes();
  const _lbl = { coques:'Coques (par meringue)', montage:'Montage (par batch de 60)', ganache:'Ganache (par batch)', vaisselle:'Vaisselle (par batch)', entretien:'Entretien (par session)' };
  const _trefRows = Object.keys(_lbl).map(k=>{
    const def = MRP_TIME_DEFAULTS[k].estimatedTime, cur = _tref[k].estimatedTime;
    const modifie = (cur!==def);
    return `<div class="sum-box"><span>${_lbl[k]}</span><b>${cur} min${modifie?` <span style="color:#9a8576;font-weight:400;font-size:.78rem">(défaut ${def})</span>`:''}</b></div>`;
  }).join('');
  const trefCard = `<div class="panel" style="margin-bottom:12px">
    <div style="font-weight:600;margin-bottom:8px">⏱️ Temps de référence (fallback)</div>
    <p class="note" style="margin-top:0">Valeurs utilisées quand aucune mesure fiable n'est disponible. Auto-apprises à chaque session, avec un plancher de plausibilité pour éviter les dérives.</p>
    ${_trefRows}
    <button class="btn ghost sm" style="margin-top:8px" onclick="mrpTimesResetConfirm()">↩︎ Réinitialiser aux valeurs par défaut</button>
  </div>`;

  host.innerHTML = `
    <div class="banner" style="background:#f4f7fb;border-color:#cdd9e6;margin-bottom:12px">🎯 <div>Temps <b>réellement mesurés</b> à l'atelier sur les 90 derniers jours, séparés par <b>étape</b> et par <b>parfum</b>. Plus tu chronomètres en rattachant le parfum, plus ces temps deviennent fiables (✓). Ils nourriront le plan de production : <b>mesuré si fiable, sinon ta saisie recette, sinon valeur par défaut</b>.</div></div>
    ${trefCard}
    ${sections}`;
}

// Reset manuel des temps de référence (avec confirmation, car efface l'historique d'apprentissage).
function mrpTimesResetConfirm(){
  openModal(`<h3>↩︎ Réinitialiser les temps de référence</h3>
    <p>Cela remet les temps de fallback (coques, montage, ganache…) à leurs <b>valeurs par défaut</b> et efface l'historique d'apprentissage (moyenne mobile). Tes <b>chronos et sessions</b> ne sont pas touchés — les temps se ré-apprendront aux prochaines productions.</p>
    <p class="note">Utile si une mesure aberrante a faussé une estimation.</p>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="mrpTimesResetDo()">↩︎ Réinitialiser</button></div>`);
}
function mrpTimesResetDo(){
  try{ localStorage.removeItem(MRP_TIME_KEY); }catch(e){swallow(e,'mrpTimesResetDo')}
  closeModal();
  toast('Temps de référence réinitialisés ✓');
  if(typeof prodRenderTempsParfum==='function' && typeof _atelierTab!=='undefined' && _atelierTab==='temps') prodRenderTempsParfum();
}

async function prodTempsParParfum(jours){
  jours = +jours || 90;
  const since = new Date(); since.setDate(since.getDate()-jours);
  const sinceStr = ymdLocal(since);
  const sessions = (typeof prodSessLoad==='function') ? prodSessLoad() : [];

  // 1) Temps d'atelier réparti FINEMENT par recette (minute par minute + temps non distribué).
  const msParRec = {};   // recipeId -> ms cumulés
  sessions.filter(s=>(s.date||'').slice(0,10) >= sinceStr).forEach(s=>{
    const parRec = prodSessTempsParRecette(s);   // {recipeId: ms} pour cette session
    Object.keys(parRec).forEach(rid=>{ msParRec[rid] = (msParRec[rid]||0) + parRec[rid]; });
  });

  // 2) Macarons finis par recette (recipeId) sur la fenêtre.
  const prods = await db.productions.toArray().catch(()=>[]);
  const macParRec = {};
  prods.forEach(p=>{
    const c = p.composant || 'complet';
    // [FIX v1319 — PÉRIMÈTRE, même bug que prodTempsLissePerMacaron] Le numérateur (temps d'atelier
    // rattaché à cette recette) inclut la fabrication des COQUES. Les exclure du dénominateur
    // surévaluait le temps par macaron — et donc le coût de main-d'œuvre du parfum, faussant le
    // CLASSEMENT DE RENTABILITÉ PAR PARFUM (un parfum dont on avait fait beaucoup de coques d'avance
    // paraissait anormalement coûteux). On compte en MACARONS ÉQUIVALENTS (coques ÷ 2).
    if(c!=='complet' && c!=='assemble' && c!=='coques') return;
    if(p.libre || p.recipeId==null) return;
    const d = (p.date || (p.prodTimestamp||'').slice(0,10) || '');
    if(String(d).slice(0,10) < sinceStr) return;
    const q = (+p.qteReelle||+p.qteProduite||0);
    if(!(q>0)) return;
    const macEq = (c==='coques') ? (q / COQUES_PAR_MACARON) : q;
    macParRec[p.recipeId] = (macParRec[p.recipeId]||0) + macEq;
  });

  // 3) Temps par macaron, par recette (quand on a temps ET pièces).
  const out = {};   // recipeId -> {minParMac, minAtelier, nbMac, fiable}
  Object.keys(msParRec).forEach(rid=>{
    const minAtelier = msParRec[rid]/60000;
    const nbMac = macParRec[rid]||0;
    if(nbMac>0){
      out[rid] = {
        minParMac: minAtelier/nbMac,
        minAtelier: Math.round(minAtelier),
        nbMac,
        // Fiable si assez de matière pour que la moyenne ait du sens (seuils volontairement bas par recette).
        fiable: (minAtelier>=20 && nbMac>=30)
      };
    }
  });
  return out;   // clés = recipeId
}
// Vue AGRÉGÉE PAR NOM normalisé de prodTempsParParfum (pour les écrans qui raisonnent par nom :
// ordonnanceur, cerveau). Fusionne les recettes de même nom (GF + classique) en cumulant temps
// et pièces, puis recalcule un temps moyen par macaron. Conserve un flag « fiable » global.
async function prodTempsParParfumParNom(jours){
  const parRec = await prodTempsParParfum(jours);
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recName = rid => (recipes.find(r=>+r.id===+rid)||{}).produitNom || '';
  const agg = {};   // nomNormalisé -> {minAtelier(min), nbMac}
  Object.keys(parRec).forEach(rid=>{
    const e = parRec[rid];
    const nom = recName(rid); if(!nom) return;
    const k = (typeof aiNormalize==='function') ? aiNormalize(nom) : nom.toLowerCase();
    (agg[k] ||= {minAtelier:0, nbMac:0});
    agg[k].minAtelier += (+e.minAtelier||0);
    agg[k].nbMac      += (+e.nbMac||0);
  });
  const out = {};
  Object.keys(agg).forEach(k=>{
    const a = agg[k];
    if(a.nbMac>0){
      out[k] = { minParMac:a.minAtelier/a.nbMac, minAtelier:Math.round(a.minAtelier), nbMac:a.nbMac,
                 fiable:(a.minAtelier>=20 && a.nbMac>=30) };
    }
  });
  return out;   // clés = noms normalisés
}

/* [TEMPS PAR PARFUM — brique croisement] Trouve les parfums probablement produits pendant
   une session de chronos d'atelier, par recoupement d'horodatage.
   Priorité 1 : productions dont la fabrication CHEVAUCHE la fenêtre de la session.
   Priorité 2 (repli) : productions du MÊME JOUR que la session.
   Renvoie { chevauche:[noms], memeJour:[noms], suggestions:[{parfum, source:'chevauche'|'jour'}] }.
   Aucune écriture : pure proposition, la confirmation se fait ailleurs.
*/
function sessFenetre(s){
  const tasks=(s&&s.tasks)||[];
  if(!tasks.length) return null;
  let minStart=Infinity, maxEnd=0;
  tasks.forEach(t=>{ const st=+t.start||0; const en=+t.end||Date.now();
    if(st>0 && st<minStart) minStart=st; if(en>maxEnd) maxEnd=en; });
  if(!isFinite(minStart) || maxEnd<=minStart) return null;
  return {start:minStart, end:maxEnd};
}

async function sessProdsChevauchantes(session){
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const prods = await db.productions.toArray().catch(()=>[]);
  const fen = sessFenetre(session);
  const jour = (session && session.date) ? String(session.date).slice(0,10) : '';
  const nomDe = p => (typeof prodNomComplet==='function') ? prodNomComplet(p, recipes) : '';

  const isoToMs = iso => { const t = Date.parse(iso||''); return isNaN(t)?0:t; };

  const setChevauche = new Map();   // nom normalisé -> nom affiché
  const setJour = new Map();
  prods.forEach(p=>{
    // On ne s'intéresse qu'aux productions de macarons (composants ou finis), pas aux autres objets.
    const comp = (typeof prodComposant==='function') ? prodComposant(p) : 'complet';
    const nom = nomDe(p);
    if(!nom || nom==='(recette supprimée)') return;
    const k = (typeof aiNormalize==='function') ? aiNormalize(nom) : nom.toLowerCase();

    // Fenêtre de fabrication de la production.
    const deb = isoToMs(p.prodDebutTs || p.prodTimestamp);
    const fin = isoToMs(p.prodTermineTs) || deb;

    // Priorité 1 : chevauchement horaire avec la session.
    if(fen && deb>0){
      const overlap = (deb <= fen.end) && (fin >= fen.start);
      if(overlap){ setChevauche.set(k, nom); return; }
    }
    // Priorité 2 : même jour que la session.
    const dProd = (p.date || (p.prodDebutTs||p.prodTimestamp||'').slice(0,10) || '');
    if(jour && String(dProd).slice(0,10)===jour){ setJour.set(k, nom); }
  });

  const chevauche = Array.from(setChevauche.values());
  // [DUO MERINGUE] Une fournée de meringue commune relie 2+ parfums (même meringueBatchId).
  // Si UN des parfums d'une fournée est détecté (chevauchement ou même jour), on coche AUSSI
  // ses binômes : le temps « meringue » est mutualisé, les deux parfums vont ensemble.
  const detectes = new Set([...setChevauche.keys(), ...setJour.keys()]);
  const batchParfums = {};   // meringueBatchId -> Map(normName -> displayName)
  prods.forEach(p=>{
    if(!p.meringueBatchId) return;
    const nom = nomDe(p); if(!nom || nom==='(recette supprimée)') return;
    const k = (typeof aiNormalize==='function') ? aiNormalize(nom) : nom.toLowerCase();
    (batchParfums[p.meringueBatchId] ||= new Map()).set(k, nom);
  });
  Object.values(batchParfums).forEach(m=>{
    // La fournée est-elle concernée par la session ? (au moins un de ses parfums détecté)
    const concernee = [...m.keys()].some(k=>detectes.has(k));
    if(!concernee) return;
    // Oui → on s'assure que TOUS les parfums de la fournée sont au moins en « même jour ».
    m.forEach((nom,k)=>{ if(!setChevauche.has(k) && !setJour.has(k)) setJour.set(k, nom); });
  });

  // Le repli "même jour" n'inclut pas ce qui chevauche déjà (évite les doublons).
  const memeJour = Array.from(setJour.entries()).filter(([k])=>!setChevauche.has(k)).map(([,v])=>v);
  const suggestions = [
    ...chevauche.map(p=>({parfum:p, source:'chevauche'})),
    ...memeJour.map(p=>({parfum:p, source:'jour'})),
  ];
  return { chevauche, memeJour, suggestions };
}

/* [TEMPS PAR PARFUM — confirmation fin de session] Après clôture d'une session de chronos,
   on propose les parfums probablement produits (croisement horaire + même jour, pré-cochés),
   l'utilisateur confirme/ajuste, et on écrit t.parfums sur les tâches de la session.
   La saisie se fait À FROID, une seule fois, pas en plein travail.
*/
async function prodSessParfumsConfirm(sessId){
  const s = (typeof prodSessGet==='function') ? prodSessGet(sessId) : null;
  if(!s){ toast('Session introuvable'); return; }
  const recipes = await db.recipes.toArray().catch(()=>[]);
  // Suggestions croisées (chevauchement horaire prioritaire, puis même jour).
  let crois = {chevauche:[], memeJour:[], suggestions:[]};
  try{ crois = await sessProdsChevauchantes(s) || crois; }catch(e){ console.error('sessParfums.crois',e); }
  const preCoche = new Set([...crois.chevauche, ...crois.memeJour].map(n=>aiNormalize(n)));

  // Parfums déjà déclarés sur la session (si on rouvre la confirmation).
  const dejaSet = new Set();
  (s.tasks||[]).forEach(t=> (Array.isArray(t.parfums)?t.parfums:[]).forEach(x=>{
    const nom = (typeof x==='number') ? ((recipes.find(r=>+r.id===+x)||{}).produitNom||'') : String(x||'');
    if(nom) dejaSet.add(aiNormalize(nom));
  }));
  const coche = (dejaSet.size>0) ? dejaSet : preCoche;

  // Liste de toutes les RECETTES (par id, pour distinguer GF/classique de même nom), suggérées en haut.
  const recsTri = recipes.slice().filter(r=>r.produitNom).sort((a,b)=>{
    const sa = preCoche.has(aiNormalize(a.produitNom))?0:1, sb = preCoche.has(aiNormalize(b.produitNom))?0:1;
    return sa-sb || (a.produitNom||'').localeCompare(b.produitNom||'');
  });
  // Pré-cochage : par recipeId si déjà déclaré, sinon par nom suggéré (croisement).
  const dejaIds = new Set();
  (s.tasks||[]).forEach(t=> (Array.isArray(t.parfums)?t.parfums:[]).forEach(x=>{ const rid=+x; if(Number.isFinite(rid)&&rid>0) dejaIds.add(rid); }));
  window._sessParfumId = sessId;
  window._sessRecList = recsTri.map(r=>r.id);

  const rows = recsTri.map(r=>{
    const k=aiNormalize(r.produitNom);
    const checkedById = dejaIds.has(r.id);
    const checked = (dejaIds.size>0 ? checkedById : coche.has(k)) ? 'checked' : '';
    const gfTag = r.grandFormat ? ' <span class="tag" style="background:#8a6d3b;color:#fff;font-size:.62rem">grand format</span>' : '';
    const src = crois.chevauche.map(n=>aiNormalize(n)).includes(k) ? '<span style="color:#3f7d52;font-size:.72rem">pendant le chrono</span>'
              : crois.memeJour.map(n=>aiNormalize(n)).includes(k) ? '<span style="color:#8a6d3b;font-size:.72rem">même jour</span>'
              : '';
    return `<label class="sum-box" style="align-items:center;cursor:pointer">
      <span style="flex:1">${esc(r.produitNom)}${gfTag} ${src?'<br>'+src:''}</span>
      <input type="checkbox" id="sp_${r.id}" ${checked} style="width:22px;height:22px"></label>`;
  }).join('');

  const dateTxt = s.date ? fmtDate(s.date) : '';
  openModal(`<h3>🎯 Quels parfums pour cette session ?</h3>
    <p class="note">Session du ${esc(dateTxt)}. Coche les parfums que tu as produits pendant cette session de chronos. Pré-coché à partir de tes productions — ajuste si besoin. Sert à affiner le temps par parfum.</p>
    ${rows || '<p class="note">Aucune recette.</p>'}
    <div class="modal-actions">
      <button class="btn ghost" style="margin-right:auto" onclick="closeModal()">Plus tard</button>
      <button class="btn gold" onclick="prodSessParfumsSave()">Confirmer</button>
    </div>`);
}

// Enregistre les recettes confirmées (recipeId) sur TOUTES les tâches de la session.
function prodSessParfumsSave(){
  const sessId = window._sessParfumId; if(sessId==null) return;
  const recIds = window._sessRecList||[];
  const choisis = recIds.filter(rid=>{ const el=document.getElementById('sp_'+rid); return el && el.checked; }).map(rid=>+rid);
  const s = (typeof prodSessGet==='function') ? prodSessGet(sessId) : null;
  if(!s){ closeModal(); return; }
  // [v1380] Cette confirmation SESSION écrase le parfum de CHAQUE tâche. Si Ben a fait des
  // réattributions fines par tâche (🖊), les écraser en silence détruirait son travail — on demande.
  if(s.parfumsParTache && !confirm('Des parfums ont été corrigés TÂCHE PAR TÂCHE sur cette session.\nAppliquer la même liste à toutes les tâches ÉCRASERA ces corrections.\nContinuer ?')) return;
  // On applique la liste de recettes (recipeId) à chaque tâche (le calcul répartira à parts égales par session).
  (s.tasks||[]).forEach(t=>{ t.parfums = choisis.slice(); });
  if(s.parfumsParTache) s.parfumsParTache = false;   // les corrections fines n'existent plus
  s.parfumsConfirmes = true;   // marqueur : confirmation faite
  if(typeof prodSessUpsert==='function') prodSessUpsert(s);
  closeModal();
  toast(choisis.length?`${choisis.length} recette(s) enregistrée(s) ✓`:'Aucune recette cochée');
  if(typeof markUnsaved==='function') markUnsaved();
}

// ════════════════════════════════════════════════════════════════════════════
// [v1380] JOURNAL DE L'ATELIER — réattribuer le parfum d'UNE tâche, et voir les
// parfums de chaque session en en-tête.
//
// LE BESOIN (Ben) : le bouton « 🎯 Parfums » existant travaille au niveau SESSION — il applique la
// même liste à TOUTES les tâches. Or une tâche peut être mal rattachée individuellement (une ganache
// pointée sur le mauvais parfum) : il faut pouvoir la corriger UNE PAR UNE depuis le journal, et le
// temps par parfum doit suivre. Il suit TOUT SEUL : prodSessTempsParRecette et
// _tempsDecompoParParfum relisent `t.parfums` à chaque calcul — la réattribution persistée suffit
// (prouvé par la suite v1380, avant/après sur le même moteur).
// ════════════════════════════════════════════════════════════════════════════

// Parfums distincts d'une session (PURE) : recipeIds valides, dans l'ordre de première apparition
// des tâches (l'ordre du travail réel, pas l'ordre alphabétique).
function _sessParfumsDistincts(s){
  const vus = new Set(); const out = [];
  ((s && s.tasks) || []).slice().sort((a,b)=>(+a.start||0)-(+b.start||0)).forEach(t=>{
    (Array.isArray(t.parfums)?t.parfums:[]).map(Number).filter(r=>Number.isFinite(r)&&r>0).forEach(r=>{
      if(vus.has(r)) return; vus.add(r); out.push(r);
    });
  });
  return out;
}

// Applique une réattribution de parfums à UNE tâche (PURE sur ses entrées : mute la session passée,
// c'est le contrat — l'appelant persiste). Retourne { ok, raison }.
// Règles : la tâche doit exister ; les ids sont assainis (nombres > 0, dédupliqués) ; une liste VIDE
// est PERMISE (détacher une tâche de tout parfum : vaisselle, rangement…) — le temps redevient alors
// du « commun » réparti à parts égales, comme décidé en v1310.
function _prodTacheParfumsApplique(s, taskId, rids){
  if(!s || !Array.isArray(s.tasks)) return { ok:false, raison:'Session introuvable.' };
  const t = s.tasks.find(x => String(x.id) === String(taskId));
  if(!t) return { ok:false, raison:'Tâche introuvable dans cette session.' };
  const propres = [...new Set((rids || []).map(Number).filter(r => Number.isFinite(r) && r > 0))];
  t.parfums = propres;
  // Une correction à la tâche vaut confirmation — et elle est plus fine que le niveau session :
  // le drapeau `parfumsParTache` protège ce travail d'un écrasement par le flux « 🎯 Parfums ».
  s.parfumsConfirmes = true;
  s.parfumsParTache = true;
  return { ok:true };
}

// Remplace le contenu du modal EN PLACE s'il est ouvert (règle v1375 : jamais fermer-puis-rouvrir
// à travers un saut async — le history.back différé refermerait le nouveau).
function _prodModalSwap(html){
  if(overlay && overlay.classList.contains('show') && modal){ modal.innerHTML = html; }
  else openModal(html);
}

// ── ÉCRAN 1 : la liste des tâches d'une session, parfum(s) visibles, tap pour corriger ──
async function prodSessTaches(sessId){
  const s = (typeof prodSessGet === 'function') ? prodSessGet(sessId) : null;
  if(!s){ toast('Session introuvable'); return; }
  const recipes = await db.recipes.toArray().catch(() => []);
  const nomOf = rid => { const r = recipes.find(x => +x.id === +rid); return r ? r.produitNom : ('#' + rid); };
  const tasks = (s.tasks || []).slice().sort((a,b)=>(+a.start||0)-(+b.start||0));
  const rows = tasks.length ? tasks.map(t => {
    const parfs = (Array.isArray(t.parfums)?t.parfums:[]).map(Number).filter(r=>Number.isFinite(r)&&r>0);
    const noms = parfs.length ? parfs.map(nomOf).map(esc).join(' + ') : '<span style="color:#9a8a82">aucun parfum (temps commun)</span>';
    const mut = parfs.length >= 2 ? ' <span class="tag" style="background:#8a6d3b;color:#fff;font-size:.6rem">mutualisée</span>' : '';
    const dur = (typeof prodTaskNet === 'function' && typeof prodDurShort === 'function') ? prodDurShort(prodTaskNet(t)) : '';
    return `<div class="sum-box" style="cursor:pointer;align-items:flex-start" onclick="prodTacheParfumsEdit('${escJs(s.id)}','${escJs(t.id)}')">
      <span style="flex:1"><b>${esc(t.label || 'Tâche')}</b> · ${dur}<br>
        <span style="font-size:.78rem;color:#7a6a62">🎨 ${noms}${mut}</span></span>
      <span style="color:#9a8a82">🖊</span>
    </div>`;
  }).join('') : '<p class="note">Aucune tâche dans cette session.</p>';
  _prodModalSwap(`<h3>🖊 Parfums par tâche</h3>
    <p class="note" style="margin-bottom:8px">Session du ${esc(s.date ? fmtDate(s.date) : '')}. Touche une tâche pour corriger le ou les parfums qui lui sont rattachés — le temps par parfum se recalcule à partir de là.</p>
    ${rows}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal(); if(typeof prodRenderJournal==='function') prodRenderJournal();">Fermer</button></div>`);
}

// ── ÉCRAN 2 : l'éditeur d'UNE tâche (cases à cocher, parfums de la session en tête) ──
async function prodTacheParfumsEdit(sessId, taskId){
  const s = (typeof prodSessGet === 'function') ? prodSessGet(sessId) : null;
  const t = s && (s.tasks || []).find(x => String(x.id) === String(taskId));
  if(!t){ toast('Tâche introuvable'); return; }
  const recipes = (await db.recipes.toArray().catch(() => [])).filter(r => r.produitNom);
  const actuels = new Set((Array.isArray(t.parfums)?t.parfums:[]).map(Number).filter(r=>Number.isFinite(r)&&r>0));
  const sessRids = new Set(_sessParfumsDistincts(s));
  // Parfums de la session d'abord (le cas normal : corriger vers un parfum de la fournée), puis le
  // reste par ordre alphabétique (le cas rare : un parfum jamais rattaché à cette session).
  const tri = recipes.slice().sort((a,b) => {
    const sa = sessRids.has(+a.id) ? 0 : 1, sb = sessRids.has(+b.id) ? 0 : 1;
    return sa - sb || (a.produitNom || '').localeCompare(b.produitNom || '');
  });
  window._tpeSess = sessId; window._tpeTask = taskId;
  window._tpeRecList = tri.map(r => r.id);
  const rows = tri.map(r => {
    const gfTag = r.grandFormat ? ' <span class="tag" style="background:#8a6d3b;color:#fff;font-size:.62rem">grand format</span>' : '';
    const sess = sessRids.has(+r.id) ? '<span style="color:#3f7d52;font-size:.72rem">dans cette session</span>' : '';
    return `<label class="sum-box" style="align-items:center;cursor:pointer">
      <span style="flex:1">${esc(r.produitNom)}${gfTag}${sess ? '<br>' + sess : ''}</span>
      <input type="checkbox" id="tpe_${r.id}" ${actuels.has(+r.id) ? 'checked' : ''} style="width:22px;height:22px"></label>`;
  }).join('');
  _prodModalSwap(`<h3>🖊 ${esc(t.label || 'Tâche')}</h3>
    <p class="note" style="margin-bottom:8px">Coche le ou les parfums de cette tâche (plusieurs = mutualisée). Aucune case = temps commun (vaisselle, rangement…), réparti à parts égales.</p>
    ${rows || '<p class="note">Aucune recette.</p>'}
    <div class="modal-actions">
      <button class="btn ghost" style="margin-right:auto" onclick="prodSessTaches('${sessId}')">← Retour</button>
      <button class="btn gold" onclick="prodTacheParfumsSave()">Enregistrer</button>
    </div>`);
}

async function prodTacheParfumsSave(){
  const sessId = window._tpeSess, taskId = window._tpeTask;
  const s = (typeof prodSessGet === 'function') ? prodSessGet(sessId) : null;
  if(!s){ closeModal(); return; }
  const choisis = (window._tpeRecList || []).filter(rid => { const el = document.getElementById('tpe_' + rid); return el && el.checked; });
  const r = _prodTacheParfumsApplique(s, taskId, choisis);
  if(!r.ok){ toast(r.raison); return; }
  if(typeof prodSessUpsert === 'function') prodSessUpsert(s);
  if(typeof markUnsaved === 'function') markUnsaved();
  toast(choisis.length ? 'Parfum(s) de la tâche mis à jour ✓ — temps par parfum recalculé' : 'Tâche passée en temps commun ✓');
  prodSessTaches(sessId);   // retour à la liste, EN PLACE
}


// Collecte unique des données brutes sur une fenêtre de N jours.
// Sert de socle commun aux 3 couches (audit, indicateur, simulateur).
async function revenuHoraireData(arg){
  // [v1083] La période peut être : un NOMBRE de jours (compat : derniers N jours jusqu'à aujourd'hui),
  // ou un OBJET {start, end} pour une période précise au jour près (comme la comptabilité).
  let sinceStr, untilStr, jours;
  if(arg && typeof arg==='object'){
    sinceStr = arg.start || '0000-01-01';     // pas de borne basse → tout depuis le début
    untilStr = arg.end   || '9999-12-31';     // pas de borne haute → jusqu'à aujourd'hui/futur
    // durée de la fenêtre demandée, en jours (sert aux calculs de couverture/charges)
    const d0 = new Date((arg.start||'1970-01-01')+'T00:00:00');
    const d1 = new Date((arg.end||today())+'T00:00:00');
    jours = Math.max(1, Math.round((d1 - d0)/86400000) + 1);
  } else {
    jours = +arg || REVH_DEFAULT_DAYS;
    const since = new Date(); since.setDate(since.getDate()-jours);
    sinceStr = ymdLocal(since);
    untilStr = '9999-12-31';
  }
  // Helper : une date (YYYY-MM-DD) est-elle dans la fenêtre [sinceStr, untilStr] ?
  const inWin = ds => { ds=(ds||'').slice(0,10); return ds && ds>=sinceStr && ds<=untilStr; };

  // 1) TEMPS MESURÉ (en heures) sur la fenêtre : pointeuse (workSessions) + atelier (prodSessions)
  const ws = await db.workSessions.toArray().catch(()=>[]);
  const wsIn = ws.filter(s=>inWin(s.date));
  const hPointeuse = wsIn.reduce((a,s)=>a+(+s.dureeHeures|| ((+s.dureeMin||0)/60) ||0),0);

  const psAll = (typeof prodSessLoad==='function') ? prodSessLoad() : [];
  const psIn = psAll.filter(s=>inWin(s.date));
  let msAtelier = 0;
  psIn.forEach(s=>{ (s.tasks||[]).forEach(t=>{ msAtelier += (typeof prodTaskNet==='function')?prodTaskNet(t):0; }); });
  const hAtelier = msAtelier/3600000;

  const heuresMesurees = round3(hPointeuse + hAtelier);

  // [v1082] COUVERTURE TEMPORELLE DES POINTAGES : sur combien de jours DISTINCTS as-tu réellement
  // pointé du temps (pointeuse + atelier) ? Sert à juger si le temps mesuré couvre la période du CA.
  // Le revenu horaire n'a de sens que si le temps pointé représente bien le travail de la période ;
  // sinon (ex. 34,9 h pointées pour plusieurs mois de CA), diviser la marge par ce temps est trompeur.
  const _joursPointes = new Set();
  wsIn.forEach(s=>{ const ds=(s.date||'').slice(0,10); if(ds) _joursPointes.add(ds); });
  psIn.forEach(s=>{ const ds=(s.date||'').slice(0,10); if(ds) _joursPointes.add(ds); });
  const nbJoursPointes = _joursPointes.size;
  let pointageMinStr=null, pointageMaxStr=null;
  if(nbJoursPointes>0){
    const arr=[..._joursPointes].sort();
    pointageMinStr=arr[0]; pointageMaxStr=arr[arr.length-1];
  }

  // 2) CA ENCAISSÉ sur la fenêtre (cash basis), via les paiements datés des commandes + marchés clos
  const orders = await db.orders.toArray().catch(()=>[]);
  const clients = await db.clients.toArray().catch(()=>[]);
  const _cliNom = id => { const c=clients.find(x=>x.id===id); return c?(c.nom||c.prenom||'Client'):'Client'; };
  let caCommandes = 0;
  // [v1325] VENTILATION marchandise / prestation, avec la MÊME règle que la base URSSAF
  // (partServiceCommande). Le revenu horaire appliquait jusqu'ici le taux marchandise (12,3 %) à
  // TOUT le CA, prestations comprises — alors qu'elles cotisent à 25,6 %. Il sous-estimait donc les
  // cotisations, et surestimait d'autant ce qu'il te restait de l'heure.
  let caGoods = 0, caService = 0;
  const detailCommandes = [];   // [v1077] {label, montant} par commande encaissée sur la fenêtre
  orders.forEach(o=>{
    // [v1194] Source unique d'encaissement : paiementsDe(o) (registre + repli legacy daté),
    // IDENTIQUE au dashboard (caDuMois) et à la compta (computeAccounting). L'ancien repli
    // « regs sinon o.datePaiement » divergeait : il ratait une commande legacy « Payé » sans
    // datePaiement (comptée ailleurs) et comptait à tort une commande datée mais non payée.
    let encO = 0;
    paiementsDe(o).forEach(p=>{ if(inWin(p.date)) encO += (+p.montant||0); });
    if(encO>0){
      caCommandes += encO;
      // Prorata service/marchandise appliqué à l'ENCAISSÉ de la fenêtre (et non au montant total
      // de la commande) — exactement comme computeMonthlyBilan le fait sur l'encaissé du mois.
      const _svc = money2(encO * partServiceCommande(o));
      caService += _svc; caGoods += money2(encO - _svc);
      detailCommandes.push({ label:_cliNom(o.clientId)+(o.dateLivraison?' · '+o.dateLivraison.slice(0,10):''), montant:money2(encO) });
    }
  });
  detailCommandes.sort((a,b)=>b.montant-a.montant);
  const markets = await db.markets.toArray().catch(()=>[]);
  // [v1091] On date le CA d'un marché par la DATE OÙ IL A EU LIEU (mk.date, saisie par Benjamin),
  // et seulement à défaut par la date de clôture. La clôture est une action administrative datée à
  // today() : s'y fier rangeait le CA d'un marché de Noël clos en juin DANS juin. La date événement
  // est la bonne base d'encaissement (les ventes sur marché sont encaissées le jour même).
  const mkDateFin = mk => (mk.date||mk.dateCloture||'');
  const closIn = markets.filter(mk=>mk.statut==='clos' && inWin(mkDateFin(mk)));
  let caMarches = 0;
  const detailMarches = [];     // [v1077] {label, montant} par marché clos sur la fenêtre
  // [FIX v1336] LE FOND DE CAISSE ÉTAIT COMPTÉ COMME DU CHIFFRE D'AFFAIRES.
  // Les espèces étaient sommées BRUTES. Or le fond de caisse, c'est l'argent que Benjamin met
  // LUI-MÊME dans la caisse le matin pour rendre la monnaie — ce n'est pas une vente. Sa compta le
  // retire depuis toujours ; le revenu horaire l'oubliait, et surestimait donc son revenu de l'heure.
  // Une règle écrite à deux endroits finit toujours par diverger : elle n'est plus écrite qu'une fois.
  closIn.forEach(mk=>{ const m=caMarcheEncaisse(mk);
    caMarches += m; detailMarches.push({ label:(mk.nom||'Marché')+(mkDateFin(mk)?' · '+mkDateFin(mk).slice(0,10):''), montant:m }); });
  detailMarches.sort((a,b)=>b.montant-a.montant);
  const caEncaisse = money2(caCommandes + caMarches);
  // [v1325] Un marché, c'est de la vente de marchandise pure (aucune prestation de service).
  // Même règle que computeMonthlyBilan.
  caGoods = money2(caGoods + caMarches);
  caService = money2(caService);

  // 3) CHARGES (réelles, datées) sur la fenêtre + charges récurrentes actives (référence mensuelle)
  const charges = await db.charges.toArray().catch(()=>[]);
  const chargesIn = charges.filter(c=>inWin(c.date));
  const totalCharges = money2(chargesIn.reduce((a,c)=>a+(+c.montant||0),0));
  const detailChargesPonct = chargesIn.map(c=>({ label:(c.libelle||c.categorie||'Charge')+(c.date?' · '+c.date.slice(0,10):''), montant:money2(+c.montant||0) })).sort((a,b)=>b.montant-a.montant);
  const recur = (typeof getRecurringCharges==='function'?getRecurringCharges():[]).filter(m=>m.actif!==false && +m.montant>0);
  const chargesRecurMensuel = money2(recur.reduce((a,m)=>a+(+m.montant||0),0));
  const detailRecur = recur.map(m=>({ label:m.libelle||m.categorie||'Récurrent', montant:money2(+m.montant||0) })).sort((a,b)=>b.montant-a.montant);

  // 4) CAPACITÉ À VENDRE : taux d'invendus moyen des marchés clos de la fenêtre.
  //    Le taux n'est pas stocké sur le marché : on le recalcule via marketTotals (comme partout).
  let invendusSum=0, invendusN=0;
  if(closIn.length){
    const recipes = await db.recipes.toArray().catch(()=>[]);
    const recipeItems = await db.recipeItems.toArray().catch(()=>[]);
    const lots = await db.materialLots.toArray().catch(()=>[]);
    const avgUnit = (typeof avgMacaronCost==='function') ? avgMacaronCost(recipes, recipeItems, lots) : 0;
    for(const mk of closIn){
      const moves = await db.marketMoves.where('marketId').equals(mk.id).toArray().catch(()=>[]);
      const T = marketTotals(mk, moves, avgUnit);
      if(typeof T.tauxInvendus==='number'){ invendusSum+=T.tauxInvendus; invendusN++; }
    }
  }
  const tauxInvendusMoyen = invendusN>0 ? Math.round(invendusSum/invendusN) : null;

  // [v1076] DURÉE RÉELLE D'ACTIVITÉ sur la fenêtre. Sert à étendre correctement les charges récurrentes
  // mensuelles : on ne peut pas multiplier un coût mensuel par la fenêtre théorique (« Tout » = 99999 j
  // = 3333 mois !). On borne au temps réellement écoulé entre la 1re donnée de la fenêtre et la FIN
  // de la fenêtre (aujourd'hui par défaut, ou la date de fin si une période perso passée est demandée).
  const _aujStr = today();
  const _finStr = (untilStr && untilStr < '9999-12-31') ? (untilStr < _aujStr ? untilStr : _aujStr) : _aujStr;
  const _auj = new Date(_finStr+'T00:00:00');
  const _dates = [];
  orders.forEach(o=>{
    // [v1194] Mêmes dates de paiement que le CA ci-dessus (source unique paiementsDe), pour que
    // la durée d'activité soit bornée exactement par les encaissements réellement comptés.
    paiementsDe(o).forEach(p=>{ const ds=(p.date||'').slice(0,10); if(inWin(ds)) _dates.push(ds); });
  });
  closIn.forEach(mk=>{ const ds=mkDateFin(mk).slice(0,10); if(ds) _dates.push(ds); });
  chargesIn.forEach(c=>{ const ds=(c.date||'').slice(0,10); if(ds) _dates.push(ds); });
  wsIn.forEach(s=>{ const ds=(s.date||'').slice(0,10); if(ds) _dates.push(ds); });
  psIn.forEach(s=>{ const ds=(s.date||'').slice(0,10); if(ds) _dates.push(ds); });
  let moisActivite;
  if(_dates.length){
    const _min = _dates.reduce((a,b)=> a<b?a:b);
    const _d0 = new Date(_min+'T00:00:00');
    const _joursReels = Math.max(1, Math.round((_auj - _d0)/86400000) + 1);
    // On prend le plus PETIT entre la fenêtre demandée et la durée réelle écoulée.
    const _joursBorne = Math.min(jours, _joursReels);
    moisActivite = _joursBorne/30;
  } else {
    // Aucune donnée datée : on retombe sur la fenêtre, mais bornée à 12 mois pour rester sain.
    moisActivite = Math.min(jours, 365)/30;
  }
  moisActivite = Math.round(moisActivite*100)/100;

  // [v1082] TAUX DE COUVERTURE : est-ce que les pointages s'étendent sur (à peu près) toute la période
  // d'activité, ou seulement sur un petit bout ? On compare l'amplitude des jours pointés (1er→dernier)
  // à l'amplitude de la période d'activité. Faible → le temps mesuré ne représente pas la période.
  const joursActivite = (moisActivite*30) || 0;       // durée de la période, en jours
  let amplitudePointage = 0;
  if(pointageMinStr && pointageMaxStr){
    amplitudePointage = Math.round((new Date(pointageMaxStr+'T00:00:00') - new Date(pointageMinStr+'T00:00:00'))/86400000) + 1;
  }
  // couverture = part de la période d'activité réellement « balayée » par des pointages.
  const couverture = (joursActivite>0) ? Math.min(1, amplitudePointage/joursActivite) : 0;

  return {
    jours, sinceStr, untilStr,   // [v1326] bornes de la fenêtre exposées : le coût d'emballage doit pouvoir filtrer sur la MÊME période que le CA
    heuresMesurees, hPointeuse:round3(hPointeuse), hAtelier:round3(hAtelier),
    nbSessionsPointeuse: wsIn.length, nbSessionsAtelier: psIn.length,
    nbJoursPointes, amplitudePointage, joursActivite:Math.round(joursActivite),
    couverture: Math.round(couverture*100)/100,   // [v1082] 0..1 : couverture temporelle des pointages
    pointageMinStr, pointageMaxStr,
    caEncaisse, caCommandes:money2(caCommandes), caMarches:money2(caMarches),
    caGoods, caService,   // [v1325] ventilation URSSAF (règle partagée avec computeMonthlyBilan)
    totalCharges, chargesRecurMensuel, nbCharges: chargesIn.length,
    nbMarchesClos: closIn.length, tauxInvendusMoyen,
    moisActivite,   // [v1076] durée réelle d'activité (mois), pour étendre les charges récurrentes
    // [v1077] DÉTAILS pour traçabilité (cartes cliquables de l'écran revenu horaire)
    detailCommandes, detailMarches, detailChargesPonct, detailRecur
  };
}

// ============================================================================
//  [v1326] L'EMBALLAGE ÉTAIT GRATUIT.
// ----------------------------------------------------------------------------
//  Dans revenuHoraireCalcul, `coutEmballages` était initialisé à 0… et n'était JAMAIS
//  calculé. Le commentaire l'assumait à demi-mot (« approche prudente : si non calculable
//  finement, laissé à 0 (n'invente pas) »). Sauf que ce n'était PAS prudent : mettre 0
//  n'est pas s'abstenir, c'est affirmer que l'emballage ne coûte rien. Chaque coffret,
//  chaque ruban, chaque sachet acheté par Benjamin sortait gratuit de ce calcul — et son
//  revenu horaire s'en trouvait SURESTIMÉ.
//
//  Le plus frustrant : l'app SAIT chiffrer un emballage. Elle le fait déjà
//    • par commande — computeOrderMargins.coutEmb (hiérarchie FIFO réelle, avec ratio
//      d'estimation pour les commandes de reprise sans détail) ;
//    • par marché  — marketTotals.coutEmb (réel : stock d'emballages avant − après).
//  Le revenu horaire ne le lui a simplement jamais demandé.
//
//  RÈGLE CLÉ — l'emballage suit l'ENCAISSEMENT, comme le CA. Le revenu horaire raisonne en
//  trésorerie (cash basis) : une commande encaissée à 50 % sur la fenêtre n'y apporte que
//  50 % de son CA. Elle ne doit donc y apporter que 50 % de son emballage. Compter 100 % du
//  carton en face de 50 % de la recette fabriquerait une fausse perte.
//
//  Pure : ne lit aucune base. On lui passe ce qui a été mesuré ailleurs.
//    cmds    : [{ encaisse, montant, coutEmb, coutEmbEstime }]
//    marches : [{ coutEmb, coutEmbEstime }]
// ============================================================================
function coutEmballagesFenetre(cmds, marches){
  let reel = 0, estime = 0;
  const detail = [];

  (cmds || []).forEach(c => {
    const enc = Math.max(0, +c.encaisse || 0);
    const tot = Math.max(0, +c.montant || 0);
    if(!(enc > 0) || !(tot > 0)) return;
    // Part encaissée de la commande sur la fenêtre (bornée à 1 : un trop-perçu ou un
    // arrondi ne doit pas faire compter 130 % du carton).
    const part = Math.min(1, enc / tot);
    const emb = money2((+c.coutEmb || 0) * part);
    const est = money2((+c.coutEmbEstime || 0) * part);
    if(emb <= 0) return;
    reel = money2(reel + emb);
    estime = money2(estime + est);
    detail.push({ label: c.label || 'Commande', montant: emb, estime: est > 0 });
  });

  // Un marché clos est encaissé le jour même, en totalité : pas de prorata à appliquer.
  (marches || []).forEach(m => {
    const emb = money2(+m.coutEmb || 0);
    if(emb <= 0) return;
    reel = money2(reel + emb);
    estime = money2(estime + money2(+m.coutEmbEstime || 0));
    detail.push({ label: m.label || 'Marché', montant: emb, estime: (+m.coutEmbEstime || 0) > 0 });
  });

  detail.sort((a, b) => b.montant - a.montant);
  return {
    total: reel,
    estime,                                   // part du total qui repose sur une ESTIMATION
    mesure: money2(reel - estime),            // part réellement mesurée (FIFO / stock)
    partEstimee: reel > 0 ? Math.round(estime / reel * 100) : 0,
    detail
  };
}

// BRIQUE 3 — REVENU HORAIRE GLOBAL RÉEL.
// Ce que tu peux te payer de l'heure = marge avant rémunération ÷ temps total travaillé.
//  • numérateur = CA encaissé − matières et consommables − emballages − charges fixes.
//    La main-d'œuvre n'est PAS déduite : c'est précisément ce qu'on cherche à chiffrer.
//    [v1325] Cette promesse était FAUSSE jusqu'ici — voir le FIX du double comptage ci-dessous.
//  • dénominateur = temps total = atelier (production) + pointeuse (hors-production).
//  • trois paliers fournis : avant cotisations, après cotisations, puis APRÈS IMPÔT (revHoraireNet).
//    Seul le dernier est comparable à un salaire net.
async function revenuHoraireCalcul(arg){
  // [v1083] accepte un nombre de jours (compat) OU un objet {start,end} (période précise).
  const d = await revenuHoraireData((arg && typeof arg==='object') ? arg : (+arg || REVH_DEFAULT_DAYS));
  const s = getSettings();

  // Coût matières + emballages des VENTES de la période, via l'analyse de rentabilité par parfum
  // (coutVentes = pièces vendues × coût de revient matière unitaire ; déjà calculé ailleurs).
  let coutMatieres = 0, coutEmballages = 0;
  // [v1325] On garde trace du coût de revient COMPLET et de sa part main-d'œuvre, pour rendre le
  // numérateur entièrement traçable (« voici ce que j'ai déduit, et ce que je n'ai PAS déduit »).
  let coutMOD = 0, coutVentesFenetre = 0;
  // [v1326] Détail du coût d'emballage (total, part estimée, ligne à ligne).
  let _emb = { total:0, estime:0, mesure:0, partEstimee:0, detail:[] };
  // Même fenêtre EXACTEMENT que celle du CA (bornes remontées par revenuHoraireData) : un emballage
  // compté sur une période et une recette sur une autre fabriquerait une marge fantaisiste.
  const inWinEmb = ds => { ds=(ds||'').slice(0,10); return ds && ds>=(d.sinceStr||'0000-01-01') && ds<=(d.untilStr||'9999-12-31'); };
  let _anomaliesCout = [];   // [v1075] recettes au coût unitaire implausible, écartées du calcul
  try{
    const [recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions] = await Promise.all([
      db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray(), db.materials.toArray(),
      db.orders.toArray(), db.markets.toArray(), db.marketMoves.toArray(), db.productions.toArray()
    ]);
    const A = analyzeFlavorProfitability({recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions, settings:s});
    // [v1075] GARDE-FOU DE PLAUSIBILITÉ. Un coût de revient matière par macaron au-delà de ce seuil
    // n'est pas un vrai coût : c'est presque toujours une recette mal paramétrée (rendement saisi à 1
    // au lieu de ~60, ou prix matière aberrant). Sans ce filtre, UNE recette fausse fait exploser le
    // coût total (ex. 47 €/pièce × 3000 pièces = 142 000 €) et rend le revenu horaire absurdement négatif.
    // On ÉCARTE ces lignes du calcul, on les SIGNALE, et on dégrade la confiance — plutôt qu'un faux chiffre.
    const SEUIL_COUT_UNIT_PLAUSIBLE = 8;   // €/macaron — borne haute très généreuse (réel ~0,30–2 €)
    let coutVentesTotal = 0;
    // [FIX v1325 — LE DOUBLE COMPTAGE DE TA MAIN-D'ŒUVRE] Le commentaire de cette fonction promet que
    // « la main-d'œuvre N'est PAS déduite : c'est justement ce qu'on cherche à rémunérer ». C'était
    // FAUX. `coutVentes` = piècesVendues × coutRevientUnit, et coutRevientUnit = matières +
    // consommables + coutMODUnit (la main-d'œuvre D'ATELIER, dès que laborEnabled est actif).
    // L'app soustrayait donc ta paie du numérateur… puis divisait par les heures qu'elle venait de
    // te payer, et appelait le résultat « ce que tu peux te payer de l'heure ». Elle te retirait
    // purement et simplement ton propre taux horaire.
    // On accumule désormais la MOD à part, pour pouvoir la RENDRE au numérateur.
    let coutMODTotal = 0;
    (A.rows||[]).forEach(r=>{
      const cu = (r.cost && +r.cost.coutRevientUnit) || 0;
      const cv = +r.coutVentes||0;
      if(cu > SEUIL_COUT_UNIT_PLAUSIBLE && (r.piecesVendues>0)){
        _anomaliesCout.push({ nom:r.nom||'?', coutUnit:money2(cu), pieces:round3(r.piecesVendues),
                              rendement:(r.cost&&r.cost.rendement)||null });
        return;   // écartée du total
      }
      coutVentesTotal += cv;
      // Part main-d'œuvre des MÊMES pièces vendues (même périmètre, mêmes exclusions : sinon on
      // rendrait une MOD relative à des lignes dont le coût a été écarté).
      coutMODTotal += (+r.piecesVendues||0) * ((r.cost && +r.cost.coutMODUnit) || 0);
    });
    coutVentesTotal = money2(coutVentesTotal);
    coutMODTotal = money2(coutMODTotal);
    const caTotalAnalyse = (A.totals && +A.totals.ca) || (A.rows||[]).reduce((a,r)=>a + (+r.ca||0), 0);
    // prorata : part du CA de la fenêtre sur le CA total analysé (évite de surcompter,
    // car l'analyse couvre toutes les périodes, pas seulement la fenêtre).
    const ratio = caTotalAnalyse>0 ? Math.min(1, d.caEncaisse/caTotalAnalyse) : 0;
    coutVentesFenetre = money2(coutVentesTotal * ratio);   // coût de revient COMPLET (MOD incluse)
    coutMOD = money2(coutMODTotal * ratio);                // dont main-d'œuvre d'atelier
    // Le numérateur ne doit retenir QUE la matière et les consommables : la main-d'œuvre est
    // précisément ce que le revenu horaire cherche à rémunérer. La déduire ici, puis diviser par
    // ces mêmes heures, revenait à la compter deux fois.
    coutMatieres = money2(coutVentesFenetre - coutMOD);
    // [v1075 — DIAG, lecture seule] Trace des recettes écartées pour le débogage (rubrique Technique).
    try{
      if(typeof diagPublish==='function' && _anomaliesCout.length){
        diagPublish('revhAnomalies', '⚠ Revenu horaire — coûts de revient écartés', {
          'Seuil de plausibilité': SEUIL_COUT_UNIT_PLAUSIBLE+' €/macaron',
          'Recettes écartées': _anomaliesCout.map(a=>`${a.nom} : ${a.coutUnit} €/pièce${a.rendement!=null?` (rendement ${a.rendement})`:''} × ${a.pieces} vendues`),
          'Effet': 'Ces lignes auraient ajouté un coût matière aberrant. Écartées du numérateur du revenu horaire.',
          'À corriger': 'Vérifier le rendement (nb par batch) et les prix matière de ces recettes.'
        });
      }
    }catch(e){swallow(e,'revenuHoraireCalcul')}

    // [FIX v1326 — L'EMBALLAGE ÉTAIT GRATUIT] AVANT, il n'y avait ici que ce commentaire :
    //   « emballages : estimés via coût d'emballage moyen par macaron vendu (table packaging)
    //     approche prudente : si non calculable finement, laissé à 0 (n'invente pas). »
    // Mettre 0 n'est PAS s'abstenir : c'est affirmer que l'emballage est gratuit. Chaque coffret,
    // ruban et sachet sortait donc gratuit du numérateur, et le revenu horaire était SURESTIMÉ.
    // Or l'app sait parfaitement les chiffrer — elle le fait déjà par commande et par marché.
    // On le lui demande enfin, en respectant la base TRÉSORERIE : l'emballage suit l'encaissement.
    const _cmdsEmb = [];
    orders.forEach(o=>{
      let encO = 0;
      paiementsDe(o).forEach(p=>{ if(inWinEmb(p.date)) encO += (+p.montant||0); });
      if(!(encO>0)) return;
      let m=null;
      try{ m = computeOrderMargins(o, recipes, recipeItems, lots, mats); }
      catch(e){ swallow(e,'revh emballage commande'); return; }
      if(!m || !(+m.coutEmb>0)) return;
      _cmdsEmb.push({ label:'Commande'+(o.id?' #'+o.id:''), encaisse:encO, montant:(+o.montant||0),
                      coutEmb:+m.coutEmb||0, coutEmbEstime:+m.coutEmbEstime||0 });
    });

    const _marchesEmb = [];
    const _mkDateFin = mk => (mk.date||mk.dateCloture||'');
    const _avgUnit = (typeof avgMacaronCost==='function') ? avgMacaronCost(recipes, recipeItems, lots) : 0;
    markets.filter(mk=>mk.statut==='clos' && inWinEmb(_mkDateFin(mk))).forEach(mk=>{
      try{
        const mvs = (marketMoves||[]).filter(mv=>mv.marketId===mk.id);
        const T = marketTotals(mk, mvs, _avgUnit);
        if(T && +T.coutEmb>0){
          _marchesEmb.push({ label:(mk.nom||'Marché'), coutEmb:+T.coutEmb||0, coutEmbEstime:+T.coutEmbEstime||0 });
        }
      }catch(e){ swallow(e,'revh emballage marché'); }
    });

    _emb = coutEmballagesFenetre(_cmdsEmb, _marchesEmb);
    coutEmballages = _emb.total;
  }catch(e){ console.error('revh coûts ventes', e); }

  // Charges fixes sur la fenêtre : récurrent mensuel × DURÉE RÉELLE D'ACTIVITÉ + charges ponctuelles datées.
  // [v1076] On utilise moisActivite (borné au temps réellement écoulé) et PAS jours/30 : sinon la vue
  // « Tout » (99999 j) multiplierait le récurrent par 3333 mois → charges fictives de ~146 000 €.
  const moisEquiv = (d.moisActivite!=null && d.moisActivite>0) ? d.moisActivite : ((d.jours||90)/30);
  const chargesFixes = money2(d.chargesRecurMensuel*moisEquiv + d.totalCharges);
  // [v1076 — DIAG] Trace du calcul des charges fixes (évite le retour du bug « 3333 mois »).
  try{
    if(typeof diagPublish==='function'){
      diagPublish('revhCharges', '🧮 Revenu horaire — calcul des charges fixes', {
        'Fenêtre demandée': ((d.jours||0)>=99999?'Tout':(d.jours||0)+' j'),
        'Durée réelle d\'activité retenue': moisEquiv.toFixed(2)+' mois',
        'Récurrent mensuel': euro(d.chargesRecurMensuel),
        'Charges ponctuelles datées': euro(d.totalCharges),
        'Charges fixes totales': euro(chargesFixes),
        'Garde-fou': 'moisEquiv borné à la durée réelle écoulée (et non jours/30) pour ne pas multiplier le récurrent par une fenêtre théorique géante.'
      });
    }
  }catch(e){swallow(e,'revenuHoraireCalcul')}

  // [FIX v1325 — LE TAUX UNIQUE] AVANT : `cotisations = caEncaisse × socialGoods`, c'est-à-dire le
  // taux MARCHANDISE (12,3 %) appliqué à TOUT le CA — prestations comprises, alors qu'elles cotisent
  // à 25,6 %. Les cotisations étaient donc sous-estimées, et ce qui « restait de l'heure »
  // d'autant surestimé. On applique désormais les DEUX taux, sur la ventilation URSSAF réelle
  // (même règle que computeMonthlyBilan : une seule vérité par commande).
  const cotisGoods   = money2((+d.caGoods||0)   * (+s.socialGoods||0)/100);
  const cotisService = money2((+d.caService||0) * (+s.socialService||0)/100);
  const cotisations  = money2(cotisGoods + cotisService);

  // [v1325] L'IMPÔT SUR LE REVENU était totalement absent — comme il l'était du point mort (v1324).
  // En micro-BIC, la base imposable est un pourcentage forfaitaire du CA, puis la tranche marginale
  // s'applique. C'est de l'argent qui sort du compte, exactement comme les cotisations : l'ignorer,
  // c'est promettre un revenu horaire que tu ne toucheras jamais.
  const baseIrGoods   = money2((+d.caGoods||0)   * (1 - (+s.irAbattementGoods||0)/100));
  const baseIrService = money2((+d.caService||0) * (1 - (+s.irAbattementService||0)/100));
  const baseImposable = money2(baseIrGoods + baseIrService);
  const impotRevenu   = money2(baseImposable * (+s.irTrancheMarginale||0)/100);

  // Numérateur — marge avant rémunération. La main-d'œuvre n'y est PLUS déduite (fix du double
  // comptage) : c'est bien elle que le revenu horaire cherche à chiffrer.
  const margeAvantRemu  = money2(d.caEncaisse - coutMatieres - coutEmballages - chargesFixes);
  const margeApresCotis = money2(margeAvantRemu - cotisations);
  const margeApresImpot = money2(margeApresCotis - impotRevenu);

  const h = d.heuresMesurees;
  // [v1082] GARDE-FOU « PAS DE CHIFFRE ABSURDE ». Le revenu horaire ne se calcule QUE si le temps
  // mesuré couvre vraiment la période du CA. Trois conditions cumulatives doivent tenir :
  //  (1) un minimum d'heures pointées (sinon l'échantillon est trop maigre) ;
  //  (2) les pointages s'étendent sur une part suffisante de la période d'activité (couverture) ;
  //  (3) une cohérence d'échelle : pas des mois de CA pour quelques heures pointées.
  // Si une condition manque, on N'AFFICHE PAS de taux : on l'admet honnêtement et on dit ce qui manque.
  const SEUIL_HEURES_MIN = 8;          // au moins ~1 journée de travail pointée
  const SEUIL_COUVERTURE = 0.5;        // les pointages couvrent au moins la moitié de la période
  // Heures théoriques minimales attendues si on avait pointé ~ne serait-ce qu'un peu chaque semaine
  // de la période : sert à détecter le cas « beaucoup de mois, presque pas d'heures ».
  const semainesPeriode = Math.max(1, (d.joursActivite||0)/7);
  const heuresAttenduesMin = semainesPeriode * 2;   // hypothèse plancher très basse : 2 h/semaine
  const ratioVraisemblance = heuresAttenduesMin>0 ? (h/heuresAttenduesMin) : 0;

  const raisonsAbstention = [];
  if(h < SEUIL_HEURES_MIN) raisonsAbstention.push('pas assez d\'heures pointées');
  if((d.couverture||0) < SEUIL_COUVERTURE) raisonsAbstention.push('couverture temporelle insuffisante');
  if(ratioVraisemblance < 0.25) raisonsAbstention.push('échelle incohérente (beaucoup de mois, peu d\'heures)');
  const calculable = (h>0 && raisonsAbstention.length===0);

  const revAvant = calculable ? money2(margeAvantRemu/h) : null;
  const revApres = calculable ? money2(margeApresCotis/h) : null;
  // [v1325] LE CHIFFRE QUI COMPTE VRAIMENT : ce qu'il te reste de l'heure, une fois l'URSSAF ET
  // l'impôt payés. C'est celui-là qu'il faut comparer au SMIC, pas les deux précédents.
  const revNet = calculable ? money2(margeApresImpot/h) : null;

  return {
    ...d,
    coutMatieres, coutEmballages, chargesFixes, cotisations,
    // [v1325] TRAÇABILITÉ : on expose ce qu'on a déduit ET ce qu'on a délibérément NON déduit.
    coutVentesFenetre,   // coût de revient complet des ventes (matière + consommables + MOD)
    coutMOD,             // … dont main-d'œuvre d'atelier : RENDUE au numérateur (fix du double comptage)
    embDetail: _emb.detail, embEstime: _emb.estime, embMesure: _emb.mesure, embPartEstimee: _emb.partEstimee,   // [v1326]
    cotisGoods, cotisService,
    baseImposable, impotRevenu, trancheIr: (+s.irTrancheMarginale||0),
    margeAvantRemu, margeApresCotis, margeApresImpot,
    revHoraireAvantCotis: revAvant,
    revHoraireApresCotis: revApres,
    revHoraireNet: revNet,   // [v1325] net d'URSSAF ET d'impôt — le seul comparable au SMIC
    heures: h,
    calculable, raisonsAbstention,   // [v1082] le calcul s'abstient si les données ne le permettent pas
    anomaliesCout: _anomaliesCout   // [v1075] recettes écartées car coût unitaire implausible
  };
}

// COUCHE 0 — AUDIT : évalue la fiabilité de chaque source et un niveau de confiance global.
// Aucun revenu n'est encore calculé ici : on prépare le terrain honnêtement.
function revenuHoraireAudit(d){
  const checks = [];
  // a) Temps mesuré — on juge la COUVERTURE (le temps couvre-t-il la période ?), pas que le volume.
  const _couvPct = Math.round((d.couverture||0)*100);
  checks.push({
    cle:'temps', label:'Temps de travail mesuré',
    niveau: (d.heuresMesurees>=8 && (d.couverture||0)>=0.5) ? 'ok' : (d.heuresMesurees>0 ? 'warn' : 'ko'),
    detail: d.heuresMesurees>0
      ? `${d.heuresMesurees.toFixed(1)} h sur ${d.nbJoursPointes||0} jour(s) pointé(s) · couvre ${_couvPct}% de la période. ${(d.couverture||0)<0.5?'Trop peu pour un revenu horaire fiable.':'Couverture suffisante.'}`
      : 'Aucun temps mesuré sur la période — lance tes chronos pour fiabiliser le calcul.'
  });
  // b) CA encaissé
  checks.push({
    cle:'ca', label:'Chiffre d\'affaires encaissé',
    niveau: d.caEncaisse>0 ? 'ok' : 'ko',
    detail: d.caEncaisse>0
      ? `${euro(d.caEncaisse)} encaissés (${euro(d.caCommandes)} commandes + ${euro(d.caMarches)} marchés)`
      : 'Aucun encaissement détecté sur la période.'
  });
  // c) Charges
  checks.push({
    cle:'charges', label:'Charges (coûts fixes)',
    niveau: (d.totalCharges>0 || d.chargesRecurMensuel>0) ? 'ok' : 'warn',
    detail: (d.totalCharges>0 || d.chargesRecurMensuel>0)
      ? `${euro(d.totalCharges)} sur la période${d.chargesRecurMensuel>0?` · ${euro(d.chargesRecurMensuel)}/mois récurrent`:''}`
      : 'Aucune charge saisie — ton revenu serait surestimé. Renseigne tes charges fixes.'
  });
  // d) Capacité à vendre (lien production → vente)
  checks.push({
    cle:'vente', label:'Capacité à écouler (marchés)',
    niveau: d.nbMarchesClos>0 ? (d.tauxInvendusMoyen!=null ? 'ok' : 'warn') : 'warn',
    detail: d.nbMarchesClos>0
      ? `${d.nbMarchesClos} marché(s) clôturé(s)${d.tauxInvendusMoyen!=null?` · ${d.tauxInvendusMoyen}% d'invendus en moyenne`:''}`
      : 'Pas de marché clôturé sur la période — la capacité de vente reste à estimer.'
  });
  // e) [v1075] Anomalies de coût détectées (recettes au coût unitaire implausible, écartées).
  const nbAnom = (d.anomaliesCout||[]).length;
  if(nbAnom>0){
    checks.push({
      cle:'anomalie', label:'Cohérence des coûts de revient',
      niveau:'warn',
      detail:`${nbAnom} recette${nbAnom>1?'s':''} au coût anormalement élevé (${(d.anomaliesCout||[]).slice(0,3).map(a=>esc(a.nom)).join(', ')}${nbAnom>3?'…':''}) — probablement un rendement ou un prix matière mal saisi. ${nbAnom>1?'Elles ont':'Elle a'} été écartée${nbAnom>1?'s':''} du calcul pour ne pas le fausser.`
    });
  }
  // f) [v1326] Fiabilité du coût d'emballage. Il valait 0 € jusqu'en v1325 (l'emballage était
  // gratuit) ; maintenant qu'il est compté, il faut dire s'il est MESURÉ ou ESTIMÉ.
  const _embTot = +d.coutEmballages || 0;
  const _embPct = +d.embPartEstimee || 0;
  checks.push({
    cle:'emballage', label:'Coût des emballages',
    niveau: _embTot<=0 ? 'ko' : (_embPct>50 ? 'warn' : 'ok'),
    detail: _embTot<=0
      ? 'Aucun coût d\'emballage détecté. Si tu emballes bien tes macarons, c\'est que tes coffrets ne sont pas paramétrés — ton revenu horaire est alors SURESTIMÉ.'
      : (_embPct>0
          ? `${euro(_embTot)} sur la période, dont ${_embPct}% estimé (commandes de reprise sans détail). ${_embPct>50?'La majorité repose sur une estimation : à prendre avec prudence.':'L\'essentiel est mesuré au réel.'}`
          : `${euro(_embTot)} sur la période, entièrement mesuré au réel (FIFO commandes + stock marchés).`)
  });
  const nbOk = checks.filter(c=>c.niveau==='ok').length;
  let confiance, confLabel;
  // [v1082] Si le temps mesuré ne couvre pas la période, le revenu horaire n'est PAS calculé.
  // La confiance le dit franchement (priorité sur tout le reste).
  const semainesP = Math.max(1, (d.joursActivite||0)/7);
  const ratioVrais = (semainesP*2)>0 ? (d.heuresMesurees/(semainesP*2)) : 0;
  const nonCalculable = !(d.heuresMesurees>=8 && (d.couverture||0)>=0.5 && ratioVrais>=0.25);
  if(nonCalculable){
    confiance='ko';
    confLabel='Indéterminée — pas assez de temps pointé pour rapporter la marge à un horaire fiable. Le revenu horaire n\'est pas affiché tant que tes pointages ne couvrent pas la période.';
  }
  else if(nbAnom>0){
    confiance='warn';
    confLabel=`Moyenne — ${nbAnom} coût${nbAnom>1?'s':''} incohérent${nbAnom>1?'s':''} écarté${nbAnom>1?'s':''} du calcul. Corrige ${nbAnom>1?'ces recettes':'cette recette'} pour fiabiliser le résultat.`;
  }
  else if(nbOk>=4){ confiance='ok'; confLabel='Élevée — les estimations seront fiables.'; }
  else if(nbOk>=2){ confiance='warn'; confLabel=`Moyenne — ${nbOk}/4 sources fiables, estimations indicatives.`; }
  else { confiance='ko'; confLabel=`Faible — ${nbOk}/4 sources fiables, complète tes données d'abord.`; }
  return { checks, nbOk, confiance, confLabel, nbAnomalies:nbAnom, nonCalculable };
}

let _revhDays = REVH_DEFAULT_DAYS;
// [v1083] Mode période : 'jours' (derniers N jours) ou 'perso' (dates précises au jour près).
let _revhMode = 'jours';
let _revhDateDebut = '';   // YYYY-MM-DD (vide = pas de borne basse)
let _revhDateFin = '';     // YYYY-MM-DD (vide = jusqu'à aujourd'hui)
// [v1077] LIGNE TRAÇABLE : une carte cliquable du calcul du revenu horaire.
//  - libelle / valeur : ce qui s'affiche replié (toujours visible).
//  - formule : phrase « comment ce chiffre est obtenu » (en clair).
//  - lignes : [{label, montant}] détail réel poste par poste / commande par commande.
//  - vue / vueLabel : écran source vers lequel renvoyer (bouton « voir l'écran complet »).
//  - sousTotal : libellé du total du détail (def. « Total »).
//  - neg : true si la ligne est une soustraction (affiche « − »).
//  - accent : true pour les lignes de résultat (marge), mises en gras.
function revhLigneTracable(o){
  o = o||{};
  const sign = o.neg ? '− ' : '';
  const valAff = (o.valeurStr!=null) ? o.valeurStr : (sign + euro(o.valeur||0));
  const aDetail = (Array.isArray(o.lignes) && o.lignes.length) || o.formule;
  const lab = o.accent ? `<b>${esc(o.libelle)}</b>` : esc(o.libelle);
  const valHtml = o.accent ? `<b>${valAff}</b>` : `<b>${valAff}</b>`;
  if(!aDetail){
    return `<div class="sum-box"${o.borderTop?' style="border-top:1px solid #e6dccd"':''}><span>${lab}</span>${valHtml}</div>`;
  }
  // corps déplié
  const det = (o.lignes||[]).slice(0, o.max||12).map(l=>
    `<div class="sum-box" style="background:#fff"><span style="font-size:.84rem">${esc(l.label)}</span><b style="font-size:.84rem">${l.neg?'− ':''}${euro(l.montant)}</b></div>`
  ).join('');
  const reste = (o.lignes && o.lignes.length>(o.max||12)) ? `<p class="note" style="margin:4px 2px">+ ${o.lignes.length-(o.max||12)} autre(s)…</p>` : '';
  const totLab = o.sousTotal || 'Total';
  const totLigne = (o.lignes && o.lignes.length>1)
    ? `<div class="sum-box" style="background:#fff;border-top:1px solid #ece1d2"><span style="font-size:.84rem"><b>${esc(totLab)}</b></span><b style="font-size:.84rem">${sign}${euro(o.valeur||0)}</b></div>` : '';
  const btn = o.vue ? `<div style="margin-top:8px"><button class="btn ghost sm" onclick="goView('${o.vue}')">${esc(o.vueLabel||'Voir l\'écran complet')} ›</button></div>` : '';
  const formule = o.formule ? `<p class="note" style="margin:2px 2px 8px"><b>Comment c'est obtenu :</b> ${o.formule}</p>` : '';
  return `<details class="revh-trace">
    <summary class="sum-box" style="cursor:pointer;list-style:none${o.borderTop?';border-top:1px solid #e6dccd':''}"><span>${lab} <span class="revh-chevron" style="color:#b39a86;font-size:.74rem">détail ›</span></span>${valHtml}</summary>
    <div style="padding:6px 4px 4px">${formule}${det}${reste}${totLigne}${btn}</div>
  </details>`;
}
async function renderRevenuHoraire(){
  const main=document.getElementById('main'); if(!main) return;
  main.innerHTML = `<div class="topbar"><div><h1>Mon revenu horaire</h1><p>Chargement…</p></div></div>`;
  let d, audit, calc;
  // [v1083] période : derniers N jours, ou plage précise {start,end}.
  const periodeArg = (_revhMode==='perso')
    ? { start:_revhDateDebut||null, end:_revhDateFin||null }
    : _revhDays;
  try{ calc = await revenuHoraireCalcul(periodeArg); d = calc; audit = revenuHoraireAudit(d); }
  catch(e){ console.error('revenuHoraire',e); main.innerHTML=`<div class="topbar"><div><h1>Mon revenu horaire</h1></div></div><div class="panel"><p class="note">Erreur de chargement des données.</p></div>`; return; }

  const dot = n => n==='ok'?'#3f7d52':(n==='warn'?'#d98324':'#b3261e');
  const ico = n => n==='ok'?'✓':(n==='warn'?'!':'✕');
  const rows = audit.checks.map(c=>`
    <div class="sum-box" style="align-items:flex-start;gap:10px">
      <span style="flex:0 0 auto;width:22px;height:22px;border-radius:50%;background:${dot(c.niveau)};color:#fff;display:inline-flex;align-items:center;justify-content:center;font-weight:700;font-size:.8rem">${ico(c.niveau)}</span>
      <span style="flex:1"><b>${esc(c.label)}</b><br><span style="font-size:.82rem;color:#9a8a82">${esc(c.detail)}</span></span>
    </div>`).join('');

  const periodBtns = (()=>{
    const quick = [30,90,0].map(j=>{
      const lib = j===0?'Tout':j+' j';
      const on = (_revhMode==='jours' && (_revhDays===j || (j===0 && _revhDays>=99999)));
      return `<button class="btn ${on?'gold':'ghost'} sm" onclick="revhSetDays(${j===0?99999:j})">${lib}</button>`;
    }).join('');
    const persoOn = _revhMode==='perso';
    const btnPerso = `<button class="btn ${persoOn?'gold':'ghost'} sm" onclick="revhModePerso()">📅 Période précise</button>`;
    return quick + btnPerso;
  })();
  // [v1083] Bloc dates au jour près (visible en mode perso), calqué sur la comptabilité.
  const persoBloc = (_revhMode==='perso') ? `<div class="banner" style="background:#fdf8e9;border-color:#e8d09a;margin:8px 0">📅 <div style="flex:1">
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end">
        <div><label style="font-size:.74rem;color:#7a6a62;display:block">Du</label><input type="date" id="revhDateDebut" value="${esc(_revhDateDebut)}" style="padding:6px;border:1px solid var(--hair);border-radius:8px"></div>
        <div><label style="font-size:.74rem;color:#7a6a62;display:block">Au</label><input type="date" id="revhDateFin" value="${esc(_revhDateFin)}" style="padding:6px;border:1px solid var(--hair);border-radius:8px"></div>
        <button class="btn gold sm" onclick="revhSetDates()">Appliquer</button>
      </div>
      <p class="note" style="margin:6px 0 0">Choisis une période exacte — par exemple les jours où tu as vraiment pointé ton temps. Laisse un champ vide pour ne pas le borner.</p>
    </div></div>` : '';
  // Libellé de la période active.
  const periodeLabel = (_revhMode==='perso')
    ? `du ${_revhDateDebut?fmtDate(_revhDateDebut):'début'} au ${_revhDateFin?fmtDate(_revhDateFin):"aujourd'hui"}`
    : (_revhDays>=99999?'toutes les données':`les ${_revhDays} derniers jours`);

  main.innerHTML = `
    <div class="topbar"><div><h1>Mon revenu horaire</h1>
      <p>Combien tu peux espérer te payer, d'après tes ventes et ta production réelles.</p></div></div>
    <div class="panel">
      <div class="flex" style="gap:6px;justify-content:flex-end;margin-bottom:10px;flex-wrap:wrap">${periodBtns}</div>
      ${persoBloc}
      <p class="note" style="margin:-4px 2px 10px;color:#9a8a82">Période analysée : <b>${esc(periodeLabel)}</b></p>
      <div class="banner" style="background:#eef5f0;border-color:#bcd9c6"><div>
        <b>Étape 1 — Fiabilité de tes données.</b> Avant tout calcul, voici ce que l'outil sait mesurer sur les ${d.jours>=99999?'données disponibles':`${d.jours} derniers jours`}. Plus tes sources sont vertes, plus l'estimation de revenu (étape suivante) sera juste.
      </div></div>
      ${rows}
      <div class="sum-box" style="margin-top:8px;align-items:flex-start;gap:10px;border:1px solid ${dot(audit.confiance)};background:#fff">
        <span style="flex:0 0 auto;width:22px;height:22px;border-radius:50%;background:${dot(audit.confiance)};color:#fff;display:inline-flex;align-items:center;justify-content:center;font-weight:700;font-size:.8rem">${ico(audit.confiance)}</span>
        <span style="flex:1"><b>Niveau de confiance global</b><br><span style="font-size:.82rem;color:#9a8a82">${esc(audit.confLabel)}</span></span>
      </div>
      <p class="note" style="margin-top:12px">Le calcul ci-dessous s'appuie sur ces données. Plus elles sont complètes, plus il est juste.</p>
    </div>
    ${(()=>{
      const c=calc; const fiable=audit.nbOk>=2 && c.heures>0;
      const euroOrTiret = v => v==null?'—':euro(v);
      if(!(c.heures>0)){
        return `<div class="panel"><h2>Ton revenu horaire</h2>
          <p class="note">Pas assez de temps mesuré sur la période pour calculer un revenu horaire. Lance tes chronos (atelier + pointeuse) et reviens ici.</p></div>`;
      }
      return `<div class="panel">
        <h2>Ton revenu horaire réel</h2>
        ${(c.anomaliesCout&&c.anomaliesCout.length)?`<div class="banner" style="background:#fdecea;border-color:#e7a9a3;margin-bottom:10px"><div>
          <b>⚠ ${c.anomaliesCout.length} recette${c.anomaliesCout.length>1?'s':''} au coût anormalement élevé</b> — ${c.anomaliesCout.slice(0,3).map(a=>`<b>${esc(a.nom)}</b> (${euro(a.coutUnit)}/pièce${a.rendement!=null?`, rendement ${qty(a.rendement)}`:''})`).join(', ')}${c.anomaliesCout.length>3?'…':''}.
          <br>Un macaron coûte normalement quelques dizaines de centimes en matière. Un coût aussi élevé vient presque toujours d'un <b>rendement</b> mal saisi (ex. 1 au lieu de 60) ou d'un <b>prix matière</b> erroné. ${c.anomaliesCout.length>1?'Ces recettes ont':'Cette recette a'} été <b>écartée${c.anomaliesCout.length>1?'s':''} du calcul</b> pour ne pas le fausser — corrige-${c.anomaliesCout.length>1?'les':'la'} pour un revenu horaire juste.
          <div style="margin-top:8px"><button class="btn ghost sm" onclick="goView('recettes')">🧪 Vérifier mes recettes</button></div>
        </div></div>`:''}
        ${c.calculable ? `<div class="row2" style="gap:8px">
          <div class="card" style="background:#eef5f0;border-color:#bcd9c6">
            <div class="lbl">Avant prélèvements</div>
            <div class="val" style="color:#2e7d32">${euroOrTiret(c.revHoraireAvantCotis)}/h</div>
            <div class="sub">marge ${euro(c.margeAvantRemu)} ÷ ${c.heures.toFixed(1)} h</div>
          </div>
          <div class="card" style="background:#fbf6ee;border-color:#e5d3b3">
            <div class="lbl">Après cotisations</div>
            <div class="val" style="color:#AA7C39">${euroOrTiret(c.revHoraireApresCotis)}/h</div>
            <div class="sub">− ${euro(c.cotisations)} d'URSSAF</div>
          </div>
        </div>
        <div class="card" style="margin-top:8px;background:linear-gradient(135deg,#52252F,#3d1a22);border:none;color:#fff;text-align:left">
          <div class="lbl" style="color:#fff;opacity:.85">✅ Ce qu'il te reste vraiment de l'heure — net d'URSSAF ET d'impôt</div>
          <div class="val" style="color:#fff;font-size:1.9rem">${euroOrTiret(c.revHoraireNet)}/h</div>
          <div class="sub" style="color:#fff;opacity:.8">marge ${euro(c.margeApresImpot)} ÷ ${c.heures.toFixed(1)} h · seul ce chiffre est comparable à un salaire net</div>
        </div>
        ${c.coutMOD>0?`<div style="margin-top:8px;padding:9px 12px;background:#fff6e5;border-radius:8px;font-size:.78rem;color:#6a5a52;line-height:1.55">
          🔧 <b>Correction v1325.</b> L'app déduisait ta main-d'œuvre d'atelier (${euro(c.coutMOD)}) du numérateur… puis divisait par ces mêmes heures. Elle te retirait ton propre taux horaire et appelait ça « ce que tu peux te payer ». Cette main-d'œuvre est désormais <b>rendue</b> : c'est précisément ce que ce chiffre sert à mesurer.
        </div>`:''}` : `<div class="card" style="background:#fbf6ee;border:2px solid #e5d3b3;text-align:left">
          <div style="font-size:1.05rem;font-weight:700;color:var(--bordeaux);margin-bottom:6px">⏸ Revenu horaire non calculable pour l'instant</div>
          <p class="note" style="margin:0 0 8px">Le revenu horaire = ta marge ÷ ton temps de travail. Pour qu'il ait du sens, le <b>temps pointé</b> doit couvrir la <b>période</b> du chiffre d'affaires. Ce n'est pas encore le cas ${c.raisonsAbstention&&c.raisonsAbstention.length?`(${c.raisonsAbstention.map(r=>esc(r)).join(' ; ')})`:''} :</p>
          <div class="sum-box" style="background:#fff"><span>Temps pointé</span><b>${c.heures.toFixed(1)} h sur ${c.nbJoursPointes||0} jour(s)</b></div>
          <div class="sum-box" style="background:#fff"><span>Période du chiffre d'affaires</span><b>≈ ${(c.moisActivite||0).toFixed(1)} mois</b></div>
          <div class="sum-box" style="background:#fff"><span>Couverture des pointages</span><b>${Math.round((c.couverture||0)*100)}%</b></div>
          <p class="note" style="margin:8px 2px 0">Plutôt que d'afficher un chiffre trompeur (des mois de marge ÷ quelques heures), l'app préfère <b>s'abstenir</b>. Pour le débloquer : pointe ton temps de façon régulière, ou consulte le revenu horaire sur une fenêtre courte (ex. « 30 jours ») correspondant à tes pointages réels.</p>
          <div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap">
            <button class="btn ghost sm" onclick="goView('pointeuse')">⏱ Pointer mon temps</button>
            <button class="btn ghost sm" onclick="revhSetDays(30)">📅 Voir sur 30 jours</button>
          </div>
        </div>`}
        <h2 style="margin-top:14px;font-size:1rem">D'où vient ce chiffre</h2>
        <p class="note" style="margin:-2px 2px 8px">Touche une ligne pour voir comment elle est calculée, poste par poste.</p>
        ${revhLigneTracable({
          libelle:'CA encaissé', valeur:c.caEncaisse,
          formule:`l'argent réellement <b>reçu</b> sur la période : ${euro(c.caCommandes)} de commandes payées + ${euro(c.caMarches)} de marchés clôturés.`,
          lignes:[
            ...(c.detailCommandes||[]).map(x=>({label:'🧾 '+x.label, montant:x.montant})),
            ...(c.detailMarches||[]).map(x=>({label:'🏪 '+x.label, montant:x.montant}))
          ],
          sousTotal:'Total encaissé', vue:'compta', vueLabel:'Voir la comptabilité'
        })}
        ${revhLigneTracable({
          libelle:'Matières et consommables des ventes', valeur:c.coutMatieres, neg:true,
          formule:`coût des ingrédients et consommables des macarons vendus.${c.coutMOD>0?` <b>La main-d'œuvre d'atelier (${euro(c.coutMOD)}) en a été RETIRÉE</b> : elle fait partie du coût de revient (${euro(c.coutVentesFenetre)}), mais la déduire ici puis diviser par ces mêmes heures reviendrait à la compter deux fois — c'était le bug corrigé en v1325.`:''}${(c.anomaliesCout&&c.anomaliesCout.length)?` ⚠ ${c.anomaliesCout.length} recette(s) au coût aberrant ont été écartées (voir alerte plus haut).`:''}`,
          lignes:[
            ...(c.coutMOD>0?[
              {label:'Coût de revient complet des ventes', montant:c.coutVentesFenetre},
              {label:'− dont main-d\'œuvre d\'atelier (rendue)', montant:-c.coutMOD}
            ]:[]),
            ...((c.anomaliesCout&&c.anomaliesCout.length)? c.anomaliesCout.map(a=>({label:'⚠ écarté : '+a.nom+' ('+euro(a.coutUnit)+'/pc)', montant:0})) : [])
          ],
          sousTotal:c.coutMOD>0?'= Matières et consommables seuls':null,
          vue:'rentaparfum', vueLabel:'Voir la rentabilité par parfum'
        })}
        ${revhLigneTracable({
          libelle:'Emballages', valeur:c.coutEmballages, neg:true,
          formule:`coffrets, sachets, rubans des ventes de la période. <b>Jusqu'en v1325, cette ligne valait 0 €</b> — l'emballage était donc, littéralement, gratuit dans ce calcul, et ton revenu horaire surestimé d'autant. Il suit l'ENCAISSEMENT comme le CA : une commande payée à moitié n'apporte que la moitié de son carton.${(c.embPartEstimee||0)>0?` ⚠ ${c.embPartEstimee}% de ce montant est <b>estimé</b> (commandes de reprise sans détail d'emballage) — le reste est mesuré au réel.`:''}`,
          lignes:(c.embDetail||[]).map(x=>({label:(x.estime?'≈ ':'📦 ')+x.label, montant:x.montant})),
          sousTotal:'Total emballages', vue:'stock', vueLabel:'Voir mes emballages'
        })}
        ${revhLigneTracable({
          libelle:'Charges fixes', valeur:c.chargesFixes, neg:true,
          formule:`tes charges récurrentes étalées sur ta durée réelle d'activité : ${euro(c.chargesRecurMensuel)}/mois × ${(c.moisActivite!=null?c.moisActivite:(c.jours/30)).toFixed(1)} mois${c.totalCharges>0?` + ${euro(c.totalCharges)} de charges ponctuelles datées`:''}.`,
          lignes:[
            ...(c.detailRecur||[]).map(x=>({label:'🔁 '+x.label+' (mensuel)', montant:money2(x.montant*(c.moisActivite!=null?c.moisActivite:(c.jours/30)))})),
            ...(c.detailChargesPonct||[]).map(x=>({label:'📅 '+x.label, montant:x.montant}))
          ],
          sousTotal:'Total charges fixes', vue:'chargesventil', vueLabel:'Voir mes charges'
        })}
        ${revhLigneTracable({libelle:'= Marge avant rémunération', valeur:c.margeAvantRemu, accent:true, borderTop:true,
          formule:`CA encaissé − matières et consommables − emballages − charges fixes. La main-d'œuvre n'y est <b>pas</b> déduite : c'est précisément ce que le revenu horaire cherche à chiffrer.`})}
        ${revhLigneTracable({
          libelle:'Cotisations sociales (URSSAF)', valeur:c.cotisations, neg:true,
          formule:`chaque euro encaissé cotise, mais <b>pas au même taux</b> : la marchandise à ${(+getSettings().socialGoods||0)}%, la prestation de service à ${(+getSettings().socialService||0)}%. Jusqu'en v1324, l'app appliquait le taux marchandise à TOUT le CA — prestations comprises — et sous-estimait donc tes cotisations.`,
          lignes:[
            {label:'🧁 Marchandise : '+euro(c.caGoods||0)+' × '+(+getSettings().socialGoods||0)+'%', montant:c.cotisGoods||0},
            ...((c.caService||0)>0?[{label:'🎓 Prestation : '+euro(c.caService||0)+' × '+(+getSettings().socialService||0)+'%', montant:c.cotisService||0}]:[])
          ],
          sousTotal:'Total cotisations', vue:'compta', vueLabel:'Voir la comptabilité'})}
        ${revhLigneTracable({libelle:'= Marge après cotisations', valeur:c.margeApresCotis, accent:true,
          formule:'marge avant rémunération − cotisations sociales. Ce n\'est pas encore ce que tu touches : l\'impôt n\'est pas payé.'})}
        ${revhLigneTracable({
          libelle:'Impôt sur le revenu', valeur:c.impotRevenu, neg:true,
          formule:`en micro-BIC, l'impôt se calcule sur un pourcentage forfaitaire du CA, pas sur ta marge réelle : base imposable ${euro(c.baseImposable||0)} (CA après abattement) × ta tranche marginale de ${c.trancheIr||0}%. C'est de l'argent qui sort du compte, exactement comme les cotisations — l'app l'oubliait complètement jusqu'en v1324.`,
          vue:'compta', vueLabel:'Voir la comptabilité'})}
        ${revhLigneTracable({libelle:'= Ce qu\'il te reste vraiment', valeur:c.margeApresImpot, accent:true, borderTop:true,
          formule:'marge après cotisations − impôt. C\'est ta rémunération réelle pour le temps travaillé, tout payé. Divisée par tes heures, c\'est le seul chiffre comparable à un salaire net.'})}
        ${revhLigneTracable({
          libelle:'Temps total travaillé', valeurStr:c.heures.toFixed(1)+' h',
          formule:`tout le temps mesuré sur la période : ${c.hAtelier.toFixed(1)} h de production (atelier) + ${c.hPointeuse.toFixed(1)} h hors-production (pointeuse).`,
          lignes:[
            {label:'🏭 Production (atelier) — '+(c.nbSessionsAtelier||0)+' session(s)', montant:0},
            {label:'⏱ Hors-production (pointeuse) — '+(c.nbSessionsPointeuse||0)+' session(s)', montant:0}
          ],
          vue:'pointeuse', vueLabel:'Voir la pointeuse'})}
        ${!fiable?`<p class="note" style="margin-top:10px;color:#d98324">⚠ Données encore partielles : ce chiffre est indicatif. Complète tes sources (voir ci-dessus) pour le fiabiliser.</p>`:''}
        ${c.coutMatieres===0?`<p class="note" style="margin-top:8px">Note : le coût matières des ventes n'a pas pu être estimé (pas de ventes rattachées à des recettes chiffrées sur la période).</p>`:''}
        <p class="note" style="margin-top:8px">La main-d'œuvre n'est pas déduite ici : ce revenu horaire <b>est</b> ta rémunération du temps travaillé. À comparer avec ce que tu voudrais te payer — l'écart te dit s'il faut ajuster prix, vitesse ou volume de ventes.</p>
      </div>`;
    })()}
    <div class="panel">
      <details>
        <summary style="cursor:pointer;color:var(--caramel,#AA7C39);font-weight:600;font-size:1.02rem">📐 Comment c'est calculé</summary>
        <div style="margin-top:12px">
          <p class="note">Toutes les formules utilisées par cet écran et par ton coût de revient. Tes données alimentent ces calculs automatiquement.</p>

          <h2 style="font-size:1rem;margin-top:14px">1 · Temps de production par macaron</h2>
          <p class="body" style="font-size:.9rem">Mesuré à l'atelier, lissé sur 90 jours pour rester stable.</p>
          <div class="sum-box" style="display:block"><b>min / macaron</b> = temps total d'atelier (toutes tâches) ÷ macarons finis produits</div>
          <p class="note">Exemple : 300 min d'atelier ÷ 600 macarons = <b>0,5 min/macaron</b>. Seuls les macarons finis (assemblés ou complets) comptent, pas les coques ou ganaches seules.</p>

          <h2 style="font-size:1rem;margin-top:14px">2 · Coût de revient d'un macaron</h2>
          <div class="sum-box" style="display:block"><b>coût/pièce</b> = matières + consommables + main-d'œuvre, le tout réparti sur les pièces vendables (les pertes renchérissent le coût)</div>
          <p class="body" style="font-size:.9rem">La main-d'œuvre (si activée) = temps × taux horaire. Le temps vient soit de la recette (manuel), soit de la mesure atelier (brique 1), selon ton réglage.</p>
          <p class="note">Exemple : 0,5 min/macaron × 12 €/h ÷ 60 = <b>0,10 €</b> de main-d'œuvre par macaron. L'emballage n'est pas inclus ici (il dépend du format de coffret).</p>

          <h2 style="font-size:1rem;margin-top:14px">3 · Ton revenu horaire</h2>
          <div class="sum-box" style="display:block"><b>revenu/h</b> = marge avant rémunération ÷ temps total travaillé</div>
          <p class="body" style="font-size:.9rem">avec :</p>
          <div class="sum-box"><span>Marge avant rémunération</span><b>CA encaissé − matières − emballages − charges fixes</b></div>
          <div class="sum-box"><span>Marge nette</span><b>marge avant rému − cotisations sociales</b></div>
          <div class="sum-box"><span>Temps total</span><b>atelier (production) + pointeuse (hors-prod)</b></div>
          <p class="note">La main-d'œuvre n'est <b>pas</b> retirée du numérateur : ce revenu horaire est justement ce que ton travail te rapporte. Les cotisations (~${(+getSettings().socialGoods||0)} % du CA marchandise) donnent la version « après cotisations ».</p>
          <p class="note">Exemple : (3000 € − 450 € matières − 750 € charges) ÷ 120 h = <b>15 €/h</b> avant cotisations ; après cotisations ≈ 11,93 €/h.</p>

          <h2 style="font-size:1rem;margin-top:14px">Pourquoi « lissé » et pas le temps du jour ?</h2>
          <p class="body" style="font-size:.9rem">Un mauvais jour de prod ne doit pas faire exploser ton coût de revient. Le coût utilise donc ta <b>moyenne</b> sur 90 jours (stable, pilotable). La variation au jour le jour, elle, servira au suivi de performance (à venir).</p>

          <p class="note" style="margin-top:14px;color:#9a8a82">Fenêtre de calcul actuelle : ${d.jours>=99999?'toutes les données':`${d.jours} derniers jours`}. Modifiable en haut de l'écran.</p>
        </div>
      </details>
    </div>`;
}
// [v1083] Handlers du sélecteur de période du revenu horaire.
function revhSetDays(j){ _revhMode='jours'; _revhDays = j; renderRevenuHoraire(); }
// Bascule en mode « période précise » (dates au jour près).
function revhModePerso(){
  _revhMode='perso';
  // pré-remplit avec une plage par défaut si vide : les 90 derniers jours.
  if(!_revhDateDebut && !_revhDateFin){
    const fin=new Date(); const deb=new Date(); deb.setDate(deb.getDate()-90);
    _revhDateDebut=ymdLocal(deb); _revhDateFin=ymdLocal(fin);
  }
  renderRevenuHoraire();
}
// Applique les dates saisies dans les champs Du/Au.
function revhSetDates(){
  const deb=document.getElementById('revhDateDebut'); const fin=document.getElementById('revhDateFin');
  _revhDateDebut = deb ? (deb.value||'') : _revhDateDebut;
  _revhDateFin   = fin ? (fin.value||'') : _revhDateFin;
  // garde-fou : si début > fin, on échange pour rester cohérent.
  if(_revhDateDebut && _revhDateFin && _revhDateDebut>_revhDateFin){
    const t=_revhDateDebut; _revhDateDebut=_revhDateFin; _revhDateFin=t;
  }
  _revhMode='perso';
  renderRevenuHoraire();
}


// ---- VUE ATELIER (héberge le board de pilotage) ----
let _atelierTab = 'pilotage';   // 'pilotage' | 'tableau'
function renderAtelier(){
  const main=document.getElementById('main'); if(!main) return;
  main.innerHTML = `
    <div class="topbar"><div><h1>Atelier de production</h1><p>Mesure du temps par tâche — chronos parallèles</p></div>
      <button class="btn ghost" onclick="goView('agendaprod')">🧭 Production →</button></div>
    <div class="banner" style="background:#eef5f0;border-color:#bcd9c6">⏱ <div>C'est <b>ICI</b> que tu mesures ton <b>temps de travail</b> : chaque tâche chronométrée nourrit les <b>estimations du Plan de production</b> (plus tu mesures, plus le calage horaire de tes journées devient juste). <span style="color:#6a8a5a">À ne pas confondre avec le chrono de la page Productions, qui sert seulement au suivi de fraîcheur (DLC).</span></div></div>
    ${prodSessDexieKo()?`<div class="banner" style="background:#fdeaea;border-color:#d9534f">⚠ <div><b>La sauvegarde sécurisée des chronos a rencontré un souci</b> (${esc(prodSessDexieKo())}). Tes sessions sont encore en mémoire locale mais moins protégées.<br><button class="btn gold sm" style="margin-top:8px" onclick="reparerBaseSessions()">🔧 Réparer la base maintenant</button></div></div>`:''}
    ${(typeof unsavedCount==='function'&&unsavedCount()>0)?`<div class="banner" style="background:#fff7e6;border-color:#e8d09a">☁️ <div><b>Pense à sauvegarder sur iCloud.</b> Tes sessions ne sont vraiment à l'abri qu'une fois exportées hors de l'appareil. <button class="btn gold sm" style="margin-top:6px" onclick="shareBackupToICloud()">Sauvegarder maintenant</button></div></div>`:''}
    <div class="atelier-tabs">
      <button class="at-tab ${_atelierTab==='pilotage'?'active':''}" onclick="atelierSwitch('pilotage')">⏱ Pilotage</button>
      <button class="at-tab ${_atelierTab==='tableau'?'active':''}" onclick="atelierSwitch('tableau')">📊 Tableau</button>
      <button class="at-tab ${_atelierTab==='journal'?'active':''}" onclick="atelierSwitch('journal')">📅 Journal</button>
      <button class="at-tab ${_atelierTab==='temps'?'active':''}" onclick="atelierSwitch('temps')">🎯 Temps/parfum</button>
      <button class="at-tab ${_atelierTab==='mestaches'?'active':''}" onclick="atelierSwitch('mestaches')">🛠 Mes tâches</button>
    </div>
    <div id="prodBoardHost"></div>`;
  if(_atelierTab==='tableau') prodRenderGantt();
  else if(_atelierTab==='journal') prodRenderJournal();
  else if(_atelierTab==='temps') prodRenderTempsParfum();
  else if(_atelierTab==='mestaches') prodRenderMesTaches();
  else prodRenderBoard();
}
function atelierSwitch(tab){
  _atelierTab=tab;
  const host=document.getElementById('prodBoardHost'); if(!host) return;
  const btns=document.querySelectorAll('.at-tab');
  btns.forEach(b=>b.classList.remove('active'));
  const idx = tab==='pilotage'?0 : tab==='tableau'?1 : tab==='journal'?2 : tab==='temps'?3 : 4;
  if(btns[idx]) btns[idx].classList.add('active');
  if(tab==='tableau') prodRenderGantt();
  else if(tab==='journal') prodRenderJournal();
  else if(tab==='temps') prodRenderTempsParfum();
  else if(tab==='mestaches') prodRenderMesTaches();
  else prodRenderBoard();
}

// ---- VUE TABLEAU BLANC (Gantt) de la session du jour ----
// Barres horizontales positionnées selon l'heure de début/fin ; empilées verticalement ;
// le chevauchement temporel est visible (deux barres sur la même tranche horaire).
function prodRenderGantt(targetSession){
  const host = document.getElementById('prodBoardHost');
  if(!host) return;
  const s = targetSession || prodSessActive() || prodLastSession();
  if(!s || !(s.tasks||[]).length){
    host.innerHTML = `<div class="prodb-empty"><div class="prodb-empty-ico">📊</div>
      <p>Aucune tâche à afficher pour l'instant.</p>
      <p class="note">Lance des tâches depuis l'onglet « Pilotage » : elles apparaîtront ici sous forme de barres positionnées dans le temps.</p></div>`;
    return;
  }
  // Échelle temporelle : du début de la 1re tâche à la fin de la dernière (ou maintenant).
  const tasks = (s.tasks||[]).slice().sort((a,b)=>a.start-b.start);
  const t0 = Math.min(...tasks.map(t=>t.start));
  const t1 = Math.max(...tasks.map(t=>t.end||Date.now()));
  const span = Math.max(1, t1 - t0);
  const fmtH = ms => new Date(ms).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});

  // Graduations à intervalle ADAPTATIF : on choisit un pas « rond » qui produit au plus
  // ~8 graduations, pour ne jamais les entasser (même si la session est anormalement longue).
  const ticks=[];
  const PAS_RONDS = [5,10,15,20,30,60,120,180,240,360,720,1440]; // en minutes
  const spanMin = span/60000;
  let pasMin = PAS_RONDS[PAS_RONDS.length-1];
  for(const p of PAS_RONDS){ if(spanMin/p <= 8){ pasMin = p; break; } }
  const pasMs = pasMin*60000;
  const startH=new Date(t0); startH.setMinutes(0,0,0);
  // on aligne le 1er tick sur un multiple du pas après t0
  let first = startH.getTime();
  while(first < t0) first += pasMs;
  for(let h=first; h<=t1; h+=pasMs){ ticks.push(h); }
  // format : si le pas est < 1h on garde HH:MM ; au-delà aussi (HH:MM reste lisible)

  const _recNames = (window._allRecipesCache||[]);
  const _recNm = rid => { const r=_recNames.find(x=>+x.id===+rid); return r?r.produitNom:('#'+rid); };
  const rows = tasks.map(t=>{
    const left = ((t.start - t0)/span)*100;
    const end = t.end||Date.now();
    const width = Math.max(1.5, ((end - t.start)/span)*100);
    const running = !t.end;
    const dur = prodDurShort(prodTaskNet(t));
    const parfums = Array.isArray(t.parfums)?t.parfums:[];
    const parfumTxt = parfums.length
      ? parfums.map(_recNm).join(', ')
      : '<span style="color:#b08a3a">parfum ?</span>';
    return `<div class="gantt-row">
      <div class="gantt-label" title="${esc(t.label)}">
        <span class="prodt-dot" style="background:${t.color}"></span>${esc(t.label)}
        <div style="font-size:.68rem;color:#9a8a82;margin-top:1px">🎯 ${parfumTxt}
          <span class="act" style="cursor:pointer;color:var(--bordeaux)" onclick="prodTaskRattachManuel('${t.id}')">✏️</span></div>
      </div>
      <div class="gantt-track">
        ${ticks.map(tk=>`<div class="gantt-grid" style="left:${((tk-t0)/span)*100}%"></div>`).join('')}
        <div class="gantt-bar ${running?'is-running':''}" style="left:${left}%;width:${width}%;background:${t.color}">
          <span class="gantt-bar-txt">${dur}</span>
        </div>
      </div>
    </div>`;
  }).join('');

  const sessTitle = s.end
    ? `Session du ${fmtDate(s.date)} · ${fmtH(s.start)}–${fmtH(s.end)}`
    : `Session en cours · démarrée à ${fmtH(s.start)}`;

  host.innerHTML = `
    <div class="gantt-wrap">
      <div class="gantt-sess">${sessTitle}</div>
      <div class="gantt-scale">
        <div class="gantt-label gantt-corner"></div>
        <div class="gantt-track gantt-axis">
          ${ticks.map(tk=>`<div class="gantt-tick" style="left:${((tk-t0)/span)*100}%">${fmtH(tk)}</div>`).join('')}
        </div>
      </div>
      <div class="gantt-rows">${rows}</div>
      ${(function(){
        var reel=prodSessReelMs(s), cumul=prodSessCumulMs(s), gain=Math.max(0,cumul-reel);
        return `<div class="gantt-totaux">
          <div class="gt-box"><span class="gt-lbl">Temps réel</span><b>${prodDurShort(reel)}</b><span class="gt-sub">passé au mur</span></div>
          <div class="gt-box"><span class="gt-lbl">Cumul des tâches</span><b>${prodDurShort(cumul)}</b><span class="gt-sub">si faites à la chaîne</span></div>
          ${gain>=60000?`<div class="gt-box gt-gain"><span class="gt-lbl">Gagné en parallèle</span><b>${prodDurShort(gain)}</b><span class="gt-sub">grâce au chevauchement</span></div>`:''}
        </div>`;
      })()}
      <p class="note gantt-hint">Chaque barre = une tâche. Deux barres sur la même tranche horaire = tâches menées en parallèle (ex. cuisson pendant la meringue suivante). Le « temps réel » ne compte jamais deux fois une même tranche.</p>
    </div>`;
  if((s.tasks||[]).some(prodTaskRunning)) prodStartTicking();
}
// Dernière session clôturée (pour afficher quelque chose même sans session active).
function prodLastSession(){
  const all = prodSessLoad().filter(s=>s.end).sort((a,b)=>b.end-a.end);
  return all[0]||null;
}
// ---- JOURNAL DE BORD (étape 4) : sessions passées, groupées par jour ----
async function prodRenderJournal(){
  const host = document.getElementById('prodBoardHost'); if(!host) return;
  const sessions = prodSessLoad().slice().sort((a,b)=> (b.start)-(a.start));
  // [v1380] Les parfums fabriqués s'affichent en en-tête de chaque session (demande de Ben).
  const _recs = await db.recipes.toArray().catch(()=>[]);
  const _nomRec = rid => { const r=_recs.find(x=>+x.id===+rid); return r?r.produitNom:('#'+rid); };
  if(!sessions.length){
    host.innerHTML = `<div class="prodb-empty"><div class="prodb-empty-ico">📅</div>
      <p>Aucune session enregistrée pour l'instant.</p>
      <p class="note">Tes journées de production apparaîtront ici, consultables sous forme de tableau blanc daté.</p></div>`;
    return;
  }
  const fmtH = ms => new Date(ms).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});
  const cards = sessions.map(s=>{
    const tasks=s.tasks||[];
    const totMs = prodSessCumulMs(s);        // cumul (charge de travail à la chaîne)
    const reelMs = prodSessReelMs(s);         // durée réelle « mur à mur » (chevauchements compris)
    const gainMs = Math.max(0, totMs - reelMs); // temps gagné grâce au chevauchement
    const phases = {};
    tasks.forEach(t=>{ phases[t.phase]=(phases[t.phase]||0)+prodTaskNet(t); });
    const phaseChips = Object.keys(phases).map(p=>{
      const meta = prodAllTasks().find(t=>t.phase===p);
      const col = meta?meta.color:'#8a7a72';
      return `<span class="pj-chip" style="background:${col}">${esc(p)} ${prodDurShort(phases[p])}</span>`;
    }).join('');
    const open = !s.end;
    return `<div class="pj-card">
      <div class="pj-head" onclick="prodJournalOpen('${s.id}')">
        <div>
          <div class="pj-date">${fmtDate(s.date)} ${open?'<span class="pj-live">● en cours</span>':''}</div>
          <div class="pj-time">${fmtH(s.start)}${s.end?'–'+fmtH(s.end):''} · ${tasks.length} tâche(s)</div>
        </div>
        <div class="pj-tot" style="text-align:right">${prodDurShort(reelMs)}<br><span style="font-size:.62rem;color:#9a8a82;font-weight:400">temps réel${gainMs>=60000?` <span style="color:#3f7d52" title="Tâches menées en parallèle : le temps réel passé au mur, chevauchements déduits. Le cumul additionne les tâches comme si elles étaient faites à la chaîne.">· cumul ${prodDurShort(totMs)} · ⏱ ${prodDurShort(gainMs)} gagné en parallèle</span>`:''}</span></div>
      </div>
      ${(()=>{ const rids=_sessParfumsDistincts(s);
        return rids.length
          ? `<div style="font-size:.76rem;color:#6b4f45;margin:2px 0 0">🎨 ${rids.map(r=>esc(_nomRec(r))).join(' · ')}</div>`
          : `<div style="font-size:.72rem;color:#b0a29a;margin:2px 0 0">🎨 parfums non rattachés — utilise 🎯 ou 🖊</div>`; })()}
      <div class="pj-chips">${phaseChips}</div>
      <div class="pj-actions">
        <button class="qa" onclick="prodJournalOpen('${s.id}')">📊 Voir le tableau</button>
        <button class="qa" style="background:#aa7c39;color:#fff" onclick="prodSessParfumsConfirm('${s.id}')" title="Rattacher les parfums/recettes produits pendant cette session (affine le temps par recette, y compris pour tes anciennes sessions)">🎯 Parfums${s.parfumsConfirmes?' ✓':''}</button>
        <button class="qa" style="background:#6b4f45;color:#fff" onclick="prodSessTaches('${s.id}')" title="Corriger le parfum d'UNE tâche précise — le temps par parfum se recalcule selon tes corrections">🖊 Par tâche</button>
        ${!open?`<button class="qa" style="background:#3f7d52;color:#fff" onclick="prodSessReopen('${s.id}')" title="Rouvrir cette session pour y ajouter des tâches (ex : garnissage après refroidissement)">↻ Rouvrir</button>`:''}
        ${!open?`<button class="qa del" onclick="prodJournalDelete('${s.id}')">🗑</button>`:''}
      </div>
    </div>`;
  }).join('');
  host.innerHTML = `<div class="pj-list">${cards}</div>`;
}
// Ouvre une session du journal dans la vue tableau blanc (lecture).
function prodJournalOpen(sessId){
  const s = prodSessGet(sessId); if(!s) return;
  _atelierTab='tableau';
  renderAtelier();
  // afficher CETTE session précise dans le Gantt
  setTimeout(()=>prodRenderGantt(s), 0);
}
function prodJournalDelete(sessId){
  const s=prodSessGet(sessId); if(!s) return;
  if(!confirm(`Supprimer la session du ${fmtDate(s.date)} du journal ?\nLes temps enregistrés seront perdus.`)) return;
  prodSessRemove(sessId);
  prodRenderJournal();
  toast('Session supprimée');
}
// ---- ÉCRAN DE PILOTAGE (étape 2 : vue liste des tâches actives) ----
// (La vue « tableau blanc » Gantt arrive à l'étape 3.)
async function prodRenderBoard(){
  const host = document.getElementById('prodBoardHost');
  if(!host) return;
  const s = prodSessActive();
  if(!s){
    host.innerHTML = `<div class="prodb-empty">
      <div class="prodb-empty-ico">🥣</div>
      <p>Aucune session de production en cours.</p>
      <button class="btn" onclick="prodSessionStart();prodRenderBoard()">▶ Démarrer une session</button>
      <p class="note" style="margin-top:10px">Une session sert à mesurer le temps de tes tâches (pesées, macaronnage, cuisson, nettoyage…). Tu peux en lancer plusieurs en parallèle.</p>
    </div>`;
    return;
  }
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recipesById = {}; recipes.forEach(r=>recipesById[+r.id]=r.produitNom);
  const parfums = await atParfumsDispo();
  // Onglet partagé avec le flottant. Réinit si l'onglet courant n'est plus valide.
  const validIds = parfums.map(p=>+p.recipeId);
  if(_atOnglet!=='mutualise' && _atOnglet!=null && !validIds.includes(+_atOnglet)) _atOnglet = null;
  // [DÉFAUT MUTUALISÉ] Une session démarre par le tronc commun (la meringue partagée) : si au moins
  // 2 parfums sont en jeu, on ouvre sur l'onglet « Mutualisé ». Sinon, sur le parfum unique.
  if(_atOnglet==null && parfums.length) _atOnglet = (parfums.length>=2) ? 'mutualise' : parfums[0].recipeId;
  _atSyncParfum();

  // ---- onglets parfum ----
  let tabsHtml='';
  if(parfums.length){
    const pf = parfums.map(p=>`<button class="pb-tabp ${(+_atOnglet===+p.recipeId)?'on':''}" onclick="prodBoardSetOnglet(${p.recipeId})">${esc(p.nom)}</button>`).join('');
    const mut = (parfums.length>=2) ? `<button class="pb-tabp mut ${_atOnglet==='mutualise'?'on':''}" onclick="prodBoardSetOnglet('mutualise')">⇄ Mutualisé</button>` : '';
    tabsHtml = `<div class="pb-tabps">${pf}${mut}</div>`;
  }

  // ---- zone mutualisée ----
  let mutBoxHtml='';
  if(_atOnglet==='mutualise'){
    if(!_atMutSel.length) _atMutSel = parfums.map(p=>+p.recipeId);
    const checks = parfums.map(p=>{
      const on=_atMutSel.includes(+p.recipeId);
      return `<label class="pb-mutchk"><input type="checkbox" ${on?'checked':''} onchange="prodBoardMutToggle(${p.recipeId})"> ${esc(p.nom)}</label>`;
    }).join('');
    mutBoxHtml = `<div class="pb-mutbox"><div class="pb-mutlab">⇄ Tâche partagée — parfums concernés :</div><div class="pb-mutchks">${checks}</div></div>`;
  }

  // ---- tâches filtrées sur l'onglet ----
  const running = (s.tasks||[]).filter(t=>prodTaskRunning(t) && _atTaskMatchOnglet(t));
  const done = (s.tasks||[]).filter(t=>t.end && _atTaskMatchOnglet(t));
  const startedTxt = new Date(s.start).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});

  // libellé du parfum d'une tâche (pour rappel visuel)
  const parfTag = t=>{
    const ps=_atTaskParfums(t);
    if(!ps.length) return '';
    const nom = ps.length===1 ? (recipesById[ps[0]]||'') : ps.map(r=>recipesById[r]||('#'+r)).join(' + ');
    return `<span class="prodt-parf${ps.length>=2?' multi':''}">${esc(nom)}</span>`;
  };

  const runCards = running.length ? running.map(t=>{
    const paused = prodTaskPaused(t);
    return `<div class="prodt-card ${paused?'is-paused':''}" style="border-left-color:${t.color}">
      <div class="prodt-top">
        <span class="prodt-dot" style="background:${t.color}"></span>
        <span class="prodt-label">${esc(t.label)}</span>
        ${parfTag(t)}
      </div>
      <div class="prodt-bottom">
        <span class="prodt-chrono" data-prodchrono="${t.id}">${prodFmt(prodTaskNet(t))}</span>
        <div class="prodt-ctrl">
          <button class="pt-btn pt-pause" onclick="prodTaskPauseToggle('${t.id}')" title="${paused?'Reprendre':'Pause'}">${paused?'▶':'⏸'}</button>
          <button class="pt-btn pt-stop" onclick="prodTaskStop('${t.id}')" title="Terminer">⏹</button>
          <button class="pt-btn pt-edit" onclick="prodTaskEditForm('${t.id}')" title="Modifier le temps">✎</button>
          <button class="pt-btn pt-del" onclick="prodConfirmDelTask('${t.id}')" title="Supprimer">✕</button>
        </div>
      </div>
      ${paused?'<div class="prodt-pausetag">⏸ en pause</div>':''}
    </div>`;
  }).join('') : `<p class="note" style="text-align:center;padding:14px 0">${_atOnglet==='mutualise'?'Aucune tâche mutualisée en cours.':'Aucune tâche en cours pour ce parfum.'} Lance-en une ci-dessous 👇</p>`;

  const doneList = done.length ? `
    <div class="prodb-done">
      <div class="prodb-done-head">✓ Tâches terminées (${done.length})</div>
      ${done.map(t=>`<div class="prodb-done-row">
        <span class="prodt-dot" style="background:${t.color}"></span>
        <span class="pd-label">${esc(t.label)}</span>
        ${parfTag(t)}
        <span class="pd-dur">${prodDurShort(prodTaskNet(t))}</span>
        <button class="pt-btn pt-edit" onclick="prodTaskEditForm('${t.id}')" title="Modifier le temps" style="margin-left:8px">✎</button>
      </div>`).join('')}
    </div>` : '';

  // bouton lancer : rappelle le rattachement courant
  const addLabel = (_atOnglet==='mutualise')
    ? `＋ Lancer une tâche <span style="font-weight:400;opacity:.85">(partagée entre les parfums cochés)</span>`
    : (_atParfum!=null ? `＋ Lancer une tâche <span style="font-weight:400;opacity:.85">(rattachée à ${esc(recipesById[_atParfum]||'')})</span>` : '＋ Lancer une tâche');

  // ---- [SUGGESTION D'ENCHAÎNEMENT] même moteur que le flottant ----
  const estMut = (_atOnglet==='mutualise');
  const last = (typeof atLastLabel==='function') ? atLastLabel(_atParfum) : null;
  let sug=[]; try{ sug = await prodSuggestNext(_atParfum, last, 1, {mutualise:estMut, contexteFamille:(last?prodTaskFamille(last):null)}); }catch(e){swallow(e,'prodRenderBoard')}
  const nxt = sug && sug[0];
  let nextHtml='';
  if(nxt){
    const why = estMut ? 'le temps sera partagé entre les parfums cochés' : (last ? 'suite habituelle' : 'tu commences souvent par là');
    const mini = '';   // [v1364] plus de minuteur : une passive est un chrono normal
    nextHtml = `<button class="at-next" onclick="atLaunch('${escJs(nxt)}')">
      <span class="at-next-dot"></span><span>${esc(nxt)}${mini}</span><span class="at-next-why">${why}</span></button>`;
  }
  let listeHtml='';
  if(_atPicker){
    const groups={};
    let recsActs=[];
    if(estMut){ recsActs=_atMutSel.map(rid=>recipes.find(r=>+r.id===+rid)).filter(Boolean); }
    else if(_atParfum!=null){ const r=recipes.find(r=>+r.id===+_atParfum); if(r) recsActs=[r]; }
    const seen=new Set();
    const pushTask=t=>{ const k=t.phase+'|'+t.label; if(!seen.has(k)){ seen.add(k); (groups[t.phase]=groups[t.phase]||{color:t.color,items:[]}).items.push(t.label); } };
    if(recsActs.length){ recsActs.forEach(r=>prodAllTasks(r).forEach(pushTask)); } else { prodAllTasks().forEach(pushTask); }
    listeHtml = prodSortPhases(Object.keys(groups)).map(phase=>{
      const g=groups[phase];
      return `<div class="at-grp"><div class="at-grp-phase" style="color:${g.color}">${esc(phase)}</div>
        ${g.items.map(l=>`<button class="at-grp-task" onclick="atLaunch('${escJs(l)}')"><span class="at-d"></span>${esc(l)}</button>`).join('')}</div>`;
    }).join('');
  }
  const suggBloc = `<div class="pb-sugg">
    <div class="pb-sugg-head">Et maintenant ?</div>
    ${nextHtml||'<p class="note" style="margin:2px 0">Lance une première tâche : les suggestions apparaîtront ensuite.</p>'}
    <button class="btn ghost sm" style="margin-top:8px" onclick="atTogglePicker()">${_atPicker?'▲ Masquer la liste des tâches':'▼ Voir toutes les tâches'}</button>
    ${listeHtml?`<div class="at-list" style="margin-top:8px">${listeHtml}</div>`:''}
  </div>`;
  const trashBtn = (s.trash&&s.trash.length)
    ? `<button class="btn ghost sm" style="margin-top:10px" onclick="prodTrashOpen()">🗑 Corbeille (${s.trash.length})</button>` : '';

  host.innerHTML = `
    <div class="prodb-session">
      <div class="prodb-sess-head">
        <div><span class="prodb-live-dot"></span> Session en cours <span class="prodb-sess-time">démarrée à ${startedTxt}</span></div>
        <div style="display:flex;gap:6px">
          <button class="btn ghost sm" onclick="goView('controletemps')" title="Corriger les heures et durées des séances">✎ Temps</button>
          <button class="btn ghost sm" onclick="prodConfirmEndSession()">⏹ Clôturer</button>
        </div>
      </div>
    </div>
    ${tabsHtml}
    ${mutBoxHtml}
    <div class="prodb-running">${runCards}</div>
    <button class="btn prodb-addbtn" onclick="prodBoardLaunch()">${addLabel}</button>
    ${suggBloc}
    ${doneList}
    ${trashBtn}`;

  if((s.tasks||[]).some(prodTaskRunning)) prodStartTicking();
}

// Actions onglets de l'atelier complet (état partagé avec le flottant).
function prodBoardSetOnglet(v){
  _atOnglet = (v==='mutualise') ? 'mutualise' : +v;
  if(_atOnglet!=='mutualise') _atMutSel = [];
  _atSyncParfum();
  prodRenderBoard();
}
function prodBoardMutToggle(rid){
  rid=+rid; const i=_atMutSel.indexOf(rid);
  if(i>=0) _atMutSel.splice(i,1); else _atMutSel.push(rid);
  prodRenderBoard();
}
// Lancer une tâche depuis l'atelier complet : ouvre le sélecteur, rattachement selon l'onglet.
// [FIX v1439] Appelait prodTaskPicker() — un sélecteur MODAL qui n'existe plus depuis le passage
// à la « couche flottante » (commentaire ligne 61637 : « sans ouvrir de modale »). La fonction
// n'était définie NULLE PART dans app.js (seule une ligne de commentaire, ligne 11608, prétendait
// qu'elle était « réutilisée » — elle ne l'était pas). Chaque clic sur « ＋ Lancer une tâche »
// dans l'atelier complet levait donc un ReferenceError et n'ouvrait rien. Le mécanisme réel existe
// déjà : `_atPicker` + un nouveau rendu, exactement ce que fait `atTogglePicker()` pour le panneau
// flottant. Ici on FORCE l'ouverture (pas un bascule) : le bouton dédié « lancer » doit toujours
// afficher la liste, jamais la refermer sous le clic.
// [FIX v1439b] Le fix ci-dessus corrigeait bien le plantage, mais Ben a signalé « plus rien ne se
// passe » : la liste s'ouvre EFFECTIVEMENT (même mécanisme que le bouton ▼ « Voir toutes les
// tâches », qui lui a toujours marché), mais plus bas dans l'écran, après les tâches en cours —
// sans aucun repère visuel, un clic qui n'entraîne aucun mouvement à l'écran est indiscernable
// d'un clic qui ne fait rien. Idem si `_atPicker` était déjà à `true` d'un essai précédent (il
// n'est jamais remis à `false` par un rechargement de vue, seulement par un pick ou un ▲ explicite) :
// rouvrir un panneau déjà ouvert ne change visuellement RIEN. Fix : on attend le rendu puis on fait
// défiler la liste dans le cadre — un clic sur ce bouton a maintenant TOUJOURS un effet visible,
// que le sélecteur vienne de s'ouvrir ou qu'il l'était déjà.
async function prodBoardLaunch(){
  _atPicker = true;
  if(typeof prodRenderBoard==='function') await prodRenderBoard();
  const cible = document.querySelector('#prodBoardHost .at-list') || document.querySelector('#prodBoardHost .pb-sugg');
  if(cible && typeof cible.scrollIntoView==='function') cible.scrollIntoView({behavior:'smooth', block:'start'});
}
// Durée courte lisible (ex. « 1 h 20 », « 14 min »).
function prodDurShort(ms){
  const totalMin = Math.round(ms/60000);
  if(totalMin<60) return totalMin+' min';
  const h=Math.floor(totalMin/60), m=totalMin%60;
  return m? `${h} h ${String(m).padStart(2,'0')}` : `${h} h`;
}
// Sélecteur de tâche à lancer (catalogue groupé par phase + ajout perso).
// === Version « couche flottante » du sélecteur de tâche ===
// Affiche le choix de tâche DANS le panneau chrono flottant (cfBody), sans ouvrir de modale.
// Ainsi, si une saisie de production (modale) est ouverte derrière, elle reste INTACTE.
function prodPickTask(label){
  closeModal();
  const parfs=_atParfumsPourLancement();
  prodTaskStartSmart(label, {recipeId: parfs.length===1?parfs[0]:null, parfums: parfs});
  prodRenderBoard();
  toast(`▶ ${label}`);
}
function prodPickCustom(){
  const label=(val('ptp_custom')||'').trim();
  if(!label){ toast('Donne un nom à la tâche'); return; }
  // mémorise la tâche perso pour la prochaine fois
  const s=getSettings(); const list=s.prodCustomTasks||[];
  if(!list.some(c=>(typeof c==='string'?c:c.label)===label)){ list.push(label); s.prodCustomTasks=list; saveSettings(s); }
  closeModal();
  const parfs=_atParfumsPourLancement();
  prodTaskStartSmart(label, {recipeId: parfs.length===1?parfs[0]:null, parfums: parfs});
  prodRenderBoard();
  toast(`▶ ${label}`);
}
function prodConfirmDelTask(taskId){
  if(!confirm('Supprimer cette tâche en cours sans l\'enregistrer ?')) return;
  prodTaskDelete(taskId);
}
// Rouvre une session clôturée (clôture par erreur). Refuse s'il y a déjà une session active,
// pour ne jamais avoir deux sessions ouvertes en même temps. La dernière tâche n'est PAS
// redémarrée : on rouvre la session pour pouvoir y AJOUTER de nouvelles tâches (ex : garnissage).
function prodSessReopen(sessId){
  const active = prodSessActive();
  if(active && active.id!==sessId){
    toast('Termine d\'abord la session en cours avant d\'en rouvrir une autre');
    return;
  }
  const s = prodSessLoad().find(x=>x.id===sessId); if(!s) return;
  if(!s.end){ toast('Cette session est déjà ouverte'); return; }
  if(!confirm(`Rouvrir la session du ${fmtDate(s.date)} ?\nTu pourras y ajouter de nouvelles tâches (ex : garnissage, montage).`)) return;
  s.end = null;                 // redevient « ouverte »
  prodSessUpsert(s);
  _atelierTab = 'pilotage';
  if(typeof renderAtelier==='function') renderAtelier();
  if(typeof prodStartTicking==='function') prodStartTicking();
  toast('Session rouverte ✓ — ajoute tes tâches');
}
function prodConfirmEndSession(){
  const s=prodSessActive(); if(!s) return;
  const running=(s.tasks||[]).filter(prodTaskRunning).length;
  const msg = running>0
    ? `Clôturer la session ?\n${running} tâche(s) encore en cours seront arrêtées et enregistrées.`
    : 'Clôturer la session de production ?';
  if(!confirm(msg)) return;
  prodSessionEnd();
  prodRenderBoard();
  // La correction des temps existe (écran « Contrôle des temps ») mais n'était atteignable
  // que par le menu. On offre le lien DIRECT juste après la clôture, quand on en a besoin.
  toastAction('Session clôturée ✓', '✎ Corriger les temps', "goView('controletemps')");
  // Apprentissage des temps : on ne le propose que pour les catégories ayant du temps NON encore
  // appris. Si la session a été rouverte pour ajouter du garnissage, on apprendra ce nouveau temps
  // sans recompter les catégories déjà comptabilisées (ex : coques).
  const sClosed = prodSessLoad().find(x=>x.id===s.id) || s;
  const mins = prodSessMinutesByCategory(sClosed);
  const deja = Array.isArray(sClosed._apprisCats) ? sClosed._apprisCats : [];
  const aApprendre = Object.keys(mins).some(cat => mins[cat]>0.1 && !deja.includes(cat));
  if(aApprendre) prodLearnQtyForm(sClosed.id);
}

// Demande le nombre de batchs / meringues réalisés, pour ramener les durées à l'unité de référence.
function prodLearnQtyForm(sessId){
  const s = prodSessLoad().find(x=>x.id===sessId); if(!s) return;
  const mins = prodSessMinutesByCategory(s);
  const deja = Array.isArray(s._apprisCats) ? s._apprisCats : [];
  // on ne montre que les catégories ayant du temps ET pas déjà apprises (cas session rouverte)
  const neuf = cat => mins[cat]>0.1 && !deja.includes(cat);
  const lignes = [];
  if(neuf('coques'))    lignes.push(`🟤 Coques : ${Math.round(mins.coques)} min mesurées`);
  if(neuf('ganache'))   lignes.push(`🍫 Ganache : ${Math.round(mins.ganache)} min`);
  if(neuf('montage'))   lignes.push(`🔧 Montage : ${Math.round(mins.montage)} min`);
  if(neuf('vaisselle')) lignes.push(`🧽 Vaisselle : ${Math.round(mins.vaisselle)} min`);
  if(neuf('entretien')) lignes.push(`🧹 Entretien : ${Math.round(mins.entretien)} min`);
  const needMeringues = neuf('coques');
  const needBatchs = (neuf('ganache')||neuf('montage')||neuf('vaisselle'));
  const dejaTxt = deja.length ? `<p class="note" style="color:#6a8a5a">✓ Déjà comptabilisé précédemment : ${deja.join(', ')} — non redemandé.</p>` : '';
  openModal(`<h3>📊 Affiner les temps de l'atelier</h3>
    <p class="note">Pour que l'ordonnancement apprenne <b>tes</b> temps réels, indique ce que cette session a produit. Les durées seront ramenées « par batch » et « par meringue ».</p>
    ${dejaTxt}
    <div class="sum-box" style="display:block;background:#faf6ee">${lignes.join('<br>')}</div>
    ${needMeringues?`<div class="field"><label>Nombre de meringues réalisées <span style="color:#9a8a82;font-weight:400">(1 meringue ≈ 2 batchs)</span></label>
      <input type="number" inputmode="numeric" min="0" step="1" id="learn_mer" placeholder="ex : 2"></div>`:''}
    ${needBatchs?`<div class="field"><label>Nombre de batchs réalisés <span style="color:#9a8a82;font-weight:400">(1 batch ≈ 60 macarons)</span></label>
      <input type="number" inputmode="numeric" min="0" step="1" id="learn_bat" placeholder="ex : 4"></div>`:''}
    <p class="note">Tu peux ignorer : la session reste enregistrée, seul l'apprentissage des temps est sauté.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Ignorer</button>
      <button class="btn" onclick="prodLearnQtySave('${sessId}')">Enregistrer & apprendre</button>
    </div>`);
}
function prodLearnQtySave(sessId){
  const s = prodSessLoad().find(x=>x.id===sessId); if(!s){ closeModal(); return; }
  const nbMer = +val('learn_mer')||0;
  const nbBat = +val('learn_bat')||0;
  const fed = prodSessFeedLearning(s, nbBat, nbMer);
  if(fed.length){
    // mémorise les catégories désormais apprises (cumul), pour qu'une re-clôture ne les recompte pas
    const prev = Array.isArray(s._apprisCats) ? s._apprisCats : [];
    s._apprisCats = Array.from(new Set([...prev, ...fed]));
    prodSessUpsert(s);
  }
  closeModal();
  if(fed.length) toast(`Temps appris ✓ (${fed.join(', ')})`);
  else toast('Aucune quantité renseignée — apprentissage sauté');
}

function ttLoad(){
  try{ const a=JSON.parse(localStorage.getItem(TT_SESSIONS_KEY)||'[]'); return Array.isArray(a)?a:[]; }
  catch(e){ return []; }
}
function ttSave(arr){ localStorage.setItem(TT_SESSIONS_KEY, JSON.stringify(arr||[])); }
function ttGet(id){ return ttLoad().find(s=>s.id===id); }
function ttUpsert(sess){ const a=ttLoad(); const i=a.findIndex(s=>s.id===sess.id); if(i>=0) a[i]=sess; else a.push(sess); ttSave(a); }
function ttRemove(id){ ttSave(ttLoad().filter(s=>s.id!==id)); }
// Annule un chrono en cours SANS l'enregistrer dans l'historique (suppression directe).
function ttCancel(id){
  const s=ttGet(id); if(!s){ ttRefresh(); return; }
  const lbl = s.activite ? `« ${s.activite} »` : 'ce chrono';
  if(!confirm(`Annuler ${lbl} sans l'enregistrer ?\nLe temps écoulé ne sera pas conservé.`)) return;
  ttRemove(id);
  ttRefresh();
  if(!ttLoad().length) ttStopTicking();
  toast('Chrono annulé');
}
function ttSessionPaused(s){ return s && (+s.pauseAt||0)>0; }
// Temps net d'UN chrono (ms) — recalculé depuis les timestamps (résilient à la veille iOS).
function ttSessionNet(s){
  if(!s||!s.start) return 0;
  const accum=+s.pausedAccum||0;
  const cur=(+s.pauseAt||0)>0 ? Math.max(0, Date.now()-(+s.pauseAt)) : 0;
  return Math.max(0, Date.now()-s.start-accum-cur);
}
function ttAnyRunning(){ return ttLoad().some(s=>!ttSessionPaused(s)); }

// Migration : convertit une éventuelle ancienne session mono en multi.
function ttMigrateLegacy(){
  const start=+localStorage.getItem(TT_KEY)||0;
  if(start>0 && !ttLoad().length){
    ttUpsert({ id:'tt'+start, start, activite:localStorage.getItem(TT_ACT_KEY)||'',
      pausedAccum:+localStorage.getItem(TT_PAUSED_KEY)||0, pauseAt:+localStorage.getItem(TT_PAUSE_AT_KEY)||0 });
  }
  [TT_KEY,TT_PAUSED_KEY,TT_PAUSE_AT_KEY,TT_ACT_KEY].forEach(k=>localStorage.removeItem(k));
}

function ttFormat(ms){
  // Garde : une durée NÉGATIVE (fin avant début = paire d'horodatages inversée) ne doit jamais
  // s'afficher en clair (« -161629s »). C'est un incident de données, pas une mesure : on le
  // signale honnêtement plutôt que d'imprimer un nombre absurde. (cf. « zéro n'est pas une mesure »)
  if(!(ms>0)){
    if(ms<0) return 'durée invalide';           // horodatages incohérents (début après fin)
    return '00h 00m 00s';                        // durée nulle (assemblage instantané, p.ex.)
  }
  const totalMin = Math.floor(ms/60000);
  const h = Math.floor(totalMin/60), m = totalMin%60;
  if(totalMin<1){ const s=Math.floor(ms/1000); return `00h 00m ${String(s).padStart(2,'0')}s`; }
  return `${String(h).padStart(2,'0')}h ${String(m).padStart(2,'0')}m`;
}

// Couleur associée à chaque type d'activité (pour repérer la tâche en cours d'un coup d'œil).
// Les activités connues ont une teinte fixe ; les libres (« Autre … ») dérivent une couleur
// stable de leur texte, pour qu'une même tâche garde toujours la même couleur.
const TT_ACT_COLORS = {
  'Déplacements / livraisons':'#5a7a9a', 'Administratif':'#7a6a9a', 'Courses':'#cf7a3a',
  'Préparation marché':'#caa23b', 'Préparation commande':'#6aa3a0',
  'Relations commerciales / prospection / réseautage':'#d76b86', 'Autre':'#9a8a82'
};
const TT_COLOR_PALETTE = ['#d76b86','#caa23b','#9bc081','#6aa3a0','#8a5a3c','#cf7a3a','#7a6a9a','#5a7a9a','#b98756','#3f7d52','#9a6a82','#5a8a7a'];
function ttActivityColor(activite){
  const a=(activite||'').trim();
  if(!a) return '#3f7d52';                       // sans précision → vert
  if(TT_ACT_COLORS[a]) return TT_ACT_COLORS[a];  // activité connue
  // activité libre : couleur stable dérivée du texte (hash simple)
  let h=0; for(let i=0;i<a.length;i++){ h=(h*31 + a.charCodeAt(i))>>>0; }
  return TT_COLOR_PALETTE[h % TT_COLOR_PALETTE.length];
}
// Petit macaron SVG colorable : deux coques crème + ganache de la couleur de l'activité.
function macaronSVG(col){
  return `<svg viewBox="0 0 40 32" width="100%" height="100%" aria-hidden="true">
    <ellipse cx="20" cy="9" rx="15" ry="8" fill="#efe3c4"/>
    <ellipse cx="20" cy="23" rx="15" ry="8" fill="#efe3c4"/>
    <rect x="6" y="13" width="28" height="6" rx="3" fill="${col}"/>
    <ellipse cx="13" cy="24" rx="3" ry="1.6" fill="#e3d4b0" opacity=".7"/>
    <ellipse cx="27" cy="24" rx="3" ry="1.6" fill="#e3d4b0" opacity=".7"/>
  </svg>`;
}
// Rendu du bandeau : une puce par chrono actif + bouton « + ».
function ttRefresh(){
  const bar=document.getElementById('timeTracker'); if(!bar) return;
  const sessions=ttLoad();
  bar.innerHTML = `<span class="tt-grip">⠿⠿</span>
    <button type="button" class="tt-light green" onclick="ttLightTap(event)" title="Pointeuse"><span>▶</span></button>
    <button type="button" class="tt-light dim" onclick="ttOpenHistory()" title="Historique"><span>🗒</span></button>
    <span class="tt-histlabel">Historique</span>`;
  ttBindDrag(bar, 'sm_tt_pos');
  const wrap=document.getElementById('ttWhisks'); if(!wrap) return;
  wrap.innerHTML = sessions.map(s=>{
    const paused=ttSessionPaused(s);
    const col=ttActivityColor(s.activite);
    return `<div class="tt-whisk${paused?' paused':''}" data-w="${s.id}" style="--tt-col:${col}" onclick="ttWhiskToggle(event,'${s.id}')">
      <span class="whisk-ico">${macaronSVG(col)}</span>
      <span class="whisk-time" data-tt="${s.id}">${ttFormat(ttSessionNet(s))}</span>
      <span class="whisk-ctrl">
        <span class="whisk-lbl">${esc(s.activite||'Production')}${paused?' · pause':''}</span>
        <button type="button" class="wc-pause" onclick="event.stopPropagation();ttPause('${s.id}')" title="${paused?'Reprendre':'Pause'}">${paused?'▶':'⏸'}</button>
        <button type="button" class="wc-cancel" onclick="event.stopPropagation();ttCancel('${s.id}')" title="Annuler sans enregistrer">✕</button>
        <button type="button" class="wc-stop" onclick="event.stopPropagation();ttStop('${s.id}')" title="Stop">⏹</button>
      </span>
    </div>`;
  }).join('');
  wrap.querySelectorAll('.tt-whisk').forEach((el,i)=>ttBindDrag(el, 'sm_ttw_'+i, true));
}
// Tap sur le feu vert : si le bandeau est replié → on le déploie ; s'il est déjà déployé →
// on démarre une activité. Un drag ne déclenche rien (géré par _dragged). Repli auto après délai.
let _ttCollapseTimer=null;
function ttLightTap(ev){
  const bar=document.getElementById('timeTracker'); if(!bar) return;
  if(bar._dragged){ bar._dragged=false; return; }   // c'était un déplacement, pas un tap
  if(ev && ev.stopPropagation) ev.stopPropagation();
  // Un seul tap ouvre la fenêtre : choix d'activité + accès direct à l'historique.
  ttStart();
}
function ttCollapse(){
  const bar=document.getElementById('timeTracker'); if(bar) bar.classList.remove('tt-open');
  clearTimeout(_ttCollapseTimer);
}
function ttWhiskToggle(ev, id){
  const el=ev.currentTarget; if(el._dragged){ el._dragged=false; return; }
  el.classList.toggle('open');
}
function ttBindDrag(el, storeKey, isWhisk){
  if(!el || el._dragBound) return; el._dragBound=true;
  try{ const p=JSON.parse(localStorage.getItem(storeKey)||'null');
    if(p && p.left!=null){ el.style.left=p.left+'px'; el.style.top=p.top+'px'; el.style.right='auto'; el.style.bottom='auto'; } }catch(e){swallow(e,'ttBindDrag')}
  let sx,sy,ox,oy,moved;
  const down=e=>{
    const t=e.touches?e.touches[0]:e; sx=t.clientX; sy=t.clientY; moved=false;
    const r=el.getBoundingClientRect(); ox=r.left; oy=r.top;
    el.classList.add('dragging');
    document.addEventListener('mousemove',move); document.addEventListener('mouseup',up);
    document.addEventListener('touchmove',move,{passive:false}); document.addEventListener('touchend',up);
  };
  const move=e=>{
    const t=e.touches?e.touches[0]:e; const dx=t.clientX-sx, dy=t.clientY-sy;
    if(Math.abs(dx)>4||Math.abs(dy)>4){ moved=true; if(e.cancelable)e.preventDefault(); }
    let nl=Math.max(4,Math.min(window.innerWidth-el.offsetWidth-4, ox+dx));
    let nt=Math.max(4,Math.min(window.innerHeight-el.offsetHeight-4, oy+dy));
    el.style.left=nl+'px'; el.style.top=nt+'px'; el.style.right='auto'; el.style.bottom='auto';
  };
  const up=()=>{
    el.classList.remove('dragging');
    document.removeEventListener('mousemove',move); document.removeEventListener('mouseup',up);
    document.removeEventListener('touchmove',move); document.removeEventListener('touchend',up);
    if(moved){ el._dragged=true;
      try{ localStorage.setItem(storeKey, JSON.stringify({left:parseInt(el.style.left), top:parseInt(el.style.top)})); }catch(e){swallow(e,'ttBindDrag')} }
  };
  el.addEventListener('mousedown',down); el.addEventListener('touchstart',down,{passive:true});
}
function ttStartTicking(){ ttStopTicking(); _ttTick=setInterval(ttTick,1000); }
function ttStopTicking(){ if(_ttTick){ clearInterval(_ttTick); _ttTick=null; } }
// Tick léger : met à jour uniquement les chronos non en pause (pas de re-render complet).
function ttTick(){
  const sessions=ttLoad(); if(!sessions.length){ ttStopTicking(); return; }
  sessions.forEach(s=>{ const el=document.querySelector(`.whisk-time[data-tt="${s.id}"]`); if(el && !ttSessionPaused(s)) el.textContent=ttFormat(ttSessionNet(s)); });
}

// Démarre un NOUVEAU chrono (choix rapide d'activité). N'interrompt pas les autres.
function ttStart(){
  ttCollapse();
  openModal(`<h3>⏱ Pointeuse</h3>
    <button class="btn gold" style="width:100%;margin-bottom:6px" onclick="closeModal();ttOpenHistory()">🗒 Voir l'historique / journal de bord</button>
    <button class="btn ghost" style="width:100%;margin-bottom:6px" onclick="ttManualForm()">➕ Saisir un temps a posteriori (décalé)</button>
    <p class="note" style="margin-top:12px">Démarrer un chrono (plusieurs activités peuvent tourner en parallèle) :</p>
    <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:10px">
      ${TT_ACTIVITIES.map(a=>`<button class="btn ghost" style="flex:1;min-width:44%" onclick="ttStartWith(${JSON.stringify(a).replace(/"/g,'&quot;')})">${esc(a)}</button>`).join('')}
    </div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="ttStartWith('')">Démarrer sans préciser</button></div>`);
}
function ttStartWith(activite){
  // « Autre » → demander une précision libre avant de démarrer.
  if(activite==='Autre'){ ttStartAutre(); return; }
  const id='tt'+Date.now()+'-'+Math.floor(Math.random()*1000);
  ttUpsert({id, start:Date.now(), activite:activite||'', pausedAccum:0, pauseAt:0});
  closeModal(); ttRefresh(); ttStartTicking();
  toast(activite?`⏱ ${activite} démarré`:'Chrono démarré ⏱');
}
// Saisie d'une précision pour l'activité « Autre ».
function ttStartAutre(){
  openModal(`<h3>⏱ Autre activité</h3>
    <div class="field"><label>Précise l'activité</label>
      <input id="tt_autre" placeholder="ex : préparation décor, livraison, courses…" onkeydown="if(event.key==='Enter'){event.preventDefault();ttStartAutreGo();}"></div>
    <div class="modal-actions"><button class="btn ghost" onclick="ttStart()">Retour</button>
      <button class="btn" onclick="ttStartAutreGo()">Démarrer</button></div>`);
  const i=document.getElementById('tt_autre'); if(i) i.focus();
}
function ttStartAutreGo(){
  const txt=(val('tt_autre')||'').trim();
  const label = txt ? `Autre : ${txt}` : 'Autre';
  const id='tt'+Date.now()+'-'+Math.floor(Math.random()*1000);
  ttUpsert({id, start:Date.now(), activite:label, pausedAccum:0, pauseAt:0});
  closeModal(); ttRefresh(); ttStartTicking();
  toast(`⏱ ${label} démarré`);
}
// Pause / reprise d'UN chrono donné.
function ttPause(id){
  const s=ttGet(id); if(!s) return;
  if((+s.pauseAt||0)>0){
    s.pausedAccum=(+s.pausedAccum||0)+Math.max(0,Date.now()-(+s.pauseAt)); s.pauseAt=0;
    ttUpsert(s); ttRefresh(); ttStartTicking(); toast('Reprise ▶');
  } else {
    s.pauseAt=Date.now(); ttUpsert(s); ttRefresh();
    if(!ttAnyRunning()) ttStopTicking();
    toast('En pause ⏸');
  }
}
// Arrêt d'UN chrono : fige la durée, demande le taux, enregistre la session.
function ttStop(id){
  const s=ttGet(id); if(!s){ ttRefresh(); return; }
  const start=s.start, end=Date.now();
  const ms=ttSessionNet(s);
  const heuresDec=Math.round(ms/3600000*100)/100;
  const accum=+s.pausedAccum||0; const pauseMs=accum+((+s.pauseAt||0)>0?Math.max(0,Date.now()-(+s.pauseAt)):0);
  const set=getSettings(); const tauxDefaut=+set.laborRate||0;
  const curAct=s.activite||'';
  // inclut la valeur courante même si personnalisée (ex. « Autre : … »)
  const baseActs=['',...TT_ACTIVITIES];
  if(curAct && !baseActs.includes(curAct)) baseActs.push(curAct);
  const actOpts=baseActs.map(a=>`<option value="${esc(a)}" ${a===curAct?'selected':''}>${a?esc(a):'— non précisé —'}</option>`).join('');
  openModal(`<h3>Fin de chrono</h3>
    <div class="sum-box"><span>Temps travaillé (pauses déduites)</span><b>${ttFormat(ms)}</b></div>
    ${pauseMs>=60000?`<div class="sum-box"><span>Dont pauses déduites</span><b>${ttFormat(pauseMs)}</b></div>`:''}
    <div class="sum-box"><span>Soit en heures</span><b>${heuresDec.toFixed(2)} h</b></div>
    <div class="field" style="margin-top:12px"><label>Nature de l'activité</label><select id="tt_act">${actOpts}</select></div>
    <div class="field"><label>Taux horaire de cette session (€/h)</label>
      <input type="number" min="0" step="0.5" id="tt_rate" value="${tauxDefaut||''}" placeholder="ex : 12"></div>
    <p class="note" id="tt_cost" style="margin-top:4px"></p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal();ttRefresh()">Annuler</button>
      <button class="btn" onclick="ttConfirmStop('${id}',${start},${end},${ms},${pauseMs})">Enregistrer</button>
    </div>`);
  const rate=document.getElementById('tt_rate'), cost=document.getElementById('tt_cost');
  const upd=()=>{ const t=+rate.value||0; cost.textContent=t>0?`Coût de main-d'œuvre : ${euro(money2(heuresDec*t))}`:''; };
  if(rate){ rate.addEventListener('input',upd); upd(); rate.focus(); }
}
async function ttConfirmStop(id, start, end, ms, pauseMs){
  const taux=Math.max(0,+val('tt_rate')||0);
  ms=Math.max(0,+ms||0); pauseMs=Math.max(0,+pauseMs||0);
  const heuresDec=Math.round(ms/3600000*100)/100;
  const totalMin=Math.floor(ms/60000);
  const session={ date:today(), debut:new Date(start).toISOString(), fin:new Date(end).toISOString(),
    dureeMin:totalMin, dureeHeures:heuresDec, pauseMin:Math.floor(pauseMs/60000),
    activite:val('tt_act')||'', tauxHoraire:money2(taux), coutTotal:money2(heuresDec*taux) };
  try{ await db.workSessions.add(session); }catch(e){ console.error('workSession',e); }
  ttRemove(id);
  closeModal(); ttRefresh();
  if(!ttAnyRunning()) ttStopTicking();
  toast(`Session enregistrée${session.activite?` · ${session.activite}`:''} : ${ttFormat(ms)} · ${euro(session.coutTotal)}`);
  if(view==='pointeuse' && typeof renderTimeTracker==='function') renderTimeTracker();
}

// SAISIE DÉCALÉE : créer une session déjà terminée a posteriori, sans chrono.
// Deux modes : durée directe (minutes) OU horaires début/fin. Date choisie (défaut : aujourd'hui).
function ttManualForm(){
  const set=getSettings(); const tauxDefaut=+set.laborRate||0;
  const actOpts=['',...TT_ACTIVITIES].map(a=>`<option value="${esc(a)}">${a?esc(a):'— non précisé —'}</option>`).join('');
  openModal(`<h3>➕ Saisir un temps a posteriori</h3>
    <p class="note">Pour enregistrer un temps de travail passé (ex : une livraison de cet après-midi) sans avoir lancé le chrono.</p>
    <div class="field"><label>Date</label><input type="date" id="ttm_date" value="${today()}"></div>
    <div class="field"><label>Catégorie</label><select id="ttm_act">${actOpts}</select>
      <input id="ttm_autre" placeholder="Préciser si « Autre »… (laisser vide sinon)" style="margin-top:6px"></div>
    <div class="field"><label>Durée (minutes)</label>
      <input type="number" min="0" step="1" id="ttm_dur" inputmode="numeric" placeholder="ex : 40"></div>
    <details style="margin:6px 0">
      <summary style="cursor:pointer;color:var(--caramel,#AA7C39);font-weight:600">Ou saisir les horaires réels</summary>
      <div class="row2" style="margin-top:8px">
        <div class="field"><label>Début</label><input type="time" id="ttm_start"></div>
        <div class="field"><label>Fin</label><input type="time" id="ttm_end"></div>
      </div>
      <p class="note">Si renseignés, les horaires priment sur la durée.</p>
    </details>
    <div class="field"><label>Taux horaire (€/h)</label>
      <input type="number" min="0" step="0.5" id="ttm_rate" value="${tauxDefaut||''}" placeholder="ex : 12"></div>
    <p class="note" id="ttm_cost"></p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="ttStart()">Retour</button>
      <button class="btn" onclick="ttManualSave()">Enregistrer</button>
    </div>`);
  const dur=document.getElementById('ttm_dur'), st=document.getElementById('ttm_start'),
        en=document.getElementById('ttm_end'), rate=document.getElementById('ttm_rate'),
        cost=document.getElementById('ttm_cost');
  const calcMin=()=>{
    const a=(st.value||'').trim(), b=(en.value||'').trim();
    if(a && b){ const pa=a.split(':'), pb=b.split(':');
      let d=(+pb[0]*60+ +pb[1])-(+pa[0]*60+ +pa[1]); if(d<0) d+=1440; return d; }
    return +dur.value||0;
  };
  const upd=()=>{ const m=calcMin(); const t=+rate.value||0;
    cost.textContent=(m>0&&t>0)?`Durée ${Math.floor(m/60)}h${String(m%60).padStart(2,'0')} · Coût : ${euro(money2(m/60*t))}`:(m>0?`Durée ${Math.floor(m/60)}h${String(m%60).padStart(2,'0')}`:''); };
  [dur,st,en,rate].forEach(el=>el&&el.addEventListener('input',upd)); upd();
}
async function ttManualSave(){
  const date=val('ttm_date')||today();
  let act=val('ttm_act')||'';
  const autre=(val('ttm_autre')||'').trim();
  if(act==='Autre' && autre) act='Autre : '+autre;
  // durée : horaires prioritaires sinon minutes
  const a=(val('ttm_start')||'').trim(), b=(val('ttm_end')||'').trim();
  let totalMin;
  if(a && b){ const pa=a.split(':'), pb=b.split(':');
    let d=(+pb[0]*60+ +pb[1])-(+pa[0]*60+ +pa[1]); if(d<0) d+=1440; totalMin=d; }
  else { totalMin=Math.round(+val('ttm_dur')||0); }
  if(!(totalMin>0)){ toast('Indique une durée ou des horaires valides'); return; }
  const taux=Math.max(0,+val('ttm_rate')||0);
  const heuresDec=Math.round(totalMin/60*100)/100;
  // début/fin indicatifs : ancrés sur la date choisie (midi si pas d'horaire), pour l'historique
  let debutIso, finIso;
  if(a && b){ debutIso=new Date(date+'T'+a+':00').toISOString(); finIso=new Date(date+'T'+b+':00').toISOString(); }
  else { const base=new Date(date+'T12:00:00'); debutIso=base.toISOString(); finIso=new Date(base.getTime()+totalMin*60000).toISOString(); }
  const session={ date, debut:debutIso, fin:finIso,
    dureeMin:totalMin, dureeHeures:heuresDec, pauseMin:0,
    activite:act, tauxHoraire:money2(taux), coutTotal:money2(heuresDec*taux), saisieDecalee:true };
  try{ await db.workSessions.add(session); }catch(e){ console.error('workSession manual',e); toast('Erreur d\'enregistrement'); return; }
  closeModal();
  toast(`Temps enregistré${act?` · ${act}`:''} : ${Math.floor(totalMin/60)}h${String(totalMin%60).padStart(2,'0')}`);
  if(view==='pointeuse' && typeof renderTimeTracker==='function') renderTimeTracker();
}
// Historique rapide des sessions (modale).
async function ttOpenHistory(){
  const sessions = (await db.workSessions.orderBy('date').reverse().toArray().catch(()=>[]))
    .filter(x => x.fin || (+x.dureeMin>0));   // n'afficher que les sessions terminées (chrono arrêté)
  const totMin = sessions.reduce((s,x)=>s+(+x.dureeMin||0),0);
  const totCout = sessions.reduce((s,x)=>s+(+x.coutTotal||0),0);
  const th=Math.floor(totMin/60), tm=totMin%60;
  // Couleur de pastille par type d'activité (cohérence visuelle)
  const actColor = a => {
    const m={'Pesées':'#6aa3a0','Ganache':'#8a6d3b','Meringue':'#c1a27c','Macaronnage':'#aa7c39',
      'Pochage':'#7a6a9a','Cuisson':'#c0392b','Garnissage/Montage':'#3f7d52','Vaisselle':'#5a8aa0',
      'Nettoyage fin de prod':'#6a8a5a','Conditionnement':'#9a7320'};
    return m[a]||'#8a7a72';
  };
  // Regroupement par jour pour un vrai « journal de bord »
  const parJour={};
  sessions.forEach(x=>{ const d=(x.date||'').slice(0,10)||'?'; (parJour[d]=parJour[d]||[]).push(x); });
  const jours=Object.keys(parJour).sort().reverse().slice(0,30);

  const cards = jours.map(d=>{
    const list=parJour[d];
    const jourMin=list.reduce((s,x)=>s+(+x.dureeMin||0),0);
    const jourCout=list.reduce((s,x)=>s+(+x.coutTotal||0),0);
    const jh=Math.floor(jourMin/60), jm=jourMin%60;
    const items=list.map(x=>{
      const h=Math.floor((+x.dureeMin||0)/60), m=(+x.dureeMin||0)%60;
      const pMin=+x.pauseMin||0;
      return `<div class="ws-line">
        <div class="ws-line-l">
          <span class="ws-act" style="background:${actColor(x.activite)}">${x.activite?esc(x.activite):'Activité'}</span>
          <span class="ws-time">${fmtTime(x.debut)}${x.fin?'–'+fmtTime(x.fin):''}</span>
        </div>
        <div class="ws-line-m">
          <span class="ws-dur"><b>${String(h).padStart(2,'0')}h${String(m).padStart(2,'0')}</b></span>
          ${pMin>=1?`<span class="ws-pause">+${pMin}m pause</span>`:''}
        </div>
        <div class="ws-line-r">
          <span class="ws-cost">${euro(x.coutTotal)}</span>
          <span class="ws-edit" onclick="ttEditSession(${x.id})" title="Modifier">✎</span><span class="ws-del" onclick="ttDeleteSession(${x.id})" title="Supprimer">🗑</span>
        </div>
      </div>`;
    }).join('');
    return `<div class="ws-card">
      <div class="ws-card-head">
        <span class="ws-date">${fmtDate(d)}</span>
        <span class="ws-day-tot">${String(jh).padStart(2,'0')}h ${String(jm).padStart(2,'0')}m · ${euro(jourCout)}</span>
      </div>
      <div class="ws-lines">${items}</div>
    </div>`;
  }).join('');

  openModal(`<h3>🗒 Journal de bord — temps de travail</h3>
    <div class="ws-total"><div><span class="ws-total-lbl">Total cumulé</span><b>${String(th).padStart(2,'0')}h ${String(tm).padStart(2,'0')}m</b></div><div class="ws-total-cout">${euro(totCout)}</div></div>
    ${sessions.length?`<div class="flex" style="gap:8px;margin:10px 0"><button class="btn gold sm" onclick="closeModal();goView('analyse')">📊 Analyse des temps & conseils</button></div>
    <div class="ws-cards">${cards}</div>${jours.length>=30?'<p class="note">30 derniers jours affichés.</p>':''}`
    :'<p class="empty">Aucune session enregistrée pour l\'instant. Lance une activité depuis le feu vert pour commencer à chronométrer ton temps de travail.</p>'}
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}
// ===================== ATELIER CHRONO — ÉDITION D'UNE SESSION (bloc A, point 3) =====================
// Manque comblé : on pouvait supprimer une session mais pas la corriger. ttEditSession ouvre un
// formulaire pré-rempli (activité, durée, taux) et met à jour la session en recalculant le coût.

async function ttEditSession(id){
  const s = await db.workSessions.get(id);
  if(!s){ toast('Session introuvable'); return; }
  const set = (typeof getSettings==='function') ? getSettings() : {};
  const tauxDef = (+s.tauxHoraire || +set.laborRate || 0);
  const curAct = s.activite || '';
  const baseActs = ['', ...TT_ACTIVITIES];
  if(curAct && !baseActs.includes(curAct)) baseActs.push(curAct);
  const actOpts = baseActs.map(a=>`<option value="${esc(a)}" ${a===curAct?'selected':''}>${a?esc(a):'— non précisé —'}</option>`).join('');
  const dureeMin = +s.dureeMin || 0;

  openModal(`<h3>✎ Modifier la session</h3>
    <p class="note" style="margin-bottom:8px">${s.date?fmtDate(s.date):''}${s.debut?` · ${fmtTime(s.debut)}${s.fin?'–'+fmtTime(s.fin):''}`:''}</p>
    <div class="field"><label>Activité</label><select id="tte_act">${actOpts}</select>
      <input id="tte_autre" placeholder="Préciser si « Autre »… (laisser vide sinon)" style="margin-top:6px"></div>
    <div class="field"><label>Durée (minutes)</label>
      <input type="number" min="0" step="1" id="tte_dur" inputmode="numeric" value="${dureeMin}"></div>
    <div class="field"><label>Taux horaire (€/h)</label>
      <input type="number" min="0" step="0.5" id="tte_rate" value="${tauxDef||''}" placeholder="ex : 12"></div>
    <p class="note" id="tte_cost"></p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal();ttOpenHistory()">Annuler</button>
      <button class="btn" onclick="ttEditSave(${id})">Enregistrer</button>
    </div>`);

  const dur=document.getElementById('tte_dur'), rate=document.getElementById('tte_rate'), cost=document.getElementById('tte_cost');
  const upd=()=>{
    const m=+dur.value||0, t=+rate.value||0;
    const h=Math.round(m/60*100)/100;
    cost.textContent = (m>0&&t>0) ? `Coût recalculé : ${euro(money2(h*t))} (${h.toFixed(2)} h)` : '';
  };
  if(dur){ dur.addEventListener('input',upd); }
  if(rate){ rate.addEventListener('input',upd); }
  upd();
}

async function ttEditSave(id){
  const s = await db.workSessions.get(id);
  if(!s){ toast('Session introuvable'); return; }
  let act = (typeof val==='function' ? val('tte_act') : '') || '';
  const autre = (typeof val==='function' ? val('tte_autre') : '') || '';
  if(autre.trim()){ act = act && act!=='Autre' ? act : ('Autre : '+autre.trim()); }
  const dureeMin = Math.max(0, Math.floor(+val('tte_dur')||0));
  const taux = Math.max(0, +val('tte_rate')||0);
  const heures = Math.round(dureeMin/60*100)/100;
  await db.workSessions.update(id, {
    activite: act,
    dureeMin: dureeMin,
    dureeHeures: heures,
    tauxHoraire: money2(taux),
    coutTotal: money2(heures*taux)
  });
  closeModal();
  ttOpenHistory();
  if(view==='pointeuse' && typeof renderTimeTracker==='function') renderTimeTracker();
  toast('Session modifiée ✓');
}
// =============================================================================

async function ttDeleteSession(id){
  if(!confirm('Supprimer cette session de travail ?')) return;
  await db.workSessions.delete(id).catch(()=>{});
  ttOpenHistory();
  if(view==='pointeuse' && typeof renderTimeTracker==='function') renderTimeTracker();
}
// Initialisation au boot : migre une éventuelle session mono, reprend les chronos en cours.
function ttInit(){
  ttMigrateLegacy();
  ttRefresh();
  if(ttAnyRunning()) ttStartTicking();
  document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState==='visible'){ ttRefresh(); if(ttAnyRunning()) ttStartTicking(); } });
}

/* ============================================================
   MASCOTTE — Chat de labo, reflet de la jauge de sérénité
   - 5 expressions calées sur les paliers exacts de la jauge.
   - SVG inline (net, léger, colorable, 100% offline).
   - Bulle flottante DÉPLAÇABLE au doigt ; position mémorisée.
   - S'estompe quand on touche près d'elle / pendant le drag, pour
     ne jamais gêner la lecture. Un tap ouvre l'Assistant (jauge).
   - Synchronisée en continu (au changement de vue + rafraîchissement).
   ============================================================ */
// Mappage partagé jauge ↔ mascotte (paliers IDENTIQUES à la jauge).
function serenityTier(score){
  if(score>=85) return {label:'Sérénité',       col:'#3f7d52', mood:'tres-serein'};
  if(score>=60) return {label:'Maîtrisé',        col:'#7faa4f', mood:'serein'};
  if(score>=40) return {label:'Vigilance',       col:'#caa23b', mood:'vigilance'};
  if(score>=20) return {label:'Tension',         col:'#d98324', mood:'tension'};
  return            {label:'Zone de stress',  col:'#b3261e', mood:'stress'};
}

// Dessine le chat selon l'humeur. Couleur = couleur de palier (col).
// moods : 'stress' | 'tension' | 'vigilance' | 'serein' | 'tres-serein'
// Mascotte MACARON (inspirée d'une photo) : coque haute caramel, coque basse jaune safran,
// ganache foncée au centre. Le visage (sur la coque haute) change selon l'humeur ; la couleur
// de la jauge (col) sert d'accent (liseré + joues) pour rester cohérent avec le système.
function mascotSVG(mood, col){
  let eyes, mouth, brows='', extra='', cheekOp='.55';
  switch(mood){
    case 'stress': // yeux écarquillés, bouche ouverte inquiète, gouttes de sueur
      brows = `<path d="M22 30 L33 27 M58 30 L47 27" stroke="#5a3a22" stroke-width="2.2" stroke-linecap="round"/>`;
      eyes  = `<ellipse cx="30" cy="36" rx="5.2" ry="6" fill="#fff"/><ellipse cx="50" cy="36" rx="5.2" ry="6" fill="#fff"/>
               <circle cx="30" cy="37.5" r="3" fill="#3a2418"/><circle cx="50" cy="37.5" r="3" fill="#3a2418"/>`;
      mouth = `<ellipse cx="40" cy="50" rx="5" ry="6" fill="#5a2a22"/>`;
      extra = `<path d="M63 33 q3 5 0 9 q-3 -4 0 -9Z" fill="#7ec8e3"/><path d="M16 30 q2.5 4 0 7.5 q-2.5 -3.5 0 -7.5Z" fill="#7ec8e3"/>`;
      cheekOp='.3';
      break;
    case 'tension': // sourcils froncés, bouche plate ondulée
      brows = `<path d="M23 29 L33 31 M57 29 L47 31" stroke="#5a3a22" stroke-width="2.2" stroke-linecap="round"/>`;
      eyes  = `<circle cx="30" cy="39" r="4.4" fill="#3a2418"/><circle cx="50" cy="39" r="4.4" fill="#3a2418"/>`;
      mouth = `<path d="M32 52 Q36 49 40 52 Q44 55 48 52" fill="none" stroke="#5a2a22" stroke-width="2.4" stroke-linecap="round"/>`;
      cheekOp='.4';
      break;
    case 'vigilance': // neutre attentif, petit sourire discret
      eyes  = `<circle cx="30" cy="38" r="4.6" fill="#3a2418"/><circle cx="50" cy="38" r="4.6" fill="#3a2418"/>
               <circle cx="31.6" cy="36.6" r="1.5" fill="#fff"/><circle cx="51.6" cy="36.6" r="1.5" fill="#fff"/>`;
      mouth = `<path d="M34 51 Q40 54 46 51" fill="none" stroke="#5a2a22" stroke-width="2.4" stroke-linecap="round"/>`;
      break;
    case 'serein': // sourire franc, joues roses, yeux pétillants
      eyes  = `<circle cx="30" cy="38" r="4.6" fill="#3a2418"/><circle cx="50" cy="38" r="4.6" fill="#3a2418"/>
               <circle cx="31.8" cy="36.4" r="1.6" fill="#fff"/><circle cx="51.8" cy="36.4" r="1.6" fill="#fff"/>`;
      mouth = `<path d="M32 50 Q40 58 48 50" fill="none" stroke="#5a2a22" stroke-width="2.6" stroke-linecap="round"/>`;
      cheekOp='.75';
      break;
    default: // tres-serein : yeux fermés satisfaits, grand sourire, petites notes de bonheur
      eyes  = `<path d="M25 38 Q30 33 35 38" fill="none" stroke="#3a2418" stroke-width="2.4" stroke-linecap="round"/>
               <path d="M45 38 Q50 33 55 38" fill="none" stroke="#3a2418" stroke-width="2.4" stroke-linecap="round"/>`;
      mouth = `<path d="M31 50 Q40 60 49 50" fill="none" stroke="#5a2a22" stroke-width="2.6" stroke-linecap="round"/>`;
      extra = `<text x="58" y="22" font-size="10" fill="${col}" font-family="serif">♪</text><text x="66" y="15" font-size="7" fill="${col}" font-family="serif">♫</text>`;
      cheekOp='.8';
      break;
  }
  // joues colorées selon la jauge
  const cheeks = `<ellipse cx="22" cy="44" rx="4.5" ry="3" fill="${col}" opacity="${cheekOp}"/><ellipse cx="58" cy="44" rx="4.5" ry="3" fill="${col}" opacity="${cheekOp}"/>`;
  return `<svg viewBox="0 0 80 80" width="100%" height="100%" aria-hidden="true">
    <defs>
      <linearGradient id="mcTop" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#c98a4e"/><stop offset="1" stop-color="#a96a32"/>
      </linearGradient>
      <linearGradient id="mcBot" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#f4c43a"/><stop offset="1" stop-color="#e0a81f"/>
      </linearGradient>
    </defs>
    <!-- coque basse (jaune safran) + sa collerette -->
    <ellipse cx="40" cy="62" rx="30" ry="11" fill="url(#mcBot)"/>
    <path d="M11 60 q4 5 10 5.5 M69 60 q-4 5 -10 5.5 M24 64 q3 3 7 3.2 M49 64 q3 0 7 -3.2" stroke="#caa01c" stroke-width="1.4" fill="none" opacity=".5"/>
    <!-- ganache foncée -->
    <ellipse cx="40" cy="55" rx="27" ry="7" fill="#4a2a1c"/>
    <!-- coque haute (caramel) -->
    <ellipse cx="40" cy="40" rx="32" ry="24" fill="url(#mcTop)"/>
    <!-- liseré couleur jauge (fin, en bas de la coque haute) -->
    <path d="M9 44 q31 14 62 0" fill="none" stroke="${col}" stroke-width="2.4" stroke-linecap="round" opacity=".85"/>
    <!-- collerette (pied) de la coque haute -->
    <path d="M10 47 q5 5 11 5.5 M70 47 q-5 5 -11 5.5 M25 51 q4 3 8 3 M47 51 q4 0 8 -3" stroke="#8a5a2e" stroke-width="1.5" fill="none" opacity=".55"/>
    <!-- brillance -->
    <ellipse cx="30" cy="28" rx="13" ry="6" fill="#fff" opacity=".18"/>
    ${cheeks}${brows}${eyes}${mouth}${extra}
  </svg>`;
}

let _mascotScore=null, _mascotTimer=null;
// Rafraîchit l'expression de la mascotte d'après le score courant.
async function mascotRefresh(){
  const host=document.getElementById('mascot'); if(!host) return;
  let g; try{ g=await calculateSerenityScore({horizon:15}); }catch(e){ return; }
  _mascotScore=g.score;
  const tier=serenityTier(g.score);
  const face=host.querySelector('.mascot-face');
  if(face) face.innerHTML=mascotSVG(tier.mood, tier.col);
  host.style.setProperty('--mascot-col', tier.col);
  host.classList.toggle('alarm', tier.mood==='stress'); // léger tremblement si stress
  const lbl=host.querySelector('.mascot-badge');
  if(lbl){ lbl.textContent=g.score+'%'; lbl.style.background=tier.col; }
  host.setAttribute('aria-label', `Sérénité : ${g.score}% (${tier.label})`);
  host.title=`Sérénité : ${g.score}% · ${tier.label}`;
}
// Crée la bulle flottante déplaçable et lance la synchro.
function mascotInit(){
  if(document.getElementById('mascot')) return;
  const host=document.createElement('div');
  host.id='mascot';
  host.innerHTML=`<div class="mascot-bubble" id="mascotBubble">Coucou ! 🍩</div>
    <div class="mascot-face"></div><span class="mascot-badge">—</span>`;
  document.body.appendChild(host);
  // Position FIXE (bas-droite, près du CA du mois) : on ne restaure plus de position
  // déplacée et on purge toute position mémorisée (évite qu'elle reste coincée hors écran).
  try{
    if(localStorage.getItem('sm_mascot_home')!=='v3-fixed'){
      localStorage.removeItem('sm_mascot_pos');
      localStorage.setItem('sm_mascot_home','v3-fixed');
    }
    localStorage.removeItem('sm_mascot_pos'); // ancrage CSS systématique
  }catch(e){swallow(e,'mascotInit')}
  mascotSetupTap(host);
  mascotRefresh();
  // visible uniquement sur l'accueil au démarrage
  mascotSetVisible(view==='dash');
  // synchro périodique (background) tant que l'app est au premier plan
  if(_mascotTimer) clearInterval(_mascotTimer);
  _mascotTimer=setInterval(()=>{ if(document.visibilityState==='visible') mascotRefresh(); }, 60000);
  document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState==='visible') mascotRefresh(); });
}
// Affiche ou masque la mascotte (présente uniquement sur l'accueil).
function mascotSetVisible(on){
  const host=document.getElementById('mascot'); if(!host) return;
  host.style.display = on ? '' : 'none';
  if(!on && typeof mascotBubbleReset==='function') mascotBubbleReset(); // repli au départ de l'accueil
}
// Mascotte FIXE : un tap agrandit la bulle et y affiche le briefing « À faire aujourd'hui ».
function mascotSetupTap(host){
  // Comportements DISTINCTS :
  //  - la BULLE « Coucou ! » → ouvre le briefing « À faire aujourd'hui »
  //  - la MASCOTTE (le donut) → va directement à la page Assistant
  host.addEventListener('click', (e)=>{
    e.stopPropagation();
    // Si le clic vient de la bulle, son propre handler s'en charge (ne rien faire ici).
    if(e.target && e.target.closest && e.target.closest('#mascotBubble')) return;
    mascotGoAssistantDirect();
  });
  const bubble=host.querySelector('#mascotBubble');
  if(bubble){
    bubble.style.cursor='pointer';
    bubble.addEventListener('click', (e)=>{ e.stopPropagation(); mascotToggleBubble(); });
  }
}
// Navigation directe vers l'assistant depuis la mascotte (sans modale → pas de conflit d'historique).
function mascotGoAssistantDirect(){
  goView('assistant');
}
// Répliques de la mascotte : ton complice et taquin, déclinées par état de sérénité.
// Plusieurs variantes par état → tirage au hasard pour varier à chaque ouverture.
