/* ============================================================
   MRP — Assistant Plan de Production Adaptatif
   Branché sur les structures réelles (orders → orderToLines/_orderParfumDemand,
   stock fini = somme productions.qteRestante par parfum, recipes.poidsGarnitureUnit).
   Apprentissage des temps stocké en localStorage (config, sans toucher au schéma).
   ============================================================ */
// Habitude de production réelle : 1 batch = 60 macarons (120 coques).
// Une seule MERINGUE sert 2 batchs (2 parfums) = production mutualisée :
// on coule une meringue, on la divise pour 2 ordres de fabrication.
// → l'étape coques/meringue est partagée ; ganache + montage restent par parfum.
const TAILLE_BATCH_MACARONS = 60;        // macarons par "batch" unitaire (1 ordre de fabrication)
// [v1315] GRAND FORMAT : l'usage diffère — 1 batch = 48 coques = 24 macarons (règle métier Benjamin).
// Rapporter un temps GF à un batch de 60 le surestimerait de 2,5×.
const TAILLE_BATCH_MACARONS_GF = 24;     // macarons par batch en grand format (48 coques)
// Taille de batch applicable à une recette donnée (lit recipe.grandFormat — jamais le nom du parfum).
function _tailleBatchPour(recipe){
  return (recipe && recipe.grandFormat) ? TAILLE_BATCH_MACARONS_GF : TAILLE_BATCH_MACARONS;
}
const COQUES_PAR_BATCH = 120;            // coques par batch (2 coques/macaron)
const BATCHS_PAR_MERINGUE = 2;           // capacité d'une meringue = 2 batchs = 120 macarons = 240 coques
const MACARONS_PAR_MERINGUE = 120;       // capacité utile réelle d'une meringue (240 coques)

// REMPLISSAGE DES MERINGUES par capacité (120 macarons / 240 coques chacune).
// La mutualisation n'est pas imposée : un parfum qui a besoin de ≥120 macarons
// remplit des meringues entières à lui seul ; on ne regroupe 2 parfums que pour
// combler une meringue partiellement vide (optimisation du remplissage, pas une règle).
// ───────────────────────────────────────────────────────────────────────────
// [SUGGESTION PARFUMS] Moteur PUR de suggestion de parfums pour les macarons « sans
// parfum » d'un coffret. Aucune dépendance à la base : tout arrive en paramètres, donc
// testable au harnais Node. La collecte des données (stock, coûts, temps) est faite par
// un appelant async séparé.
//
// Entrées :
//   quantite       : nb de macarons à attribuer (le « sansParfum » de la ligne).
//   taille         : format du coffret (6, 8, 16, 25, ou autre).
//   parfumsPresents: noms déjà ventilés dans la ligne (pour respecter le plafond).
//   stockLibre     : { nomParfum: qteDisponible } — stock dormant NON réservé.
//   catalogue      : [{ nom, coutMatUnit, tempsUnitMin }] — parfums produisibles, avec coût/temps.
//   opts           : { paliers:true, palierSet:[30,60,120] } — arrondi batch.
//
// Logique : (1) plafond de parfums selon le format ; (2) écouler le STOCK dormant d'abord
// (gros stocks en tête) ; (3) compléter le reste au plus RENTABLE (coût matière croissant,
// départage par temps) ; (4) respecter les paliers de batch si demandé.
//
// Sortie : { ok, repartition:[{nom, qte, source:'stock'|'production'}], totalAttribue,
//            plafond, nbParfumsAjoutes, reste, note }.
// Nombre de parfums DIFFÉRENTS d'un coffret selon l'offre (BOX_FLAVOR_LIMIT). C'est à la fois le
// plafond ET la cible : un coffret généré vise ce nombre de parfums (6→3, 8→4, 16→4, 25→5).
function PLAFOND_PARFUMS_COFFRET(taille){
  const t = +taille||0;
  // Source unique : la table de l'offre si dispo, sinon repli équivalent.
  if(typeof BOX_FLAVOR_LIMIT!=='undefined' && BOX_FLAVOR_LIMIT){
    if(BOX_FLAVOR_LIMIT[t]!=null) return BOX_FLAVOR_LIMIT[t];
    // taille hors table : on prend la plus grande borne connue (25→5).
    const cles = Object.keys(BOX_FLAVOR_LIMIT).map(Number).sort((a,b)=>a-b);
    for(const c of cles){ if(t<=c) return BOX_FLAVOR_LIMIT[c]; }
    return BOX_FLAVOR_LIMIT[cles[cles.length-1]];
  }
  if(t<=6)  return 3;
  if(t<=16) return 4;
  return 5;
}
function suggererParfumsPur(quantite, taille, parfumsPresents, stockLibre, catalogue, opts){
  opts = opts || {};
  const paliers = opts.paliers!==false;
  const palierSet = (opts.palierSet && opts.palierSet.length) ? opts.palierSet.slice().sort((a,b)=>a-b) : [30,60,120];
  const Q = Math.max(0, Math.round(+quantite||0));
  if(Q<=0) return { ok:false, note:'Aucun macaron à attribuer.', repartition:[], totalAttribue:0 };

  const plafond = PLAFOND_PARFUMS_COFFRET(taille);
  const presents = new Set((parfumsPresents||[]).map(n=> (n||'').trim()).filter(Boolean));
  // Combien de NOUVEAUX parfums on peut encore ajouter sans dépasser le plafond.
  let slotsRestants = Math.max(0, plafond - presents.size);

  const repartition = [];   // [{nom, qte, source}]
  let reste = Q;

  // normalise une clé de comparaison stock/catalogue (insensible casse/accents léger).
  const norm = n => (n||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();

  // ── ÉTAPE 1 : écouler le STOCK dormant, MAIS en respectant la ventilation du coffret.
  // Un coffret doit rester un assortiment : on plafonne ce qu'un seul parfum prend, pour ne pas
  // qu'un gros stock monopolise tout le coffret et écrase la cible de parfums différents.
  // Part max par parfum ≈ quantité répartie sur le nombre de parfums cible (arrondi au-dessus),
  // pour laisser de la place aux autres. Les parfums DÉJÀ présents ne consomment pas de slot.
  const cibleParfums = Math.max(1, plafond);
  const partMaxStock = Math.max(1, Math.ceil(Q / cibleParfums));
  const stockArr = Object.keys(stockLibre||{})
    .map(nom=>({ nom, qte:Math.max(0, Math.floor(+stockLibre[nom]||0)) }))
    .filter(x=>x.qte>0)
    .sort((a,b)=>{
      const pa = presents.has(a.nom)?0:1, pb = presents.has(b.nom)?0:1;
      if(pa!==pb) return pa-pb;
      return b.qte - a.qte;
    });

  for(const s of stockArr){
    if(reste<=0) break;
    const estPresent = presents.has(s.nom);
    if(!estPresent && slotsRestants<=0) continue;   // plus de place pour un nouveau parfum
    // On limite la prise à la part équilibrée (sauf parfum déjà présent : on peut le compléter plus).
    const cap = estPresent ? reste : partMaxStock;
    const prendre = Math.min(s.qte, reste, cap);
    if(prendre<=0) continue;
    repartition.push({ nom:s.nom, qte:prendre, source:'stock' });
    reste -= prendre;
    if(!estPresent){ presents.add(s.nom); slotsRestants--; }
  }

  // ── ÉTAPE 2 : compléter le reste au plus RENTABLE, en VISANT le nombre de parfums cible.
  // Un coffret doit avoir une vraie ventilation (autant de parfums différents que l'offre le prévoit),
  // pas tout sur un seul. On répartit AU MACARON PRÈS (les paliers de batch 30/60/120 concernent la
  // production groupée, pas la composition d'un coffret). Quantités inégales autorisées, mais on
  // étale sur tous les slots disponibles pour atteindre la cible.
  if(reste>0 && slotsRestants>0){
    const dispo = (catalogue||[])
      .filter(c=> c && c.nom && !repartition.some(r=>norm(r.nom)===norm(c.nom)) && !presents.has(c.nom))
      .sort((a,b)=>{
        const ca=+a.coutMatUnit||0, cb=+b.coutMatUnit||0;
        if(ca!==cb) return ca-cb;                        // moins cher en matière d'abord
        return (+a.tempsUnitMin||0)-(+b.tempsUnitMin||0); // départage par temps
      });
    // On retient autant de parfums que de slots restants (= viser la cible), bornés au catalogue dispo.
    const aProduire = dispo.slice(0, slotsRestants);
    if(aProduire.length){
      // Répartition équilibrée au macaron près : base + 1 pour les premiers (les plus rentables).
      // Ex. 6 macarons sur 3 parfums → 2+2+2 ; 7 sur 3 → 3+2+2.
      const n = aProduire.length;
      const base = Math.floor(reste/n);
      let extra = reste - base*n;
      aProduire.forEach(c=>{
        let q = base + (extra>0?1:0); if(extra>0) extra--;
        if(q>0){ repartition.push({ nom:c.nom, qte:q, source:'production' }); reste -= q; }
      });
    }
  }

  const totalAttribue = repartition.reduce((s,r)=>s+r.qte,0);
  const nbParfumsAjoutes = new Set(repartition.map(r=>r.nom).filter(n=>!(parfumsPresents||[]).includes(n))).size;
  let note = '';
  if(reste>0 && slotsRestants<=0 && PLAFOND_PARFUMS_COFFRET(taille)<=presents.size){
    note = `Plafond de ${plafond} parfums atteint : ${reste} macaron(s) à répartir sur les parfums existants.`;
  } else if(reste>0){
    note = `${reste} macaron(s) n'ont pas pu être attribués (catalogue ou stock insuffisant).`;
  }
  return { ok:true, repartition, totalAttribue, plafond, nbParfumsAjoutes, reste, note };
}

// [SUGGESTION PARFUMS — DÉTECTION] Helper PUR : parmi des commandes décrites par
// { id, client, sansParfum, debutProduction(ISO|null) }, renvoie celles dont la production
// DOIT démarrer (debutProduction atteint ou passé, au jour près) ET qui ont encore des macarons
// à déterminer (sansParfum>0). C'est le « moment clé » : on ne fige les parfums qu'ici, avec la
// réalité du jour. maintenant = Date de référence (injectable pour test).
function detecterCommandesADeterminer(commandes, maintenant){
  const now = maintenant ? new Date(maintenant) : new Date();
  const jourNow = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const out = [];
  const vus = new Set();   // [FIX doublon] une commande ne doit apparaître qu'UNE fois dans l'alerte,
                           // même si la collecte amont l'a listée plusieurs fois (ex. via mut).
  (commandes||[]).forEach(c=>{
    const sp = +c.sansParfum||0;
    if(sp<=0) return;
    if(!c.debutProduction) return;
    if(c.id!=null){ if(vus.has(c.id)) return; vus.add(c.id); }
    const dp = new Date(c.debutProduction);
    if(isNaN(dp)) return;
    const jourDP = new Date(dp.getFullYear(), dp.getMonth(), dp.getDate()).getTime();
    // « Pile au début de production » = le jour J du début de prod est arrivé (ou dépassé).
    if(jourDP <= jourNow){
      out.push({ id:c.id, client:c.client||'', sansParfum:sp, debutProduction:c.debutProduction });
    }
  });
  // Les plus urgentes d'abord (début de prod le plus ancien = le plus en retard).
  out.sort((a,b)=> new Date(a.debutProduction) - new Date(b.debutProduction));
  return out;
}


// appelle le moteur pur. ASYNC car lit la base. AUCUNE écriture.
//   quantite, taille, parfumsPresents : cf. moteur pur.
//   dateLiv : date de livraison de la commande (pour calculer le stock NON réservé aux commandes
//             de la fenêtre). Optionnel : si absente, on prend le stock mobilisable brut.
// Renvoie le même objet que suggererParfumsPur, enrichi de { stockLibre, catalogue } pour debug.
// ⚠️ DÉPRÉCIÉ (v1182) — MOTEUR A. Remplacé par le moteur unifié genererCompositionsCoffret (moteur B),
// qui intègre en plus le surplus mutualisable des batchs planifiés et TOUTES les dépendances
// temporelles (repos ganache, prise crémeux, congélation, dates de dispo réelles des composants).
// Plus aucun appelant actif ; conservé uniquement en repli historique le temps de valider B en réel.
// À SUPPRIMER (avec suggererParfumsPur et appliquerSuggestionParfums) après validation iPhone.
async function suggererParfumsCommande(quantite, taille, parfumsPresents, dateLiv, opts){
  opts = opts || {};
  // 1) Stock mobilisable brut par parfum (clé = nom normalisé via stockMoveKey).
  let mob = {};
  try{ mob = await stockMobilisableParParfum(); }catch(e){ mob = {}; }

  // 2) Réservations : besoins des commandes dont la date tombe dans la fenêtre de calcul.
  //    On retranche du stock ce qui est déjà promis à ces commandes, pour ne garder que le
  //    stock DORMANT réellement libre. Fenêtre : de today à dateLiv + marge (par défaut large).
  const reserve = {};   // nomNorm -> qte réservée
  try{
    const today0 = new Date(); today0.setHours(0,0,0,0);
    const finFenetre = dateLiv ? new Date(dateLiv) : new Date(today0.getTime()+ (opts.fenetreJours||21)*86400000);
    finFenetre.setHours(23,59,59,999);
    const toStr = x => x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');
    const sStr = toStr(today0), eStr = toStr(finFenetre);
    let cmds;
    try{ cmds = await db.orders.where('date').between(sStr, eStr, true, true).toArray(); }
    catch(_){ const all=await db.orders.toArray().catch(()=>[]); cmds=all.filter(o=>o.date&&o.date>=sStr&&o.date<=eStr); }
    cmds = (cmds||[]).filter(o=> (typeof normStatus==='function'?normStatus(o.statut):o.statut)!=='Livrée');
    cmds.forEach(o=>{
      _parfumsQtesDe(o).forEach(p=>{
        const k = (typeof stockMoveKey==='function') ? stockMoveKey(p.nom) : (p.nom||'').toLowerCase();
        reserve[k] = (reserve[k]||0) + (+p.qte||0);
      });
    });
  }catch(e){ /* fenêtre indisponible : on garde le stock brut */ }

  // 3) Stock LIBRE = mobilisable − réservé (jamais négatif). Clé d'affichage = nom lisible.
  const stockLibre = {};
  Object.values(mob).forEach(b=>{
    const k = (typeof stockMoveKey==='function') ? stockMoveKey(b.nom) : (b.nom||'').toLowerCase();
    const libre = Math.max(0, Math.floor((+b.mobilisable||0) - (reserve[k]||0)));
    if(libre>0) stockLibre[b.nom] = libre;   // on garde le nom lisible comme clé
  });

  // 4) Catalogue produisible : chaque recette active → { nom, coutMatUnit, tempsUnitMin }.
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recipeItems = await db.recipeItems.toArray().catch(()=>[]);
  const lots = await db.materialLots.toArray().catch(()=>[]);
  const tempsParNom = await prodTempsParParfumParNom(90).catch(()=>({}));
  const settings = (typeof getSettings==='function') ? getSettings() : {};
  const normNom = n => (typeof aiNormalize==='function') ? aiNormalize(n) : (n||'').toLowerCase();
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const tDef = (typeof MRP_TIME_DEFAULTS!=='undefined') ? MRP_TIME_DEFAULTS : null;
  const tempsDefautMac = tDef ? ((+(tDef.montage&&tDef.montage.estimatedTime)||4)/Math.max(1,TB) + 0.4) : 0.4;
  const catalogue = [];
  // Liste blanche optionnelle : ne suggérer que des parfums que l'appelant sait afficher/commander
  // (ex. la grille du formulaire = constante FLAVORS). Évite de proposer un parfum dont le nom de
  // recette ne correspond à aucune entrée du formulaire. Comparaison normalisée.
  const blanche = (opts.parfumsAutorises && opts.parfumsAutorises.length)
    ? new Set(opts.parfumsAutorises.map(normNom)) : null;
  recipes.forEach(r=>{
    if(r.actif===false) return;
    const nom = r.produitNom; if(!nom) return;
    if(blanche && !blanche.has(normNom(nom))) return;   // hors liste blanche → ignoré
    let coutMatUnit = 0;
    try{ const cr = coutRevientRecette(r, recipeItems, lots, settings, {}); coutMatUnit = +cr.coutMatUnit||0; }catch(_){ coutMatUnit = 0; }
    const tk = tempsParNom[normNom(nom)];
    const tempsUnitMin = (tk && tk.minParMac>0) ? tk.minParMac : tempsDefautMac;
    catalogue.push({ nom, coutMatUnit, tempsUnitMin });
  });
  // De même, on filtre le stock dormant sur la liste blanche (cohérence d'affichage).
  let stockLibreFiltre = stockLibre;
  if(blanche){
    stockLibreFiltre = {};
    Object.keys(stockLibre).forEach(nom=>{ if(blanche.has(normNom(nom))) stockLibreFiltre[nom]=stockLibre[nom]; });
  }

  // 5) Appel du moteur pur.
  const res = suggererParfumsPur(quantite, taille, parfumsPresents, stockLibreFiltre, catalogue,
    { paliers: opts.paliers!==false, palierSet: opts.palierSet });
  res.stockLibre = stockLibreFiltre;
  res.catalogue = catalogue;
  return res;
}

// lignes : [{parfum, besoinNet, ...}]. Renvoie [{parfums:[...], repartition:{p:qte}, macarons, nbBatchs, partielle}].
function _packMeringues(lignes){
  const MAX_PARFUMS = 3;   // une meringue se divise en 3 parts max (3 parfums/colorants)
  // 1) Chaque parfum : autant de meringues PLEINES mono-parfum que possible, + un reste < 120.
  const meringues=[]; const restes=[];   // restes : {parfum, qte<120}
  lignes.forEach(l=>{
    let q=Math.max(0, +l.besoinNet||0);
    while(q>=MACARONS_PAR_MERINGUE){
      meringues.push({parfums:[l.parfum], repartition:{[l.parfum]:MACARONS_PAR_MERINGUE},
        macarons:MACARONS_PAR_MERINGUE, nbBatchs:BATCHS_PAR_MERINGUE, partielle:false});
      q-=MACARONS_PAR_MERINGUE;
    }
    if(q>0) restes.push({parfum:l.parfum, qte:q});
  });
  // 2) Regrouper les restes pour faire le MINIMUM de meringues.
  //    Règle métier : 3 parfums MAX par meringue (contrainte forte, prime sur le 120 strict) ;
  //    on privilégie 2 parfums et on bascule sur 3 quand ça économise une meringue.
  //    Nb mini de meringues = max(capacité, nb parfums / 3). On distribue du plus gros reste au
  //    plus petit, dans le panier le moins rempli ayant encore < 3 parfums (équilibrage).
  if(restes.length){
    restes.sort((a,b)=>b.qte-a.qte);
    const totalMac = restes.reduce((a,r)=>a+r.qte,0);
    const parCapacite = Math.ceil(totalMac / MACARONS_PAR_MERINGUE);
    const parParfums  = Math.ceil(restes.length / MAX_PARFUMS);
    const nbMer = Math.max(1, parCapacite, parParfums);
    const paniers = Array.from({length:nbMer}, ()=>({items:[], qte:0}));
    restes.forEach(r=>{
      let cible=-1, minQte=Infinity;
      for(let i=0;i<paniers.length;i++){
        if(paniers[i].items.length<MAX_PARFUMS && paniers[i].qte<minQte){ cible=i; minQte=paniers[i].qte; }
      }
      if(cible<0){ paniers.push({items:[r], qte:r.qte}); return; }
      paniers[cible].items.push(r); paniers[cible].qte+=r.qte;
    });
    paniers.filter(p=>p.items.length).forEach(p=>{
      const rep={}; p.items.forEach(g=>rep[g.parfum]=g.qte);
      meringues.push({parfums:p.items.map(g=>g.parfum), repartition:rep, macarons:p.qte,
        nbBatchs:Math.min(p.items.length, BATCHS_PAR_MERINGUE), partielle:p.qte<MACARONS_PAR_MERINGUE});
    });
  }
  return meringues;
}

/* ============================================================
   DISPONIBILITÉS & FAISABILITÉ DE COMMANDE
   Planning de travail récurrent BI-HEBDOMADAIRE (alternance A/B),
   ancré sur le lundi 8 juin 2026 (= semaine A). Permet de calculer le
   temps réellement disponible d'ici une date, et de dire instantanément
   si une commande est tenable (stock + temps vs besoin de production).
   Stocké en localStorage (config éditable, sans toucher au schéma).
   ============================================================ */
const AVAIL_KEY = 'sm_availability';
const AVAIL_ANCHOR = '2026-06-08';   // lundi → début d'un cycle, semaine A
// Plages par défaut. dow : 0=Dim … 6=Sam. Chaque plage = [start, end] en "HH:MM".
// 'A' et 'B' alternent une semaine sur deux.
const AVAIL_DEFAULTS = {
  anchor: AVAIL_ANCHOR,
  weekA: {
    1:[['14:00','22:00']], 2:[['14:00','22:00']], 3:[['14:00','22:00']], 4:[['14:00','22:00']], 5:[['14:00','22:00']],
    6:[['09:00','19:00']], 0:[['09:00','19:00']]
  },
  weekB: {
    1:[['08:30','12:00'],['21:30','24:00']], 2:[['08:30','12:00'],['21:30','24:00']],
    3:[['08:30','12:00'],['21:30','24:00']], 4:[['08:30','12:00'],['21:30','24:00']],
    5:[['08:30','12:00'],['21:30','24:00']],
    6:[['09:00','19:00']], 0:[['09:00','19:00']]
  }
};
function getAvailability(){
  try{ const s=JSON.parse(localStorage.getItem(AVAIL_KEY)||'null');
    if(s && s.weekA && s.weekB) return s; }catch(e){swallow(e,'getAvailability')}
  return JSON.parse(JSON.stringify(AVAIL_DEFAULTS));
}
function saveAvailability(a){ localStorage.setItem(AVAIL_KEY, JSON.stringify(a)); }

// --- Exceptions de planning (vacances, jours fermés, horaires ponctuels) ---
// Une exception = {id, start:'YYYY-MM-DD', end:'YYYY-MM-DD', etat:'ferme'|'full'|'custom', slots:[['HH:MM','HH:MM']]}
// Elle REMPLACE le cycle A/B sur les dates couvertes (incluses). 'ferme' = aucune plage.
const AVAIL_EXC_KEY = 'sm_availExceptions';
function getAvailExceptions(){
  try{ const a=JSON.parse(localStorage.getItem(AVAIL_EXC_KEY)||'[]'); return Array.isArray(a)?a:[]; }
  catch(e){ return []; }
}
function saveAvailExceptions(arr){ localStorage.setItem(AVAIL_EXC_KEY, JSON.stringify(Array.isArray(arr)?arr:[])); }
// Trouve l'exception couvrant une date (la plus récemment ajoutée gagne en cas de chevauchement).
function findAvailException(dateStr){
  const list=getAvailExceptions();
  let found=null;
  list.forEach(e=>{ if(e && e.start && e.end && dateStr>=e.start && dateStr<=e.end) found=e; });
  return found;
}

// "HH:MM" → minutes depuis minuit (gère 24:00 = 1440 = minuit fin de journée).
function hmToMin(hm){ const [h,m]=String(hm).split(':').map(Number); return (h||0)*60+(m||0); }
// Numéro de semaine du cycle (A ou B) pour une date donnée, par rapport à l'ancre.
function availWeekType(dateStr, conf){
  const anchor=new Date((conf||getAvailability()).anchor||AVAIL_ANCHOR);
  // lundi de la semaine de l'ancre (déjà un lundi) ; lundi de la date cible
  const d=new Date(dateStr);
  const mondayOf = x=>{ const t=new Date(x); const day=(t.getDay()+6)%7; t.setDate(t.getDate()-day); t.setHours(0,0,0,0); return t; };
  const a=mondayOf(anchor), b=mondayOf(d);
  const weeks=Math.round((b-a)/(7*86400000));
  return (((weeks%2)+2)%2===0) ? 'A' : 'B';
}
// Plages d'un jour donné (Date) selon le cycle.
function availSlotsForDate(d, conf){
  conf=conf||getAvailability();
  const dateStr = ymdLocal(d);
  // [EXCEPTIONS] Priorité absolue : si une exception couvre cette date, elle remplace le cycle A/B.
  const exc = findAvailException(dateStr);
  if(exc){
    if(exc.etat==='ferme') return [];                       // fermé : aucune plage
    return Array.isArray(exc.slots) ? exc.slots : [];       // full/custom : les plages de l'exception
  }
  const wk = availWeekType(dateStr, conf);
  const map = wk==='A' ? conf.weekA : conf.weekB;
  return (map[d.getDay()]||[]);
}
// Minutes disponibles un jour donné, en ne comptant que le temps APRÈS "fromMin"
// si c'est aujourd'hui (sinon toute la journée). limitMin borne la fin (date/heure de livraison).
function availMinutesOnDay(d, fromMin, untilMin, conf){
  const slots=availSlotsForDate(d, conf); let total=0;
  for(const [s,e] of slots){
    let a=hmToMin(s), b=hmToMin(e);
    if(fromMin!=null) a=Math.max(a, fromMin);
    if(untilMin!=null) b=Math.min(b, untilMin);
    if(b>a) total+=(b-a);
  }
  return total;
}
// Temps total disponible entre maintenant et une échéance (date + heure de livraison).
// Renvoie les minutes cumulées sur toutes les plages de travail d'ici là.
function availableMinutesUntil(deadlineDateStr, deadlineHM, conf){
  conf=conf||getAvailability();
  const now=new Date();
  // Par défaut, l'échéance = minuit (fin de la dernière plage de travail) ; on peut dépasser si besoin.
  const hm = (deadlineHM && /^\d/.test(deadlineHM)) ? deadlineHM : '23:59';
  const end=new Date(deadlineDateStr+'T'+hm);
  if(end<=now) return 0;
  let total=0;
  const cur=new Date(now); cur.setHours(0,0,0,0);
  const endDay=new Date(end); endDay.setHours(0,0,0,0);
  let guard=0;
  while(cur<=endDay && guard++<400){
    const isToday = cur.toDateString()===now.toDateString();
    const isEndDay = cur.toDateString()===end.toDateString();
    const fromMin = isToday ? (now.getHours()*60+now.getMinutes()) : null;
    const untilMin = isEndDay ? (end.getHours()*60+end.getMinutes()) : null;
    total += availMinutesOnDay(cur, fromMin, untilMin, conf);
    cur.setDate(cur.getDate()+1);
  }
  return total;
}

// TEMPS DE PRODUCTION nécessaire pour un ensemble de besoins {parfum: qte},
// en tenant compte du stock courant, avec la logique de mutualisation des meringues.
async function productionMinutesForNeeds(needs, opts){
  opts=opts||{};
  const ignoreStock = opts.ignoreStock===true;
  // [v1189 — SOURCE UNIQUE] La disponibilité par parfum vient de parfumDispoMap() (mobilisable = fini +
  // assemblable). Plus aucune notion de stock recalculée localement : cette fonction, le générateur, la
  // faisabilité et l'ordre du jour lisent TOUS la même source. La lecture par nom passe par parfumDispoDe
  // (normalisation centralisée).
  const times = getMrpTimes();
  let dispoMap = {};
  try{ dispoMap = await parfumDispoMap(); }catch(_){ dispoMap = {}; }
  let nbBatchsTotal=0, tGanache=0, tMontage=0; const manqueParfums=[];
  for(const parfum in needs){
    const besoin=+needs[parfum]||0; if(besoin<=0) continue;
    const enStock = ignoreStock ? 0 : parfumDispoDe(dispoMap, parfum);
    const net=Math.max(0, besoin-enStock);
    if(net<=0) continue;
    const nb=Math.ceil(net/TAILLE_BATCH_MACARONS);
    nbBatchsTotal+=nb;
    tGanache += nb*times.ganache.estimatedTime;
    tMontage += nb*times.montage.estimatedTime;
    manqueParfums.push({parfum, net});
  }
  const nbMeringues=Math.ceil(nbBatchsTotal/BATCHS_PAR_MERINGUE);
  const tMeringue=nbMeringues*times.coques.estimatedTime;
  return {minutes: tMeringue+tGanache+tMontage, nbBatchsTotal, nbMeringues, manqueParfums};
}

// VERDICT DE FAISABILITÉ d'une commande (date + heure + parfums demandés).
// Compare stock + temps disponible d'ici la livraison au temps de production requis.
async function assessOrderFeasibility(needs, deadlineDateStr, deadlineHM){
  const fmtH = m=>{ m=Math.round(+m||0); const h=Math.floor(m/60), mm=m%60; return `${h?h+'h':''}${h?String(mm).padStart(2,'0'):mm+' min'}`; };
  if(!deadlineDateStr) return {statut:'inconnu', msg:'Renseigne une date de livraison.'};
  const totalDem = Object.values(needs||{}).reduce((s,x)=>s+(+x||0),0);
  if(totalDem<=0) return {statut:'inconnu', msg:'Ajoute des parfums pour évaluer la faisabilité.'};
  const debut = (typeof today==='function') ? today().slice(0,10) : ymdLocal(new Date());
  if(deadlineDateStr < debut) return {statut:'ko', msg:'⛔ Date de livraison déjà passée.'};
  const conf = (typeof getAvailability==='function') ? getAvailability() : null;

  // [CONTEXTE RÉEL] On juge la commande DANS son environnement, pas isolée : le moteur de fenêtre agrège
  // TOUTES les commandes non livrées + marchés de [aujourd'hui → livraison], DÉDUIT le stock physique (ce
  // qui est déjà fait), puis ajoute CETTE commande (besoin additionnel fictif — rien n'est écrit en base).
  // C'est ce qui empêche le « OK au doigt mouillé » qui ignorait les autres échéances.
  let ctx=null;
  try{ ctx = await _faisabiliteFenetre(debut, deadlineDateStr, conf, needs); }catch(e){ console.error('assessFeas.ctx',e); }
  // ─────────────────────────────────────────────────────────────────────────────
  // [SÉQUENCE PHYSIQUE — délais incompressibles] Avoir assez de MINUTES d'atelier ne
  // suffit pas : certaines étapes ne se compressent pas dans le temps. Mais toutes les contraintes
  // n'ont pas le même statut :
  //   • DURES (techniques) : repos ganache, congélation crémeux → non négociables. Ganache lancée
  //     trop tard = ratée. Si le 1er travail du rétroplanning DUR tombe dans le passé → 🔴 impossible.
  //   • QUALITÉ (maturation) : un macaron non mûri reste vendable, juste moins abouti aromatiquement.
  //     Livrer sans maturation complète est un CHOIX légitime de Benjamin → jamais 🔴, au pire 🟡.
  // On calcule donc DEUX rétroplannings : "dur" (opts.ignorerMaturation) pour le blocage réel, et
  // "complet" (avec maturation) pour signaler une maturation qui ne pourra pas être respectée.
  // Multi-parfums : retroplanningDepuisParfums retient la contrainte la PLUS forte (parfum le plus exigeant).
  let seqBlocage=null;     // 🔴 blocage DUR (repos ganache/crémeux) : {premierJalon, retardMs, rp}
  let seqMaturation=null;  // 🟡 maturation non respectée mais production faisable : {manqueMs, rp}
  let parfumsAProduire=[]; // [v1186] parfums net-de-stock > 0 : la SEULE base légitime du rétroplanning
  const _detailStock=[];   // [v1186 diag] décision par parfum (besoin/dispo/net) — publié en fin de fonction
  try{
    // [v1186 — FIX incohérence compo/faisabilité] Le rétroplanning DUR (repos ganache, congélation
    // crémeux) ne doit porter QUE sur les parfums réellement À PRODUIRE. Un parfum déjà couvert par le
    // stock de PRODUIT FINI (prodVendable : complet/assemblé — donc ganache faite ET montée) n'impose
    // AUCUNE séquence de repos : sa ganache n'est pas à relancer. Sans ce filtre, la compo générée
    // depuis les stocks (parfums qu'on a déjà) déclenchait quand même un blocage « ganache aurait dû
    // démarrer hier » — d'où l'incohérence « compo appliquée OK mais bandeau 🔴 impossible ».
    // On déduit le stock parfum par parfum ; ne restent dans le rétroplanning que les net > 0.
    const parfumsNomsBruts = Object.keys(needs||{}).filter(n=>n && n!=='À définir' && (+needs[n]>0));
    let parfumsNoms = parfumsNomsBruts;
    try{
      // [v1189 — SOURCE UNIQUE] Disponibilité mobilisable via parfumDispoMap() : EXACTEMENT la même
      // source que le générateur de compo et le calcul des minutes. Un parfum dont la ganache existe
      // déjà (assemblable) est couvert → exclu du rétroplanning de repos ganache. Lecture par nom via
      // parfumDispoDe (normalisation centralisée).
      const dispoMap = await parfumDispoMap();
      parfumsNoms = parfumsNomsBruts.filter(n=>{
        const besoin=+needs[n]||0; const dispo=parfumDispoDe(dispoMap, n);
        const net = Math.max(0, besoin-dispo);
        // trace la décision par parfum (transparence : même stock que le générateur)
        _detailStock.push({parfum:n, besoin, dispoMobilisable:dispo, netAProduire:net, dansRetroplanning: net>0});
        return net > 0;   // ne garder que ce qu'il reste RÉELLEMENT à fabriquer
      });
    }catch(_){ /* si le stock est illisible, on retombe sur la liste brute (prudent) */ }
    parfumsAProduire = parfumsNoms;   // exposé au reste de la fonction (boucle « date au plus tôt »)
    if(parfumsNoms.length && typeof retroplanningDepuisParfums==='function'){
      const recettes = (typeof window!=='undefined' && window._allRecipesCache) ? window._allRecipesCache
                        : (typeof db!=='undefined' && db.recipes ? await db.recipes.toArray().catch(()=>[]) : []);
      const maintenant = new Date();
      const premierTravailDe = rp => (rp && !rp.error && Array.isArray(rp.jalons))
        ? rp.jalons.filter(j=>j.type==='travail').sort((a,b)=>a.date-b.date)[0] : null;

      // 1) Rétroplanning DUR (maturation neutralisée) → seul juge du 🔴.
      const rpDur = retroplanningDepuisParfums(deadlineDateStr, deadlineHM, parfumsNoms, recettes, {ignorerMaturation:true});
      const ptDur = premierTravailDe(rpDur);
      if(ptDur && ptDur.date < maintenant){
        seqBlocage = {premierJalon: ptDur, retardMs: maintenant - ptDur.date, rp: rpDur};
      } else {
        // 2) Pas de blocage dur → la production tient. Reste à voir si la MATURATION est respectée.
        //    On calcule le rétroplanning COMPLET : si son 1er travail est dans le passé alors que le
        //    dur ne l'était pas, c'est la maturation qui déborde → 🟡 (faisable, non optimisé).
        const rpFull = retroplanningDepuisParfums(deadlineDateStr, deadlineHM, parfumsNoms, recettes);
        const ptFull = premierTravailDe(rpFull);
        if(ptFull && ptFull.date < maintenant && rpFull.maturationH>0){
          seqMaturation = {manqueMs: maintenant - ptFull.date, rp: rpFull, maturationH: rpFull.maturationH};
        }
      }
    }
  }catch(e){ console.error('assessFeas.seq',e); }


  // Contribution propre de cette commande (temps de prod net du stock) + batchs, pour le détail.
  let prodThis={minutes:0,nbBatchsTotal:0,nbMeringues:0};
  try{ prodThis = await productionMinutesForNeeds(needs); }catch(e){swallow(e,'assessOrderFeasibility')}

  // [v1186 — TRANSPARENCE anti-divergence] Publie, pour CETTE commande, la décision stock par parfum :
  // besoin, dispo MOBILISABLE (fini + assemblable = EXACTEMENT la notion du générateur de compo), net à
  // produire, et si le parfum est entré dans le rétroplanning de repos ganache. But : pouvoir vérifier en
  // réel que le générateur et la faisabilité voient le MÊME stock. À désactiver une fois validé sur iPhone.
  try{
    if(typeof diagPublish==='function'){
      const lignes = _detailStock.map(d=>`${d.parfum} : besoin ${d.besoin} · dispo ${d.dispoMobilisable} · à produire ${d.netAProduire}${d.dansRetroplanning?' · ⏱ repos ganache pris en compte':' · ✅ couvert par le stock (aucun repos)'}`);
      diagPublish('faisabiliteStockParfum', '🍬 Faisabilité — stock vu par parfum (= vision générateur)', {
        'Livraison': (typeof fmtDate==='function'?fmtDate(deadlineDateStr):deadlineDateStr)+(deadlineHM?(' '+deadlineHM):''),
        'Source stock': 'stockMobilisableParParfum (fini + assemblable) — IDENTIQUE au générateur de compo',
        'Décision par parfum': lignes.length ? lignes : 'aucun parfum',
        'Parfums entrés au rétroplanning': parfumsAProduire.length ? parfumsAProduire.join(', ') : 'aucun (tout est couvert par le stock)',
        'Batchs à produire': (prodThis&&prodThis.nbBatchsTotal)||0,
        'Minutes de production': (prodThis&&prodThis.minutes)||0,
        'Lecture': 'Si un parfum est « couvert par le stock » ici, le générateur le propose SANS relance et la faisabilité ne doit PAS exiger de repos ganache pour lui. Les deux visions partagent cette même source.'
      });
    }
  }catch(e){swallow(e,'assessOrderFeasibility')}

  // Repli : moteur de fenêtre indisponible → ancien calcul isolé (mieux que rien).
  if(!ctx){
    // La séquence physique prime même en repli : une ganache lancée trop tard reste infaisable.
    if(seqBlocage){
      const jal=seqBlocage.premierJalon;
      const etape=(jal.label||'préparation').replace(/\s*\(.*\)$/,'').toLowerCase();
      const quand=jal.date.toLocaleString('fr-FR',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
      return {statut:'ko', stockSuffit:false, seqBlocage:true,
        msg:`⛔ Impossible pour le ${(typeof fmtDate==='function')?fmtDate(deadlineDateStr):deadlineDateStr}${deadlineHM?' à '+deadlineHM:''} : la ${etape} aurait dû démarrer avant maintenant pour respecter les temps de repos.`};
    }
    const dispoIso = availableMinutesUntil(deadlineDateStr, deadlineHM);
    const bmin = prodThis.minutes||0;
    if(bmin<=0) return {statut:'ok', stockSuffit:true, besoinMin:0, dispoMin:dispoIso, msg:'✅ Stock suffisant : aucune production nécessaire.'};
    const marge=dispoIso-bmin, statut = dispoIso<=0?'inconnu' : marge<0?'ko' : (bmin/dispoIso>0.8?'tendu':'ok');
    return {statut, stockSuffit:false, besoinMin:bmin, dispoMin:dispoIso,
      nbBatchs:prodThis.nbBatchsTotal, nbMeringues:prodThis.nbMeringues,
      msg: statut==='inconnu' ? 'Renseigne tes disponibilités pour trancher.' :
           statut==='ko' ? `⛔ ${fmtH(bmin)} à produire pour ${fmtH(dispoIso)} dispo — il manque ${fmtH(-marge)}.` :
           statut==='tendu' ? `⚠ Tendu : ${fmtH(bmin)} sur ${fmtH(dispoIso)} dispo.` :
           `✅ Réalisable : ${fmtH(bmin)} à produire, ${fmtH(dispoIso)} dispo.`};
  }

  const dispo = ctx.tempsDispo||0;
  const besoinTot = ctx.tempsTotal||0;                 // TOUT ce qu'il faut produire d'ici la livraison
  const surcout = Math.max(0, prodThis.minutes||0);    // ≈ ce que cette commande ajoute
  const dateFr = (typeof fmtDate==='function') ? fmtDate(deadlineDateStr) : deadlineDateStr;

  if(dispo<=0){
    return {statut:'inconnu', stockSuffit:false, besoinMin:besoinTot, dispoMin:0,
      nbBatchs:prodThis.nbBatchsTotal, nbMeringues:prodThis.nbMeringues,
      msg:`Renseigne tes disponibilités pour trancher (charge totale d'ici le ${dateFr} : ${fmtH(besoinTot)}).`};
  }
  if(besoinTot<=0){
    return {statut:'ok', stockSuffit:true, besoinMin:0, dispoMin:dispo,
      msg:`✅ Réalisable pour le ${dateFr} : le stock couvre déjà tout, rien à produire.`};
  }

  let statut;
  if(seqBlocage) statut='ko';                 // blocage technique dur (repos ganache/crémeux) → prime sur tout
  else if(ctx.depassement) statut='ko';
  else if(ctx.chargePct>80) statut='tendu';
  else statut='ok';
  // Maturation non respectée : jamais bloquant, mais dégrade 🟢 en 🟡 (faisable, pas optimisé).
  if(!seqBlocage && seqMaturation && statut==='ok') statut='tendu';

  // Formatage d'un délai en langage courant (« 5 h », « 1 j 3 h ») pour expliquer le retard de séquence.
  const fmtDelai = ms=>{
    const h=Math.round(ms/3600000);
    if(h<24) return h<=1?'moins d\u2019une heure':(h+' h');
    const j=Math.floor(h/24), r=h%24;
    return j+' j'+(r?(' '+r+' h'):'');
  };

  // [DATE AU PLUS TÔT] Si infaisable (blocage dur OU charge), on cherche la 1re date de livraison
  // (jusqu'à +10 j) où ça passe. Critère séquence = rétroplanning DUR (maturation ignorée) : on cherche
  // la 1re date PRODUCTIBLE, pas la 1re date parfaitement mûrie (la maturation ne bloque jamais).
  let earliest=null;
  if(statut==='ko'){
    // [v1186] même base que le rétroplanning principal : uniquement les parfums réellement à produire.
    const parfumsNomsE = parfumsAProduire;
    const recettesE = (typeof window!=='undefined' && window._allRecipesCache) ? window._allRecipesCache : [];
    const d0=new Date(deadlineDateStr+'T00:00:00');
    for(let k=1;k<=10;k++){
      d0.setDate(d0.getDate()+1);
      const ds=d0.getFullYear()+'-'+String(d0.getMonth()+1).padStart(2,'0')+'-'+String(d0.getDate()).padStart(2,'0');
      let f; try{ f=await _faisabiliteFenetre(debut, ds, conf, needs); }catch(_){ f=null; }
      const chargeOk = f && f.tempsDispo>0 && !f.depassement;
      let seqOk=true;
      if(parfumsNomsE.length && typeof retroplanningDepuisParfums==='function'){
        try{
          const rpE=retroplanningDepuisParfums(ds, deadlineHM, parfumsNomsE, recettesE, {ignorerMaturation:true});
          if(rpE && !rpE.error && Array.isArray(rpE.jalons)){
            const pt=rpE.jalons.filter(j=>j.type==='travail').sort((a,b)=>a.date-b.date)[0];
            seqOk = !(pt && pt.date < new Date());
          }
        }catch(e){swallow(e,'assessOrderFeasibility')}
      }
      if(chargeOk && seqOk){ earliest=ds; break; }
    }
  }

  const ajout = surcout>0 ? ` Cette commande ≈ +${fmtH(surcout)}.` : '';
  const earlyTxt = earliest ? ` ✅ Au plus tôt réalisable : ${(typeof fmtDate==='function')?fmtDate(earliest):earliest}.` : '';
  // Note maturation à accoler quand la prod est faisable mais la maturation incomplète.
  const matTxt = seqMaturation
    ? ` ⏳ Maturation optimale de ${seqMaturation.maturationH} h non tenue (manque ${fmtDelai(seqMaturation.manqueMs)}) : les macarons seront bons mais pas à leur apogée aromatique.`
    : '';
  let msg;
  if(seqBlocage){
    // Blocage technique dur : on nomme l'étape bloquante (ganache, crémeux) et le retard.
    const jal = seqBlocage.premierJalon;
    const etape = (jal.label||'préparation').replace(/\s*\(.*\)$/,'').toLowerCase();
    const quand = jal.date.toLocaleString('fr-FR',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
    msg=`⛔ Impossible pour le ${dateFr}${deadlineHM?' à '+deadlineHM:''} : la ${etape} aurait dû commencer le ${quand} (il y a ${fmtDelai(seqBlocage.retardMs)}). Le repos avant montage ne peut pas être raccourci.${earlyTxt}`;
  }
  else if(statut==='ok')
    msg=`✅ Réalisable pour le ${dateFr} : ${fmtH(besoinTot)} à produire d'ici là sur ${fmtH(dispo)} dispo (${ctx.chargePct}%).${ajout}`;
  else if(statut==='tendu' && seqMaturation && !ctx.depassement && ctx.chargePct<=80)
    // 🟡 dû UNIQUEMENT à la maturation (la charge, elle, passe) : message centré qualité.
    msg=`🟡 Faisable pour le ${dateFr} mais pas optimisé :${matTxt}${ajout}`;
  else if(statut==='tendu')
    msg=`⚠ Tendu pour le ${dateFr} : ${fmtH(besoinTot)} / ${fmtH(dispo)} dispo (${ctx.chargePct}%), marge faible.${ajout}${matTxt}`;
  else
    msg=`⛔ Infaisable pour le ${dateFr} : ${fmtH(besoinTot)} à produire d'ici là pour ${fmtH(dispo)} dispo — il manque ${fmtH(ctx.debordementMin)} (autres commandes déjà prévues comprises).${earlyTxt}`;

  return {statut, stockSuffit:false, besoinMin:besoinTot, dispoMin:dispo, surcoutMin:surcout,
    chargePct:ctx.chargePct, earliest, seqBlocage:!!seqBlocage, seqMaturation:!!seqMaturation,
    nbBatchs:prodThis.nbBatchsTotal, nbMeringues:prodThis.nbMeringues, msg};
}

/* ============================================================
   RÉTROPLANNING D'UNE COMMANDE (v1 : jalons datés à rebours)
   Part de la date/heure de livraison et remonte en tenant compte
   des délais incompressibles : maturation, repos ganache.
   Les heures de travail précises (imbrication dans les dispos)
   seront raffinées dans une version ultérieure.
   ============================================================ */
// Renvoie { livraison:Date, jalons:[{cle, label, date:Date, type:'travail'|'attente', note}], contraintes:[...] }
// [CŒUR DE CALAGE NEUTRE] Calcule le rétroplanning à partir de données BRUTES (date, heure, parfums),
// sans objet commande. Appelé aussi bien par les commandes (retroplanningCommande, qui extrait ces
// données de l'objet o) que par les MARCHÉS (qui n'ont pas de commande). Aucun « pseudo-objet » :
// un marché reste un marché, une commande reste une commande ; seules les 3 données utiles transitent.
//   dateLiv       : 'YYYY-MM-DD' (date de remise / de vente)
//   hmRaw         : 'HH:MM' (heure de remise) ou null → défaut 10:00
//   parfumsNoms   : [string] noms de parfums concernés (pour retrouver les recettes → contraintes)
//   recipes       : db.recipes (déjà chargé)
// Renvoie le MÊME format que l'ancien retroplanningCommande.
function retroplanningDepuisParfums(dateLiv, hmRaw, parfumsNoms, recipes, opts){
  opts = opts || {};
  recipes = recipes || window._allRecipesCache || [];
  const recByNom = {};
  recipes.forEach(r=>{ recByNom[aiNormalize ? aiNormalize(r.produitNom) : (r.produitNom||'').toLowerCase()] = r; });
  const normNom = n => aiNormalize ? aiNormalize(n) : (n||'').toLowerCase();

  // 1) Date + heure de livraison.
  if(!dateLiv) return {error:'Aucune date de livraison.'};
  // [FIX point 3 — racine] Sans parfum, il n'y a rien à produire : caler un planning sur du vide
  // produit un déroulé fantôme (ganache « À définir », ordre incohérent). On bloque ici, ce qui
  // protège d'un coup TOUS les appelants (rétroplanning réel, simulation, mutualisation).
  if(!(parfumsNoms||[]).length){ return {error:'Aucun parfum sélectionné : rien à produire, donc pas de rétroplanning.'}; }
  const hm = (hmRaw && /^\d{1,2}:\d{2}/.test(hmRaw)) ? hmRaw : '10:00';
  const hmFull = (hm.length===4?'0'+hm:hm).slice(0,5);   // garantit 'HH:MM'
  const _dp = dateLiv.split('-').map(Number);
  const _tp = hmFull.split(':').map(Number);
  const livraison = new Date(_dp[0], (_dp[1]||1)-1, _dp[2]||1, _tp[0]||0, _tp[1]||0, 0, 0);

  // 2) Recettes impliquées → contraintes (repos ganache max, jour J, congélation, maturation).
  const recsUtilisees = [];
  (parfumsNoms||[]).forEach(nom=>{ const r=recByNom[normNom(nom)]; if(r && !recsUtilisees.includes(r)) recsUtilisees.push(r); });
  // Contraintes agrégées (on prend la plus forte).
  let reposGanacheH = 0, jourJ = false, congelObl = false, maturationRequise = true, aCremeux = false, gfCongele = false, aStandard = false;
  // [MATURATION PAR RECETTE] On retient la maturation la PLUS LONGUE parmi les parfums de la commande
  // (le macaron le plus exigeant impose le repos : on ne peut pas livrer avant que tous aient maturé).
  // Une recette sans réglage (maturationH==null) hérite du défaut global PROC.maturationH ; une recette
  // qui fixe une valeur (même 0) la surcharge. matParRecetteVue = true dès qu'au moins une recette a un réglage.
  const DEFAUT_MATURATION_H = (typeof PROC!=='undefined' && PROC.maturationH!=null) ? PROC.maturationH : 24;
  let maturationParfumMaxH = null;   // null tant qu'aucune recette n'a parlé
  recsUtilisees.forEach(r=>{
    const dg = (r.ganacheDelaiH!=null) ? +r.ganacheDelaiH : 12;
    if(dg>reposGanacheH) reposGanacheH = dg;
    if(r.jourJUniquement) jourJ = true;
    if(r.congelObligatoire) congelObl = true;
    // Maturation propre à la recette (surcharge le défaut) ; sinon le défaut global s'applique.
    const matR = (r.maturationH!=null) ? Math.max(0, +r.maturationH) : DEFAUT_MATURATION_H;
    if(maturationParfumMaxH==null || matR>maturationParfumMaxH) maturationParfumMaxH = matR;
    // Macaron STANDARD (≠ grand format) : ses coques doivent être faites le JOUR du montage
    // (règle métier : coques fraîches le jour de l'assemblage). Les grands formats sont exclus.
    if(!r.grandFormat) aStandard = true;
    // Convention de l'app : une recette grand format utilise un CRÉMEUX (cf. garniture GF).
    if(r.grandFormat) aCremeux = true;
    // Grand format CONGELÉ (congélation obligatoire des coques ou de la recette) → décongélation
    // au frigo avant service. On ne l'applique que si la recette impose effectivement le congélateur.
    if(r.grandFormat && (r.congelObligatoire || r.coquesCongelObligatoire)) gfCongele = true;
  });
  // [FIX point 3 — repos par défaut] reposGanacheH démarre à 0 et n'est relevé que par les recettes
  // TROUVÉES. Si un (ou tous les) parfum(s) n'a pas de recette correspondante, aucun repos n'était
  // appliqué → la ganache se calait à montage−0 (même créneau que les coques) et pouvait apparaître
  // APRÈS elles : ordre métier cassé. Sécurité : si on a des parfums à produire mais qu'AUCUNE recette
  // n'a été trouvée (recsUtilisees vide), on applique le repos standard de 12 h — une ganache a
  // toujours besoin de reposer. On ne touche PAS au cas où une recette fixe explicitement un délai 0
  // (choix volontaire respecté), seulement au cas « recette manquante ».
  const REPOS_GANACHE_DEFAUT = (typeof PROC!=='undefined' && PROC.reposGanacheDefautH!=null) ? PROC.reposGanacheDefautH : 12;
  if(reposGanacheH===0 && recsUtilisees.length===0 && (parfumsNoms||[]).length>0){
    reposGanacheH = REPOS_GANACHE_DEFAUT;
  }
  // Congélation du crémeux avant montage (règle générale : 6 h). 0 si pas de crémeux.
  const cremeuxCongelH = aCremeux ? (typeof PROC!=='undefined' ? (PROC.cremeuxCongelH||6) : 6) : 0;
  // Décongélation au frigo avant service (2 h) : seulement si le grand format a été congelé.
  // Jour J = pas de congélation/avance, donc pas de décongélation à prévoir.
  const decongelH = (gfCongele && !jourJ) ? (typeof PROC!=='undefined' ? (PROC.decongelFrigoH||2) : 2) : 0;
  // Jour J : pas de maturation longue ni d'avance (tout le jour même).
  // [MATURATION NON BLOQUANTE] La maturation est une contrainte de QUALITÉ (arômes), pas une contrainte
  // technique dure comme le repos ganache. Un macaron non mûri reste vendable. Le verdict de faisabilité
  // demande donc un rétroplanning "dur" (opts.ignorerMaturation) où la maturation vaut 0 : ça isole les
  // vrais blocages (repos ganache, congélation crémeux) des simples pertes d'optimum aromatique.
  const maturationH = (jourJ || opts.ignorerMaturation) ? 0 : ((maturationParfumMaxH!=null) ? maturationParfumMaxH : DEFAUT_MATURATION_H);

  // 3) Remontée à rebours.
  const jalons = [];
  const minus = (base, hours) => { const d=new Date(base); d.setHours(d.getHours()-hours); return d; };

  // Prêt à livrer = livraison.
  jalons.push({cle:'livraison', label:'Livraison', date:new Date(livraison), type:'jalon', note:'Date/heure de remise au client.'});

  // [DÉCONGÉLATION] Grand format congelé : le sortir au frigo 2 h avant le service.
  // « Sortie congélateur » = livraison − 2 h ; c'est le nouveau point de référence amont.
  let refApresFroid = new Date(livraison);
  if(decongelH>0){
    refApresFroid = minus(livraison, decongelH);
    jalons.push({cle:'decongel', label:`Décongélation au frigo (${decongelH} h)`, date:new Date(refApresFroid), type:'attente',
      note:`Sors le grand format du congélateur et place-le au frigo ${decongelH} h avant de le servir.`});
  }

  // Fin de maturation = sortie du froid avant service ; fin du montage = ce point − maturation.
  const finMontage = minus(refApresFroid, maturationH);
  if(maturationH>0){
    jalons.push({cle:'maturation', label:`Maturation (${maturationH} h au frais)`, date:new Date(finMontage), type:'attente',
      note:`Repos au froid pour développer les arômes. Le montage doit être fini à cette date.`});
  }

  // Montage/assemblage : à finir pour finMontage. (durée de travail raffinée plus tard)
  jalons.push({cle:'montage', label:'Montage / assemblage', date:new Date(finMontage), type:'travail',
    note:'Garnir les coques. À terminer avant le début de la maturation.'});

  // Ganache prête = au plus tard au début du montage. Début ganache = ganache prête − repos.
  const ganachePrete = new Date(finMontage); // simplification v1 : montage commence quand ganache prête
  const debutGanache = minus(ganachePrete, reposGanacheH);
  if(reposGanacheH>0){
    jalons.push({cle:'repos-ganache', label:`Repos ganache (${reposGanacheH} h)`, date:new Date(debutGanache), type:'attente',
      note:`La ganache doit reposer ${reposGanacheH} h avant le montage. À préparer pour cette date.`});
  }
  jalons.push({cle:'ganache', label:'Préparation ganache / crémeux', date:new Date(debutGanache), type:'travail',
    note:'Cuire et couler la ganache, puis la laisser reposer.'});

  // [CRÉMEUX] Si la commande contient un grand format (→ crémeux), il doit passer au congélateur
  // 6 h avant le montage. Préparation crémeux → 6 h congélateur → montage.
  if(cremeuxCongelH>0){
    const cremeuxPret = new Date(finMontage);                 // dispo au montage
    const debutCremeux = minus(cremeuxPret, cremeuxCongelH);   // préparé 6 h avant
    jalons.push({cle:'congel-cremeux', label:`Congélation crémeux (${cremeuxCongelH} h)`, date:new Date(debutCremeux), type:'attente',
      note:`Le crémeux doit passer ${cremeuxCongelH} h au congélateur avant le montage. À préparer pour cette date.`});
    jalons.push({cle:'cremeux', label:'Préparation du crémeux', date:new Date(debutCremeux), type:'travail',
      note:'Préparer le crémeux du grand format, puis le placer au congélateur.'});
  }

  // Coques : avant le montage.
  // RÈGLE MÉTIER (macarons standard) : les coques se font le JOUR du montage — pivot = montage,
  // PAS la livraison (le montage peut être la veille de la livraison à cause de la maturation).
  // On les cale donc le même jour calendaire que finMontage, le matin (8h par défaut), et jamais
  // après le début du montage (si le montage est avant 8h, on place les coques juste avant).
  // Les GRANDS FORMATS sont exclus : ils gardent la possibilité de coques congelées en amont.
  // L'usage de coques congelées d'un ancien batch reste une EXCEPTION ponctuelle à l'assemblage,
  // non planifiée ici.
  let coquesAvant;
  if(aStandard){
    const COQUES_HEURE_MATIN = (typeof PROC!=='undefined' && PROC.coquesHeureMatin!=null) ? PROC.coquesHeureMatin : 8;
    const jourMontage = new Date(finMontage);
    jourMontage.setHours(COQUES_HEURE_MATIN, 0, 0, 0);   // même jour que le montage, à 8h
    // Si le montage est calé plus tôt que 8h ce jour-là, on place les coques juste avant le montage.
    coquesAvant = (jourMontage <= finMontage) ? jourMontage : minus(finMontage, 2);
  } else {
    coquesAvant = minus(finMontage, 2); // grand format uniquement : comportement existant
  }
  jalons.push({cle:'coques', label:'Coques (meringue + cuisson)', date:new Date(coquesAvant), type:'travail',
    note: aStandard ? 'Coques à réaliser le jour même du montage (coques fraîches — règle macaron standard). Exception : des coques d\'un ancien batch peuvent venir du congélateur pour l\'assemblage.' : (congelObl ? 'Coques cuites puis congelées (obligatoire pour cette recette).' : 'Coques cuites, prêtes pour le montage. Peuvent être faites en avance.')});

  // Tri chronologique (du plus tôt au plus tard) pour l'affichage.
  jalons.sort((a,b)=> a.date - b.date);

  const contraintes = [];
  if(jourJ) contraintes.push('📅 Jour J : à produire le jour même (pas d\'avance ni maturation longue).');
  if(congelObl) contraintes.push('❄️ Congélation obligatoire des coques.');
  if(cremeuxCongelH>0) contraintes.push(`🧊 Congélation crémeux : ${cremeuxCongelH} h avant le montage.`);
  if(decongelH>0) contraintes.push(`🌡 Décongélation : ${decongelH} h au frigo avant le service (grand format congelé).`);
  if(reposGanacheH>0) contraintes.push(`⏱ Repos ganache : ${reposGanacheH} h.`);
  if(maturationH>0) contraintes.push(`🧊 Maturation : ${maturationH} h avant livraison.`);
  if(aStandard) contraintes.push('🍪 Coques le jour du montage (coques fraîches — macaron standard).');

  return {livraison, jalons, contraintes, reposGanacheH, maturationH, cremeuxCongelH, decongelH, jourJ, congelObl, aCremeux, gfCongele, aStandard, recsUtilisees:recsUtilisees.length};
}

// [COMMANDE] Rétroplanning d'une vraie commande : extrait (date, heure, parfums) de l'objet o et
// délègue au cœur neutre. Comportement IDENTIQUE à l'ancienne version (régression nulle).
function retroplanningCommande(o, recipes){
  const dateLiv = o.dateEvenement || o.date || '';
  if(!dateLiv) return {error:'Aucune date de livraison sur cette commande.'};
  // Parfums concernés, extraits des lignes de la commande (grand format → items, sinon parfums).
  const lignes = (typeof orderToLines==='function') ? orderToLines(o) : [];
  const parfumsNoms = [];
  lignes.forEach(ln=>{
    const parfums = ln.type==='grand' ? (ln.items||[]) : (ln.parfums||[]);
    parfums.forEach(p=>{ if(p && p.nom) parfumsNoms.push(p.nom); });
  });
  return retroplanningDepuisParfums(dateLiv, o.heureLivraison, parfumsNoms, recipes);
}

/* [CHANTIER 1] COUCHE DE CALAGE du rétroplanning sur les plages de disponibilité.
   N'altère PAS retroplanningCommande : on récupère ses paramètres et on RECONSTRUIT
   la cascade à rebours en calant chaque étape selon son type (3 types), en lisant les
   vraies plages (exceptions comprises via availSlotsForDate).
   - active   : montage, ganache, crémeux → tient d'un seul tenant dans un créneau.
   - encadree : coques (meringue + cuisson) → présence début+fin, idem active.
   - libre    : repos, maturation, congélation, décongélation → traverse nuit & week-end.
   Durées actives/encadrées = temps MRP × volume ; durées libres = constantes (heures).
*/

// [EXTRACTEUR NEUTRE] Réduit une commande (ou tout objet à lignes) à la liste [{nom, qte}] des
// parfums, seule donnée dont les calculs de durée du rétroplanning ont besoin. Pour les MARCHÉS,
// on passe directement la liste ventilée sans construire d'objet commande (cf. retroplanningCaleParfums).
function _parfumsQtesDeLignes(lignes){
  const out = [];
  (lignes||[]).forEach(ln=>{
    const arr = (ln.type==='grand') ? (ln.items||[]) : (ln.parfums||[]);
    arr.forEach(p=>{ if(p && p.nom && +p.qte>0) out.push({nom:p.nom, qte:+p.qte}); });
    // [FIX invisibilité] Les macarons « sans parfum » comptent dans la PRODUCTION (volume, temps,
    // rétroplanning) au même titre que les autres — sinon une commande 100 % « à définir » pèse 0
    // macaron et devient muette dans Production. On les agrège sous « À définir » (même convention
    // que _orderParfumDemand). Ils seront remplacés par de vrais parfums au moment du figeage.
    if(+ln.sansParfum>0) out.push({ nom:'À définir', qte:+ln.sansParfum });
  });
  return out;
}
function _parfumsQtesDe(o){
  const lignes = (typeof orderToLines==='function') ? orderToLines(o) : [];
  return _parfumsQtesDeLignes(lignes);
}
// [SUGGESTION PARFUMS] Total des macarons « sans parfum » d'une commande (toutes lignes coffret),
// et la taille de coffret de référence (pour le plafond de parfums). On prend la plus grande ligne
// coffret comme référence de format si plusieurs.
function _sansParfumTotalDe(o){
  const lignes = (typeof orderToLines==='function') ? orderToLines(o) : [];
  let total = 0, taille = 0;
  (lignes||[]).forEach(ln=>{
    if(ln.type==='coffret'){
      const sp = +ln.sansParfum||0;
      if(sp>0){ total += sp; if((+ln.taille||0)>taille) taille = +ln.taille||0; }
    }
    // [v1452] Un sachet peut lui aussi porter des macarons « sans parfum » : sans ça, ils ne
    // seraient jamais proposés à la détermination au lancement de production. Il n'a pas de
    // « taille de coffret » — il ne fixe donc pas la référence de format, il alimente le total.
    else if(ln.type==='sachet'){ total += (+ln.sansParfum||0); }
  });
  return { total, taille: taille||25 };
}

// nbMacarons depuis une liste neutre [{nom,qte}].
function _retroNbMacaronsDe(parfumsQtes){
  let n=0; (parfumsQtes||[]).forEach(p=>{ n+=(+p.qte||0); }); return n;
}

// [GANACHE PAR PARFUM — durée juste] La ganache se fait UNE FOIS PAR PARFUM (temps fixe par parfum),
// PAS par batch de 60. _retroDurees faisait \u00ab 12 min \u00d7 nbBatchs \u00bb, ce qui sous-estimait
// fortement une commande multi-parfums (ex. 6 parfums = 6 ganaches, pas 2 batchs). On somme donc le
// temps ganache de CHAQUE parfum distinct, avec la MÊME règle de source que le plan opérationnel
// (mesuré fiable > recette > défaut) — source unique, donc rétroplanning et plan concordent.
// Retourne { totalMin, nbParfums } ; totalMin déjà multiplié par le facteur de cadence.
function _retroGanacheTotalMinDe(parfumsQtes, recipes, tEtape, facteur){
  const t = (typeof getMrpTimes==='function') ? getMrpTimes() : {ganache:{estimatedTime:12}};
  const defMin = t.ganache.estimatedTime;
  const f = (typeof facteur==='number' && isFinite(facteur) && facteur>0) ? facteur : 1;
  const norm = nom => (typeof aiNormalize==='function') ? aiNormalize(nom||'') : String(nom||'').toLowerCase().trim();
  // Parfums DISTINCTS, clé normalisée.
  const parfums = new Set();
  (parfumsQtes||[]).forEach(pp=>{ if(+pp.qte>0){ const k=norm(pp.nom); if(k) parfums.add(k); } });
  if(!parfums.size) return { totalMin: defMin*f, nbParfums: 1 };
  const recByNomK = {};
  (recipes||[]).forEach(r=>{ recByNomK[norm(r.produitNom||'')] = r; });
  let total = 0;
  parfums.forEach(k=>{
    const mes = tEtape && tEtape.ganache && tEtape.ganache[k];
    if(mes && mes.fiable && mes.nbMac>0){ total += (mes.minTotal/(mes.nbSessions||1)); return; }
    const r = recByNomK[k];
    if(r && r.tempsGanacheMin!=null && +r.tempsGanacheMin>0){ total += (+r.tempsGanacheMin); return; }
    total += defMin;
  });
  return { totalMin: total*f, nbParfums: parfums.size };
}

// [MONTAGE PAR PARFUM — durée juste] Le montage se fait PARFUM PAR PARFUM, et chaque parfum mobilise
// au moins un batch entamé (un batch commencé = un batch travaillé). _retroDurees faisait
// \u00ab 15 \u00d7 ceil(nbMacTotal/60) \u00bb (batchs GLOBAUX), ce qui sous-estimait : 6 parfums de 14 mac
// donnaient 2 batchs au lieu de 6. On somme donc, par parfum distinct, perBatch \u00d7 ceil(qte/60),
// avec la MÊME règle de source que le plan (mesuré fiable > recette > défaut). Source unique.
// Retourne { totalMin } ; déjà multiplié par le facteur de cadence.
function _retroMontageTotalMinDe(parfumsQtes, recipes, tEtape, facteur){
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const t = (typeof getMrpTimes==='function') ? getMrpTimes() : {montage:{estimatedTime:15}};
  const defPerBatch = t.montage.estimatedTime;
  const f = (typeof facteur==='number' && isFinite(facteur) && facteur>0) ? facteur : 1;
  const norm = nom => (typeof aiNormalize==='function') ? aiNormalize(nom||'') : String(nom||'').toLowerCase().trim();
  // Quantité par parfum distinct.
  const qParNom = {};
  (parfumsQtes||[]).forEach(pp=>{ if(+pp.qte>0){ const k=norm(pp.nom); if(k) qParNom[k]=(qParNom[k]||0)+(+pp.qte); } });
  const noms = Object.keys(qParNom);
  if(!noms.length){ // repli : prorata global
    const nb = Math.max(1, Math.ceil(_retroNbMacaronsDe(parfumsQtes)/TB));
    return { totalMin: defPerBatch*nb*f };
  }
  const recByNomK = {};
  (recipes||[]).forEach(r=>{ recByNomK[norm(r.produitNom||'')] = r; });
  let total = 0;
  noms.forEach(k=>{
    // [MODÈLE FIXE+VARIABLE] Même calcul que le plan opérationnel (_montageMinutes) pour des horaires
    // cohérents : part fixe par batch + part variable par macaron. Détermine la source du perBatch.
    const mes = tEtape && tEtape.montage && tEtape.montage[k];
    let perBatch, source;
    if(mes && mes.fiable && mes.nbMac>0){ perBatch = mes.minTotal/mes.nbMac*TB; source='mesuré'; }
    else { const r = recByNomK[k]; if(r && r.tempsMontageMin!=null && +r.tempsMontageMin>0){ perBatch=+r.tempsMontageMin; source='recette'; } else { perBatch=defPerBatch; source='défaut'; } }
    total += (typeof _montageMinutes==='function') ? _montageMinutes(qParNom[k], perBatch, source) : perBatch*Math.max(1, Math.ceil(qParNom[k]/TB));
  });
  return { totalMin: total*f };
}

function _retroDurees(nbMacarons, facteurCadence, ganacheTotalMin, montageTotalMin){
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const MM = (typeof MACARONS_PAR_MERINGUE!=='undefined') ? MACARONS_PAR_MERINGUE : 120;
  const t = (typeof getMrpTimes==='function') ? getMrpTimes() : {coques:{estimatedTime:35},montage:{estimatedTime:15},ganache:{estimatedTime:12}};
  const nbBatchs = Math.max(1, Math.ceil(nbMacarons/TB));
  const nbMeringues = Math.max(1, Math.ceil(nbMacarons/MM));
  // [TEMPS MESURES PAR PARFUM] facteurCadence = ratio cadence reelle mesuree / cadence theorique,
  // borne et pondere par parfum (voir _retroFacteurCadence). Defaut 1 => comportement identique
  // (aucune regression quand aucune mesure fiable n'existe).
  const f = (typeof facteurCadence==='number' && isFinite(facteurCadence) && facteurCadence>0) ? facteurCadence : 1;
  // [GANACHE PAR PARFUM] Si on fournit ganacheTotalMin (somme des temps ganache par parfum distinct),
  // on l'utilise pour la ganache/crémeux au lieu de \u00ab 12 \u00d7 nbBatchs \u00bb (qui sous-estime). Le
  // facteur de cadence est déjà appliqué dans ganacheTotalMin, donc on ne le remultiplie pas ici.
  // Défaut (non fourni) : ancien calcul, pour ne rien casser ailleurs.
  const ganacheMin = (typeof ganacheTotalMin==='number' && isFinite(ganacheTotalMin) && ganacheTotalMin>0)
    ? ganacheTotalMin
    : t.ganache.estimatedTime * nbBatchs * f;
  // [MONTAGE PAR PARFUM] idem : si montageTotalMin fourni (somme par parfum, ceil par batch), on l'utilise.
  const montageMin = (typeof montageTotalMin==='number' && isFinite(montageTotalMin) && montageTotalMin>0)
    ? montageTotalMin
    : t.montage.estimatedTime * nbBatchs * f;
  return {
    coques: t.coques.estimatedTime * nbMeringues * f,
    montage: montageMin,
    ganache: ganacheMin,
    cremeux: ganacheMin,
    nbBatchs, nbMeringues, facteurCadence: f
  };
}

// [TEMPS MESURES PAR PARFUM -> RETROPLANNING] Calcule un facteur d'ajustement de cadence pour une
// commande, a partir des temps REELS chronometres a l'atelier (prodTempsParParfumParNom).
// Principe (Option A) : la mesure par parfum donne un temps GLOBAL par macaron, pas par etape ;
// on s'en sert donc comme FACTEUR multiplicatif applique aux 3 durees d'etape, plutot que de
// remplacer une etape precise (qu'on ne mesure pas separement).
//   facteur d'un parfum = minParMac mesure / minParMac theorique, uniquement si la mesure est FIABLE,
//   borne dans [0.5, 2.5] pour qu'une mesure aberrante ne casse jamais le planning.
//   facteur de la commande = MOYENNE PONDEREE par les quantites de chaque parfum
//   (un parfum sans mesure fiable compte avec un facteur 1 = cadence theorique).
// Renvoie 1 si rien de fiable => zero regression.
async function _retroFacteurCadenceDe(parfumsQtes, recipes){
  try{
    if(typeof prodTempsParParfumParNom!=='function' || typeof getMrpTimes!=='function') return 1;
    const _k = nom => (typeof aiNormalize==='function') ? aiNormalize(nom||'') : String(nom||'').toLowerCase().trim();
    const qParNom = {};
    (parfumsQtes||[]).forEach(pp=>{ const k=_k(pp.nom); if(!k) return; qParNom[k]=(qParNom[k]||0)+(+pp.qte||0); });
    const noms = Object.keys(qParNom);
    if(!noms.length) return 1;
    const t = getMrpTimes();
    const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
    const MM = (typeof MACARONS_PAR_MERINGUE!=='undefined') ? MACARONS_PAR_MERINGUE : 120;
    const theoParMac = (t.coques.estimatedTime/MM) + (t.ganache.estimatedTime/TB) + (t.montage.estimatedTime/TB);
    if(!(theoParMac>0)) return 1;
    const mesures = await prodTempsParParfumParNom(90);
    let sommePondere=0, sommeQte=0;
    noms.forEach(k=>{
      const q = qParNom[k]||0; if(q<=0) return;
      const m = mesures[k];
      let f = 1;
      if(m && m.fiable && m.minParMac>0){
        f = m.minParMac / theoParMac;
        if(f<0.5) f=0.5; else if(f>2.5) f=2.5;
      }
      sommePondere += f*q; sommeQte += q;
    });
    if(sommeQte<=0) return 1;
    const facteur = sommePondere/sommeQte;
    return (isFinite(facteur) && facteur>0) ? facteur : 1;
  }catch(e){ return 1; }
}
async function _retroFacteurCadence(o, recipes){
  return _retroFacteurCadenceDe(_parfumsQtesDe(o), recipes);
}

// Place une tâche ACTIVE/ENCADRÉE de durée 'duree' (min) finissant AU PLUS TARD à 'finVoulue'.
function _retroPlacerActive(finVoulue, duree, conf, guardDays=180){
  const hm = s => { const [h,m]=String(s).split(':').map(Number); return (h||0)*60+(m||0); };
  const slotsOf = day => {
    const raw = (typeof availSlotsForDate==='function') ? availSlotsForDate(day, conf) : [];
    return raw.map(([s,e])=>[hm(s), hm(e)]).sort((a,b)=>a[0]-b[0]);
  };
  const dayKey = d => { const x=new Date(d); x.setHours(0,0,0,0); return x; };
  const minOfDay = d => d.getHours()*60+d.getMinutes();
  const atDayMin = (day,min) => { const r=dayKey(day); if(min>=1440){ r.setHours(23,59,59,0); return r; } r.setMinutes(min); return r; };
  let cur = new Date(finVoulue);
  for(let i=0;i<guardDays;i++){
    const slots = slotsOf(cur);
    const m = (i===0) ? minOfDay(cur) : 1440;
    for(let k=slots.length-1;k>=0;k--){
      const [a,b]=slots[k];
      const finPossible = Math.min(m, b);
      if(finPossible - a >= duree){
        return { debut:atDayMin(cur, finPossible-duree), fin:atDayMin(cur, finPossible), tropLongue:false };
      }
    }
    cur = dayKey(cur); cur.setDate(cur.getDate()-1); cur.setHours(23,59,0,0);
  }
  return { debut:null, fin:null, tropLongue:true };
}

// Place les coques (macaron STANDARD) le MÊME JOUR que le montage, dans une plage AVANT le montage.
// Bascule vers « à congeler » (exception) si le jour J est impossible ou absurde :
//   - aucune plage ne rentre avant le montage ce jour-là, OU
//   - les coques devraient démarrer avant 7h du matin (heure absurde), OU
//   - le trou coques→montage dépasse la fenêtre de fraîcheur (9h : 6h + 3h de tolérance) le même jour.
// Renvoie { debut, fin, tropLongue, congeler, raison } ; congeler=true => coques à congeler.
function _retroPlacerCoquesJourJ(montageDebut, dureeCoques, conf){
  const HEURE_MIN = (typeof PROC!=='undefined' && PROC.coquesHeureMinMatin!=null) ? PROC.coquesHeureMinMatin : 7;   // avant 7h = absurde
  const TROU_MAX_MIN = (typeof PROC!=='undefined' && PROC.coquesTrouMaxH!=null ? PROC.coquesTrouMaxH : 9) * 60;       // trou coques→montage > fenêtre de fraîcheur (9h : 6h + 3h de tolérance) = trop
  const hm = s => { const [h,m]=String(s).split(':').map(Number); return (h||0)*60+(m||0); };
  const dayKey = d => { const x=new Date(d); x.setHours(0,0,0,0); return x; };
  const atDayMin = (day,min) => { const r=dayKey(day); r.setMinutes(min); return r; };
  const slotsOf = day => {
    const raw = (typeof availSlotsForDate==='function') ? availSlotsForDate(day, conf) : [];
    return raw.map(([s,e])=>[hm(s), hm(e)]).sort((a,b)=>a[0]-b[0]);
  };
  const jour = dayKey(montageDebut);
  const montageMin = montageDebut.getHours()*60 + montageDebut.getMinutes();
  const slots = slotsOf(jour);
  // Cherche, le JOUR DU MONTAGE, la plage la plus TARDIVE qui permet de finir les coques
  // avant le début du montage. (finPossible = min(fin de plage, début montage))
  let best=null;
  for(let k=slots.length-1;k>=0;k--){
    const [a,b]=slots[k];
    const finPossible = Math.min(b, montageMin);
    if(finPossible - a >= dureeCoques){
      best = { debutMin: finPossible - dureeCoques, finMin: finPossible };
      break;
    }
  }
  if(!best){
    return { congeler:true, raison:'pas_de_place', debut:null, fin:null, tropLongue:false };
  }
  // Critère « heure absurde » : démarrage avant 7h.
  if(best.debutMin < HEURE_MIN*60){
    return { congeler:true, raison:'trop_tot', debut:atDayMin(jour,best.debutMin), fin:atDayMin(jour,best.finMin), tropLongue:false };
  }
  // Critère « trou trop grand » : attente entre fin des coques et début du montage.
  if(montageMin - best.finMin > TROU_MAX_MIN){
    return { congeler:true, raison:'trou', debut:atDayMin(jour,best.debutMin), fin:atDayMin(jour,best.finMin), tropLongue:false };
  }
  // OK : coques le jour J, fraîches, avant le montage.
  return { congeler:false, raison:'', debut:atDayMin(jour,best.debutMin), fin:atDayMin(jour,best.finMin), tropLongue:false };
}

// [CALAGE COQUES — placement meringue par meringue] Place chaque meringue de la semaine dans les
// plages A/B, travail actif en UN créneau continu, calé au plus PRÈS du montage mais en gardant
// 1h de coussin minimum (fenêtre : montage−9h → montage−1h). Cuisson en cascade (présence requise).
// Si aucune plage ne convient dans la fenêtre → meringue la VEILLE avec congélation des coques.
// meringues = plan.coques (avec actifMin, cuissonMin) ; montageDebut = Date ; conf = getAvailability().
// Renvoie [{ index, parfums, debut, fin, finCuisson, congeler, raison }].
function calerCoquesSemaine(meringues, montageDebut, conf){
  conf = conf || (typeof getAvailability==='function' ? getAvailability() : null);
  const COUSSIN_MIN = 60;          // 1h de coussin minimum avant le montage
  const FRAICHEUR_MAX_MIN = (typeof PROC!=='undefined' && PROC.coquesTrouMaxH!=null ? PROC.coquesTrouMaxH : 9) * 60;
  const out = [];
  if(!montageDebut) return out;

  // Limite haute de fin de cuisson : au plus tard montage − coussin.
  let finCuissonMax = new Date(montageDebut.getTime() - COUSSIN_MIN*60000);
  // Limite basse : montage − 9h (au-delà, congélation).
  const finCuissonMin = new Date(montageDebut.getTime() - FRAICHEUR_MAX_MIN*60000);

  // On place les meringues à rebours (la dernière cuite en premier, au plus près du montage),
  // chaque meringue avant la précédente pour ne pas se chevaucher.
  meringues.forEach((m, idx)=>{
    const actif = +m.actifMin || 0;
    const cuisson = +m.cuissonMin || 0;
    const dureeTotale = actif + cuisson;   // travail actif + cuisson (présence requise) en continu
    // On veut que la cuisson finisse au plus tard à finCuissonMax, donc le bloc actif+cuisson
    // finit à finCuissonMax. _retroPlacerActive cale un bloc continu finissant au plus tard voulu.
    const r = (typeof _retroPlacerActive==='function')
      ? _retroPlacerActive(finCuissonMax, dureeTotale, conf)
      : { debut:null, fin:null, tropLongue:true };

    if(r.tropLongue || !r.debut){
      // Pas de place dans la fenêtre → veille + congélation.
      out.push({ index:idx, parfums:m.parfums, repartition:m.repartition, debut:null, fin:null,
                 finCuisson:null, congeler:true, raison:'pas_de_place', actifMin:actif, cuissonMin:cuisson });
      return;
    }
    const finCuisson = r.fin;
    // Vérifie la règle de fraîcheur : fin de cuisson ne doit pas être avant montage−9h.
    const congeler = finCuisson < finCuissonMin;
    out.push({ index:idx, parfums:m.parfums, repartition:m.repartition,
               debut:r.debut, fin:r.fin, finCuisson, congeler,
               raison: congeler ? 'trop_tot_9h' : '', actifMin:actif, cuissonMin:cuisson });
    // La meringue suivante (à rebours) doit finir avant le début de celle-ci.
    finCuissonMax = new Date(r.debut.getTime());
  });

  return out;
}

// [MATURATION FLEXIBLE] Cale les coques en jouant sur la maturation si besoin.
// Règle métier (Benjamin) : la fraîcheur des coques (montées le jour de leur confection) PRIME
// sur la maturation de 24h. Si la maturation pleine force une congélation des coques, on RÉDUIT
// la maturation par paliers (jusqu'à 12h minimum) et on garde la PREMIÈRE valeur qui évite la
// congélation — ce qui maximise la maturation. Réduction en DERNIER RECOURS uniquement.
// livraison = Date de remise au client ; maturationIdealeH = 24 par défaut ; decongelH = avance grand format.
// Renvoie { coques:[...], maturationRetenueH, maturationReduite:bool, montageDebut }.


async function retroplanningCale(orderId){
  const o = await db.orders.get(orderId);
  if(!o) return { ok:false, error:'Commande introuvable.' };
  const recipes = await db.recipes.toArray().catch(()=>[]);
  // Délègue au cœur neutre : on extrait les parfums/quantités de la commande, rien d'autre.
  const dateLiv = o.dateEvenement || o.date || '';
  return retroplanningCaleParfums(dateLiv, o.heureLivraison, _parfumsQtesDe(o), recipes);
}

// [SAUT CONTEXTUEL — CARTE « COMMANDE QUI PRESSE »] Sélectionne la commande dont la PRODUCTION
// presse le plus, pour l'accueil-fil. Critère retenu (décision Benjamin) : le DÉBUT DE PRODUCTION
// le plus pressant — c'est là-dessus qu'on peut encore agir. Le bouton de la carte ouvrira
// retroplanningView(orderId). Seuil ≤ 2 j = urgent (cohérent avec la faisabilité du prévisionnel).
//
// _classerUrgenceProd est PUR (début de prod ISO + instant courant → statut), donc testable en
// isolation ; commandeQuiPresse lit la base et délègue le calage à retroplanningCale.
function _classerUrgenceProd(debutProdISO, now){
  const debutProd = new Date(debutProdISO);
  const joursAvantDebut = Math.ceil((debutProd - now) / 86400000);
  if(debutProd < now) return { rang:2, statut:'retard', joursAvantDebut };
  if(joursAvantDebut <= 2) return { rang:1, statut:'urgent', joursAvantDebut };
  return { rang:0, statut:'ok', joursAvantDebut };
}
async function commandeQuiPresse(){
  const STATUT_FINI = new Set(['Terminée','Livrée']);
  const now = new Date();
  let orders=[], clients=[];
  try{ [orders, clients] = await Promise.all([db.orders.toArray(), db.clients.toArray()]); }
  catch(_){ return null; }
  const nomClient = id => { const c=clients.find(x=>+x.id===+id); return c ? ([c.prenom,c.nom].filter(Boolean).join(' ')||c.nom||'') : ''; };
  const candidats = [];
  for(const o of orders){
    if(o.histo) continue;                                   // commandes historisées : pas d'action
    const st = (typeof normStatus==='function') ? normStatus(o.statut) : o.statut;
    if(STATUT_FINI.has(st)) continue;                       // déjà fait → ne presse plus
    let cale=null;
    try{ cale = await retroplanningCale(o.id); }catch(_){ cale=null; }
    if(!cale || !cale.ok || !cale.debutProduction) continue; // pas de prod calée → on ignore
    const u = _classerUrgenceProd(cale.debutProduction, now);
    candidats.push({
      orderId: o.id, clientNom: nomClient(o.clientId),
      statut: u.statut, rang: u.rang, joursAvantDebut: u.joursAvantDebut,
      debutProduction: cale.debutProduction, livraison: cale.livraison,
      aDesDebordements: !!cale.aDesDebordements,
    });
  }
  if(!candidats.length) return null;
  // retard d'abord, puis le début de production le plus ancien (le plus pressant)
  candidats.sort((a,b)=> b.rang - a.rang || new Date(a.debutProduction) - new Date(b.debutProduction));
  return candidats[0];
}

// [CŒUR DE CALAGE HORAIRE NEUTRE] Cale le rétroplanning dans les plages A/B à partir de données
// BRUTES (date, heure, parfums+quantités), sans objet commande. Appelé par retroplanningCale (pour
// les commandes) et par le plan pour les MARCHÉS (parfums ventilés passés directement). Aucun
// pseudo-objet commande : un marché reste un marché. Renvoie le MÊME format que retroplanningCale.
async function retroplanningCaleParfums(dateLiv, heureLiv, parfumsQtes, recipes){
  recipes = recipes || await db.recipes.toArray().catch(()=>[]);
  const parfumsNoms = (parfumsQtes||[]).map(p=>p.nom);
  const rp = (typeof retroplanningDepuisParfums==='function') ? retroplanningDepuisParfums(dateLiv, heureLiv, parfumsNoms, recipes) : null;
  if(!rp || rp.error) return { ok:false, error:(rp&&rp.error)||'Rétroplanning indisponible.' };

  const conf = (typeof getAvailability==='function') ? getAvailability() : null;
  const nbMac = _retroNbMacaronsDe(parfumsQtes);
  // [TEMPS MESURES PAR PARFUM] facteur de cadence reel (1 si aucune mesure fiable => inchange).
  const facteurCadence = await _retroFacteurCadenceDe(parfumsQtes, recipes);
  // [GANACHE PAR PARFUM] durée ganache JUSTE = somme des temps par parfum distinct (pas 12 × nbBatchs).
  // Même source de temps que le plan (mesuré fiable > recette > défaut). Repli silencieux si indispo.
  let tEtapeRetro=null; try{ tEtapeRetro = await prodTempsParEtapeParParfum(90); }catch(e){swallow(e,'retroplanningCaleParfums')}
  let ganacheTotalMin; try{ ganacheTotalMin = _retroGanacheTotalMinDe(parfumsQtes, recipes, tEtapeRetro, facteurCadence).totalMin; }catch(_){ ganacheTotalMin = undefined; }
  // [MONTAGE PAR PARFUM] durée montage JUSTE = somme par parfum de perBatch × ceil(qte/60). Repli silencieux.
  let montageTotalMin; try{ montageTotalMin = _retroMontageTotalMinDe(parfumsQtes, recipes, tEtapeRetro, facteurCadence).totalMin; }catch(_){ montageTotalMin = undefined; }
  const durees = _retroDurees(nbMac, facteurCadence, ganacheTotalMin, montageTotalMin);

  // Construire la séquence des étapes du plus tard (livraison) au plus tôt, avec durée + type.
  // On s'appuie sur les paramètres exposés par retroplanningCommande pour savoir quelles
  // phases existent et leur durée (en heures pour les phases libres).
  const H = 60; // minutes par heure
  // ════════════════════════════════════════════════════════════════════════════
  // CALAGE EN 2 BRANCHES PARALLÈLES qui convergent au MONTAGE (pivot).
  //   • Branche AVAL (commune) : montage → maturation → (décongélation) → livraison.
  //   • Branche GANACHE : repos ganache COLLÉ au montage (montage − repos) ; ganache collée
  //       à la fin = au début du repos. La ganache peut donc tomber la veille (repos 12 h).
  //   • Branche COQUES : calées le JOUR DU MONTAGE, juste avant le montage (_retroPlacerCoquesJourJ,
  //       qui gère la règle « jour même » + bascule congélation si impossible).
  // Coques et ganache ne sont PLUS chaînées l'une à l'autre : deux branches indépendantes.
  // Résultat : ordre d'exécution correct (ganache avant coques quand repos 12 h), repos collé
  // à la ganache, et coques le jour du montage respecté par construction.
  // ────────────────────────────────────────────────────────────────────────────
  const jalonsCales = [];
  const pushJ = (cle, label, type, debut, fin, extra) => {
    jalonsCales.push(Object.assign({ cle, label, type, duree:0,
      debut:debut||null, fin:fin||null, tropLongue:false }, extra||{}));
  };

  // 1) MONTAGE = pivot. Calé dans les plages A/B, finissant au plus tard à (livraison − maturation − décongel).
  let finMontageVoulue = new Date(rp.livraison);
  if(rp.decongelH>0) finMontageVoulue = new Date(finMontageVoulue.getTime() - rp.decongelH*H*60000);
  if(rp.maturationH>0) finMontageVoulue = new Date(finMontageVoulue.getTime() - rp.maturationH*H*60000);
  const placMontage = _retroPlacerActive(finMontageVoulue, durees.montage, conf);
  const montageDebut = placMontage.debut;
  const montageFin   = placMontage.fin;

  // 2) BRANCHE GANACHE : repos collé au montage, ganache collée au début du repos.
  if(rp.aCremeux){
    // Crémeux : préparation active + éventuelle congélation avant le montage.
    let finCremeuxVoulue = montageDebut ? new Date(montageDebut) : finMontageVoulue;
    if(rp.cremeuxCongelH>0){
      const congelFin = new Date(finCremeuxVoulue);
      const congelDebut = new Date(congelFin.getTime() - rp.cremeuxCongelH*H*60000);
      pushJ('congel-cremeux', `Congélation crémeux (${rp.cremeuxCongelH} h)`, 'libre', congelDebut, congelFin, {duree:rp.cremeuxCongelH*H});
      finCremeuxVoulue = congelDebut;
    }
    const placCremeux = _retroPlacerActive(finCremeuxVoulue, durees.cremeux, conf);
    pushJ('cremeux', 'Préparation du crémeux', 'active', placCremeux.debut, placCremeux.fin, {duree:durees.cremeux, tropLongue:placCremeux.tropLongue});
  } else {
    // Ganache : on place d'abord le travail actif au plus tard possible (montage − repos minimum),
    // puis le REPOS occupe TOUT l'intervalle entre la fin réelle de la ganache et le montage.
    // Ainsi le repos est COLLÉ à la ganache (pas de trou) et dure AU MOINS reposGanacheH (minimum
    // métier) — souvent davantage si la ganache tombe la veille au soir, ce qui est sans problème.
    const finGanacheVoulue = (montageDebut && rp.reposGanacheH>0)
      ? new Date(montageDebut.getTime() - rp.reposGanacheH*H*60000)
      : (montageDebut ? new Date(montageDebut) : finMontageVoulue);
    const placGanache = _retroPlacerActive(finGanacheVoulue, durees.ganache, conf);
    pushJ('ganache', 'Préparation ganache / crémeux', 'active', placGanache.debut, placGanache.fin, {duree:durees.ganache, tropLongue:placGanache.tropLongue});
    // Repos = de la fin réelle de la ganache jusqu'au montage (collé des deux côtés).
    if(rp.reposGanacheH>0 && placGanache.fin && montageDebut){
      const reposDebut = new Date(placGanache.fin);
      const reposFin = new Date(montageDebut);
      const reposReelMin = Math.max(0, (reposFin - reposDebut)/60000);
      const reposReelH = Math.round(reposReelMin/60*10)/10;
      pushJ('repos-ganache', `Repos ganache (${reposReelH} h)`, 'libre', reposDebut, reposFin,
        {duree:reposReelMin, reposMinH:rp.reposGanacheH});
    }
  }

  // 3) BRANCHE COQUES : le JOUR DU MONTAGE, juste avant le montage (règle métier + congélation).
  if(montageDebut){
    const c = _retroPlacerCoquesJourJ(montageDebut, durees.coques, conf);
    if(c.congeler){
      const jourMontage = new Date(montageDebut); jourMontage.setHours(8,0,0,0);
      pushJ('coques', 'Coques (meringue + cuisson)', 'encadree',
        c.debut || jourMontage, c.fin || new Date(jourMontage.getTime()+durees.coques*60000),
        {duree:durees.coques, congeler:true, congelRaison:c.raison, tropLongue:(c.raison==='pas_de_place')});
    } else {
      pushJ('coques', 'Coques (meringue + cuisson)', 'encadree', c.debut, c.fin,
        {duree:durees.coques, congeler:false});
    }
  } else {
    // Pas de montage calé (cas dégénéré) : coques en repli à rebours.
    const c = _retroPlacerActive(finMontageVoulue, durees.coques, conf);
    pushJ('coques', 'Coques (meringue + cuisson)', 'encadree', c.debut, c.fin, {duree:durees.coques, tropLongue:c.tropLongue});
  }

  // 4) MONTAGE puis branche AVAL (maturation, décongélation) et ANCRE livraison.
  pushJ('montage', 'Montage / assemblage', 'active', montageDebut, montageFin, {duree:durees.montage, tropLongue:placMontage.tropLongue});
  if(rp.maturationH>0){
    const matDebut = montageFin ? new Date(montageFin) : finMontageVoulue;
    const matFin = new Date(matDebut.getTime() + rp.maturationH*H*60000);
    pushJ('maturation', `Maturation (${rp.maturationH} h au frais)`, 'libre', matDebut, matFin, {duree:rp.maturationH*H});
  }
  if(rp.decongelH>0){
    const decFin = new Date(rp.livraison);
    const decDebut = new Date(decFin.getTime() - rp.decongelH*H*60000);
    pushJ('decongel', `Décongélation au frigo (${rp.decongelH} h)`, 'libre', decDebut, decFin, {duree:rp.decongelH*H});
  }
  pushJ('livraison', 'Livraison', 'ancre', new Date(rp.livraison), new Date(rp.livraison), {duree:0});

  // [MATURATION FLEXIBLE] Règle métier : la fraîcheur des coques (montées le jour de leur confection)
  // PRIME sur la maturation de 24h. Si les coques finissent congelées, on RÉDUIT la maturation par
  // paliers (jusqu'à 12h min) pour reculer le montage et tenter de garder les coques fraîches le jour J.
  // On garde la PREMIÈRE maturation qui évite la congélation (donc la plus proche de 24h possible).
  let maturationRetenueH = (rp.maturationH!=null) ? rp.maturationH : 0;
  let maturationReduite = false;
  if(rp.aStandard && rp.maturationH>12){
    const coquesJalon = jalonsCales.find(j=>j.cle==='coques');
    if(coquesJalon && coquesJalon.congeler){
      const MAT_MIN_H = 12, PAS_H = 3;
      const matIdx = jalonsCales.findIndex(j=>j.cle==='maturation');
      for(let mat=rp.maturationH-PAS_H; mat>=MAT_MIN_H; mat-=PAS_H){
        // Recalcule le montage avec cette maturation réduite, puis les coques le jour du montage.
        const refApresFroid = rp.decongelH>0 ? new Date(new Date(rp.livraison).getTime()-rp.decongelH*3600000) : new Date(rp.livraison);
        const finMontageTest = new Date(refApresFroid.getTime() - mat*3600000);
        const rMontage = _retroPlacerActive(finMontageTest, durees.montage, conf);
        if(rMontage.tropLongue || !rMontage.debut) continue;
        const cTest = _retroPlacerCoquesJourJ(rMontage.debut, durees.coques, conf);
        if(!cTest.congeler && cTest.debut){
          // Trouvé : cette maturation garde les coques fraîches. On applique tout.
          maturationRetenueH = mat; maturationReduite = true;
          const montageJalon = jalonsCales.find(j=>j.cle==='montage');
          if(montageJalon){ montageJalon.debut = rMontage.debut; montageJalon.fin = rMontage.fin; montageJalon.tropLongue=false; }
          if(matIdx>=0){
            jalonsCales[matIdx].duree = mat*60;
            jalonsCales[matIdx].label = `Maturation (${mat} h au frais)`;
            jalonsCales[matIdx].debut = new Date(rMontage.fin);
            jalonsCales[matIdx].fin = new Date(refApresFroid);
          }
          coquesJalon.debut = cTest.debut; coquesJalon.fin = cTest.fin;
          coquesJalon.congeler = false; coquesJalon.tropLongue = false; coquesJalon.congelRaison = '';
          break;
        }
      }
    }
  }

  const aDesDebordements = jalonsCales.some(j=>j.tropLongue);
  const debutProd = jalonsCales.find(j=>j.debut && j.type!=='ancre');
  return {
    ok:true, livraison:rp.livraison, nbMacarons:nbMac, durees,
    jalonsCales, aDesDebordements,
    debutProduction: debutProd ? debutProd.debut : null,
    contraintes:rp.contraintes,
    maturationRetenueH, maturationReduite
  };
}

// [ÉCRAN] Production (écran unique) : toutes les commandes et marchés à venir, fusionnés par semaine.


// [MUTUALISATION — index par commande] À partir de buildMutualisationSemaine, construit pour chaque
// commande la liste de ses partages PAR PARFUM : « sur la vanille de la semaine 26, je suis
// regroupé avec ces autres commandes ». Sert à afficher le lien précis sur chaque étape et le
// badge global, + les raccourcis « voir / détail » vers les commandes liées.
// Renvoie une Map orderId -> { wk, wkLabel, parfums:[{nom, qte, autres:[{orderId, client, qte}]}], aDesPartages }.
function _buildMutualIndex(mut){
  const idx = new Map();
  if(!mut || !mut.semaines) return idx;
  mut.semaines.forEach(s=>{
    s.parfums.forEach(p=>{
      if(p.commandes.length < 2) return;   // pas de partage si une seule commande sur ce parfum
      p.commandes.forEach(c=>{
        if(c.orderId==null) return;
        const autres = p.commandes.filter(x=>x.orderId!==c.orderId)
                                  .map(x=>({ orderId:x.orderId, client:x.client, qte:x.qte }));
        if(!autres.length) return;
        let entry = idx.get(c.orderId);
        if(!entry){ entry = { wk:s.wk, wkLabel:s.label, parfums:[], aDesPartages:true }; idx.set(c.orderId, entry); }
        entry.parfums.push({ nom:p.nom, qte:c.qte, autres });
      });
    });
  });
  return idx;
}

// [VUE COMMANDES REPLIABLES] Pour chaque commande à venir, calcule son rétroplanning calé
// (mêmes étapes que la modale détaillée) et le présente en une ligne « client + chevron »
// dépliable, montrant l'enchaînement complet. Remplace le déroulé jour-par-jour.
// Renvoie { commandes:[{ id, clientNom, livraison, livraisonTxt, nbMacarons, parfumsTxt,
//   etapes:[{cle, label, type, debutTxt, finTxt, jourTxt, congeler, congelRaison, tropLongue}],
//   aCongeler, aDebordement }], horizonJours }.
async function buildCommandesRetro(horizonJours, mut){
  horizonJours = +horizonJours || 45;
  const orders  = await db.orders.toArray().catch(()=>[]);
  const clients = await db.clients.toArray().catch(()=>[]);
  const clientNom = id => { const c=clients.find(x=>+x.id===+id); return c?(c.nom||c.prenom||'Client'):'—'; };
  const today0 = new Date(); today0.setHours(0,0,0,0);
  const horizon = new Date(today0); horizon.setDate(horizon.getDate()+horizonJours);
  // Index des partages par commande (parfum → autres commandes de la même semaine).
  const mutIdx = _buildMutualIndex(mut);
  // Étapes concernées par la mutualisation (par parfum) : coques, montage, ganache/crémeux.
  const ETAPES_MUTUALISABLES = new Set(['coques','montage','ganache','cremeux']);

  const fmtJour = d => { try{ return new Date(d).toLocaleDateString('fr-FR',{weekday:'short',day:'2-digit',month:'short'}); }catch(e){ return ''; } };
  const fmtH    = d => { try{ return new Date(d).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}); }catch(e){ return ''; } };
  const fmtLiv  = d => { try{ return new Date(d).toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'}); }catch(e){ return String(d).slice(0,10); } };

  const out = [];
  for(const o of orders){
    const st = (typeof normStatus==='function') ? normStatus(o.statut) : (o.statut||'');
    if(st==='Livrée') continue;
    const dLiv = o.dateEvenement || o.date || '';
    if(!dLiv) continue;
    const dLiv0 = new Date(String(dLiv).slice(0,10)+'T12:00:00');
    if(dLiv0 < today0 || dLiv0 > horizon) continue;

    let cale=null;
    try{ cale = await retroplanningCale(o.id); }catch(e){swallow(e,'buildCommandesRetro')}
    if(!cale || !cale.ok || !Array.isArray(cale.jalonsCales)) continue;

    // Liste lisible des parfums de la commande.
    const lignes = (typeof orderToLines==='function') ? orderToLines(o) : [];
    const pf = {};
    lignes.forEach(ln=>{
      const src = (ln.type==='grand') ? (ln.items||[]) : (ln.parfums||[]);
      src.forEach(p=>{ const n=(p.nom||'').trim(); const q=+p.qte||0; if(n&&q>0) pf[n]=(pf[n]||0)+q; });
    });
    const parfumsTxt = Object.keys(pf).sort((a,b)=>pf[b]-pf[a]).map(n=>`${n} (${pf[n]})`).join(', ');

    const partages = mutIdx.get(o.id) || null;   // { wk, wkLabel, parfums:[...] } ou null
    const etapes = cale.jalonsCales.map(j=>{
      // Si l'étape est mutualisable et que la commande a des partages, on attache la liste
      // des parfums partagés (pour cette étape, tous les parfums partagés s'appliquent).
      let partagesEtape = null;
      if(partages && ETAPES_MUTUALISABLES.has(j.cle) && partages.parfums.length){
        partagesEtape = partages.parfums.map(pp=>({ nom:pp.nom, autres:pp.autres }));
      }
      return {
        cle:j.cle, label:j.label, type:j.type,
        debutTxt: j.debut?fmtH(j.debut):'', finTxt: j.fin?fmtH(j.fin):'',
        jourTxt: j.debut?fmtJour(j.debut):'',
        congeler: !!j.congeler, congelRaison: j.congelRaison||'', tropLongue: !!j.tropLongue,
        partages: partagesEtape
      };
    });

    out.push({
      id:o.id, clientNom:clientNom(o.clientId),
      livraison:String(dLiv).slice(0,10), livraisonTxt:fmtLiv(dLiv),
      livraisonJourTxt: fmtJour(cale.livraison),
      nbMacarons:cale.nbMacarons||0, parfumsTxt,
      etapes,
      aCongeler: etapes.some(e=>e.congeler),
      aDebordement: !!cale.aDesDebordements,
      partages   // badge global : non-null si la commande partage des fournées
    });
  }
  // Tri par date de livraison croissante (la plus proche en premier).
  out.sort((a,b)=> a.livraison<b.livraison?-1 : a.livraison>b.livraison?1 : 0);
  return { commandes:out, horizonJours };
}

// Rendu repliable : une carte par commande, dépliée au clic sur l'en-tête (chevron).
function _agendaCommandesSection(cr){
  if(!cr || !cr.commandes || !cr.commandes.length){
    return `<div class="panel"><p class="note">Aucune commande à produire sur les ${cr?cr.horizonJours:45} prochains jours.</p></div>`;
  }
  const META = {
    coques:  {ico:'🟤', col:'#8a6d3b'},
    ganache: {ico:'🍫', col:'#7a4b2a'},
    cremeux: {ico:'🟠', col:'#c0651a'},
    'congel-cremeux':{ico:'❄️', col:'#3b6ea5'},
    'repos-ganache': {ico:'😴', col:'#5a8a6a'},
    montage: {ico:'🔧', col:'#3f7d52'},
    maturation:{ico:'🧊', col:'#5a8a6a'},
    decongel:{ico:'🌡', col:'#3b6ea5'},
    livraison:{ico:'🎁', col:'#3f7d52'}
  };
  const cartes = cr.commandes.map(c=>{
    const etapes = c.etapes.map(e=>{
      const m = META[e.cle] || {ico:'•', col:'#8a7a72'};
      const horaire = e.type==='ancre'
        ? `<b>${esc(e.jourTxt)}</b>`
        : (e.debutTxt ? `${esc(e.jourTxt)} · <b>${esc(e.debutTxt)}${e.finTxt?'→'+esc(e.finTxt):''}</b>` : '');
      const congelBadge = e.congeler ? ` <span style="background:#3b6ea5;color:#fff;font-size:.58rem;font-weight:600;padding:1px 6px;border-radius:7px">❄️</span>` : '';
      const warn = e.tropLongue ? ` <span style="color:var(--red);font-size:.72rem">⚠</span>` : '';
      // Détail de mutualisation par parfum sur cette étape (coques/ganache/montage partagés).
      let mutualBloc = '';
      if(e.partages && e.partages.length){
        const lignesP = e.partages.map(pp=>{
          const liens = pp.autres.map(a=>`<span style="display:inline-flex;gap:3px;align-items:center;margin:2px 4px 0 0">
            <span style="color:#5a6b80">${esc(a.client)} (${a.qte})</span>
            <button class="btn-mut" onclick="event.stopPropagation();goToCommande(${a.orderId})" title="Voir la commande dans l'agenda">voir</button>
            <button class="btn-mut" onclick="event.stopPropagation();retroplanningView(${a.orderId})" title="Rétroplanning détaillé">détail</button>
          </span>`).join('');
          return `<div style="font-size:.74rem;color:#3b6ea5;margin-top:3px">🔗 <b>${esc(pp.nom)}</b> regroupé avec ${liens}</div>`;
        }).join('');
        mutualBloc = `<div style="margin-top:5px;padding-top:5px;border-top:1px dashed #cfe0f2">${lignesP}</div>`;
      }
      return `<div class="sum-box" style="align-items:flex-start;border-left:3px solid ${m.col};cursor:pointer;margin:4px 0"
        onclick="event.stopPropagation();retroplanningView(${c.id})">
        <div style="flex:1">
          <div>${m.ico} <b style="color:${m.col}">${esc(e.label)}</b>${congelBadge}${warn}</div>
          <div style="font-size:.78rem;color:#9a8576;margin-top:1px">${horaire}</div>
          ${mutualBloc}
        </div>
        <span style="color:var(--bordeaux);font-size:.75rem">détail →</span>
      </div>`;
    }).join('');
    const mutBadge = (c.partages && c.partages.parfums.length)
      ? `<span style="background:#3b6ea5;color:#fff;font-size:.58rem;font-weight:600;padding:1px 6px;border-radius:7px">🔗 mutualisée</span> ` : '';
    const badges = `${mutBadge}${c.aCongeler?'<span style="background:#3b6ea5;color:#fff;font-size:.58rem;font-weight:600;padding:1px 6px;border-radius:7px">❄️ congel.</span> ':''}${c.aDebordement?'<span style="background:#a5453b;color:#fff;font-size:.58rem;font-weight:600;padding:1px 6px;border-radius:7px">⚠ tendu</span> ':''}`;
    return `<details class="panel cmd-retro" style="margin-bottom:12px" data-cmd="${c.id}" id="cmd-retro-${c.id}">
      <summary style="cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
        <div style="flex:1">
          <div style="font-weight:700;color:var(--bordeaux);font-size:1rem">${esc(c.clientNom)} <span style="font-weight:400;color:#9a8576;font-size:.82rem">· livraison ${esc(c.livraisonTxt)}</span></div>
          <div style="font-size:.8rem;color:#9a8576;margin-top:2px">${c.nbMacarons} macaron${c.nbMacarons>1?'s':''}${c.parfumsTxt?' · '+esc(c.parfumsTxt):''} ${badges}</div>
        </div>
        <span class="cmd-chevron" style="color:var(--caramel,#AA7C39);font-size:1.1rem;line-height:1">▸</span>
      </summary>
      <div style="margin-top:10px">${etapes}</div>
    </details>`;
  }).join('');
  return cartes;
}

// Raccourci « voir B » : déplie la commande cible dans l'agenda et fait défiler vers elle.
function goToCommande(orderId){
  const el = document.getElementById('cmd-retro-'+orderId);
  if(!el){ // pas dans la vue courante (hors horizon ou autre écran) → ouvrir le détail
    if(typeof retroplanningView==='function') retroplanningView(orderId);
    return;
  }
  el.open = true;
  el.scrollIntoView({ behavior:'smooth', block:'center' });
  // Flash visuel pour repérer la carte cible.
  el.style.transition = 'box-shadow .3s';
  const old = el.style.boxShadow;
  el.style.boxShadow = '0 0 0 3px #3b6ea5';
  setTimeout(()=>{ el.style.boxShadow = old; }, 900);
}

// ════════════════════════════════════════════════════════════════════════════
// SOCLE « ÉCRAN VIVANT » — synchronisation de la Production avec l'heure réelle.
// Objectif (Benjamin) : savoir à tout moment OÙ j'en suis dans ma journée, combien de
// temps il me reste pour produire, et pouvoir ajuster mon planning d'un geste.
// ────────────────────────────────────────────────────────────────────────────
// Temps de travail restant AUJOURD'HUI à partir de l'instant présent (minutes).
// Réutilise availMinutesOnDay avec fromMin = heure courante : ne compte que ce qui reste
// devant soi dans les plages A/B du jour (exceptions ponctuelles comprises via availSlotsForDate).
function _prodTempsRestantAujourdhui(conf){
  conf = conf || ((typeof getAvailability==='function') ? getAvailability() : null);
  const now = new Date();
  const fromMin = now.getHours()*60 + now.getMinutes();
  let restant = 0, totalJour = 0;
  try{
    restant = (typeof availMinutesOnDay==='function') ? availMinutesOnDay(now, fromMin, null, conf) : 0;
    totalJour = (typeof availMinutesOnDay==='function') ? availMinutesOnDay(now, null, null, conf) : 0;
  }catch(e){swallow(e,'_prodTempsRestantAujourdhui')}
  // Heure de fin du dernier créneau du jour (pour « avant HH:MM »).
  let finJour = null;
  try{
    const slots = (typeof availSlotsForDate==='function') ? availSlotsForDate(now, conf) : [];
    if(slots && slots.length){
      const finMin = Math.max(...slots.map(([s,e])=>hmToMin(e)));
      finJour = String(Math.floor(finMin/60)).padStart(2,'0')+':'+String(finMin%60).padStart(2,'0');
    }
  }catch(e){swallow(e,'_prodTempsRestantAujourdhui')}
  return { restant, totalJour, finJour, fromMin, enCreneau: restant>0 };
}

// Rendu de la barre temps réel (heure courante + temps restant + bouton synchroniser).
function _prodBarreVivante(){
  const t = _prodTempsRestantAujourdhui();
  const now = new Date();
  const dateLbl = now.toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long'});
  const heure = String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');
  const fmtH = m => m>=60 ? `${Math.floor(m/60)}h${String(m%60).padStart(2,'0')}` : `${m} min`;
  // Carte « temps restant » : valeur + total du jour en repère.
  const carteRestant = t.totalJour>0
    ? `<div class="val">${t.enCreneau?fmtH(t.restant):'—'} <small>${t.enCreneau?`/ ${fmtH(t.totalJour)}`:'hors créneau'}</small></div>`
    : `<div class="val" style="font-size:.92rem">pas de créneau</div>`;
  // Phrase contextuelle selon la situation du moment.
  let phrase;
  if(t.totalJour<=0){
    phrase = `Aucune plage de travail définie aujourd'hui. <span class="act" style="color:#ffe;text-decoration:underline" onclick="availEditor()">définir mes créneaux</span>`;
  } else if(!t.enCreneau){
    phrase = `Tu es hors de tes créneaux de travail pour le moment.`;
  } else {
    phrase = `Il te reste <b>${fmtH(t.restant)}</b> de travail${t.finJour?` avant <b>${t.finJour}</b>`:''} aujourd'hui.`;
  }
  return `<div class="prod-now" style="background:linear-gradient(135deg,#52252F,#6e3340);color:#fff;border-radius:13px;padding:13px 15px;margin:0 0 14px;box-shadow:0 2px 8px var(--shadow,rgba(82,37,47,.12))">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:9px">
      <div style="font-size:1.02rem;font-weight:700"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#7ee0a1;margin-right:6px;vertical-align:middle"></span>${esc(dateLbl)} · ${heure} <span style="font-weight:400;opacity:.8;font-size:.78rem">maintenant</span></div>
      <button onclick="prodActualiser()" style="background:rgba(255,255,255,.16);border:none;color:#fff;border-radius:8px;padding:6px 11px;font-size:.76rem;font-weight:600;cursor:pointer">🔄 Actualiser</button>
    </div>
    <div style="background:rgba(255,255,255,.1);border-radius:9px;padding:9px 11px;max-width:230px">
      <div style="font-size:.68rem;opacity:.82;margin-bottom:2px">⏱ Temps de production restant aujourd'hui</div>
      ${carteRestant}
    </div>
    <div style="margin-top:9px;font-size:.78rem;opacity:.94">📍 ${phrase}</div>
  </div>`;
}

// Raccourci « Changement de planning ? » → ouvre l'éditeur de disponibilité ; au retour,
// renderAgendaProduction se rafraîchit (déjà câblé : availSave appelle le refresh Production).
function _prodRaccourciPlanning(){
  return `<div class="panel" style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 14px;margin-bottom:14px">
    <div style="font-size:.82rem">🗓️ <b>Changement de planning ?</b>
      <div style="font-size:.74rem;color:#9a8a82;margin-top:1px">Pas dispo cet après-midi, un créneau en plus… ajuste, tout se recalcule.</div></div>
    <button class="btn sm" onclick="availEditor()" style="white-space:nowrap">Ajuster</button>
  </div>`;
}

// [SUGGESTION PARFUMS] Bandeau d'alerte « parfums à déterminer maintenant ». Recalculé à chaque
// rendu de Production (pas d'état persistant) : window._prodAlertesParfums est rempli par la collecte
// dans renderAgendaProduction. Affiche une carte par commande dont la prod démarre et qui a encore
// des macarons sans parfum, avec un bouton qui ouvre la suggestion (données fraîches du jour).
function _prodAlerteParfums(){
  const al = (typeof window!=='undefined' && Array.isArray(window._prodAlertesParfums)) ? window._prodAlertesParfums : [];
  if(!al.length) return '';
  const cartes = al.map(a=>{
    const fmtJ = iso => { try{ return new Date(iso).toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long'}); }catch(e){ return ''; } };
    return `<div style="display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:9px;background:#fff;border:1px solid #e7cf94;margin-top:6px">
      <div style="flex:1">
        <div style="font-size:.88rem;color:var(--bordeaux);font-weight:600">${esc(a.client||'Commande')} · <b>${a.sansParfum}</b> macaron${a.sansParfum>1?'s':''} à déterminer <span style="font-size:.66rem;color:#bbb;font-weight:400">#${esc(String(a.id))}</span></div>
        <div style="font-size:.74rem;color:#9a8a82;margin-top:1px">Production démarrée le ${esc(fmtJ(a.debutProduction))} — choisis maintenant, avec ton stock réel du jour.</div>
      </div>
      <button class="btn gold sm" style="white-space:nowrap" onclick="suggererParfumsProd(${a.id})">🎯 Choisir</button>
    </div>`;
  }).join('');
  return `<div class="panel" style="padding:11px 14px;margin-bottom:14px;border:1px solid #e7cf94;background:#fdf8ec">
    <div style="font-size:.84rem;font-weight:700;color:#8a6d1f">🎯 Parfums à déterminer maintenant</div>
    <div style="font-size:.74rem;color:#9a8a82;margin-top:1px">Ces commandes entrent en production et ont des macarons « au choix » à trancher.</div>
    ${cartes}
  </div>`;
}

// Ouvre la suggestion pour une commande au moment de la production (données fraîches du jour),
// puis fige les parfums validés EN BASE.
// [UNIFICATION v1182] On appelle désormais LE MÊME moteur que les compositions alternatives
// (genererCompositionsCoffret → collecte stock + surplus mutualisable + relance faisable, avec
// TOUTES les dépendances temporelles : repos ganache, prise crémeux, congélation, dates de dispo
// réelles des composants). Recalcul 100 % dynamique à chaque clic : le résultat reflète l'état réel
// du terrain à l'instant présent (aucune génération figée, aucune réservation — simple simulation).
// Fonctionne à l'identique pour les macarons standard ET les grands formats (typeFiltre).
async function suggererParfumsProd(orderId){
  openModal(`<h3>🎯 Suggestion de parfums</h3><div style="padding:14px;text-align:center;color:#9a8576">⏳ Analyse en temps réel — stock, batchs planifiés, faisabilité du jour…</div>`);
  try{
    const o = await db.orders.get(orderId);
    if(!o){ closeModal(); return; }
    const sp = _sansParfumTotalDe(o);
    if(sp.total<=0){ closeModal(); toast && toast('Plus de macaron à déterminer'); if(typeof renderAgendaProduction==='function') renderAgendaProduction(); return; }
    const dateLiv = (o.dateEvenement || o.date || '').slice(0,10);
    const heureLiv = o.heureLivraison || '';
    // Univers de la commande : grand format ou coffret standard ? On lit le type des lignes qui
    // portent du sansParfum (le figeage ne concerne que les lignes coffret aujourd'hui).
    const typeFiltre = _sansParfumTypeUnivers(o);
    // Le moteur B compose EXACTEMENT sp.total macarons (la "taille" ici = le nb à déterminer).
    const res = await genererCompositionsCoffret(sp.total, dateLiv, heureLiv, { mode:'flexible', typeFiltre });
    const props = (res && res.propositions) || [];
    if(!props.length){
      openModal(`<h3>🎯 Suggestion de parfums</h3>
        <div class="banner" style="background:#fdf8e9;border-color:#e8d09a">📋 <div>Aucune composition possible pour l'instant (ni stock, ni batch prévu, ni relance faisable pour cette date).</div></div>
        <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
      return;
    }
    _renderSuggestionProdModale(orderId, res, sp, typeFiltre, dateLiv);
  }catch(e){
    console.error('suggererParfumsProd', e);
    openModal(`<h3>🎯 Suggestion de parfums</h3>
      <div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⛔ <div>Erreur pendant l'analyse.</div></div>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
  }
}

// Détermine l'univers (grand format vs standard) des macarons SANS PARFUM d'une commande, pour
// filtrer le moteur. Règle : dès qu'une ligne coffret sans-parfum correspond à des recettes grand
// format, on bascule en 'grand'. Par défaut 'standard' (cas courant du coffret de macarons classiques).
// Aujourd'hui le sansParfum vit sur les lignes coffret → standard ; on garde le hook pour l'évolution GF.
function _sansParfumTypeUnivers(o){
  // Repli simple et sûr : les macarons "sans parfum" des coffrets sont des macarons standard.
  // (Les grands formats se commandent par item nommé, pas via sansParfum de coffret.)
  return 'standard';
}

// Rendu de la modale de suggestion au démarrage prod : meilleure proposition (moins coûteuse) mise en
// avant, ventilation par source, puis figeage. On propose aussi la 2e option (avec relance) si elle
// complète mieux. Le figeage n'écrit que les parfums (aucune réservation de stock ici).
function _renderSuggestionProdModale(orderId, res, sp, typeFiltre, dateLiv){
  const props = (res.propositions||[]).slice(0,2);
  const carte = (p, principal) => {
    const v = p.ventilation;
    const niveau = p.cout===0 ? {ico:'✅', txt:'100 % disponible maintenant', col:'#3f7d52'}
                 : p.cout===1 ? {ico:'♻️', txt:'Via tes batchs déjà prévus', col:'#c97a2a'}
                 : {ico:'🔧', txt:'Complet avec une relance de production', col:'#8a6d3b'};
    const bouts=[];
    if(v.stock>0)     bouts.push(`<b>${v.stock}</b> en stock`);
    if(v.mutualise>0) bouts.push(`<b>${v.mutualise}</b> mutualisé${v.mutualise>1?'s':''}`);
    if(v.relance>0)   bouts.push(`<b>${v.relance}</b> à produire`);
    const detail = p.lignes.map(l=>{
      const src = l.relance>0 ? '🏭' : l.mutualise>0 ? '♻️' : '📦';
      return `<span style="display:inline-block;background:#f7f2ea;border:1px solid var(--hair);border-radius:8px;padding:2px 8px;margin:2px 3px 0 0;font-size:.84rem;text-transform:capitalize">${src} ${esc(l.nom)} ×${l.qte}</span>`;
    }).join('');
    // Le figeage attend [{nom,qte}] : on mappe la compo.
    const payload = escJs(encodeURIComponent(JSON.stringify(p.lignes.map(l=>({nom:l.nom, qte:l.qte})))));
    const etat = p.complet ? `<span style="color:#3f7d52;font-weight:600">Couvre les ${sp.total} macaron${sp.total>1?'s':''}</span>`
                           : `<span style="color:#c97a2a;font-weight:600">${p.total}/${sp.total} — il manque ${p.manque}</span>`;
    return `<div style="border:1px solid ${principal?'#d8b45a':'var(--hair)'};border-radius:12px;padding:11px 13px;margin:9px 0;background:#fff">
      <div style="font-size:.8rem;font-weight:700;color:${niveau.col};margin-bottom:4px">${niveau.ico} ${niveau.txt}</div>
      <div style="margin-bottom:6px">${etat}</div>
      <div style="margin-bottom:6px">${detail}</div>
      ${bouts.length?`<div style="font-size:.8rem;color:#7a6a62;margin-bottom:8px">↳ ${bouts.join(' · ')}</div>`:''}
      <button class="btn ${principal?'gold':'ghost'} sm" onclick="figerParfumsProd(${orderId},'${payload}')">Valider &amp; figer${principal?'':' cette variante'}</button>
    </div>`;
  };
  const dateTxt = dateLiv ? ((typeof fmtDate==='function')?fmtDate(dateLiv):dateLiv) : "aujourd'hui";
  openModal(`<h3>🎯 Suggestion de parfums</h3>
    <p class="note" style="margin-bottom:6px">Pour les <b>${sp.total}</b> macaron${sp.total>1?'s':''} à déterminer — recalculé à l'instant selon ton stock, tes batchs prévus et la faisabilité pour le <b>${esc(dateTxt)}</b>. Une fois validé, c'est <b>figé</b> dans la commande.</p>
    ${props.map((p,n)=>carte(p, n===0)).join('')}
    <p class="note" style="font-size:.72rem;color:#9a8a82;margin-top:4px">Aucun stock n'est réservé maintenant : la réservation se fait au picking ou au passage en « Prête ».</p>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button></div>`);
}

// Fige les parfums validés DANS la commande (base) : ajoute aux lignes coffret et consomme le
// sansParfum. Écriture réelle via db.orders.update. Puis recalcule l'écran Production (l'alerte
// disparaît d'elle-même puisqu'il n'y a plus de sansParfum).
async function figerParfumsProd(orderId, payload){
  let rep; try{ rep = JSON.parse(decodeURIComponent(payload)); }catch(e){ rep = []; }
  if(!Array.isArray(rep) || !rep.length){ closeModal(); return; }
  try{
    const o = await db.orders.get(orderId);
    if(!o){ closeModal(); return; }
    const lignes = orderToLines(o);
    let restant = rep.slice();   // file des {nom, qte} à répartir
    // On verse les parfums dans les lignes coffret ayant du sansParfum, dans l'ordre.
    lignes.forEach(ln=>{
      if(ln.type!=='coffret') return;
      let sp = +ln.sansParfum||0;
      if(sp<=0) return;
      ln.parfums = Array.isArray(ln.parfums) ? ln.parfums : [];
      // convertit parfums en map de travail
      const map = {}; (ln.parfums||[]).forEach(p=>{ if(p&&p.nom) map[p.nom]=(+p.qte||0); });
      for(const item of restant){
        if(sp<=0) break;
        if(item.qte<=0) continue;
        const prendre = Math.min(item.qte, sp);
        map[item.nom] = (map[item.nom]||0) + prendre;
        item.qte -= prendre; sp -= prendre;
      }
      ln.parfums = Object.keys(map).filter(k=>map[k]>0).map(nom=>({nom, qte:map[nom]}));
      if(sp>0) ln.sansParfum = sp; else delete ln.sansParfum;
    });
    await db.orders.update(orderId, { lignes });
    closeModal();
    try{ toast('Parfums figés dans la commande ✓'); }catch(e){swallow(e,'figerParfumsProd')}
    if(typeof renderAgendaProduction==='function') renderAgendaProduction();
  }catch(e){
    console.error('figerParfumsProd', e);
    closeModal();
    try{ toast('Erreur lors de l\'enregistrement'); }catch(e){swallow(e,'figerParfumsProd')}
  }
}

// Handler du bouton Actualiser : recalcule l'écran à l'instant présent (heure, temps restant,
// verdicts de faisabilité, commandes/marchés à jour). Simple re-render de l'écran courant.
function prodActualiser(){
  try{ toast('Production synchronisée à l\'instant présent ✓'); }catch(e){swallow(e,'prodActualiser')}
  if(typeof renderAgendaProduction==='function') renderAgendaProduction();
}

// [RETOUR AU FIL] Marqueur d'origine : posé quand un saut PART de l'accueil (« Le Fil »). Tant qu'il
// est présent ET qu'on est resté sur l'écran cible, l'écran atteint depuis le fil affiche un bouton
// « ← Retour au fil ». Consommé au clic du bouton, en revenant à l'accueil, OU (voir filRetourSync,
// même mécanique que assistantRetourSync ci-dessous) dès qu'on repart vers un AUTRE écran par le menu.
// [FIX v1294] AVANT : le marqueur n'expirait QUE sur retour à l'accueil, jamais sur navigation vers un
// écran tiers. Un lien du copilote suivi une fois dans la session laissait le marqueur actif ; toute
// visite ULTÉRIEURE de l'écran cible par le menu (sans lien avec le copilote) réaffichait alors à tort
// le bouton « ← Retour au fil » en haut de l'écran, pile là où le doigt vient de taper pour y entrer —
// exposant à un retour accidentel à l'accueil qui pouvait ressembler à un crash.
function filMarquerOrigine(cible){ window._filRetour = { ts: Date.now(), cible: cible||'agendaprod' }; }
function filRetourActif(){ const m=window._filRetour; return !!(m && view===m.cible); }
// Appelée à chaque navigation (comme assistantRetourSync) : si on n'est plus sur l'écran cible du
// marqueur, celui-ci est obsolète et oublié — il ne doit jamais survivre à un détour par le menu.
function filRetourSync(){
  const m = window._filRetour;
  if(m && view!==m.cible) window._filRetour = null;
}

// ============================================================
//  RETOUR AU COPILOTE — bouton flottant après un raccourci de l'assistant
// ============================================================
// Quand on suit un raccourci du copilote qui QUITTE l'assistant (va sur un écran ou ouvre un objet),
// on pose un marqueur : la vue de DÉPART est 'assistant', et on note la vue d'arrivée attendue.
// Un bouton flottant « ↩ Copilote » apparaît alors sur l'écran d'arrivée, et UNIQUEMENT là :
// dès qu'on navigue ailleurs (menu, autre écran), il disparaît (choix Benjamin = visible tant qu'on
// reste sur l'écran où le raccourci a mené).
function assistantMarquerRetour(targetView){
  // On retient la vue d'arrivée ; si elle n'est pas fournie, on l'apprendra au 1er goView qui suit.
  window._assistantRetour = { cible: targetView||null, attente: !targetView };
}
function assistantRetourSync(){
  const m = window._assistantRetour;
  let host = document.getElementById('assistantRetourBtn');
  // Conditions d'affichage : marqueur présent ET on est sur la vue d'arrivée (jamais sur l'assistant lui-même).
  const surCible = m && !m.attente && view===m.cible && view!=='assistant';
  if(!surCible){
    if(host) host.remove();
    // si on est reparti ailleurs (ni la cible ni l'assistant en attente), on oublie le marqueur
    if(m && !m.attente && view!==m.cible){ window._assistantRetour=null; }
    return;
  }
  if(!host){
    host=document.createElement('button');
    host.id='assistantRetourBtn';
    host.setAttribute('type','button');
    host.onclick=assistantRetourGo;
    host.style.cssText='position:fixed;left:50%;transform:translateX(-50%);bottom:78px;z-index:55;'
      +'background:var(--bordeaux,#52252F);color:#fff;border:none;border-radius:22px;'
      +'padding:9px 18px;font-size:.9rem;font-weight:600;font-family:inherit;'
      +'box-shadow:0 4px 14px rgba(73,15,37,.28);cursor:pointer';
    host.innerHTML='↩ Retour au copilote';
    document.body.appendChild(host);
  }
}
function assistantRetourGo(){
  window._assistantRetour=null;
  const b=document.getElementById('assistantRetourBtn'); if(b) b.remove();
  if(typeof goView==='function') goView('assistant');
}
// Bouton de retour au fil. Rendu UNIQUEMENT si on vient du fil. Style discret, aligné à l'identité.
function _filRetourBanner(){
  if(!filRetourActif()) return '';
  return `<button class="btn ghost" onclick="filRetourGo()" title="Revenir à l'accueil"
    style="margin-bottom:10px;border-color:#e0d3c2;color:#7a4b2a">← Retour au fil</button>`;
}
// Clic : efface le marqueur et revient à l'accueil rafraîchi.
function filRetourGo(){
  window._filRetour = null;
  if(typeof goView==='function') goView('accueil');
}

// [SOURCE UNIQUE — extraction v903] Calcule le PLAN OPÉRATIONNEL détaillé (créneaux calés par parfum,
// ganache/coques/montage selon le rétroplanning) SANS toucher au DOM. Appelée par l'écran Production ET
// par le Copilote (_ordreProductionDuJour), garantissant des horaires identiques sans aucune manip.
// Effet de bord assumé : peuple window._prodAlertesParfums et window._planParfumCreneaux (via _agendaPlanOpSection
// au rendu) — ici on remplit aussi _planParfumCreneaux directement pour que le Copilote soit autonome.
// [FIX v1293] Petit garde-fou générique : borne la durée d'une promesse pour qu'une opération
// anormalement lente (ou bloquée) sur une base IndexedDB volumineuse ne gèle jamais tout l'écran
// Planning ni la carte « À produire » de l'accueil — elle échoue proprement (rejet) et le try/catch
// appelant s'en sort comme pour n'importe quelle autre erreur déjà tolérée.
function _withTimeout(p, ms){
  return Promise.race([
    p,
    new Promise((_,rej)=>setTimeout(()=>rej(new Error('timeout '+ms+'ms')), ms))
  ]);
}
async function _buildPlanOpAutonome(mut){
  let planOp=null;
  try{
    const recipesPlan = await db.recipes.toArray().catch(()=>[]);
    let tEtape=null; try{ tEtape = await prodTempsParEtapeParParfum(90); }catch(e){swallow(e,'_buildPlanOpAutonome')}
    let stockMob={}; try{ stockMob = await stockMobilisableParParfum(); }catch(e){swallow(e,'_buildPlanOpAutonome')}
    const ganacheCaleParCmd = {};
    const montageCaleParCmd = {};
    try{
      const orderIds = new Set();
      const marketParfums = {};
      (mut && mut.semaines ? mut.semaines : []).forEach(s=>{
        (s.parfums||[]).forEach(p=>(p.commandes||[]).forEach(c=>{
          if(c.orderId!=null){ orderIds.add(c.orderId); }
          else if(c.marche && c.marketId!=null){
            const key = 'mk'+c.marketId;
            const slot = (marketParfums[key] ||= { date:c.livraison, heure:null, parfumsQtes:[] });
            slot.parfumsQtes.push({ nom:p.nom, qte:c.qte });
          }
        }));
      });
      const _alertesParfums = [];
      const _clientsCache = await db.clients.toArray().catch(()=>[]);
      const _nomClient = cid => { const c=_clientsCache.find(x=>x.id===cid); return c ? [c.prenom,c.nom].filter(Boolean).join(' ') : ''; };
      // [FIX v1293] AVANT : une commande à la fois (for..await séquentiel). Avec des mois d'historique,
      // le nombre de commandes dans l'horizon peut être important, et chaque retroplanningCale() fait
      // plusieurs allers-retours IndexedDB : en série, la somme des latences pouvait faire traîner —
      // voire sembler bloquer — tout l'écran Planning (et la carte « À produire » de l'accueil, qui
      // partage ce même moteur). On lance maintenant tout le lot EN PARALLÈLE (Promise.all), et un
      // garde-fou de 8 s par commande empêche qu'UNE commande anormale (boucle lente, données
      // corrompues) ne bloque indéfiniment tout le reste du plan — elle est simplement ignorée,
      // comme n'importe quelle erreur déjà tolérée par le try/catch existant.
      await Promise.all(Array.from(orderIds).map(async oid=>{
        try{
          const cale = await _withTimeout(retroplanningCale(oid), 8000);
          if(cale && cale.ok && Array.isArray(cale.jalonsCales)){
            const jg = cale.jalonsCales.find(j=>(j.cle==='ganache'||j.cle==='cremeux') && j.debut);
            if(jg) ganacheCaleParCmd[oid] = { debut:jg.debut, fin:jg.fin };
            const jm = cale.jalonsCales.find(j=>j.cle==='montage' && j.debut);
            if(jm) montageCaleParCmd[oid] = { debut:jm.debut, fin:jm.fin };
            const debuts = cale.jalonsCales.filter(j=>j.debut).map(j=>new Date(j.debut).getTime()).filter(t=>!isNaN(t));
            const debutProd = debuts.length ? new Date(Math.min(...debuts)).toISOString() : null;
            const o = await db.orders.get(oid).catch(()=>null);
            if(o){
              const sp = _sansParfumTotalDe(o);
              if(sp.total>0){
                _alertesParfums.push({ id:oid, client:_nomClient(o.clientId)||'', sansParfum:sp.total, taille:sp.taille, debutProduction:debutProd });
              }
            }
          }
        }catch(e){swallow(e,'_buildPlanOpAutonome')}
      }));
      window._prodAlertesParfums = detecterCommandesADeterminer(_alertesParfums);
      const _markets = await db.markets.toArray().catch(()=>[]);
      await Promise.all(Object.keys(marketParfums).map(async key=>{
        const mInfo = marketParfums[key];
        const mk = _markets.find(x=>('mk'+x.id)===key);
        const heure = mk ? _parseHeureMarche(mk.horaires, 8) : {h:8,m:0};
        const heureStr = String(heure.h).padStart(2,'0')+':'+String(heure.m).padStart(2,'0');
        try{
          const cale = await _withTimeout(retroplanningCaleParfums(mInfo.date, heureStr, mInfo.parfumsQtes, recipesPlan), 8000);
          if(cale && cale.ok && Array.isArray(cale.jalonsCales)){
            const jg = cale.jalonsCales.find(j=>(j.cle==='ganache'||j.cle==='cremeux') && j.debut);
            if(jg) ganacheCaleParCmd[key] = { debut:jg.debut, fin:jg.fin };
            const jm = cale.jalonsCales.find(j=>j.cle==='montage' && j.debut);
            if(jm) montageCaleParCmd[key] = { debut:jm.debut, fin:jm.fin };
          }
        }catch(e){swallow(e,'_buildPlanOpAutonome')}
      }));
    }catch(e){ console.error('preCollecteGanache', e); }
    planOp = buildPlanOperationnelSemaine(mut, recipesPlan, tEtape, stockMob, ganacheCaleParCmd, montageCaleParCmd);
    if(planOp && Array.isArray(planOp.semaines)){
      const _confAvail = (typeof getAvailability==='function') ? getAvailability() : null;
      for(const s of planOp.semaines){
        try{ s.faisabilite = await _faisabiliteSemaine(s.wk, _confAvail); }
        catch(_){ s.faisabilite = null; }
      }
      // [AUTONOMIE COPILOTE] On peuple directement le registre des créneaux par parfum (sans attendre le
      // rendu HTML _agendaPlanOpSection), pour que _ordreProductionDuJour soit utilisable sans ouvrir l'écran.
      window._planParfumCreneaux = window._planParfumCreneaux || {};
      planOp.semaines.forEach(s=>{
        if(!s.wk) return;
        const _etapes = [];
        (s.ganache||[]).forEach(g=>{ if(g && g.debut) _etapes.push({ type:'ganache', parfum:g.parfum, debut:g.debut, fin:g.fin, qte:(g.qteProduite||g.qte||0) }); });
        (s.coques||[]).forEach(m=>{ if(m && m.debut) _etapes.push({ type:'coques', repartition:m.repartition||null, debut:m.debut, fin:m.finCuisson||m.fin, congeler:!!m.congeler }); });
        (s.montage||[]).forEach(g=>{ if(g && g.debut) _etapes.push({ type:'montage', parfum:g.parfum, debut:g.debut, fin:g.fin, qte:(g.qteProduite||g.qte||0), besoinNet:(+g.qte||0) }); });
        window._planParfumCreneaux[s.wk] = _etapes;
      });
    }
  }catch(e){ console.error('planOperationnel',e); }
  return planOp;
}
async function renderAgendaProduction(){
  const main = document.getElementById('main');
  // [v1252] Cache recettes à jour : la section « fournées par couleur » lit les couleurs des recettes.
  try{ if(typeof refreshRecipesCache==='function') await refreshRecipesCache(); }catch(e){swallow(e,'renderAgendaProduction')}
  // [FIX v1293 — SAUT DE PAGE] AVANT : le premier affichage (état « calcul en cours ») ne contenait
  // qu'un titre minimal, puis le second affichage (résultat) ajoutait D'UN COUP la bannière « ← Retour
  // au fil », le bouton Actualiser et tout le contenu — un empilement de nouveaux éléments cliquables
  // tout en haut de l'écran, pile là où le doigt vient de taper pour ouvrir Planning. Un tap qui arrive
  // pendant/juste après ce remaniement pouvait retomber sur « ← Retour au fil » et renvoyer à l'accueil,
  // donnant l'impression d'un crash. On affiche maintenant la MÊME ossature (titre + bannière + bouton
  // Actualiser) dès le premier paint, immuable ; seul le corps ci-dessous (#prodBody) est remplacé une
  // fois le calcul terminé — plus aucun élément cliquable n'apparaît par surprise en haut de l'écran.
  main.innerHTML = `<div class="topbar"><div><h1>Planning</h1><p>Toutes tes commandes, planifiées par jour selon tes plages A/B</p></div>
      <button class="btn ghost" onclick="prodActualiser()" title="Synchroniser l'écran avec l'heure réelle">🔄 Actualiser</button></div>
    ${_filRetourBanner()}
    <div id="prodBody"><p class="note" style="margin-top:14px">⏳ Calcul du rétroplanning de chaque commande…</p></div>`;

  // Besoins cumulés par parfum et par jour (fondation mutualisation) — affichés en tête.
  let ppj=null;
  try{ ppj = await buildParfumsParJour(45); }catch(e){ console.error('parfumsParJour',e); }
  let mut=null;
  try{ mut = await buildMutualisationSemaine(45); }catch(e){ console.error('mutualisationSemaine',e); }

  // Plan opérationnel détaillé parfum par parfum (étape 1 du moteur). Temps : mesuré si fiable,
  // sinon recette, sinon défaut.
  // [FIX v1293] Garde-fou global (60 s) en plus des garde-fous par commande déjà posés dans
  // _buildPlanOpAutonome : si malgré tout le calcul ne revient jamais, l'écran affiche un état
  // dégradé au lieu de rester bloqué indéfiniment sur « Calcul du rétroplanning… ».
  let planOp = null;
  try{ planOp = await _withTimeout(_buildPlanOpAutonome(mut), 60000); }
  catch(e){ console.error('planOp (timeout global)', e); }

  // Vue COMMANDES REPLIABLES : une carte par commande (client + chevron), dépliant l'enchaînement
  // complet de ses étapes calées. Remplace le déroulé jour-par-jour pour la lisibilité.
  let cr=null;
  try{ cr = await buildCommandesRetro(45, mut); }catch(e){ console.error('commandesRetro',e); }

  const nbCmd = cr && cr.commandes ? cr.commandes.length : 0;
  // [FIX v1293] On ne touche plus qu'au corps (#prodBody, retrouvé via le DOM courant — l'utilisateur
  // a pu naviguer entre-temps, d'où la vérification) : le titre, la bannière et le bouton Actualiser
  // restent exactement les mêmes éléments DOM du début à la fin, sans réapparition ni déplacement.
  const _topP = main.querySelector ? main.querySelector('.topbar p') : null;
  if(_topP) _topP.textContent = `${nbCmd} commande(s) à produire · ${cr?cr.horizonJours:45} prochains jours`;
  const _body = document.getElementById('prodBody');
  if(_body){
    _body.innerHTML = `${_prodBarreVivante()}
    ${_prodRaccourciPlanning()}
    ${_prodAlerteParfums()}
    <p class="note" style="margin-bottom:14px">Touche le nom d'une commande pour déplier toutes ses étapes (coques, ganache, repos, montage, maturation, livraison), puis une étape pour son rétroplanning détaillé.</p>
    ${_optimBatchToggle()}
    ${_agendaPlanOpSection(planOp)}
    ${_agendaMutualSection(mut)}
    ${_agendaCouleurSection(mut)}
    ${_agendaParfumsSection(ppj)}
    ${_agendaCommandesSection(cr)}`;
  }
  // [SAUT CONTEXTUEL] Si on est arrivé ici via planFocusTache, positionne le plan sur la bonne semaine.
  if(typeof _planConsumeFocus==='function') _planConsumeFocus();
}
// Section « Besoins par parfum et par jour » : cumul de toutes les commandes (croisées), pour
// préparer la mutualisation. Affiche, par jour de montage, chaque parfum et la quantité totale,
// avec le nombre de commandes concernées (★ = mutualisable car ≥ 2 commandes le même jour).
function _agendaParfumsSection(ppj){
  if(!ppj || !ppj.jours || !ppj.jours.length) return '';
  const jours = ppj.jours.map(j=>{
    const lignes = j.parfums.map(p=>{
      const mutual = p.nbCommandes>=2;
      const detail = p.commandes.map(c=>`${esc(c.client)} (${c.qte})`).join(', ');
      return `<div class="sum-box" style="align-items:flex-start">
        <div style="flex:1">
          <div><b>${esc(p.nom)}</b> · <b style="color:var(--caramel,#AA7C39)">${p.qte}</b> macaron${p.qte>1?'s':''}
            ${mutual?`<span style="background:#3f7d52;color:#fff;font-size:.6rem;font-weight:600;padding:1px 6px;border-radius:7px">★ ${p.nbCommandes} cmd à regrouper</span>`:''}</div>
          <div style="font-size:.78rem;color:#9a8576;margin-top:2px">${esc(detail)}</div>
        </div>
      </div>`;
    }).join('');
    return `<div class="panel" style="margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #e8dccd;padding-bottom:6px;margin-bottom:8px">
        <h3 style="margin:0;text-transform:capitalize">${esc(j.label)}</h3>
        <span style="font-size:.78rem;color:#9a8576">${j.totalJour} macaron${j.totalJour>1?'s':''}</span>
      </div>
      ${lignes}
    </div>`;
  }).join('');
  return `<details style="margin-bottom:16px">
    <summary style="cursor:pointer;font-weight:600;color:var(--bordeaux);font-size:.95rem;padding:6px 0">📊 Besoins par parfum et par jour <span style="font-weight:400;color:#9a8576;font-size:.82rem">· cumul de toutes les commandes (★ = regroupable)</span></summary>
    <div style="margin-top:10px">${jours}</div>
  </details>`;
}
// [AGENDA CONSOLIDÉ] Fusionne le rétroplanning calé de TOUTES les commandes à venir en un agenda
// de production groupé par jour. Ne retient que les tâches de TRAVAIL (présence requise) : coques,
// ganache, crémeux, montage — pas les attentes (repos, maturation) qui ne mobilisent pas l'atelier.
// Renvoie { jours:[{date:'YYYY-MM-DD', label, taches:[{heure, cle, label, commande, clientNom, fin, plage}]}], conflits:[...] }.


// [PLAN OPÉRATIONNEL — affichage] Section dépliable montrant, par semaine, le détail PARFUM PAR PARFUM
// de chaque étape (ganache, coques, montage) avec quantité, temps et source du temps (mesuré/recette/défaut).
// [OPTIMISATION BATCH] Interrupteur visible dans l'agenda. ON = arrondi aux paliers (30/60/120,
// surplus au stock) ; OFF = quantités commandées exactes. À activer selon le temps de prod dispo.
function _optimBatchToggle(){
  const on = (typeof getOptimBatch==='function') ? getOptimBatch() : false;
  return `<div class="panel" style="margin-bottom:12px;padding:12px 14px;background:${on?'#f3eefb':'#faf8f3'};border:1px solid ${on?'#d8c8ef':'#e8e0d0'}">
    <label class="switch-row" style="margin:0;cursor:pointer">
      <input type="checkbox" ${on?'checked':''} onchange="toggleOptimBatch(this.checked)">
      <span><b>📦 Optimisation des batchs</b> ${on?'<span style="color:#7a5cab;font-weight:600">activée</span>':'<span style="color:#9a8576">désactivée</span>'}</span>
    </label>
    <p class="note" style="margin:6px 0 0 0;font-size:.78rem">${on
      ? 'Les petites commandes sont arrondies au palier rationnel (30, 60 ou 120). Le surplus part au stock. Désactive quand le temps de prod est trop serré : les commandes seules primeront.'
      : 'Tu produis exactement les quantités commandées. Active quand tu as le temps : les fournées seront arrondies à 30 minimum (le surplus alimente ton stock).'}</p>
  </div>`;
}
function toggleOptimBatch(on){
  if(typeof setOptimBatch==='function') setOptimBatch(!!on);
  if(typeof renderAgendaProduction==='function') renderAgendaProduction();
  else if(typeof goView==='function') goView('agenda');
}

// [FAISABILITÉ — BANDEAU] Rend le verdict d'une semaine. CLIQUABLE : déplie le planning heure par
// heure de CETTE semaine (le « comment » naît du verdict — pas de fonction juxtaposée). vert « tient »,
// orange « déborde ». Rien si pas de dispo (on n'affiche pas de faux verdict). fa = _faisabiliteSemaine.
function _faisabiliteBandeau(fa, wk){
  if(!fa) return '';
  if(!(fa.tempsDispo>0)){
    return `<div style="margin-top:6px;font-size:.74rem;color:#9a8576">⏱ Disponibilité non définie sur cette semaine — <span class="act" onclick="availEditor()">définir mes créneaux</span> pour vérifier que ça tient.</div>`;
  }
  const fmtH = m => m>=60 ? `${Math.floor(m/60)}h${String(Math.round(m%60)).padStart(2,'0')}` : `${Math.round(m)} min`;
  const wkAttr = esc(wk||'');
  const bg = fa.depassement ? '#fdf4e6' : '#eef6ee';
  const col = fa.depassement ? '#8a5a0f' : '#3f7d52';
  const verdict = fa.depassement
    ? `⚠️ <b>Ça déborde de ${fmtH(fa.debordementMin)}</b> sur tes créneaux (${fmtH(fa.tempsTotal)} à faire pour ${fmtH(fa.tempsDispo)} dispo · ${fa.chargePct}%).`
    : `✓ <b>Tient dans tes créneaux</b> (${fmtH(fa.tempsTotal)} à faire pour ${fmtH(fa.tempsDispo)} dispo · ${fa.chargePct}%).`;
  const cta = fa.depassement ? 'comment l\'organiser ? →' : 'voir le déroulé →';
  // [FIX onclick] On passe wk entre guillemets SIMPLES (l'attribut onclick est en guillemets doubles).
  // JSON.stringify produisait des guillemets DOUBLES qui fermaient l'attribut → handler cassé, aucun
  // tap. On échappe apostrophe/antislash pour les semaines au libellé exotique. Même garde-fou que les
  // onclick du plan détaillé (clés plutôt que noms à apostrophe).
  const wkJs = escJs(wk||'');   // [v1329] helper unique (l'ordre antislash → apostrophe est critique)
  return `<div class="faiz-band" data-wk="${wkAttr}" onclick="planSemaineToggle('${wkJs}', this)"
      style="margin-top:8px;padding:8px 11px;border-radius:9px;font-size:.78rem;background:${bg};color:${col};cursor:pointer;display:flex;align-items:center;gap:8px;user-select:none">
      <span style="flex:1">${verdict}</span>
      <span class="faiz-cta" style="font-weight:700;text-decoration:underline;text-underline-offset:2px;white-space:nowrap">${cta}</span>
      <span class="faiz-chev" style="font-size:.95rem;transition:transform .2s">›</span>
    </div>
    <div class="faiz-depli" data-wk="${wkAttr}" style="display:none;margin-top:8px"></div>`;
}

// [DÉPLI PLANNING SEMAINE] Génère/affiche le planning heure par heure d'UNE semaine au clic sur son
// verdict. Réutilise la chaîne existante (generateProductionOrder + schedulePersonalPlan), alimentée
// AUTOMATIQUEMENT par les dates de la semaine et tes vraies plages A/B — aucune re-saisie, aucune
// modale : le « comment » se déplie sous le « ça tient / ça déborde ». Source de vérité unique.
async function planSemaineToggle(wk, bandEl){
  if(!bandEl) return;
  const depli = bandEl.parentElement.querySelector(`.faiz-depli[data-wk="${(wk||'').replace(/"/g,'')}"]`)
             || bandEl.nextElementSibling;
  const chev = bandEl.querySelector('.faiz-chev');
  if(!depli) return;
  // Repli si déjà ouvert.
  if(depli.style.display!=='none' && depli.dataset.loaded==='1'){
    depli.style.display='none'; if(chev) chev.style.transform='';
    return;
  }
  if(chev) chev.style.transform='rotate(90deg)';
  depli.style.display='block';
  if(depli.dataset.loaded==='1') return;   // déjà généré, on ré-ouvre simplement
  depli.innerHTML = `<div style="font-size:.78rem;color:#9a8576;padding:6px 2px">⏳ Construction du déroulé…</div>`;
  try{
    const res = await _planSemaineGenere(wk);
    depli.innerHTML = res;
    depli.dataset.loaded = '1';
  }catch(e){
    console.error('planSemaineToggle', e);
    depli.innerHTML = `<div style="font-size:.78rem;color:#b04a3e;padding:6px 2px">Impossible de générer le déroulé de cette semaine.</div>`;
  }
}

// [SAUT CONTEXTUEL — CARTE « TÂCHE DU MOMENT »] Ouvre le plan de Production ET le positionne sur la
// SEMAINE de la tâche : déplie son bandeau de faisabilité (réutilise planSemaineToggle, source unique),
// fait défiler jusqu'à lui et le surligne brièvement. Pas d'ancrage au pixel sur une sous-tâche (les
// tâches n'ont pas d'id propre) : on amène au bon CONTEXTE déjà déplié, prêt à lire/lancer — ce qui
// supprime la re-navigation. Si la date est inconnue, on ouvre simplement le plan (fallback gracieux).
//
// dateTacheISO : date de début de la tâche (ex. début de prod d'une commande). parfum : optionnel,
// pour un futur surlignage plus fin. L'intention est posée puis consommée en fin de renderAgendaProduction.
// ============================================================================================
// [COCKPIT — étape 3, niveau A] Focus contextuel GÉNÉRIQUE : amener à l'objet précis d'un écran par
// scroll + surbrillance (sans pré-filtrer l'écran). Calqué sur le pattern éprouvé planFocusTache :
// on pose une intention de focus, on navigue, et l'écran cible la consomme à son rendu en cherchant
// l'élément qui porte l'attribut data-focus="type:valeur". Robuste : si l'élément n'existe pas, on
// ne fait rien de visible (l'écran reste ouvert normalement).
function aiFocusGo(view, type, val){
  window._viewFocus = (view && type && val!=null) ? { view, type, val:String(val) } : null;
  if(typeof goView==='function') goView(view);
}
// À appeler au DÉBUT du rendu d'un écran susceptible de recevoir un focus. Cherche l'élément marqué
// data-focus="type:valeur", scrolle dessus et le surligne brièvement. `viewName` = nom de l'écran
// courant (pour ne consommer le focus que sur le bon écran). Consommé une seule fois.
function _consumeViewFocus(viewName){
  const f = window._viewFocus;
  if(!f || f.view!==viewName) return;
  window._viewFocus = null;   // une seule fois
  setTimeout(()=>{
    try{
      const valClean = String(f.val).replace(/"/g,'');
      // 1) Match exact sur data-focus="type:valeur".
      let el = document.querySelector(`[data-focus="${f.type}:${valClean}"]`);
      // 2) Repli tolérant (casse + accents) : on compare la valeur normalisée de chaque candidat.
      if(!el && typeof aiNormalize==='function'){
        const cible = aiNormalize(valClean);
        const cands = document.querySelectorAll(`[data-focus^="${f.type}:"]`);
        for(const c of cands){
          const v = (c.getAttribute('data-focus')||'').slice(f.type.length+1);
          if(aiNormalize(v)===cible){ el = c; break; }
        }
      }
      if(!el) return;   // objet absent de cet écran : on laisse l'écran tel quel
      el.scrollIntoView({ behavior:'smooth', block:'center' });
      const old = el.style.boxShadow;
      el.style.transition = 'box-shadow .3s';
      el.style.boxShadow = '0 0 0 3px rgba(170,124,57,.6)';
      setTimeout(()=>{ el.style.boxShadow = old||''; }, 1700);
    }catch(e){ console.error('_consumeViewFocus', e); }
  }, 80);
}
// ============================================================================================
function planFocusTache(dateTacheISO, parfum, mode){
  if(typeof filMarquerOrigine==='function') filMarquerOrigine();   // on vient du fil → bouton « ← Retour au fil »
  const wk = (typeof _isoWeekKey==='function') ? _isoWeekKey(dateTacheISO) : null;
  // mode : 'avance' = après dépli, scroller jusqu'au déroulé d'étapes et surligner la 1re tâche lançable.
  //        (par défaut) = on s'arrête au bandeau de la semaine (comportement carte « tâche du moment »).
  window._planFocusPending = wk ? { wk, parfum: parfum||null, mode: mode||null } : null;
  if(typeof goView==='function') goView('agendaprod');
}
// Consomme une éventuelle intention de focus après le rendu du plan : trouve le bandeau de la semaine,
// le déplie s'il ne l'est pas, scrolle dessus et le surligne. Robuste : si le bandeau n'existe pas
// (semaine hors plan), on ne fait rien de visible (le plan reste ouvert normalement).
function _planConsumeFocus(){
  const intent = window._planFocusPending;
  if(!intent || !intent.wk) return;
  window._planFocusPending = null;   // consommée une seule fois
  // Laisse le DOM se peindre, puis cible le bandeau de la bonne semaine.
  setTimeout(()=>{
    try{
      const sel = `.faiz-band[data-wk="${String(intent.wk).replace(/"/g,'')}"]`;
      const band = document.querySelector(sel);
      if(!band) return;   // semaine absente du plan : on laisse le plan ouvert tel quel
      // Déplie si ce n'est pas déjà fait (planSemaineToggle gère la génération du déroulé).
      const depli = band.nextElementSibling;
      const dejaOuvert = depli && depli.classList.contains('faiz-depli') && depli.style.display!=='none' && depli.dataset.loaded==='1';
      if(!dejaOuvert && typeof planSemaineToggle==='function'){
        planSemaineToggle(intent.wk, band);
      }
      band.scrollIntoView({ behavior:'smooth', block:'start' });
      // Surlignage bref pour matérialiser « c'est ici ».
      const oldShadow = band.style.boxShadow;
      band.style.transition = 'box-shadow .3s';
      band.style.boxShadow = '0 0 0 3px rgba(170,124,57,.55)';
      setTimeout(()=>{ band.style.boxShadow = oldShadow||''; }, 1600);
      // [MODE AVANCE] On ne s'arrête pas au bandeau : on amène à la 1re ÉTAPE CONCRÈTE à lancer.
      // Le dépli est généré en async par planSemaineToggle → on attend qu'il soit chargé, puis on
      // cible la 1re sum-box cliquable (onclick planLancer…ByKey = la tâche la plus en amont).
      if(intent.mode==='avance'){
        const depliBox = band.nextElementSibling;
        _planFocusPremiereEtape(depliBox, 0);
      }
    }catch(e){ console.error('_planConsumeFocus', e); }
  }, 60);
}
// Attend (poll borné) que le déroulé de la semaine soit généré, puis scrolle sur la PREMIÈRE étape
// concrète lançable et la surligne. tries = nombre d'essais déjà faits (borne anti-boucle).
function _planFocusPremiereEtape(depliBox, tries){
  if(!depliBox || tries>40) return;   // ~4 s max (40 × 100 ms) puis abandon silencieux
  const pret = depliBox.classList && depliBox.classList.contains('faiz-depli')
            && depliBox.dataset && depliBox.dataset.loaded==='1';
  if(!pret){ setTimeout(()=>_planFocusPremiereEtape(depliBox, tries+1), 100); return; }
  const etape = depliBox.querySelector('.sum-box[onclick^="planLancer"]');
  if(!etape) return;   // pas d'étape lançable (rien à avancer) : on laisse la semaine dépliée telle quelle
  etape.scrollIntoView({ behavior:'smooth', block:'center' });
  const old = etape.style.boxShadow;
  etape.style.transition = 'box-shadow .3s';
  etape.style.boxShadow = '0 0 0 3px rgba(170,124,57,.7)';
  setTimeout(()=>{ etape.style.boxShadow = old||''; }, 1900);
}


// daySpecs = vraies plages A/B de chaque jour de la semaine (depuis aujourd'hui pour la semaine en cours).
// [DIAGNOSTIC niveau 2] Pour chaque parfum, la date de livraison la PLUS PROCHE parmi les commandes
// non livrées de la fenêtre [debut, fin]. Sert à dire, pour une tâche qui déborde, de combien de marge
// on dispose avant l'échéance réelle (« livré le 15 → 3 jours de marge »). Lecture directe de db.orders
// car le plan agrège les besoins sans garder la trace des dates. Renvoie { parfum: 'YYYY-MM-DD' }.
// ============================================================================================
// [REPORT MANUEL — socle de données, étape 1] Helpers de gestion des overrides de planification.
// Aucune UI ici : ces fonctions posent les fondations. Tant qu'aucun override n'est créé (l'UI
// viendra plus tard), le plan reste strictement inchangé.
// --------------------------------------------------------------------------------------------
// Bornes (lundi, dimanche) d'une semaine ISO 'AAAA-Www', en chaînes 'AAAA-MM-JJ'. Helper pur,
// même construction que _planSemaineGenere (factorisé pour éviter la divergence).
function _wkBornes(wk){
  const m = /(\d{4})-W(\d{2})/.exec(wk||'');
  if(!m) return null;
  const simple = new Date(Date.UTC(+m[1],0,1+(+m[2]-1)*7));
  const dow = (simple.getUTCDay()+6)%7;
  const lundi = new Date(simple); lundi.setUTCDate(simple.getUTCDate()-dow);
  const dim = new Date(lundi); dim.setUTCDate(lundi.getUTCDate()+6);
  return { lundiStr: ymdLocal(lundi), dimStr: ymdLocal(dim) };
}
// Semaine ISO suivante. Robuste aux changements d'année : on reconstruit le lundi de la semaine
// donnée, on ajoute 7 jours, et on recalcule la clé ISO via _isoWeekKey (source de vérité unique).
function _semaineSuivante(wk){
  const m = /(\d{4})-W(\d{2})/.exec(wk||'');
  if(!m) return null;
  // Lundi de la semaine ISO (même construction que _planSemaineGenere).
  const simple = new Date(Date.UTC(+m[1],0,1+(+m[2]-1)*7));
  const dow = (simple.getUTCDay()+6)%7;
  const lundi = new Date(simple); lundi.setUTCDate(simple.getUTCDate()-dow);
  lundi.setUTCDate(lundi.getUTCDate()+7);   // +1 semaine
  const iso = ymdLocal(lundi);
  return (typeof _isoWeekKey==='function') ? _isoWeekKey(iso) : null;
}
// Crée (ou remplace) un override de report du montage d'un parfum, de wkSource vers wkSource+1.
// Unicité logique sur (wkSource, parfum, etape) : on supprime un éventuel doublon avant d'insérer.
async function planOverrideAdd(wkSource, parfum, etape){
  etape = etape || 'montage';
  const wkCible = _semaineSuivante(wkSource);
  if(!wkSource || !parfum || !wkCible) return null;
  try{
    // Supprime un override existant pour le même (wkSource, parfum, etape) — un seul actif à la fois.
    const dejas = await db.planOverrides.where('wkSource').equals(wkSource).toArray();
    for(const o of dejas){ if(o.parfum===parfum && (o.etape||'montage')===etape){ await db.planOverrides.delete(o.id); } }
    const rec = { wkSource, wkCible, parfum, etape, createdTs: new Date().toISOString() };
    const id = await db.planOverrides.add(rec);
    return { id, ...rec };
  }catch(e){ console.error('planOverrideAdd', e); return null; }
}
// Supprime l'override de report du montage d'un parfum pour une semaine source donnée (annulation).
async function planOverrideRemove(wkSource, parfum, etape){
  etape = etape || 'montage';
  try{
    const dejas = await db.planOverrides.where('wkSource').equals(wkSource).toArray();
    let n=0;
    for(const o of dejas){ if(o.parfum===parfum && (o.etape||'montage')===etape){ await db.planOverrides.delete(o.id); n++; } }
    return n;
  }catch(e){ console.error('planOverrideRemove', e); return 0; }
}
// Lit les overrides CONCERNANT une semaine donnée : ceux qui PARTENT d'elle (wkSource) et ceux qui
// ARRIVENT dans elle (wkCible). Le scheduler s'en sert pour retirer/injecter les montages.
async function planOverridesForWeek(wk){
  try{
    const sortants = await db.planOverrides.where('wkSource').equals(wk).toArray();
    const tous = await db.planOverrides.toArray();
    const entrants = tous.filter(o=> o.wkCible===wk);
    return { sortants, entrants };
  }catch(e){ console.error('planOverridesForWeek', e); return { sortants:[], entrants:[] }; }
}
// ============================================================================================

async function _datesLivraisonParParfum(debut, fin){
  const out = {};
  let orders = [];
  try{ orders = await db.orders.toArray(); }catch(_){ return out; }
  orders.forEach(o=>{
    if(!o || !o.date) return;
    if(typeof normStatus==='function' && normStatus(o.statut)==='Livrée') return;
    // On élargit la fenêtre vers le futur : une commande de la semaine peut être livrée plus tard.
    if(o.date < debut) return;
    let dem = {};
    try{ dem = (typeof _orderParfumDemand==='function') ? _orderParfumDemand(o) : {}; }catch(_){ dem = {}; }
    for(const parfum in dem){
      if(+dem[parfum] <= 0) continue;
      if(!out[parfum] || o.date < out[parfum]) out[parfum] = o.date;
    }
  });
  // [NIVEAU 2 #3 — MARCHÉS] Un besoin peut aussi venir d'un marché programmé (quantité prévue à
  // emporter), pas seulement d'une commande. On ventile chaque marché futur par parfum via la
  // répartition apprise (marketForecast), même pattern que le calcul de besoins, et on retient la
  // date la plus proche entre commandes ET marchés. Sans historique de répartition, on ne peut pas
  // attribuer la date à un parfum précis → on s'abstient (pas de fausse échéance).
  try{
    const markets = await db.markets.toArray();
    const futureMarkets = markets.filter(m=> m && m.date && m.date>=debut && m.statut!=='clos' && (+m.prevuQte||0)>0);
    // [COHÉRENCE PLAN] Le plan n'intègre les marchés QUE si l'historique est fiable (≥ SEUIL_MARCHE_FIABLE
    // marchés clos, cf. _pseudoCommandeDepuisMarche). On applique le MÊME seuil ici : sinon une tâche marché
    // afficherait une échéance alors qu'elle n'est pas dans le plan. Même source de vérité, pas de « 5 » en dur.
    const nbMarchesClos = markets.filter(m=> m && m.statut==='clos').length;
    const seuilOk = (typeof SEUIL_MARCHE_FIABLE==='number') ? (nbMarchesClos >= SEUIL_MARCHE_FIABLE) : (nbMarchesClos >= 5);
    if(futureMarkets.length && seuilOk){
      let repartition = [];
      try{ const mf = await marketForecast(); repartition = (mf && mf.repartition) ? mf.repartition : []; }catch(_){ repartition = []; }
      const totPct = repartition.reduce((s,r)=>s+(+r.pct||0),0);
      if(repartition.length && totPct>0){
        futureMarkets.forEach(m=>{
          repartition.forEach(r=>{
            if((+r.pct||0)<=0) return;
            const parfum = r.parfum;
            if(!parfum) return;
            if(!out[parfum] || m.date < out[parfum]) out[parfum] = m.date;
          });
        });
      }
    }
  }catch(_){ /* marchés indisponibles : on garde les dates issues des commandes */ }
  return out;
}

async function _planSemaineGenere(wk){
  const m = /(\d{4})-W(\d{2})/.exec(wk||'');
  if(!m) return '<div style="font-size:.78rem;color:#9a8576">Semaine non reconnue.</div>';
  const simple = new Date(Date.UTC(+m[1],0,1+(+m[2]-1)*7));
  const dow = (simple.getUTCDay()+6)%7;
  const lundi = new Date(simple); lundi.setUTCDate(simple.getUTCDate()-dow);
  const dim = new Date(lundi); dim.setUTCDate(lundi.getUTCDate()+6);
  const lundiStr = ymdLocal(lundi);
  const dimStr = ymdLocal(dim);
  const todayStr = today().slice(0,10);
  const debut = (lundiStr < todayStr) ? todayStr : lundiStr;

  // Plan de besoins de la semaine (commandes + marchés + stock), via le moteur commun.
  // [POOL 14 j] L'ordre du jour anticipe la demande des 14 jours suivant la fenêtre : grâce à la
  // congélation des macarons assemblés, on peut produire maintenant pour amortir les lancements de
  // batch sans risque DLC. La FAISABILITÉ (verdict 7 j) reste calculée à part, sur la fenêtre stricte.
  const POOL_HORIZON_JOURS = 14;
  const plan = await generateProductionOrder(debut, dimStr, 0, null, {poolHorizonJours:POOL_HORIZON_JOURS});
  if(!plan || !plan.lignes.length){
    return `<div style="font-size:.8rem;color:#3f7d52;background:#eef6ee;padding:8px 10px;border-radius:8px">✓ Rien à produire cette semaine : ton stock couvre déjà commandes et marchés.</div>`;
  }
  // daySpecs = vraies plages de travail de chaque jour (lundi→dimanche, depuis aujourd'hui).
  const conf = (typeof getAvailability==='function') ? getAvailability() : null;
  const daySpecs = [];
  const cur = new Date(debut+'T00:00:00');
  const end = new Date(dimStr+'T00:00:00');
  let guard = 0;
  while(cur <= end && guard++ < 60){
    const dateStr = ymdLocal(cur);
    const slots = (typeof availSlotsForDate==='function') ? availSlotsForDate(cur, conf) : [];
    const slotsMin = (slots||[]).map(([s,e])=>[hmToMin(s), hmToMin(e)]).filter(([a,b])=>b>a);
    if(slotsMin.length) daySpecs.push({ date:dateStr, slots:slotsMin });
    cur.setDate(cur.getDate()+1);
  }
  if(!daySpecs.length){
    return `<div style="font-size:.78rem;color:#9a8576;padding:6px 2px">Aucune plage de travail définie sur cette semaine. <span class="act" onclick="availEditor()">Définir mes créneaux →</span></div>`;
  }
  // [REPORT MANUEL — étape 2] On lit les overrides de planification concernant cette semaine :
  //   SORTANTS  = montages reportés HORS de wk → on les retire (skipMontage), coques+ganache restent.
  //   ENTRANTS  = montages reportés VERS wk depuis wk-1 → on les rajoute, soit en FUSIONNANT avec le
  //               montage natif du même parfum (besoins additionnés, un seul temps fixe), soit en
  //               INJECTANT un montage seul si le parfum n'a pas de natif dans wk.
  let _schedOpts = {};
  let _overridesWk = { sortants:[], entrants:[] };
  try{
    const ov = await planOverridesForWeek(wk);
    _overridesWk = ov || _overridesWk;
    if(ov && (ov.sortants.length || ov.entrants.length)){
      // SORTANTS : montage retiré de cette semaine.
      if(ov.sortants.length) _schedOpts.skipMontage = ov.sortants.map(o=>o.parfum);
      // ENTRANTS : il faut le besoin net SOURCE de chaque parfum reporté → on regénère le plan de la
      // semaine source (bornes via _wkBornes), une seule fois par semaine source distincte.
      if(ov.entrants.length){
        const injectMontages = [];
        const planSourceCache = {};
        for(const e of ov.entrants){
          let planSrc = planSourceCache[e.wkSource];
          if(planSrc===undefined){
            const b = _wkBornes(e.wkSource);
            try{ planSrc = b ? await generateProductionOrder(b.lundiStr, b.dimStr, 0) : null; }
            catch(_){ planSrc = null; }
            planSourceCache[e.wkSource] = planSrc;
          }
          const ligneSrc = planSrc && planSrc.lignes ? planSrc.lignes.find(l=>l.parfum===e.parfum) : null;
          const besoinSrc = ligneSrc ? (+ligneSrc.besoinNet||0) : 0;
          if(besoinSrc<=0) continue;   // plus rien à monter pour ce parfum en source : report sans objet
          const ligneCible = plan.lignes.find(l=>l.parfum===e.parfum);
          if(ligneCible){
            // FUSION : le parfum est DÉJÀ natif en S+1 (donc sa ganache fraîche est déjà prévue, temps
            // fixe par parfum). Seul le MONTAGE dépend de la quantité → on le recalcule sur le besoin
            // combiné (natif + reporté), un seul temps fixe. La ganache native couvre le parfum.
            ligneCible.tMontage = await _montageDureeParfum(e.parfum, (+ligneCible.besoinNet||0) + besoinSrc);
            ligneCible._montageFusionne = besoinSrc;   // trace pour l'affichage (étape 4)
          }else{
            // INJECTION : le parfum n'a pas de commande native en S+1. On injecte sa GANACHE FRAÎCHE
            // (temps fixe depuis la ligne source) + son MONTAGE. Ses coques, elles, sont congelées (S).
            const dur = await _montageDureeParfum(e.parfum, besoinSrc);
            injectMontages.push({
              parfum:e.parfum, dur, besoinNet:besoinSrc, fromWk:e.wkSource,
              tGanache: ligneSrc ? (+ligneSrc.tGanache||0) : 0,
              ganacheDelaiH: ligneSrc ? (+ligneSrc.ganacheDelaiH||0) : 0
            });
          }
        }
        if(injectMontages.length) _schedOpts.injectMontages = injectMontages;
      }
    }
  }catch(e){ console.error('overrides _planSemaineGenere', e); _schedOpts = {}; }

  const S = schedulePersonalPlan(daySpecs, plan, _schedOpts);
  // [niveau 2] Dates de livraison par parfum (marge réelle avant échéance) pour enrichir le diagnostic.
  let datesLiv = {};
  if(!S.ok){ try{ datesLiv = await _datesLivraisonParParfum(debut, dimStr); }catch(_){ datesLiv = {}; } }
  // [SIMULATION « et si »] On mémorise le contexte de CETTE semaine pour pouvoir rejouer le scheduler
  // (en mémoire, sans toucher db) quand l'utilisateur teste « et si je reporte ce montage ? ».
  window._planSimCtx = window._planSimCtx || {};
  window._planSimCtx[wk] = { daySpecs, plan, debut, fin:dimStr, datesLiv, schedOpts:_schedOpts };
  // [ÉTAPE 4] Bandeau des reports actifs concernant cette semaine : sortants (montage parti en S+1,
  // avec annulation) et entrants (montage reçu de S-1, coques congelées). Rendu en tête du dépli.
  let bandeauReports = '';
  const _wkSafe = escJs(wk);   // [v1329] AVANT : l'apostrophe était SUPPRIMÉE du nom (donnée mutilée)
  if(_overridesWk.sortants && _overridesWk.sortants.length){
    bandeauReports += _overridesWk.sortants.map(o=>{
      const pSafe = escJs(o.parfum);   // [v1329] AVANT : &#39; — le navigateur le REDÉCODE en apostrophe avant de compiler le JS. La « protection » ne protégeait rien.
      return `<div style="display:flex;align-items:center;gap:8px;background:#f3eef7;border:1px solid #d9c9e6;border-radius:8px;padding:6px 9px;font-size:.76rem;color:#5b3a78;margin-bottom:4px">
        <span style="flex:1">↩ <b>${esc(o.parfum)}</b> : montage reporté à la semaine suivante. Ici tu produis seulement ses coques (❄️ congelées).</span>
        <button class="btn ghost sm" onclick="planAnnulerReport('${_wkSafe}','${pSafe}')" title="Annuler ce report">✕ Annuler</button>
      </div>`;
    }).join('');
  }
  if(_overridesWk.entrants && _overridesWk.entrants.length){
    bandeauReports += _overridesWk.entrants.map(o=>
      `<div style="background:#eef4ef;border:1px solid #c4ddc9;border-radius:8px;padding:6px 9px;font-size:.76rem;color:#256b2f;margin-bottom:4px">
        ↩❄️ <b>${esc(o.parfum)}</b> : reporté depuis la semaine précédente. Ganache refaite fraîche ici, coques décongelées (cuites avant).
      </div>`
    ).join('');
  }
  return bandeauReports + _planSemaineRenderHTML(S, plan, datesLiv, wk);
}

// [REPORT MANUEL — étape 3] Génère le PLANNING BRUT (objet S de schedulePersonalPlan) d'une semaine
// donnée, avec des options scheduler optionnelles (skipMontage / injectMontages). Autonome : reconstruit
// bornes + plan de besoins + créneaux, sans passer par le rendu HTML. Sert aux garde-fous (tester si
// une semaine déborde, avec ou sans un report intégré). Renvoie { S, plan, daySpecs } ou null.
async function _planSemaineSchedule(wk, extraOpts){
  const b = _wkBornes(wk);
  if(!b) return null;
  const todayStr = (typeof today==='function') ? today().slice(0,10) : ymdLocal(new Date());
  const debut = (b.lundiStr < todayStr) ? todayStr : b.lundiStr;
  let plan;
  try{ plan = await generateProductionOrder(debut, b.dimStr, 0); }catch(_){ return null; }
  if(!plan || !plan.lignes || !plan.lignes.length) return { S:{ ok:true, totalActive:0, totalAvail:0, events:[], unplaced:[] }, plan:plan||{lignes:[]}, daySpecs:[] };
  const conf = (typeof getAvailability==='function') ? getAvailability() : null;
  const daySpecs = [];
  const cur = new Date(debut+'T00:00:00'); const end = new Date(b.dimStr+'T00:00:00');
  let guard=0;
  while(cur<=end && guard++<60){
    const dateStr = ymdLocal(cur);
    const slots = (typeof availSlotsForDate==='function') ? availSlotsForDate(cur, conf) : [];
    const slotsMin = (slots||[]).map(([s,e])=>[hmToMin(s), hmToMin(e)]).filter(([a,b2])=>b2>a);
    if(slotsMin.length) daySpecs.push({ date:dateStr, slots:slotsMin });
    cur.setDate(cur.getDate()+1);
  }
  const S = schedulePersonalPlan(daySpecs, plan, extraOpts||{});
  return { S, plan, daySpecs };
}

// [REPORT MANUEL — étape 3] Vérifie si reporter le montage de `parfum` de `wkSource` vers wkSource+1
// est acceptable. Renvoie un verdict structuré que l'UI (étape 4) utilise pour décider :
//   { wkCible, retard:{en, dateLiv}, cibleDeborde:{avant, apres}, bloquant, avertissements[] }
// - RETARD (Q1) : si le lundi de la semaine cible tombe APRÈS l'échéance de livraison du parfum →
//   avertissement NON bloquant (Benjamin confirme), conformément à la décision « avertir mais permettre ».
// - CIBLE DÉBORDE (Q2) : si la semaine cible déborde DÉJÀ (avant report) OU déborderait APRÈS avoir
//   reçu le report → BLOQUANT (on n'empile pas un montage sur une semaine qui ne tient pas).
async function planReportVerifier(wkSource, parfum){
  const wkCible = _semaineSuivante(wkSource);
  const verdict = { wkSource, wkCible, parfum, retard:null, cibleDeborde:null, bloquant:false, avertissements:[] };
  if(!wkCible){ verdict.bloquant = true; verdict.avertissements.push('Semaine cible introuvable.'); return verdict; }

  // --- Q1 : retard de livraison -------------------------------------------------------------
  try{
    const b = _wkBornes(wkSource);
    const datesLiv = b ? await _datesLivraisonParParfum(b.lundiStr, '2999-12-31') : {};
    const dateLiv = datesLiv[parfum] || null;
    const bCible = _wkBornes(wkCible);
    if(dateLiv && bCible && dateLiv < bCible.lundiStr){
      // La livraison est due AVANT même que la semaine cible ne commence → report = retard.
      verdict.retard = { dateLiv, debutCible: bCible.lundiStr };
      verdict.avertissements.push(`⚠ Ce report met la livraison de ${parfum} en retard (due le ${dateLiv}, production reportée à la semaine du ${bCible.lundiStr}).`);
    }
  }catch(e){ console.error('planReportVerifier Q1', e); }

  // --- Q2 : la semaine cible déborde-t-elle ? -----------------------------------------------
  try{
    // État AVANT : la semaine cible telle quelle.
    const av = await _planSemaineSchedule(wkCible, {});
    const debordeAvant = !!(av && av.S && av.S.ok===false);
    // État APRÈS : la semaine cible AVEC le report intégré (voie 1 : ganache fraîche + montage ;
    // les coques viennent congelées de la source). On récupère la LIGNE SOURCE complète (besoin +
    // temps ganache + repos), pas seulement le besoin, pour ne pas sous-estimer le débordement.
    const ligneSrc = await (async()=>{
      const bs = _wkBornes(wkSource);
      try{ const ps = bs ? await generateProductionOrder(bs.lundiStr, bs.dimStr, 0) : null;
        return ps && ps.lignes ? ps.lignes.find(x=>x.parfum===parfum) : null;
      }catch(_){ return null; }
    })();
    const besoinSrc = ligneSrc ? (+ligneSrc.besoinNet||0) : 0;
    let debordeApres = debordeAvant;
    if(av && av.plan && besoinSrc>0){
      const ligneCible = av.plan.lignes.find(l=>l.parfum===parfum);
      let opts = {};
      if(ligneCible){
        // FUSION : le parfum est natif en cible (ganache déjà prévue, temps fixe) → seul le montage
        // grossit sur le besoin combiné.
        ligneCible.tMontage = await _montageDureeParfum(parfum, (+ligneCible.besoinNet||0)+besoinSrc);
      } else {
        // INJECTION : ganache FRAÎCHE (temps fixe source) + montage, comme en production réelle (voie 1).
        const dur = await _montageDureeParfum(parfum, besoinSrc);
        opts = { injectMontages:[{ parfum, dur, besoinNet:besoinSrc, fromWk:wkSource,
          tGanache: (+ligneSrc.tGanache||0), ganacheDelaiH: (+ligneSrc.ganacheDelaiH||0) }] };
      }
      const apres = schedulePersonalPlan(av.daySpecs, av.plan, opts);
      debordeApres = !!(apres && apres.ok===false);
    }
    if(debordeAvant || debordeApres){
      verdict.cibleDeborde = { avant:debordeAvant, apres:debordeApres };
      verdict.bloquant = true;
      verdict.avertissements.push(debordeAvant
        ? `⛔ La semaine du ${_wkBornes(wkCible).lundiStr} déborde déjà : inutile d'y reporter un montage.`
        : `⛔ Reporter ${parfum} ferait déborder la semaine cible. Le report ne ferait que déplacer le problème.`);
    }
  }catch(e){ console.error('planReportVerifier Q2', e); }

  return verdict;
}

// Rend le HTML du résultat schedulePersonalPlan (mot du chef + déroulé par jour), version « dépli ».
// [DIAGNOSTIC DE RÉORGANISATION — niveau 1] Quand une semaine déborde, transforme le constat en
// conseil actionnable : nomme ce qui ne rentre pas, puis propose des leviers CLASSÉS par pertinence,
// chacun avec son POURQUOI. S'appuie uniquement sur des données sûres (tâches non placées + recettes
// du plan), pas d'approximation. Renvoie '' si la semaine tient (ok).
// [SIMULATION « et si » — niveau 2] Rejoue le scheduler de la semaine `wk` en REPORTANT le montage du
// parfum donné (coques + ganache restent produites). Tout est calculé EN MÉMOIRE depuis le contexte
// mémorisé (_planSimCtx) : aucune écriture en base, aucune modification du plan réel. Affiche le verdict
// (la semaine rentre-t-elle ?) et le planning re-simulé dans le conteneur dédié.
function planSimReportMontage(wk, parfum){
  const ctx = (window._planSimCtx||{})[wk];
  const cont = document.getElementById('planSimResult-'+String(wk).replace(/[^0-9A-Za-z\-]/g,''));
  if(!ctx){ if(cont) cont.innerHTML = `<div style="font-size:.74rem;color:#9a8576">Contexte de simulation expiré, rouvre le plan.</div>`; return; }
  let Sav, Ssim;
  try{
    const baseOpts = ctx.schedOpts || {};
    // État actuel = celui réellement affiché (overrides inclus).
    Sav  = schedulePersonalPlan(ctx.daySpecs, ctx.plan, baseOpts);
    // État simulé = on AJOUTE le parfum testé aux montages déjà retirés (sans écraser les overrides).
    const baseSkip = (baseOpts.skipMontage instanceof Set) ? [...baseOpts.skipMontage]
                   : (Array.isArray(baseOpts.skipMontage) ? baseOpts.skipMontage.slice() : []);
    if(!baseSkip.includes(parfum)) baseSkip.push(parfum);
    Ssim = schedulePersonalPlan(ctx.daySpecs, ctx.plan, { ...baseOpts, skipMontage: baseSkip });
  }catch(e){ console.error('planSimReportMontage', e); if(cont) cont.innerHTML = `<div style="font-size:.74rem;color:#a52a2a">Erreur de simulation.</div>`; return; }
  const fmtH = m => m>=60 ? `${Math.floor(m/60)}h${String(Math.round(m%60)).padStart(2,'0')}` : `${Math.round(m)} min`;
  const manqueAv  = Math.max(0, (Sav.totalActive||0)  - (Sav.totalAvail||0));
  const manqueSim = Math.max(0, (Ssim.totalActive||0) - (Ssim.totalAvail||0));
  const gagne = manqueAv - manqueSim;   // minutes de débordement résorbées par le report
  let verdict;
  if(Ssim.ok){
    verdict = `<div style="background:#eef6ee;border:1px solid #bcdcc0;border-radius:8px;padding:8px 10px;font-size:.8rem;color:#256b2f">
      ✓ <b>En reportant le montage ${esc(parfum)}, la semaine rentre.</b> Tu produis ses coques et sa ganache maintenant, tu l'assembles plus tard.</div>`;
  } else {
    verdict = `<div style="background:#fdf6ee;border:1px solid #e8cfa6;border-radius:8px;padding:8px 10px;font-size:.8rem;color:#8a5a0f">
      ↩ Reporter ${esc(parfum)} libère <b>${fmtH(gagne)}</b>, mais il reste <b>${fmtH(manqueSim)}</b> de trop. Reporte aussi un autre montage ou ajoute du créneau.</div>`;
  }
  // Planning re-simulé (sans le diagnostic récursif : on passe un wk vide pour éviter de re-greffer des boutons).
  let planningHTML = '';
  try{ planningHTML = _planSemaineRenderHTML(Ssim, ctx.plan, ctx.datesLiv, null); }catch(e){swallow(e,'planSimReportMontage')}
  // [ÉTAPE 4] Bouton « Appliquer » : visible dès que le report aide (la semaine rentre, ou il gagne du
  // temps). L'application réelle passe par planAppliquerReport qui revérifie les garde-fous avant d'agir.
  const peutAider = Ssim.ok || gagne>0;
  const wkSafe = escJs(wk);    // [v1329] AVANT : l'apostrophe était SUPPRIMÉE du nom (donnée mutilée)
  const pSafe = escJs(parfum);     // [v1329] AVANT : &#39; — redécodé en apostrophe par le navigateur → le bouton cassait quand même.
  const btnAppliquer = peutAider
    ? `<button class="btn" onclick="planAppliquerReport('${wkSafe}','${pSafe}')" style="margin-top:6px;background:#256b2f;color:#fff;border:none">✓ Appliquer ce report</button>`
    : '';
  if(cont){
    cont.innerHTML = `${verdict}
      <div style="margin-top:6px;border-left:3px solid #AA7C39;padding-left:9px">
        <div style="font-size:.72rem;color:#9a7a4a;margin-bottom:3px;font-weight:600">Semaine simulée (montage ${esc(parfum)} reporté) :</div>
        ${planningHTML}
      </div>
      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px">
        ${btnAppliquer}
        <button class="btn ghost sm" onclick="this.closest('[id^=planSimResult-]').innerHTML=''">✕ Fermer la simulation</button>
      </div>
      <div id="planReportApplyMsg-${wkSafe.replace(/[^0-9A-Za-z\-]/g,'')}" style="margin-top:6px"></div>`;
  }
}

// [ÉTAPE 4] Applique réellement un report : revérifie les garde-fous (planReportVerifier), puis crée
// l'override en base (planOverrideAdd) et rafraîchit le plan. Q1 (retard livraison) = avertissement
// confirmable ; Q2 (cible déborde) = bloquant. Tout passe par une confirmation explicite.
async function planAppliquerReport(wk, parfum){
  const msgBox = document.getElementById('planReportApplyMsg-'+String(wk).replace(/[^0-9A-Za-z\-]/g,''));
  const showMsg = (html)=>{ if(msgBox) msgBox.innerHTML = html; };
  try{
    showMsg(`<div style="font-size:.74rem;color:#9a8576">Vérification en cours…</div>`);
    const v = await planReportVerifier(wk, parfum);
    if(!v){ showMsg(`<div style="font-size:.74rem;color:#a52a2a">Vérification impossible.</div>`); return; }
    // Q2 bloquant : la semaine cible ne peut pas recevoir ce report.
    if(v.bloquant){
      showMsg(`<div style="background:#fdecea;border:1px solid #f0b6ae;border-radius:8px;padding:8px 10px;font-size:.78rem;color:#a52a2a">${v.avertissements.join('<br>')}</div>`);
      return;
    }
    // Q1 non bloquant : s'il y a un avertissement de retard, on demande confirmation.
    if(v.avertissements && v.avertissements.length){
      const ok = confirm(v.avertissements.join('\n\n') + '\n\nAppliquer quand même ce report ?');
      if(!ok){ showMsg(''); return; }
    }
    const rec = await planOverrideAdd(wk, parfum, 'montage');
    if(!rec){ showMsg(`<div style="font-size:.74rem;color:#a52a2a">Le report n'a pas pu être enregistré.</div>`); return; }
    if(typeof toast==='function') toast(`Report appliqué : montage ${parfum} → semaine suivante`);
    // Rafraîchit le plan pour refléter le report (la semaine source et la cible changent).
    if(typeof renderAgendaProduction==='function'){ try{ await renderAgendaProduction(); }catch(e){swallow(e,'planAppliquerReport')} }
  }catch(e){ console.error('planAppliquerReport', e); showMsg(`<div style="font-size:.74rem;color:#a52a2a">Erreur lors de l'application du report.</div>`); }
}

// [ÉTAPE 4] Annule un report (supprime l'override) : le plan redevient automatique pour ce parfum.
async function planAnnulerReport(wk, parfum){
  try{
    if(typeof confirm==='function'){
      const ok = confirm(`Annuler le report du montage ${parfum} ? Le plan redeviendra automatique (montage et ganache reviennent dans la semaine d'origine).`);
      if(!ok) return;
    }
    const n = await planOverrideRemove(wk, parfum, 'montage');
    if(typeof toast==='function') toast(n>0 ? `Report annulé : ${parfum} revient dans la semaine` : 'Aucun report à annuler');
    if(typeof renderAgendaProduction==='function'){ try{ await renderAgendaProduction(); }catch(e){swallow(e,'planAnnulerReport')} }
  }catch(e){ console.error('planAnnulerReport', e); if(typeof toast==='function') toast('Erreur lors de l\'annulation'); }
}

function _diagReorganisation(S, plan, datesLiv, wk){
  if(!S || S.ok || !Array.isArray(S.unplaced) || !S.unplaced.length) return '';
  datesLiv = datesLiv || {};
  const fmtH = m => m>=60 ? `${Math.floor(m/60)}h${String(Math.round(m%60)).padStart(2,'0')}` : `${Math.round(m)} min`;
  const manqueMin = Math.max(0, (S.totalActive||0) - (S.totalAvail||0));
  const lignesParParfum = {};
  (plan.lignes||[]).forEach(l=>{ lignesParParfum[l.parfum] = l; });
  // Date de référence = aujourd'hui (pour calculer une marge en jours jusqu'à la livraison).
  const todayStr = (typeof today==='function') ? today().slice(0,10) : ymdLocal(new Date());
  const joursEntre = (d1, d2) => {
    try{ return Math.round((new Date(d2+'T00:00') - new Date(d1+'T00:00')) / 86400000); }catch(_){ return null; }
  };
  const fmtDateCourt = ds => { try{ return new Date(ds+'T00:00').toLocaleDateString('fr-FR',{day:'2-digit',month:'short'}); }catch(_){ return ds; } };

  const ganachesOut = S.unplaced.filter(u=>u.type==='ganache');
  const montagesOut = S.unplaced.filter(u=>u.type==='montage');

  const leviers = [];

  // LEVIER 1 — Anticiper les ganaches qui supportent un repos long.
  const ganachesReposLong = ganachesOut.filter(u=>{
    const l = lignesParParfum[u.parfum];
    return l && +l.ganacheDelaiH > 0;
  });
  if(ganachesReposLong.length){
    const noms = ganachesReposLong.map(u=>u.parfum);
    const minLib = ganachesReposLong.reduce((s,u)=>s+(u.dur||0),0);
    const delaiMax = Math.max(...ganachesReposLong.map(u=>+(lignesParParfum[u.parfum]?.ganacheDelaiH)||0));
    leviers.push({
      titre: `Prépare ${noms.length>1?'ces ganaches':'la ganache '+noms[0]} la veille au soir.`,
      pourquoi: `${noms.length>1?'Elles supportent':'Elle supporte'} ${delaiMax} h de repos : ${noms.length>1?'les sortir':'la sortir'} du jour du montage libère ${fmtH(minLib)} au pic de charge.`,
      action: null
    });
  }

  // LEVIER 2 — Repousser les montages, avec la MARGE RÉELLE jusqu'à la livraison (niveau 2).
  if(montagesOut.length){
    // On enrichit chaque montage de sa date de livraison la plus proche, si connue.
    const details = montagesOut.map(u=>{
      const dLiv = datesLiv[u.parfum] || null;
      const marge = dLiv ? joursEntre(todayStr, dLiv) : null;
      return { parfum:u.parfum, dur:u.dur, dLiv, marge };
    });
    // Trie par marge décroissante : ceux qui ont le plus de marge sont les meilleurs candidats à repousser.
    details.sort((a,b)=> (b.marge==null?-1:b.marge) - (a.marge==null?-1:a.marge));
    const minM = montagesOut.reduce((s,u)=>s+(u.dur||0),0);
    // Construit un pourquoi précis selon ce qu'on sait des échéances.
    const avecMarge = details.filter(d=>d.marge!=null && d.marge>=2);
    let pourquoi;
    if(avecMarge.length){
      const d = avecMarge[0];
      const autres = avecMarge.length>1 ? ` (et ${avecMarge.length-1} autre${avecMarge.length>2?'s':''})` : '';
      pourquoi = `${d.parfum} n'est livré que le ${fmtDateCourt(d.dLiv)} — ${d.marge} jours de marge${autres}. Le produire la semaine suivante ne met aucune livraison en retard.`;
    } else if(details.some(d=>d.marge!=null && d.marge<=1)){
      pourquoi = `${fmtH(minM)} de montage ne rentrent pas, mais ${details.find(d=>d.marge!=null&&d.marge<=1).parfum} est dû très bientôt — à traiter en priorité, pas à repousser.`;
    } else {
      pourquoi = `${fmtH(minM)} de montage ne rentrent pas. Vérifie les dates de livraison : ce qui n'est pas dû tout de suite peut passer plus tard.`;
    }
    const noms = details.map(d=>d.parfum);
    // [SIMULATION « et si »] Pour chaque montage qui a de la MARGE (≥2 j), un bouton qui rejoue le
    // scheduler sans ce montage et affiche le verdict + la semaine re-simulée. wk requis (contexte).
    let simBtns = '';
    if(wk){
      const reportables = details.filter(d=>d.marge!=null && d.marge>=2);
      if(reportables.length){
        simBtns = `<div style="margin-top:5px;display:flex;flex-wrap:wrap;gap:5px">`
          + reportables.map(d=>`<button class="btn ghost sm" onclick="planSimReportMontage('${escJs(wk)}','${escJs(d.parfum)}')" title="Tester : reporter ce montage à plus tard">🔬 Et si je reporte ${esc(d.parfum)} ?</button>`).join('')
          + `</div><div id="planSimResult-${String(wk).replace(/[^0-9A-Za-z\-]/g,'')}" style="margin-top:6px"></div>`;
      }
    }
    leviers.push({
      titre: `Repousse ${noms.length>1?'un montage':'le montage '+noms[0]} si l'échéance le permet.`,
      pourquoi,
      action: simBtns || null
    });
  }

  // LEVIER 3 — Ajouter du créneau (toujours, avec le montant exact).
  leviers.push({
    titre: `Ajoute ~${fmtH(manqueMin)} de créneau cette semaine.`,
    pourquoi: `Un créneau supplémentaire d'environ ${fmtH(manqueMin)} suffit à absorber le débordement — tout se recalcule au retour.`,
    action: `<button class="btn ghost sm" onclick="availEditor()" style="margin-top:4px">🗓️ Ajuster mes créneaux</button>`
  });

  // [NIVEAU 2 — échéance par tâche] On accole à CHAQUE tâche qui déborde (ganache/coques/montage,
  // pas seulement les montages) sa marge réelle jusqu'à la livraison la plus proche, via datesLiv déjà
  // calculé. Lecture immédiate : ce qui presse vs ce qui peut attendre. Sans date connue → rien d'accolé.
  const _echeanceTxt = u => {
    const dLiv = datesLiv[u.parfum] || null;
    if(!dLiv) return '';
    const marge = joursEntre(todayStr, dLiv);
    if(marge==null) return '';
    if(marge<=1) return ` <span style="color:#a52a2a;font-weight:600">· dû ${marge<=0?'aujourd’hui':'demain'} ⚠</span>`;
    return ` <span style="color:#3f7d52">· livré ${fmtDateCourt(dLiv)}, ${marge} j de marge</span>`;
  };
  const tousNoms = S.unplaced.map(u=>`${u.type==='ganache'?'🍫':u.type==='montage'?'🧩':'🥚'} ${esc(u.label)} (${fmtH(u.dur)})${_echeanceTxt(u)}`);
  const resume = tousNoms.join(' · ');

  const leviersHTML = leviers.map((lv,i)=>`
    <div style="display:flex;gap:9px;padding:7px 0;border-bottom:1px solid #f0e4cf">
      <div style="flex:0 0 22px;height:22px;border-radius:50%;background:#AA7C39;color:#fff;font-size:.74rem;font-weight:700;display:flex;align-items:center;justify-content:center">${i+1}</div>
      <div style="font-size:.8rem;line-height:1.4">
        <b>${lv.titre}</b>
        <div style="color:#9a7a4a;font-size:.74rem;margin-top:1px">${lv.pourquoi}</div>
        ${lv.action||''}
      </div>
    </div>`).join('');

  return `<div style="background:#fbf5ec;border:1px solid #ecd9b8;border-radius:10px;padding:11px 12px;margin-bottom:10px">
    <div style="font-size:.86rem;font-weight:600;color:var(--bordeaux);margin-bottom:3px">🔧 Comment faire rentrer la semaine</div>
    <div style="font-size:.74rem;color:#8a5a0f;margin-bottom:7px">Ne trouvent pas de place : ${resume}.</div>
    ${leviersHTML}
  </div>`;
}

function _planSemaineRenderHTML(S, plan, datesLiv, wk){
  if(!S) return '';
  const JOURS = ['dimanche','lundi','mardi','mercredi','jeudi','vendredi','samedi'];
  // [fix affichage] même précaution que _minToHM (planificateur perso) : arrondir avant
  // floor/modulo pour éviter un artefact flottant du type "08:54.10000000000002".
  const minToHM = mm => { mm=Math.round(+mm||0); return String(Math.floor(mm/60)).padStart(2,'0')+':'+String(mm%60).padStart(2,'0'); };
  const byDay = {}; (S.events||[]).forEach(e=>{ (byDay[e.date] ||= []).push(e); });
  const dayBlocks = Object.keys(byDay).sort().map(date=>{
    const d = new Date(date+'T00:00');
    const rows = byDay[date].map(e=>{
      const icon = e.kind==='coques'?'🥚':e.kind==='ganache'?'🍫':e.kind==='montage'?'🧩':'•';
      // Badge congélation explicite (calage horaire v854) : coques montées hors fenêtre de fraîcheur
      // ou recette à congélation obligatoire. Visible au premier coup d'œil, pas seulement dans la note.
      const congelBadge = e.congeler
        ? ` <span style="background:#3b6ea5;color:#fff;font-size:.56rem;font-weight:600;padding:1px 6px;border-radius:7px" title="Coques à congeler puis décongeler avant montage">❄️ congélation</span>`
        : '';
      return `<div class="perso-ev">
        <div class="perso-ev-time">${minToHM(e.start)}<br><span>${minToHM(e.end)}</span></div>
        <div class="perso-ev-body"><div class="perso-ev-lbl">${icon} ${esc(e.label)}${congelBadge}</div>
          ${e.note?`<div class="perso-ev-note">${esc(e.note)}</div>`:''}</div></div>`;
    }).join('');
    return `<div style="margin-top:6px"><div style="text-transform:capitalize;font-weight:600;color:var(--bordeaux);font-size:.86rem;border-bottom:1px solid #ece2d4;padding-bottom:3px;margin-bottom:2px">${JOURS[d.getDay()]} ${d.toLocaleDateString('fr-FR',{day:'2-digit',month:'long'})}</div>${rows}</div>`;
  }).join('');
  const insights = (S.insights||[]).map(t=>`<li>${esc(t)}</li>`).join('');
  const warn = (S.warnings&&S.warnings.length)
    ? `<div class="banner" style="background:#fdf3f2;border-color:#e5b4ae;margin-bottom:8px">⚠ <div>${S.warnings.map(esc).join('<br>')}</div></div>` : '';
  const chef = insights
    ? `<div style="background:#faf6ef;border-radius:10px;padding:9px 11px;margin-bottom:8px"><div style="font-size:.86rem;font-weight:600;color:var(--bordeaux);margin-bottom:4px">🧑‍🍳 Le mot du chef</div><ul class="perso-insights" style="font-size:.82rem">${insights}</ul></div>` : '';
  // Diagnostic de réorganisation (uniquement quand ça déborde), placé EN TÊTE car c'est le plus actionnable.
  const diag = (plan && !S.ok) ? _diagReorganisation(S, plan, datesLiv, wk) : '';
  return `${diag}${warn}${chef}${dayBlocks||'<div style="font-size:.78rem;color:#9a8576;padding:4px 2px">Aucune tâche planifiable avec ces créneaux.</div>'}`;
}

function _agendaPlanOpSection(plan){
  if(!plan || !plan.semaines || !plan.semaines.length) return '';
  const srcBadge = src => {
    const m = { 'mesuré':{t:'mesuré',c:'#3f7d52'}, 'recette':{t:'recette',c:'#8a6d3b'}, 'défaut':{t:'estimé',c:'#b08a3a'} }[src] || {t:src,c:'#9a8576'};
    return `<span style="background:${m.c};color:#fff;font-size:.54rem;font-weight:600;padding:0 5px;border-radius:6px">${m.t}</span>`;
  };
  const fmtMin = m => m>=60 ? `${Math.floor(m/60)}h${String(Math.round(m%60)).padStart(2,'0')}` : `${Math.round(m)} min`;
  // Pastille de couleur du parfum (réutilise flavorColor, cohérent avec le reste de l'app).
  const dot = nom => `<span style="display:inline-block;width:12px;height:12px;border-radius:50%;background:${(typeof flavorColor==='function')?flavorColor(nom):'#cbb89f'};border:1px solid rgba(0,0,0,.1);margin-right:7px;vertical-align:middle;flex:none"></span>`;
  // [POOL] Décomposition d'une fournée par commande : qui contribue (et reçoit) combien.
  // 2+ commandes = fournée réellement fusionnée → badge + détail « répartition retour ».
  const poolLigne = (commandes, surplusStock) => {
    const cmds = (commandes||[]).filter(c=>+c.qte>0);
    const surp = +surplusStock||0;
    const stockTxt = surp>0 ? ` <span style="color:#7a5cab">·</span> <span style="color:#7a5cab">📦 stock <b>${surp}</b></span>` : '';
    if(cmds.length<=1){
      const c = cmds[0];
      if(!c && surp<=0) return '';
      const cli = c ? `${esc(c.client)} · ${c.qte}` : '';
      return `<div style="font-size:.72rem;color:#9a8576;margin-top:2px;padding-left:19px">${cli}${stockTxt}</div>`;
    }
    const total = cmds.reduce((a,c)=>a+(+c.qte||0),0);
    const detail = cmds.map(c=>`${esc(c.client)} <b>${c.qte}</b>`).join(' <span style="color:#ccd">·</span> ');
    return `<div style="font-size:.72rem;color:#3b6ea5;margin-top:3px;padding-left:19px">
      <span style="background:#3b6ea5;color:#fff;font-size:.54rem;font-weight:600;padding:0 5px;border-radius:6px">🔗 fusionnée</span>
      <span style="color:#9a8576"> ${total+surp} = </span>${detail}${stockTxt}
      <span style="color:#9a8576"> → à répartir au montage</span>
    </div>`;
  };

  const semaines = plan.semaines.map(s=>{
    // [SOURCE UNIQUE — ordre du jour Copilote] On mémorise les créneaux calés PAR PARFUM (rétroplanning :
    // ganache/coques/montage avec leur Date réelle), tels qu'affichés ici. Le Copilote (_ordreProductionDuJour)
    // lit CE registre pour montrer exactement les mêmes horaires que cet écran — zéro divergence.
    if(s.wk){
      window._planParfumCreneaux = window._planParfumCreneaux || {};
      const _etapes = [];
      (s.ganache||[]).forEach(g=>{ if(g && g.debut) _etapes.push({ type:'ganache', parfum:g.parfum, debut:g.debut, fin:g.fin, qte:(g.qteProduite||g.qte||0) }); });
      (s.coques||[]).forEach(m=>{ if(m && m.debut) _etapes.push({ type:'coques', repartition:m.repartition||null, debut:m.debut, fin:m.finCuisson||m.fin, congeler:!!m.congeler }); });
      (s.montage||[]).forEach(g=>{ if(g && g.debut) _etapes.push({ type:'montage', parfum:g.parfum, debut:g.debut, fin:g.fin, qte:(g.qteProduite||g.qte||0), besoinNet:(+g.qte||0) }); });
      window._planParfumCreneaux[s.wk] = _etapes;
    }
    // GANACHE — chaque carte est CLIQUABLE : lance le batch ganache + chrono (avec confirmation).
    const ganache = s.ganache.map((gi_g,gi)=>{
      const g = gi_g;
      const _qLance = g.qteProduite||g.qte;
      // Créneau horaire calé (travail actif → fin), avec rappel du repos avant montage.
      const fmtHg = d => { try{ return new Date(d).toLocaleString('fr-FR',{weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}); }catch(e){ return ''; } };
      const horaireGan = g.debut
        ? `<div style="font-size:.72rem;color:#7a4b2a;margin-top:2px">🕐 <b>${fmtHg(g.debut)}</b> → fin <b>${(()=>{try{return new Date(g.fin).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});}catch(e){return '';}})()}</b>${g.reposH?` <span style="color:#9a8576">· puis repos ${g.reposH}h avant montage</span>`:''}${g._recale?` <span style="color:#9a8576">· enchaînée pour tenir le repos</span>`:''}</div>`
        : (g.horaireImpossible ? `<div style="font-size:.72rem;color:#b3261e;margin-top:2px">🕐 Pas de créneau dispo avant le montage (à anticiper)</div>` : '');
      // [FIX échappement préventif] Clé de registre plutôt que le nom du parfum dans l'attribut.
      window._planGanacheLanceReg = window._planGanacheLanceReg || {};
      const ganKey = `${s.wk||'wk'}_${gi}`;
      window._planGanacheLanceReg[ganKey] = { parfum:g.parfum, qte:(+_qLance)||0 };
      return `<div class="sum-box" style="flex-direction:column;align-items:stretch;cursor:pointer" onclick="planLancerGanacheByKey('${ganKey}')" title="Lancer la production de cette ganache + chrono">
      <div style="display:flex;align-items:center;width:100%">
        <div style="flex:1;display:flex;align-items:center">${dot(g.parfum)}<span><b style="text-transform:capitalize">${esc(g.parfum)}</b> · <span style="color:#7a4b2a">${g.qteProduite||g.qte} mac</span>${g.aMarche?` <span style="background:#c97a2a;color:#fff;font-size:.56rem;font-weight:600;padding:1px 6px;border-radius:7px" title="Contient une estimation marché (compo apprise sur l'historique)">⛺ estimé</span>`:''}${(g.surplusStock>0)?` <span style="background:#7a5cab;color:#fff;font-size:.56rem;font-weight:600;padding:1px 6px;border-radius:7px">📦 dont ${g.surplusStock} stock</span>`:''}</span></div>
        <div style="display:flex;align-items:center;gap:5px"><span style="color:#aa7c39;font-size:.68rem;font-weight:600">▶ lancer</span><b>${fmtMin(g.dureeMin)}</b> ${srcBadge(g.source)}</div>
      </div>
      ${horaireGan}
      ${poolLigne(g.commandes, g.surplusStock)}
    </div>`;
    }).join('');
    // COQUES (meringues appariées) — CLIQUABLE : lance le(s) batch(s) coques + chrono(s).
    const coques = s.coques.map((m,i)=>{
      const rep = Object.entries(m.repartition).map(([p,q])=>`${dot(p)}${esc(p)} <b>${q}</b>`).join(' <span style="color:#c9b8a4">+</span> ');
      const detailTemps = (m.actifMin!=null && m.cuissonMin!=null)
        ? `<div style="font-size:.7rem;color:#9a8576;margin-top:1px">🙋 ${m.actifMin} min actif${m.chablonMin>0?` <span style="color:#3f7d52">(dont 🖌 ${m.chablonMin} min chablonnage)</span>`:''} · 🔥 ${m.cuissonMin} min four (${m.nbPlaques} pl.)</div>` : '';
      // Horaire calé dans les vraies plages A/B (début travail → fin cuisson).
      const fmtH = d => { try{ return new Date(d).toLocaleString('fr-FR',{weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}); }catch(e){ return ''; } };
      const horaireCale = m.debut
        ? `<div style="font-size:.72rem;color:#3f7d52;margin-top:2px">🕐 <b>${fmtH(m.debut)}</b> → fin cuisson <b>${(()=>{try{return new Date(m.finCuisson||m.fin).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});}catch(e){return '';}})()}</b>${m.congeler?`<br><span style="display:inline-block;white-space:nowrap;background:#3b6ea5;color:#fff;font-size:.56rem;font-weight:600;padding:2px 8px;border-radius:7px;margin-top:3px">❄️ à congeler</span>`:''}</div>`
        : (m.congeler?`<div style="font-size:.72rem;color:#3b6ea5;margin-top:2px">❄️ à congeler (pas de place dans la fenêtre de fraîcheur)</div>`:'');
      // [FIX échappement] On ne sérialise plus la répartition dans l'attribut onclick : esc() encode
      // les guillemets en &quot;, que le navigateur redécode en " au clic — ce qui cassait la chaîne JS
      // et rendait l'encart coques inerte. À la place, on stocke la répartition dans un registre global
      // et on ne passe qu'une CLÉ (robuste à tous les noms de parfums). Même pattern que la ganache.
      window._planMeringueReg = window._planMeringueReg || {};
      const repKey = `${s.wk||'wk'}_${i}`;
      window._planMeringueReg[repKey] = m.repartition;
      return `<div class="sum-box" style="cursor:pointer" onclick="planLancerMeringueByKey('${repKey}', ${i})" title="Lancer les coques de cette meringue + chrono">
        <div style="flex:1">🥣 Meringue ${i+1} · ${rep}${m.partielle?' <span style="color:#b08a3a;font-size:.7rem">(partielle)</span>':''}${detailTemps}${horaireCale}</div>
        <div style="text-align:right"><span style="color:#aa7c39;font-size:.68rem;font-weight:600;display:block">▶ lancer</span><b>${fmtMin(m.dureeMin)}</b></div>
      </div>`;
    }).join('');
    // MONTAGE
    const montage = s.montage.map((g,mi)=>{
      const specTxt = (g.specMin>0 && g.specDetail && g.specDetail.length)
        ? `<div style="font-size:.7rem;color:#8a6d3b;margin-top:2px;padding-left:19px">⚙️ +${fmtMin(g.specMin)} : ${g.specDetail.map(d=>esc(d.nom)+' '+fmtMin(d.min)).join(' · ')}</div>` : '';
      const _qMont = g.qteProduite||g.qte;
      // Créneau horaire de montage calé (pivot du rétroplanning), affiché comme la ganache.
      const fmtHg = d => { try{ return new Date(d).toLocaleString('fr-FR',{weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}); }catch(e){ return ''; } };
      const horaireMont = g.debut
        ? `<div style="font-size:.72rem;color:#3f7d52;margin-top:2px">🕐 <b>${fmtHg(g.debut)}</b>${g.fin?` → fin <b>${(()=>{try{return new Date(g.fin).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});}catch(e){return '';}})()}</b>`:''}${g._enchaine?` <span style="color:#9a8576">· enchaîné (un montage à la fois)</span>`:''}</div>`
        : '';
      // [FIX échappement préventif] Même principe que coques/ganache : pas de nom de parfum réinjecté
      // dans l'attribut (un parfum « Fleur d'oranger » casserait l'onclick à apostrophe). On passe une clé.
      window._planMontageReg = window._planMontageReg || {};
      const montKey = `${s.wk||'wk'}_${mi}`;
      window._planMontageReg[montKey] = { parfum:g.parfum, qte:(+_qMont)||0 };
      return `<div class="sum-box" style="flex-direction:column;align-items:stretch;cursor:pointer" onclick="planLancerMontageByKey('${montKey}')" title="Assembler ce parfum (coques + garniture déjà produites)">
      <div style="display:flex;align-items:center;width:100%">
        <div style="flex:1;display:flex;align-items:center;flex-wrap:wrap">${dot(g.parfum)}<span><b style="text-transform:capitalize">${esc(g.parfum)}</b> · <span style="color:#3f7d52">${g.qteProduite||g.qte} mac</span>${g.aMarche?` <span style="background:#c97a2a;color:#fff;font-size:.56rem;font-weight:600;padding:1px 6px;border-radius:7px" title="Contient une estimation marché (compo apprise sur l'historique)">⛺ estimé</span>`:''}${(g.surplusStock>0)?` <span style="background:#7a5cab;color:#fff;font-size:.56rem;font-weight:600;padding:1px 6px;border-radius:7px" title="${g.qte} commandés + ${g.surplusStock} pour le stock">📦 dont ${g.surplusStock} stock</span>`:''} <span style="color:#9a8576;font-size:.72rem">(${g.parBatchMin}/batch)</span>${(()=>{ const _lq=(typeof lignesParParfum==='object'&&lignesParParfum)?lignesParParfum[g.parfum]:null; const _am=_lq?(+_lq.couvertAssemblable||+_lq.aMonter||0):0; return _am>0?` <span style="background:#c98b4b;color:#fff;font-size:.56rem;font-weight:600;padding:1px 6px;border-radius:7px" title="${_am} macaron(s) quasi-finis : coques + ganache déjà en stock, il reste seulement à les monter. Ce n'est PAS du stock fini.">🔧 dont ${_am} à monter</span>`:''; })()}${(g.stock>0)?`<div style="font-size:.7rem;color:#9a8576;width:100%;margin-top:1px">commandé <b>${g.qte}</b> · 📦 en stock <b style="color:#3f7d52">${g.stock}</b> · à produire <b>${g.besoinNet}</b></div>`:''}</span></div>
        <div style="display:flex;align-items:center;gap:5px"><span style="color:#3f7d52;font-size:.68rem;font-weight:600">▶ monter</span>${
          g.rienAMonter
            ? `<b style="color:#3f7d52">✓ déjà en stock</b>`
            : `<b>${fmtMin(g.dureeMin)}</b>`
        } ${srcBadge(g.source)}</div>
      </div>
      ${(!g.rienAMonter && (g.qteCommande>0 || g.qteReassort>0))
        ? `<div style="font-size:.72rem;color:#9a8576;margin-top:2px">🔧 ${g.qteProduite} à monter${
            (g.qteReassort>0)
              ? ` · <b style="color:#3f7d52">${g.qteCommande} commande</b> <span style="color:#c97a2a">+ ${g.qteReassort} réassort</span>`
              : `<span style="color:#3f7d52"> (commande)</span>`
          }</div>`
        : ''}
      ${horaireMont}
      ${specTxt}
      ${poolLigne(g.commandes, g.surplusStock)}
    </div>`;
    }).join('');

    return `<div class="panel" style="margin-bottom:14px">
      <div style="border-bottom:2px solid #d8c4a8;padding-bottom:8px;margin-bottom:12px">
        <h3 style="margin:0;font-size:1.25rem;color:var(--bordeaux);text-transform:capitalize;font-weight:700;line-height:1.2">${esc(s.label)}</h3>
        <div style="font-size:.76rem;color:#9a8576;margin-top:3px">
          <div><b style="color:#7a6a60">${s.totalMacaronsCommande}</b> macaron${s.totalMacaronsCommande>1?'s':''} pour commande${(s.totalMacaronsEnStock>0)?` <span style="font-size:.68rem;color:#9a8576">(dont ${s.totalMacaronsEnStock} en stock)</span>`:''}</div>
          ${(s.totalMacaronsReassort>0)?`<div style="color:#c97a2a"><b>${s.totalMacaronsReassort}</b> macaron${s.totalMacaronsReassort>1?'s':''} pour réassort</div>`:''}
          <div style="margin-top:1px">${fmtMin(s.totalMin)} de travail</div>
        </div>
        ${_faisabiliteBandeau(s.faisabilite, s.wk)}
      </div>
      <div style="margin-bottom:10px">
        <div style="font-weight:600;color:#7a4b2a;margin-bottom:4px">🍫 Ganaches <span style="font-weight:400;color:#9a8576;font-size:.76rem">· une par parfum · ${fmtMin(s.totalGanacheMin)}</span></div>
        ${ganache}
      </div>
      <div style="margin-bottom:10px">
        <div style="font-weight:600;color:#8a6d3b;margin-bottom:4px">🟤 Coques <span style="font-weight:400;color:#9a8576;font-size:.76rem">· meringues mutualisées · ${fmtMin(s.totalCoquesMin)}</span></div>
        ${coques}
      </div>
      <div>
        <div style="font-weight:600;color:#3f7d52;margin-bottom:4px">🔧 Montage <span style="font-weight:400;color:#9a8576;font-size:.76rem">· par parfum · ${fmtMin(s.totalMontageMin)}${(s.totalMontageQteReassort>0)?` <span style="color:#9a8576">(${s.totalMontageQteCommande} commande <span style="color:#c97a2a">+ ${s.totalMontageQteReassort} réassort</span> à monter)</span>`:''}</span></div>
        ${montage}
      </div>
    </div>`;
  }).join('');

  return `<details style="margin-bottom:16px" open>
    <summary style="cursor:pointer;font-weight:600;color:var(--bordeaux);font-size:.95rem;padding:6px 0">🧭 Plan de travail détaillé <span style="font-weight:400;color:#9a8576;font-size:.82rem">· étape par étape, parfum par parfum</span></summary>
    <div style="margin-top:10px">${semaines}</div>
  </details>`;
}

// [MUTUALISATION HEBDO] Panneau de synthèse par semaine : besoins cumulés par parfum (coques+montage
// mutualisés sur la semaine), délai de ganache, et plan de congélation/décongélation du surplus.
// [v1252] SECTION MUTUALISATION PAR COULEUR — regroupe, par semaine, les besoins de coques par
// couleur et propose des fournées de meringue (une fournée peut mêler plusieurs couleurs sous la
// capacité max). Vue PARALLÈLE : n'affecte pas le plan par parfum au-dessus.
function _agendaCouleurSection(mut){
  if(!mut || !mut.semaines || !mut.semaines.length) return '';
  const recList = window._allRecipesCache || [];
  const recByNom = {}; recList.forEach(r=>recByNom[aiNormalize(r.produitNom)]=r);
  const semainesHtml = mut.semaines.map(s=>{
    const besoins = (s.parfums||[]).map(p=>({nom:p.nom, qte:+p.qte||0})).filter(b=>b.qte>0);
    if(!besoins.length) return '';
    let planC; try{ planC = ordoPlanCouleur(besoins, recByNom); }catch(_){ return ''; }
    if(!planC.items.length) return '';
    const merHTML = (m,label,col)=>`<div class="sum-box" style="border-left:3px solid ${col};margin:4px 0;align-items:flex-start">
      <div style="flex:1"><b>${label}</b> <span style="color:#9a8576;font-size:.76rem">${m.utilise}/${m.cap} éq-mac</span>
        <div style="font-size:.84rem;margin-top:2px">${m.parts.map(p=>`${p.couleur?coqueCouleurPastille(p.couleur):''}${esc(p.nom)} <b>${p.qte}</b>`).join(' &nbsp;·&nbsp; ')}</div>
        ${m.parts.map(p=>{ if(!p.parfums) return ''; const det=Object.keys(p.parfums).map(nm=>`${esc(nm)} (${qty(p.parfums[nm])}c)`).join(', '); return `<div style="font-size:.72rem;color:#9a8576;margin-top:1px">↳ ${esc(p.nom)} → ${det}</div>`; }).join('')}
      </div></div>`;
    let inner='';
    (planC.standard.meringuesPleines||[]).forEach((m,i)=> inner+=merHTML(m,`Fournée couleur #${i+1}`,'#8e6fb0'));
    if(planC.standard.complement) planC.standard.complement.forEach(m=> inner+=merHTML(m,'Fournée complément','#b79fd0'));
    if(planC.standard.restes && planC.standard.restes.length){
      inner+=`<div class="sum-box" style="background:#fff"><span style="flex:1;font-size:.78rem;color:#9a8576">Restes : ${planC.standard.restes.map(r=>esc(r.nom)+' '+r.qte).join(' · ')}</span></div>`;
    }
    if(planC.grandFormat.meringues && planC.grandFormat.meringues.length){
      inner+=`<div style="font-size:.78rem;color:#8a6d3b;margin:6px 0 2px"><b>Grands formats</b> (réserve séparée)</div>`;
      planC.grandFormat.meringues.forEach((m,i)=> inner+=merHTML(m,`Fournée GF #${i+1}`,'#8a6d3b'));
    }
    return `<div class="panel" style="margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #e8dccd;padding-bottom:6px;margin-bottom:8px">
        <h3 style="margin:0">${esc(s.label)}</h3><span style="font-size:.78rem;color:#9a8576">par couleur</span></div>
      ${inner}</div>`;
  }).filter(Boolean).join('');
  if(!semainesHtml) return '';
  return `<details style="margin-bottom:16px">
    <summary style="cursor:pointer;font-weight:600;color:#6a4b82;font-size:.95rem;padding:6px 0">🎨 Fournées de meringue par couleur <span style="font-weight:400;color:#9a8576;font-size:.82rem">· mutualisation des coques (aperçu parallèle)</span></summary>
    <div style="margin-top:10px"><p class="note" style="margin-bottom:8px">Une meringue peut mêler jusqu'à ${ORDO.STD_MAXP} couleurs sous ${ORDO.STD_CAP} éq-macarons. Les coques d'une couleur alimentent ensuite tous les parfums de cette couleur.</p>${semainesHtml}</div>
  </details>`;
}
function _agendaMutualSection(mut){  if(!mut || !mut.semaines || !mut.semaines.length) return '';
  const semaines = mut.semaines.map(s=>{
    const lignes = s.parfums.map(p=>{
      const mutual = p.nbCommandes>=2;
      const detail = p.commandes.map(c=>`${esc(c.client)} (${c.qte})${c.aCongeler?' ❄️':''}`).join(', ');
      const gan = (p.ganacheDelaiH!=null) ? `<span style="background:#8a6d3b;color:#fff;font-size:.58rem;padding:1px 6px;border-radius:7px">⏱ ganache ${p.ganacheDelaiH}h</span>` : '';
      return `<div class="sum-box" style="align-items:flex-start">
        <div style="flex:1">
          <div><b>${esc(p.nom)}</b> · <b style="color:var(--caramel,#AA7C39)">${p.qte}</b> macaron${p.qte>1?'s':''}
            <span style="color:#9a8576;font-size:.74rem">(${p.batchs} batch${p.batchs>1?'s':''})</span>
            ${mutual?`<span style="background:#3f7d52;color:#fff;font-size:.58rem;font-weight:600;padding:1px 6px;border-radius:7px">★ ${p.nbCommandes} cmd regroupées</span>`:''}
            ${gan}</div>
          <div style="font-size:.78rem;color:#9a8576;margin-top:2px">${esc(detail)}</div>
        </div>
      </div>`;
    }).join('');
    const congelBloc = s.aCongeler.length ? `
      <div style="margin-top:8px;background:#eef4fb;border:1px solid #cfe0f2;border-radius:9px;padding:8px 10px">
        <div style="font-weight:600;color:#3b6ea5;font-size:.82rem;margin-bottom:4px">❄️ À congeler puis ressortir</div>
        ${s.aCongeler.map(c=>`<div style="font-size:.78rem;color:#5a6b80;padding:1px 0">
          <b>${esc(c.parfum)}</b> ×${c.qte} <span style="color:#9a8576">(${esc(c.client)})</span> — monté le ${esc(c.montage)}, livré le ${esc(c.livraison)} → <b>sortir le ${esc(c.sortir)}</b>
        </div>`).join('')}
      </div>` : '';
    return `<div class="panel" style="margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #e8dccd;padding-bottom:6px;margin-bottom:8px">
        <h3 style="margin:0">${esc(s.label)}</h3>
        <span style="font-size:.78rem;color:#9a8576">${s.totalMacarons} macaron${s.totalMacarons>1?'s':''} · ${s.nbCommandes} cmd</span>
      </div>
      ${lignes}
      ${congelBloc}
    </div>`;
  }).join('');
  return `<details style="margin-bottom:16px">
    <summary style="cursor:pointer;font-weight:600;color:var(--bordeaux);font-size:.95rem;padding:6px 0">🧩 Mutualisation par semaine <span style="font-weight:400;color:#9a8576;font-size:.82rem">· coques + montage regroupés, surplus congelé</span></summary>
    <div style="margin-top:10px">${semaines}</div>
  </details>`;
}

// [MUTUALISATION HEBDO] Regroupe la production PAR SEMAINE ISO de montage, en croisant TOUTES
// les commandes de la semaine. Règle métier validée par Benjamin :
//  - COQUES + MONTAGE mutualisés sur toute la semaine (max de regroupement) ; les produits finis
//    non livrés le jour du montage ou le lendemain partent au CONGÉLATEUR.
//  - GANACHES mutualisées par parfum sur toute la semaine, systématiquement (même sans gain de batch).
//  - L'app signale quels macarons sont à congeler et quand les ressortir (décongélation).
// Ne modifie PAS le moteur de calage : fournit une VUE de synthèse hebdomadaire.
// Renvoie { semaines:[{ wk, label, totalMacarons, nbCommandes,
//    parfums:[{nom, qte, nbCommandes, batchs, ganacheDelaiH, commandes:[{client, qte, montage, livraison, aCongeler, sortir}]}],
//    aCongeler:[{client, parfum, qte, montage, livraison, sortir}] }], horizonJours }.

// ════════════════════════════════════════════════════════════════════════════
// [PLAN MARCHÉS] Un marché a une DATE et une QUANTITÉ prévue, mais PAS de parfums fermes :
// la répartition par parfum est estimée par marketForecast (apprise sur l'historique des
// marchés clos). Pour intégrer un marché dans le moteur de plan (qui raisonne par parfum et
// par commande), on le transforme en « pseudo-commande » : un objet en MÉMOIRE qui ressemble
// assez à une commande pour passer dans retroplanningCommande (même calage, même affichage —
// source de vérité unique, aucune logique de calage dupliquée).
// GARDE-FOUS : (1) l'objet n'est JAMAIS persisté en base (vit le temps du calcul) ; (2) il est
// marqué _pseudoMarche pour qu'on ne le confonde jamais avec une vraie commande ; (3) on ne
// ventile par parfum QUE si l'historique est fiable (≥ SEUIL_MARCHE_FIABLE marchés clos), sinon
// on renvoie null et le marché restera affiché en « quantité globale » sans calage par parfum.
// ────────────────────────────────────────────────────────────────────────────
const SEUIL_MARCHE_FIABLE = 5;   // nb minimum de marchés clos pour ventiler par parfum

// Parse l'heure d'OUVERTURE du marché depuis le champ texte libre `horaires` (« 8h–13h »,
// « 9h30-18h », « 8:00 à 13:00 »…). Repli sur defautH (8h, heure typique d'un marché) si illisible.
// Renvoie { h, m, source:'horaires'|'défaut' }.
function _parseHeureMarche(horaires, defautH){
  const def = (defautH!=null) ? defautH : 8;
  if(!horaires || typeof horaires!=='string') return {h:def, m:0, source:'défaut'};
  const m = horaires.match(/(\d{1,2})\s*[h:]\s*(\d{2})?/i);   // 1er motif d'heure
  if(!m) return {h:def, m:0, source:'défaut'};
  const hh = Math.min(23, Math.max(0, parseInt(m[1],10)));
  const mm = m[2]!=null ? Math.min(59, parseInt(m[2],10)) : 0;
  return {h:hh, m:mm, source:'horaires'};
}

// Ventile une quantité totale selon une répartition [{parfum, pct}]. Le DERNIER parfum absorbe
// le reste pour que la somme soit EXACTE (même logique que la ventilation du prévisionnel).
// Renvoie [{nom, qte}] (parfums à qté > 0 uniquement).
function _ventilerMarche(prevuQte, repartition){
  const totPct = (repartition||[]).reduce((s,r)=>s+(+r.pct||0),0);
  if(!(prevuQte>0) || !repartition || !repartition.length || totPct<=0) return [];
  const out=[]; let cumule=0;
  repartition.forEach((r,i)=>{
    const part = (i===repartition.length-1) ? (prevuQte-cumule) : Math.round(prevuQte*(+r.pct||0)/totPct);
    if(i!==repartition.length-1) cumule += part;
    if(part>0) out.push({nom:r.parfum, qte:part});
  });
  return out.filter(p=>p.qte>0);
}

// Construit la pseudo-commande marché (objet en mémoire compatible retroplanningCommande/orderToLines).
// Renvoie null si l'historique n'est pas fiable ou si la compo n'est pas exploitable.
function _pseudoCommandeDepuisMarche(market, repartition, nbMarchesClos){
  if(!market || !market.date) return null;
  if(!(+market.prevuQte>0)) return null;
  if(!(nbMarchesClos >= SEUIL_MARCHE_FIABLE)) return null;
  const parfums = _ventilerMarche(+market.prevuQte, repartition||[]);
  if(!parfums.length) return null;
  const hp = _parseHeureMarche(market.horaires, 8);
  const heureLivraison = String(hp.h).padStart(2,'0')+':'+String(hp.m).padStart(2,'0');
  return {
    _pseudoMarche: true,           // marqueur : NE JAMAIS confondre avec une vraie commande
    marketId: market.id,
    nom: market.nom || 'Marché',
    date: String(market.date).slice(0,10),
    heureLivraison,
    _heureSource: hp.source,
    lignes: [{ type:'coffret', taille:6, parfums }]
  };
}

async function buildMutualisationSemaine(horizonJours){
  horizonJours = +horizonJours || 45;
  const orders  = await db.orders.toArray().catch(()=>[]);
  const clients = await db.clients.toArray().catch(()=>[]);
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const clientNom = id => { const c=clients.find(x=>+x.id===+id); return c?(c.nom||c.prenom||'Client'):'—'; };
  // parfum → recette (pour ganacheDelaiH et heuresMaxSortie). Match souple sur le nom de produit.
  const recipeByParfum = nom => {
    const n=(nom||'').trim().toLowerCase();
    return recipes.find(r=>((r.produitNom||'').trim().toLowerCase())===n) || null;
  };
  const TB  = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const today0 = new Date(); today0.setHours(0,0,0,0);
  const horizon = new Date(today0); horizon.setDate(horizon.getDate()+horizonJours);

  // wk → { parfum → { qte, ganacheDelaiH, commandes:[...] }, commandesIds:Set, aCongeler:[...] }
  const parSemaine = {};

  for(const o of orders){
    const st = (typeof normStatus==='function') ? normStatus(o.statut) : (o.statut||'');
    if(st==='Livrée') continue;
    const dLiv = o.dateEvenement || o.date || '';
    if(!dLiv) continue;

    // Jour de montage calé (pilote la fraîcheur). À défaut, repli sur la date de livraison.
    let montageKey=null, montageISO=null;
    try{
      const cale = await retroplanningCale(o.id);
      if(cale && cale.ok && Array.isArray(cale.jalonsCales)){
        const m = cale.jalonsCales.find(j=>j.cle==='montage' && j.debut);
        if(m){ montageKey = ymdLocal(new Date(m.debut)); montageISO = m.debut; }
      }
    }catch(e){swallow(e,'buildMutualisationSemaine')}
    if(!montageKey) montageKey = String(dLiv).slice(0,10);

    const dMontage = new Date(montageKey+'T12:00:00');
    if(dMontage < today0 || dMontage > horizon) continue;

    const wk = _isoWeekKey(montageKey) || montageKey;
    const slotWk = (parSemaine[wk] ||= { parfums:{}, ids:new Set(), aCongeler:[], montageRef:null, montageRefISO:null });
    // Montage de référence de la semaine = le plus PRÉCOCE (première échéance qui contraint les coques).
    if(!slotWk.montageRef || montageKey < slotWk.montageRef){
      slotWk.montageRef = montageKey;
      slotWk.montageRefISO = montageISO || (montageKey+'T14:00:00');
    }

    // Produit fini à congeler ? Oui si la livraison est à plus d'1 jour après le montage.
    const dLiv0 = new Date(String(dLiv).slice(0,10)+'T12:00:00');
    const ecartJours = Math.round((dLiv0 - dMontage)/86400000);
    const aCongeler = ecartJours > 1;

    const cn = clientNom(o.clientId);
    const lignes = (typeof orderToLines==='function') ? orderToLines(o) : [];
    lignes.forEach(ln=>{
      const src = (ln.type==='grand') ? (ln.items||[]) : (ln.parfums||[]);
      src.forEach(p=>{
        const nom=(p.nom||'').trim(); const qte=+p.qte||0;
        if(!nom || qte<=0) return;
        const rec = recipeByParfum(nom);
        const gDelai = rec && rec.ganacheDelaiH!=null ? +rec.ganacheDelaiH : null;
        // Date de sortie du congélateur : livraison moins l'avance de sortie de la recette.
        // À défaut de paramètre dédié, on ressort la veille de la livraison.
        let sortir=null;
        if(aCongeler){
          const hMax = rec && rec.heuresMaxSortie!=null && +rec.heuresMaxSortie>0 ? +rec.heuresMaxSortie : 24;
          const ds = new Date(dLiv0.getTime() - hMax*3600000);
          sortir = ymdLocal(ds);
        }
        const slot = (slotWk.parfums[nom] ||= { qte:0, ganacheDelaiH:gDelai, commandes:[] });
        slot.qte += qte;
        if(slot.ganacheDelaiH==null && gDelai!=null) slot.ganacheDelaiH=gDelai;
        slot.commandes.push({ orderId:o.id, client:cn, qte, montage:montageKey, livraison:String(dLiv).slice(0,10), aCongeler, sortir });
        if(aCongeler){
          slotWk.aCongeler.push({ orderId:o.id, client:cn, parfum:nom, qte, montage:montageKey, livraison:String(dLiv).slice(0,10), sortir });
        }
      });
      // [FIX cas A] Les macarons « sans parfum » du coffret doivent peser dans le PLAN OPÉRATIONNEL
      // (ganaches/coques/montages), pas seulement à la livraison. On les agrège sous « À définir »
      // (même convention que _parfumsQtesDeLignes / _orderParfumDemand). Sans recette → temps par
      // défaut. Ils seront remplacés par de vrais parfums au figeage, au démarrage de la prod.
      const _sp = +ln.sansParfum||0;
      if(_sp>0){
        const nom='À définir';
        let sortir=null;
        if(aCongeler){ const ds=new Date(dLiv0.getTime()-24*3600000); sortir=ymdLocal(ds); }
        const slot = (slotWk.parfums[nom] ||= { qte:0, ganacheDelaiH:null, commandes:[] });
        slot.qte += _sp;
        slot.commandes.push({ orderId:o.id, client:cn, qte:_sp, montage:montageKey, livraison:String(dLiv).slice(0,10), aCongeler, sortir, aDefinir:true });
        if(aCongeler){
          slotWk.aCongeler.push({ orderId:o.id, client:cn, parfum:nom, qte:_sp, montage:montageKey, livraison:String(dLiv).slice(0,10), sortir });
        }
      }
      slotWk.ids.add(o.id);
    });
  }

  // [PLAN MARCHÉS] Injection des marchés à venir, VENTILÉS par parfum (marketForecast) si l'historique
  // est fiable (≥ SEUIL_MARCHE_FIABLE marchés clos). Le montage est calé HORAIREMENT par le cœur neutre
  // retroplanningCaleParfums — AUCUN pseudo-objet commande : on passe directement (date, heure, parfums).
  // Les contributions marché sont marquées marche:true / marketId pour rester distinctes des commandes.
  try{
    const markets = await db.markets.toArray().catch(()=>[]);
    let fc=null; try{ fc = await marketForecast(); }catch(_){ fc=null; }
    const repartition = (fc && fc.repartition) ? fc.repartition : [];
    const nbClos = fc ? fc.nbMarches : 0;
    const todayStr = today().slice(0,10);
    const futurs = markets.filter(m=> m.date && String(m.date).slice(0,10) >= todayStr
      && m.statut!=='clos' && (+m.prevuQte||0)>0);
    for(const mk of futurs){
      const pseudo = _pseudoCommandeDepuisMarche(mk, repartition, nbClos);
      if(!pseudo) continue;   // historique insuffisant ou compo non exploitable → pas de ventilation
      const parfumsQtes = pseudo.lignes[0].parfums.map(p=>({nom:p.nom, qte:p.qte}));

      // Montage calé horairement par le cœur NEUTRE (date du marché + heure d'ouverture + parfums).
      let montageKey=null, montageISO=null;
      try{
        const cale = await retroplanningCaleParfums(pseudo.date, pseudo.heureLivraison, parfumsQtes, recipes);
        if(cale && cale.ok && Array.isArray(cale.jalonsCales)){
          const m = cale.jalonsCales.find(j=>j.cle==='montage' && j.debut);
          if(m){ montageKey = ymdLocal(new Date(m.debut)); montageISO = m.debut; }
        }
      }catch(e){swallow(e,'buildMutualisationSemaine')}
      if(!montageKey) montageKey = pseudo.date;   // repli : date du marché

      const dMontage = new Date(montageKey+'T12:00:00');
      if(dMontage < today0 || dMontage > horizon) continue;

      const wk = _isoWeekKey(montageKey) || montageKey;
      const slotWk = (parSemaine[wk] ||= { parfums:{}, ids:new Set(), aCongeler:[], montageRef:null, montageRefISO:null });
      if(!slotWk.montageRef || montageKey < slotWk.montageRef){
        slotWk.montageRef = montageKey;
        slotWk.montageRefISO = montageISO || (montageKey+'T14:00:00');
      }
      parfumsQtes.forEach(p=>{
        const nom=(p.nom||'').trim(); const qte=+p.qte||0;
        if(!nom || qte<=0) return;
        const rec = recipeByParfum(nom);
        const gDelai = rec && rec.ganacheDelaiH!=null ? +rec.ganacheDelaiH : null;
        const slot = (slotWk.parfums[nom] ||= { qte:0, ganacheDelaiH:gDelai, commandes:[] });
        slot.qte += qte;
        if(slot.ganacheDelaiH==null && gDelai!=null) slot.ganacheDelaiH=gDelai;
        // marche:true + marketId : contribution marché, JAMAIS confondue avec une commande (pas d'orderId).
        slot.commandes.push({ marche:true, marketId:mk.id, client:'⛺ '+(mk.nom||'Marché'),
          qte, montage:montageKey, livraison:pseudo.date, aCongeler:false, sortir:null, estime:true });
      });
      slotWk.ids.add('mk'+mk.id);   // id distinct (string) — pas de collision avec un orderId numérique
    }
  }catch(e){ console.error('buildMutualisation.marches', e); }

  const semaines = Object.keys(parSemaine).sort().map(wk=>{
    const s = parSemaine[wk];
    const parfums = Object.keys(s.parfums).sort().map(nom=>{
      const p=s.parfums[nom];
      return {
        nom, qte:p.qte,
        nbCommandes:p.commandes.length,
        batchs:Math.ceil(p.qte/TB),
        ganacheDelaiH:p.ganacheDelaiH,
        commandes:p.commandes
      };
    }).sort((a,b)=>b.qte-a.qte);
    const totalMacarons = parfums.reduce((t,p)=>t+p.qte,0);
    // Libellé lisible de la semaine : « Semaine 26 · 22 → 28 juin ».
    let label = wk;
    const m = /(\d{4})-W(\d{2})/.exec(wk);
    if(m){
      // lundi de la semaine ISO
      const simple=new Date(Date.UTC(+m[1],0,1+(+m[2]-1)*7));
      const dow=(simple.getUTCDay()+6)%7;
      const lundi=new Date(simple); lundi.setUTCDate(simple.getUTCDate()-dow);
      const dim=new Date(lundi); dim.setUTCDate(lundi.getUTCDate()+6);
      const fmt=x=>x.toLocaleDateString('fr-FR',{day:'2-digit',month:'short'});
      label=`Semaine ${m[2]} · ${fmt(lundi)} → ${fmt(dim)}`;
    }
    return { wk, label, totalMacarons, nbCommandes:s.ids.size, parfums, aCongeler:s.aCongeler, montageRef:s.montageRef, montageRefISO:s.montageRefISO };
  });
  return { semaines, horizonJours };
}


// [TEMPS COQUES — modèle réel] Sépare le travail ACTIF (présence requise) du temps FOUR (cuisson).
// Calibré sur relevé atelier RÉEL de Benjamin pour 200 coques (chablonnage exclu du temps général) :
//   FIXE par fournée (meringue) : pesée ingrédients 3 + chauffe 4 + foisonnement 15 + pesée tant pour tant 6 = 28 min.
//   PROPORTIONNEL au nb de coques : 63 min pour 200 coques (silpat, incorporation, macaronnage, pochages,
//     tapages, claquages, appairages, vaisselle) = 0,315 min/coque.
//   CHABLONNAGE : proportionnel, AJOUTÉ seulement pour les parfums concernés (citron, framboise, coco citron
//     vert) — non inclus ici, géré à part. (13 min pour ~200 coques concernées ≈ 0,065 min/coque.)
// Préchauffage four (~7 min) : se fait EN PARALLÈLE du macaronnage (four lancé au macaronnage, chaud à
//   l'enfournement) → non ajouté au total, juste masqué par le travail actif.
// Cuisson = présence requise, via cuissonCascade (four 2 plaques, décalage 6 min).
// nbCoques = macarons × 2. coquesChablonnees = nb de coques chablonnées dans la fournée
// (0,065 min/coque = 13 min / 200 coques, sans distinction parfum/format).
// Renvoie { actifMin, cuissonMin, nbPlaques, totalMin, chablonMin }.
function tempsCoquesFournee(nbCoques, coquesChablonnees){
  nbCoques = Math.max(0, +nbCoques||0);
  const nbChablon = Math.max(0, Math.min(nbCoques, +coquesChablonnees||0));
  const FIXE_MIN = 28;                 // meringue (pesées + chauffe + foisonnement), fixe par fournée
  const PAR_COQUE = 63/200;            // 0,315 min/coque : travail proportionnel relevé (hors chablonnage)
  const CHABLON_PAR_COQUE = 13/200;    // 0,065 min/coque : chablonnage proportionnel (parfums concernés)
  const chablonMin = Math.round(CHABLON_PAR_COQUE * nbChablon);
  const actifMin = Math.round(FIXE_MIN + PAR_COQUE * nbCoques) + chablonMin;
  const cuisson = (typeof cuissonCascade==='function') ? cuissonCascade(nbCoques, 'standard') : { makespanMin:0, nbPlaques:0 };
  return { actifMin, cuissonMin: cuisson.makespanMin, nbPlaques: cuisson.nbPlaques, totalMin: actifMin + cuisson.makespanMin, chablonMin };
}

// [PLAN OPÉRATIONNEL — étape 1] Produit, par SEMAINE, le détail PARFUM PAR PARFUM de chaque étape
// (coques / ganache / montage), à partir de la pool de cumul (buildMutualisationSemaine).
// TEMPS À 3 NIVEAUX (règle validée) : mesuré à l'atelier si fiable, sinon saisie recette, sinon défaut.
//   - GANACHE : temps FIXE par parfum.
//   - MONTAGE : AU PRORATA (temps/batch × qte/60).
//   - COQUES : meringues appariées (_packMeringues), 35 min/meringue.
// mut = buildMutualisationSemaine(...) ; recipes = db.recipes.toArray() ; tEtape = prodTempsParEtapeParParfum(90).
// Renvoie { semaines:[{ wk, label,
//   ganache:[{parfum, qte, dureeMin, source, commandes}],
//   coques:[{parfums, repartition, macarons, dureeMin, partielle}],
//   montage:[{parfum, qte, dureeMin, parBatchMin, source, commandes}],
//   totalGanacheMin, totalCoquesMin, totalMontageMin, totalMin, totalMacarons }], horizonJours }.
// ═══════════════════════════════════════════════════════════════════════════
// [v1189 — SOURCE UNIQUE DE DISPONIBILITÉ DES PARFUMS]
// -----------------------------------------------------------------------------
// UNE SEULE implémentation calcule « combien puis-je mobiliser du parfum X ». Tous
// les modules qui répondent à cette question (générateur de compositions, contrôle
// de faisabilité, ordre du jour / plans de production, besoins unifiés, plan marchés)
// consomment cette fonction — JAMAIS un recalcul local. Objectif : une modification de
// la règle métier de disponibilité ne se fait qu'ICI, et ne peut plus diverger.
//
// Notion métier portée ici = DISPONIBILITÉ MOBILISABLE pour couvrir un besoin :
//   finis (produits vendables) + assemblable (min(coques, ganache), car il faut les DEUX).
// Elle NE couvre volontairement PAS :
//   • le stock physique BRUT / fini-seul à fin de DIAGNOSTIC d'observation
//     (_diagReservationsStock) — notion différente, ne doit rien mobiliser ;
//   • la décomposition analytique fini vs ganache de l'arbitrage réassort
//     (recoReassort) — qui a besoin de distinguer explicitement les deux.
// Ces deux-là sont documentés sur place comme hors périmètre, pas comme un oubli.
//
// Structure par parfum (indexée par CLÉ NORMALISÉE stockMoveKey/aiNormalize) :
//   { nom, finis, coquesMac, ganacheMac, assemblable, mobilisable }
// -----------------------------------------------------------------------------
async function parfumDispoSource(){
  const out = {};
  let prodsAll, recipes;
  try{
    prodsAll = (await db.productions.toArray()).filter(p=>round3(+p.qteRestante)>0);
    recipes = await db.recipes.toArray();
  }catch(e){ return out; }
  const key = nom => stockMoveKey(nom);
  const ensure = nom => {
    const k = key(nom);
    return (out[k] ||= { nom, finis:0, coquesMac:0, ganacheMac:0, assemblable:0, mobilisable:0 });
  };
  prodsAll.forEach(p=>{
    const nom = prodNomComplet(p, recipes);
    const comp = prodComposant(p);
    const q = round3(+p.qteRestante||0);
    if(prodVendable(p)){
      ensure(nom).finis = addQty(ensure(nom).finis, q);
    } else if(comp==='coques'){
      // coques en attente d'assemblage (rangées, ou non terminées, ou placées)
      if(p.rangee===true || prodStatut(p)!=='termine' || !!p.emplacement){
        ensure(nom).coquesMac = addQty(ensure(nom).coquesMac, q / COQUES_PAR_MACARON);
      }
    } else if(comp==='ganache'){
      if(p.rangee===true || prodStatut(p)!=='termine' || !!p.emplacement){
        ensure(nom).ganacheMac = addQty(ensure(nom).ganacheMac, q);
      }
    }
  });
  Object.values(out).forEach(b=>{
    b.assemblable = Math.max(0, Math.min(b.coquesMac, b.ganacheMac));
    b.mobilisable = addQty(b.finis, b.assemblable);
  });
  // [v1394] VENTE EN LIGNE — cloisonnement de l'enveloppe réservée au canal online.
  // INVARIANT DE SÉCURITÉ : une pièce réservée à la vente en ligne N'EST PLUS mobilisable en
  // direct. On la retire ici, à la source unique de disponibilité, pour qu'AUCUN appelant
  // (coffrets, marché, commandes) ne puisse vendre une pièce déjà promise au online → jamais de
  // double vente. `reserveOnline` (réglages, piloté à la main) porte la quantité par parfum ;
  // `reserveEff` ne peut retirer que ce qui existe (min avec le mobilisable), et on expose
  // `reserveOnline` + `mobilisableTotal` pour que l'écran montre la ventilation sans ambiguïté.
  try{
    const reserve = (typeof getSettings==='function' ? (getSettings().reserveOnline||{}) : {});
    Object.values(out).forEach(b=>{
      const k = stockMoveKey(b.nom);
      const r = round3(+reserve[k] || 0);
      b.mobilisableTotal = b.mobilisable;                 // avant réservation (info)
      b.reserveOnline    = Math.max(0, Math.min(r, b.mobilisable)); // ne réserve que le possible
      b.mobilisable      = Math.max(0, subQty(b.mobilisable, b.reserveOnline)); // vendable en DIRECT
    });
  }catch(e){ swallow(e,'parfumDispoSource reserveOnline'); }
  return out;
}

// [API DE CONSOMMATION — à utiliser partout] Map { cléNorm : mobilisable(nombre) }.
// C'est la forme demandée par la plupart des appelants (« combien dispo pour ce parfum »).
// Passe par parfumDispoSource : aucune relecture de logique ailleurs.
async function parfumDispoMap(){
  const src = await parfumDispoSource();
  const map = {};
  Object.keys(src).forEach(k=>{ map[k] = +src[k].mobilisable||0; });
  return map;
}
// [API DE CONSOMMATION] Lecture robuste par NOM (normalise comme la source), depuis une map
// déjà chargée via parfumDispoMap(). Évite que chaque appelant réinvente la normalisation.
function parfumDispoDe(map, nom){
  if(!map) return 0;
  const k = (typeof stockMoveKey==='function') ? stockMoveKey(nom)
          : (typeof aiNormalize==='function' ? aiNormalize(nom) : String(nom||'').toLowerCase().trim());
  return +map[k]||0;
}

// [STOCK MOBILISABLE] État du stock par parfum, mobilisable pour couvrir une commande.
// [v1189] DÉLÈGUE désormais à la source unique parfumDispoSource — plus aucune logique ici.
// Conservé comme façade nommée pour ses appelants historiques (structure identique).
// Source de vérité = table db.productions. Pour chaque parfum :
//   - finis     : macarons finis vendables en stock (qteRestante des prod. complètes/assemblées)
//   - coquesMac : coques nues en stock converties en MACARONS (÷ COQUES_PAR_MACARON)
//   - ganacheMac: ganache en stock, déjà exprimée en macarons
//   - assemblable = min(coquesMac, ganacheMac)  (il faut les DEUX pour monter un macaron)
//   - mobilisable = finis + assemblable
// Renvoie une map { nomNorm: { nom, finis, coquesMac, ganacheMac, assemblable, mobilisable } }.
async function stockMobilisableParParfum(){
  return await parfumDispoSource();
}

// [JOURNAL DE STOCK] Normalisation de la clé parfum. On réutilise aiNormalize (la norme
// dominante du code parfum : minuscules + retrait d'accents) pour que les mouvements se
// regroupent EXACTEMENT comme les parfums ailleurs dans l'app. Source de vérité unique.
function stockMoveKey(nom){
  return (typeof aiNormalize==='function') ? aiNormalize(nom||'') : String(nom||'').toLowerCase().trim();
}

/* ═══════════════════════════════════════════════════════════════════════════
   GÉNÉRATEUR DE COMPOSITIONS DE COFFRETS  (v1)
   ───────────────────────────────────────────────────────────────────────────
   Quand un coffret est infaisable (parfum indispo ou hors fenêtre), on propose
   des compositions alternatives PUISÉES DANS 3 SOURCES classées du moins coûteux
   au plus coûteux :
     1) STOCK immédiat        → stockMobilisableParParfum (finis + assemblables)
     2) SURPLUS mutualisable  → buildMutualisationSemaine (batchs déjà prévus dont
                                 le montage tombe ≤ date de retrait ; surplus =
                                 batchs×60 − demande déjà engagée)
     3) RELANCE faisable      → produire exprès un parfum, SI le repos ganache
                                 tient dans la fenêtre (retroplanningDepuisParfums
                                 en mode dur, cohérent avec le verdict de faisabilité)
   Chaque proposition est ANNOTÉE par ventilation (« 10 en stock, 5 mutualisés,
   3 à produire »). Deux modes de format : STRICT (respecte les parfums demandés)
   ou FLEXIBLE (remplit au mieux avec le plus disponible).
   ─── Cœur PUR (aucun DOM, aucune écriture base) : testable en Node. ───
   ═══════════════════════════════════════════════════════════════════════════ */

// Construit, PAR PARFUM, la disponibilité issue des 3 sources, chacune avec sa date
// de disponibilité et son "coût" (0=stock, 1=mutualisé, 2=relance). Fonction ASYNC car
// elle lit stock + mutualisation en base ; sépare clairement la collecte (I/O) du calcul pur.
//   dateLiv : 'YYYY-MM-DD' date de retrait cible
//   heureLiv: 'HH:MM' (pour le test de relance faisable)
// Renvoie { parfums:{ [nomCanon]:{ nom, stock, mutualise, relanceOk, sources:[...] } }, meta }.
async function _collecterDisponibilites(dateLiv, heureLiv, opts){
  opts = opts || {};
  const norm = n => (typeof aiNormalize==='function') ? aiNormalize(n||'') : String(n||'').toLowerCase().trim();
  const TB  = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  // [FILTRE TYPE — grand format vs coffret standard] On ne mélange pas les univers : quand on résout
  // un GRAND FORMAT, on ne propose que des parfums de recette grandFormat (et inversement pour les
  // coffrets standard). typeFiltre : 'grand' | 'standard' | null (tout). La distinction vient TOUJOURS
  // de la recette (rec.grandFormat), jamais du nom (peu fiable) — même règle que le reste de l'app.
  const typeFiltre = opts.typeFiltre || null;   // null = pas de filtre
  const recettesAll = (typeof window!=='undefined' && window._allRecipesCache)
    ? window._allRecipesCache
    : (typeof db!=='undefined' && db.recipes ? await db.recipes.toArray().catch(()=>[]) : []);
  const recByNom = {};
  recettesAll.forEach(r=>{ if(r.produitNom) recByNom[norm(r.produitNom)] = r; });
  // Un parfum est-il compatible avec le type demandé ? Inconnu (pas de recette) → accepté par défaut
  // (on ne bloque pas un stock réel sous prétexte qu'on n'a pas retrouvé la fiche), MAIS on trace ces
  // cas : un parfum accepté sans recette pourrait être un grand format non catégorisé. [v1192]
  const _ambigus = [];
  const compatType = (nom) => {
    if(!typeFiltre) return true;
    const r = recByNom[norm(nom)];
    if(!r){ _ambigus.push(nom); return true; }   // recette inconnue → ne pas exclure, mais signaler
    const estGF = !!r.grandFormat;
    return typeFiltre==='grand' ? estGF : !estGF;
  };
  const acc = {};   // nomCanon → { nom, stock, mutualise, relanceOk, sources:[] }
  const ensure = (nom) => {
    const k = norm(nom);
    return (acc[k] ||= { nom, stock:0, mutualise:0, relanceOk:false, sources:[] });
  };

  // ── SOURCE 1 : STOCK immédiat ────────────────────────────────────────────
  // [v1189 — SOURCE UNIQUE] Disponibilité mobilisable via parfumDispoSource (structure enrichie :
  // finis/coquesMac/ganacheMac/assemblable/mobilisable). Même source que faisabilité et ordre du jour.
  let mob = {};
  try{ mob = await parfumDispoSource(); }catch(_){ mob = {}; }
  Object.values(mob).forEach(b=>{
    if(!compatType(b.nom)) return;   // stock d'un autre univers (GF vs standard) → ignoré
    const dispo = Math.floor(Math.max(0, +b.mobilisable||0));
    if(dispo>0){ const e=ensure(b.nom); e.stock += dispo; }
  });

  // ── SOURCE 2 : SURPLUS mutualisable ──────────────────────────────────────
  // Un batch déjà prévu pour d'autres commandes produit 60 (ou multiple) mais la
  // demande engagée est < capacité → le RESTE est mobilisable pour ce client, à
  // condition que le montage tombe AU PLUS TARD le jour de la livraison (jour même OK).
  try{
    const mut = await buildMutualisationSemaine(60);
    (mut.semaines||[]).forEach(sem=>{
      (sem.parfums||[]).forEach(p=>{
        if(!p.nom || p.nom==='À définir') return;
        if(!compatType(p.nom)) return;   // surplus d'un autre univers → ignoré
        const surplus = Math.max(0, (p.batchs||Math.ceil(p.qte/TB))*TB - p.qte);
        if(surplus<=0) return;
        // Timing : le montage de CE parfum doit être ≤ date de retrait du client.
        // On prend le montage le plus précoce parmi les commandes du parfum (le plus permissif).
        let montageMin = null;
        (p.commandes||[]).forEach(c=>{ if(c.montage && (!montageMin || c.montage<montageMin)) montageMin=c.montage; });
        const montageOk = montageMin ? (montageMin <= dateLiv) : (sem.montageRef ? sem.montageRef<=dateLiv : false);
        if(!montageOk) return;
        const e = ensure(p.nom);
        e.mutualise += surplus;
        e.sources.push({ type:'mutualise', qte:surplus, montage:montageMin||sem.montageRef, semaine:sem.label });
      });
    });
  }catch(e){swallow(e,'_collecterDisponibilites')}

  // ── SOURCE 3 : RELANCE faisable ──────────────────────────────────────────
  // Pour CHAQUE recette existante, est-il possible de lancer un batch dédié qui
  // respecte le repos ganache pour cette date ? On réutilise le rétroplanning DUR
  // (même règle que le verdict de faisabilité). relanceOk = la séquence tient.
  try{
    const recettes = recettesAll;
    const maintenant = new Date();
    recettes.forEach(r=>{
      if(r.actif===false) return;
      const nom = r.produitNom; if(!nom) return;
      // Filtre univers : pour un grand format on ne relance que des recettes grandFormat, etc.
      if(typeFiltre){ const estGF=!!r.grandFormat; if(typeFiltre==='grand' ? !estGF : estGF) return; }
      if(typeof retroplanningDepuisParfums!=='function'){ ensure(nom).relanceOk=true; return; }
      let ok=false;
      try{
        const rp = retroplanningDepuisParfums(dateLiv, heureLiv, [nom], recettes, {ignorerMaturation:true});
        if(rp && !rp.error && Array.isArray(rp.jalons)){
          const pt = rp.jalons.filter(j=>j.type==='travail').sort((a,b)=>a.date-b.date)[0];
          ok = !(pt && pt.date < maintenant);
        } else if(rp && rp.error){ ok=false; }
      }catch(_){ ok=false; }
      const e = ensure(nom);
      e.relanceOk = e.relanceOk || ok;
    });
  }catch(e){swallow(e,'_collecterDisponibilites')}

  // [v1192 — DIAG SÉPARATION UNIVERS] Transparence sur le filtre standard/grand format : combien de
  // parfums retenus, et lesquels ont été acceptés SANS recette (potentiels grands formats non catégorisés).
  try{
    if(typeFiltre && typeof diagPublish==='function'){
      const retenus = Object.values(acc).map(p=>p.nom);
      diagPublish('compoUnivers', '🧩 Génération — séparation des univers', {
        'Univers demandé': typeFiltre==='grand' ? 'Grands formats' : 'Coffret standard',
        'Parfums retenus': retenus.length ? retenus : 'aucun',
        'Acceptés sans recette (à vérifier)': _ambigus.length ? [...new Set(_ambigus)] : 'aucun — tous catégorisés',
        'Règle': 'Un coffret standard exclut TOUT parfum dont la recette est grandFormat ; un grand format exclut tout parfum standard. La catégorie vient de la case grandFormat de la recette.'
      });
    }
  }catch(e){swallow(e,'_collecterDisponibilites')}

  return { parfums: acc, meta:{ dateLiv, heureLiv, batch:TB, typeFiltre, ambigus:[...new Set(_ambigus)] } };
}

// [COMPOSITION — cœur PUR] À partir des disponibilités déjà collectées (dispoParfums),
// génère des propositions de coffrets de la taille demandée. Pas d'I/O ici : 100% déterministe,
// donc testable en Node.
//   dispoParfums : { nomCanon:{ nom, stock, mutualise, relanceOk } }  (issu de _collecterDisponibilites)
//   taille       : 6 | 8 | 16 | 25
//   opts.mode    : 'strict' | 'flexible'
//   opts.parfumsSouhaites : [{nom, qte}] format demandé (requis en strict, indicatif en flexible)
//   opts.maxParfums : cap de variété par coffret (défaut : selon taille)
// Renvoie [{ taille, complet, lignes:[{nom, qte, stock, mutualise, relance}],
//            total, ventilation:{stock, mutualise, relance}, cout, resume }]
//   trié du MOINS coûteux (100% stock) au PLUS coûteux (avec relance).
function _composerCoffrets(dispoParfums, taille, opts){
  opts = opts || {};
  const mode = opts.mode==='flexible' ? 'flexible' : 'strict';
  const norm = n => (typeof aiNormalize==='function') ? aiNormalize(n||'') : String(n||'').toLowerCase().trim();
  const list = Object.values(dispoParfums||{});
  // Retrouve un parfum de `list` par nom (helper pour la répartition flexible).
  const clone_lookup = (arr, nom) => arr.find(x=>norm(x.nom)===norm(nom)) || null;

  // Alloue `besoin` unités d'un parfum en tirant d'abord du stock, puis du mutualisé, puis
  // de la relance (illimitée si relanceOk). Renvoie {stock, mutualise, relance, manque}.
  const allouer = (p, besoin) => {
    let reste = besoin, s=0, m=0, r=0;
    const fromStock = Math.min(reste, p.stock||0); s+=fromStock; reste-=fromStock;
    const fromMut   = Math.min(reste, p.mutualise||0); m+=fromMut; reste-=fromMut;
    if(reste>0 && p.relanceOk){ r+=reste; reste=0; }
    return { stock:s, mutualise:m, relance:r, manque:reste };
  };

  // Construit UNE proposition en respectant une liste ordonnée de (parfum, quotas) cible.
  // consomme un clone des dispos pour ne pas réutiliser deux fois le même stock.
  const buildFrom = (cibles, autoriserRelance) => {
    const clone = {}; list.forEach(p=>{ clone[norm(p.nom)] = { nom:p.nom, stock:p.stock||0, mutualise:p.mutualise||0, relanceOk:!!p.relanceOk }; });
    const lignes=[]; let total=0, vS=0, vM=0, vR=0, manqueTotal=0;
    for(const c of cibles){
      const k=norm(c.nom); const p=clone[k]; if(!p) { manqueTotal+=c.qte; continue; }
      const besoin = c.qte;
      const a = allouer(p, autoriserRelance ? besoin : Math.min(besoin, (p.stock||0)+(p.mutualise||0)));
      const pris = a.stock+a.mutualise+a.relance;
      if(pris>0){
        lignes.push({ nom:p.nom, qte:pris, stock:a.stock, mutualise:a.mutualise, relance:a.relance });
        total+=pris; vS+=a.stock; vM+=a.mutualise; vR+=a.relance;
        p.stock-=a.stock; p.mutualise-=a.mutualise;   // consommé
      }
      manqueTotal += a.manque;
    }
    return { lignes, total, vS, vM, vR, manqueTotal };
  };

  let ciblesBase;
  // Détermine les cibles selon le mode.
  // Les DEUX modes utilisent la MÊME mécanique round-robin (aucune duplication) : seul le NOMBRE de
  // parfums visé change.
  //   • STRICT  : on respecte la règle métier BOX_FLAVOR_LIMIT[taille] (6→3, 8→4, 16→4, 25→5), plus
  //     d'éventuels « parfums en + » choisis volontairement (opts.parfumsEnPlus) — chacun facturé
  //     FLAVOR_SURCHARGE (3 €) par la tarification existante de la ligne coffret.
  //   • FLEXIBLE: le moteur choisit librement le nombre de parfums pour MAXIMISER la faisabilité.
  const limiteReglementaire = (typeof BOX_FLAVOR_LIMIT!=='undefined' && BOX_FLAVOR_LIMIT[taille]!=null)
    ? BOX_FLAVOR_LIMIT[taille]
    : (taille<=6?3 : taille<=8?4 : taille<=16?4 : 5);
  const parfumsEnPlus = Math.max(0, +(opts.parfumsEnPlus||0));

  // [v1191 — PARFUMS VALIDÉS] Parfums verrouillés par l'utilisateur (bouton « valider ») : ils DOIVENT
  // figurer dans chaque proposition avec leur quantité, et sont retirés du budget que le round-robin doit
  // remplir. On borne leur quantité au dispo réel (stock+mutualisé) ou illimité si relançable, et à la taille.
  const imposesRaw = Array.isArray(opts.imposes) ? opts.imposes : [];
  const imposes = [];
  let placeImposes = 0;
  const imposeNoms = new Set();
  imposesRaw.forEach(im=>{
    if(!im || !im.nom) return;
    const k = norm(im.nom);
    if(imposeNoms.has(k)) return;
    const src = clone_lookup(list, im.nom);
    let q = Math.max(1, Math.round(+im.qte||1));
    q = Math.min(q, Math.max(0, taille - placeImposes));   // ne dépasse pas la taille
    if(q<=0) return;
    imposeNoms.add(k);
    imposes.push({nom: src?src.nom:im.nom, qte:q});
    placeImposes += q;
  });
  // La taille RESTANTE à composer par le round-robin (après les validés).
  const tailleReste = Math.max(0, taille - placeImposes);

  // Candidats triés par FACILITÉ décroissante : stock PUR d'abord (le plus simple, rien à faire),
  // puis surplus mutualisé (batch déjà prévu), puis relançable (à produire). [v1191] On sépare
  // explicitement le stock pur du mutualisé pour « démarrer par le stock » avant de courir en cuisine.
  // opts.seed : entier qui fait tourner l'ordre entre candidats de MÊME facilité → « nouvelle suggestion »
  // propose d'autres parfums sans jamais dégrader la priorité (stock reste devant relance).
  const _seed = Math.max(0, +(opts.seed||0));
  const _rot = arr => { if(!_seed || arr.length<2) return arr; const k=_seed%arr.length; return arr.slice(k).concat(arr.slice(0,k)); };
  const tri = _rot(list.slice().sort((a,b)=>
    ((b.stock||0)) - ((a.stock||0))                              // 1) stock pur d'abord
    || ((b.mutualise||0)) - ((a.mutualise||0))                   // 2) puis mutualisé
    || (b.relanceOk?1:0)-(a.relanceOk?1:0)                       // 3) puis relançable
    || norm(a.nom).localeCompare(norm(b.nom))                    // ordre stable
  ));
  // [v1191] Les parfums VALIDÉS sont retirés des candidats du round-robin (déjà placés d'office).
  const triLibre = tri.filter(p=>!imposeNoms.has(norm(p.nom)));
  if(!triLibre.length && !imposes.length){ ciblesBase = []; }
  else if(!triLibre.length){ ciblesBase = imposes.slice(); }
  else {
    let nbVise, cap;
    // Nombre de parfums encore à choisir = cible réglementaire MOINS les validés déjà comptés.
    const nbImposes = imposes.length;
    if(mode==='strict'){
      // Nombre de parfums EXACT = règle + extras, moins les validés, borné par la place restante.
      nbVise = Math.min(triLibre.length, tailleReste, Math.max(0, (limiteReglementaire + parfumsEnPlus) - nbImposes));
      nbVise = Math.max(tailleReste>0?1:0, nbVise);
      cap = nbVise;                        // strict : on ne dépasse jamais le nombre visé
    } else {
      cap = Math.max(0, (opts.maxParfums || (taille<=6?3 : taille<=8?4 : taille<=16?6 : 8)) - nbImposes);
      nbVise = Math.min(cap, Math.max(tailleReste>0?1:0, Math.min(triLibre.length, tailleReste)));
    }
    const plafondParParfum = Math.max(1, Math.ceil(taille / Math.max(1, nbVise + nbImposes)));
    const retenus = triLibre.slice(0, nbVise);
    const quotas = new Map();
    retenus.forEach(p=>quotas.set(norm(p.nom), 0));
    let reste = tailleReste;
    // Round-robin : +1 à chaque parfum ayant encore du dispo et sous son plafond.
    let progres = true;
    while(reste>0 && progres){
      progres = false;
      for(const p of retenus){
        if(reste<=0) break;
        const k=norm(p.nom); const q=quotas.get(k);
        const dispoReelle=(p.stock||0)+(p.mutualise||0);
        if(q<plafondParParfum && q<dispoReelle){ quotas.set(k, q+1); reste--; progres=true; }
      }
    }
    // Reliquat via relance (parfums retenus relançables d'abord).
    if(reste>0){
      for(const p of retenus){
        if(reste<=0) break;
        if(!p.relanceOk) continue;
        const k=norm(p.nom); const q=quotas.get(k);
        const marge=plafondParParfum-q;
        if(marge>0){ const add=Math.min(marge,reste); quotas.set(k,q+add); reste-=add; }
      }
      // Ajout de nouveaux parfums relançables (hors retenus) — SANS jamais dépasser `cap`.
      if(reste>0){
        for(const p of triLibre){
          if(reste<=0 || quotas.size>=cap) break;
          const k=norm(p.nom);
          if(quotas.has(k) || !p.relanceOk) continue;
          const add=Math.min(plafondParParfum,reste); quotas.set(k,add); reste-=add;
        }
      }
      // Dernier recours : relâcher le plafond PAR PARFUM sur du dispo réel restant, sans nouveau parfum > cap.
      if(reste>0){
        for(const p of triLibre){
          if(reste<=0) break;
          const k=norm(p.nom); const q=quotas.get(k)||0;
          const dispoReelle=(p.stock||0)+(p.mutualise||0);
          const marge=dispoReelle-q;
          if(marge>0){ if(!quotas.has(k) && quotas.size>=cap) continue; const add=Math.min(marge,reste); quotas.set(k,q+add); reste-=add; }
        }
      }
    }
    // [v1191] Cibles finales = VALIDÉS d'abord (priorité de consommation du stock), puis le round-robin.
    ciblesBase = imposes.concat(
      retenus.concat(triLibre.filter(p=>!retenus.includes(p)))
        .filter(p=>quotas.get(norm(p.nom))>0)
        .map(p=>({nom:p.nom, qte:quotas.get(norm(p.nom))}))
    );
  }


  const props = [];
  const pushProp = (res, coutRang) => {
    if(res.total<=0) return;
    const complet = res.total>=taille && res.manqueTotal<=0;
    const cout = res.vR>0 ? 2 : res.vM>0 ? 1 : 0;
    props.push({
      taille, complet, total:res.total, lignes:res.lignes,
      ventilation:{ stock:res.vS, mutualise:res.vM, relance:res.vR },
      cout: Math.max(cout, coutRang||0),
      manque: Math.max(0, taille - res.total)
    });
  };

  // 1) Proposition SANS relance (stock + mutualisé seulement) : la moins coûteuse.
  pushProp(buildFrom(ciblesBase, false), 0);
  // 2) Proposition AVEC relance autorisée (comble le manque via production dédiée).
  pushProp(buildFrom(ciblesBase, true), 0);

  // Dédoublonne (une compo identique peut sortir deux fois) + trie par coût puis complétude.
  const seen = new Set();
  const uniq = props.filter(p=>{
    const sig = p.total+'|'+p.lignes.map(l=>norm(l.nom)+':'+l.qte+':'+l.stock+':'+l.mutualise+':'+l.relance).sort().join(',');
    if(seen.has(sig)) return false; seen.add(sig); return true;
  });
  uniq.sort((a,b)=> a.cout-b.cout || (b.complet?1:0)-(a.complet?1:0) || b.total-a.total );
  return uniq;
}

// [ORCHESTRATEUR] Point d'entrée unique : collecte les dispos puis génère les propositions
// pour la taille demandée, avec fallback vers une taille plus petite si aucune compo complète.
//   opts.mode : 'strict'|'flexible' · opts.parfumsSouhaites : [{nom,qte}]
// Renvoie { propositions:[...], fallback:[{taille, propositions}], meta }.
async function genererCompositionsCoffret(taille, dateLiv, heureLiv, opts){
  opts = opts || {};
  taille = +taille || 6;
  // Le filtre d'univers (grand format vs coffret standard) descend jusqu'à la collecte : on ne
  // propose jamais un parfum du mauvais type. opts.typeFiltre : 'grand' | 'standard' | undefined.
  const { parfums, meta } = await _collecterDisponibilites(dateLiv, heureLiv, { typeFiltre: opts.typeFiltre||null });
  const propositions = _composerCoffrets(parfums, taille, { ...opts, imposes: opts.imposes||[], seed: opts.seed||0 });

  // Fallback taille : si aucune proposition COMPLÈTE pour la taille demandée, on tente les
  // formats standards plus PETITS (25→16→8→6) et on retient le premier qui donne un coffret complet.
  let fallback = [];
  const aUnComplet = propositions.some(p=>p.complet);
  if(!aUnComplet){
    const tailles = (typeof BOX_SIZES!=='undefined' ? BOX_SIZES : [6,8,16,25]).filter(t=>t<taille).sort((a,b)=>b-a);
    for(const t of tailles){
      const ps = _composerCoffrets(parfums, t, opts);
      if(ps.some(p=>p.complet)){ fallback.push({ taille:t, propositions:ps.filter(p=>p.complet).slice(0,2) }); break; }
    }
  }
  return { propositions, fallback, meta:{ ...meta, taille, mode: opts.mode||'strict', typeFiltre: opts.typeFiltre||null, parfumsEnPlus: opts.parfumsEnPlus||0, limiteReglementaire: (typeof BOX_FLAVOR_LIMIT!=='undefined' && BOX_FLAVOR_LIMIT[taille]!=null)?BOX_FLAVOR_LIMIT[taille]:null } };
}






// ============================================================
// CONTRÔLE DES TEMPS — vérification + correction manuelle
// ------------------------------------------------------------
// Panneau qui, pour chaque séance de production, montre ses tâches (parfum, lot,
// durée), un état de santé, et des actions de correction rapides :
//   ✎ corriger durée/horaires · 🏷 réassigner parfum · ⏹ fermer chrono ouvert · 🗑 supprimer.
// Travaille sur TOUTES les sessions (pas seulement l'active).
// Réutilise les fonctions existantes : prodSessLoad, prodSessUpsert, prodTaskNet,
// prodSessReelMs, fmtDureeMs, _estimeFinTache.
// ============================================================

// Retrouve {sess, task} d'une tâche par son id, dans toutes les sessions.
function _ctFindTask(taskId){
  const sessions = prodSessLoad();
  for(const s of sessions){
    const t = (s.tasks||[]).find(x=>String(x.id)===String(taskId));
    if(t) return {sess:s, task:t};
  }
  return {sess:null, task:null};
}

// Analyse de santé d'une session : retourne {ok, alerts:[...], actifMs, reelMs}.
function _ctSanteSession(s){
  const tasks = (s.tasks||[]);
  const alerts = [];
  // Temps actif = UNION des intervalles de travail (et non somme brute), pour ne pas
  // compter deux fois un temps où plusieurs chronos tournent en parallèle. Un assemblage
  // de 3 parfums lancés en même temps = un seul temps réel de travail, pas la somme.
  const segs = [];
  tasks.forEach(t=>{
    const net = prodTaskNet(t);
    if(net<=0) return;
    const st = +t.start||0;
    if(st<=0) return;
    // fin effective bornée par le plafond (cohérent avec prodTaskNet) si chrono ouvert
    let en = t.end ? (+t.end) : (st + net);
    // on retire les pauses en ramenant la fin sur la durée nette (approximation sûre :
    // l'intervalle couvert ne dépasse jamais net depuis le début)
    if(en - st > net) en = st + net;
    segs.push([st, en]);
  });
  // union des segments triés
  segs.sort((a,b)=>a[0]-b[0]);
  let actifMs = 0;
  let curS = null, curE = null;
  for(const [a,b] of segs){
    if(curS===null){ curS=a; curE=b; continue; }
    if(a<=curE){ if(b>curE) curE=b; }      // chevauchement → on étend
    else { actifMs += (curE-curS); curS=a; curE=b; }  // disjoint → on clôt
  }
  if(curS!==null) actifMs += (curE-curS);

  tasks.forEach(t=>{
    const recs = Array.isArray(t.parfums) ? t.parfums.filter(r=>r!=null) : [];
    const estBatch = t.fromBatch || (t.composant && t.composant!=='complet');
    // tâche issue d'un batch mais sans parfum rattaché
    if(estBatch && recs.length===0){
      alerts.push({type:'sans_parfum', taskId:t.id, msg:`« ${t.label||'tâche'} » n'a aucun parfum rattaché.`});
    }
    // chrono resté ouvert anormalement
    if(!t.end && (+t.start>0) && (Date.now()-(+t.start))>CHRONO_ANORMAL_MS){
      alerts.push({type:'ouvert', taskId:t.id, msg:`« ${t.label||'tâche'} » est un chrono jamais arrêté.`});
    }
  });
  const reelMs = prodSessReelMs(s);
  // temps actif > temps réel = impossible physiquement (ne devrait plus arriver avec l'union,
  // sauf vrai chrono aberrant) → reste comme garde-fou de dernier recours.
  if(reelMs>0 && actifMs > reelMs + 60000){  // tolérance 1 min
    alerts.push({type:'actif_sup', taskId:null, msg:`Le temps actif (${fmtDureeMs(actifMs)}) dépasse le temps réel (${fmtDureeMs(reelMs)}).`});
  }
  return {ok:alerts.length===0, alerts, actifMs, reelMs};
}

// ---- VUE PRINCIPALE ----
// [v1303] FUSION « Temps de production » = 2 onglets dans un seul écran :
//   • Vérifier  → l'ancien « Contrôle des temps » (renderControleTemps) : relire/corriger les sessions.
//   • Analyser  → l'ancien « Temps de production » (renderTempsProduction) : durées agrégées.
// L'Atelier (chronos, saisie en direct) reste un écran distinct — choix de Benjamin.
// Principe zéro-régression : le conteneur monte une barre d'onglets + un sous-conteneur #tempsBody,
// puis DÉLÈGUE aux deux fonctions existantes, INCHANGÉES dans leur logique. Ces deux fonctions écrivent
// désormais dans #tempsBody s'il existe (sinon #main, pour tout appel direct/legacy) — voir leur 1re ligne.
let _tempsTab = 'verifier';   // 'verifier' | 'analyser'
function setTempsTab(t){ _tempsTab = (t==='analyser'?'analyser':'verifier'); renderTemps(); }
async function renderTemps(){
  const main = document.getElementById('main'); if(!main) return;
  const tab = _tempsTab;
  main.innerHTML = `<div class="topbar"><div><h1>⏱️ Temps de production</h1><p>Vérifie tes séances chronométrées, puis analyse les durées réelles</p></div></div>
    <div class="seg" style="display:flex;gap:6px;margin:4px 0 12px">
      <button class="btn ${tab==='verifier'?'gold':'ghost'} sm" onclick="setTempsTab('verifier')">🔍 Vérifier les séances</button>
      <button class="btn ${tab==='analyser'?'gold':'ghost'} sm" onclick="setTempsTab('analyser')">📊 Analyser les durées</button>
    </div>
    <div id="tempsBody"><p class="note">Chargement…</p></div>`;
  try{
    if(tab==='analyser'){ await renderTempsProduction(); }
    else { await renderControleTemps(); }
  }catch(e){ swallow(e,'renderTemps'); const b=document.getElementById('tempsBody'); if(b) b.innerHTML='<div class="panel"><p class="note">Affichage indisponible.</p></div>'; }
}
// [v1303] Compat : les anciens noms de vue (et les boutons internes qui y renvoient encore, ex.
// « ✎ Temps », « ⏱ Temps de production → ») atterrissent sur l'écran fusionné, au bon onglet.
async function renderControleTempsCompat(){ _tempsTab='verifier'; return renderTemps(); }
async function renderTempsProductionCompat(){ _tempsTab='analyser'; return renderTemps(); }

async function renderControleTemps(){
  // [v1303] Écrit dans le sous-conteneur d'onglets #tempsBody si présent (écran fusionné « Temps »),
  // sinon dans #main (appel direct/legacy) — aucun changement de comportement dans ce dernier cas.
  const main = document.getElementById('tempsBody') || document.getElementById('main'); if(!main) return;
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const recName = id => { const r = recipes.find(x=>+x.id===+id); return r?(r.produitNom||('recette #'+id)):('recette #'+id); };
  window._ctRecipes = recipes;  // pour le sélecteur de réassignation

  const sessions = prodSessLoad().slice().sort((a,b)=>{
    const ea = +a.start||0, eb = +b.start||0; return eb-ea;   // plus récent d'abord
  });

  const fmtHM = ms => { if(!(+ms>0)) return '—'; const d=new Date(+ms); return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'); };
  const compLbl = c => ({coques:'Coques', ganache:'Ganache', cremeux:'Crémeux', assemble:'Assemblage', complet:'Production', degustation:'Dégustation'})[c]||'Production';

  // Construit le HTML d'une tâche.
  function taskHTML(s, t, estLive){
    const recs = Array.isArray(t.parfums) ? t.parfums.filter(r=>r!=null) : [];
    const parfum = recs.length ? recs.map(recName).join(' + ') : null;
    const etape = compLbl(t.composant);
    const nom = parfum ? `${etape} — ${parfum}` : (t.label || `${etape} — (sans parfum)`);
    const lot = t.lotBase ? `lot ${esc(t.lotBase)}` : '';
    const ouvert = !t.end;
    const anormal = ouvert && (+t.start>0) && (Date.now()-(+t.start))>CHRONO_ANORMAL_MS;
    const sansParfum = (t.fromBatch || (t.composant && t.composant!=='complet')) && recs.length===0;
    const dur = fmtDureeMs(prodTaskNet(t));
    // ligne meta : lot · état/horaires
    let etat;
    if(anormal) etat = '⚠ jamais arrêté · ' + fmtHM(t.start) + ' → (en cours)';
    else if(ouvert) etat = 'en cours · démarrée ' + fmtHM(t.start);
    else etat = fmtHM(t.start) + ' → ' + fmtHM(t.end);
    if(t.finEstimee) etat += ' · fin estimée';
    const metaParts = [lot, etat].filter(Boolean).join(' · ');

    // Couleurs adaptées au fond (séance en cours = fond bordeaux → texte clair lisible).
    const cNom  = estLive ? '#f7ece0' : 'var(--bordeaux)';
    const cMeta = estLive ? (anormal||sansParfum ? '#f3b8ae' : '#d8c3ac') : (anormal||sansParfum ? '#b04a3e' : '#9a8a82');
    const cEtape= estLive ? '#f0c97a' : 'var(--caramel,#AA7C39)';
    const cDur  = estLive ? '#f0c97a' : 'var(--caramel,#AA7C39)';

    // actions
    const acts = [];
    if(sansParfum || anormal){
      if(sansParfum) acts.push(`<button class="btn ghost sm" onclick="ctReassignParfum('${t.id}')" title="Définir le parfum">🏷 Parfum</button>`);
      if(anormal){
        acts.push(`<button class="btn ghost sm" style="border-color:#e5b4ae;color:#b04a3e" onclick="ctFermerChrono('${t.id}')" title="Fermer ce chrono (fin estimée)">⏹ Fermer</button>`);
        acts.push(`<button class="btn ghost sm" style="border-color:#e5b4ae;color:#b04a3e" onclick="ctSupprimerTache('${t.id}')" title="Supprimer cette tâche">🗑</button>`);
      }
    } else {
      acts.push(`<button class="btn ghost sm" onclick="ctEditTache('${t.id}')" title="Corriger la durée ou les horaires">✎</button>`);
      acts.push(`<button class="btn ghost sm" onclick="ctReassignParfum('${t.id}')" title="Changer le parfum">🏷</button>`);
      acts.push(`<button class="btn ghost sm" onclick="ctSupprimerTache('${t.id}')" title="Supprimer cette tâche">🗑</button>`);
    }
    const durHtml = (!sansParfum && !anormal) ? `<span style="font-weight:700;color:${cDur};flex:none">${dur}</span>` : '';
    const bgAlert = (sansParfum||anormal) ? (estLive ? ';background:rgba(255,255,255,.08)' : ';background:#fdf6f5') : '';

    // Détail dépliable : étape précise + phase + horaires + lot complet.
    const detailId = 'ctd_'+t.id;
    const phase = t.phase ? esc(t.phase) : '';
    const detailHtml = `<div id="${detailId}" style="display:none;margin-top:6px;padding:8px 10px;border-radius:8px;background:${estLive?'rgba(255,255,255,.07)':'#faf6f0'};font-size:.78rem;color:${estLive?'#d8c3ac':'#6a5a52'}">
      <div><b style="color:${estLive?'#f0c97a':'var(--caramel,#AA7C39)'}">Étape :</b> ${esc(etape)}${phase?` · ${phase}`:''}</div>
      <div><b style="color:${estLive?'#f0c97a':'var(--caramel,#AA7C39)'}">Intitulé complet :</b> ${esc(t.label||nom)}</div>
      ${lot?`<div><b style="color:${estLive?'#f0c97a':'var(--caramel,#AA7C39)'}">Lot :</b> ${esc(t.lotBase)}</div>`:''}
      <div><b style="color:${estLive?'#f0c97a':'var(--caramel,#AA7C39)'}">Horaires :</b> ${fmtHM(t.start)}${t.end?(' → '+fmtHM(t.end)):' → (en cours)'}${t.finEstimee?' · fin estimée':''}</div>
      <div style="margin-top:5px"><button class="btn ghost sm" onclick="ctEditTache('${t.id}')">✎ Corriger</button> <button class="btn ghost sm" onclick="ctReassignParfum('${t.id}')">🏷 Parfum</button></div>
    </div>`;

    return `<div class="trace-step" style="display:block${bgAlert}">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
        <div style="min-width:0;cursor:pointer" onclick="ctToggleDetail('${detailId}',this)">
          <div style="font-weight:600;color:${cNom}"><span style="color:${cEtape}">▸</span> ${esc(nom)}</div>
          <div style="font-size:.76rem;color:${cMeta};margin-top:2px">${esc(metaParts)}</div></div>
        <div style="display:flex;align-items:center;gap:6px;flex:none">${durHtml}${acts.join('')}</div>
      </div>
      ${detailHtml}
    </div>`;
  }

  // Construit le HTML d'une session.
  function sessHTML(s, estLive){
    const sante = _ctSanteSession(s);
    const tasks = (s.tasks||[]);
    // Date en JJ/MM/AAAA (s.date est en ISO AAAA-MM-JJ, on reformate proprement).
    let dateLbl = '';
    if(s.date && /^\d{4}-\d{2}-\d{2}/.test(s.date)){
      const [Y,M,D] = s.date.slice(0,10).split('-');
      dateLbl = `${D}/${M}/${Y}`;
    } else if(s.start){
      dateLbl = new Date(+s.start).toLocaleDateString('fr-FR');
    }
    const heure = (s.start? new Date(+s.start).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}) : '');
    const healthBadge = sante.ok
      ? `<span style="font-size:.76rem;padding:3px 10px;border-radius:20px;font-weight:600;background:#e7f3ec;color:#3f7d52">✓ cohérent</span>`
      : `<span style="font-size:.76rem;padding:3px 10px;border-radius:20px;font-weight:600;background:#fdf3f2;color:#b04a3e">⚠ ${sante.alerts.length} alerte${sante.alerts.length>1?'s':''}</span>`;
    const alertBoxes = sante.alerts.filter(a=>a.type==='actif_sup').map(a=>
      `<div style="background:#fdf3f2;border:1px solid #e5b4ae;border-radius:9px;padding:9px 11px;font-size:.8rem;color:#7a3a32;margin:8px 0">${esc(a.msg)} Corrige un chrono ouvert ci-dessous.</div>`).join('');
    const tasksHtml = tasks.length ? tasks.map(t=>taskHTML(s,t,estLive)).join('') : '<p class="note" style="padding:6px 0">Aucune tâche dans cette séance.</p>';
    const totaux = tasks.length ? `<div style="display:flex;gap:10px;margin-top:10px;padding-top:10px;border-top:1px solid var(--hair)">
      <div style="flex:1;text-align:center;background:var(--creme-2,#F5F0E8);border-radius:9px;padding:8px"><div style="font-weight:700;color:var(--bordeaux);font-size:1.02rem">${fmtDureeMs(sante.actifMs)}</div><div style="font-size:.72rem;color:#9a8a82">actif total</div></div>
      <div style="flex:1;text-align:center;background:var(--creme-2,#F5F0E8);border-radius:9px;padding:8px"><div style="font-weight:700;color:var(--bordeaux);font-size:1.02rem">${fmtDureeMs(sante.reelMs)}</div><div style="font-size:.72rem;color:#9a8a82">réel (mur à mur)</div></div>
    </div>` : '';
    const liveStyle = estLive ? 'background:linear-gradient(135deg,#52252F,#3d1a22);color:#fff' : '';
    const liveTitleCol = estLive ? 'color:#fff' : 'color:var(--bordeaux)';
    const liveDateCol = estLive ? 'color:#e8d5c0' : 'color:#9a8a82';
    // Barre d'actions au niveau SÉANCE : clôturer/corriger l'heure de fin, scinder.
    const btnStyle = estLive ? 'background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.25);color:#f7ece0' : '';
    const sessActs = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px">
      ${!s.end
        ? `<button class="btn ghost sm" style="${btnStyle}" onclick="ctClotureSession('${s.id}')" title="Fixer l'heure de fin réelle de cette séance">⏹ Clôturer la séance</button>`
        : `<button class="btn ghost sm" style="${btnStyle}" onclick="ctClotureSession('${s.id}')" title="Corriger l'heure de fin">✎ Heure de fin</button>`}
      ${tasks.length>=2?`<button class="btn ghost sm" style="${btnStyle}" onclick="ctScinderSession('${s.id}')" title="Séparer si deux journées se sont mélangées">✂️ Scinder</button>`:''}
      <button class="btn ghost sm" style="${estLive?'background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.25);color:#f3b8ae':'border-color:#e5b4ae;color:#b04a3e'}" onclick="ctSupprimerSession('${s.id}')" title="Supprimer entièrement cette séance">🗑 Supprimer la séance</button>
    </div>`;
    return `<div class="card" style="${liveStyle}">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;padding-bottom:8px;border-bottom:1px solid ${estLive?'rgba(255,255,255,.15)':'var(--hair)'}">
        <div><div style="font-weight:700;${liveTitleCol}">${estLive?'⏱ Séance en cours':('Séance du '+esc(dateLbl))}</div>
        <div style="font-size:.78rem;${liveDateCol}">${tasks.length} tâche${tasks.length>1?'s':''}${heure?' · démarrée '+esc(heure):''}</div></div>
        ${healthBadge}
      </div>
      ${alertBoxes}
      ${tasksHtml}
      ${totaux}
      ${sessActs}
    </div>`;
  }

  const active = sessions.find(s=>!s.end);
  const passees = sessions.filter(s=>s.end);

  // [v1304] Quand cet écran est affiché DANS le conteneur à onglets « Temps de production »
  // (#tempsBody présent), son propre bandeau de titre est redondant avec celui du conteneur, et le
  // bouton « ⏱ Temps de production → » fait doublon avec l'onglet « Analyser les durées ». On les
  // masque donc dans ce cas. En appel autonome (legacy, sans conteneur), le bandeau complet est conservé.
  const _dansOnglets = !!document.getElementById('tempsBody');
  let html = _dansOnglets ? '' : `<div class="topbar"><div><h1>🔍 Contrôle des temps</h1>
    <p style="color:#8a776c;font-size:.86rem">Vérifie que chaque minute est rattachée au bon parfum. Corrige d'un geste si besoin.</p></div>
    <div class="flex"><button class="btn" onclick="goView('tempsproduction')">⏱ Temps de production →</button></div></div>`;

  // Bandeau récapitulatif : jusqu'où remonte l'historique des chronos.
  const nbSess = sessions.length;
  const nbTaches = sessions.reduce((n,s)=>n+((s.tasks||[]).length),0);
  if(nbSess>0){
    const debuts = sessions.map(s=>+s.start||0).filter(x=>x>0);
    const minTs = debuts.length?Math.min(...debuts):0;
    const maxTs = debuts.length?Math.max(...debuts):0;
    const fmtJ = ts => ts>0 ? new Date(ts).toLocaleDateString('fr-FR') : '—';
    const periode = (minTs && maxTs) ? (minTs===maxTs ? `le ${fmtJ(minTs)}` : `du ${fmtJ(minTs)} au ${fmtJ(maxTs)}`) : '—';
    html += `<div class="card" style="background:var(--creme-2,#F5F0E8);border:1px solid var(--hair)">
      <div style="font-size:.86rem;color:#6a5a52">📒 <b>${nbSess}</b> séance${nbSess>1?'s':''} enregistrée${nbSess>1?'s':''} · <b>${nbTaches}</b> tâche${nbTaches>1?'s':''} chronométrée${nbTaches>1?'s':''}<br>
      Historique disponible <b>${periode}</b>.</div>
      <div style="font-size:.78rem;color:#9a8a82;margin-top:6px">Seules les productions qui ont été chronométrées apparaissent ici. Celles faites sans lancer de chrono n'ont pas de temps à contrôler.</div>
    </div>`;
  }

  if(active) html += sessHTML(active, true);
  if(passees.length){
    html += passees.map(s=>sessHTML(s,false)).join('');
  }
  if(!active && !passees.length){
    html += `<div class="card"><p class="note">Aucune séance de production enregistrée pour l'instant.</p></div>`;
  }

  main.innerHTML = html;
}

// ---- ACTIONS DE CORRECTION ----

// Déplie / replie le détail d'une tâche (chevron).
function ctToggleDetail(detailId, el){
  const d = document.getElementById(detailId);
  if(!d) return;
  const open = d.style.display==='none';
  d.style.display = open ? 'block' : 'none';
  // fait pivoter le chevron ▸ → ▾
  const chev = el && el.querySelector('span');
  if(chev) chev.textContent = open ? '▾' : '▸';
}

// ✎ Corriger durée / horaires d'une tâche (toutes sessions).
function ctEditTache(taskId){
  const {sess, task} = _ctFindTask(taskId);
  if(!task){ toast('Tâche introuvable'); return; }
  const netMin = Math.round(prodTaskNet(task)/60000);
  const fmtHM = ms => { const d=new Date(+ms); return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'); };
  const startHM = (+task.start>0) ? fmtHM(task.start) : '';
  const endHM = task.end ? fmtHM(task.end) : '';
  const pauseMin = Math.round(((+task.pausedAccum||0))/60000);
  openModal(`<h3>Corriger le temps — ${esc(task.label||'tâche')}</h3>
    <p class="note">${task.end?'Tâche terminée : corrige sa durée ou ses horaires.':'Tâche en cours.'}${pauseMin>0?`<br>Pauses déjà déduites : <b>${pauseMin} min</b> (conservées).`:''}</p>
    <div class="field"><label>Durée nette (minutes)</label>
      <input type="number" min="0" step="1" id="cte_dur" value="${netMin}" inputmode="numeric"></div>
    <details style="margin:6px 0">
      <summary style="cursor:pointer;color:var(--caramel,#AA7C39);font-weight:600">Ou saisir les horaires réels</summary>
      <div class="row2" style="margin-top:8px">
        <div class="field"><label>Heure de début</label><input type="time" id="cte_start" value="${startHM}"></div>
        <div class="field"><label>Heure de fin</label><input type="time" id="cte_end" value="${endHM}"></div>
      </div>
      <p class="note">Si renseignés, les horaires priment sur la durée. Durée nette = (fin − début) − pauses.</p>
    </details>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="ctEditTacheSave('${task.id}')">Enregistrer</button>
    </div>`);
}

function ctEditTacheSave(taskId){
  const {sess, task} = _ctFindTask(taskId);
  if(!sess || !task){ toast('Tâche introuvable'); return; }
  const pauseMs = (+task.pausedAccum||0);
  const startHM = (val('cte_start')||'').trim();
  const endHM = (val('cte_end')||'').trim();
  const durMin = +val('cte_dur');
  const dayBase = new Date(+task.start||Date.now()); dayBase.setSeconds(0,0);
  const tsFromHM = hm => { const m=/^(\d{1,2}):(\d{2})$/.exec(hm); if(!m) return null; const d=new Date(dayBase); d.setHours(+m[1],+m[2],0,0); return d.getTime(); };
  const startTs = tsFromHM(startHM);
  const endTs = endHM ? tsFromHM(endHM) : null;
  // MODE horaires (prioritaire)
  if(startTs!=null && endHM){
    if(endTs==null){ toast('Heure de fin invalide'); return; }
    if(endTs < startTs){ toast('La fin ne peut pas précéder le début'); return; }
    const net = (endTs - startTs) - pauseMs;
    if(net < 0){ toast('Durée négative : les pauses dépassent l\'intervalle'); return; }
    task.start = startTs; task.end = endTs; task.pauseAt = null; task.finEstimee = false;
    prodSessUpsert(sess); closeModal(); toast('Temps corrigé ✓'); renderControleTemps(); return;
  }
  // MODE durée nette (sur la base du début existant)
  if(durMin>=0){
    const base = (+task.start>0) ? +task.start : Date.now();
    task.start = base;
    task.end = base + durMin*60000 + pauseMs;
    task.pauseAt = null; task.finEstimee = false;
    prodSessUpsert(sess); closeModal(); toast('Durée corrigée ✓'); renderControleTemps(); return;
  }
  toast('Saisie invalide');
}

// 🏷 Réassigner / définir le parfum d'une tâche.
function ctReassignParfum(taskId){
  const {sess, task} = _ctFindTask(taskId);
  if(!task){ toast('Tâche introuvable'); return; }
  const recipes = window._ctRecipes || [];
  const cur = new Set((Array.isArray(task.parfums)?task.parfums:[]).map(Number));
  const lignes = recipes.slice().sort((a,b)=>(a.produitNom||'').localeCompare(b.produitNom||''))
    .map(r=>`<label style="display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid var(--hair);border-radius:9px;margin-bottom:5px;cursor:pointer">
      <input type="checkbox" class="ct_pf" value="${r.id}"${cur.has(+r.id)?' checked':''} style="width:18px;height:18px;flex:none">
      <span>${esc(r.produitNom||('recette #'+r.id))}</span></label>`).join('');
  openModal(`<h3>Parfum(s) de la tâche</h3>
    <p class="note">Coche le ou les parfums réellement concernés par cette tâche. <b>Un seul</b> si tu t'es trompé en en déclarant deux ; <b>plusieurs</b> si la tâche est mutualisée (le temps sera partagé entre eux).</p>
    <div style="max-height:48vh;overflow:auto;margin:8px 0">${lignes||'<p class="note">Aucune recette enregistrée.</p>'}</div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="ctReassignParfumSave('${task.id}')">Enregistrer</button>
    </div>`);
}

function ctReassignParfumSave(taskId){
  const {sess, task} = _ctFindTask(taskId);
  if(!sess || !task){ toast('Tâche introuvable'); return; }
  const checks = Array.from(document.querySelectorAll('.ct_pf:checked'))
    .map(c=>+c.value).filter(n=>Number.isFinite(n));
  task.parfums = checks;   // 0, 1 ou plusieurs parfums
  // met à jour le libellé pour rester cohérent à l'affichage
  const recipes = window._ctRecipes || [];
  const compLbl = ({coques:'Coques', ganache:'Ganache', cremeux:'Crémeux', assemble:'Assemblage', complet:'Production', degustation:'Dégustation'})[task.composant]||'Production';
  if(checks.length){
    const noms = checks.map(rid=>{ const r=recipes.find(x=>+x.id===rid); return r?(r.produitNom||''):''; }).filter(Boolean);
    task.label = `${compLbl} — ${noms.join(' + ')}`.trim();
  }
  prodSessUpsert(sess); closeModal();
  toast(checks.length>1?`${checks.length} parfums rattachés ✓`:(checks.length===1?'Parfum mis à jour ✓':'Parfum retiré ✓'));
  renderControleTemps();
}

// ⏹ Fermer un chrono resté ouvert (fin estimée), réutilise _estimeFinTache.
function ctFermerChrono(taskId){
  const {sess, task} = _ctFindTask(taskId);
  if(!sess || !task){ toast('Tâche introuvable'); return; }
  if(task.end){ toast('Cette tâche est déjà terminée'); renderControleTemps(); return; }
  if((+task.pauseAt||0)>0){ task.pausedAccum=(+task.pausedAccum||0)+Math.max(0,Date.now()-(+task.pauseAt)); task.pauseAt=null; }
  task.end = _estimeFinTache(sess, task);
  if(task.end <= task.start) task.end = task.start + 30*60000;
  task.finEstimee = true;
  prodSessUpsert(sess); toast('Chrono fermé ✓'); renderControleTemps();
}

// 🗑 Supprimer une tâche (doublon ou erreur).
function ctSupprimerTache(taskId){
  const {sess, task} = _ctFindTask(taskId);
  if(!sess || !task){ toast('Tâche introuvable'); return; }
  openModal(`<h3>Supprimer cette tâche ?</h3>
    <p class="note">« ${esc(task.label||'tâche')} » sera retirée de la séance. Son temps ne sera plus compté. Action définitive.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" style="background:#b04a3e;border-color:#b04a3e" onclick="ctSupprimerTacheRun('${task.id}')">Supprimer</button>
    </div>`);
}

function ctSupprimerTacheRun(taskId){
  const {sess, task} = _ctFindTask(taskId);
  if(!sess || !task){ toast('Tâche introuvable'); return; }
  sess.tasks = (sess.tasks||[]).filter(x=>String(x.id)!==String(taskId));
  prodSessUpsert(sess); closeModal(); toast('Tâche supprimée ✓'); renderControleTemps();
}

// ============================================================
// CONTRÔLE DES TEMPS — gestion au niveau SÉANCE
// Clôturer une séance restée ouverte · corriger son heure de fin · scinder une
// séance où plusieurs journées se sont mélangées (détection d'un grand trou).
// ============================================================

// Helper : retrouve une session par id.
function _ctFindSession(sessId){
  return prodSessLoad().find(s=>String(s.id)===String(sessId)) || null;
}

// Heure de fin "naturelle" suggérée = fin de la dernière tâche terminée de la séance.
function _ctFinSuggeree(s){
  const fins = (s.tasks||[]).filter(t=>t.end && +t.end>0).map(t=>+t.end);
  if(fins.length) return Math.max(...fins);
  // sinon, début de la dernière tâche + 30 min, ou start de session
  const starts = (s.tasks||[]).map(t=>+t.start||0).filter(x=>x>0);
  if(starts.length) return Math.max(...starts) + 30*60000;
  return (+s.start||Date.now());
}

// ⏹ Clôturer une séance ouverte / ✎ corriger son heure de fin.
function ctClotureSession(sessId){
  const s = _ctFindSession(sessId);
  if(!s){ toast('Séance introuvable'); return; }
  const ouverte = !s.end;
  const suggestee = s.end ? +s.end : _ctFinSuggeree(s);
  const d = new Date(suggestee);
  const dateVal = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const heureVal = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
  const nbOuvertes = (s.tasks||[]).filter(t=>!t.end).length;
  openModal(`<h3>${ouverte?'Clôturer la séance':'Corriger l\'heure de fin'}</h3>
    <p class="note">${ouverte?'Fixe l\'heure à laquelle cette séance s\'est réellement terminée. Les tâches encore ouvertes seront fermées à cette heure.':'Ajuste l\'heure de fin de cette séance.'}${nbOuvertes>0?`<br><b>${nbOuvertes}</b> tâche(s) encore ouverte(s) seront fermées.`:''}</p>
    <div class="row2">
      <div class="field"><label>Date de fin</label><input type="date" id="ctcs_date" value="${dateVal}"></div>
      <div class="field"><label>Heure de fin</label><input type="time" id="ctcs_heure" value="${heureVal}"></div>
    </div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="ctClotureSessionSave('${s.id}')">${ouverte?'Clôturer':'Enregistrer'}</button>
    </div>`);
}

function ctClotureSessionSave(sessId){
  const s = _ctFindSession(sessId);
  if(!s){ toast('Séance introuvable'); return; }
  const dateStr = (val('ctcs_date')||'').trim();
  const heureStr = (val('ctcs_heure')||'').trim();
  const m = /^(\d{1,2}):(\d{2})$/.exec(heureStr);
  if(!dateStr || !m){ toast('Date ou heure invalide'); return; }
  const fin = new Date(dateStr+'T00:00:00'); fin.setHours(+m[1], +m[2], 0, 0);
  const finTs = fin.getTime();
  if(!(finTs>0)){ toast('Date/heure invalide'); return; }
  // la fin ne peut précéder le début de la première tâche
  const debuts = (s.tasks||[]).map(t=>+t.start||0).filter(x=>x>0);
  const minStart = debuts.length?Math.min(...debuts):(+s.start||0);
  if(minStart>0 && finTs<minStart){ toast('La fin ne peut pas précéder le début de la séance'); return; }
  // fermer les tâches encore ouvertes à cette heure (en figeant les pauses en cours)
  (s.tasks||[]).forEach(t=>{
    if(!t.end){
      if((+t.pauseAt||0)>0){ t.pausedAccum=(+t.pausedAccum||0)+Math.max(0,Date.now()-(+t.pauseAt)); t.pauseAt=null; }
      // fin = heure de clôture, mais jamais avant le début de la tâche
      t.end = (finTs >= (+t.start||0)) ? finTs : (+t.start||finTs);
      t.finEstimee = true;
    }
  });
  s.end = finTs;
  prodSessUpsert(s);
  if(typeof markUnsaved==='function') markUnsaved();
  closeModal(); toast('Séance clôturée ✓'); renderControleTemps();
}

// ✂️ Scinder une séance : détecte les "trous" entre tâches et propose un point de coupure.
function ctScinderSession(sessId){
  const s = _ctFindSession(sessId);
  if(!s){ toast('Séance introuvable'); return; }
  const tasks = (s.tasks||[]).slice().filter(t=>+t.start>0).sort((a,b)=>(+a.start)-(+b.start));
  if(tasks.length<2){ toast('Trop peu de tâches pour scinder'); return; }
  // calcule les écarts entre la fin d'une tâche et le début de la suivante
  const trous = [];
  for(let i=1;i<tasks.length;i++){
    const prevEnd = +tasks[i-1].end || +tasks[i-1].start;
    const curStart = +tasks[i].start;
    const gap = curStart - prevEnd;
    if(gap>0) trous.push({idx:i, gap, at:curStart, prevEnd});
  }
  trous.sort((a,b)=>b.gap-a.gap);   // plus grand trou d'abord
  if(!trous.length || trous[0].gap < 30*60000){
    openModal(`<h3>Scinder la séance</h3>
      <p class="note">Aucune coupure évidente détectée (pas de pause de plus de 30 min entre deux tâches). La séance semble continue.</p>
      <div class="modal-actions"><button class="btn" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  const fmtDT = ts => { const d=new Date(ts); return d.toLocaleDateString('fr-FR')+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'); };
  const opts = trous.slice(0,5).map((tr,i)=>{
    const gapH = Math.round(tr.gap/3600000*10)/10;
    return `<label style="display:flex;align-items:center;gap:8px;padding:9px 11px;border:1px solid var(--hair);border-radius:9px;margin-bottom:6px;cursor:pointer">
      <input type="radio" name="ct_coupe" value="${tr.idx}"${i===0?' checked':''} style="width:18px;height:18px;flex:none">
      <span style="font-size:.85rem">Couper avant la tâche de <b>${esc(fmtDT(tr.at))}</b><br>
      <span style="color:#9a8a82;font-size:.78rem">pause de ${gapH>=1?gapH+' h':Math.round(tr.gap/60000)+' min'} avant cette tâche</span></span></label>`;
  }).join('');
  openModal(`<h3>Scinder la séance en deux</h3>
    <p class="note">Choisis où couper : les tâches avant le point de coupure restent dans cette séance, celles après forment une nouvelle séance. Utile quand deux journées se sont mélangées.</p>
    ${opts}
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="ctScinderSessionSave('${s.id}')">Scinder ici</button>
    </div>`);
}

function ctScinderSessionSave(sessId){
  const s = _ctFindSession(sessId);
  if(!s){ toast('Séance introuvable'); return; }
  const sel = document.querySelector('input[name="ct_coupe"]:checked');
  if(!sel){ toast('Choisis un point de coupure'); return; }
  const tasks = (s.tasks||[]).slice().filter(t=>+t.start>0).sort((a,b)=>(+a.start)-(+b.start));
  const idx = +sel.value;
  if(!(idx>0 && idx<tasks.length)){ toast('Point de coupure invalide'); return; }
  const avant = tasks.slice(0, idx);
  const apres = tasks.slice(idx);
  if(!avant.length || !apres.length){ toast('Coupure invalide'); return; }
  // Séance 1 (existante) : tâches avant, fin = dernière fin connue avant la coupure
  const finAvant = Math.max(...avant.map(t=>+t.end||+t.start));
  s.tasks = avant;
  s.end = s.end ? Math.min(+s.end, finAvant) : finAvant;
  prodSessUpsert(s);
  // Séance 2 (nouvelle) : tâches après
  const debutApres = Math.min(...apres.map(t=>+t.start));
  const finApres = apres.some(t=>!t.end) ? null : Math.max(...apres.map(t=>+t.end));
  const d2 = new Date(debutApres);
  const nouvelle = {
    id: prodNewId(),
    date: `${d2.getFullYear()}-${String(d2.getMonth()+1).padStart(2,'0')}-${String(d2.getDate()).padStart(2,'0')}`,
    start: debutApres,
    end: finApres,
    note: (s.note||'')+' (scindée)',
    tasks: apres
  };
  prodSessUpsert(nouvelle);
  if(typeof markUnsaved==='function') markUnsaved();
  closeModal(); toast('Séance scindée en deux ✓'); renderControleTemps();
}

// 🗑 Supprimer entièrement une séance (erreur de saisie, séance fantôme…).
function ctSupprimerSession(sessId){
  const s = _ctFindSession(sessId);
  if(!s){ toast('Séance introuvable'); return; }
  const nbT = (s.tasks||[]).length;
  openModal(`<h3>Supprimer toute la séance ?</h3>
    <p class="note">Cette séance${nbT>0?` et ses <b>${nbT}</b> tâche(s)`:''} seront définitivement supprimées. ${nbT>0?'Leur temps ne sera plus compté nulle part. ':''}Action irréversible.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" style="background:#b04a3e;border-color:#b04a3e" onclick="ctSupprimerSessionRun('${s.id}')">Supprimer la séance</button>
    </div>`);
}

function ctSupprimerSessionRun(sessId){
  const s = _ctFindSession(sessId);
  if(!s){ toast('Séance introuvable'); return; }
  prodSessRemove(s.id);
  if(typeof markUnsaved==='function') markUnsaved();
  closeModal(); toast('Séance supprimée ✓'); renderControleTemps();
}



// ============================================================
// CORRECTION DES CHRONOS D'ATELIER RESTÉS OUVERTS
// ------------------------------------------------------------
// Une tâche jamais arrêtée (t.end absent) voit sa durée gonfler jusqu'à « maintenant »,
// faussant le suivi des temps. Cet outil détecte ces tâches anormales et les ferme
// proprement, en estimant une fin réaliste :
//   • fin de la dernière tâche TERMINÉE de la même session, si elle existe ;
//   • sinon, début de la tâche + durée médiane des tâches du même nom (ou 30 min par défaut).
// ============================================================

const CHRONO_ANORMAL_MS = 6*60*60*1000; // au-delà de 6 h ouvert = anormal (chrono oublié)

// Détecte les tâches ouvertes anormalement longues (sans rien modifier).
function _chronosOuvertsAnormaux(){
  const sessions = (typeof prodSessLoad==='function') ? prodSessLoad() : [];
  const out = [];
  sessions.forEach(s=>{
    (s.tasks||[]).forEach(t=>{
      if(t.end) return;                          // déjà terminée
      if(!(+t.start>0)) return;
      const ouvertMs = Date.now() - (+t.start);
      if(ouvertMs <= CHRONO_ANORMAL_MS) return;  // encore dans le raisonnable (peut-être en cours réel)
      out.push({ sessId:s.id, date:s.date, taskId:t.id, nom:t.nom||'(tâche)', start:+t.start, ouvertMs });
    });
  });
  return out;
}

// Estime une fin réaliste pour une tâche restée ouverte.
function _estimeFinTache(s, t){
  // 1) fin de la dernière tâche terminée de la session (cohérence avec le déroulé réel)
  const finsConnues = (s.tasks||[]).filter(x=>x.end && +x.end>+t.start).map(x=>+x.end);
  if(finsConnues.length){
    return Math.min(...finsConnues.filter(f=>f>+t.start)) || (+t.start + 30*60000);
  }
  // 2) durée médiane des tâches de même nom (terminées), sinon 30 min
  const memeNom = (s.tasks||[]).filter(x=>x.end && (x.nom||'')===(t.nom||'')).map(x=>prodTaskNet(x)).filter(d=>d>0).sort((a,b)=>a-b);
  const med = memeNom.length ? memeNom[Math.floor(memeNom.length/2)] : 30*60000;
  return +t.start + med;
}

// Aperçu (sans écrire).
function corrigerChronosOuvertsPreview(){
  const anomalies = _chronosOuvertsAnormaux();
  if(!anomalies.length){
    openModal(`<h2>Chronos restés ouverts</h2>
      <p class="note">Aucun chrono anormal détecté. Tout est cohérent ✓</p>
      <div class="flex" style="justify-content:flex-end"><button class="btn" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  const lignes = anomalies.slice(0,12).map(a=>{
    const h = Math.round(a.ouvertMs/3600000);
    return `<div style="font-size:.8rem;color:#6a5a52;padding:4px 0;border-bottom:1px solid #f3ede3">
      ${esc(a.nom)} · ${esc(a.date||'')} · <b style="color:#b04a3e">ouvert depuis ~${h} h</b></div>`;
  }).join('');
  openModal(`<h2>Chronos d'atelier restés ouverts</h2>
    <p class="note">${anomalies.length} chrono(s) n'ont jamais été arrêtés et gonflent le suivi des temps. Je peux les fermer proprement en estimant une fin réaliste (fin de la dernière tâche terminée de la séance, ou durée habituelle de la même tâche).</p>
    ${lignes}${anomalies.length>12?`<p class="note">… et ${anomalies.length-12} autre(s).</p>`:''}
    <p class="note" style="margin-top:10px;color:#b04a3e">⚠️ Sauvegarde iCloud conseillée avant.</p>
    <div class="flex" style="justify-content:flex-end;gap:8px;margin-top:12px">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="corrigerChronosOuvertsRun()">Fermer ${anomalies.length} chrono(s)</button>
    </div>`);
}

// Exécute la fermeture (écrit).
function corrigerChronosOuvertsRun(){
  try{
    closeModal();
    const sessions = (typeof prodSessLoad==='function') ? prodSessLoad() : [];
    let n = 0;
    sessions.forEach(s=>{
      let modif = false;
      (s.tasks||[]).forEach(t=>{
        if(t.end) return;
        if(!(+t.start>0)) return;
        if((Date.now()-(+t.start)) <= CHRONO_ANORMAL_MS) return;
        // fige une éventuelle pause en cours
        if((+t.pauseAt||0)>0){ t.pausedAccum=(+t.pausedAccum||0)+Math.max(0,Date.now()-(+t.pauseAt)); t.pauseAt=null; }
        t.end = _estimeFinTache(s, t);
        if(t.end <= t.start) t.end = t.start + 30*60000;
        t.finEstimee = true;   // trace : fin estimée par l'outil, pas mesurée
        modif = true; n++;
      });
      if(modif) prodSessUpsert(s);
    });
    if(typeof markUnsaved==='function') markUnsaved();
    toast(`✓ ${n} chrono(s) fermé(s) proprement`);
    // [v1303] L'écran « Temps de production » vit désormais sous la vue fusionnée 'temps' (onglet
    // Analyser) ; on rafraîchit via le conteneur d'onglets s'il est actif, sinon l'ancien direct.
    if(typeof view!=='undefined'){
      if(view==='temps' && typeof renderTemps==='function') renderTemps();
      else if(view==='tempsproduction' && typeof renderTempsProduction==='function') renderTempsProduction();
    }
  }catch(e){ toast('Erreur : '+(e&&e.message||e)); }
}

// ============================================================
// RAPPORT « TEMPS DE PRODUCTION »
// ------------------------------------------------------------
// Deux mesures, côte à côte :
//   • Durée RÉELLE : prodDebutTs → prodTermineTs de chaque batch (temps mur-à-mur)
//   • Temps ACTIF  : cumul des tâches chrono d'atelier (prodTaskNet), via les sessions
// Agrégé en 4 niveaux : total général · par parfum · par jour · ligne par batch.
// S'appuie sur les fonctions existantes (prodSessLoad, prodTaskNet, prodNomComplet).
// ============================================================

let _tempsProdPeriode = '30';   // '7' | '30' | '90' | 'tout'
function setTempsProdPeriode(p){ _tempsProdPeriode = p; renderTempsProduction(); }

// Formate une durée en millisecondes -> "Xh YY" (ou "Ym" si < 1h).
function fmtDureeMs(ms){
  ms = +ms || 0;
  if(ms<=0) return '—';
  const totMin = Math.round(ms/60000);
  const h = Math.floor(totMin/60), m = totMin%60;
  if(h<=0) return m+' min';
  return h+' h '+(m<10?'0':'')+m;
}

// Durée réelle d'un batch (début -> fin). Renvoie ms, ou 0 si incalculable.
function _batchDureeReelleMs(p){
  const deb = p.prodDebutTs || p.prodTimestamp || (p.date ? p.date+'T08:00:00' : '');
  const fin = p.prodTermineTs || '';
  if(!deb || !fin) return 0;
  const d = new Date(deb).getTime(), f = new Date(fin).getTime();
  if(!(f>d)) return 0;
  return f - d;
}

// [v1309] Filtre des productions comptées comme un BATCH pour les moyennes de temps.
// Extrait en fonction pure pour être TESTABLE (et donc protégé contre toute régression).
// Règle : ne compter que les macarons RÉELLEMENT PRODUITS (complet / assemblé). Une production
// peut aussi être un simple COMPOSANT (fournée de coques, ganache, chantache, dégustation) : la
// compter comme un batch gonflerait le dénominateur et écraserait la moyenne — c'était le bug qui
// donnait « Framboise : 17 min/batch », soit moins que la seule cuisson des coques (impossible).
// Même règle que le reste de l'app (cf. filtre historique : c!=='complet' && c!=='assemble' → exclu).
// [v1312] BATCHES CHRONOMÉTRÉS — dénominateur des moyennes de temps.
// BUG STRUCTUREL : le numérateur (temps actif) ne provient QUE des séances chronométrées, alors que
// le dénominateur comptait TOUTES les productions terminées — y compris celles faites SANS chrono
// (« 7 batches mesurés · 16 sans durée » dans les données réelles). On divisait le temps de 7 batches
// par 23 : la moyenne s'effondrait (Coco Rafaello à 20 min, sous la seule cuisson des coques).
//
// [CORRECTIF v1312] La v1311 s'appuyait sur le champ `atelierTaskId` pour repérer un batch chronométré.
// ERREUR : ce champ n'est posé que dans certains flux (« lancer un batch avec fiche ») et reste vide
// dans l'usage réel de Benjamin → le dénominateur tombait à ZÉRO partout. On relie désormais une
// production à son chrono par un lien qui existe VRAIMENT dans les données : sa RECETTE + sa DATE.
// Un batch de framboise du 7 juillet est « chronométré » s'il existe, ce jour-là, une séance
// comportant une tâche rattachée à la framboise.
// Renvoie un Set de clés 'recipeId|YYYY-MM-DD'.
function _clesChronometrees(sessions, sinceStr){
  const out = new Set();
  (sessions||[]).forEach(s=>{
    const jour = (s.date||'').slice(0,10);
    if(!jour) return;
    if(sinceStr && jour < sinceStr) return;
    (s.tasks||[]).forEach(t=>{
      const net = (typeof prodTaskNet==='function') ? prodTaskNet(t) : 0;
      if(!(net>0)) return;                       // une tâche à 0 n'a rien mesuré
      (Array.isArray(t.parfums)?t.parfums:[]).forEach(r=>{
        const n = +r; if(Number.isFinite(n) && n>0) out.add(n + '|' + jour);
      });
    });
  });
  return out;
}

function _estBatchComptable(p, sinceStr, clesChrono){
  if(!p) return false;
  const fini = (p.prodStatut==='termine') || (p.prodTermineTs && String(p.prodTermineTs).length>0) || (p.prodStatut==null);
  if(!fini) return false;
  const c = p.composant || 'complet';
  if(c!=='complet' && c!=='assemble') return false;   // exclut coques / ganache / chantache / dégustation
  const d = (p.prodTermineTs||p.prodTimestamp||p.date||'').slice(0,10);
  if(d < sinceStr) return false;
  // [v1312] Ne compte au dénominateur QUE les batches dont la recette a été chronométrée CE JOUR-LÀ,
  // pour que numérateur et dénominateur portent sur le même périmètre.
  // (Sans ensemble fourni — appel legacy —, l'ancien comportement est conservé.)
  if(clesChrono instanceof Set){
    if(p.recipeId==null) return false;
    const rid = +p.recipeId;
    // Une production peut DÉMARRER un jour et se TERMINER le lendemain (repos de nuit) : on accepte
    // le rapprochement sur l'une OU l'autre des dates, sinon des batches réellement chronométrés
    // seraient exclus à tort.
    const jours = new Set();
    [p.prodDebutTs, p.prodTimestamp, p.prodTermineTs, p.date].forEach(x=>{
      const j = String(x||'').slice(0,10);
      if(j) jours.add(j);
    });
    for(const j of jours){ if(clesChrono.has(rid + '|' + j)) return true; }
    return false;
  }
  return true;
}

// [v1310] POIDS DE PRODUCTION PAR RECETTE — base du PRORATA de répartition du temps mutualisé.
// Règle métier (Benjamin) : « on ne peut pas faire 50/50 entre 300 pièces et 10 pièces sur la même
// étape ». Une tâche partagée (ex. cuisson d'une fournée mixte) doit donc être répartie AU PRORATA
// des quantités, et non à parts égales.
//
// Difficulté résolue ici : les quantités ne sont PAS dans la même unité selon le composant —
// une production 'coques' stocke ses pièces en COQUES (×2 macarons), une production 'complet' en
// MACARONS. Les comparer brutalement ferait compter une fournée de coques pour le double.
// On ramène donc tout à une base commune : le MACARON ÉQUIVALENT.
//
// Renvoie { recipeId: qteEnMacaronsEquivalents } pour les productions de la fenêtre.
function _poidsProductionParRecette(prods, sinceStr){
  const out = {};
  (prods||[]).forEach(p=>{
    if(!p || p.recipeId==null) return;
    const d = (p.prodTermineTs||p.prodTimestamp||p.date||'').slice(0,10);
    if(sinceStr && d < sinceStr) return;
    const q = (typeof prodQteAffichee==='function') ? prodQteAffichee(p) : (+p.qteReelle||+p.qteTheorique||0);
    if(!(q>0)) return;
    const comp = p.composant || 'complet';
    // Conversion en macarons équivalents : les coques sont stockées ×2.
    const macEq = (comp==='coques') ? (q / COQUES_PAR_MACARON) : q;
    if(!(macEq>0)) return;
    const rid = +p.recipeId;
    out[rid] = (out[rid]||0) + macEq;
  });
  return out;
}

// [v1310] Calcule les PARTS (poids relatifs, somme = 1) de chaque recette d'une tâche mutualisée.
// - Si les quantités sont connues pour au moins une recette → prorata des quantités.
// - Sinon (aucune quantité exploitable) → repli à parts égales, pour ne jamais perdre de temps
//   ni produire NaN. Le repli est signalé par `prorata:false` afin de rester traçable.
function _partsMutualisation(recIds, poids){
  const ids = (recIds||[]).map(x=>+x).filter(x=>Number.isFinite(x)&&x>0);
  const parts = {};
  if(!ids.length) return { parts, prorata:false };
  const total = ids.reduce((s,r)=>s + (+(poids||{})[r] || 0), 0);
  if(total > 0){
    ids.forEach(r=>{ parts[r] = (+(poids||{})[r] || 0) / total; });
    return { parts, prorata:true };
  }
  // Aucune quantité connue → parts égales (repli honnête plutôt qu'un chiffre inventé).
  ids.forEach(r=>{ parts[r] = 1/ids.length; });
  return { parts, prorata:false };
}

// [v1313] Format court pour les très petites durées (temps par macaron) : « 1 min 12 s », « 48 s ».
// fmtDureeMs arrondit à la minute et afficherait « 1 min » ou « 0 min », inexploitable à cette échelle.
function _fmtMinSec(ms){
  const s = Math.round((+ms||0)/1000);
  if(s<=0) return '—';
  const m = Math.floor(s/60), r = s%60;
  if(m<=0) return r+' s';
  return m+' min'+(r>0?(' '+r+' s'):'');
}

async function renderTempsProduction(){
  // [v1303] Écrit dans #tempsBody si présent (écran fusionné « Temps »), sinon #main (legacy).
  const main = document.getElementById('tempsBody') || document.getElementById('main'); if(!main) return;
  const jours = _tempsProdPeriode==='tout' ? 100000 : (+_tempsProdPeriode||30);
  const since = new Date(); since.setDate(since.getDate()-jours);
  const sinceStr = ymdLocal(since);

  const recipes = await db.recipes.toArray().catch(()=>[]);
  window._allRecipesCache = recipes;
  const prods = await db.productions.toArray().catch(()=>[]);
  const sessions = (typeof prodSessLoad==='function') ? prodSessLoad() : [];

  // [v1310] Poids de production par recette (macarons équivalents) — base du PRORATA de répartition
  // du temps mutualisé. Calculé UNE fois ici, puis passé partout sur cet écran (total ET détail),
  // pour que le chiffre affiché et sa décomposition suivent EXACTEMENT la même règle.
  const _poidsProd = _poidsProductionParRecette(prods, sinceStr);

  // ── Temps ACTIF par recette (ms), via les sessions sur la fenêtre ──
  const actifParRec = {};
  sessions.filter(s=>(s.date||'').slice(0,10) >= sinceStr).forEach(s=>{
    const parRec = (typeof prodSessTempsParRecette==='function') ? prodSessTempsParRecette(s, _poidsProd) : {};
    Object.keys(parRec).forEach(rid=>{ actifParRec[rid] = (actifParRec[rid]||0) + parRec[rid]; });
  });
  const actifTotal = Object.values(actifParRec).reduce((a,b)=>a+b,0);

  // ── Batches terminés sur la fenêtre (pour durée réelle + groupements) ──
  // [v1312] Dénominateur = seulement les batches RÉELLEMENT CHRONOMÉTRÉS (recette + jour présents
  // dans une séance), pour porter sur le même périmètre que le temps actif.
  const _clesChrono = _clesChronometrees(sessions, sinceStr);
  let batches = prods.filter(p => _estBatchComptable(p, sinceStr, _clesChrono));
  const _tousBatches = prods.filter(p => _estBatchComptable(p, sinceStr));
  // GARDE-FOU : si le rapprochement ne trouve AUCUN batch alors que des séances existent, c'est que
  // le lien recette/date ne colle pas avec ces données. Plutôt que d'afficher « 0 batch » partout
  // (ce que faisait la v1311, à tort), on retombe sur le comptage complet et on le SIGNALE.
  let _rapprochementKO = false;
  if(batches.length===0 && _tousBatches.length>0 && _clesChrono.size>0){
    batches = _tousBatches;
    _rapprochementKO = true;
  }
  // Batches produits mais NON chronométrés : pour dire honnêtement sur quoi porte la moyenne.
  const _batchesNonChrono = _rapprochementKO ? 0 : Math.max(0, _tousBatches.length - batches.length);

  // Agrégations (le temps mur à mur n'est plus affiché ; on ne garde que ce qui sert à l'actif).
  const parParfum = {};   // nomNorm -> {nom, reel, actif, nb}
  const parJour = {};     // 'YYYY-MM-DD' -> {reel, actif, nb}
  const lignes = [];      // par batch
  batches.forEach(p=>{
    const dms = _batchDureeReelleMs(p);
    const nom = prodNomComplet(p, recipes);
    const k = (typeof aiNormalize==='function') ? aiNormalize(nom) : nom.toLowerCase();
    const jour = (p.prodTermineTs||p.prodTimestamp||p.date||'').slice(0,10);
    // [v1313] On accumule aussi la QUANTITÉ réellement produite (en macarons). Le simple comptage
    // d'enregistrements ne suffit pas : une production de 300 macarons et une de 20 comptaient
    // toutes deux pour « 1 batch », ce qui rendait la moyenne ininterprétable (27 min par batch de
    // quoi ? 20 macarons ? 300 ?). La quantité permet de dériver un temps PAR MACARON (comparable)
    // et un temps par BATCH STANDARD de 60 macarons (l'unité de travail réelle de Benjamin).
    const qte = (typeof prodQteAffichee==='function') ? (+prodQteAffichee(p)||0) : 0;
    (parParfum[k] ||= {nom, reel:0, actif:0, nb:0, nbMesure:0, qte:0});
    parParfum[k].reel += dms;
    parParfum[k].nb += 1;
    parParfum[k].qte += qte;
    if(dms>0) parParfum[k].nbMesure += 1;   // ne compter que les batches RÉELLEMENT mesurés
    (parJour[jour] ||= {reel:0, actif:0, nb:0});
    parJour[jour].reel += dms;
    parJour[jour].nb += 1;
    lignes.push({ ts:(p.prodTermineTs||p.prodTimestamp||p.date||''), nom, lot:p.lotProduction||('#'+p.id), reel:dms, recipeId:p.recipeId });
  });

  // Le temps actif est calculé par RECETTE (pas par batch). On le rattache au parfum par son nom.
  // Réinitialise proprement l'actif par parfum à partir de actifParRec.
  Object.keys(parParfum).forEach(k=>{ parParfum[k].actif = 0; });
  Object.keys(actifParRec).forEach(rid=>{
    const r = recipes.find(x=>+x.id===+rid); if(!r) return;
    const nom = r.produitNom||''; if(!nom) return;
    const k = (typeof aiNormalize==='function') ? aiNormalize(nom) : nom.toLowerCase();
    if(parParfum[k]) parParfum[k].actif += actifParRec[rid];
    else parParfum[k] = {nom, reel:0, actif:actifParRec[rid], nb:0, nbMesure:0, qte:0};
    // [v1307] Mémorise les recipeId qui alimentent ce parfum (classique + grand format), pour la
    // décomposition traçable phase→tâche affichée sous la carte.
    (parParfum[k].recIds ||= new Set()).add(+rid);
  });

  // Actif par jour : réparti via les sessions datées
  sessions.filter(s=>(s.date||'').slice(0,10) >= sinceStr).forEach(s=>{
    const jour = (s.date||'').slice(0,10); if(!jour) return;
    const parRec = (typeof prodSessTempsParRecette==='function') ? prodSessTempsParRecette(s, _poidsProd) : {};
    const ms = Object.values(parRec).reduce((a,b)=>a+b,0);
    (parJour[jour] ||= {reel:0, actif:0, nb:0});
    parJour[jour].actif += ms;
  });

  // ── Rendu ──
  const periodes = [['7','7 jours'],['30','30 jours'],['90','90 jours'],['tout','Tout']]
    .map(([v,l])=>`<button class="btn ${_tempsProdPeriode===v?'':'ghost'} sm" onclick="setTempsProdPeriode('${v}')">${l}</button>`).join('');

  // [v1306] nbMesure / ratio retirés : ils ne servaient qu'à l'affichage du temps mur à mur,
  // désormais supprimé de cet écran (centré sur le seul temps actif).

  // [FIX v1315 — MOYENNES ABSURDES (21 h/batch)] Le temps actif d'un parfum inclut la fabrication de
  // ses COQUES (souvent produites d'avance, en grande quantité). Or le dénominateur ne comptait que les
  // macarons ASSEMBLÉS dans la fenêtre. Résultat : 300 coques de myrtille fabriquées mais 5 macarons
  // assemblés → un temps énorme divisé par 5 → « 21 h 16 par batch », absurde.
  // On aligne les périmètres : le dénominateur compte TOUT ce qui a réellement été produit pour ce
  // parfum, en MACARONS ÉQUIVALENTS (une fournée de coques ÷ 2), soit exactement la base déjà utilisée
  // pour le prorata. Numérateur et dénominateur parlent enfin de la même chose.
  const qteEquivParParfum = {};
  prods.forEach(p=>{
    if(!p || p.recipeId==null) return;
    const comp = p.composant || 'complet';
    if(comp!=='complet' && comp!=='assemble' && comp!=='coques') return;   // ganache/chantache : pas des macarons
    // Même filtre chronométré que les batches (recette + jour présents dans une séance).
    if(!_rapprochementKO){
      const rid = +p.recipeId;
      const jours = new Set();
      [p.prodDebutTs, p.prodTimestamp, p.prodTermineTs, p.date].forEach(x=>{ const j=String(x||'').slice(0,10); if(j) jours.add(j); });
      let vu = false;
      for(const j of jours){ if(_clesChrono.has(rid+'|'+j)){ vu=true; break; } }
      if(!vu) return;
    }
    const d = (p.prodTermineTs||p.prodTimestamp||p.date||'').slice(0,10);
    if(d < sinceStr) return;
    const q = (typeof prodQteAffichee==='function') ? (+prodQteAffichee(p)||0) : 0;
    if(!(q>0)) return;
    const macEq = (comp==='coques') ? (q / COQUES_PAR_MACARON) : q;
    const r = recipes.find(x=>+x.id===+p.recipeId); if(!r) return;
    const nom = r.produitNom||''; if(!nom) return;
    const k = (typeof aiNormalize==='function') ? aiNormalize(nom) : nom.toLowerCase();
    qteEquivParParfum[k] = (qteEquivParParfum[k]||0) + macEq;
  });
  Object.keys(parParfum).forEach(k=>{ parParfum[k].qte = qteEquivParParfum[k] || 0; });

  const cartesParfum = Object.values(parParfum)
    .sort((a,b)=>b.actif-a.actif)
    .map(e=>{
      const actifNul = e.actif<=0;

      // [v1307] DÉCOMPOSITION TRAÇABLE (repliable) : d'où viennent ces minutes ? Phase → tâche, avec
      // pour chaque ligne son temps, son nombre de mesures, et un marqueur si c'est du temps PASSIF
      // (cuisson, refroidissement, congélation… = attente chronométrée, pas de la manipulation).
      let decompoHTML = '';
      const decompo = _tempsDecompoParParfum(e.recIds || new Set(), jours, _poidsProd);
      if(decompo.total>0){
        // [v1316] Vue consolidée par ÉTAPE PRINCIPALE (Coques → Ganache → Assemblage → Support),
        // dans l'ordre de fabrication. Chaque étape montre son temps, sa part du total, et les tâches
        // qui la composent. C'est la structure réelle d'une production, au lieu de 10 phases éparses.
        const etapesHTML = (decompo.etapes||[]).map(et=>{
          const pct = Math.round((et.part||0)*100);
          const tachesHTML = et.taches.map(tk=>`
            <div style="display:flex;justify-content:space-between;gap:8px;padding:3px 0 3px 14px;font-size:.79rem;color:#6a5a52">
              <span>${tk.passive?'<span title="Étape d\'attente (le four/batteur travaille)" style="opacity:.6">💤</span> ':''}${esc(tk.label)} <span style="color:#b0a196">· ${tk.nb} mesure${tk.nb>1?'s':''}</span></span>
              <span style="white-space:nowrap;font-weight:600${tk.passive?';color:#b0a196':''}">${fmtDureeMs(tk.ms)}</span>
            </div>`).join('');
          return `<div style="margin-top:10px">
            <div style="display:flex;justify-content:space-between;gap:8px;align-items:baseline;font-weight:700;font-size:.88rem;color:var(--bordeaux)">
              <span>${esc(et.etape)} <span style="font-weight:400;color:#b0a196;font-size:.74rem">${pct}% du temps${et.passif>0?` · dont ${fmtDureeMs(et.passif)} d'attente`:''}</span></span>
              <span style="white-space:nowrap">${fmtDureeMs(et.ms)}</span>
            </div>
            <div style="height:4px;background:#eee3d4;border-radius:3px;margin:4px 0 2px">
              <div style="height:100%;width:${pct}%;background:var(--caramel);border-radius:3px"></div>
            </div>
            ${tachesHTML}
          </div>`;
        }).join('');
        decompoHTML = `<details class="tp-decompo" style="margin-top:10px">
          <summary style="cursor:pointer;font-size:.8rem;color:var(--caramel);font-weight:600">🔎 Détail du temps (étape → tâche)</summary>
          <div style="margin-top:6px;padding-top:8px;border-top:1px dashed var(--hair)">
            ${etapesHTML}
            <div style="display:flex;justify-content:space-between;gap:8px;margin-top:12px;padding-top:8px;border-top:1px solid var(--hair);font-size:.84rem">
              <span style="font-weight:700">Total chronométré</span>
              <span style="font-weight:700">${fmtDureeMs(decompo.total)}</span>
            </div>
            ${decompo.passif>0?`<div style="display:flex;justify-content:space-between;gap:8px;font-size:.78rem;color:#b0a196;margin-top:4px">
              <span>💤 dont étapes d'attente (four, batteur…)</span><span style="font-weight:600">${fmtDureeMs(decompo.passif)}</span></div>`:''}
            <div class="note" style="font-size:.7rem;margin-top:6px;color:#b0a196">
              Quand des tâches se chevauchent, leurs durées ne s'additionnent PAS (c'est justement là que tu gagnes du temps) : le temps réel est partagé entre elles, au prorata de leur durée propre.
              ${decompo.reparti==='prorata'
                ? ' Les étapes partagées entre parfums sont réparties <b>au prorata des quantités</b> ; la vaisselle et la mise en place, à parts égales.'
                : ' Étapes partagées réparties <b>à parts égales</b> (quantités indisponibles sur cette période).'}
            </div>
          </div>
        </details>`;
      }

      // [v1313] DEUX moyennes, l'une comparable, l'autre parlante :
      //  • par MACARON  = temps actif ÷ nombre de macarons réellement produits. Unité stable, permet
      //    de chiffrer n'importe quelle commande (200 macarons → 200 × ce temps).
      //  • par BATCH de 60 = la même valeur ramenée à l'unité de travail réelle (1 batch = 60 macarons,
      //    120 coques — constante TAILLE_BATCH_MACARONS déjà utilisée par l'app).
      // L'ancienne « moy./batch » divisait par le NOMBRE D'ENREGISTREMENTS de production : une
      // production de 300 macarons pesait autant qu'une de 20, ce qui rendait le chiffre inutilisable.
      const qteTot = +e.qte || 0;
      const parMacaronMs = qteTot>0 ? e.actif/qteTot : 0;
      // [v1315] La taille d'un batch dépend du FORMAT : 60 macarons en classique, 24 en grand format
      // (48 coques). On lit recipe.grandFormat sur les recettes qui alimentent ce parfum.
      const _recsDuParfum = Array.from(e.recIds || []).map(id=>recipes.find(r=>+r.id===+id)).filter(Boolean);
      const _estGF = _recsDuParfum.length>0 && _recsDuParfum.every(r=>!!r.grandFormat);
      const _tailleBatch = _estGF ? TAILLE_BATCH_MACARONS_GF : TAILLE_BATCH_MACARONS;
      const parBatchMs = parMacaronMs * _tailleBatch;
      const sansQte = !(qteTot>0) || actifNul;

      return `<div class="tp-card">
        <div class="tp-head">
          <div class="tp-flavour">${esc(e.nom)}</div>
          <div class="tp-qty"><b>${qteTot?Math.round(qteTot):e.nb}</b><span>${qteTot?('macaron'+(qteTot>1?'s':'')+' équiv. produit'+(qteTot>1?'s':'')):('batch'+(e.nb>1?'es':''))}</span></div>
        </div>
        <div class="tp-grid" style="grid-template-columns:1fr 1fr 1fr">
          <div class="tp-metric actif">
            <div class="tp-lbl">Temps actif</div>
            <div class="tp-val${actifNul?' na':''}">${actifNul?'—':fmtDureeMs(e.actif)}</div>
          </div>
          <div class="tp-metric">
            <div class="tp-lbl">Par macaron</div>
            <div class="tp-val">${sansQte?'—':_fmtMinSec(parMacaronMs)}</div>
          </div>
          <div class="tp-metric">
            <div class="tp-lbl">Par batch (${_tailleBatch})</div>
            <div class="tp-val">${sansQte?'—':fmtDureeMs(parBatchMs)}</div>
          </div>
        </div>
        ${decompoHTML}
      </div>`;
    }).join('') || `<p class="note" style="padding:10px">Aucune production sur la période.</p>`;

  const lignesJour = Object.keys(parJour).sort().reverse()
    .map(j=>{
      const e = parJour[j];
      const lbl = (typeof fmtDate==='function') ? fmtDate(j) : j;
      return `<tr><td>${esc(lbl)}</td>
        <td style="text-align:right">${e.nb}</td>
        <td style="text-align:right;color:var(--gold);font-weight:600">${fmtDureeMs(e.actif)}</td></tr>`;
    }).join('') || `<tr><td colspan="3" class="note" style="padding:10px">Aucune session sur la période.</td></tr>`;

  // [v1306] (Ancien tableau « Détail par batch » retiré — il n'affichait que le temps mur à mur,
  // sans valeur pour le pilotage. La variable lignesBatch n'a donc plus lieu d'être.)

  // [v1304] Dans le conteneur à onglets « Temps de production » (#tempsBody présent) : le titre
  // « ⏱️ Temps de production » et le bouton « 🔍 Contrôle des temps » sont redondants avec le
  // bandeau du conteneur et l'onglet « Vérifier les séances ». On ne garde ici que les actions
  // propres à l'analyse (Chronos ouverts, Historique). En appel autonome, le bandeau complet reste.
  const _dansOnglets = !!document.getElementById('tempsBody');
  const _barreActions = `<div class="flex"><button class="btn ghost sm" onclick="corrigerChronosOuvertsPreview()" title="Détecter et fermer les chronos jamais arrêtés">🔧 Chronos ouverts</button><button class="btn" onclick="goView('histostock')">📦 Historique →</button></div>`;
  main.innerHTML = `
   ${_dansOnglets
      ? `<div style="display:flex;justify-content:flex-end;margin-bottom:10px">${_barreActions}</div>`
      : `<div class="topbar"><div><h1>⏱️ Temps de production</h1>
     <p>Temps réellement passé par production, parfum et période.</p></div>
     <div class="flex"><button class="btn ghost sm" onclick="goView('controletemps')" title="Vérifier et corriger le temps de chaque séance">🔍 Contrôle des temps</button><button class="btn ghost sm" onclick="corrigerChronosOuvertsPreview()" title="Détecter et fermer les chronos jamais arrêtés">🔧 Chronos ouverts</button><button class="btn" onclick="goView('histostock')">📦 Historique →</button></div></div>`}

   <div class="panel">
     <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">${periodes}</div>
     <div style="background:linear-gradient(135deg,#AA7C39,#8a6322);color:#fff;border-radius:14px;padding:18px">
       <div style="font-size:.72rem;opacity:.85;text-transform:uppercase;letter-spacing:.04em">🔧 Temps actif atelier</div>
       <div style="font-size:2rem;font-weight:700;margin-top:4px">${fmtDureeMs(actifTotal)}</div>
       <div style="font-size:.74rem;opacity:.85;margin-top:2px">Temps réellement passé aux fourneaux (hors repos et maturation)</div>
     </div>
   </div>

   <div class="panel">
     <h2>Par parfum / recette</h2>
     <p class="note" style="margin:2px 0 12px">Temps de travail effectif (chrono), repos et attente exclus.</p>
     ${_rapprochementKO?`<div class="note" style="margin:0 0 12px;padding:8px 10px;background:#fdecea;border-left:3px solid #c0392b;border-radius:6px;font-size:.78rem">
       ⚠️ Impossible de relier tes séances chronométrées à tes batches produits (recette + date ne correspondent pas). Les moyennes portent donc sur <b>tous</b> les batches, y compris ceux sans chrono : elles sont probablement <b>sous-estimées</b>. Le « Temps actif » reste juste.
     </div>`:''}
     ${_batchesNonChrono>0?`<div class="note" style="margin:0 0 12px;padding:8px 10px;background:#fdf6e8;border-left:3px solid var(--caramel);border-radius:6px;font-size:.78rem">
       ⚠️ <b>${_batchesNonChrono} batch${_batchesNonChrono>1?'es':''}</b> produit${_batchesNonChrono>1?'s':''} sans chrono sur cette période ${_batchesNonChrono>1?'sont exclus':'est exclu'} des moyennes : le temps mesuré ne porte que sur les batches réellement chronométrés. Les compter au dénominateur écraserait la moyenne.
     </div>`:''}
     <div class="tp-cards">${cartesParfum}</div>
   </div>

   <div class="panel">
     <h2>Par jour</h2>
     <table style="width:100%;border-collapse:collapse;font-size:.88rem">
       <tr><th style="text-align:left;padding:6px 8px;border-bottom:2px solid var(--hair);color:#9a8a82;font-size:.74rem">Jour</th>
       <th style="text-align:right;padding:6px 8px;border-bottom:2px solid var(--hair);color:#9a8a82;font-size:.74rem">Batches</th>
       <th style="text-align:right;padding:6px 8px;border-bottom:2px solid var(--hair);color:#9a8a82;font-size:.74rem">Temps actif</th></tr>
       ${lignesJour}
     </table>
   </div>

  `;
}

// ============================================================
// RECONSTRUCTION DE L'HISTORIQUE DE STOCK (rattrapage rétroactif)
// ------------------------------------------------------------
// Recrée les mouvements PASSÉS qui n'ont pas été journalisés (avant que
// le journal fonctionne). Sources SÛRES uniquement :
//   • ENTRÉES : productions terminées (prodTermineTs / statut termine) → +qteReelle
//   • SORTIES : orderItems de commandes Livrées/Terminées → -qte
// Chaque mouvement reconstruit porte reconstruit:true → RÉVERSIBLE et IDEMPOTENT
// (on ne recrée pas un mouvement déjà reconstruit pour la même source).
// ============================================================

// Calcule (sans rien écrire) la liste des mouvements à reconstruire.
async function _reconstructStockPlan(){
  const recipes = await db.recipes.toArray().catch(()=>[]);
  window._allRecipesCache = recipes;
  const prods  = await db.productions.toArray().catch(()=>[]);
  const orders = await db.orders.toArray().catch(()=>[]);
  const items  = await db.orderItems.toArray().catch(()=>[]);
  const losses = await db.losses.toArray().catch(()=>[]);
  const existing = await db.stockMoves.toArray().catch(()=>[]);

  // Clés des reconstructions déjà faites (idempotence)
  const dejaEntree = new Set(existing.filter(m=>m.reconstruit && m.sens>0 && m.productionId!=null).map(m=>'P'+m.productionId));
  const dejaSortie = new Set(existing.filter(m=>m.reconstruit && m.sens<0 && m.orderId!=null && m.productionId!=null).map(m=>'O'+m.orderId+'_'+m.productionId));
  const dejaPerte  = new Set(existing.filter(m=>m.reconstruit && m.type==='perte' && m.lossId!=null).map(m=>'L'+m.lossId));
  const dejaAsmSortie = new Set(existing.filter(m=>m.reconstruit && m.type==='assemblage' && m.sens<0 && m.asmId!=null && m.composant).map(m=>'A'+m.asmId+'_'+m.composant+'_'+m.productionId));

  const entrees = [];
  for(const p of prods){
    const fini = (p.prodStatut==='termine') || (p.prodTermineTs && String(p.prodTermineTs).length>0) || (p.prodStatut==null);
    if(!fini) continue;
    const q = round3(+p.qteReelle || +p.qteProduite || 0);
    if(q<=0) continue;
    const ts = p.prodTermineTs || p.prodTimestamp || (p.date ? p.date+'T08:00' : '');
    if(!ts) continue;
    if(dejaEntree.has('P'+p.id)) continue;
    // Une production au composant 'degustation' est une ENTRÉE de stock dégustation (type dédié).
    const estDeg = (p.composant==='degustation') || p.degustation===true;
    // Un assemblage se reconnaît au champ assembleFrom (liste des composants consommés),
    // pas seulement au composant 'assemble' : d'anciennes prods migrées peuvent être
    // 'complet' tout en ayant été assemblées. assembleFrom rempli = assemblage.
    const aAssembleFrom = Array.isArray(p.assembleFrom) && p.assembleFrom.length>0;
    const estAsm = (p.composant==='assemble') || (aAssembleFrom && !estDeg);
    const comp = (estDeg || estAsm) ? 'macaron'
               : (p.composant==='coques') ? 'coques'
               : (p.composant==='ganache') ? 'ganache' : 'macaron';
    const typeEntree = estDeg ? 'degustation' : (estAsm ? 'assemblage' : 'production');
    entrees.push({ ts, qte:q, nom:prodNomComplet(p, recipes), composant:comp,
      type: typeEntree, productionId:p.id });
  }

  // ASSEMBLAGES : pour chaque production assemblée, recréer les SORTIES des composants
  // sources (coques + ganache consommées), lues dans le champ assembleFrom.
  const asmSorties = [];
  for(const p of prods){
    // Tout ce qui a un assembleFrom rempli est un assemblage (composant 'assemble',
    // 'degustation' issue d'assemblage, ou 'complet' migré).
    if(!Array.isArray(p.assembleFrom) || !p.assembleFrom.length) continue;
    const ts = p.prodTermineTs || p.prodTimestamp || (p.date ? p.date+'T08:00' : '');
    if(!ts) continue;
    for(const src of p.assembleFrom){
      const q = round3(+src.qte||0); if(q<=0) continue;
      const compSrc = (src.composant==='coques') ? 'coques'
                    : (src.composant==='ganache') ? 'ganache'
                    : (src.composant==='garniture-sup') ? 'ganache' : 'macaron';
      if(dejaAsmSortie.has('A'+p.id+'_'+compSrc+'_'+(src.id!=null?src.id:''))) continue;
      const nom = src.parfum || (src.id!=null ? (prodNomComplet(prods.find(x=>+x.id===+src.id)||{}, recipes)) : prodNomComplet(p, recipes));
      asmSorties.push({ ts, qte:q, nom, composant:compSrc, type:'assemblage',
        asmId:p.id, productionId:(src.id!=null?src.id:null) });
    }
  }

  const ordById = {}; orders.forEach(o=>{ ordById[o.id]=o; });
  const sorties = [];
  for(const it of items){
    const o = ordById[it.orderId]; if(!o) continue;
    const st = normStatus(o.statut);
    if(st!=='Livrée' && st!=='Terminée') continue;
    const q = round3(+it.qte||0); if(q<=0) continue;
    if(it.productionId==null) continue;
    if(dejaSortie.has('O'+it.orderId+'_'+it.productionId)) continue;
    // retrouver le parfum via la production liée
    const prod = prods.find(pp=>+pp.id===+it.productionId);
    const nom = prod ? prodNomComplet(prod, recipes) : '(production supprimée)';
    const ts = o.dateLivraison || o.date || (prod && (prod.prodTermineTs||prod.date)) || today();
    const tsIso = String(ts).length>10 ? ts : (ts+'T12:00');
    sorties.push({ ts:tsIso, qte:q, nom, composant:'macaron', orderId:it.orderId, productionId:it.productionId });
  }

  // PERTES : table dédiée db.losses → chaque perte = une sortie de stock (type 'perte').
  const pertes = [];
  for(const l of losses){
    const q = round3(+l.qte||0); if(q<=0) continue;
    if(l.id!=null && dejaPerte.has('L'+l.id)) continue;
    const prod = (l.productionId!=null) ? prods.find(pp=>+pp.id===+l.productionId) : null;
    let nom = '(perte)';
    if(prod) nom = prodNomComplet(prod, recipes);
    else if(l.recipeId!=null){ const r=recipes.find(x=>+x.id===+l.recipeId); if(r) nom=r.produitNom; }
    const comp = (prod && prodComposant(prod)==='coques') ? 'coques'
               : (prod && prodComposant(prod)==='ganache') ? 'ganache' : 'macaron';
    const ts = (l.date && String(l.date).length>=10) ? (String(l.date).length>10 ? l.date : l.date+'T12:00') : today()+'T12:00';
    pertes.push({ ts, qte:q, nom, composant:comp, type:'perte', lossId:l.id, productionId:l.productionId, note:l.motif||'' });
  }

  return { entrees, sorties, pertes, asmSorties, existing:existing.length };
}

// Affiche l'aperçu (modale) avant toute écriture.
async function reconstructStockHistoryPreview(){
  try{
    toast('Calcul en cours…');
    // Inspection rapide : répartition des productions par composant (pour comprendre le classement).
    let _diagComp = '';
    try{
      const _pr = await db.productions.toArray().catch(()=>[]);
      const _byComp = {};
      _pr.forEach(p=>{ const c=p.composant||'complet'; _byComp[c]=(_byComp[c]||0)+1; });
      _diagComp = Object.keys(_byComp).sort().map(c=>`${c}: ${_byComp[c]}`).join(' · ');
    }catch(e){swallow(e,'reconstructStockHistoryPreview')}
    const plan = await _reconstructStockPlan();
    const pertes = plan.pertes||[];
    const asmS = plan.asmSorties||[];
    const nE = plan.entrees.length, nS = plan.sorties.length, nP = pertes.length, nA = asmS.length;
    // séparer entrées production vs dégustation pour l'affichage
    const nDeg = plan.entrees.filter(e=>e.type==='degustation').length;
    const nProd = nE - nDeg;
    const qS = round3(plan.sorties.reduce((s,m)=>s+m.qte,0));
    const qP = round3(pertes.reduce((s,m)=>s+m.qte,0));
    const qA = round3(asmS.reduce((s,m)=>s+m.qte,0));
    if(nE+nS+nP+nA===0){
      openModal(`<h2>Reconstruction de l'historique</h2>
        <p class="note">Rien à reconstruire : soit c'est déjà fait, soit aucune trace exploitable n'a été trouvée.</p>
        <div class="flex" style="justify-content:flex-end"><button class="btn" onclick="closeModal()">Fermer</button></div>`);
      return;
    }
    const echant = plan.entrees.slice().sort((a,b)=>a.ts<b.ts?1:-1).slice(0,5)
      .map(e=>`<div style="font-size:.78rem;color:#6a5a52">${esc(e.ts.slice(0,16))} · +${qty(e.qte)} · ${esc(e.nom)} <span style="color:#9a8a82">(${esc(e.composant)}${e.type==='degustation'?', dégustation':''})</span></div>`).join('');
    openModal(`<h2>Reconstruction de l'historique de stock</h2>
      <p class="note">Recrée les mouvements passés à partir des traces sûres : productions, dégustations, assemblages, livraisons et pertes. Tout est <b>marqué comme reconstruit</b> (retirable d'un clic). Les ajustements manuels et recrédits passés ne peuvent pas être reconstruits (aucune trace).</p>
      <div class="panel" style="background:#faf6f0;border:1px solid var(--hair)">
        <div style="display:flex;justify-content:space-between;padding:6px 0"><span>📦 Entrées (productions)</span><b>${nProd} mvts</b></div>
        <div style="display:flex;justify-content:space-between;padding:6px 0;border-top:1px solid var(--hair)"><span>🔗 Assemblages (sorties coques/ganache)</span><b>${nA} mvts · −${qty(qA)}</b></div>
        <div style="display:flex;justify-content:space-between;padding:6px 0;border-top:1px solid var(--hair)"><span>🥄 Dégustations</span><b>${nDeg} mvts</b></div>
        <div style="display:flex;justify-content:space-between;padding:6px 0;border-top:1px solid var(--hair)"><span>📤 Sorties (livraisons)</span><b>${nS} mvts · −${qty(qS)}</b></div>
        <div style="display:flex;justify-content:space-between;padding:6px 0;border-top:1px solid var(--hair)"><span>⚠️ Pertes</span><b>${nP} mvts · −${qty(qP)}</b></div>
        <div style="display:flex;justify-content:space-between;padding:6px 0;border-top:1px solid var(--hair)"><span><b>Total à créer</b></span><b>${nE+nS+nP+nA} mouvements</b></div>
      </div>
      ${echant?`<p class="note" style="margin-bottom:4px">Aperçu (5 dernières entrées) :</p>${echant}`:''}
      <p class="note" style="margin-top:10px;color:#b04a3e">⚠️ Pense à sauvegarder ta base (iCloud) avant, par précaution.</p>
      <div class="flex" style="justify-content:flex-end;gap:8px;margin-top:12px">
        <button class="btn ghost" onclick="closeModal()">Annuler</button>
        <button class="btn gold" onclick="reconstructStockHistoryRun()">Reconstruire ${nE+nS+nP+nA} mouvements</button>
      </div>`);
  }catch(e){
    toast('Erreur aperçu : '+(e&&e.message||e));
  }
}

// Exécute la reconstruction (écrit réellement, après confirmation).
async function reconstructStockHistoryRun(){
  try{
    closeModal();
    toast('Reconstruction en cours…');
    // MIGRATION : re-typer les entrées d'assemblage déjà reconstruites qui ont été
    // classées 'production' par erreur (elles doivent être 'assemblage' pour apparaître
    // avec les sorties coques/ganache du même assemblage).
    try{
      const prodsRef = await db.productions.toArray().catch(()=>[]);
      // Un assemblage = production avec assembleFrom rempli (capte aussi les 'complet' migrés).
      const asmIds = new Set(prodsRef.filter(p=>Array.isArray(p.assembleFrom)&&p.assembleFrom.length>0 && p.composant!=='degustation').map(p=>+p.id));
      const existants = await db.stockMoves.toArray().catch(()=>[]);
      for(const m of existants){
        if(m.reconstruit && m.sens>0 && m.type==='production' && m.productionId!=null && asmIds.has(+m.productionId)){
          try{ await db.stockMoves.update(m.id, {type:'assemblage'}); }catch(e){swallow(e,'reconstructStockHistoryRun')}
        }
      }
    }catch(e){swallow(e,'reconstructStockHistoryRun')}
    const plan = await _reconstructStockPlan();
    let ok = 0;
    for(const e of plan.entrees){
      try{
        await db.stockMoves.add({
          ts:e.ts, parfumNorm:stockMoveKey(e.nom), parfumNom:e.nom,
          composant:e.composant, sens:1, qte:e.qte, type:(e.type||'production'),
          productionId:e.productionId, reconstruit:true, note:'reconstruit (rattrapage)'
        });
        ok++;
      }catch(e){swallow(e,'reconstructStockHistoryRun')}
    }
    for(const s of plan.sorties){
      try{
        await db.stockMoves.add({
          ts:s.ts, parfumNorm:stockMoveKey(s.nom), parfumNom:s.nom,
          composant:s.composant, sens:-1, qte:s.qte, type:'livraison',
          orderId:s.orderId, productionId:s.productionId, reconstruit:true, note:'reconstruit (rattrapage)'
        });
        ok++;
      }catch(e){swallow(e,'reconstructStockHistoryRun')}
    }
    for(const pr of (plan.pertes||[])){
      try{
        await db.stockMoves.add({
          ts:pr.ts, parfumNorm:stockMoveKey(pr.nom), parfumNom:pr.nom,
          composant:pr.composant, sens:-1, qte:pr.qte, type:'perte',
          productionId:pr.productionId, lossId:pr.lossId, reconstruit:true,
          note:'reconstruit (rattrapage)'+(pr.note?(' · '+pr.note):'')
        });
        ok++;
      }catch(e){swallow(e,'reconstructStockHistoryRun')}
    }
    for(const a of (plan.asmSorties||[])){
      try{
        await db.stockMoves.add({
          ts:a.ts, parfumNorm:stockMoveKey(a.nom), parfumNom:a.nom,
          composant:a.composant, sens:-1, qte:a.qte, type:'assemblage',
          asmId:a.asmId, productionId:a.productionId, reconstruit:true,
          note:'reconstruit (rattrapage)'
        });
        ok++;
      }catch(e){swallow(e,'reconstructStockHistoryRun')}
    }
    if(typeof markUnsaved==='function') markUnsaved();
    toast(`✓ ${ok} mouvement(s) reconstruit(s)`);
    if(view==='histostock' && typeof renderHistoStock==='function') renderHistoStock();
  }catch(e){
    toast('Erreur reconstruction : '+(e&&e.message||e));
  }
}

// Annule (retire) tous les mouvements reconstruits — réversibilité totale.
async function reconstructStockHistoryUndoRun(){
  try{
    closeModal();
    const all = await db.stockMoves.toArray().catch(()=>[]);
    const recon = all.filter(m=>m.reconstruit);
    let n=0;
    for(const m of recon){ try{ await db.stockMoves.delete(m.id); n++; }catch(e){swallow(e,'reconstructStockHistoryUndoRun')} }
    if(typeof markUnsaved==='function') markUnsaved();
    toast(`✓ ${n} mouvement(s) reconstruit(s) retiré(s)`);
    if(view==='histostock' && typeof renderHistoStock==='function') renderHistoStock();
  }catch(e){ toast('Erreur : '+(e&&e.message||e)); }
}

// [JOURNAL DE STOCK] Enregistre UN mouvement de stock fini dans la table stockMoves.
// Socle de la « consommation effective » du moteur de stock : chaque entrée/sortie est tracée
// (date, parfum, composant, sens, quantité, type, références). Démarrage à zéro en v20.
//
// IMPORTANT — non bloquant par construction : toute erreur (table absente sur un vieil appareil,
// base bloquée…) est avalée silencieusement. Journaliser ne doit JAMAIS faire échouer le
// mouvement de stock réel (qteRestante) qui, lui, reste la source de vérité de l'état courant.
// On n'enveloppe donc PAS l'appelant : on se contente d'ajouter la trace en parallèle.
//
// Paramètres (objet) :
//   parfumNom (req) · composant 'macaron'|'coques'|'ganache' (déf 'macaron')
//   sens +1|-1 (req) · qte > 0 (req, valeur absolue) · type (req)
//   productionId? · orderId? · marketId? · note? · ts? (déf maintenant)
// Renvoie l'id du mouvement (ou null si non journalisé). await optionnel.
async function logStockMove(m){
  try{
    if(!m) return null;
    const qte = round3(Math.abs(+m.qte||0));
    if(qte<=0) return null;                       // pas de mouvement nul
    const sens = (+m.sens<0) ? -1 : 1;            // normalise à ±1
    const nom  = (m.parfumNom!=null) ? String(m.parfumNom) : '';
    const rec = {
      ts:        m.ts || new Date().toISOString(),
      parfumNorm: stockMoveKey(nom),
      parfumNom:  nom,
      composant: m.composant || 'macaron',
      sens, qte,
      type:      m.type || 'ajustement'
    };
    if(m.productionId!=null) rec.productionId = m.productionId;
    if(m.orderId!=null)      rec.orderId      = m.orderId;
    if(m.marketId!=null)     rec.marketId     = m.marketId;
    if(m.note)               rec.note         = String(m.note);
    return await db.stockMoves.add(rec);
  }catch(e){
    // Silencieux : la trace est secondaire, l'état réel (qteRestante) prime.
    try{ console.warn('logStockMove ignoré:', e && e.message); }catch(e){swallow(e,'logStockMove')}
    return null;
  }
}

// [OPTIMISATION BATCH] Interrupteur ON/OFF persistant. Par défaut OFF : on produit exactement
// les quantités commandées (priorité absolue aux commandes). Quand ON : on arrondit au palier
// rationnel (30/60/120) et le surplus va au stock — à activer quand le temps de prod le permet.
const OPTIM_BATCH_KEY = 'sm_optimBatch';
function getOptimBatch(){
  try{ return localStorage.getItem(OPTIM_BATCH_KEY)==='1'; }catch(e){ return false; }
}
function setOptimBatch(on){
  try{ localStorage.setItem(OPTIM_BATCH_KEY, on?'1':'0'); }catch(e){swallow(e,'setOptimBatch')}
}

// [OPTIMISATION BATCH] Arrondit une quantité commandée au palier de production rationnel.
// Règle métier (Benjamin) : les commandes priment sur le réassort, MAIS pas d'absurdité —
// on ne lance pas une meringue pour 14 macarons. Paliers : 30 (mini), 60 (demi-meringue),
// 120 (meringue pleine) ; au-delà de 120 → meringues pleines + reste arrondi au palier.
// Le SURPLUS (produire − commandé) est destiné au STOCK (point d'ancrage du futur moteur de stock).
// Renvoie { produire, surplus, paliers:[...] }.
function arrondirPalierProduction(qte){
  qte = Math.max(0, Math.round(+qte||0));
  if(qte === 0) return { produire:0, surplus:0, paliers:[] };
  const PLEINE = 120;
  const pleines = Math.floor(qte / PLEINE);
  let reste = qte - pleines*PLEINE;
  const paliers = [];
  for(let i=0;i<pleines;i++) paliers.push(PLEINE);
  if(reste > 0){
    paliers.push(reste<=30 ? 30 : (reste<=60 ? 60 : 120));
  }
  const produire = paliers.reduce((a,b)=>a+b,0);
  return { produire, surplus: produire - qte, paliers };
}

// [FAISABILITÉ PAR SEMAINE] Verdict « tient / déborde » d'une semaine du plan, en réutilisant
// le moteur de faisabilité existant (generateProductionOrder) borné aux dates de la semaine, et
// le temps de travail réel disponible (plages A/B). Source de vérité UNIQUE : aucun calcul de
// charge réécrit, on appelle le même moteur que l'écran Plan de production.
//   wk = clé ISO 'YYYY-Www'. Renvoie null si bornes illisibles, sinon
//   { lundi, dim, debut, tempsTotal, tempsDispo, depassement, debordementMin, chargePct }.
// [CONVERGENCE MOTEUR 1 → MOTEUR 2 — étape 1, lecture seule] Somme les MINUTES DE TRAVAIL RÉELLES que
// le moteur 2 (rétroplanning : buildMutualisationSemaine → _buildPlanOpAutonome) a calées dans la fenêtre
// [debutStr, finStr]. Ces créneaux (window._planParfumCreneaux) sont EXACTEMENT ceux qu'affiche l'ordre du
// jour : même besoin (stock MOBILISABLE déduit), même congélation, même placement horaire. But : permettre
// à la faisabilité (étape 2) de juger la VRAIE production au lieu d'un second calcul divergent (moteur 1).
//
// Un créneau a {type, parfum, debut, fin, qte}. debut/fin sont des dates ISO parsables. On compte un créneau
// si sa DATE LOCALE de début ∈ [debutStr, finStr] (peu importe sa semaine ISO : le rétroplanning peut caler
// un montage hors de la semaine de livraison). Durée = (fin − debut) en minutes ; à défaut de fin, 0.
//
// AUTO-PEUPLEMENT : si le registre est vide (faisabilité appelée avant tout affichage du Plan/ordre du jour),
// on le construit nous-mêmes via le même chemin que _ordreProductionDuJour (aucun écran, aucun DOM touché).
// Lecture seule : ne modifie ni la base, ni le plan. Publie un diag de transparence.
async function _chargeCreneauxFenetre(debutStr, finStr){
  if(!debutStr || !finStr) return null;
  const ymdOf = d => { const x=new Date(d); return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0'); };
  const dureeMin = c => { try{ const a=new Date(c.debut).getTime(), b=new Date(c.fin).getTime();
    return (isFinite(a)&&isFinite(b)&&b>a) ? Math.round((b-a)/60000) : 0; }catch(_){ return 0; } };
  // 1) S'assurer que le registre des créneaux est peuplé (même pattern que _ordreProductionDuJour).
  let reg = (typeof window!=='undefined' && window._planParfumCreneaux) ? window._planParfumCreneaux : null;
  if(!reg || !Object.keys(reg).length){
    // [GARDE ANTI-RÉCURSION] _buildPlanOpAutonome appelle _faisabiliteSemaine AVANT de peupler le registre.
    // Sans ce flag, _faisabiliteFenetre → _chargeCreneauxFenetre → _buildPlanOpAutonome → _faisabiliteSemaine
    // → … boucle. Pendant un peuplement déjà en cours, on NE relance PAS : on renvoie « registre vide » et la
    // faisabilité retombe sur son repli (moteur 1). Le verdict final, lui, sera recalculé avec le registre plein.
    if(typeof window!=='undefined' && window.__chargeCreneauxPeuplementEnCours){
      return { tempsTotal:0, nbCreneaux:0, registreVide:true, parType:{}, recursionGuard:true };
    }
    try{
      if(typeof buildMutualisationSemaine==='function' && typeof _buildPlanOpAutonome==='function'){
        if(typeof window!=='undefined') window.__chargeCreneauxPeuplementEnCours = true;
        const mut = await buildMutualisationSemaine(45);
        await _buildPlanOpAutonome(mut);   // peuple window._planParfumCreneaux pour toutes les semaines
        reg = (typeof window!=='undefined' && window._planParfumCreneaux) ? window._planParfumCreneaux : null;
      }
    }catch(e){ console.error('_chargeCreneauxFenetre auto-peuplement', e); }
    finally{ if(typeof window!=='undefined') window.__chargeCreneauxPeuplementEnCours = false; }
  }
  if(!reg){ return { tempsTotal:0, nbCreneaux:0, registreVide:true, parType:{} }; }
  // 2) Sommer les minutes des créneaux dont la date locale de début ∈ [debut, fin], toutes semaines confondues.
  let tempsTotal=0, nbCreneaux=0; const parType={ ganache:0, coques:0, montage:0 };
  const _detail=[];
  for(const wk in reg){
    const creneaux = reg[wk] || [];
    creneaux.forEach(c=>{
      if(!c || !c.debut) return;
      const dloc = ymdOf(c.debut);
      if(dloc < debutStr || dloc > finStr) return;   // hors fenêtre
      const d = dureeMin(c);
      tempsTotal += d; nbCreneaux++;
      if(parType[c.type]!=null) parType[c.type]+=d; else parType[c.type]=d;
      if(_detail.length<40) _detail.push(dloc+' '+c.type+(c.parfum?(' '+c.parfum):'')+' '+d+'min');
    });
  }
  // 3) Diag transparence (rubrique technique) : ce que la faisabilité VERRA en étape 2.
  try{
    if(typeof diagPublish==='function'){
      diagPublish('chargeCreneaux', '⏱️ Charge réelle (créneaux moteur 2)', {
        'Fenêtre': debutStr+' → '+finStr,
        'Source': 'window._planParfumCreneaux (rétroplanning, même registre que l\'ordre du jour)',
        'Créneaux dans la fenêtre': nbCreneaux,
        'Temps total (min)': tempsTotal,
        'Détail par étape (min)': 'ganache '+(parType.ganache||0)+' · coques '+(parType.coques||0)+' · montage '+(parType.montage||0),
        'Créneaux (échantillon)': _detail.length ? _detail : 'aucun créneau dans la fenêtre'
      });
    }
  }catch(e){swallow(e,'_chargeCreneauxFenetre')}
  return { tempsTotal, nbCreneaux, registreVide:false, parType };
}
// [FAISABILITÉ — fenêtre explicite] Charge vs disponibilité sur une fenêtre [debut, fin] quelconque.
// Utilisé par le verdict (fenêtre GLISSANTE de 7 jours : aujourd'hui + 6) et par _faisabiliteSemaine
// (bornes ISO, pour l'écran Production). Ne compte jamais le passé : debut est déjà ≥ aujourd'hui côté appelant.
async function _faisabiliteFenetre(debutStr, finStr, conf, besoinAdditionnel){
  if(!debutStr || !finStr) return null;
  if(finStr < debutStr) return null;
  conf = conf || ((typeof getAvailability==='function') ? getAvailability() : null);
  let tempsDispo = 0;
  try{
    const cur = new Date(debutStr+'T00:00:00');
    const end = new Date(finStr+'T00:00:00');
    let guard = 0;
    while(cur <= end && guard++ < 60){
      tempsDispo += (typeof availMinutesOnDay==='function') ? availMinutesOnDay(cur, null, null, conf) : 0;
      cur.setDate(cur.getDate()+1);
    }
  }catch(_){ tempsDispo = 0; }
  // [CONVERGENCE — étape 3] La charge vient des CRÉNEAUX RÉELS du moteur 2 (rétroplanning : stock
  // mobilisable déduit, congélation, placement horaire) — la VRAIE production que l'ordre du jour affiche.
  // Le moteur 1 (generateProductionOrder) est DÉBRANCHÉ de la faisabilité courante : il n'est plus appelé
  // QUE dans deux cas résiduels —
  //   (a) SIMULATION d'ajout (besoinAdditionnel) : les créneaux ne contiennent pas l'ajout fictif, seul le
  //       moteur 1 sait l'intégrer ;
  //   (b) REPLI d'urgence : si les créneaux sont indisponibles (registre vide non peuplable), on retombe sur
  //       le moteur 1 plutôt que de renvoyer une charge de 0 (qui ferait un verdict faussement rassurant).
  // En fonctionnement normal (créneaux présents, pas de simulation), le moteur 1 n'est PLUS appelé.
  const simulation = !!(besoinAdditionnel && typeof besoinAdditionnel==='object' && Object.keys(besoinAdditionnel).length);
  let charge = 0, source = '', m1Repli = null;
  if(simulation){
    // (a) Simulation : seul le moteur 1 intègre le besoin additionnel fictif.
    try{ const plan = await generateProductionOrder(debutStr, finStr, tempsDispo, besoinAdditionnel);
      charge = plan ? (plan.tempsTotal||0) : 0; }catch(_){ return null; }
    source = 'moteur 1 (simulation besoinAdditionnel)';
  } else {
    let cr = null;
    try{ cr = await _chargeCreneauxFenetre(debutStr, finStr); }catch(_){ cr = null; }
    if(cr && !cr.registreVide){
      charge = cr.tempsTotal||0; source = 'créneaux moteur 2';
    } else {
      // (b) Repli : créneaux indisponibles → moteur 1 comme filet de sécurité.
      try{ const plan = await generateProductionOrder(debutStr, finStr, tempsDispo, null);
        m1Repli = plan ? (plan.tempsTotal||0) : 0; }catch(_){ m1Repli = 0; }
      charge = m1Repli; source = 'moteur 1 (créneaux indisponibles — repli)';
    }
  }
  // [DIAG] Transparence : charge retenue + source. Plus de comparaison systématique (moteur 1 débranché en
  // v920 : la convergence a été validée en réel — écart négligeable en semaine légère, significatif en semaine
  // chargée, toujours en faveur du calcul juste). Clé par fenêtre (un diag distinct par semaine du plan).
  try{
    if(typeof diagPublish==='function'){
      diagPublish('faisabiliteSource:'+debutStr+'_'+finStr, '⚖️ Faisabilité '+debutStr+'→'+finStr, {
        'Fenêtre': debutStr+' → '+finStr,
        'Charge RETENUE (min)': charge+'  ['+source+']',
        'Capacité (min)': tempsDispo,
        'Charge %': tempsDispo>0 ? Math.round(charge/tempsDispo*100)+' %' : 'n/a',
        'Moteur 1': simulation ? 'utilisé (simulation)' : (m1Repli!=null ? 'utilisé (repli — créneaux absents)' : 'non appelé (débranché)'),
        'Lecture': 'La faisabilité juge la VRAIE production (créneaux moteur 2). Moteur 1 réservé à la simulation d\'ajout et au repli d\'urgence.'
      });
    }
  }catch(e){swallow(e,'_faisabiliteFenetre')}
  return {
    debut:debutStr, fin:finStr,
    tempsTotal: charge,
    tempsDispo,
    depassement: tempsDispo>0 && charge > tempsDispo,
    debordementMin: Math.max(0, charge - tempsDispo),
    chargePct: tempsDispo>0 ? Math.round(charge/tempsDispo*100) : 0
  };
}
async function _faisabiliteSemaine(wk, conf, besoinAdditionnel){
  const m = /(\d{4})-W(\d{2})/.exec(wk||'');
  if(!m) return null;
  // Bornes ISO de la semaine (même calcul que l'affichage des semaines du plan).
  const simple = new Date(Date.UTC(+m[1],0,1+(+m[2]-1)*7));
  const dow = (simple.getUTCDay()+6)%7;
  const lundi = new Date(simple); lundi.setUTCDate(simple.getUTCDate()-dow);
  const dim = new Date(lundi); dim.setUTCDate(lundi.getUTCDate()+6);
  const lundiStr = ymdLocal(lundi);
  const dimStr = ymdLocal(dim);
  // [DATE LOCALE — cohérence avec l'ordre du jour] today() repose sur toISOString() (UTC) et provoque un
  // off-by-one en France le soir (UTC+1/+2) : la fenêtre se décalait d'un jour vs l'ordre du jour (qui, lui,
  // utilise la date locale). On force la date LOCALE ici pour que verdict et ordre du jour voient le MÊME jour.
  const _now = new Date();
  const todayStr = _now.getFullYear()+'-'+String(_now.getMonth()+1).padStart(2,'0')+'-'+String(_now.getDate()).padStart(2,'0');
  if(dimStr < todayStr) return null;   // semaine entièrement passée → pas de verdict
  // [FENÊTRE GLISSANTE 7 JOURS] La SEMAINE COURANTE (celle qui contient aujourd'hui) est toujours vue
  // sur aujourd'hui + 6 jours — JAMAIS bornée au dimanche. Sinon, un dimanche, la fenêtre se réduirait à
  // une seule journée et ignorerait le lundi chargé du lendemain : l'outil de pilotage perdrait tout
  // son sens pile au pire moment. Pour les semaines FUTURES, on garde leurs bornes propres (lundi→dimanche).
  const estSemaineCourante = (lundiStr <= todayStr && todayStr <= dimStr);
  let debut, fin;
  if(estSemaineCourante){
    debut = todayStr;
    const d7 = new Date(todayStr+'T00:00:00'); d7.setDate(d7.getDate()+6);
    fin = ymdLocal(d7);          // aujourd'hui + 6 = 7 jours glissants
  } else {
    debut = lundiStr; fin = dimStr;              // semaine future : ses propres bornes
  }
  const f = await _faisabiliteFenetre(debut, fin, conf, besoinAdditionnel);
  if(!f) return null;
  return { lundi:lundiStr, dim:dimStr, debut:f.debut, fin:f.fin, glissant:estSemaineCourante,
           tempsTotal:f.tempsTotal, tempsDispo:f.tempsDispo,
           depassement:f.depassement, debordementMin:f.debordementMin, chargePct:f.chargePct };
}

function buildPlanOperationnelSemaine(mut, recipes, tEtape, stockMob, ganacheCaleParCmd, montageCaleParCmd){
  ganacheCaleParCmd = ganacheCaleParCmd || {};
  montageCaleParCmd = montageCaleParCmd || {};
  stockMob = stockMob || {};
  // [CLÉ UNIQUE] Même clé que la construction de stockMob (stockMoveKey = aiNormalize) et que
  // le journal des mouvements : un seul et même regroupement parfum dans tout le moteur de stock.
  const _stockKey = nom => stockMoveKey(nom);
  const stockDe = nom => { const b = stockMob[_stockKey(nom)]; return b ? (b.mobilisable||0) : 0; };
  if(!mut || !mut.semaines) return { semaines:[], horizonJours:(mut&&mut.horizonJours)||45 };
  recipes = recipes || [];
  tEtape  = tEtape || { coques:{}, ganache:{}, montage:{} };
  const t = (typeof getMrpTimes==='function') ? getMrpTimes()
            : { coques:{estimatedTime:35}, montage:{estimatedTime:15}, ganache:{estimatedTime:12} };
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const round1 = x => Math.round(x*10)/10;
  const norm = nom => (typeof aiNormalize==='function') ? aiNormalize(nom) : String(nom||'').toLowerCase().trim();
  const recByNom = nom => {
    const n=(nom||'').trim().toLowerCase();
    return recipes.find(r=>((r.produitNom||'').trim().toLowerCase())===n) || null;
  };

  // GANACHE : temps fixe par parfum. Mesuré (fiable) > recette > défaut 12.
  const tempsGanache = nom => {
    const k = norm(nom);
    const mes = tEtape.ganache && tEtape.ganache[k];
    if(mes && mes.fiable && mes.nbMac>0) return { min: round1(mes.minTotal/ (mes.nbSessions||1)), source:'mesuré' };
    const r = recByNom(nom);
    if(r && r.tempsGanacheMin!=null && +r.tempsGanacheMin>0) return { min:+r.tempsGanacheMin, source:'recette' };
    return { min: t.ganache.estimatedTime, source:'défaut' };
  };
  // MONTAGE : temps PAR BATCH (60). Mesuré (fiable, ramené au batch) > recette > défaut 15.
  const tempsMontageBatch = nom => {
    const k = norm(nom);
    const mes = tEtape.montage && tEtape.montage[k];
    if(mes && mes.fiable && mes.nbMac>0) return { perBatch: round1(mes.minTotal/mes.nbMac*TB), source:'mesuré' };
    const r = recByNom(nom);
    if(r && r.tempsMontageMin!=null && +r.tempsMontageMin>0) return { perBatch:+r.tempsMontageMin, source:'recette' };
    return { perBatch: t.montage.estimatedTime, source:'défaut' };
  };

  // [DIAG STOCK vs BESOIN — instrumentation, lecture seule] Pour chaque parfum/semaine, on capture le nom
  // demandé, la clé de regroupement (stockMoveKey), le stock mobilisable trouvé et son détail (finis /
  // assemblable). But : élucider les cas où un parfum est programmé à produire ALORS QUE du stock fini
  // existe (ex. Vanille). Si stock=0 mais qu'il y a du fini, c'est un décalage de CLÉ ou une EXCLUSION.
  const _diagStockBesoin = [];
  const semaines = mut.semaines.map(s=>{
    // [OPTIMISATION BATCH] Pour chaque parfum, on arrondit la quantité commandée au palier rationnel.
    // La PRODUCTION (coques, montage, ganache, temps) est pilotée par la quantité ARRONDIE ;
    // le surplus est tracé comme destiné au stock. Les commandes restent la référence affichée.
    const prodInfo = {};
    const _optimOn = (typeof getOptimBatch==='function') ? getOptimBatch() : false;
    s.parfums.forEach(p=>{
      const stockDispo = stockDe(p.nom);
      // Besoin NET après stock : ce qu'il reste à produire une fois le stock mobilisé.
      const besoinNet = Math.max(0, p.qte - stockDispo);
      // [DIAG] Détail du mobilisable trouvé pour ce parfum (par sa clé).
      try{
        const _k = _stockKey(p.nom);
        const _b = stockMob[_k] || null;
        _diagStockBesoin.push({
          parfum:p.nom, cle:_k, demande:p.qte, stockTrouve:stockDispo, besoinNet,
          detail: _b ? `finis ${round3(_b.finis||0)} · assemblable ${round3(_b.assemblable||0)} · coques ${round3(_b.coquesMac||0)} · ganache ${round3(_b.ganacheMac||0)}` : 'AUCUNE entrée stockMob pour cette clé'
        });
      }catch(e){swallow(e,'buildPlanOperationnelSemaine')}
      if(_optimOn){
        const ar = arrondirPalierProduction(besoinNet);
        prodInfo[p.nom] = { commande:p.qte, stock:stockDispo, besoinNet, produire:ar.produire, surplus:ar.surplus, paliers:ar.paliers };
      } else {
        prodInfo[p.nom] = { commande:p.qte, stock:stockDispo, besoinNet, produire:besoinNet, surplus:0, paliers:[besoinNet] };
      }
    });
    const qProd = nom => (prodInfo[nom] ? prodInfo[nom].produire : 0);
    // [FIX v924] Un parfum entièrement couvert par le stock (qteProduite=0) n'a RIEN à produire : on ne
    // génère NI ganache, NI coques, NI montage pour lui. Sans ce filtre, la ligne était créée et l'affichage
    // « qteProduite||qte » retombait sur qte (>0), montrant une fausse tâche (ex. Vanille « 14 mac · 12 min »
    // alors que 47 finis couvrent les 14). On filtre à la SOURCE pour que le temps total n'en tienne pas compte.
    const ganache = s.parfums.filter(p=> qProd(p.nom) > 0).map(p=>{
      const g = tempsGanache(p.nom);
      const pi = prodInfo[p.nom] || {commande:p.qte, produire:p.qte, surplus:0};
      return { parfum:p.nom, qte:p.qte, qteProduite:pi.produire, surplusStock:pi.surplus, paliers:pi.paliers, dureeMin:g.min, source:g.source,
               aMarche: p.commandes.some(c=>c.marche),
               commandes:p.commandes.map(c=>({client:c.client, qte:c.qte, orderId:c.orderId, marche:c.marche, marketId:c.marketId})) };
    });
    const montage = s.parfums.filter(p=> qProd(p.nom) > 0).map(p=>{
      const m = tempsMontageBatch(p.nom);
      const pi = prodInfo[p.nom] || {commande:p.qte, produire:p.qte, surplus:0, paliers:[]};
      const qp = pi.produire;   // on monte tout ce qu'on produit (commande + surplus stock)
      // [MONTAGE PAR PARFUM — MODÈLE FIXE+VARIABLE] Le temps de montage = part fixe de mise en place
      // (par batch entamé) + part variable proportionnelle aux macarons garnis. Voir _montageMinutes.
      // Remplace l'ancien « perBatch × nbBatchs » qui surestimait les petites séries.
      const nbBatchsMontage = Math.max(qp>0?1:0, Math.ceil(qp/TB));
      const base = _montageMinutes(qp, m.perBatch, m.source);
      // Temps spécifiques de la recette (noisettes, incrustation…), hors chablonnage (déjà compté aux coques).
      let specMin = 0; const specDetail = [];
      const rec = recByNom(p.nom);
      if(rec && Array.isArray(rec.tempsSpecifiques)){
        rec.tempsSpecifiques.forEach(op=>{
          const d = Math.max(0, +op.duree||0); if(d<=0) return;
          const nomOp = (op.nom||'').toLowerCase();
          if(nomOp.includes('chablon')) return;   // chablonnage géré au niveau des coques
          // Op « par macaron » = × quantité ; op « par batch » = × nb de batchs entamés (ceil).
          const min = (op.unite==='macaron') ? d*qp : d*nbBatchsMontage;
          specMin += min; specDetail.push({ nom:op.nom||'opération', min:round1(min) });
        });
      }
      const dureeTot = round1(base + specMin);
      // [MONTAGE — COMMANDE vs RÉASSORT, par QUANTITÉS] On monte qp = besoinNet (sert les commandes)
      // + surplus (réassort : clôturer le batch entamé, seulement si l'arrondi batch est coché).
      // On NE ventile PAS le temps en minutes : un montage = un seul batch/geste, découper son temps
      // donnerait des chiffres faux (« 0 min commande »). On garde donc UN temps total et on expose
      // les QUANTITÉS (exactes) : qteCommande = besoinNet, qteReassort = surplus. L'UI affiche
      // « X à monter (a commande + b réassort) ». Quand surplus=0, qteReassort=0 → pas de mention.
      const qteCommande = Math.max(0, +pi.besoinNet||0);   // macarons servant les commandes
      const qteReassort = Math.max(0, +pi.surplus||0);     // macarons de réassort (surplus d'arrondi batch)
      // « rien à monter » : le stock fini couvre la commande ET aucun réassort (qp=0).
      const rienAMonter = (qp<=0);
      return { parfum:p.nom, qte:p.qte, qteProduite:qp, stock:pi.stock, besoinNet:pi.besoinNet, surplusStock:pi.surplus, paliers:pi.paliers, parBatchMin:m.perBatch, source:m.source,
               dureeMin: dureeTot, baseMin:base, specMin:round1(specMin), specDetail,
               qteCommande, qteReassort, rienAMonter,
               aMarche: p.commandes.some(c=>c.marche),
               commandes:p.commandes.map(c=>({client:c.client, qte:c.qte, orderId:c.orderId, marche:c.marche, marketId:c.marketId})) };
    });
    const lignesCoques = s.parfums.filter(p=> qProd(p.nom) > 0).map(p=>({ parfum:p.nom, besoinNet:qProd(p.nom) }));
    const meringues = (typeof _packMeringues==='function') ? _packMeringues(lignesCoques) : [];
    const coques = meringues.map(m=>{
      // Coques chablonnées de cette meringue : somme des coques des parfums dont la recette a chablonnee=true.
      let coquesChablon = 0;
      Object.entries(m.repartition||{}).forEach(([nom,q])=>{
        const r = recByNom(nom);
        if(r && r.chablonnee) coquesChablon += (+q||0)*2;   // q macarons → 2 coques chacun
      });
      const tc = (typeof tempsCoquesFournee==='function') ? tempsCoquesFournee((m.macarons||0)*2, coquesChablon) : null;
      return {
        parfums:m.parfums, repartition:m.repartition, macarons:m.macarons, partielle:m.partielle,
        dureeMin: tc ? tc.totalMin : t.coques.estimatedTime,
        actifMin: tc ? tc.actifMin : null, cuissonMin: tc ? tc.cuissonMin : null, nbPlaques: tc ? tc.nbPlaques : null,
        chablonMin: tc ? tc.chablonMin : 0
      };
    });
    // [CALAGE HORAIRE DES COQUES] Place chaque meringue dans les vraies plages A/B (getAvailability),
    // étalée à rebours depuis le montage de référence de la semaine, ≤9h avant (sinon congélation).
    if(s.montageRef && typeof calerCoquesSemaine==='function'){
      try{
        // Vraie heure de montage calée par le rétroplanning (sinon repli 14h sur la date).
        const montageDebut = s.montageRefISO ? new Date(s.montageRefISO) : new Date(s.montageRef+'T14:00:00');
        const cal = calerCoquesSemaine(coques, montageDebut, (typeof getAvailability==='function'?getAvailability():null));
        cal.forEach(c=>{
          if(coques[c.index]){
            coques[c.index].debut = c.debut; coques[c.index].fin = c.fin;
            coques[c.index].finCuisson = c.finCuisson;
            coques[c.index].congeler = c.congeler; coques[c.index].congelRaison = c.raison;
          }
        });
      }catch(e){ console.error('calerCoquesSemaine',e); }
    }
    // [FUSION HORAIRE GANACHE — source de vérité unique] Au lieu de recalculer un horaire (qui
    // pourrait diverger du rétroplanning par commande), on RÉUTILISE l'horaire ganache déjà calé
    // par retroplanningCale (pré-collecté dans ganacheCaleParCmd : orderId → {debut, fin}).
    // Une ganache mutualisée concerne plusieurs commandes → on garde le créneau le plus PRÉCOCE
    // (le montage le plus urgent contraint la prépa). Ainsi plan et rétroplanning affichent le MÊME
    // horaire : aucune divergence possible.
    // [CRÉNEAU GANACHE — étape 1] Pour chaque ganache, créneau de DÉPART le plus précoce parmi
    // ses commandes (le montage le plus urgent contraint la prépa). On note aussi le repos.
    ganache.forEach(g=>{
      let best=null;
      (g.commandes||[]).forEach(c=>{
        // Clé unifiée : orderId pour une commande, 'mk'+marketId pour une contribution marché.
        const ckey = (c.orderId!=null) ? c.orderId : (c.marche && c.marketId!=null ? 'mk'+c.marketId : null);
        const cal = ckey!=null ? ganacheCaleParCmd[ckey] : null;
        if(cal && cal.debut){
          const d = new Date(cal.debut);
          if(!best || d < new Date(best.debut)) best = { debut:cal.debut, fin:cal.fin };
        }
      });
      const rec = recByNom(g.parfum);
      g.reposH = (rec && rec.ganacheDelaiH!=null) ? +rec.ganacheDelaiH : 12;
      g._ancre = best ? best.debut : null;          // heure de départ calée (point d'ancrage)
      g._echeance = best ? best.fin : null;          // échéance : la ganache doit être finie AU PLUS TARD à best.fin (= montage − repos)
      if(!best) g.horaireImpossible = true;          // aucune commande calée (rare)
    });
    // [CRÉNEAU GANACHE — étape 2] ÉTALEMENT SÉQUENTIEL : on ne peut faire qu'UNE ganache à la fois.
    // Les ganaches qui partagent le MÊME créneau de départ (même commande/échéance) sont enchaînées
    // les unes après les autres : la 1re démarre à l'ancre, chaque suivante démarre quand la
    // précédente finit (durée propre = g.dureeMin). Évite l'incohérence « toutes au même horaire ».
    // Règle validée : enchaînement AU PLUS TÔT à partir du créneau de départ.
    (function _etalerGanaches(){
      const groupes = {};
      ganache.forEach(g=>{ if(!g._ancre) return; (groupes[g._ancre] ||= []).push(g); });
      Object.keys(groupes).forEach(ancreIso=>{
        // ordre stable : ordre d'apparition dans la liste ganache (déjà trié par le plan)
        const grp = groupes[ancreIso];
        const dureesMs = grp.map(g=>Math.max(1, Math.round(+g.dureeMin||0))*60000);
        const totalMs = dureesMs.reduce((a,b)=>a+b,0);
        // [OPTION 3] Départ AU PLUS TÔT à l'ancre. Mais le créneau du rétroplanning est calé au plus
        // tard (collé au repos) et ne réserve souvent qu'UNE durée de ganache ; étaler N ganaches
        // vers l'avant déborderait après l'échéance (montage − repos), grignotant le repos.
        // Donc : si la séquence dépasse l'échéance du groupe, on RECULE tout le bloc juste ce qu'il
        // faut pour que la DERNIÈRE ganache finisse pile à l'échéance (repos préservé pour toutes).
        let debutBlocMs = new Date(ancreIso).getTime();
        // Échéance du groupe = le best.fin le plus précoce parmi ses ganaches (la plus contraignante).
        let echeanceMs = null;
        grp.forEach(g=>{ if(g._echeance){ const e=new Date(g._echeance).getTime(); if(echeanceMs===null || e<echeanceMs) echeanceMs=e; } });
        if(echeanceMs!==null && (debutBlocMs + totalMs) > echeanceMs){
          debutBlocMs = echeanceMs - totalMs;   // recule tout le bloc pour finir à l'échéance
          grp.forEach(g=>{ g._recale = true; }); // info : séquence reculée pour tenir le repos
        }
        let curseur = debutBlocMs;
        grp.forEach((g,i)=>{
          g.debut = new Date(curseur).toISOString();
          g.fin   = new Date(curseur + dureesMs[i]).toISOString();
          curseur += dureesMs[i];   // la suivante démarre à la fin de celle-ci
        });
      });
    })();
    // [CRÉNEAU MONTAGE — étape 1] Chaque parfum du montage reçoit l'ÉCHÉANCE de montage calée de sa
    // commande (pivot du rétroplanning, déjà dans les plages A/B). Mutualisé entre commandes →
    // échéance la plus PRÉCOCE (le montage le plus urgent contraint). On ne fixe PAS encore
    // g.debut/g.fin : ce créneau brut est partagé par tous les parfums d'une même commande, donc
    // les afficher tels quels les empilerait au même horaire (faux : un seul opérateur, deux bras).
    montage.forEach(g=>{
      let best=null;
      (g.commandes||[]).forEach(c=>{
        const ckey = (c.orderId!=null) ? c.orderId : (c.marche && c.marketId!=null ? 'mk'+c.marketId : null);
        const cal = ckey!=null ? montageCaleParCmd[ckey] : null;
        if(cal && cal.debut){
          const d = new Date(cal.debut);
          if(!best || d < new Date(best.debut)) best = { debut:cal.debut, fin:cal.fin };
        }
      });
      // [RIEN À MONTER] Si le stock fini couvre tout (qp=0), pas de créneau : on ne planifie pas
      // une tâche vide. Elle s'affichera « ✓ déjà en stock » sans horaire ni durée fantôme.
      g._echeanceMont = (best && !g.rienAMonter) ? best.fin : null;
      if(!best && !g.rienAMonter) g.horaireImpossible = true;
    });
    // [CRÉNEAU MONTAGE — étape 2] ÉTALEMENT SÉQUENTIEL À REBOURS. Comme les ganaches, on ne peut
    // monter qu'UN parfum à la fois (deux bras). Le montage est l'étape FINALE (collée à la
    // maturation/livraison) : on cale donc à REBOURS depuis l'échéance commune. Les montages qui
    // partagent la même échéance forment un groupe ; le DERNIER finit pile à l'échéance, chaque
    // précédent finit quand le suivant commence. Le bloc démarre donc à (échéance − durée totale).
    // Symétrique de _etalerGanaches, mais ancré sur la FIN (le montage ne peut pas déborder après
    // l'échéance sans repousser la livraison).
    (function _etalerMontages(){
      const groupes = {};
      montage.forEach(g=>{ if(!g._echeanceMont) return; (groupes[g._echeanceMont] ||= []).push(g); });
      Object.keys(groupes).forEach(echIso=>{
        const grp = groupes[echIso];
        const dureesMs = grp.map(g=>Math.max(1, Math.round(+g.dureeMin||0))*60000);
        const totalMs = dureesMs.reduce((a,b)=>a+b,0);
        // Enchaînement au plus tôt à partir de (échéance − total) → le dernier finit à l'échéance.
        const echeanceMs = new Date(echIso).getTime();
        let curseur = echeanceMs - totalMs;
        grp.forEach((g,i)=>{
          g.debut = new Date(curseur).toISOString();
          g.fin   = new Date(curseur + dureesMs[i]).toISOString();
          curseur += dureesMs[i];   // la suivante démarre à la fin de celle-ci
        });
        if(grp.length>1) grp.forEach(g=>{ g._enchaine = true; }); // info : séquence (plusieurs montages enchaînés)
      });
    })();
    const totalGanacheMin = Math.round(ganache.reduce((a,g)=>a+g.dureeMin,0));
    const totalMontageMin = Math.round(montage.reduce((a,g)=>a+g.dureeMin,0));
    const totalMontageQteCommande = montage.reduce((a,g)=>a+(+g.qteCommande||0),0);
    const totalMontageQteReassort = montage.reduce((a,g)=>a+(+g.qteReassort||0),0);
    const totalCoquesMin  = coques.reduce((a,m)=>a+m.dureeMin,0);
    // [TOTAL MACARONS] Trois notions distinctes pour un affichage clair selon l'optimisation :
    // - commandé  = ce que les clients ont demandé (p.qte brut), invariant ;
    // - produit   = ce qu'on fabrique réellement (somme des 'produire' = besoin net + surplus réassort) ;
    // - réassort  = produit − commandé net = le surplus d'arrondi batch (0 si optim désactivée).
    // L'affichage montre commandé seul si pas de réassort, sinon « commandé + réassort = produit ».
    const totalMacaronsCommande = s.parfums.reduce((a,p)=>a+(+p.qte||0),0);
    const totalMacaronsProduits = s.parfums.reduce((a,p)=>a+qProd(p.nom),0);
    const totalMacaronsReassort = Math.max(0, totalMacaronsProduits - totalMacaronsCommande);
    // Part des commandes déjà couverte par le stock fini (commandé − besoin net à produire), bornée.
    const totalMacaronsEnStock = s.parfums.reduce((a,p)=>{
      const pi = prodInfo[p.nom]; const bn = pi ? +pi.besoinNet||0 : +p.qte||0;
      return a + Math.max(0, (+p.qte||0) - bn);
    }, 0);
    const totalMacarons   = totalMacaronsCommande;   // rétrocompat : reste le commandé par défaut
    return { wk:s.wk, label:s.label, ganache, coques, montage,
             totalGanacheMin, totalCoquesMin, totalMontageMin,
             totalMontageQteCommande, totalMontageQteReassort,
             totalMacaronsCommande, totalMacaronsProduits, totalMacaronsReassort, totalMacaronsEnStock,
             totalMin: totalGanacheMin+totalMontageMin+totalCoquesMin, totalMacarons };
  });
  // [DIAG STOCK vs BESOIN] Publie la table parfum → clé → stock trouvé → à produire. Met en évidence les
  // cas suspects : besoin programmé alors que le stock devrait couvrir (élucide la Vanille). Lecture seule.
  try{
    if(typeof diagPublish==='function' && _diagStockBesoin.length){
      const _susp = _diagStockBesoin.filter(d=> d.besoinNet>0 && /finis [1-9]/.test(d.detail));
      diagPublish('stockBesoin', '📦 Stock vs besoin par parfum (production)', {
        'Lecture': 'Pour chaque parfum à produire : nom demandé, clé de regroupement, stock mobilisable trouvé, à produire. Un « à produire > 0 » AVEC des « finis » non nuls = stock non pris en compte (décalage de clé ou exclusion).',
        'Parfums (demande → stock → à produire)': _diagStockBesoin.map(d=>
          `${d.parfum} [clé: ${d.cle}] : demande ${d.demande}, stock ${d.stockTrouve}, à produire ${d.besoinNet}  ·  ${d.detail}`),
        '⚠ Suspects (à produire malgré du stock fini)': _susp.length
          ? _susp.map(d=>`${d.parfum} : ${d.detail} mais à produire ${d.besoinNet} (stock vu = ${d.stockTrouve})`)
          : 'aucun'
      });
    }
  }catch(e){swallow(e,'buildPlanOperationnelSemaine')}
  return { semaines, horizonJours: mut.horizonJours||45 };
}

// [FONDATION MUTUALISATION] Agrège les besoins en macarons PAR PARFUM et PAR JOUR DE MONTAGE,
// en croisant TOUTES les commandes à venir. Ne mutualise rien encore : se contente de CUMULER
// pour qu'on puisse voir « le 26/06 : 75 vanille (2 commandes), 40 pistache (1 commande)… ».
// Le jour retenu = jour du MONTAGE calé (c'est lui qui pilote la fraîcheur et les coques jour J).
// Renvoie { jours:[{date, label, semaineType, parfums:[{nom, qte, nbCommandes, commandes:[{client, qte, livraison}]}], totalJour}], horizonJours }.
async function buildParfumsParJour(horizonJours){
  horizonJours = +horizonJours || 45;
  const orders  = await db.orders.toArray().catch(()=>[]);
  const clients = await db.clients.toArray().catch(()=>[]);
  const clientNom = id => { const c=clients.find(x=>+x.id===+id); return c?(c.nom||c.prenom||'Client'):'—'; };
  const today0 = new Date(); today0.setHours(0,0,0,0);
  const horizon = new Date(today0); horizon.setDate(horizon.getDate()+horizonJours);

  // 'YYYY-MM-DD' -> { parfum -> { qte, commandes:[{client, qte, livraison}] } }
  const parJour = {};

  for(const o of orders){
    const st = (typeof normStatus==='function') ? normStatus(o.statut) : (o.statut||'');
    if(st==='Livrée') continue;
    const dLiv = o.dateEvenement || o.date || '';
    if(!dLiv) continue;

    // Jour de montage calé (pilote la fraîcheur). À défaut, on retombe sur la date de livraison.
    let jourKey=null;
    try{
      const cale = await retroplanningCale(o.id);
      if(cale && cale.ok && Array.isArray(cale.jalonsCales)){
        const montage = cale.jalonsCales.find(j=>j.cle==='montage' && j.debut);
        if(montage) jourKey = ymdLocal(new Date(montage.debut));
      }
    }catch(e){swallow(e,'buildParfumsParJour')}
    if(!jourKey) jourKey = String(dLiv).slice(0,10);

    const d = new Date(jourKey+'T12:00:00');
    if(d < today0 || d > horizon) continue;

    // Cumul des parfums de la commande (coffrets, événements, vrac, dons → parfums ; grands → items).
    const lignes = (typeof orderToLines==='function') ? orderToLines(o) : [];
    const cn = clientNom(o.clientId);
    lignes.forEach(ln=>{
      const src = (ln.type==='grand') ? (ln.items||[]) : (ln.parfums||[]);
      src.forEach(p=>{
        const nom=(p.nom||'').trim(); const qte=+p.qte||0;
        if(!nom || qte<=0) return;
        (parJour[jourKey] ||= {});
        const slot = (parJour[jourKey][nom] ||= { qte:0, commandes:[] });
        slot.qte += qte;
        slot.commandes.push({ client:cn, qte, livraison:String(dLiv).slice(0,10) });
      });
    });
  }

  const jours = Object.keys(parJour).sort().map(key=>{
    const parfumsObj = parJour[key];
    const parfums = Object.keys(parfumsObj).sort().map(nom=>({
      nom,
      qte: parfumsObj[nom].qte,
      nbCommandes: parfumsObj[nom].commandes.length,
      commandes: parfumsObj[nom].commandes
    })).sort((a,b)=>b.qte-a.qte);   // du parfum le plus demandé au moins demandé
    const totalJour = parfums.reduce((s,p)=>s+p.qte,0);
    const d = new Date(key+'T12:00:00');
    return {
      date:key,
      label:d.toLocaleDateString('fr-FR',{weekday:'long', day:'2-digit', month:'long'}),
      semaineType:(typeof availWeekType==='function') ? availWeekType(key) : '',
      parfums, totalJour
    };
  });
  return { jours, horizonJours };
}


// Affiche le rétroplanning d'une commande dans une modale (jalons datés à rebours).
async function retroplanningView(orderId){
  const o = await db.orders.get(orderId);
  if(!o){ toast('Commande introuvable'); return; }
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const r = retroplanningCommande(o, recipes);
  if(r.error){
    openModal(`<h3>🕘 Rétroplanning</h3><div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⛔ <div>${esc(r.error)}</div></div>
      <div class="modal-actions"><button class="btn gold" onclick="closeModal()">Fermer</button></div>`);
    return;
  }
  const cl = o.clientId ? await db.clients.get(o.clientId).catch(()=>null) : null;
  const fmtJ = d => d.toLocaleString('fr-FR',{weekday:'long', day:'2-digit', month:'long', hour:'2-digit', minute:'2-digit'});
  const fmtHeure = d => d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});
  const fmtJour = d => d.toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long'});

  // [CHANTIER 1] Rétroplanning CALÉ sur les disponibilités (3 types de tâches).
  let cale = null;
  try{ cale = await retroplanningCale(orderId); }catch(e){ console.error('retroCale',e); }

  // Métadonnées d'affichage par type de tâche calée.
  const TYPE_META = {
    encadree: {ico:'🟡', col:'#b8860b', tag:'présence requise'},
    active:   {ico:'🔴', col:'#a52a2a', tag:'travail actif'},
    libre:    {ico:'🟢', col:'#3f7d52', tag:'sans surveillance'},
    ancre:    {ico:'🎁', col:'#3f7d52', tag:''}
  };

  let corps, sousTitre, debordementBanner='';
  // [DÉTAIL PARFUM] Parfums de la commande, et meringues appariées pour les coques.
  const _lignesCmd = (typeof orderToLines==='function') ? orderToLines(o) : [];
  const _pf = {};
  _lignesCmd.forEach(ln=>{
    const src = (ln.type==='grand') ? (ln.items||[]) : (ln.parfums||[]);
    src.forEach(p=>{ const n=(p.nom||'').trim(); const q=+p.qte||0; if(n&&q>0) _pf[n]=(_pf[n]||0)+q; });
  });
  const _parfumsListe = Object.keys(_pf).sort((a,b)=>_pf[b]-_pf[a]);
  const _dot = nom => `<span style="display:inline-block;width:11px;height:11px;border-radius:50%;background:${(typeof flavorColor==='function')?flavorColor(nom):'#cbb89f'};border:1px solid rgba(0,0,0,.1);margin-right:5px;vertical-align:middle;flex:none"></span>`;
  // Détail HTML par type d'étape (ganache/montage en ligne ; coques groupées par meringue).
  const _detailParfums = cle => {
    if(!_parfumsListe.length) return '';
    if(cle==='coques'){
      const lignesC = _parfumsListe.map(n=>({parfum:n, besoinNet:_pf[n]}));
      const meringues = (typeof _packMeringues==='function') ? _packMeringues(lignesC) : [];
      if(!meringues.length) return '';
      const items = meringues.map((m,i)=>{
        const rep = Object.entries(m.repartition).map(([p,q])=>`${_dot(p)}${esc(p)} <b>${q}</b>`).join(' <span style="color:#c9b8a4">+</span> ');
        return `<div style="font-size:.76rem;color:#7a6a60;margin-top:2px">🥣 Meringue ${i+1} · ${rep}${m.partielle?' <span style="color:#b08a3a">(partielle)</span>':''}</div>`;
      }).join('');
      return `<div style="margin-top:4px;padding-left:4px">${items}</div>`;
    }
    if(cle==='ganache' || cle==='cremeux' || cle==='montage'){
      const enLigne = _parfumsListe.map(n=>`<span style="white-space:nowrap;margin-right:8px;display:inline-block">${_dot(n)}${esc(n)} <b>${_pf[n]}</b></span>`).join('');
      return `<div style="margin-top:4px;padding-left:4px;font-size:.78rem;color:#7a6a60;line-height:1.7">${enLigne}</div>`;
    }
    return '';
  };

  if(cale && cale.ok && Array.isArray(cale.jalonsCales)){
    // Vue CALÉE, en ordre CHRONOLOGIQUE STRICT (tri par heure de début réelle).
    // Lecture linéaire haut→bas : la 1re étape est ce que tu fais en PREMIER, la dernière = livraison.
    const chrono = cale.jalonsCales.slice().sort((a,b)=>{
      const ta = a.debut ? new Date(a.debut).getTime() : Infinity;
      const tb = b.debut ? new Date(b.debut).getTime() : Infinity;
      if(ta!==tb) return ta-tb;
      // À heure égale, la livraison (ancre) passe en dernier.
      if(a.type==='ancre') return 1;
      if(b.type==='ancre') return -1;
      return 0;
    });
    // Numérotation : seules les étapes de TRAVAIL et d'attente sont numérotées (pas la livraison finale).
    let _num = 0;
    // [SÉPARATEUR DE JOUR] On insère un bandeau de jour avant chaque étape qui change de journée,
    // pour distinguer visuellement à quel jour appartient chaque tâche. _jourCourant suit le jour rendu.
    let _jourCourant = null;
    const _fmtJourSep = iso => { try{ const d=new Date(iso); return d.toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long'}); }catch(e){ return ''; } };
    const rows = chrono.map(j=>{
      const meta = TYPE_META[j.type] || TYPE_META.active;
      const isLivraison = (j.cle==='livraison' || j.type==='ancre');
      // Bandeau de jour si on change de journée (basé sur le début de l'étape, ou la livraison pour l'ancre).
      let sepJour = '';
      const refIso = j.debut || (isLivraison ? j.fin : null);
      if(refIso){
        // Clé jour en heure LOCALE (cohérente avec fmtJour affiché), pas depuis l'ISO UTC qui
        // décalerait le jour pour les étapes de fin de soirée (fuseau positif).
        let jk = '';
        try{ const d=new Date(refIso); jk = d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate(); }catch(e){ jk = String(refIso).slice(0,10); }
        if(jk !== _jourCourant){
          _jourCourant = jk;
          const lbl = _fmtJourSep(refIso);
          sepJour = `<div style="display:flex;align-items:center;gap:8px;margin:14px 0 8px">
            <span style="flex:none;font-size:.8rem;font-weight:700;color:var(--bordeaux);text-transform:capitalize">📅 ${esc(lbl)}</span>
            <span style="flex:1;height:1px;background:#e3d6c4"></span>
          </div>`;
        }
      }
      const numBadge = isLivraison ? '🏁' : `<span style="display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:50%;background:var(--bordeaux);color:#fff;font-size:.72rem;font-weight:700;flex:none">${++_num}</span>`;
      if(j.tropLongue){
        return `${sepJour}<div class="sugg-row" style="align-items:flex-start;gap:8px">
          ${numBadge}
          <div class="sugg-main">
            <div><b style="color:#b3261e">⚠️ ${esc(j.label)}</b></div>
            <div style="font-size:.8rem;color:#b3261e;margin-top:1px">Trop longue pour tes créneaux habituels — à étaler sur plusieurs sessions.</div>
            ${_detailParfums(j.cle)}
          </div></div>`;
      }
      let quand;
      if(j.type==='ancre'){
        quand = esc(fmtJ(j.debut));
      } else if(j.type==='libre'){
        const mj = (a,b)=> dayKey2(a)===dayKey2(b);
        quand = mj(j.debut,j.fin)
          ? `${esc(fmtJour(j.debut))} de <b>${esc(fmtHeure(j.debut))}</b> à <b>${esc(fmtHeure(j.fin))}</b>`
          : `de ${esc(fmtJour(j.debut))} <b>${esc(fmtHeure(j.debut))}</b> à ${esc(fmtJour(j.fin))} <b>${esc(fmtHeure(j.fin))}</b>`;
      } else {
        quand = `${esc(fmtJour(j.debut))} · <b>${esc(fmtHeure(j.debut))}</b> → <b>${esc(fmtHeure(j.fin))}</b>`;
      }
      return `${sepJour}<div class="sugg-row" style="align-items:flex-start;gap:8px">
        ${numBadge}
        <div class="sugg-main">
          <div><b style="color:${meta.col}">${meta.ico} ${esc(j.label)}</b>${meta.tag?` <span style="font-size:.7rem;color:#9a8a82">· ${meta.tag}</span>`:''}${j.congeler?' <span style="background:#3b6ea5;color:#fff;font-size:.58rem;font-weight:600;padding:1px 6px;border-radius:7px">❄️ à congeler</span>':''}</div>
          <div style="font-size:.82rem;color:#8a6d3b;margin-top:1px">${quand}</div>
          ${_detailParfums(j.cle)}
        </div></div>`;
    }).join('');
    sousTitre = `Calé sur tes disponibilités · ${cale.nbMacarons} macaron(s)`;
    if(cale.maturationReduite){
      debordementBanner += `<div class="banner" style="background:#eef5ee;border-color:#bcd8bc;margin-top:8px">🧊 <div><b>Maturation ajustée à ${cale.maturationRetenueH} h</b> (au lieu de 24 h) pour garder les coques fraîches le jour du montage et éviter la congélation. La fraîcheur des coques prime sur la durée de maturation.</div></div>`;
    }
    if(cale.aDesDebordements){
      debordementBanner = `<div class="banner" style="background:#fdf3f2;border-color:#e5b4ae;margin-top:8px">⚠️ <div>Une ou plusieurs étapes ne tiennent pas dans tes créneaux habituels. Il faudra les étaler sur plusieurs sessions, ou élargir tes disponibilités sur cette période.</div></div>`;
    }
    corps = rows;
  } else {
    // Repli : ancienne vue brute (délais incompressibles, sans calage horaire).
    const ico = j => j.cle==='livraison'?'🎁' : j.type==='attente'?'⏳' : j.cle==='coques'?'🥚' : j.cle==='ganache'?'🍫' : j.cle==='montage'?'🔗' : '•';
    corps = r.jalons.map(j=>{
      const col = j.cle==='livraison' ? '#3f7d52' : (j.type==='attente' ? '#9a8a82' : '#5a3a2a');
      return `<div class="sugg-row" style="align-items:flex-start">
        <div class="sugg-main">
          <div><b style="color:${col}">${ico(j)} ${esc(j.label)}</b></div>
          <div style="font-size:.82rem;color:#8a6d3b;margin-top:1px">${esc(fmtJ(j.date))}</div>
          ${j.note?`<div style="font-size:.76rem;color:#9a8a82;margin-top:2px">${esc(j.note)}</div>`:''}
        </div></div>`;
    }).join('');
    sousTitre = 'Jalons indicatifs (délais incompressibles)';
  }
  const contraintes = (r.contraintes&&r.contraintes.length)
    ? `<div class="banner" style="background:#fdf8e9;border-color:#e8d09a;margin-top:8px">📋 <div><b>Contraintes prises en compte :</b><br>${r.contraintes.map(esc).join('<br>')}</div></div>`
    : '';
  // [SIMULATION — ÉTAPE B] Bloc « et si je livrais le X ? » : rejoue le calage à une date fictive
  // (sans rien écrire en base) et affiche heure de démarrage + faisabilité + comparaison au réel.
  // La date réelle pré-remplit le sélecteur. Le calcul est délégué à retroSimuler (réutilise
  // retroplanningCaleParfums, le moteur paramétré par date). Repliable pour ne pas alourdir la vue.
  const _dateLivReelle = (o.dateEvenement || o.date || '').slice(0,10);
  const _heureLivReelle = o.heureLivraison || '';
  const simBloc = `
    <div style="margin-top:12px;border-top:1px solid #eadfd3;padding-top:10px">
      <button type="button" onclick="retroSimToggle(this)" style="width:100%;text-align:left;background:none;border:none;cursor:pointer;font-size:.92rem;font-weight:600;color:var(--bordeaux);display:flex;align-items:center;gap:6px;padding:0">
        <span class="retrosim-chev" style="transition:transform .2s">▸</span> 🔮 Simuler une autre date de livraison
      </button>
      <div class="retrosim-body" style="display:none;margin-top:10px">
        <p class="note" style="margin-top:0">Teste une date différente sans rien modifier : l'app recalcule quand il faudrait démarrer et si ça tient dans tes créneaux.</p>
        <div class="row2">
          <div class="field"><label>Date de livraison testée</label><input type="date" id="retroSimDate" value="${esc(_dateLivReelle)}"></div>
          <div class="field"><label>Heure</label><input type="time" id="retroSimHeure" value="${esc(_heureLivReelle||'10:00')}"></div>
        </div>
        <button class="btn gold sm" style="width:100%;margin-top:4px" onclick="retroSimuler(${orderId})">🔮 Simuler cette date</button>
        <div id="retroSimResult" style="margin-top:10px"></div>
      </div>
    </div>`;
  openModal(`<h3>🕘 Rétroplanning</h3>
    <p style="margin-bottom:4px"><b>Livraison ${esc(cl?cl.nom:'')}</b> · ${esc(fmtJ(r.livraison))}</p>
    <p class="note" style="margin-bottom:10px">${esc(sousTitre)}. 🔴 travail actif · 🟡 présence requise (cuisson) · 🟢 sans surveillance (peut tourner la nuit).</p>
    ${corps}
    ${debordementBanner}
    ${contraintes}
    ${simBloc}
    <div class="modal-actions"><button class="btn ghost" style="margin-right:auto" onclick="closeModal()">Fermer</button><button class="btn gold" onclick="retroplanningICS(${orderId})" title="Ajouter ces étapes à ton calendrier iPhone">📲 Ajouter au calendrier</button></div>`);
}

// [SIMULATION] Replie/déplie le bloc de simulation.
function retroSimToggle(btn){
  const body = btn.parentElement.querySelector('.retrosim-body');
  const chev = btn.querySelector('.retrosim-chev');
  if(!body) return;
  const open = body.style.display!=='none';
  body.style.display = open ? 'none' : 'block';
  if(chev) chev.style.transform = open ? '' : 'rotate(90deg)';
}

// [SIMULATION — niveaux 1 & 2] Rejoue le calage à la date fictive et affiche le résultat.
// AUCUNE écriture en base : on lit la commande, on appelle le moteur paramétré (retroplanningCaleParfums)
// avec la date/heure saisies, et on compare au calage réel. Niveau 1 = heure de démarrage + faisabilité ;
// niveau 2 = comparaison au réel (jours de marge gagnés/perdus).
async function retroSimuler(orderId){
  const out = document.getElementById('retroSimResult');
  if(out) out.innerHTML = `<div style="font-size:.8rem;color:#9a8576">⏳ Calcul…</div>`;
  try{
    const dateSim = (document.getElementById('retroSimDate')||{}).value || '';
    const heureSim = (document.getElementById('retroSimHeure')||{}).value || '';
    if(!dateSim){ if(out) out.innerHTML = `<div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⛔ <div>Choisis une date à tester.</div></div>`; return; }
    const o = await db.orders.get(orderId);
    if(!o){ if(out) out.innerHTML = `<div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⛔ <div>Commande introuvable.</div></div>`; return; }
    const recipes = await db.recipes.toArray().catch(()=>[]);
    const parfumsQtes = _parfumsQtesDe(o);
    // [FIX point 3 — racine] Sans parfum sélectionné, il n'y a RIEN à produire : pas de ganache, pas
    // de coques. Caler un planning sur une commande vide produit un déroulé fantôme (ganache « À
    // définir », ordre incohérent). On le dit clairement plutôt que d'afficher un faux résultat.
    if(!parfumsQtes.length){
      if(out) out.innerHTML = `<div class="banner" style="background:#fdf8e9;border-color:#e8d09a">📋 <div>Cette commande n'a <b>aucun parfum</b> sélectionné — il n'y a rien à produire, donc rien à simuler. Ajoute des parfums à la commande pour tester une date.</div></div>`;
      return;
    }

    // Calage à la date FICTIVE (simulation pure).
    const sim = await retroplanningCaleParfums(dateSim, heureSim, parfumsQtes, recipes);
    // Calage RÉEL (référence pour la comparaison).
    const dateReelle = (o.dateEvenement || o.date || '').slice(0,10);
    const reel = await retroplanningCale(orderId).catch(()=>null);

    if(!sim || !sim.ok){
      if(out) out.innerHTML = `<div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⛔ <div>${esc((sim&&sim.error)||'Simulation impossible pour cette date.')}</div></div>`;
      return;
    }

    const fmtDH = iso => { try{ const d=new Date(iso); return d.toLocaleString('fr-FR',{weekday:'long',day:'2-digit',month:'long',hour:'2-digit',minute:'2-digit'}); }catch(e){ return '—'; } };
    const jourDe = iso => { try{ const d=new Date(iso); d.setHours(0,0,0,0); return d.getTime(); }catch(e){ return null; } };

    // NIVEAU 1 : heure de démarrage impliquée + verdict de faisabilité.
    const debutSim = sim.debutProduction;
    const tient = !sim.aDesDebordements;
    const verdictCol = tient ? '#3f7d52' : '#a8521f';
    const verdictBg  = tient ? '#eef6ee' : '#fdf4e6';
    const verdictTxt = tient
      ? `✓ <b>Ça tient</b> dans tes créneaux à cette date.`
      : `⚠️ <b>Ça déborde</b> de tes créneaux à cette date — il faudrait t'y prendre autrement.`;
    const debutTxt = debutSim
      ? `Il faudrait <b>commencer la production le ${esc(fmtDH(debutSim))}</b>.`
      : `Démarrage non calculable pour cette date.`;

    // NIVEAU 2 : comparaison au réel (jours de marge sur le démarrage).
    let compaTxt = '';
    if(reel && reel.ok && reel.debutProduction && debutSim){
      const jSim = jourDe(debutSim), jReel = jourDe(reel.debutProduction);
      if(jSim!=null && jReel!=null){
        const deltaJ = Math.round((jSim - jReel)/86400000);
        if(deltaJ===0){
          compaTxt = `<div style="font-size:.8rem;color:#7a6a60;margin-top:6px">Même jour de démarrage que la date réelle (${esc(fmtDate(dateReelle))}).</div>`;
        } else if(deltaJ>0){
          compaTxt = `<div style="font-size:.8rem;color:#3f7d52;margin-top:6px">↩︎ Démarrage <b>repoussé de ${deltaJ} jour${deltaJ>1?'s':''}</b> par rapport à ta date réelle (${esc(fmtDate(dateReelle))}) — tu gagnes de la marge.</div>`;
        } else {
          compaTxt = `<div style="font-size:.8rem;color:#a8521f;margin-top:6px">⏪ Démarrage <b>avancé de ${-deltaJ} jour${-deltaJ>1?'s':''}</b> par rapport à ta date réelle (${esc(fmtDate(dateReelle))}) — il faut s'y mettre plus tôt.</div>`;
        }
      }
    }

    // NIVEAU 3 : impact sur la semaine cible (chevauche-t-elle les autres commandes ?).
    let impactTxt = '';
    try{
      const imp = await _retroImpactSemaine(orderId, dateSim, sim);
      if(imp && imp.ok){
        if(imp.nbAutresCommandes===0){
          impactTxt = `<div style="font-size:.8rem;color:#7a6a60;margin-top:8px;padding-top:7px;border-top:1px solid #00000012">📅 <b>Semaine ${esc(imp.semaineLabel)}</b> : aucune autre commande cette semaine-là, tu as le champ libre.</div>`;
        } else if(!imp.conflits.length){
          impactTxt = `<div style="font-size:.8rem;color:#3f7d52;margin-top:8px;padding-top:7px;border-top:1px solid #00000012">📅 <b>Semaine ${esc(imp.semaineLabel)}</b> : ${imp.nbAutresCommandes} autre${imp.nbAutresCommandes>1?'s':''} commande${imp.nbAutresCommandes>1?'s':''}, mais <b>aucun chevauchement</b> — la semaine peut l'absorber.</div>`;
        } else {
          const fmtH = m => m>=60 ? `${Math.floor(m/60)}h${String(Math.round(m%60)).padStart(2,'0')}` : `${Math.round(m)} min`;
          const details = imp.conflits.map(c=>`<div style="margin-top:2px">• <b>${esc(c.client)}</b> — chevauchement de <b>${fmtH(c.minutes)}</b></div>`).join('');
          impactTxt = `<div style="font-size:.8rem;color:#a8521f;margin-top:8px;padding-top:7px;border-top:1px solid #00000012">📅 <b>Semaine ${esc(imp.semaineLabel)}</b> : ⚠️ ça <b>chevaucherait ${imp.conflits.length} commande${imp.conflits.length>1?'s':''}</b> (${fmtH(imp.totalMinutes)} au total) — risque d'embouteillage à l'atelier.${details}</div>`;
        }
      }
    }catch(e){ console.error('retroSim niveau 3', e); }

    if(out) out.innerHTML = `
      <div style="background:${verdictBg};border:1px solid ${verdictCol}33;border-radius:9px;padding:9px 11px;font-size:.82rem;color:${verdictCol}">
        ${verdictTxt}
        <div style="color:#5a4a44;margin-top:4px">${debutTxt}</div>
        ${compaTxt}
        ${impactTxt}
      </div>`;
  }catch(e){
    console.error('retroSimuler', e);
    if(out) out.innerHTML = `<div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⛔ <div>Erreur pendant la simulation.</div></div>`;
  }
}
// Helper : clé de jour (YYYY-MM-DD local) pour comparer deux dates.
function dayKey2(d){ return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate(); }

// [CONNEXION D] Exporte le rétroplanning d'une commande en fichier .ics (calendrier iPhone).
// Un événement daté/heuré par jalon, avec alarme. Timezone Europe/Paris.
async function retroplanningICS(orderId){
  const o = await db.orders.get(orderId);
  if(!o){ toast('Commande introuvable'); return; }
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const r = retroplanningCommande(o, recipes);
  if(r.error){ toast(r.error); return; }
  const cl = o.clientId ? await db.clients.get(o.clientId).catch(()=>null) : null;
  const clNom = cl ? cl.nom : '';

  const pad = n => String(n).padStart(2,'0');
  // Format DTSTART local (sans Z) pour TZID=Europe/Paris.
  const fmtLocal = d => d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+'T'+pad(d.getHours())+pad(d.getMinutes())+'00';
  const stamp = (()=>{ const d=new Date(); return d.getUTCFullYear()+pad(d.getUTCMonth()+1)+pad(d.getUTCDate())+'T'+pad(d.getUTCHours())+pad(d.getUTCMinutes())+pad(d.getUTCSeconds())+'Z'; })();
  const uid = ()=> 'smretro-'+Math.random().toString(36).slice(2)+'@sensations-macarons';
  // Échappement minimal pour les champs texte ICS.
  const esc = s => String(s||'').replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\n/g,'\\n');

  // Un VEVENT par jalon (on inclut la livraison comme repère, sans alarme anticipée).
  const vevents = r.jalons.map(j=>{
    const isLiv = j.cle==='livraison';
    const sum = `${j.label}${clNom?(' — '+clNom):''}`;
    const lines = [
      'BEGIN:VEVENT','UID:'+uid(),'DTSTAMP:'+stamp,
      'DTSTART;TZID=Europe/Paris:'+fmtLocal(j.date),
      'DURATION:PT15M',
      'SUMMARY:'+esc((isLiv?'🎁 ':(j.type==='attente'?'⏳ ':'👨‍🍳 '))+sum),
      'DESCRIPTION:'+esc((j.note||'')+'\nRétroplanning Sensations Macarons.')
    ];
    // Alarme : à l'heure pour une tâche, pas d'alarme anticipée pour la livraison.
    if(!isLiv){
      lines.push('BEGIN:VALARM','ACTION:DISPLAY','TRIGGER:PT0M','DESCRIPTION:'+esc(sum),'END:VALARM');
    }
    lines.push('END:VEVENT');
    return lines.join('\r\n');
  });

  const body = [
    'BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Sensations Macarons//Retroplanning//FR','CALSCALE:GREGORIAN','METHOD:PUBLISH',
    'BEGIN:VTIMEZONE','TZID:Europe/Paris',
    'BEGIN:STANDARD','DTSTART:19701025T030000','TZOFFSETFROM:+0200','TZOFFSETTO:+0100','RRULE:FREQ=YEARLY;BYMONTH=10;BYDAY=-1SU','END:STANDARD',
    'BEGIN:DAYLIGHT','DTSTART:19700329T020000','TZOFFSETFROM:+0100','TZOFFSETTO:+0200','RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=-1SU','END:DAYLIGHT',
    'END:VTIMEZONE',
    ...vevents,
    'END:VCALENDAR'
  ].join('\r\n');

  try{
    const blob=new Blob([body],{type:'text/calendar;charset=utf-8'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    const datePart = (o.date||'').replace(/-/g,'');
    a.href=url; a.download=`retroplanning-${datePart||'commande'}.ics`;
    document.body.appendChild(a); a.click();
    setTimeout(()=>{ document.body.removeChild(a); URL.revokeObjectURL(url); }, 1500);
    toast('Rétroplanning créé — choisis « Calendrier » dans iOS ✓');
  }catch(e){ console.error('retroplanningICS',e); toast('Erreur lors de la création du fichier'); }
}

// Éditeur des disponibilités (planning bi-hebdomadaire A/B).
const _DOW_LBL = {1:'Lundi',2:'Mardi',3:'Mercredi',4:'Jeudi',5:'Vendredi',6:'Samedi',0:'Dimanche'};
const _DOW_ORDER = [1,2,3,4,5,6,0];
// Convertit les plages d'un jour en texte éditable : "14:00-22:00, 21:30-24:00"
function _slotsToText(slots){ return (slots||[]).map(s=>`${s[0]}-${s[1]}`).join(', '); }
function _textToSlots(txt){
  return String(txt||'').split(',').map(x=>x.trim()).filter(Boolean).map(x=>{
    const [a,b]=x.split('-').map(s=>s.trim());
    return (/^\d{1,2}:\d{2}$/.test(a)&&/^\d{1,2}:\d{2}$/.test(b))?[a,b]:null;
  }).filter(Boolean);
}
function availEditor(){
  const conf=getAvailability();
  const weekRows = (wk, map)=> _DOW_ORDER.map(dw=>`
    <div class="avail-row">
      <label>${_DOW_LBL[dw]}</label>
      <input id="av_${wk}_${dw}" value="${esc(_slotsToText(map[dw]))}" placeholder="ex : 14:00-22:00" spellcheck="false">
    </div>`).join('');
  openModal(`<h3>🗓 Mes disponibilités</h3>
    <p class="note">Plages de travail récurrentes, en alternance une semaine sur deux. Format : <b>HH:MM-HH:MM</b>, plusieurs plages séparées par une virgule (ex : <i>08:30-12:00, 21:30-24:00</i>). Minuit = <b>24:00</b>.</p>
    <div class="avail-anchor">Cycle ancré au <b>${fmtDate(conf.anchor||AVAIL_ANCHOR)}</b> (= Semaine A).</div>
    <h4 style="margin:12px 0 4px;color:var(--bordeaux)">Semaine A</h4>${weekRows('A', conf.weekA)}
    <h4 style="margin:14px 0 4px;color:var(--bordeaux)">Semaine B</h4>${weekRows('B', conf.weekB)}
    <div style="margin-top:14px;padding-top:12px;border-top:1px solid #eadfd3">
      <h4 style="margin:0 0 4px;color:var(--bordeaux)">🏖 Exceptions / vacances</h4>
      <p class="note" style="margin:0 0 8px">Jours fermés, vacances, horaires ponctuels — ils remplacent ton cycle habituel sur les dates choisies.</p>
      <button class="btn ghost" style="width:100%" onclick="availSave(true);availExceptionsForm()">Gérer mes exceptions →</button>
    </div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="availSave()">Enregistrer</button></div>`);
}
function availSave(silencieux){
  const conf=getAvailability();
  const out={anchor:conf.anchor||AVAIL_ANCHOR, weekA:{}, weekB:{}};
  _DOW_ORDER.forEach(dw=>{
    out.weekA[dw]=_textToSlots(document.getElementById('av_A_'+dw)?.value);
    out.weekB[dw]=_textToSlots(document.getElementById('av_B_'+dw)?.value);
  });
  saveAvailability(out);
  if(silencieux) return;   // sauvegarde sans fermer le modal (enchaînement vers exceptions)
  closeModal(); toast('Disponibilités enregistrées ✓');
  if(view==='agendaprod') renderAgendaProduction();
}

// --- UI : gestion des exceptions de planning (vacances, fermetures, horaires ponctuels) ---
function availExceptionsForm(){
  const list = getAvailExceptions().slice().sort((a,b)=>(a.start||'').localeCompare(b.start||''));
  const etatLabel = e => e==='ferme' ? '🔒 Fermé' : e==='full' ? '🏖 Full dispo' : '🕐 Horaires';
  const etatSlots = e => (e.etat==='ferme') ? 'aucune dispo'
    : (e.slots||[]).map(([s,end])=>`${s}-${end}`).join(', ') || '—';
  const rows = list.length ? list.map(e=>{
    const periode = (e.start===e.end) ? fmtDate(e.start) : `${fmtDate(e.start)} → ${fmtDate(e.end)}`;
    return `<div class="sum-box" style="align-items:flex-start">
      <span style="flex:1"><b>${etatLabel(e.etat)}</b><br><span style="font-size:.82rem">${periode}</span><br><span style="color:#9a8a82;font-size:.76rem">${etatSlots(e)}</span></span>
      <button class="btn ghost sm" onclick="availExceptionRemove('${e.id}')" title="Supprimer">🗑</button></div>`;
  }).join('') : '<p class="note">Aucune exception. Ton cycle A/B s\'applique partout.</p>';

  openModal(`<h3>🏖 Exceptions / vacances</h3>
    <p class="note">Une exception remplace ton cycle habituel sur les dates choisies. Pratique pour les vacances, jours fériés, ou horaires ponctuels.</p>

    <h4 style="margin:10px 0 6px;color:var(--bordeaux)">Raccourcis rapides</h4>
    <div style="display:flex;flex-wrap:wrap;gap:6px">
      <button class="btn ghost sm" onclick="availExceptionQuick('ferme-today')">🔒 Fermer aujourd'hui</button>
      <button class="btn ghost sm" onclick="availExceptionQuick('ferme-weekend')">🔒 Fermer ce week-end</button>
      <button class="btn ghost sm" onclick="availExceptionQuick('full-week')">🏖 Full dispo cette semaine</button>
    </div>

    <h4 style="margin:14px 0 6px;color:var(--bordeaux)">Sur-mesure</h4>
    <div class="field"><label>Du</label><input type="date" id="exc_start"></div>
    <div class="field"><label>Au (inclus)</label><input type="date" id="exc_end"></div>
    <div class="field"><label>État</label>
      <select id="exc_etat" onchange="availExceptionEtatChange()">
        <option value="ferme">🔒 Fermé (aucune dispo)</option>
        <option value="full">🏖 Full dispo (vacances)</option>
        <option value="custom">🕐 Horaires précis</option>
      </select></div>
    <div class="field" id="exc_slots_wrap" style="display:none"><label>Plages (ex : 08:00-20:00, plusieurs séparées par virgule)</label>
      <input id="exc_slots" placeholder="08:00-20:00" spellcheck="false"></div>
    <button class="btn gold" style="width:100%;margin-top:4px" onclick="availExceptionAdd()">＋ Ajouter cette exception</button>

    <h4 style="margin:16px 0 6px;color:var(--bordeaux)">Mes exceptions</h4>
    ${rows}
    <div class="modal-actions"><button class="btn ghost" onclick="availEditor()">← Retour au planning</button>
      <button class="btn" onclick="closeModal()">Fermer</button></div>`);
  availExceptionEtatChange();
}

// Affiche le champ plages seulement pour 'full' et 'custom'.
function availExceptionEtatChange(){
  const etat=document.getElementById('exc_etat')?.value;
  const wrap=document.getElementById('exc_slots_wrap');
  const inp=document.getElementById('exc_slots');
  if(!wrap) return;
  if(etat==='ferme'){ wrap.style.display='none'; }
  else { wrap.style.display='block';
    if(inp && !inp.value){ inp.value = (etat==='full') ? '08:00-20:00' : ''; }
  }
}

// Ajoute une exception sur-mesure depuis le formulaire.
function availExceptionAdd(){
  const start=document.getElementById('exc_start')?.value;
  const end=document.getElementById('exc_end')?.value || start;
  const etat=document.getElementById('exc_etat')?.value||'ferme';
  if(!start){ toast('Choisis au moins une date de début'); return; }
  if(end<start){ toast('La date de fin est avant le début'); return; }
  let slots=[];
  if(etat!=='ferme'){
    slots=_textToSlots(document.getElementById('exc_slots')?.value);
    if(!slots.length){ toast('Renseigne au moins une plage horaire'); return; }
  }
  const list=getAvailExceptions();
  list.push({ id:'exc'+Date.now(), start, end, etat, slots });
  saveAvailExceptions(list);
  toast('Exception ajoutée ✓');
  availExceptionsForm();
  if(view==='agendaprod') renderAgendaProduction();
}

// Raccourcis rapides.
function availExceptionQuick(kind){
  const list=getAvailExceptions();
  const d=new Date(); const iso = x => ymdLocal(x);
  if(kind==='ferme-today'){
    list.push({id:'exc'+Date.now(), start:iso(d), end:iso(d), etat:'ferme', slots:[]});
    toast('Aujourd\'hui fermé ✓');
  } else if(kind==='ferme-weekend'){
    // prochain samedi + dimanche
    const day=d.getDay(); const toSat=(6-day+7)%7;
    const sat=new Date(d); sat.setDate(d.getDate()+toSat);
    const sun=new Date(sat); sun.setDate(sat.getDate()+1);
    list.push({id:'exc'+Date.now(), start:iso(sat), end:iso(sun), etat:'ferme', slots:[]});
    toast('Week-end fermé ✓');
  } else if(kind==='full-week'){
    // lundi → dimanche de la semaine courante
    const day=(d.getDay()+6)%7; const mon=new Date(d); mon.setDate(d.getDate()-day);
    const sun=new Date(mon); sun.setDate(mon.getDate()+6);
    list.push({id:'exc'+Date.now(), start:iso(mon), end:iso(sun), etat:'full', slots:[['08:00','20:00']]});
    toast('Semaine en full dispo ✓');
  }
  saveAvailExceptions(list);
  availExceptionsForm();
  if(view==='agendaprod') renderAgendaProduction();
}

// Supprime une exception.
function availExceptionRemove(id){
  saveAvailExceptions(getAvailExceptions().filter(e=>e.id!==id));
  toast('Exception supprimée');
  availExceptionsForm();
  if(view==='agendaprod') renderAgendaProduction();
}


// --- Persistance des temps de production (apprentissage) ---
// 'coques' = temps d'UNE meringue (mutualisée, sert 2 batchs) ; 'ganache'/'montage' = PAR batch.
const MRP_TIME_KEY = 'sm_mrp_times';
const MRP_TIME_DEFAULTS = {
  coques:    { estimatedTime: 35, totalRealTime: 0, completions: 0 },  // par MERINGUE (2 batchs)
  montage:   { estimatedTime: 15, totalRealTime: 0, completions: 0 },  // par batch (60 macarons)
  ganache:   { estimatedTime: 12, totalRealTime: 0, completions: 0 },  // par batch (60 macarons)
  vaisselle: { estimatedTime: 10, totalRealTime: 0, completions: 0 },  // par batch — charge de prod
  entretien: { estimatedTime: 15, totalRealTime: 0, completions: 0 }   // par SESSION — indép. du volume
};
// [PLANCHERS DE PLAUSIBILITÉ] Temps minimaux physiquement crédibles par étape (par batch/meringue).
// L'auto-apprentissage (validateTask) peut, sur une mesure aberrante (chrono lancé/arrêté trop vite),
// faire descendre estimatedTime sous le crédible (ex. montage à 1 min/batch). Ces planchers servent à
// (1) refuser d'apprendre une valeur sous le seuil et (2) réparer une valeur déjà corrompue au chargement.
// Seul le montage a une valeur métier confirmée (Benjamin : garnir 60 macarons ≥ 15 min). Les autres
// sont laissés à 0 (pas de plancher) tant qu'aucune valeur sûre n'est établie — on ne devine pas.
const MRP_TIME_FLOOR = {
  coques:    0,
  montage:   15,   // min/batch — garnir 60 macarons ne peut pas descendre sous 15 min (donnée métier)
  ganache:   0,
  vaisselle: 0,
  entretien: 0
};
// [MODÈLE MONTAGE FIXE + VARIABLE] Le temps de montage d'un parfum = une PART FIXE (mise en place :
// sortir/remplir la poche, installer le poste — indépendante de la quantité, payée une fois par batch
// entamé) + une PART VARIABLE proportionnelle au nombre de macarons réellement garnis. Calibré sur les
// données terrain de Benjamin : 26 min pour 55 macarons garnis = 4 min de mise en place + 0,4 min/mac
// (16 min pochage + 10 min assemblage, prép. incluse). Remplace l'ancien « batch entier » qui surestimait
// les petites séries (10 mac comptaient 1 batch = 15 min au lieu de ~8 min réelles).
const MONTAGE_FIXE_MIN    = 4;     // part fixe de mise en place, par batch entamé
const MONTAGE_PAR_MAC_MIN = 0.4;   // part variable, par macaron (pochage + assemblage)
// Calcule le temps de montage (minutes) pour une quantité donnée, selon le modèle fixe+variable.
// - perBatch : temps « pour un batch de 60 » issu de la source (mesuré / recette / défaut). On en
//   dérive la part variable par macaron : parMac = max(0, (perBatch − fixe)/TB). Si perBatch n'est pas
//   fourni (défaut), on utilise directement MONTAGE_PAR_MAC_MIN. La part fixe est comptée une fois par
//   batch ENTAMÉ (ceil(qté/TB)), car chaque batch a sa propre mise en place.
// - source : 'défaut' → modèle calibré (4 + 0,4×qté) ; 'mesuré'/'recette' → on respecte leur perBatch
//   en le décomposant sur le même squelette (part fixe + variable dérivée).
function _montageMinutes(qte, perBatch, source){
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const q = Math.max(0, Math.round(+qte||0));
  if(q<=0) return 0;
  const nbBatchs = Math.max(1, Math.ceil(q/TB));
  let parMac;
  if(source==='défaut' || perBatch==null){
    parMac = MONTAGE_PAR_MAC_MIN;
  } else {
    // Mesure ou recette : on dérive la part variable de leur perBatch (mise en place déjà incluse
    // dedans), en retirant la part fixe puis en répartissant sur un batch plein. Jamais négatif.
    parMac = Math.max(0, ((+perBatch||0) - MONTAGE_FIXE_MIN) / TB);
  }
  const fixe = MONTAGE_FIXE_MIN * nbBatchs;
  return Math.round((fixe + parMac*q) * 10) / 10;
}
function getMrpTimes(){
  try{
    const s=JSON.parse(localStorage.getItem(MRP_TIME_KEY)||'{}');
    const out={};
    let repare=false;
    for(const k of Object.keys(MRP_TIME_DEFAULTS)){
      const d=MRP_TIME_DEFAULTS[k], v=s[k]||{};
      let est = v.estimatedTime!=null ? +v.estimatedTime : d.estimatedTime;
      // [AUTO-RÉPARATION] Si une valeur APPRISE est tombée sous le plancher physique (apprentissage
      // faussé par une mesure aberrante), on la ramène au défaut codé. Ne touche pas aux étapes sans
      // plancher (floor=0). Réparation silencieuse et persistée pour ne pas se répéter à chaque appel.
      const floor = MRP_TIME_FLOOR[k]||0;
      if(floor>0 && est<floor){ est = d.estimatedTime; repare=true; }
      out[k]={ estimatedTime: est, totalRealTime: +v.totalRealTime||0, completions: +v.completions||0 };
    }
    if(repare){ try{ localStorage.setItem(MRP_TIME_KEY, JSON.stringify(out)); }catch(e){swallow(e,'getMrpTimes')} }
    return out;
  }catch(e){ return JSON.parse(JSON.stringify(MRP_TIME_DEFAULTS)); }
}
function saveMrpTimes(t){ localStorage.setItem(MRP_TIME_KEY, JSON.stringify(t)); }

// [v1189 — VUE DÉRIVÉE DE LA SOURCE UNIQUE] Stock FINI courant par parfum. Ne recalcule plus rien :
// projette le champ `finis` de parfumDispoSource (le calcul canonique). Ainsi il n'existe qu'UNE seule
// implémentation du décompte des productions ; cette fonction n'en expose qu'une facette (fini seul),
// tandis que stockMobilisableParParfum en expose une autre (mobilisable). Comportement identique à
// l'ancienne version : `stock` indexé par nom de produit, valeur = qté finie vendable. `recipes` fourni
// pour les appelants qui en ont besoin (mrpFindRecipe, etc.).
async function mrpCurrentStockByParfum(){
  let recipes = [];
  try{ recipes = await db.recipes.toArray(); }catch(_){ recipes = []; }
  const stock = {};
  try{
    const src = await parfumDispoSource();
    Object.values(src).forEach(b=>{ if((+b.finis||0)!==0) stock[b.nom] = (stock[b.nom]||0) + (+b.finis||0); });
  }catch(_){ /* base illisible → stock vide, comme l'ancienne version en cas d'erreur */ }
  return {stock, recipes};
}
// Associe un parfum de commande (ex "Caramel") à une recette (ex "Macaron caramel").
function mrpFindRecipe(recipes, parfum){
  const a=aiNormalize(parfum);
  return recipes.find(r=>{ const b=aiNormalize(r.produitNom); return b===a || b.includes(a) || a.includes(b); }) || null;
}

// GÉNÉRATION DU PLAN DE PRODUCTION pour une période [startDate, endDate].
// [UNIFICATION MODÈLE DE TEMPS — source unique] Durées montage/ganache d'une ligne de plan, selon le
// MÊME modèle que le plan de travail détaillé : montage fixe+variable (_montageMinutes), ganache UNE
// fois par parfum. Source : mesuré fiable (tEtape) > recette > défaut. Utilisé par generateProductionOrder
// ET _planFromNeeds pour que le dépli de faisabilité ne contredise plus le plan détaillé.
// [v1190] Per-batch de MONTAGE d'un parfum selon le modèle unifié (mesuré fiable > recette > défaut).
// Isolé pour être partagé par _dureesLignePlan (production) ET le montage du quasi-fini (assemblable),
// afin que les deux temps de montage suivent EXACTEMENT le même modèle. Renvoie {perBatch, src}.
function _montagePerBatchModel(parfum, rec, times, tEtape){
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const k = (typeof aiNormalize==='function') ? aiNormalize(parfum||'') : String(parfum||'').toLowerCase().trim();
  const mesM = tEtape && tEtape.montage && tEtape.montage[k];
  if(mesM && mesM.fiable && mesM.nbMac>0) return { perBatch: mesM.minTotal/mesM.nbMac*TB, src:'mesuré' };
  if(rec && rec.tempsMontageMin!=null && +rec.tempsMontageMin>0) return { perBatch:+rec.tempsMontageMin, src:'recette' };
  return { perBatch: times.montage.estimatedTime, src:'défaut' };
}
// [v1190] Temps de montage SEUL pour un nombre de macarons donné (quasi-fini : ni coques ni ganache).
// Même modèle per-batch que la production, via _montageMinutes (fixe+variable).
function _montageMinutesParfum(parfum, qte, rec, times, tEtape){
  const q = Math.max(0, Math.round(+qte||0)); if(q<=0) return 0;
  const { perBatch, src } = _montagePerBatchModel(parfum, rec, times, tEtape);
  return (typeof _montageMinutes==='function')
    ? _montageMinutes(q, perBatch, src)
    : Math.ceil(q/((typeof TAILLE_BATCH_MACARONS!=='undefined')?TAILLE_BATCH_MACARONS:60))*times.montage.estimatedTime;
}
function _dureesLignePlan(parfum, besoinNet, nbBatchs, rec, times, tEtape){
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const k = (typeof aiNormalize==='function') ? aiNormalize(parfum||'') : String(parfum||'').toLowerCase().trim();
  // Montage : fixe+variable, source mesuré > recette > défaut (via helper partagé avec le quasi-fini).
  const { perBatch, src } = _montagePerBatchModel(parfum, rec, times, tEtape);
  const tMontage = (typeof _montageMinutes==='function')
    ? _montageMinutes(besoinNet, perBatch, src)
    : nbBatchs*times.montage.estimatedTime;
  // Ganache : UNE fois par parfum (pas × nbBatchs). Mesuré > recette > défaut.
  let tGanache;
  const mesG = tEtape && tEtape.ganache && tEtape.ganache[k];
  if(mesG && mesG.fiable && mesG.nbMac>0){ tGanache = Math.round(mesG.minTotal/(mesG.nbSessions||1)); }
  else if(rec && rec.tempsGanacheMin!=null && +rec.tempsGanacheMin>0){ tGanache = +rec.tempsGanacheMin; }
  else { tGanache = times.ganache.estimatedTime; }
  return { tMontage, tGanache };
}
// [REPORT MANUEL — étape 2] Durée de montage d'un parfum pour un besoin net donné, en réutilisant
// EXACTEMENT le modèle de _dureesLignePlan (mesuré > recette > défaut + _montageMinutes). Sert à
// calculer le montage FUSIONNÉ (besoin natif + besoin reporté en UN seul appel → un seul temps fixe)
// et le montage d'un report injecté. Autonome : charge recettes + temps mesurés.
async function _montageDureeParfum(parfum, besoinNet){
  const q = Math.max(0, Math.round(+besoinNet||0));
  if(q<=0) return 0;
  const TB = (typeof TAILLE_BATCH_MACARONS!=='undefined') ? TAILLE_BATCH_MACARONS : 60;
  const times = (typeof getMrpTimes==='function') ? getMrpTimes() : {montage:{estimatedTime:15}};
  let recipes = []; try{ recipes = await db.recipes.toArray(); }catch(_){ recipes = []; }
  const rec = (typeof mrpFindRecipe==='function') ? mrpFindRecipe(recipes, parfum) : null;
  let tEtape = null; try{ tEtape = await prodTempsParEtapeParParfum(90); }catch(_){ tEtape = null; }
  const k = (typeof aiNormalize==='function') ? aiNormalize(parfum||'') : String(parfum||'').toLowerCase().trim();
  let perBatch, src;
  const mesM = tEtape && tEtape.montage && tEtape.montage[k];
  if(mesM && mesM.fiable && mesM.nbMac>0){ perBatch = mesM.minTotal/mesM.nbMac*TB; src='mesuré'; }
  else if(rec && rec.tempsMontageMin!=null && +rec.tempsMontageMin>0){ perBatch = +rec.tempsMontageMin; src='recette'; }
  else { perBatch = times.montage.estimatedTime; src='défaut'; }
  return (typeof _montageMinutes==='function') ? _montageMinutes(q, perBatch, src)
       : Math.ceil(q/TB)*times.montage.estimatedTime;
}
// [STOCK RÉELLEMENT DISPONIBLE — réservations] Renvoie, par parfum, le nombre de macarons déjà PROMIS à
// des commandes livrables APRÈS endDate mais dans l'horizon de concurrence (endDate + N jours). Ces macarons
// puisent dans le stock physique sans appartenir au besoin de la fenêtre [startDate,endDate] : il faut donc
// les retirer du stock avant de conclure « déjà couvert ». NEUTRE quand il n'y a aucune commande proche
// (réservé=0 → stock inchangé). Règle métier (Benjamin) : horizon de concurrence = 7 jours (au-delà, le
// stock a le temps d'être reconstitué, la commande ne réserve plus).
// [DÉPRÉCIÉ v917] Plus appelée : le modèle POOL/FIFO (§4) a remplacé la réservation. Conservée
// temporairement pour référence ; à supprimer une fois le pool validé sur appareil réel.
async function generateProductionOrder(startDate, endDate, tempsDisponibleMinutes, besoinAdditionnel, opts){
  // [MODÈLE POOL — §4] Le besoin de production = (somme des demandes sur l'HORIZON) − stock physique BRUT.
  // Plus de "réservation" de stock pour une commande future (mauvaise abstraction : cadenas inexistants).
  // Le stock va naturellement à la commande la plus proche (FIFO) au moment de SERVIR ; ce calcul-ci ne
  // s'occupe que du VOLUME à produire. opts.poolHorizonJours élargit la fenêtre de demande au-delà de
  // endDate (anticipation rendue licite par la congélation des macarons assemblés) sans changer le stock.
  opts = opts || {};
  const _poolH = (+opts.poolHorizonJours>0) ? (+opts.poolHorizonJours) : 0;
  let _endPool = endDate;
  if(_poolH>0){
    try{ const dP=new Date(endDate+'T00:00:00'); dP.setDate(dP.getDate()+_poolH); _endPool=ymdLocal(dP); }
    catch(_){ _endPool=endDate; }
  }
  // requête ciblée sur l'index date (bornée) plutôt qu'un scan global
  // Requête bornée sur l'index date ; repli sur un filtre mémoire si l'index
  // n'est pas (encore) disponible dans la base locale (ancienne version non migrée).
  let orders;
  try{
    orders = await db.orders.where('date').between(startDate, _endPool, true, true).toArray();
  }catch(e){
    const all = await db.orders.toArray();
    orders = all.filter(o=> o.date && o.date>=startDate && o.date<=_endPool);
  }
  const {stock, recipes} = await mrpCurrentStockByParfum();
  // [v1190 — QUASI-FINI] En plus du stock FINI (stock[parfum]), on charge la disponibilité ENRICHIE
  // (source unique) pour connaître l'ASSEMBLABLE par parfum (coques + ganache déjà prêtes, reste à
  // MONTER). On mobilise cet assemblable pour couvrir le besoin — MAIS on le garde STRICTEMENT distinct
  // du fini : un « quasi-fini » n'est pas un fini, il demande encore le montage et doit être signalé.
  let _dispoSrc = {};
  try{ _dispoSrc = await parfumDispoSource(); }catch(_){ _dispoSrc = {}; }
  const _assemblableDe = parfum => {
    const k = (typeof stockMoveKey==='function') ? stockMoveKey(parfum) : (typeof aiNormalize==='function'?aiNormalize(parfum):String(parfum||'').toLowerCase().trim());
    const b = _dispoSrc[k]; return b ? Math.max(0, +b.assemblable||0) : 0;
  };
  const times = getMrpTimes();
  // [UNIFICATION MODÈLE DE TEMPS] Temps mesurés par parfum (mesuré fiable > recette > défaut), pour
  // que tMontage/tGanache des lignes suivent le MÊME modèle que le plan de travail détaillé
  // (fixe+variable pour le montage, une ganache PAR PARFUM). Évite la contradiction avec le dépli.
  let _tEtape = null; try{ _tEtape = await prodTempsParEtapeParParfum(90); }catch(_){ _tEtape = null; }
  const _normP = nom => (typeof aiNormalize==='function') ? aiNormalize(nom||'') : String(nom||'').toLowerCase().trim();
  // 1) Besoin brut agrégé par parfum
  const brut={};
  orders.forEach(o=>{ if(normStatus(o.statut)==='Livrée') return; const dem=_orderParfumDemand(o);
    for(const nom in dem) brut[nom]=(brut[nom]||0)+dem[nom]; });
  // [SIMULATION] Besoin additionnel fictif (ex. « si je rajoute 25 macarons café jeudi »), injecté
  // SANS toucher la base : on l'ajoute au besoin brut comme une commande de plus. Absent = identique.
  if(besoinAdditionnel && typeof besoinAdditionnel==='object'){
    for(const nom in besoinAdditionnel){ const q=+besoinAdditionnel[nom]||0; if(q>0) brut[nom]=(brut[nom]||0)+q; }
  }

  // [v1435] MARCHÉS PROGRAMMÉS — même point de vérité que l'ordonnanceur et le plan de production.
  // La quantité prévue à emporter est un besoin de production au même titre qu'une commande.
  // Cette version-ci ignorait les parfums visés (v1431) : trois écrans, trois résultats possibles
  // pour la même question. Un seul appel désormais.
  let _mrpMarketTotal = 0;
  try{
    const _allMk = await db.markets.toArray().catch(()=>[]);
    let _rep = []; try{ const _mf = await marketForecast(); _rep = (_mf && _mf.repartition) ? _mf.repartition : []; }catch(e){ _rep=[]; }
    // La fenêtre de cet écran est un intervalle de DATES, pas un horizon en jours : on convertit
    // en bornes de jours pour réutiliser la fonction commune sans la dénaturer.
    const _jDe = d => { try{ const a=new Date(d+'T00:00:00'), b=new Date(startDate+'T00:00:00');
                              return Math.round((a-b)/86400000); }catch(_){ return null; } };
    const _H = _jDe(_endPool);
    const besoinMk = besoinMarchesParParfum(_allMk, _rep, brut, {horizonJours:_H!=null?_H:14, daysTo:_jDe});
    for(const nom in besoinMk){ brut[nom] = (brut[nom]||0) + besoinMk[nom]; _mrpMarketTotal += besoinMk[nom]; }
  }catch(e){ console.error('mrp marchés', e); }
  // 2) Pour chaque parfum : besoin net, nb de batchs (60), garniture, temps ganache+montage (par batch)
  const lignes=[]; const warnings=[];
  for(const parfum in brut){
    const besoinBrut=brut[parfum];
    const enStockPhys=stock[parfum]||0;                         // FINI (macarons prêts)
    // [v1190 — QUASI-FINI] On couvre le besoin d'abord par le FINI, puis par l'ASSEMBLABLE (coques+ganache
    // prêtes → il ne reste QUE le montage), puis par une production complète pour le reste.
    //   couvertFini        : servi par des macarons finis (0 travail)
    //   couvertAssemblable : servi par du quasi-fini (montage SEUL, ni coques ni ganache à refaire)
    //   besoinNet          : à produire de zéro (coques + ganache + montage)
    const assemblableDispo = _assemblableDe(parfum);
    const couvertFini = Math.min(besoinBrut, enStockPhys);
    const resteApresFini = Math.max(0, besoinBrut - couvertFini);
    const couvertAssemblable = Math.min(resteApresFini, assemblableDispo);
    const besoinNet = Math.max(0, resteApresFini - couvertAssemblable);
    // [POOL] enStock reste la couverture SANS production (fini + assemblable), pour la traçabilité.
    const enStock = couvertFini + couvertAssemblable;
    const reserve=0;
    // Une ligne existe si on doit PRODUIRE (besoinNet>0) OU s'il reste juste à MONTER (couvertAssemblable>0).
    if(besoinNet<=0 && couvertAssemblable<=0) continue;
    const nbBatchs=Math.ceil(besoinNet/TAILLE_BATCH_MACARONS);   // batchs = production de zéro uniquement
    const rec=mrpFindRecipe(recipes, parfum);
    if(!rec) warnings.push(parfum);
    const poidsUnit = rec && rec.poidsGarnitureUnit!=null ? +rec.poidsGarnitureUnit : 0;
    const garnitureG = Math.round(nbBatchs*TAILLE_BATCH_MACARONS*poidsUnit);
    // [UNIFICATION] Durées de PRODUCTION via le helper commun (sur besoinNet : ce qu'on fait de zéro).
    const { tMontage: tMontageProd, tGanache: tGanacheProd } = _dureesLignePlan(parfum, besoinNet, nbBatchs, rec, times, _tEtape);
    // [v1190] La GANACHE n'est comptée QUE s'il y a une production de zéro (besoinNet>0). Pour un parfum
    // 100% quasi-fini, la ganache est déjà en stock → 0 temps de ganache (sinon on la compterait deux fois).
    const tGanache = besoinNet>0 ? tGanacheProd : 0;
    // [v1190] Montage SUPPLÉMENTAIRE pour le quasi-fini : il faut monter couvertAssemblable macarons,
    // mais SANS coques ni ganache (déjà en stock). Même modèle per-batch que la production.
    let tMontageAssemblable = 0;
    if(couvertAssemblable>0){
      try{
        if(typeof _montageMinutesParfum==='function'){
          tMontageAssemblable = _montageMinutesParfum(parfum, couvertAssemblable, rec, times, _tEtape);
        } else {
          const perBatch = (rec && +rec.tempsMontageMin>0) ? +rec.tempsMontageMin : times.montage.estimatedTime;
          tMontageAssemblable = (typeof _montageMinutes==='function')
            ? _montageMinutes(couvertAssemblable, perBatch, 'défaut')
            : Math.ceil(couvertAssemblable/TAILLE_BATCH_MACARONS)*times.montage.estimatedTime;
        }
      }catch(_){ tMontageAssemblable = 0; }
    }
    const tMontage = tMontageProd + tMontageAssemblable;   // total montage = production + quasi-fini
    // Délai de repos ganache avant montage (réglage recette, défaut 12 h ; 0 = exception)
    const ganacheDelaiH = (rec && rec.ganacheDelaiH!=null) ? +rec.ganacheDelaiH : 12;
    const coquesCongelObl = !!(rec && rec.coquesCongelObligatoire);
    lignes.push({parfum, recipeId:rec?rec.id:null, besoinBrut, enStock, enStockPhys, reserve, besoinNet, nbBatchs,
      // [v1190] quantités DISTINCTES pour l'affichage : ne jamais confondre fini et quasi-fini.
      couvertFini, couvertAssemblable, aMonter: couvertAssemblable,
      tMontageProd, tMontageAssemblable,
      coques:nbBatchs*COQUES_PAR_BATCH, garnitureG, poidsUnit, tMontage, tGanache,
      ganacheDelaiH, coquesCongelObl,
      garnitureManque: !rec || poidsUnit<=0});
  }
  lignes.sort((a,b)=>(b.besoinNet+b.couvertAssemblable)-(a.besoinNet+a.couvertAssemblable));

  // [v1190 — DIAG QUASI-FINI] Transparence : par parfum, ventile la couverture du besoin en
  // fini (prêt) / quasi-fini (à monter) / à produire (de zéro). Preuve visible qu'on mobilise
  // bien l'assemblable SANS le confondre avec du fini. À désactiver une fois validé sur iPhone.
  try{
    if(typeof diagPublish==='function' && lignes.some(l=>l.couvertAssemblable>0)){
      const detail = lignes.filter(l=>l.couvertFini>0||l.couvertAssemblable>0||l.besoinNet>0).map(l=>
        `${l.parfum} : demandé ${l.besoinBrut} → 📦 ${l.couvertFini} fini · 🔧 ${l.couvertAssemblable} à monter (quasi-fini) · 🏭 ${l.besoinNet} à produire`
        + (l.tMontageAssemblable>0?` [+${l.tMontageAssemblable} min montage quasi-fini]`:''));
      diagPublish('quasiFiniPlan', '🔧 Plan — quasi-fini mobilisé (à monter, distinct du fini)', {
        'Fenêtre': startDate+' → '+endDate,
        'Règle': 'Besoin couvert d\'abord par le FINI (prêt), puis par le QUASI-FINI (coques+ganache prêtes → montage seul), puis production de zéro.',
        'Par parfum': detail.length ? detail : 'aucun quasi-fini mobilisé',
        'Rappel': 'Un quasi-fini n\'est JAMAIS compté comme fini : il reste le temps de montage, signalé séparément.'
      });
    }
  }catch(e){swallow(e,'generateProductionOrder')}

  // 3) REMPLISSAGE DES MERINGUES (capacité 120 macarons) — mutualisation seulement
  //    pour combler une meringue, jamais imposée. Un parfum ≥120 prend des meringues pleines.
  const meringues = _packMeringues(lignes);
  const nbBatchsTotal = lignes.reduce((s,l)=>s+l.nbBatchs,0);
  const tMeringue = meringues.length*times.coques.estimatedTime;   // par meringue
  const tGanacheTot = lignes.reduce((s,l)=>s+l.tGanache,0);
  const tMontageTot = lignes.reduce((s,l)=>s+l.tMontage,0);
  const tempsTotal = tMeringue + tGanacheTot + tMontageTot;

  const dispo = +tempsDisponibleMinutes||0;

  // [DIAG POOL + ÉCLATEMENT FIFO — transparence §4] Publie, quand le pool est élargi, le raisonnement :
  // demandes datées versées au pool, stock physique brut, besoin net (= pool − stock), puis l'éclatement
  // FIFO (le stock le plus ancien va à la commande la plus PROCHE ; le frais produit couvre les suivantes).
  // Lecture seule : n'altère ni le calcul ni la base. Vit dans la rubrique technique.
  try{
    if(_poolH>0 && typeof diagPublish==='function'){
      // Demandes datées par parfum sur le pool (commandes seules ; marchés/simu déjà fondus dans brut).
      const _demDatee = {};   // parfum -> [{date, qte}]
      orders.forEach(o=>{ if(!o||!o.date||normStatus(o.statut)==='Livrée') return;
        const dem=_orderParfumDemand(o);
        for(const nom in dem){ (_demDatee[nom]=_demDatee[nom]||[]).push({date:o.date, qte:dem[nom]}); }
      });
      const _fifoLignes = [];
      Object.keys(brut).sort().forEach(parfum=>{
        const pool = brut[parfum];
        const phys = +stock[parfum]||0;
        const net = Math.max(0, pool - phys);
        // Éclatement FIFO : on sert les commandes par date croissante, stock d'abord puis frais produit.
        const cmds = (_demDatee[parfum]||[]).slice().sort((a,b)=> a.date<b.date?-1:a.date>b.date?1:0);
        let stockRest = phys, fraisRest = net;
        const trace = cmds.map(c=>{
          let q=c.qte, duStock=Math.min(stockRest,q); stockRest-=duStock; q-=duStock;
          let duFrais=Math.min(fraisRest,q); fraisRest-=duFrais;
          const parts=[]; if(duStock>0) parts.push(duStock+' stock'); if(duFrais>0) parts.push(duFrais+' frais');
          return c.date+' : '+c.qte+' ('+(parts.join(' + ')||'0')+')';
        });
        const marche = pool - cmds.reduce((t,c)=>t+c.qte,0);   // part marché/simu non datée par commande
        _fifoLignes.push(
          `${parfum} : pool ${pool}${marche>0?' (dont '+marche+' marché/simu)':''} − stock ${phys} = à produire ${net}`
          + (trace.length ? '  ·  FIFO → '+trace.join(' | ') : '')
        );
      });
      diagPublish('pool', '🫗 Pool de production & éclatement FIFO', {
        'Fenêtre stricte (faisabilité)': startDate+' → '+endDate,
        'Pool élargi (quoi produire)': startDate+' → '+_endPool+' (+'+_poolH+' j ; anticipation congelable)',
        'Modèle': 'besoin = demandes du pool − stock physique BRUT (aucune réservation). Le stock va à la commande la plus PROCHE en FIFO ; le frais couvre les suivantes.',
        'Par parfum': _fifoLignes.length ? _fifoLignes : 'Aucun besoin sur le pool',
        'Total à produire (net)': lignes.reduce((t,l)=>t+(+l.besoinNet||0),0)
      });
    }
  }catch(e){ console.error('diag pool', e); }

  return {lignes, meringues, nbMeringues:meringues.length, nbBatchsTotal,
    tMeringue, tGanacheTot, tMontageTot, tempsTotal, tempsDisponible:dispo,
    depassement: dispo>0 && tempsTotal>dispo,
    chargePct: dispo>0 ? Math.round(tempsTotal/dispo*100) : 0,
    warnings, nbParfums:lignes.length,
    marketTotal: round3(_mrpMarketTotal),   // demande marché intégrée au plan (info affichage)
    poolHorizonJours:_poolH, poolDebut:startDate, poolFin:_endPool, fenetreFin:endDate};   // périmètre du pool (transparence/diag)
}

// [CONNEXION A] Vérifie si le stock de MATIÈRES PREMIÈRES suffit à exécuter le plan de production.
// Pour chaque ligne (recette × nbBatchs), somme les besoins matières (qteParBatch × nbBatchs),
// puis compare au stock disponible (somme des qteRestante des lots). Retourne la liste des manques.
// Affichage en grammes pour les denrées au kg (cohérent avec le reste de l'app).
async function mrpCheckMatieres(plan){
  if(!plan || !Array.isArray(plan.lignes) || !plan.lignes.length) return {manques:[], ok:true, details:[]};
  const [mats, lots, allItems] = await Promise.all([
    db.materials.toArray(),
    db.materialLots.toArray(),
    db.recipeItems.toArray()
  ]);
  const matById = id => mats.find(m=>m.id===id) || null;
  const dispOf = mat => { const u=(mat&&mat.unite||'').toLowerCase();
    return (mat && mat.categorie!=='emballage' && u==='kg') ? {u:'g', f:1000} : {u:(mat&&mat.unite)||'', f:1}; };
  // Stock par matière (unité de stockage).
  const stockBy = {};
  lots.forEach(l=>{ stockBy[l.materialId]=(stockBy[l.materialId]||0)+(+l.qteRestante||0); });
  // Besoin cumulé par matière sur tout le plan (unité de stockage).
  const besoinBy = {};
  plan.lignes.forEach(l=>{
    if(!l.recipeId || !(l.nbBatchs>0)) return;
    const items = allItems.filter(it=>it.recipeId===l.recipeId);
    items.forEach(it=>{
      const q = (+it.qteParBatch||0) * l.nbBatchs;   // qteParBatch est en unité de stockage (kg ou unité)
      if(q>0) besoinBy[it.materialId] = round3((besoinBy[it.materialId]||0) + q);
    });
  });
  // Comparaison.
  const manques = [], details = [];
  Object.keys(besoinBy).forEach(idStr=>{
    const id = +idStr;
    const mat = matById(id); if(!mat) return;
    const besoin = round3(besoinBy[id]);
    const stock = round3(stockBy[id]||0);
    const d = dispOf(mat);
    const ligne = {
      materialId:id, nom:mat.nom||'(matière ?)',
      besoinAff: round3(besoin*d.f), stockAff: round3(stock*d.f), unite:d.u,
      manqueAff: round3(Math.max(0, besoin-stock)*d.f),
      manqueStock: round3(Math.max(0, besoin-stock))   // pour la liste de courses éventuelle
    };
    details.push(ligne);
    if(besoin - stock > 1e-6) manques.push(ligne);
  });
  details.sort((a,b)=> b.manqueAff - a.manqueAff || a.nom.localeCompare(b.nom));
  manques.sort((a,b)=> b.manqueAff - a.manqueAff);
  return {manques, ok: manques.length===0, details};
}

// [CONNEXION C] Génère une liste de courses à partir des MANQUES MATIÈRES du plan de production.
// Réutilise la modale de liste de courses existante (openShoppingListModal), mais les quantités
// « à prévoir » sont celles nécessaires au plan (et non le simple seuil de réassort).
async function mrpShoppingFromPlan(){
  const check = _mrpMatCheck;
  if(!check || !Array.isArray(check.manques) || !check.manques.length){
    toast('Aucun manque matière à acheter pour ce plan'); return;
  }
  const [mats, lots, suppliers] = await Promise.all([
    db.materials.toArray(), db.materialLots.toArray(), db.suppliers.toArray()
  ]);
  const supName = id => (suppliers.find(s=>s.id===id)||{}).nom || '—';
  const matById = id => mats.find(m=>m.id===id) || null;
  // Meilleur fournisseur (même logique que genShoppingList).
  function bestSupplier(materialId){
    const perSup = new Map();
    for(const l of lots){
      if(l.materialId!==materialId || !l.supplierId) continue;
      const cur = perSup.get(l.supplierId);
      const newer = !cur || (l.dateReception||'') > (cur.dateReception||'')
        || ((l.dateReception||'')===(cur.dateReception||'') && (l.id||0)>(cur.id||0));
      if(newer) perSup.set(l.supplierId, l);
    }
    const offres=[];
    for(const [sid,lot] of perSup){ const pu=lotPU(lot); if(pu>0) offres.push({sid,pu,date:lot.dateReception||''}); }
    if(!offres.length) return null;
    offres.sort((a,b)=>a.pu-b.pu);
    return { nom:supName(offres[0].sid), pu:offres[0].pu, date:offres[0].date,
             nbAutres:offres.length-1, ecart: offres.length>1 ? money2(offres[offres.length-1].pu-offres[0].pu) : 0 };
  }
  // Construire les lignes à partir des manques du plan. manqueAff/stockAff sont en unité d'affichage (g pour kg).
  const lignes = check.manques.map(m=>{
    const mat = matById(m.materialId) || {};
    return {
      nom: m.nom, unite: m.unite, cat: mat.categorie||'denree',
      stock: m.stockAff, seuil: m.besoinAff,        // « seuil » = besoin du plan (réutilise l'affichage existant)
      manque: m.manqueAff, low: true,               // tout manque du plan est « à commander »
      best: bestSupplier(m.materialId),
      _planContext: true
    };
  });
  openShoppingListModal(lignes, lignes.length);
}

// Rendu d'un encart « stock matières pour ce plan » à insérer dans le résultat MRP.

/* ============================================================
   ORDONNANCEMENT PERSONNEL « CHEF D'ATELIER »
   ------------------------------------------------------------
   À partir de créneaux de disponibilité saisis librement (jour par jour,
   plusieurs plages possibles) + une liste de tâches souhaitées, on construit
   un planning minute par minute qui respecte la SÉQUENCE TECHNIQUE du macaron
   et exploite les temps PASSIFS (croûtage, cuisson, maturation) pour caser
   d'autres tâches actives en parallèle. Chaque décision est argumentée.
   ============================================================ */
// Constantes process (minutes). Passif = ne consomme pas de main d'œuvre (on peut faire autre chose).
const PROC = {
  maturationH: 24,     // maturation au frais avant vente (passif)
  cremeuxCongelH: 6,   // congélation du crémeux avant montage (passif, règle générale)
  decongelFrigoH: 2,   // grand format congelé : passage au frigo avant service (passif)
  relancePlaqueMin: 6, // décalage minimum entre 2 enfournements (plaque 2 entre 6 min après plaque 1)
  coquesTrouMaxH: 9,   // coques VIDES : 6h de fraîcheur + 3h de tolérance avant garnissage ; au-delà = congélation
  coquesHeureMinMatin: 7 // démarrer les coques avant 7h du matin = absurde → congélation
};
// Formats de cuisson : coques/plaque + durée de cuisson d'une plaque + capacité meringue.
const CUISSON = {
  standard: { coquesParPlaque:39, cuissonMin:20, coquesParMeringue:240, macaronsParMeringue:120 },
  grand:    { coquesParPlaque:12, cuissonMin:28, coquesParMeringue:48,  macaronsParMeringue:24  }
};
// Temps FOUR total (makespan) pour cuire `nbCoques` d'un format donné, en cascade :
// P1 à t=0, P2 à t=+6, puis P3 quand P1 sort, P4 6 min après, etc. (four ~2 plaques).
// Renvoie {nbPlaques, makespanMin, four:[{plaque,entree,sortie}]}.
function cuissonCascade(nbCoques, format){
  const C = CUISSON[format] || CUISSON.standard;
  const nbPlaques = Math.ceil(Math.max(0,nbCoques)/C.coquesParPlaque);
  const B = C.cuissonMin, R = PROC.relancePlaqueMin;
  const four=[]; 
  // Les plaques entrent par paires : la paire k démarre à t = k*B (k=0,1,2…),
  // 1ère plaque de la paire à k*B, 2ème à k*B + R. Capacité simultanée = 2.
  for(let i=0;i<nbPlaques;i++){
    const pair=Math.floor(i/2), within=i%2;
    const entree = pair*B + (within===1?R:0);
    four.push({plaque:i+1, entree, sortie:entree+B});
  }
  const makespan = four.length ? Math.max(...four.map(p=>p.sortie)) : 0;
  return {nbPlaques, makespanMin:makespan, four, cuissonMin:B, coquesParPlaque:C.coquesParPlaque};
}

// Convertit une saisie de dispo en blocs datés exploitables.
// daySpecs : [{date:'AAAA-MM-JJ', slots:[[startMin,endMin],...]}] déjà en minutes.
function _flattenAvailability(daySpecs){
  const blocks=[];
  daySpecs.forEach(d=>{
    (d.slots||[]).forEach(([s,e])=>{ if(e>s) blocks.push({date:d.date, start:s, end:e, used:0}); });
  });
  // tri chronologique (date puis heure)
  blocks.sort((a,b)=> a.date.localeCompare(b.date) || a.start-b.start);
  return blocks;
}
function _totalAvail(blocks){ return blocks.reduce((s,b)=>s+(b.end-b.start),0); }

// Ordonnance une liste de tâches actives (avec dépendances souples) dans les blocs.
// tasks: [{id,label,type,active,after,passiveAfter}] ; renvoie le planning + diagnostic.
// Heuristique : on respecte l'ordre des phases (meringue → ganache → montage),
// on place chaque tâche active dans le premier créneau qui la contient, et on
// déclenche les temps passifs (cuisson/maturation) en tâche de fond.
function schedulePersonalPlan(daySpecs, plan, opts){
  opts=opts||{};
  // [SIMULATION] parfums dont le montage est reporté (voir garde plus bas). Accepte Set ou tableau.
  const skipMontage = (opts.skipMontage instanceof Set) ? opts.skipMontage
                    : new Set(Array.isArray(opts.skipMontage) ? opts.skipMontage : []);
  // [REPORT MANUEL — étape 2] Montages venus d'une autre semaine à injecter en phase 3 (voir plus bas).
  const injectMontages = Array.isArray(opts.injectMontages) ? opts.injectMontages : [];
  const blocks=_flattenAvailability(daySpecs);
  const times=getMrpTimes();
  const events=[];           // {date,start,end,label,kind,passive}
  const unplaced=[];         // tâches qui ne rentrent dans aucun créneau : {id,type,parfum,label,dur,after}
  const warnings=[], insights=[];
  if(!blocks.length) return {events, warnings:['Aucun créneau de disponibilité renseigné.'], insights, blocks, ok:false, totalActive:0, totalAvail:0};

  // 1) Construire la liste ORDONNÉE des tâches actives selon la séquence technique.
  //    Phase 1 : meringues (remplies à la capacité utile). Phase 2 : ganaches. Phase 3 : montages.
  //    On entrelace : les ganaches se font pendant la cuisson des coques (temps passif).
  const meringues = plan.meringues||[];
  const lignes = plan.lignes||[];
  const tMer = Math.round((plan.tMeringue||0)/Math.max(1,plan.nbMeringues||1));

  // file de tâches actives, dans un ordre logique de production
  const active=[];
  meringues.forEach((mg,i)=>{
    const rep = mg.repartition ? Object.entries(mg.repartition).map(([p,q])=>`${p} ${q}`).join(' + ') : mg.parfums.join(' + ');
    const remplissage = mg.partielle ? ` (meringue partielle : ${mg.macarons||''}/${MACARONS_PAR_MERINGUE})` : '';
    const cuis = cuissonCascade((mg.macarons||0)*2, 'standard');
    active.push({
      id:'meringue:'+i, phase:1, label:`Meringue ${i+1} — ${rep}`,
      repartition: mg.repartition || null,
      dur:tMer, type:'coques', passiveAfter:cuis.makespanMin,
      note:`Coulage + dressage de ${(mg.macarons||0)*2} coques${remplissage}. Cuisson : ${cuis.nbPlaques} plaque(s) en cascade (~${cuis.makespanMin} min four). Pendant la cuisson, on enchaîne une ganache pour ne pas perdre de temps.`
    });
  });
  lignes.forEach(l=> {
    // [REPORT MANUEL — voie 1] Un parfum reporté part en S+1 avec sa GANACHE ET son montage : en
    // semaine SOURCE on ne garde QUE ses coques (congelées). On ne génère donc pas non plus sa ganache
    // ici (elle serait périmée avant le montage de S+1 : DLC ganache ≤ 6 j). La ganache sera refaite
    // fraîche en S+1. skipMontage = parfums reportés hors de cette semaine.
    if(skipMontage.has(l.parfum)) return;
    // [v1190] Pas de tâche ganache pour un parfum 100% quasi-fini (ganache déjà en stock) : elle serait
    // de durée 0 et créerait une dépendance vers une ganache qui n'existe pas à produire.
    if((+l.besoinNet||0)<=0) return;
    active.push({
    id:'ganache:'+l.parfum, phase:2, label:`Ganache ${l.parfum}`,
    dur:l.tGanache, type:'ganache',
    passiveAfter: (l.ganacheDelaiH>0 ? Math.round(l.ganacheDelaiH*60) : 0),
    note:`${l.garnitureManque?'⚠ poids garniture à renseigner. ':''}${l.garnitureG||'?'} g pour ${l.nbBatchs} batch(s). À préparer pendant la cuisson des coques pour ne pas perdre de temps machine.${l.ganacheDelaiH>0?` ⏱ Repos ${l.ganacheDelaiH} h avant montage.`:' (montage possible sans délai pour cette recette.)'}`
    });
  });
  lignes.forEach(l=> {
    // [REPORT MANUEL — voie 1] Même garde pour le montage : le parfum reporté ne se monte pas cette
    // semaine (il part en S+1 avec sa ganache fraîche). Seules ses coques sont produites ici, congelées.
    if(skipMontage.has(l.parfum)) return;
    // [v1190] Quantité totale à monter = production de zéro (besoinNet) + quasi-fini (couvertAssemblable).
    const _qMonter = (+l.besoinNet||0) + (+l.couvertAssemblable||0);
    if(_qMonter<=0) return;
    // Le montage attend la ganache fraîche UNIQUEMENT s'il y a une production de zéro (sinon la ganache
    // est déjà en stock : aucune dépendance, aucun repos à attendre pour la part quasi-fini).
    const _aProduire = (+l.besoinNet||0)>0;
    const _qfNote = (+l.couvertAssemblable||0)>0
      ? ` Dont ${l.couvertAssemblable} quasi-fini(s) (coques + ganache déjà en stock, montage seul).`
      : '';
    active.push({
    id:'montage:'+l.parfum, phase:3, label:`Montage ${l.parfum}`,
    dur:l.tMontage, type:'montage',
    besoinNet: _qMonter,
    couvertAssemblable: (+l.couvertAssemblable||0),
    after: (_aProduire && l.ganacheDelaiH>0 ? 'ganache:'+l.parfum : null),
    ganacheDelaiMin: (_aProduire && l.ganacheDelaiH>0 ? Math.round(l.ganacheDelaiH*60) : 0),
    coquesCongelObl: !!l.coquesCongelObl,
    note:`Garnissage de ${_qMonter} macarons.${_qfNote} Nécessite coques cuites + ganache prête${(_aProduire && l.ganacheDelaiH>0)?` (reposée ${l.ganacheDelaiH} h)`:''}.${l.coquesCongelObl?' ❄️ Coques congelées obligatoires pour cette recette.':''} Lance la maturation de ${PROC.maturationH} h juste après.`
    });
  });
  // [REPORT MANUEL — voie 1] Reports INJECTÉS : parfums reportés depuis une semaine SOURCE. En voie 1,
  // seules leurs COQUES ont été produites en source (congelées) ; leur GANACHE est refaite FRAÎCHE ici,
  // avec son repos normal, puis le montage. On injecte donc DEUX tâches par report (ganache phase 2 +
  // montage phase 3, lié à la ganache par `after`), exactement comme un parfum natif — la seule
  // différence est que les coques sont congelées (badge ❄️, note de décongélation).
  injectMontages.forEach(im=>{
    if(!im || !(+im.dur>0)) return;
    const delaiMin = (im.ganacheDelaiH>0) ? Math.round(im.ganacheDelaiH*60) : 0;
    const ganId = 'ganache:'+im.parfum+'@report';
    // Ganache fraîche (si la recette en a une : tGanache>0).
    if(+im.tGanache>0){
      active.push({
        id:ganId, phase:2, label:`Ganache ${im.parfum} (reporté)`,
        dur:+im.tGanache, type:'ganache',
        passiveAfter: delaiMin,
        _reporte:true, _fromWk: im.fromWk||null,
        note:`↩ Reporté depuis ${im.fromWk||'la semaine précédente'} : ganache FRAÎCHE pour ${im.besoinNet||'?'} macarons (les coques, elles, ont été cuites en semaine source et congelées).${im.ganacheDelaiH>0?` ⏱ Repos ${im.ganacheDelaiH} h avant montage.`:''}`
      });
    }
    // Montage (lié à la ganache fraîche par son repos, comme un montage natif).
    active.push({
      id:'montage:'+im.parfum+'@report', phase:3, label:`Montage ${im.parfum} (reporté)`,
      dur:+im.dur, type:'montage',
      after: (+im.tGanache>0 ? ganId : null),
      ganacheDelaiMin: delaiMin,
      coquesCongelObl:true, congeler:true,        // coques produites en source → forcément congelées
      _reporte:true, _fromWk: im.fromWk||null,
      note:`↩ Montage reporté depuis ${im.fromWk||'la semaine précédente'} : garnissage de ${im.besoinNet||'?'} macarons. ❄️ Coques congelées (cuites en semaine source), à décongeler au frigo avant garnissage. Ganache refaite fraîche ci-dessus${im.ganacheDelaiH>0?` (reposée ${im.ganacheDelaiH} h)`:''}. Lance la maturation de ${PROC.maturationH} h juste après.`
    });
  });

  // 2) Placement glouton dans les blocs, en respectant l'ordre des phases.
  //    On garde un curseur par bloc ; une tâche ne peut pas être coupée (atomique)
  //    sauf le montage qu'on autorise à se fractionner par batch si besoin.
  //
  //    CALAGE HORAIRE RÉEL (v854) : pour faire respecter le repos ganache 12 h et la
  //    fraîcheur des coques, on raisonne en MINUTES ABSOLUES (à travers les jours), pas
  //    seulement en offset dans un bloc. _absMin(date, offset) donne un instant comparable
  //    d'un jour à l'autre. placedEnd[id] mémorise la fin absolue de chaque tâche posée,
  //    pour que le montage puisse exiger « début ≥ fin ganache + délai ».
  const _dayIndex = ds => { const [y,m,d]=String(ds).split('-').map(Number); return Math.floor(Date.UTC(y,(m||1)-1,d||1)/86400000); };
  const _absMin = (ds, off) => _dayIndex(ds)*1440 + off;
  const placedEnd = {};   // task.id -> minutes absolues de fin de la tâche placée
  let bi=0;
  // place(task, notBefore) : notBefore = instant absolu (minutes) minimal de DÉBUT, ou null.
  // Le début effectif est calé sur max(curseur du bloc, notBefore converti dans ce jour).
  function place(task, notBefore){
    notBefore = (notBefore==null) ? -Infinity : notBefore;
    for(let k=bi;k<blocks.length;k++){
      const b=blocks[k];
      let startOff = b.start + b.used;                 // curseur courant du bloc
      const nbOffInBlock = notBefore - _dayIndex(b.date)*1440;  // notBefore exprimé en offset de CE jour
      if(nbOffInBlock > startOff) startOff = nbOffInBlock;       // ne pas démarrer avant la contrainte
      // la tâche doit tenir entièrement dans le bloc à partir de startOff
      if(startOff >= b.start && startOff + task.dur <= b.end){
        const endOff = startOff + task.dur;
        b.used = endOff - b.start; bi=k;
        events.push({date:b.date, start:startOff, end:endOff, label:task.label, kind:task.type, note:task.note, id:task.id, repartition:task.repartition||null, besoinNet:task.besoinNet||0});
        const ev = {date:b.date, start:startOff, end:endOff, blockIdx:k};
        if(task.id) placedEnd[task.id] = _absMin(b.date, endOff);
        return ev;
      }
    }
    // pas de place : tâche non planifiée
    warnings.push(`« ${task.label} » (${task.dur} min) ne rentre dans aucun créneau disponible.`);
    // Version STRUCTURÉE pour le diagnostic de réorganisation : on sépare type et parfum depuis l'id.
    const _sep = String(task.id||'').indexOf(':');
    unplaced.push({
      id: task.id,
      type: task.type || (_sep>0 ? task.id.slice(0,_sep) : ''),
      parfum: _sep>0 ? task.id.slice(_sep+1) : '',
      label: task.label, dur: task.dur, after: task.after || null,
      raison: task._raison || null
    });
    return null;
  }
  // placement : phase 1 et 2 entrelacées (meringue puis ganache pendant le passif), puis phase 3.
  const ph1=active.filter(t=>t.phase===1), ph2=active.filter(t=>t.phase===2), ph3=active.filter(t=>t.phase===3);
  // on alterne meringue / ganache pour matérialiser l'entrelacement
  const interleaved=[]; let gi=0;
  ph1.forEach(m=>{ interleaved.push(m); if(gi<ph2.length) interleaved.push(ph2[gi++]); });
  while(gi<ph2.length) interleaved.push(ph2[gi++]);
  interleaved.forEach(t=>place(t));
  // Instant où les COQUES sont prêtes au montage = fin de la dernière tâche coques + sa cuisson
  // passive (makespan four). On prend le max sur toutes les meringues posées.
  let coquesPretesAbs = -Infinity;
  active.filter(t=>t.phase===1).forEach(m=>{
    const fin = placedEnd[m.id];
    if(fin!=null) coquesPretesAbs = Math.max(coquesPretesAbs, fin + (m.passiveAfter||0));
  });
  // montages en dernier (dépendent de tout le reste) — AVEC calage horaire réel :
  //  (1) repos ganache : début montage ≥ fin ganache + délai recette (ganacheDelaiMin).
  //  (2) fraîcheur coques : si le trou coques→montage dépasse coquesTrouMaxH, on marque la
  //      congélation explicite sur l'event (réutilise le seuil unique PROC.coquesTrouMaxH).
  const FRESH_MAX_MIN = (PROC.coquesTrouMaxH!=null ? PROC.coquesTrouMaxH : 9) * 60;
  ph3.forEach(t=>{
    let notBefore = -Infinity, raisonDelai=false;
    if(t.after){
      const ganFin = placedEnd[t.after];
      if(ganFin==null){
        // la ganache dont dépend ce montage n'a pas pu être placée → montage impossible.
        t._raison='ganache_absente';
        const ev = place(t, +Infinity); // forcera l'unplaced en conservant la raison
        return;
      }
      notBefore = ganFin + (t.ganacheDelaiMin||0);
      raisonDelai = (t.ganacheDelaiMin||0) > 0;
    }
    if(raisonDelai) t._raison='repos_ganache';
    const ev = place(t, notBefore);
    if(ev){
      // fraîcheur : congélation si coques trop vieilles au moment du montage, OU si la recette l'impose.
      const montageStartAbs = _absMin(ev.date, ev.start);
      const trouMin = (coquesPretesAbs>-Infinity) ? (montageStartAbs - coquesPretesAbs) : 0;
      const congeler = t.coquesCongelObl || (trouMin > FRESH_MAX_MIN);
      // on enrichit l'event poussé dans `events` (dernier de la liste pour cette tâche).
      const pushed = events[events.length-1];
      if(pushed && pushed.label===t.label){
        pushed.congeler = !!congeler;
        pushed.trouCoquesH = Math.round(trouMin/60*10)/10;
        if(congeler){
          pushed.note = (pushed.note||'') + ` ❄️ Coques à CONGELER : ${t.coquesCongelObl?'imposé par la recette':`trou de ${pushed.trouCoquesH} h depuis la cuisson (> ${PROC.coquesTrouMaxH} h de fraîcheur)`}. Décongélation au frigo avant montage.`;
        }
      }
    }
  });

  // 3) Diagnostic chiffré + insights argumentés (le « chef » explique ses choix).
  // [fix affichage] totalActive/totalAvail sont des SOMMES DE MINUTES issues de calculs en
  // chaîne (conversions h↔min, divisions de créneaux) : l'arithmétique flottante JS peut
  // laisser des résidus (ex. 4.300000000000068 au lieu de 4). Une fraction de minute n'a de
  // toute façon aucun sens métier ici → on arrondit à la minute entière AVANT tout affichage
  // ou modulo, pour ne jamais exposer ces artefacts à l'écran (ex. "8h4.3000…" ou "43h55.69…").
  const totalActive = Math.round(active.reduce((s,t)=>s+t.dur,0));
  const totalAvail = Math.round(_totalAvail(blocks));
  const placed = events.length;
  const lastEvent = events[events.length-1];
  // estimation de fin (avec maturation) → prêt à vendre
  let readyInfo=null;
  if(lastEvent){
    const matEnd = new Date(lastEvent.date+'T00:00'); matEnd.setMinutes(lastEvent.end); matEnd.setHours(matEnd.getHours()+PROC.maturationH);
    readyInfo = matEnd;
  }
  // insights
  const pleines = (plan.meringues||[]).filter(m=>!m.partielle).length;
  const partielles = (plan.meringues||[]).length - pleines;
  const mutualisees = (plan.meringues||[]).filter(m=>m.parfums.length>1).length;
  insights.push(`⏱️ Charge active totale : ${Math.floor(totalActive/60)}h${String(totalActive%60).padStart(2,'0')} pour ${Math.floor(totalAvail/60)}h${String(totalAvail%60).padStart(2,'0')} disponibles (${totalAvail>0?Math.round(totalActive/totalAvail*100):0} % de remplissage).`);
  insights.push(`🥚 ${plan.nbMeringues} meringue(s) de ${MACARONS_PAR_MERINGUE} macarons max (240 coques) : ${pleines} pleine(s)${partielles?`, ${partielles} partielle(s)`:''}. ${mutualisees?`${mutualisees} meringue(s) regroupent 2 parfums uniquement pour combler la capacité`:`Aucun regroupement forcé : chaque parfum remplit ses propres meringues`}.`);
  if(partielles) insights.push(`💡 ${partielles} meringue(s) ne sont pas pleines. Si une échéance approche, tu peux soit les lancer telles quelles, soit attendre une commande qui complète la capacité pour ne pas gâcher de blancs.`);
  const coquesTot = (plan.meringues||[]).reduce((s,m)=>s+(m.macarons||0)*2,0);
  const cuisTot = cuissonCascade(coquesTot,'standard');
  const makespanMin = Math.round(cuisTot.makespanMin);   // défense en profondeur (même précaution que totalActive/totalAvail)
  insights.push(`🔥 Cuisson : ${cuisTot.nbPlaques} plaque(s) de 39 coques, enfournées en cascade (2ᵉ plaque +${PROC.relancePlaqueMin} min, 3ᵉ à la sortie de la 1ʳᵉ…). Temps four estimé ~${Math.floor(makespanMin/60)?Math.floor(makespanMin/60)+'h':''}${makespanMin%60} min, en parallèle des ganaches/montages.`);
  if(readyInfo) insights.push(`📦 Avec ${PROC.maturationH} h de maturation après le dernier montage, le lot complet est prêt à la vente le ${readyInfo.toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'long'})} vers ${String(readyInfo.getHours()).padStart(2,'0')}h${String(readyInfo.getMinutes()).padStart(2,'0')}.`);
  // Insight délai ganache : matérialise la contrainte de repos avant montage par recette.
  {
    const avecDelai = lignes.filter(l=>l.ganacheDelaiH>0);
    const sansDelai = lignes.filter(l=>l.ganacheDelaiH===0);
    if(avecDelai.length){
      const maxDelai = Math.max(...avecDelai.map(l=>l.ganacheDelaiH));
      insights.push(`⏱ Repos ganache : prévois les ganaches ${maxDelai>0?`au moins ${maxDelai} h`:''} avant le montage (${avecDelai.map(l=>l.parfum).join(', ')}). Idéalement, prépare-les la veille pour monter le jour J.`);
    }
    if(sansDelai.length) insights.push(`✓ Sans délai de repos imposé : ${sansDelai.map(l=>l.parfum).join(', ')} — montage possible dès la ganache prête.`);
    const coquesCongel = lignes.filter(l=>l.coquesCongelObl);
    if(coquesCongel.length) insights.push(`❄️ Coques à congeler avant montage : ${coquesCongel.map(l=>l.parfum).join(', ')}. Cuis les coques en amont, congèle-les, puis monte au moment voulu.`);
  }
  if(totalActive>totalAvail) insights.push(`⚠ Il manque ${Math.ceil((totalActive-totalAvail)/60*10)/10} h de créneau : envisage d'étaler sur un jour de plus, ou de réduire les quantités les moins prioritaires.`);
  else insights.push(`✅ Tout tient dans tes créneaux, avec ${Math.floor((totalAvail-totalActive)/60)}h${String((totalAvail-totalActive)%60).padStart(2,'0')} de marge pour les imprévus (nettoyage, étiquetage, pauses).`);

  return {events, warnings, insights, unplaced, blocks, ok: warnings.length===0,
    totalActive, totalAvail, placed, readyInfo, nbMeringues:plan.nbMeringues, nbBatchsTotal:plan.nbBatchsTotal};
}

// APPRENTISSAGE : enregistre le temps réel d'une tâche et met à jour l'estimation (moyenne mobile).
// MAPPING d'une tâche d'atelier (label/phase) vers une catégorie de temps MRP.
// Phases Préparation/Meringue/Macaronnage/Cuisson → coques.
// Phase Garnissage : ganache (prépa ganache, cristallisation beurre cacao) vs montage (pochage,
// assemblage, chablonnage). Phase Entretien : vaisselle vs entretien (nettoyage surfaces).
function prodTaskMrpCategory(task){
  const phase = (task.phase||'').toLowerCase();
  const label = (task.label||'').toLowerCase();
  if(phase==='préparation'||phase==='preparation'||phase==='meringue'||phase==='macaronnage'||phase==='cuisson') return 'coques';
  // Nouvelle phase dédiée : toute la préparation de la ganache (pesée, émulsion) → ganache.
  if(phase==='préparation ganache'||phase==='preparation ganache') return 'ganache';
  if(phase==='garnissage'){
    // Mise en congélation des coques pour cristallisation : finalise les COQUES (manip active sur coques).
    // À attraper AVANT la règle d'exclusion de "cristallisation", sinon elle serait ignorée à tort.
    if(label.includes('congélation')||label.includes('congelation')) return 'coques';
    // Chablonnage = finalise la coque, mais SPÉCIFIQUE à certaines recettes (ganaches humides :
    // framboise, citron…). Compté comme COQUES : grâce au rattachement par parfum sur la tâche, ce
    // temps tombe sur le parfum réellement chablonné et ne dilue pas les autres.
    if(label.includes('chablonnage')) return 'coques';
    // Cristallisation du beurre de cacao : reste exclue des catégories génériques (opération très
    // spécifique, gérée via les "temps spécifiques par recette" si besoin).
    if(label.includes('cristallisation')||label.includes('beurre de cacao')) return null;
    if(label.includes('ganache')&&label.includes('prépar')) return 'ganache';
    // pochage ganache, assemblage → montage
    return 'montage';
  }
  if(phase==='entretien'){
    if(label.includes('vaisselle')) return 'vaisselle';
    return 'entretien';
  }
  return null; // tâche non mappable (ex. "Autre") → ignorée pour l'apprentissage
}

// Agrège les durées nettes (minutes) d'une session, par catégorie MRP.
function prodSessMinutesByCategory(sess){
  const acc = { coques:0, ganache:0, montage:0, vaisselle:0, entretien:0 };
  (sess.tasks||[]).forEach(t=>{
    const cat = prodTaskMrpCategory(t); if(!cat) return;
    const ms = (typeof prodTaskNet==='function') ? prodTaskNet(t) : 0;
    acc[cat] += ms/60000;
  });
  return acc;
}

// APPRENTISSAGE depuis une session close : ramène les durées mesurées à l'unité de référence
// (coques÷meringues, ganache/montage/vaisselle÷batchs, entretien par session) et nourrit validateTask.
function prodSessFeedLearning(sess, nbBatchs, nbMeringues){
  const mins = prodSessMinutesByCategory(sess);
  const nb = Math.max(0, +nbBatchs||0);
  const nm = Math.max(0, +nbMeringues||0);
  const deja = Array.isArray(sess._apprisCats) ? sess._apprisCats : [];
  const fed = [];
  // On n'apprend QUE les catégories pas encore apprises (évite le double comptage si session rouverte).
  // coques : par meringue
  if(mins.coques>0 && nm>0 && !deja.includes('coques')){ validateTask('coques', mins.coques/nm); fed.push('coques'); }
  // ganache, montage, vaisselle : par batch
  if(mins.ganache>0 && nb>0 && !deja.includes('ganache')){ validateTask('ganache', mins.ganache/nb); fed.push('ganache'); }
  if(mins.montage>0 && nb>0 && !deja.includes('montage')){ validateTask('montage', mins.montage/nb); fed.push('montage'); }
  if(mins.vaisselle>0 && nb>0 && !deja.includes('vaisselle')){ validateTask('vaisselle', mins.vaisselle/nb); fed.push('vaisselle'); }
  // entretien : par session (indépendant du volume)
  if(mins.entretien>0 && !deja.includes('entretien')){ validateTask('entretien', mins.entretien); fed.push('entretien'); }
  return fed;
}

function validateTask(taskType, actualMinutes){
  const t=getMrpTimes();
  if(!t[taskType]) return null;
  const m=Math.max(0, +actualMinutes||0);
  // [GARDE-FOU APPRENTISSAGE] On refuse d'apprendre une mesure physiquement implausible (sous le
  // plancher de l'étape) : un chrono lancé/arrêté trop vite ne doit pas corrompre l'estimation
  // moyenne. La session n'est simplement pas prise en compte pour cette étape (on ne touche ni à
  // estimatedTime ni au cumul). Sans plancher (floor=0), tout est appris comme avant.
  const floor = MRP_TIME_FLOOR[taskType]||0;
  if(floor>0 && m>0 && m<floor){ return null; }
  const e=t[taskType];
  e.completions += 1;
  e.totalRealTime = money2(e.totalRealTime + m);
  // moyenne mobile : on lisse l'estimation vers la moyenne réelle observée
  const moyenneReelle = e.totalRealTime / e.completions;
  // pondération douce (70% historique lissé, 30% dernière mesure) pour rester réactif sans osciller
  let est = Math.round((moyenneReelle*0.7 + m*0.3));
  // Filet de sécurité : même la moyenne lissée ne descend jamais sous le plancher.
  if(floor>0 && est<floor) est = floor;
  e.estimatedTime = est;
  saveMrpTimes(t);
  return e;
}

// ---------- UI ----------
let _mrpStart=null, _mrpEnd=null, _mrpPlan=null, _mrpDispo=0, _mrpMatCheck=null;

// Liste les commandes non livrées de la période du plan, avec un bouton rétroplanning par commande.

/* ============================================================
   DÉTECTION DE CONFLITS DE PRODUCTION (rétroplanning multi-commandes)
   Superpose les rétroplannings de toutes les commandes d'une période.
   Deux tâches de TRAVAIL (coques, ganache, crémeux, montage) de commandes
   différentes sont « en conflit » si leurs plages horaires se chevauchent
   (impossibles à réaliser en même temps par une seule personne).
   Les étapes d'ATTENTE (repos, maturation, congélation) sont passives et
   ne créent jamais de conflit (plusieurs lots peuvent reposer en parallèle).
   ============================================================ */
// [CODE RETIRÉ v759] _retroDureeTache + retroTachesTravail : ces deux fonctions calculaient des
// tâches de travail THÉORIQUES (non calées dans les plages A/B) avec les anciennes durées
// (ganache/montage × nbBatchs global). Depuis v758, retroConflicts s'appuie sur retroplanningCale
// (calage réel + durées par parfum), ce qui les a rendues inutiles. Supprimées pour éviter toute
// réutilisation accidentelle d'un calcul périmé.

// [HELPER PUR — extrait de retroConflicts, v831] Détection de chevauchements à partir d'une LISTE
// DE TÂCHES déjà calées (aucune lecture de base). Sépare la logique pure (triable, testable en
// isolation) de la collecte des données. Réutilisé tel quel par retroConflicts (données réelles)
// ET par la simulation « et si je livrais le X ? » (une commande à date fictive, en mémoire).
// taches : [{orderId, client, cle, label, debut:Date, fin:Date, dureeMin, dateLiv}]
// Renvoie { conflits:[{a,b,debut,fin,minutes}], taches } — comportement identique à l'ancien inline.
function _retroDetecterConflits(taches){
  const arr = (taches||[]).slice().sort((a,b)=> a.debut - b.debut);
  const conflits = [];
  for(let i=0;i<arr.length;i++){
    for(let j=i+1;j<arr.length;j++){
      const A=arr[i], B=arr[j];
      if(B.debut >= A.fin) break;                 // trié par début : plus de chevauchement possible avec A
      if(A.orderId===B.orderId) continue;          // même commande : pas un conflit
      const overlapStart = new Date(Math.max(A.debut, B.debut));
      const overlapEnd   = new Date(Math.min(A.fin, B.fin));
      const minutes = Math.round((overlapEnd - overlapStart)/60000);
      if(minutes>0) conflits.push({a:A, b:B, debut:overlapStart, fin:overlapEnd, minutes});
    }
  }
  return { conflits, taches:arr };
}

// [HELPER PUR — v831] Transforme un jeu de jalons calés (issus de retroplanningCale/Parfums) en
// tâches de TRAVAIL exploitables par _retroDetecterConflits. Seuls les jalons 'active' et 'encadree'
// comptent (le repos/maturation/livraison ne créent jamais de conflit). On passe le calage déjà
// fait → ce helper ne touche NI la base NI le réseau, il est donc testable en Node.
// entrees : [{orderId, dateLiv, clientNom, cale}] où cale = retour de retroplanningCale(Parfums).
function _retroTachesDepuisCales(entrees){
  const TYPES_TRAVAIL = new Set(['active','encadree']);
  const taches = [];
  (entrees||[]).forEach(e=>{
    const cale = e.cale;
    if(!cale || !cale.ok || !Array.isArray(cale.jalonsCales)) return;
    cale.jalonsCales.forEach(j=>{
      if(!TYPES_TRAVAIL.has(j.type)) return;
      if(!j.debut || !j.fin) return;
      const debut = new Date(j.debut), fin = new Date(j.fin);
      if(!(fin>debut)) return;
      taches.push({ orderId:e.orderId, client:e.clientNom||'', cle:j.cle, label:j.label,
                    debut, fin, dureeMin: Math.round((fin-debut)/60000), dateLiv:e.dateLiv });
    });
  });
  return taches;
}

// Détecte les conflits (chevauchements) entre tâches de travail de commandes DIFFÉRENTES.
async function retroConflicts(startDate, endDate){
  let orders;
  try{ orders = await db.orders.where('date').between(startDate, endDate, true, true).toArray(); }
  catch(e){ const all=await db.orders.toArray().catch(()=>[]); orders=all.filter(o=>o.date&&o.date>=startDate&&o.date<=endDate); }
  orders = orders.filter(o=> (typeof normStatus==='function'?normStatus(o.statut):o.statut)!=='Livrée');
  const [recipes, clients] = await Promise.all([db.recipes.toArray().catch(()=>[]), db.clients.toArray().catch(()=>[])]);
  const clName = id => (clients.find(c=>c.id===id)||{}).nom || '—';
  const times = (typeof getMrpTimes==='function') ? getMrpTimes() : null;

  // [POINT C — CALAGE RÉEL] On compare les tâches CALÉES dans les vraies plages A/B (via
  // retroplanningCale), pas des tâches théoriques qui pourraient tomber un jour/heure non
  // travaillé (faux conflits). retroplanningCale intègre déjà toutes les corrections de durée
  // (ganache/montage par parfum, facteur de cadence, étalement) → conflits justes par construction.
  // Seuls les jalons de TRAVAIL ACTIF créent un conflit : 'active' (ganache/crémeux/montage) et
  // 'encadree' (coques, présence requise). Les passifs ('libre'/'ancre' : repos, maturation,
  // congélation, livraison) n'en créent jamais.
  // [v831] Calage de chaque commande (lecture base), puis délégation aux helpers PURS
  // _retroTachesDepuisCales + _retroDetecterConflits. La logique de détection est désormais
  // isolée et testée en Node ; ici on ne fait que collecter les données réelles.
  const entrees = [];
  for(const o of orders){
    let cale=null;
    try{ cale = await retroplanningCale(o.id); }catch(_){ cale=null; }
    entrees.push({ orderId:o.id, dateLiv:o.date, clientNom:clName(o.clientId)||'', cale });
  }
  const taches = _retroTachesDepuisCales(entrees);
  const { conflits } = _retroDetecterConflits(taches);
  return { conflits, taches, nbCommandes:orders.length };
}

// [SIMULATION — NIVEAU 3 / ÉTAPE C] Impact d'une commande déplacée à une date FICTIVE sur sa semaine
// cible : est-ce que ça chevauche les autres commandes de cette semaine, combien, lesquelles ?
// 100 % EN MÉMOIRE : on ne touche JAMAIS db.orders. On lit les AUTRES commandes de la semaine (leur
// calage réel), puis on injecte la commande simulée avec son calage FICTIF (simCale, déjà calculé au
// niveau 1-2), et on délègue aux helpers PURS _retroTachesDepuisCales + _retroDetecterConflits.
// On ne renvoie que les conflits qui IMPLIQUENT la commande simulée (orderId).
// Retour : { ok, nbAutresCommandes, conflits:[{client, minutes, label}], totalMinutes, semaineLabel }.
async function _retroImpactSemaine(orderId, dateSim, simCale){
  try{
    if(!dateSim || !simCale || !simCale.ok) return { ok:false };
    // Bornes lundi→dimanche de la semaine de la date fictive (heure locale, cohérent avec l'app).
    const d = new Date(dateSim); if(isNaN(d)) return { ok:false };
    const day = (d.getDay()+6)%7;                 // lundi=0
    const lundi = new Date(d); lundi.setDate(d.getDate()-day); lundi.setHours(0,0,0,0);
    const dim = new Date(lundi); dim.setDate(lundi.getDate()+6); dim.setHours(23,59,59,999);
    const toStr = x => x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');

    // [FIX point 2] Un CONFLIT naît du chevauchement de TÂCHES DE TRAVAIL, pas des dates de livraison.
    // Le travail d'une commande (ganache + repos) peut tomber PLUSIEURS JOURS avant sa livraison, donc
    // une commande livrée hors de la semaine cible peut quand même travailler dedans (et inversement).
    // On élargit donc la fenêtre de SÉLECTION : large en amont (le travail amont d'une livraison plus
    // tardive peut chevaucher), un peu en aval. La détection fine reste sur les vraies tâches calées,
    // donc élargir ne crée pas de faux conflits — ça évite seulement d'en RATER.
    const MARGE_AMONT = 10, MARGE_AVAL = 9;       // jours : couvre repos long + production étalée
    const winStart = new Date(lundi);  winStart.setDate(lundi.getDate()-MARGE_AMONT);
    const winEnd   = new Date(dim);    winEnd.setDate(dim.getDate()+MARGE_AVAL);
    const startStr = toStr(winStart), endStr = toStr(winEnd);

    // AUTRES commandes dont la livraison tombe dans la fenêtre élargie (jamais la commande simulée).
    let orders;
    try{ orders = await db.orders.where('date').between(startStr, endStr, true, true).toArray(); }
    catch(e){ const all=await db.orders.toArray().catch(()=>[]); orders=all.filter(o=>o.date&&o.date>=startStr&&o.date<=endStr); }
    orders = orders.filter(o=> o.id!==orderId && (typeof normStatus==='function'?normStatus(o.statut):o.statut)!=='Livrée');

    const clients = await db.clients.toArray().catch(()=>[]);
    const clName = id => (clients.find(c=>c.id===id)||{}).nom || '—';

    // Calage RÉEL des autres commandes (lecture base, aucune écriture).
    const entrees = [];
    for(const o of orders){
      let cale=null;
      try{ cale = await retroplanningCale(o.id); }catch(_){ cale=null; }
      entrees.push({ orderId:o.id, dateLiv:o.date, clientNom:clName(o.clientId)||'', cale });
    }
    // Commande SIMULÉE injectée à sa date fictive avec son calage fictif (en mémoire).
    const oSim = await db.orders.get(orderId).catch(()=>null);
    entrees.push({ orderId, dateLiv:dateSim, clientNom: oSim ? (clName(oSim.clientId)||'cette commande') : 'cette commande', cale: simCale });

    const taches = _retroTachesDepuisCales(entrees);
    // [FIX point 2] « Autres commandes de la semaine » = celles dont au moins une TÂCHE de travail
    // tombe dans la semaine cible (lundi→dimanche), pas toute la fenêtre élargie de sélection.
    const lundiMs = lundi.getTime(), dimMs = dim.getTime();
    const autresActives = new Set();
    taches.forEach(t=>{
      if(t.orderId===orderId) return;
      const db_ = t.debut instanceof Date ? t.debut.getTime() : new Date(t.debut).getTime();
      const df_ = t.fin   instanceof Date ? t.fin.getTime()   : new Date(t.fin).getTime();
      // chevauchement de la tâche avec la fenêtre semaine
      if(df_ >= lundiMs && db_ <= dimMs) autresActives.add(t.orderId);
    });
    const { conflits } = _retroDetecterConflits(taches);
    // Ne garder que les conflits impliquant la commande simulée, agrégés par AUTRE commande.
    const parAutre = new Map();
    conflits.forEach(c=>{
      const implique = (c.a.orderId===orderId) || (c.b.orderId===orderId);
      if(!implique) return;
      const autre = (c.a.orderId===orderId) ? c.b : c.a;
      const key = autre.orderId;
      const prev = parAutre.get(key) || { client:autre.client||'—', minutes:0, labels:new Set() };
      prev.minutes += c.minutes;
      if(autre.label) prev.labels.add(autre.label);
      parAutre.set(key, prev);
    });
    const liste = Array.from(parAutre.values()).map(v=>({ client:v.client, minutes:v.minutes, labels:Array.from(v.labels) }))
                       .sort((a,b)=> b.minutes - a.minutes);
    const totalMinutes = liste.reduce((s,v)=>s+v.minutes,0);
    const fmt = x => x.toLocaleDateString('fr-FR',{day:'2-digit',month:'short'});
    return { ok:true, nbAutresCommandes:autresActives.size, conflits:liste, totalMinutes,
             semaineLabel:`${fmt(lundi)} → ${fmt(dim)}` };
  }catch(e){
    console.error('_retroImpactSemaine', e);
    return { ok:false };
  }
}

// Affiche les conflits de production détectés sur les 14 prochains jours.
// état des tâches cochées (en mémoire pour la session de production en cours)
// Au clic : ouvre l'écran inline de validation du temps réel.
// Validation inline du temps réel passé (pré-rempli avec l'estimation).

/* ---------- Planification personnelle (UI) ---------- */
let _persoDays = null;   // [{date, slotsTxt}]
let _persoPlan = null;   // résultat schedulePersonalPlan
function _persoDefaultDays(){
  const d0=today();
  return [{date:d0, slotsTxt:''}];
}
function persoPlanForm(){
  if(!_persoDays) _persoDays=_persoDefaultDays();
  const rows=_persoDays.map((d,i)=>`
    <div class="perso-day">
      <div class="row2">
        <div class="field"><label>Jour ${i+1}</label><input type="date" id="pd_date_${i}" value="${esc(d.date)}"></div>
        <div class="field"><label>Créneaux (ex : 14:00-18:00, 21:00-23:00)</label>
          <input id="pd_slots_${i}" value="${esc(d.slotsTxt)}" placeholder="14:00-18:00, 21:00-23:00" spellcheck="false"></div>
      </div>
      ${_persoDays.length>1?`<button class="act del" onclick="persoDelDay(${i})">– retirer ce jour</button>`:''}
    </div>`).join('');
  openModal(`<h3>🧑‍🍳 Ma disponibilité</h3>
    <p class="note">Indique tes créneaux réels jour par jour. Tu peux mettre plusieurs plages par jour (séparées par une virgule). Exemples : « 3h aujourd'hui » → un créneau de 3h ; « 1 jour 4h puis le lendemain 5h » → deux jours.</p>
    <div class="perso-presets">
      <button class="btn ghost sm" onclick="persoPreset('today3')">Aujourd'hui 3h</button>
      <button class="btn ghost sm" onclick="persoPreset('2days')">2 jours</button>
      <button class="btn ghost sm" onclick="persoPreset('fromAvail')">⤵ Importer mes dispos</button>
    </div>
    <div id="persoDays">${rows}</div>
    <button class="act" onclick="persoAddDay()">+ ajouter un jour</button>
    <div class="field" style="margin-top:10px"><label>Tâches à accomplir</label>
      <select id="pd_source">
        <option value="orders">Honorer les commandes de la période ci-dessous</option>
        <option value="custom">Quantités libres par parfum</option>
      </select></div>
    <div class="row2">
      <div class="field"><label>Commandes du</label><input type="date" id="pd_from" value="${_mrpStart||today()}"></div>
      <div class="field"><label>au</label><input type="date" id="pd_to" value="${_mrpEnd||today()}"></div>
    </div>
    <div class="field" id="pd_customWrap" style="display:none"><label>Quantités libres (ex : Vanille 120, Caramel 60)</label>
      <input id="pd_custom" placeholder="Vanille 120, Caramel 60" spellcheck="false"></div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="persoGenerate()">⚙ Générer mon planning</button></div>`);
  const sel=document.getElementById('pd_source');
  if(sel) sel.onchange=()=>{ document.getElementById('pd_customWrap').style.display = sel.value==='custom'?'block':'none'; };
}
function _persoReadDays(){
  _persoDays = _persoDays.map((d,i)=>({
    date: val('pd_date_'+i)||d.date,
    slotsTxt: val('pd_slots_'+i)||''
  }));
}
function persoAddDay(){ _persoReadDays(); const last=_persoDays[_persoDays.length-1];
  const nd=new Date(last.date); nd.setDate(nd.getDate()+1);
  _persoDays.push({date:ymdLocal(nd), slotsTxt:''}); persoPlanForm(); }
function persoDelDay(i){ _persoReadDays(); _persoDays.splice(i,1); if(!_persoDays.length)_persoDays=_persoDefaultDays(); persoPlanForm(); }
function persoPreset(kind){
  _persoReadDays();
  if(kind==='today3'){ _persoDays=[{date:today(), slotsTxt:_presetNextHours(3)}]; }
  else if(kind==='2days'){ const d0=today(); const d1=new Date(d0); d1.setDate(d1.getDate()+1);
    _persoDays=[{date:d0, slotsTxt:_presetNextHours(4)},{date:ymdLocal(d1), slotsTxt:'09:00-14:00'}]; }
  else if(kind==='fromAvail'){
    const conf=getAvailability(); const out=[]; const cur=new Date(today());
    for(let k=0;k<3;k++){ const slots=availSlotsForDate(cur,conf); if(slots.length) out.push({date:ymdLocal(cur), slotsTxt:_slotsToText(slots)}); cur.setDate(cur.getDate()+1); }
    _persoDays = out.length?out:_persoDefaultDays();
  }
  persoPlanForm();
}
// Construit un créneau "maintenant → +Nh" arrondi, borné à 23:00.
function _presetNextHours(h){
  const now=new Date(); let sh=now.getHours()+(now.getMinutes()>0?1:0); if(sh<8)sh=8;
  let eh=Math.min(23, sh+h);
  return `${String(sh).padStart(2,'0')}:00-${String(eh).padStart(2,'0')}:00`;
}
function _parseCustomNeeds(txt){
  const needs={};
  String(txt||'').split(',').forEach(part=>{
    const m=part.trim().match(/^(.+?)\s+(\d+)$/);
    if(m){ needs[m[1].trim()] = (needs[m[1].trim()]||0)+(+m[2]||0); }
  });
  return needs;
}
async function persoGenerate(){
  _persoReadDays();
  const source=val('pd_source')||'orders';
  // 1) Construire le plan de besoins (batchs/meringues/temps) selon la source choisie.
  let plan;
  if(source==='custom'){
    const needs=_parseCustomNeeds(val('pd_custom'));
    if(!Object.keys(needs).length){ toast('Indique au moins un parfum et une quantité'); return; }
    plan = await _planFromNeeds(needs);
  } else {
    const from=val('pd_from')||today(), to=val('pd_to')||from;
    plan = await generateProductionOrder(from, to, 0);
    if(!plan.lignes.length){ closeModal(); toast('Le stock couvre déjà ces commandes — rien à produire'); return; }
  }
  // 2) Convertir la dispo saisie en blocs (minutes).
  const daySpecs=_persoDays.map(d=>({ date:d.date,
    slots:_textToSlots(d.slotsTxt).map(([a,b])=>[hmToMin(a), hmToMin(b)]) }))
    .filter(d=>d.slots.length);
  if(!daySpecs.length){ toast('Renseigne au moins un créneau horaire'); return; }
  // 3) Ordonnancer.
  _persoPlan = schedulePersonalPlan(daySpecs, plan, {});
  closeModal();
  _mrpPlan = plan;   // pour cohérence d'affichage
  persoRenderResult();
}
// Construit un "plan" (même forme que generateProductionOrder) à partir de besoins libres.
async function _planFromNeeds(needs){
  const {stock, recipes}=await mrpCurrentStockByParfum();
  const times=getMrpTimes();
  let _tEtape=null; try{ _tEtape = await prodTempsParEtapeParParfum(90); }catch(_){ _tEtape=null; }
  const lignes=[]; const warnings=[];
  for(const parfum in needs){
    const besoinBrut=+needs[parfum]||0; if(besoinBrut<=0) continue;
    const enStock=stock[parfum]||0; const besoinNet=Math.max(0,besoinBrut-enStock);
    if(besoinNet<=0) continue;
    const nbBatchs=Math.ceil(besoinNet/TAILLE_BATCH_MACARONS);
    const rec=mrpFindRecipe(recipes,parfum); if(!rec) warnings.push(parfum);
    const poidsUnit=rec&&rec.poidsGarnitureUnit!=null?+rec.poidsGarnitureUnit:0;
    const { tMontage, tGanache } = _dureesLignePlan(parfum, besoinNet, nbBatchs, rec, times, _tEtape);
    lignes.push({parfum, recipeId:rec?rec.id:null, besoinBrut, enStock, besoinNet, nbBatchs,
      coques:nbBatchs*COQUES_PAR_BATCH, garnitureG:Math.round(nbBatchs*TAILLE_BATCH_MACARONS*poidsUnit),
      poidsUnit, tMontage, tGanache,
      garnitureManque:!rec||poidsUnit<=0});
  }
  lignes.sort((a,b)=>b.besoinNet-a.besoinNet);
  const meringues=_packMeringues(lignes);
  const nbBatchsTotal=lignes.reduce((s,l)=>s+l.nbBatchs,0);
  const tMeringue=meringues.length*times.coques.estimatedTime;
  const tGanacheTot=lignes.reduce((s,l)=>s+l.tGanache,0), tMontageTot=lignes.reduce((s,l)=>s+l.tMontage,0);
  return {lignes, meringues, nbMeringues:meringues.length, nbBatchsTotal,
    tMeringue, tGanacheTot, tMontageTot, tempsTotal:tMeringue+tGanacheTot+tMontageTot,
    tempsDisponible:0, depassement:false, chargePct:0, warnings, nbParfums:lignes.length};
}
const _JOURS_FR=['dimanche','lundi','mardi','mercredi','jeudi','vendredi','samedi'];
// [fix affichage] m peut porter une imprécision flottante (calculs en chaîne de durées) ;
// une fraction de minute n'a aucun sens pour un horaire → on arrondit AVANT floor/modulo,
// sinon un horaire comme "08:54.10000000000002" s'affiche au lieu de "08:54".
function _minToHM(m){ m=Math.round(+m||0); return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0'); }
function persoRenderResult(){
  if(!_persoPlan) return;
  const S=_persoPlan;
  // grouper les événements par jour
  const byDay={}; S.events.forEach(e=>{ (byDay[e.date] ||= []).push(e); });
  const dayBlocks=Object.keys(byDay).sort().map(date=>{
    const d=new Date(date+'T00:00');
    const rows=byDay[date].map(e=>{
      const icon=e.kind==='coques'?'🥚':e.kind==='ganache'?'🍫':e.kind==='montage'?'🧩':'•';
      return `<div class="perso-ev">
        <div class="perso-ev-time">${_minToHM(e.start)}<br><span>${_minToHM(e.end)}</span></div>
        <div class="perso-ev-body"><div class="perso-ev-lbl">${icon} ${esc(e.label)}</div>
          ${e.note?`<div class="perso-ev-note">${esc(e.note)}</div>`:''}</div></div>`;
    }).join('');
    return `<div class="panel"><h2 style="text-transform:capitalize">${_JOURS_FR[d.getDay()]} ${d.toLocaleDateString('fr-FR',{day:'2-digit',month:'long'})}</h2>${rows}</div>`;
  }).join('');
  const insightHtml=S.insights.map(t=>`<li>${esc(t)}</li>`).join('');
  const warnHtml=S.warnings.length?`<div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">⚠ <div>${S.warnings.map(esc).join('<br>')}</div></div>`:'';
  const html=`
    ${warnHtml}
    <div class="panel" style="background:#faf6ef">
      <h2>🧑‍🍳 Le mot du chef d'atelier</h2>
      <ul class="perso-insights">${insightHtml}</ul>
    </div>
    ${dayBlocks||'<div class="banner">Aucune tâche planifiable avec ces créneaux.</div>'}
    <div class="panel"><button class="btn ghost" onclick="persoPlanForm()">✎ Ajuster ma disponibilité</button></div>`;
  // Le chef d'atelier s'affiche dans une modale (l'écran Production n'a pas de conteneur dédié).
  // La branche #mrpResult est conservée par sécurité mais n'est plus alimentée depuis la fusion.
  const box=document.getElementById('mrpResult');
  if(box){
    box.innerHTML=html;
    box.scrollIntoView({behavior:'smooth', block:'start'});
  } else {
    openModal(`<h3>🧑‍🍳 Mon planning de séance</h3>
      <div style="max-height:70vh;overflow:auto">${html}</div>
      <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
  }
}

/* ============================================================
   HACCP / PMS — Plan de Maîtrise Sanitaire (utilisateur unique)
   Suivi numérique : relevés de température (matin/soir) + plan de
   nettoyage (quotidien/hebdo/mensuel) + export DDPP 30 jours.
   ============================================================ */
const PMS_CORRECTIVES = [
  'Isolation du lot NC / Réglage thermostat',
  'Déplacement marchandise vers équipement conforme'
];
const PMS_FREQ_ORDER = ['Quotidien','Hebdo','Mensuel'];

// Peuple la base PMS si elle est vide (idempotent).
async function seedPMS(){
  const nbEq = await db.pmsEquipments.count().catch(()=>0);
  if(nbEq===0){
    await db.pmsEquipments.bulkAdd([
      {nom:'Frigo F',            type:'positif', tempMin:0,   tempMax:5,   marcheOnly:false},
      {nom:'Congélateur A (Petit)',   type:'negatif', tempMin:-24, tempMax:-18, marcheOnly:false},
      {nom:'Congélateur B (Bahut)',   type:'negatif', tempMin:-24, tempMax:-18, marcheOnly:false},
      {nom:'Congélateur C (Colonne)', type:'negatif', tempMin:-24, tempMax:-18, marcheOnly:false},
      {nom:'Vitrine Marché V',   type:'positif', tempMin:0,   tempMax:5,   marcheOnly:true}
    ]);
  }
  const nbTasks = await db.pmsTasks.count().catch(()=>0);
  if(nbTasks===0){
    const q=['Plans de travail','Robot','Sol','Façades et poignées de placards','Plonge et Poubelles'];
    const h=['Nettoyage frigos et congélateurs','Étagères de rangement denrées','Four','Hotte'];
    const m=['Nettoyage en profondeur des équipements froid','Dépoussiérage VMC/Aérations'];
    const tasks=[
      ...q.map(nom=>({nom, frequence:'Quotidien'})),
      ...h.map(nom=>({nom, frequence:'Hebdo'})),
      ...m.map(nom=>({nom, frequence:'Mensuel'}))
    ];
    await db.pmsTasks.bulkAdd(tasks);
  }
}

// ⚠ FONCTION TEMPORAIRE — génération d'un historique de relevés de température.
// À RETIRER après usage. Génère 2 relevés/jour (Matin/Soir) par équipement fixe (non marcheOnly),
// conformes (température aléatoire dans [tempMin, tempMax] de CHAQUE équipement), sur une période donnée.
// ⚠ FONCTION TEMPORAIRE — génération d'un historique de nettoyages périodiques.
// À RETIRER après usage. Respecte les cadences depuis le 15/10/2025 :
//   Quotidien → chaque jour ; Hebdo → tous les 7 jours (1re éch. 22/10) ;
//   Mensuel → tous les 30 jours (1re éch. 15/11). Une validation par échéance.
// Une température est-elle conforme à la plage de l'équipement ?
// Début de période d'une tâche selon sa fréquence (pour savoir si "faite" sur la période courante).
function pmsPeriodStart(freq){
  const d=new Date(today());
  if(freq==='Hebdo'){ const day=(d.getDay()+6)%7; d.setDate(d.getDate()-day); }   // lundi de la semaine
  else if(freq==='Mensuel'){ d.setDate(1); }                                       // 1er du mois
  return ymdLocal(d);
}

let _pmsTab = 'temp';        // 'temp' | 'nettoyage'
let _pmsPeriode = null;      // 'Matin' | 'Soir' (auto si null)
let _pmsDate = null;         // date du relevé (défaut = aujourd'hui ; permet de corriger un jour passé)
function pmsSetDate(d){ if(d!==_pmsDate && !pmsGuardUnsaved()) return; _pmsDate = d || today(); pmsRenderTemp(); }

// ============================================================
//  ÉQUIPEMENTS — modèle à NIVEAUX multiples.
//  Chaque équipement = liste de niveaux, chacun avec ses dimensions (L×l×h cm) et un mode :
//   'empilable' (on empile les boîtes sur la hauteur du niveau) ou 'clayette' (1 couche).
//  Un niveau peut être 'reserve' (matières premières) → exclu du calcul macarons.
//  Le stockage global = somme des niveaux de tous les équipements (espace unique sectionné).
//  Orientation des boîtes fixe (pas de rotation), conforme à la préférence.
// ============================================================
async function equipGetSpecs(){
  const arr = await db.equipmentSpecs.toArray().catch(()=>[]);
  return Object.fromEntries(arr.map(s=>[s.key,s]));
}
// Rôles et accessibilité des niveaux (pour le rangement intelligent et le picking).
const NIV_ROLES = {reserve:{label:'Réserve profonde', ico:'📦', c:'#7a6a9a'}, transit:{label:'Transit', ico:'🔄', c:'#3f7d52'}, standard:{label:'Standard', ico:'•', c:'#9a8a82'}};
const NIV_ACCES = {facile:{label:'Facile', ico:'🟢'}, moyenne:{label:'Moyenne', ico:'🟡'}, difficile:{label:'Difficile', ico:'🔴'}};
function nivRole(lv){ return NIV_ROLES[lv&&lv.role] ? lv.role : 'standard'; }
function nivAcces(lv){ return NIV_ACCES[lv&&lv.acces] ? lv.acces : 'facile'; }
function boxesPerLayer(eL, el, bL, bl){
  if(bL<=0||bl<=0||eL<=0||el<=0) return {fixe:0, tourne:0};
  return { fixe: Math.floor(eL/bL)*Math.floor(el/bl), tourne: Math.floor(eL/bl)*Math.floor(el/bL) };
}
// Capacité d'UN niveau pour un type de boîte (orientation fixe).
function levelCapacityForBox(level, box){
  if(!level || level.reserve) return null;
  const eL=+level.L||0, el=+level.l||0, eh=+level.h||0;
  const bL=+box.L||0, bl=+box.l||0, bh=+box.h||0;
  if(eL<=0||el<=0||eh<=0||bL<=0||bl<=0||bh<=0) return null;
  const per = boxesPerLayer(eL, el, bL, bl);
  const couches = (level.mode==='clayette') ? (bh<=eh?1:0) : Math.floor(eh/bh);
  return { nbBoites: per.fixe*couches, nbBoitesTourne: per.tourne*couches,
    capaciteMacarons: per.fixe*couches*(+box.capacite||0) };
}
// Capacité d'un équipement (somme de ses niveaux) pour un type de boîte.
function equipCapacityForBox(spec, box){
  if(!spec || !Array.isArray(spec.niveaux)) return null;
  let nbBoites=0, capMac=0, gain=0, niveauxUtiles=0;
  spec.niveaux.forEach(lv=>{
    const c=levelCapacityForBox(lv, box); if(!c) return;
    nbBoites+=c.nbBoites; capMac+=c.capaciteMacarons; gain+=Math.max(0,c.nbBoitesTourne-c.nbBoites);
    if(c.nbBoites>0) niveauxUtiles++;
  });
  return { nbBoites, capaciteMacarons:capMac, gainRotation:gain, niveauxUtiles };
}
