// ---- OCCUPATION RÉELLE DES NIVEAUX (par empreinte/volume des boîtes présentes) ----
// L'unité physique est la BOÎTE. Un niveau a une empreinte au sol (L×l) et une hauteur ;
// chaque boîte présente consomme une empreinte (sa L×l) sur une couche, et s'empile selon
// la hauteur. On raisonne en "empreinte au sol disponible par couche" pour gérer des boîtes
// de types différents dans un même niveau (occupation volumétrique réaliste).
//
// Modèle de placement (sur une production p) :
//   p.emplacement (équipement), p.niveauNom/niveauIndex (niveau), p.boiteNom, p.nbBoites
// Un lot peut occuper plusieurs boîtes (p.nbBoites). Le nb de macarons est porté par qteRestante.

// Surface d'empreinte au sol d'un niveau (cm²).
function levelFloorArea(lv){ return (+lv.L||0)*(+lv.l||0); }
// Empreinte au sol d'une boîte (cm²).
function boxFloorArea(box){ return (+box.L||0)*(+box.l||0); }
// Nombre de couches qu'un niveau peut empiler pour une hauteur de boîte donnée.
function levelLayersForHeight(lv, boxH){
  const eh=+lv.h||0; if(eh<=0||boxH<=0) return 0;
  return (lv.mode==='clayette') ? (boxH<=eh?1:0) : Math.floor(eh/boxH);
}
// Calcule l'occupation d'un niveau à partir des placements présents.
// placements = [{box, nbBoites, nbMacarons}] (box = objet boîte avec dimensions).
// Retourne {capaciteEmpreinte, empreinteUtilisee, tauxVolume, nbBoites, nbMacarons, plein:bool, reste}.
function levelOccupancy(lv, placements){
  const aireNiveau = levelFloorArea(lv);
  if(aireNiveau<=0) return null;
  // Capacité de référence : on mesure la surface "couche au sol" disponible, multipliée par
  // le nb de couches MOYEN pondéré n'a pas de sens (hauteurs de boîtes variables). On raisonne
  // donc en surface-couche : chaque boîte consomme (empreinte / nbCouchesPossibles pour SA hauteur).
  // Concrètement : une boîte haute "coûte" plus cher qu'une boîte basse à empreinte égale.
  let empreintePondereeUtilisee = 0;   // somme des (empreinte boîte / couches possibles)
  let nbBoites = 0, nbMacarons = 0;
  (placements||[]).forEach(pl=>{
    const box=pl.box; if(!box) return;
    const nb=Math.max(0, +pl.nbBoites||0);
    const couches = levelLayersForHeight(lv, +box.h||0) || 1;
    const coutUneBoite = boxFloorArea(box) / couches;  // surface-sol équivalente par boîte empilée
    empreintePondereeUtilisee += coutUneBoite * nb;
    nbBoites += nb;
    nbMacarons += Math.max(0, +pl.nbMacarons||0);
  });
  const tauxVolume = aireNiveau>0 ? Math.min(1, empreintePondereeUtilisee/aireNiveau) : 1;
  const resteSurface = Math.max(0, aireNiveau - empreintePondereeUtilisee);
  return {
    capaciteEmpreinte: aireNiveau,
    empreinteUtilisee: empreintePondereeUtilisee,
    tauxVolume,
    nbBoites, nbMacarons,
    plein: tauxVolume>=0.999,
    resteSurface
  };
}
// Une boîte (avec sa hauteur) tient-elle ENCORE dans le niveau compte tenu de l'occupation ?
function levelCanFit(lv, occ, box){
  if(!box) return false;
  const couches = levelLayersForHeight(lv, +box.h||0);
  if(couches<=0) return false; // trop haute pour ce niveau
  const coutUneBoite = boxFloorArea(box) / couches;
  const reste = lv ? (levelFloorArea(lv) - (occ?occ.empreinteUtilisee:0)) : 0;
  return reste >= coutUneBoite - 0.01;
}
// Regroupe tous les placements existants par équipement+niveau, à partir des productions.
// Retourne une Map "equipKey|niveauNom" -> [{box, nbBoites, nbMacarons, prodId, lot}].
function buildPlacementsMap(prods, boxesByNom){
  const map = new Map();
  (prods||[]).forEach(p=>{
    if(!p.emplacement || !p.niveauNom || round3(+p.qteRestante)<=0) return;
    const box = boxesByNom[p.boiteNom]; if(!box) return;
    const key = p.emplacement+'|'+p.niveauNom;
    if(!map.has(key)) map.set(key, []);
    map.get(key).push({ box, nbBoites:Math.max(1,+p.nbBoites||1), nbMacarons:round3(+p.qteRestante), prodId:p.id, lot:p.lotProduction });
  });
  return map;
}

// Construit les segments colorés (par parfum) d'un niveau pour la jauge d'occupation.
// placements : liste issue de buildPlacementsMap ; prodParfum : Map prodId -> parfum.
// Retourne {taux, segments:[{parfum, color, part, nbMacarons}]} où part = fraction du REMPLISSAGE.
function levelFlavorSegments(lv, placements, prodParfum){
  const occ = levelOccupancy(lv, placements);
  if(!occ) return {taux:0, segments:[], nbMacarons:0};
  // empreinte pondérée par parfum (même logique que levelOccupancy, mais ventilée)
  const parParfum = {};
  (placements||[]).forEach(pl=>{
    const box=pl.box; if(!box) return;
    const couches = levelLayersForHeight(lv, +box.h||0) || 1;
    const cout = (boxFloorArea(box)/couches) * Math.max(0,+pl.nbBoites||0);
    const parfum = (prodParfum && prodParfum.get(pl.prodId)) || '(?)';
    if(!parParfum[parfum]) parParfum[parfum]={parfum, emp:0, nbMacarons:0};
    parParfum[parfum].emp += cout;
    parParfum[parfum].nbMacarons += Math.max(0,+pl.nbMacarons||0);
  });
  const aire = levelFloorArea(lv)||1;
  const segments = Object.values(parParfum).map(s=>({
    parfum:s.parfum, color:flavorColor(s.parfum),
    part: s.emp/aire,            // fraction de la surface totale du niveau
    nbMacarons: s.nbMacarons
  })).sort((a,b)=>b.part-a.part);
  return {taux:occ.tauxVolume, segments, nbMacarons:occ.nbMacarons};
}

// Sert à juger la "durée de stockage prévue" d'un lot : un parfum très demandé bientôt
// doit être rangé accessible (sortie rapide) ; un parfum sans demande proche peut dormir
// en réserve profonde. S'appuie sur buildUnifiedNeeds (commandes fermes datées + vélocité).
async function computeDemandeProche(opts){
  opts = opts || {};
  const seuilJours = opts.seuilJours!=null ? opts.seuilJours : 3; // "imminent" = sous 3 jours
  const map = new Map();
  let needs=[];
  try{ needs = await buildUnifiedNeeds({horizon:opts.horizon||14}); }catch(e){ return map; }
  (needs||[]).forEach(n=>{
    const nom = n.parfum || n.nom; if(!nom) return;
    const qte = +n.besoin||0;
    const echeance = n.echeance || null;
    const joursAvant = echeance ? daysTo(echeance) : null;
    const estCommande = (n.type==='commande');
    const urgent = estCommande && joursAvant!=null && joursAvant<=seuilJours;
    map.set(aiNormalize(nom), {qte, echeance, joursAvant, urgent, type:n.type||'flux'});
  });
  return map;
}
function demandeProchePour(map, parfum){
  if(!map || !parfum) return {qte:0, joursAvant:null, urgent:false, type:'flux'};
  return map.get(aiNormalize(parfum)) || {qte:0, joursAvant:null, urgent:false, type:'flux'};
}

// Logique de priorité validée : thermique → rôle → accès → capacité.
// thermique : un lot congelé (emplacement A/B/C ou destiné au froid négatif) va en réserve/standard
//   des congélateurs ; un lot en maturation (à maturer après) ou réfrigéré va en transit (F).
// Score d'accès : facile=0, moyenne=1, difficile=2 (plus c'est petit, mieux c'est).
const ACCES_SCORE = {facile:0, moyenne:1, difficile:2};
// Choisit la boîte la plus adaptée pour ranger `nb` macarons d'un format donné.
// Préfère la plus petite boîte dont la capacité couvre le lot ; sinon la plus grande dispo.
function suggestBox(boxes, nb, grandFormat){
  const capOf = b => grandFormat ? (+b.capaciteGF||0) : (+b.capacite||0);
  const utilisables = boxes.filter(b=>capOf(b)>0 && (+b.stockVide||0)>0);
  if(!utilisables.length) return null;
  // boîtes dont une seule suffit, triées par capacité croissante (la plus juste)
  const suffisantes = utilisables.filter(b=>capOf(b)>=nb).sort((a,b)=>capOf(a)-capOf(b));
  if(suffisantes.length) return suffisantes[0];
  // sinon la plus grande capacité dispo (il en faudra plusieurs)
  return utilisables.sort((a,b)=>capOf(b)-capOf(a))[0];
}
// Suggère le meilleur niveau pour un lot. ctx = {congele:bool, aMaturer:bool, nb, grandFormat}.
// Retourne {equipKey, nivIndex, niveau, score} ou null.
// ---- SCORE FUSIONNÉ : place (occupation réelle) + accès + flux, pondéré par la DEMANDE ----
// occMap : Map "equipKey|niveauNom" -> occupation (levelOccupancy) déjà calculée.
// demande : {urgent, joursAvant, qte} pour ce parfum (sortie imminente ?).
// Retourne la liste TRIÉE des candidats avec le détail du score (pour transparence/simulation).
function suggestLevelSmart(specsMap, box, ctx, occMap, demande){
  if(!box) return {best:null, candidates:[]};
  demande = demande || {urgent:false, joursAvant:null, qte:0};
  // "sort vite" = commande imminente OU une bonne part du lot est déjà demandée
  const ratioDemande = ctx.nb>0 ? (demande.qte/ctx.nb) : 0;
  const sortVite = !!demande.urgent || ratioDemande>=0.4;
  // Pondérations (validées en simulation) : si ça sort vite, l'accès prime ; sinon flux + économie de place.
  const wAcces = sortVite ? 3.0 : 1.0;
  const wFlux  = 2.0;
  const wPlace = sortVite ? 1.0 : 3.0; // en réserve longue, économiser la place premium compte davantage
  const candidates = [];
  for(const e of EMPLACEMENTS){
    const spec = specsMap[e.key]; if(!spec || !Array.isArray(spec.niveaux)) continue;
    const estFroidPositif = (e.type==='frigo');
    if(ctx.congele && estFroidPositif) continue;
    if(ctx.aMaturer && !estFroidPositif) continue;
    if(ctx.congelObligatoire && estFroidPositif) continue;
    spec.niveaux.forEach((lv,i)=>{
      if(lv.reserve) return;
      // 1) Est-ce que ça RENTRE (volumétrie + occupation réelle) ?
      const occ = (occMap && occMap.get(e.key+'|'+(lv.nom||('niveau '+(i+1))))) || null;
      const cap = levelCapacityForBox(lv, box);
      if(!cap || cap.nbBoites<=0) return;          // boîte incompatible avec ce niveau
      if(occ && !levelCanFit(lv, occ, box)) return; // plein → éliminé
      const tauxRempli = occ ? occ.tauxVolume : 0;
      // 2) FLUX (rôle adapté à la durée prévue)
      const role = NIV_ROLES[nivRole(lv)] ? nivRole(lv) : 'standard';
      let fluxScore;
      if(sortVite)         fluxScore = (role==='transit')?0:(role==='standard'?1:2);
      else if(ctx.aMaturer)fluxScore = (role==='transit')?0:(role==='standard'?1:2);
      else                 fluxScore = (role==='reserve')?0:(role==='standard'?1:2);
      // 3) ACCÈS
      const accesScore = ACCES_SCORE[nivAcces(lv)] ?? 1;
      // 4) PLACE : pénalise les niveaux déjà bien remplis (0 vide … 1 presque plein)
      const placeScore = tauxRempli;
      const score = wAcces*accesScore + wFlux*fluxScore + wPlace*placeScore*2;
      candidates.push({
        equipKey:e.key, nivIndex:i, niveau:lv, score,
        capBoites:cap.nbBoites, tauxRempli, accesScore, fluxScore, role, sortVite,
        acces:nivAcces(lv)
      });
    });
  }
  candidates.sort((a,b)=>a.score-b.score);
  return {best:candidates[0]||null, candidates, sortVite};
}
// ---- SCINDAGE : répartir un batch sur plusieurs niveaux quand il ne tient pas en un seul ----
// Place le maximum au meilleur niveau, puis le reste au suivant, etc. (capacité = nb boîtes × macarons/boîte).
// Retourne {parts:[{equipKey,nivIndex,niveauNom,nbMacarons,nbBoites}], reste, complet:bool}.
function splitPlacement(specsMap, box, ctx, occMap, demande){
  const capParMacaron = ctx.grandFormat ? (+box.capaciteGF||0) : (+box.capacite||0);
  if(capParMacaron<=0) return {parts:[], reste:ctx.nb, complet:false};
  let reste = ctx.nb;
  const parts = [];
  // copie locale de l'occupation pour la décrémenter au fur et à mesure
  const occLocal = new Map(); if(occMap) occMap.forEach((v,k)=>occLocal.set(k,Object.assign({},v)));
  let garde = 0;
  while(reste>0 && garde<20){
    garde++;
    const smart = suggestLevelSmart(specsMap, box, {...ctx, nb:reste}, occLocal, demande);
    const best = smart.best; if(!best) break; // plus aucun niveau ne rentre
    const lv = best.niveau;
    const cap = levelCapacityForBox(lv, box); // {nbBoites}
    if(!cap || cap.nbBoites<=0) break;
    // combien de boîtes peut-on encore mettre vu l'occupation réelle
    const key = best.equipKey+'|'+(lv.nom||'');
    const occ = occLocal.get(key);
    let boitesLibres = cap.nbBoites;
    if(occ){
      const surfNiv = levelFloorArea(lv);
      const couches = levelLayersForHeight(lv, +box.h||0)||1;
      const coutBoite = boxFloorArea(box)/couches;
      const resteSurf = surfNiv - (occ.empreinteUtilisee||0);
      boitesLibres = Math.max(0, Math.min(cap.nbBoites, Math.floor(resteSurf/coutBoite + 0.01)));
    }
    if(boitesLibres<=0){
      // niveau plein : on le neutralise pour la prochaine itération
      occLocal.set(key, {empreinteUtilisee: levelFloorArea(lv), tauxVolume:1, plein:true});
      continue;
    }
    const capaciteNiveau = boitesLibres * capParMacaron;
    const aPoser = Math.min(reste, capaciteNiveau);
    const boitesUtilisees = Math.ceil(aPoser/capParMacaron);
    parts.push({equipKey:best.equipKey, nivIndex:best.nivIndex, niveauNom:lv.nom||'',
      nbMacarons:aPoser, nbBoites:boitesUtilisees, boiteNom:box.nom});
    reste -= aPoser;
    // décrémente l'occupation locale pour ne pas re-remplir le même niveau
    const couches = levelLayersForHeight(lv, +box.h||0)||1;
    const coutBoite = boxFloorArea(box)/couches;
    const prevEmp = occ ? (occ.empreinteUtilisee||0) : 0;
    occLocal.set(key, {empreinteUtilisee: prevEmp + boitesUtilisees*coutBoite,
      tauxVolume: Math.min(1,(prevEmp + boitesUtilisees*coutBoite)/levelFloorArea(lv))});
  }
  return {parts, reste, complet: reste<=0};
}
function lotPlacementCtx(p, recipe){
  const totalLot = round3(+p.qteRestante||0);
  // [RANGEMENT PARTIEL] Si le lot a déjà des pièces placées (placements) mais n'est pas
  // entièrement rangé, on ne propose au rangement que le RESTE non encore placé.
  let dejaPlace = 0;
  if(!p.rangee && Array.isArray(p.placements) && p.placements.length){
    dejaPlace = round3(p.placements.reduce((s,pl)=>s+(+pl.nbMacarons||0),0));
  }
  const nb = round3(Math.max(0, totalLot - dejaPlace));
  const grandFormat = !!(recipe && recipe.grandFormat);
  const congelObligatoire = !!(recipe && recipe.congelObligatoire);
  const aMaturer = prodMaturation(p)==='apres'; // doit passer par F
  // congelé par défaut si déjà au congélo, sans emplacement, ou si la recette l'impose
  let congele = isFreezer(p.emplacement) || (!p.emplacement) || congelObligatoire;
  // une recette à congélateur obligatoire prime : pas de maturation frigo imposée
  const aMaturerEff = congelObligatoire ? false : aMaturer;
  // Unité d'affichage selon le composant : un sous-lot coques se compte en COQUES, une
  // garniture en doses, un produit fini ou complet en macarons. Évite d'écrire « macaron »
  // là où l'on manipule en réalité des coques.
  const comp = p.composant||'complet';
  const unite = comp==='coques' ? 'coque' : ((comp==='ganache'||comp==='cremeux') ? 'dose' : 'macaron');
  return {nb, grandFormat, congele: aMaturerEff?false:congele, aMaturer:aMaturerEff, congelObligatoire, unite, composant:comp, dejaPlace, totalLot};
}
// ===================== RANGEMENT GUIDÉ — MOTEUR DU PLAN GLOBAL (étape 1) =====================
// Orchestrateur : pour tous les lots en attente, calcule un plan de placement complet en
// réutilisant le moteur existant (lotPlacementCtx, suggestBox, splitPlacement, occupation,
// demande proche pour le picking). Accumule l'occupation d'un lot au suivant pour ne pas
// sur-remplir un même niveau. Regroupe le résultat PAR EMPLACEMENT (vue cible).
//
// Sortie : {
//   parEmplacement: [ { equipKey, equipNom, equipIcon, equipType,
//                       niveaux: [ { nivIndex, niveauNom, role, acces,
//                                    instructions: [ { prodId, nom, fab, qte, boiteNom, nbBoites,
//                                                      pourquoi, sortVite, congele } ] } ] } ],
//   nonPlaces: [ { prodId, nom, qte, raison } ],
//   totalLots, totalPieces
// }

async function buildPlanRangementGlobal(){
  const specsMap = await equipGetSpecs();
  const boxes = await db.storageBoxes.toArray().catch(()=>[]);
  const recipes = await db.recipes.toArray().catch(()=>[]);
  window._allRecipesCache = recipes;
  const recById = {}; recipes.forEach(r=>recById[+r.id]=r);
  const allProds = await db.productions.toArray().catch(()=>[]);

  // Lots EN ATTENTE de rangement = terminés, non rangés, avec du reste non placé.
  const enAttente = allProds.filter(p=>{
    const st = (typeof prodStatut==='function') ? prodStatut(p) : 'termine';
    if(st!=='termine' || p.rangee) return false;
    const ctx = lotPlacementCtx(p, recById[+p.recipeId]);
    return ctx.nb > 0;
  });

  // Occupation réelle de départ (placements existants).
  const boxesByNom = {}; boxes.forEach(b=>{ boxesByNom[b.nom]=b; });
  const placements = buildPlacementsMap(allProds, boxesByNom);
  const occMap = new Map();
  for(const e of EMPLACEMENTS){
    const spec=specsMap[e.key]; if(!spec||!Array.isArray(spec.niveaux)) continue;
    spec.niveaux.forEach((lv,i)=>{
      const key=e.key+'|'+(lv.nom||('niveau '+(i+1)));
      const occ=levelOccupancy(lv, placements.get(key)||[]);
      if(occ) occMap.set(key, occ);
    });
  }

  // Demande proche (picking) une seule fois.
  let demandeMap = {};
  try{ demandeMap = await computeDemandeProche({}); }catch(e){ demandeMap = {}; }

  // Tri des lots : ceux qui SORTENT VITE d'abord (ils prennent les meilleures places).
  const withDemande = enAttente.map(p=>{
    const recipe = recById[+p.recipeId];
    const ctx = lotPlacementCtx(p, recipe);
    const dem = (recipe && typeof demandeProchePour==='function')
      ? demandeProchePour(demandeMap, recipe.produitNom) : {urgent:false, qte:0, joursAvant:null};
    return {p, recipe, ctx, dem};
  });
  withDemande.sort((a,b)=>{
    const ua = a.dem.urgent?0:1, ub = b.dem.urgent?0:1;
    if(ua!==ub) return ua-ub;
    const ja = a.dem.joursAvant==null?9999:a.dem.joursAvant;
    const jb = b.dem.joursAvant==null?9999:b.dem.joursAvant;
    return ja-jb;
  });

  // accumulateur de plan par clé d'emplacement+niveau
  const planByKey = new Map(); // key -> { equipKey, nivIndex, niveauNom, instructions:[] }
  const nonPlaces = [];

  for(const item of withDemande){
    const {p, recipe, ctx, dem} = item;
    // Priorité de choix de boîte : (1) override manuel en cours, (2) boîte préférée
    // mémorisée d'un rangement précédent, (3) reco de l'algorithme. Aucune n'est verrouillée :
    // l'utilisateur peut toujours changer via « changer ».
    const override = (window._rangBoxOverride||{})[p.id];
    let box = override ? boxes.find(b=>b.nom===override) : null;
    let boxSource = box ? 'override' : null;
    if(!box && p.boitePreferee){ box = boxes.find(b=>b.nom===p.boitePreferee); if(box) boxSource='preferee'; }
    if(!box){ box = (typeof suggestBox==='function') ? suggestBox(boxes, ctx.nb, ctx.grandFormat) : (boxes[0]||null); boxSource='algo'; }
    if(!box){ nonPlaces.push({prodId:p.id, nom:prodNomEpure(p,recipes), qte:ctx.nb, raison:'aucune boîte'}); continue; }

    const res = splitPlacement(specsMap, box, ctx, occMap, dem);
    if(!res.parts.length){
      nonPlaces.push({prodId:p.id, nom:prodNomEpure(p,recipes), qte:ctx.nb, raison:'pas de place'});
      continue;
    }

    const ratio = ctx.nb>0 ? (dem.qte/ctx.nb) : 0;
    const sortVite = !!dem.urgent || ratio>=0.4;
    const nom = prodNomEpure(p, recipes);
    const fab = (typeof prodFabCourt==='function') ? prodFabCourt(p) : '';

    res.parts.forEach(part=>{
      const key = part.equipKey+'|'+(part.niveauNom||('niveau '+(part.nivIndex+1)));
      if(!planByKey.has(key)) planByKey.set(key, {equipKey:part.equipKey, nivIndex:part.nivIndex, niveauNom:part.niveauNom, instructions:[]});
      planByKey.get(key).instructions.push({
        prodId:p.id, nom, fab, qte:part.nbMacarons, boiteNom:part.boiteNom, nbBoites:part.nbBoites,
        sortVite, congele:!!ctx.congele, boxSource,
        pourquoi: _rangementPourquoi(part, ctx, dem, sortVite)
      });
    });

    // met à jour occMap pour le lot suivant (déjà fait dans splitPlacement en local, mais on
    // doit le répercuter ici pour la persistance entre lots).
    res.parts.forEach(part=>{
      const key = part.equipKey+'|'+(part.niveauNom||('niveau '+(part.nivIndex+1)));
      const spec = specsMap[part.equipKey];
      const lv = spec && spec.niveaux ? spec.niveaux[part.nivIndex] : null;
      if(!lv) return;
      const box2 = box;
      const couches = (typeof levelLayersForHeight==='function') ? (levelLayersForHeight(lv, +box2.h||0)||1) : 1;
      const coutBoite = (typeof boxFloorArea==='function') ? boxFloorArea(box2)/couches : 0;
      const prev = occMap.get(key) || {empreinteUtilisee:0, tauxVolume:0};
      const newEmp = (prev.empreinteUtilisee||0) + (part.nbBoites||0)*coutBoite;
      const aire = (typeof levelFloorArea==='function') ? levelFloorArea(lv) : 1;
      occMap.set(key, {empreinteUtilisee:newEmp, tauxVolume: Math.min(1, aire>0?newEmp/aire:0)});
    });
  }

  // Regroupe par emplacement, dans l'ordre des EMPLACEMENTS, niveaux dans l'ordre.
  const parEmplacement = [];
  let totalPieces=0; const lotsVus=new Set();
  for(const e of EMPLACEMENTS){
    const spec=specsMap[e.key]; if(!spec||!Array.isArray(spec.niveaux)) continue;
    const niveaux=[];
    spec.niveaux.forEach((lv,i)=>{
      const key=e.key+'|'+(lv.nom||('niveau '+(i+1)));
      const entry=planByKey.get(key);
      if(!entry || !entry.instructions.length) return;
      entry.instructions.forEach(ins=>{ totalPieces+=ins.qte; lotsVus.add(ins.prodId); });
      niveaux.push({
        nivIndex:i, niveauNom:lv.nom||('niveau '+(i+1)),
        role:(typeof nivRole==='function')?nivRole(lv):'standard',
        acces:(typeof nivAcces==='function')?nivAcces(lv):'facile',
        instructions:entry.instructions
      });
    });
    if(niveaux.length){
      parEmplacement.push({
        equipKey:e.key, equipNom:e.nom, equipIcon:e.icon, equipType:e.type, niveaux
      });
    }
  }

  return {
    parEmplacement, nonPlaces,
    totalLots: lotsVus.size, totalPieces
  };
}

// Construit la phrase « pourquoi » d'une instruction (transparence du raisonnement).
function _rangementPourquoi(part, ctx, dem, sortVite){
  if(ctx.congele) return 'Surplus / réserve longue → congélateur';
  if(sortVite){
    if(dem.urgent) return 'Commande imminente → à portée de main';
    if(dem.joursAvant!=null) return `Sort dans ${dem.joursAvant} j → accessible`;
    return 'Part demandée → accessible';
  }
  return 'Pas de commande proche → range plus profond';
}
// =============================================================================

// ===================== RANGEMENT GUIDÉ — ÉCRAN (étape 2) =====================
// Affiche le plan global (buildPlanRangementGlobal) en vue par emplacement, avec check-list
// à cocher et progression. À ce stade : cocher est visuel (mémoire de session). L'application
// réelle des emplacements arrivera à l'étape 4.

let _rangPlan = null;        // plan calculé
let _rangDone = new Set();   // clés d'instructions cochées (prodId|equipKey|nivIndex)

function _rangInsKey(ins, equipKey, nivIndex){ return ins.prodId+'|'+equipKey+'|'+nivIndex; }

async function renderRangementGuide(){
  const main=document.getElementById('main'); if(!main) return;
  main.innerHTML = `<div class="rg-wrap"><div class="rg-head"><h1 class="rg-title">Rangement guidé</h1>
    <div class="rg-sub">Calcul du plan…</div></div><div class="rg-loading">⏳ L'app répartit tes lots…</div></div>`;

  let plan;
  try{ plan = await buildPlanRangementGlobal(); }
  catch(e){ main.innerHTML = `<div class="rg-wrap"><p class="note">Impossible de calculer le plan : ${esc(e.message||'erreur')}</p></div>`; return; }
  _rangPlan = plan;

  if(!plan.parEmplacement.length){
    const undoBtn = (_rangSnapshot && _rangSnapshot.length)
      ? `<button class="rg-undo-perm" onclick="rangUndoAll()">↩ Annuler le dernier rangement (${_rangSnapshot.length} lot${_rangSnapshot.length>1?'s':''})</button>` : '';
    main.innerHTML = `<div class="rg-wrap"><div class="rg-head"><h1 class="rg-title">Rangement guidé</h1></div>
      <div class="rg-empty"><span class="ic">✓</span>${_rangSnapshot&&_rangSnapshot.length?'Rangement effectué !':'Rien à ranger pour le moment.'}<br>${_rangSnapshot&&_rangSnapshot.length?'Tu peux encore tout annuler ci-dessous.':'Les lots fraîchement produits apparaîtront ici à ranger.'}</div>${undoBtn}</div>`;
    return;
  }

  // total d'instructions (pour la progression)
  let totalIns=0;
  plan.parEmplacement.forEach(e=>e.niveaux.forEach(n=>totalIns+=n.instructions.length));

  const blocs = plan.parEmplacement.map(e=>{
    const cls = e.equipType==='frigo' ? 'frigo' : 'congel';
    let nbIns=0, nbP=0;
    e.niveaux.forEach(n=>n.instructions.forEach(i=>{nbIns++;nbP+=i.qte;}));
    const niveaux = e.niveaux.map(n=>{
      const role = NIV_ROLES[n.role]||NIV_ROLES.standard;
      const acc = NIV_ACCES[n.acces]||NIV_ACCES.facile;
      const tagRole = n.role!=='standard' ? `<span class="rg-tag tag-${n.role}">${role.ico} ${esc(role.label.toLowerCase())}</span>` : '';
      const lignes = n.instructions.map(ins=>{
        const key=_rangInsKey(ins,e.equipKey,n.nivIndex);
        const done=_rangDone.has(key);
        const col=(typeof flavorColor==='function')?flavorColor(ins.nom):'#cbb89f';
        const whyCls = ins.congele||!ins.sortVite ? 'surplus' : '';
        return `<div class="rg-instr ${done?'done':''}" onclick="rangToggle('${key}')">
          <div class="rg-check">✓</div>
          <div class="rg-instr-main">
            <div class="rg-instr-l1"><span class="rg-stage" style="background:${col}"></span>${qty(ins.qte)} ${esc(ins.nom.toLowerCase())} · ${esc(ins.fab)}${ins.congele?' <span class="rg-snow">❄️ à congeler</span>':''}</div>
            <div class="rg-instr-box">${esc(ins.boiteNom)}${ins.nbBoites>1?` ×${ins.nbBoites}`:''}${ins.boxSource==='preferee'?' <span class="rg-pref">↩ ton choix</span>':''} <span class="rg-chg" onclick="event.stopPropagation();rangChangeBox('${key}')">changer ›</span></div>
            <div class="rg-instr-why ${whyCls}">${esc(ins.pourquoi)}</div>
          </div>
        </div>`;
      }).join('');
      return `<div class="rg-niv">
        <div class="rg-niv-h"><span class="rg-niv-nom">${esc(n.niveauNom)}</span>
          <span class="rg-tag tag-${n.acces}">${acc.ico} accès ${esc(acc.label.toLowerCase())}</span>${tagRole}</div>
        ${lignes}</div>`;
    }).join('');
    return `<div class="rg-equip">
      <div class="rg-equip-h ${cls}"><span class="rg-e-ic">${e.equipIcon}</span>
        <span class="rg-e-nom">${esc(e.equipNom)}</span>
        <span class="rg-e-tot">${nbIns} instruction${nbIns>1?'s':''} · ${qty(nbP)} pièces</span></div>
      ${niveaux}</div>`;
  }).join('');

  // lots non plaçables
  const nonP = (plan.nonPlaces&&plan.nonPlaces.length) ? `<div class="rg-nonplace">
    <b>⚠️ ${plan.nonPlaces.length} lot${plan.nonPlaces.length>1?'s':''} sans place trouvée :</b>
    ${plan.nonPlaces.map(x=>`<div>· ${qty(x.qte)} ${esc(x.nom.toLowerCase())} <span class="note">(${esc(x.raison)})</span></div>`).join('')}
    <div class="note" style="margin-top:4px">Libère de la place ou range-les manuellement.</div></div>` : '';

  main.innerHTML = `<div class="rg-wrap">
    <div class="rg-head"><h1 class="rg-title">Rangement guidé</h1>
      <div class="rg-sub">Un plan complet, prêt à suivre</div></div>
    <div class="rg-intro">L'app a réparti <b>${plan.totalLots} lot${plan.totalLots>1?'s':''}</b> selon la place réelle, la fraîcheur et ce qui <b>part bientôt</b>. Suis les instructions, coche au fur et à mesure.</div>
    ${blocs}
    ${nonP}
    <div class="rg-spacer"></div>
  </div>
  <div class="rg-bar" id="rgBar">
    <div class="rg-bar-in">
      <div class="rg-prog"><div class="rg-prog-f" id="rgProgF"></div></div>
      <span class="rg-prog-txt" id="rgProgT">0 / ${totalIns} rangé</span>
    </div>
    <button class="rg-btn-done" onclick="rangFinish()">✓ Tout est rangé</button>
    ${(_rangSnapshot && _rangSnapshot.length) ? `<button class="rg-undo-perm" onclick="rangUndoAll()">↩ Annuler le dernier rangement (${_rangSnapshot.length} lot${_rangSnapshot.length>1?'s':''})</button>` : ''}
  </div>`;
  rangUpdateProgress();
}

function rangToggle(key){
  if(_rangDone.has(key)) _rangDone.delete(key); else _rangDone.add(key);
  // bascule visuelle sans tout re-render
  const main=document.getElementById('main');
  renderRangementGuide();   // simple et sûr à ce stade ; optimisable plus tard
}

function rangUpdateProgress(){
  if(!_rangPlan) return;
  let total=0; _rangPlan.parEmplacement.forEach(e=>e.niveaux.forEach(n=>total+=n.instructions.length));
  const done=_rangDone.size;
  const f=document.getElementById('rgProgF'), t=document.getElementById('rgProgT');
  if(f) f.style.width=(total>0?done/total*100:0)+'%';
  if(t) t.textContent=`${done} / ${total} rangé`;
}

// Étape 3 : changer la boîte d'un lot → recalcul du plan.
async function rangChangeBox(key){
  const prodId = +String(key).split('|')[0];
  const p = await db.productions.get(prodId);
  if(!p){ toast('Lot introuvable'); return; }
  const boxes = await db.storageBoxes.toArray().catch(()=>[]);
  const recipe = p.recipeId ? await db.recipes.get(p.recipeId).catch(()=>null) : null;
  const ctx = lotPlacementCtx(p, recipe);
  const gf = ctx.grandFormat;
  const capOf = b => gf ? (+b.capaciteGF||0) : (+b.capacite||0);
  const q = ctx.nb;
  const nom = prodNomEpure(p, window._allRecipesCache||[]);
  const sugg = (typeof suggestBox==='function') ? suggestBox(boxes, q, gf) : null;
  const courant = (window._rangBoxOverride||{})[prodId] || (sugg?sugg.nom:null);

  // boîtes assez grandes (la part tient si possible), triées par capacité croissante
  let elig = boxes.filter(b=>capOf(b)>0).sort((a,b)=>capOf(a)-capOf(b));
  // la boîte préférée d'abord (sans retirer les autres : souplesse maximale)
  if(p.boitePreferee){ elig = elig.slice().sort((a,b)=>(b.nom===p.boitePreferee?1:0)-(a.nom===p.boitePreferee?1:0)); }
  const opts = elig.map(b=>{
    const cap=capOf(b);
    const sel = b.nom===courant;
    const recommande = sugg && b.nom===sugg.nom;
    const prefere = p.boitePreferee && b.nom===p.boitePreferee;
    const tient = cap>=q;
    const nbB = tient ? 1 : Math.ceil(q/cap);
    const tags = [];
    if(prefere) tags.push('↩ ton choix précédent');
    if(recommande) tags.push('recommandée');
    return `<div class="rg-box-opt ${sel?'sel':''}" onclick="rangPickBox(${prodId},${JSON.stringify(b.nom).replace(/\"/g,'&quot;')})">
      <b>${esc(b.nom)}</b>
      <small>${cap} ${gf?'GF':'pièces'}${tient?'':` · ×${nbB} boîtes`}${tags.length?' · '+tags.join(' · '):''}</small>
    </div>`;
  }).join('');

  openModal(`<h3>Changer la boîte</h3>
    <p class="note" style="margin-bottom:10px">Pour ${qty(q)} ${esc(nom.toLowerCase())} — l'app recalcule l'emplacement selon ton choix.</p>
    <div class="rg-box-list">${opts}</div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Fermer</button></div>`);
}

// Choix d'une boîte → mémorise l'override et recalcule le plan.
async function rangPickBox(prodId, nom){
  window._rangBoxOverride = window._rangBoxOverride || {};
  window._rangBoxOverride[prodId] = nom;
  closeModal();
  await renderRangementGuide();
  toast('Boîte changée · plan recalculé');
}
// ===================== RANGEMENT GUIDÉ — APPLICATION DU PLAN (étape 4) =====================
// Applique le plan calculé aux vrais enregistrements, lot par lot, en réutilisant
// doMoveEmplacement (règles froid/DLC/lot) + le format placements existant. Capture un
// snapshot AVANT écriture pour permettre l'annulation (restauration fidèle).

let _rangSnapshot = null;   // [{id, before:{...champs}}] pour annuler

// Regroupe les parts du plan PAR LOT (un lot peut avoir plusieurs parts sur plusieurs niveaux).
function _rangPartsParLot(plan){
  const parLot = new Map(); // prodId -> { equipKey (1er), placements:[{equipKey,niveauNom,boiteNom,nbMacarons}] }
  plan.parEmplacement.forEach(e=>{
    e.niveaux.forEach(n=>{
      n.instructions.forEach(ins=>{
        if(!parLot.has(ins.prodId)) parLot.set(ins.prodId, {prodId:ins.prodId, equipKey:e.equipKey, placements:[]});
        parLot.get(ins.prodId).placements.push({
          equipKey:e.equipKey, niveauNom:n.niveauNom, nivIndex:n.nivIndex,
          boiteNom:ins.boiteNom, nbMacarons:ins.qte
        });
      });
    });
  });
  return parLot;
}

// Capture l'état actuel d'un lot (pour annulation).
function _rangSnapLot(p){
  return {
    id:p.id,
    emplacement:p.emplacement, emplacementMaj:p.emplacementMaj,
    histEmplacement:p.histEmplacement ? JSON.parse(JSON.stringify(p.histEmplacement)) : undefined,
    lotProduction:p.lotProduction,
    qteRestante:p.qteRestante,
    placements:p.placements ? JSON.parse(JSON.stringify(p.placements)) : undefined,
    niveauIndex:p.niveauIndex, niveauNom:p.niveauNom, boiteNom:p.boiteNom,
    rangee:p.rangee, rangeeTs:p.rangeeTs,
    dlcProduit:p.dlcProduit, dlcAuto:p.dlcAuto,
    venuDuCongelateur:p.venuDuCongelateur
  };
}

// Applique le plan. Retourne {ok, applied, failed:[{prodId,nom,raison}]}.
// [v1389] ROUTÉ vers le moteur unique. Ce plan (« Rangement guidé », système D) n'écrit PLUS
// placements lui-même : chaque lot du plan est confié à `rangerLot` (→ prodPreparerBoites), qui
// scinde en lignes-filles -B1/-B2, déplace via doMoveEmplacement et recalcule les DLC. Décision
// Ben (Voie 2) : il range souvent un lot en plusieurs boîtes → chaque placement du plan devient
// UNE boîte { qte, destination }. Les listes replient ensuite les boîtes d'un même lot (affichage
// seul, cf renderProductions). L'undo capture les lignes-filles CRÉÉES (à supprimer au rollback)
// plutôt qu'un patch de champs placements qui n'existe plus.
async function applyPlanRangement(plan){
  const parLot = _rangPartsParLot(plan);
  const snapshot = [];
  const failed = [];
  let applied = 0;

  for(const [prodId, info] of parLot){
    const p = await db.productions.get(prodId);
    if(!p){ failed.push({prodId, raison:'lot introuvable'}); continue; }

    // Traduit les placements du plan en boîtes { qte, destination } — le vocabulaire du moteur.
    // La destination d'une boîte = son équipement cible (equipKey) ; le niveau/nom de boîte du
    // plan n'est plus un champ stocké mais une suggestion d'affichage, absorbée par la scission.
    const boites = info.placements.map(pl=>({ qte: pl.nbMacarons, destination: pl.equipKey }));
    if(!boites.length){ continue; }

    // UN SEUL moteur. On simule d'abord pour capturer l'état AVANT (undo), puis on exécute.
    const res = await rangerLot(prodId, boites);
    if(!res || !res.ok){
      failed.push({prodId, raison: (res && res.raison) || 'rangement refusé (règle froid/DLC)'});
      continue;
    }
    // Undo : mémorise le lot parent (pour restaurer sa qteRestante/rangee) et les lignes-filles
    // créées (à supprimer). Le cas simple (1 boîte, même emplacement) ne crée aucune fille.
    snapshot.push({
      id: prodId,
      before: _rangSnapLot(p),
      childrenCreated: (res.boxes||[]).filter(b=>b.id!==prodId).map(b=>b.id)
    });
    applied++;
  }

  _rangSnapshot = snapshot.length ? snapshot : null;
  return {ok:failed.length===0, applied, failed, snapshotCount:snapshot.length};
}

// Annule le dernier rangement appliqué : restaure l'instantané.
// [v1389] Adapté au moteur unique : le rangement crée désormais des lignes-filles (scission),
// donc annuler = SUPPRIMER les filles créées puis RESTAURER le lot parent (qteRestante, rangee,
// emplacement…). On enveloppe dans une transaction pour que l'annulation soit tout-ou-rien.
async function undoPlanRangement(){
  if(!_rangSnapshot || !_rangSnapshot.length){ toast('Rien à annuler'); return false; }
  await db.transaction('rw', db.productions, async()=>{
    for(const snap of _rangSnapshot){
      // 1) supprime les lignes-filles créées par la scission
      for(const childId of (snap.childrenCreated||[])){
        try{ await db.productions.delete(childId); }catch(e){ swallow(e,'undoPlan child'); }
      }
      // 2) restaure le lot parent à son état d'avant rangement
      const before = snap.before;
      const patch = {
        emplacement:before.emplacement, emplacementMaj:before.emplacementMaj,
        histEmplacement:before.histEmplacement, lotProduction:before.lotProduction,
        qteRestante:before.qteRestante,
        rangee:before.rangee, rangeeTs:before.rangeeTs,
        dlcProduit:before.dlcProduit, dlcAuto:before.dlcAuto,
        venuDuCongelateur:before.venuDuCongelateur
      };
      await db.productions.update(snap.id, patch);
    }
  });
  const n=_rangSnapshot.length;
  _rangSnapshot = null;
  toast(`Rangement annulé · ${n} lot${n>1?'s':''} restauré${n>1?'s':''}`);
  return true;
}
// =============================================================================

// Annulation globale permanente : défait tout le dernier rangement (tous les lots).
async function rangUndoAll(){
  if(!_rangSnapshot || !_rangSnapshot.length){ toast('Rien à annuler'); return; }
  const n=_rangSnapshot.length;
  if(!confirm(`Annuler le dernier rangement ?\n${n} lot${n>1?'s':''} reviendront « à ranger ».`)) return;
  await undoPlanRangement();
  await renderRangementGuide();
}

// Étape 4 : confirmation récapitulative → application → filet d'annulation.
async function rangFinish(){
  if(!_rangPlan || !_rangPlan.parEmplacement.length){ toast('Aucun plan à appliquer'); return; }
  const parLot = _rangPartsParLot(_rangPlan);
  const nbLots = parLot.size;
  let nbPlacements=0, nbPieces=0;
  _rangPlan.parEmplacement.forEach(e=>e.niveaux.forEach(n=>n.instructions.forEach(i=>{nbPlacements++;nbPieces+=i.qte;})));
  // changements de boîte manuels
  const overrides = window._rangBoxOverride||{};
  const nbModifs = Object.keys(overrides).length;

  // récap par emplacement
  const recapEmp = _rangPlan.parEmplacement.map(e=>{
    let n=0,pc=0; e.niveaux.forEach(nv=>nv.instructions.forEach(i=>{n++;pc+=i.qte;}));
    return `<div style="display:flex;justify-content:space-between;font-size:.84rem;padding:4px 0;border-bottom:1px solid var(--creme,#E8DDCD)"><span>${e.equipIcon} ${esc(e.equipNom)}</span><span style="color:#7a6a60">${n} instr. · ${qty(pc)} pièces</span></div>`;
  }).join('');

  openModal(`<h3>Confirmer le rangement</h3>
    <p class="note" style="margin-bottom:10px">L'app va enregistrer les emplacements de <b>${nbLots} lot${nbLots>1?'s':''}</b> (${qty(nbPieces)} pièces, ${nbPlacements} instruction${nbPlacements>1?'s':''})${nbModifs?` · dont <b>${nbModifs} boîte${nbModifs>1?'s':''} modifiée${nbModifs>1?'s':''}</b>`:''}.</p>
    <div class="panel" style="margin-bottom:10px">${recapEmp}</div>
    <p class="note" style="font-size:.76rem;color:#7a6a60">Les règles de fraîcheur (chaîne du froid, DLC) sont respectées. Tu pourras annuler juste après.</p>
    <div class="modal-actions">
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="rangFinishGo()">✓ Confirmer et ranger</button>
    </div>`);
}

async function rangFinishGo(){
  closeModal();
  const res = await applyPlanRangement(_rangPlan);
  // réinitialise les overrides (le plan est appliqué)
  window._rangBoxOverride = {};
  _rangDone = new Set();
  if(res.failed && res.failed.length){
    const noms = res.failed.map(f=>'#'+f.prodId+' ('+f.raison+')').join(', ');
    toast(`${res.applied} rangé(s) · ${res.failed.length} refusé(s) : ${noms}`);
  } else {
    toast(`${res.applied} lot${res.applied>1?'s':''} rangé${res.applied>1?'s':''} ✓`);
  }
  // Le bouton « Annuler ce rangement » reste affiché tant que _rangSnapshot existe
  // (permanent jusqu'au prochain rangement), via renderRangementGuide.
  await renderRangementGuide();
}
// =============================================================================

// Libellé d'unité avec accord pluriel, à partir du contexte de placement (coque/dose/macaron).
function uniteLabel(ctx, n){
  const u = (ctx && ctx.unite) || 'macaron';
  const plur = Math.abs(+n||0) >= 2;
  return u + (plur ? 's' : '');
}

// ---- CATALOGUE DE COMPOSANTS RÉUTILISABLES ----
const COMPONENT_TYPES = {
  ganache:  {label:'Ganache montée', ico:'🍫'},
  coques:   {label:'Coques',          ico:'🟤'},
  insert:   {label:'Insert',          ico:'⭐'},
  autre:    {label:'Autre',           ico:'🔹'},
};
// Libellé non ambigu d'un composant : icône + type court + nom, pour ne JAMAIS
// le confondre avec un produit fini. Ex : "🍫 Ganache · vanille".
// Type court (sans "montée" etc.) pour rester lisible.
const COMPONENT_TYPE_SHORT = { ganache:'Ganache', coques:'Coques', insert:'Insert', autre:'Composant' };
function componentLabel(c){
  if(!c) return '';
  const t = COMPONENT_TYPES[c.type]||COMPONENT_TYPES.autre;
  const court = COMPONENT_TYPE_SHORT[c.type]||'Composant';
  return `${t.ico} ${court} · ${c.nom||''}`.trim();
}
async function renderComposants(){
  const main=document.getElementById('main'); if(!main) return;
  const comps = await db.components.orderBy('nom').toArray().catch(()=>[]);
  const recipes = await db.recipes.toArray().catch(()=>[]);
  // compte combien de recettes pointent chaque composant (mutualisation visible)
  const usage = {};
  recipes.forEach(r=>{ (r.componentRefs||[]).forEach(ref=>{ usage[ref.componentId]=(usage[ref.componentId]||0)+1; }); });
  const card = c => {
    const t = COMPONENT_TYPES[c.type]||COMPONENT_TYPES.autre;
    const nbRen = usage[c.id]||0;
    return `<div class="sum-box" style="flex-direction:column;align-items:stretch;gap:4px">
      <div style="display:flex;align-items:center;gap:8px">
        <span style="flex:1">${componentLabel(c)}</span>
        <button class="btn ghost sm" onclick="componentForm(${c.id})">✎</button>
      </div>
      <div style="font-size:.74rem;color:#9a8a82">Rendement : ${c.rendement||'?'} /batch${c.congelObligatoire?' · ❄️ congélation':''}${nbRen>0?` · <span style="color:#3f7d52">partagé par ${nbRen} recette(s)</span>`:' · non utilisé'}</div>
    </div>`;
  };
  main.innerHTML=`
   <div class="topbar"><div><h1>Composants</h1><p>Briques réutilisables : ganaches, crémeux, coques…</p></div>
     <button class="btn gold" onclick="componentForm(0)">+ Composant</button></div>
   <div class="banner" style="background:#eef5f0;border-color:#bcd9c6"><div>Un composant (ex : une ganache montée) existe une seule fois ici et peut être <b>partagé par plusieurs recettes</b>. C'est ce qui permet de mutualiser sa production (ex : la même ganache pour mangue passion et myrtille framboise).</div></div>
   ${comps.length?comps.map(card).join(''):'<div class="panel"><p class="note">Aucun composant pour l\'instant. Crée ta première brique réutilisable (ex : « Ganache montée mangue/framboise »).</p></div>'}`;
}
let cmpBomDraft=[];
async function componentForm(id){
  const c = id ? (await db.components.get(id))||{} : {};
  const mats = await db.materials.toArray().catch(()=>[]);
  window._matsCache = mats;
  cmpBomDraft = id ? (await db.recipeItems.where('componentId').equals(id).toArray().catch(()=>[]))
    .map(it=>({materialId:it.materialId, qteParBatch:it.qteParBatch, note:it.note||''})) : [];
  const typeOpts = Object.entries(COMPONENT_TYPES).map(([k,t])=>`<option value="${k}" ${c.type===k?'selected':''}>${t.ico} ${t.label}</option>`).join('');
  openModal(`<h3>${id?'Modifier':'Nouveau'} composant</h3>
    <div class="field"><label>Nom</label><input type="text" id="cmp_nom" value="${esc(c.nom||'')}" placeholder="ex : Ganache montée mangue/framboise"></div>
    <div class="field"><label>Type</label><select id="cmp_type">${typeOpts}</select></div>
    <div class="field"><label>Rendement (nb de pièces/portions par batch)</label>
      <input type="number" step="1" min="1" id="cmp_rend" value="${c.rendement!=null?c.rendement:''}" placeholder="ex : 24"></div>
    <div class="field"><label>Délai à prévoir à l'avance (heures)</label>
      <input type="number" step="0.5" min="0" id="cmp_delai" value="${c.delaiPrepaH!=null?c.delaiPrepaH:''}" placeholder="ex : 12 (repos au frigo)">
      <p class="note" style="margin:4px 0 0">Temps minimum entre la fabrication et l'utilisation (repos, prise au froid…). Le système l'anticipera pour planifier la production assez tôt.</p></div>
    <label class="switch-row"><input type="checkbox" id="cmp_congel" ${c.congelObligatoire?'checked':''}> <span>❄️ <b>Congélation</b> systématique</span></label>
    <div class="field"><label>Ingrédients (par batch) <span style="color:#9a8a82;font-weight:400">— la nomenclature propre à ce composant</span></label>
      <div id="cmpBomList"></div>
      ${mats.length?`<button class="btn ghost sm" style="margin-top:6px" onclick="cmpBomAdd()">+ Ajouter une matière</button>`:'<p class="note">Crée d\'abord des matières premières.</p>'}</div>
    <div class="field"><label>Notes (optionnel)</label><input type="text" id="cmp_notes" value="${esc(c.notes||'')}" placeholder="process, particularités…"></div>
    <div class="modal-actions">${id?`<button class="btn ghost" style="color:var(--red,#b3261e)" onclick="componentDelete(${id})">Supprimer</button>`:''}
      <button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn gold" onclick="componentSave(${id})">Enregistrer</button></div>`);
  drawCmpBom();
}
function drawCmpBom(){
  const box=document.getElementById('cmpBomList'); if(!box) return;
  const mats=(window._matsCache||[]).slice().sort((a,b)=>(a.nom||'').localeCompare(b.nom||'','fr',{sensitivity:'base'}));
  box.innerHTML = cmpBomDraft.map((b,i)=>{
    const opts = mats.map(m=>`<option value="${m.id}" ${m.id===b.materialId?'selected':''}>${esc(m.nom)}${m.marque?' — '+esc(m.marque):''}</option>`).join('');
    return `<div style="margin-bottom:8px">
      <div class="bom-line" style="grid-template-columns:1fr 90px 24px">
        <select onchange="cmpBomSet(${i},'materialId',+this.value)">${opts}</select>
        <input type="number" step="0.001" min="0" value="${b.qteParBatch!=null?b.qteParBatch:''}" oninput="cmpBomSet(${i},'qteParBatch',+this.value)" placeholder="qté">
        <span class="x" onclick="cmpBomDel(${i})">×</span>
      </div>
      <input type="text" value="${esc(b.note||'')}" oninput="cmpBomSet(${i},'note',this.value)" placeholder="💬 précision (ex : crème chaude, crème froide…)" style="width:100%;margin-top:3px;font-size:.82rem;padding:6px 8px;border:1px solid #e8dccd;border-radius:8px;background:#fff;color:#6a5a52">
    </div>`;
  }).join('') || '<p class="note">Aucun ingrédient.</p>';
}
function cmpBomAdd(){ const mats=window._matsCache||[]; if(!mats.length) return; cmpBomDraft.push({materialId:mats[0].id, qteParBatch:0, note:''}); drawCmpBom(); }
function cmpBomDel(i){ cmpBomDraft.splice(i,1); drawCmpBom(); }
function cmpBomSet(i,k,v){ if(cmpBomDraft[i]){ cmpBomDraft[i][k]=(k==='qteParBatch')?Math.max(0,+v||0):v; } }
async function componentSave(id){
  const nom=(val('cmp_nom')||'').trim();
  if(!nom){ toast('Nom requis'); return; }
  const o={ nom, type:val('cmp_type')||'autre',
    rendement:Math.max(1, Math.round(+val('cmp_rend')||1)),
    congelObligatoire: !!document.getElementById('cmp_congel')?.checked,
    delaiPrepaH: Math.max(0, +val('cmp_delai')||0),
    notes:(val('cmp_notes')||'').trim() };
  let cid = id;
  if(id){ await db.components.update(id, o); }
  else { cid = await db.components.add(o); }
  // ingrédients du composant : on remplace l'ensemble (via componentId)
  await db.recipeItems.where('componentId').equals(cid).delete().catch(()=>{});
  for(const b of cmpBomDraft){ if(b.materialId) await db.recipeItems.add({componentId:cid, materialId:b.materialId, qteParBatch:Math.max(0,+b.qteParBatch||0), note:(b.note||'').trim()}); }
  closeModal(); toast('Composant enregistré ✓'); renderComposants();
}
async function componentDelete(id){
  const recipes = await db.recipes.toArray().catch(()=>[]);
  const used = recipes.filter(r=>(r.componentRefs||[]).some(ref=>ref.componentId===id));
  if(used.length){ toast(`Utilisé par ${used.length} recette(s) — détache-le d'abord`); return; }
  if(!confirm('Supprimer ce composant ?')) return;
  await db.components.delete(id); closeModal(); toast('Composant supprimé'); renderComposants();
}
async function renderEquipements(){
  const main=document.getElementById('main'); if(!main) return;
  const specs = await equipGetSpecs();
  const boxes = await db.storageBoxes.orderBy('nom').toArray().catch(()=>[]);
  const anySpec = Object.values(specs).some(s=>Array.isArray(s.niveaux)&&s.niveaux.length);
  // Données d'occupation réelle pour les jauges colorées par parfum.
  const _prods = await db.productions.toArray().catch(()=>[]);
  const _recipes = await db.recipes.toArray().catch(()=>[]);
  const _recName = rid => (_recipes.find(r=>r.id===rid)||{}).produitNom||'(?)';
  const _prodParfum = new Map();
  _prods.forEach(p=>{ _prodParfum.set(p.id, p.libre?(p.produitLibre||'(libre)'):_recName(p.recipeId)); });
  const _boxesByNom = {}; boxes.forEach(b=>{ _boxesByNom[b.nom]=b; });
  const _placements = buildPlacementsMap(_prods, _boxesByNom);
  // Jauge HTML d'un niveau (segments colorés par parfum, longueur = taux d'occupation).
  const gaugeHtml = (eKey, lv, i)=>{
    const pls = _placements.get(eKey+'|'+(lv.nom||('Niveau '+(i+1)))) || [];
    if(!pls.length) return `<div class="gauge-empty">vide</div>`;
    const fs = levelFlavorSegments(lv, pls, _prodParfum);
    const pct = Math.round(fs.taux*100);
    const segs = fs.segments.map(s=>`<span title="${esc(s.parfum)} : ${s.nbMacarons} mac" style="display:block;height:100%;width:${Math.max(2,Math.round(s.part*100))}%;background:${s.color}"></span>`).join('');
    return `<div class="gauge"><div class="gauge-bar">${segs}</div><span class="gauge-pct">${pct}%</span></div>
      <div class="gauge-legend">${fs.segments.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.parfum)} ${s.nbMacarons}</span>`).join('')}</div>`;
  };
  const card = e => {
    const s = specs[e.key];
    const bg = e.type==='frigo' ? '#6aa3a0' : '#3b6ea5';
    let corps;
    if(!s || !Array.isArray(s.niveaux) || !s.niveaux.length){
      corps = `<p class="note">Niveaux non renseignés.</p>`;
    } else {
      const nivList = s.niveaux.map((lv,i)=>{
        const r=NIV_ROLES[nivRole(lv)], a=NIV_ACCES[nivAcces(lv)];
        return `<div class="sum-box" style="flex-direction:column;align-items:stretch;gap:4px">
          <div style="display:flex;justify-content:space-between;align-items:center"><span style="padding-left:10px">${lv.reserve?'🔒 ':''}${esc(lv.nom||('Niveau '+(i+1)))} <span style="font-size:.72rem;color:${r.c}">${r.ico} ${r.label}</span> <span style="font-size:.72rem">${a.ico}</span></span><b style="font-size:.78rem;color:#9a8a82">${lv.L}×${lv.l}×${lv.h}${lv.reserve?' · MP':''}</b></div>
          ${lv.reserve?'':gaugeHtml(e.key, lv, i)}</div>`;
      }).join('');
      let capBloc='';
      if(boxes.length){
        capBloc = boxes.map(b=>{
          const c=equipCapacityForBox(s,b); if(!c||c.nbBoites<=0) return '';
          return `<div class="sum-box" style="background:#faf6ee"><span>${esc(b.nom)}</span><b>${c.nbBoites} boîte(s) = ${qty(c.capaciteMacarons)} mac.</b></div>`;
        }).join('');
      }
      corps = `${nivList}${capBloc||(boxes.length?'':'<p class="note">Ajoute des boîtes pour voir la capacité.</p>')}`;
    }
    return `<div class="panel">
      <div style="display:flex;align-items:center;justify-content:space-between">
        <h2 style="font-size:1rem;margin:0">${e.icon} ${esc(e.nom)} <span class="tag" style="background:${bg};color:#fff">${e.lettre}</span></h2>
        <button class="btn ghost sm" onclick="equipForm('${e.key}')">✎ Niveaux</button>
      </div>
      ${corps}</div>`;
  };
  // Vue inverse : par parfum, où est-il rangé.
  const parfumMap = {};
  _placements.forEach((pls, key)=>{
    pls.forEach(pl=>{
      const parfum=_prodParfum.get(pl.prodId)||'(?)';
      (parfumMap[parfum] ||= {parfum, total:0, lieux:{}});
      parfumMap[parfum].total += Math.max(0,+pl.nbMacarons||0);
      parfumMap[parfum].lieux[key] = (parfumMap[parfum].lieux[key]||0) + Math.max(0,+pl.nbMacarons||0);
    });
  });
  const parfumsRanges = Object.values(parfumMap).sort((a,b)=>b.total-a.total);
  const maxParfum = Math.max(1, ...parfumsRanges.map(p=>p.total));
  const parParfumHtml = parfumsRanges.length ? parfumsRanges.map(pf=>{
    const col=flavorColor(pf.parfum);
    const lieux = Object.entries(pf.lieux).map(([k,nb])=>{
      const [ek,niv]=k.split('|'); const e=empInfo(ek);
      return `${e.lettre} ${esc(niv)} (${nb})`;
    }).join(' · ');
    return `<div style="padding:6px 0;border-bottom:1px solid #f0e9e2">
      <div style="display:flex;align-items:center;gap:8px">
        <span style="width:11px;height:11px;border-radius:50%;background:${col};flex:none"></span>
        <span style="flex:1;font-weight:600">${esc(pf.parfum)}</span><b style="font-size:.82rem">${pf.total} mac</b></div>
      <div class="gauge-bar" style="margin:4px 0 2px"><span style="display:block;height:100%;width:${Math.round(pf.total/maxParfum*100)}%;background:${col}"></span></div>
      <div style="font-size:.72rem;color:#9a8a82">${lieux}</div></div>`;
  }).join('') : '<p class="note">Aucun macaron rangé pour l\'instant.</p>';
  main.innerHTML=`
   <div class="topbar"><div><h1>Équipements de stockage</h1><p>Niveaux & capacité — espace de stockage global</p></div></div>
   <div class="banner" style="background:#eef5f0;border-color:#bcd9c6"><div>Chaque équipement est décrit par ses niveaux (dimensions réelles). La capacité en boîtes et macarons se calcule automatiquement, sans rotation des boîtes. Un niveau peut être réservé aux matières premières.</div></div>
   ${!anySpec?`<div class="panel" style="border:1.5px solid var(--gold,#AA7C39)"><h2 style="font-size:1rem">⚡ Pré-remplissage</h2><p class="note">Tes 4 équipements peuvent être pré-remplis avec les dimensions que tu as fournies (A, B, C, F). Tu pourras vérifier et ajuster ensuite.</p><button class="btn gold" onclick="equipSeedFill()">Pré-remplir mes équipements</button></div>`:''}
   ${EMPLACEMENTS.map(card).join('')}
   <div class="panel"><h2 style="font-size:1rem">🎨 Où est chaque parfum ?</h2>
     <p class="note" style="margin-top:0">Répartition de ton stock rangé, par parfum. Les couleurs reprennent celles de la boutique.</p>
     ${parParfumHtml}</div>
   ${!boxes.length?`<div class="panel"><p class="note">💡 Renseigne tes <b>boîtes de conservation</b> pour voir les capacités calculées.</p></div>`:''}`;
}
async function equipForm(key){
  const e = EMP_BY_KEY[key]; if(!e) return;
  const specs = await equipGetSpecs();
  const s = specs[key]||{niveaux:[]};
  _equipDraft = JSON.parse(JSON.stringify(s.niveaux||[]));
  _equipKey = key;
  openModal(`<h3>${e.icon} ${esc(e.nom)} — niveaux</h3>
    <p class="note">Dimensions de chaque niveau en cm (L × l × h). Coche « réservé » si le niveau sert aux matières premières.</p>
    <div id="eq_niv"></div>
    <button class="btn ghost sm" style="margin-top:6px" onclick="equipNivAdd()">+ Ajouter un niveau</button>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="equipSave()">Enregistrer</button></div>`);
  equipDrawNiv();
}
let _equipDraft=[], _equipKey=null;
function equipDrawNiv(){
  const box=document.getElementById('eq_niv'); if(!box) return;
  box.innerHTML = _equipDraft.map((lv,i)=>`
    <div style="border:1px solid #ece2d4;border-radius:8px;padding:8px;margin:6px 0">
      <div style="display:flex;gap:6px;align-items:center;margin-bottom:4px">
        <input style="flex:1" value="${esc(lv.nom||('Niveau '+(i+1)))}" oninput="equipNivSet(${i},'nom',this.value)" placeholder="Nom du niveau">
        <span class="x" onclick="equipNivDel(${i})">×</span>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:4px">
        <input type="number" step="0.1" min="0" value="${lv.L!=null?lv.L:''}" oninput="equipNivSet(${i},'L',+this.value)" placeholder="L">
        <input type="number" step="0.1" min="0" value="${lv.l!=null?lv.l:''}" oninput="equipNivSet(${i},'l',+this.value)" placeholder="l">
        <input type="number" step="0.1" min="0" value="${lv.h!=null?lv.h:''}" oninput="equipNivSet(${i},'h',+this.value)" placeholder="h">
      </div>
      <div style="display:flex;gap:10px;align-items:center;margin-top:4px">
        <select onchange="equipNivSet(${i},'mode',this.value)" style="flex:1">
          <option value="clayette" ${lv.mode!=='empilable'?'selected':''}>Clayette (1 couche)</option>
          <option value="empilable" ${lv.mode==='empilable'?'selected':''}>Empilable (sur la hauteur)</option>
        </select>
        <label style="display:flex;align-items:center;gap:4px;font-size:.8rem"><input type="checkbox" ${lv.reserve?'checked':''} onchange="equipNivSet(${i},'reserve',this.checked)"> 🔒 MP</label>
      </div>
      <div style="display:flex;gap:6px;margin-top:4px">
        <select onchange="equipNivSet(${i},'role',this.value)" style="flex:1">
          ${Object.keys(NIV_ROLES).map(k=>`<option value="${k}" ${nivRole(lv)===k?'selected':''}>${NIV_ROLES[k].ico} ${NIV_ROLES[k].label}</option>`).join('')}
        </select>
        <select onchange="equipNivSet(${i},'acces',this.value)" style="flex:1">
          ${Object.keys(NIV_ACCES).map(k=>`<option value="${k}" ${nivAcces(lv)===k?'selected':''}>${NIV_ACCES[k].ico} ${NIV_ACCES[k].label}</option>`).join('')}
        </select>
      </div>
    </div>`).join('') || '<p class="note">Aucun niveau. Ajoute-en un.</p>';
}
function equipNivAdd(){ _equipDraft.push({nom:'Niveau '+(_equipDraft.length+1), L:'', l:'', h:'', mode:'clayette', reserve:false, role:'standard', acces:'facile'}); equipDrawNiv(); }
function equipNivDel(i){ _equipDraft.splice(i,1); equipDrawNiv(); }
function equipNivSet(i,k,v){ if(_equipDraft[i]){ _equipDraft[i][k] = (k==='nom'||k==='mode'||k==='role'||k==='acces')?v : (k==='reserve'?!!v:Math.max(0,+v||0)); if(k==='mode'||k==='reserve')equipDrawNiv(); } }
async function equipSave(){
  const niveaux=_equipDraft.filter(lv=>(+lv.L>0&&+lv.l>0&&+lv.h>0)).map(lv=>({
    nom:(lv.nom||'Niveau').trim(), L:+lv.L||0, l:+lv.l||0, h:+lv.h||0,
    mode:lv.mode==='empilable'?'empilable':'clayette', reserve:!!lv.reserve,
    role:NIV_ROLES[lv.role]?lv.role:'standard', acces:NIV_ACCES[lv.acces]?lv.acces:'facile' }));
  await db.equipmentSpecs.put({key:_equipKey, niveaux});
  closeModal(); renderEquipements(); toast('Niveaux enregistrés ✓');
}

// ============================================================
//  BOÎTES DE CONSERVATION — catalogue des contenants réutilisables.
//  Chaque boîte : nom, dimensions L×l×h (cm), capacité (macarons), stock de boîtes
//  vides propres disponibles. Fondation du module de répartition du stock.
// ============================================================
async function renderBoites(){
  const main=document.getElementById('main'); if(!main) return;
  const boxes = await db.storageBoxes.orderBy('nom').toArray().catch(()=>[]);
  const volCm3 = b => (+b.L||0)*(+b.l||0)*(+b.h||0);
  const card = b => {
    const vol = volCm3(b);
    const dims = (b.L&&b.l&&b.h) ? `${b.L}×${b.l}×${b.h} cm` : 'dimensions non renseignées';
    const litres = vol>0 ? ` · ${(vol/1000).toFixed(1)} L` : '';
    return `<div class="sum-box" style="align-items:flex-start;gap:10px">
      <span style="flex:0 0 auto;font-size:1.1rem">📦</span>
      <span style="flex:1"><b>${esc(b.nom)}</b><br>
        <span style="font-size:.8rem;color:#9a8a82">${dims}${litres} · capacité ${qty(b.capacite||0)} std${(b.capaciteGF!=null)?` · ${qty(b.capaciteGF||0)} GF`:''}</span><br>
        <span style="font-size:.8rem;color:${(+b.stockVide||0)>0?'#3f7d52':'#b3261e'}">${qty(b.stockVide||0)} boîte(s) vide(s) propre(s) dispo</span></span>
      <span style="display:flex;gap:4px">
        <button class="btn ghost sm" onclick="boiteForm(${b.id})">✎</button>
        <button class="btn ghost sm" onclick="boiteDel(${b.id})">🗑</button>
      </span></div>`;
  };
  const totalCap = boxes.reduce((a,b)=>a+(+b.capacite||0)*(+b.stockVide||0),0);
  main.innerHTML=`
   <div class="topbar"><div><h1>Boîtes de conservation</h1><p>Tes contenants réutilisables et leur capacité</p></div>
     <button class="btn" onclick="boiteForm(0)">+ Nouvelle boîte</button></div>
   <div class="banner" style="background:#eef5f0;border-color:#bcd9c6"><div>Renseigne chaque type de boîte avec ses dimensions, sa capacité en macarons (standard et grand format) et le nombre de boîtes vides propres disponibles. Ces données serviront à répartir le stock dans tes équipements.</div></div>
   ${boxes.some(b=>/couvercle|transparente|rectangle/i.test(b.nom||''))?`<div class="panel" style="border:1.5px solid var(--gold,#AA7C39)"><h2 style="font-size:1rem">✨ Noms courts</h2><p class="note">Renomme tes boîtes avec des noms clairs basés sur leur capacité (Boîte 21 T, Boîte 20, Boîte 30, Boîte 30 R, Boîte 22, Boîte 10, Boîte 16).</p><button class="btn gold" onclick="boitesRenameClean()">Appliquer les noms courts</button></div>`:''}
   ${boxes.some(b=>b.capaciteGF==null)?`<div class="panel" style="border:1.5px solid var(--gold,#AA7C39)"><h2 style="font-size:1rem">⚡ Capacités grand format</h2><p class="note">Applique automatiquement les capacités grand format à tes boîtes connues (transparente, couvercles bleu/noir, rectangle, etc.). Tu pourras ajuster ensuite.</p><button class="btn gold" onclick="boitesSeedGF()">Appliquer les capacités grand format</button></div>`:''}
   <div class="panel">
     ${boxes.length?boxes.map(card).join(''):'<p class="note">Aucune boîte enregistrée. Ajoute ta première boîte de conservation.</p>'}
   </div>
   ${boxes.length?`<div class="panel"><div class="sum-box" style="background:#faf6ee"><span><b>Capacité totale disponible</b> (boîtes vides × capacité)</span><b>${qty(totalCap)} macarons</b></div></div>`:''}`;
}
async function boiteForm(id){
  const b = id ? (await db.storageBoxes.get(id))||{} : {};
  openModal(`<h3>${id?'Modifier':'Nouvelle'} boîte de conservation</h3>
    <div class="field"><label>Nom / type *</label><input id="bx_nom" value="${esc(b.nom||'')}" placeholder="ex : Grande boîte hermétique"></div>
    <label style="font-size:.85rem;color:#6b5d54;font-weight:600">Dimensions intérieures (cm)</label>
    <div class="row3" style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin:4px 0 10px">
      <div class="field" style="margin:0"><label>Longueur</label><input type="number" step="0.1" min="0" id="bx_L" value="${b.L!=null?b.L:''}" placeholder="L"></div>
      <div class="field" style="margin:0"><label>Largeur</label><input type="number" step="0.1" min="0" id="bx_l" value="${b.l!=null?b.l:''}" placeholder="l"></div>
      <div class="field" style="margin:0"><label>Hauteur</label><input type="number" step="0.1" min="0" id="bx_h" value="${b.h!=null?b.h:''}" placeholder="h"></div>
    </div>
    <div class="row2">
      <div class="field"><label>Capacité — standard (macarons)</label><input type="number" step="1" min="0" id="bx_cap" value="${b.capacite!=null?b.capacite:''}" placeholder="ex : 60"></div>
      <div class="field"><label>Capacité — grand format</label><input type="number" step="1" min="0" id="bx_capGF" value="${b.capaciteGF!=null?b.capaciteGF:''}" placeholder="ex : 6"></div>
    </div>
    <div class="field"><label>Boîtes vides propres dispo</label><input type="number" step="1" min="0" id="bx_vide" value="${b.stockVide!=null?b.stockVide:''}" placeholder="ex : 3"></div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="boiteSave(${id||0})">Enregistrer</button></div>`);
}
async function boiteSave(id){
  const nom=(val('bx_nom')||'').trim();
  if(!nom){ toast('Nom requis'); return; }
  const o={ nom,
    L:Math.max(0,+val('bx_L')||0), l:Math.max(0,+val('bx_l')||0), h:Math.max(0,+val('bx_h')||0),
    capacite:Math.max(0,Math.round(+val('bx_cap')||0)), capaciteGF:Math.max(0,Math.round(+val('bx_capGF')||0)), stockVide:Math.max(0,Math.round(+val('bx_vide')||0)) };
  if(id) await db.storageBoxes.update(id, o); else await db.storageBoxes.add(o);
  closeModal(); renderBoites(); toast('Boîte enregistrée ✓');
}
// Renomme les boîtes connues avec des noms courts et logiques (capacité + distinctif).
async function boitesRenameClean(){
  const boxes = await db.storageBoxes.toArray().catch(()=>[]);
  let n=0;
  for(const b of boxes){
    const nom=(b.nom||'').toLowerCase();
    let nouveau=null;
    if(nom.includes('transparente')) nouveau='Boîte 21 T';
    else if(nom.includes('rectangle')) nouveau='Boîte 30 R';
    else if(nom.includes('grande') && nom.includes('couvercle bleu')) nouveau='Boîte 20';
    else if(nom.includes('grande') && nom.includes('couvercle noir')) nouveau='Boîte 30';
    else if(nom.includes('moyenne') && nom.includes('couvercle noir')) nouveau='Boîte 22';
    else if(nom.includes('moyenne') && nom.includes('couvercle bleu')) nouveau='Boîte 10';
    else if(nom.includes('petite') && nom.includes('couvercle noir')) nouveau='Boîte 16';
    if(nouveau && nouveau!==b.nom){ await db.storageBoxes.update(b.id, {nom:nouveau}); n++; }
  }
  renderBoites();
  toast(n? `${n} boîte(s) renommée(s) ✓` : 'Aucune boîte à renommer');
}
async function boiteDel(id){
  const b=await db.storageBoxes.get(id); if(!b) return;
  if(!confirm(`Supprimer la boîte « ${b.nom} » ?`)) return;
  await db.storageBoxes.delete(id); renderBoites(); toast('Supprimé');
}
// Pré-remplit les capacités grand format des boîtes connues (rattachement par nom).
const BOITES_GF_SEED = [
  {match:'transparente', gf:0},
  {match:'couvercle bleu', grande:true, gf:2},   // Grande boîte couvercle bleu
  {match:'couvercle noir', grande:true, gf:6},   // Grande boîte couvercle noir
  {match:'rectangle', gf:6},                     // Grande boîte rectangle couv noir
  {match:'moyenne boîte couvercle noir', gf:4},
  {match:'moyenne boîte couvercle bleu', gf:2},
  {match:'petite boîte couvercle noir', gf:0},
];
async function boitesSeedGF(){
  const boxes = await db.storageBoxes.toArray().catch(()=>[]);
  let n=0;
  const norm = s => (s||'').toLowerCase();
  for(const b of boxes){
    const nom=norm(b.nom);
    let gf=null;
    // Noms courts (après renommage) OU anciens noms longs — les plus précis d'abord
    if(/\b21\s*t\b/.test(nom) || nom.includes('transparente')) gf=0;
    else if(/\b30\s*r\b/.test(nom) || nom.includes('rectangle')) gf=6;
    else if(/\bbo[iî]te\s*30\b/.test(nom) || (nom.includes('grande') && nom.includes('couvercle noir'))) gf=6;
    else if(/\bbo[iî]te\s*20\b/.test(nom) || (nom.includes('grande') && nom.includes('couvercle bleu'))) gf=2;
    else if(/\bbo[iî]te\s*22\b/.test(nom) || (nom.includes('moyenne') && nom.includes('couvercle noir'))) gf=4;
    else if(/\bbo[iî]te\s*10\b/.test(nom) || (nom.includes('moyenne') && nom.includes('couvercle bleu'))) gf=2;
    else if(/\bbo[iî]te\s*16\b/.test(nom) || (nom.includes('petite') && nom.includes('couvercle noir'))) gf=0;
    if(gf!==null){ await db.storageBoxes.update(b.id, {capaciteGF:gf}); n++; }
  }
  renderBoites();
  toast(n? `Capacités grand format appliquées à ${n} boîte(s) ✓` : 'Aucune boîte reconnue');
}

// ============================================================
//  MODULE CONSOMMABLES — listing centralisé + dispatch vers le bon calcul.
//  3 familles : 'atelier' (→ charges), 'coffret' (→ supplément emballage par format),
//  'recette' (→ consommable par pièce de la recette concernée).
// ============================================================
const CONSO_FAMILLES = {
  atelier:  {label:'Atelier', ico:'🧰', desc:'Papier cuisson, film, gants, sopalin… → comptés en charges (dépense réelle).'},
  coffret:  {label:'Par coffret', ico:'🎁', desc:'Cartes, stickers… → imputés au coût du coffret, par format.'},
  recette:  {label:'Par recette', ico:'🍪', desc:'Ronds dorés grand format… → consommable par pièce d\'une recette.'}
};
const BOX_SIZES_CONSO = [6,8,16,25];
function getConsommables(){ const s=getSettings(); return Array.isArray(s.consommables)?s.consommables:[]; }
function saveConsommables(arr){ const s=getSettings(); s.consommables=arr||[]; saveSettings(s); }
// Supplément consommable par format de coffret (€), agrégé depuis les consommables 'coffret'.
function consoCoffretSupplement(taille){
  return money2(getConsommables()
    .filter(c=>c.famille==='coffret' && Array.isArray(c.formats) && c.formats.includes(+taille))
    .reduce((a,c)=>a+(+c.prixUnitaire||0),0));
}
// Coût des consommables qui s'appliquent à CHAQUE PIÈCE de grand format (ex : rond or),
// déclarés famille « recette » avec l'option « tous les grands formats ». Par pièce.
function consoGrandFormatSupplement(){
  return money2(getConsommables()
    .filter(c=>c.famille==='recette' && c.tousGF)
    .reduce((a,c)=>a+(+c.prixUnitaire||0),0));
}

async function renderConsommables(){
  const main=document.getElementById('main'); if(!main) return;
  const list=getConsommables();
  const byFam = f => list.filter(c=>c.famille===f);

  const card = (c,idx)=>{
    const f=CONSO_FAMILLES[c.famille]||{};
    let detail='';
    if(c.famille==='coffret') detail = `Formats : ${(c.formats||[]).map(t=>t+'').join(', ')||'—'} · +${euro(c.prixUnitaire)}/coffret`;
    else if(c.famille==='recette') detail = `${euro(c.prixUnitaire)}/pièce${c.tousGF?' · 🍪 tous les grands formats':(c.recetteNom?` · ${esc(c.recetteNom)}`:'')}`;
    else detail = `${euro(c.prixUnitaire)}/${esc(c.unite||'unité')}${c.recurrent?' · récurrent':''}`;
    return `<div class="sum-box" style="align-items:flex-start;gap:10px">
      <span style="flex:0 0 auto;font-size:1.1rem">${f.ico||'•'}</span>
      <span style="flex:1"><b>${esc(c.nom)}</b><br><span style="font-size:.8rem;color:#9a8a82">${detail}</span></span>
      <span style="display:flex;gap:4px">
        <button class="btn ghost sm" onclick="consoForm(${idx})">✎</button>
        <button class="btn ghost sm" onclick="consoDel(${idx})">🗑</button>
      </span></div>`;
  };

  const section = (fam)=>{
    const f=CONSO_FAMILLES[fam]; const items=byFam(fam);
    return `<div class="panel">
      <h2 style="font-size:1rem">${f.ico} ${f.label}</h2>
      <p class="note">${f.desc}</p>
      ${items.length?items.map((c)=>card(c,list.indexOf(c))).join(''):'<p class="note">Aucun consommable dans cette famille.</p>'}
      <button class="btn ghost sm" style="margin-top:6px" onclick="consoForm(-1,'${fam}')">+ Ajouter</button>
    </div>`;
  };

  main.innerHTML=`
   <div class="topbar"><div><h1>Consommables</h1><p>Listing centralisé — chaque article alimente le bon calcul</p></div></div>
   <div class="banner" style="background:#eef5f0;border-color:#bcd9c6"><div>Range chaque consommable dans sa famille : l'app l'impute automatiquement au bon endroit (charges, coût du coffret, ou coût d'une recette).</div></div>
   ${section('atelier')}
   ${section('coffret')}
   ${section('recette')}
   <div class="panel">
     <h2 style="font-size:1rem">📊 Récapitulatif d'impact</h2>
     <div class="sum-box"><span>Supplément consommables par coffret</span><b></b></div>
     ${BOX_SIZES_CONSO.map(t=>`<div class="sum-box"><span style="padding-left:10px">· Coffret ${t}</span><b>+${euro(consoCoffretSupplement(t))}</b></div>`).join('')}
     <p class="note">Ce supplément s'ajoute au coût d'emballage du coffret concerné et impacte ta marge par commande.</p>
     ${consoGrandFormatSupplement()>0?`<div class="sum-box" style="margin-top:10px"><span>✨ Supplément par pièce de grand format</span><b>+${euro(consoGrandFormatSupplement())}</b></div>
     <p class="note">S'ajoute à chaque pièce de grand format vendue (ex : rond or), quel que soit l'emballage.</p>`:''}
   </div>`;
}

function consoForm(idx, presetFam){
  const list=getConsommables();
  const c = idx>=0 ? list[idx] : {nom:'', famille:presetFam||'atelier', prixUnitaire:'', unite:'unité', recurrent:false, formats:[], recetteNom:''};
  const famOpts = Object.keys(CONSO_FAMILLES).map(k=>`<option value="${k}" ${c.famille===k?'selected':''}>${CONSO_FAMILLES[k].ico} ${CONSO_FAMILLES[k].label}</option>`).join('');
  openModal(`<h3>${idx>=0?'Modifier':'Ajouter'} un consommable</h3>
    <div class="field"><label>Nom *</label><input id="co_nom" value="${esc(c.nom||'')}" placeholder="ex : Carte de présentation parfum"></div>
    <div class="field"><label>Famille</label><select id="co_fam" onchange="consoFormFam()">${famOpts}</select>
      <p class="note" id="co_famdesc">${CONSO_FAMILLES[c.famille].desc}</p></div>
    <div class="field"><label>Prix unitaire (€)</label><input type="number" step="0.001" min="0" id="co_prix" value="${c.prixUnitaire!==''&&c.prixUnitaire!=null?c.prixUnitaire:''}" placeholder="ex : 0.05"></div>
    <div id="co_extra"></div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Annuler</button>
      <button class="btn" onclick="consoSave(${idx})">Enregistrer</button></div>`);
  consoFormFam(c);
}
function consoFormFam(preset){
  const fam=val('co_fam')|| (preset&&preset.famille) || 'atelier';
  const d=document.getElementById('co_famdesc'); if(d) d.textContent=CONSO_FAMILLES[fam].desc;
  const extra=document.getElementById('co_extra'); if(!extra) return;
  const c=preset||{};
  if(fam==='atelier'){
    extra.innerHTML=`<div class="row2">
      <div class="field"><label>Unité</label><input id="co_unite" value="${esc(c.unite||'unité')}" placeholder="rouleau, boîte…"></div>
      <div class="field"><label class="pay-opt" style="display:flex;align-items:center;gap:8px;margin-top:24px"><input type="checkbox" id="co_recur" ${c.recurrent?'checked':''}> <span>Achat récurrent</span></label></div>
    </div>
    <p class="note">À l'enregistrement, tu pourras l'ajouter comme charge (ponctuelle ou récurrente mensuelle).</p>`;
  } else if(fam==='coffret'){
    extra.innerHTML=`<div class="field"><label>Formats concernés</label>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:4px">
        ${BOX_SIZES_CONSO.map(t=>`<label class="pay-opt" style="display:flex;align-items:center;gap:4px"><input type="checkbox" class="co_fmt" value="${t}" ${(c.formats||[]).includes(t)?'checked':''}> ${t}</label>`).join('')}
      </div>
      <p class="note">Coche les tailles de coffret qui contiennent ce consommable (ex : carte de visite → 16 et 25 seulement).</p></div>`;
  } else {
    extra.innerHTML=`<div class="field">
      <label class="pay-opt" style="display:flex;align-items:center;gap:8px"><input type="checkbox" id="co_allgf" ${c.tousGF?'checked':''} onchange="document.getElementById('co_recetteWrap').style.display=this.checked?'none':'block'"> <span>S'applique à <b>tous les grands formats</b> (par pièce)</span></label>
      <p class="note">Coché : ce coût (ex : un rond or) s'ajoute automatiquement à chaque pièce de grand format vendue, quel que soit le parfum ou l'emballage.</p>
      <div id="co_recetteWrap" style="display:${c.tousGF?'none':'block'}">
        <label>Recette concernée</label><input id="co_recette" value="${esc(c.recetteNom||'')}" placeholder="ex : Grand format / Praliné">
        <p class="note">Sinon, cible une recette précise par son nom (rattachement fin à venir).</p>
      </div></div>`;
  }
}
function consoSave(idx){
  const nom=(val('co_nom')||'').trim();
  if(!nom){ toast('Nom requis'); return; }
  const famille=val('co_fam')||'atelier';
  const prixUnitaire=Math.max(0,+val('co_prix')||0);
  const item={nom, famille, prixUnitaire};
  if(famille==='atelier'){ item.unite=(val('co_unite')||'unité').trim(); item.recurrent=!!document.getElementById('co_recur')?.checked; }
  else if(famille==='coffret'){ item.formats=[...document.querySelectorAll('.co_fmt:checked')].map(x=>+x.value); }
  else { item.recetteNom=(val('co_recette')||'').trim(); item.tousGF=!!document.getElementById('co_allgf')?.checked; }
  const list=getConsommables();
  if(idx>=0) list[idx]=item; else list.push(item);
  saveConsommables(list);
  closeModal(); renderConsommables();
  toast('Consommable enregistré ✓');
  // Famille atelier : proposer de créer la charge dans la foulée.
  if(famille==='atelier' && prixUnitaire>0) consoOfferCharge(item);
}
function consoDel(idx){
  const list=getConsommables(); const c=list[idx]; if(!c) return;
  if(!confirm(`Supprimer « ${c.nom} » ?`)) return;
  list.splice(idx,1); saveConsommables(list); renderConsommables();
  toast('Supprimé');
}
// Proposer d'enregistrer un consommable d'atelier comme charge (ponctuelle ou récurrente).
function consoOfferCharge(item){
  openModal(`<h3>Ajouter « ${esc(item.nom)} » aux charges ?</h3>
    <p class="note">Ce consommable d'atelier est une dépense. Tu peux l'enregistrer maintenant.</p>
    <div class="field"><label>Montant de l'achat (€)</label><input type="number" step="0.01" min="0" id="cc_montant" value="${item.prixUnitaire||''}" placeholder="montant total payé"></div>
    <div class="field"><label>Type</label>
      <select id="cc_type"><option value="ponctuel">Achat ponctuel (ce mois)</option><option value="recurrent">Charge récurrente mensuelle</option></select></div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeModal()">Plus tard</button>
      <button class="btn" onclick="consoAddCharge('${escJs(item.nom)}')">Enregistrer la charge</button></div>`);
}
async function consoAddCharge(nom){
  const montant=Math.max(0,+val('cc_montant')||0);
  const type=val('cc_type')||'ponctuel';
  if(montant<=0){ toast('Montant invalide'); return; }
  if(type==='recurrent'){
    const models=getRecurringCharges();
    models.push({id:'rc'+Date.now(), libelle:'Consommable : '+nom, categorie:'Équipement', montant:money2(montant), jourMois:1, debut:today().slice(0,7), actif:true});
    saveRecurringCharges(models);
    if(typeof materializeRecurringCharges==='function') await materializeRecurringCharges();
    toast('Charge récurrente créée ✓');
  } else {
    await db.charges.add({date:today(), categorie:'Équipement', libelle:'Consommable : '+nom, montant:money2(montant)});
    toast('Charge enregistrée ✓');
  }
  closeModal();
}

async function renderPMS(){
  await seedPMS();
  if(!_pmsPeriode){ _pmsPeriode = (new Date().getHours() < 14) ? 'Matin' : 'Soir'; }
  _pmsDate = today();   // on repart toujours sur aujourd'hui en entrant dans l'écran
  document.getElementById('main').innerHTML=`
   <div class="topbar"><div><h1>HACCP / PMS</h1><p>Plan de Maîtrise Sanitaire — ${fmtDate(today())}</p></div>
     <div class="flex"><button class="btn ghost" onclick="pmsRemindersInfo()">🔔 Rappels iOS</button><button class="btn ghost" onclick="pmsExportDDPP()">🗄 Historique / Contrôle DDPP</button></div></div>
   <div class="pick-tabs">
     <button class="${_pmsTab==='temp'?'active':''}" onclick="pmsSetTab('temp')">🌡 Températures</button>
     <button class="${_pmsTab==='nettoyage'?'active':''}" onclick="pmsSetTab('nettoyage')">🧼 Nettoyage</button>
     <button class="${_pmsTab==='doc'?'active':''}" onclick="pmsSetTab('doc')">📋 Document</button>
     <button class="${_pmsTab==='5m'?'active':''}" onclick="pmsSetTab('5m')">🔬 Analyse 5M</button>
   </div>
   <div id="pmsBody"></div>`;
  if(_pmsTab==='temp') await pmsRenderTemp();
  else if(_pmsTab==='nettoyage') await pmsRenderCleaning();
  else if(_pmsTab==='doc') pmsRenderDoc();
  else if(_pmsTab==='5m') pmsRender5M();
}
function pmsSetTab(t){ if(t!==_pmsTab && !pmsGuardUnsaved()) return; _pmsTab=t; renderPMS(); }

// ---------- C. DOCUMENT PMS (consultable + infos labo saisies en local) ----------
function pmsGetLaboInfo(){ const s=getSettings(); return s.pmsLabo||{}; }
function pmsSaveLaboInfo(){
  const s=getSettings();
  s.pmsLabo = {
    responsable: (val('pms_resp')||'').trim(),
    adresse: (val('pms_adr')||'').trim(),
    siret: (val('pms_siret')||'').trim(),
    declaration: (val('pms_decl')||'').trim(),
    formation: (val('pms_form')||'').trim(),
    maj: today()
  };
  saveSettings(s);
  toast('Informations du labo enregistrées ✓');
  pmsRenderDoc();
}
// Bloc d'accordéon réutilisable (titre + contenu HTML).
function pmsAccordion(titre, contenuHtml, open){
  return `<details ${open?'open':''} style="margin:8px 0;border:1px solid #ece2d4;border-radius:10px;overflow:hidden">
    <summary style="cursor:pointer;padding:12px 14px;background:#faf6ee;font-weight:600;color:var(--bordeaux,#7a2230)">${titre}</summary>
    <div style="padding:6px 14px 14px">${contenuHtml}</div></details>`;
}
function pmsLi(arr){ return `<ul style="margin:4px 0 4px 18px;padding:0">${arr.map(x=>`<li style="margin:3px 0;font-size:.9rem;line-height:1.45">${x}</li>`).join('')}</ul>`; }

